-- FQHA_DIV_TELNO (FUNCTION, VALID)
CREATE FUNCTION "FQHA_DIV_TELNO" (p_TELNO IN VARCHAR2)
-- ===============================================
-- 설  명: 구분자가 없는 전화번호에 구분자를 추가하여 반환한다.
-- 인  수: p_TELNO IN VARCHAR2 - 결재상태코드
-- 리  턴: 결과      IN VARCHAR2
-- 작성자: 곽민욱
-- 작성일: 2019/09/20
-- 변경이력:
-- ===============================================
    RETURN VARCHAR2
IS
    v_DIV_TELNO VARCHAR2(200);

BEGIN

    SELECT REGEXP_REPLACE(p_TELNO,'(02|031|032|033|041|042|043|051|052|053|054|055|061|062|063|064'||'|010|011|016|017|018|019'||'|030|050|060|070|080)'||'(.+)(.{4})','\1-\2-\3')
       INTO v_DIV_TELNO
      FROM DUAL;

    RETURN(v_DIV_TELNO);
END;
/

-- FQHA_GETCHRC_VAL_1 (FUNCTION, VALID)
CREATE FUNCTION "FQHA_GETCHRC_VAL_1" (P_CD IN VARCHAR2)
-- ===============================================
-- 설  명: 코드를 받아 코드명을 반환한다.
-- 인  수: V_CD   IN VARCHAR2 - 코드
-- 리  턴: 결과   IN VARCHAR2
-- 작성자: 곽민욱
-- 작성일: 2020/02/11
-- 변경이력:
-- ===============================================
    RETURN VARCHAR2
IS
    v_CDNM VARCHAR2(500);
BEGIN
    SELECT CHRC_VAL_1
      INTO v_CDNM
      FROM TCOA_COMCODE
     WHERE COM_CD   = p_CD;

    RETURN(v_CDNM);
END;
/

-- FQHA_GETCMSITE01_BY_SITECD (FUNCTION, VALID)
CREATE FUNCTION "FQHA_GETCMSITE01_BY_SITECD" (
    p_SIT_CD      IN TCMZ_SIT.SIT_CD%TYPE,   -- 현장코드
    p_DEFAULT_DT  IN VARCHAR2                -- 기준일자
) RETURN QHSITETAB01 
IS 
    v_RS          QHSITETAB01;
    v_DEFAULT_DT  VARCHAR2(10);  
BEGIN
    -- 1. 날짜 형식 변환 및 유효성 체크
    BEGIN
        SELECT CASE 
                 WHEN LENGTH(REGEXP_REPLACE(p_DEFAULT_DT, '[^0-9]')) = 6 THEN 
                      TO_CHAR(TO_DATE('20' || REGEXP_REPLACE(p_DEFAULT_DT, '[^0-9]'), 'YYYYMMDD'), 'YYYY/MM/DD')
                 WHEN LENGTH(REGEXP_REPLACE(p_DEFAULT_DT, '[^0-9]')) = 8 THEN 
                      TO_CHAR(TO_DATE(REGEXP_REPLACE(p_DEFAULT_DT, '[^0-9]'), 'YYYYMMDD'), 'YYYY/MM/DD')
                 ELSE TO_CHAR(SYSDATE, 'YYYY/MM/DD') -- 형식이 맞지 않을 경우 기본값 처리 (필요시 수정)
               END
          INTO v_DEFAULT_DT
          FROM DUAL;
    EXCEPTION
        WHEN OTHERS THEN
            v_DEFAULT_DT := TO_CHAR(SYSDATE, 'YYYY/MM/DD');
    END;

    -- 2. 데이터 조회 및 컬렉션 담기 (BULK COLLECT)
    SELECT QHSITEOBJ01 (
             SIT_CD,            -- 현장코드
             LM_YN,             -- 주간사여부
             NVL(CONT_ERT, 100), -- 계약지분율
             WHL_SPLPRC_AMT,    -- 전체공급금액
             WHL_VAT            -- 전체부가세
           )
      BULK COLLECT INTO v_RS
      FROM (
             WITH SITE_INFO AS (
                 SELECT SIT_CD
                   FROM TCMZ_SIT
                  WHERE 1 = CASE 
                              WHEN p_SIT_CD IS NULL THEN 1 
                              WHEN p_SIT_CD = 'X' THEN 0 
                              WHEN SIT_CD = p_SIT_CD THEN 1 
                              ELSE 0 
                            END
             ),
             JV_INFO AS (
                 SELECT SIT_CD, LM_YN, CONT_ERT
                   FROM (
                         SELECT A.SIT_CD,
                                B.LM_YN,
                                B.SKAT_RT AS CONT_ERT,
                                ROW_NUMBER() OVER (PARTITION BY A.SIT_CD ORDER BY A.SEQ DESC) AS SORT_NO
                           FROM TCSB_JOINT_HIS A
                           JOIN TSOC_JOINT_INFO B ON A.SIT_CD = B.SIT_CD AND A.SEQ = B.DGR_CONT_SEQ
                          WHERE A.PAY_DT <= NVL(v_DEFAULT_DT, '2999/12/31')
                            AND 1 = CASE 
                                      WHEN p_SIT_CD IS NULL THEN 1 
                                      WHEN A.SIT_CD = p_SIT_CD THEN 1 
                                      ELSE 0 
                                    END
                        )
                  WHERE SORT_NO = 1
             ),
             CONT_INFO AS (
                 SELECT SIT_CD, WHL_SPLPRC_AMT, WHL_VAT
                   FROM (
                         SELECT SIT_CD,
                                SPLPRC_AMT AS WHL_SPLPRC_AMT,
                                VAT AS WHL_VAT,
                                ROW_NUMBER() OVER (PARTITION BY SIT_CD ORDER BY DGR_CONT_SEQ ASC) AS SORT_NO
                           FROM TSOC_CONTRACT
                          WHERE DGR_CONT_SEQ = 0
                            AND CONT_DT <= NVL(v_DEFAULT_DT, '2999/12/31')
                            AND 1 = CASE 
                                      WHEN p_SIT_CD IS NULL THEN 1 
                                      WHEN SIT_CD = p_SIT_CD THEN 1 
                                      ELSE 0 
                                    END
                        )
                  WHERE SORT_NO = 1
             )
             -- 최종 조인
             SELECT A.SIT_CD,
                    B.LM_YN,
                    B.CONT_ERT,
                    C.WHL_SPLPRC_AMT,
                    C.WHL_VAT
               FROM SITE_INFO A
               LEFT OUTER JOIN JV_INFO B ON A.SIT_CD = B.SIT_CD
               LEFT OUTER JOIN CONT_INFO C ON A.SIT_CD = C.SIT_CD
           );

    RETURN v_RS;

END FQHA_GETCMSITE01_BY_SITECD;
/

-- FQHA_GETCMSITENM_BY_SITECD (FUNCTION, VALID)
CREATE FUNCTION "FQHA_GETCMSITENM_BY_SITECD" (
    p_SIT_CD IN TCMZ_SIT.SIT_CD%TYPE
) RETURN VARCHAR2 
IS 
    v_RS TCMZ_SIT.SIT_NM%TYPE := '';
BEGIN
	SELECT DEPT_NM INTO v_RS
	FROM TCOZ_DEPT_INFO 
	WHERE DEPT_CD =p_SIT_CD;
    RETURN v_RS;
EXCEPTION
    WHEN NO_DATA_FOUND THEN RETURN NULL;
    WHEN OTHERS THEN RAISE;
END FQHA_GETCMSITENM_BY_SITECD;
/

-- FQHA_GETDEPTNM_BY_DEPTCD (FUNCTION, VALID)
CREATE FUNCTION "FQHA_GETDEPTNM_BY_DEPTCD" (
    p_DEPT_CD IN TCOZ_DEPT_INFO.DEPT_CD%TYPE                                  
) RETURN VARCHAR2 
IS 
    v_RS TCOZ_DEPT_INFO.DEPT_NM%TYPE := '';
BEGIN
    -- 1. 회계부서코드와 상위부서 조건을 이용한 조회
    SELECT MAX(DEPT_NM)
      INTO v_RS
      FROM TCOZ_DEPT_INFO
     WHERE ACCTG_DEPT_CD = p_DEPT_CD
       AND HRNK_DEPT_CD NOT LIKE 'D00%';

    -- 2. 결과가 없으면 일반 부서코드로 조회
    IF (v_RS IS NULL) THEN
        SELECT MAX(DEPT_NM)
          INTO v_RS
          FROM TCOZ_DEPT_INFO
         WHERE DEPT_CD = p_DEPT_CD;
    END IF;

    -- 3. 그래도 결과가 없으면 회계부서코드의 MAX값 조회
    IF (v_RS IS NULL) THEN
        SELECT MAX(DEPT_NM)
          INTO v_RS
          FROM TCOZ_DEPT_INFO
         WHERE ACCTG_DEPT_CD = p_DEPT_CD;
    END IF;

    RETURN v_RS;
END FQHA_GETDEPTNM_BY_DEPTCD;
/

-- FQHA_GETLMYN_BY_SITECD (FUNCTION, VALID)
CREATE FUNCTION "FQHA_GETLMYN_BY_SITECD" (
    p_SIT_CD IN TCSA_ERT.SIT_CD%TYPE                        
) RETURN VARCHAR2 
IS 
    v_RS TSOC_JOINT_INFO.LM_YN%TYPE := '';
BEGIN
    SELECT AA.LM_YN
      INTO v_RS
      FROM (
             SELECT DECODE(B.LM_YN, '0', 'N', 'Y') AS LM_YN
                  , ROW_NUMBER() OVER (PARTITION BY A.SIT_CD ORDER BY A.SEQ DESC) AS SORT_NO
               FROM TCSB_JOINT_HIS A
               JOIN TSOC_JOINT_INFO B ON A.SIT_CD = B.SIT_CD AND A.SEQ = B.DGR_CONT_SEQ
              WHERE A.SIT_CD = p_SIT_CD
           ) AA
     WHERE AA.SORT_NO = 1;

    IF (v_RS IS NULL) THEN
       v_RS := 'N';
    END IF;     
    RETURN v_RS;
EXCEPTION
    WHEN NO_DATA_FOUND THEN RETURN 'N';
    WHEN OTHERS THEN RETURN 'N';
END FQHA_GETLMYN_BY_SITECD;
/

-- FQHA_GET_CDNM_BY_COMCD (FUNCTION, VALID)
CREATE FUNCTION "FQHA_GET_CDNM_BY_COMCD" (
    p_COMCD IN TCOA_COMCODE.COM_CD%TYPE                                  
) RETURN VARCHAR2
IS 
    v_RS TCOA_COMCODE.CD_NM%TYPE := '';                                
BEGIN
    SELECT CD_NM
      INTO v_RS
      FROM TCOA_COMCODE
     WHERE COM_CD = p_COMCD  
       AND ROWNUM = 1;
    RETURN v_RS;
EXCEPTION
    WHEN NO_DATA_FOUND THEN RETURN NULL;
    WHEN OTHERS THEN RETURN NULL;
END FQHA_GET_CDNM_BY_COMCD;
/

-- FQHA_GET_TELNO (FUNCTION, VALID)
CREATE FUNCTION "FQHA_GET_TELNO" (
    P_TEL_NO VARCHAR2
) RETURN VARCHAR2
IS
BEGIN
    IF P_TEL_NO IS NULL THEN
        RETURN NULL;

    ELSIF P_TEL_NO LIKE '02%' AND LENGTH(P_TEL_NO) = 9 THEN
        RETURN REGEXP_REPLACE(P_TEL_NO,
                              '(02)([0-9]{3})([0-9]{4})',
                              '\1-\2-\3');

    ELSIF P_TEL_NO LIKE '02%' AND LENGTH(P_TEL_NO) = 10 THEN
        RETURN REGEXP_REPLACE(P_TEL_NO,
                              '(02)([0-9]{4})([0-9]{4})',
                              '\1-\2-\3');

    ELSIF LENGTH(P_TEL_NO) = 10 THEN
        RETURN REGEXP_REPLACE(P_TEL_NO,
                              '([0-9]{3})([0-9]{3})([0-9]{4})',
                              '\1-\2-\3');

    ELSIF LENGTH(P_TEL_NO) = 11 THEN
        RETURN REGEXP_REPLACE(P_TEL_NO,
                              '([0-9]{3})([0-9]{4})([0-9]{4})',
                              '\1-\2-\3');

    ELSE
        RETURN P_TEL_NO;
    END IF;
END;
/

-- FQHA_GET_USRNM_BY_USRID (FUNCTION, VALID)
CREATE FUNCTION "FQHA_GET_USRNM_BY_USRID" (
                                 p_USR_ID IN TCOZ_USR_INFO.USR_ID%TYPE                                  
                               ) RETURN VARCHAR2

IS v_RS TCOZ_USR_INFO.USR_NM%TYPE := '';                                

BEGIN
    SELECT (
             SELECT USR_NM
               FROM TCOZ_USR_INFO
              WHERE USR_ID = p_USR_ID
                AND USE_YN  = '1'  
                AND ROWNUM = 1
           )      
      INTO v_RS
      FROM DUAL;                                
  RETURN v_RS;
END FQHA_GET_USRNM_BY_USRID;
/

-- FQHA_XML_CLOB (FUNCTION, VALID)
CREATE FUNCTION "FQHA_XML_CLOB" (p_Table_Nmae    VARCHAR2 ) RETURN CLOB

AS
    CURSOR v_CUR IS
        SELECT A.COLUMN_ID, A.COLUMN_NAME, B.COMMENTS, A.DATA_TYPE, A.DATA_LENGTH, A.NULLABLE, DECODE (A.COLUMN_NAME, C.COLUMN_NAME,'Y','N')AS PK, COUNT(A.COLUMN_ID) OVER() CNT
          FROM ALL_TAB_COLUMNS A, ALL_COL_COMMENTS B,
               (SELECT C.TABLE_NAME, C.COLUMN_NAME
                  FROM USER_CONS_COLUMNS C, USER_CONSTRAINTS S
                 WHERE C.CONSTRAINT_NAME = S.CONSTRAINT_NAME
                   AND S.CONSTRAINT_TYPE = 'P'
                   AND C.TABLE_NAME      = p_Table_Nmae ) C
         WHERE A.TABLE_NAME  = B.TABLE_NAME
           AND A.COLUMN_NAME = B.COLUMN_NAME
           AND A.TABLE_NAME  = C.TABLE_NAME(+)
           AND A.COLUMN_NAME = C.COLUMN_NAME(+)
           AND A.OWNER       = 'VPLUS'
           AND A.TABLE_NAME  = p_Table_Nmae
     ORDER BY  A.COLUMN_ID;

    v_COLUMN_ID ALL_TAB_COLUMNS.COLUMN_ID%TYPE;
    v_COLUMN_NAME ALL_TAB_COLUMNS.COLUMN_NAME%TYPE;
    v_COMMENTS ALL_COL_COMMENTS.COMMENTS%TYPE;
    v_DATA_TYPE ALL_TAB_COLUMNS.DATA_TYPE%TYPE;
    v_DATA_LENGTH ALL_TAB_COLUMNS.DATA_LENGTH%TYPE;
    v_NULLABLE ALL_TAB_COLUMNS.NULLABLE%TYPE;

    v_CNT_R INT           :=0;
    v_CNT   INT           := 0;
    v_TEXT CLOB :='';
    v_TYPE VARCHAR2(200);
    v_PK   VARCHAR2(1);

    BEGIN

        v_TEXT := v_TEXT || '    <!-- 설명 -->' || CHR(13);
        v_TEXT := v_TEXT || '    <select id="get_Test" resultType="map">' || CHR(13);
        v_TEXT := v_TEXT || CHR(13);

        OPEN v_CUR;

        LOOP
            FETCH v_CUR INTO v_COLUMN_ID,v_COLUMN_NAME,v_COMMENTS,v_DATA_TYPE,v_DATA_LENGTH,v_NULLABLE,v_PK,v_CNT_R;
            EXIT WHEN v_CUR%NOTFOUND;

            v_CNT := v_CNT + 1;

            IF (v_CNT = 1) THEN
               v_TEXT := v_TEXT || '        SELECT ' || v_COLUMN_NAME || '                -- ' || v_COMMENTS || CHR(13);
            ELSE
                IF v_COLUMN_NAME NOT IN ('UPD_ID','UPD_DTM','UPD_IP','IPT_ID','IPT_DTM','IPT_IP') THEN
                    v_TEXT := v_TEXT || '             , ' || v_COLUMN_NAME || '                -- ' || v_COMMENTS || CHR(13);
                END IF;
            END IF;
        END LOOP;

        CLOSE v_CUR;
        v_TEXT := v_TEXT || CHR(13);
        v_TEXT := v_TEXT || '          FROM ' || p_Table_Nmae || CHR(13);

        v_TEXT := v_TEXT || CHR(13);
        v_TEXT := v_TEXT || '    </select>' || CHR(13);
        v_TEXT := v_TEXT || CHR(13);
        v_TEXT := v_TEXT || CHR(13);

        v_TEXT := v_TEXT || '    <!-- 설명 -->' || CHR(13);
        v_TEXT := v_TEXT || '    <select id="get_Test" statementType="CALLABLE" resultType="map">' || CHR(13);
        v_TEXT := v_TEXT || CHR(13);
        v_TEXT := v_TEXT || '        { CALL PCOZ_TEST_Q(' || CHR(13);
        v_TEXT := v_TEXT || '               #{WRK_TP           ,jdbcType=VARCHAR}  -- 작업종류' || CHR(13);
        v_TEXT := v_TEXT || '              ,#{WRK_ID           ,jdbcType=VARCHAR}  -- 아이디' || CHR(13);
        v_TEXT := v_TEXT || '              ,#{WRK_IP           ,jdbcType=VARCHAR}  -- 아이피' || CHR(13);

        OPEN v_CUR;

        LOOP
            FETCH v_CUR INTO v_COLUMN_ID,v_COLUMN_NAME,v_COMMENTS,v_DATA_TYPE,v_DATA_LENGTH,v_NULLABLE,v_PK,v_CNT_R;
            EXIT WHEN v_CUR%NOTFOUND;

             IF v_COLUMN_NAME NOT IN ('UPD_ID','UPD_DTM','UPD_IP','IPT_ID','IPT_DTM','IPT_IP') THEN
                v_TEXT := v_TEXT || '              ,#{' || v_COLUMN_NAME || '           ,jdbcType=VARCHAR}  -- ' || v_COMMENTS || CHR(13);
             END IF;

        END LOOP;

        CLOSE v_CUR;
        v_TEXT := v_TEXT || '        )}' || CHR(13);
        v_TEXT := v_TEXT || CHR(13);
        v_TEXT := v_TEXT || '    </select>' || CHR(13);

        RETURN  v_TEXT;
    END;
/

-- FQHZ_GET_CORP_NM (FUNCTION, VALID)
CREATE FUNCTION "FQHZ_GET_CORP_NM" (p_SIT_CD IN VARCHAR2)
                  RETURN VARCHAR2
/*******************************************************************************************************************
 설  명      : [공통함수] 현장코드를 받아 법인명을 반환
 작성자      : HumamPlus
 작성일      : 2022/12/23
 PARAMETERS  : p_CORP_CD IN VARCHAR2 - 부서코드
 RETURN VALUE: 결과      IN VARCHAR2  
            
 개정번호   개정일자      변경내용요약                                      관련근거
 -------------------------------------------------------------------------------------------------------------------
 
*******************************************************************************************************************/                  
IS
    v_CORP_NM TCOA_CORP.CORP_NM%TYPE;

BEGIN

  SELECT T2.CORP_NM INTO v_CORP_NM
  FROM TCOZ_DEPT_INFO T1
      ,TCOA_CORP T2
 WHERE T1.CORP_CD = T2.CORP_CD
   AND T1.DEPT_CD = p_SIT_CD;

    RETURN(v_CORP_NM);
END;
/

-- FQHZ_SAFT_DEFC_IF (FUNCTION, VALID)
CREATE FUNCTION "FQHZ_SAFT_DEFC_IF" (
                                                      p_INQ_DIV IN VARCHAR2 --조회구분(SAFT: 안전_도급/실행금액, DEFC: 하자_도급/실행금액, SM: 안전_계약금액)
                                                     ,p_SIT_CD  IN VARCHAR2 --현장코드
                                                     )

RETURN T_OCMZ_SAFT_DEFC_IF

/******************************************************************************************************************
--설  명     : 조회대상의 [안전_도급,실행금액 / 하자보수_도급,실행금액 / 계약_안전관리비금액]을 반환한다.

--작성자     : HumamPlus
--작성일     : 2024.05.20
--수정일     : 
--PARAMETERS : p_INQ_DIV  : 조회구분(SAFT: 안전_도급/실행금액, DEFC: 하자_도급/실행금액, SM: 안전_계약금액)
               p_SIT_CD   현장코드

RETURN VALUE:  안전_도급,실행금액 / 하자보수_도급,실행금액 / 계약_안전관리비금액 반환

개정번호   개정일자      변경내용요약                                      관련근거 
-------------------------------------------------------------------------------------------------------------------

*******************************************************************************************************************/

IS
    v_RESULT_ROW T_OCMZ_SAFT_DEFC_IF;

    v_EBGT_DGR   NUMBER(10); --현실행차수 

BEGIN
	--#. [현실행차수] SELECT
    SELECT MAX(EBGT_DGR)
      INTO v_EBGT_DGR
      FROM TCMA_EBGT
     WHERE SIT_CD = p_SIT_CD
    ; 

    --#. [안전_도급/실행금액] 조회인 경우
    IF p_INQ_DIV = 'SAFT' THEN
        WITH TMP_10 AS (--안전 : 공종ID SELECT
                        SELECT A.SIT_CD
                              ,A.EBGT_DGR
                              ,A.CTP_ID
                          FROM TCMA_EBGT_DTL A
                         WHERE A.SIT_CD        = p_SIT_CD
                           AND A.EBGT_DGR      = v_EBGT_DGR
                         START WITH A.SIT_CD   = p_SIT_CD
                                AND A.EBGT_DGR = v_EBGT_DGR
                                AND A.STD_CD   = 'B002001' --산업안전보건법
                         CONNECT BY PRIOR A.SIT_CD   = A.SIT_CD
                                AND PRIOR A.EBGT_DGR = A.EBGT_DGR
                                AND PRIOR A.CTP_ID   = A.HRNK_CTP_ID
                       )

        SELECT OCMZ_SAFT_DEFC_IF ( 
                                  Z.SIT_CD        --현장코드                       : SIT_CD       
                                 ,NULL            --계약번호(= 발주번호) : 외주用  : CONT_NO      
                                 ,NULL            --거래처코드           : 외주用  : CUST_CD

                                 ,SUM(Z.UNTK_AMT) --안전_도급금액                  : SAFT_UNTK_AMT
                                 ,SUM(Z.EBGT_AMT) --안전_실행금액                  : SAFT_EBGT_AMT
                                 ,0               --안전_계약금액                  : SAFT_CONT_AMT

                                 ,0               --하자_도급금액                  : DEFC_UNTK_AMT
                                 ,0               --하자_실행금액                  : DEFC_EBGT_AMT
                                 )
          BULK COLLECT INTO v_RESULT_ROW
          FROM TMP_10 A
               INNER JOIN TCMA_EBGT_DTL Z ON Z.SIT_CD   = A.SIT_CD
                                         AND Z.EBGT_DGR = A.EBGT_DGR
                                         AND Z.CTP_ID   = A.CTP_ID
                                         AND Z.SIT_CD   = p_SIT_CD 
                                         AND Z.EBGT_DGR = v_EBGT_DGR
                                         AND Z.DTLS_YN  = '1' --내역여부
         WHERE A.SIT_CD   = p_SIT_CD
           AND A.EBGT_DGR = v_EBGT_DGR
         GROUP BY Z.SIT_CD
        ;


    --#. [하자_도급/실행금액] 조회인 경우
    ELSIF p_INQ_DIV = 'DEFC' THEN
        WITH TMP_10 AS (--하자 : 공종ID SELECT
                        SELECT A.SIT_CD
                              ,A.EBGT_DGR
                              ,A.CTP_ID
                          FROM TCMA_EBGT_DTL A
                         WHERE A.SIT_CD        = p_SIT_CD
                           AND A.EBGT_DGR      = v_EBGT_DGR
                         START WITH A.SIT_CD   = p_SIT_CD
                                AND A.EBGT_DGR = v_EBGT_DGR
                                AND A.STD_CD   = 'E' --하자보수충당금
                         CONNECT BY PRIOR A.SIT_CD   = A.SIT_CD
                                AND PRIOR A.EBGT_DGR = A.EBGT_DGR
                                AND PRIOR A.CTP_ID   = A.HRNK_CTP_ID
                       )

        SELECT OCMZ_SAFT_DEFC_IF ( 
                                  Z.SIT_CD        --현장코드                       : SIT_CD       
                                 ,NULL            --계약번호(= 발주번호) : 외주用  : CONT_NO      
                                 ,NULL            --거래처코드           : 외주用  : CUST_CD

                                 ,0               --안전_도급금액                  : SAFT_UNTK_AMT
                                 ,0               --안전_실행금액                  : SAFT_EBGT_AMT
                                 ,0               --안전_계약금액                  : SAFT_CONT_AMT

                                 ,SUM(Z.UNTK_AMT) --하자_도급금액                  : DEFC_UNTK_AMT
                                 ,SUM(Z.EBGT_AMT) --하자_실행금액                  : DEFC_EBGT_AMT    ( 하자 보수비 ? )
                                 )
          BULK COLLECT INTO v_RESULT_ROW
          FROM TMP_10 A
               INNER JOIN TCMA_EBGT_DTL Z ON Z.SIT_CD   = A.SIT_CD
                                         AND Z.EBGT_DGR = A.EBGT_DGR
                                         AND Z.CTP_ID   = A.CTP_ID
                                         AND Z.SIT_CD   = p_SIT_CD 
                                         AND Z.EBGT_DGR = v_EBGT_DGR
                                         AND Z.DTLS_YN  = '1' --내역여부
         WHERE A.SIT_CD   = p_SIT_CD
           AND A.EBGT_DGR = v_EBGT_DGR
         GROUP BY Z.SIT_CD
        ;


    --#. [안전_계약금액 : 최종계약건 기준] 조회인 경우
    ELSIF p_INQ_DIV = 'SM' THEN
        WITH TMP_10 AS (--안전 : 공종ID SELECT
                        SELECT A.SIT_CD
                              ,A.EBGT_DGR
                              ,A.CTP_ID
                          FROM TCMA_EBGT_DTL A
                         WHERE A.SIT_CD        = p_SIT_CD
                           AND A.EBGT_DGR      = v_EBGT_DGR
                         START WITH A.SIT_CD   = p_SIT_CD
                                AND A.EBGT_DGR = v_EBGT_DGR
                                AND A.STD_CD   = 'B002001' --산업안전보건법
                         CONNECT BY PRIOR A.SIT_CD   = A.SIT_CD
                                AND PRIOR A.EBGT_DGR = A.EBGT_DGR
                                AND PRIOR A.CTP_ID   = A.HRNK_CTP_ID
                       )

        SELECT OCMZ_SAFT_DEFC_IF ( 
                                  Z.SIT_CD        --현장코드                       : SIT_CD       
                                 ,Z.ORD_NO        --계약번호(= 발주번호) : 외주用  : CONT_NO      
                                 ,MAX(B.CUST_CD)  --거래처코드           : 외주用  : CUST_CD

                                 ,0               --안전_도급금액                  : SAFT_UNTK_AMT
                                 ,0               --안전_실행금액                  : SAFT_EBGT_AMT
                                 ,SUM(Z.CONT_AMT) --안전_계약금액                  : SAFT_CONT_AMT

                                 ,0               --하자_도급금액                  : DEFC_UNTK_AMT
                                 ,0               --하자_실행금액                  : DEFC_EBGT_AMT
                                 )

          BULK COLLECT INTO v_RESULT_ROW
          FROM TMP_10 A
               INNER JOIN TSMC_CONT_DTL Z ON Z.SIT_CD      = A.SIT_CD
                                         AND Z.CTP_ID      = A.CTP_ID
               INNER JOIN TSMC_CONT     B ON B.SIT_CD      = Z.SIT_CD
                                         AND B.ORD_NO      = Z.ORD_NO
                                         AND B.ORD_DGR     = Z.ORD_DGR
                                         AND B.SIT_CD      = p_SIT_CD
                                         AND B.CUR_CONT_YN = '1' --현계약여부(최종계약)

         WHERE A.SIT_CD   = p_SIT_CD
           AND A.EBGT_DGR = v_EBGT_DGR
         GROUP BY Z.SIT_CD
                 ,Z.ORD_NO
        ;


    --#. [안전_계약금액 : 최최계약건 기준] 조회인 경우
    ELSIF p_INQ_DIV = 'SM_0' THEN
        WITH TMP_10 AS (--안전 : 공종ID SELECT
                        SELECT A.SIT_CD
                              ,A.EBGT_DGR
                              ,A.CTP_ID
                          FROM TCMA_EBGT_DTL A
                         WHERE A.SIT_CD        = p_SIT_CD
                           AND A.EBGT_DGR      = v_EBGT_DGR
                         START WITH A.SIT_CD   = p_SIT_CD
                                AND A.EBGT_DGR = v_EBGT_DGR
                                AND A.STD_CD   = 'B002001' --산업안전보건법
                         CONNECT BY PRIOR A.SIT_CD   = A.SIT_CD
                                AND PRIOR A.EBGT_DGR = A.EBGT_DGR
                                AND PRIOR A.CTP_ID   = A.HRNK_CTP_ID
                       )

        SELECT OCMZ_SAFT_DEFC_IF ( 
                                  Z.SIT_CD        --현장코드                       : SIT_CD       
                                 ,Z.ORD_NO        --계약번호(= 발주번호) : 외주用  : CONT_NO      
                                 ,MAX(B.CUST_CD)  --거래처코드           : 외주用  : CUST_CD

                                 ,0               --안전_도급금액                  : SAFT_UNTK_AMT
                                 ,0               --안전_실행금액                  : SAFT_EBGT_AMT
                                 ,SUM(Z.CONT_AMT) --안전_계약금액                  : SAFT_CONT_AMT

                                 ,0               --하자_도급금액                  : DEFC_UNTK_AMT
                                 ,0               --하자_실행금액                  : DEFC_EBGT_AMT
                                 )

          BULK COLLECT INTO v_RESULT_ROW
          FROM TMP_10 A
               INNER JOIN TSMC_CONT_DTL Z ON Z.SIT_CD  = A.SIT_CD
                                         AND Z.CTP_ID  = A.CTP_ID
               INNER JOIN TSMC_CONT     B ON B.SIT_CD  = Z.SIT_CD
                                         AND B.ORD_NO  = Z.ORD_NO
                                         AND B.ORD_DGR = Z.ORD_DGR
                                         AND B.SIT_CD  = p_SIT_CD
                                         AND B.ORD_DGR = 0 --최초계약 건

         WHERE A.SIT_CD   = p_SIT_CD
           AND A.EBGT_DGR = v_EBGT_DGR
         GROUP BY Z.SIT_CD
                 ,Z.ORD_NO
        ;
    END IF;

    RETURN v_RESULT_ROW;
END;
/

-- PQHA_ADDRISK_NCR_CNC_S (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_ADDRISK_NCR_CNC_S" (
    p_WRK_TP            VARCHAR2 :='U'                      -- UPDATE FLAG( I: ISNERT, U:UPDATE, D:DELTE)
,   p_WRK_ID            VARCHAR2                            -- 사용자 ID 
,   p_WRK_IP            VARCHAR2                            -- 사용자 IP 
,   p_SIT_CD            TQHA_ADDRISK_ORD.SIT_CD%TYPE        -- 현장코드
,   p_WRT_DT            TQHA_ADDRISK_ORD.WRT_DT%TYPE        -- 작성일자
,   p_WRT_SEQ           TQHA_ADDRISK_ORD.WRT_SEQ%TYPE       -- 작성순번
)
IS 
    /**************************************************************************************************************************
      Purpose : 

      REVISIONS
      Ver      Date               Author                  Description 
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2026/01/30                                  최초생성

    **************************************************************************************************************************/

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR2(200);            -- ERROR Message
    USER_EXCEPTION EXCEPTION;

    v_NCR_DOC_NO        NVARCHAR2(20);
    v_VNDR_APRV_YN      VARCHAR2(1);
    v_MGR_APRV_YN       VARCHAR2(1);

BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 필수입력 필드  Check  ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_SIT_CD IS NULL)  THEN
        ERR_MSG := '현장코드는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_WRT_DT IS NULL)  THEN
        ERR_MSG := '작성일자는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_WRT_SEQ IS NULL  AND p_WRK_TP <> 'I')  THEN
        ERR_MSG := '작성순번는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Process 선행조건 Check ]
    ---------------------------------------------------------------------------------------------------------------------------

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Business Process ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_WRK_TP ='D') THEN

        SELECT NCR_DOC_NO
          INTO v_NCR_DOC_NO
          FROM TQHA_ADDRISK_ORD
         WHERE SIT_CD       = p_SIT_CD          --현장코드
           AND WRT_DT       = p_WRT_DT          --작성일자
           AND WRT_SEQ      = p_WRT_SEQ         --작성순번
        ;

        IF NVL(v_NCR_DOC_NO, '*') = '*' THEN
            ERR_MSG := 'NCR 발급취소된 상태입니다.';
            RAISE USER_EXCEPTION;

        -- 부적합보고서 승인 상태 체크하여, 업체 승인 요청시 또는 관리자 승인시엔 불량에서 다른걸로 변경하지 못하게 막아야 함.
        ELSE

            SELECT VNDR_APRV_YN
                 , MGR_APRV_YN
              INTO v_VNDR_APRV_YN
                 , v_MGR_APRV_YN
              FROM TQHA_NCR_REP
             WHERE SIT_CD       = p_SIT_CD
               AND NCR_DOC_NO   = v_NCR_DOC_NO
            ;

            IF v_MGR_APRV_YN = '1' THEN
                ERR_MSG := '부적합보고서 관리자가 승인한 상태여서 발급취소할 수 없습니다.'
                        || CHR(10) || '관리자 반려 후, 업체 승인요청취소 후에 변경 가능합니다. ';
                RAISE USER_EXCEPTION;
            END IF;

            IF v_VNDR_APRV_YN = '1' THEN
                ERR_MSG := '부적합보고서 업체 승인요청중이어서 발급취소할 수 없습니다.'
                        || CHR(10) || '승인요청 취소 후 변경 가능합니다 ';
                RAISE USER_EXCEPTION;
            END IF;

        END IF;

        DELETE 
          FROM TQHA_NCR_REP
         WHERE SIT_CD       = p_SIT_CD          -- 현장코드
           AND NCR_DOC_NO   = v_NCR_DOC_NO      -- 부적합보고서번호
        ;

        UPDATE TQHA_ADDRISK_ORD
           SET NCR_DOC_NO   = ''                -- 부적합문서번호
             , NCR_PUBC_YN  = '0'
             , UPD_ID       = p_WRK_ID          -- 수정ID 
             , UPD_DTM      = SYSDATE()         -- 수정일시
             , UPD_IP       = p_WRK_IP          -- 수정IP
         WHERE SIT_CD       = p_SIT_CD          -- 현장코드
           AND WRT_DT       = p_WRT_DT          -- 작성일자
           AND WRT_SEQ      = p_WRT_SEQ         -- 작성순번
        ;

    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 5. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN 
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);
END PQHA_ADDRISK_NCR_CNC_S;
/

-- PQHA_ADDRISK_ORD_CO_S (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_ADDRISK_ORD_CO_S" (
    p_WRK_TP                    VARCHAR2 :='U'                              -- UPDATE FLAG( I: ISNERT, U:UPDATE, D:DELTE)
,   p_WRK_ID                    VARCHAR2                                    -- 사용자 ID 
,   p_WRK_IP                    VARCHAR2                                    -- 사용자 IP 
,   p_SIT_CD                    TQHA_ADDRISK_ORD.SIT_CD%TYPE                -- 현장코드
,   p_CUST_CD                   TQHA_ADDRISK_ORD.CUST_CD%TYPE               -- 업체코드
,   p_VNDR_SEQ                  TQHA_ADDRISK_ORD.VNDR_SEQ%TYPE              -- 업체순번
,   p_WRT_DT                    TQHA_ADDRISK_ORD.WRT_DT%TYPE                -- 작성일자
,   p_WRT_SEQ                   TQHA_ADDRISK_ORD.WRT_SEQ%TYPE               -- 작성순번
,   p_VNDR_MA_DT                TQHA_ADDRISK_ORD.VNDR_MA_DT%TYPE            -- 업체조치일자
,   p_VNDR_MA_YN                TQHA_ADDRISK_ORD.VNDR_MA_YN%TYPE            -- 조치구분(QS007) 1 조치, 0 미조치
,   p_VNDR_MA_PSN_NM            TQHA_ADDRISK_ORD.VNDR_MA_PSN%TYPE           -- 업체조치자
,   p_VNDR_MA_CTS               TQHA_ADDRISK_ORD.VNDR_MA_CTS%TYPE           -- 업체조치내용
,   p_VNDR_PHOTO_GRP1           TQHA_ADDRISK_ORD.VNDR_PHOTO_GRP1%TYPE       -- 업체조치첨부파일그룹사진1
,   p_VNDR_PHOTO_DESC_1         TQHA_ADDRISK_ORD.VNDR_PHOTO_DESC_1%TYPE     -- 사진설명1
,   p_VNDR_PHOTO_GRP2           TQHA_ADDRISK_ORD.VNDR_PHOTO_GRP2%TYPE       -- 업체조치첨부파일그룹사진2
,   p_VNDR_PHOTO_DESC_2         TQHA_ADDRISK_ORD.VNDR_PHOTO_DESC_2%TYPE     -- 사진설명2
,   p_MGR_NOTI_YN               TQHA_ADDRISK_ORD.MGR_NOTI_YN%TYPE           -- 발송 1 미발송 0
)
IS 
    /**************************************************************************************************************************
      Purpose : 

      REVISIONS
      Ver      Date               Author                  Description 
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2026/03/03                                    최초생성

    **************************************************************************************************************************/


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR2(200);            -- ERROR Message
    USER_EXCEPTION EXCEPTION;

    v_WRT_SEQ TQHA_ADDRISK_ORD.WRT_SEQ%TYPE ;             -- 순번 변수 선언

BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 필수입력 필드  Check  ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_SIT_CD IS NULL)  THEN
        ERR_MSG := '현장코드는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_WRT_DT IS NULL)  THEN
        ERR_MSG := '작성일자는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Process 선행조건 Check ]
    ---------------------------------------------------------------------------------------------------------------------------


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Business Process ]
    ---------------------------------------------------------------------------------------------------------------------------
    -- 폼 저장 : 추가위험발굴 조치결과 작성
    IF p_WRK_TP ='U1' THEN

        UPDATE TQHA_ADDRISK_ORD
           SET VNDR_MA_DT           = p_VNDR_MA_DT               -- 조치일자
             , VNDR_MA_YN           = p_VNDR_MA_YN               -- 조치여부
             , VNDR_MA_PSN          = p_VNDR_MA_PSN_NM          -- 조치자
             , VNDR_MA_CTS          = p_VNDR_MA_CTS             -- 조치내용
             , VNDR_PHOTO_GRP1      = p_VNDR_PHOTO_GRP1     -- 조치후사진그룹1
             , VNDR_PHOTO_DESC_1    = p_VNDR_PHOTO_DESC_1 -- 사진설명1
             , VNDR_PHOTO_GRP2      = p_VNDR_PHOTO_GRP2     -- 조치후사진그룹2
             , VNDR_PHOTO_DESC_2    = p_VNDR_PHOTO_DESC_2 -- 사진설명2
             , MGR_NOTI_YN          = p_MGR_NOTI_YN             -- 관리자 발송여부
             , UPD_ID               = p_WRK_ID
             , UPD_DTM              = SYSDATE
             , UPD_IP               = p_WRK_IP
         WHERE SIT_CD               = p_SIT_CD
           AND CUST_CD              = p_CUST_CD
           AND VNDR_SEQ             = p_VNDR_SEQ
           AND WRT_DT               = p_WRT_DT
           AND WRT_SEQ              = p_WRT_SEQ
        ;

    --------------------------------------------------------------------------------------
    -- 폼 저장 : 추가위험발굴 조치결과 SMS발송
    ELSIF p_WRK_TP ='U2' THEN

        UPDATE TQHA_ADDRISK_ORD
           SET MGR_NOTI_YN          = p_MGR_NOTI_YN -- 관리자 발송여부
             , UPD_ID               = p_WRK_ID
             , UPD_DTM              = SYSDATE
             , UPD_IP               = p_WRK_IP
         WHERE SIT_CD               = p_SIT_CD
           AND CUST_CD              = p_CUST_CD
           AND VNDR_SEQ             = p_VNDR_SEQ
           AND WRT_DT               = p_WRT_DT
           AND WRT_SEQ              = p_WRT_SEQ
        ;

    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 5. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN 
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);

END PQHA_ADDRISK_ORD_CO_S;
/

-- PQHA_ADDRISK_ORD_Q (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_ADDRISK_ORD_Q" (  
    p_WRK_TP                    IN VARCHAR2 DEFAULT 'Q'         -- FLAG(Q:ERP추가위험발굴, Q1:ERP추가위험발굴작성, B:B2B추가위험발굴, B1:B2B추가위험발굴작성)
,   p_SIT_CD                    IN VARCHAR2                     -- 현장코드
,   p_SEARCH_WRT_YM             IN VARCHAR2
,   p_SEARCH_VNDR_MA_YN         IN VARCHAR2
,   p_WRT_DT                    IN VARCHAR2
,   p_WRT_SEQ                   IN VARCHAR2
,   p_CUST_CD                   IN VARCHAR2
,   p_VNDR_SEQ                  IN VARCHAR2
,   p_SEARCH_XCL_YN             IN VARCHAR2
,   RTN_CURSOR                  OUT SYS_REFCURSOR
)
IS
    /**************************************************************************************************************************
      Purpose : [평가항목 조회] PROCEDRE (QSE > 안전관리 > 중점점검관리 > 추가위험발굴  )

      REVISIONS
      Ver      Date               Author                  Description
      -------  -----------------  ----------------------  ---------------------------------------------------------------------
      1.0      2023/12/06                                 최초생성  

    **************************************************************************************************************************/

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE  NUMBER :=-20009; -- ERROR 코드
    ERR_MSG   VARCHAR(200);    -- ERROR Message
    USER_EXCEPTION EXCEPTION;

BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 수행전 Check Logic ]
    ---------------------------------------------------------------------------------------------------------------------------

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Logic 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------

    IF p_WRK_TP = 'Q' THEN        -- ERP추가위험발굴

        OPEN RTN_CURSOR FOR
        SELECT A.SIT_CD                     -- 현장코드
             , A.WRT_DT                     -- 작성일자
             , A.WRT_SEQ                    -- 작성순번
             /*, A.ADD_RISK_TTL             -- 추가위험제목*/
             , A.MA_DDLN_DT                 -- 조치기한일자
             , A.CUST_CD                    -- 업체코드
             , CASE WHEN A.DIRECT_YN = '1' THEN '휴먼플러스 건설'
                    ELSE ( SELECT CUST_NM FROM VQSZ_TRADE WHERE CUST_CD = A.CUST_CD )
               END AS VNDR_NM               -- 업체명 (22.07.05 수정)
             , A.VNDR_SEQ                   -- 업체순번
             , A.CTP_CD                     -- 공종코드
             , A.RISK_LOC                   -- 위험위치
             , A.REQ_MATT                   -- 요구사항
             , A.PHOTO_GRP1                 -- 첨부그룹사진1
             , A.PHOTO_DESC_1               -- 사진설명1
             , A.PHOTO_GRP2                 -- 첨부그룹사진2
             , A.PHOTO_DESC_2               -- 사진설명2
             , A.RISK_CTS                   -- 위험내용
             , A.ADD_WRTR                   -- 작성자ID
             , ( SELECT USR_NM FROM TCOZ_USR_INFO WHERE USR_ID = A.ADD_WRTR ) AS ADD_WRTR_NM     -- 작성자명
             , A.VNDR_NOTI_YN               -- SMS발송여부(관리자->업체)
             , A.VNDR_NOTI_DT               -- 업체통보일자
             , A.NCR_PUBC_YN                -- 부적합문서 발행여부
             , A.NCR_DOC_NO                 -- 부적합문서번호
             , A.VNDR_MA_DT                 -- 업체조치일자
             , A.VNDR_MA_YN                 -- 조치구분
             , A.VNDR_MA_CTS                -- 업체조치내용
             , A.VNDR_MA_PSN                -- 업체조치자
             , A.VNDR_APRV_YN               -- 업체승인여부
             , A.VNDR_APRV_DT               -- 업체승인요청일자
             , A.MGR_NOTI_YN                -- SMS발송여부(업체->관리자)
             , A.MGR_APRV_YN                -- 관리자승인여부
             , A.VNDR_PHOTO_GRP1            -- 조치첨부사진그룹1
             , A.VNDR_PHOTO_DESC_1          -- 사진설명1
             , A.VNDR_PHOTO_GRP2            -- 조치첨부사진그룹2
             , A.VNDR_PHOTO_DESC_2          -- 사진설명2
          FROM TQHA_ADDRISK_ORD A
         WHERE A.SIT_CD = p_SIT_CD
           AND ( SUBSTR(A.WRT_DT,1,6) = p_SEARCH_WRT_YM OR NVL(p_SEARCH_WRT_YM, 0) = 0 )
           AND ( A.VNDR_MA_YN = p_SEARCH_VNDR_MA_YN OR NVL(p_SEARCH_VNDR_MA_YN, 0) = 0 )
         ORDER BY A.WRT_DT DESC
        ;

    --------------------------------------------------------------------------------------------
    ELSIF p_WRK_TP = 'Q1' THEN        --ERP추가위험발굴작성

        OPEN RTN_CURSOR FOR
        SELECT A.SIT_CD                     -- 현장코드
             , A.WRT_DT                     -- 작성일자
             , A.WRT_SEQ                    -- 작성순번
             /*, A.ADD_RISK_TTL             -- 추가위험제목*/
             , A.MA_DDLN_DT                 -- 조치기한일자
             , A.CUST_CD                    -- 업체코드
             , CASE WHEN A.DIRECT_YN = '1' THEN '휴먼플러스 건설'
                    ELSE ( SELECT CUST_NM FROM VQSZ_TRADE WHERE CUST_CD = A.CUST_CD )
               END AS VNDR_NM               -- 업체명 (22.07.05 수정)
             , ( SELECT VNDR_PSN_NM FROM TQHA_VNDR WHERE CUST_CD = A.CUST_CD AND SIT_CD = A.SIT_CD AND VNDR_SEQ = A.VNDR_SEQ) AS VNDR_PSN_NM -- 담당자
             , ( SELECT VNDR_PSN_CADDR FROM TQHA_VNDR WHERE CUST_CD = A.CUST_CD AND SIT_CD = A.SIT_CD AND VNDR_SEQ = A.VNDR_SEQ) AS VNDR_PSN_CADDR -- 담당자 연락처
             , A.VNDR_SEQ                   -- 업체순번
             , A.CTP_CD                     -- 공종코드
             , ( SELECT CTP_NM FROM TQHA_CTP WHERE CTP_CD = A.CTP_CD ) AS CTP_NM -- 공종명
             , A.RISK_LOC                   -- 위험위치
             , A.REQ_MATT                   -- 요구사항
             , A.PHOTO_GRP1                 -- 첨부그룹사진1
             , A.PHOTO_DESC_1               -- 사진설명1
             , A.PHOTO_GRP2                 -- 첨부그룹사진2
             , A.PHOTO_DESC_2               -- 사진설명2
             , A.RISK_CTS                   -- 위험내용
             , A.ADD_WRTR                   -- 작성자ID
             , ( SELECT USR_NM FROM TCOZ_USR_INFO WHERE USR_ID = A.ADD_WRTR ) AS ADD_WRTR_NM  -- 작성자명
             , A.VNDR_NOTI_YN               -- 업체통보여부(관리자->업체)
             , A.VNDR_NOTI_DT               -- 업체통보일자
             , A.NCR_PUBC_YN                -- 부적합문서 발행여부
             , A.NCR_DOC_NO                 -- 부적합문서번호
             , A.VNDR_MA_DT                 -- 업체조치일자 
             , A.VNDR_MA_YN                 -- 조치구분
             , A.VNDR_MA_CTS                -- 업체조치내용
             , A.VNDR_MA_PSN                -- 업체조치자ID
             , DECODE((SELECT USR_NM FROM TCOZ_USR_INFO WHERE USR_ID = A.VNDR_MA_PSN), '', A.VNDR_MA_PSN, (SELECT USR_NM FROM TCOZ_USR_INFO WHERE USR_ID = A.VNDR_MA_PSN)) AS VNDR_MA_PSN_NM  -- 업체조치자명
             , A.VNDR_APRV_YN               -- 업체승인여부
             , A.VNDR_APRV_DT               -- 업체승인요청일자
             , A.MGR_NOTI_YN                -- SMS발송여부(업체->관리자)
             , A.MGR_APRV_YN                -- 관리자승인여부
             , A.VNDR_PHOTO_GRP1            -- 조치첨부사진그룹1
             , A.VNDR_PHOTO_DESC_1          -- 사진설명1
             , A.VNDR_PHOTO_GRP2            -- 조치첨부사진그룹2
             , A.VNDR_PHOTO_DESC_2          -- 사진설명2
             , A.DIRECT_YN                  -- 직영공사 체크여부(22.07.05 추가)
             ,'▶ 승인상태 : ' ||
               CASE WHEN A.NCR_PUBC_YN = '1' THEN '부적합보고서발행(수정불가)'
                    ELSE CASE WHEN A.MGR_APRV_YN = '1' THEN '관리자승인완료'
                              ELSE CASE WHEN A.VNDR_APRV_YN = '1' THEN '업체승인요청중'
                                        ELSE '-'
                                   END
                         END
               END AS STATS_NM
          FROM TQHA_ADDRISK_ORD A
         WHERE SIT_CD           = p_SIT_CD
           AND WRT_DT           = p_WRT_DT
           AND WRT_SEQ          = p_WRT_SEQ
        ;

    --------------------------------------------------------------------------------------------
    ELSIF p_WRK_TP = 'B' THEN        --B2B추가위험발굴

        OPEN RTN_CURSOR FOR
        SELECT A.SIT_CD                 -- 현장코드
             , A.WRT_DT                 -- 작성일자
             , A.WRT_SEQ                -- 작성순번
             /*, A.ADD_RISK_TTL         -- 추가위험제목*/
             , A.MA_DDLN_DT             -- 조치기한일자
             , A.CUST_CD                -- 업체코드
             , ( SELECT CUST_NM FROM VQSZ_TRADE WHERE CUST_CD = A.CUST_CD )     AS VNDR_NM          -- 업체명
             , A.VNDR_SEQ               -- 업체순번
             , A.CTP_CD                 -- 공종코드
             , A.RISK_LOC               -- 위험위치
             , A.REQ_MATT               -- 요구사항
             , A.PHOTO_GRP1             -- 첨부그룹사진1
             , A.PHOTO_DESC_1           -- 사진설명1
             , A.PHOTO_GRP2             -- 첨부그룹사진2
             , A.PHOTO_DESC_2           -- 사진설명2
             , A.RISK_CTS               -- 위험내용
             , A.ADD_WRTR               -- 작성자ID
             , ( SELECT USR_NM FROM TCOZ_USR_INFO WHERE USR_ID = A.ADD_WRTR )   AS ADD_WRTR_NM      -- 작성자명
             , A.VNDR_NOTI_YN           -- SMS발송여부(관리자->업체)
             , A.VNDR_NOTI_DT           -- 업체통보일자
             , A.NCR_PUBC_YN            -- 부적합문서 발행여부
             , A.NCR_DOC_NO             -- 부적합문서번호
             , A.VNDR_MA_DT             -- 업체조치일자
             , A.VNDR_MA_YN             -- 조치구분
             , A.VNDR_MA_CTS            -- 업체조치내용
             , A.VNDR_MA_PSN            -- 업체조치자
             , A.VNDR_APRV_YN           -- 업체승인여부
             , A.VNDR_APRV_DT           -- 업체승인요청일자
             , A.MGR_NOTI_YN            -- SMS발송여부(업체->관리자)
             , A.MGR_APRV_YN            -- 관리자승인여부
             , A.VNDR_PHOTO_GRP1        -- 조치첨부사진그룹1
             , A.VNDR_PHOTO_DESC_1      -- 사진설명1
             , A.VNDR_PHOTO_GRP2        -- 조치첨부사진그룹2
             , A.VNDR_PHOTO_DESC_2      -- 사진설명2
          FROM TQHA_ADDRISK_ORD A
         WHERE A.SIT_CD             = p_SIT_CD
           AND A.CUST_CD            = p_CUST_CD
           AND A.VNDR_SEQ           = p_VNDR_SEQ
           AND ( SUBSTR(A.WRT_DT,1,6) = p_SEARCH_WRT_YM OR NVL(p_SEARCH_WRT_YM, 0) = 0 )
           AND ( A.VNDR_MA_YN = p_SEARCH_VNDR_MA_YN OR NVL(p_SEARCH_VNDR_MA_YN, 0) = 0 )
           AND (NVL(p_SEARCH_XCL_YN, '0') = '0' OR NVL(NCR_PUBC_YN, '0') = '0') 
         ORDER BY A.WRT_DT DESC
        ;

    --------------------------------------------------------------------------------------------
    ELSIF p_WRK_TP = 'B1' THEN        --B2B추가위험발굴상세조회

          OPEN RTN_CURSOR FOR
             SELECT A.SIT_CD                -- 현장코드
             , A.WRT_DT                     -- 작성일자
             , A.WRT_SEQ                    -- 작성순번
             /*, A.ADD_RISK_TTL             -- 추가위험제목*/
             , A.MA_DDLN_DT                 -- 조치기한일자
             , A.CUST_CD                    -- 업체코드
             , ( SELECT CUST_NM FROM VQSZ_TRADE WHERE CUST_CD = A.CUST_CD )                                                         AS VNDR_NM -- 업체명
             , ( SELECT VNDR_PSN_NM FROM TQHA_VNDR WHERE CUST_CD = A.CUST_CD AND SIT_CD = A.SIT_CD AND VNDR_SEQ = A.VNDR_SEQ)       AS VNDR_PSN_NM      -- 담당자
             , ( SELECT VNDR_PSN_CADDR FROM TQHA_VNDR WHERE CUST_CD = A.CUST_CD AND SIT_CD = A.SIT_CD AND VNDR_SEQ = A.VNDR_SEQ)    AS VNDR_PSN_CADDR   -- 담당자 연락처
             , A.VNDR_SEQ                   -- 업체순번
             , A.CTP_CD                     -- 공종코드
             , ( SELECT CTP_NM FROM TQHA_CTP WHERE CTP_CD = A.CTP_CD ) AS CTP_NM -- 공종명
             , A.RISK_LOC                   -- 위험위치
             , A.REQ_MATT                   -- 요구사항
             , A.PHOTO_GRP1                 -- 첨부그룹사진1
             , A.PHOTO_DESC_1               -- 사진설명1
             , A.PHOTO_GRP2                 -- 첨부그룹사진2
             , A.PHOTO_DESC_2               -- 사진설명2
             , A.RISK_CTS                   -- 위험내용
             , A.ADD_WRTR                   -- 작성자ID
             , ( SELECT USR_NM FROM TCOZ_USR_INFO WHERE USR_ID = A.ADD_WRTR ) AS ADD_WRTR_NM  -- 작성자명
             , A.VNDR_NOTI_YN               -- 업체통보여부(관리자->업체)
             , A.VNDR_NOTI_DT               -- 업체통보일자
             , A.NCR_PUBC_YN                -- 부적합문서 발행여부
             , A.NCR_DOC_NO                 -- 부적합문서번호
             , A.VNDR_MA_DT                 -- 업체조치일자 
             , A.VNDR_MA_YN                 -- 조치구분
             , A.VNDR_MA_CTS                -- 업체조치내용
             , A.VNDR_MA_PSN                -- 업체조치자ID
             , DECODE((SELECT USR_NM FROM TCOZ_USR_INFO WHERE USR_ID = A.VNDR_MA_PSN), '', A.VNDR_MA_PSN, (SELECT USR_NM FROM TCOZ_USR_INFO WHERE USR_ID = A.VNDR_MA_PSN)) AS VNDR_MA_PSN_NM -- 업체조치자명
             , A.VNDR_APRV_YN               -- 업체승인여부
             , A.VNDR_APRV_DT               -- 업체승인요청일자
             , A.MGR_NOTI_YN                -- SMS발송여부(업체->관리자)
             , A.MGR_APRV_YN                -- 관리자승인여부
             , A.VNDR_PHOTO_GRP1            -- 조치첨부사진그룹1
             , A.VNDR_PHOTO_DESC_1          -- 사진설명1
             , A.VNDR_PHOTO_GRP2            -- 조치첨부사진그룹2
             , A.VNDR_PHOTO_DESC_2          -- 사진설명2
             , '▶ 승인상태 : ' || 
               CASE WHEN A.NCR_PUBC_YN = '1' THEN '부적합보고서발행'
                    ELSE CASE WHEN A.MGR_APRV_YN = '1' THEN '관리자승인완료'
                              ELSE CASE WHEN A.VNDR_APRV_YN = '1' THEN '승인요청중'
                                        ELSE '-'
                                   END
                         END
               END  AS STATS_NM
          FROM TQHA_ADDRISK_ORD A
         WHERE A.SIT_CD         = p_SIT_CD
           AND A.CUST_CD        = p_CUST_CD
           AND A.VNDR_SEQ       = p_VNDR_SEQ
           AND A.WRT_DT         = p_WRT_DT
           AND A.WRT_SEQ        = p_WRT_SEQ
         ORDER BY A.WRT_DT DESC
        ;

    END IF;


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
         WHEN OTHERS THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);

END PQHA_ADDRISK_ORD_Q;
/

-- PQHA_ADDRISK_ORD_S (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_ADDRISK_ORD_S" (
    p_WRK_TP                    VARCHAR2 :='U'                                          -- UPDATE FLAG( I: ISNERT, U:UPDATE, D:DELTE)
,   p_WRK_ID                    VARCHAR2                                                -- 사용자 ID
,   p_WRK_IP                    VARCHAR2                                                -- 사용자 IP
,   p_SIT_CD                    TQHA_ADDRISK_ORD.SIT_CD                     %TYPE       -- 현장코드
,   p_WRT_DT                    TQHA_ADDRISK_ORD.WRT_DT                     %TYPE       -- 작성일자
,   p_WRT_SEQ                   TQHA_ADDRISK_ORD.WRT_SEQ                    %TYPE       -- 작성순번
--, p_ADD_RISK_TTL              TQHA_ADDRISK_ORD.ADD_RISK_TTL               %TYPE       -- 추가위험제목
,   p_MA_DDLN_DT                TQHA_ADDRISK_ORD.MA_DDLN_DT                 %TYPE       -- 조치기한일자
,   p_CUST_CD                   TQHA_ADDRISK_ORD.CUST_CD                    %TYPE       -- 업체코드
,   p_VNDR_SEQ                  TQHA_ADDRISK_ORD.VNDR_SEQ                   %TYPE       -- 업체순번
,   p_CTP_CD                    TQHA_ADDRISK_ORD.CTP_CD                     %TYPE       -- 공종코드
,   p_RISK_LOC                  TQHA_ADDRISK_ORD.RISK_LOC                   %TYPE       -- 위험위치
,   p_REQ_MATT                  TQHA_ADDRISK_ORD.REQ_MATT                   %TYPE       -- 요구사항
,   p_PHOTO_GRP1                TQHA_ADDRISK_ORD.PHOTO_GRP1                 %TYPE       -- 첨부파일그룹사진1
,   p_PHOTO_DESC_1              TQHA_ADDRISK_ORD.PHOTO_DESC_1               %TYPE       -- 사진설명1
,   p_PHOTO_GRP2                TQHA_ADDRISK_ORD.PHOTO_GRP2                 %TYPE       -- 첨부파일그룹사진2
,   p_PHOTO_DESC_2              TQHA_ADDRISK_ORD.PHOTO_DESC_2               %TYPE       -- 사진설명2
,   p_RISK_CTS                  TQHA_ADDRISK_ORD.RISK_CTS                   %TYPE       -- 위험내용
,   p_ADD_WRTR                  TQHA_ADDRISK_ORD.ADD_WRTR                   %TYPE       -- 작성자
,   p_VNDR_NOTI_YN              TQHA_ADDRISK_ORD.VNDR_NOTI_YN               %TYPE       -- 발송Y (SMS)
,   p_VNDR_NOTI_DT              TQHA_ADDRISK_ORD.VNDR_NOTI_DT               %TYPE       -- 업체통보일자
,   p_NCR_PUBC_YN               TQHA_ADDRISK_ORD.NCR_PUBC_YN                %TYPE       -- 발행 1, 미발행 0
,   p_NCR_DOC_NO                TQHA_ADDRISK_ORD.NCR_DOC_NO                 %TYPE       -- 부적합문서번호
,   p_VNDR_MA_DT                TQHA_ADDRISK_ORD.VNDR_MA_DT                 %TYPE       -- 업체조치일자
,   p_VNDR_MA_YN                TQHA_ADDRISK_ORD.VNDR_MA_YN                 %TYPE       -- 조치구분(QS007) 1 조치, 0 미조치
,   p_VNDR_MA_CTS               TQHA_ADDRISK_ORD.VNDR_MA_CTS                %TYPE       -- 업체조치내용
,   p_VNDR_MA_PSN               TQHA_ADDRISK_ORD.VNDR_MA_PSN                %TYPE       -- 업체조치자
,   p_VNDR_PHOTO_GRP1           TQHA_ADDRISK_ORD.VNDR_PHOTO_GRP1            %TYPE       -- 업체조치첨부파일그룹사진1
,   p_VNDR_PHOTO_DESC_1         TQHA_ADDRISK_ORD.VNDR_PHOTO_DESC_1          %TYPE       -- 사진설명1
,   p_VNDR_PHOTO_GRP2           TQHA_ADDRISK_ORD.VNDR_PHOTO_GRP2            %TYPE       -- 업체조치첨부파일그룹사진2
,   p_VNDR_PHOTO_DESC_2         TQHA_ADDRISK_ORD.VNDR_PHOTO_DESC_2          %TYPE       -- 사진설명2
,   p_VNDR_APRV_YN              TQHA_ADDRISK_ORD.VNDR_APRV_YN               %TYPE       -- 승인요청 1 미요청 0
,   p_VNDR_APRV_DT              TQHA_ADDRISK_ORD.VNDR_APRV_DT               %TYPE       -- 업체승인요청일자
,   p_MGR_NOTI_YN               TQHA_ADDRISK_ORD.MGR_NOTI_YN                %TYPE       -- 발송 1 미발송 0
,   p_MGR_APRV_YN               TQHA_ADDRISK_ORD.MGR_APRV_YN                %TYPE       -- 승인 1, 반려 2
,   p_DIRECT_YN                 TQHA_ADDRISK_ORD.DIRECT_YN                  %TYPE       -- 직영여부
,   p_RNT_WRT_SEQ               OUT VARCHAR2)                                           -- 리턴변수(작성순번)
IS
    /**************************************************************************************************************************
      Purpose :

      REVISIONS
      Ver      Date               Author                  Description
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2021/11/05 14:17:07                         최초생성

    **************************************************************************************************************************/


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR2(200);            -- ERROR Message
    USER_EXCEPTION EXCEPTION;

    v_WRT_SEQ TQHA_ADDRISK_ORD.WRT_SEQ%TYPE ;             -- 순번 변수 선언

BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 필수입력 필드  Check  ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_SIT_CD IS NULL)  THEN
        ERR_MSG := '현장코드는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_WRT_DT IS NULL)  THEN
        ERR_MSG := '작성일자는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_WRT_SEQ IS NULL  AND p_WRK_TP <> 'I')  THEN
        ERR_MSG := '작성순번는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Process 선행조건 Check ]
    ---------------------------------------------------------------------------------------------------------------------------


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Business Process ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_WRK_TP ='D') THEN

        DELETE
          FROM TQHA_ADDRISK_ORD
         WHERE SIT_CD       = p_SIT_CD      -- 현장코드
           AND WRT_DT       = p_WRT_DT      -- 작성일자
           AND WRT_SEQ      = p_WRT_SEQ     -- 작성순번
        ;

        v_WRT_SEQ := p_WRT_SEQ;

    ELSIF (p_WRK_TP ='U') THEN

        UPDATE TQHA_ADDRISK_ORD
           SET -- ADD_RISK_TTL          = p_ADD_RISK_TTL            -- 추가위험제목
               MA_DDLN_DT               = p_MA_DDLN_DT              -- 조치기한일자
             , CUST_CD                  = p_CUST_CD                 -- 업체코드
             , VNDR_SEQ                 = p_VNDR_SEQ                -- 업체순번
             , CTP_CD                   = p_CTP_CD                  -- 공종코드
             , RISK_LOC                 = p_RISK_LOC                -- 위험위치
             , REQ_MATT                 = p_REQ_MATT                -- 요구사항
             , PHOTO_GRP1               = p_PHOTO_GRP1              -- 첨부파일그룹사진1
             , PHOTO_DESC_1             = p_PHOTO_DESC_1            -- 사진설명1
             , PHOTO_GRP2               = p_PHOTO_GRP2              -- 첨부파일그룹사진2
             , PHOTO_DESC_2             = p_PHOTO_DESC_2            -- 사진설명2
             , RISK_CTS                 = p_RISK_CTS                -- 위험내용
             , ADD_WRTR                 = p_ADD_WRTR                -- 작성자
             , VNDR_NOTI_YN             = p_VNDR_NOTI_YN            -- 발송Y (SMS)
             , VNDR_NOTI_DT             = p_VNDR_NOTI_DT            -- 업체통보일자
             , NCR_PUBC_YN              = p_NCR_PUBC_YN             -- 발행 1, 미발행 0
             , NCR_DOC_NO               = p_NCR_DOC_NO              -- 부적합문서번호
             , VNDR_MA_DT               = p_VNDR_MA_DT              -- 업체조치일자
             , VNDR_MA_YN               = p_VNDR_MA_YN              -- 조치구분(QS007) 1 조치, 0 미조치
             , VNDR_MA_CTS              = p_VNDR_MA_CTS             -- 업체조치내용
             , VNDR_MA_PSN              = p_VNDR_MA_PSN             -- 업체조치자
             , VNDR_PHOTO_GRP1          = p_VNDR_PHOTO_GRP1         -- 업체조치첨부파일그룹사진1
             , VNDR_PHOTO_DESC_1        = p_VNDR_PHOTO_DESC_1       -- 사진설명1
             , VNDR_PHOTO_GRP2          = p_VNDR_PHOTO_GRP2         -- 업체조치첨부파일그룹사진2
             , VNDR_PHOTO_DESC_2        = p_VNDR_PHOTO_DESC_2       -- 사진설명2
             , VNDR_APRV_YN             = p_VNDR_APRV_YN            -- 승인요청 1 미요청 0
             , VNDR_APRV_DT             = p_VNDR_APRV_DT            -- 업체승인요청일자
             , MGR_NOTI_YN              = p_MGR_NOTI_YN             -- 발송 1 미발송 0
             , MGR_APRV_YN              = p_MGR_APRV_YN             -- 승인 1, 반려 2
             , DIRECT_YN                = p_DIRECT_YN               -- 직영여부
             , UPD_ID                   = p_WRK_ID                  -- 수정ID
             , UPD_DTM                  = SYSDATE()                 -- 수정일시
             , UPD_IP                   = p_WRK_IP                  -- 수정IP
         WHERE SIT_CD                   = p_SIT_CD                  --현장코드
           AND WRT_DT                   = p_WRT_DT                  --작성일자
           AND WRT_SEQ                  = p_WRT_SEQ                 --작성순번
        ;

        v_WRT_SEQ := p_WRT_SEQ;

    ELSE

        -- 순번 생성
        SELECT NVL( (MAX(WRT_SEQ)+1),'1' )
          INTO v_WRT_SEQ
          FROM TQHA_ADDRISK_ORD
         WHERE SIT_CD       = p_SIT_CD      -- 현장코드
           AND WRT_DT       = p_WRT_DT      -- 일자
        ;

        -- 순번 생성
        INSERT
          INTO TQHA_ADDRISK_ORD
             ( SIT_CD                   -- 현장코드
             , WRT_DT                   -- 작성일자
             , WRT_SEQ                  -- 작성순번
             --, ADD_RISK_TTL           -- 추가위험제목
             , MA_DDLN_DT               -- 조치기한일자
             , CUST_CD                  -- 업체코드
             , VNDR_SEQ                 -- 업체순번
             , CTP_CD                   -- 공종코드
             , RISK_LOC                 -- 위험위치
             , REQ_MATT                 -- 요구사항
             , PHOTO_GRP1               -- 첨부파일그룹사진1
             , PHOTO_DESC_1             -- 사진설명1
             , PHOTO_GRP2               -- 첨부파일그룹사진2
             , PHOTO_DESC_2             -- 사진설명2
             , RISK_CTS                 -- 위험내용
             , ADD_WRTR                 -- 작성자
             , VNDR_NOTI_YN             -- 발송Y (SMS)
             , VNDR_NOTI_DT             -- 업체통보일자
             , NCR_PUBC_YN              -- 발행 1, 미발행 0
             , NCR_DOC_NO               -- 부적합문서번호
             , VNDR_MA_DT               -- 업체조치일자
             , VNDR_MA_YN               -- 조치구분(QS007) 1 조치, 0 미조치
             , VNDR_MA_CTS              -- 업체조치내용
             , VNDR_MA_PSN              -- 업체조치자
             , VNDR_PHOTO_GRP1          -- 업체조치첨부파일그룹사진1
             , VNDR_PHOTO_DESC_1        -- 사진설명1
             , VNDR_PHOTO_GRP2          -- 업체조치첨부파일그룹사진2
             , VNDR_PHOTO_DESC_2        -- 사진설명2
             , VNDR_APRV_YN             -- 승인요청 1 미요청 0
             , VNDR_APRV_DT             -- 업체승인요청일자
             , MGR_NOTI_YN              -- 발송 1 미발송 0
             , MGR_APRV_YN              -- 승인 1, 반려 2
             , DIRECT_YN                -- 직영여부
             , IPT_ID                   -- 입력ID
             , IPT_DTM                  -- 입력일시
             , IPT_IP                   -- 입력IP
             , UPD_ID                   -- 수정ID
             , UPD_DTM                  -- 수정일시
             , UPD_IP                   -- 수정IP
             )
        VALUES
             ( p_SIT_CD                 -- 현장코드
             , p_WRT_DT                 -- 작성일자
             , v_WRT_SEQ                -- 작성순번
             --,p_ADD_RISK_TTL          -- 추가위험제목
             , p_MA_DDLN_DT             -- 조치기한일자
             , p_CUST_CD                -- 업체코드
             , p_VNDR_SEQ               -- 업체순번
             , p_CTP_CD                 -- 공종코드
             , p_RISK_LOC               -- 위험위치
             , p_REQ_MATT               -- 요구사항
             , p_PHOTO_GRP1             -- 첨부파일그룹사진1
             , p_PHOTO_DESC_1           -- 사진설명1
             , p_PHOTO_GRP2             -- 첨부파일그룹사진2
             , p_PHOTO_DESC_2           -- 사진설명2
             , p_RISK_CTS               -- 위험내용
             , p_ADD_WRTR               -- 작성자
             , p_VNDR_NOTI_YN           -- 발송Y (SMS)
             , p_VNDR_NOTI_DT           -- 업체통보일자
             , p_NCR_PUBC_YN            -- 발행 1, 미발행 0
             , p_NCR_DOC_NO             -- 부적합문서번호
             , p_VNDR_MA_DT             -- 업체조치일자
             , p_VNDR_MA_YN             -- 조치구분(QS007) 1 조치, 0 미조치
             , p_VNDR_MA_CTS            -- 업체조치내용
             , p_VNDR_MA_PSN            -- 업체조치자
             , p_VNDR_PHOTO_GRP1        -- 업체조치첨부파일그룹사진1
             , p_VNDR_PHOTO_DESC_1      -- 사진설명1
             , p_VNDR_PHOTO_GRP2        -- 업체조치첨부파일그룹사진2
             , p_VNDR_PHOTO_DESC_2      -- 사진설명2
             , p_VNDR_APRV_YN           -- 승인요청 1 미요청 0
             , p_VNDR_APRV_DT           -- 업체승인요청일자
             , p_MGR_NOTI_YN            -- 발송 1 미발송 0
             , p_MGR_APRV_YN            -- 승인 1, 반려 2
             , p_DIRECT_YN              -- 직영여부
             , p_WRK_ID                 -- 입력ID
             , SYSDATE()                -- 입력일시
             , p_WRK_IP                 -- 입력IP
             , p_WRK_ID                 -- 수정ID
             , SYSDATE()                -- 수정일시
             , p_WRK_IP                 -- 수정IP
             )
        ;

    END IF;

       p_RNT_WRT_SEQ := v_WRT_SEQ;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 5. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);

END PQHA_ADDRISK_ORD_S;
/

-- PQHA_ADDRISK_ORD_W (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_ADDRISK_ORD_W" (
    p_WRK_TP                VARCHAR2 :='U'      -- UPDATE FLAG( I: ISNERT, U:UPDATE, D:DELTE)
,   p_WRK_ID                VARCHAR2            -- 사용자 ID
,   p_WRK_IP                VARCHAR2            -- 사용자 IP
,   p_SIT_CD                VARCHAR2            -- 현장코드
,   p_CUST_CD               VARCHAR2            -- 협력업체코드
,   p_VNDR_SEQ              VARCHAR2            -- 업체순번
,   p_WRT_DT                VARCHAR2            -- 작성일
,   p_WRT_SEQ               VARCHAR2            -- 작성순번
)
IS
    /**************************************************************************************************************************
      Purpose :

      REVISIONS
      Ver      Date               Author                  Description
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2025/01/27                                    최초생성

    /**************************************************************************************************************************/

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR(200);             -- ERROR Message
    USER_EXCEPTION EXCEPTION;

    v_VNDR_APRV_YN  VARCHAR2(1);
    v_VNDR_APRV_DT  VARCHAR2(8);
    v_MGR_APRV_YN   VARCHAR2(1);

BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 필수입력 필드  Check  ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_SIT_CD IS NULL)  THEN
        ERR_MSG := '현장코드는 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_CUST_CD IS NULL)  THEN
        ERR_MSG := '협력업체코드는 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_VNDR_SEQ IS NULL)  THEN
        ERR_MSG := '업체순번은 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_WRT_DT IS NULL)  THEN
        ERR_MSG := '작성일은 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_WRT_SEQ IS NULL)  THEN
        ERR_MSG := '작성순번은 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Process 선행조건 Check ]
    ---------------------------------------------------------------------------------------------------------------------------

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Business Process ]
    ---------------------------------------------------------------------------------------------------------------------------
    -- 업체 승인요청 / 요청 취소
    IF (p_WRK_TP IN ('APRV_CO', 'RSTOR_CO')) THEN

        -- 관리자 승인 여부 체크
        SELECT NVL(MAX(MGR_APRV_YN), '0')
          INTO v_MGR_APRV_YN
          FROM TQHA_ADDRISK_ORD
         WHERE SIT_CD               = p_SIT_CD
           AND CUST_CD              = p_CUST_CD
           AND VNDR_SEQ             = p_VNDR_SEQ
           AND WRT_DT               = p_WRT_DT
           AND WRT_SEQ              = p_WRT_SEQ
        ;

        IF v_MGR_APRV_YN = '1' THEN
            IF p_WRK_TP = 'APRV_CO' THEN
                ERR_MSG := '승인된 상태이므로 제출 불가합니다.';
            ELSE
                ERR_MSG := '승인된 상태이므로 제출취소 불가합니다.';
            END IF;

            RAISE USER_EXCEPTION;
        END IF;

        v_VNDR_APRV_YN := CASE WHEN p_WRK_TP = 'APRV_CO' THEN '1' ELSE '0' END;
        v_VNDR_APRV_DT := CASE WHEN p_WRK_TP = 'APRV_CO' THEN TO_CHAR(SYSDATE, 'YYYYMMDD') ELSE '' END;

        UPDATE TQHA_ADDRISK_ORD
           SET VNDR_APRV_YN         = v_VNDR_APRV_YN
             , VNDR_APRV_DT         = v_VNDR_APRV_DT
             , UPD_ID               = p_WRK_ID
             , UPD_DTM              = SYSDATE
         WHERE SIT_CD               = p_SIT_CD
           AND CUST_CD              = p_CUST_CD
           AND VNDR_SEQ             = p_VNDR_SEQ
           AND WRT_DT               = p_WRT_DT
           AND WRT_SEQ              = p_WRT_SEQ
        ;

    ---------------------------------------------------------------------------------
    -- 관리자 승인 / 반려
    ELSIF (p_WRK_TP IN ('APRV', 'RSTOR')) THEN

        -- 업체 승인요청 여부 체크
        SELECT NVL(MAX(VNDR_APRV_YN), '0')
          INTO v_VNDR_APRV_YN
          FROM TQHA_ADDRISK_ORD
         WHERE SIT_CD               = p_SIT_CD
           AND CUST_CD              = p_CUST_CD
           AND VNDR_SEQ             = p_VNDR_SEQ
           AND WRT_DT               = p_WRT_DT
           AND WRT_SEQ              = p_WRT_SEQ
        ;

        IF v_VNDR_APRV_YN = '0' THEN
            ERR_MSG := '업체 승인요청상태가 아니어서 승인 및 반려가 불가합니다.';
            RAISE USER_EXCEPTION;
        END IF;

        v_MGR_APRV_YN := CASE WHEN p_WRK_TP = 'APRV' THEN '1' ELSE '0' END;

        UPDATE TQHA_ADDRISK_ORD
           SET MGR_APRV_YN          = v_MGR_APRV_YN
             , UPD_ID               = p_WRK_ID
             , UPD_DTM              = SYSDATE
         WHERE SIT_CD               = p_SIT_CD
           AND CUST_CD              = p_CUST_CD
           AND VNDR_SEQ             = p_VNDR_SEQ
           AND WRT_DT               = p_WRT_DT
           AND WRT_SEQ              = p_WRT_SEQ
        ;

    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 5. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
         WHEN OTHERS THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);
END;
/

-- PQHA_APPVLINE_Q (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_APPVLINE_Q" 
(
      p_WRK_TP  	VARCHAR2 DEFAULT 'Q'    -- FLAG( Q: SELECT )
     ,p_SIT_CD 	VARCHAR2                -- 현장코드
     ,p_APRV_NO 	VARCHAR2                -- 결재번호
     ,RTN_CURSOR 	OUT SYS_REFCURSOR
)
IS

    /**************************************************************************************************************************
      Purpose : 현장별 결재번호별 결재라인 조회

      REVISIONS
      Ver      Date               Author                  Description
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2022/5/2 11:38:19                            최초생성

    **************************************************************************************************************************/

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR2(200);            -- ERROR Message
    USER_EXCEPTION EXCEPTION;

    v_cnt  INTEGER;                                -- 결재 라인 존재 여부
    v_QUERY VARCHAR2(4000); 

BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 수행전 Check Logic ]
    ---------------------------------------------------------------------------------------------------------------------------


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Logic 처리
    ---------------------------------------------------------------------------------------------------------------------------

	-- 결재라인 이 존재하는지 체크
    SELECT nvl(COUNT(APRV_SO),0)
      INTO v_cnt
      FROM   TQHA_APRV_LINE A
           , TCOZ_USR_INFO B
     WHERE A.APRV_PSN_ID = B.USR_ID
       AND A.SIT_CD = p_SIT_CD
       AND A.APRV_NO = p_APRV_NO ;


         IF v_cnt >= 1 THEN   -- 이미 결재라인 이 존재하는 경우
			 OPEN RTN_CURSOR FOR
		     SELECT   A.SIT_CD
					, A.APRV_NO
					, A.APRV_SO
					, A.APRV_PSN_ID AS USR_ID
					, B.USR_NM
					, B.JB_NM
					, A.APRV_STATS
					, A.APRV_OPIN
					, TO_CHAR(A.APRV_APRV_DTM, 'YYMMDDHH24MI') AS APRV_DTM
					, A.APRV_APRV_DTM
			  FROM  TQHA_APRV_LINE A
			      , TCOZ_USR_INFO B
			 WHERE  A.APRV_PSN_ID = B.USR_ID
			   AND  A.SIT_CD = p_SIT_CD
			   AND  A.APRV_NO = p_APRV_NO
		            ;

        ELSIF v_cnt < 1  THEN   -- 결재라인이 없는 경우

             -- 임시 테이블에 결재라인 4개 생성
        	 OPEN RTN_CURSOR FOR
   		     SELECT p_SIT_CD SIT_CD, p_APRV_NO APRV_NO, 1 APRV_SO, NULL USR_ID, NULL USR_NM, NULL JB_NM, NULL APRV_STATS, NULL APRV_OPIN, NULL APRV_DTM, NULL APRV_APRV_DTM FROM DUAL UNION ALL
   		     SELECT p_SIT_CD SIT_CD, p_APRV_NO APRV_NO, 2 APRV_SO, NULL USR_ID, NULL USR_NM, NULL JB_NM, NULL APRV_STATS, NULL APRV_OPIN, NULL APRV_DTM, NULL APRV_APRV_DTM FROM DUAL UNION ALL
   		     SELECT p_SIT_CD SIT_CD, p_APRV_NO APRV_NO, 3 APRV_SO, NULL USR_ID, NULL USR_NM, NULL JB_NM, NULL APRV_STATS, NULL APRV_OPIN, NULL APRV_DTM, NULL APRV_APRV_DTM FROM DUAL UNION ALL
   		     SELECT p_SIT_CD SIT_CD, p_APRV_NO APRV_NO, 4 APRV_SO, NULL USR_ID, NULL USR_NM, NULL JB_NM, NULL APRV_STATS, NULL APRV_OPIN, NULL APRV_DTM, NULL APRV_APRV_DTM FROM DUAL ;

        END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);

END PQHA_APPVLINE_Q;
/

-- PQHA_APROV_INFO_Q (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_APROV_INFO_Q" (
    p_WRK_TP                VARCHAR2 DEFAULT 'Q'        -- FLAG( Q: SELECT )
,   p_SITE_APRV_TP          VARCHAR2                    -- 결재유형
,   p_SIT_CD                VARCHAR2                    -- 현장코드
,   p_PLN_YM                VARCHAR2                    -- 계획년월
,   p_PLN_DGR               VARCHAR2                    -- 계획차수
,   p_EDU_SEQ               VARCHAR2                    -- 교육일련번호
,   p_CHK_SEQ               VARCHAR2                    -- 점검일련번호
,   p_ODAY_WRT_DT           VARCHAR2                    -- 일일작성일자
,   p_RLV_YM                VARCHAR2                    -- 결재년월 
,   p_CONF_SEQ              VARCHAR2                    -- 회의순번
,   p_FST_DIV               VARCHAR2                    -- 최초여부
,   p_ACCD_SEQ              VARCHAR2                    -- 사고순번
,   p_TRG_YY                VARCHAR2                    -- 목표년도
,   p_TRG_DGR               VARCHAR2                    -- 목표차수
,   p_ARSLT_DGR             VARCHAR2                    -- 실적차수
,   p_CHK_DIV               VARCHAR2                    -- 점검구분
,   p_CHK_DT                VARCHAR2                    -- 점검일자
,   p_CHK_DGR                VARCHAR2                    -- 점검구분
,   RTN_CURSOR              OUT SYS_REFCURSOR
) 
IS  
    /**************************************************************************************************************************
      Purpose : QSE > 안전관리 결재 정보 조회

      REVISIONS
      Ver      Date               Author                  Description 
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2025/02/25                                    최초생성

    **************************************************************************************************************************/

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=20009;          -- ERROR 코드
    ERR_MSG        VARCHAR2(200);            -- ERROR Message
    USER_EXCEPTION EXCEPTION;

BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 수행전 Check Logic ]
    ---------------------------------------------------------------------------------------------------------------------------


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Logic 처리
    ---------------------------------------------------------------------------------------------------------------------------

    ----------------------------------------------------------------------------------------------------
    --  협의체 회의 : 결재정보 조회 
    IF p_SITE_APRV_TP = '02' THEN

        OPEN RTN_CURSOR FOR
        SELECT A.SIT_CD         -- 현장코드
             , A.PLN_YM          -- 계획년월
             , A.PLN_DGR         -- 계획차수
             , A.APRV_NO         -- 결재번호
             , A.AREC_ATFL_GRP   -- 회의록 첨부파일
             , B.APRV_STATS      -- 결재상태(QS031)
             , B.APRV_CLS_NO     -- 키변수처리
             , B.SITE_APRV_TP    -- 결재유형(QS039)
             , B.APRV_ATFL_GRP   -- 결재첨부파일
          FROM TQHA_RISK_DGR A
             , TQHA_APRV B
         WHERE A.SIT_CD     = B.SIT_CD (+)
           AND A.APRV_NO    = B.APRV_NO (+)
           AND A.SIT_CD     = p_SIT_CD
           AND A.PLN_YM     = p_PLN_YM
           AND A.PLN_DGR    = p_PLN_DGR
        ;

    ----------------------------------------------------------------------------------------------------
    -- 교육 일지 : 결재정보 조회
    ELSIF p_SITE_APRV_TP = '06' THEN

        OPEN RTN_CURSOR FOR
        SELECT A.SIT_CD                -- 현장코드
             , A.EDU_SEQ                -- 교육순번
             , A.EDU_CD                -- 교육코드
             , A.DEEDU_CD                -- 교육세부코드
             , A.COP_VNDR_NM                -- 협력업체명칭
             , A.EDU_DT                -- 교육시작일
             , A.EDU_TIME                -- 교육시간
             , A.REL_LNR1                -- 관련법규1
             , A.REL_LNR2                -- 관련법규2
             , A.EDU_OBJ_MAN                -- 교육대상인원
             , A.EDU_IMPL_MAN                -- 교육실시인원
             , A.USE_TCMT                -- 교육방법
             , A.EDU_IMPL                -- 교육강사
             , A.EDU_PLC                -- 교육장소
             , A.EDU_MTD                -- 교육대상
             , A.EDU_CTS                -- 공통교육내용
             , A.EDU_CTS2                -- 개별교육내용
             , A.EDU_CTS3                -- 기타교육내용
             , A.MSDS_RMKS                -- MSDS비고
             , A.PHOTO_GRP1                -- 첨부파일그룹사진1
             , A.PHOTO_DESC_1                -- 사진설명1
             , A.PHOTO_DT_1                -- 사진설명1
             , A.PHOTO_GRP2                -- 첨부파일그룹사진2
             , A.PHOTO_DESC_2                -- 사진설명2
             , A.PHOTO_DT_2                -- 사진설명1
             , A.PHOTO_GRP3                -- 첨부파일그룹사진3
             , A.PHOTO_DESC_3                -- 사진설명3
             , A.PHOTO_DT_3                -- 사진일자3
             , A.ATFL_GRP                -- 첨부파일그룹
             , A.APRV_NO                -- 결재번호
             , A.DEEDU_CD          --세부교육코드
             , B.APRV_STATS        -- 결재상태
             , B.APRV_ATFL_GRP   -- 결재첨부파일
          FROM TQHA_EDU A
          LEFT JOIN TQHA_APRV B
            ON A.SIT_CD     = B.SIT_CD
           AND A.APRV_NO    = B.APRV_NO
         WHERE A.SIT_CD     = p_SIT_CD
           AND A.EDU_SEQ    = p_EDU_SEQ
        ;
/*
    ----------------------------------------------------------------------------------------------------
    -- 노사합동점검 : 결재정보 조회
    ELSIF p_SITE_APRV_TP = '07' THEN

        OPEN RTN_CURSOR FOR
        SELECT A.SIT_CD      -- 현장코드
             , A.CHK_SEQ      -- 점검순번
             , A.CHK_DT       -- 점검일자
             , A.LBR_PSN      -- 근로자
             , A.LBR_USR      -- 사용자
             , A.IMPTC_MATT   -- 중요사항
             , A.CORR_RSLT    -- 시정조치결과
             , A.ETC_MATT     -- 기타사항
             , A.SAFT_OPIN    -- 안전관리자 의견
             , A.SITE_OPIN    -- 현장소장 의견
             , PHOTO_GRP1 AS PHOTO_GRP1  -- 첨부파일그룹1
             , A.PHOTO_DESC_1 -- 첨부사진 명칭1
             , PHOTO_GRP2 AS PHOTO_GRP2  -- 첨부파일그룹1
             , A.PHOTO_DESC_2 -- 첨부사진 명칭2
             , A.ATFL_GRP     -- 첨부파일 그룹
             , A.APRV_NO      -- 공통코드 QS031 결재번호
             , B.APRV_STATS   -- 결재상태
             , B.APRV_ATFL_GRP   -- 결재첨부파일
        FROM TQHA_LBR_CHK A
                 LEFT JOIN TQHA_APRV B
                           ON A.SIT_CD      = B.SIT_CD
                          AND A.APRV_NO     = B.APRV_NO
        WHERE A.SIT_CD = p_SIT_CD
          AND A.CHK_SEQ = p_CHK_SEQ
        ;
        */

/*
    ----------------------------------------------------------------------------------------------------
    -- 일일안전일지 : 결재정보 조회
    ELSIF p_SITE_APRV_TP = '05' THEN

        OPEN RTN_CURSOR FOR
        SELECT A.SIT_CD         -- 현장코드
             , A.ODAY_WRT_DT     -- 작성일자
             , A.APRV_NO         -- 결재번호
             , B.APRV_STATS      -- 결재상태(QS031)
             , B.APRV_CLS_NO     -- 키변수처리
             , B.SITE_APRV_TP    -- 결재유형(QS039)
             , B.APRV_ATFL_GRP   -- 결재첨부파일
             , A.ATFL_GRP        -- 안전순회점검일지 첨부파일
          FROM TQSA_ODAYSAFE_LOG A
             , TQHA_APRV B
         WHERE A.SIT_CD         = B.SIT_CD (+)
           AND A.APRV_NO        = B.APRV_NO (+)
           AND A.SIT_CD         = p_SIT_CD
           AND A.ODAY_WRT_DT    = p_ODAY_WRT_DT
        ;
*/

    ----------------------------------------------------------------------------------------------------
    --  안전관리비 월별실적 : 결재정보 조회
    ELSIF p_SITE_APRV_TP = '09' THEN

        OPEN RTN_CURSOR FOR
        SELECT A.SIT_CD           -- 현장코드
             , A.APRV_YM
             , A.APRV_NO          -- 공통코드 QS031 결재번호
             , B.APRV_STATS       -- 결재상태
             , B.APRV_ATFL_GRP    -- 결재첨부파일
             , A.ATFL_GRP         -- 안전관리비 월별실적 첨부파일
          FROM TQHA_SAFECOST_APRV A
          LEFT JOIN TQHA_APRV B
            ON A.SIT_CD     = B.SIT_CD
           AND A.APRV_NO    = B.APRV_NO
         WHERE A.SIT_CD     = p_SIT_CD
           AND A.APRV_DIV   = '2' -- 월별예산
           AND A.APRV_YM    = p_RLV_YM
        ;

    ----------------------------------------------------------------------------------------------------
    --  노사협의체회의 : 결재정보 조회
    ELSIF p_SITE_APRV_TP = '08' THEN

        OPEN RTN_CURSOR FOR
        SELECT A.SIT_CD       -- 현장코드
             , A.CONF_SEQ      -- 회의순번
             , A.APRV_NO       -- 결재번호
             , A.ATFL_GRP      -- 첨부파일
             , B.APRV_STATS    -- 결재상태(QS031)
             , B.APRV_CLS_NO   -- 키변수처리
             , B.APRV_ATFL_GRP -- 결재첨부파일
             , B.SITE_APRV_TP  -- 결재유형(QS039)
          FROM TQHA_LAB_AREC A
             , TQHA_APRV B
         WHERE A.SIT_CD     = B.SIT_CD (+)
           AND A.APRV_NO    = B.APRV_NO (+)
           AND A.SIT_CD     = p_SIT_CD
           AND A.CONF_SEQ   = p_CONF_SEQ
        ;

    ----------------------------------------------------------------------------------------------------
    --  위험성평가 계획수립 : 결재정보 조회
    ELSIF p_SITE_APRV_TP = '01' THEN

        OPEN RTN_CURSOR FOR
        SELECT A.SIT_CD       -- 현장코드 
             , A.FST_DIV       -- 최초여부
             , A.PLN_DGR       -- 차수구분
             , A.APRV_NO       -- 결재번호
             , B.APRV_STATS    -- 결재상태(QS031)
             , B.APRV_CLS_NO   -- 키변수처리
             , B.APRV_ATFL_GRP -- 결재첨부파일
             , B.SITE_APRV_TP  -- 결재유형(QS039)
          FROM TQHA_RISKPLAN A
             , TQHA_APRV B
         WHERE A.SIT_CD     = B.SIT_CD (+)
           AND A.APRV_NO    = B.APRV_NO (+)
           AND A.SIT_CD     = p_SIT_CD
           AND A.FST_DIV    = p_FST_DIV
           AND A.PLN_DGR    = p_PLN_DGR
        ;

    ----------------------------------------------------------------------------------------------------
    --  산재관리(현장) : 결재정보 조회
    ELSIF p_SITE_APRV_TP = '10' THEN
 
        OPEN RTN_CURSOR FOR
        SELECT A.SIT_CD       -- 현장코드
             , A.ACCD_SEQ      -- 사고순번
             , A.APRV_NO       -- 결재번호
             , A.ATFL_GRP      -- 업무첨부파일
             , B.APRV_STATS    -- 결재상태(QS031)
             , B.APRV_CLS_NO   -- 키변수처리
             , B.APRV_ATFL_GRP -- 결재첨부파일
             , B.SITE_APRV_TP  -- 결재유형(QS039)
          FROM ( SELECT T1.SIT_CD
                      , T1.ACCD_SEQ
                      , T1.ATFL_GRP
                      , T1.APRV_NO
                   FROM TQHA_IDAC T1
                  WHERE T1.SIT_CD       = p_SIT_CD
                    AND T1.ACCD_SEQ     = p_ACCD_SEQ
               ) A
             , TQHA_APRV B
         WHERE A.SIT_CD     = B.SIT_CD (+)
           AND A.APRV_NO    = B.APRV_NO (+)
           AND A.SIT_CD     = p_SIT_CD
           AND A.ACCD_SEQ   = p_ACCD_SEQ
        ;

/*
    ----------------------------------------------------------------------------------------------------
    --  안전관리 : 보건순회점검일지 결재문서 조회
    ELSIF p_SITE_APRV_TP = '11' THEN

        OPEN RTN_CURSOR FOR
        SELECT A.SIT_CD       -- 현장코드 
            , A.ODAY_WRT_DT   -- 작성일자
            , A.APRV_NO       -- 결재번호
            , B.APRV_STATS    -- 결재상태(QS031)
            , B.APRV_CLS_NO   -- 키변수처리
            , B.APRV_ATFL_GRP -- 결재첨부파일
            , B.SITE_APRV_TP  -- 결재유형(QS039)
            , A.ATFL_GRP      -- 보건순회점검일지 첨부파일
        FROM TQSA_ODAYHEALT_LOG A
            , TQHA_APRV B
        WHERE A.SIT_CD      = B.SIT_CD (+)
          AND A.APRV_NO     = B.APRV_NO (+)
          AND A.SIT_CD      = p_SIT_CD
          AND A.ODAY_WRT_DT = p_ODAY_WRT_DT
        ;
*/

/*        
    ----------------------------------------------------------------------------------------------------
    --  월간실적 : 월별실적보고(현장) 조회
    ELSIF p_SITE_APRV_TP = '12' THEN

        OPEN RTN_CURSOR FOR
        SELECT A.SIT_CD       -- 현장코드
             , A.RLV_YM        -- 해당년월
             , A.ATFL_GRP      -- 업무첨부파일
             , A.APRV_NO       -- 결재번호
             , B.APRV_STATS    -- 결재상태(QS031)
             , B.APRV_CLS_NO   -- 키변수처리
             , B.APRV_ATFL_GRP -- 결재첨부파일
             , B.SITE_APRV_TP  -- 결재유형(QS039)
          FROM TQSA_MON_RSLT A
             , TQHA_APRV B
         WHERE A.SIT_CD     = B.SIT_CD (+)
           AND A.APRV_NO    = B.APRV_NO (+)
           AND A.SIT_CD     = p_SIT_CD
           AND A.RLV_YM     = p_RLV_YM
        ;

*/
    ----------------------------------------------------------------------------------------------------
    --  안전보건목표계획 결재문서 조회
    ELSIF p_SITE_APRV_TP = '13' THEN

        OPEN RTN_CURSOR FOR
        SELECT A.SIT_CD        -- 현장코드
             , A.TRG_YY        -- 목표년도
             , A.TRG_DGR       -- 목표차수
             , A.APRV_NO       -- 결재번호
             , B.APRV_STATS    -- 결재상태(QS031)
             , B.APRV_CLS_NO   -- 키변수처리
             , B.APRV_ATFL_GRP -- 결재첨부파일
             , B.SITE_APRV_TP  -- 결재유형(QS039)
          FROM TQHA_YYTRGPLNSEQ A
             , TQHA_APRV B
         WHERE A.SIT_CD   = B.SIT_CD (+)
           AND A.APRV_NO  = B.APRV_NO (+)
           AND A.SIT_CD   = p_SIT_CD
           AND A.TRG_YY   = p_TRG_YY
           AND A.TRG_DGR  = p_TRG_DGR
        ;

    ----------------------------------------------------------------------------------------------------
    --  안전보건실적 결재문서 조회
    ELSIF p_SITE_APRV_TP = '14' THEN 

        OPEN RTN_CURSOR FOR
        SELECT A.SIT_CD        -- 현장코드
             , A.TRG_YY        -- 목표년도
             , A.TRG_DGR       -- 목표차수
             , A.ARSLT_DGR     -- 실적차수
             , A.APRV_NO       -- 결재번호
             , B.APRV_STATS    -- 결재상태(QS031)
             , B.APRV_CLS_NO   -- 키변수처리
             , B.APRV_ATFL_GRP -- 결재첨부파일
             , B.SITE_APRV_TP  -- 결재유형(QS039)
          FROM TQHA_YYTRGARSLTSEQ A
             , TQHA_APRV B
         WHERE A.SIT_CD     = B.SIT_CD (+)
           AND A.APRV_NO    = B.APRV_NO (+)
           AND A.SIT_CD     = p_SIT_CD
           AND A.TRG_YY     = p_TRG_YY
           AND A.TRG_DGR    = p_TRG_DGR
           AND A.ARSLT_DGR  = p_ARSLT_DGR
        ;

    ----------------------------------------------------------------------------------------------------
    --  본사점검(환경) 결재문서 조회
    ELSIF p_SITE_APRV_TP = '15' THEN

        OPEN RTN_CURSOR FOR
        SELECT A.SIT_CD        -- 현장코드
             , A.CHK_DIV       -- 점검구분
             , A.CHK_DGR        -- 점검일
             , A.CHK_DT        -- 점검일
             , A.APRV_NO1   AS APRV_NO       -- 결재번호
             , B.APRV_STATS    -- 결재상태(QS031)
             , B.APRV_CLS_NO   -- 키변수처리
             , B.APRV_ATFL_GRP -- 결재첨부파일
             , B.SITE_APRV_TP  -- 결재유형(QS039)
          FROM TQHA_HOCHKRPT A
             , TQHA_APRV B
         WHERE A.SIT_CD   = B.SIT_CD (+)
           AND A.APRV_NO1 = B.APRV_NO (+)
           AND A.SIT_CD   = p_SIT_CD
           AND A.CHK_DIV  = p_CHK_DIV
           AND A.CHK_DGR   = p_CHK_DGR
        ;

    ----------------------------------------------------------------------------------------------------
    --  조치결과 결재문서 조회
    ELSIF p_SITE_APRV_TP = '16' THEN

        OPEN RTN_CURSOR FOR
        SELECT A.SIT_CD        -- 현장코드
             , A.CHK_DIV       -- 점검구분
             , A.CHK_DGR        -- 점검일
             , A.CHK_DT        -- 점검일
             , A.APRV_NO2   AS APRV_NO       -- 결재번호
             , B.APRV_STATS    -- 결재상태(QS031)
             , B.APRV_CLS_NO   -- 키변수처리
             , B.APRV_ATFL_GRP -- 결재첨부파일
             , B.SITE_APRV_TP  -- 결재유형(QS039)
             , A.ATFL_GRP  AS AREC_ATFL_GRP  -- 업무첨부파일
          FROM TQHA_HOCHKRPT A
             , TQHA_APRV B
         WHERE A.SIT_CD   = B.SIT_CD (+)
           AND A.APRV_NO2 = B.APRV_NO (+)
           AND A.SIT_CD   = p_SIT_CD
           AND A.CHK_DIV  = p_CHK_DIV
           AND A.CHK_DGR  = p_CHK_DGR
        ;

    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN 
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);
END ;
/

-- PQHA_APROV_LINE_Q (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_APROV_LINE_Q" (
    p_WRK_TP                VARCHAR2 DEFAULT 'Q'        -- FLAG( Q: SELECT )
,   p_SIT_CD                VARCHAR2                    -- 현장코드
,   p_SRCH_WRD              VARCHAR2                    -- 검색어
,   p_APRV_NO               VARCHAR2                    -- 결재번호
,   p_APRV_WRTR             VARCHAR2                    -- 결재상신자
,   p_APRVLINE_SEQ          VARCHAR2                    -- 결재선순번
,   RTN_CURSOR              OUT SYS_REFCURSOR
)
IS 
    /**************************************************************************************************************************
      Purpose : QSE > 안전관리 결재선 조회

      REVISIONS
      Ver      Date               Author                  Description 
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2025/02/25                                    최초생성

    **************************************************************************************************************************/

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR2(200);            -- ERROR Message
    USER_EXCEPTION EXCEPTION;

BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 수행전 Check Logic ]
    ---------------------------------------------------------------------------------------------------------------------------


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Logic 처리
    ---------------------------------------------------------------------------------------------------------------------------

    ----------------------------------------------------------------------------------------------------
    -- get_UsrInfoLineAprv 조회 
    IF p_WRK_TP = 'Q1' THEN
        OPEN RTN_CURSOR FOR
        SELECT EMPE_NO AS USR_ID
             , PNM AS USR_NM
             --, DTY_CD AS JB_CD
             --, DTY_NM AS JB_NM
             , JB_CD
             , NVL((SELECT CD_NM FROM TCOA_COMCODE WHERE COM_CD = T1.JB_CD AND HRNK_CD = 'QS077' AND USE_YN = '1'),'') AS JB_NM
             , CELPH    AS MP_NO
          FROM TQHA_SITENAM T1 
         WHERE SIT_CD   = p_SIT_CD
           AND (UPPER(T1.EMPE_NO) LIKE UPPER(p_SRCH_WRD) || '%' OR UPPER(T1.PNM) LIKE '%' || UPPER(p_SRCH_WRD) || '%')
           AND USE_YN = '1'
         ORDER 
            BY CO_DIV_CD, PNM, DTY_CD
        ;

    ----------------------------------------------------------------------------------------------------
    -- 결재선정보 조회
    ELSIF p_WRK_TP = 'Q2' THEN

        OPEN RTN_CURSOR FOR
        SELECT A.SIT_CD               -- 현장코드
             , A.APRV_NO               -- 결재번호
             , A.APRV_SO               -- 결재순서
             , A.APRV_PSN_ID AS USR_ID -- 결재자ID
             , B.PNM AS USR_NM
             , NVL((SELECT CD_NM FROM TCOA_COMCODE WHERE COM_CD = B.JB_CD AND HRNK_CD = 'QS077' AND USE_YN = '1'),'') AS JB_NM
             , A.APRV_STATS            -- 결재상태
             , A.APRV_OPIN             -- 결재의견
          FROM TQHA_APRV_LINE A
             , TQHA_SITENAM B
         WHERE A.APRV_PSN_ID    = B.EMPE_NO 
           AND A.SIT_CD         = B.SIT_CD 
           AND A.SIT_CD         = p_SIT_CD
           AND A.APRV_NO        = p_APRV_NO
        ;

    ----------------------------------------------------------------------------------------------------
    -- 개인결재선 selectBox 조회
    ELSIF p_WRK_TP = 'Q3' THEN

        OPEN RTN_CURSOR FOR
        SELECT APRVLINE_SEQ -- 결재선순번
             , APRVLINE_NM  -- 결재선명
          FROM TQHA_APRVLINE
         WHERE SIT_CD       = p_SIT_CD
           AND APRV_WRTR    = p_APRV_WRTR
         ORDER BY APRVLINE_SEQ
        ;

    ----------------------------------------------------------------------------------------------------
    -- 개인결재선 상세 조회
    ELSIF p_WRK_TP = 'Q4' THEN

        OPEN RTN_CURSOR FOR
        SELECT A.SIT_CD               -- 현장코드
             , A.APRV_SO               -- 결재선순번
             , A.APRV_PSN_ID AS USR_ID -- 결재자ID
             , B.PNM AS USR_NM
             , NVL((SELECT CD_NM FROM TCOA_COMCODE WHERE COM_CD = B.JB_CD AND HRNK_CD = 'QS077' AND USE_YN = '1'),'') AS JB_NM
          FROM TQHA_APRVLINE_DTL A
             , TQHA_SITENAM B
         WHERE A.APRV_PSN_ID    = B.EMPE_NO 
           AND A.SIT_CD         = B.SIT_CD
           AND A.SIT_CD         = p_SIT_CD
           AND A.APRV_WRTR      = p_APRV_WRTR
           AND A.APRVLINE_SEQ   = p_APRVLINE_SEQ
        ;

    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN 
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);
END ;
/

-- PQHA_APROV_PAGE_NM_Q (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_APROV_PAGE_NM_Q" (
    p_WRK_TP                VARCHAR2 DEFAULT 'Q'        -- FLAG( Q: SELECT )
,   p_SITE_APRV_TP          VARCHAR2                    -- 결재유형
,   RTN_CURSOR              OUT SYS_REFCURSOR
)
IS 
    /**************************************************************************************************************************
      Purpose : QSE > 안전관리 결재 페이지 조회

      REVISIONS
      Ver      Date               Author                  Description 
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2025/02/25                                    최초생성

    **************************************************************************************************************************/

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR2(200);            -- ERROR Message
    USER_EXCEPTION EXCEPTION;

BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 수행전 Check Logic ]
    ---------------------------------------------------------------------------------------------------------------------------


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Logic 처리
    ---------------------------------------------------------------------------------------------------------------------------

    OPEN RTN_CURSOR FOR
    SELECT MAX(CHRC_VAL_1)  AS RTN_PAGE_NM       -- 화면명
      FROM TCOA_COMCODE
     WHERE HRNK_CD  = 'QS039'
       AND COM_CD   = p_SITE_APRV_TP
    ;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
