-- PQHA_APROV_STATS_Q (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_APROV_STATS_Q" (
    p_WRK_TP                VARCHAR2 DEFAULT 'Q'        -- FLAG( Q: SELECT )
,   p_SIT_CD                VARCHAR2                    -- 현장코드
,   p_APRV_NO               VARCHAR2                    -- 결재번호
,   RTN_CURSOR              OUT SYS_REFCURSOR
)
IS 
    /**************************************************************************************************************************
      Purpose : QSE > 안전관리 결재 상태 조회

      REVISIONS
      Ver      Date               Author                  Description 
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2025/02/25                                    최초생성

    **************************************************************************************************************************/

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR2(200);            -- ERROR Message
    USER_EXCEPTION EXCEPTION;

BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 수행전 Check Logic ]
    ---------------------------------------------------------------------------------------------------------------------------


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Logic 처리
    ---------------------------------------------------------------------------------------------------------------------------

    ----------------------------------------------------------------------------------------------------
    -- 결재상태 조회 
    IF p_WRK_TP = 'Q1' THEN
        OPEN RTN_CURSOR FOR
        SELECT B.APRV_STATS         -- 결재상태(QS031)
             , B.APRV_CLS_NO        -- 키변수처리
             , B.APRV_ATFL_GRP      -- 결재첨부파일
             , B.SITE_APRV_TP       -- 결재유형(QS039)
             , '▶ 결재상태 : ' || NVL(( SELECT CD_NM FROM TCOA_COMCODE WHERE HRNK_CD = 'QS031' AND COM_CD = B.APRV_STATS ), '-') AS APRV_STATS_NM -- 결재상태명
             , B.APRV_NO
          FROM TQHA_APRV B
         WHERE B.SIT_CD     = p_SIT_CD
           AND B.APRV_NO    = p_APRV_NO
        ;

    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN 
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);
END ;
/

-- PQHA_APRVLINE_DTL_S (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_APRVLINE_DTL_S" 
                            (p_WRK_TP  VARCHAR2 :='U'                                     -- UPDATE FLAG( I: ISNERT, U:UPDATE, D:DELTE)
                            ,p_WRK_ID  VARCHAR2                                           -- 사용자 ID 
                            ,p_WRK_IP  VARCHAR2                                           -- 사용자 IP 
                            ,p_SIT_CD TQHA_APRVLINE_DTL.SIT_CD%TYPE                     -- 현장코드
                            ,p_APRV_WRTR TQHA_APRVLINE_DTL.APRV_WRTR%TYPE                 -- 결재상신자
                            ,p_APRVLINE_SEQ TQHA_APRVLINE_DTL.APRVLINE_SEQ%TYPE           -- 결재선순번
                            ,p_APRV_SO TQHA_APRVLINE_DTL.APRV_SO%TYPE                     -- 결재순서
                            ,p_APRV_PSN_ID TQHA_APRVLINE_DTL.APRV_PSN_ID%TYPE)            -- 결재자ID
IS 
    /**************************************************************************************************************************
      Purpose : 결재선 결재정보

      REVISIONS
      Ver      Date               Author                  Description 
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2022/01/25 15:12:31                         최초생성

    **************************************************************************************************************************/


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR2(200);            -- ERROR Message 
    USER_EXCEPTION EXCEPTION;

   	v_APRV_SO TQHA_APRVLINE_DTL.APRV_SO%TYPE;

	v_APRV_WRTR  VARCHAR2(100);

BEGIN

	v_APRV_WRTR := p_WRK_ID;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 필수입력 필드  Check  ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_SIT_CD IS NULL)  THEN
        ERR_MSG := '현장코드는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_APRV_WRTR IS NULL)  THEN
        ERR_MSG := '결재상신자는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_APRVLINE_SEQ IS NULL)  THEN
        ERR_MSG := '결재선순번는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_APRV_SO IS NULL AND p_WRK_TP <> 'I')  THEN
        ERR_MSG := '결재순서는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Process 선행조건 Check ]
    ---------------------------------------------------------------------------------------------------------------------------



    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Business Process ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_WRK_TP ='D') THEN
        DELETE 
          FROM TQHA_APRVLINE_DTL
         WHERE SIT_CD = p_SIT_CD         --현장코드
           AND APRV_WRTR = v_APRV_WRTR       --결재상신자
           AND APRVLINE_SEQ = p_APRVLINE_SEQ    --결재선순번
           AND APRV_SO = p_APRV_SO;        --결재순서

        v_APRV_SO := p_APRV_SO;

    ELSIF (p_WRK_TP ='U') THEN
        UPDATE TQHA_APRVLINE_DTL
           SET APRV_PSN_ID          = p_APRV_PSN_ID             --결재자ID
              ,UPD_ID               = p_WRK_ID                  --수정ID 
              ,UPD_DTM              = SYSDATE()                 --수정일시
              ,UPD_IP               = p_WRK_IP                  --수정IP
         WHERE SIT_CD = p_SIT_CD         --현장코드
           AND APRV_WRTR = v_APRV_WRTR       --결재상신자
           AND APRVLINE_SEQ = p_APRVLINE_SEQ    --결재선순번
           AND APRV_SO = p_APRV_SO;        --결재순서

        v_APRV_SO := p_APRV_SO;

    ELSE 

        -- 신규 결재순번 채번
    	SELECT NVL(MAX(APRV_SO), 0)+1
    	  INTO v_APRV_SO
          FROM TQHA_APRVLINE_DTL
         WHERE SIT_CD = p_SIT_CD
           AND APRV_WRTR = v_APRV_WRTR
           AND APRVLINE_SEQ = p_APRVLINE_SEQ;

        INSERT INTO TQHA_APRVLINE_DTL
                   ( SIT_CD                 --현장코드
                    ,APRV_WRTR               --결재상신자
                    ,APRVLINE_SEQ            --결재선순번
                    ,APRV_SO                 --결재순서
                    ,APRV_PSN_ID             --결재자ID
                    ,IPT_ID                  --입력ID
                    ,IPT_DTM                 --입력일시
                    ,IPT_IP                  --입력IP
                    ,UPD_ID                  --수정ID
                    ,UPD_DTM                 --수정일시
                    ,UPD_IP)                 --수정IP
             VALUES (p_SIT_CD               --현장코드
                    ,v_APRV_WRTR             --결재상신자
                    ,p_APRVLINE_SEQ          --결재선순번
                    ,v_APRV_SO               --결재순서
                    ,p_APRV_PSN_ID           --결재자ID
                    ,p_WRK_ID                --입력ID 
                    ,SYSDATE()               --입력일시
                    ,p_WRK_IP                --입력IP
                    ,p_WRK_ID                --수정ID
                    ,SYSDATE()               --수정일시
                    ,p_WRK_IP);              --수정IP
    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 5. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN 
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);
END ;
/

-- PQHA_APRVLINE_S (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_APRVLINE_S" 
                            (p_WRK_TP  VARCHAR2 :='U'                                     -- UPDATE FLAG( I: ISNERT, U:UPDATE, D:DELTE)
                            ,p_WRK_ID  VARCHAR2                                           -- 사용자 ID 
                            ,p_WRK_IP  VARCHAR2                                           -- 사용자 IP 
                            ,p_SIT_CD TQHA_APRVLINE.SIT_CD%TYPE                         -- 현장코드
                            ,p_APRV_WRTR TQHA_APRVLINE.APRV_WRTR%TYPE                     -- 결재상신자
                            ,p_APRVLINE_SEQ TQHA_APRVLINE.APRVLINE_SEQ%TYPE               -- 결재선순번
                            ,p_APRVLINE_NM TQHA_APRVLINE.APRVLINE_NM%TYPE                 -- 결재선명칭
                            ,p_RTN_APRVLINE_SEQ OUT VARCHAR2)                             -- 리턴변수(결재선순번)
                            
IS 
    /**************************************************************************************************************************
      Purpose : 결재선 관리

      REVISIONS
      Ver      Date               Author                  Description 
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2022/01/25 15:10:29                         최초생성

    **************************************************************************************************************************/


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR2(200);            -- ERROR Message
    USER_EXCEPTION EXCEPTION;

	v_APRVLINE_SEQ TQHA_APRVLINE.APRVLINE_SEQ%TYPE;
	
	v_APRV_WRTR  VARCHAR2(100);

BEGIN

	v_APRV_WRTR := p_WRK_ID;
	
    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 필수입력 필드  Check  ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_SIT_CD IS NULL)  THEN
        ERR_MSG := '현장코드는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_APRV_WRTR IS NULL)  THEN
        ERR_MSG := '결재상신자는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_APRVLINE_SEQ IS NULL AND p_WRK_TP <> 'I')  THEN
        ERR_MSG := '결재선순번는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Process 선행조건 Check ]
    ---------------------------------------------------------------------------------------------------------------------------



    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Business Process ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_WRK_TP ='D') THEN
    	DELETE 
          FROM TQHA_APRVLINE_DTL
         WHERE SIT_CD = p_SIT_CD         --현장코드
           AND APRV_WRTR = v_APRV_WRTR       --결재상신자
           AND APRVLINE_SEQ = p_APRVLINE_SEQ;    --결재선순번

        DELETE 
          FROM TQHA_APRVLINE
         WHERE SIT_CD = p_SIT_CD         --현장코드
           AND APRV_WRTR = v_APRV_WRTR       --결재상신자
           AND APRVLINE_SEQ = p_APRVLINE_SEQ;   --결재선순번

        v_APRVLINE_SEQ := p_APRVLINE_SEQ;

    ELSIF (p_WRK_TP ='U') THEN
        UPDATE TQHA_APRVLINE
           SET APRVLINE_NM          = p_APRVLINE_NM             --결재선명칭
              ,UPD_ID               = p_WRK_ID                  --수정ID 
              ,UPD_DTM              = SYSDATE()                 --수정일시
              ,UPD_IP               = p_WRK_IP                  --수정IP
         WHERE SIT_CD = p_SIT_CD         --현장코드
           AND APRV_WRTR = v_APRV_WRTR       --결재상신자
           AND APRVLINE_SEQ = p_APRVLINE_SEQ;   --결재선순번

        v_APRVLINE_SEQ := p_APRVLINE_SEQ;

    ELSE 

    	-- 신규 결재선순번 채번
    	SELECT NVL(MAX(APRVLINE_SEQ), 0)+1
    	  INTO v_APRVLINE_SEQ
          FROM TQHA_APRVLINE
         WHERE SIT_CD = p_SIT_CD
           AND APRV_WRTR = v_APRV_WRTR;

        INSERT INTO TQHA_APRVLINE
                   ( SIT_CD                 --현장코드
                    ,APRV_WRTR               --결재상신자
                    ,APRVLINE_SEQ            --결재선순번
                    ,APRVLINE_NM             --결재선명칭
                    ,IPT_ID                  --입력ID
                    ,IPT_DTM                 --입력일시
                    ,IPT_IP                  --입력IP
                    ,UPD_ID                  --수정ID
                    ,UPD_DTM                 --수정일시
                    ,UPD_IP)                 --수정IP
             VALUES (p_SIT_CD               --현장코드
                    ,v_APRV_WRTR             --결재상신자
                    ,v_APRVLINE_SEQ          --결재선순번
                    ,p_APRVLINE_NM           --결재선명칭
                    ,p_WRK_ID                --입력ID 
                    ,SYSDATE()               --입력일시
                    ,p_WRK_IP                --입력IP
                    ,p_WRK_ID                --수정ID
                    ,SYSDATE()               --수정일시
                    ,p_WRK_IP);              --수정IP
    END IF;

   	p_RTN_APRVLINE_SEQ := v_APRVLINE_SEQ;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 5. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN 
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);
END ;
/

