             VALUES (p_SIT_CD               --현장코드
                    ,v_APRV_NO               --결재번호
                    ,'4'                     --결재상태(QS031)    ??
                    ,p_WRK_ID                --결재상신ID
                    ,SYSDATE());             --결재상신일시

        p_APRV_NO := v_APRV_NO;
    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 5. Exception 처리 ]
