END ;
/

-- PQHA_APRV_B1 (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_APRV_B1" -- 현장결재 버튼 처리 SP 
                            (p_WRK_TP  VARCHAR2 :='S'                                     -- UPDATE FLAG( I: ISNERT, U:UPDATE, D:DELTE, S : 승인처리)
                            ,p_WRK_ID  VARCHAR2                                           -- 사용자 ID 
                            ,p_WRK_IP  VARCHAR2                                           -- 사용자 IP 
                            ,p_SIT_CD TQHA_APRV.SIT_CD%TYPE                               -- 현장코드
                            ,p_APRV_NO TQHA_APRV.APRV_NO%TYPE                             -- 결재번호
                            ,p_USR_ID  VARCHAR2                       					  -- 사번                             
                            ,p_RTN_VALUE  OUT VARCHAR2)                                   -- 리턴값 (결재상신/상신취소/결재승인/결재취소/결재반려/결재선)

IS 
    /**************************************************************************************************************************
      Purpose : 현장 결재 버튼 처리 SP 

      REVISIONS
      Ver      Date               Author                  Description 
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2021/1/28 12:48:42                         최초생성

    **************************************************************************************************************************/

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR2(200);            -- ERROR Message
    USER_EXCEPTION EXCEPTION;

    v_APRV_STATS       VARCHAR2(1);            -- 현재 결재상태 값
    v_APRV_SCHF_STATS  VARCHAR2(1);            -- 현재 결재선의 상신자 결재 상태 값   
    v_APRV_SCHF_NEXT   VARCHAR2(1);            -- 다음 결재 상태 값   

    v_APRV_LINE_STATS   VARCHAR2(1);           -- 현재 결재선의 상신자 결재 상태 값
    v_APRV_LINE_PRE    VARCHAR2(1);            -- 이전 결재자 상태 값
    v_APRV_LINE_NEXT   VARCHAR2(1);            -- 다음 결재 상태 값

    v_BTN_1         VARCHAR2(1)  := '0' ;   -- 결재상신 버튼
    v_BTN_2         VARCHAR2(1)  := '0' ;   -- 결재상신취소 버튼
    v_BTN_3         VARCHAR2(1)  := '0' ;   -- 결재승인 버튼
    v_BTN_4         VARCHAR2(1)  := '0' ;   -- 결재승인취소 버튼
    v_BTN_5         VARCHAR2(1)  := '0' ;   -- 결재반려 버튼
    v_BTN_6         VARCHAR2(1)  := '0' ;   -- 결재선 버튼

    v_APRV_SCHF     VARCHAR2(10);               -- 최조 결재 상신자 id 
    v_APRV_ID     VARCHAR2(10);                 -- 현재 결재대상자    

    v_ACCD_DT     VARCHAR2(8);               -- 이관된 데이타 결재 여부 체크 (사고일자)

    v_RTN_VALUE     VARCHAR2(10) ;              -- 리턴값 변수

BEGIN


	---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 필수입력 필드  Check  ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_SIT_CD IS NULL)  THEN
        ERR_MSG := '현장코드는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_APRV_NO IS NULL )  THEN
        ERR_MSG := '결재번호는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 필수입력 필드  Check  ]
    ---------------------------------------------------------------------------------------------------------------------------
 /* 
   --  산재 데이타 이관한거 메세지 표시(이관된 결재이므로 결재 양식을 볼수 없습니다)

       SELECT B.ACCD_DT 
         INTO v_ACCD_DT
         FROM TQHA_IDAC_APRV A, TQHA_IDAC B  
        WHERE A.SIT_CD = p_SIT_CD
          AND A.APRV_DIV = '1'
          AND A.APRV_NO = p_APRV_NO
          AND A.SIT_CD = B.SIT_CD 
          AND A.ACCD_SEQ = B.ACCD_SEQ ;

         -- 단위작업 코드 Validation
        IF v_ACCD_DT < '20220601' THEN
           ERR_MSG := '시스템 오픈 전 산재결재 가 완료되어 시스템에서 결재 조회가 불가합니다. ';
           RAISE USER_EXCEPTION;
        END IF;
   */
    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Process 선행조건 Check ]
    ---------------------------------------------------------------------------------------------------------------------------


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Business Process ]
    ---------------------------------------------------------------------------------------------------------------------------
	-- 결재 상태 체크
     SELECT NVL(APRV_STATS,0) 
       INTO v_APRV_STATS
       FROM TQHA_APRV
	  WHERE	SIT_CD	= p_SIT_CD                -- 변수 (현장코드)
        AND	APRV_NO  = p_APRV_NO ;              -- 변수 (결재번호)

    IF (v_APRV_STATS = '1') THEN         -- 결재 상신 전
        v_BTN_1 := '1';         -- 결재상신 버튼
        v_BTN_6 := '1';         -- 결재선 버튼

    ELSIF (v_APRV_STATS = '2') THEN         -- 결재 진행 중

        -- 최조 결재 상신자 찾기  v_APRV_SCHF
                SELECT   A.APRV_PSN_ID
                       , NVL(A.APRV_STATS,0) AS APRV_STATS
                       , NVL(A.APRV_STATS_NEXT,0) AS APRV_STATS_NEXT
                  INTO v_APRV_SCHF                             -- 결재 상신자 ID
                       , v_APRV_SCHF_STATS                      -- 결재 상신자 결재 값          
                       , v_APRV_SCHF_NEXT                      -- 다음 결재자 결재 값 
		         FROM (  -- 결재번호별 이전 결재자의 결재상태를 조회
				        SELECT    SIT_CD 
				                , APRV_NO
				                , APRV_SO
				                , APRV_PSN_ID
				                , NVL(APRV_STATS,0) AS APRV_STATS
				                , NVL(LEAD(APRV_STATS) OVER( ORDER BY SIT_CD, APRV_NO, APRV_SO),0) AS APRV_STATS_NEXT
				           FROM TQHA_APRV_LINE
						  WHERE	SIT_CD	 =  p_SIT_CD                    -- 변수 (현장코드)
				            AND	APRV_NO  =  p_APRV_NO                   -- 변수 (결재번호)
                        ) A
				  WHERE	A.SIT_CD  =  p_SIT_CD                 -- 변수 (현장코드)
		            AND	A.APRV_NO  =  p_APRV_NO                 -- 변수 (결재번호)
		            AND A.APRV_SO  =  1  	                    -- 결재 상신자 순번 1
                             ;  

        IF ( v_APRV_SCHF = p_USR_ID ) THEN   -- 최초 상신자 인경우
           -- 결재 완료한 경우 
           IF ( v_APRV_SCHF_STATS = '4' AND v_APRV_SCHF_NEXT = '0' )  THEN  -- 내가 결재를 완료하고 다음 결재자가 결재 안 한경우     
              v_BTN_2 := '1';                -- 결재상신취소 버튼

           END IF;

        ELSE                                  -- 결재 진행자

   -- 결재 내가 바로 결재해야 할 항목 조회(미결함)  - 테스트 후 삭제
       -- 결재라인 상태 조회        
            BEGIN
	            SELECT  APRV_PSN_ID                                      -- 결재자 id
	                  , NVL(APRV_STATS,0) AS APRV_STATS                  -- 결재상태
	                  , NVL(PRE_APRV_STATS,0)    AS PRE_APRV_STATS       -- 이전 결재자의 결재상태                                  
	                  , NVL(NEXT_APRV_STATS,0) AS NEXT_APRV_STATS        -- 다음 결재자의 결재상태   
	             INTO  v_APRV_ID                               -- 현재 결재대산자 ID
	                  , v_APRV_LINE_STATS                     -- 현재 결재상태          
	                  , v_APRV_LINE_PRE                       -- 이전 결재자 결재 값 
	                  , v_APRV_LINE_NEXT                      -- 다음 결재자 결재 값	                  
		         FROM (  -- 결재번호별 이전 결재자의 결재상태를 조회
		                 SELECT   SIT_CD
			                     , APRV_PSN_ID                                                                           -- 결재자 id
	                             , NVL(APRV_STATS,0)   AS APRV_STATS                                                      -- 결재상태
	                             , NVL(LAG(APRV_STATS) OVER (ORDER BY SIT_CD, APRV_NO , APRV_SO),0) AS PRE_APRV_STATS    -- 이전 결재자의 결재상태                                  
	                             , NVL(LEAD(APRV_STATS) OVER( ORDER BY SIT_CD, APRV_NO, APRV_SO),0) AS NEXT_APRV_STATS	  -- 다음 결재자의 결재상태                                                                 
	                       FROM TQHA_APRV_LINE
	                      WHERE SIT_CD =  p_SIT_CD                           -- 변수 (현장코드)
	                        AND APRV_NO =  p_APRV_NO                           -- 변수 (결재번호)
	                   ORDER BY SIT_CD, APRV_NO , APRV_SO 
	                   )
	            WHERE SIT_CD = p_SIT_CD                                      -- 변수 (현장코드) 
	              AND APRV_PSN_ID IN (p_USR_ID)                              -- 결재자                                  
                     ;
			EXCEPTION WHEN No_Data_Found THEN
				--Raise_Application_Error(-20009,'데이타가 없습니다. 확인하신 후 다시 작업하시기 바랍니다.');    --- 에러 안나고 진행 할수 있는 방안 ?
			      v_BTN_1 := '0';         -- 결재상신 버튼
		          v_BTN_2 := '0';         -- 결재상신취소 버튼          
		          v_BTN_3 := '0';         -- 결재승인 버튼
		          v_BTN_4 := '0';         -- 결재승인취소 버튼
		          v_BTN_5 := '0';         -- 결재반려 버튼                              
		          v_BTN_6 := '0';         -- 결재선 버튼
			END;

               -- 내가 결재를 안 하고 이전 결재자가 결재 완료 한 경우
	           IF ( v_APRV_LINE_STATS = '0' AND v_APRV_LINE_PRE = '4' )  THEN  
			        v_BTN_3 := '1';         -- 결재승인 버튼
                    v_BTN_5 := '1';         -- 결재반려 버튼			        

	           END IF;

	            -- 내가 결재를 하고 다음 결재자가 결재 한 경우
	           IF ( v_APRV_LINE_STATS = '4' AND v_APRV_LINE_NEXT = '0' )  THEN   
                    v_BTN_4 := '1';         -- 결재승인취소 버튼			        

	           END IF;
        END IF;   

    ELSIF (v_APRV_STATS = '3') THEN         -- 결재 반려
          v_BTN_1 := '1';         -- 결재상신 버튼
          v_BTN_6 := '1';         -- 결재선 버튼

    ELSIF (v_APRV_STATS = '4') THEN         -- 결재 완료
          v_BTN_1 := '0';         -- 결재상신 버튼
          v_BTN_2 := '0';         -- 결재상신취소 버튼          
          v_BTN_3 := '0';         -- 결재승인 버튼
          v_BTN_4 := '0';         -- 결재승인취소 버튼
          v_BTN_5 := '0';         -- 결재반려 버튼                              
          v_BTN_6 := '0';         -- 결재선 버튼

    END IF;

    v_RTN_VALUE := v_BTN_1 || v_BTN_2 || v_BTN_3 || v_BTN_4 || v_BTN_5 || v_BTN_6 ;
    p_RTN_VALUE := v_RTN_VALUE ;                 -- 리턴값
    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 5. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN 
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);
END PQHA_APRV_B1;
/

-- PQHA_APRV_CANCEL_S (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_APRV_CANCEL_S" 
                            (p_WRK_TP  VARCHAR2 :='U'                                     -- UPDATE FLAG( I: ISNERT, U:UPDATE, D:DELTE,  DA :삭제(전체)
                            ,p_WRK_ID  VARCHAR2                                           -- 사용자 ID 
                            ,p_WRK_IP  VARCHAR2                                           -- 사용자 IP 
                            ,p_SIT_CD  VARCHAR2
                            ,p_APRV_NO VARCHAR2
                            )
IS 
    /**************************************************************************************************************************
      Purpose : 결재라인 등록

      REVISIONS
      Ver      Date               Author                  Description 
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2022/01/20 14:24:15                         최초생성

    **************************************************************************************************************************/


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR2(200);            -- ERROR Message
    USER_EXCEPTION EXCEPTION;

    v_APRV_SO TQHA_APRV_LINE.APRV_SO%TYPE ;             -- 결재순서 변수 선언
    v_APRV_STATS  VARCHAR2(1) := '0';                   -- 결재진행 상태(1 작성중, 2 결재진행, 3 결재반려, 4 결재완료 )
BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 필수입력 필드  Check  ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_SIT_CD IS NULL)  THEN
        ERR_MSG := '현장코드는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_APRV_NO IS NULL)  THEN 
        ERR_MSG := '결재번호는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Process 선행조건 Check ]
    ---------------------------------------------------------------------------------------------------------------------------


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Business Process ]
    ---------------------------------------------------------------------------------------------------------------------------
   
    UPDATE TQHA_APRV_LINE
    SET APRV_STATS = '1'
    WHERE SIT_CD = p_SIT_CD
      AND APRV_NO = p_APRV_NO;
    
    UPDATE TQHA_APRV
    SET APRV_STATS = '1'
    WHERE SIT_CD = p_SIT_CD
      AND APRV_NO = p_APRV_NO;
    

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 5. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN 
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);
END ;
/

-- PQHA_APRV_CREATE (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_APRV_CREATE" -- 신규 결재문서 생성
                            (p_WRK_TP  VARCHAR2 :='U'                           -- UPDATE FLAG( I: ISNERT, U:UPDATE, D:DELTE)
                            ,p_WRK_ID  VARCHAR2                                 -- 사용자 ID 
                            ,p_WRK_IP  VARCHAR2                                 -- 사용자 IP 
                            ,p_SIT_CD TQHA_APRV.SIT_CD%TYPE                   -- 현장코드
                            ,p_APRV_TTL TQHA_APRV.APRV_TTL%TYPE                 -- 결재제목
                            ,p_APRV_CLS_NO TQHA_APRV.APRV_CLS_NO%TYPE           -- 키변수
                            ,p_SITE_APRV_TP TQHA_APRV.SITE_APRV_TP%TYPE         -- 결재유형
                            ,p_RTN_APRV_NO OUT VARCHAR2)                        -- 리턴변수(결재번호)
IS  
    /**************************************************************************************************************************
      Purpose : 결재라인 등록

      REVISIONS
      Ver      Date               Author                  Description 
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2022/01/24                                  최초생성

    **************************************************************************************************************************/
     ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR2(200);            -- ERROR Message
    USER_EXCEPTION EXCEPTION; 

   	v_APRV_NO TQHA_APRV.APRV_NO%TYPE; 

   	v_WRK_PARM  VARCHAR2(200);  
    v_KEY_PARM1 VARCHAR2(200);
    v_KEY_PARM2 VARCHAR2(200);
    v_KEY_PARM3 VARCHAR2(200);
    v_KEY_PARM4 VARCHAR2(200);
    v_KEY_PARM5 VARCHAR2(200);
    v_KEY_PARM6 VARCHAR2(200);

BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 필수입력 필드  Check  ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_SIT_CD IS NULL)  THEN
        ERR_MSG := '현장코드는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Process 선행조건 Check ]
    ---------------------------------------------------------------------------------------------------------------------------

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Business Process ]
    ---------------------------------------------------------------------------------------------------------------------------

    -- 신규 결재문서 생성(결재번호 리턴)
    --         작업상태, 사용자ID, 사용자IP, 현장코드, 결재번호, 결재제목, 결재상신자, 결재상신일시, 결재상태구분, 결재승인일시, 키변수처리, 결재유형, 리턴변수(결재번호) 
    PQHA_APRV_S('I', p_WRK_ID, p_WRK_IP, p_SIT_CD, '', p_APRV_TTL, '', '', '1', '', p_APRV_CLS_NO, p_SITE_APRV_TP, v_APRV_NO);

    -- 결재번호를 업무테이블에 업데이트시 필요한 키값
    v_WRK_PARM := SUBSTR(p_APRV_CLS_NO, 1, INSTR(p_APRV_CLS_NO, '§')-1);

    -- 위험성평가(최초/연간) 계획수립 결재번호 업데이트
    IF (p_SITE_APRV_TP ='01') THEN
    	v_KEY_PARM1 := SUBSTR(v_WRK_PARM, 1, INSTR(v_WRK_PARM, '^')-1);
    	v_KEY_PARM2 := SUBSTR(v_WRK_PARM, INSTR(v_WRK_PARM, '^')+1, INSTR(v_WRK_PARM, '^',1,2)-(INSTR(v_WRK_PARM, '^')+1));
        v_KEY_PARM3 := SUBSTR(v_WRK_PARM, INSTR(v_WRK_PARM, '^', 1, 2)+1);

        UPDATE TQHA_RISKPLAN
           SET APRV_NO = v_APRV_NO    
             , UPD_ID  = p_WRK_ID
             , UPD_DTM = SYSDATE
             , UPD_IP  = p_WRK_IP
         WHERE SIT_CD = v_KEY_PARM1
           AND FST_DIV = v_KEY_PARM2
           AND PLN_DGR = v_KEY_PARM3;

	-- 위험성평가 회의록 결재번호 업데이트
    ELSIF (p_SITE_APRV_TP ='02') THEN
    	v_KEY_PARM1 := SUBSTR(v_WRK_PARM, 1, INSTR(v_WRK_PARM, '^')-1);
    	v_KEY_PARM2 := SUBSTR(v_WRK_PARM, INSTR(v_WRK_PARM, '^')+1, INSTR(v_WRK_PARM, '^',1,2)-(INSTR(v_WRK_PARM, '^')+1));
        --v_KEY_PARM3 := SUBSTR(v_WRK_PARM, INSTR(v_WRK_PARM, '^', 1, 2)+1);
    	v_KEY_PARM3 := SUBSTR(v_WRK_PARM, INSTR(v_WRK_PARM, '^', 1, 2)+1, INSTR(v_WRK_PARM, '^',1,3)-(INSTR(v_WRK_PARM, '^',1,2)+1));
        v_KEY_PARM4 := SUBSTR(v_WRK_PARM, INSTR(v_WRK_PARM, '^', 1, 3)+1);

    	UPDATE TQHA_RISK_DGR
           SET APRV_NO = v_APRV_NO   
             , UPD_ID  = p_WRK_ID
             , UPD_DTM = SYSDATE
             , UPD_IP  = p_WRK_IP
         WHERE SIT_CD = v_KEY_PARM1
           AND PLN_YM = v_KEY_PARM2
           AND PLN_DGR = v_KEY_PARM3;
/*

    -- 일일안전일지 결재번호 업데이트
    ELSIF (p_SITE_APRV_TP ='05') THEN
         v_KEY_PARM1 := SUBSTR(v_WRK_PARM, 1, INSTR(v_WRK_PARM, '^')-1);
         v_KEY_PARM2 := SUBSTR(v_WRK_PARM, INSTR(v_WRK_PARM, '^')+1, LENGTH(v_WRK_PARM));

         UPDATE TQSA_ODAYSAFE_LOG
    	    SET APRV_NO = v_APRV_NO
    	      , UPD_ID  = p_WRK_ID
              , UPD_DTM = SYSDATE
              , UPD_IP  = p_WRK_IP
          WHERE SIT_CD = v_KEY_PARM1
            AND ODAY_WRT_DT = v_KEY_PARM2;
*/

    -- 교육일지 결재번호 업데이트
    ELSIF (p_SITE_APRV_TP ='06') THEN
    	 v_KEY_PARM1 := SUBSTR(v_WRK_PARM, 1, INSTR(v_WRK_PARM, '^')-1);
    	 v_KEY_PARM2 := SUBSTR(v_WRK_PARM, INSTR(v_WRK_PARM, '^')+1, LENGTH(v_WRK_PARM));

    	 UPDATE TQHA_EDU
            SET APRV_NO = v_APRV_NO
              , UPD_ID  = p_WRK_ID
              , UPD_DTM = SYSDATE
              , UPD_IP  = p_WRK_IP
          WHERE SIT_CD = v_KEY_PARM1
            AND EDU_SEQ = v_KEY_PARM2;
/*

    -- 노사합동점검 결재번호 업데이트
    ELSIF (p_SITE_APRV_TP ='07') THEN
         v_KEY_PARM1 := SUBSTR(v_WRK_PARM, 1, INSTR(v_WRK_PARM, '^')-1);
    	 v_KEY_PARM2 := SUBSTR(v_WRK_PARM, INSTR(v_WRK_PARM, '^')+1, LENGTH(v_WRK_PARM));

    	 UPDATE TQHA_LBR_CHK
            SET APRV_NO = v_APRV_NO
              , UPD_ID  = p_WRK_ID
              , UPD_DTM = SYSDATE
              , UPD_IP  = p_WRK_IP
          WHERE SIT_CD = v_KEY_PARM1
            AND CHK_SEQ = v_KEY_PARM2;
*/
/*

    -- 노사협의체회의 결재번호 업데이트
    ELSIF (p_SITE_APRV_TP ='08') THEN
   		 v_KEY_PARM1 := SUBSTR(v_WRK_PARM, 1, INSTR(v_WRK_PARM, '^')-1);
    	 v_KEY_PARM2 := SUBSTR(v_WRK_PARM, INSTR(v_WRK_PARM, '^')+1, LENGTH(v_WRK_PARM));

    	 UPDATE TQHA_LAB_AREC
            SET APRV_NO = v_APRV_NO
              , UPD_ID  = p_WRK_ID
              , UPD_DTM = SYSDATE
              , UPD_IP  = p_WRK_IP
          WHERE SIT_CD = v_KEY_PARM1
            AND CONF_SEQ = v_KEY_PARM2;
*/

    -- 안전관리비 월별실적 결재번호 업데이트
    ELSIF (p_SITE_APRV_TP ='09') THEN
         v_KEY_PARM1 := SUBSTR(v_WRK_PARM, 1, INSTR(v_WRK_PARM, '^')-1);
    	 v_KEY_PARM2 := SUBSTR(v_WRK_PARM, INSTR(v_WRK_PARM, '^')+1, LENGTH(v_WRK_PARM));

    	 UPDATE TQHA_SAFECOST_APRV
            SET APRV_NO = v_APRV_NO
              , UPD_ID  = p_WRK_ID
              , UPD_DTM = SYSDATE
              , UPD_IP  = p_WRK_IP
          WHERE SIT_CD = v_KEY_PARM1
            AND APRV_DIV = '2'
            AND APRV_YM = v_KEY_PARM2;


    -- 산재관리(현장) 결재번호 업데이트
    ELSIF (p_SITE_APRV_TP ='10') THEN
         v_KEY_PARM1 := SUBSTR(v_WRK_PARM, 1, INSTR(v_WRK_PARM, '^')-1);
    	 v_KEY_PARM2 := SUBSTR(v_WRK_PARM, INSTR(v_WRK_PARM, '^')+1, LENGTH(v_WRK_PARM));

         UPDATE TQHA_IDAC
            SET APRV_NO = v_APRV_NO
              , UPD_ID  = p_WRK_ID
              , UPD_DTM = SYSDATE
              , UPD_IP  = p_WRK_IP
          WHERE SIT_CD = v_KEY_PARM1
            AND ACCD_SEQ = v_KEY_PARM2;

/*
    -- 보건순회점검일지 결재번호 업데이트
    ELSIF (p_SITE_APRV_TP ='11') THEN
         v_KEY_PARM1 := SUBSTR(v_WRK_PARM, 1, INSTR(v_WRK_PARM, '^')-1);
    	 v_KEY_PARM2 := SUBSTR(v_WRK_PARM, INSTR(v_WRK_PARM, '^')+1, LENGTH(v_WRK_PARM));

         UPDATE TQSA_ODAYHEALT_LOG
            SET APRV_NO = v_APRV_NO
              , UPD_ID  = p_WRK_ID
              , UPD_DTM = SYSDATE
              , UPD_IP  = p_WRK_IP
          WHERE SIT_CD = v_KEY_PARM1
            AND ODAY_WRT_DT = v_KEY_PARM2;

    -- 월별실적보고(현장) 결재번호 업데이트
    ELSIF (p_SITE_APRV_TP ='12') THEN
         v_KEY_PARM1 := SUBSTR(v_WRK_PARM, 1, INSTR(v_WRK_PARM, '^')-1);
    	 v_KEY_PARM2 := SUBSTR(v_WRK_PARM, INSTR(v_WRK_PARM, '^')+1, LENGTH(v_WRK_PARM));

         UPDATE TQSA_MON_RSLT
            SET APRV_NO = v_APRV_NO
              , UPD_ID  = p_WRK_ID
              , UPD_DTM = SYSDATE
              , UPD_IP  = p_WRK_IP
          WHERE SIT_CD = v_KEY_PARM1
            AND RLV_YM  = v_KEY_PARM2;

*/

    -- 안전보건계획목표 계획수립 결재번호 업데이트
    ELSIF (p_SITE_APRV_TP ='13') THEN
        v_KEY_PARM1 := SUBSTR(v_WRK_PARM, 1, INSTR(v_WRK_PARM, '^')-1);
        v_KEY_PARM2 := SUBSTR(v_WRK_PARM, INSTR(v_WRK_PARM, '^')+1, INSTR(v_WRK_PARM, '^',1,2)-(INSTR(v_WRK_PARM, '^')+1));
        v_KEY_PARM3 := SUBSTR(v_WRK_PARM, INSTR(v_WRK_PARM, '^', 1, 2)+1);

         UPDATE TQHA_YYTRGPLNSEQ
            SET APRV_NO = v_APRV_NO
              , UPD_ID  = p_WRK_ID
              , UPD_DTM = SYSDATE
              , UPD_IP  = p_WRK_IP
          WHERE SIT_CD  = v_KEY_PARM1
            AND TRG_YY  = v_KEY_PARM2
            AND TRG_DGR = v_KEY_PARM3
        ;

    -- 안전보건실적 결재번호 업데이트
    ELSIF (p_SITE_APRV_TP ='14') THEN
        v_KEY_PARM1 := SUBSTR(v_WRK_PARM, 1, INSTR(v_WRK_PARM, '^')-1);
        v_KEY_PARM2 := SUBSTR(v_WRK_PARM, INSTR(v_WRK_PARM, '^')+1, INSTR(v_WRK_PARM, '^',1,2)-(INSTR(v_WRK_PARM, '^')+1));
        v_KEY_PARM3 := SUBSTR(v_WRK_PARM, INSTR(v_WRK_PARM, '^', 1, 2)+1, INSTR(v_WRK_PARM, '^',1,3)-(INSTR(v_WRK_PARM, '^',1,2)+1));
        v_KEY_PARM4 := SUBSTR(v_WRK_PARM, INSTR(v_WRK_PARM, '^', 1, 3)+1);

         UPDATE TQHA_YYTRGARSLTSEQ
            SET APRV_NO = v_APRV_NO
              , UPD_ID  = p_WRK_ID
              , UPD_DTM = SYSDATE
              , UPD_IP  = p_WRK_IP
          WHERE SIT_CD  = v_KEY_PARM1
            AND TRG_YY  = v_KEY_PARM2
            AND TRG_DGR = v_KEY_PARM3
            AND ARSLT_DGR = v_KEY_PARM4
        ;

    -- 본사점검(환경) 결재번호 업데이트
    ELSIF (p_SITE_APRV_TP ='15') THEN
        v_KEY_PARM1 := SUBSTR(v_WRK_PARM, 1, INSTR(v_WRK_PARM, '^')-1);
        v_KEY_PARM2 := SUBSTR(v_WRK_PARM, INSTR(v_WRK_PARM, '^')+1, INSTR(v_WRK_PARM, '^',1,2)-(INSTR(v_WRK_PARM, '^')+1));
        v_KEY_PARM3 := SUBSTR(v_WRK_PARM, INSTR(v_WRK_PARM, '^', 1, 2)+1);

         UPDATE TQHA_HOCHKRPT
            SET APRV_NO1 = v_APRV_NO
              , UPD_ID  = p_WRK_ID
              , UPD_DTM = SYSDATE
              , UPD_IP  = p_WRK_IP
          WHERE SIT_CD  = v_KEY_PARM1
            AND CHK_DIV = v_KEY_PARM2
            AND CHK_DGR  = v_KEY_PARM3
        ;

    -- 조치결과 결재번호 업데이트
    ELSIF (p_SITE_APRV_TP ='16') THEN
        v_KEY_PARM1 := SUBSTR(v_WRK_PARM, 1, INSTR(v_WRK_PARM, '^')-1);
        v_KEY_PARM2 := SUBSTR(v_WRK_PARM, INSTR(v_WRK_PARM, '^')+1, INSTR(v_WRK_PARM, '^',1,2)-(INSTR(v_WRK_PARM, '^')+1));
        v_KEY_PARM3 := SUBSTR(v_WRK_PARM,INSTR(v_WRK_PARM, '^', 1, 2) + 1, INSTR(v_WRK_PARM, '^', 1, 3) - INSTR(v_WRK_PARM, '^', 1, 2) - 1);

         UPDATE TQHA_HOCHKRPT
            SET APRV_NO2 = v_APRV_NO
              , UPD_ID  = p_WRK_ID
              , UPD_DTM = SYSDATE
              , UPD_IP  = p_WRK_IP
          WHERE SIT_CD  = v_KEY_PARM1
            AND CHK_DIV = v_KEY_PARM2
            AND CHK_DGR  = v_KEY_PARM3
        ;

    -- 주간업무보고현장 결재번호 업데이트
    ELSIF (p_SITE_APRV_TP ='20') THEN
        v_KEY_PARM1 := SUBSTR(v_WRK_PARM, 1, INSTR(v_WRK_PARM, '^')-1);
        v_KEY_PARM2 := SUBSTR(v_WRK_PARM, INSTR(v_WRK_PARM, '^') + 1);

         UPDATE TQHA_WEEK_WORK_LOG
           SET APRV_NO              = v_APRV_NO              --주간시작일자
              ,UPD_ID               = p_WRK_ID                  --수정ID 
              ,UPD_DTM              = SYSDATE()                 --수정일시
              ,UPD_IP               = p_WRK_IP                  --수정IP
         WHERE SIT_CD = v_KEY_PARM1          --현장코드
           AND RPTING_DT = v_KEY_PARM2;      --보고일자

    END IF;

   	p_RTN_APRV_NO := v_APRV_NO;


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 5. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN 
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);
END PQHA_APRV_CREATE;
/

-- PQHA_APRV_LINE_S (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_APRV_LINE_S" 
                            (p_WRK_TP  VARCHAR2 :='U'                                     -- UPDATE FLAG( I: ISNERT, U:UPDATE, D:DELTE,  DA :삭제(전체)
                            ,p_WRK_ID  VARCHAR2                                           -- 사용자 ID 
                            ,p_WRK_IP  VARCHAR2                                           -- 사용자 IP 
                            ,p_SIT_CD TQHA_APRV_LINE.SIT_CD%TYPE                         -- 현장코드
                            ,p_APRV_NO TQHA_APRV_LINE.APRV_NO%TYPE                        -- 결재번호
                            ,p_APRV_SO TQHA_APRV_LINE.APRV_SO%TYPE                        -- 결재순서
                            ,p_APRV_PSN_ID TQHA_APRV_LINE.APRV_PSN_ID%TYPE                -- 결재자ID
                            ,p_APRV_STATS TQHA_APRV_LINE.APRV_STATS%TYPE                  -- 결재상태구분(QS031) 
                            ,p_APRV_APRV_DTM TQHA_APRV_LINE.APRV_APRV_DTM%TYPE            -- 결재승인일시
                            ,p_APRV_OPIN TQHA_APRV_LINE.APRV_OPIN%TYPE                    -- 결재의견
                            ,p_RMKS TQHA_APRV_LINE.RMKS%TYPE)                             -- 비고
IS 
    /**************************************************************************************************************************
      Purpose : 결재라인 등록

      REVISIONS
      Ver      Date               Author                  Description 
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2022/01/20 14:24:15                         최초생성

    **************************************************************************************************************************/


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR2(200);            -- ERROR Message
    USER_EXCEPTION EXCEPTION;

    v_APRV_SO TQHA_APRV_LINE.APRV_SO%TYPE ;             -- 결재순서 변수 선언
    v_APRV_STATS  VARCHAR2(1) := '0';                   -- 결재진행 상태(1 작성중, 2 결재진행, 3 결재반려, 4 결재완료 )
BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 필수입력 필드  Check  ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_SIT_CD IS NULL)  THEN
        ERR_MSG := '현장코드는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_APRV_NO IS NULL)  THEN 
        ERR_MSG := '결재번호는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_APRV_SO IS NULL AND p_WRK_TP <> 'I')  THEN
        ERR_MSG := '결재순서는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Process 선행조건 Check ]
    ---------------------------------------------------------------------------------------------------------------------------


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Business Process ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_WRK_TP ='D') THEN
        DELETE 
          FROM TQHA_APRV_LINE
         WHERE SIT_CD = p_SIT_CD         --현장코드
           AND APRV_NO = p_APRV_NO         --결재번호
           AND APRV_SO = p_APRV_SO;        --결재순서

    ELSIF (p_WRK_TP ='U') THEN
        UPDATE TQHA_APRV_LINE
           SET APRV_PSN_ID          = p_APRV_PSN_ID             --결재자ID
              ,APRV_STATS           = p_APRV_STATS              --결재상태구분(QS031) 
              ,APRV_APRV_DTM        = p_APRV_APRV_DTM           --결재승인일시
              ,APRV_OPIN            = p_APRV_OPIN               --결재의견
              ,RMKS                 = p_RMKS                    --비고
              ,UPD_ID               = p_WRK_ID                  --수정ID 
              ,UPD_DTM              = SYSDATE()                 --수정일시
              ,UPD_IP               = p_WRK_IP                  --수정IP
         WHERE SIT_CD = p_SIT_CD         --현장코드
           AND APRV_NO = p_APRV_NO         --결재번호
           AND APRV_SO = p_APRV_SO;        --결재순서
    ELSIF (p_WRK_TP ='I') THEN
         -- 결재순서 생성
        SELECT NVL((MAX(APRV_SO)+1),1) 
          INTO v_APRV_SO
          FROM TQHA_APRV_LINE
         WHERE SIT_CD = p_SIT_CD          --현장코드
           AND APRV_NO = p_APRV_NO ;        --결재번호 
         --

        INSERT INTO TQHA_APRV_LINE
                   ( SIT_CD                 --현장코드
                    ,APRV_NO                 --결재번호
                    ,APRV_SO                 --결재순서
                    ,APRV_PSN_ID             --결재자ID
                    ,APRV_STATS              --결재상태구분(QS031) 
                    ,APRV_APRV_DTM           --결재승인일시
                    ,APRV_OPIN               --결재의견
                    ,RMKS                    --비고
                    ,IPT_ID                  --입력ID
                    ,IPT_DTM                 --입력일시
                    ,IPT_IP                  --입력IP
                    ,UPD_ID                  --수정ID
                    ,UPD_DTM                 --수정일시
                    ,UPD_IP)                 --수정IP
             VALUES (p_SIT_CD               --현장코드
                    ,p_APRV_NO               --결재번호
                    ,v_APRV_SO               --결재순서
                    ,p_APRV_PSN_ID           --결재자ID
                    ,p_APRV_STATS            --결재상태구분(QS031) 
                    ,p_APRV_APRV_DTM         --결재승인일시
                    ,p_APRV_OPIN             --결재의견
                    ,p_RMKS                  --비고
                    ,p_WRK_ID                --입력ID 
                    ,SYSDATE()               --입력일시
                    ,p_WRK_IP                --입력IP
                    ,p_WRK_ID                --수정ID
                    ,SYSDATE()               --수정일시
                    ,p_WRK_IP);              --수정IP
    ELSIF (p_WRK_TP ='DA') THEN

    	  -- 결재 상태가 1(작성중)이 아닌경우는 결재선 추가 불가
		  SELECT NVL(APRV_STATS,0)              -- 결재진행상태  1 작성중
		    INTO v_APRV_STATS                   -- 결재 상태가 1이 아닌경우는 결재선 추가 불가
		    FROM TQHA_APRV
		   WHERE SIT_CD = p_SIT_CD     -- 변수 (현장코드)
		     AND APRV_NO = p_APRV_NO ;    -- 변수 (결재번호)

		  IF ( v_APRV_STATS = '0' OR v_APRV_STATS = '1') THEN   -- 결재 작성중 경우  

		      -- 결재선 삭제
			      DELETE 
			        FROM TQHA_APRV_LINE
			       WHERE SIT_CD = p_SIT_CD       -- 변수 (현장코드)
			         AND APRV_NO = p_APRV_NO;         -- 변수 (결재번호)

		  ELSE       

		    ERR_MSG := '결재 진행(완료) 중으로 결재선 수정을 할 수 없습니다.';
		    RAISE USER_EXCEPTION;

          END IF ; 

    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 5. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN 
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);
END ;
/

-- PQHA_APRV_Q (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_APRV_Q" (
    p_WRK_TP            IN VARCHAR2 DEFAULT 'Q'         -- FLAG
,   p_USR_ID            IN VARCHAR2                     -- 사용자ID
,   p_SIT_CD            IN VARCHAR2                     -- 현장코드
,   p_SEARCH_STR_YM     IN VARCHAR2                     -- 결재년월
,   p_SITE_APRV_TP      IN VARCHAR2                     -- 결재유형
,   p_APRV_STATS        IN VARCHAR2                     -- 결재상태
,   p_APRV_NO           IN VARCHAR2                     -- 결재번호
,   RTN_CURSOR          OUT SYS_REFCURSOR
)
IS
    /**************************************************************************************************************************
      Purpose : [안전 결재관리] PROCEDRE 

      REVISIONS
      Ver      Date               Author                  Description
      -------  -----------------  ----------------------  ---------------------------------------------------------------------
      1.0      2026/02/05                                 최초생성

    **************************************************************************************************************************/

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE  NUMBER :=-20009; -- ERROR 코드
    ERR_MSG   VARCHAR(200);    -- ERROR Message
    USER_EXCEPTION EXCEPTION;

BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 수행전 Check Logic ]
    ---------------------------------------------------------------------------------------------------------------------------

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Logic 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------

    ---------------------------------------------------------------------------------------
    -- 
    IF p_WRK_TP = 'Q1' THEN

        -- 결재선 미결함
        OPEN RTN_CURSOR FOR
        SELECT A.SIT_CD                                                                                                             -- 현장코드
             , A.APRV_NO                                                                                                            -- 결재번호
             , A.SITE_APRV_TP                                                                                                       -- 결재 유형
             , (SELECT CD_NM FROM TCOA_COMCODE WHERE COM_CD = A.SITE_APRV_TP AND HRNK_CD = 'QS039')         AS APRV_TP_NM           -- 결재유형명칭
             , (SELECT CHRC_VAL_1 FROM TCOA_COMCODE WHERE COM_CD = A.SITE_APRV_TP AND HRNK_CD = 'QS039')    AS APRV_TP_PAGE_NM      -- 결재유형별 화면명
             , A.APRV_TTL                                                                                                           -- 결재 제목
             , A.APRV_SCHF                                                                                                          -- 결재 상신자ID
             , B.USR_NM                                                                                                             -- 상신자 성명
             , TO_CHAR(A.APRV_SCHF_DTM, 'YYYY-MM-DD')                                                       AS APRV_SCHF_DTM        -- 결재 상신일자
             , TO_CHAR(A.APRV_APRV_DTM, 'YYYY-MM-DD')                                                       AS APRV_APRV_DTM        -- 결재 승인일자(진행중/최종 일자 함게 사용)
             , A.APRV_STATS                                                                                                         -- 결재 상태
             , (SELECT CD_NM FROM TCOA_COMCODE WHERE COM_CD = A.APRV_STATS AND HRNK_CD = 'QS031')           AS APRV_STATS_NM        -- 결재 상태명칭
             , A.APRV_CLS_NO                                                                                                        -- 결재 키 변수
          FROM TQHA_APRV A
             , TCOZ_USR_INFO B
             , ( -- 결재 내가 바로 결재해야 할 항목 조회(미결함)
                SELECT SIT_CD        -- 현장코드
                     , APRV_NO        -- 결재번호
                     , APRV_SO        -- 결재순서
                     , APRV_PSN_ID    -- 결재자 id
                     , APRV_STATS     -- 결재상태
                     , PRE_APRV_STATS -- 이전 결재자의 결재상태
                     , APRV_APRV_DTM  -- 결재승인일자
                     , APRV_OPIN      -- 결재의견
                  FROM ( -- 결재번호별 이전 결재자의 결재상태를 조회
                        SELECT SIT_CD                                                                           -- 현장코드
                             , APRV_NO                                                                          -- 결재번호
                             , APRV_SO                                                                          -- 결재순서
                             , APRV_PSN_ID                                                                      -- 결재자 id
                             , APRV_STATS                                                                       -- 결재상태
                             , LAG(APRV_STATS) OVER (ORDER BY SIT_CD, APRV_NO , APRV_SO) AS PRE_APRV_STATS      -- 이전 결재자의 결재상태
                             , APRV_APRV_DTM                                                                    -- 결재승인일자
                             , APRV_OPIN                                                                        -- 결재의견
                          FROM TQHA_APRV_LINE
                         WHERE SIT_CD   = p_SIT_CD -- 변수 (현장코드)
                         ORDER BY SIT_CD
                             , APRV_NO
                             , APRV_SO
                      )
                 WHERE SIT_CD       = p_SIT_CD          -- 변수 (현장코드)
                   AND APRV_PSN_ID  IN (p_USR_ID) -- 결재자
                   AND (APRV_STATS  IS NULL AND PRE_APRV_STATS = '4') -- 이전 결재자가 결재완료 한경우 완 내가 결재 안한 상태를 조회
               ) C
         WHERE A.SIT_CD     = p_SIT_CD              -- 변수 (현장코드)
           AND A.APRV_STATS = '2'                   -- 변수 (결재상태) 2 결재진행
           AND A.SIT_CD     = C.SIT_CD
           AND A.APRV_NO    = C.APRV_NO
           AND A.APRV_SCHF  = B.USR_ID
           AND (SUBSTR(TO_CHAR(A.APRV_SCHF_DTM, 'YYYYMMDD'), 1, 6) = p_SEARCH_STR_YM 
                OR
                NVL(p_SEARCH_STR_YM, 0) = 0)        -- 검색조전 변수 결재년월 ( 결재상신일자 기준 )
           AND (A.SITE_APRV_TP = p_SITE_APRV_TP OR NVL(p_SITE_APRV_TP, 0) = 0)                                                   -- 검색조건 변수 결재유형 ( 결재유형 )
         ORDER BY TO_CHAR(A.APRV_SCHF_DTM, 'YYYY-MM-DD') DESC
        ;

    ELSIF p_WRK_TP = 'Q2' THEN

        -- 미결함 이외의 결재함(진행, 완료, 반려)
        OPEN RTN_CURSOR FOR
        SELECT A.SIT_CD                                                                                                         -- 현장코드
             , A.APRV_NO                                                                                                        -- 결재번호
             , A.SITE_APRV_TP                                                                                                   -- 결재 유형
             , ( SELECT CD_NM FROM TCOA_COMCODE WHERE COM_CD = A.SITE_APRV_TP AND HRNK_CD = 'QS039')        AS APRV_TP_NM       -- 결재유형명칭
             , (SELECT CHRC_VAL_1 FROM TCOA_COMCODE WHERE COM_CD = A.SITE_APRV_TP AND HRNK_CD = 'QS039')    AS APRV_TP_PAGE_NM  -- 결재유형별 화면명
             , A.APRV_TTL                                                                                                       -- 결재 제목
             , A.APRV_SCHF                                                                                                      -- 결재 상신자ID
             , B.USR_NM                                                                                                         -- 상신자 성명 
             , TO_CHAR(A.APRV_SCHF_DTM, 'YYYY-MM-DD')                                                       AS APRV_SCHF_DTM    -- 결재 상신일자
             , TO_CHAR(A.APRV_APRV_DTM, 'YYYY-MM-DD')                                                       AS APRV_APRV_DTM    -- 결재 승인일자(진행중/최종 일자 함게 사용)
             , A.APRV_STATS                                                                                                     -- 결재 상태
             , ( SELECT CD_NM FROM TCOA_COMCODE WHERE COM_CD = A.APRV_STATS AND HRNK_CD = 'QS031')          AS APRV_STATS_NM    --  결재 상태명칭
             , A.APRV_CLS_NO                                                                                                    -- 결재 키 변수
          FROM TQHA_APRV A
             , TCOZ_USR_INFO B
             , ( -- 결재라인에 있는 결재자 인지 체크(진행함)
                SELECT SIT_CD                   -- 현장코드
                     , APRV_NO                  -- 결재번호
                     , APRV_SO                  -- 결재순서
                     , APRV_PSN_ID              -- 결재자 id
                     , APRV_STATS               -- 결재상태
                     , APRV_APRV_DTM            -- 결재승인일자
                     , APRV_OPIN                -- 결재의견
                  FROM TQHA_APRV_LINE
                 WHERE SIT_CD = p_SIT_CD            -- 변수 (현장코드)
                   AND APRV_PSN_ID IN (p_USR_ID)    -- 변수 (사용자 id)
               ) C
         WHERE A.SIT_CD         = p_SIT_CD          -- 변수 (현장코드)
           AND A.APRV_STATS     = p_APRV_STATS      -- 변수 (결재상태) 3 결재반려
           AND A.SIT_CD         = C.SIT_CD
           AND A.APRV_NO        = C.APRV_NO
           AND A.APRV_SCHF      = B.USR_ID
           AND (SUBSTR(TO_CHAR(A.APRV_SCHF_DTM,'YYYYMMDD'),1,6) = p_SEARCH_STR_YM OR  NVL(p_SEARCH_STR_YM, 0) = 0)  -- 검색조전 변수 결재년월 ( 결재상신일자 기준 )
           AND (A.SITE_APRV_TP = p_SITE_APRV_TP OR NVL(p_SITE_APRV_TP, 0) = 0)                                      -- 검색조건 변수 결재유형 ( 결재유형 )
         ORDER BY TO_CHAR(A.APRV_SCHF_DTM, 'YYYY-MM-DD') DESC
        ;

    ELSIF p_WRK_TP = 'Q3' THEN

        -- 결재선 미결함 ( 결재상태 )
        OPEN RTN_CURSOR FOR
        SELECT A.SIT_CD                                                                                                 -- 현장코드
             , A.APRV_NO                                                                                                -- 결재번호
             , A.APRV_SO                                                                                                -- 결재순서
             , A.APRV_PSN_ID                                                                                            -- 결재자 id
             , B.USR_NM                                                                                                 -- 결재자 성명                                
             , A.APRV_STATS                                                                                             -- 결재상태
             , (SELECT CD_NM FROM TCOA_COMCODE WHERE COM_CD = A.APRV_STATS AND HRNK_CD = 'QS031') AS APRV_STATS_NM      --  결재 상태명칭
             , TO_CHAR(A.APRV_APRV_DTM, 'YYYY-MM-DD') AS APRV_APRV_DTM                                                  -- 결재 승인일자(진행중/최종 일자 함게 사용)
             , A.APRV_OPIN                                                                                              -- 결재의견
          FROM TQHA_APRV_LINE A
             , TCOZ_USR_INFO B
         WHERE A.SIT_CD         = p_SIT_CD      -- 변수 (현장코드)
           AND A.APRV_NO        = p_APRV_NO     -- 변수 (결재번호)  
           AND A.APRV_PSN_ID    = B.USR_ID
        ;

    ELSIF p_WRK_TP = 'Q4' THEN

        -- 현장소장
     OPEN RTN_CURSOR FOR
     SELECT A.JB_CD
	  FROM TQHA_SITENAM A
	 WHERE 1=1
	    AND A.SIT_CD = p_SIT_CD
	    AND A.EMPE_NO = p_USR_ID
	    ;
--    
--        OPEN RTN_CURSOR FOR
--        SELECT JB_CD                -- 직무 (현장소장)
--          FROM TCOZ_USR_INFO
--         WHERE USR_ID =  p_USR_ID   -- 사번
--        ;

    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
         WHEN OTHERS THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);

END PQHA_APRV_Q;
/

-- PQHA_APRV_S (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_APRV_S" 
                            (p_WRK_TP  VARCHAR2 :='U'                                     -- UPDATE FLAG( I: ISNERT, U:UPDATE, D:DELTE)
                            ,p_WRK_ID  VARCHAR2                                           -- 사용자 ID 
                            ,p_WRK_IP  VARCHAR2                                           -- 사용자 IP 
                            ,p_SIT_CD TQHA_APRV.SIT_CD%TYPE                               -- 현장코드
                            ,p_APRV_NO TQHA_APRV.APRV_NO%TYPE                             -- 결재번호
                            ,p_APRV_TTL TQHA_APRV.APRV_TTL%TYPE                           -- 결재제목
                            ,p_APRV_SCHF TQHA_APRV.APRV_SCHF%TYPE                         -- 결재상신자
                            ,p_APRV_SCHF_DTM TQHA_APRV.APRV_SCHF_DTM%TYPE                 -- 결재상신일시
                            ,p_APRV_STATS TQHA_APRV.APRV_STATS%TYPE                       -- 결재상태구분(QS031) 
                            ,p_APRV_APRV_DTM TQHA_APRV.APRV_APRV_DTM%TYPE                 -- 결재승인일시
                            ,p_APRV_CLS_NO TQHA_APRV.APRV_CLS_NO%TYPE                     -- 키변수처리
                            ,p_SITE_APRV_TP TQHA_APRV.SITE_APRV_TP%TYPE                   -- 결재유형(QS039)
                            ,p_RTN_APRV_NO OUT VARCHAR2)                                  -- 리턴변수(결재번호)
IS 
    /**************************************************************************************************************************
      Purpose : 안전 결재번호 진행사항 관리

      REVISIONS
      Ver      Date               Author                  Description 
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2022/01/20 14:22:09                         최초생성

    **************************************************************************************************************************/


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR2(200);            -- ERROR Message
    USER_EXCEPTION EXCEPTION;

   	v_APRV_NO TQHA_APRV.APRV_NO%TYPE;

BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 필수입력 필드  Check  ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_SIT_CD IS NULL)  THEN
        ERR_MSG := '현장코드는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_APRV_NO IS NULL AND p_WRK_TP <> 'I')  THEN
        ERR_MSG := '결재번호는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Process 선행조건 Check ]
    ---------------------------------------------------------------------------------------------------------------------------



    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Business Process ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_WRK_TP ='D') THEN
        DELETE 
          FROM TQHA_APRV
         WHERE SIT_CD = p_SIT_CD         --현장코드
           AND APRV_NO = p_APRV_NO;        --결재번호

        v_APRV_NO := p_APRV_NO;

    ELSIF (p_WRK_TP ='U') THEN
        UPDATE TQHA_APRV
           SET APRV_TTL             = p_APRV_TTL                --결재제목
              ,APRV_SCHF            = p_APRV_SCHF               --결재상신자
              ,APRV_SCHF_DTM        = p_APRV_SCHF_DTM           --결재상신일시
              ,APRV_STATS           = p_APRV_STATS              --결재상태구분(QS031) 
              ,APRV_APRV_DTM        = p_APRV_APRV_DTM           --결재승인일시
              ,APRV_CLS_NO          = p_APRV_CLS_NO             --키변수처리
              ,SITE_APRV_TP         = p_SITE_APRV_TP            --결재유형(QS039) 
              ,UPD_ID               = p_WRK_ID                  --수정ID 
              ,UPD_DTM              = SYSDATE()                 --수정일시
              ,UPD_IP               = p_WRK_IP                  --수정IP
         WHERE SIT_CD = p_SIT_CD         --현장코드
           AND APRV_NO = p_APRV_NO;        --결재번호

        v_APRV_NO := p_APRV_NO;

    ELSE 

    	-- 신규 결재번호 채번
		SELECT NVL((MAX(TO_NUMBER(APRV_NO))+1), 1) 
	      INTO v_APRV_NO
	      FROM TQHA_APRV
	     WHERE SIT_CD = p_SIT_CD;          --현장코드

        INSERT INTO TQHA_APRV
                   ( SIT_CD                 --현장코드
                    ,APRV_NO                 --결재번호
                    ,APRV_TTL                --결재제목
                    ,APRV_SCHF               --결재상신자
                    ,APRV_SCHF_DTM           --결재상신일시
                    ,APRV_STATS              --결재상태구분(QS031) 
                    ,APRV_APRV_DTM           --결재승인일시
                    ,APRV_CLS_NO             --키변수처리
                    ,SITE_APRV_TP            --결재유형(QS039) 
                    ,IPT_ID                  --입력ID
                    ,IPT_DTM                 --입력일시
                    ,IPT_IP                  --입력IP
                    ,UPD_ID                  --수정ID
                    ,UPD_DTM                 --수정일시
                    ,UPD_IP)                 --수정IP
             VALUES (p_SIT_CD               --현장코드
                    ,v_APRV_NO               --결재번호
                    ,p_APRV_TTL              --결재제목
                    ,p_APRV_SCHF             --결재상신자
                    ,p_APRV_SCHF_DTM         --결재상신일시
                    ,p_APRV_STATS            --결재상태구분(QS031) 
                    ,p_APRV_APRV_DTM         --결재승인일시
                    ,p_APRV_CLS_NO           --키변수처리
                    ,p_SITE_APRV_TP          --결재유형(QS039) 
                    ,p_WRK_ID                --입력ID 
                    ,SYSDATE()               --입력일시
                    ,p_WRK_IP                --입력IP
                    ,p_WRK_ID                --수정ID
                    ,SYSDATE()               --수정일시
                    ,p_WRK_IP);              --수정IP
    END IF;

   	p_RTN_APRV_NO := v_APRV_NO;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 5. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN 
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);
END ;
/

-- PQHA_APRV_SCHF_B (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_APRV_SCHF_B" -- 결재상신
                            (p_WRK_TP  VARCHAR2 :='S'                                     -- UPDATE FLAG( S: 결재상신, A : 결재승인,  C: 취소,  R: 반려)    
                            ,p_WRK_ID  VARCHAR2                                           -- 사용자 ID
                            ,p_WRK_IP  VARCHAR2                                           -- 사용자 IP
                            ,p_SIT_CD TQHA_APRV.SIT_CD%TYPE                               -- 현장코드
                            ,p_APRV_NO TQHA_APRV.APRV_NO%TYPE                             -- 결재번호
--                            ,p_APRV_SCHF TQHA_APRV.APRV_SCHF%TYPE                       -- 결재상신자                            
                            ,p_APRV_OPIN TQHA_APRV_LINE.APRV_OPIN%TYPE                    -- 결재의견 
                            )
IS
    /**************************************************************************************************************************
      Purpose : 현장 결재 상신 

      REVISIONS
      Ver      Date               Author                  Description
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2022/01/19                                  최초생성

    **************************************************************************************************************************/

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR2(200);            -- ERROR Message
    USER_EXCEPTION EXCEPTION;

    v_LINE_CNT         INTEGER;                           -- 결재라인 존재여무 체크
    v_FIRST_APRV_SO    INTEGER;                           -- 현재 결재선의 1번째 결재대상 순서 
    v_LAST_APRV_SO     INTEGER;                           -- 현재 결재선의 마지막번째 결재대상 순서

    v_APRV_SELF_SO     INTEGER;                                     -- 내 결재순번
    v_APRV_NEXT_SO     INTEGER;                                     -- 내 다음 결재순번
    v_NEXT_APRV        INTEGER := 0;                                -- 내 결재순번 결재했는지 체크 0 미결재, 1 결재

    v_FIRST_PSN_ID     VARCHAR2(10);                       -- 현재 결재선의 1번째 결재대상 ID 
    v_LAST_PSN_ID      VARCHAR2(10);                       -- 현재 결재선의 마지막번째 결재대상 ID    
    v_APRV_SCHF        VARCHAR2(10);                       -- 최조 결재 상신자 id 

BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 필수입력 필드  Check  ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_SIT_CD IS NULL)  THEN
        ERR_MSG := '현장코드는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_APRV_NO IS NULL)  THEN
        ERR_MSG := '결재번호는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Process 선행조건 Check ]
    ---------------------------------------------------------------------------------------------------------------------------
	    -- 결재선 라인 지정 유무 확인
   IF (p_WRK_TP <> 'C') THEN	-- 취소(회수 인 경우)는 제외 처리
        SELECT nvl(COUNT(APRV_SO),0) 
          INTO v_LINE_CNT 
          FROM TQHA_APRV_LINE
         WHERE SIT_CD = p_SIT_CD         -- 변수 ( 현장코드)
           AND APRV_NO = p_APRV_NO  ;       -- 변수 ( 현장코드)

        IF v_LINE_CNT < 2 THEN   -- 결재라인이 등록 안 된경우
           ERR_MSG := '결재라인이 제대로 등록되 지 않았습니다. 확인 후 다시 진행해주세요 ';
           RAISE USER_EXCEPTION;
        END IF;

        -- 결재선의 현재 결재해야 할 사람중 첫번째와 마지막 사번을 체크
	     SELECT    FIRST_VALUE(APRV_SO) OVER()     AS FIRST_APRV_SO 
	             , LAST_VALUE(APRV_SO) OVER()      AS LAST_APRV_SO	                    
	             , FIRST_VALUE(APRV_PSN_ID) OVER() AS FIRST_PSN_ID
	             , LAST_VALUE(APRV_PSN_ID) OVER()  AS LAST_PSN_ID	                           
	       INTO    v_FIRST_APRV_SO  
	             , v_LAST_APRV_SO  
	             , v_FIRST_PSN_ID  
	             , v_LAST_PSN_ID   
	        FROM TQHA_APRV_LINE  
	       WHERE SIT_CD = p_SIT_CD                 -- 변수 (현장코드)
	         AND APRV_NO = p_APRV_NO                 -- 변수 (결재번호)  
--	         AND ( APRV_STATS IS NULL  )                 -- 조건 승인상태가 NULL 인경우 와 결재 작성중  
	         AND ( APRV_STATS IS NULL  OR  APRV_STATS = '1' )                 -- 조건 승인상태가 NULL 인경우 와 결재 작성중	         
	    ORDER BY SIT_CD, APRV_NO ,APRV_SO   
	    FETCH FIRST 1 ROW ONLY ;

        IF ( v_FIRST_PSN_ID <> p_WRK_ID ) THEN   -- 현재결재 대상이 아니면
           ERR_MSG := '결재 대상자가 아닙니다. 확인 후 다시 진행해주세요  ';
           RAISE USER_EXCEPTION;
        END IF;
    END IF;       

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Business Process ]
    ---------------------------------------------------------------------------------------------------------------------------
	IF (p_WRK_TP ='S' OR p_WRK_TP ='A') THEN	-- 결재 상신(S)/ 결재 승인(A)

	    -- 결재선 결재처리
		UPDATE	TQHA_APRV_LINE 
		   SET	  APRV_STATS = '4'            -- 결재상태 ( 1 작성중, 2 결재진행  3, 결재반려, 4 결재완료)
		        , APRV_APRV_DTM = SYSDATE()   -- 결재승인 일시
		        , APRV_OPIN = p_APRV_OPIN     -- 결재 의견
		 WHERE	SIT_CD	= p_SIT_CD                -- 변수 (현장코드)
           AND	APRV_NO  = p_APRV_NO               -- 변수 (결재번호)
           AND  APRV_PSN_ID = p_WRK_ID ; 	       -- 변수 (결재자id)

        -- 결재 테이블에 결재상태 UPDATE   
        IF ( v_LAST_PSN_ID = p_WRK_ID ) THEN   -- 최종결재자 인경우

            -- 결재 최종상태 UPDATE
	  		UPDATE	TQHA_APRV
			   SET	  APRV_STATS = '4'            -- 결재상태 ( 1 작성중, 2 결재진행  3, 결재반려, 4 결재완료)
			        , APRV_APRV_DTM = SYSDATE()    -- 결재승인 일시
			 WHERE	SIT_CD	= p_SIT_CD                -- 변수 (현장코드)
	           AND	APRV_NO = p_APRV_NO  ;             -- 변수 (결재번호)

        ELSE
	       IF (p_WRK_TP ='S' ) THEN	-- 결재 상신(S)        
	            -- 결재 진행상태 UPDATE
		  		UPDATE	TQHA_APRV 
				   SET	  APRV_STATS = '2'            -- 결재상태 ( 1 작성중, 2 결재진행  3, 결재반려, 4 결재완료)
				        , APRV_APRV_DTM = SYSDATE()   -- 결재승인 일시				   
				        , APRV_SCHF = p_WRK_ID        -- 결재상신자				   
				        , APRV_SCHF_DTM = SYSDATE()   -- 결재상신 일시
				 WHERE	SIT_CD	= p_SIT_CD                -- 변수 (현장코드)
		           AND	APRV_NO = p_APRV_NO  ;             -- 변수 (결재번호)
           END IF;
		   IF (p_WRK_TP ='A' ) THEN	-- 결재 승인(A)
	            -- 결재 진행상태 UPDATE
		  		UPDATE	TQHA_APRV 
				   SET	  APRV_STATS = '2'            -- 결재상태 ( 1 작성중, 2 결재진행  3, 결재반려, 4 결재완료)
				        , APRV_APRV_DTM = SYSDATE()   -- 결재승인 일시
				 WHERE	SIT_CD	= p_SIT_CD                -- 변수 (현장코드)
		           AND	APRV_NO = p_APRV_NO  ;             -- 변수 (결재번호)
           END IF ;
        END IF;


	ELSIF (p_WRK_TP = 'C') THEN	-- 결재 상신 취소   ( 결재 회수 기능 추가 : 다음 단계 결재자가 미결재 중인경우 다시 결재를 활수 있는 기능)

	    -- 최조 결재 상신자 찾기  v_APRV_SCHF
             SELECT APRV_PSN_ID
               INTO v_APRV_SCHF
               FROM TQHA_APRV_LINE
			  WHERE	SIT_CD	= p_SIT_CD                -- 변수 (현장코드)
                AND	APRV_NO  = p_APRV_NO               -- 변수 (결재번호)
 	            AND APRV_SO = '1' ; 	               -- 결재 상신자 순번 1

        IF (  v_APRV_SCHF = p_WRK_ID ) THEN   -- 최초 상신자 취소 인경우    

		    -- 결재라인 상신자 결재 취소 
			UPDATE	TQHA_APRV_LINE 
--			   SET	  APRV_STATS = '1'             -- 결재상태 ( 1 작성중, 2 결재진행  3, 결재반려, 4 결재완료)
			   SET	  APRV_STATS = NULL             -- 결재상태 ( 1 작성중, 2 결재진행  3, 결재반려, 4 결재완료)			   
			        , APRV_APRV_DTM = NULL         -- 결재승인 일시
			        , APRV_OPIN = p_APRV_OPIN      -- 결재취소 의견  
			 WHERE	SIT_CD	= p_SIT_CD                -- 변수 (현장코드)
	           AND	APRV_NO  = p_APRV_NO               -- 변수 (결재번호)
	           AND  APRV_PSN_ID = p_WRK_ID ; 	       -- 변수 (결재자id)


		    -- 결재 상태 UPDATE(결재 상신 취소)
			UPDATE	TQHA_APRV
			  SET	  APRV_STATS = '1'           -- 결재상태 ( 1 작성중, 2 결재진행  3, 결재반려, 4 결재완료)
			        , APRV_SCHF = NULL           -- 결재상신자iD			   
			        , APRV_APRV_DTM = NULL       -- 결재승인 일시
			 WHERE	SIT_CD	= p_SIT_CD
	           AND	APRV_NO  = p_APRV_NO  ; 

        ELSE                                  -- 결재 진행자 취소(회수기능)

          -- 내 결재 순번 찾기
             SELECT APRV_SO 
               INTO v_APRV_SELF_SO
               FROM TQHA_APRV_LINE
			  WHERE	SIT_CD	= p_SIT_CD                -- 변수 (현장코드)
                AND	APRV_NO  = p_APRV_NO               -- 변수 (결재번호)
 	            AND APRV_PSN_ID = p_WRK_ID ; 	       -- 변수 (결재자id)

 	        v_APRV_NEXT_SO :=  v_APRV_SELF_SO + 1  ; -- 내 다음 결재자 순번 

 	      -- 내 다음 결재자가 결재를 했는지 여부  

           SELECT NVL(MAX(1),0) INTO v_NEXT_APRV
             FROM DUAL
            WHERE EXISTS (SELECT 1 
                      FROM TQHA_APRV_LINE  
                     WHERE SIT_CD =  p_SIT_CD                   -- 변수 (현장코드)
 		               AND APRV_NO =  p_APRV_NO                   -- 변수 (결재번호)  
 		               AND APRV_SO =  v_APRV_NEXT_SO              -- 내 다음결재 순번 		               
                       AND APRV_STATS IS NOT NULL                 -- 내 다음결재 순번 결재상태가 NULL 인지 확인(미 결재)
                      );

		     IF v_NEXT_APRV > 0   THEN
		         ERR_MSG := '다음 결재가 결재가 완료되어 취소할 수 없습니다.';
		         RAISE USER_EXCEPTION;
		     ELSE

			    -- 내 완료된 결재 취소(회수)
				UPDATE	TQHA_APRV_LINE 
				   SET	  APRV_STATS = NULL                 -- 결재상태 ( 1 작성중, 2 결재진행  3, 결재반려, 4 결재완료)
				        , APRV_APRV_DTM = NULL              -- 결재승인 일시
			            , APRV_OPIN = NULL                   -- 결재취소 의견
				 WHERE	SIT_CD	= p_SIT_CD                -- 변수 (현장코드)
		           AND	APRV_NO  = p_APRV_NO               -- 변수 (결재번호)
		           AND  APRV_SO = v_APRV_SELF_SO ; 	       -- 내 결재 순번


			    -- 결재 상태 UPDATE(결재 상신 취소)
				UPDATE	TQHA_APRV
				   SET	  APRV_STATS = '2'             -- 결재상태 ( 1 작성중, 2 결재진행  3, 결재반려, 4 결재완료)
				        , APRV_APRV_DTM = NULL         -- 결재승인 일시
				 WHERE	SIT_CD	= p_SIT_CD
		           AND	APRV_NO  = p_APRV_NO  ; 

		     END IF; 	            

         END IF;     

    ELSIF (p_WRK_TP ='R') THEN	-- 결재 반려  

	    -- 결재라인 결재 반려 ( 반려  )
			UPDATE	TQHA_APRV_LINE 
			   SET	  APRV_STATS = '3'             -- 결재상태 ( 1 작성중, 2 결재진행  3, 결재반려, 4 결재완료)
			        , APRV_APRV_DTM = SYSDATE()    -- 결재승인 일시
			        , APRV_OPIN = p_APRV_OPIN      -- 결재반려 의견  
			 WHERE	SIT_CD	= p_SIT_CD                -- 변수 (현장코드)
	           AND	APRV_NO  = p_APRV_NO               -- 변수 (결재번호)
	           AND  APRV_PSN_ID = p_WRK_ID ; 	       -- 변수 (결재자id)


		    -- 결재 상태 UPDATE(결재 반려)
			UPDATE	TQHA_APRV
			   SET	  APRV_STATS = '3'               -- 결재상태 ( 1 작성중, 2 결재진행  3, 결재반려, 4 결재완료)
			        , APRV_APRV_DTM = SYSDATE()      -- 결재승인 일시
			 WHERE	SIT_CD	= p_SIT_CD
	           AND	APRV_NO  = p_APRV_NO  ; 

    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 5. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);
END PQHA_APRV_SCHF_B;
/

-- PQHA_AREC_CD_Q (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_AREC_CD_Q" (
    p_WRK_TP        VARCHAR2 DEFAULT 'Q'            -- FLAG( Q: SELECT )
,   RTN_CURSOR      OUT SYS_REFCURSOR
)
IS 
    /**************************************************************************************************************************
      Purpose : 협의체코드 조회

      REVISIONS
      Ver      Date               Author                  Description 
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2024/03/04 12:06:21                         최초생성
      1.1     2024/03/05 17:00:00   정우성                  실시주기/심의의결사항 추가

    **************************************************************************************************************************/


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR2(200);            -- ERROR Message
    USER_EXCEPTION EXCEPTION;


BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 수행전 Check Logic ]
    ---------------------------------------------------------------------------------------------------------------------------


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Logic 처리
    ---------------------------------------------------------------------------------------------------------------------------

    OPEN RTN_CURSOR FOR
    SELECT AREC_CD                  -- 회의록코드
         , AREC_NM                  -- 회의록명
         --2024/03/05 17:00:00   정우성                  실시주기/심의의결사항 추가
         , IMPL_CYCLE               -- 실시주기
         , DECD_MATT                -- 심의의결사항
         , RELGRN                   -- 관련근거
         ------------------------------------------------
         , USE_YN                   -- 사용 1 미사용 0
         , IPT_ID                   -- 입력ID
         , IPT_DTM                  -- 입력일시
         , IPT_IP                   -- 입력IP
         , UPD_ID                   -- 수정ID
         , UPD_DTM                  -- 수정일시
         , UPD_IP                   -- 수정IP
      FROM TQHA_AREC_CD
    ;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN 
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);
END ;
/

-- PQHA_AREC_CD_S (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_AREC_CD_S" (
    p_WRK_TP            VARCHAR2 :='U'                                  -- UPDATE FLAG( I: ISNERT, U:UPDATE, D:DELTE)
,   p_WRK_ID            VARCHAR2                                        -- 사용자 ID
,   p_WRK_IP            VARCHAR2                                        -- 사용자 IP
,   p_AREC_CD           TQHA_AREC_CD.AREC_CD            %TYPE           -- 회의록코드
,   p_AREC_NM           TQHA_AREC_CD.AREC_NM            %TYPE           -- 회의록명
,   p_IMPL_CYCLE        TQHA_AREC_CD.IMPL_CYCLE         %TYPE           -- 실시주기
,   p_DECD_MATT         TQHA_AREC_CD.DECD_MATT          %TYPE           -- 의결사항
,   p_USE_YN            TQHA_AREC_CD.USE_YN             %TYPE           -- 사용 1 미사용 0
,   p_RELGRN            TQHA_AREC_CD.RELGRN             %TYPE           -- 관련근거
)
IS
    /**************************************************************************************************************************
      Purpose : 협의체코드 저장

      REVISIONS
      Ver      Date               Author                  Description
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2024/03/04 12:04:58                         최초생성
      1.1     2024/03/06 10:00:00   정우성                  Validation 수정

    **************************************************************************************************************************/


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR2(200);            -- ERROR Message
    USER_EXCEPTION EXCEPTION;

    v_AREC_CD       TQHA_AREC_CD.AREC_CD    %TYPE;      -- 협의체코드 변수 선언
    v_cnt           INTEGER;                            -- 사용여부 변수

BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 필수입력 필드  Check  ]
    ---------------------------------------------------------------------------------------------------------------------------

    --2024/03/06 10:00:00    Validation 수정 (정우성)--------
    IF (p_AREC_NM IS NULL)  THEN
        ERR_MSG := '회의록명는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;
    -------------------------------------------------------

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Process 선행조건 Check ]
    ---------------------------------------------------------------------------------------------------------------------------
      --  2024/03/05 협의체 회의록에서 사용중인 코드는 삭제불가 처리 추가
    IF p_WRK_TP = 'D' THEN

        SELECT nvl(COUNT(AREC_CD),0)
          INTO v_cnt
          FROM TQHA_LAB_AREC
         WHERE AREC_CD = p_AREC_CD
        ;

         -- 협의체 코드 사용여부 체크
        IF v_cnt > 0 THEN
            ERR_MSG := '협의체 회의록 "' || p_AREC_NM || '" 은(는) 이미 사용중입니다. 이미 사용중인 협의체 항목은 삭제할 수 없습니다. ';
            RAISE USER_EXCEPTION;
        END IF;
    END IF;


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Business Process ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_WRK_TP ='D') THEN

        DELETE
          FROM TQHA_AREC_CD
         WHERE AREC_CD = p_AREC_CD        --회의록코드
        ;

    ELSIF (p_WRK_TP ='U') THEN

        UPDATE TQHA_AREC_CD
           SET AREC_NM          = p_AREC_NM             -- 회의록명
             , IMPL_CYCLE       = p_IMPL_CYCLE          -- 실시주기
             , DECD_MATT        = p_DECD_MATT           -- 의결사항
             , USE_YN           = p_USE_YN              -- 사용 1 미사용 0
             , RELGRN           = p_RELGRN              -- 관련근거
             , UPD_ID           = p_WRK_ID              -- 수정ID
             , UPD_DTM          = SYSDATE()             -- 수정일시
             , UPD_IP           = p_WRK_IP              -- 수정IP
         WHERE AREC_CD          = p_AREC_CD             -- 회의록코드
        ;

    ELSE

        -- 협의체 코드 MAX부여
        SELECT LPAD(NVL(MAX(SUBSTR(AREC_CD, 1, 3)), 0) + 1, 3,'0')
          INTO v_AREC_CD
          FROM TQHA_AREC_CD 
        ;
        --

        INSERT 
          INTO TQHA_AREC_CD
             ( AREC_CD              -- 회의록코드
             , AREC_NM              -- 회의록명
             , IMPL_CYCLE           -- 실시주기
             , DECD_MATT            -- 의결사항
             , USE_YN               -- 사용 1 미사용 0
             , RELGRN               -- 관련근거
             , IPT_ID               -- 입력ID
             , IPT_DTM              -- 입력일시
             , IPT_IP               -- 입력IP
             , UPD_ID               -- 수정ID
             , UPD_DTM              -- 수정일시
             , UPD_IP               -- 수정IP
             )
        VALUES 
             ( v_AREC_CD            -- 회의록코드
             , p_AREC_NM            -- 회의록명
             , p_IMPL_CYCLE         -- 실시주기
             , p_DECD_MATT          -- 의결사항
             , p_USE_YN             -- 사용 1 미사용 0
             , p_RELGRN             -- 관련근거
             , p_WRK_ID             -- 입력ID
             , SYSDATE()            -- 입력일시
             , p_WRK_IP             -- 입력IP
             , p_WRK_ID             -- 수정ID
             , SYSDATE()            -- 수정일시
             , p_WRK_IP             -- 수정IP
             )
        ;

    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 5. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);

END ;
/

-- PQHA_ARND_CHK_DRY_Q (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_ARND_CHK_DRY_Q"
							(
							      p_WRK_TP  VARCHAR2 :='Q'
	                             ,p_WRK_ID  VARCHAR2                                           -- 사용자 ID
	                             ,p_WRK_IP  VARCHAR2                                           -- 사용자 IP
							     ,p_SIT_CD TQHA_ARND_CHK_DRY.SIT_CD%TYPE                             -- 현장코드
							     ,p_CHK_FRDT TQHA_ARND_CHK_DRY.CHK_DT%TYPE                           -- 작성시작일자
							     ,p_CHK_TODT TQHA_ARND_CHK_DRY.CHK_DT%TYPE                           -- 작성종료일자
							     ,RTN_CURSOR OUT SYS_REFCURSOR
							)
IS 
    /**************************************************************************************************************************
      Purpose :  

      REVISIONS
      Ver      Date               Author                  Description 
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2026/05/22 12:27:56                         최초생성

    /**************************************************************************************************************************/


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR2(200);            -- ERROR Message
    USER_EXCEPTION EXCEPTION;


BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 수행전 Check Logic ]
    ---------------------------------------------------------------------------------------------------------------------------


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Logic 처리
    ---------------------------------------------------------------------------------------------------------------------------

    OPEN RTN_CURSOR FOR
    SELECT  A.SIT_CD                 --현장코드
           ,( SELECT CNST_NM FROM VQSZ_SITEINFO WHERE SIT_CD = A.SIT_CD ) AS SIT_NM
           ,A.CHK_SEQ                 --점검순번
           ,A.CHK_NM                 --점검명
           ,A.CHK_DT                 --점검일자
           ,A.CHK_QRT                 --점검분기
           ,A.CHK_CTS                 --점검내용
           ,A.RMKS                 --비고
           ,A.ATFL_GRP                 --첨부파일그룹
      FROM TQHA_ARND_CHK_DRY A
    WHERE SIT_CD LIKE p_SIT_CD ||'%'
      AND CHK_DT BETWEEN NVL(p_CHK_FRDT, '19000101') AND NVL(p_CHK_TODT, '47121231')
      ORDER BY SIT_CD, CHK_DT DESC           
           ;


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN 
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);
END ;
/

-- PQHA_ARND_CHK_DRY_S (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_ARND_CHK_DRY_S"
                            (p_WRK_TP  VARCHAR2 :='U'                                     -- UPDATE FLAG( I: ISNERT, U:UPDATE, D:DELTE)
                            ,p_WRK_ID  VARCHAR2                                           -- 사용자 ID 
                            ,p_WRK_IP  VARCHAR2                                           -- 사용자 IP 
                            ,p_SIT_CD TQHA_ARND_CHK_DRY.SIT_CD%TYPE                       -- 현장코드
                            ,p_CHK_SEQ TQHA_ARND_CHK_DRY.CHK_SEQ%TYPE                     -- 점검순번
                            ,p_CHK_NM TQHA_ARND_CHK_DRY.CHK_NM%TYPE                       -- 점검명
                            ,p_CHK_DT TQHA_ARND_CHK_DRY.CHK_DT%TYPE                       -- 점검일자
                            ,p_CHK_QRT TQHA_ARND_CHK_DRY.CHK_QRT%TYPE                     -- 점검분기
                            ,p_CHK_CTS TQHA_ARND_CHK_DRY.CHK_CTS%TYPE                     -- 점검내용
                            ,p_RMKS TQHA_ARND_CHK_DRY.RMKS%TYPE                           -- 비고
                            ,p_ATFL_GRP TQHA_ARND_CHK_DRY.ATFL_GRP%TYPE)                  -- 첨부파일그룹
IS 
    /**************************************************************************************************************************
      Purpose : 

      REVISIONS
      Ver      Date               Author                  Description 
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2026/05/22 12:33:02                         최초생성

    /**************************************************************************************************************************/


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR2(200);            -- ERROR Message
    USER_EXCEPTION EXCEPTION;

    v_SEQ NUMBER;

BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 필수입력 필드  Check  ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_SIT_CD IS NULL)  THEN
        ERR_MSG := '현장코드는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_WRK_TP != 'I' AND p_CHK_SEQ IS NULL)  THEN
        ERR_MSG := '순번는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Process 선행조건 Check ]
    ---------------------------------------------------------------------------------------------------------------------------

	SELECT NVL(MAX(CHK_SEQ), 0) + 1 INTO v_SEQ
    FROM TQHA_ARND_CHK_DRY
    WHERE SIT_CD = p_SIT_CD;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Business Process ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_WRK_TP ='D') THEN
        DELETE 
          FROM TQHA_ARND_CHK_DRY
         WHERE SIT_CD = p_SIT_CD          --현장코드
           AND CHK_SEQ = p_CHK_SEQ;        --점검순번

    ELSIF (p_WRK_TP ='U') THEN
        UPDATE TQHA_ARND_CHK_DRY
           SET CHK_NM               = p_CHK_NM                  --점검명
              ,CHK_DT               = p_CHK_DT                  --점검일자
              ,CHK_QRT              = p_CHK_QRT                 --점검분기
              ,CHK_CTS              = p_CHK_CTS                 --점검내용
              ,RMKS                 = p_RMKS                    --비고
              ,ATFL_GRP             = p_ATFL_GRP                --첨부파일그룹
              ,UPD_ID               = p_WRK_ID                  --수정ID 
              ,UPD_DTM              = SYSDATE()                 --수정일시
              ,UPD_IP               = p_WRK_IP                  --수정IP
         WHERE SIT_CD = p_SIT_CD          --현장코드
           AND CHK_SEQ = p_CHK_SEQ;        --점검순번 
    ELSE 
        INSERT INTO TQHA_ARND_CHK_DRY
                   ( SIT_CD                  --현장코드
                    ,CHK_SEQ                 --점검순번
                    ,CHK_NM                  --점검명
                    ,CHK_DT                  --점검일자
                    ,CHK_QRT                 --점검분기
                    ,CHK_CTS                 --점검내용
                    ,RMKS                    --비고
                    ,ATFL_GRP                --첨부파일그룹
                    ,IPT_ID                  --입력ID
                    ,IPT_DTM                 --입력일시
                    ,IPT_IP                  --입력IP
                    ,UPD_ID                  --수정ID
                    ,UPD_DTM                 --수정일시
                    ,UPD_IP                  --수정IP
                    )
             VALUES (p_SIT_CD                --현장코드
                    ,v_SEQ                   --점검순번
                    ,p_CHK_NM                --점검명
                    ,p_CHK_DT                --점검일자
                    ,p_CHK_QRT               --점검분기
                    ,p_CHK_CTS               --점검내용
                    ,p_RMKS                  --비고
                    ,p_ATFL_GRP              --첨부파일그룹
                    ,p_WRK_ID                --입력ID 
                    ,SYSDATE()               --입력일시
                    ,p_WRK_IP                --입력IP
                    ,p_WRK_ID                --수정ID
                    ,SYSDATE()               --수정일시
                    ,p_WRK_IP);              --수정IP
    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 5. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN 
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);
END ;
/

-- PQHA_ASSLOG_CIRC_Q (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_ASSLOG_CIRC_Q" (
    p_WRK_TP            IN VARCHAR2 DEFAULT 'Q'         -- FLAG
,   p_SIT_CD            IN VARCHAR2                     -- 현장코드
,   p_PLN_YM            IN VARCHAR2                     -- 계획년월 
,   p_PLN_DGR           IN VARCHAR2                     -- 계획회차
,   RTN_CURSOR          OUT SYS_REFCURSOR
)
IS
    /**************************************************************************************************************************
      Purpose : [수시위험성평가회의 참석자] PROCEDRE  

      REVISIONS
      Ver      Date               Author                  Description
      -------  -----------------  ----------------------  ---------------------------------------------------------------------
      1.0      2026/03/04                                 최초생성

    **************************************************************************************************************************/

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE  NUMBER :=-20009; -- ERROR 코드
    ERR_MSG   VARCHAR(200);    -- ERROR Message
    USER_EXCEPTION EXCEPTION;

BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 수행전 Check Logic ]
    ---------------------------------------------------------------------------------------------------------------------------

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Logic 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------

    --------------------------------------------------------------------------------------
    -- 회의록 개요 : 당사 그리드 조회
    IF (p_WRK_TP = 'Q1') THEN

        OPEN RTN_CURSOR FOR
        SELECT T1.EMPE_NO
             , T3.USR_NM
             , T1.DTY_NM
             ,(SELECT CD_NM FROM TCOA_COMCODE WHERE COM_CD = T1.JB_CD AND HRNK_CD = 'QS077' AND USE_YN = '1') AS JB_NM
             , T2.PRTR_YN                       -- 참석여부
             , T1.SIT_CD
             , p_PLN_YM         AS PLN_YM
             , p_PLN_DGR        AS PLN_DGR
             , '1'              AS CO_DIV_CD    -- 회사구분 1:당사
          FROM TQHA_SITENAM T1
          LEFT JOIN TQHA_ASSLOG_CIRC T2
            ON T1.EMPE_NO       = T2.EMPE_NO
           AND T2.PLN_YM        = p_PLN_YM
           AND T2.PLN_DGR       = p_PLN_DGR
           AND T2.CO_DIV_CD     = '1'
          LEFT JOIN TCOZ_USR_INFO T3 ON T1.EMPE_NO = T3.USR_ID
         WHERE T1.SIT_CD = p_SIT_CD
         ORDER BY T3.USR_NM
        ;

    ---------------------------------------------------------------------------------------
    -- 회의록 개요 : 협력회사 그리드 조회
    ELSIF p_WRK_TP = 'Q2' THEN

        OPEN RTN_CURSOR FOR
        SELECT T1.VNDR_PSN_ID       AS EMPE_NO
             , T1.VNDR_PSN_NM       AS USR_NM       -- 협력사명
             , T3.CUST_NM
             , T2.PRTR_YN                           -- 참석여부
             , T1.SIT_CD
             , p_PLN_YM             AS PLN_YM
             , p_PLN_DGR            AS PLN_DGR
             , '2'                  AS CO_DIV_CD    -- 회사구분 1:당사
          FROM TQHA_VNDR T1
          LEFT JOIN TQHA_ASSLOG_CIRC T2
            ON T1.VNDR_PSN_ID = T2.EMPE_NO
           AND T2.PLN_YM    = p_PLN_YM
           AND T2.PLN_DGR   = p_PLN_DGR
           AND T2.CO_DIV_CD = '2'
          LEFT JOIN VQSZ_TRADE T3 ON T1.CUST_CD = T3.CUST_CD
          WHERE T1.SIT_CD = p_SIT_CD
          ORDER BY T1.VNDR_PSN_NM
        ;

    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
         WHEN OTHERS THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);

END PQHA_ASSLOG_CIRC_Q;
/

-- PQHA_ASSLOG_CIRC_S (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_ASSLOG_CIRC_S" (
    p_WRK_TP            VARCHAR2 :='U'                              -- UPDATE FLAG( I: ISNERT, U:UPDATE, D:DELTE)
,   p_WRK_ID            VARCHAR2                                    -- 사용자 ID 
,   p_WRK_IP            VARCHAR2                                    -- 사용자 IP 
,   p_SIT_CD            TQHA_ASSLOG_CIRC.SIT_CD         %TYPE       -- 현장코드
,   p_PLN_YM            TQHA_ASSLOG_CIRC.PLN_YM         %TYPE       -- 계획년월
,   p_PLN_DGR           TQHA_ASSLOG_CIRC.PLN_DGR        %TYPE       -- 차수구분코드(QS005) 1 1차,2 2차
,   p_CO_DIV_CD         TQHA_ASSLOG_CIRC.CO_DIV_CD      %TYPE       -- 회사구분코드
,   p_EMPE_NO           TQHA_ASSLOG_CIRC.EMPE_NO        %TYPE       -- 사원번호
,   p_PRTR_YN           TQHA_ASSLOG_CIRC.PRTR_YN        %TYPE       -- 참석여부
)
IS 
    /**************************************************************************************************************************
      Purpose : 

      REVISIONS
      Ver      Date               Author                  Description 
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2026/01/28 09:30:07                         최초생성

    /**************************************************************************************************************************/


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR2(200);            -- ERROR Message
    USER_EXCEPTION EXCEPTION;

    v_APRV_STATS        VARCHAR2(20);
    v_APRV_STATS_NM     VARCHAR2(50);

BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 필수입력 필드  Check  ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_SIT_CD IS NULL)  THEN
        ERR_MSG := '현장코드는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_PLN_YM IS NULL)  THEN
        ERR_MSG := '계획년월는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_PLN_DGR IS NULL)  THEN
        ERR_MSG := '차수구분코드(QS005) 1 1차,2 2차는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_CO_DIV_CD IS NULL)  THEN
        ERR_MSG := '회사구분코드는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_EMPE_NO IS NULL)  THEN
        ERR_MSG := '사원번호는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    ---------------------------------------------------------------------
    -- 결재상태 체크
    SELECT MAX(T2.APRV_STATS)
         , MAX(T3.CD_NM )
      INTO v_APRV_STATS
         , v_APRV_STATS_NM
      FROM TQHA_RISK_DGR        T1
      LEFT JOIN TQHA_APRV       T2 ON T1.SIT_CD     = T2.SIT_CD
                                  AND T1.APRV_NO    = T2.APRV_NO
      LEFT JOIN TCOA_COMCODE    T3 ON T2.APRV_STATS = T3.COM_CD 
                                  AND T3.HRNK_CD    = 'QS031'
     WHERE T1.SIT_CD    = p_SIT_CD
       AND T1.PLN_YM    = p_PLN_YM
       AND T1.PLN_DGR   = p_PLN_DGR
    ;

    IF v_APRV_STATS IN ('2', '4') THEN
        ERR_MSG := '결재상태 [' || v_APRV_STATS_NM || ']인 데이터는 수정 불가합니다.';
        RAISE USER_EXCEPTION;
    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Process 선행조건 Check ]
    ---------------------------------------------------------------------------------------------------------------------------



    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Business Process ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_PRTR_YN = '0') THEN

        DELETE FROM TQHA_ASSLOG_CIRC
         WHERE SIT_CD    = p_SIT_CD
           AND PLN_YM    = p_PLN_YM
           AND PLN_DGR   = p_PLN_DGR
           AND CO_DIV_CD = p_CO_DIV_CD
           AND EMPE_NO   = p_EMPE_NO
       ;

    -----------------------------------------------------------------------------
    ELSIF (p_PRTR_YN = '1') THEN

        MERGE 
          INTO TQHA_ASSLOG_CIRC T
         USING DUAL 
        ON (
                T.SIT_CD    = p_SIT_CD     
            AND T.PLN_YM    = p_PLN_YM     
            AND T.PLN_DGR   = p_PLN_DGR    
            AND T.CO_DIV_CD = p_CO_DIV_CD  
            AND T.EMPE_NO   = p_EMPE_NO
        )
        WHEN MATCHED THEN
            UPDATE 
               SET T.PRTR_YN    = p_PRTR_YN
                 , T.UPD_ID     = p_WRK_ID
                 , T.UPD_DTM    = SYSDATE
                 , T.UPD_IP     = p_WRK_IP
        WHEN NOT MATCHED THEN
            INSERT 
                 ( SIT_CD                  --현장코드
                 , PLN_YM                  --계획년월
                 , PLN_DGR                 --차수구분코드(QS005) 1 1차,2 2차
                 , CO_DIV_CD               --회사구분코드
                 , EMPE_NO                 --사원번호
                 , PRTR_YN                 --참석여부
                 , IPT_ID                  --입력ID
                 , IPT_DTM                 --입력일시
                 , IPT_IP                  --입력IP
                 , UPD_ID                  --수정ID
                 , UPD_DTM                 --수정일시
                 , UPD_IP                  --수정IP
                 ) 
            VALUES 
                 ( p_SIT_CD                --현장코드
                 , p_PLN_YM                --계획년월
                 , p_PLN_DGR               --차수구분코드(QS005) 1 1차,2 2차
                 , p_CO_DIV_CD             --회사구분코드
                 , p_EMPE_NO               --사원번호
                 , '1'                     --참석여부
                 , p_WRK_ID                --입력ID 
                 , SYSDATE()               --입력일시
                 , p_WRK_IP                --입력IP
                 , p_WRK_ID                --수정ID
                 , SYSDATE()               --수정일시
                 , p_WRK_IP                --수정IP
                 )
            ;

    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 5. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN 
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);

END PQHA_ASSLOG_CIRC_S;
/

-- PQHA_BON_ORG_S (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_BON_ORG_S" (
    p_WRK_TP                VARCHAR2 :='U'                                      -- UPDATE FLAG( I: ISNERT, U:UPDATE, D:DELTE)
,   p_WRK_ID                VARCHAR2                                            -- 사용자 ID 
,   p_WRK_IP                VARCHAR2                                            -- 사용자 IP 
,   p_SIT_CD                TQHA_BON_ORG.SIT_CD                 %TYPE           -- 현장코드
,   p_RLV_YM                TQHA_BON_ORG.RLV_YM                 %TYPE           -- 해당년월
,   p_APRS_RNK              TQHA_BON_ORG.APRS_RNK               %TYPE           -- 시공능력평가순위
,   p_ORG_NM                TQHA_BON_ORG.ORG_NM                 %TYPE           -- 조직명
,   p_ORG_DTY               TQHA_BON_ORG.ORG_DTY                %TYPE           -- 직책
,   p_ORG_PCNT              TQHA_BON_ORG.ORG_PCNT               %TYPE           -- 인원수
,   p_SAFT_APRP_TAMT        TQHA_BON_ORG.SAFT_APRP_TAMT         %TYPE           -- 안전보건관리비계상총액
,   p_SAFT_PLAN_TAMT        TQHA_BON_ORG.SAFT_PLAN_TAMT         %TYPE           -- 본사임금 등 계상액(계획)
)
IS 
    /**************************************************************************************************************************
      Purpose : 조직 현황 저장

      REVISIONS
      Ver      Date               Author                  Description 
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2022/07/08 13:10:18                         최초생성 

    **************************************************************************************************************************/


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR2(200);            -- ERROR Message
    USER_EXCEPTION EXCEPTION;


BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 필수입력 필드  Check  ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_SIT_CD IS NULL)  THEN
        ERR_MSG := '현장코드는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_RLV_YM IS NULL)  THEN
        ERR_MSG := '해당년월는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Process 선행조건 Check ]
    ---------------------------------------------------------------------------------------------------------------------------



    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Business Process ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_WRK_TP ='D') THEN

        DELETE 
          FROM TQHA_BON_ORG
         WHERE SIT_CD   = p_SIT_CD          -- 현장코드
           AND RLV_YM   = p_RLV_YM          -- 해당년월
        ;


    ELSIF (p_WRK_TP ='U') THEN

        UPDATE TQHA_BON_ORG
           SET APRS_RNK             = p_APRS_RNK                --시공능력평가순위
             , ORG_NM               = p_ORG_NM                  --조직명
             , ORG_DTY              = p_ORG_DTY                 --직책
             , ORG_PCNT             = p_ORG_PCNT                --인원수
             , SAFT_APRP_TAMT       = p_SAFT_APRP_TAMT          --안전보건관리비계상총액
             , SAFT_PLAN_TAMT       = p_SAFT_PLAN_TAMT          --본사임금 등 계상액(계획)
             , UPD_ID               = p_WRK_ID                  --수정ID 
             , UPD_DTM              = SYSDATE()                 --수정일시
             , UPD_IP               = p_WRK_IP                  --수정IP
         WHERE SIT_CD               = p_SIT_CD                  --현장코드
           AND RLV_YM               = p_RLV_YM                  --해당년월
        ;

    ELSE 

        INSERT 
          INTO TQHA_BON_ORG
             ( SIT_CD                   -- 현장코드
             , RLV_YM                   -- 해당년월
             , APRS_RNK                 -- 시공능력평가순위
             , ORG_NM                   -- 조직명
             , ORG_DTY                  -- 직책
             , ORG_PCNT                 -- 인원수
             , SAFT_APRP_TAMT           -- 안전보건관리비계상총액
             , SAFT_PLAN_TAMT           -- 본사임금 등 계상액(계획)
             , IPT_ID                   -- 입력ID
             , IPT_DTM                  -- 입력일시
             , IPT_IP                   -- 입력IP
             , UPD_ID                   -- 수정ID
             , UPD_DTM                  -- 수정일시
             , UPD_IP                   -- 수정IP
             )
        VALUES 
             ( p_SIT_CD                 -- 현장코드
             , p_RLV_YM                 -- 해당년월
             , p_APRS_RNK               -- 시공능력평가순위
             , p_ORG_NM                 -- 조직명
             , p_ORG_DTY                -- 직책
             , p_ORG_PCNT               -- 인원수
             , p_SAFT_APRP_TAMT         -- 안전보건관리비계상총액
             , p_SAFT_PLAN_TAMT         -- 본사임금 등 계상액(계획)
             , p_WRK_ID                 -- 입력ID 
             , SYSDATE()                -- 입력일시
             , p_WRK_IP                 -- 입력IP
             , p_WRK_ID                 -- 수정ID
             , SYSDATE()                -- 수정일시
             , p_WRK_IP                 -- 수정IP
             )
        ;

    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 5. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN 
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);

END ;
/

-- PQHA_CKLST_ITM_S (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_CKLST_ITM_S" (
    p_WRK_TP                    VARCHAR2 :='U'                                          -- UPDATE FLAG( I: ISNERT, U:UPDATE, D:DELTE)
,   p_WRK_ID                    VARCHAR2                                                -- 사용자 ID
,   p_WRK_IP                    VARCHAR2                                                -- 사용자 IP
,   p_COM_CD                    TQHA_CKLST_ITM.COM_CD                   %TYPE           -- 공통코드
,   p_HO_CHK_DIV_CD             TQHA_CKLST_ITM.HO_CHK_DIV_CD            %TYPE           -- 본사점검탭분류
,   p_HO_CHK_DIV_CD2            TQHA_CKLST_ITM.HO_CHK_DIV_CD2           %TYPE           -- 본사점검구분코드
,   p_HO_CHK_ITM_CD             TQHA_CKLST_ITM.HO_CHK_ITM_CD            %TYPE           -- 본사점검항목코드
,   p_HO_CHK_ITM_NM             TQHA_CKLST_ITM.HO_CHK_ITM_NM            %TYPE           -- 본사점검항목명
,   p_HO_CHK_ITM_NM2            TQHA_CKLST_ITM.HO_CHK_ITM_NM            %TYPE           -- 본사점검항목명2
,   p_HO_CHK_ITM_RMKS           TQHA_CKLST_ITM.HO_CHK_ITM_RMKS          %TYPE           -- 본사점검항목비고
,   p_HO_CHK_ITM_USE_YN         TQHA_CKLST_ITM.HO_CHK_ITM_USE_YN        %TYPE           -- 본사점검항목사용여부
,   p_MAX_SCORE        			TQHA_CKLST_ITM.MAX_SCORE   			    %TYPE           -- 배점
)
IS
    /**************************************************************************************************************************
      Purpose :

      REVISIONS
      Ver      Date               Author                  Description
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2019/04/05 13:52:50                         최초생성

    /**************************************************************************************************************************/


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR(200);             -- ERROR Message
    USER_EXCEPTION EXCEPTION;

    p_UPD_ID        VARCHAR2(30);
    p_UPD_DTM       DATE;
    p_UPD_IP        VARCHAR2(30);
    p_IPT_ID        VARCHAR2(30);
    p_IPT_DTM       DATE;
    p_IPT_IP        VARCHAR2(30);

BEGIN
    IF p_WRK_TP = 'I' THEN
        p_IPT_ID  := p_WRK_ID;
        p_IPT_DTM := SYSDATE();
        p_IPT_IP  := p_WRK_IP;
        p_UPD_ID  := p_WRK_ID;
        p_UPD_DTM := SYSDATE();
        p_UPD_IP  := p_WRK_IP;
    ELSE
        p_UPD_ID  := p_WRK_ID;
        p_UPD_DTM := SYSDATE();
        p_UPD_IP  := p_WRK_IP;
    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 필수입력 필드  Check  ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_COM_CD IS NULL)  THEN
        ERR_MSG := '점검종류는 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_HO_CHK_DIV_CD2 IS NULL)  THEN
        ERR_MSG := '점검분류는 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_HO_CHK_DIV_CD IS NULL)  THEN
        ERR_MSG := '구분코드는 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_HO_CHK_ITM_CD IS NULL)  THEN
        ERR_MSG := '코드는 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_HO_CHK_ITM_NM IS NULL)  THEN
        ERR_MSG := '본사점검항목명은 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Process 선행조건 Check ]
    ---------------------------------------------------------------------------------------------------------------------------



    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Business Process ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_WRK_TP ='D') THEN

        DELETE
          FROM TQHA_CKLST_ITM
         WHERE COM_CD               = p_COM_CD                  -- 공통코드
           AND HO_CHK_DIV_CD        = p_HO_CHK_DIV_CD           -- 본사점검탭분류
           AND HO_CHK_DIV_CD2       = p_HO_CHK_DIV_CD2          -- 본사점검구분코드
           AND HO_CHK_ITM_CD        = p_HO_CHK_ITM_CD           -- 본사점검항목코드
        ;

    ELSIF (p_WRK_TP ='U') THEN

        UPDATE TQHA_CKLST_ITM
           SET HO_CHK_ITM_NM        = p_HO_CHK_ITM_NM           -- 본사점검항목명
             , HO_CHK_ITM_NM2       = p_HO_CHK_ITM_NM2          -- 본사점검항목명
             , HO_CHK_ITM_RMKS      = p_HO_CHK_ITM_RMKS         -- 본사점검항목비고
             , HO_CHK_ITM_USE_YN    = p_HO_CHK_ITM_USE_YN       -- 본사점검항목사용여부
             , MAX_SCORE   			= p_MAX_SCORE      		    -- 배점             
             , UPD_ID               = p_UPD_ID                  -- 최종수정ID
             , UPD_DTM              = p_UPD_DTM                 -- 최종수정일시
             , UPD_IP               = p_UPD_IP                  -- 최종수정IP
         WHERE COM_CD               = p_COM_CD                  -- 공통코드
           AND HO_CHK_DIV_CD        = p_HO_CHK_DIV_CD           -- 본사점검탭분류
           AND HO_CHK_DIV_CD2       = p_HO_CHK_DIV_CD2          -- 본사점검구분코드
           AND HO_CHK_ITM_CD        = p_HO_CHK_ITM_CD           -- 본사점검항목코드
        ;

    ELSE

        INSERT 
          INTO TQHA_CKLST_ITM
             ( COM_CD                   -- 공통코드
             , HO_CHK_DIV_CD            -- 본사점검탭분류
             , HO_CHK_DIV_CD2           -- 본사점검구분코드
             , HO_CHK_ITM_CD            -- 본사점검항목코드
             , HO_CHK_ITM_NM            -- 본사점검항목명
             , HO_CHK_ITM_NM2
             , HO_CHK_ITM_RMKS          -- 본사점검항목비고
             , HO_CHK_ITM_USE_YN        -- 본사점검항목사용여부
             , MAX_SCORE   		        -- 배점
             , IPT_ID                   -- 신규입력ID
             , IPT_DTM                  -- 신규입력일시
             , IPT_IP                   -- 신규입력IP
             , UPD_ID                   -- 최종수정ID
             , UPD_DTM                  -- 최종수정일시
             , UPD_IP                   -- 최종수정IP
             )
        VALUES 
             ( p_COM_CD                 -- 공통코드
             , p_HO_CHK_DIV_CD          -- 본사점검탭분류
             , p_HO_CHK_DIV_CD2         -- 본사점검구분코드
             , p_HO_CHK_ITM_CD          -- 본사점검항목코드
             , p_HO_CHK_ITM_NM          -- 본사점검항목명
             , p_HO_CHK_ITM_NM2
             , p_HO_CHK_ITM_RMKS        -- 본사점검항목비고
             , p_HO_CHK_ITM_USE_YN      -- 본사점검항목사용여부
             , p_MAX_SCORE      	    -- 배점
             , p_IPT_ID                 -- 신규입력ID
             , p_IPT_DTM                -- 신규입력일시
             , p_IPT_IP                 -- 신규입력IP
             , p_UPD_ID                 -- 최종수정ID
             , p_UPD_DTM                -- 최종수정일시
             , p_UPD_IP                 -- 최종수정IP
             )
        ;

    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 5. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
         WHEN OTHERS THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);

END;
/

-- PQHA_CKLST_Q (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_CKLST_Q" (
    p_WRK_TP            IN VARCHAR2 DEFAULT 'Q'         -- FLAG
,   p_COM_CD            IN VARCHAR2                     -- 공통코드
,   p_HO_CHK_DIV_CD2    IN VARCHAR2                     -- 본사점검구분코드
,   p_HO_CHK_DIV_CD     IN VARCHAR2                     -- 본사점검탭분류
,   RTN_CURSOR          OUT SYS_REFCURSOR
)
IS
    /**************************************************************************************************************************
      Purpose : [점검체크리스트지표 조회] PROCEDRE (QSE > 표준정보 > 점검체크리스트지표  )

      REVISIONS
      Ver      Date               Author                  Description
      -------  -----------------  ----------------------  ---------------------------------------------------------------------
      1.0      XXXX/XX/XX                                 최초생성

    **************************************************************************************************************************/

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE  NUMBER :=-20009; -- ERROR 코드
    ERR_MSG   VARCHAR(200);    -- ERROR Message
    USER_EXCEPTION EXCEPTION;

BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 수행전 Check Logic ]
    ---------------------------------------------------------------------------------------------------------------------------

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Logic 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------

    IF p_WRK_TP = 'Q' THEN

        OPEN RTN_CURSOR FOR
        SELECT AA.COM_CD                       -- 공통코드
             , AA.HO_CHK_DIV_CD2               -- 본사점검탭분류
             , AA.HO_CHK_DIV_CD                -- 본사점검구분코드
             , AA.HO_CHK_DIV_NM                -- 본사점검구분명
             , AA.HO_CHK_RMKS                  -- 본사점검비고
             , AA.HO_CHK_DIV_USE_YN            -- 본사점검구분사용여부
             , (
                SELECT COUNT(1)
                  FROM TQHA_CKLST_ITM
                 WHERE COM_CD           = AA.COM_CD
                   AND HO_CHK_DIV_CD2   = AA.HO_CHK_DIV_CD2
                   AND HO_CHK_DIV_CD    = AA.HO_CHK_DIV_CD
               ) AS DTLCOUNT                    -- 점검항목갯수
          FROM TQHA_CKLST AA
         WHERE AA.COM_CD            = p_COM_CD
           AND AA.HO_CHK_DIV_CD2    = p_HO_CHK_DIV_CD2
         ORDER BY AA.HO_CHK_DIV_CD
        ;

    ---------------------------------------------------------------------------------------
    ELSIF p_WRK_TP = 'Q2' THEN

        OPEN RTN_CURSOR FOR
        SELECT COM_CD                -- 공통코드
             , HO_CHK_DIV_CD         -- 본사점검탭분류
             , HO_CHK_DIV_CD2        -- 본사점검구분코드
             , HO_CHK_ITM_CD         -- 본사점검항목코드
             , HO_CHK_ITM_NM         -- 본사점검항목명
             , HO_CHK_ITM_NM2         -- 본사점검항목명
             , HO_CHK_ITM_RMKS       -- 본사점검항목비고
             , HO_CHK_ITM_USE_YN     -- 본사점검항목사용여부
             , MAX_SCORE
          FROM TQHA_CKLST_ITM
         WHERE COM_CD           = p_COM_CD
           AND HO_CHK_DIV_CD2   = p_HO_CHK_DIV_CD2
           AND HO_CHK_DIV_CD    = p_HO_CHK_DIV_CD
         ORDER BY HO_CHK_ITM_CD
        ;

    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
         WHEN OTHERS THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);

END PQHA_CKLST_Q;
/

-- PQHA_CKLS_S (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_CKLS_S" (
    p_WRK_TP                VARCHAR2 :='U'                                      -- UPDATE FLAG( I: ISNERT, U:UPDATE, D:DELTE)
,   p_WRK_ID                VARCHAR2                                            -- 사용자 ID
,   p_WRK_IP                VARCHAR2                                            -- 사용자 IP
,   p_COM_CD                TQHA_CKLST.COM_CD                   %TYPE           -- 공통코드
,   p_HO_CHK_DIV_CD2        TQHA_CKLST.HO_CHK_DIV_CD2           %TYPE           -- 본사점검탭분류
,   p_HO_CHK_DIV_CD         TQHA_CKLST.HO_CHK_DIV_CD            %TYPE           -- 본사점검구분코드
,   p_HO_CHK_DIV_NM         TQHA_CKLST.HO_CHK_DIV_NM            %TYPE           -- 본사점검구분명
,   p_HO_CHK_RMKS           TQHA_CKLST.HO_CHK_RMKS              %TYPE           -- 본사점검비고
,   p_HO_CHK_DIV_USE_YN     TQHA_CKLST.HO_CHK_DIV_USE_YN        %TYPE           -- 본사점검구분사용여부
)
IS
    /**************************************************************************************************************************
      Purpose :

      REVISIONS
      Ver      Date               Author                  Description
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2019/04/05 11:21:11                         최초생성

    /**************************************************************************************************************************/


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR(200);             -- ERROR Message
    USER_EXCEPTION EXCEPTION;

    p_UPD_ID        VARCHAR2(30);
    p_UPD_DTM       DATE;
    p_UPD_IP        VARCHAR2(30);
    p_IPT_ID        VARCHAR2(30);
    p_IPT_DTM       DATE;
    p_IPT_IP        VARCHAR2(30);

BEGIN
    IF p_WRK_TP = 'I' THEN
        p_IPT_ID  := p_WRK_ID;
        p_IPT_DTM := SYSDATE();
        p_IPT_IP  := p_WRK_IP;
        p_UPD_ID  := p_WRK_ID;
        p_UPD_DTM := SYSDATE();
        p_UPD_IP  := p_WRK_IP;
    ELSE
        p_UPD_ID  := p_WRK_ID;
        p_UPD_DTM := SYSDATE();
        p_UPD_IP  := p_WRK_IP;
    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 필수입력 필드  Check  ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_COM_CD IS NULL)  THEN
        ERR_MSG := '점검종류는 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_HO_CHK_DIV_CD2 IS NULL)  THEN
        ERR_MSG := '점검분류는 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_HO_CHK_DIV_CD IS NULL)  THEN
        ERR_MSG := '코드는 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_HO_CHK_DIV_NM IS NULL)  THEN
        ERR_MSG := '구분명은 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Process 선행조건 Check ]
    ---------------------------------------------------------------------------------------------------------------------------



    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Business Process ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_WRK_TP ='D') THEN

        DELETE
          FROM TQHA_CKLST
         WHERE COM_CD = p_COM_CD          --공통코드
           AND HO_CHK_DIV_CD2       = p_HO_CHK_DIV_CD2      -- 본사점검탭분류
           AND HO_CHK_DIV_CD        = p_HO_CHK_DIV_CD       -- 본사점검구분코드
        ;

    ELSIF (p_WRK_TP ='U') THEN

        UPDATE TQHA_CKLST
           SET HO_CHK_DIV_NM        = p_HO_CHK_DIV_NM           -- 본사점검구분명
             , HO_CHK_RMKS          = p_HO_CHK_RMKS             -- 본사점검비고
             , HO_CHK_DIV_USE_YN    = p_HO_CHK_DIV_USE_YN       -- 본사점검구분사용여부
             , UPD_ID               = p_UPD_ID                  -- 최종수정ID
             , UPD_DTM              = p_UPD_DTM                 -- 최종수정일시
             , UPD_IP               = p_UPD_IP                  -- 최종수정IP
         WHERE COM_CD               = p_COM_CD                  -- 공통코드
           AND HO_CHK_DIV_CD2       = p_HO_CHK_DIV_CD2          -- 본사점검탭분류
           AND HO_CHK_DIV_CD        = p_HO_CHK_DIV_CD           -- 본사점검구분코드
        ;

    ELSE
        INSERT 
          INTO TQHA_CKLST
             ( COM_CD                   -- 공통코드
             , HO_CHK_DIV_CD2           -- 본사점검탭분류
             , HO_CHK_DIV_CD            -- 본사점검구분코드
             , HO_CHK_DIV_NM            -- 본사점검구분명
             , HO_CHK_RMKS              -- 본사점검비고
             , HO_CHK_DIV_USE_YN        -- 본사점검구분사용여부
             , IPT_ID                   -- 신규입력ID
             , IPT_DTM                  -- 신규입력일시
             , IPT_IP                   -- 신규입력IP
             , UPD_ID                   -- 최종수정ID
             , UPD_DTM                  -- 최종수정일시
             , UPD_IP                   -- 최종수정IP
             )
        VALUES 
             ( p_COM_CD                 -- 공통코드
             , p_HO_CHK_DIV_CD2         -- 본사점검탭분류
             , p_HO_CHK_DIV_CD          -- 본사점검구분코드
             , p_HO_CHK_DIV_NM          -- 본사점검구분명
             , p_HO_CHK_RMKS            -- 본사점검비고
             , p_HO_CHK_DIV_USE_YN      -- 본사점검구분사용여부
             , p_IPT_ID                 -- 신규입력ID
             , p_IPT_DTM                -- 신규입력일시
             , p_IPT_IP                 -- 신규입력IP
             , p_UPD_ID                 -- 최종수정ID
             , p_UPD_DTM                -- 최종수정일시
             , p_UPD_IP                 -- 최종수정IP
             )
        ;

    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 5. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
         WHEN OTHERS THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);
END;
/

-- PQHA_CTPUNT_CHKITM_S (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_CTPUNT_CHKITM_S" (
    p_WRK_TP                VARCHAR2 :='U'                                          -- UPDATE FLAG( I: ISNERT, U:UPDATE, D:DELTE)
,   p_WRK_ID                VARCHAR2                                                -- 사용자 ID
,   p_WRK_IP                VARCHAR2                                                -- 사용자 IP
,   p_CTP_CD                TQHA_CTPUNT_CHKITM.CTP_CD               %TYPE           -- 공종코드
,   p_UNT_CD                TQHA_CTPUNT_CHKITM.UNT_CD               %TYPE           -- 단위코드
,   p_CHK_ITM_CD            TQHA_CTPUNT_CHKITM.CHK_ITM_CD           %TYPE           -- 점검항목코드
,   p_CHK_ITM_NM            TQHA_CTPUNT_CHKITM.CHK_ITM_NM           %TYPE           -- 점검항목명
,   p_DISS_SHP              TQHA_CTPUNT_CHKITM.DISS_SHP             %TYPE           -- 재해형태(QS036)
,   p_RISK_FREQ             TQHA_CTPUNT_CHKITM.RISK_FREQ            %TYPE           -- 빈도레벨(QS003)
,   p_RISK_APRV             TQHA_CTPUNT_CHKITM.RISK_APRV            %TYPE           -- 강도레벨(QS004)
,   p_RISK_CRIT             TQHA_CTPUNT_CHKITM.RISK_CRIT            %TYPE           -- 위험성(QS063)
,   p_RISK_GRD              TQHA_CTPUNT_CHKITM.RISK_GRD             %TYPE           -- 위험등급(QS024)
,   p_PRRT_REG              TQHA_CTPUNT_CHKITM.PRRT_REG             %TYPE           -- 중점등록(QS002)
,   p_IMPRV_CPLN            TQHA_CTPUNT_CHKITM.IMPRV_CPLN           %TYPE           -- 개선대책
,   p_USR_DEFN_YN           TQHA_CTPUNT_CHKITM.USR_DEFN_YN          %TYPE           -- 표준 0, 사용자정의 1
,   p_CUST_CD               TQHA_CTPUNT_CHKITM.CUST_CD              %TYPE           -- 업체코드
,   p_SIT_CD                TQHA_CTPUNT_CHKITM.SIT_CD               %TYPE           -- 현장코드
,   p_USE_YN                TQHA_CTPUNT_CHKITM.USE_YN               %TYPE           -- 사용여부
) 
IS 
    /**************************************************************************************************************************
      Purpose : 

      REVISIONS
      Ver      Date               Author                  Description
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2021/10/21 14:21:20                         최초생성

    **************************************************************************************************************************/


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR2(200);            -- ERROR Message
    USER_EXCEPTION EXCEPTION;

    v_CHK_ITM_CD TQHA_CTPUNT_CHKITM.CHK_ITM_CD%TYPE ;           -- 점검코드 변수 선언
    v_cnt   INTEGER := 0;                                       -- 점검항목코드 사용여부 확인
    v_cnt1  INTEGER := 0;                                       -- 점검항목코드 사용여부 확인
    v_cnt2  INTEGER := 0;                                       -- 점검항목코드 사용여부 확인
    v_cnt3  INTEGER := 0;                                       -- 점검항목코드 사용여부 확인

BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 필수입력 필드  Check  ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_CTP_CD IS NULL)  THEN
        ERR_MSG := '공종코드는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_UNT_CD IS NULL)  THEN
        ERR_MSG := '단위코드는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_CHK_ITM_CD IS NULL AND p_WRK_TP <> 'I' )  THEN
        ERR_MSG := '점검항목코드는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_USR_DEFN_YN IS NULL)  THEN
        ERR_MSG := '표준 0, 사용자정의 1는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    --  점검항목 사용 여부
    --  점검항목 코드 사용 여부 확인
    IF p_WRK_TP = 'D' THEN
        -- 위험성평가 세부계획(최초/연간)
        SELECT nvl(COUNT(CHK_ITM_CD),0)
          INTO v_cnt
          FROM TQHA_RISKPLAN_D
         WHERE CTP_CD       = p_CTP_CD
           AND UNT_CD       = p_UNT_CD
           AND CHK_ITM_CD   = p_CHK_ITM_CD
        ;

        IF v_cnt < 1  THEN
            -- 위험성평가 점검내용(수시)
            SELECT nvl(COUNT(CHK_ITM_CD),0)
              INTO v_cnt1
              FROM TQHA_RISK_CHK
             WHERE CTP_CD       = p_CTP_CD
               AND UNT_CD       = p_UNT_CD
               AND CHK_ITM_CD   = p_CHK_ITM_CD
            ;
        END IF;
--
--        IF v_cnt1 < 1  THEN
--            -- 위험성평가 취수 중점점검(수시)
--            SELECT nvl(COUNT(CHK_ITM_CD),0)
--              INTO v_cnt2
--              FROM TQSA_RISK_PRRTCHK
--             WHERE CTP_CD       = p_CTP_CD
--               AND UNT_CD       = p_UNT_CD
--               AND CHK_ITM_CD   = p_CHK_ITM_CD
--            ;
--        END IF ;

        IF v_cnt2 < 1  THEN
            -- 위험성평가 일일 안전점검목록(수시)
            SELECT nvl(COUNT(CHK_ITM_CD),0)
              INTO v_cnt3
              FROM TQHA_DAYSAFE_CHKLST
             WHERE CTP_CD       = p_CTP_CD
               AND UNT_CD       = p_UNT_CD
               AND CHK_ITM_CD   = p_CHK_ITM_CD
            ;

        END IF ;

        -- 단위작업 코드 Validation
        IF ( v_cnt +  v_cnt1 + v_cnt2 + v_cnt3 ) > 0 THEN
            ERR_MSG := '점검항목 "' || p_CHK_ITM_NM || '" 은(는) 사용중입니다.. 사용중인 점검항목은 삭제할 수 없습니다. ';
            RAISE USER_EXCEPTION;
        END IF;

    END IF;


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Process 선행조건 Check ]
    ---------------------------------------------------------------------------------------------------------------------------



    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Business Process ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_WRK_TP ='D') THEN

        DELETE
          FROM TQHA_CTPUNT_CHKITM
         WHERE CTP_CD       = p_CTP_CD          -- 공종코드
           AND UNT_CD       = p_UNT_CD          -- 단위코드
           AND CHK_ITM_CD   = p_CHK_ITM_CD      -- 점검항목코드
        ;

    --------------------------------------------------------------------------------------
    ELSIF (p_WRK_TP ='U') THEN

        UPDATE TQHA_CTPUNT_CHKITM
           SET CHK_ITM_NM           = p_CHK_ITM_NM          -- 점검항목명
             , DISS_SHP             = p_DISS_SHP            -- 재해형태(QS036)
             , RISK_FREQ            = p_RISK_FREQ           -- 빈도레벨(QS003)
             , RISK_APRV            = p_RISK_APRV           -- 강도레벨(QS004)
             , RISK_CRIT            = p_RISK_CRIT           -- 위험성(QS063)
             , RISK_GRD             = p_RISK_GRD            -- 위험등급(QS024)
             , PRRT_REG             = p_PRRT_REG            -- 중점등록(QS002)
             , IMPRV_CPLN           = p_IMPRV_CPLN          -- 개선대책
             , USR_DEFN_YN          = p_USR_DEFN_YN         -- 표준 0, 사용자정의 1
             , CUST_CD              = p_CUST_CD             -- 업체코드
             , SIT_CD               = p_SIT_CD              -- 현장코드
             , USE_YN               = p_USE_YN              -- 사용여부
             , UPD_ID               = p_WRK_ID              -- 수정ID
             , UPD_DTM              = SYSDATE()             -- 수정일시
             , UPD_IP               = p_WRK_IP              -- 수정IP
         WHERE CTP_CD               = p_CTP_CD              -- 공종코드
           AND UNT_CD               = p_UNT_CD              -- 단위코드
           AND CHK_ITM_CD           = p_CHK_ITM_CD          -- 점검항목코드
        ;

    --------------------------------------------------------------------------------------
    ELSE
        -- 점검항목코드 MAX부여
        SELECT LPAD(NVL(MAX(SUBSTR(CHK_ITM_CD, 1, 5)), 0) + 1, 5,'0')
          INTO v_CHK_ITM_CD
          FROM TQHA_CTPUNT_CHKITM
         WHERE CTP_CD   = p_CTP_CD          -- 공종코드
           AND UNT_CD   = p_UNT_CD          -- 단위작업코드
        ;
        --
        INSERT 
          INTO TQHA_CTPUNT_CHKITM
             ( CTP_CD                   -- 공종코드
             , UNT_CD                   -- 단위코드
             , CHK_ITM_CD               -- 점검항목코드
             , CHK_ITM_NM               -- 점검항목명
             , DISS_SHP                 -- 재해형태(QS036)
             , RISK_FREQ                -- 빈도레벨(QS003)
             , RISK_APRV                -- 강도레벨(QS004)
             , RISK_CRIT                -- 위험성(QS063)
             , RISK_GRD                 -- 위험등급(QS024)
             , PRRT_REG                 -- 중점등록(QS002)
             , IMPRV_CPLN               -- 개선대책
             , USR_DEFN_YN              -- 표준 0, 사용자정의 1
             , CUST_CD                  -- 업체코드
             , SIT_CD                   -- 현장코드
             , USE_YN                   -- 사용여부
             , IPT_ID                   -- 입력ID
             , IPT_DTM                  -- 입력일시
             , IPT_IP                   -- 입력IP
             , UPD_ID                   -- 수정ID
             , UPD_DTM                  -- 수정일시
             , UPD_IP                   -- 수정IP
             )
        VALUES 
             ( p_CTP_CD                 -- 공종코드
             , p_UNT_CD                 -- 단위코드
             , v_CHK_ITM_CD             -- 점검항목코드
             , p_CHK_ITM_NM             -- 점검항목명
             , p_DISS_SHP               -- 재해형태(QS036)
             , p_RISK_FREQ              -- 빈도레벨(QS003)
             , p_RISK_APRV              -- 강도레벨(QS004)
             , p_RISK_CRIT              -- 위험성(QS063)
             , p_RISK_GRD               -- 위험등급(QS024)
             , p_PRRT_REG               -- 중점등록(QS002)
             , p_IMPRV_CPLN             -- 개선대책
             , p_USR_DEFN_YN            -- 표준 0, 사용자정의 1
             , p_CUST_CD                -- 업체코드
             , p_SIT_CD                 -- 현장코드
             , p_USE_YN                 -- 사용여부
             , p_WRK_ID                 -- 입력ID
             , SYSDATE()                -- 입력일시
             , p_WRK_IP                 -- 입력IP
             , p_WRK_ID                 -- 수정ID
             , SYSDATE()                -- 수정일시
             , p_WRK_IP                 -- 수정IP
             )
        ;

    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 5. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);
END ;
/

-- PQHA_CTPUNT_S (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_CTPUNT_S" (
    p_WRK_TP        VARCHAR2 :='U'                      -- UPDATE FLAG( I: ISNERT, U:UPDATE, D:DELTE)
,   p_WRK_ID        VARCHAR2                            -- 사용자 ID 
,   p_WRK_IP        VARCHAR2                            -- 사용자 IP 
,   p_CTP_CD        TQHA_CTPUNT.CTP_CD      %TYPE       -- 공종코드
,   p_UNT_CD        TQHA_CTPUNT.UNT_CD      %TYPE       -- 단위코드
,   p_UNT_NM        TQHA_CTPUNT.UNT_NM      %TYPE       -- 단위명칭
,   p_USE_YN        TQHA_CTPUNT.USE_YN      %TYPE       -- 사용여부
)
IS 
    /**************************************************************************************************************************
      Purpose : 안전 공종코드 별 단위코드 등록
 
      REVISIONS
      Ver      Date               Author                  Description 
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2021/10/21 14:13:22                         최초생성

    **************************************************************************************************************************/

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR2(200);            -- ERROR Message
    USER_EXCEPTION EXCEPTION;

     v_UNT_CD       TQHA_CTPUNT.UNT_CD  %TYPE ;             -- 단우작업코드 변수 선언
     v_cnt          INTEGER;                                -- 하위 점검항목  코드 존재 여부
BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 필수입력 필드  Check  ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_CTP_CD IS NULL)  THEN
        ERR_MSG := '공종코드는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_UNT_CD IS NULL AND p_WRK_TP <> 'I')  THEN
        ERR_MSG := '단위코드는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

       --  하위 점검항목코드 존재 여부 확인
    IF p_WRK_TP = 'D' THEN

        SELECT nvl(COUNT(UNT_CD),0) 
          INTO v_cnt
          FROM TQHA_CTPUNT_CHKITM
         WHERE CTP_CD   = p_CTP_CD
           AND UNT_CD   = p_UNT_CD
        ;

         -- 단위작업 코드 Validation
        IF v_cnt > 0 THEN
           ERR_MSG := '단위작업 코드 "' || p_UNT_NM || '" 은(는) 하위 점검항목이 존재합니다. 하위 점검항목을 전부 삭제해야 단위작업 코드를 삭제할 수 있습니다. ';
           RAISE USER_EXCEPTION;
        END IF;

    END IF;  
    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Process 선행조건 Check ]
    ---------------------------------------------------------------------------------------------------------------------------



    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Business Process ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_WRK_TP ='D') THEN

        DELETE 
          FROM TQHA_CTPUNT
         WHERE CTP_CD   = p_CTP_CD      -- 공종코드
           AND UNT_CD   = p_UNT_CD      -- 단위코드
        ;

    ELSIF (p_WRK_TP ='U') THEN

        UPDATE TQHA_CTPUNT
           SET UNT_NM           = p_UNT_NM          -- 단위명칭
             , USE_YN           = p_USE_YN          -- 사용여부
             , UPD_ID           = p_WRK_ID          -- 수정ID 
             , UPD_DTM          = SYSDATE()         -- 수정일시
             , UPD_IP           = p_WRK_IP          -- 수정IP
         WHERE CTP_CD           = p_CTP_CD          -- 공종코드
           AND UNT_CD           = p_UNT_CD          -- 단위코드
        ;

    ELSE

        -- 단위코드 MAX부여
        SELECT LPAD(NVL(MAX(SUBSTR(UNT_CD, 1, 4)), 0) + 1, 4,'0')
          INTO v_UNT_CD
          FROM TQHA_CTPUNT 
         WHERE CTP_CD = p_CTP_CD 
        ; 
        --
        INSERT 
          INTO TQHA_CTPUNT
             ( CTP_CD               -- 공종코드
             , UNT_CD               -- 단위코드
             , UNT_NM               -- 단위명칭
             , USE_YN               -- 사용여부
             , IPT_ID               -- 입력ID
             , IPT_DTM              -- 입력일시
             , IPT_IP               -- 입력IP
             , UPD_ID               -- 수정ID
             , UPD_DTM              -- 수정일시
             , UPD_IP               -- 수정IP
             )
        VALUES 
             ( p_CTP_CD             -- 공종코드
             , v_UNT_CD             -- 단위코드
             , p_UNT_NM             -- 단위명칭
             , p_USE_YN             -- 사용여부 
             , p_WRK_ID             -- 입력ID 
             , SYSDATE()            -- 입력일시
             , p_WRK_IP             -- 입력IP
             , p_WRK_ID             -- 수정ID
             , SYSDATE()            -- 수정일시
             , p_WRK_IP             -- 수정IP
             )
        ;

    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 5. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN 
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);
END ;
/

-- PQHA_CTP_PSN_Q (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_CTP_PSN_Q" (
    p_WRK_TP              IN VARCHAR2 DEFAULT 'Q'           -- FLAG(Q)
,   p_SIT_CD              IN VARCHAR2                       -- 현장 
,   p_CTP_DIV             IN VARCHAR2                       -- 공종코드
,   RTN_CURSOR            OUT SYS_REFCURSOR
) 
IS 
    /**************************************************************************************************************************
    COPYRIGHT:    HUMAN PLUS         
    PROCEDURE:    [PQHA_CTP_PSN_Q] PROCEDRE 
    설명     :    [QSE > 안전관리 > 위험성평가(최초/연간) > 현장담당자등록 목록  조회] 프로시저

     개정일자                      변경내용요약                                 관련근거
    --------------------------------------------------------------------------------------------------------------------------- 
     2023-11-28   HUMANPLUS        신규
    ***************************************************************************************************************************/


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009 ; --ERROR 코드
    ERR_MSG        VARCHAR2(200)   ; --ERROR Message
    USER_EXCEPTION EXCEPTION       ;

BEGIN
    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 수행전 Check Logic ]
    ---------------------------------------------------------------------------------------------------------------------------


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Logic 처리
    ---------------------------------------------------------------------------------------------------------------------------

    -- get_RiskPlanChrList 현장별 담당자 지정
    IF p_WRK_TP = 'Q1' THEN

        OPEN RTN_CURSOR FOR

        SELECT B.SIT_CD         -- 현장코드
             , A.CTP_DIV        -- 공종구분
             , A.CTP_DIV_NM     -- 공종구분명칭
             , B.CTP_CHR_PSN    -- 공종담당자ID
             , C.USR_NM AS CTP_CHR_PSN_NM -- 공종담당자명
          FROM (SELECT CTP_DIV
                     , ( SELECT CD_NM FROM TCOA_COMCODE WHERE COM_CD = CTP_DIV AND HRNK_CD = 'QS035') AS CTP_DIV_NM  -- 공종구분명
                  FROM TQHA_CTP
                 GROUP BY CTP_DIV 
                 ORDER BY CTP_DIV ) A
             , TQHA_CTP_PSN B
             , TCOZ_USR_INFO C
         WHERE A.CTP_DIV        = B.CTP_DIV(+)
           AND B.CTP_CHR_PSN    = C.USR_ID(+)
           AND B.SIT_CD(+)      = p_SIT_CD
         ORDER BY A.CTP_DIV
        ;

    ---------------------------------------------------------------------------
    -- get_RiskPlanChrDtlList 공종
    ELSIF p_WRK_TP = 'Q2' THEN

        OPEN RTN_CURSOR FOR

        SELECT TC.CTP_CD        AS CTP_CD        -- 공종코드
             , TC.CTP_NM        AS CTP_NM        -- 공종명칭
             , TC.CTP_DIV       AS CTP_DIV       -- 공종별 구분코드(QS035)
             , TA.CD_NM         AS CTP_DIV_NM    -- 공종구분명
             , TC.USE_YN        AS USE_YN        -- 공종 사용유무
          FROM TQHA_CTP TC
          LEFT JOIN TCOA_COMCODE TA ON TA.HRNK_CD = 'QS035'
                                   AND TA.COM_CD  = TC.CTP_DIV
         WHERE CTP_DIV = p_CTP_DIV
         ORDER BY CTP_CD
        ;

    END IF; -- 'Q' END


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN 
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);

END ;
/

-- PQHA_CTP_PSN_S (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_CTP_PSN_S" (
    p_WRK_TP            VARCHAR2 :='U'                          -- UPDATE FLAG( I: ISNERT, U:UPDATE, D:DELTE)
,   p_WRK_ID            VARCHAR2                                -- 사용자 ID 
,   p_WRK_IP            VARCHAR2                                -- 사용자 IP 
,   p_SIT_CD            TQHA_CTP_PSN.SIT_CD         %TYPE       -- 현장코드
,   p_CTP_DIV           TQHA_CTP_PSN.CTP_DIV        %TYPE       -- 공종별 구분코드(QS035) 01건축 02토목
,   p_CTP_CHR_PSN       TQHA_CTP_PSN.CTP_CHR_PSN    %TYPE       -- 공종담당자
)
IS 
    /**************************************************************************************************************************
      Purpose : 

      REVISIONS
      Ver      Date               Author                  Description 
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2021/11/30 12:53:23                         최초생성

    **************************************************************************************************************************/


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR2(200);            -- ERROR Message
    USER_EXCEPTION EXCEPTION;


BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 필수입력 필드  Check  ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_SIT_CD IS NULL)  THEN
        ERR_MSG := '현장코드는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_CTP_DIV IS NULL)  THEN
        ERR_MSG := '공종별 구분코드(QS035) 01건축 02토목는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Process 선행조건 Check ]
    ---------------------------------------------------------------------------------------------------------------------------



    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Business Process ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_WRK_TP ='D') THEN

        DELETE 
          FROM TQHA_CTP_PSN
         WHERE SIT_CD   = p_SIT_CD      -- 현장코드
           AND CTP_DIV  = p_CTP_DIV     -- 공종별 구분코드(QS035) 01건축 02토목
        ;

    -------------------------------------------------------------------------------
    -- 
    ELSIF (p_WRK_TP ='U') THEN

        UPDATE TQHA_CTP_PSN
           SET CTP_CHR_PSN      = p_CTP_CHR_PSN     --공종담당자
             , UPD_ID           = p_WRK_ID          --수정ID 
             , UPD_DTM          = SYSDATE()         --수정일시
             , UPD_IP           = p_WRK_IP          --수정IP
         WHERE SIT_CD           = p_SIT_CD          --현장코드
           AND CTP_DIV          = p_CTP_DIV         --공종별 구분코드(QS035) 01건축 02토목
        ;

    -------------------------------------------------------------------------------
    -- 
    ELSE 

        INSERT 
          INTO TQHA_CTP_PSN
             ( SIT_CD               -- 현장코드
             , CTP_DIV              -- 공종별 구분코드(QS035) 01건축 02토목
             , CTP_CHR_PSN          -- 공종담당자
             , IPT_ID               -- 입력ID
             , IPT_DTM              -- 입력일시
             , IPT_IP               -- 입력IP
             , UPD_ID               -- 수정ID
             , UPD_DTM              -- 수정일시
             , UPD_IP               -- 수정IP
             )
        VALUES 
             ( p_SIT_CD             -- 현장코드
             , p_CTP_DIV            -- 공종별 구분코드(QS035) 01건축 02토목
             , p_CTP_CHR_PSN        -- 공종담당자
             , p_WRK_ID             -- 입력ID 
             , SYSDATE()            -- 입력일시
             , p_WRK_IP             -- 입력IP
             , p_WRK_ID             -- 수정ID
             , SYSDATE()            -- 수정일시
             , p_WRK_IP             -- 수정IP
             )
        ;

    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 5. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN 
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);

END ;
/

-- PQHA_CTP_S (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_CTP_S" (
    p_WRK_TP        VARCHAR2 :='U'                          -- UPDATE FLAG( I: ISNERT, U:UPDATE, D:DELTE)
,   p_WRK_ID        VARCHAR2                                -- 사용자 ID
,   p_WRK_IP        VARCHAR2                                -- 사용자 IP
,   p_CTP_CD        TQHA_CTP.CTP_CD         %TYPE           -- 공종코드
,   p_CTP_NM        TQHA_CTP.CTP_NM         %TYPE           -- 공종명
,   p_CTP_DIV       TQHA_CTP.CTP_DIV        %TYPE           -- 공종별 구분코드(QS035) 01건축 02토목
,   p_USE_YN        TQHA_CTP.USE_YN         %TYPE           -- 사용여부
)
IS 
    /**************************************************************************************************************************
      Purpose : 안전/안전관리/기준정보/공종관리 공종관리 저장

      REVISIONS
      Ver      Date               Author                  Description
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2021/10/21 13:37:08                         최초생성

    **************************************************************************************************************************/

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR2(200);            -- ERROR Message
    USER_EXCEPTION EXCEPTION;

     v_CTP_CD TQHA_CTP.CTP_CD%TYPE ;             -- 공종코드 변수 선언
     v_cnt  INTEGER;                             -- 공종코드 하위 단위레벨 코드 존재 여부

BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 필수입력 필드  Check  ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_CTP_CD IS NULL AND p_WRK_TP <> 'I' )  THEN     -- 추가 일때 공종코드 필수 입력사항 안 물어보게
        ERR_MSG := '공종코드는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_CTP_NM IS NULL)  THEN
        ERR_MSG := '공종명는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    --  단위작업별 코드 존재 여부 확인
    IF p_WRK_TP = 'D' THEN

       SELECT nvl(COUNT(CTP_CD),0)
         INTO v_cnt
         FROM TQHA_CTPUNT
        WHERE CTP_CD = p_CTP_CD;

         -- 단위작업 코드 Validation
        IF v_cnt > 0 THEN
           ERR_MSG := '공종코드 "' || p_CTP_NM || '" 은(는) 하위 공종별 단위작업 항목이 존재합니다. 하위 공종별 단위작업을 전부 삭제해야 공종코드를 삭제할 수 있습니다. ';
           RAISE USER_EXCEPTION;
        END IF;
    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Process 선행조건 Check ]
    ---------------------------------------------------------------------------------------------------------------------------


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Business Process ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_WRK_TP ='D') THEN

        DELETE
          FROM TQHA_CTP
         WHERE CTP_CD = p_CTP_CD         --공종코드
        ;

    ELSIF (p_WRK_TP ='U') THEN

        UPDATE TQHA_CTP
           SET CTP_NM           = p_CTP_NM          -- 공종명
             , CTP_DIV          = p_CTP_DIV         -- 공종별 구분코드(QS035) 01건축 02토목
             , USE_YN           = p_USE_YN          -- 사용여부
             , UPD_ID           = p_WRK_ID          -- 수정ID
             , UPD_DTM          = SYSDATE()         -- 수정일시
             , UPD_IP           = p_WRK_IP          -- 수정IP
         WHERE CTP_CD           = p_CTP_CD          -- 공종코드
        ;

    ELSE
        -- 공종코드 MAX부여
        SELECT LPAD(NVL(MAX(SUBSTR(CTP_CD, 1, 3)), 0) + 1, 3,'0')
          INTO v_CTP_CD
          FROM TQHA_CTP
        ;
        --
        INSERT 
          INTO TQHA_CTP
             ( CTP_CD           -- 공종코드
             , CTP_NM           -- 공종명
             , CTP_DIV          -- 공종별 구분코드(QS035) 01건축 02토목
             , USE_YN           -- 사용여부
             , IPT_ID           -- 입력ID
             , IPT_DTM          -- 입력일시
             , IPT_IP           -- 입력IP
             , UPD_ID           -- 수정ID
             , UPD_DTM          -- 수정일시
             , UPD_IP           -- 수정IP
             )
        VALUES 
             ( v_CTP_CD         -- 공종코드
             , p_CTP_NM         -- 공종명
             , p_CTP_DIV        -- 공종별 구분코드(QS035) 01건축 02토목
             , p_USE_YN         -- 사용여부
             , p_WRK_ID         -- 입력ID
             , SYSDATE()        -- 입력일시
             , p_WRK_IP         -- 입력IP
             , p_WRK_ID         -- 수정ID
             , SYSDATE()        -- 수정일시
             , p_WRK_IP         -- 수정IP
             )
        ;

    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 5. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);

END ;
/

-- PQHA_DASHBOARD_CO_Q (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_DASHBOARD_CO_Q" (
    p_WRK_TP            IN VARCHAR2 DEFAULT 'Q'             -- FLAG(Q: 현장평가, Q1:본사평가)
,   p_SIT_CD            IN VARCHAR2                         -- 현장코드
,   p_CUST_CD           IN VARCHAR2                         -- 고객코드
,   p_VNDR_SEQ          IN VARCHAR2                         -- 업체순번
,   p_WRK_CORP          IN VARCHAR2                         -- 법인코드
,   p_SEARCH_DIV        IN VARCHAR2                         -- 검색구분
,   p_SEARCH_TEXT       IN VARCHAR2                         -- 검색단어
,   p_BLT_NO            IN VARCHAR2                         -- 게시번호
,   RTN_CURSOR       OUT SYS_REFCURSOR
)
IS

    /**************************************************************************************************************************
      Purpose : 안전 파트너 대시보드 

      REVISIONS
      Ver      Date               Author                  Description
      -------  -----------------  ----------------------  ---------------------------------------------------------------------
      1.0      2026/03/03                                 최초생성

    **************************************************************************************************************************/

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE  NUMBER :=-20009; -- ERROR 코드
    ERR_MSG   VARCHAR(200);    -- ERROR Message
    USER_EXCEPTION EXCEPTION;

BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 수행전 Check Logic ]
    ---------------------------------------------------------------------------------------------------------------------------

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Logic 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    -- 추가 위험발굴 작성
    IF p_WRK_TP = 'Q1' THEN

        OPEN RTN_CURSOR FOR
        SELECT A.SIT_CD                                                                -- 현장코드
              , (SELECT CNST_NM FROM VQSZ_SITEINFO WHERE SIT_CD = A.SIT_CD) AS CNST_NM -- 현장명칭
              , A.WRT_YY                                                                 -- 작성년도
              , SUBSTR(A.WRT_MM, 5,2) AS WRT_MM                                          -- 작성월
              , NVL(A.WRT_CNT, 0) AS WRT_CNT                                             -- 지시건수
              , NVL(B.MA_CNT, 0) AS MA_CNT                                               -- 조치건수
              , (NVL(B.MA_CNT, 0) / NVL(A.WRT_CNT, 0)) * 100 AS RATE                     -- 대비
              , p_VNDR_SEQ VNDR_SEQ
           FROM ( -- 지시건수
                  SELECT SIT_CD                          -- 현장코드
                       , substr(WRT_DT, 1, 4)  AS WRT_YY  -- 작성년도
                       , substr(WRT_DT, 1, 6)  AS WRT_MM  -- 작성월
                       , nvl(count(WRT_DT), 0) AS WRT_CNT -- 지시건수
                  FROM TQHA_ADDRISK_ORD
                  WHERE CUST_CD     = p_CUST_CD -- 변수(업체코드)
                    AND VNDR_SEQ    = p_VNDR_SEQ     -- 변수(업체순번)
                    AND SIT_CD      = p_SIT_CD
                  GROUP BY SIT_CD, substr(WRT_DT, 1, 4), substr(WRT_DT, 1, 6)
                  ORDER BY SIT_CD, substr(WRT_DT, 1, 4), substr(WRT_DT, 1, 6)
                ) A
              , ( -- 조치건수
                  SELECT SIT_CD                             -- 현장코드
                       , substr(VNDR_MA_DT, 1, 4)  AS MA_YY  -- 작성년도
                       , substr(VNDR_MA_DT, 1, 6)  AS MA_MM  -- 작성월
                       , nvl(count(VNDR_MA_DT), 0) AS MA_CNT -- 처리건수
                  FROM TQHA_ADDRISK_ORD
                  WHERE CUST_CD         = p_CUST_CD -- 변수(업체코드)
                    AND VNDR_SEQ        = p_VNDR_SEQ     -- 변수(업체순번)
                    AND VNDR_MA_YN      = '1'   -- 조치여부(1 조치완료)
                    AND SIT_CD = p_SIT_CD
                  GROUP BY SIT_CD, substr(VNDR_MA_DT, 1, 4), substr(VNDR_MA_DT, 1, 6)
                  ORDER BY SIT_CD, substr(VNDR_MA_DT, 1, 4), substr(VNDR_MA_DT, 1, 6)
                ) B
          WHERE A.SIT_CD    = B.SIT_CD(+)
            AND A.WRT_YY    = B.MA_YY(+) 
            AND A.WRT_MM    = B.MA_MM(+)
          ORDER BY WRT_YY DESC, WRT_MM DESC
        ;

    --------------------------------------------------------------------------------
    -- 
    ELSIF p_WRK_TP = 'Q2' THEN 

        OPEN RTN_CURSOR FOR
        SELECT A.SIT_CD                                                                -- 현장코드
              , (SELECT CNST_NM FROM VQSZ_SITEINFO WHERE SIT_CD = A.SIT_CD) AS CNST_NM -- 현장명칭
              , A.PUBC_YY                                                                -- 작성년도
              , SUBSTR(A.PUBC_MM, 0, 4) || '-' || SUBSTR(A.PUBC_MM, 5, 6) PUBC_MM        -- 작성월
              , '안전' DIV_NM                                                                     -- 구분
              , A.PUBC_CNT                                                               -- 지시건수
              , B.MA_CNT                                                                 -- 조치건수
              , (B.MA_CNT / A.PUBC_CNT) * 100 RATE                                           -- 대비
         FROM ( -- 지시건수
                  SELECT SIT_CD                            -- 현장코드
                       , substr(PUBC_DT, 1, 4)  AS PUBC_YY  -- 작성년도
                       , substr(PUBC_DT, 1, 6)  AS PUBC_MM  -- 작성월
                       , nvl(count(PUBC_DT), 0) AS PUBC_CNT -- 지시건수
                  FROM TQHA_NCR_REP
                  WHERE CUST_CD     = p_CUST_CD         -- 변수(업체코드)
                    AND VNDR_SEQ    = p_VNDR_SEQ        -- 변수(업체순번)
                    AND SIT_CD      = p_SIT_CD
                  GROUP BY SIT_CD, substr(PUBC_DT, 1, 4), substr(PUBC_DT, 1, 6)
                  ORDER BY SIT_CD, substr(PUBC_DT, 1, 4), substr(PUBC_DT, 1, 6)
              ) A,
              ( -- 조치건수
                  SELECT SIT_CD                                 -- 현장코드
                       , substr(VNDR_MA_DT, 1, 4)  AS MA_YY     -- 작성년도
                       , substr(VNDR_MA_DT, 1, 6)  AS MA_MM     -- 작성월
                       , nvl(count(VNDR_MA_DT), 0) AS MA_CNT    -- 처리건수
                  FROM TQHA_NCR_REP
                  WHERE CUST_CD         = p_CUST_CD         -- 변수(업체코드)
                    AND VNDR_SEQ        = p_VNDR_SEQ        -- 변수(업체순번)
                    AND VNDR_MA_YN      = '1'   -- 조치여부(1 조치완료)
                    AND SIT_CD          = p_SIT_CD
                  GROUP BY SIT_CD, substr(VNDR_MA_DT, 1, 4), substr(VNDR_MA_DT, 1, 6)
                  ORDER BY SIT_CD, substr(VNDR_MA_DT, 1, 4), substr(VNDR_MA_DT, 1, 6)
              ) B
         WHERE A.SIT_CD     = B.SIT_CD
           AND A.PUBC_YY    = B.MA_YY
           AND A.PUBC_MM    = B.MA_MM
        --  <!-- UNION ALL
        -- - 품질 부적합보고서 작성
        --  SELECT A.SIT_CD                                                                - 현장코드
        --       , (SELECT CNST_NM FROM VQSZ_SITEINFO WHERE SIT_CD = A.SIT_CD) AS CNST_NM  - 현장명칭
        --       , A.PUBC_YY                                                                - 작성년도
        --       , SUBSTR(A.PUBC_MM, 0, 4) || '-' || SUBSTR(A.PUBC_MM, 5, 6) PUBC_MM        - 작성월
        --       , '품질' DIV_NM                                                            - 구분
        --       , NVL(A.PUBC_CNT, 0)                                                       - 지시건수
        --       , NVL(B.MA_CNT, 0)                                                         - 조치건수
        --       , (NVL(B.MA_CNT, 0) / NVL(A.PUBC_CNT, 0)) * 100 RATE                       - 대비
        --  FROM ( - 지시건수
        --           SELECT SIT_CD                            - 현장코드
        --                , substr(PUBC_DT, 1, 4)  AS PUBC_YY  - 작성년도
        --                , substr(PUBC_DT, 1, 6)  AS PUBC_MM  - 작성월
        --                , nvl(count(PUBC_DT), 0) AS PUBC_CNT - 지시건수
        --           FROM TQSC_NCR_REP
        --           WHERE CUST_CD = P_CUST_CD - 변수(업체코드)
        --             AND VNDR_SEQ = P_VNDR_SEQ     - 변수(업체순번)
        --             AND SIT_CD = P_SIT_CD
        --           GROUP BY SIT_CD, substr(PUBC_DT, 1, 4), substr(PUBC_DT, 1, 6)
        --           ORDER BY SIT_CD, substr(PUBC_DT, 1, 4), substr(PUBC_DT, 1, 6)
        --       ) A,
        --       ( - 조치건수
        --           SELECT SIT_CD                               - 현장코드
        --                , substr(VNDR_APRV_DT, 1, 4)  AS MA_YY  - 작성년도
        --                , substr(VNDR_APRV_DT, 1, 6)  AS MA_MM  - 작성월
        --                , nvl(count(VNDR_APRV_DT), 0) AS MA_CNT - 처리건수
        --           FROM TQSC_NCR_REP
        --           WHERE CUST_CD = P_CUST_CD - 변수(업체코드)
        --             AND VNDR_SEQ = P_VNDR_SEQ     - 변수(업체순번)
        --             AND SIT_CD = P_SIT_CD
        --           GROUP BY SIT_CD, substr(VNDR_APRV_DT, 1, 4), substr(VNDR_APRV_DT, 1, 6)
        --           ORDER BY SIT_CD, substr(VNDR_APRV_DT, 1, 4), substr(VNDR_APRV_DT, 1, 6)
        --       ) B
        --  WHERE A.SIT_CD = B.SIT_CD(+)
        --    AND A.PUBC_YY = B.MA_YY(+)
        --    AND A.PUBC_MM = B.MA_MM(+)
        -- ORDER BY PUBC_MM DESC -->
        ;

    --------------------------------------------------------------------------------
    -- 위험성 평가 작성/승인요청 건수
    ELSIF p_WRK_TP = 'Q3' THEN

        OPEN RTN_CURSOR FOR
        SELECT A.SIT_CD                                                                -- 현장코드
             , (SELECT CNST_NM FROM VQSZ_SITEINFO WHERE SIT_CD = A.SIT_CD) AS CNST_NM -- 현장명칭
             , A.PLN_YM                                                                 -- 평가년월
             , A.PLN_DGR                                                                -- 평가차수
          FROM TQHA_RISK_VNDR A
         WHERE A.CUST_CD    = P_CUST_CD -- 변수(업체코드)
           AND A.VNDR_SEQ   = P_VNDR_SEQ     -- 변수(업체순번)
           AND (A.SBM_YN != '1' OR nvl(A.SBM_YN, 0) = 0) -- 평가서 제출 안한 경우
           AND A.SIT_CD     = P_SIT_CD
        ;

    --------------------------------------------------------------------------------
    -- 산업안전 관리비 작성/승인 요청 건수
    ELSIF p_WRK_TP = 'Q4' THEN

        OPEN RTN_CURSOR FOR
        SELECT A.SIT_CD                                                                -- 현장코드
             , (SELECT CNST_NM FROM VQSZ_SITEINFO WHERE SIT_CD = A.SIT_CD) AS CNST_NM -- 현장명칭
             , A.RLV_YM                                                                 -- 해당년월
          FROM TQHA_SAFECOST_MMARSLT_CO A
         WHERE A.CUST_CD    = P_CUST_CD -- 변수(업체코드)
           AND A.VNDR_SEQ   = P_VNDR_SEQ     -- 변수(업체순번)
           AND (A.VNDR_APRV_YN != '1' OR nvl(A.VNDR_APRV_YN, 0) = 0) -- 평가서 제출 안한 경우
           AND A.SIT_CD     = P_SIT_CD
        ;

    --------------------------------------------------------------------------------
    -- 안전작업허가 승인요청
    ELSIF p_WRK_TP = 'Q5' THEN

        OPEN RTN_CURSOR FOR
        SELECT A.SIT_CD                                                                -- 현장코드
             , (SELECT CNST_NM FROM VQSZ_SITEINFO WHERE SIT_CD = A.SIT_CD) AS CNST_NM -- 현장명칭
             , A.VNDR_REQ_DT                                                            -- 요청일자
          FROM TQHA_SAFE_PERREQ A
         WHERE A.CUST_CD        = P_CUST_CD -- 변수(업체코드)
           AND A.VNDR_SEQ       = P_VNDR_SEQ     -- 변수(업체순번)
           AND (A.VNDR_APRV_YN  != '1' OR nvl(A.VNDR_APRV_YN, 0) = 0) -- 안전작업 허가 요청승인 안한 경우
           AND A.SIT_CD         = P_SIT_CD
        ;

    --------------------------------------------------------------------------------
    -- 
    ELSIF p_WRK_TP = 'Q6' THEN

        OPEN RTN_CURSOR FOR
        SELECT A.SIT_CD                                                                -- 현장코드
             , (SELECT CNST_NM FROM VQSZ_SITEINFO WHERE SIT_CD = A.SIT_CD) AS CNST_NM -- 현장명칭
             , A.VNDR_REQ_DT                                                            -- 요청일자
          FROM TQHA_SAFE_PERREQ A
         WHERE A.CUST_CD            = P_CUST_CD    -- 변수(업체코드)
           AND A.VNDR_SEQ           = P_VNDR_SEQ        -- 변수(업체순번)
           -- AND A.VNDR_APRV_YN    = '1' -- 안전작업 허가 요청 승인한 경우
           AND A.SITE_APRV_STATS    = '1' -- 혀장소장 승인 완료
           AND (A.VNDR_CMPL_YN != '1' OR nvl(A.VNDR_CMPL_YN, 0) = 0) -- 안전작업 허가 작업죵료 요청 안한 경우
           AND A.SIT_CD             = P_SIT_CD
        ;

    --------------------------------------------------------------------------------
    -- 공지사항(협력업체용)
    ELSIF p_WRK_TP = 'Q7' THEN

        OPEN RTN_CURSOR FOR
        SELECT A.BLT_NO -- 게시번호
             , A.BLT_DIV -- 공통코드(QS046)
             , (SELECT CD_NM FROM TCOA_COMCODE WHERE COM_CD = A.BLT_DIV AND HRNK_CD = 'QS046') AS BLT_DIV_NM -- 공통코드명
             , A.SIT_CD -- 현장코드
             , ( SELECT CNST_NM FROM VQSZ_SITEINFO WHERE SIT_CD = A.SIT_CD ) AS SIT_NM -- 현장명칭
             , A.BLT_TTL -- 게시제목
             , A.DTL_CTS -- 상세내용
             , FCOZ_GET_USR_NM(p_WRK_CORP, A.BLT_PSN) AS BLT_PSN -- 게시자
             , A.BLT_DT -- 게시일자
             , A.INQ_NO -- 조회수
             , A.ATFL_GRP -- 첨부파일그룹
             , A.ANNC_STR_DD -- 공지시작일
             , A.ANNC_END_DD -- 공지종료일
          FROM TQHA_SUBJECT A
         WHERE (BLT_DIV = '3'
                OR ( BLT_DIV = '2' AND SIT_CD = p_SIT_CD ) )     -- 변수(현장코드)
           AND 'Y' = CASE WHEN (p_SEARCH_DIV  = '0' AND (NVL(p_SEARCH_TEXT, '*') = '*' OR FCOZ_GET_USR_NM(p_WRK_CORP, BLT_PSN) LIKE '%'||p_SEARCH_TEXT||'%' ))
                          THEN 'Y'
                          WHEN (p_SEARCH_DIV  = '1' AND (NVL(p_SEARCH_TEXT, '*') = '*' OR (BLT_TTL LIKE '%'||p_SEARCH_TEXT||'%' OR DTL_CTS LIKE '%'||p_SEARCH_TEXT||'%' )))
                          THEN 'Y'
                          WHEN NVL(p_SEARCH_DIV, '*') = '*'
                          THEN 'Y'
                          ELSE 'N'
                    END
         ORDER BY BLT_DT DESC
        ;

    --------------------------------------------------------------------------------
    -- 공지사항 상세정보
    ELSIF p_WRK_TP = 'Q8' THEN

        OPEN RTN_CURSOR FOR
        SELECT A.BLT_NO                                                           --게시번호
             , A.BLT_DIV                                                          --업무구분
             , A.BLT_TTL                                                          --제목
             --, TO_CHAR(A.DTL_CTS) AS DTL_CTS                                      --상세내용
             , A.DTL_CTS
             , A.ATFL_GRP                                                         --첨부파일그룹
             , A.ANNC_STR_DD                                                      --공지시작일
             , A.ANNC_END_DD                                                      --공지종료일
             , A.IPT_ID                                                           --작성자ID
             , FCOZ_GET_USR_NM(p_WRK_CORP, A.IPT_ID) AS IPT_NM                                  --작성자명
             , TO_CHAR(A.IPT_DTM,'YYYY/MM/DD') AS IPT_DTM                         --작성일
             , A.BLT_DT                                                           --게시일자
             , A.INQ_NO                                                           --조회수
             , A.SIT_CD                                                          --현장코드
             , A.BLT_PSN
             , ( SELECT CNST_NM FROM VQSZ_SITEINFO WHERE SIT_CD = A.SIT_CD ) AS SIT_NM -- 현장명칭
          FROM TQHA_SUBJECT A
         WHERE A.BLT_NO = p_BLT_NO
        ;

    END IF;


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
         WHEN OTHERS THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);

END PQHA_DASHBOARD_CO_Q ;
/

-- PQHA_DASHBOARD_Q (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_DASHBOARD_Q" (
    p_WRK_TP        VARCHAR2 DEFAULT 'Q'    --FLAG(Q: SELECT)
,   p_SRCH_Y        VARCHAR2                --해당년도 재해현황
,   p_DISS_DIV      VARCHAR2                --재해구분
,   RTN_CURSOR      OUT SYS_REFCURSOR
)
IS
    /**************************************************************************************************************************
     Purpose : 안전 대시보드 조회
     Procedure:    [PQHA_DASHBOARD_Q] Procedure
     설명      :   안전 대시보드 조회

     개정일자                      변경내용요약                                 관련근거
    ---------------------------------------------------------------------------------------------------------------------------
     [2024-10-14]         HumanPlus 신규 자동 생성               [Procedure Creator]
    ***************************************************************************************************************************/

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009; --ERROR 코드
    ERR_MSG        VARCHAR2(200)  ; --ERROR Message
    USER_EXCEPTION EXCEPTION      ;

BEGIN
    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 수행전 Check Logic ]
    ---------------------------------------------------------------------------------------------------------------------------

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Logic 처리
    ---------------------------------------------------------------------------------------------------------------------------
    IF p_WRK_TP ='Q1' THEN

        OPEN RTN_CURSOR FOR 

        -- 안전 대쉬보드 작업
		WITH 
		/* 1. [기준] SIT_TERR가 NULL이 아닌 현장 목록 */
		BASE_SIT AS (
		    SELECT 
		        SIT_CD
		    FROM TQHA_SAFT_SIT
		    WHERE SIT_TERR IS NOT NULL
		),
		
		/* 2. 점검항목 및 실시건수 집계 (중점 / 일상) */
		CHKLST_AGG AS (
		    SELECT 
		        CHK.SIT_CD,
		        -- 중점점검
		        SUM(CASE WHEN CHK.RISK_GRD = 'QS0900201' AND CHK.ODAY_CHK_RSLT IS NOT NULL THEN 1 ELSE 0 END) AS MAIN_EXEC_CNT,
		        COUNT(CASE WHEN CHK.RISK_GRD = 'QS0900201' THEN CHK.CHK_ITM_CD END)                           AS MAIN_TOT_CNT,
		        -- 일상점검
		        SUM(CASE WHEN CHK.RISK_GRD = 'QS0900202' AND CHK.ODAY_CHK_RSLT IS NOT NULL THEN 1 ELSE 0 END) AS DAILY_EXEC_CNT,
		        COUNT(CASE WHEN CHK.RISK_GRD = 'QS0900202' THEN CHK.CHK_ITM_CD END)                          AS DAILY_TOT_CNT
		    FROM BASE_SIT S
		    INNER JOIN TQHB_DAYSAFE_DT DT 
		            ON S.SIT_CD = DT.SIT_CD
		           AND DT.PLN_YM = p_SRCH_Y
		    INNER JOIN TQHB_DAYSAFE_CHKLST CHK
		            ON DT.SIT_CD      = CHK.SIT_CD
		           AND DT.PLN_YM      = CHK.PLN_YM
		           AND DT.PLN_DGR     = CHK.PLN_DGR
		           AND DT.ODAY_CHK_DT = CHK.ODAY_CHK_DT
		           AND DT.RISK_GRD    = CHK.RISK_GRD
		    GROUP BY CHK.SIT_CD
		),
		
		/* 3. 점검승인일수 집계 (현장소장 승인: SITE_OMGR_YN = '1') */
		APRV_AGG AS (
		    SELECT 
		        DT.SIT_CD,
		        COUNT(DISTINCT CASE WHEN DT.RISK_GRD = 'QS0900201' AND DT.SITE_OMGR_YN = '1' THEN DT.ODAY_CHK_DT END) AS MAIN_APRV_CNT,
		        COUNT(DISTINCT CASE WHEN DT.RISK_GRD = 'QS0900202' AND DT.SITE_OMGR_YN = '1' THEN DT.ODAY_CHK_DT END) AS DAILY_APRV_CNT
		    FROM BASE_SIT S
		    INNER JOIN TQHB_DAYSAFE_DT DT 
		            ON S.SIT_CD = DT.SIT_CD
		           AND DT.PLN_YM = p_SRCH_Y
		    GROUP BY DT.SIT_CD
		),
		
		/* 4. 추가위험발굴 집계 (승인: MGR_APRV_YN = '1') */
		ADDRISK_AGG AS (
		    SELECT 
		        ORD.SIT_CD,
		        COUNT(CASE WHEN ORD.MGR_APRV_YN = '1' THEN 1 END) AS ADD_EXEC_CNT, -- 승인된 건수 (실시)
		        COUNT(*)                                          AS ADD_TOT_CNT   -- 전체 건수
		    FROM BASE_SIT S
		    INNER JOIN TQHA_ADDRISK_ORD ORD
		            ON S.SIT_CD = ORD.SIT_CD
		           AND ORD.WRT_DT LIKE p_SRCH_Y || '%'
		    GROUP BY ORD.SIT_CD
		),
		
		/* 5. 산업보건관리비 실적 집계 */
		ARSLT_TOTAL AS (
		    SELECT SIT_CD
		         , SUM(USE_AMT) AS USE_AMT
		      FROM (
		            SELECT SIT_CD, USE_AMT
		              FROM TQHA_SAFECOST_ARSLT
		             WHERE RLV_YM = p_SRCH_Y
		
		            UNION ALL
		
		            SELECT SIT_CD, USE_AMT
		              FROM TQHA_SAFECOST_ARSLT_CO
		             WHERE RLV_YM = p_SRCH_Y
		           )
		     GROUP BY SIT_CD
		),
		
		/* 6. 산업보건관리비 예산 집계 */
		BGT_TOTAL AS (
		    SELECT SIT_CD
		         , APRP_SAFT_MCHR AS BYM_EBGT_BGT
		      FROM TQHA_SAFECOST_INFO
		)
		
		/* 최종 결과 집합 */
		SELECT 
		    ROW_NUMBER() OVER (ORDER BY B.SIT_CD) AS RNUM,
		    B.SIT_CD,
		    ( SELECT CNST_NM FROM VQSZ_SITEINFO WHERE SIT_CD = B.SIT_CD ) AS SIT_NM,
		    
		    /* 1. 중점점검 */
		    NVL(C.MAIN_EXEC_CNT, 0) AS MAIN_EXEC_CNT, -- 중점 실시
		    NVL(C.MAIN_TOT_CNT, 0)  AS MAIN_TOT_CNT,  -- 중점 전체
		    
		    /* 2. 일상점검 */
		    NVL(C.DAILY_EXEC_CNT, 0) AS DAILY_EXEC_CNT, -- 일상 실시
		    NVL(C.DAILY_TOT_CNT, 0)  AS DAILY_TOT_CNT,  -- 일상 전체
		    
		    /* 3. 추가위험발굴 */
		    NVL(A.ADD_EXEC_CNT, 0) AS ADD_EXEC_CNT, -- 추가위험발굴 실시
		    NVL(A.ADD_TOT_CNT, 0)  AS ADD_TOT_CNT,  -- 추가위험발굴 전체
		    
		    /* 4. 점검승인 */
		    NVL(V.MAIN_APRV_CNT, 0)  AS MAIN_APRV_CNT, -- 중점 승인
		    NVL(V.DAILY_APRV_CNT, 0) AS DAILY_APRV_CNT, -- 일상 승인
		
		    /* 5. 안전보건관리비 (실적 및 예산) */
		    NVL(R.USE_AMT, 0)       AS USE_AMT,     -- 사용금액
		    NVL(BG.BYM_EBGT_BGT, 0) AS BYM_EBGT_BGT -- 예산액
		
		FROM BASE_SIT B
		LEFT JOIN CHKLST_AGG  C  ON B.SIT_CD = C.SIT_CD
		LEFT JOIN APRV_AGG    V  ON B.SIT_CD = V.SIT_CD
		LEFT JOIN ADDRISK_AGG A  ON B.SIT_CD = A.SIT_CD
		LEFT JOIN ARSLT_TOTAL R  ON B.SIT_CD = R.SIT_CD
		LEFT JOIN BGT_TOTAL   BG ON B.SIT_CD = BG.SIT_CD
		ORDER BY B.SIT_CD
        ;

    ELSIF p_WRK_TP ='Q2' THEN

        OPEN RTN_CURSOR FOR
        SELECT A.*
		      ,(SELECT CNST_NM FROM VQSZ_SITEINFO WHERE SIT_CD = A.SIT_CD) AS SIT_NM
		FROM (
		    SELECT 
		        A.SIT_CD                                      AS SIT_CD,
		        COUNT(B.SIT_CD)                               AS TOT_CNT, -- B의 데이터가 있을 때만 집계
		        COUNT(CASE WHEN B.DISS_DIV = '01' THEN 1 END) AS DISS_CNT_01,
		        COUNT(CASE WHEN B.DISS_DIV = '02' THEN 1 END) AS DISS_CNT_02,
		        COUNT(CASE WHEN B.DISS_DIV = '03' THEN 1 END) AS DISS_CNT_03,
		        COUNT(CASE WHEN B.DISS_DIV = '04' THEN 1 END) AS DISS_CNT_04
		    FROM TQHA_SAFT_SIT A
		        ,TQHA_IDAC B
		        ,TCOF_APPROVE C
		    WHERE A.SIT_CD = B.SIT_CD(+) 
		      AND B.APRV_NO_GW = C.APRV_NO(+)
		      AND C.APRV_STATS(+) = '3010'        -- (+) 추가
		      AND B.ACCD_DT(+) LIKE p_SRCH_Y||'%'       -- (+) 추가
		    GROUP BY A.SIT_CD
		) A
		ORDER BY A.SIT_CD;
		
    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);
END;
/

-- PQHA_DAYSAFE_CHKLST_B1 (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_DAYSAFE_CHKLST_B1" (    -- 일일안전점검 승인
    p_WRK_TP                VARCHAR2 :='S'                                  -- UPDATE FLAG( I: ISNERT, U:UPDATE, D:DELTE, S : 승인처리)
,   p_WRK_ID                VARCHAR2                                        -- 사용자 ID
,   p_WRK_IP                VARCHAR2                                        -- 사용자 IP
,   p_SIT_CD                TQHA_DAYSAFE_CHKLST.SIT_CD          %TYPE       -- 현장코드
,   p_PLN_YM                TQHA_DAYSAFE_CHKLST.PLN_YM          %TYPE       -- 계획년월
,   p_PLN_DGR               TQHA_DAYSAFE_CHKLST.PLN_DGR         %TYPE       -- 회자
,   p_ODAY_CHK_DT           TQHA_DAYSAFE_CHKLST.ODAY_CHK_DT     %TYPE       -- 점검일자
,   p_USR_ID                TQHA_DAYSAFE_CHKLST.ODAY_INSP       %TYPE       -- 사번
,   p_RTN_BTN               OUT VARCHAR2                                    -- 리턴값 (안전관리자, 현장소장 승인여부)
,   p_RTN_BTN_MGR           OUT VARCHAR2                                    -- 리턴값 (관리감독자 승인여부)
,   p_RTN_MNG_DIV           OUT VARCHAR2                                    -- 리턴값 (관리자/안전/소장)
,   p_RTN_STATS_NM          OUT VARCHAR2                                    -- 리턴값 (상태)
)
IS 
    /**************************************************************************************************************************
      Purpose : 일일안전점검 승인

      REVISIONS
      Ver      Date               Author                  Description
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2021/12/13 12:48:42                         최초생성

    **************************************************************************************************************************/


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR2(200);            -- ERROR Message
    USER_EXCEPTION EXCEPTION;


    v_MGR_APRV      VARCHAR2(1) ;   -- 관리감독자 승인여부
    v_SAFT_APRV     VARCHAR2(1) ;   -- 안전감독자 승인여부
    v_SITE_APRV     VARCHAR2(1) ;   -- 현장소장 승인여부

    v_MGR_CNT       INTEGER;        -- 관리감독자 여부
    v_SAFT_CNT      INTEGER;        -- 안전관리자 여부
    v_SITE_CNT      INTEGER;        -- 현장소장 여부

    v_RTN_BTN       VARCHAR2(1)     := 'F' ;    -- 리턴 초기값 (안전관리자, 현장소장인 경우)
    v_RTN_BTN_MGR   VARCHAR2(1)     := 'F' ;    -- 리턴 초기값 (관리감독자인 경우)
    v_RTN_MNG_DIV   VARCHAR2(10)    := 'N' ;    -- 리턴 상태 초기값 ( 관리자 MGR : 관리자, SAFT : 안전관리자, SITE : 현장소장 )

BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 필수입력 필드  Check  ]
    ---------------------------------------------------------------------------------------------------------------------------
    -- 일일점검일자테이블에서 승읜 할 데이터가 있는지 체크
    SELECT   nvl(MNG_APRV_STATS,0)           -- 관리감독자 승인여부
           , nvl(SAFT_APRV_STATS,0)          -- 안전관리자 승인여부
           , nvl(SITE_APRV_STATS,0)          -- 현장소장 승인여부
           , '▶ 상태 : ' ||
               CASE WHEN SITE_APRV_STATS IN ('1', '2') THEN
                         CASE WHEN SITE_APRV_STATS = '1' THEN '현장소장-승인'
                              ELSE '현장소장-반려'
                         END
                    ELSE CASE WHEN SAFT_APRV_STATS IN ('1', '2') THEN
                                   CASE WHEN SAFT_APRV_STATS = '1' THEN '안전관리자-승인'
                                        ELSE '안전관리자-반려'
                                   END
                              ELSE CASE WHEN MNG_APRV_STATS IN ('1', '2') THEN
                                             CASE WHEN MNG_APRV_STATS = '1' THEN '관리자-승인요청'
                                                  ELSE '-'
                                             END
                                        ELSE '-'
                                   END
                         END
               END              AS STATS_NM
        INTO v_MGR_APRV                         -- 관리감독자 승인여부
           , v_SAFT_APRV                        -- 안전관리자 승인여부
           , v_SITE_APRV                        -- 현장소장 승인여부
           , p_RTN_STATS_NM
      FROM TQHA_DAYSAFE_DT
     WHERE SIT_CD       = p_SIT_CD              --변수 (현장코드)
       AND ODAY_CHK_DT  = p_ODAY_CHK_DT         --변수 (점검일자 )
    ;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Process 선행조건 Check ]
    ---------------------------------------------------------------------------------------------------------------------------


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Business Process ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_WRK_TP = 'S') THEN    -- 승인처리

        -- 관리자 승인 전 단계
        IF (v_MGR_APRV = '0') THEN

            -- 관리자가 승인 권한이 있는지 체크
            SELECT nvl(COUNT(MA_PSN),0)
              INTO v_MGR_CNT
              FROM TQHA_RISK_CHK
             WHERE SIT_CD         = p_SIT_CD          -- 변수 (현장코드)
               AND PLN_YM         = p_PLN_YM          -- 변수 (계획년월)
               AND PLN_DGR        = p_PLN_DGR         -- 변수 (차수)
               AND PRRT_REG       = '1'               -- 중점등록 체크
               AND MA_PSN    IN (p_USR_ID)       -- 변수 (사번)
            ;
            -- 숭인권한이 있음
            IF v_MGR_CNT > 0 then
                v_RTN_BTN       := 'F';
                v_RTN_BTN_MGR   := 'T';
                v_RTN_MNG_DIV   := 'MGR';
            END IF;
        END IF;

       -- 관리자 승인 후 단계
        IF (v_MGR_APRV = '1' AND v_SAFT_APRV = '0' ) THEN     -- 관리자 승인 후 AND 안전관리자 승인 전

            /*
            -- 안전관리자 승인 권한이 있는지 체크
            SELECT  nvl(COUNT(JB_CD),0)
              INTO v_SAFT_CNT
              FROM  ( -- 조직도에서 직무코드가 안전관리자인 경우
                     SELECT   DEPT_CD   -- 현장코드
                           , USR_ID    -- 사용자 id
                           , JB_CD     -- 직무코드
                      FROM TCOZ_USR_INFO
                     WHERE DEPT_CD = p_SIT_CD       -- 변수(현장코드)
                     AND  JB_CD IN ('B37E01','CM0135','CM0136','CM0137') ) A
             WHERE A.DEPT_CD = p_SIT_CD   -- 변수 (현장코드)
               AND A.USR_ID = p_USR_ID     -- 변수 (사용자id)
                  ;
            */

            -- 안전관리자 승인 권한이 있는지 체크
            SELECT  nvl(COUNT(JB_CD),0)
              INTO v_SAFT_CNT
              FROM (
                    -- 2026.01.20 주석 처리
                    -- 조직도에서 직무코드가 안전관리자인 경우
                    --SELECT   DEPT_CD   -- 현장코드
                    --        , USR_ID    -- 사용자 id
                    --        , JB_CD     -- 직무코드
                    --  FROM TCOZ_USR_INFO
                    -- WHERE DEPT_CD = p_SIT_CD       -- 변수(현장코드)
                    --   AND  JB_CD IN ('B37E01','CM0135','CM0136','CM0137')
                    -- UNION   -- 2020/5/18 일 겸직정보 추가
                    -- SELECT DEPT_CD   -- 현장코드
                    --       , USR_ID    -- 사용자 id
                    --       , JB_CD     -- 직무코드
                    --   FROM TCOZ_SBJB_INFO
                    --  WHERE DEPT_CD = p_SIT_CD
                    --    AND JB_CD IN ('B37E01','CM0135','CM0136','CM0137')

                     SELECT SIT_CD    AS DEPT_CD
                         , EMPE_NO    AS USR_ID
                         , JB_CD      AS JB_CD
                      FROM TQHA_SITENAM
                     WHERE SIT_CD = p_SIT_CD
                       AND EMPE_NO = p_USR_ID
                       AND JB_CD IN ('QS07702')  -- 안전관리자, 안전총괄
                   ) A
             WHERE A.DEPT_CD     = p_SIT_CD      -- 변수 (현장코드)
               AND A.USR_ID      = p_USR_ID      -- 변수 (사용자id)
            ;

            -- 안전관리자가 승인 권한이 있는지 체크
            IF v_SAFT_CNT > 0 then
                v_RTN_BTN       := 'T';
                v_RTN_BTN_MGR   := 'F';
                v_RTN_MNG_DIV   := 'SAFT';
            END IF;

        END IF;

        -- 안전관리자 승인 후 단계
        IF (v_MGR_APRV = '1' AND v_SAFT_APRV = '1') THEN

            -- 현장소장 승인 권한이 있는지 체크
            SELECT  nvl(COUNT(JB_CD),0)
              INTO v_SITE_CNT
              FROM (
                    -- 2026.01.20 주석
                    -- 조직도에서 직무코드가 안전관리자인 경우
                    --                    SELECT   DEPT_CD   -- 현장코드
                    --                          , USR_ID    -- 사용자 id
                    --                          , JB_CD     -- 직무코드
                    --                     FROM TCOZ_USR_INFO
                    --                    WHERE DEPT_CD = p_SIT_CD   -- 변수(현장코드)
                    --                    AND  JB_CD IN ('B37F01') ) A

                     SELECT SIT_CD    AS DEPT_CD
                         , EMPE_NO    AS USR_ID
                         , JB_CD      AS JB_CD
                      FROM TQHA_SITENAM
                     WHERE SIT_CD = p_SIT_CD
                       AND EMPE_NO = p_USR_ID
                       AND JB_CD IN ('QS07703')  -- 현장소장
                   ) A
             WHERE A.DEPT_CD    = p_SIT_CD      -- 변수 (현장코드)
               AND A.USR_ID     = p_USR_ID      -- 변수 (사용자id)
            ;

            -- 현장소장 승인 권한이 있는지 체크
            IF v_SITE_CNT > 0 then
               v_RTN_BTN        := 'T';
               v_RTN_BTN_MGR    := 'F';
               v_RTN_MNG_DIV    := 'SITE';
            END IF;

        END IF;

       -- 현장소장 승인 후 단계
        IF (v_SITE_APRV <> '0' ) THEN
            v_RTN_BTN       := 'F';
            v_RTN_BTN_MGR   := 'F';
            v_RTN_MNG_DIV   := 'N';
        END IF;

        p_RTN_BTN := v_RTN_BTN ;
        p_RTN_BTN_MGR := v_RTN_BTN_MGR ;
        p_RTN_MNG_DIV := v_RTN_MNG_DIV;

    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 5. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);
END PQHA_DAYSAFE_CHKLST_B1;
/

-- PQHA_DAYSAFE_CHKLST_Q (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_DAYSAFE_CHKLST_Q" (  
    p_WRK_TP                IN VARCHAR2 DEFAULT 'Q'             -- FLAG
,   p_SIT_CD                IN VARCHAR2
,   p_PLN_YM                IN VARCHAR2
,   p_PLN_DGR               IN VARCHAR2
,   p_RISK_GRD              IN VARCHAR2
,   RTN_CURSOR              OUT SYS_REFCURSOR
)
IS
    /**************************************************************************************************************************
      Purpose : [평가항목 조회] PROCEDRE (QSE > 안전관리 > 중점점검관리 > 일일안전점검  )

      REVISIONS
      Ver      Date               Author                  Description
      -------  -----------------  ----------------------  ---------------------------------------------------------------------
      1.0      2023/12/07                                 최초생성  

    **************************************************************************************************************************/

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE  NUMBER :=-20009; -- ERROR 코드
    ERR_MSG   VARCHAR(200);    -- ERROR Message
    USER_EXCEPTION EXCEPTION;

BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 수행전 Check Logic ]
    ---------------------------------------------------------------------------------------------------------------------------

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Logic 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------

    IF p_WRK_TP = 'Q' THEN

        OPEN RTN_CURSOR FOR
        SELECT A.SIT_CD             -- 현장코드
		     , A.PLN_YM             -- 계획년월
		     , A.PLN_DGR            -- 계획차수
		     , ( SELECT CD_NM FROM TCOA_COMCODE WHERE COM_CD = A.PLN_DGR AND HRNK_CD = 'QS005') AS PLN_DGR_NM -- 계획차수명
		     , A.ODAY_CHK_DT        -- 점검일자
		     , ( SELECT USR_NM FROM TCOZ_USR_INFO WHERE USR_ID = A.EMPE_NO_SAFT ) AS EMPE_NO_SAFT_NM --안전책임자
		     , A.EMPE_NO_SAFT
			 , A.SAFT_MGR_YN
			 , DECODE(A.SAFT_MGR_YN,'1','O','X') AS SAFT_MGR_YN_NM
			 , DECODE(A.SAFT_MGR_YN,'1',A.SAFT_MGR_DT,'') AS SAFT_MGR_DT
			 , A.SAFT_MGR_OPIN
			 , ( SELECT USR_NM FROM TCOZ_USR_INFO WHERE USR_ID = A.EMPE_NO_OMGR ) AS EMPE_NO_OMGR_NM --현장소장
			 , A.EMPE_NO_OMGR
			 , A.SITE_OMGR_YN
			 , DECODE(A.SITE_OMGR_YN,'1','O','X') AS SITE_OMGR_YN_NM
			 , DECODE(A.SITE_OMGR_YN,'1',A.SITE_OMGR_DT,'') AS SITE_OMGR_DT
			 , A.SITE_OMGR_OPIN
		     , A.RISK_GRD     
		  FROM TQHB_DAYSAFE_DT A
		 WHERE 1=1
           AND A.SIT_CD = p_SIT_CD
           AND A.PLN_YM = p_PLN_YM
           AND A.RISK_GRD = p_RISK_GRD
         ORDER BY A.ODAY_CHK_DT
	       ;

    END IF;


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
         WHEN OTHERS THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);

END PQHA_DAYSAFE_CHKLST_Q;
/

-- PQHA_DAYSAFE_CHKLST_S (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_DAYSAFE_CHKLST_S" (
    p_WRK_TP                VARCHAR2 :='U'                                          -- UPDATE FLAG( I: ISNERT, U:UPDATE, D:DELTE)
,   p_WRK_ID                VARCHAR2                                                -- 사용자 ID
,   p_WRK_IP                VARCHAR2                                                -- 사용자 IP
,   p_SIT_CD                TQHA_DAYSAFE_CHKLST.SIT_CD              %TYPE           -- 현장코드
,   p_PLN_YM                TQHA_DAYSAFE_CHKLST.PLN_YM              %TYPE           -- 계획년월
,   p_PLN_DGR               TQHA_DAYSAFE_CHKLST.PLN_DGR             %TYPE           -- 차수구분코드(QS005) 1 1차,2 2차
,   p_ODAY_CHK_DT           TQHA_DAYSAFE_CHKLST.ODAY_CHK_DT         %TYPE           -- 일일점검일자
,   p_CTP_CD                TQHA_DAYSAFE_CHKLST.CTP_CD              %TYPE           -- 공종코드
,   p_CHK_ITM_CD            TQHA_DAYSAFE_CHKLST.CHK_ITM_CD          %TYPE           -- 점검항목코드
,   p_UNT_CD                TQHA_DAYSAFE_CHKLST.UNT_CD              %TYPE           -- 단위코드
,   p_CUST_CD               TQHA_DAYSAFE_CHKLST.CUST_CD             %TYPE           -- 협력업체코드
,   p_VNDR_SEQ              TQHA_DAYSAFE_CHKLST.VNDR_SEQ            %TYPE           -- 업체순번
,   p_ODAY_CHK_RSLT         TQHA_DAYSAFE_CHKLST.ODAY_CHK_RSLT       %TYPE           -- 점검결과(QS006) 1 N/A,2 완료(유지),3 불량
,   p_ODAY_CHK_OPIN         TQHA_DAYSAFE_CHKLST.ODAY_CHK_OPIN       %TYPE           -- 일일점검의견
,   p_ODAY_INSP             TQHA_DAYSAFE_CHKLST.ODAY_INSP           %TYPE           -- 일일점검자
,   p_PHOTO_GRP1            TQHA_DAYSAFE_CHKLST.PHOTO_GRP1          %TYPE           -- 첨부파일그룹사진1
,   p_PHOTO_DESC_1          TQHA_DAYSAFE_CHKLST.PHOTO_DESC_1        %TYPE           -- 사진설명1
,   p_PHOTO_GRP2            TQHA_DAYSAFE_CHKLST.PHOTO_GRP2          %TYPE           -- 첨부파일그룹사진2
,   p_PHOTO_DESC_2          TQHA_DAYSAFE_CHKLST.PHOTO_DESC_2        %TYPE           -- 사진설명2
,   p_NCR_PUBC_YN           TQHA_DAYSAFE_CHKLST.NCR_PUBC_YN         %TYPE           -- 발행 1, 미발행 0
,   p_NCR_DOC_NO            TQHA_DAYSAFE_CHKLST.NCR_DOC_NO          %TYPE           -- 부적합문서번호
,   p_MA_DDLN_DT            TQHA_DAYSAFE_CHKLST.MA_DDLN_DT          %TYPE           -- 조치기한일자
,   p_VNDR_NOTI_YN          TQHA_DAYSAFE_CHKLST.VNDR_NOTI_YN        %TYPE           -- 업체통보여부
,   p_VNDR_SEND_DT          TQHA_DAYSAFE_CHKLST.VNDR_SEND_DT        %TYPE           -- 업체발송일자
)
IS
    /**************************************************************************************************************************
      Purpose :

      REVISIONS
      Ver      Date               Author                  Description
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2021/12/17 14:26:11                         최초생성

    **************************************************************************************************************************/


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR2(200);            -- ERROR Message
    USER_EXCEPTION EXCEPTION;

    v_CNT              NUMBER := 0;
    v_OLD_NCR_DOC_NO   VARCHAR2(50);
    v_VNDR_APRV_YN     VARCHAR2(1);
    v_MGR_APRV_YN      VARCHAR2(1);

BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 필수입력 필드  Check  ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_SIT_CD IS NULL)  THEN
        ERR_MSG := '현장코드는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_PLN_YM IS NULL)  THEN
        ERR_MSG := '계획년월는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_PLN_DGR IS NULL)  THEN
        ERR_MSG := '차수구분코드(QS005) 1 1차,2 2차는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_ODAY_CHK_DT IS NULL)  THEN
        ERR_MSG := '일일점검일자는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_CTP_CD IS NULL)  THEN
        ERR_MSG := '공종코드는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_CHK_ITM_CD IS NULL)  THEN
        ERR_MSG := '점검항목코드는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_UNT_CD IS NULL)  THEN
        ERR_MSG := '단위코드는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_CUST_CD IS NULL)  THEN
        ERR_MSG := '협력업체코드는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_VNDR_SEQ IS NULL)  THEN
        ERR_MSG := '업체순번는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Process 선행조건 Check ]
    ---------------------------------------------------------------------------------------------------------------------------


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Business Process ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_WRK_TP ='P') THEN

        -- 2025.02.02 부적합보고서 승인 상태 체크하여, 업체 승인 요청시 또는 관리자 승인시엔 불량에서 다른걸로 변경하지 못하게 막아야 함.
        SELECT NVL(MAX(NCR_DOC_NO), '*')
          INTO v_OLD_NCR_DOC_NO
          FROM TQHA_DAYSAFE_CHKLST
         WHERE SIT_CD       = p_SIT_CD          --현장코드
           AND PLN_YM       = p_PLN_YM          --계획년월
           AND PLN_DGR      = p_PLN_DGR         --차수구분코드(QS005) 1 1차,2 2차
           AND ODAY_CHK_DT  = p_ODAY_CHK_DT     --일일점검일자
           AND CTP_CD       = p_CTP_CD          --공종코드
           AND CHK_ITM_CD   = p_CHK_ITM_CD      --점검항목코드
           AND UNT_CD       = p_UNT_CD          --단위코드
        ;

        IF v_OLD_NCR_DOC_NO != '*' THEN
            SELECT VNDR_APRV_YN
                 , MGR_APRV_YN
              INTO v_VNDR_APRV_YN
                 , v_MGR_APRV_YN
              FROM TQHA_NCR_REP
             WHERE SIT_CD       = p_SIT_CD
               AND NCR_DOC_NO   = v_OLD_NCR_DOC_NO
            ;

            IF v_MGR_APRV_YN = '1' THEN
                ERR_MSG := '부적합보고서 관리자가 승인한 상태여서 변경할 수 없습니다.'
                        || CHR(10) || '관리자 반려 후, 업체 승인요청취소 후에 변경 가능합니다. ';
                RAISE USER_EXCEPTION;
            END IF;

            IF v_VNDR_APRV_YN = '1' THEN
                ERR_MSG := '부적합보고서 업체 승인요청중이어서 변경할 수 없습니다.'
                        || CHR(10) || '승인요청 취소 후 변경 가능합니다 ';
                RAISE USER_EXCEPTION;
            END IF;

        END IF;

        -- 해당 데이터가 있는지 확인
        SELECT COUNT(*) INTO v_CNT
          FROM TQHA_DAYSAFE_CHKLST
         WHERE SIT_CD           = p_SIT_CD          -- 현장코드
           AND PLN_YM           = p_PLN_YM          -- 계획년월
           AND PLN_DGR          = p_PLN_DGR         -- 차수구분코드(QS005) 1 1차,2 2차
           AND ODAY_CHK_DT      = p_ODAY_CHK_DT     -- 일일점검일자
           AND CTP_CD           = p_CTP_CD          -- 공종코드
           AND CHK_ITM_CD       = p_CHK_ITM_CD      -- 점검항목코드
           AND UNT_CD           = p_UNT_CD          -- 단위코드
        ;

        -- 대상업체가 있는 경우
        IF (v_CNT > 0) THEN

            UPDATE TQHA_DAYSAFE_CHKLST
               SET CUST_CD              = p_CUST_CD                 --협력업체코드
                 , VNDR_SEQ             = p_VNDR_SEQ                --업체순번
                 , ODAY_CHK_RSLT        = p_ODAY_CHK_RSLT           --점검결과(QS006) 1 N/A,2 완료(유지),3 불량
                 , ODAY_CHK_OPIN        = p_ODAY_CHK_OPIN           --일일점검의견
                 , ODAY_INSP            = p_ODAY_INSP               --일일점검자
                 , PHOTO_GRP1           = p_PHOTO_GRP1              --첨부파일그룹사진1
                 , PHOTO_DESC_1         = p_PHOTO_DESC_1            --사진설명1
                 , PHOTO_GRP2           = p_PHOTO_GRP2              --첨부파일그룹사진2
                 , PHOTO_DESC_2         = p_PHOTO_DESC_2            --사진설명2
                 , NCR_PUBC_YN          = p_NCR_PUBC_YN             --발행 1, 미발행 0
                 , NCR_DOC_NO           = p_NCR_DOC_NO              --부적합문서번호
                 , MA_DDLN_DT           = p_MA_DDLN_DT              --조치기한일자
                 , VNDR_NOTI_YN         = p_VNDR_NOTI_YN            --업체통보여부
                 , VNDR_SEND_DT         = p_VNDR_SEND_DT            --업체발송일자
                 , UPD_ID               = p_WRK_ID                  --수정ID
                 , UPD_DTM              = SYSDATE()                 --수정일시
                 , UPD_IP               = p_WRK_IP                  --수정IP
             WHERE SIT_CD               = p_SIT_CD                  --현장코드
               AND PLN_YM               = p_PLN_YM                  --계획년월
               AND PLN_DGR              = p_PLN_DGR                 --차수구분코드(QS005) 1 1차,2 2차
               AND ODAY_CHK_DT          = p_ODAY_CHK_DT             --일일점검일자
               AND CTP_CD               = p_CTP_CD                  --공종코드
               AND CHK_ITM_CD           = p_CHK_ITM_CD              --점검항목코드
               AND UNT_CD               = p_UNT_CD                  --단위코드
            ;

        ELSE

            INSERT 
              INTO TQHA_DAYSAFE_CHKLST
                 ( SIT_CD                   -- 현장코드
                 , PLN_YM                   -- 계획년월
                 , PLN_DGR                  -- 차수구분코드(QS005) 1 1차,2 2차
                 , ODAY_CHK_DT              -- 일일점검일자
                 , CTP_CD                   -- 공종코드
                 , CHK_ITM_CD               -- 점검항목코드
                 , UNT_CD                   -- 단위코드
                 , CUST_CD                  -- 협력업체코드
                 , VNDR_SEQ                 -- 업체순번
                 , ODAY_CHK_RSLT            -- 점검결과(QS006) 1 N/A,2 완료(유지),3 불량
                 , ODAY_CHK_OPIN            -- 일일점검의견
                 , ODAY_INSP                -- 일일점검자
                 , PHOTO_GRP1               -- 첨부파일그룹사진1
                 , PHOTO_DESC_1             -- 사진설명1
                 , PHOTO_GRP2               -- 첨부파일그룹사진2
                 , PHOTO_DESC_2             -- 사진설명2
                 , NCR_PUBC_YN              -- 발행 1, 미발행 0
                 , NCR_DOC_NO               -- 부적합문서번호
                 , MA_DDLN_DT               -- 조치기한일자
                 , VNDR_NOTI_YN             -- 업체통보여부
                 , VNDR_SEND_DT             -- 업체발송일자
                 , IPT_ID                   -- 입력ID
                 , IPT_DTM                  -- 입력일시
                 , IPT_IP                   -- 입력IP
                 , UPD_ID                   -- 수정ID
                 , UPD_DTM                  -- 수정일시
                 , UPD_IP                   -- 수정IP
                 )
            VALUES 
                 ( p_SIT_CD                 -- 현장코드
                 , p_PLN_YM                 -- 계획년월
                 , p_PLN_DGR                -- 차수구분코드(QS005) 1 1차,2 2차
                 , p_ODAY_CHK_DT            -- 일일점검일자
                 , p_CTP_CD                 -- 공종코드
                 , p_CHK_ITM_CD             -- 점검항목코드
                 , p_UNT_CD                 -- 단위코드
                 , p_CUST_CD                -- 협력업체코드
                 , p_VNDR_SEQ               -- 업체순번
                 , p_ODAY_CHK_RSLT          -- 점검결과(QS006) 1 N/A,2 완료(유지),3 불량
                 , p_ODAY_CHK_OPIN          -- 일일점검의견
                 , p_ODAY_INSP              -- 일일점검자
                 , p_PHOTO_GRP1             -- 첨부파일그룹사진1
                 , p_PHOTO_DESC_1           -- 사진설명1
                 , p_PHOTO_GRP2             -- 첨부파일그룹사진2
                 , p_PHOTO_DESC_2           -- 사진설명2
                 , p_NCR_PUBC_YN            -- 발행 1, 미발행 0
                 , p_NCR_DOC_NO             -- 부적합문서번호
                 , p_MA_DDLN_DT             -- 조치기한일자
                 , p_VNDR_NOTI_YN           -- 업체통보여부
                 , p_VNDR_SEND_DT           -- 업체발송일자
                 , p_WRK_ID                 -- 입력ID
                 , SYSDATE()                -- 입력일시
                 , p_WRK_IP                 -- 입력IP
                 , p_WRK_ID                 -- 수정ID
                 , SYSDATE()                -- 수정일시
                 , p_WRK_IP                 -- 수정IP
                 )
            ;

    END IF;

    ELSIF (p_WRK_TP ='D') THEN

        DELETE
          FROM TQHA_DAYSAFE_CHKLST
         WHERE SIT_CD           = p_SIT_CD          -- 현장코드
           AND PLN_YM           = p_PLN_YM          -- 계획년월
           AND PLN_DGR          = p_PLN_DGR         -- 차수구분코드(QS005) 1 1차,2 2차
           AND ODAY_CHK_DT      = p_ODAY_CHK_DT     -- 일일점검일자
           AND CTP_CD           = p_CTP_CD          -- 공종코드
           AND CHK_ITM_CD       = p_CHK_ITM_CD      -- 점검항목코드
           AND UNT_CD           = p_UNT_CD          -- 단위코드
        ;

    ELSIF (p_WRK_TP ='U') THEN

        UPDATE TQHA_DAYSAFE_CHKLST
           SET CUST_CD              = p_CUST_CD                 -- 협력업체코드
             , VNDR_SEQ             = p_VNDR_SEQ                -- 업체순번
             , ODAY_CHK_RSLT        = p_ODAY_CHK_RSLT           -- 점검결과(QS006) 1 N/A,2 완료(유지),3 불량
             , ODAY_CHK_OPIN        = p_ODAY_CHK_OPIN           -- 일일점검의견
             , ODAY_INSP            = p_ODAY_INSP               -- 일일점검자
             , PHOTO_GRP1           = p_PHOTO_GRP1              -- 첨부파일그룹사진1
             , PHOTO_DESC_1         = p_PHOTO_DESC_1            -- 사진설명1
             , PHOTO_GRP2           = p_PHOTO_GRP2              -- 첨부파일그룹사진2
             , PHOTO_DESC_2         = p_PHOTO_DESC_2            -- 사진설명2
             , NCR_PUBC_YN          = p_NCR_PUBC_YN             -- 발행 1, 미발행 0
             , NCR_DOC_NO           = p_NCR_DOC_NO              -- 부적합문서번호
             , MA_DDLN_DT           = p_MA_DDLN_DT              -- 조치기한일자
             , VNDR_NOTI_YN         = p_VNDR_NOTI_YN            -- 업체통보여부
             , VNDR_SEND_DT         = p_VNDR_SEND_DT            -- 업체발송일자
             , UPD_ID               = p_WRK_ID                  -- 수정ID
             , UPD_DTM              = SYSDATE()                 -- 수정일시
             , UPD_IP               = p_WRK_IP                  -- 수정IP
         WHERE SIT_CD               = p_SIT_CD                  -- 현장코드
           AND PLN_YM               = p_PLN_YM                  -- 계획년월
           AND PLN_DGR              = p_PLN_DGR                 -- 차수구분코드(QS005) 1 1차,2 2차
           AND ODAY_CHK_DT          = p_ODAY_CHK_DT             -- 일일점검일자
           AND CTP_CD               = p_CTP_CD                  -- 공종코드
           AND CHK_ITM_CD           = p_CHK_ITM_CD              -- 점검항목코드
           AND UNT_CD               = p_UNT_CD                  -- 단위코드
        ;

    ELSE

        INSERT 
          INTO TQHA_DAYSAFE_CHKLST
             ( SIT_CD                   -- 현장코드
             , PLN_YM                   -- 계획년월
             , PLN_DGR                  -- 차수구분코드(QS005) 1 1차,2 2차
             , ODAY_CHK_DT              -- 일일점검일자
             , CTP_CD                   -- 공종코드
             , CHK_ITM_CD               -- 점검항목코드
             , UNT_CD                   -- 단위코드
             , CUST_CD                  -- 협력업체코드
             , VNDR_SEQ                 -- 업체순번
             , ODAY_CHK_RSLT            -- 점검결과(QS006) 1 N/A,2 완료(유지),3 불량
             , ODAY_CHK_OPIN            -- 일일점검의견
             , ODAY_INSP                -- 일일점검자
             , PHOTO_GRP1               -- 첨부파일그룹사진1
             , PHOTO_DESC_1             -- 사진설명1
             , PHOTO_GRP2               -- 첨부파일그룹사진2
             , PHOTO_DESC_2             -- 사진설명2
             , NCR_PUBC_YN              -- 발행 1, 미발행 0
             , NCR_DOC_NO               -- 부적합문서번호
             , MA_DDLN_DT               -- 조치기한일자
             , VNDR_NOTI_YN             -- 업체통보여부
             , VNDR_SEND_DT             -- 업체발송일자
             , IPT_ID                   -- 입력ID
             , IPT_DTM                  -- 입력일시
             , IPT_IP                   -- 입력IP
             , UPD_ID                   -- 수정ID
             , UPD_DTM                  -- 수정일시
             , UPD_IP                   -- 수정IP
             )
        VALUES 
             ( p_SIT_CD                 -- 현장코드
             , p_PLN_YM                 -- 계획년월
             , p_PLN_DGR                -- 차수구분코드(QS005) 1 1차,2 2차
             , p_ODAY_CHK_DT            -- 일일점검일자
             , p_CTP_CD                 -- 공종코드
             , p_CHK_ITM_CD             -- 점검항목코드
             , p_UNT_CD                 -- 단위코드
             , p_CUST_CD                -- 협력업체코드
             , p_VNDR_SEQ               -- 업체순번
             , p_ODAY_CHK_RSLT          -- 점검결과(QS006) 1 N/A,2 완료(유지),3 불량
             , p_ODAY_CHK_OPIN          -- 일일점검의견
             , p_ODAY_INSP              -- 일일점검자
             , p_PHOTO_GRP1             -- 첨부파일그룹사진1
             , p_PHOTO_DESC_1           -- 사진설명1
             , p_PHOTO_GRP2             -- 첨부파일그룹사진2
             , p_PHOTO_DESC_2           -- 사진설명2
             , p_NCR_PUBC_YN            -- 발행 1, 미발행 0
             , p_NCR_DOC_NO             -- 부적합문서번호
             , p_MA_DDLN_DT             -- 조치기한일자
             , p_VNDR_NOTI_YN           -- 업체통보여부
             , p_VNDR_SEND_DT           -- 업체발송일자
             , p_WRK_ID                 -- 입력ID
             , SYSDATE()                -- 입력일시
             , p_WRK_IP                 -- 입력IP
             , p_WRK_ID                 -- 수정ID
             , SYSDATE()                -- 수정일시
             , p_WRK_IP                 -- 수정IP
             )
        ;

    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 5. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);

END ;
/

-- PQHA_DAYSAFE_DT_B (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_DAYSAFE_DT_B" ( -- 해당년월회차의 일일안전점검 일자 생성
    p_WRK_TP                VARCHAR2 :='I'                              -- UPDATE FLAG( I: ISNERT, U:UPDATE, D:DELTE)
,   p_WRK_ID                VARCHAR2                                    -- 사용자 ID
,   p_WRK_IP                VARCHAR2                                    -- 사용자 IP
,   p_SIT_CD                TQHA_DAYSAFE_DT.SIT_CD          %TYPE       -- 현장코드
,   p_PLN_YM                TQHA_DAYSAFE_DT.PLN_YM          %TYPE       -- 계획년월
,   p_PLN_DGR               TQHA_DAYSAFE_DT.PLN_DGR         %TYPE       -- 계획차수
,   p_ODAY_CHK_SDT          TQHA_DAYSAFE_DT.ODAY_CHK_DT     %TYPE       -- 일일점검 시작일자
,   p_ODAY_CHK_FDT          TQHA_DAYSAFE_DT.ODAY_CHK_DT     %TYPE       -- 일일점검 종료일자
)
IS
    /**************************************************************************************************************************
      Purpose : 해당년월회차의 일일안전점검 일자 생성

      REVISIONS
      Ver      Date               Author                  Description
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2021/12/17 14:24:00                         최초생성

    **************************************************************************************************************************/

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE        NUMBER :=-20009;        -- ERROR 코드
    ERR_MSG         VARCHAR2(200);          -- ERROR Message
    USER_EXCEPTION EXCEPTION;

    v_cnt           INTEGER;                -- 일일안전 점검일자 존재여부 체크

BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 필수입력 필드  Check  ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_SIT_CD IS NULL)  THEN
        ERR_MSG := '현장코드는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_ODAY_CHK_SDT IS NULL)  THEN
        ERR_MSG := '일일점검 시작일자는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Process 선행조건 Check ]
    ---------------------------------------------------------------------------------------------------------------------------



    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Business Process ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_WRK_TP ='I') THEN


        /**** 일일 안전점검일자 생성 및 점검항목 생성 ******/
        BEGIN
            FOR DAYSAFE IN (  -- 계획년월 차수의 시작일자 부터 종료일자까지 생성하기 위한 FOR문
                            SELECT TO_CHAR(TO_DATE(CHK_SDT,'YYYYMMDD') + LEVEL - 1 ,'YYYYMMDD') AS CHK_DT
                              FROM (SELECT p_ODAY_CHK_SDT AS CHK_SDT
                                         , p_ODAY_CHK_FDT AS CHK_FDT
                                      FROM  DUAL
                                   )
                            CONNECT BY LEVEL <= TO_DATE(CHK_FDT,'YYYYMMDD' ) - TO_DATE(CHK_SDT,'YYYYMMDD' ) + 1
                           )
            LOOP

                -- 해당차수의 일일안전 점검일자 생성 여부 체크
                SELECT nvl(COUNT(ODAY_CHK_DT),0)
                  INTO v_cnt
                  FROM TQHA_DAYSAFE_DT
                 WHERE SIT_CD       = p_SIT_CD          -- 현장코드
                   AND ODAY_CHK_DT  = DAYSAFE.CHK_DT    -- 일일점검일자
                ;

                -- 일일안전점검 일자가 없으면
                IF v_cnt < 1 THEN
                    -- 일일안전점검일자 생성
                    INSERT 
                      INTO TQHA_DAYSAFE_DT
                         ( SIT_CD               -- 현장코드
                         , ODAY_CHK_DT          -- 일일점검일자
                         , PLN_YM               -- 계획년월
                         , PLN_DGR              -- 계획차수
                         , IPT_ID               -- 입력ID
                         , IPT_DTM              -- 입력일시
                         , IPT_IP               -- 입력IP
                         , UPD_ID               -- 수정ID
                         , UPD_DTM              -- 수정일시
                         , UPD_IP               -- 수정IP
                         )
                    VALUES 
                         ( p_SIT_CD             -- 현장코드
                         , DAYSAFE.CHK_DT       -- 일일점검일자
                         , p_PLN_YM             -- 계획년월
                         , p_PLN_DGR            -- 계획차수
                         , p_WRK_ID             -- 입력ID
                         , SYSDATE()            -- 입력일시
                         , p_WRK_IP             -- 입력IP
                         , p_WRK_ID             -- 수정ID
                         , SYSDATE()            -- 수정일시
                         , p_WRK_IP             -- 수정IP
                         )
                    ;

                END IF;
            END LOOP;
        END;

    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 5. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);

END PQHA_DAYSAFE_DT_B;
/

-- PQHA_DAYSAFE_DT_S (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_DAYSAFE_DT_S" (
    p_WRK_TP            VARCHAR2 :='U'                  -- UPDATE FLAG( I: ISNERT, U:UPDATE, D:DELTE)
,   p_WRK_ID            VARCHAR2                        -- 사용자 ID 
,   p_WRK_IP            VARCHAR2                        -- 사용자 IP 
,   p_SIT_CD            TQHA_RISK_DGR.SIT_CD%TYPE       -- 현장코드
,   p_ODAY_CHK_DT       VARCHAR2                        -- 일일점검일자
,   p_MNG_SUPR          VARCHAR2                        -- 관리자ID
,   p_MNG_APRV_DT       VARCHAR2                        -- 관리자 승인일자
,   p_MNG_APRV_STATS    VARCHAR2                        -- 관리자 승인여부
,   p_SAFT_MGR          VARCHAR2                        -- 안전관리자ID
,   p_SAFT_APRV_DT      VARCHAR2                        -- 안전관리자 승인일자
,   p_SAFT_APRV_STATS   VARCHAR2                        -- 안전관리자 승인여부
,   p_SITE_OMGR         VARCHAR2                        -- 현장소장ID
,   p_SITE_APRV_DT      VARCHAR2                        -- 현장소장 승인일자
,   p_SITE_APRV_STATS   VARCHAR2                        -- 현장소장 승인여부
)
IS 
    /**************************************************************************************************************************
      Purpose : 

      REVISIONS
      Ver      Date               Author                  Description 
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2026/02/09                                   최초생성

    **************************************************************************************************************************/

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR2(200);            -- ERROR Message
    USER_EXCEPTION EXCEPTION;

    v_cnt  INTEGER;                             -- 위험성 평가 일정 하위데이타 존재 여부

BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 필수입력 필드  Check  ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_SIT_CD IS NULL)  THEN
        ERR_MSG := '현장코드는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_ODAY_CHK_DT IS NULL)  THEN
        ERR_MSG := '일일점검일자는(은) 필수 입력사항 입니다.'; 
        RAISE USER_EXCEPTION;
    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Process 선행조건 Check ]
    ---------------------------------------------------------------------------------------------------------------------------



    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Business Process ]
    ---------------------------------------------------------------------------------------------------------------------------

    ----------------------------------------------------------------------------------------------------
    -- 그리드 저장 : 일일안전점검 작성 - 일일안전점검목록
    IF (p_WRK_TP ='U') THEN

        UPDATE TQHA_DAYSAFE_DT
           SET MNG_SUPR                 = p_MNG_SUPR                -- 관리자ID
             , MNG_APRV_DT              = p_MNG_APRV_DT             -- 관리자 승인일자
             , MNG_APRV_STATS           = p_MNG_APRV_STATS          -- 관리자 승인여부
             , SAFT_MGR                 = p_SAFT_MGR                -- 안전관리자ID
             , SAFT_APRV_DT             = p_SAFT_APRV_DT            -- 안전관리자 승인일자
             , SAFT_APRV_STATS          = p_SAFT_APRV_STATS         -- 안전관리자 승인여부
             , SITE_OMGR                = p_SITE_OMGR               -- 현장소장ID
             , SITE_APRV_DT             = p_SITE_APRV_DT            -- 현장소장 승인일자
             , SITE_APRV_STATS          = p_SITE_APRV_STATS         -- 현장소장 승인여부
             , UPD_ID                   = p_WRK_ID
             , UPD_DTM                  = SYSDATE
         WHERE SIT_CD                   = p_SIT_CD                  -- 현장코드
           AND ODAY_CHK_DT              = p_ODAY_CHK_DT             -- 일일점검일자
        ;

    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 5. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN 
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);
END ;
/

-- PQHA_DAY_SAFT_CHK_REG_OTHER_Q (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_DAY_SAFT_CHK_REG_OTHER_Q" (
    p_WRK_TP            IN VARCHAR2 DEFAULT 'Q'         -- FLAG
,   p_SIT_CD            IN VARCHAR2                     -- 현장코드
,   p_PLN_YM            IN VARCHAR2                     -- 계획연월
,   p_PLN_DGR           IN VARCHAR2                     -- 계획차수
,   p_ODAY_CHK_DT       IN VARCHAR2                     -- 일일점검일자
,   p_RISK_GRD          IN VARCHAR2                     -- 점검구분
,   RTN_CURSOR          OUT SYS_REFCURSOR
)
IS
    /**************************************************************************************************************************
      Purpose : [일일안전점검] PROCEDRE 

      REVISIONS
      Ver      Date               Author                  Description
      -------  -----------------  ----------------------  ---------------------------------------------------------------------
      1.0      2026/02/09                                 최초생성

    **************************************************************************************************************************/

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE  NUMBER :=-20009; -- ERROR 코드
    ERR_MSG   VARCHAR(200);    -- ERROR Message
    USER_EXCEPTION EXCEPTION;

BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 수행전 Check Logic ]
    ---------------------------------------------------------------------------------------------------------------------------

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Logic 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------

    ---------------------------------------------------------------------------------------
    -- 
    IF p_WRK_TP = 'Q1' THEN

        -- 그리드 조회 : 일일안전점검 작성 - 일일안전점검목록
        OPEN RTN_CURSOR FOR
        	SELECT  A.SIT_CD                 --현장코드
		           ,A.PLN_YM                 --계획년월
		           ,A.PLN_DGR                 --차수구분코드(QS005) 1 1차,2 2차
		           ,A.CUST_CD                 --협력업체코드
		           ,A.VNDR_SEQ                 --업체순번   
		           ,(SELECT CUST_NM FROM VQSZ_TRADE WHERE CUST_CD = A.CUST_CD) AS CUST_NM
		           ,A.CTP_CD                 --공종코드
		           ,(SELECT CTP_NM FROM TQHA_CTP WHERE CTP_CD = A.CTP_CD) AS CTP_NM
		           ,A.UNT_CD                 --단위코드
		           ,(SELECT UNT_NM FROM TQHA_CTPUNT WHERE CTP_CD = A.CTP_CD AND UNT_CD = A.UNT_CD) AS UNT_NM
		           ,A.CHK_LOC
		           ,A.CHK_ITM_CD                 --점검항목코드
		           ,A.CHK_ITM_SEQ
				   ,A.CHK_ITM_NM
		           ,A.IMPRV_CPLN                 --개선대책
		           ,A.MGR_OPIN                 --관리자의견
		           ,B.RISK_GRD
		           ,B.ODAY_CHK_DT
		           ,B.ODAY_CHK_RSLT                 --점검결과(QS006) 1 N/A,2 완료(유지),3 불량
		           ,B.ODAY_CHK_OPIN                 --일일안전책임자 점검의견
		           ,B.EMPE_NO                 --일일안전책임자 사번
		           ,(SELECT USR_NM FROM TCOZ_USR_INFO WHERE EMPNO = B.EMPE_NO) AS USR_NM
		           ,B.PHOTO_GRP1                 --첨부파일그룹사진1
		           ,B.PHOTO_DESC_1                 --사진설명1
		           ,B.PHOTO_GRP2                 --첨부파일그룹사진2
		           ,B.PHOTO_DESC_2                 --사진설명2
		           ,B.NCR_PUBC_YN                 --발행 1, 미발행 0
		           ,B.VNDR_NOTI_YN                 --발송 1 미발송0
		           ,B.VNDR_SEND_DT                 --업체발송일자
		           ,B.VNDR_MA_YN                 --조치구분(QS007) 1 조치, 0 미조치
		           ,B.NCR_DOC_NO                    -- 부적합문서번호
		           ,C.APRS_STR_DT
				  , C.APRS_END_DT				 
				  , ( SELECT CUST_NM FROM VQSZ_TRADE WHERE CUST_CD = D.CUST_CD ) AS VNDR_NM
	              , ( SELECT CD_NM FROM TCOA_COMCODE WHERE COM_CD = D.VNDR_MA_YN AND HRNK_CD = 'QS025') AS VNDR_MA_YN_NM
	              , D.MA_DDLN_DT
	              , D.VNDR_MA_DT
	              , DECODE((SELECT USR_NM FROM TCOZ_USR_INFO WHERE USR_ID = D.VNDR_MA_PSN), '', D.VNDR_MA_PSN, (SELECT USR_NM FROM TCOZ_USR_INFO WHERE USR_ID = D.VNDR_MA_PSN)) AS VNDR_MA_PSN_NM				  
		          FROM TQHB_RISK_LST A
		             , TQHB_DAYSAFE_CHKLST B
		             , TQHB_RISK_DGR C
		             , TQHA_NCR_REP D
		         WHERE A.SIT_CD             = p_SIT_CD
		           AND A.PLN_YM             = p_PLN_YM
		           AND A.PLN_DGR            = p_PLN_DGR
		           AND B.RISK_GRD           = p_RISK_GRD
		           AND B.ODAY_CHK_DT(+)     = p_ODAY_CHK_DT
		           AND A.SIT_CD             = B.SIT_CD(+)
		           AND A.PLN_YM             = B.PLN_YM(+)
		           AND A.PLN_DGR            = B.PLN_DGR(+)
		           AND A.CUST_CD            = B.CUST_CD(+)
		           AND A.VNDR_SEQ           = B.VNDR_SEQ(+)
		           AND A.CTP_CD             = B.CTP_CD(+)
		           AND A.UNT_CD             = B.UNT_CD(+)
		           AND A.CHK_ITM_CD         = B.CHK_ITM_CD(+)
		           AND A.RISK_GRD           = B.RISK_GRD(+)
		           AND A.SIT_CD             = C.SIT_CD(+)
		           AND A.PLN_YM             = C.PLN_YM(+)
		           AND A.PLN_DGR            = C.PLN_DGR(+)
		           AND B.SIT_CD             = D.SIT_CD(+)
		           AND B.NCR_DOC_NO         = D.NCR_DOC_NO(+)
		     ORDER BY A.CUST_CD, A.CTP_CD, A.UNT_CD
		           
        ;

    ---------------------------------------------------------------------------------------
    ELSIF p_WRK_TP = 'Q2' THEN

        -- 그리드 조회 : 조회조건 - 점검일자
        OPEN RTN_CURSOR FOR
        SELECT APRS_STR_DT    -- 평가시작일
             , APRS_END_DT    -- 평가종료일
          FROM TQHB_RISK_DGR A
         WHERE A.SIT_CD     = p_SIT_CD
           AND A.PLN_YM     = p_PLN_YM
           AND A.PLN_DGR    = p_PLN_DGR
        ;

    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
         WHEN OTHERS THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);

END PQHA_DAY_SAFT_CHK_REG_OTHER_Q;
/

-- PQHA_DEEDU_CD_Q (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_DEEDU_CD_Q" (
    p_WRK_TP            VARCHAR2 DEFAULT 'Q'                    -- FLAG( Q: SELECT )
,   p_EDU_CD            TQHA_DEEDU_CD.EDU_CD        %TYPE       -- 교육코드
,   RTN_CURSOR          OUT SYS_REFCURSOR
) 
