            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN 
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);
END ;
/

-- PQHA_DEEDU_CD_S (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_DEEDU_CD_S" (
    p_WRK_TP                VARCHAR2 :='U'                                      -- UPDATE FLAG( I: ISNERT, U:UPDATE, D:DELTE)
,   p_WRK_ID                VARCHAR2                                            -- 사용자 ID
,   p_WRK_IP                VARCHAR2                                            -- 사용자 IP
,   p_EDU_CD                TQHA_DEEDU_CD.EDU_CD                %TYPE           -- 교육코드
,   p_DEEDU_CD              TQHA_DEEDU_CD.DEEDU_CD              %TYPE           -- 세부교육코드
,   p_DEEDU_NM              TQHA_DEEDU_CD.DEEDU_NM              %TYPE           -- 세부교육코드명
,   p_DEEDU_CTS             TQHA_DEEDU_CD.DEEDU_CTS             %TYPE           -- 교육내용
,   p_SPCL_CTS              TQHA_DEEDU_CD.SPCL_CTS              %TYPE           -- 개별교욱내용
,   p_EDU_TIME              TQHA_DEEDU_CD.EDU_TIME              %TYPE           -- 교육시간
,   p_USE_YN                TQHA_DEEDU_CD.USE_YN                %TYPE           -- 사용 1 미사용 0
) 
IS
    /**************************************************************************************************************************
      Purpose : 세부교육내용 저장

      REVISIONS
      Ver      Date               Author                  Description
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2024/02/21 10:30:02                         최초생성

    **************************************************************************************************************************/


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR2(200);            -- ERROR Message
    USER_EXCEPTION EXCEPTION;

     v_DEEDU_CD     TQHA_DEEDU_CD.DEEDU_CD  %TYPE;      -- 세부교육코드 변수 선언
     v_cnt          INTEGER;                            -- 세부 교육항목 이 교육일지에서 사용 존재 여부

BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 필수입력 필드  Check  ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_EDU_CD IS NULL)  THEN
        ERR_MSG := '교육코드는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_DEEDU_NM IS NULL )  THEN
        ERR_MSG := '세부 교육명칭는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;


      --  세부 교육코드가 교육일지에서  존재 여부 확인
    IF p_WRK_TP = 'D' THEN

        SELECT nvl(COUNT(DEEDU_CD),0)
          INTO v_cnt
          FROM TQHA_EDU
         WHERE EDU_CD       = p_EDU_CD
           AND DEEDU_CD     = p_DEEDU_CD
        ;

         -- 단위작업 코드 Validation
        IF v_cnt > 0 THEN
           ERR_MSG := '세부 교육항목 "' || p_DEEDU_NM || '" 은(는) 교육일지에서 이미 사용중입니다. 이미 사용중인 세부 교육항목을 삭제할 수 없습니다. ';
           RAISE USER_EXCEPTION;
        END IF;
    END IF;
    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Process 선행조건 Check ]
    ---------------------------------------------------------------------------------------------------------------------------



    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Business Process ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_WRK_TP ='D') THEN

        DELETE
          FROM TQHA_DEEDU_CD
         WHERE EDU_CD       = p_EDU_CD          -- 교육코드
           AND DEEDU_CD     = p_DEEDU_CD        -- 세부교육코드
        ;

    ELSIF (p_WRK_TP ='U') THEN

        UPDATE TQHA_DEEDU_CD
           SET DEEDU_NM             = p_DEEDU_NM        -- 세부교육코드명
             , DEEDU_CTS            = p_DEEDU_CTS       -- 교육내용
             , SPCL_CTS             = p_SPCL_CTS        -- 개별교육내용
             , EDU_TIME             = p_EDU_TIME        -- 교육시간
             , USE_YN               = p_USE_YN          -- 사용 1 미사용 0
             , UPD_ID               = p_WRK_ID          -- 수정ID
             , UPD_DTM              = SYSDATE()         -- 수정일시
             , UPD_IP               = p_WRK_IP          -- 수정IP
         WHERE EDU_CD               = p_EDU_CD          -- 교육코드
           AND DEEDU_CD             = p_DEEDU_CD        -- 세부교육코드
        ;

    ELSE

        -- 단위코드 MAX부여
        SELECT LPAD(NVL(MAX(SUBSTR(DEEDU_CD, 1, 4)), 0) + 1, 4,'0')
          INTO v_DEEDU_CD
          FROM TQHA_DEEDU_CD
         WHERE EDU_CD = p_EDU_CD 
        ;
        --

        INSERT 
          INTO TQHA_DEEDU_CD
             ( EDU_CD               -- 교육코드
             , DEEDU_CD             -- 세부교육코드
             , DEEDU_NM             -- 세부교육코드명
             , DEEDU_CTS            -- 교육내용
             , SPCL_CTS             -- 개별교육내용
             , EDU_TIME
             , USE_YN               -- 사용 1 미사용 0
             , IPT_ID               -- 입력ID
             , IPT_DTM              -- 입력일시
             , IPT_IP               -- 입력IP
             , UPD_ID               -- 수정ID
             , UPD_DTM              -- 수정일시
             , UPD_IP               -- 수정IP
             )
        VALUES 
             ( p_EDU_CD             -- 교육코드
             , v_DEEDU_CD           -- 세부교육코드
             , p_DEEDU_NM           -- 세부교육코드명
             , p_DEEDU_CTS          -- 교육내용
             , p_SPCL_CTS           -- 개별교육내용
             , p_EDU_TIME
             , p_USE_YN             -- 사용 1 미사용 0
             , p_WRK_ID             -- 입력ID
             , SYSDATE()            -- 입력일시
             , p_WRK_IP             -- 입력IP
             , p_WRK_ID             -- 수정ID
             , SYSDATE()            -- 수정일시
             , p_WRK_IP             -- 수정IP
             )
        ;

    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 5. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);

END ;
/

