-- PQHA_DISASTER_CD_S (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_DISASTER_CD_S"
                            (p_WRK_TP  VARCHAR2 :='U'                                     -- UPDATE FLAG( I: ISNERT, U:UPDATE, D:DELTE)
                            ,p_WRK_ID  VARCHAR2                                           -- 사용자 ID 
                            ,p_WRK_IP  VARCHAR2                                           -- 사용자 IP 
                            ,p_DIV_CD TQHA_DISASTER_CD.DIV_CD%TYPE                        -- 구분코드
                            ,p_DIS_CD TQHA_DISASTER_CD.DIS_CD%TYPE                        -- 발생형태코드
                            ,p_DIS_NM TQHA_DISASTER_CD.DIS_NM%TYPE                        -- 발생형태명칭
                            ,p_USE_YN TQHA_DISASTER_CD.USE_YN%TYPE)                       -- 사용 1 미사용 0
IS 
    /**************************************************************************************************************************
      Purpose : 

      REVISIONS
      Ver      Date               Author                  Description 
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2026/08/12 16:19:48                         최초생성

    /**************************************************************************************************************************/


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR2(200);            -- ERROR Message
    USER_EXCEPTION EXCEPTION;

	v_CNT NUMBER;
BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 필수입력 필드  Check  ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_DIV_CD IS NULL)  THEN
        ERR_MSG := '구분코드는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_DIS_CD IS NULL)  THEN
        ERR_MSG := '발생형태코드는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Process 선행조건 Check ]
    ---------------------------------------------------------------------------------------------------------------------------



    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Business Process ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_WRK_TP ='D') THEN
        DELETE 
          FROM TQHA_DISASTER_CD
         WHERE DIV_CD = p_DIV_CD          --구분코드
           AND DIS_CD = p_DIS_CD;         --발생형태코드

    ELSIF (p_WRK_TP ='U') THEN
        UPDATE TQHA_DISASTER_CD
           SET DIS_NM               = p_DIS_NM                  --발생형태명칭
              ,USE_YN               = p_USE_YN                  --사용 1 미사용 0
              ,UPD_ID               = p_WRK_ID                  --수정ID 
              ,UPD_DTM              = SYSDATE()                 --수정일시
              ,UPD_IP               = p_WRK_IP                  --수정IP
         WHERE DIV_CD = p_DIV_CD          --구분코드
           AND DIS_CD = p_DIS_CD;         --발생형태코드
    ELSE 
    
    	SELECT COUNT(1) INTO v_CNT
		FROM TQHA_DISASTER_CD
		WHERE DIV_CD = p_DIV_CD
		  AND DIS_CD = p_DIS_CD
		;
	    
	    IF (v_CNT > 0)  THEN
	        ERR_MSG := '이미 등록된 발생형태코드 입니다.';
	        RAISE USER_EXCEPTION;
	    END IF;
	     
        INSERT INTO TQHA_DISASTER_CD
                   ( DIV_CD                  --구분코드
                    ,DIS_CD                  --발생형태코드
                    ,DIS_NM                  --발생형태명칭
                    ,USE_YN                  --사용 1 미사용 0
                    ,IPT_ID                  --입력ID
                    ,IPT_DTM                 --입력일시
                    ,IPT_IP                  --입력IP
                    ,UPD_ID                  --수정ID
                    ,UPD_DTM                 --수정일시
                    ,UPD_IP                  --수정IP
                    )
             VALUES (p_DIV_CD                --구분코드
                    ,p_DIS_CD                --발생형태코드
                    ,p_DIS_NM                --발생형태명칭
                    ,p_USE_YN                --사용 1 미사용 0
                    ,p_WRK_ID                --입력ID 
                    ,SYSDATE()               --입력일시
                    ,p_WRK_IP                --입력IP
                    ,p_WRK_ID                --수정ID
                    ,SYSDATE()               --수정일시
                    ,p_WRK_IP);              --수정IP
    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 5. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN 
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);
END ;
/

