,   p_REG_NO        TQHA_DRM_ANNC.REG_NO%TYPE       -- 등록번호
,   RTN_CURSOR      OUT SYS_REFCURSOR
)
IS 
    /**************************************************************************************************************************
      Purpose : 

      REVISIONS
      Ver      Date               Author                  Description 
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2026/01/30 13:57:26                         최초생성

    /**************************************************************************************************************************/


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR2(200);            -- ERROR Message
    USER_EXCEPTION EXCEPTION;


BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 수행전 Check Logic ]
    ---------------------------------------------------------------------------------------------------------------------------


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Logic 처리
    ---------------------------------------------------------------------------------------------------------------------------

    OPEN RTN_CURSOR FOR
    SELECT A.REG_NO                 -- 등록번호
         , A.EMPNO                  -- 사번
         , B.USR_NM                 -- 성명
         , A.ANNC_DTM               -- 공지일시
         , B.MAIL_ADDR              -- 메일
         , A.IPT_ID                 -- 입력자
         , A.IPT_DTM                -- 입력일시
         , A.IPT_IP                 -- 입력IP
         , A.UPD_ID                 -- 수정자
         , A.UPD_DTM                -- 수정일시
         , A.UPD_IP                 -- 수정IP
      FROM TQHA_DRM_ANNC        A
     INNER JOIN TCOZ_USR_INFO   B ON A.EMPNO = B.USR_ID
     WHERE REG_NO = p_REG_NO        -- 등록번호
    ;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN 
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);
END ;
/

-- PQHA_DRM_ANNC_S (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_DRM_ANNC_S" (
    p_WRK_TP            VARCHAR2 :='U'                          -- UPDATE FLAG( I: ISNERT, U:UPDATE, D:DELTE)
,   p_WRK_ID            VARCHAR2                                -- 사용자 ID 
,   p_WRK_IP            VARCHAR2                                -- 사용자 IP 
,   p_REG_NO            TQHA_DRM_ANNC.REG_NO        %TYPE       -- 등록번호
,   p_EMPNO             TQHA_DRM_ANNC.EMPNO         %TYPE       -- 사번
,   p_BLT_MAIL          TQHA_DRM.BLT_MAIL           %TYPE       -- 메일전송여부
,   p_BLT_SMS           TQHA_DRM.BLT_SMS            %TYPE       -- SMS전송여부
)
IS 
    /**************************************************************************************************************************
      Purpose : 

      REVISIONS
      Ver      Date               Author                  Description 
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2026/01/30 13:58:41                         최초생성

    /**************************************************************************************************************************/


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR2(200);            -- ERROR Message
    USER_EXCEPTION EXCEPTION;


BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 필수입력 필드  Check  ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_REG_NO IS NULL)  THEN
        ERR_MSG := '등록번호는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_EMPNO IS NULL)  THEN
        ERR_MSG := '사번는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Process 선행조건 Check ]
    ---------------------------------------------------------------------------------------------------------------------------



    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Business Process ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_WRK_TP ='D') THEN

        DELETE 
          FROM TQHA_DRM_ANNC
         WHERE REG_NO   = p_REG_NO          -- 등록번호
           AND EMPNO    = p_EMPNO           -- 사번
        ;
    ------------------------------------------------------------------------------------
    --
    ELSIF (p_WRK_TP ='U') THEN
        UPDATE TQHA_DRM_ANNC
           SET ANNC_DTM         = SYSDATE()         -- 공지일시
             , UPD_ID           = p_WRK_ID          -- 수정ID 
             , UPD_DTM          = SYSDATE()         -- 수정일시
             , UPD_IP           = p_WRK_IP          -- 수정IP
         WHERE REG_NO           = p_REG_NO          -- 등록번호
           AND EMPNO            = p_EMPNO           -- 사번
        ;

       -- 메일, SMS 전송여부
          UPDATE TQHA_DRM
           SET BLT_MAIL         = p_BLT_MAIL        -- 메일전송여부
             , BLT_SMS          = p_BLT_SMS         -- SMS전송여부
             , UPD_ID           = p_WRK_ID          -- 수정ID 
             , UPD_DTM          = SYSDATE()         -- 수정일시
             , UPD_IP           = p_WRK_IP          -- 수정IP
         WHERE REG_NO           = p_REG_NO          -- 등록번호
        ;

    ------------------------------------------------------------------------------------
    --
    ELSE 

        INSERT 
          INTO TQHA_DRM_ANNC
             ( REG_NO               -- 등록번호
             , EMPNO                -- 사번
             , ANNC_DTM             -- 공지일시
             , IPT_ID               -- 입력자
             , IPT_DTM              -- 입력일시
             , IPT_IP               -- 입력IP
             , UPD_ID               -- 수정자
             , UPD_DTM              -- 수정일시
             , UPD_IP               -- 수정IP
             )
        VALUES 
             ( p_REG_NO             -- 등록번호
             , p_EMPNO              -- 사번
             , SYSDATE()            -- 공지일시
             , p_WRK_ID             -- 입력ID 
             , SYSDATE()            -- 입력일시
             , p_WRK_IP             -- 입력IP
             , p_WRK_ID             -- 수정ID
             , SYSDATE()            -- 수정일시
             , p_WRK_IP             -- 수정IP
             )
        ;

        -- 메일, SMS 전송여부
        UPDATE TQHA_DRM
           SET BLT_MAIL         = p_BLT_MAIL        -- 메일전송여부
             , BLT_SMS          = p_BLT_SMS         -- SMS전송여부
             , UPD_ID           = p_WRK_ID          -- 수정ID 
             , UPD_DTM          = SYSDATE()         -- 수정일시
             , UPD_IP           = p_WRK_IP          -- 수정IP
         WHERE REG_NO           = p_REG_NO          -- 등록번호
        ;

    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 5. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN 
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);

END PQHA_DRM_ANNC_S;
/

