,   p_SEARCH_DATA_DIV   IN VARCHAR2             -- 자료구분
,   p_SEARCH_OTHER_SIT_INC  IN VARCHAR2         -- 타현장 자료
,   p_REG_NO            IN NUMBER               -- 등록번호
,   p_REG_DGR           IN NUMBER               -- 등록차수
,   p_ADM_YN            IN VARCHAR2             -- 자료실관리자 여부
,   RTN_CURSOR          OUT SYS_REFCURSOR
)
IS 
    /**************************************************************************************************************************
      Purpose : 

      REVISIONS
      Ver      Date               Author                  Description 
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2026/01/30 12:36:20                         최초생성
      1.1     2026/04/22                                  3레벨 구조로 변경 (DATA_SUB_DIV2 추가)

    /**************************************************************************************************************************/


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR2(200);            -- ERROR Message
    USER_EXCEPTION EXCEPTION;

    v_CURSOR        SYS_REFCURSOR;
    v_LIST          OQSA_DRM_INFO_LIST := OQSA_DRM_INFO_LIST();     -- TYPE OBJECT

    v_REG_NO           NUMBER       ;        -- 등록번호 (NVL 계산식에 숫자가 보여 NUMBER로 지정)
    v_REG_DGR          NUMBER       ;        -- 등록차수
    v_DATA_DIV         VARCHAR2(50) ;        -- 자료구분
    v_DATA_SUB_DIV     VARCHAR2(50) ;        -- 자료구분2
    v_DATA_SUB_DIV2    VARCHAR2(50) ;        -- 자료구분3
    v_DATA_DIV_NM      VARCHAR2(100);        -- 자료구분명
    v_DATA_SUB_DIV_NM  VARCHAR2(100);        -- 자료구분2명
    v_DATA_SUB_DIV2_NM VARCHAR2(100);        -- 자료구분3명
    v_DATA_NM          VARCHAR2(300);        -- 자료명
    v_DATA_DESC        CLOB         ;        -- 자료설명
    v_BLT_MAIL         VARCHAR2(10) ;        -- 게시우편물
    v_BLT_SMS          VARCHAR2(10) ;        -- 게시SMS
    v_ATFL_GRP         VARCHAR2(50) ;        -- 첨부파일 그룹
    v_SIT_CD           VARCHAR2(50) ;        -- 현장코드
    v_SIT_NM           VARCHAR2(200);        -- 현장명
    v_FNL_YN           VARCHAR2(1)  ;        -- 최종여부
    v_TAG              VARCHAR2(100);        -- 검색태그
    v_IPT_ID           VARCHAR2(50) ;        -- 입력자ID
    v_IPT_DTM          DATE         ;        -- 입력일시
    v_IPT_YMD          VARCHAR2(8)  ;        -- 입력일자(YYYYMMDD)
    v_VIEW_YN          VARCHAR2(1)  ;        -- 보기권한 ('1' or '0')
    v_APL_SEQ          NUMBER       ;        -- 열람신청번호
    v_APL_STATS        VARCHAR2(20) ;        -- 열람신청상태
    v_DEPT_CD          VARCHAR2(50) ;        -- 부서코드
    v_VIEW_CNT         NUMBER       ;        -- 조회수
    v_VIEW_STATS       VARCHAR2(100);        -- 열람상태(열람가능 등)
    v_VIEW_TERM        VARCHAR2(100);        -- 열람기간(YYYY-MM-DD~...)
    v_MNU_CD           VARCHAR(50);          -- 메뉴코드
    v_DATA_DIV_1       VARCHAR(20);          -- 자료구분
    v_DATA_DIV_2       VARCHAR(20);          -- 자료구분2
    v_DATA_DIV_3       VARCHAR(20);          -- 자료구분3
    v_EDT_YN           VARCHAR(1);           -- 수정권한
    v_WRTR_NM          VARCHAR(100);         -- 등록자명
BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 수행전 Check Logic ]
    ---------------------------------------------------------------------------------------------------------------------------


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Logic 처리
    ---------------------------------------------------------------------------------------------------------------------------

    IF (p_WRK_TP = 'Q') THEN

        OPEN RTN_CURSOR FOR
        SELECT
		      T1.REG_NO                                       -- 등록번호
		    , T1.REG_DGR                                      -- 등록차수
		    , T1.DATA_DIV                                     -- 자료구분
		    , T1.DATA_SUB_DIV                                 -- 자료구분2
		    , T1.DATA_SUB_DIV2                                -- 자료구분3
		    , T7.CD_NM                         AS DATA_DIV_NM
		    , T8.CD_NM                         AS DATA_SUB_DIV_NM
		    , T13.CD_NM                        AS DATA_SUB_DIV2_NM
		    , T1.DATA_NM                                      -- 자료명
		    , T1.DATA_DESC                                    -- 자료설명
		    , T1.BLT_MAIL                                     -- 게시우편물
		    , T1.BLT_SMS                                      -- 게시SMS
		    , T1.ATFL_GRP                                     -- 첨부파일
		    , T1.SIT_CD                                       -- 현장코드
		    , T10.SIT_NM
		    , T1.FNL_YN                                       -- 최종여부
		    , T1.TAG                                          -- 검색태그
		    , T1.IPT_ID
		    , T1.IPT_DTM
		    , TO_CHAR(T1.IPT_DTM, 'YYYYMMDD') AS IPT_YMD      -- 등록일
		    , CASE
		          WHEN NVL(T1.SIT_CD, '*') = '*'
		            OR NVL(T2.DEPT_CD, '*') != '*'
		            OR NVL(T5.REG_NO, -1) != -1
		          THEN '1'
		          ELSE '0'
		      END AS VIEW_YN                                  -- 보기권한
		    , CASE
		          WHEN NVL(T1.SIT_CD, '*') = '*'
		            OR NVL(T2.DEPT_CD, '*') != '*'
		            OR NVL(T5.REG_NO, -1) != -1
		          THEN 0
		          ELSE T6.APL_SEQ
		      END AS APL_SEQ                                  -- 열람신청번호
		    , T6.APL_STATS
		    , T2.DEPT_CD                                      -- 부서코드(현장코드)-권한여부
		    , T9.VIEW_CNT
		    , CASE
		          WHEN NVL(T1.SIT_CD, '*') = '*'
		            OR NVL(T2.DEPT_CD, '*') != '*'
		          THEN '열람가능'
		          WHEN NVL(T5.READ_STR_DD, '*') = '*'
		          THEN ''
		          ELSE NVL(T5.VIEW_STATS, T11.CD_NM)
		      END AS VIEW_STATS
		    , CASE
		          WHEN NVL(T5.READ_STR_DD, '*') = '*'
		          THEN ''
		          ELSE TO_CHAR(TO_DATE(T5.READ_STR_DD, 'YYYYMMDD'), 'YYYY-MM-DD')
		               || '~' ||
		               TO_CHAR(TO_DATE(T5.READ_END_DD, 'YYYYMMDD'), 'YYYY-MM-DD')
		      END AS VIEW_TERM
		    , p_WRK_MNU AS MNU_CD
		    , T1.DATA_DIV AS DATA_DIV_1                       -- 자료구분 - CHAIN 연결 SELECT BOX로 별도 추가.
		    , T1.DATA_SUB_DIV AS DATA_DIV_2                   -- 자료구분2
		    , T1.DATA_SUB_DIV2 AS DATA_DIV_3                  -- 자료구분3
		    , CASE
		          WHEN p_ADM_YN = '1' OR p_WRK_ID = T1.IPT_ID
		          THEN '1'
		          ELSE '0'
		      END AS EDT_YN                                   -- 수정권한여부. 일단 전사 권한은 무조건 수정 가능.
		    , T12.USR_NM AS WRTR_NM
		FROM TQHA_DRM T1
		LEFT JOIN TABLE(
		    FCOZ_USR_DEPT(
		          p_WRK_MNU
		        , p_WRK_ID
		        , p_WRK_CORP
		        , p_WRK_DEPT
		    )
		) T2
		    ON T1.SIT_CD = T2.DEPT_CD
		LEFT JOIN (
		    SELECT
		          ST4.REG_NO
		        , MAX(ST3.APL_SEQ) AS APL_SEQ
		        , MAX(ST3.READ_STR_DD) KEEP (DENSE_RANK LAST ORDER BY ST3.APL_SEQ) AS READ_STR_DD
		        , MAX(ST3.READ_END_DD) KEEP (DENSE_RANK LAST ORDER BY ST3.APL_SEQ) AS READ_END_DD
		        , '열람가능' AS VIEW_STATS
		    FROM TQHA_VIEW_REQ ST3
		    JOIN TQHA_VIEW_REQ_LST ST4
		        ON ST3.APL_SEQ = ST4.APL_SEQ
		    WHERE ST3.READ_STR_DD <= TO_CHAR(SYSDATE, 'YYYYMMDD')
		      AND ST3.READ_END_DD >= TO_CHAR(SYSDATE, 'YYYYMMDD')
		      AND ST3.APL_STATS = '003'                       -- 승인
		      AND ST3.REQ_USR_ID = p_WRK_ID
		    GROUP BY ST4.REG_NO
		) T5
		    ON T1.REG_NO = T5.REG_NO
		-- T5와 T6 차이는 일자를 포함하느냐의 차이로 별개로 구성. 아래는 열람기간에 상관없고, 승인되지 않은 건도 조회.
		LEFT JOIN (
		    SELECT
		          ST6.REG_NO
		        , MAX(ST5.APL_SEQ) AS APL_SEQ
		        , MAX(ST5.APL_STATS) KEEP (DENSE_RANK LAST ORDER BY ST5.APL_SEQ) AS APL_STATS
		    FROM TQHA_VIEW_REQ ST5
		    JOIN TQHA_VIEW_REQ_LST ST6
		        ON ST5.APL_SEQ = ST6.APL_SEQ
		    WHERE 1 = 1
		      AND ST5.REQ_USR_ID = p_WRK_ID
		    GROUP BY ST6.REG_NO
		) T6
		    ON T1.REG_NO = T6.REG_NO
		LEFT JOIN TCOA_COMCODE T7
		    ON T1.DATA_DIV = T7.COM_CD
		   AND T7.HRNK_CD = 'QS060'                           -- 자료구분
		LEFT JOIN TCOA_COMCODE T8
		    ON T1.DATA_SUB_DIV = T8.COM_CD
		   AND T8.HRNK_CD = T1.DATA_DIV
		LEFT JOIN TCOA_COMCODE T13
		    ON T1.DATA_SUB_DIV2 = T13.COM_CD
		   AND T13.HRNK_CD = T1.DATA_SUB_DIV
		LEFT JOIN (
		    SELECT
		          REG_NO
		        , REG_DGR
		        , COUNT(1) AS VIEW_CNT
		    FROM TQHA_VIEW_HIS T1
		    GROUP BY REG_NO, REG_DGR
		) T9
		    ON T1.REG_NO  = T9.REG_NO
		   AND T1.REG_DGR = T9.REG_DGR
		LEFT JOIN TCMZ_SIT T10
		    ON T1.SIT_CD = T10.SIT_CD
		LEFT JOIN TCOA_COMCODE T11
		    ON T6.APL_STATS = T11.COM_CD
		   AND T11.HRNK_CD  = 'QS061'
		LEFT JOIN TCOZ_USR_INFO T12
		    ON T1.IPT_ID = T12.USR_ID
		WHERE T1.FNL_YN = '1'
		  AND (
		        NVL(T1.SIT_CD, '*') = '*'
		        OR (
		            NVL(p_SEARCH_OTHER_SIT_INC, '0') = '1'
		            OR (
		                NVL(p_SIT_CD, '*') = '*'
		                OR T1.SIT_CD = p_SIT_CD
		            )
		        )
		      )
		  AND EXISTS (
		      SELECT
		            ST1.REG_NO
		          , ST1.DATA_NM || ST1.TAG || ST2.ATFL_ORI_NM || ST3.USR_NM
		      FROM TQHA_DRM ST1
		      LEFT JOIN TCOZ_ATFL ST2
		          ON ST1.ATFL_GRP = ST2.ATFL_GRP
		      LEFT JOIN TCOZ_USR_INFO ST3
		          ON ST1.IPT_ID = ST3.USR_ID
		      WHERE ST1.FNL_YN = '1'
		        AND ST1.DATA_NM || ST1.TAG || ST2.ATFL_ORI_NM || ST3.USR_NM
		            LIKE '%' || p_SEARCH_TEXT || '%'
		        AND T1.REG_NO = ST1.REG_NO
		  )
		  AND (
		        NVL(p_SEARCH_IPT_YM_FR, '*') = '*'
		        OR T1.IPT_DTM >= TO_DATE(p_SEARCH_IPT_YM_FR, 'YYYYMMDD')
		      )
		  AND (
		        NVL(p_SEARCH_IPT_YM_TO, '*') = '*'
		        OR T1.IPT_DTM < TO_DATE(p_SEARCH_IPT_YM_TO, 'YYYYMMDD') + 1
		      )
		  AND (
		        NVL(p_SEARCH_DATA_DIV, '*') = '*'
		        OR T1.DATA_DIV = p_SEARCH_DATA_DIV
		      )
		ORDER BY T1.IPT_DTM DESC
        ;

    --------------------------------------------------------------------------------------
    -- FORM 조회
    ELSIF (p_WRK_TP = 'Q1') THEN

        OPEN RTN_CURSOR FOR
        SELECT T1.REG_NO                --등록번호
             , T1.REG_DGR
             , T1.DATA_DIV              --자료구분
             , T1.DATA_SUB_DIV
             , T1.DATA_SUB_DIV2
             , T1.DATA_NM               --자료명
             , T1.DATA_DESC             --자료설명
             , T1.BLT_MAIL              --메일알림여부
             , T1.BLT_SMS               --SMS알림여부
             , T1.ATFL_GRP              --첨부파일그룹
             , T1.SIT_CD                --현장코드
             , T1.SIT_CD    AS SIT_CD2  --현장코드
             , T1.FNL_YN
             , T1.TAG
             , T1.IPT_ID                --입력자
             , T1.IPT_DTM               --입력일시
             , T1.IPT_IP                --입력IP
             , T1.UPD_ID                --수정자
             , T1.UPD_DTM               --수정일시
             , T1.UPD_IP                --수정IP
             , TO_CHAR(T1.IPT_DTM, 'YYYY-MM-DD')    AS REG_DD
             , TO_CHAR(T2.VIEW_CNT, 'FM9,990')      AS VIEW_CNT
             , T3.USR_NM                            AS WRTR_NM
             , T1.DATA_DIV                          AS DATA_DIV_1   -- 자료구분 - CHAIN 연결 SELECT BOX로 별도 추가.
             , T1.DATA_SUB_DIV                      AS DATA_DIV_2   -- 자료구분2
             , T1.DATA_SUB_DIV2                     AS DATA_DIV_3   -- 자료구분3
             , T4.SIT_NM                            AS SIT_NM
             , NVL(T4.SIT_NM, '전사공통')               AS SIT_NM2
--             , T4.SIT_NM                            AS SIT_NM3
             , CASE WHEN p_ADM_YN = '1' OR p_WRK_ID = T1.IPT_ID THEN '1' ELSE '0' END AS EDT_YN    -- 수정권한여부.  일단 전사 권한은 무조건 수정 가능.
             , p_ADM_YN                             AS ADM_YN
          FROM TQHA_DRM T1
          LEFT JOIN (SELECT REG_NO
                          , REG_DGR
                          , COUNT(1)    AS VIEW_CNT
                       FROM TQHA_VIEW_HIS T1
                      GROUP BY REG_NO, REG_DGR
                    )               T2 ON T1.REG_NO     = T2.REG_NO
                                      AND T1.REG_DGR    = T2.REG_DGR
          LEFT JOIN TCOZ_USR_INFO   T3 ON T1.IPT_ID     = T3.USR_ID
          LEFT JOIN TCMZ_SIT        T4 ON T1.SIT_CD     = T4.SIT_CD
         WHERE T1.REG_NO = p_REG_NO
           AND T1.REG_DGR = p_REG_DGR
        ;

    --------------------------------------------------------------------------------------
    -- TREE 조회
    ELSIF (p_WRK_TP = 'Q2') THEN

        PQHA_DRM_Q('Q'                      -- p_WRK_TP
                 , p_WRK_ID                 -- 입력자ID
                 , p_WRK_CORP               -- 법인
                 , p_WRK_DEPT               -- 부서
                 , p_WRK_MNU                -- 메뉴코드
                 , p_SIT_CD                 -- 현장코드
                 , p_SEARCH_TEXT            -- 검색어
                 , p_SEARCH_IPT_YM_FR       -- 조회기간 ST
                 , p_SEARCH_IPT_YM_TO       -- 조회기간 ED
                 , p_SEARCH_DATA_DIV        -- 자료구분
                 , p_SEARCH_OTHER_SIT_INC   -- 타현장 자료
                 , p_REG_NO                 -- 등록번호
                 , p_REG_DGR                -- 등록차수
                 , p_ADM_YN                 -- 자료실관리자 여부
                 , v_CURSOR 
                 );
        LOOP
            FETCH v_CURSOR INTO 
                  v_REG_NO
                , v_REG_DGR
                , v_DATA_DIV
                , v_DATA_SUB_DIV
                , v_DATA_SUB_DIV2
                , v_DATA_DIV_NM
                , v_DATA_SUB_DIV_NM
                , v_DATA_SUB_DIV2_NM
                , v_DATA_NM
                , v_DATA_DESC
                , v_BLT_MAIL
                , v_BLT_SMS
                , v_ATFL_GRP
                , v_SIT_CD
                , v_SIT_NM
                , v_FNL_YN
                , v_TAG
                , v_IPT_ID
                , v_IPT_DTM
                , v_IPT_YMD
                , v_VIEW_YN
                , v_APL_SEQ
                , v_APL_STATS
                , v_DEPT_CD
                , v_VIEW_CNT
                , v_VIEW_STATS
                , v_VIEW_TERM
                , v_MNU_CD
                , v_DATA_DIV_1
                , v_DATA_DIV_2
                , v_DATA_DIV_3
                , v_EDT_YN
                , v_WRTR_NM 
                ; 
            EXIT WHEN v_CURSOR%NOTFOUND;

            v_LIST.EXTEND;
            v_LIST(v_LIST.LAST) := OQSA_DRM_INFO(
                  v_REG_NO
                , v_REG_DGR
                , v_DATA_DIV
                , v_DATA_SUB_DIV
                , v_DATA_SUB_DIV2
                , v_DATA_DIV_NM
                , v_DATA_SUB_DIV_NM
                , v_DATA_SUB_DIV2_NM
                , v_DATA_NM
                , v_DATA_DESC
                , v_BLT_MAIL
                , v_BLT_SMS
                , v_ATFL_GRP
                , v_SIT_CD
                , v_SIT_NM
                , v_FNL_YN
                , v_TAG
                , v_IPT_ID
                , v_IPT_DTM
                , v_IPT_YMD
                , v_VIEW_YN
                , v_APL_SEQ
                , v_APL_STATS
                , v_DEPT_CD
                , v_VIEW_CNT
                , v_VIEW_STATS
                , v_VIEW_TERM
                , v_MNU_CD
                , v_DATA_DIV_1
                , v_DATA_DIV_2
                , v_DATA_DIV_3
                , v_EDT_YN
                , v_WRTR_NM
            );
        END LOOP; 
        CLOSE v_CURSOR;

--        FETCH v_CURSOR BULK COLLECT INTO v_LIST;
--        CLOSE v_CURSOR;
--        
--        OPEN RTN_CURSOR FOR
--        SELECT * 
--          FROM TABLE(v_LIST)
--        ;  

        OPEN RTN_CURSOR FOR
        WITH WT1
            AS (SELECT * 
                  FROM TABLE(v_LIST)
               )
        SELECT LEVEL AS "Level"
             , T1.HRNK_CD
             , T1.COM_CD
             , T1.CD_NM
             , T1.SRT_SO
             , T1.DATA_YN
             , T1.REG_NO
             , T1.REG_DGR
             , T1.DATA_DESC
             , T1.VIEW_CNT
             , T1.VIEW_STATS
             , T1.VIEW_TERM
             , T1.VIEW_YN
             , T1.APL_SEQ
             , T1.SIT_NM
             , T1.IPT_YMD
             , T1.WRTR_NM
          FROM (
                SELECT A.HRNK_CD
                     , A.COM_CD
                     , A.CD_NM
                     , A.SRT_SO
                     , NULL         AS REG_NO
                     , NULL         AS REG_DGR
                     , TO_CLOB('')  AS DATA_DESC
                     , ''           AS VIEW_CNT
                     , ''           AS VIEW_STATS
                     , ''           AS VIEW_TERM
                     , '0'          AS DATA_YN
                     , ''           AS VIEW_YN
                     , NULL         AS APL_SEQ
                     , ''           AS SIT_NM
                     , ''           AS IPT_YMD
                     , ''           AS WRTR_NM
                  FROM TCOA_COMCODE A
                 WHERE A.USE_YN = '1'
                   AND A.COM_CD IN (
                                   SELECT X.COM_CD
                                     FROM TCOA_COMCODE X
                                    START WITH X.COM_CD IN (SELECT DISTINCT DATA_SUB_DIV2 FROM WT1)
                                   CONNECT BY PRIOR X.HRNK_CD = X.COM_CD  
                   )
                UNION ALL
                SELECT DATA_SUB_DIV2    AS HRNK_CD
                     , TO_CHAR(REG_NO)  AS COM_CD
                     , DATA_NM          AS CD_NM
                     , REG_NO           AS SRT_SO
                     , REG_NO
                     , REG_DGR
                     , DATA_DESC                        AS DATA_DESC
                     , TO_CHAR(VIEW_CNT, 'FM9,999,999') AS VIEW_CNT
                     , VIEW_STATS
                     , VIEW_TERM
                     , '1'                              AS DATA_YN
                     , VIEW_YN
                     , APL_SEQ
                     , SIT_NM
                     , IPT_YMD
                     , WRTR_NM
                  FROM WT1
               ) T1
         START WITH T1.HRNK_CD = 'QS060'
        CONNECT BY PRIOR T1.COM_CD = T1.HRNK_CD
         ORDER SIBLINGS BY T1.SRT_SO
        ;

    --------------------------------------------------------------------------------------
    -- 관리자 권한 확인
    ELSIF (p_WRK_TP = 'Q3') THEN

        OPEN RTN_CURSOR FOR
        SELECT NVL(MAX('1'), '0')   AS ADM_YN
          FROM TCOA_COMCODE
         WHERE HRNK_CD = 'QS062'
           AND COM_CD = p_WRK_ID
        ;


    --------------------------------------------------------------------------------------
    -- 버전 이력 조회
    ELSIF (p_WRK_TP = 'Q4') THEN

        OPEN RTN_CURSOR FOR
        SELECT T1.REG_NO                --등록번호
             , T1.REG_DGR
             , T1.DATA_DIV              --자료구분
             , T1.DATA_SUB_DIV
             , T1.DATA_SUB_DIV2
             , T8.CD_NM             AS DATA_SUB_DIV_NM
             , T14.CD_NM            AS DATA_SUB_DIV2_NM
             , T1.DATA_NM               --자료명
             , T1.DATA_DESC             --자료설명
             , T1.BLT_MAIL              --메일알림여부
             , T1.BLT_SMS               --SMS알림여부
             , T1.ATFL_GRP              --첨부파일그룹
             , T1.SIT_CD                --현장코드
             , T1.SIT_CD            AS SIT_CD2      --현장코드
             , T1.FNL_YN
             , T1.TAG
             , T1.IPT_ID                --입력자
             , T1.IPT_DTM               --입력일시
             , T1.IPT_IP                --입력IP
             , T1.UPD_ID                --수정자
             , T1.UPD_DTM               --수정일시
             , T1.UPD_IP                --수정IP
             , TO_CHAR(T1.IPT_DTM, 'YYYY-MM-DD')    AS REG_DD
             , T3.USR_NM                            AS WRTR_NM
             , T1.DATA_DIV                          AS DATA_DIV_1   -- 자료구분 - CHAIN 연결 SELECT BOX로 별도 추가.
             , T1.DATA_SUB_DIV                      AS DATA_DIV_2   -- 자료구분2
             , T1.DATA_SUB_DIV2                     AS DATA_DIV_3   -- 자료구분3
             , T4.SIT_NM                            AS SIT_NM
             , NVL(T4.SIT_NM, '전사공통')               AS SIT_NM2
--             , T4.SIT_NM                            AS SIT_NM3
             , CASE WHEN p_ADM_YN = '1' OR p_WRK_ID = T1.IPT_ID THEN '1' ELSE '0' END AS EDT_YN    -- 수정권한여부.  일단 전사 권한은 무조건 수정 가능.
             , T9.VIEW_CNT
          FROM TQHA_DRM T1
          LEFT JOIN TCOZ_USR_INFO   T3 ON T1.IPT_ID         = T3.USR_ID
          LEFT JOIN TCMZ_SIT        T4 ON T1.SIT_CD         = T4.SIT_CD
          LEFT JOIN TCOA_COMCODE    T8 ON T1.DATA_SUB_DIV   = T8.COM_CD
                                      AND T8.HRNK_CD        = T1.DATA_DIV
          LEFT JOIN TCOA_COMCODE    T14 ON T1.DATA_SUB_DIV2 = T14.COM_CD
                                       AND T14.HRNK_CD      = T1.DATA_SUB_DIV
          LEFT JOIN (   SELECT REG_NO
                             , REG_DGR
                             , COUNT(1)    AS VIEW_CNT
                          FROM TQHA_VIEW_HIS T1
                         GROUP BY REG_NO, REG_DGR
                    )               T9 ON T1.REG_NO         = T9.REG_NO
                                      AND T1.REG_DGR        = T9.REG_DGR
         WHERE T1.REG_NO    = p_REG_NO
         ORDER 
            BY T1.REG_DGR DESC
        ;

    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN 
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);
END ;
/

-- PQHA_DRM_S (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_DRM_S" (
    p_WRK_TP        VARCHAR2 :='U'      -- UPDATE FLAG( I: ISNERT, U:UPDATE, D:DELTE)
,   p_WRK_ID        VARCHAR2            -- 사용자 ID 
,   p_WRK_IP        VARCHAR2            -- 사용자 IP 
,   p_REG_NO        NUMBER              -- 등록번호
,   p_REG_DGR       NUMBER              -- 등록번호
,   p_DATA_DIV      VARCHAR2            -- 자료구분
,   p_DATA_SUB_DIV  VARCHAR2            -- 자료구분2
,   p_DATA_SUB_DIV2 VARCHAR2            -- 자료구분3
,   p_DATA_NM       VARCHAR2            -- 자료명
,   p_DATA_DESC     VARCHAR2            -- 자료설명
,   p_BLT_MAIL      VARCHAR2            -- 메일알림여부
,   p_BLT_SMS       VARCHAR2            -- SMS알림여부
,   p_ATFL_GRP      VARCHAR2            -- 첨부파일그룹
,   p_SIT_CD        VARCHAR2            -- 현장코드
,   p_TAG           VARCHAR2
,   p_RTN_REG_NO    OUT VARCHAR2        -- 리턴변수(등록번호 + 등록차수)
)
IS 
    /**************************************************************************************************************************
      Purpose : 자료실 저장

      REVISIONS
      Ver      Date               Author                  Description 
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2026/01/30 18:42:41                         최초생성

    **************************************************************************************************************************/


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드 
    ERR_MSG        VARCHAR2(200);            -- ERROR Message
    USER_EXCEPTION EXCEPTION;

    v_REG_NO        NUMBER;                   -- 게시번호 MAX
    v_REG_DGR       NUMBER;
    v_CNT           NUMBER := 0;               -- 등록알림

BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 필수입력 필드  Check  ]
    ---------------------------------------------------------------------------------------------------------------------------
--    IF (p_BLT_NO IS NULL)  THEN
--        ERR_MSG := '게시번호는(은) 필수 입력사항 입니다.';
--        RAISE USER_EXCEPTION;
--    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Process 선행조건 Check ]
    ---------------------------------------------------------------------------------------------------------------------------

    --IF (p_WRK_TP = 'D') THEN
    --    SELECT COUNT(*) AS CNT
    --      INTO v_CNT
    --      FROM DUAL
    --     WHERE EXISTS (
    --                     SELECT REG_NO 
    --                       FROM TQHA_DRM_ANNC
    --                     WHERE REG_NO = p_REG_NO
    --                     );
    --    
    --    IF (v_CNT > 0) THEN
    --        ERR_MSG := '등록알림이 등록되어 있어 삭제 할 수 없습니다.';
    --        RAISE USER_EXCEPTION;
    --    END IF;
    --END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Business Process ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_WRK_TP ='D') THEN

        DELETE 
          FROM TQHA_DRM
         WHERE REG_NO   = p_REG_NO
           AND REG_DGR  = p_REG_DGR
        ;

        --등록번호
        v_REG_NO    := p_REG_NO;
        v_REG_DGR   := p_REG_DGR;

    ---------------------------------------------------------------------------------------------
    ELSIF (p_WRK_TP ='U') THEN

        UPDATE TQHA_DRM
           SET DATA_DIV      = p_DATA_DIV        -- 자료구분
             , DATA_SUB_DIV  = p_DATA_SUB_DIV    -- 자료구분2
             , DATA_SUB_DIV2 = p_DATA_SUB_DIV2  -- 자료구분3
             , DATA_NM       = p_DATA_NM         -- 자료명
             , DATA_DESC     = p_DATA_DESC       -- 자료설명
             , BLT_MAIL      = p_BLT_MAIL        -- 메일알림여부
             , BLT_SMS       = p_BLT_SMS         -- SMS알림여부
             , ATFL_GRP      = p_ATFL_GRP        -- 첨부파일그룹
             , SIT_CD        = p_SIT_CD          -- 현장코드
             , TAG           = p_TAG             --
             , UPD_ID        = p_WRK_ID          -- 수정ID
             , UPD_DTM       = SYSDATE           -- 수정일시
             , UPD_IP        = p_WRK_IP          -- 수정IP
         WHERE REG_NO        = p_REG_NO          -- 등록번호
           AND REG_DGR       = p_REG_DGR
        ;

        v_REG_NO    := p_REG_NO;
        v_REG_DGR   := p_REG_DGR;

    ---------------------------------------------------------------------------------------------
    ELSIF p_WRK_TP = 'I' THEN

        -- 게시번호 생성
        SELECT NVL(MAX(REG_NO), 0) + 1
          INTO v_REG_NO
          FROM TQHA_DRM 
        ;

        v_REG_DGR   := 1;

        -- 게시번호 생성 완료

        INSERT 
          INTO TQHA_DRM
             ( REG_NO               -- 등록번호
             , REG_DGR
             , DATA_DIV             -- 자료구분
             , DATA_SUB_DIV
             , DATA_SUB_DIV2
             , DATA_NM              -- 자료명
             , DATA_DESC            -- 자료설명
             , BLT_MAIL             -- 메일알림여부
             , BLT_SMS              -- SMS알림여부
             , ATFL_GRP             -- 첨부파일그룹
             , SIT_CD               -- 현장코드
             , FNL_YN
             , TAG                  -- 검색태그
             , IPT_ID               -- 입력자
             , IPT_DTM              -- 입력일시
             , IPT_IP               -- 입력IP
             , UPD_ID               -- 수정자
             , UPD_DTM              -- 수정일시
             , UPD_IP               -- 수정IP
             )
        VALUES 
             ( v_REG_NO             -- 등록번호
             , v_REG_DGR
             , p_DATA_DIV           -- 자료구분
             , p_DATA_SUB_DIV
             , p_DATA_SUB_DIV2
             , p_DATA_NM            -- 자료명
             , p_DATA_DESC          -- 자료설명
             , p_BLT_MAIL           -- 메일알림여부
             , p_BLT_SMS            -- SMS알림여부
             , p_ATFL_GRP           -- 첨부파일그룹
             , p_SIT_CD             -- 현장코드
             , '1'                  -- 최종여부
             , p_TAG                -- 검색태그
             , p_WRK_ID             -- 입력ID 
             , SYSDATE()            -- 입력일시
             , p_WRK_IP             -- 입력IP
             , p_WRK_ID             -- 수정ID
             , SYSDATE()            -- 수정일시
             , p_WRK_IP             -- 수정IP
             )
        ;

    ---------------------------------------------------------------------------------------------
    ELSIF p_WRK_TP = 'VERUP' THEN

        UPDATE TQHA_DRM
           SET FNL_YN       = '0'
         WHERE REG_NO       = p_REG_NO          -- 등록번호
        ;

        SELECT NVL(MAX(REG_DGR), 0) + 1
          INTO v_REG_DGR
          FROM TQHA_DRM
         WHERE REG_NO       = p_REG_NO          -- 등록번호
        ;

        INSERT
          INTO TQHA_DRM
             ( REG_NO               -- 등록번호
             , REG_DGR
             , DATA_DIV             -- 자료구분
             , DATA_SUB_DIV
             , DATA_SUB_DIV2
             , DATA_NM              -- 자료명
             , DATA_DESC            -- 자료설명
             , BLT_MAIL             -- 메일알림여부
             , BLT_SMS              -- SMS알림여부
             , ATFL_GRP             -- 첨부파일그룹
             , SIT_CD               -- 현장코드
             , FNL_YN
             , TAG
             , IPT_ID               -- 입력자
             , IPT_DTM              -- 입력일시
             , IPT_IP               -- 입력IP
             , UPD_ID               -- 수정자
             , UPD_DTM              -- 수정일시
             , UPD_IP               -- 수정IP
             )
        SELECT REG_NO               -- 등록번호
             , v_REG_DGR
             , DATA_DIV             -- 자료구분
             , DATA_SUB_DIV
             , DATA_SUB_DIV2
             , DATA_NM              -- 자료명
             , DATA_DESC            -- 자료설명
             , BLT_MAIL             -- 메일알림여부
             , BLT_SMS              -- SMS알림여부
             , NULL         AS ATFL_GRP     -- 첨부파일그룹
             , SIT_CD               -- 현장코드
             , '1'                  -- 최종여부
             , TAG
             , p_WRK_ID             -- 입력자
             , SYSDATE              -- 입력일시
             , p_WRK_IP             -- 입력IP
             , p_WRK_ID             -- 수정자
             , SYSDATE              -- 수정일시
             , p_WRK_IP             -- 수정IP
          FROM TQHA_DRM
         WHERE REG_NO       = p_REG_NO          -- 등록번호
           AND REG_DGR      = p_REG_DGR
        ;

        v_REG_NO := p_REG_NO;

    END IF;

    p_RTN_REG_NO := v_REG_NO || '$' || v_REG_DGR;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 5. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN 
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);
END ;
/

-- PQHA_EDU_B (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_EDU_B" ( -- 교육일지 전일복사 (교육구분에 따른)
    p_WRK_TP                VARCHAR2 :='U'                              -- UPDATE FLAG( I: ISNERT, U:UPDATE, D:DELTE)
,   p_WRK_ID                VARCHAR2                                    -- 사용자 ID
,   p_WRK_IP                VARCHAR2                                    -- 사용자 IP
,   p_SIT_CD                TQHA_EDU.SIT_CD             %TYPE           -- 현장코드
,   p_EDU_SEQ               TQHA_EDU.EDU_SEQ            %TYPE           -- 교육순번
,   p_EDU_CD                TQHA_EDU.EDU_CD             %TYPE           -- 교육코드
,   p_DEEDU_CD              TQHA_EDU.DEEDU_CD           %TYPE           -- 세부교육코드
,   p_EDU_DT                TQHA_EDU.EDU_DT             %TYPE           -- 교육일자
,   p_MOBILE_REG_DIV        VARCHAR2                                    -- 모바일등록여부(0:모바일등록x, 1:모바일등록o)
,   p_RTN_EDU_SEQ           OUT VARCHAR2                                -- 리턴변수(교육순번)
)
IS
    /**************************************************************************************************************************
      Purpose : 교육일지 전일복사 

      REVISIONS
      Ver      Date               Author                  Description
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2022/02/21 16:00:00                         최초생성
      1.1     2024/03/05 10:13:00 정우성                   교육코드/세부교육코드/특별교육내용 추가

    **************************************************************************************************************************/


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR2(200);            -- ERROR Message
    USER_EXCEPTION EXCEPTION;

    v_EDU_SEQ           TQHA_EDU.EDU_SEQ%TYPE ;        -- 순번 변수 선언
    v_BEF_EDU_SEQ       TQHA_EDU.EDU_SEQ%TYPE;         -- 전일 교육순번 변수

    v_APRV_STATS        VARCHAR2(20);
    v_APRV_STATS_NM     VARCHAR2(50);

BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 필수입력 필드  Check  ]
    ---------------------------------------------------------------------------------------------------------------------------
    ---------------------------------------------------------------------
    -- 결재상태 체크
    SELECT MAX(T2.APRV_STATS)
         , MAX(T3.CD_NM )
      INTO v_APRV_STATS
         , v_APRV_STATS_NM
      FROM TQHA_EDU             T1
      LEFT JOIN TQHA_APRV       T2 ON T1.SIT_CD     = T2.SIT_CD
                                  AND T1.APRV_NO    = T2.APRV_NO
      LEFT JOIN TCOA_COMCODE    T3 ON T2.APRV_STATS = T3.COM_CD
                                  AND T3.HRNK_CD    = 'QS031'
     WHERE T1.SIT_CD    = p_SIT_CD
       AND T1.EDU_SEQ   = p_EDU_SEQ
    ;

    IF v_APRV_STATS IN ('2', '4') THEN
        ERR_MSG := '결재상태 [' || v_APRV_STATS_NM || ']인 데이터는 수정 불가합니다.';
        RAISE USER_EXCEPTION;
    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Process 선행조건 Check ]
    ---------------------------------------------------------------------------------------------------------------------------
    -- 전일 조회
    SELECT MAX(EDU_SEQ) AS EDU_SEQ
      INTO v_BEF_EDU_SEQ
      FROM TQHA_EDU
     WHERE SIT_CD       = p_SIT_CD
      -- 2024/03/05 교육코드/세부교육코드 추가
       AND EDU_CD       = p_EDU_CD
       AND DEEDU_CD     = p_DEEDU_CD
      ------------------------------------------
       --AND EDU_DT < p_EDU_DT
     ;

    IF (v_BEF_EDU_SEQ IS NULL) THEN
        ERR_MSG := '복사할 데이터가 없습니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_EDU_SEQ IS NULL) THEN
        -- 교육순번 생성
        SELECT NVL((MAX(EDU_SEQ)+1), 1)
          INTO v_EDU_SEQ
          FROM TQHA_EDU
         WHERE SIT_CD = p_SIT_CD
         ;
    
        -- 교육순번 생성 완료
    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Business Process ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_WRK_TP = 'U') THEN

        IF (p_MOBILE_REG_DIV = '1') THEN      -- 모바일에 등록한 항목은 업데이트 안함

            UPDATE TQHA_EDU
               SET ( 
                       EDU_CD                -- 교육코드
					 , DEEDU_CD                -- 교육세부코드
					 , COP_VNDR_NM                -- 협력업체명칭
					 , EDU_DT                -- 교육시작일
					 , EDU_TIME                -- 교육시간
					 , REL_LNR1                -- 관련법규1
					 , REL_LNR2                -- 관련법규2
					 , EDU_OBJ_MAN                -- 교육대상인원
					 , EDU_IMPL_MAN                -- 교육실시인원
					 , USE_TCMT                -- 교육방법
					 , EDU_IMPL                -- 교육강사
					 , EDU_PLC                -- 교육장소
					 , EDU_MTD                -- 교육대상
					 , EDU_CTS                -- 공통교육내용
					 , EDU_CTS2                -- 개별교육내용
					 , EDU_CTS3                -- 기타교육내용
					 , MSDS_RMKS                -- MSDS비고
                   ----------------------------------------------------------------
                   , UPD_ID       -- 수정ID
                   , UPD_DTM      -- 수정일시
                   , UPD_IP       -- 수정IP
                   ) = ( SELECT 
                                   EDU_CD                -- 교육코드
								 , DEEDU_CD                -- 교육세부코드
								 , COP_VNDR_NM                -- 협력업체명칭
								 , EDU_DT                -- 교육시작일
								 , EDU_TIME                -- 교육시간
								 , REL_LNR1                -- 관련법규1
								 , REL_LNR2                -- 관련법규2
								 , EDU_OBJ_MAN                -- 교육대상인원
								 , EDU_IMPL_MAN                -- 교육실시인원
								 , USE_TCMT                -- 교육방법
								 , EDU_IMPL                -- 교육강사
								 , EDU_PLC                -- 교육장소
								 , EDU_MTD                -- 교육대상
								 , EDU_CTS                -- 공통교육내용
								 , EDU_CTS2                -- 개별교육내용
								 , EDU_CTS3                -- 기타교육내용
								 , MSDS_RMKS                -- MSDS비고
                              ----------------------------------------------------------------
                              , p_WRK_ID     -- 수정ID
                              , SYSDATE()    -- 수정일시
                              , p_WRK_IP     -- 수정IP
                           FROM TQHA_EDU
                          WHERE SIT_CD = p_SIT_CD
                            AND EDU_SEQ = v_BEF_EDU_SEQ )
             WHERE SIT_CD = p_SIT_CD
               AND EDU_SEQ = p_EDU_SEQ;

             v_EDU_SEQ := p_EDU_SEQ;

        ELSIF (p_MOBILE_REG_DIV = '0') THEN   -- 모바일에 등록한 항목도 업데이트 처리

            UPDATE TQHA_EDU
               SET 
                 ( 
				   EDU_CD                -- 교육코드
				 , DEEDU_CD                -- 교육세부코드
				 , COP_VNDR_NM                -- 협력업체명칭
				 , EDU_DT                -- 교육시작일
				 , EDU_TIME                -- 교육시간
				 , REL_LNR1                -- 관련법규1
				 , REL_LNR2                -- 관련법규2
				 , EDU_OBJ_MAN                -- 교육대상인원
				 , EDU_IMPL_MAN                -- 교육실시인원
				 , USE_TCMT                -- 교육방법
				 , EDU_IMPL                -- 교육강사
				 , EDU_PLC                -- 교육장소
				 , EDU_MTD                -- 교육대상
				 , EDU_CTS                -- 공통교육내용
				 , EDU_CTS2                -- 개별교육내용
				 , EDU_CTS3                -- 기타교육내용
				 , MSDS_RMKS                -- MSDS비고
                 ----------------------------------------------------------------
                 , UPD_ID               -- 수정ID
                 , UPD_DTM              -- 수정일시
                 , UPD_IP               -- 수정IP
                 ) 
                 = 
                 ( SELECT 
                          EDU_CD                -- 교육코드
						 , DEEDU_CD                -- 교육세부코드
						 , COP_VNDR_NM                -- 협력업체명칭
						 , EDU_DT                -- 교육시작일
						 , EDU_TIME                -- 교육시간
						 , REL_LNR1                -- 관련법규1
						 , REL_LNR2                -- 관련법규2
						 , EDU_OBJ_MAN                -- 교육대상인원
						 , EDU_IMPL_MAN                -- 교육실시인원
						 , USE_TCMT                -- 교육방법
						 , EDU_IMPL                -- 교육강사
						 , EDU_PLC                -- 교육장소
						 , EDU_MTD                -- 교육대상
						 , EDU_CTS                -- 공통교육내용
						 , EDU_CTS2                -- 개별교육내용
						 , EDU_CTS3                -- 기타교육내용
						 , MSDS_RMKS                -- MSDS비고
                        ----------------------------------------------------------------
                        , p_WRK_ID          -- 수정ID
                        , SYSDATE()         -- 수정일시
                        , p_WRK_IP          -- 수정IP
                     FROM TQHA_EDU
                    WHERE SIT_CD = p_SIT_CD
                      AND EDU_SEQ = v_BEF_EDU_SEQ 
                 )
             WHERE SIT_CD       = p_SIT_CD
               AND EDU_SEQ      = p_EDU_SEQ
            ;

            v_EDU_SEQ := p_EDU_SEQ;

        END IF;

    ELSIF (p_WRK_TP = 'I') THEN

        INSERT 
          INTO TQHA_EDU
             ( 
               SIT_CD                -- 현장코드
			 , EDU_SEQ                -- 교육순번
			 , EDU_CD                -- 교육코드
			 , DEEDU_CD                -- 교육세부코드
			 , COP_VNDR_NM                -- 협력업체명칭
			 , EDU_DT                -- 교육시작일
			 , EDU_TIME                -- 교육시간
			 , REL_LNR1                -- 관련법규1
			 , REL_LNR2                -- 관련법규2
			 , EDU_OBJ_MAN                -- 교육대상인원
			 , EDU_IMPL_MAN                -- 교육실시인원
			 , USE_TCMT                -- 교육방법
			 , EDU_IMPL                -- 교육강사
			 , EDU_PLC                -- 교육장소
			 , EDU_MTD                -- 교육대상
			 , EDU_CTS                -- 공통교육내용
			 , EDU_CTS2                -- 개별교육내용
			 , EDU_CTS3                -- 기타교육내용
			 , MSDS_RMKS                -- MSDS비고
             ----------------------------------------------------------------
             , IPT_ID                   -- 입력ID
             , IPT_DTM                  -- 입력일시
             , IPT_IP                   -- 입력IP
             , UPD_ID                   -- 수정ID
             , UPD_DTM                  -- 수정일시
             , UPD_IP                   -- 수정IP
             )
        SELECT SIT_CD                   -- 현장코드
             , v_EDU_SEQ                -- 교육순번
             , EDU_CD                -- 교육코드
			 , DEEDU_CD                -- 교육세부코드
			 , COP_VNDR_NM                -- 협력업체명칭
			 , EDU_DT                -- 교육시작일
			 , EDU_TIME                -- 교육시간
			 , REL_LNR1                -- 관련법규1
			 , REL_LNR2                -- 관련법규2
			 , EDU_OBJ_MAN                -- 교육대상인원
			 , EDU_IMPL_MAN                -- 교육실시인원
			 , USE_TCMT                -- 교육방법
			 , EDU_IMPL                -- 교육강사
			 , EDU_PLC                -- 교육장소
			 , EDU_MTD                -- 교육대상
			 , EDU_CTS                -- 공통교육내용
			 , EDU_CTS2                -- 개별교육내용
			 , EDU_CTS3                -- 기타교육내용
			 , MSDS_RMKS                -- MSDS비고
             , p_WRK_ID                 -- 입력ID
             , SYSDATE()                -- 입력일시
             , p_WRK_IP                 -- 입력IP
             , p_WRK_ID                 -- 수정ID
             , SYSDATE()                -- 수정일시
             , p_WRK_IP                 -- 수정IP
          FROM TQHA_EDU
         WHERE SIT_CD = p_SIT_CD
           AND EDU_SEQ = v_BEF_EDU_SEQ
        ;
        
        INSERT INTO TQHA_EDU_MSDS
                   ( SIT_CD                  --현장코드
                    ,EDU_SEQ                 --교육순번
                    ,MSDS_SEQ                --MSDS순번
                    ,CHEM_CD                 --대상화학물질
                    ,CHEM_NM                 --대상화학물질명
                    ,HAZ_INFO                --위험성유해성
                    ,HDL_PRECT               --취급주의사항
                    ,PREQ                    --보호구
                    ,FAID_MEAS               --응급조치요령
                    ,GHS_LBL                 --경고표지이해방법
                    ,MSDS_NM                 --제품명
                    ,MNFR_NM                 --제조사명
                    ,IPT_ID                  --입력ID
                    ,IPT_DTM                 --입력일시
                    ,IPT_IP                  --입력IP
                    ,UPD_ID                  --수정ID
                    ,UPD_DTM                 --수정일시
                    ,UPD_IP                  --수정IP
                    )
            SELECT  SIT_CD                 --현장코드
		           ,v_EDU_SEQ                 --교육순번
		           ,MSDS_SEQ               --MSDS순번
		           ,CHEM_CD                 --대상화학물질
		           ,CHEM_NM                 --대상화학물질명
		           ,HAZ_INFO                 --위험성유해성
		           ,HDL_PRECT                 --취급주의사항
		           ,PREQ                 --보호구
		           ,FAID_MEAS                 --응급조치요령
		           ,GHS_LBL                 --경고표지이해방법
		           ,MSDS_NM
				   ,MNFR_NM
		           ,p_WRK_ID                 -- 입력ID
		           ,SYSDATE()                -- 입력일시
		           ,p_WRK_IP                 -- 입력IP
		           ,p_WRK_ID                 -- 수정ID
		           ,SYSDATE()                -- 수정일시
		           ,p_WRK_IP                 -- 수정IP
		      FROM TQHA_EDU_MSDS
		    WHERE SIT_CD = p_SIT_CD                     --현장코드
		      AND EDU_SEQ = v_BEF_EDU_SEQ               --교육순번
		;
    END IF; 

    p_RTN_EDU_SEQ := v_EDU_SEQ;

   ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 5. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);

END PQHA_EDU_B;
/

