-- PQHA_EDU_CD_S (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_EDU_CD_S" (
    p_WRK_TP        VARCHAR2 :='U'                          -- UPDATE FLAG( I: ISNERT, U:UPDATE, D:DELTE)
,   p_WRK_ID        VARCHAR2                                -- 사용자 ID 
,   p_WRK_IP        VARCHAR2                                -- 사용자 IP  
,   p_EDU_CD        TQHA_EDU_CD.EDU_CD      %TYPE           -- 교육코드
,   p_EDU_NM        TQHA_EDU_CD.EDU_NM      %TYPE           -- 교육코드명
,   p_USE_YN        TQHA_EDU_CD.USE_YN      %TYPE           -- 사용 1 미사용 0
)
IS  
    /**************************************************************************************************************************
      Purpose : 교육구분 저장

      REVISIONS
      Ver      Date               Author                  Description 
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2024/02/21 10:23:51                         최초생성

    **************************************************************************************************************************/


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR2(200);            -- ERROR Message
    USER_EXCEPTION EXCEPTION;

     v_EDU_CD       TQHA_EDU_CD.EDU_CD  %TYPE;      -- 교육코드 변수 선언
     v_cnt          INTEGER;                        -- 교육코드 존재 여부

BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 필수입력 필드  Check  ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_EDU_NM IS NULL )  THEN
        ERR_MSG := '교육명칭는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;


    --  세부교육 코드 존재 여부 확인
    IF p_WRK_TP = 'D' THEN

        SELECT nvl(COUNT(EDU_CD),0) 
          INTO v_cnt
          FROM TQHA_DEEDU_CD
         WHERE EDU_CD = p_EDU_CD
        ;

         -- 세부교육 코드 Validation
        IF v_cnt > 0 THEN
           ERR_MSG := '교육항목 "' || p_EDU_NM || '" 은(는) 세부 교육항목이 존재합니다. 세부 교육항목을 전부 삭제해야 교육코드를 삭제할 수 있습니다. ';
           RAISE USER_EXCEPTION;
        END IF;
    END IF;   
    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Process 선행조건 Check ]
    ---------------------------------------------------------------------------------------------------------------------------



    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Business Process ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_WRK_TP ='D') THEN

        DELETE 
          FROM TQHA_EDU_CD
         WHERE EDU_CD = p_EDU_CD         --교육코드
        ;

    ELSIF (p_WRK_TP ='U') THEN

        UPDATE TQHA_EDU_CD
           SET EDU_NM           = p_EDU_NM          -- 교육코드명
             , USE_YN           = p_USE_YN          -- 사용 1 미사용 0
             , UPD_ID           = p_WRK_ID          -- 수정ID 
             , UPD_DTM          = SYSDATE()         -- 수정일시
             , UPD_IP           = p_WRK_IP          -- 수정IP
         WHERE EDU_CD           = p_EDU_CD          -- 교육코드
        ;

    ELSE 

        -- 교육코드 MAX부여
        SELECT LPAD(NVL(MAX(SUBSTR(EDU_CD, 1, 3)), 0) + 1, 3,'0')
          INTO v_EDU_CD
          FROM TQHA_EDU_CD 
        ; 
        --          

        INSERT 
          INTO TQHA_EDU_CD
             ( EDU_CD               -- 교육코드
             , EDU_NM               -- 교육코드명
             , USE_YN               -- 사용 1 미사용 0
             , IPT_ID               -- 입력ID
             , IPT_DTM              -- 입력일시
             , IPT_IP               -- 입력IP
             , UPD_ID               -- 수정ID
             , UPD_DTM              -- 수정일시
             , UPD_IP               -- 수정IP
             )
        VALUES 
             ( v_EDU_CD             -- 교육코드
             , p_EDU_NM             -- 교육코드명
             , p_USE_YN             -- 사용 1 미사용 0
             , p_WRK_ID             -- 입력ID 
             , SYSDATE()            -- 입력일시
             , p_WRK_IP             -- 입력IP
             , p_WRK_ID             -- 수정ID
             , SYSDATE()            -- 수정일시
             , p_WRK_IP             -- 수정IP
             )
        ;

    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 5. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN 
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);

END ;
/

-- PQHA_EDU_DRY_Q (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_EDU_DRY_Q"
							 (p_WRK_TP  VARCHAR2 :='U'                                     -- UPDATE FLAG( I: ISNERT, U:UPDATE, D:DELTE)
                             ,p_WRK_ID  VARCHAR2                                           -- 사용자 ID
                             ,p_WRK_IP  VARCHAR2                                           -- 사용자 IP
						     ,p_SIT_CD TQHA_EDU_DRY.SIT_CD%TYPE                                                   -- 현장코드
						     ,p_EDU_FRDT TQHA_EDU_DRY.EDU_DT%TYPE                           -- 작성시작일자
						     ,p_EDU_TODT TQHA_EDU_DRY.EDU_DT%TYPE                           -- 작성종료일자
						     ,RTN_CURSOR OUT SYS_REFCURSOR
							)  
IS 
    /**************************************************************************************************************************
      Purpose : 

      REVISIONS
      Ver      Date               Author                  Description 
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2026/05/21 17:00:27                         최초생성

    /**************************************************************************************************************************/


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR2(200);            -- ERROR Message
    USER_EXCEPTION EXCEPTION;


BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 수행전 Check Logic ]
    ---------------------------------------------------------------------------------------------------------------------------


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Logic 처리
    ---------------------------------------------------------------------------------------------------------------------------

    OPEN RTN_CURSOR FOR
    SELECT  A.SIT_CD                 --현장코드
    	   ,( SELECT CNST_NM FROM VQSZ_SITEINFO WHERE SIT_CD = A.SIT_CD ) AS SIT_NM
           ,A.EDU_SEQ                 --업체순번
           ,A.EDU_DT                 --교육일자
           ,A.EDU_NM                 --교육명
           ,A.EDU_CTS                 --교육내용
           ,A.RMKS                 --비고
           ,A.ATFL_GRP                 --첨부파일그룹
      FROM TQHA_EDU_DRY A
    WHERE SIT_CD LIKE p_SIT_CD ||'%'
      AND SUBSTR(EDU_DT,1,6) BETWEEN NVL(p_EDU_FRDT, '190001') AND NVL(p_EDU_TODT, '471212')
      ORDER BY SIT_CD, EDU_DT DESC           
		;


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN 
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);
END ;
/

-- PQHA_EDU_DRY_S (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_EDU_DRY_S"
                            (p_WRK_TP  VARCHAR2 :='U'                                     -- UPDATE FLAG( I: ISNERT, U:UPDATE, D:DELTE)
                            ,p_WRK_ID  VARCHAR2                                           -- 사용자 ID 
                            ,p_WRK_IP  VARCHAR2                                           -- 사용자 IP 
                            ,p_SIT_CD TQHA_EDU_DRY.SIT_CD%TYPE                            -- 현장코드
                            ,p_EDU_SEQ TQHA_EDU_DRY.EDU_SEQ%TYPE                          -- 교육순번
                            ,p_EDU_DT TQHA_EDU_DRY.EDU_DT%TYPE                            -- 교육일자
                            ,p_EDU_NM TQHA_EDU_DRY.EDU_NM%TYPE                            -- 교육명
                            ,p_EDU_CTS TQHA_EDU_DRY.EDU_CTS%TYPE                          -- 교육내용
                            ,p_RMKS TQHA_EDU_DRY.RMKS%TYPE                                -- 비고 
                            ,p_ATFL_GRP TQHA_EDU_DRY.ATFL_GRP%TYPE)                       -- 첨부파일그룹
IS 
    /**************************************************************************************************************************
      Purpose : 

      REVISIONS
      Ver      Date               Author                  Description 
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2026/05/21 17:04:40                         최초생성

    /**************************************************************************************************************************/


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR2(200);            -- ERROR Message
    USER_EXCEPTION EXCEPTION;

    v_SEQ NUMBER;

BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 필수입력 필드  Check  ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_SIT_CD IS NULL)  THEN
        ERR_MSG := '현장코드는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_WRK_TP != 'I' AND p_EDU_SEQ IS NULL)  THEN
        ERR_MSG := '교육순번는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_EDU_DT IS NULL)  THEN
        ERR_MSG := '교육일자는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Process 선행조건 Check ]
    ---------------------------------------------------------------------------------------------------------------------------

    SELECT NVL(MAX(EDU_SEQ), 0) + 1 INTO v_SEQ
    FROM TQHA_EDU_DRY
    WHERE SIT_CD = p_SIT_CD;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Business Process ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_WRK_TP ='D') THEN
        DELETE 
          FROM TQHA_EDU_DRY
         WHERE SIT_CD = p_SIT_CD          --현장코드
           AND EDU_SEQ = p_EDU_SEQ;        --교육순번

    ELSIF (p_WRK_TP ='U') THEN
        UPDATE TQHA_EDU_DRY
           SET EDU_DT               = p_EDU_DT                  --교육일자
              ,EDU_NM               = p_EDU_NM                  --교육명
              ,EDU_CTS              = p_EDU_CTS                 --교육내용
              ,RMKS                 = p_RMKS                    --비고
              ,ATFL_GRP             = p_ATFL_GRP                --첨부파일그룹
              ,UPD_ID               = p_WRK_ID                  --수정ID 
              ,UPD_DTM              = SYSDATE()                 --수정일시
              ,UPD_IP               = p_WRK_IP                  --수정IP
         WHERE SIT_CD = p_SIT_CD          --현장코드
           AND EDU_SEQ = p_EDU_SEQ;        --교육순번
    ELSE 
        INSERT INTO TQHA_EDU_DRY
                   ( SIT_CD                  --현장코드
                    ,EDU_SEQ                 --교육순번
                    ,EDU_DT                  --교육일자
                    ,EDU_NM                  --교육명
                    ,EDU_CTS                 --교육내용
                    ,RMKS                    --비고
                    ,ATFL_GRP                --첨부파일그룹
                    ,IPT_ID                  --입력ID
                    ,IPT_DTM                 --입력일시
                    ,IPT_IP                  --입력IP
                    ,UPD_ID                  --수정ID
                    ,UPD_DTM                 --수정일시
                    ,UPD_IP                  --수정IP
                    )
             VALUES (p_SIT_CD                --현장코드
                    ,v_SEQ                   --교육순번
                    ,p_EDU_DT                --교육일자
                    ,p_EDU_NM                --교육명
                    ,p_EDU_CTS               --교육내용
                    ,p_RMKS                  --비고
                    ,p_ATFL_GRP              --첨부파일그룹
                    ,p_WRK_ID                --입력ID 
                    ,SYSDATE()               --입력일시
                    ,p_WRK_IP                --입력IP
                    ,p_WRK_ID                --수정ID
                    ,SYSDATE()               --수정일시
                    ,p_WRK_IP);              --수정IP
    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 5. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN 
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);
END ;
/

