           ,UPD_ID                 --수정ID
           ,UPD_DTM                 --수정일시
           ,UPD_IP                 --수정IP
      FROM TQHA_EDU_MSDS
    WHERE SIT_CD = p_SIT_CD                     --현장코드
      AND EDU_SEQ = p_EDU_SEQ                     --교육순번
    ORDER BY SIT_CD, EDU_SEQ DESC 
           ;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN 
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);
END ;
/

-- PQHA_EDU_MSDS_S (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_EDU_MSDS_S"
                            (p_WRK_TP  VARCHAR2 :='U'                                     -- UPDATE FLAG( I: ISNERT, U:UPDATE, D:DELTE)
                            ,p_WRK_ID  VARCHAR2                                           -- 사용자 ID 
                            ,p_WRK_IP  VARCHAR2                                           -- 사용자 IP 
                            ,p_SIT_CD TQHA_EDU_MSDS.SIT_CD%TYPE                           -- 현장코드
                            ,p_EDU_SEQ TQHA_EDU_MSDS.EDU_SEQ%TYPE                         -- 교육순번
                            ,p_MSDS_SEQ TQHA_EDU_MSDS.MSDS_SEQ%TYPE                       -- MSDS순번
                            ,p_CHEM_CD TQHA_EDU_MSDS.CHEM_CD%TYPE                         -- 대상화학물질
                            ,p_CHEM_NM TQHA_EDU_MSDS.CHEM_NM%TYPE                         -- 대상화학물질명
                            ,p_HAZ_INFO TQHA_EDU_MSDS.HAZ_INFO%TYPE                       -- 위험성유해성
                            ,p_HDL_PRECT TQHA_EDU_MSDS.HDL_PRECT%TYPE                     -- 취급주의사항
                            ,p_PREQ TQHA_EDU_MSDS.PREQ%TYPE                               -- 보호구
                            ,p_FAID_MEAS TQHA_EDU_MSDS.FAID_MEAS%TYPE                     -- 응급조치요령
                            ,p_GHS_LBL TQHA_EDU_MSDS.GHS_LBL%TYPE                        -- 경고표지이해방법
                            ,p_MSDS_NM TQHA_EDU_MSDS.MSDS_NM%TYPE                          -- 제품명
                            ,p_MNFR_NM TQHA_EDU_MSDS.MNFR_NM%TYPE                          -- 제조사명
                            ) 
IS 
    /**************************************************************************************************************************
      Purpose : 

      REVISIONS
      Ver      Date               Author                  Description 
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2026/06/12 11:06:01                         최초생성

    /**************************************************************************************************************************/


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR2(200);            -- ERROR Message
    USER_EXCEPTION EXCEPTION;

	v_SEQ NUMBER;
BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 필수입력 필드  Check  ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_SIT_CD IS NULL)  THEN
        ERR_MSG := '현장코드는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_EDU_SEQ IS NULL)  THEN
        ERR_MSG := '교육순번는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_MSDS_SEQ IS NULL)  THEN
        ERR_MSG := 'MSDS순번는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION; 
    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Process 선행조건 Check ]
    ---------------------------------------------------------------------------------------------------------------------------
	 SELECT NVL(MAX(MSDS_SEQ), 0) + 1 INTO v_SEQ
    FROM TQHA_EDU_MSDS
    WHERE SIT_CD = p_SIT_CD
     AND EDU_SEQ = p_EDU_SEQ;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Business Process ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_WRK_TP ='D') THEN
        DELETE 
          FROM TQHA_EDU_MSDS
         WHERE SIT_CD = p_SIT_CD          --현장코드
           AND EDU_SEQ = p_EDU_SEQ         --교육순번
           AND MSDS_SEQ = p_MSDS_SEQ;       --MSDS순번

    ELSIF (p_WRK_TP ='U') THEN
        UPDATE TQHA_EDU_MSDS
           SET CHEM_CD              = p_CHEM_CD                 --대상화학물질
              ,CHEM_NM              = p_CHEM_NM                 --대상화학물질명
              ,HAZ_INFO             = p_HAZ_INFO                --위험성유해성
              ,HDL_PRECT            = p_HDL_PRECT               --취급주의사항
              ,PREQ                 = p_PREQ                    --보호구
              ,FAID_MEAS            = p_FAID_MEAS               --응급조치요령
              ,GHS_LBL              = p_GHS_LBL                 --경고표지이해방법
              ,MSDS_NM              = p_MSDS_NM                 --제품명
              ,MNFR_NM              = p_MNFR_NM                 --제조사명
              ,UPD_ID               = p_WRK_ID                  --수정ID 
              ,UPD_DTM              = SYSDATE()                 --수정일시
              ,UPD_IP               = p_WRK_IP                  --수정IP
         WHERE SIT_CD = p_SIT_CD          --현장코드
           AND EDU_SEQ = p_EDU_SEQ         --교육순번
           AND MSDS_SEQ = p_MSDS_SEQ;       --MSDS순번
    ELSE 
        INSERT INTO TQHA_EDU_MSDS
                   ( SIT_CD                  --현장코드
                    ,EDU_SEQ                 --교육순번
                    ,MSDS_SEQ                --MSDS순번
                    ,CHEM_CD                 --대상화학물질
                    ,CHEM_NM                 --대상화학물질명
                    ,HAZ_INFO                --위험성유해성
                    ,HDL_PRECT               --취급주의사항
                    ,PREQ                    --보호구
                    ,FAID_MEAS               --응급조치요령
                    ,GHS_LBL                 --경고표지이해방법
                    ,MSDS_NM                 --제품명
                    ,MNFR_NM                 --제조사명
                    ,IPT_ID                  --입력ID
                    ,IPT_DTM                 --입력일시
                    ,IPT_IP                  --입력IP
                    ,UPD_ID                  --수정ID
                    ,UPD_DTM                 --수정일시
                    ,UPD_IP                  --수정IP
                    )
             VALUES (p_SIT_CD                --현장코드
                    ,p_EDU_SEQ               --교육순번
                    ,v_SEQ                   --MSDS순번
                    ,p_CHEM_CD               --대상화학물질
                    ,p_CHEM_NM               --대상화학물질명
                    ,p_HAZ_INFO              --위험성유해성
                    ,p_HDL_PRECT             --취급주의사항
                    ,p_PREQ                  --보호구
                    ,p_FAID_MEAS             --응급조치요령
                    ,p_GHS_LBL               --경고표지이해방법
                    ,p_MSDS_NM                 --제품명
                    ,p_MNFR_NM                 --제조사명
                    ,p_WRK_ID                --입력ID 
                    ,SYSDATE()               --입력일시
                    ,p_WRK_IP                --입력IP
                    ,p_WRK_ID                --수정ID
                    ,SYSDATE()               --수정일시
                    ,p_WRK_IP);              --수정IP
    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 5. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN 
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);
END ;
/

-- PQHA_EDU_Q (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_EDU_Q" (
    p_WRK_TP            VARCHAR2 DEFAULT 'Q'        -- FLAG( Q: SELECT )
,   p_SIT_CD            VARCHAR2                    -- 현장코드
,   p_EDU_YM            VARCHAR2                    -- 년월    
--,   p_EDU_DIV           VARCHAR2                    -- 교육구분 
,   p_EDU_SEQ           VARCHAR2                    -- 교육순번
,   RTN_CURSOR          OUT SYS_REFCURSOR
)
IS 
    /**************************************************************************************************************************
      Purpose :  교육일지 관리 (Q) -> 교육목록 조회, (Q1) -> 교육일지 조회

      REVISIONS
      Ver      Date               Author                  Description 
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2023/11/28 12:46:42                         최초생성 
      1.1      2023/03/04 12:50:00                          교육코드/세부교육코드/공통교육내용/특별교육내용 추가

    **************************************************************************************************************************/


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR2(200);            -- ERROR Message
    USER_EXCEPTION EXCEPTION;


BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 수행전 Check Logic ]
    ---------------------------------------------------------------------------------------------------------------------------


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Logic 처리
    ---------------------------------------------------------------------------------------------------------------------------
    IF p_WRK_TP = 'Q' THEN

        OPEN RTN_CURSOR FOR
        SELECT 
               A.SIT_CD                -- 현장코드
             , A.EDU_SEQ                -- 교육순번
             , A.EDU_CD                -- 교육코드
             , A.DEEDU_CD                -- 교육세부코드
             , A.COP_VNDR_NM                -- 협력업체명칭
             , A.EDU_DT                -- 교육시작일
             , A.EDU_TIME                -- 교육시간
             , A.REL_LNR1                -- 관련법규1
             , A.REL_LNR2                -- 관련법규2
             , A.EDU_OBJ_MAN                -- 교육대상인원
             , A.EDU_IMPL_MAN                -- 교육실시인원
             , A.USE_TCMT                -- 교육방법
             , A.EDU_IMPL                -- 교육강사
             , A.EDU_PLC                -- 교육장소
             , A.EDU_MTD                -- 교육대상
             , A.EDU_CTS                -- 공통교육내용
             , A.EDU_CTS2                -- 개별교육내용
             , A.EDU_CTS3                -- 기타교육내용
             , A.MSDS_RMKS                -- MSDS비고
             , A.PHOTO_GRP1                -- 첨부파일그룹사진1
             , A.PHOTO_DESC_1                -- 사진설명1
             , A.PHOTO_DT_1                -- 사진설명1
             , A.PHOTO_GRP2                -- 첨부파일그룹사진2
             , A.PHOTO_DESC_2                -- 사진설명2
             , A.PHOTO_DT_2                -- 사진일자2
             , A.PHOTO_GRP3                -- 첨부파일그룹사진3
             , A.PHOTO_DESC_3                -- 사진설명3
             , A.PHOTO_DT_3                -- 사진일자3
             , A.ATFL_GRP                -- 첨부파일그룹
             , A.APRV_NO                -- 결재번호
             , C.EDU_NM             --교육코드명
             , D.DEEDU_NM           --세부교육코드명  
             , D.DEEDU_CTS          --세부교육내용
             , B.APRV_STATS         -- 공통코드 QS031
             , E.CD_NM      AS APRV_STATS_NM
          FROM TQHA_EDU             A
          LEFT JOIN TQHA_APRV       B ON A.SIT_CD = B.SIT_CD
                                     AND A.APRV_NO = B.APRV_NO
           -- 2023/03/04     교육코드(명)/세부교육코드(명)/공통교육내용/특별교육내용 추가
          LEFT JOIN TQHA_EDU_CD     C ON C.EDU_CD = A.EDU_CD
          LEFT JOIN TQHA_DEEDU_CD   D ON D.EDU_CD = A.EDU_CD
                                     AND D.DEEDU_CD = A.DEEDU_CD
          LEFT JOIN TCOA_COMCODE    E ON E.COM_CD = B.APRV_STATS
                                     AND E.HRNK_CD = 'QS031'
         WHERE A.SIT_CD = p_SIT_CD
           AND (SUBSTR(A.EDU_DT, 1, 6) = p_EDU_YM OR NVL(p_EDU_YM, '0') = '0')
           --AND (A.EDU_DIV = p_EDU_DIV OR NVL(p_EDU_DIV, '0') = '0')
         ORDER BY A.SIT_CD, A.EDU_DT  DESC, A.EDU_SEQ DESC
        ;

    ELSIF p_WRK_TP = 'Q1' THEN

        OPEN RTN_CURSOR FOR
        SELECT A.SIT_CD                -- 현장코드
             , A.EDU_SEQ                -- 교육순번
             , A.EDU_CD                -- 교육코드
             , A.DEEDU_CD                -- 교육세부코드
             , A.COP_VNDR_NM                -- 협력업체명칭
             , A.EDU_DT                -- 교육시작일
             , A.EDU_TIME                -- 교육시간
             , A.REL_LNR1                -- 관련법규1
             , A.REL_LNR2                -- 관련법규2
             , A.EDU_OBJ_MAN                -- 교육대상인원
             , A.EDU_IMPL_MAN                -- 교육실시인원
             , A.USE_TCMT                -- 교육방법
             , A.EDU_IMPL                -- 교육강사
             , A.EDU_PLC                -- 교육장소
             , A.EDU_MTD                -- 교육대상
             , A.EDU_CTS                -- 공통교육내용
             , A.EDU_CTS2                -- 개별교육내용
             , A.EDU_CTS3                -- 기타교육내용
             , A.MSDS_RMKS                -- MSDS비고
             , A.PHOTO_GRP1                -- 첨부파일그룹사진1
             , A.PHOTO_DESC_1                -- 사진설명1
             , A.PHOTO_DT_1                -- 사진설명1
             , A.PHOTO_GRP2                -- 첨부파일그룹사진2
             , A.PHOTO_DESC_2                -- 사진설명2
             , A.PHOTO_DT_2                -- 사진설명1
             , A.PHOTO_GRP3                -- 첨부파일그룹사진3
             , A.PHOTO_DESC_3                -- 사진설명3
             , A.PHOTO_DT_3                -- 사진일자3
             , A.ATFL_GRP                -- 첨부파일그룹
             , A.APRV_NO                -- 결재번호
             , C.EDU_NM            --교육코드명
             , A.DEEDU_CD          --세부교육코드
             , D.DEEDU_NM          --세부교육코드명  
             , D.DEEDU_CTS         --세부교육내용  
             --------------------------------------
             , B.APRV_STATS        -- 결재상태
             , '▶ 결재상태 : ' || NVL(( SELECT CD_NM FROM TCOA_COMCODE WHERE HRNK_CD = 'QS031' AND COM_CD = B.APRV_STATS ), '-') AS APRV_STATS_NM -- 결재상태명
             , (SELECT COUNT(1) FROM TQHA_EDU_MSDS WHERE SIT_CD = A.SIT_CD AND EDU_SEQ = A.EDU_SEQ) AS MSDS_CNT
          FROM TQHA_EDU             A
          LEFT JOIN TQHA_APRV       B ON A.SIT_CD = B.SIT_CD
                                     AND A.APRV_NO = B.APRV_NO
          -- 2023/03/04     교육코드(명)/세부교육코드(명)/공통교육내용/특별교육내용 추가
          LEFT JOIN TQHA_EDU_CD     C ON C.EDU_CD = A.EDU_CD
          LEFT JOIN TQHA_DEEDU_CD   D ON D.EDU_CD = A.EDU_CD
                                     AND D.DEEDU_CD = A.DEEDU_CD
         WHERE A.SIT_CD         = p_SIT_CD
           AND A.EDU_SEQ        = p_EDU_SEQ
           ORDER BY A.SIT_CD, A.EDU_DT DESC, A.EDU_SEQ DESC
        ;

    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN 
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);

END ;
/

-- PQHA_EDU_S (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_EDU_S" (
   					 		 p_WRK_TP  VARCHAR2 :='U'                                     -- UPDATE FLAG( I: ISNERT, U:UPDATE, D:DELTE)
                            ,p_WRK_ID  VARCHAR2                                           -- 사용자 ID 
                            ,p_WRK_IP  VARCHAR2                                           -- 사용자 IP 
                            ,p_SIT_CD TQHA_EDU.SIT_CD%TYPE                                -- 현장코드
                            ,p_EDU_SEQ TQHA_EDU.EDU_SEQ%TYPE                              -- 교육순번
                            ,p_EDU_CD TQHA_EDU.EDU_CD%TYPE                                -- 교육코드
                            ,p_DEEDU_CD TQHA_EDU.DEEDU_CD%TYPE                            -- 교육세부코드
                            ,p_COP_VNDR_NM TQHA_EDU.COP_VNDR_NM%TYPE                      -- 협력업체명칭
                            ,p_EDU_DT TQHA_EDU.EDU_DT%TYPE                                -- 교육일자
                            ,p_EDU_TIME TQHA_EDU.EDU_TIME%TYPE                            -- 교육시간
                            ,p_REL_LNR1 TQHA_EDU.REL_LNR1%TYPE                            -- 관련법규1
                            ,p_REL_LNR2 TQHA_EDU.REL_LNR2%TYPE                            -- 관련법규2
                            ,p_EDU_OBJ_MAN TQHA_EDU.EDU_OBJ_MAN%TYPE                      -- 교육대상인원
                            ,p_EDU_IMPL_MAN TQHA_EDU.EDU_IMPL_MAN%TYPE                    -- 교육실시인원
                            ,p_USE_TCMT TQHA_EDU.USE_TCMT%TYPE                            -- 교육방법
                            ,p_EDU_IMPL TQHA_EDU.EDU_IMPL%TYPE                            -- 교육강사
                            ,p_EDU_PLC TQHA_EDU.EDU_PLC%TYPE                              -- 교육장소
                            ,p_EDU_MTD TQHA_EDU.EDU_MTD%TYPE                              -- 교육대상
                            ,p_EDU_CTS TQHA_EDU.EDU_CTS%TYPE                              -- 공통교육내용
                            ,p_EDU_CTS2 TQHA_EDU.EDU_CTS2%TYPE                            -- 개별교육내용
                            ,p_EDU_CTS3 TQHA_EDU.EDU_CTS3%TYPE                            -- 기타교육내용
                            ,p_MSDS_RMKS TQHA_EDU.MSDS_RMKS%TYPE                          -- MSDS비고
                            ,p_PHOTO_GRP1 TQHA_EDU.PHOTO_GRP1%TYPE                        -- 첨부파일그룹사진1
                            ,p_PHOTO_DESC_1 TQHA_EDU.PHOTO_DESC_1%TYPE                    -- 사진설명1
                            ,p_PHOTO_DT_1 TQHA_EDU.PHOTO_DT_1%TYPE                        -- 사진설명1
                            ,p_PHOTO_GRP2 TQHA_EDU.PHOTO_GRP2%TYPE                        -- 첨부파일그룹사진2
                            ,p_PHOTO_DESC_2 TQHA_EDU.PHOTO_DESC_2%TYPE                    -- 사진설명2
                            ,p_PHOTO_DT_2 TQHA_EDU.PHOTO_DT_2%TYPE                        -- 사진설명1
                            ,p_PHOTO_GRP3 TQHA_EDU.PHOTO_GRP3%TYPE                        -- 첨부파일그룹사진3
                            ,p_PHOTO_DESC_3 TQHA_EDU.PHOTO_DESC_3%TYPE                    -- 사진설명3
                            ,p_PHOTO_DT_3 TQHA_EDU.PHOTO_DT_3%TYPE                        -- 사진일자3
                            ,p_ATFL_GRP TQHA_EDU.ATFL_GRP%TYPE                            -- 첨부파일그룹
                            ,p_APRV_NO TQHA_EDU.APRV_NO%TYPE                             -- 결재번호
							,p_RTN_EDU_SEQ           OUT VARCHAR2                         -- 리턴변수(교육순번)
)
IS
    /**************************************************************************************************************************
      Purpose : 교육일지 저장
 
      REVISIONS
      Ver      Date               Author                  Description
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2024/02/20 20:18:08                         최초생성(윤남진)
      1.1     2024/02/28                                  교육코드/세부교육코드 추가, 특별교육내용 추가(정우성)
      1.2       2024/03/21 09:00:00                          개별교육코드(내용) 2,3 추가(정우성)

    **************************************************************************************************************************/


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR2(200);            -- ERROR Message
    USER_EXCEPTION EXCEPTION;

    v_EDU_SEQ           TQHA_EDU.EDU_SEQ%TYPE ;             -- 순번 변수 선언

    v_APRV_STATS        VARCHAR2(20);
    v_APRV_STATS_NM     VARCHAR2(50);

BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 필수입력 필드  Check  ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_SIT_CD IS NULL AND p_WRK_TP <> 'I')  THEN
        ERR_MSG := '현장코드는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

--    IF (p_EDU_SEQ IS NULL AND p_WRK_TP <> 'I')  THEN
--        ERR_MSG := '교육순번는(은) 필수 입력사항 입니다.';
--        RAISE USER_EXCEPTION;
--    END IF;

    ---------------------------------------------------------------------
    -- 결재상태 체크
    SELECT MAX(T2.APRV_STATS)
         , MAX(T3.CD_NM )
      INTO v_APRV_STATS
         , v_APRV_STATS_NM
      FROM TQHA_EDU             T1
      LEFT JOIN TQHA_APRV       T2 ON T1.SIT_CD     = T2.SIT_CD
                                  AND T1.APRV_NO    = T2.APRV_NO
      LEFT JOIN TCOA_COMCODE    T3 ON T2.APRV_STATS = T3.COM_CD
                                  AND T3.HRNK_CD    = 'QS031'
     WHERE T1.SIT_CD    = p_SIT_CD
       AND T1.EDU_SEQ   = p_EDU_SEQ
    ;

    IF v_APRV_STATS IN ('2', '4') THEN
        ERR_MSG := '결재상태 [' || v_APRV_STATS_NM || ']인 데이터는 수정 불가합니다.';
        RAISE USER_EXCEPTION;
    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Process 선행조건 Check ]
    ---------------------------------------------------------------------------------------------------------------------------



    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Business Process ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_WRK_TP ='D') THEN

    	DELETE 
          FROM TQHA_EDU_MSDS
         WHERE SIT_CD = p_SIT_CD          --현장코드
           AND EDU_SEQ = p_EDU_SEQ;         --교육순번
           
        DELETE
          FROM TQHA_EDU
         WHERE SIT_CD   = p_SIT_CD      -- 현장코드
           AND EDU_SEQ  = p_EDU_SEQ     -- 교육순번
        ;

        v_EDU_SEQ := p_EDU_SEQ;

    ELSIF (p_WRK_TP ='U') THEN

        UPDATE TQHA_EDU
           SET EDU_CD               = p_EDU_CD                  --교육코드
              ,DEEDU_CD             = p_DEEDU_CD                --교육세부코드
              ,COP_VNDR_NM          = p_COP_VNDR_NM             --협력업체명칭
              ,EDU_DT               = p_EDU_DT                  --교육일자
              ,EDU_TIME             = p_EDU_TIME                --교육시간
              ,REL_LNR1             = p_REL_LNR1                --관련법규1
              ,REL_LNR2             = p_REL_LNR2                --관련법규2
              ,EDU_OBJ_MAN          = p_EDU_OBJ_MAN             --교육대상인원
              ,EDU_IMPL_MAN         = p_EDU_IMPL_MAN            --교육실시인원
              ,USE_TCMT             = p_USE_TCMT                --교육방법
              ,EDU_IMPL             = p_EDU_IMPL                --교육강사
              ,EDU_PLC              = p_EDU_PLC                 --교육장소
              ,EDU_MTD              = p_EDU_MTD                 --교육대상
              ,EDU_CTS              = p_EDU_CTS                 --공통교육내용
              ,EDU_CTS2             = p_EDU_CTS2                --개별교육내용
              ,EDU_CTS3             = p_EDU_CTS3                --기타교육내용
              ,MSDS_RMKS            = p_MSDS_RMKS               --MSDS비고
              ,PHOTO_GRP1           = p_PHOTO_GRP1              --첨부파일그룹사진1
              ,PHOTO_DESC_1         = p_PHOTO_DESC_1            --사진설명1
              ,PHOTO_DT_1           = p_PHOTO_DT_1              --사진설명1
              ,PHOTO_GRP2           = p_PHOTO_GRP2              --첨부파일그룹사진2
              ,PHOTO_DESC_2         = p_PHOTO_DESC_2            --사진설명2
              ,PHOTO_DT_2           = p_PHOTO_DT_2              --사진일자2
              ,PHOTO_GRP3           = p_PHOTO_GRP3              --첨부파일그룹사진3
              ,PHOTO_DESC_3         = p_PHOTO_DESC_3            --사진설명3
              ,PHOTO_DT_3           = p_PHOTO_DT_3              --사진일자3
              ,ATFL_GRP             = p_ATFL_GRP                --첨부파일그룹
              ,APRV_NO              = p_APRV_NO                 --결재번호
              ,UPD_ID               = p_WRK_ID                  --수정ID 
              ,UPD_DTM              = SYSDATE()                 --수정일시
              ,UPD_IP               = p_WRK_IP                  --수정IP
         WHERE SIT_CD = p_SIT_CD          --현장코드
           AND EDU_SEQ = p_EDU_SEQ        --교육순번
        ;

        v_EDU_SEQ := p_EDU_SEQ;

    ELSE

           -- 교육순번 생성
        SELECT NVL(MAX(EDU_SEQ),0) + 1
          INTO v_EDU_SEQ
          FROM TQHA_EDU
         WHERE SIT_CD = p_SIT_CD         -- 현장코드
        ;

        INSERT INTO TQHA_EDU
                   ( SIT_CD                  --현장코드
                    ,EDU_SEQ                 --교육순번
                    ,EDU_CD                  --교육코드
                    ,DEEDU_CD                --교육세부코드
                    ,COP_VNDR_NM             --협력업체명칭
                    ,EDU_DT                  --교육일자
                    ,EDU_TIME                --교육시간
                    ,REL_LNR1                --관련법규1
                    ,REL_LNR2                --관련법규2
                    ,EDU_OBJ_MAN             --교육대상인원
                    ,EDU_IMPL_MAN            --교육실시인원
                    ,USE_TCMT                --교육방법
                    ,EDU_IMPL                --교육강사
                    ,EDU_PLC                 --교육장소
                    ,EDU_MTD                 --교육대상
                    ,EDU_CTS                 --공통교육내용
                    ,EDU_CTS2                --개별교육내용
                    ,EDU_CTS3                --기타교육내용
                    ,MSDS_RMKS               --MSDS비고
                    ,PHOTO_GRP1              --첨부파일그룹사진1
                    ,PHOTO_DESC_1            --사진설명1
                    ,PHOTO_DT_1              --사진설명1
                    ,PHOTO_GRP2              --첨부파일그룹사진2
                    ,PHOTO_DESC_2            --사진설명2
                    ,PHOTO_DT_2              --사진설명1
                    ,PHOTO_GRP3              --첨부파일그룹사진3
                    ,PHOTO_DESC_3            --사진설명3
		            ,PHOTO_DT_3              --사진일자3
                    ,ATFL_GRP                --첨부파일그룹
                    ,APRV_NO                 --결재번호
                    ,IPT_ID                  --입력ID
                    ,IPT_DTM                 --입력일시
                    ,IPT_IP                  --입력IP
                    ,UPD_ID                  --수정ID
                    ,UPD_DTM                 --수정일시
                    ,UPD_IP                  --수정IP
                    )
             VALUES (p_SIT_CD                --현장코드
                    ,v_EDU_SEQ               --교육순번
                    ,p_EDU_CD                --교육코드
                    ,p_DEEDU_CD              --교육세부코드
                    ,p_COP_VNDR_NM           --협력업체명칭
                    ,p_EDU_DT                --교육일자
                    ,p_EDU_TIME              --교육시간
                    ,p_REL_LNR1              --관련법규1
                    ,p_REL_LNR2              --관련법규2
                    ,p_EDU_OBJ_MAN           --교육대상인원
                    ,p_EDU_IMPL_MAN          --교육실시인원
                    ,p_USE_TCMT              --교육방법
                    ,p_EDU_IMPL              --교육강사
                    ,p_EDU_PLC               --교육장소
                    ,p_EDU_MTD               --교육대상
                    ,p_EDU_CTS               --공통교육내용
                    ,p_EDU_CTS2              --개별교육내용
                    ,p_EDU_CTS3              --기타교육내용
                    ,p_MSDS_RMKS             --MSDS비고
                    ,p_PHOTO_GRP1            --첨부파일그룹사진1
                    ,p_PHOTO_DESC_1          --사진설명1
                    ,p_PHOTO_DT_1            --사진설명1
                    ,p_PHOTO_GRP2            --첨부파일그룹사진2
                    ,p_PHOTO_DESC_2          --사진설명2
                    ,p_PHOTO_DT_2            --사진설명2
                    ,p_PHOTO_GRP3            --첨부파일그룹사진3
   	                ,p_PHOTO_DESC_3          --사진설명3
	                ,p_PHOTO_DT_3            --사진일자3
                    ,p_ATFL_GRP              --첨부파일그룹
                    ,p_APRV_NO               --결재번호
                    ,p_WRK_ID                --입력ID 
                    ,SYSDATE()               --입력일시
                    ,p_WRK_IP                --입력IP
                    ,p_WRK_ID                --수정ID
                    ,SYSDATE()               --수정일시
                    ,p_WRK_IP)              --수정IP
        ;

    END IF;

    p_RTN_EDU_SEQ := v_EDU_SEQ;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 5. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);

END ;
/

-- PQHA_EMG_TRN_Q (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_EMG_TRN_Q"
							 (p_WRK_TP  VARCHAR2 :='Q'
                             ,p_WRK_ID  VARCHAR2                                            -- 사용자 ID
                             ,p_WRK_IP  VARCHAR2                                            -- 사용자 IP
						     ,p_SIT_CD TQHA_EMG_TRN.SIT_CD%TYPE                             -- 현장코드
						     ,p_TRN_FRDT TQHA_EMG_TRN.TRN_DT%TYPE                           -- 작성시작일자
						     ,p_TRN_TODT TQHA_EMG_TRN.TRN_DT%TYPE                           -- 작성종료일자
						     ,p_HALF_DIV TQHA_EMG_TRN.TRN_DT%TYPE                          
						     ,RTN_CURSOR OUT SYS_REFCURSOR
							)  
IS 
    /**************************************************************************************************************************
      Purpose : 

      REVISIONS
      Ver      Date               Author                  Description 
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2026/05/21 17:00:27                         최초생성

    /**************************************************************************************************************************/


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR2(200);            -- ERROR Message
    USER_EXCEPTION EXCEPTION;


BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 수행전 Check Logic ]
    ---------------------------------------------------------------------------------------------------------------------------


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Logic 처리
    ---------------------------------------------------------------------------------------------------------------------------

    OPEN RTN_CURSOR FOR
    SELECT  A.SIT_CD                 --현장코드
           ,( SELECT CNST_NM FROM VQSZ_SITEINFO WHERE SIT_CD = A.SIT_CD ) AS SIT_NM
           ,A.TRN_SEQ                 --훈련순번
           ,A.HALF_DIV                 --상하반기구분
           ,A.TRN_NM                 --훈련명
           ,A.TRN_DT                 --훈련일자
           ,A.TRN_CTS                 --훈련내용
           ,A.RMKS                 --비고
           ,A.ATFL_GRP                 --첨부파일그룹
      FROM TQHA_EMG_TRN A
    WHERE SIT_CD LIKE p_SIT_CD ||'%'
      AND HALF_DIV LIKE p_HALF_DIV ||'%'
      AND TRN_DT BETWEEN NVL(p_TRN_FRDT, '19000101') AND NVL(p_TRN_TODT, '47121231')
      ORDER BY SIT_CD, TRN_DT DESC
		;


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN 
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);
END ;
/

-- PQHA_EMG_TRN_S (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_EMG_TRN_S"
                            (p_WRK_TP  VARCHAR2 :='U'                                     -- UPDATE FLAG( I: ISNERT, U:UPDATE, D:DELTE)
                            ,p_WRK_ID  VARCHAR2                                           -- 사용자 ID 
                            ,p_WRK_IP  VARCHAR2                                           -- 사용자 IP 
                            ,p_SIT_CD TQHA_EMG_TRN.SIT_CD%TYPE                            -- 현장코드
                            ,p_TRN_SEQ TQHA_EMG_TRN.TRN_SEQ%TYPE                          -- 훈련순번
                            ,p_HALF_DIV TQHA_EMG_TRN.HALF_DIV%TYPE                        -- 상하반기구분
                            ,p_TRN_NM TQHA_EMG_TRN.TRN_NM%TYPE                            -- 훈련명
                            ,p_TRN_DT TQHA_EMG_TRN.TRN_DT%TYPE                            -- 훈련일자
                            ,p_TRN_CTS TQHA_EMG_TRN.TRN_CTS%TYPE                          -- 훈련내용
                            ,p_RMKS TQHA_EMG_TRN.RMKS%TYPE                                -- 비고
                            ,p_ATFL_GRP TQHA_EMG_TRN.ATFL_GRP%TYPE)                       -- 첨부파일그룹
IS 
    /**************************************************************************************************************************
      Purpose :  

      REVISIONS
      Ver      Date               Author                  Description 
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2026/05/22 11:17:56                         최초생성

    /**************************************************************************************************************************/


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR2(200);            -- ERROR Message
    USER_EXCEPTION EXCEPTION;

	v_SEQ NUMBER;
	
BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 필수입력 필드  Check  ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_SIT_CD IS NULL)  THEN
        ERR_MSG := '현장코드는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_WRK_TP != 'I' AND p_TRN_SEQ IS NULL)  THEN
        ERR_MSG := '순번는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_HALF_DIV IS NULL)  THEN
        ERR_MSG := '상하반기구분는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Process 선행조건 Check ]
    ---------------------------------------------------------------------------------------------------------------------------

	SELECT NVL(MAX(TRN_SEQ), 0) + 1 INTO v_SEQ
    FROM TQHA_EMG_TRN
    WHERE SIT_CD = p_SIT_CD;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Business Process ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_WRK_TP ='D') THEN
        DELETE 
          FROM TQHA_EMG_TRN
         WHERE SIT_CD = p_SIT_CD          --현장코드
           AND TRN_SEQ = p_TRN_SEQ;        --훈련순번

    ELSIF (p_WRK_TP ='U') THEN
        UPDATE TQHA_EMG_TRN
           SET HALF_DIV             = p_HALF_DIV                --상하반기구분
              ,TRN_NM               = p_TRN_NM                  --훈련명
              ,TRN_DT               = p_TRN_DT                  --훈련일자
              ,TRN_CTS              = p_TRN_CTS                 --훈련내용
              ,RMKS                 = p_RMKS                    --비고
              ,ATFL_GRP             = p_ATFL_GRP                --첨부파일그룹
              ,UPD_ID               = p_WRK_ID                  --수정ID 
              ,UPD_DTM              = SYSDATE()                 --수정일시
              ,UPD_IP               = p_WRK_IP                  --수정IP
         WHERE SIT_CD = p_SIT_CD          --현장코드
           AND TRN_SEQ = p_TRN_SEQ;        --훈련순번
    ELSE 
        INSERT INTO TQHA_EMG_TRN
                   ( SIT_CD                  --현장코드
                    ,TRN_SEQ                 --훈련순번
                    ,HALF_DIV                --상하반기구분
                    ,TRN_NM                  --훈련명
                    ,TRN_DT                  --훈련일자
                    ,TRN_CTS                 --훈련내용
                    ,RMKS                    --비고
                    ,ATFL_GRP                --첨부파일그룹
                    ,IPT_ID                  --입력ID
                    ,IPT_DTM                 --입력일시
                    ,IPT_IP                  --입력IP
                    ,UPD_ID                  --수정ID
                    ,UPD_DTM                 --수정일시
                    ,UPD_IP                  --수정IP
                    )
             VALUES (p_SIT_CD                --현장코드
                    ,v_SEQ               --훈련순번
                    ,p_HALF_DIV              --상하반기구분
                    ,p_TRN_NM                --훈련명
                    ,p_TRN_DT                --훈련일자
                    ,p_TRN_CTS               --훈련내용
                    ,p_RMKS                  --비고
                    ,p_ATFL_GRP              --첨부파일그룹
                    ,p_WRK_ID                --입력ID 
                    ,SYSDATE()               --입력일시
                    ,p_WRK_IP                --입력IP
                    ,p_WRK_ID                --수정ID
                    ,SYSDATE()               --수정일시
                    ,p_WRK_IP);              --수정IP
    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 5. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN 
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);
END ;
/

-- PQHA_EQMTABK_Q (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_EQMTABK_Q" (
    p_WRK_TP            IN VARCHAR2 DEFAULT 'Q'         -- FLAG
,   p_SIT_CD            IN VARCHAR2                     -- 현장코드
,   p_CUST_CD           IN VARCHAR2                     -- 거래처코드
,   p_STR_DT            IN VARCHAR2                     -- 시작일자
,   p_END_DT            IN VARCHAR2                     -- 종료일자
,   p_UPLOAD_PATH       IN VARCHAR2                     -- 업로드경로
,   RTN_CURSOR          OUT SYS_REFCURSOR
)
IS
    /**************************************************************************************************************************
      Purpose : [건설기계관리대장 조회] PROCEDRE (QSE > 재해예방관리 > 건설기계관리대장  ) 

      REVISIONS
      Ver      Date               Author                  Description
      -------  -----------------  ----------------------  ---------------------------------------------------------------------
      1.0      XXXX/XX/XX                                 최초생성

    **************************************************************************************************************************/

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE  NUMBER :=-20009; -- ERROR 코드
    ERR_MSG   VARCHAR(200);    -- ERROR Message
    USER_EXCEPTION EXCEPTION;

BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 수행전 Check Logic ]
    ---------------------------------------------------------------------------------------------------------------------------

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Logic 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------

    IF p_WRK_TP = 'Q' THEN

        OPEN RTN_CURSOR FOR
        SELECT TE.SIT_CD               -- 현장코드
             , TE.REG_NO                -- 등록번호
--             , (SELECT --PKG_XX1.DEC_VARCHAR2_SEL(BR_NO , 10 , 'SSN' , 'TQSZ_SITECOPCO' ,'BR_NO') AS BR_NO  -- 개인정보_사업자등록번호
--                         BR_NO                
--                 FROM TQSZ_SITECOPCO
--                WHERE SIT_CD = TE.SIT_CD
--                  AND CUST_CD = TE.CUST_CD
--                  AND ROWNUM = 1             
--               ) AS BR_NO
             , NULL AS BR_NO
             , TE.MNF_YM                -- 제조년월
             , TE.CNST_MCH_CD           -- 공통코드 QSI01
             , TE.INSU_NOTI_YN          -- 공통코드 QSI02
             , TE.INSU_JN_STR_DD        -- 보험가입시작일
             , TE.INSU_JN_END_DD        -- 보험가입종료일
             , TE.INSU_CTS_1            -- 대인
             , TE.INSU_CTS_2            -- 대물
             , TE.INSU_CTS_3            -- 자차
             , TE.INSU_CTS_4            -- 자손
             , TE.DRVR_PNM              -- 운전원성명
--             , PKG_XX1.DEC_VARCHAR2_SEL(TE.DRVR_CELPH , 10 , 'SSN' , 'TQSI_EQMTABK' ,'TE.DRVR_CELPH') AS DRVR_CELPH            -- 개인정보_운전원핸드폰
             , TE.DRVR_CELPH
             , TE.DRVR_QLF              -- 운전원자격
             , TE.CUST_CD               -- 협력회사
             , TE.CUST_NM               -- 거래처명
             , TE.CNST_MCH_CO           -- 건설기계회사
             , TE.USE_USG               -- 사용용도 
             , TE.CIN_DT                -- 반입일자
             , TE.ATFL_GRP              -- 운전원사진
             , FQHA_GETCMSITENM_BY_SITECD(TE.SIT_CD) AS SIT_NM
             , p_UPLOAD_PATH             AS UPLOAD_PATH
             , TE.RGL_STR_DD
             , TE.RGL_END_DD
             , TE.MNG_PNM
             , TE.MNG_CELPH
          FROM TQHA_EQMTABK TE
         WHERE 1=1
           AND TE.SIT_CD  = NVL(p_SIT_CD, TE.SIT_CD)
           AND TE.CUST_CD = NVL(p_CUST_CD, TE.CUST_CD)
           AND (NVL(p_STR_DT, 'X') = 'X' OR TE.CIN_DT >= p_STR_DT)
           AND (NVL(p_END_DT, 'X') = 'X' OR TE.CIN_DT <= p_END_DT)
         ORDER BY TE.CIN_DT DESC, TE.INSU_JN_END_DD DESC
        ;

    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
         WHEN OTHERS THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);

END PQHA_EQMTABK_Q;
/

-- PQHA_EQMTABK_S (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_EQMTABK_S" (
    p_WRK_TP                    VARCHAR2                                            -- UPDATE FLAG( I: ISNERT, U:UPDATE, D:DELTE)
,   p_WRK_ID                    VARCHAR2                                            -- 사용자 ID
,   p_WRK_IP                    VARCHAR2                                            -- 사용자 IP
,   p_SIT_CD                    TQHA_EQMTABK.SIT_CD                 %TYPE           -- 현장코드
,   p_REG_NO                    TQHA_EQMTABK.REG_NO                 %TYPE           -- 등록번호
,   p_MNF_YM                    TQHA_EQMTABK.MNF_YM                 %TYPE           -- 제조년월
,   p_CNST_MCH_CD               TQHA_EQMTABK.CNST_MCH_CD            %TYPE           -- 공통코드 QSA01
,   p_INSU_NOTI_YN              TQHA_EQMTABK.INSU_NOTI_YN           %TYPE           -- 공통코드 QSA02
,   p_INSU_JN_STR_DD            TQHA_EQMTABK.INSU_JN_STR_DD         %TYPE           -- 보험가입시작일
,   p_INSU_JN_END_DD            TQHA_EQMTABK.INSU_JN_END_DD         %TYPE           -- 보험가입종료일
,   p_INSU_CTS_1                TQHA_EQMTABK.INSU_CTS_1             %TYPE           -- 대인
,   p_INSU_CTS_2                TQHA_EQMTABK.INSU_CTS_2             %TYPE           -- 대물
,   p_INSU_CTS_3                TQHA_EQMTABK.INSU_CTS_3             %TYPE           -- 자차
,   p_INSU_CTS_4                TQHA_EQMTABK.INSU_CTS_4             %TYPE           -- 자손
,   p_DRVR_PNM                  TQHA_EQMTABK.DRVR_PNM               %TYPE           -- 운전원성명
,   p_DRVR_CELPH                VARCHAR2                                            -- 개인정보_운전원핸드폰
,   p_DRVR_QLF                  TQHA_EQMTABK.DRVR_QLF               %TYPE           -- 운전원자격
,   p_CUST_CD                   TQHA_EQMTABK.CUST_CD                %TYPE           -- 협력회사
,   p_CUST_NM                   TQHA_EQMTABK.CUST_NM                %TYPE           -- 거래처명
,   p_CNST_MCH_CO               TQHA_EQMTABK.CNST_MCH_CO            %TYPE           -- 건설기계회사
,   p_USE_USG                   TQHA_EQMTABK.USE_USG                %TYPE           -- 사용용도
,   p_CIN_DT                    TQHA_EQMTABK.CIN_DT                 %TYPE           -- 반입일자
,   p_ATFL_GRP                  TQHA_EQMTABK.ATFL_GRP               %TYPE           -- 운전원사진
,   p_RGL_STR_DD                TQHA_EQMTABK.RGL_STR_DD             %TYPE
,   p_RGL_END_DD                TQHA_EQMTABK.RGL_END_DD             %TYPE
,   p_MNG_PNM              	    TQHA_EQMTABK.MNG_PNM                %TYPE
,   p_MNG_CELPH                 TQHA_EQMTABK.MNG_CELPH              %TYPE

)
IS
    /**************************************************************************************************************************
      Purpose :

      REVISIONS
      Ver      Date               Author                  Description
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2019/05/07 16:27:00                         최초생성

    /**************************************************************************************************************************/


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR(200);             -- ERROR Message
    USER_EXCEPTION EXCEPTION;

    v_cnt INTEGER;


BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 필수입력 필드  Check  ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_SIT_CD IS NULL)  THEN
        ERR_MSG := '현장코드는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_REG_NO IS NULL)  THEN
        ERR_MSG := '등록번호는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_CUST_CD IS NULL)  THEN
        ERR_MSG := '협력회사는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_REG_NO IS NOT NULL)  THEN

        SELECT COUNT(p_REG_NO) INTO v_cnt
          FROM TQHA_EQMTABK
         WHERE REG_NO = p_REG_NO;

    END IF;

    IF (v_cnt > 0 AND p_WRK_TP !='U' AND p_WRK_TP != 'U2'  AND p_WRK_TP !='D')  THEN
        ERR_MSG := '등록번호 ' || p_REG_NO || '은 기등록  번호입니다.';
        RAISE USER_EXCEPTION;
    END IF;


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Process 선행조건 Check ]
    ---------------------------------------------------------------------------------------------------------------------------



    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Business Process ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_WRK_TP ='D') THEN

        DELETE
          FROM TQHA_EQMTABK
         WHERE SIT_CD   = p_SIT_CD      -- 현장코드
           AND REG_NO   = p_REG_NO      -- 등록번호
        ;

    ELSIF (p_WRK_TP ='U2') THEN --사진저장

        UPDATE TQHA_EQMTABK
           SET ATFL_GRP     = p_ATFL_GRP
             , UPD_ID       = p_WRK_ID          -- 수정ID
             , UPD_DTM      = SYSDATE()         -- 수정일시
             , UPD_IP       = p_WRK_IP
         WHERE SIT_CD       = p_SIT_CD          -- 현장코드
           AND REG_NO       = p_REG_NO
        ;

    ELSE

        MERGE 
          INTO TQHA_EQMTABK
         USING DUAL
        ON (    SIT_CD = p_SIT_CD 
            AND REG_NO = p_REG_NO
           )
        WHEN MATCHED THEN
            UPDATE 
               SET MNF_YM               = REPLACE(p_MNF_YM,'-','')          -- 제조년월
                 , CNST_MCH_CD          = p_CNST_MCH_CD                     -- 공통코드 QSA01
                 , INSU_NOTI_YN         = p_INSU_NOTI_YN                    -- 공통코드 QSA02
                 , INSU_JN_STR_DD       = REPLACE(p_INSU_JN_STR_DD,'-','')  -- 보험가입시작일
                 , INSU_JN_END_DD       = REPLACE(p_INSU_JN_END_DD,'-','')  -- 보험가입종료일
                 , INSU_CTS_1           = p_INSU_CTS_1                      -- 대인
                 , INSU_CTS_2           = p_INSU_CTS_2                      -- 대물
                 , INSU_CTS_3           = p_INSU_CTS_3                      -- 자차
                 , INSU_CTS_4           = p_INSU_CTS_4                      -- 자손
                 , DRVR_PNM             = p_DRVR_PNM                        -- 운전원성명
                 , DRVR_CELPH           = REPLACE(p_DRVR_CELPH,'-','') --PKG_XX1.ENC_VARCHAR2_INS(REPLACE(P_DRVR_CELPH,'-','') , 10 , 'SSN','TQHA_EQMTABK','DRVR_CELPH' ) --개인정보_운전원핸드폰
                 , DRVR_QLF             = p_DRVR_QLF                        -- 운전원자격
                 , CUST_CD              = p_CUST_CD                         -- 협력회사
                 , CUST_NM              = p_CUST_NM                         -- 거래처명
                 , CNST_MCH_CO          = p_CNST_MCH_CO                     -- 건설기계회사
                 , USE_USG              = p_USE_USG                         -- 사용용도
                 , CIN_DT               = REPLACE(p_CIN_DT,'-','')          -- 반입일자
                 , ATFL_GRP             = p_ATFL_GRP
                 , RGL_STR_DD           = REPLACE(p_RGL_STR_DD,'-','')
				 , RGL_END_DD			= REPLACE(p_RGL_END_DD,'-','')
				 , MNG_PNM              = p_MNG_PNM                       
                 , MNG_CELPH            = REPLACE(p_MNG_CELPH,'-','')
                 , UPD_ID               = p_WRK_ID                          -- 수정ID
                 , UPD_DTM              = SYSDATE()                         -- 수정일시
                 , UPD_IP               = p_WRK_IP                          -- 수정IP
        WHEN NOT MATCHED THEN
            INSERT
                 ( SIT_CD                               -- 현장코드
                 , REG_NO                               -- 등록번호
                 , MNF_YM                               -- 제조년월
                 , CNST_MCH_CD                          -- 공통코드 QSA01
                 , INSU_NOTI_YN                         -- 공통코드 QSA02
                 , INSU_JN_STR_DD                       -- 보험가입시작일
                 , INSU_JN_END_DD                       -- 보험가입종료일
                 , INSU_CTS_1                           -- 대인
                 , INSU_CTS_2                           -- 대물
                 , INSU_CTS_3                           -- 자차
                 , INSU_CTS_4                           -- 자손
                 , DRVR_PNM                             -- 운전원성명
                 , DRVR_CELPH                           -- 개인정보_운전원핸드폰
                 , DRVR_QLF                             -- 운전원자격
                 , CUST_CD                              -- 협력회사
                 , CUST_NM                              -- 거래처명
                 , CNST_MCH_CO                          -- 건설기계회사
                 , USE_USG                              -- 사용용도
                 , CIN_DT                               -- 반입일자
                 , ATFL_GRP                             -- 운전원사진
                 , RGL_STR_DD
				 , RGL_END_DD
				 , MNG_PNM                       
                 , MNG_CELPH
                 , IPT_ID                               -- 신규입력ID
                 , IPT_DTM                              -- 신규입력일시
                 , IPT_IP                               -- 신규입력IP
                 , UPD_ID                               -- 최종수정ID
                 , UPD_DTM                              -- 최종수정일시
                 , UPD_IP                               -- 최종수정IP
                 )
            VALUES 
                 ( p_SIT_CD                             -- 현장코드
                 , p_REG_NO                             -- 등록번호
                 , REPLACE(p_MNF_YM,'-','')             -- 제조년월
                 , p_CNST_MCH_CD                        -- 공통코드 QSA01
                 , p_INSU_NOTI_YN                       -- 공통코드 QSA02
                 , REPLACE(p_INSU_JN_STR_DD,'-','')     -- 보험가입시작일
                 , REPLACE(p_INSU_JN_END_DD,'-','')     -- 보험가입종료일
                 , p_INSU_CTS_1                         -- 대인
                 , p_INSU_CTS_2                         -- 대물
                 , p_INSU_CTS_3                         -- 자차
                 , p_INSU_CTS_4                         -- 자손
                 , p_DRVR_PNM                           -- 운전원성명
--               , PKG_XX1.ENC_VARCHAR2_INS(REPLACE(p_DRVR_CELPH,'-','') , 10 , 'SSN','TQHA_EQMTABK','DRVR_CELPH' ) --개인정보_운전원핸드폰
                 , REPLACE(p_DRVR_CELPH,'-','')
                 , p_DRVR_QLF                           -- 운전원자격
                 , p_CUST_CD                            -- 협력회사
                 , p_CUST_NM                            -- 거래처명
                 , p_CNST_MCH_CO                        -- 건설기계회사
                 , p_USE_USG                            -- 사용용도
                 , REPLACE(p_CIN_DT,'-','')             -- 반입일자
                 , p_ATFL_GRP                           -- 운전원사진
                 , REPLACE(p_RGL_STR_DD,'-','')
				 , REPLACE(p_RGL_END_DD,'-','')
				 , p_MNG_PNM                       
                 , REPLACE(p_MNG_CELPH,'-','')
                 , p_WRK_ID                             -- 입력ID
                 , SYSDATE()                            -- 입력일시
                 , p_WRK_IP                             -- 입력IP
                 , p_WRK_ID                             -- 수정ID
                 , SYSDATE()                            -- 수정일시
                 , p_WRK_IP                             -- 수정IP
                 )
            ;

    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 5. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
         WHEN OTHERS THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);

END;
/

-- PQHA_HLTH_CHKUP_EXCEL_DEL_S (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_HLTH_CHKUP_EXCEL_DEL_S"
                            (p_WRK_TP  VARCHAR2 :='U'                                     -- UPDATE FLAG( I: ISNERT, U:UPDATE, D:DELTE)
                            ,p_WRK_ID  VARCHAR2                                           -- 사용자 ID 
                            ,p_WRK_IP  VARCHAR2                                           -- 사용자 IP 
                            ,p_SIT_CD TQHA_HLTH_CHKUP_LIST.SIT_CD%TYPE                    -- 현장코드
                            ,p_CHKUP_YY TQHA_HLTH_CHKUP_LIST.CHKUP_YY%TYPE                -- 검진연도
                            ,p_CHKUP_DIV VARCHAR2						                  -- 검진구분
                            )
IS 
    /**************************************************************************************************************************
      Purpose : 

      REVISIONS
      Ver      Date               Author                  Description 
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2026/06/16 15:43:31                         최초생성

    /**************************************************************************************************************************/


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR2(200);            -- ERROR Message
    USER_EXCEPTION EXCEPTION;

	v_SEQ NUMBER;
	v_CUST_CD NUMBER;
BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 필수입력 필드  Check  ]
    ---------------------------------------------------------------------------------------------------------------------------

	
    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Process 선행조건 Check ]
    ---------------------------------------------------------------------------------------------------------------------------
    DELETE 
      FROM TQHA_HLTH_CHKUP_LIST
     WHERE SIT_CD = p_SIT_CD           
       AND CHKUP_YY = p_CHKUP_YY      
       AND CHKUP_DIV = (CASE WHEN LENGTH(p_CHKUP_DIV) <= 2 THEN LPAD(p_CHKUP_DIV, 2, '0')
					      ELSE (SELECT COM_CD FROM TCOA_COMCODE WHERE HRNK_CD = 'QS068' AND CD_NM = p_CHKUP_DIV) --검진구분
					 END)
      ;   

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 5. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN 
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);
END ;
/

-- PQHA_HLTH_CHKUP_EXCEL_S (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_HLTH_CHKUP_EXCEL_S"
                            (p_WRK_TP  VARCHAR2 :='U'                                     -- UPDATE FLAG( I: ISNERT, U:UPDATE, D:DELTE)
                            ,p_WRK_ID  VARCHAR2                                           -- 사용자 ID 
                            ,p_WRK_IP  VARCHAR2                                           -- 사용자 IP 
                            ,p_SIT_CD TQHA_HLTH_CHKUP_LIST.SIT_CD%TYPE                    -- 현장코드
                            ,p_CHKUP_YY TQHA_HLTH_CHKUP_LIST.CHKUP_YY%TYPE                -- 검진연도
                            ,p_CHKUP_SEQ TQHA_HLTH_CHKUP_LIST.CHKUP_SEQ%TYPE              -- 검진순번
                            ,p_CHKUP_DIV VARCHAR2						                  -- 검진구분
                            ,p_CUST_CD TQHA_HLTH_CHKUP_LIST.CUST_CD%TYPE                  -- 업체코드
                            ,p_VNDR_SEQ TQHA_HLTH_CHKUP_LIST.VNDR_SEQ%TYPE                -- 업체순번
                            ,p_DGS_DT TQHA_HLTH_CHKUP_LIST.DGS_DT%TYPE                    -- 진단일자
                            ,p_CHKUP_NM TQHA_HLTH_CHKUP_LIST.CHKUP_NM%TYPE                -- 검진자
                            ,p_CHKUP_AGE TQHA_HLTH_CHKUP_LIST.CHKUP_AGE%TYPE              -- 연령
                            ,p_HRM_ARG TQHA_HLTH_CHKUP_LIST.HRM_ARG%TYPE                  -- 유해인자
                            ,p_HLTH_DIV TQHA_HLTH_CHKUP_LIST.HLTH_DIV%TYPE                -- 건강구분
                            ,p_CHKUP_OPIN TQHA_HLTH_CHKUP_LIST.CHKUP_OPIN%TYPE            -- 검진의견
                            ,p_POST_MNG_OPIN TQHA_HLTH_CHKUP_LIST.POST_MNG_OPIN%TYPE      -- 사후관리의견
                            ,p_DUTY_FIT TQHA_HLTH_CHKUP_LIST.DUTY_FIT%TYPE                -- 업무수행적합도
                            ,p_RSLT_NOTI_YN TQHA_HLTH_CHKUP_LIST.RSLT_NOTI_YN%TYPE        -- 결과통보여부
                            ,p_HLTH_CNS_YN TQHA_HLTH_CHKUP_LIST.HLTH_CNS_YN%TYPE          -- 건강상담여부
                            ,p_PREQ_PAY_YN TQHA_HLTH_CHKUP_LIST.PREQ_PAY_YN%TYPE          -- 보호구지급여부
                            ,p_TRC_EM_YN TQHA_HLTH_CHKUP_LIST.TRC_EM_YN%TYPE              -- 추적검사여부
                            ,p_WRK_TRT_YN TQHA_HLTH_CHKUP_LIST.WRK_TRT_YN%TYPE            -- 근무중치료여부
                            ,p_MOEL_RPT_YN TQHA_HLTH_CHKUP_LIST.MOEL_RPT_YN%TYPE          -- 노동부보고여부
                            ,p_RTCO_YN TQHA_HLTH_CHKUP_LIST.RTCO_YN%TYPE                  -- 퇴수여부
                            ,p_RMKS TQHA_HLTH_CHKUP_LIST.RMKS%TYPE                        -- 비고
                            ,p_ATFL_GRP TQHA_HLTH_CHKUP_LIST.ATFL_GRP%TYPE                -- 첨부파일그룹
                            ,p_PROC_NM TQHA_HLTH_CHKUP_LIST.PROC_NM%TYPE                  -- 공정명
                            ,p_BZMN_NO VARCHAR2  										  -- 사업자번호
                            )
IS 
    /**************************************************************************************************************************
      Purpose : 

      REVISIONS
      Ver      Date               Author                  Description 
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2026/06/16 15:43:31                         최초생성

    /**************************************************************************************************************************/


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR2(200);            -- ERROR Message
    USER_EXCEPTION EXCEPTION;

	v_SEQ NUMBER;
	v_CNT NUMBER;
	v_CUST_CD NUMBER;
BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 필수입력 필드  Check  ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_SIT_CD IS NULL)  THEN
        ERR_MSG := '현장코드는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION; 
    END IF;

    IF (p_CHKUP_YY IS NULL)  THEN
        ERR_MSG := '검진연도는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_CHKUP_DIV IS NULL)  THEN
        ERR_MSG := '검진구분는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_BZMN_NO IS NULL)  THEN
        ERR_MSG := '사업자번호는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;
    
    IF (p_CHKUP_NM IS NULL)  THEN
        ERR_MSG := '이름는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;
    
    IF (p_CHKUP_AGE IS NULL)  THEN
        ERR_MSG := '연령는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;
    
    IF (p_HLTH_DIV IS NULL)  THEN
        ERR_MSG := '건강구분는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;
    
    IF (p_CHKUP_DIV IN ('06','07','배치전(수시)','특수(수시)') AND p_DGS_DT IS NULL)  THEN
        ERR_MSG := '수시는 진단일이 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;
    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Process 선행조건 Check ]
    ---------------------------------------------------------------------------------------------------------------------------
       
    -- 거래처번호 가져오기
    SELECT MAX(CUST_CD) INTO v_CUST_CD
--    FROM VQSZ_TRADE 
--    WHERE BZMN_NO = REPLACE(p_BZMN_NO,'-','')
    FROM TCOA_TRADE 
    WHERE BR_NO = REPLACE(p_BZMN_NO,'-','')    
    ;    
    
    IF (v_CUST_CD IS NULL)  THEN
        ERR_MSG := '사업자번호 ' || p_BZMN_NO || ' 의 업체정보가 없습니다.';
        RAISE USER_EXCEPTION;
    END IF;

	SELECT NVL(MAX(CHKUP_SEQ),0) + 1 INTO v_SEQ
      FROM TQHA_HLTH_CHKUP_LIST
     WHERE SIT_CD = p_SIT_CD          --현장코드
       AND CHKUP_YY = p_CHKUP_YY        --검진연도
    ;
	
/*
	-- 수시항목 중복값 찾기
	 SELECT COUNT(1) INTO v_CNT
      FROM TQHA_HLTH_CHKUP_LIST
     WHERE SIT_CD = p_SIT_CD          --현장코드
       AND CHKUP_YY = p_CHKUP_YY      --검진연도
       AND CUST_CD = v_CUST_CD     
       AND CHKUP_NM = p_CHKUP_NM     
       AND CHKUP_AGE = p_CHKUP_AGE
       AND CHKUP_DIV IN ('06','07')
       AND DGS_DT = REPLACE(p_DGS_DT,'-','')
    ;
	
	IF (v_CNT > 0)  THEN
        ERR_MSG := '파일에 중복 데이터가 있어 진행할 수 없습니다.';
        RAISE USER_EXCEPTION;
    END IF;
*/	 
	
    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Business Process ]
    ---------------------------------------------------------------------------------------------------------------------------
    INSERT INTO TQHA_HLTH_CHKUP_LIST
                   ( SIT_CD                  --현장코드
                    ,CHKUP_YY                --검진연도
                    ,CHKUP_SEQ               --검진순번
                    ,CHKUP_DIV               --검진구분
                    ,CUST_CD                 --업체코드
                    ,VNDR_SEQ                --업체순번
                    ,DGS_DT                  --진단일자
                    ,CHKUP_NM                --검진자
                    ,CHKUP_AGE               --연령
                    ,HRM_ARG                 --유해인자
                    ,HLTH_DIV                --건강구분
                    ,CHKUP_OPIN              --검진의견
                    ,POST_MNG_OPIN           --사후관리의견
                    ,DUTY_FIT                --업무수행적합도
                    ,RSLT_NOTI_YN            --결과통보여부
                    ,HLTH_CNS_YN             --건강상담여부
                    ,PREQ_PAY_YN             --보호구지급여부
                    ,TRC_EM_YN               --추적검사여부
                    ,WRK_TRT_YN              --근무중치료여부
                    ,MOEL_RPT_YN             --노동부보고여부
                    ,RTCO_YN                 --퇴사여부
                    ,RMKS                    --비고
                    ,ATFL_GRP                --첨부파일그룹
                    ,PROC_NM
                    ,IPT_ID                  --입력ID
                    ,IPT_DTM                 --입력일시
                    ,IPT_IP                  --입력IP
                    ,UPD_ID                  --수정ID
                    ,UPD_DTM                 --수정일시
                    ,UPD_IP                  --수정IP
                    )
             VALUES (p_SIT_CD                --현장코드
                    ,p_CHKUP_YY              --검진연도
                    ,v_SEQ		             --검진순번
                    ,CASE WHEN LENGTH(p_CHKUP_DIV) <= 2 THEN LPAD(p_CHKUP_DIV, 2, '0')
					      ELSE (SELECT COM_CD FROM TCOA_COMCODE WHERE HRNK_CD = 'QS068' AND CD_NM = p_CHKUP_DIV) --검진구분
					 END
                    ,v_CUST_CD               --업체코드
                    ,1                       --업체순번
                    ,REPLACE(p_DGS_DT,'-','')  --진단일자
                    ,p_CHKUP_NM              --검진자
                    ,p_CHKUP_AGE             --연령
                    ,p_HRM_ARG               --유해인자
                    ,(SELECT COM_CD FROM TCOA_COMCODE WHERE HRNK_CD = 'QS066' AND CD_NM = p_HLTH_DIV) --건강구분
                    ,p_CHKUP_OPIN            --검진의견
                    ,p_POST_MNG_OPIN         --사후관리의견
                    ,(SELECT COM_CD FROM TCOA_COMCODE WHERE HRNK_CD = 'QS067' AND CD_NM = p_DUTY_FIT) --업무수행적합도
                    ,DECODE(p_RSLT_NOTI_YN,'○','1',p_RSLT_NOTI_YN)          --결과통보여부
                    ,DECODE(p_HLTH_CNS_YN,'○','1',p_HLTH_CNS_YN)           --건강상담여부
                    ,DECODE(p_PREQ_PAY_YN,'○','1',p_PREQ_PAY_YN)           --보호구지급여부
                    ,DECODE(p_TRC_EM_YN,'○','1',p_TRC_EM_YN)             --추적검사여부
                    ,DECODE(p_WRK_TRT_YN,'○','1',p_WRK_TRT_YN)            --근무중치료여부
                    ,DECODE(p_MOEL_RPT_YN,'○','1',p_MOEL_RPT_YN)           --노동부보고여부
                    ,DECODE(p_RTCO_YN,'○','1','퇴사','1',p_RTCO_YN)         --퇴사여부
                    ,p_RMKS                  --비고
                    ,p_ATFL_GRP              --첨부파일그룹
                    ,p_PROC_NM
                    ,p_WRK_ID                --입력ID 
                    ,SYSDATE()               --입력일시
                    ,p_WRK_IP                --입력IP
                    ,p_WRK_ID                --수정ID
                    ,SYSDATE()               --수정일시
                    ,p_WRK_IP);              --수정IP

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 5. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN 
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);
END ;
/

-- PQHA_HLTH_CHKUP_LIST_Q (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_HLTH_CHKUP_LIST_Q"
(
     p_WRK_TP  VARCHAR2 DEFAULT 'Q'                                                       -- FLAG( Q: SELECT )
     ,p_SIT_CD TQHA_HLTH_CHKUP_LIST.SIT_CD%TYPE                                           -- 현장코드
     ,p_CHKUP_YY TQHA_HLTH_CHKUP_LIST.CHKUP_YY%TYPE                                       -- 검진연도
     ,p_CHKUP_DIV TQHA_HLTH_CHKUP_LIST.CHKUP_DIV%TYPE
     ,RTN_CURSOR OUT SYS_REFCURSOR
)
IS 
    /**************************************************************************************************************************
      Purpose : 

      REVISIONS
      Ver      Date               Author                  Description 
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2026/06/16 15:40:16                         최초생성

    /**************************************************************************************************************************/


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR2(200);            -- ERROR Message
    USER_EXCEPTION EXCEPTION;


BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 수행전 Check Logic ]
    ---------------------------------------------------------------------------------------------------------------------------


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Logic 처리
    ---------------------------------------------------------------------------------------------------------------------------

    OPEN RTN_CURSOR FOR
    SELECT  A.SIT_CD                 --현장코드
           ,( SELECT DEPT_NM FROM TCOZ_DEPT_INFO WHERE DEPT_CD = A.SIT_CD ) AS SIT_NM -- 현장명칭
           ,A.CHKUP_YY                 --검진연도
           ,A.CHKUP_SEQ                 --검진순번
           ,A.CHKUP_DIV                 --검진구분
           ,A.CUST_CD                 --업체코드
           ,A.VNDR_SEQ                 --업체순번
           ,( SELECT CUST_NM FROM TCOA_TRADE WHERE CUST_CD = A.CUST_CD ) AS CUST_NM  -- 업체명칭
           ,A.DGS_DT                 --진단일자
           ,A.CHKUP_NM                 --검진자
           ,A.CHKUP_AGE                 --연령
           ,A.HRM_ARG                 --유해인자
           ,A.HLTH_DIV                 --건강구분
           ,A.CHKUP_OPIN                 --검진의견
           ,A.POST_MNG_OPIN                 --사후관리의견
           ,A.DUTY_FIT                 --업무수행적합도
           ,A.RSLT_NOTI_YN                 --결과통보여부
           ,A.HLTH_CNS_YN                 --건강상담여부
           ,A.PREQ_PAY_YN                 --보호구지급여부
           ,A.TRC_EM_YN                 --추적검사여부
           ,A.WRK_TRT_YN                 --근무중치료여부
           ,A.MOEL_RPT_YN                 --노동부보고여부
           ,A.RTCO_YN                 --퇴수여부
           ,A.RMKS                 --비고
           ,A.ATFL_GRP                 --첨부파일그룹
           ,A.PROC_NM
           ,(SELECT REPLACE(MAX(BR_NO),'-','') FROM TCOA_TRADE WHERE CUST_CD = A.CUST_CD) AS BZMN_NO
      FROM TQHA_HLTH_CHKUP_LIST A
    WHERE A.SIT_CD = p_SIT_CD                     --현장코드
      AND A.CHKUP_YY = p_CHKUP_YY                 --검진연도 
      AND A.CHKUP_DIV = p_CHKUP_DIV                    
    --ORDER BY A.CUST_CD, A.CHKUP_NM, A.CHKUP_AGE, A.CHKUP_SEQ
      ORDER BY A.SIT_CD, A.CHKUP_YY, A.CHKUP_SEQ
           ;
    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN 
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);
END ;
/

-- PQHA_HLTH_CHKUP_LIST_S (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_HLTH_CHKUP_LIST_S"
                            (p_WRK_TP  VARCHAR2 :='U'                                     -- UPDATE FLAG( I: ISNERT, U:UPDATE, D:DELTE)
                            ,p_WRK_ID  VARCHAR2                                           -- 사용자 ID 
                            ,p_WRK_IP  VARCHAR2                                           -- 사용자 IP 
                            ,p_SIT_CD TQHA_HLTH_CHKUP_LIST.SIT_CD%TYPE                    -- 현장코드
                            ,p_CHKUP_YY TQHA_HLTH_CHKUP_LIST.CHKUP_YY%TYPE                -- 검진연도
                            ,p_CHKUP_SEQ TQHA_HLTH_CHKUP_LIST.CHKUP_SEQ%TYPE              -- 검진순번
                            ,p_CHKUP_DIV TQHA_HLTH_CHKUP_LIST.CHKUP_DIV%TYPE              -- 검진구분
                            ,p_CUST_CD TQHA_HLTH_CHKUP_LIST.CUST_CD%TYPE                  -- 업체코드
                            ,p_VNDR_SEQ TQHA_HLTH_CHKUP_LIST.VNDR_SEQ%TYPE                -- 업체순번
                            ,p_DGS_DT TQHA_HLTH_CHKUP_LIST.DGS_DT%TYPE                    -- 진단일자
                            ,p_CHKUP_NM TQHA_HLTH_CHKUP_LIST.CHKUP_NM%TYPE                -- 검진자
                            ,p_CHKUP_AGE TQHA_HLTH_CHKUP_LIST.CHKUP_AGE%TYPE              -- 연령
                            ,p_HRM_ARG TQHA_HLTH_CHKUP_LIST.HRM_ARG%TYPE                  -- 유해인자
                            ,p_HLTH_DIV TQHA_HLTH_CHKUP_LIST.HLTH_DIV%TYPE                -- 건강구분
                            ,p_CHKUP_OPIN TQHA_HLTH_CHKUP_LIST.CHKUP_OPIN%TYPE            -- 검진의견
                            ,p_POST_MNG_OPIN TQHA_HLTH_CHKUP_LIST.POST_MNG_OPIN%TYPE      -- 사후관리의견
                            ,p_DUTY_FIT TQHA_HLTH_CHKUP_LIST.DUTY_FIT%TYPE                -- 업무수행적합도
                            ,p_RSLT_NOTI_YN TQHA_HLTH_CHKUP_LIST.RSLT_NOTI_YN%TYPE        -- 결과통보여부
                            ,p_HLTH_CNS_YN TQHA_HLTH_CHKUP_LIST.HLTH_CNS_YN%TYPE          -- 건강상담여부
                            ,p_PREQ_PAY_YN TQHA_HLTH_CHKUP_LIST.PREQ_PAY_YN%TYPE          -- 보호구지급여부
                            ,p_TRC_EM_YN TQHA_HLTH_CHKUP_LIST.TRC_EM_YN%TYPE              -- 추적검사여부
                            ,p_WRK_TRT_YN TQHA_HLTH_CHKUP_LIST.WRK_TRT_YN%TYPE            -- 근무중치료여부
                            ,p_MOEL_RPT_YN TQHA_HLTH_CHKUP_LIST.MOEL_RPT_YN%TYPE          -- 노동부보고여부
                            ,p_RTCO_YN TQHA_HLTH_CHKUP_LIST.RTCO_YN%TYPE                  -- 퇴수여부
                            ,p_RMKS TQHA_HLTH_CHKUP_LIST.RMKS%TYPE                        -- 비고
                            ,p_ATFL_GRP TQHA_HLTH_CHKUP_LIST.ATFL_GRP%TYPE               -- 첨부파일그룹
                            ,p_PROC_NM TQHA_HLTH_CHKUP_LIST.PROC_NM%TYPE                 -- 공정명
                            )
IS 
    /**************************************************************************************************************************
      Purpose : 

      REVISIONS
      Ver      Date               Author                  Description 
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2026/06/16 15:43:31                         최초생성

    /**************************************************************************************************************************/


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR2(200);            -- ERROR Message
    USER_EXCEPTION EXCEPTION;

	v_SEQ NUMBER;
BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 필수입력 필드  Check  ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_SIT_CD IS NULL)  THEN
        ERR_MSG := '현장코드는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_CHKUP_YY IS NULL)  THEN
        ERR_MSG := '검진연도는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_WRK_TP != 'I' AND p_CHKUP_SEQ IS NULL)  THEN
        ERR_MSG := '검진순번는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_CHKUP_DIV IS NULL)  THEN
        ERR_MSG := '검진구분는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_CUST_CD IS NULL)  THEN
        ERR_MSG := '업체코드는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_VNDR_SEQ IS NULL)  THEN
        ERR_MSG := '업체순번는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;
    
    IF (p_CHKUP_DIV IN ('06','07') AND p_DGS_DT IS NULL)  THEN
        ERR_MSG := '진단일는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Process 선행조건 Check ]
    ---------------------------------------------------------------------------------------------------------------------------

	SELECT NVL(MAX(CHKUP_SEQ),0) + 1 INTO v_SEQ
      FROM TQHA_HLTH_CHKUP_LIST
     WHERE SIT_CD = p_SIT_CD          --현장코드
       AND CHKUP_YY = p_CHKUP_YY        --검진연도
    ;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Business Process ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_WRK_TP ='D') THEN
        DELETE 
          FROM TQHA_HLTH_CHKUP_LIST
         WHERE SIT_CD = p_SIT_CD          --현장코드
           AND CHKUP_YY = p_CHKUP_YY        --검진연도
           AND CHKUP_SEQ = p_CHKUP_SEQ;      --검진순번

    ELSIF (p_WRK_TP ='U') THEN
        UPDATE TQHA_HLTH_CHKUP_LIST
           SET CHKUP_DIV            = p_CHKUP_DIV               --검진구분
              ,CUST_CD              = p_CUST_CD                 --업체코드
              ,VNDR_SEQ             = p_VNDR_SEQ                --업체순번
              ,DGS_DT               = p_DGS_DT                  --진단일자
              ,CHKUP_NM             = p_CHKUP_NM                --검진자
              ,CHKUP_AGE            = p_CHKUP_AGE               --연령
              ,HRM_ARG              = p_HRM_ARG                 --유해인자
              ,HLTH_DIV             = p_HLTH_DIV                --건강구분
              ,CHKUP_OPIN           = p_CHKUP_OPIN              --검진의견
              ,POST_MNG_OPIN        = p_POST_MNG_OPIN           --사후관리의견
              ,DUTY_FIT             = p_DUTY_FIT                --업무수행적합도
              ,RSLT_NOTI_YN         = p_RSLT_NOTI_YN            --결과통보여부
              ,HLTH_CNS_YN          = p_HLTH_CNS_YN             --건강상담여부
              ,PREQ_PAY_YN          = p_PREQ_PAY_YN             --보호구지급여부
              ,TRC_EM_YN            = p_TRC_EM_YN               --추적검사여부
              ,WRK_TRT_YN           = p_WRK_TRT_YN              --근무중치료여부
              ,MOEL_RPT_YN          = p_MOEL_RPT_YN             --노동부보고여부
              ,RTCO_YN              = p_RTCO_YN                 --퇴수여부
              ,RMKS                 = p_RMKS                    --비고
              ,ATFL_GRP             = p_ATFL_GRP                --첨부파일그룹
              ,PROC_NM              = p_PROC_NM
              ,UPD_ID               = p_WRK_ID                  --수정ID 
              ,UPD_DTM              = SYSDATE()                 --수정일시
              ,UPD_IP               = p_WRK_IP                  --수정IP
         WHERE SIT_CD = p_SIT_CD          --현장코드
           AND CHKUP_YY = p_CHKUP_YY        --검진연도
           AND CHKUP_SEQ = p_CHKUP_SEQ;      --검진순번
    ELSE 
        INSERT INTO TQHA_HLTH_CHKUP_LIST
                   ( SIT_CD                  --현장코드
                    ,CHKUP_YY                --검진연도
                    ,CHKUP_SEQ               --검진순번
                    ,CHKUP_DIV               --검진구분
                    ,CUST_CD                 --업체코드
                    ,VNDR_SEQ                --업체순번
                    ,DGS_DT                  --진단일자
                    ,CHKUP_NM                --검진자
                    ,CHKUP_AGE               --연령
                    ,HRM_ARG                 --유해인자
                    ,HLTH_DIV                --건강구분
                    ,CHKUP_OPIN              --검진의견
                    ,POST_MNG_OPIN           --사후관리의견
                    ,DUTY_FIT                --업무수행적합도
                    ,RSLT_NOTI_YN            --결과통보여부
                    ,HLTH_CNS_YN             --건강상담여부
                    ,PREQ_PAY_YN             --보호구지급여부
                    ,TRC_EM_YN               --추적검사여부
                    ,WRK_TRT_YN              --근무중치료여부
                    ,MOEL_RPT_YN             --노동부보고여부
                    ,RTCO_YN                 --퇴수여부
                    ,RMKS                    --비고
                    ,ATFL_GRP                --첨부파일그룹
                    ,PROC_NM
                    ,IPT_ID                  --입력ID
                    ,IPT_DTM                 --입력일시
                    ,IPT_IP                  --입력IP
                    ,UPD_ID                  --수정ID
                    ,UPD_DTM                 --수정일시
                    ,UPD_IP                  --수정IP
                    )
             VALUES (p_SIT_CD                --현장코드
                    ,p_CHKUP_YY              --검진연도
                    ,v_SEQ		             --검진순번
                    ,p_CHKUP_DIV             --검진구분
                    ,p_CUST_CD               --업체코드
                    ,p_VNDR_SEQ              --업체순번
                    ,p_DGS_DT                --진단일자
                    ,p_CHKUP_NM              --검진자
                    ,p_CHKUP_AGE             --연령
                    ,p_HRM_ARG               --유해인자
                    ,p_HLTH_DIV              --건강구분
                    ,p_CHKUP_OPIN            --검진의견
                    ,p_POST_MNG_OPIN         --사후관리의견
                    ,p_DUTY_FIT              --업무수행적합도
                    ,p_RSLT_NOTI_YN          --결과통보여부
                    ,p_HLTH_CNS_YN           --건강상담여부
                    ,p_PREQ_PAY_YN           --보호구지급여부
                    ,p_TRC_EM_YN             --추적검사여부
                    ,p_WRK_TRT_YN            --근무중치료여부
                    ,p_MOEL_RPT_YN           --노동부보고여부
                    ,p_RTCO_YN               --퇴수여부
                    ,p_RMKS                  --비고
                    ,p_ATFL_GRP              --첨부파일그룹
                    ,p_PROC_NM
                    ,p_WRK_ID                --입력ID 
                    ,SYSDATE()               --입력일시
                    ,p_WRK_IP                --입력IP
                    ,p_WRK_ID                --수정ID
                    ,SYSDATE()               --수정일시
                    ,p_WRK_IP);              --수정IP
    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 5. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN 
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);
END ;
/

-- PQHA_HLTH_CHKUP_Q (PROCEDURE, VALID)
CREATE PROCEDURE PQHA_HLTH_CHKUP_Q
(
      p_WRK_TP  VARCHAR2 DEFAULT 'Q'                                                      -- FLAG( Q: SELECT )
     ,p_SIT_CD TQHA_HLTH_CHKUP.SIT_CD%TYPE                                                -- 현장코드
     ,p_CHKUP_YY TQHA_HLTH_CHKUP.CHKUP_YY%TYPE                                            -- 검진연도
     ,p_CHKUP_DIV TQHA_HLTH_CHKUP_LIST.CHKUP_DIV%TYPE                                     
     ,p_CHKUP_YY_FR TQHA_HLTH_CHKUP.CHKUP_YY%TYPE                                            -- 검진연도
     ,p_CHKUP_YY_TO TQHA_HLTH_CHKUP.CHKUP_YY%TYPE                                            -- 검진연도
     ,RTN_CURSOR OUT SYS_REFCURSOR
)
IS 
    /**************************************************************************************************************************
      Purpose : 

      REVISIONS
      Ver      Date               Author                  Description 
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2026/06/16 15:07:45                         최초생성

    /**************************************************************************************************************************/


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR2(200);            -- ERROR Message
    USER_EXCEPTION EXCEPTION;


BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 수행전 Check Logic ]
    ---------------------------------------------------------------------------------------------------------------------------


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Logic 처리
    ---------------------------------------------------------------------------------------------------------------------------
	IF (p_WRK_TP ='Q1') THEN
   	    -- 건강검진 상세
	    OPEN RTN_CURSOR FOR
		SELECT  A.SIT_CD
		       ,(SELECT DEPT_NM FROM TCOZ_DEPT_INFO WHERE DEPT_CD = A.SIT_CD) AS SIT_NM
		       ,A.CHKUP_YY
		       ,(CASE WHEN p_CHKUP_DIV = '01' THEN A.CHKUP_DATA1
		              WHEN p_CHKUP_DIV = '02' THEN A.CHKUP_DATA2
		              WHEN p_CHKUP_DIV = '03' THEN A.CHKUP_DATA3
		              WHEN p_CHKUP_DIV = '04' THEN A.CHKUP_DATA4
		              WHEN p_CHKUP_DIV = '05' THEN A.CHKUP_DATA5
		              WHEN p_CHKUP_DIV = '06' THEN A.CHKUP_DATA6
		              WHEN p_CHKUP_DIV = '07' THEN A.CHKUP_DATA7
		              ELSE ''
		          END 
		        ) AS CHKUP_DATA
		       ,(CASE WHEN p_CHKUP_DIV = '01' THEN A.WRT_DT1
		              WHEN p_CHKUP_DIV = '02' THEN A.WRT_DT2
		              WHEN p_CHKUP_DIV = '03' THEN A.WRT_DT3
		              WHEN p_CHKUP_DIV = '04' THEN A.WRT_DT4
		              WHEN p_CHKUP_DIV = '05' THEN A.WRT_DT5
		              WHEN p_CHKUP_DIV = '06' THEN A.WRT_DT6
		              WHEN p_CHKUP_DIV = '07' THEN A.WRT_DT7
		              ELSE ''
		          END 
		        ) AS WRT_DT
		       ,A.ATFL_GRP
		       ,NVL(B.A_CNT ,0) || ' 건' AS CNT_A
		       ,NVL(B.B_CNT ,0) || ' 건' AS CNT_B
		       ,NVL(B.C_CNT ,0) || ' 건' AS CNT_C
		       ,NVL(B.C1_CNT,0) || ' 건' AS CNT_C1
		       --,NVL(B.C2_CNT,0) || ' 건' AS CNT_C2
		       ,CASE WHEN p_CHKUP_DIV = '01' THEN NVL(B.C_CNT,0) || ' 건'
		             ELSE NVL(B.C2_CNT,0) || ' 건'
		       END AS CNT_C2
		       ,CASE WHEN p_CHKUP_DIV = '01' THEN NVL(B.D_CNT,0) || ' 건'
		             ELSE NVL(B.D2_CNT,0) || ' 건'
		       END AS CNT_D2
		       ,NVL(B.D_CNT ,0) || ' 건' AS CNT_D
		       ,NVL(B.D1_CNT,0) || ' 건' AS CNT_D1
		       --,NVL(B.D2_CNT,0) || ' 건' AS CNT_D2
		       ,NVL(B.CN_CNT,0) || ' 건' AS CNT_CN
		       ,NVL(B.DN_CNT,0) || ' 건' AS CNT_DN
		       ,NVL(B.R_CNT ,0) || ' 건' AS CNT_R
		       ,NVL(B.U_CNT ,0) || ' 건' AS CNT_U
		       ,NVL(B.CNT_IMPL ,0) || ' 명' AS CNT_IMPL
		       ,NVL(B.CNT_MRML ,0) || ' 명' AS CNT_MRML
		       ,NVL(B.R_CNT ,0) + NVL(B.U_CNT ,0) || ' 건' AS CNT_RU
		       --,NVL(B.C_CNT ,0) + NVL(B.D_CNT ,0) || ' 건' AS CNT_CD
		       --,NVL(B.C1_CNT ,0) + NVL(B.C2_CNT ,0) + NVL(B.CN_CNT ,0) + NVL(B.D1_CNT ,0) + NVL(B.D2_CNT ,0) + NVL(B.DN_CNT ,0) || ' 건' AS CNT_CD
		       ,CASE WHEN p_CHKUP_DIV = '01' THEN NVL(B.C_CNT ,0) + NVL(B.D_CNT ,0) || ' 건'
		             ELSE NVL(B.C1_CNT ,0) + NVL(B.C2_CNT ,0) + NVL(B.CN_CNT ,0) + NVL(B.D1_CNT ,0) + NVL(B.D2_CNT ,0) + NVL(B.DN_CNT ,0) || ' 건'
		        END AS CNT_CD
		FROM TQHA_HLTH_CHKUP A
		LEFT JOIN (
				    SELECT SIT_CD
				          ,CHKUP_YY
				          ,CHKUP_DIV
				          ,COUNT(CASE WHEN HLTH_DIV = '01'  THEN 1 END) AS A_CNT
				          ,COUNT(CASE WHEN HLTH_DIV = '02'  THEN 1 END) AS B_CNT
				          ,COUNT(CASE WHEN HLTH_DIV = '03'  THEN 1 END) AS C_CNT
				          ,COUNT(CASE WHEN HLTH_DIV = '04' THEN 1 END) AS C1_CNT
				          ,COUNT(CASE WHEN HLTH_DIV = '05' THEN 1 END) AS C2_CNT
				          ,COUNT(CASE WHEN HLTH_DIV = '06'  THEN 1 END) AS D_CNT
				          ,COUNT(CASE WHEN HLTH_DIV = '07' THEN 1 END) AS D1_CNT
				          ,COUNT(CASE WHEN HLTH_DIV = '08' THEN 1 END) AS D2_CNT
				          ,COUNT(CASE WHEN HLTH_DIV = '09' THEN 1 END) AS CN_CNT
				          ,COUNT(CASE WHEN HLTH_DIV = '10' THEN 1 END) AS DN_CNT
				          ,COUNT(CASE WHEN HLTH_DIV = '11'  THEN 1 END) AS R_CNT
				          ,COUNT(CASE WHEN HLTH_DIV = '12'  THEN 1 END) AS U_CNT
				          /* 중복 제거 실시인원수 */
				          , CASE WHEN p_CHKUP_DIV IN ('06','07') THEN COUNT(DISTINCT DGS_DT|| '|' || CUST_CD|| '|' || NVL(CHKUP_NM, ' ') || '|' || NVL(TO_CHAR(CHKUP_AGE), ' ')) 
				                 ELSE COUNT(DISTINCT CUST_CD|| '|' || NVL(CHKUP_NM, ' ') || '|' || NVL(TO_CHAR(CHKUP_AGE), ' ')) 
				            END AS CNT_IMPL		
				        /* 정상 인원수 : 동일인의 모든 HLTH_DIV가 '01'인 경우만 카운트 */
						,(
						    SELECT COUNT(*)
						      FROM (
						            SELECT CUST_CD
						              FROM TQHA_HLTH_CHKUP_LIST T2
						             WHERE T2.SIT_CD   = p_SIT_CD
						               AND T2.CHKUP_YY = p_CHKUP_YY
						               AND T2.CHKUP_DIV = p_CHKUP_DIV
						             GROUP BY CUST_CD
						                    , NVL(CHKUP_NM, ' ')
						                    , NVL(TO_CHAR(CHKUP_AGE), ' ')
						                    , CASE
						                          WHEN p_CHKUP_DIV IN ('06', '07')
						                          THEN NVL(DGS_DT, ' ')
						                          ELSE NULL
						                      END
						            HAVING COUNT(*) =
						                   COUNT(CASE
						                             WHEN HLTH_DIV = '01'
						                             THEN 1
						                         END)
						           )
						) AS CNT_MRML
				      FROM TQHA_HLTH_CHKUP_LIST
				      WHERE SIT_CD = p_SIT_CD
					    AND CHKUP_YY = p_CHKUP_YY
				        AND CHKUP_DIV = p_CHKUP_DIV
				     GROUP BY SIT_CD, CHKUP_YY, CHKUP_DIV
				) B
		       ON A.SIT_CD   = B.SIT_CD
		      AND A.CHKUP_YY = B.CHKUP_YY
		WHERE A.SIT_CD = p_SIT_CD
		  AND A.CHKUP_YY = p_CHKUP_YY
		  ;
	    
	ELSE
	    -- 건강검진 목록
		OPEN RTN_CURSOR FOR
	    SELECT  A.SIT_CD                 --현장코드
	           ,( SELECT DEPT_NM FROM TCOZ_DEPT_INFO WHERE DEPT_CD = A.SIT_CD ) AS SIT_NM -- 현장명칭
	           ,A.CHKUP_YY                 --검진연도
	           ,(CASE WHEN p_CHKUP_DIV = '01' THEN A.CHKUP_DATA1
		              WHEN p_CHKUP_DIV = '02' THEN A.CHKUP_DATA2
		              WHEN p_CHKUP_DIV = '03' THEN A.CHKUP_DATA3
		              WHEN p_CHKUP_DIV = '04' THEN A.CHKUP_DATA4
		              WHEN p_CHKUP_DIV = '05' THEN A.CHKUP_DATA5
		              WHEN p_CHKUP_DIV = '06' THEN A.CHKUP_DATA6
		              WHEN p_CHKUP_DIV = '07' THEN A.CHKUP_DATA7
		              ELSE ''
		          END 
		        ) AS CHKUP_DATA
		        ,(CASE WHEN p_CHKUP_DIV = '01' THEN A.WRT_DT1
		              WHEN p_CHKUP_DIV = '02' THEN A.WRT_DT2
		              WHEN p_CHKUP_DIV = '03' THEN A.WRT_DT3
		              WHEN p_CHKUP_DIV = '04' THEN A.WRT_DT4
		              WHEN p_CHKUP_DIV = '05' THEN A.WRT_DT5
		              WHEN p_CHKUP_DIV = '06' THEN A.WRT_DT6
		              WHEN p_CHKUP_DIV = '07' THEN A.WRT_DT7
		              ELSE ''
		          END 
		        ) AS WRT_DT
	            ,A.ATFL_GRP                 --첨부파일그룹
	            ,B.CNT_IMPL1
	            ,B.CNT_IMPL2
	            ,B.CNT_IMPL3
	            ,B.CNT_IMPL4
	            ,B.CNT_IMPL5
	            ,B.CNT_IMPL6
	            ,B.CNT_IMPL7
	      FROM TQHA_HLTH_CHKUP A	      
	       LEFT JOIN (
				    SELECT A.SIT_CD
					      ,A.CHKUP_YY
					      ,COUNT(DISTINCT CASE WHEN A.CHKUP_DIV = '01' THEN A.CUST_CD || '|' || NVL(A.CHKUP_NM, ' ') || '|' || NVL(TO_CHAR(A.CHKUP_AGE), ' ') END) AS CNT_IMPL1
					      ,COUNT(DISTINCT CASE WHEN A.CHKUP_DIV = '02' THEN A.CUST_CD || '|' || NVL(A.CHKUP_NM, ' ') || '|' || NVL(TO_CHAR(A.CHKUP_AGE), ' ') END) AS CNT_IMPL2
					      ,COUNT(DISTINCT CASE WHEN A.CHKUP_DIV = '03' THEN A.CUST_CD || '|' || NVL(A.CHKUP_NM, ' ') || '|' || NVL(TO_CHAR(A.CHKUP_AGE), ' ') END) AS CNT_IMPL3
					      ,COUNT(DISTINCT CASE WHEN A.CHKUP_DIV = '04' THEN A.CUST_CD || '|' || NVL(A.CHKUP_NM, ' ') || '|' || NVL(TO_CHAR(A.CHKUP_AGE), ' ') END) AS CNT_IMPL4
					      ,COUNT(DISTINCT CASE WHEN A.CHKUP_DIV = '05' THEN A.CUST_CD || '|' || NVL(A.CHKUP_NM, ' ') || '|' || NVL(TO_CHAR(A.CHKUP_AGE), ' ') END) AS CNT_IMPL5
					      ,COUNT(DISTINCT CASE WHEN A.CHKUP_DIV = '06' THEN A.DGS_DT  || '|' || A.CUST_CD || '|' || NVL(A.CHKUP_NM, ' ') || '|' || NVL(TO_CHAR(A.CHKUP_AGE), ' ') END) AS CNT_IMPL6
					      ,COUNT(DISTINCT CASE WHEN A.CHKUP_DIV = '07' THEN A.DGS_DT  || '|' || A.CUST_CD || '|' || NVL(A.CHKUP_NM, ' ') || '|' || NVL(TO_CHAR(A.CHKUP_AGE), ' ') END) AS CNT_IMPL7
					  FROM TQHA_HLTH_CHKUP_LIST A
					 WHERE A.SIT_CD = p_SIT_CD                   
				       AND A.CHKUP_YY BETWEEN NVL(p_CHKUP_YY_FR, '19000101') AND NVL(p_CHKUP_YY_TO, '99991231')
					 GROUP BY A.SIT_CD, A.CHKUP_YY
				) B
       ON A.SIT_CD   = B.SIT_CD
      AND A.CHKUP_YY = B.CHKUP_YY
	    WHERE A.SIT_CD LIKE p_SIT_CD ||'%'                     --현장코드
	      AND A.CHKUP_YY BETWEEN NVL(p_CHKUP_YY_FR, '19000101') AND NVL(p_CHKUP_YY_TO, '99991231')
	    ;
  
	END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN 
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);
END ;
/

-- PQHA_HLTH_CHKUP_S (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_HLTH_CHKUP_S"
                            (p_WRK_TP  VARCHAR2 :='U'                                     -- UPDATE FLAG( I: ISNERT, U:UPDATE, D:DELTE)
                            ,p_WRK_ID  VARCHAR2                                           -- 사용자 ID 
                            ,p_WRK_IP  VARCHAR2                                           -- 사용자 IP 
                            ,p_SIT_CD TQHA_HLTH_CHKUP.SIT_CD%TYPE                         -- 현장코드
                            ,p_CHKUP_YY TQHA_HLTH_CHKUP.CHKUP_YY%TYPE                     -- 검진연도
                            ,p_CHKUP_DATA TQHA_HLTH_CHKUP.CHKUP_DATA1%TYPE                -- 검진자료
                            ,p_WRT_DT TQHA_HLTH_CHKUP.WRT_DT1%TYPE                	      -- 작성일자
                            ,p_CHKUP_DIV TQHA_HLTH_CHKUP_LIST.CHKUP_DIV%TYPE
                            ,p_ATFL_GRP TQHA_HLTH_CHKUP.ATFL_GRP%TYPE                     -- 첨부파일그룹
                            ,p_APRV_NO TQHA_HLTH_CHKUP.APRV_NO%TYPE)                      -- 결재번호
IS 
    /**************************************************************************************************************************
      Purpose : 건강진단 차수

      REVISIONS 
      Ver      Date               Author                  Description 
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2026/06/16 15:16:58                         최초생성

    /**************************************************************************************************************************/


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR2(200);            -- ERROR Message
    USER_EXCEPTION EXCEPTION;

	v_CNT NUMBER;
BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 필수입력 필드  Check  ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_SIT_CD IS NULL)  THEN
        ERR_MSG := '현장코드는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_CHKUP_YY IS NULL)  THEN
        ERR_MSG := '검진연도는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Process 선행조건 Check ]
    ---------------------------------------------------------------------------------------------------------------------------
	

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Business Process ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_WRK_TP ='D') THEN
    
   	    DELETE 
          FROM TQHA_HLTH_CHKUP_LIST
         WHERE SIT_CD = p_SIT_CD          --현장코드
           AND CHKUP_YY = p_CHKUP_YY;        --검진연도
           
        DELETE 
          FROM TQHA_HLTH_CHKUP
         WHERE SIT_CD = p_SIT_CD          --현장코드
           AND CHKUP_YY = p_CHKUP_YY;       --검진연도

    ELSIF (p_WRK_TP ='U') THEN
    
        UPDATE TQHA_HLTH_CHKUP
           SET CHKUP_DATA1 = CASE WHEN p_CHKUP_DIV = '01' THEN p_CHKUP_DATA ELSE CHKUP_DATA1 END
			  ,CHKUP_DATA2 = CASE WHEN p_CHKUP_DIV = '02' THEN p_CHKUP_DATA ELSE CHKUP_DATA2 END
			  ,CHKUP_DATA3 = CASE WHEN p_CHKUP_DIV = '03' THEN p_CHKUP_DATA ELSE CHKUP_DATA3 END
			  ,CHKUP_DATA4 = CASE WHEN p_CHKUP_DIV = '04' THEN p_CHKUP_DATA ELSE CHKUP_DATA3 END
			  ,CHKUP_DATA5 = CASE WHEN p_CHKUP_DIV = '05' THEN p_CHKUP_DATA ELSE CHKUP_DATA3 END
			  ,CHKUP_DATA6 = CASE WHEN p_CHKUP_DIV = '06' THEN p_CHKUP_DATA ELSE CHKUP_DATA3 END
			  ,CHKUP_DATA7 = CASE WHEN p_CHKUP_DIV = '07' THEN p_CHKUP_DATA ELSE CHKUP_DATA3 END			  
			  ,WRT_DT1 = p_WRT_DT
			  ,WRT_DT2 = p_WRT_DT
			  ,WRT_DT3 = p_WRT_DT
			  ,WRT_DT4 = p_WRT_DT
			  ,WRT_DT5 = p_WRT_DT
			  ,WRT_DT6 = p_WRT_DT
			  ,WRT_DT7 = p_WRT_DT
              ,ATFL_GRP             = p_ATFL_GRP                --첨부파일그룹
              ,UPD_ID               = p_WRK_ID                  --수정ID 
              ,UPD_DTM              = SYSDATE()                 --수정일시
              ,UPD_IP               = p_WRK_IP                  --수정IP
         WHERE SIT_CD = p_SIT_CD          --현장코드
           AND CHKUP_YY = p_CHKUP_YY;       --검진연도
    ELSE 
    
	    SELECT COUNT(1) INTO v_CNT
		FROM TQHA_HLTH_CHKUP
	    WHERE SIT_CD = p_SIT_CD          --현장코드
	      AND CHKUP_YY = p_CHKUP_YY;       --검진연도
	
	    IF (v_CNT > 0)  THEN
	        ERR_MSG := '이미 등록된 검진연도 입니다.';
	        RAISE USER_EXCEPTION;
	    END IF;
    
        INSERT INTO TQHA_HLTH_CHKUP
                   ( SIT_CD                  --현장코드
                    ,CHKUP_YY                --검진연도
                    ,ATFL_GRP                --첨부파일그룹
                    ,APRV_NO                 --결재번호
                    ,IPT_ID                  --입력ID
                    ,IPT_DTM                 --입력일시
                    ,IPT_IP                  --입력IP
                    ,UPD_ID                  --수정ID
                    ,UPD_DTM                 --수정일시
                    ,UPD_IP                  --수정IP
                    )
             VALUES (p_SIT_CD                --현장코드
                    ,p_CHKUP_YY              --검진연도
                    ,p_ATFL_GRP              --첨부파일그룹
                    ,p_APRV_NO               --결재번호
                    ,p_WRK_ID                --입력ID 
                    ,SYSDATE()               --입력일시
                    ,p_WRK_IP                --입력IP
                    ,p_WRK_ID                --수정ID
                    ,SYSDATE()               --수정일시
                    ,p_WRK_IP);              --수정IP
    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 5. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN 
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);
END ;
/

-- PQHA_HOCHKRPT_CK_Q (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_HOCHKRPT_CK_Q" (
    p_WRK_TP            IN VARCHAR2 DEFAULT 'Q'         -- FLAG
,   p_SIT_CD            IN VARCHAR2                     -- 현장코드
,   p_CHK_DIV           IN VARCHAR2                     -- 체크구분
,   p_CHK_DGR           IN VARCHAR2                     -- 차수
,   p_HO_CHK_DIV_CD2    IN VARCHAR2                     --
,   p_CHK_CD            IN VARCHAR2                     --
,   RTN_CURSOR          OUT SYS_REFCURSOR
)
IS
    /**************************************************************************************************************************
      Purpose : [본사점검 체크리스트 조회] PROCEDRE (QSE > 재해예방관리 > 본사점검 체크리스트 )

      REVISIONS
      Ver      Date               Author                  Description
      -------  -----------------  ----------------------  ---------------------------------------------------------------------
      1.0      XXXX/XX/XX                                 최초생성

    **************************************************************************************************************************/
 
    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE  NUMBER :=-20009; -- ERROR 코드
    ERR_MSG   VARCHAR(200);    -- ERROR Message
    USER_EXCEPTION EXCEPTION;

BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 수행전 Check Logic ]
    ---------------------------------------------------------------------------------------------------------------------------

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Logic 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------

    IF p_WRK_TP = 'Q' THEN

        OPEN RTN_CURSOR FOR
        SELECT CK.SIT_CD                -- 현장코드
             , CK.CHK_DIV               -- 공통코드 : QSZ03
             , CK.CHK_DGR                -- 점검일자
             , CK.COM_CD                -- 공통코드 : QSZ03
             , CK.HO_CHK_DIV_CD         -- 공통코드 : QSZ0310
             , B.HO_CHK_DIV_NM
             , CK.HO_CHK_DIV_CD2        -- 본사점검구분코드
             , CK.HO_CHK_ITM_CD         -- 본사점검항목코드
             , C.HO_CHK_ITM_NM         -- 본사점검항목코드
             , C.HO_CHK_ITM_NM2         -- 본사점검항목코드
             , C.MAX_SCORE              -- 배점
             , CK.APRS_CHK
			 , CK.APRS_PNDS
			 , CK.APRS_SCR
			 , CK.APRS_CTS
          FROM TQHA_HOCHKRPT_CK CK
              ,TQHA_CKLST B
              ,TQHA_CKLST_ITM C
         WHERE CK.SIT_CD            = p_SIT_CD
           AND CK.CHK_DIV           = p_CHK_DIV
           AND CK.CHK_DGR           = p_CHK_DGR
           AND CK.HO_CHK_DIV_CD2    = p_HO_CHK_DIV_CD2
            AND (
			       ( SUBSTR(p_CHK_DIV, 1, 7) = 'QS07301' AND CK.COM_CD = p_CHK_DIV ) OR ( SUBSTR(p_CHK_DIV, 1, 7) = 'QS07302' AND CK.HO_CHK_DIV_CD2 = p_CHK_DIV )
		        )
           AND CK.COM_CD            = B.COM_CD
           AND CK.HO_CHK_DIV_CD     = B.HO_CHK_DIV_CD
           AND CK.HO_CHK_DIV_CD2    = B.HO_CHK_DIV_CD2
           AND B.HO_CHK_DIV_USE_YN  = '1'
           AND CK.COM_CD            = C.COM_CD
           AND CK.HO_CHK_DIV_CD     = C.HO_CHK_DIV_CD
           AND CK.HO_CHK_DIV_CD2    = C.HO_CHK_DIV_CD2
           AND CK.HO_CHK_ITM_CD     = C.HO_CHK_ITM_CD
           AND C.HO_CHK_ITM_USE_YN  = '1'
         ORDER BY CK.HO_CHK_DIV_CD ASC, CK.HO_CHK_ITM_CD ASC
        ;

    --------------------------------------------------------------------------------------------
    ELSIF p_WRK_TP = 'Q2' THEN

        OPEN RTN_CURSOR FOR
        SELECT 1 FROM DUAL;

    --------------------------------------------------------------------------------------------
    ELSIF p_WRK_TP = 'Q3' THEN

        OPEN RTN_CURSOR FOR
        SELECT A.COM_CD                       -- 공통코드
             , A.HO_CHK_DIV_CD2               -- 본사점검탭분류
             , A.HO_CHK_DIV_CD                -- 본사점검구분코드
             , A.HO_CHK_DIV_NM                -- 본사점검구분명
             , A.HO_CHK_RMKS                  -- 본사점검비고
             , p_SIT_CD     AS SIT_CD
             , p_CHK_DIV    AS CHK_DIV
             , p_CHK_DGR     AS CHK_DGR
             , DECODE(B.CHK_DGR,NULL,'0','1') AS USE_YN
          FROM TQHA_CKLST A
              ,(SELECT SIT_CD,CHK_DIV,CHK_DGR,COM_CD,HO_CHK_DIV_CD
                  FROM TQHA_HOCHKRPT_CK
                 WHERE SIT_CD           = p_SIT_CD
                   AND CHK_DIV          = p_CHK_DIV
                   AND CHK_DGR           = p_CHK_DGR
                 GROUP BY SIT_CD,CHK_DIV,CHK_DGR,COM_CD,HO_CHK_DIV_CD) B
         WHERE A.COM_CD                 = 'QSZ0360'
           AND A.COM_CD                 = B.COM_CD(+)
           AND A.HO_CHK_DIV_CD          = B.HO_CHK_DIV_CD(+)
           AND A.HO_CHK_DIV_USE_YN      = '1'
         ORDER BY A.HO_CHK_DIV_CD
        ;

    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
         WHEN OTHERS THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);

END PQHA_HOCHKRPT_CK_Q;
/

-- PQHA_HOCHKRPT_CK_S (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_HOCHKRPT_CK_S" (
    p_WRK_TP                VARCHAR2 :='U'                                      -- UPDATE FLAG( I: ISNERT, U:UPDATE, D:DELTE)
,   p_WRK_ID                VARCHAR2                                            -- 사용자 ID
,   p_WRK_IP                VARCHAR2                                            -- 사용자 IP
,   p_SIT_CD                TQHA_HOCHKRPT_CK.SIT_CD                 %TYPE       -- 현장코드
,   p_CHK_DIV               TQHA_HOCHKRPT_CK.CHK_DIV                %TYPE       -- 공통코드 : QSZ03
,   p_CHK_DGR               TQHA_HOCHKRPT_CK.CHK_DGR                %TYPE       -- 점검차수
,   p_COM_CD                TQHA_HOCHKRPT_CK.COM_CD                 %TYPE       -- 공통코드 : QSZ03
,   p_HO_CHK_DIV_CD         TQHA_HOCHKRPT_CK.HO_CHK_DIV_CD          %TYPE       -- 공통코드 : QSZ0310
,   p_HO_CHK_DIV_CD2        TQHA_HOCHKRPT_CK.HO_CHK_DIV_CD2         %TYPE       -- 본사점검구분코드
,   p_HO_CHK_ITM_CD         TQHA_HOCHKRPT_CK.HO_CHK_ITM_CD          %TYPE       -- 본사점검항목코드
,   p_APRS_CHK              TQHA_HOCHKRPT_CK.APRS_CHK               %TYPE
,   p_APRS_SCR              TQHA_HOCHKRPT_CK.APRS_SCR               %TYPE
,   p_APRS_CTS              TQHA_HOCHKRPT_CK.APRS_CTS               %TYPE
,   p_USE_YN                VARCHAR2
)

IS
    /**************************************************************************************************************************
      Purpose : [본사점검 체크리스트 저장]

      REVISIONS
      Ver      Date               Author                  Description
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2019/06/21 16:29:27                         최초생성

    /**************************************************************************************************************************/


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR(200);             -- ERROR Message
    USER_EXCEPTION EXCEPTION;

    v_APRV_STATS        VARCHAR2(20);
    v_APRV_STATS_NM     VARCHAR2(50);

BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 필수입력 필드  Check  ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_SIT_CD IS NULL)  THEN
        ERR_MSG := '현장코드는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_CHK_DIV IS NULL)  THEN
        ERR_MSG := '공통코드 : QSZ03는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_CHK_DGR IS NULL)  THEN
        ERR_MSG := '점검차수는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_COM_CD IS NULL)  THEN
        ERR_MSG := '공통코드 : QSZ03는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_HO_CHK_DIV_CD IS NULL)  THEN
        ERR_MSG := '공통코드 : QSZ0310는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    ---------------------------------------------------------------------
    -- 결재상태 체크
--    SELECT MAX(T2.APRV_STATS)
--      INTO v_APRV_STATS
--      FROM TQHA_HOCHKRPT        T1
--      LEFT JOIN TQHA_APRV       T2 ON T1.SIT_CD     = T2.SIT_CD
--                                  AND T1.APRV_NO1   = T2.APRV_NO
--     WHERE T1.SIT_CD    = p_SIT_CD
--       AND T1.CHK_DIV   = p_CHK_DIV
--       AND T1.CHK_DGR    = p_CHK_DGR
--    ;
--
--    IF v_APRV_STATS IN ('2', '4') THEN
--        ERR_MSG := '결재상태 [' || v_APRV_STATS_NM || ']인 데이터는 수정 불가합니다.';
--        RAISE USER_EXCEPTION;
--    END IF;

   /*
    IF (p_HO_CHK_DIV_CD2 IS NULL)  THEN
        ERR_MSG := '본사점검구분코드는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_HO_CHK_ITM_CD IS NULL)  THEN
        ERR_MSG := '본사점검항목코드는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;
    */

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Process 선행조건 Check ]
    ---------------------------------------------------------------------------------------------------------------------------



    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Business Process ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_WRK_TP ='D') THEN

        DELETE
          FROM TQHA_HOCHKRPT_CK
         WHERE SIT_CD               = p_SIT_CD              --현장코드
           AND CHK_DIV              = p_CHK_DIV             --공통코드 : QSZ03
           AND CHK_DGR               = p_CHK_DGR              --점검차수
           AND COM_CD               = p_COM_CD              --공통코드 : QSZ03
           AND HO_CHK_DIV_CD        = p_HO_CHK_DIV_CD       --공통코드 : QSZ0310
           AND HO_CHK_DIV_CD2       = p_HO_CHK_DIV_CD2      --본사점검구분코드
           AND HO_CHK_ITM_CD        = p_HO_CHK_ITM_CD       --본사점검항목코드
        ;

    ELSIF (p_WRK_TP ='U') THEN -- 체크리스트 저장 시

        UPDATE TQHA_HOCHKRPT_CK
           SET APRS_CHK      		= p_APRS_CHK
             , APRS_SCR      		= p_APRS_SCR
             , APRS_CTS      		= p_APRS_CTS
             , UPD_ID               = p_WRK_ID              -- 수정ID
             , UPD_DTM              = SYSDATE()             -- 수정일시
             , UPD_IP               = p_WRK_IP              -- 수정IP
         WHERE SIT_CD               = p_SIT_CD              -- 현장코드
           AND CHK_DIV              = p_CHK_DIV             -- 공통코드 : QSZ03
           AND CHK_DGR              = p_CHK_DGR              -- 점검차수
           AND COM_CD               = p_COM_CD              -- 공통코드 : QSZ03
           AND HO_CHK_DIV_CD        = p_HO_CHK_DIV_CD       -- 공통코드 : QSZ0310
           AND HO_CHK_DIV_CD2       = p_HO_CHK_DIV_CD2      -- 본사점검구분코드
           AND HO_CHK_ITM_CD        = p_HO_CHK_ITM_CD       -- 본사점검항목코드
        ;
        
        
        UPDATE TQHA_HOCHKRPT M
		SET -- 1. 전회점수 (이전 차수 데이터가 없으면 0)
		       (M.RVLT_SCR1, M.RVLT_SCR2, M.RVLT_SCR3, M.RVLT_SCR4, M.RVLT_SCR5) = 
		       (
		           SELECT NVL(MAX(PREV.TTM_SCR1), 0)
		                , NVL(MAX(PREV.TTM_SCR2), 0)
		                , NVL(MAX(PREV.TTM_SCR3), 0)
		                , NVL(MAX(PREV.TTM_SCR4), 0)
		                , NVL(MAX(PREV.TTM_SCR5), 0)
		             FROM TQHA_HOCHKRPT PREV
		            WHERE PREV.SIT_CD  = p_SIT_CD
		              AND PREV.CHK_DIV = p_CHK_DIV
		              AND PREV.CHK_DGR = p_CHK_DGR - 1
		       )
		       
		     -- 2. 금회점수 (별칭을 부여해 구조를 단순화)
		     , (M.TTM_SCR1, M.TTM_SCR2, M.TTM_SCR3, M.TTM_SCR4, M.TTM_SCR5) = 
		       (
		             SELECT G.V1, G.V2, G.V3, G.V4
		                  , G.V1 + G.V2 + G.V3 
		             FROM (
		                   SELECT NVL(MAX(CASE WHEN SUBSTR(CK.HO_CHK_DIV_CD2, -1) = '1' THEN CK.SM_SCR END), 0) AS V1
		                        , NVL(MAX(CASE WHEN SUBSTR(CK.HO_CHK_DIV_CD2, -1) = '2' THEN CK.SM_SCR END), 0) AS V2
		                        , NVL(MAX(CASE WHEN SUBSTR(CK.HO_CHK_DIV_CD2, -1) = '3' THEN CK.SM_SCR END), 0) AS V3
		                        , 0 AS V4
		                     FROM (
		                           SELECT HO_CHK_DIV_CD2
		                                , SUM(APRS_SCR) AS SM_SCR
		                             FROM TQHA_HOCHKRPT_CK
		                            WHERE SIT_CD  = p_SIT_CD
		                              AND CHK_DIV = p_CHK_DIV
		                              AND CHK_DGR = p_CHK_DGR
		                            GROUP BY SIT_CD, CHK_DIV, CHK_DGR, HO_CHK_DIV_CD2
		                          ) CK
		                  ) G
		       )
		     
		     -- 3. 기타 변수 반영
		 /*    , M.APRS_GRD1            = p_APRS_GRD1
		     , M.APRS_GRD2            = p_APRS_GRD2
		     , M.APRS_GRD3            = p_APRS_GRD3
		     , M.APRS_GRD4            = p_APRS_GRD4
		     , M.APRS_GRD5            = p_APRS_GRD5
		     , M.ATFL_GRP             = p_ATFL_GRP
		     , M.UPD_ID               = p_WRK_ID
		     , M.UPD_DTM              = SYSDATE()
		     , M.UPD_IP               = p_WRK_IP */
		 WHERE M.SIT_CD  = p_SIT_CD
		   AND M.CHK_DIV = p_CHK_DIV
		   AND M.CHK_DGR = p_CHK_DGR;

    ELSIF (p_WRK_TP ='U2') THEN -- 체크리스트 복사시

        DELETE FROM TQHA_HOCHKRPT_CK
         WHERE SIT_CD           = p_SIT_CD          -- 현장코드
           AND CHK_DIV          = p_CHK_DIV         -- 공통코드 : QSZ03
           AND CHK_DGR           = p_CHK_DGR          -- 점검차수
           AND COM_CD           = p_COM_CD          -- 공통코드 : QSZ03
           AND HO_CHK_DIV_CD    = p_HO_CHK_DIV_CD
        ;

        IF(p_USE_YN != '0') THEN

            INSERT 
              INTO TQHA_HOCHKRPT_CK
                 ( SIT_CD                   -- 현장코드
                 , CHK_DIV                  -- 공통코드 : QSZ03
                 , CHK_DGR                   -- 점검차수
                 , COM_CD                   -- 공통코드 : QSZ03
                 , HO_CHK_DIV_CD            -- 공통코드 : QSZ0310
                 , HO_CHK_DIV_CD2           -- 본사점검구분코드
                 , HO_CHK_ITM_CD            -- 본사점검항목코드
                 , APRS_PNDS
                 , IPT_ID                   -- 신규입력ID
                 , IPT_DTM                  -- 신규입력일시
                 , IPT_IP                   -- 신규입력IP
                 , UPD_ID                   -- 최종수정ID
                 , UPD_DTM                  -- 최종수정일시
                 , UPD_IP                   -- 최종수정IP
                 )
            SELECT p_SIT_CD                 -- 현장코드
                 , p_CHK_DIV                -- 공통코드 : QSZ03
                 , p_CHK_DGR                 -- 점검차수
                 , A.COM_CD
                 , A.HO_CHK_DIV_CD
                 , A.HO_CHK_DIV_CD2
                 , B.HO_CHK_ITM_CD
                 , B.MAX_SCORE
                 , p_WRK_ID                 -- 입력ID
                 , SYSDATE()                -- 입력일시
                 , p_WRK_IP                 -- 입력IP
                 , p_WRK_ID                 -- 수정ID
                 , SYSDATE()                -- 수정일시
                 , p_WRK_IP                 -- 수정IP
              FROM TQHA_CKLST       A
                 , TQHA_CKLST_ITM   B
             WHERE A.COM_CD                 = p_CHK_DIV
               AND A.HO_CHK_DIV_CD          = p_HO_CHK_DIV_CD
               AND A.HO_CHK_DIV_USE_YN      = '1'
               AND B.HO_CHK_ITM_USE_YN      = '1'
               AND A.COM_CD                 = B.COM_CD
               AND A.HO_CHK_DIV_CD          = B.HO_CHK_DIV_CD
               AND A.HO_CHK_DIV_CD2         = B.HO_CHK_DIV_CD2
            ;

        END IF;

    ELSE

        INSERT 
          INTO TQHA_HOCHKRPT_CK
             ( SIT_CD                   -- 현장코드
             , CHK_DIV                  -- 공통코드 : QSZ03
             , CHK_DGR                   -- 점검차수
             , COM_CD                   -- 공통코드 : QSZ03
             , HO_CHK_DIV_CD            -- 공통코드 : QSZ0310
             , HO_CHK_DIV_CD2           -- 본사점검구분코드
             , HO_CHK_ITM_CD            -- 본사점검항목코드
             , APRS_CHK                 -- 공통코드 : QSA04
             , APRS_SCR
             , APRS_CTS             
             , IPT_ID                   -- 신규입력ID
             , IPT_DTM                  -- 신규입력일시
             , IPT_IP                   -- 신규입력IP
             , UPD_ID                   -- 최종수정ID
             , UPD_DTM                  -- 최종수정일시
             , UPD_IP                   -- 최종수정IP
             )
        VALUES 
             ( p_SIT_CD                 -- 현장코드
             , p_CHK_DIV                -- 공통코드 : QSZ03
             , p_CHK_DGR                 -- 점검차수
             , p_COM_CD                 -- 공통코드 : QSZ03
             , p_HO_CHK_DIV_CD          -- 공통코드 : QSZ0310
             , p_HO_CHK_DIV_CD2         -- 본사점검구분코드
             , p_HO_CHK_ITM_CD          -- 본사점검항목코드
             , p_APRS_CHK               -- 공통코드 : QSA04
             , p_APRS_SCR
             , p_APRS_CTS
             , p_WRK_ID                 -- 입력ID
             , SYSDATE()                -- 입력일시
             , p_WRK_IP                 -- 입력IP
             , p_WRK_ID                 -- 수정ID
             , SYSDATE()                -- 수정일시
             , p_WRK_IP                 -- 수정IP
             )
        ;

    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 5. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
         WHEN OTHERS THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);

END;
/

