-- PQHA_HOCHKRPT_ERR_Q (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_HOCHKRPT_ERR_Q" (
    p_WRK_TP            IN VARCHAR2 DEFAULT 'Q'         -- FLAG
,   p_SIT_CD            IN VARCHAR2                     -- 현장코드
,   p_CHK_DIV           IN VARCHAR2                     -- 체크구분
,   p_CHK_DGR           IN VARCHAR2                     -- 
,   RTN_CURSOR          OUT SYS_REFCURSOR
)
IS
    /**************************************************************************************************************************
      Purpose : [본사점검 지적사항 조회] PROCEDRE (QSE > 재해예방관리 > 본사점검 지적사항 )

      REVISIONS
      Ver      Date               Author                  Description
      -------  -----------------  ----------------------  ---------------------------------------------------------------------
      1.0      XXXX/XX/XX                                 최초생성

    **************************************************************************************************************************/

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE  NUMBER :=-20009; -- ERROR 코드
    ERR_MSG   VARCHAR(200);    -- ERROR Message
    USER_EXCEPTION EXCEPTION;

BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 수행전 Check Logic ]
    ---------------------------------------------------------------------------------------------------------------------------

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Logic 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------

    IF p_WRK_TP = 'Q' THEN

        OPEN RTN_CURSOR FOR
        SELECT SIT_CD              -- 현장코드
             , CHK_DIV              -- 공통코드 : QSZ03
             , CHK_DGR
             , CHK_DT               -- 점검일자
             , ERR_SEQ              -- 지적순번
             , DIV_1 AS CODE01             
             , DIV_1                -- 안전 > 공통코드 : QSM02, 환경 > 공통코드 : QSM03
             , DIV_2 AS CODE02             
             , DIV_2                -- 안전 > 공통코드 : QSM02, 환경 > 공통코드 : QSM03
             , DIV_3 AS CODE03
             , DIV_3                -- 공통코드 : QSK03
             , CHK_ELMT             -- 지적부위
             , CHK_MATT             -- 지적사항
             , CSE                  -- 원인
             , CPLN_MA_SHM          -- 대책조치방안
             , INSP_EMPNO           -- 점검자
             , INSP_NM             -- 점검자성명
             , MA_DT                -- 조치일자
             , MA_MATT              -- 조치사항
             , MA_PSN_EMPNO         -- 조치자/담당직원
             , MA_PSN_NM            -- 조치자성명
             , CUST_CD              -- 협력회사
             , CUST_NM              -- 거래처명
             , ATFL_GRP             -- 첨부문서
             , ATFL_GRP2            -- 조치전 사진
             , PHOTO_DESC_2         -- 조치전 사진내용
             , ATFL_GRP3            -- 조치후 사진
             , PHOTO_DESC_3
          FROM TQHA_HOCHKRPT_ERR
         WHERE SIT_CD   = p_SIT_CD
           AND CHK_DIV  = p_CHK_DIV
           AND CHK_DGR  = p_CHK_DGR
         ORDER BY ERR_SEQ
        ;

    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
         WHEN OTHERS THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);

END PQHA_HOCHKRPT_ERR_Q;
/

-- PQHA_HOCHKRPT_ERR_S (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_HOCHKRPT_ERR_S" (
    p_WRK_TP                VARCHAR2 :='U'                                          -- UPDATE FLAG( I: ISNERT, U:UPDATE, D:DELTE)
,   p_WRK_ID                VARCHAR2                                                -- 사용자 ID
,   p_WRK_IP                VARCHAR2                                                -- 사용자 IP
,   p_SIT_CD                TQHA_HOCHKRPT_ERR.SIT_CD                %TYPE           -- 현장코드
,   p_CHK_DIV               TQHA_HOCHKRPT_ERR.CHK_DIV               %TYPE           -- 공통코드 : QSZ03
,   p_CHK_DGR               TQHA_HOCHKRPT_ERR.CHK_DGR               %TYPE           -- 점검차수
,   p_CHK_DT                TQHA_HOCHKRPT_ERR.CHK_DT                %TYPE           -- 점검일자
,   p_ERR_SEQ               TQHA_HOCHKRPT_ERR.ERR_SEQ               %TYPE           -- 지적순번
,   p_DIV_1                 TQHA_HOCHKRPT_ERR.DIV_1                 %TYPE           -- 안전 > 공통코드 : QSA02, 환경 > 공통코드 : QSA03
,   p_DIV_2                 TQHA_HOCHKRPT_ERR.DIV_2                 %TYPE           -- 안전 > 공통코드 : QSA02, 환경 > 공통코드 : QSA03
,   p_DIV_3                 TQHA_HOCHKRPT_ERR.DIV_3                 %TYPE           -- 공통코드 : QSK03
,   p_CHK_ELMT              TQHA_HOCHKRPT_ERR.CHK_ELMT              %TYPE           -- 지적부위
,   p_CHK_MATT              TQHA_HOCHKRPT_ERR.CHK_MATT              %TYPE           -- 지적사항
,   p_CSE                   TQHA_HOCHKRPT_ERR.CSE                   %TYPE           -- 원인
,   p_CPLN_MA_SHM           TQHA_HOCHKRPT_ERR.CPLN_MA_SHM           %TYPE           -- 대책조치방안
,   p_INSP_EMPNO            TQHA_HOCHKRPT_ERR.INSP_EMPNO            %TYPE           -- 점검자
,   p_INSP_NM              TQHA_HOCHKRPT_ERR.INSP_NM                %TYPE           -- 점검자성명
,   p_MA_DT                 TQHA_HOCHKRPT_ERR.MA_DT                 %TYPE           -- 조치일자
,   p_MA_MATT               TQHA_HOCHKRPT_ERR.MA_MATT               %TYPE           -- 조치사항
,   p_MA_PSN_EMPNO          TQHA_HOCHKRPT_ERR.MA_PSN_EMPNO          %TYPE           -- 조치자/담당직원
,   p_MA_PSN_NM            TQHA_HOCHKRPT_ERR.MA_PSN_NM              %TYPE           -- 조치자성명
,   p_CUST_CD               TQHA_HOCHKRPT_ERR.CUST_CD               %TYPE           -- 협력회사
,   p_CUST_NM               TQHA_HOCHKRPT_ERR.CUST_NM               %TYPE           -- 거래처명
,   p_ATFL_GRP              TQHA_HOCHKRPT_ERR.ATFL_GRP              %TYPE           -- 첨부문서
,   p_ATFL_GRP2             TQHA_HOCHKRPT_ERR.ATFL_GRP2             %TYPE           -- 조치전 사진
,   p_ATFL_GRP3             TQHA_HOCHKRPT_ERR.ATFL_GRP3             %TYPE           -- 조치후 사진
,   p_PHOTO_DESC_2          TQHA_HOCHKRPT_ERR.PHOTO_DESC_2          %TYPE           -- 조치전 사진내용
,   p_PHOTO_DESC_3          TQHA_HOCHKRPT_ERR.PHOTO_DESC_3          %TYPE           -- 조치후 사진내용
)
IS
    /**************************************************************************************************************************
      Purpose :

      REVISIONS
      Ver      Date               Author                  Description
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2019/06/19 17:19:07                         최초생성

    /**************************************************************************************************************************/


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR(200);             -- ERROR Message
    USER_EXCEPTION EXCEPTION;

    v_cnt               INTEGER;
    v_cnt2              INTEGER;
    v_cnt3              INTEGER;
    v_text              VARCHAR(100);

    v_APRV_STATS        VARCHAR2(20);
    v_APRV_STATS_NM     VARCHAR2(50);

BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 필수입력 필드  Check  ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_SIT_CD IS NULL)  THEN
        ERR_MSG := '현장코드는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_CHK_DIV IS NULL)  THEN
        ERR_MSG := '공통코드 : QSZ03는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    -----------------------------------------------------------------
--     --결재상태 체크
--    SELECT MAX(T2.APRV_STATS)
--      INTO v_APRV_STATS
--      FROM TQHA_HOCHKRPT        T1
--      LEFT JOIN TQHA_APRV       T2 ON T1.SIT_CD     = T2.SIT_CD
--                                  AND T1.APRV_NO1   = T2.APRV_NO
--     WHERE T1.SIT_CD    = p_SIT_CD
--       AND T1.CHK_DIV   = p_CHK_DIV
--       AND T1.CHK_DGR   = p_CHK_DGR
--    ;
--
--    IF v_APRV_STATS IN ('2', '4') THEN
--        ERR_MSG := '결재상태 [' || v_APRV_STATS_NM || ']인 데이터는 수정 불가합니다.';
--        RAISE USER_EXCEPTION;
--    END IF;
--    ---------------------------------------------------------------------

    
    
    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Process 선행조건 Check ]
    ---------------------------------------------------------------------------------------------------------------------------



    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Business Process ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_WRK_TP ='D') THEN

        DELETE
          FROM TQHA_HOCHKRPT_ERR
         WHERE SIT_CD       = p_SIT_CD          -- 현장코드
           AND CHK_DIV      = p_CHK_DIV         -- 공통코드 : QSZ03
           AND CHK_DGR      = p_CHK_DGR
           AND ERR_SEQ      = p_ERR_SEQ         -- 지적순번
        ;

    ELSIF (p_WRK_TP ='U') THEN

        UPDATE TQHA_HOCHKRPT_ERR
           SET DIV_1                = p_DIV_1                   -- 안전 > 공통코드 : QSA02, 환경 > 공통코드 : QSA03
             , DIV_2                = p_DIV_2                   -- 안전 > 공통코드 : QSA02, 환경 > 공통코드 : QSA03
             , DIV_3                = p_DIV_3                   -- 공통코드 : QSK03
             , CHK_ELMT             = p_CHK_ELMT                -- 지적부위
             , CHK_MATT             = p_CHK_MATT                -- 지적사항
             , CSE                  = p_CSE                     -- 원인
             , CPLN_MA_SHM          = p_CPLN_MA_SHM             -- 대책조치방안
             , INSP_EMPNO           = p_INSP_EMPNO              -- 점검자
             , INSP_NM              = p_INSP_NM                -- 점검자성명
             , CUST_CD              = p_CUST_CD                 -- 협력회사
             , CUST_NM              = p_CUST_NM                 -- 거래처명
             , ATFL_GRP2            = p_ATFL_GRP2               -- 조치전 사진
             , PHOTO_DESC_2         = p_PHOTO_DESC_2               -- 조치전 사진
             , UPD_ID               = p_WRK_ID                  -- 수정ID
             , UPD_DTM              = SYSDATE()                 -- 수정일시
             , UPD_IP               = p_WRK_IP                  -- 수정IP
         WHERE SIT_CD               = p_SIT_CD                  -- 현장코드
           AND CHK_DIV              = p_CHK_DIV                 -- 공통코드 : QSZ03
           AND CHK_DGR              = p_CHK_DGR
           AND ERR_SEQ              = p_ERR_SEQ                 -- 지적순번
        ;

    ELSIF (p_WRK_TP ='U2') THEN -- 지적사항 조치후 저장시

         UPDATE TQHA_HOCHKRPT_ERR
           SET MA_DT                = p_MA_DT           -- 조치일자
             , MA_MATT              = p_MA_MATT         -- 조치내용
             , MA_PSN_EMPNO         = p_WRK_ID          -- 조치자/담당직원
             , PHOTO_DESC_2         = p_PHOTO_DESC_2    -- 조치전 사진내용
             , PHOTO_DESC_3         = p_PHOTO_DESC_3    -- 조치후 사진내용
             , ATFL_GRP             = p_ATFL_GRP        -- 첨부문서
             , ATFL_GRP2            = p_ATFL_GRP2       -- 조치전 사진
             , ATFL_GRP3            = p_ATFL_GRP3       -- 조치후 사진
             , UPD_ID               = p_WRK_ID          -- 수정ID
             , UPD_DTM              = SYSDATE()         -- 수정일시
             , UPD_IP               = p_WRK_IP          -- 수정IP
         WHERE SIT_CD               = p_SIT_CD          -- 현장코드
           AND CHK_DIV              = p_CHK_DIV         -- 공통코드 : QSZ03
           AND CHK_DGR              = p_CHK_DGR
           AND ERR_SEQ              = p_ERR_SEQ
        ;
         
          UPDATE TQHA_HOCHKRPT
           SET MA_DT                = p_MA_DT
             , UPD_ID               = p_WRK_ID          -- 수정ID
             , UPD_DTM              = SYSDATE()         -- 수정일시
             , UPD_IP               = p_WRK_IP
         WHERE SIT_CD               = p_SIT_CD          -- 현장코드
           AND CHK_DIV              = p_CHK_DIV         -- 공통코드 : QSZ03
           AND CHK_DGR              = p_CHK_DGR
        ;
          
    ELSIF (p_WRK_TP ='U3') THEN

        UPDATE TQHA_HOCHKRPT_ERR
           SET ATFL_GRP2            = p_ATFL_GRP2               -- 조치전 사진
             , UPD_ID               = p_WRK_ID                  -- 수정ID
             , UPD_DTM              = SYSDATE()                 -- 수정일시
             , UPD_IP               = p_WRK_IP                  -- 수정IP
         WHERE SIT_CD               = p_SIT_CD                  -- 현장코드
           AND CHK_DIV              = p_CHK_DIV                 -- 공통코드 : QSZ03
           AND CHK_DGR              = p_CHK_DGR
           AND ERR_SEQ              = p_ERR_SEQ                 -- 지적순번
        ;
        
     ELSIF (p_WRK_TP ='U3_2') THEN

        UPDATE TQHA_HOCHKRPT_ERR
           SET ATFL_GRP3            = p_ATFL_GRP3               -- 조치전 사진
             , UPD_ID               = p_WRK_ID                  -- 수정ID
             , UPD_DTM              = SYSDATE()                 -- 수정일시
             , UPD_IP               = p_WRK_IP                  -- 수정IP
         WHERE SIT_CD               = p_SIT_CD                  -- 현장코드
           AND CHK_DIV              = p_CHK_DIV                 -- 공통코드 : QSZ03
           AND CHK_DGR              = p_CHK_DGR
           AND ERR_SEQ              = p_ERR_SEQ                 -- 지적순번
        ;
        
     ELSIF (p_WRK_TP ='U4') THEN

        UPDATE TQHA_HOCHKRPT_ERR
           SET ATFL_GRP             = p_ATFL_GRP                 -- 첨부
             , UPD_ID               = p_WRK_ID                  -- 수정ID
             , UPD_DTM              = SYSDATE()                 -- 수정일시
             , UPD_IP               = p_WRK_IP                  -- 수정IP
         WHERE SIT_CD               = p_SIT_CD                  -- 현장코드
           AND CHK_DIV              = p_CHK_DIV                 -- 공통코드 : QSZ03
           AND CHK_DGR              = p_CHK_DGR
           AND ERR_SEQ              = p_ERR_SEQ                 -- 지적순번
        ;
        
    ELSE

        INSERT 
          INTO TQHA_HOCHKRPT_ERR
              ( SIT_CD                  -- 현장코드
              , CHK_DIV                 -- 공통코드 : QSZ03
              , CHK_DGR
              , CHK_DT
              , ERR_SEQ                 -- 지적순번
              , DIV_1                   -- 안전 > 공통코드 : QSA02, 환경 > 공통코드 : QSA03
              , DIV_2                   -- 안전 > 공통코드 : QSA02, 환경 > 공통코드 : QSA03
              , DIV_3                   -- 공통코드 : QSK03
              , CHK_ELMT                -- 지적부위
              , CHK_MATT                -- 지적사항
              , CSE                     -- 원인
              , CPLN_MA_SHM             -- 대책조치방안
              , INSP_EMPNO              -- 점검자
              , INSP_NM                -- 점검자성명
              , MA_DT                   -- 조치일자
              , MA_MATT                 -- 조치사항
              , MA_PSN_EMPNO            -- 조치자/담당직원
              , MA_PSN_NM              -- 조치자성명
              , CUST_CD                 -- 협력회사
              , CUST_NM                 -- 거래처명
              , ATFL_GRP                -- 첨부문서
              , ATFL_GRP2               -- 조치전 사진
              , ATFL_GRP3               -- 조치후 사진
              , PHOTO_DESC_3            -- 조치후 사진내용
              , IPT_ID                  -- 신규입력ID
              , IPT_DTM                 -- 신규입력일시
              , IPT_IP                  -- 신규입력IP
              , UPD_ID                  -- 최종수정ID
              , UPD_DTM                 -- 최종수정일시
              , UPD_IP                  -- 최종수정IP
              )
        VALUES 
             ( p_SIT_CD                 -- 현장코드
             , p_CHK_DIV                -- 공통코드 : QSZ03
             , p_CHK_DGR
             , p_CHK_DT
             , (SELECT NVL(MAX(ERR_SEQ),0) +1 FROM TQHA_HOCHKRPT_ERR WHERE SIT_CD = p_SIT_CD AND CHK_DIV = p_CHK_DIV AND CHK_DGR = p_CHK_DGR ) --지적순번
             , p_DIV_1                  -- 안전 > 공통코드 : QSA02, 환경 > 공통코드 : QSA03
             , p_DIV_2                  -- 안전 > 공통코드 : QSA02, 환경 > 공통코드 : QSA03
             , p_DIV_3                  -- 공통코드 : QSK03
             , p_CHK_ELMT               -- 지적부위
             , p_CHK_MATT               -- 지적사항
             , p_CSE                    -- 원인
             , p_CPLN_MA_SHM            -- 대책조치방안
             , p_INSP_EMPNO             -- 점검자
             , p_INSP_NM               -- 점검자성명 
             , NULL                     -- 조치일자
             , p_MA_MATT                -- 조치사항
             , p_MA_PSN_EMPNO           -- 조치자/담당직원
             , p_MA_PSN_NM             -- 조치자성명
             , p_CUST_CD                -- 협력회사
             , p_CUST_NM                -- 거래처명
             , p_ATFL_GRP               -- 첨부문서
             , p_ATFL_GRP2              -- 조치전 사진
             , p_ATFL_GRP3              -- 조치후 사진
             , p_PHOTO_DESC_3           -- 조치후 사진내용
             , p_WRK_ID                 -- 입력ID
             , SYSDATE()                -- 입력일시
             , p_WRK_IP                 -- 입력IP
             , p_WRK_ID                 -- 수정ID
             , SYSDATE()                -- 수정일시
             , p_WRK_IP                 -- 수정IP
             )
        ;


    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 5. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
         WHEN OTHERS THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);
END;
/

-- PQHA_HOCHKRPT_PHOTO_Q (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_HOCHKRPT_PHOTO_Q" (
    p_WRK_TP            IN VARCHAR2 DEFAULT 'Q'         -- FLAG
,   p_SIT_CD            IN VARCHAR2                     -- 현장코드
,   p_CHK_DIV           IN VARCHAR2                     -- 체크구분
,   p_CHK_DGR            IN VARCHAR2                    -- 체크차수
,   RTN_CURSOR          OUT SYS_REFCURSOR 
)
IS
    /**************************************************************************************************************************
      Purpose : [본사점검 내부점검사진 조회] PROCEDRE (QSE > 재해예방관리 > 본사점검 내부점검사진 )

      REVISIONS
      Ver      Date               Author                  Description
      -------  -----------------  ----------------------  ---------------------------------------------------------------------
      1.0      XXXX/XX/XX                                 최초생성

    **************************************************************************************************************************/

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE  NUMBER :=-20009; -- ERROR 코드
    ERR_MSG   VARCHAR(200);    -- ERROR Message
    USER_EXCEPTION EXCEPTION;

BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 수행전 Check Logic ]
    ---------------------------------------------------------------------------------------------------------------------------

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Logic 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------

    IF p_WRK_TP = 'Q' THEN

        OPEN RTN_CURSOR FOR
        SELECT SIT_CD                   -- 현장코드
             , FQHA_GETDEPTNM_BY_DEPTCD(SIT_CD) AS SIT_NM
             , CHK_DIV                  -- 공통코드 : QSZ03
             , CHK_DGR                   -- 점검일자
             , PHOTO_DESC               -- 사진설명
             , ATFL_GRP                 -- 첨부파일
             , ATFL_GRP2 AS ATFL_GRP3                -- 첨부파일2
             , (SELECT ATFL_DESC 
                  FROM TCOZ_ATFL 
                 WHERE ATFL_GRP = A.ATFL_GRP 
                   AND ATFL_SEQ = (SELECT MIN(ATFL_SEQ) 
                                     FROM TCOZ_ATFL
                                    WHERE ATFL_GRP = A.ATFL_GRP)
             ) AS ATFL_DESC
          FROM TQHA_HOCHKRPT_PHOTO A
         WHERE 1=1
           AND SIT_CD   = p_SIT_CD
           AND CHK_DIV  = p_CHK_DIV
           AND CHK_DGR  = p_CHK_DGR
        ;

    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
         WHEN OTHERS THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);

END PQHA_HOCHKRPT_PHOTO_Q;
/

-- PQHA_HOCHKRPT_PHOTO_S (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_HOCHKRPT_PHOTO_S" (
    p_WRK_TP        VARCHAR2 :='U'      -- UPDATE FLAG( I: ISNERT, U:UPDATE, D:DELTE)
,   p_WRK_ID        VARCHAR2            -- 사용자 ID
,   p_WRK_IP        VARCHAR2            -- 사용자 IP
,   p_SIT_CD        VARCHAR2            -- 현장코드
,   p_CHK_DIV       VARCHAR2            -- 
,   p_CHK_DGR       VARCHAR2            -- 
,   p_ATFL_GRP      VARCHAR2            --
,   p_ATFL_GRP2     VARCHAR2            -- 
,   p_PHOTO_DESC    VARCHAR2            --

)
IS
    /**************************************************************************************************************************
      Purpose :

      REVISIONS
      Ver      Date               Author                  Description
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     XXXX-XX-XX                                    최초생성

    /**************************************************************************************************************************/


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR(200);             -- ERROR Message
    USER_EXCEPTION EXCEPTION;

    v_PHOTO_SEQ    	    NUMBER;

    v_APRV_STATS        VARCHAR2(20);
    v_APRV_STATS_NM     VARCHAR2(50);

BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 필수입력 필드  Check  ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_SIT_CD IS NULL)  THEN
        ERR_MSG := '현장코드는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_CHK_DIV IS NULL)  THEN
        ERR_MSG := '점검구분는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_WRK_TP != 'I' AND p_CHK_DGR IS NULL)  THEN
        ERR_MSG := '점검일자는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    ---------------------------------------------------------------------
--     결재상태 체크
--    SELECT MAX(T2.APRV_STATS)
--      INTO v_APRV_STATS
--      FROM TQHA_HOCHKRPT        T1
--      LEFT JOIN TQHA_APRV       T2 ON T1.SIT_CD     = T2.SIT_CD
--                                  AND T1.APRV_NO1   = T2.APRV_NO
--     WHERE T1.SIT_CD    = p_SIT_CD 
--       AND T1.CHK_DIV   = p_CHK_DIV
--       AND T1.CHK_DGR   = p_CHK_DGR
--    ;
--
--    IF v_APRV_STATS IN ('2', '4') THEN
--        ERR_MSG := '결재상태 [' || v_APRV_STATS_NM || ']인 데이터는 수정 불가합니다.';
--        RAISE USER_EXCEPTION;
--    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Process 선행조건 Check ]
    ---------------------------------------------------------------------------------------------------------------------------



    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Business Process ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF p_WRK_TP IN ('I', 'U') THEN


        MERGE INTO TQHA_HOCHKRPT_PHOTO  A  
        USING   DUAL
        ON     (      SIT_CD    = p_SIT_CD
                 AND  CHK_DIV   = p_CHK_DIV
                 AND  CHK_DGR   = p_CHK_DGR
                )
        WHEN MATCHED THEN
            UPDATE
                SET 
                 ATFL_GRP = p_ATFL_GRP
                ,ATFL_GRP2 = p_ATFL_GRP2
                ,PHOTO_DESC = p_PHOTO_DESC
                ,UPD_ID   = p_WRK_ID
                ,UPD_DTM  = SYSDATE
                ,UPD_IP   = p_WRK_IP
        WHEN NOT MATCHED THEN
            INSERT 
                 ( SIT_CD                  --현장코드
                 , CHK_DIV                 --공통코드 : QSZ03
                 , CHK_DGR                  --점검일자
                 , ATFL_GRP                --현장조감도,현장전경
                 , ATFL_GRP2                --현장조감도,현장전경
                 , PHOTO_DESC
                 , IPT_ID                  --신규입력ID
                 , IPT_DTM                 --신규입력일시
                 , IPT_IP                  --신규입력IP
                 , UPD_ID                  --최종수정ID
                 , UPD_DTM                 --최종수정일시
                 , UPD_IP                  --최종수정IP
                 )
            VALUES
                 ( p_SIT_CD
                 , p_CHK_DIV
                 , p_CHK_DGR
                 , p_ATFL_GRP
                 , p_ATFL_GRP2
                 , p_PHOTO_DESC
                 , p_WRK_ID
                 , SYSDATE                  --입력일시
                 , p_WRK_IP
                 , p_WRK_ID
                 , SYSDATE                  --수정일시
                 , p_WRK_IP
                 )
        ;
    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 5. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
         WHEN OTHERS THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);
END;
/

-- PQHA_HOCHKRPT_Q (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_HOCHKRPT_Q" (
    p_WRK_TP            IN VARCHAR2 DEFAULT 'Q'         -- FLAG
,   p_SIT_CD            IN VARCHAR2                     -- 현장코드
,   p_CHK_DIV           IN VARCHAR2                     -- 점검구분
,   p_CHK_DGR           IN VARCHAR2                     -- 점검차수
,   p_STR_DT            IN VARCHAR2                     -- 시작일자
,   p_END_DT            IN VARCHAR2                     -- 종료일자
,   p_CHK_DT            IN VARCHAR2                     -- 점검일자
,   p_QUARTER           IN VARCHAR2                     -- 분기
,   p_SCR_DIV           IN VARCHAR2                     -- 
,   RTN_CURSOR          OUT SYS_REFCURSOR
)
IS 
    /**************************************************************************************************************************
      Purpose : [본사점검(안전/보건) 조회] PROCEDRE (QSE > 재해예방관리 > 본사점검(안전/보건)  )

      REVISIONS
      Ver      Date               Author                  Description
      -------  -----------------  ----------------------  ---------------------------------------------------------------------
      1.0      XXXX/XX/XX                                 최초생성

    **************************************************************************************************************************/

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE  NUMBER :=-20009; -- ERROR 코드
    ERR_MSG   VARCHAR(200);    -- ERROR Message
    USER_EXCEPTION EXCEPTION; 

BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 수행전 Check Logic ]
    ---------------------------------------------------------------------------------------------------------------------------

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Logic 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------

    IF p_WRK_TP = 'Q' THEN

        OPEN RTN_CURSOR FOR        
        WITH HOCHKRPT AS (
		    SELECT 
		           A.SIT_CD                          -- 현장코드
		         , FQHA_GETCMSITENM_BY_SITECD(A.SIT_CD) AS SIT_NM
		         , A.CHK_DIV                          -- 공통코드 : QSZ03
		         , A.CHK_DGR                          -- 점검차수
		         , A.CHK_DT                           -- 점검일자
		         , A.QUARTER
		         , A.MA_DT                            -- 조치기간
		         , A.SIT_OMGR_EMPNO                   -- 현장소장사번
		         , A.INSP_EMPNO                       -- 점검자
		         , A.SAFT_MGR                         -- 안전관리자
		         -- , A.SIT_OMGR_NM                      -- 현장소장명
		         , A.INSP_NM                         -- 점검자성명
		         , A.SAFT_MGR_NM                     -- 안전관리자성명 
		         --,( SELECT USR_NM FROM TCOZ_USR_INFO WHERE USR_ID = A.INSP_EMPNO ) AS INSP_NM   			  -- 점검자
		         ,( SELECT USR_NM FROM TCOZ_USR_INFO WHERE USR_ID = A.SIT_OMGR_EMPNO ) AS SIT_OMGR_EMPNO_NM   -- 현장소장
	             --,( SELECT USR_NM FROM TCOZ_USR_INFO WHERE USR_ID = A.SAFT_MGR )  AS SAFT_MGR_NM   		  -- 안전관리자명	
		         , A.ORDPLC                           -- 발주처
		         , A.CNST_STR_DD
		         , A.CNST_END_DD                      -- 공사종료일
		         , A.CNST_STR_DD || ' ~ ' || A.CNST_END_DD AS CNST_DD -- 공사기간
		         , A.CNST_AMT                         -- 공사금액
		         , A.PROCRT                           -- 공정율
		         , A.MBOT_PSNNO                       -- 출역인원
		         , A.CNST_SCAL                        -- 공사규모
		         , A.DISS_ACM                         -- 재해누계
		         , A.DISS_CY                          -- 재해당해
		         , A.SAFT_MCHR                        -- 계상안전관리비
		         , A.SAFT_ACM_AMT                     -- 누계사용금액
		         , A.SAFT_USE_RT                      -- 사용율
		         , A.WRK_MATT                         -- 작업사항
		         , A.TDAY_WRK                         -- 금일작업
		         , A.SCH_WRK                          -- 예정작업
		         , A.RVLT_SCR1                        -- 전회점수1
		         , A.RVLT_SCR2                        -- 전회점수2
		         , A.RVLT_SCR3                        -- 전회점수3
		         , A.RVLT_SCR4                        -- 전회점수4
		         , A.RVLT_SCR5                        -- 전회점수5
		         , A.TTM_SCR1                         -- 금회점수1
		         , A.TTM_SCR2                         -- 금회점수2
		         , A.TTM_SCR3                         -- 금회점수3
		         , A.TTM_SCR4                         -- 금회점수4
		         , A.TTM_SCR5                         -- 금회점수5
		         , A.APRS_GRD1                        -- 평가등급1
		         , A.APRS_GRD2                        -- 평가등급2
		         , A.APRS_GRD3                        -- 평가등급3
		         , A.APRS_GRD4                        -- 평가등급4
		         , A.APRS_GRD5                        -- 평가등급5
		         , A.RMKS1                            -- 비고1
		         , A.RMKS2                            -- 비고2
		         , A.RMKS3                            -- 비고3
		         , A.RMKS4                            -- 비고4
		         , A.RMKS5                            -- 비고5
		         , A.EXCL_EXMP                        -- 우수사례
		         , A.MNG_MATT                         -- 관리사항
		         , A.ATFL_GRP                         -- 첨부파일
		         , A.PRGS_STATS_CD1                   -- 본사점검상태
		         , A.APRV_NO1                         -- 본사점검결재번호
		         , A.PRGS_STATS_CD2                   -- 조치결과상태
		         , A.APRV_NO2                         -- 조치결과결재번호
		         , A.CLOSE_YN
		         , DECODE(A.CLOSE_YN,'1','마감','') AS CLOSE_YN_NM
		           -- 1. 스칼라 서브쿼리 영역
		         , (SELECT FQHA_GETDEPTNM_BY_DEPTCD(BB.DEPT_CD)
		              FROM TCOZ_USR_INFO BB
		             WHERE BB.USR_ID = A.INSP_EMPNO) AS INSP_BLN        -- 점검자소속     
		         , (SELECT MAX(ERR.MA_DT)
		              FROM TQHA_HOCHKRPT_ERR ERR
		             WHERE ERR.SIT_CD  = A.SIT_CD
		               AND ERR.CHK_DIV = A.CHK_DIV
		               AND ERR.CHK_DT  = A.CHK_DT)   AS MX_MA_DT        -- 최대 조치일자
		      FROM TQHA_HOCHKRPT A
		      LEFT OUTER JOIN TQHA_APRV C 
		        ON A.SIT_CD   = C.SIT_CD
		       AND A.APRV_NO1 = C.APRV_NO
		     WHERE 1=1
		       AND A.SIT_CD     = NVL(p_SIT_CD, A.SIT_CD)
		       AND (
					    (p_CHK_DIV IS NOT NULL AND A.CHK_DIV = p_CHK_DIV)
					    OR
					    (p_CHK_DIV IS NULL AND (
					        (p_SCR_DIV = 1 AND A.CHK_DIV IN ('QS0730101', 'QS0730102')) OR
					        (p_SCR_DIV = 2 AND A.CHK_DIV IN ('QS073020101', 'QS073020102', 'QS073020103'))
					    ))
					)
		       AND REPLACE(A.CHK_DT, '-', '') BETWEEN REPLACE(NVL(p_STR_DT, A.CHK_DT), '-', '') AND REPLACE(NVL(p_END_DT, A.CHK_DT), '-', '')
		)
		SELECT R.*
		     , (TO_DATE(R.MX_MA_DT, 'YYYY/MM/DD') - TO_DATE(R.MA_DT, 'YYYY/MM/DD')) AS DIFF_MA_DT
		     , CASE WHEN (TO_DATE(R.MX_MA_DT, 'YYYY/MM/DD') - TO_DATE(R.MA_DT, 'YYYY/MM/DD')) > 0 THEN '●'
		            ELSE ''
		       END AS MA_DT_MARK
		  FROM HOCHKRPT R
		 ORDER BY R.CHK_DT DESC, R.CHK_DGR DESC, R.SIT_CD ASC
        ;

    ---------------------------------------------------------------------------------------------
    ELSIF p_WRK_TP = 'Q2' THEN

        OPEN RTN_CURSOR FOR 
            SELECT A.SIT_CD                          -- 현장코드
		         , FQHA_GETCMSITENM_BY_SITECD(A.SIT_CD) AS SIT_NM
		         , A.CHK_DIV                          -- 공통코드 : QSZ03
		         , A.CHK_DGR                          -- 점검차수
		         , A.CHK_DT                           -- 점검일자
		         , A.QUARTER
		         , A.MA_DT                            -- 조치기간
		         , A.SIT_OMGR_EMPNO                   -- 현장소장사번
		         , A.SAFT_MGR                         -- 안전관리자
		         , A.INSP_EMPNO                       -- 점검자		         
		         --,( SELECT USR_NM FROM TCOZ_USR_INFO WHERE USR_ID = A.INSP_EMPNO ) AS INSP_NM   			  -- 점검자
		         ,( SELECT USR_NM FROM TCOZ_USR_INFO WHERE USR_ID = A.SIT_OMGR_EMPNO ) AS SIT_OMGR_EMPNO_NM   -- 현장소장
	             --,( SELECT USR_NM FROM TCOZ_USR_INFO WHERE USR_ID = A.SAFT_MGR )  AS SAFT_MGR_NM   		  -- 안전관리자명		         
		         , A.INSP_NM                         -- 점검자성명		         
		         , A.SAFT_MGR_NM                     -- 안전관리자성명
		         --, A.SIT_OMGR_NM                      -- 현장소장명
		         , A.ORDPLC                           -- 발주처
		         , A.CNST_STR_DD      -- 공사시작일
		         , A.CNST_END_DD      -- 공사종료일
		         , A.CNST_AMT         -- 공사금액
		         , A.PROCRT           -- 공정율
		         , A.MBOT_PSNNO                       -- 출역인원
		         , A.CNST_SCAL                        -- 공사규모		         
		         , A.DISS_CY
		         , A.DISS_ACM		         
		         , A.SAFT_MCHR                        -- 계상안전관리비
		         , A.SAFT_ACM_AMT                     -- 누계사용금액
		         , A.SAFT_USE_RT                      -- 사용율
		         , A.WRK_MATT                         -- 작업사항
		         , A.TDAY_WRK                         -- 금일작업
		         , A.SCH_WRK                          -- 예정작업
		         , A.RVLT_SCR1                        -- 전회점수1
		         , A.RVLT_SCR2                        -- 전회점수2
		         , A.RVLT_SCR3                        -- 전회점수3
		         , A.RVLT_SCR4                        -- 전회점수4
		         , A.RVLT_SCR5                        -- 전회점수5
		         , A.TTM_SCR1                         -- 금회점수1
		         , A.TTM_SCR2                         -- 금회점수2
		         , A.TTM_SCR3                         -- 금회점수3
		         , A.TTM_SCR4                         -- 금회점수4
		         , A.TTM_SCR5                         -- 금회점수5
		         , A.APRS_GRD1                        -- 평가등급1
		         , A.APRS_GRD2                        -- 평가등급2
		         , A.APRS_GRD3                        -- 평가등급3
		         , A.APRS_GRD4                        -- 평가등급4
		         , A.APRS_GRD5                        -- 평가등급5
		         , A.RMKS1                            -- 비고1
		         , A.RMKS2                            -- 비고2
		         , A.RMKS3                            -- 비고3
		         , A.RMKS4                            -- 비고4
		         , A.RMKS5                            -- 비고5
		         , A.EXCL_EXMP                        -- 우수사례
		         , A.MNG_MATT                         -- 관리사항
		         , A.ATFL_GRP                         -- 첨부파일
		         , A.PRGS_STATS_CD1                   -- 본사점검상태
		         , A.APRV_NO1                         -- 본사점검결재번호
		         , A.PRGS_STATS_CD2                   -- 조치결과상태
		         , A.APRV_NO2                         -- 조치결과결재번호
		         , A.CLOSE_YN
		           -- 스칼라 서브쿼리 가공 영역
		         , (SELECT FQHA_GETDEPTNM_BY_DEPTCD(BB.DEPT_CD)
		              FROM TCOZ_USR_INFO BB
		             WHERE BB.USR_ID = A.INSP_EMPNO) AS INSP_BLN        
		         , (SELECT MAX(ERR.MA_DT)
		              FROM TQHA_HOCHKRPT_ERR ERR
		             WHERE ERR.SIT_CD  = A.SIT_CD
		               AND ERR.CHK_DIV = A.CHK_DIV
		               AND ERR.CHK_DT  = A.CHK_DT)   AS MX_MA_DT        
		         , A.CNST_STR_DD || ' ~ ' || A.CNST_END_DD AS CNST_PERIOD -- ★ 별칭 중복 방지를 위해 수정한 공사기간
		         , '▶ 결재상태 : ' || NVL((SELECT CD_NM FROM TCOA_COMCODE WHERE HRNK_CD = 'QS031' AND COM_CD = C.APRV_STATS), '-') AS APRV_STATS_NM 
		      FROM TQHA_HOCHKRPT A
		      LEFT OUTER JOIN TQHA_APRV C 
		        ON A.SIT_CD   = C.SIT_CD
		       AND A.APRV_NO1 = C.APRV_NO
		     WHERE A.SIT_CD  = p_SIT_CD
		       AND A.CHK_DIV = p_CHK_DIV
		       AND A.CHK_DGR = p_CHK_DGR
		 ;
			
    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
         WHEN OTHERS THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);

END PQHA_HOCHKRPT_Q;
/

-- PQHA_HOCHKRPT_S (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_HOCHKRPT_S" 
                            (p_WRK_TP  VARCHAR2 :='U'                                     -- UPDATE FLAG( I: ISNERT, U:UPDATE, D:DELTE)
                            ,p_WRK_ID  VARCHAR2                                           -- 사용자 ID 
                            ,p_WRK_IP  VARCHAR2                                           -- 사용자 IP 
                            ,p_SIT_CD TQHA_HOCHKRPT.SIT_CD%TYPE                           -- 현장코드
                            ,p_CHK_DIV TQHA_HOCHKRPT.CHK_DIV%TYPE                         -- 공통코드 : QSZ03
                            ,p_CHK_DGR TQHA_HOCHKRPT.CHK_DGR%TYPE                         -- 점검차수
                            ,p_CHK_DT TQHA_HOCHKRPT.CHK_DT%TYPE                           -- 점검일자
                            ,p_QUARTER TQHA_HOCHKRPT.QUARTER%TYPE                         -- 분기
                            ,p_MA_DT TQHA_HOCHKRPT.MA_DT%TYPE                             -- 조치기간
                            ,p_SIT_OMGR_EMPNO TQHA_HOCHKRPT.SIT_OMGR_EMPNO%TYPE           -- 현장소장사번
                            ,p_SIT_OMGR_NM TQHA_HOCHKRPT.SIT_OMGR_NM%TYPE                 -- 현장소장명
                            ,p_INSP_BLN TQHA_HOCHKRPT.INSP_BLN%TYPE                       -- 점검자소속
                            ,p_INSP_EMPNO TQHA_HOCHKRPT.INSP_EMPNO%TYPE                   -- 점검자
                            ,p_INSP_NM TQHA_HOCHKRPT.INSP_NM%TYPE                         -- 점검자성명
                            ,p_SAFT_MGR TQHA_HOCHKRPT.SAFT_MGR%TYPE                       -- 안전관리자
                            ,p_SAFT_MGR_NM TQHA_HOCHKRPT.SAFT_MGR_NM%TYPE                 -- 안전관리자성명
                            ,p_ORDPLC TQHA_HOCHKRPT.ORDPLC%TYPE                           -- 발주처
                            ,p_CNST_STR_DD TQHA_HOCHKRPT.CNST_STR_DD%TYPE                 -- 공사시작일 
                            ,p_CNST_END_DD TQHA_HOCHKRPT.CNST_END_DD%TYPE                 -- 공사종료일
                            ,p_CNST_AMT TQHA_HOCHKRPT.CNST_AMT%TYPE                       -- 공사금액
                            ,p_PROCRT TQHA_HOCHKRPT.PROCRT%TYPE                           -- 공정율
                            ,p_MBOT_PSNNO TQHA_HOCHKRPT.MBOT_PSNNO%TYPE                   -- 출역인원
                            ,p_CNST_SCAL TQHA_HOCHKRPT.CNST_SCAL%TYPE                     -- 공사규모
                            ,p_DISS_ACM TQHA_HOCHKRPT.DISS_ACM%TYPE                       -- 재해누계
                            ,p_DISS_CY TQHA_HOCHKRPT.DISS_CY%TYPE                         -- 재해당해
                            ,p_SAFT_MCHR TQHA_HOCHKRPT.SAFT_MCHR%TYPE                     -- 계상안전관리비
                            ,p_SAFT_ACM_AMT TQHA_HOCHKRPT.SAFT_ACM_AMT%TYPE               -- 누계사용금액
                            ,p_SAFT_USE_RT TQHA_HOCHKRPT.SAFT_USE_RT%TYPE                 -- 사용율
                            ,p_WRK_MATT TQHA_HOCHKRPT.WRK_MATT%TYPE                       -- 작업사항
                            ,p_TDAY_WRK TQHA_HOCHKRPT.TDAY_WRK%TYPE                       -- 금일작업
                            ,p_SCH_WRK TQHA_HOCHKRPT.SCH_WRK%TYPE                         -- 예정작업
                            ,p_RVLT_SCR1 TQHA_HOCHKRPT.RVLT_SCR1%TYPE                     -- 전회점수1
                            ,p_RVLT_SCR2 TQHA_HOCHKRPT.RVLT_SCR2%TYPE                     -- 전회점수2
                            ,p_RVLT_SCR3 TQHA_HOCHKRPT.RVLT_SCR3%TYPE                     -- 전회점수3
                            ,p_RVLT_SCR4 TQHA_HOCHKRPT.RVLT_SCR4%TYPE                     -- 전회점수4
                            ,p_RVLT_SCR5 TQHA_HOCHKRPT.RVLT_SCR5%TYPE                     -- 전회점수5
                            ,p_TTM_SCR1 TQHA_HOCHKRPT.TTM_SCR1%TYPE                       -- 금회점수1
                            ,p_TTM_SCR2 TQHA_HOCHKRPT.TTM_SCR2%TYPE                       -- 금회점수2
                            ,p_TTM_SCR3 TQHA_HOCHKRPT.TTM_SCR3%TYPE                       -- 금회점수3
                            ,p_TTM_SCR4 TQHA_HOCHKRPT.TTM_SCR4%TYPE                       -- 금회점수4
                            ,p_TTM_SCR5 TQHA_HOCHKRPT.TTM_SCR5%TYPE                       -- 금회점수5
                            ,p_APRS_GRD1 TQHA_HOCHKRPT.APRS_GRD1%TYPE                     -- 평가등급1
                            ,p_APRS_GRD2 TQHA_HOCHKRPT.APRS_GRD2%TYPE                     -- 평가등급2
                            ,p_APRS_GRD3 TQHA_HOCHKRPT.APRS_GRD3%TYPE                     -- 평가등급3
                            ,p_APRS_GRD4 TQHA_HOCHKRPT.APRS_GRD4%TYPE                     -- 평가등급4
                            ,p_APRS_GRD5 TQHA_HOCHKRPT.APRS_GRD5%TYPE                     -- 평가등급5
                            ,p_RMKS1 TQHA_HOCHKRPT.RMKS1%TYPE                             -- 비고1
                            ,p_RMKS2 TQHA_HOCHKRPT.RMKS2%TYPE                             -- 비고2
                            ,p_RMKS3 TQHA_HOCHKRPT.RMKS3%TYPE                             -- 비고3
                            ,p_RMKS4 TQHA_HOCHKRPT.RMKS4%TYPE                             -- 비고4
                            ,p_RMKS5 TQHA_HOCHKRPT.RMKS5%TYPE                             -- 비고5
                            ,p_EXCL_EXMP TQHA_HOCHKRPT.EXCL_EXMP%TYPE                     -- 우수사례
                            ,p_MNG_MATT TQHA_HOCHKRPT.MNG_MATT%TYPE                       -- 관리사항
                            ,p_ATFL_GRP TQHA_HOCHKRPT.ATFL_GRP%TYPE                       -- 첨부파일
                            ,p_PRGS_STATS_CD1 TQHA_HOCHKRPT.PRGS_STATS_CD1%TYPE           -- 본사점검상태
                            ,p_APRV_NO1 TQHA_HOCHKRPT.APRV_NO1%TYPE                       -- 본사점검결재번호
                            ,p_PRGS_STATS_CD2 TQHA_HOCHKRPT.PRGS_STATS_CD2%TYPE           -- 조치결과상태
                            ,p_APRV_NO2 TQHA_HOCHKRPT.APRV_NO2%TYPE                       -- 조치결과결재번호
                            )
IS 
    /**************************************************************************************************************************
      Purpose : 

      REVISIONS
      Ver      Date               Author                  Description 
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2026/07/08 16:56:48                         최초생성

    /**************************************************************************************************************************/


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR2(200);            -- ERROR Message
    USER_EXCEPTION EXCEPTION;

	v_cnt           NUMBER;
    v_cnt2          NUMBER;
    v_text          VARCHAR(100); 

    v_aplCnt        NUMBER;
    
    v_SEQ			NUMBER;
    v_APRV_STATS        VARCHAR2(20);
    v_APRV_STATS_NM     VARCHAR2(50);
    
BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 필수입력 필드  Check  ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_SIT_CD IS NULL)  THEN
        ERR_MSG := '현장코드는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_CHK_DIV IS NULL)  THEN
        ERR_MSG := '점검구분는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_WRK_TP != 'I' AND p_CHK_DGR IS NULL)  THEN
        ERR_MSG := '점검차수는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_CHK_DT IS NULL)  THEN
        ERR_MSG := '점검일자는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_QUARTER IS NULL)  THEN
        ERR_MSG := '분기는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;
    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Process 선행조건 Check ]
    ---------------------------------------------------------------------------------------------------------------------------

     -- 결재상태 체크
    SELECT MAX(T2.APRV_STATS)
         , MAX(T3.CD_NM )
      INTO v_APRV_STATS
         , v_APRV_STATS_NM
      FROM TQHA_HOCHKRPT        T1
      LEFT JOIN TQHA_APRV       T2 ON T1.SIT_CD     = T2.SIT_CD
                                  AND T1.APRV_NO2   = T2.APRV_NO
      LEFT JOIN TCOA_COMCODE    T3 ON T2.APRV_STATS = T3.COM_CD
                                  AND T3.HRNK_CD    = 'QS031'
     WHERE T1.SIT_CD    = p_SIT_CD
       AND T1.CHK_DIV   = p_CHK_DIV
       AND T1.CHK_DGR   = p_CHK_DGR
    ;
--
--    IF v_APRV_STATS IN ('2', '4') THEN
--        ERR_MSG := '결재상태 [' || v_APRV_STATS_NM || ']인 데이터는 수정 불가합니다.';
--        RAISE USER_EXCEPTION;
--    END IF;

    
    
    IF (p_WRK_TP = 'I')  THEN
   		     
	    SELECT COUNT(*) INTO v_cnt2
	      FROM TQHA_HOCHKRPT
	     WHERE SIT_CD       = p_SIT_CD
	       AND CHK_DIV      = p_CHK_DIV
	       AND QUARTER      = p_QUARTER
	       AND SUBSTR(CHK_DT,1,4) = SUBSTR(p_CHK_DT,1,4)
	    ;
	    IF (v_cnt2 > 0)  THEN
	        ERR_MSG := '이미 등록된 분기 입니다.';
	        RAISE USER_EXCEPTION;
	    END IF;
    
    END IF;
    
     SELECT COUNT(*) INTO v_cnt
      FROM TQHA_HOCHKRPT_CK
     WHERE SIT_CD       = p_SIT_CD
       AND CHK_DIV      = p_CHK_DIV
       AND CHK_DGR      = p_CHK_DGR
    ;
     
     /*
    IF LENGTHB(p_EXCL_EXMP) > 1000 THEN
	    ERR_MSG := '우수사례 글자수가 너무 많습니다.';
	    RAISE USER_EXCEPTION;
	END IF;
    
    IF LENGTHB(p_MNG_MATT) > 1000 THEN
	    ERR_MSG := '관리사항 글자수가 너무 많습니다.';
	    RAISE USER_EXCEPTION;
	END IF;
     */     

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Business Process ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_WRK_TP ='D') THEN
    
        IF v_APRV_STATS IN ('2', '4') THEN
            ERR_MSG := '결재중 또는 결재완료된 문서는 삭제 할 수 없습니다.';
            RAISE USER_EXCEPTION;
        END IF;
        
        --본사점검보고서_지적사항
        DELETE
          FROM TQHA_HOCHKRPT_ERR
         WHERE SIT_CD       = p_SIT_CD
           AND CHK_DIV      = p_CHK_DIV
           AND CHK_DGR      = p_CHK_DGR
        ;
        --본사점검보고서_체크리스트
        DELETE
          FROM TQHA_HOCHKRPT_CK
         WHERE SIT_CD       = p_SIT_CD
           AND CHK_DIV      = p_CHK_DIV
           AND CHK_DGR      = p_CHK_DGR
        ;
        
        --본사점검보고서_점검사진
        DELETE
          FROM TQHA_HOCHKRPT_PHOTO
         WHERE SIT_CD       = p_SIT_CD
           AND CHK_DIV      = p_CHK_DIV
           AND CHK_DGR      = p_CHK_DGR
         ;
          
        DELETE 
          FROM TQHA_HOCHKRPT
         WHERE SIT_CD = p_SIT_CD          --현장코드
           AND CHK_DIV = p_CHK_DIV         --공통코드 : QSZ03
           AND CHK_DGR = p_CHK_DGR;        --점검차수

    ELSIF (p_WRK_TP ='U') THEN
    
        UPDATE TQHA_HOCHKRPT
           SET CHK_DT               = p_CHK_DT                  --점검일자
              ,QUARTER              = p_QUARTER
              ,MA_DT                = p_MA_DT                   --조치기간
              ,SIT_OMGR_EMPNO       = p_SIT_OMGR_EMPNO          --현장소장사번
              ,SIT_OMGR_NM          = p_SIT_OMGR_NM             --현장소장명
              ,INSP_BLN             = p_INSP_BLN                --점검자소속
              ,INSP_EMPNO           = p_INSP_EMPNO              --점검자
              ,INSP_NM              = p_INSP_NM                --점검자성명
              ,SAFT_MGR             = p_SAFT_MGR                --안전관리자
              ,SAFT_MGR_NM          = p_SAFT_MGR_NM            --안전관리자성명
              ,ORDPLC               = p_ORDPLC                  --발주처
              ,CNST_STR_DD          = p_CNST_STR_DD             --공사시작일
              ,CNST_END_DD          = p_CNST_END_DD             --공사종료일
              ,CNST_AMT             = p_CNST_AMT                --공사금액
              ,PROCRT               = p_PROCRT                  --공정율
              ,MBOT_PSNNO           = p_MBOT_PSNNO              --출역인원
              ,CNST_SCAL            = p_CNST_SCAL               --공사규모
              ,DISS_ACM             = p_DISS_ACM                --재해누계
              ,DISS_CY              = p_DISS_CY                 --재해당해
              ,SAFT_MCHR            = p_SAFT_MCHR               --계상안전관리비
              ,SAFT_ACM_AMT         = p_SAFT_ACM_AMT            --누계사용금액
              ,SAFT_USE_RT          = p_SAFT_USE_RT             --사용율
              ,WRK_MATT             = p_WRK_MATT                --작업사항
              ,TDAY_WRK             = p_TDAY_WRK                --금일작업
              ,SCH_WRK              = p_SCH_WRK                 --예정작업
              ,RVLT_SCR1            = p_RVLT_SCR1               --전회점수1
              ,RVLT_SCR2            = p_RVLT_SCR2               --전회점수2
              ,RVLT_SCR3            = p_RVLT_SCR3               --전회점수3
              ,RVLT_SCR4            = p_RVLT_SCR4               --전회점수4
              ,RVLT_SCR5            = p_RVLT_SCR5               --전회점수5
              ,TTM_SCR1             = p_TTM_SCR1                --금회점수1
              ,TTM_SCR2             = p_TTM_SCR2                --금회점수2
              ,TTM_SCR3             = p_TTM_SCR3                --금회점수3
              ,TTM_SCR4             = p_TTM_SCR4                --금회점수4
              ,TTM_SCR5             = p_TTM_SCR5                --금회점수5
              ,APRS_GRD1            = p_APRS_GRD1               --평가등급1
              ,APRS_GRD2            = p_APRS_GRD2               --평가등급2
              ,APRS_GRD3            = p_APRS_GRD3               --평가등급3
              ,APRS_GRD4            = p_APRS_GRD4               --평가등급4
              ,APRS_GRD5            = p_APRS_GRD5               --평가등급5
              ,RMKS1                = p_RMKS1                   --비고1
              ,RMKS2                = p_RMKS2                   --비고2
              ,RMKS3                = p_RMKS3                   --비고3
              ,RMKS4                = p_RMKS4                   --비고4
              ,RMKS5                = p_RMKS5                   --비고5
              ,EXCL_EXMP            = p_EXCL_EXMP               --우수사례
              ,MNG_MATT             = p_MNG_MATT                --관리사항
              ,ATFL_GRP             = p_ATFL_GRP                --첨부파일
              ,UPD_ID               = p_WRK_ID                  --수정ID 
              ,UPD_DTM              = SYSDATE()                 --수정일시
              ,UPD_IP               = p_WRK_IP                  --수정IP
         WHERE SIT_CD = p_SIT_CD          --현장코드
           AND CHK_DIV = p_CHK_DIV         --공통코드 : QSZ03
           AND CHK_DGR = p_CHK_DGR;        --점검차수
           
           
            IF (v_cnt <= 0)  THEN

            INSERT 
              INTO TQHA_HOCHKRPT_CK
                 ( SIT_CD               -- 현장코드
                 , CHK_DIV              -- 공통코드 : QSZ03
                 , CHK_DGR               -- 점검차수
                 , CHK_DT               -- 점검일자
                 , COM_CD               -- 공통코드 : QSZ03
                 , HO_CHK_DIV_CD        -- 공통코드 : QSZ0310
                 , HO_CHK_DIV_CD2       -- 본사점검구분코드
                 , HO_CHK_ITM_CD        -- 본사점검항목코드
                 , APRS_CHK 		    -- 공통코드 : QSA04
                 , APRS_PNDS
                 , IPT_ID               -- 신규입력ID
                 , IPT_DTM              -- 신규입력일시
                 , IPT_IP               -- 신규입력IP
                 , UPD_ID               -- 최종수정ID
                 , UPD_DTM              -- 최종수정일시
                 , UPD_IP               -- 최종수정IP
                 )
            SELECT 
		           p_SIT_CD             -- 현장코드
                 , p_CHK_DIV            -- 공통코드 : QSZ03
                 , p_CHK_DGR               -- 점검차수
                 , p_CHK_DT             -- 점검일자
                 , A.COM_CD
			     , A.HO_CHK_DIV_CD
			     , A.HO_CHK_DIV_CD2
			     , A.HO_CHK_ITM_CD
			      , NULL                 -- 공통코드 : QSA04
			     , A.MAX_SCORE
                 , p_WRK_ID             -- 입력ID
                 , SYSDATE()            -- 입력일시
                 , p_WRK_IP             -- 입력IP
                 , p_WRK_ID             -- 수정ID
                 , SYSDATE()            -- 수정일시
                 , p_WRK_IP             -- 수정IP
		   FROM TQHA_CKLST_ITM A,
		   (
		   	   SELECT HO_CHK_DIV_CD2
			   FROM TQHA_CKLST
			   WHERE COM_CD = p_CHK_DIV
			   AND HO_CHK_DIV_USE_YN = '1'
			   GROUP BY HO_CHK_DIV_CD2
		   ) B
		   WHERE A.HO_CHK_DIV_CD2 = B.HO_CHK_DIV_CD2
 		     AND A.HO_CHK_ITM_USE_YN = '1'
		   ORDER BY HO_CHK_DIV_CD, HO_CHK_ITM_CD
		   ;
		   
        END IF;
        
    ELSE 
    
    	SELECT NVL(MAX(CHK_DGR), 0) + 1 INTO v_SEQ
    	FROM TQHA_HOCHKRPT
    	WHERE SIT_CD = p_SIT_CD
          AND CHK_DIV = p_CHK_DIV;
    	
        INSERT INTO TQHA_HOCHKRPT
                   ( SIT_CD                  --현장코드
                    ,CHK_DIV                 --공통코드 : QSZ03
                    ,CHK_DGR                 --점검차수
                    ,CHK_DT                  --점검일자
                    ,QUARTER
                    ,MA_DT                   --조치기간
                    ,SIT_OMGR_EMPNO          --현장소장사번
                    ,SIT_OMGR_NM             --현장소장명
                    ,INSP_BLN                --점검자소속
                    ,INSP_EMPNO              --점검자
                    ,INSP_NM                --점검자성명
                    ,SAFT_MGR                --안전관리자
                    ,SAFT_MGR_NM            --안전관리자성명
                    ,ORDPLC                  --발주처
                    ,CNST_STR_DD             --공사시작일
                    ,CNST_END_DD             --공사종료일
                    ,CNST_AMT                --공사금액
                    ,PROCRT                  --공정율
                    ,MBOT_PSNNO              --출역인원
                    ,CNST_SCAL               --공사규모
                    ,DISS_ACM                --재해누계
                    ,DISS_CY                 --재해당해
                    ,SAFT_MCHR               --계상안전관리비
                    ,SAFT_ACM_AMT            --누계사용금액
                    ,SAFT_USE_RT             --사용율
                    ,WRK_MATT                --작업사항
                    ,TDAY_WRK                --금일작업
                    ,SCH_WRK                 --예정작업
                    ,RVLT_SCR1               --전회점수1
                    ,RVLT_SCR2               --전회점수2
                    ,RVLT_SCR3               --전회점수3
                    ,RVLT_SCR4               --전회점수4
                    ,RVLT_SCR5               --전회점수5
                    ,TTM_SCR1                --금회점수1
                    ,TTM_SCR2                --금회점수2
                    ,TTM_SCR3                --금회점수3
                    ,TTM_SCR4                --금회점수4
                    ,TTM_SCR5                --금회점수5
                    ,APRS_GRD1               --평가등급1
                    ,APRS_GRD2               --평가등급2
                    ,APRS_GRD3               --평가등급3
                    ,APRS_GRD4               --평가등급4
                    ,APRS_GRD5               --평가등급5
                    ,RMKS1                   --비고1
                    ,RMKS2                   --비고2
                    ,RMKS3                   --비고3
                    ,RMKS4                   --비고4
                    ,RMKS5                   --비고5
                    ,EXCL_EXMP               --우수사례
                    ,MNG_MATT                --관리사항
                    ,ATFL_GRP                --첨부파일
                    ,PRGS_STATS_CD1          --본사점검상태
                    ,APRV_NO1                --본사점검결재번호
                    ,PRGS_STATS_CD2          --조치결과상태
                    ,APRV_NO2                --조치결과결재번호
                    ,CLOSE_YN
                    ,IPT_ID                  --입력ID
                    ,IPT_DTM                 --입력일시
                    ,IPT_IP                  --입력IP
                    ,UPD_ID                  --수정ID
                    ,UPD_DTM                 --수정일시
                    ,UPD_IP                  --수정IP
                    )
             VALUES (p_SIT_CD                --현장코드
                    ,p_CHK_DIV               --공통코드 : QSZ03
                    ,v_SEQ                   --점검차수
                    ,p_CHK_DT                --점검일자
                    ,p_QUARTER
                    ,p_MA_DT                 --조치기간
                    ,p_SIT_OMGR_EMPNO        --현장소장사번
                    ,p_SIT_OMGR_NM           --현장소장명
                    ,p_INSP_BLN              --점검자소속
                    ,p_INSP_EMPNO            --점검자
                    ,p_INSP_NM              --점검자성명
                    ,p_SAFT_MGR              --안전관리자
                    ,p_SAFT_MGR_NM          --안전관리자성명
                    ,(SELECT LISTAGG(B.CUST_NM, ', ') WITHIN GROUP (ORDER BY B.CUST_NM) AS CUST_LIST
	                  FROM TCMZ_SIT_CLIENT A
	                       JOIN TCOA_TRADE   B ON B.CUST_CD = A.CUST_CD
	                 WHERE A.SIT_CD         = p_SIT_CD
	                   AND A.ORDPLC_DIV     = '1010'
	                 GROUP BY A.SIT_CD
	                )
                    ,p_CNST_STR_DD             --공사시작일
                    ,p_CNST_END_DD             --공사종료일
                    ,p_CNST_AMT                --공사금액
                    ,p_PROCRT                --공정율
                    ,p_MBOT_PSNNO            --출역인원
                    ,p_CNST_SCAL             --공사규모
                    ,p_DISS_ACM              --재해누계
                    ,p_DISS_CY               --재해당해
                    ,p_SAFT_MCHR             --계상안전관리비
                    ,p_SAFT_ACM_AMT          --누계사용금액
                    ,p_SAFT_USE_RT           --사용율
                    ,p_WRK_MATT              --작업사항
                    ,p_TDAY_WRK              --금일작업
                    ,p_SCH_WRK               --예정작업
                    ,p_RVLT_SCR1             --전회점수1
                    ,p_RVLT_SCR2             --전회점수2
                    ,p_RVLT_SCR3             --전회점수3
                    ,p_RVLT_SCR4             --전회점수4
                    ,p_RVLT_SCR5             --전회점수5
                    ,p_TTM_SCR1              --금회점수1
                    ,p_TTM_SCR2              --금회점수2
                    ,p_TTM_SCR3              --금회점수3
                    ,p_TTM_SCR4              --금회점수4
                    ,p_TTM_SCR5              --금회점수5
                    ,p_APRS_GRD1             --평가등급1
                    ,p_APRS_GRD2             --평가등급2
                    ,p_APRS_GRD3             --평가등급3
                    ,p_APRS_GRD4             --평가등급4
                    ,p_APRS_GRD5             --평가등급5
                    ,p_RMKS1                 --비고1
                    ,p_RMKS2                 --비고2
                    ,p_RMKS3                 --비고3
                    ,p_RMKS4                 --비고4
                    ,p_RMKS5                 --비고5
                    ,p_EXCL_EXMP             --우수사례
                    ,p_MNG_MATT              --관리사항
                    ,p_ATFL_GRP              --첨부파일
                    ,p_PRGS_STATS_CD1        --본사점검상태
                    ,p_APRV_NO1              --본사점검결재번호
                    ,p_PRGS_STATS_CD2        --조치결과상태
                    ,p_APRV_NO2              --조치결과결재번호
                    ,'0'
                    ,p_WRK_ID                --입력ID 
                    ,SYSDATE()               --입력일시
                    ,p_WRK_IP                --입력IP
                    ,p_WRK_ID                --수정ID
                    ,SYSDATE()               --수정일시
                    ,p_WRK_IP);              --수정IP                    
                   
                    
        IF (v_cnt <= 0)  THEN

            INSERT 
              INTO TQHA_HOCHKRPT_CK
                 ( SIT_CD               -- 현장코드
                 , CHK_DIV              -- 공통코드 : QSZ03
                 , CHK_DGR               -- 점검차수
                 , CHK_DT               -- 점검일자
                 , COM_CD               -- 공통코드 : QSZ03
                 , HO_CHK_DIV_CD        -- 공통코드 : QSZ0310
                 , HO_CHK_DIV_CD2       -- 본사점검구분코드
                 , HO_CHK_ITM_CD        -- 본사점검항목코드
                 , APRS_CHK 		    -- 공통코드 : QSA04
                 , APRS_PNDS
                 , IPT_ID               -- 신규입력ID
                 , IPT_DTM              -- 신규입력일시
                 , IPT_IP               -- 신규입력IP
                 , UPD_ID               -- 최종수정ID
                 , UPD_DTM              -- 최종수정일시
                 , UPD_IP               -- 최종수정IP
                 )
            SELECT 
		           p_SIT_CD             -- 현장코드
                 , p_CHK_DIV            -- 공통코드 : QSZ03
                 , v_SEQ                -- 점검차수
                 , p_CHK_DT             -- 점검일자
                 , A.COM_CD
			     , A.HO_CHK_DIV_CD
			     , A.HO_CHK_DIV_CD2
			     , A.HO_CHK_ITM_CD
			     , CASE WHEN A.HO_CHK_DIV_CD2 IN ('QS073010101', 'QS073010102', 'QS073010201', 'QS073010202') THEN 'QS0740202' 
				         WHEN A.HO_CHK_DIV_CD2 IN ('QS073010103', 'QS073010203', 'QS073020101', 'QS073020102','QS073020103') THEN 'QS0740102' 
			       ELSE NULL END
			     , A.MAX_SCORE
                 , p_WRK_ID             -- 입력ID
                 , SYSDATE()            -- 입력일시
                 , p_WRK_IP             -- 입력IP
                 , p_WRK_ID             -- 수정ID
                 , SYSDATE()            -- 수정일시
                 , p_WRK_IP             -- 수정IP
		   FROM TQHA_CKLST_ITM A,
		   (
		   	   SELECT HO_CHK_DIV_CD2
			   FROM TQHA_CKLST
			   WHERE 1=1
			    AND (
				       ( SUBSTR(p_CHK_DIV, 1, 7) = 'QS07301' AND COM_CD = p_CHK_DIV ) OR ( SUBSTR(p_CHK_DIV, 1, 7) = 'QS07302' AND HO_CHK_DIV_CD2 = p_CHK_DIV )
			        )
			   AND HO_CHK_DIV_USE_YN = '1'
			   GROUP BY HO_CHK_DIV_CD2
		   ) B
		   WHERE A.HO_CHK_DIV_CD2 = B.HO_CHK_DIV_CD2
 		     AND A.HO_CHK_ITM_USE_YN = '1'
		   ORDER BY HO_CHK_DIV_CD, HO_CHK_ITM_CD
		   ;
            
            -- 점수
            UPDATE TQHA_HOCHKRPT_CK M
				SET M.APRS_SCR = CASE WHEN HO_CHK_DIV_CD2 IN ('QS073010101', 'QS073010102', 'QS073010201', 'QS073010202') 
											THEN APRS_PNDS * ((SELECT NO_VAL_1 FROM TCOA_COMCODE WHERE COM_CD = 'QS0740202') / 100) -- 항목4개
							          WHEN HO_CHK_DIV_CD2 IN ('QS073010103', 'QS073010203', 'QS073020101', 'QS073020102','QS073020103') 
							          		THEN APRS_PNDS * ((SELECT NO_VAL_1 FROM TCOA_COMCODE WHERE COM_CD = 'QS0740102') / 100) --항목 3개
						         ELSE NULL END
			 WHERE M.SIT_CD  = p_SIT_CD
			   AND M.CHK_DIV = p_CHK_DIV
			   AND M.CHK_DGR = v_SEQ;            
            
            
            -- 총점
            UPDATE TQHA_HOCHKRPT M
			SET -- 1. 전회점수 (이전 차수 데이터가 없으면 0)
		       (M.RVLT_SCR1, M.RVLT_SCR2, M.RVLT_SCR3, M.RVLT_SCR4, M.RVLT_SCR5) = 
		       (
		           SELECT NVL(MAX(PREV.TTM_SCR1), 0)
		                , NVL(MAX(PREV.TTM_SCR2), 0)
		                , NVL(MAX(PREV.TTM_SCR3), 0)
		                , NVL(MAX(PREV.TTM_SCR4), 0)
		                , NVL(MAX(PREV.TTM_SCR5), 0)
		             FROM TQHA_HOCHKRPT PREV
		            WHERE PREV.SIT_CD  = p_SIT_CD
		              AND PREV.CHK_DIV = p_CHK_DIV
		              AND PREV.CHK_DGR = v_SEQ - 1
		       )
		       
		     -- 2. 금회점수 (별칭을 부여해 구조를 단순화)
		     , (M.TTM_SCR1, M.TTM_SCR2, M.TTM_SCR3, M.TTM_SCR4, M.TTM_SCR5) = 
		       (
		             SELECT G.V1, G.V2, G.V3, G.V4
		                  , G.V1 + G.V2 + G.V3 
		             FROM (
		                   SELECT NVL(MAX(CASE WHEN SUBSTR(CK.HO_CHK_DIV_CD2, -1) = '1' THEN CK.SM_SCR END), 0) AS V1
		                        , NVL(MAX(CASE WHEN SUBSTR(CK.HO_CHK_DIV_CD2, -1) = '2' THEN CK.SM_SCR END), 0) AS V2
		                        , NVL(MAX(CASE WHEN SUBSTR(CK.HO_CHK_DIV_CD2, -1) = '3' THEN CK.SM_SCR END), 0) AS V3
		                        , 0 AS V4
		                     FROM (
		                           SELECT HO_CHK_DIV_CD2
		                                , SUM(APRS_SCR) AS SM_SCR
		                             FROM TQHA_HOCHKRPT_CK
		                            WHERE SIT_CD  = p_SIT_CD
		                              AND CHK_DIV = p_CHK_DIV
		                              AND CHK_DGR = v_SEQ
		                            GROUP BY SIT_CD, CHK_DIV, CHK_DGR, HO_CHK_DIV_CD2
		                          ) CK
		                  ) G
		       )
		     
			 WHERE M.SIT_CD  = p_SIT_CD
			   AND M.CHK_DIV = p_CHK_DIV
			   AND M.CHK_DGR = v_SEQ;
            
        END IF;
        
        -- 공사관련 값 가져오기
        MERGE INTO TQHA_HOCHKRPT H
		USING (
		    WITH CM_SIT AS (
		        -- [A] 기본 현장 정보 및 출역인원 조회 (전달해주신 쿼리 기반)
		        SELECT A1.SIT_CD
		             , A1.CNST_STR_DT                              AS CNST_STR_DD
		             , A1.CNST_END_DT                              AS CNST_END_DD
		              , A1.CNST_CMPD                                AS CNST_SCAL
		             , (SELECT SUM(IPT_PCNT) 
		                  FROM TCMW_WRK_MBOT 
		                 WHERE SIT_CD = p_SIT_CD)                 AS MBOT_PSNNO             
		             , B1.OCO_UNTKSO_SUM_AMT AS CNST_AMT
		--             
		--             , TO_CHAR(CASE WHEN NVL(B1.TOT_UNTK_SPLCM_AMT,0) = 0
		--	                   THEN 0
		--                        ELSE ROUND(NVL(B1.OCO_UNTK_SPLCM_AMT,0) * 1.0 /
		--                             NVL(B1.TOT_UNTK_SPLCM_AMT,0) * 100, 2)
		--               END, 'FM999,999,990.00')                     AS PROCRT --지분율(공사)
		--               
		          FROM TCMZ_SIT A1
		         INNER JOIN TCMZ_SIT_CONT B1
		            ON A1.SIT_CD = B1.SIT_CD
		         WHERE A1.SIT_CD = p_SIT_CD
		    ),
		    SAFT_DATA AS (
		        -- [B] 안전관리비 및 재해 현황 데이터 집계
		        SELECT 
		            A.SIT_CD,
		            NVL(I.APRP_SAFT_MCHR, 0) AS APRP_SAFT_MCHR,
		            NVL(B.C_USE_AMT, 0) AS C_USE_AMT,
		            ROUND(NVL(B.C_USE_AMT, 0) / DECODE(I.APRP_SAFT_MCHR, 0, NULL, I.APRP_SAFT_MCHR) * 100, 2) AS APRP_USE_RATE,
		           '사망 : '||D.YTD_DEAD_CNT||'명 / 부상 : '||D.YTD_INJ_CNT||'명' AS YTD_DSS_CNT,
				   '사망 : '||D.TOTAL_DEAD_CNT||'명 / 부상 : '||D.TOTAL_INJ_CNT||'명' AS TOTAL_DSS_CNT
		        FROM (
		            SELECT SIT_CD
		              FROM TQHA_SAFECOST_BGTYM
		             WHERE SIT_CD = p_SIT_CD
		               AND SUBSTR(RLV_YM, 1, 4) <= SUBSTR(p_CHK_DT, 1, 4)
		             GROUP BY SIT_CD
		        ) A
		        LEFT JOIN (
		            SELECT SIT_CD
		                 , SUM(C_USE_AMT) AS C_USE_AMT
		              FROM (
		                  SELECT SIT_CD
		                       , SUM(USE_AMT) AS C_USE_AMT  
		                    FROM TQHA_SAFECOST_ARSLT
		                   WHERE SIT_CD = p_SIT_CD
		                     AND SUBSTR(RLV_YM, 1, 4) <= SUBSTR(p_CHK_DT, 1, 4)
		                   GROUP BY SIT_CD
		                   UNION ALL
		                  SELECT A.SIT_CD
		                       , SUM(A.USE_AMT) AS C_USE_AMT 
		                    FROM TQHA_SAFECOST_ARSLT_CO A
		                    LEFT JOIN TQHA_SAFECOST_MMARSLT_CO B 
		                      ON A.SIT_CD   = B.SIT_CD
		                     AND A.CUST_CD  = B.CUST_CD
		                     AND A.VNDR_SEQ = B.VNDR_SEQ
		                     AND A.RLV_YM   = B.RLV_YM
		                   WHERE A.SIT_CD = p_SIT_CD
		                     AND SUBSTR(A.RLV_YM, 1, 4) <= SUBSTR(p_CHK_DT, 1, 4)
		                     AND B.SITE_APRV_YN = '1'
		                   GROUP BY A.SIT_CD
		              )
		             GROUP BY SIT_CD
		        ) B ON A.SIT_CD = B.SIT_CD
		        LEFT JOIN TQHA_SAFECOST_INFO I ON A.SIT_CD = I.SIT_CD
		        LEFT JOIN (
		            SELECT SIT_CD 
		                 ,SUM(CASE WHEN SUBSTR(ACCD_DT, 1, 4) = SUBSTR(p_CHK_DT, 1, 4) THEN DSS_CNT ELSE 0 END)     AS YTD_DSS_CNT     -- 당해 재해자수
					     ,SUM(CASE WHEN SUBSTR(ACCD_DT, 1, 4) = SUBSTR(p_CHK_DT, 1, 4) THEN DEAD_CNT ELSE 0 END)    AS YTD_DEAD_CNT    -- 당해 사망자수
					     ,SUM(CASE WHEN SUBSTR(ACCD_DT, 1, 4) = SUBSTR(p_CHK_DT, 1, 4) THEN INJ_CNT ELSE 0 END)     AS YTD_INJ_CNT     -- 당해 부상자수
					     ,SUM(CASE WHEN SUBSTR(ACCD_DT, 1, 4) = SUBSTR(p_CHK_DT, 1, 4) THEN OCC_DIS_CNT ELSE 0 END) AS YTD_OCC_DIS_CNT -- 당해 직업병수
					     -- ==========================================
					     -- 2. 전체 누계 (과거 전체 기간 합산)
					     -- ==========================================
					     ,SUM(DSS_CNT)     AS TOTAL_DSS_CNT     -- 전체 누계 재해자수
					     ,SUM(DEAD_CNT)    AS TOTAL_DEAD_CNT    -- 전체 누계 사망자수
					     ,SUM(INJ_CNT)     AS TOTAL_INJ_CNT     -- 전체 누계 부상자수
					     ,SUM(OCC_DIS_CNT) AS TOTAL_OCC_DIS_CNT -- 전체 누계 직업병수			     
		              FROM TQHA_IDAC
		             WHERE SIT_CD = p_SIT_CD
		             GROUP BY SIT_CD
		        ) D ON A.SIT_CD = D.SIT_CD
		    )
		    -- [C] 업데이트에 매핑할 원천 데이터 결합
		    SELECT 
		        H.ROWID AS RID,
		        C.CNST_STR_DD,
		        C.CNST_END_DD,
		        C.CNST_AMT,
		        --C.PROCRT,
		        C.CNST_SCAL,
		        C.MBOT_PSNNO,
		        S.TOTAL_DSS_CNT                      AS DISS_ACM,
		        S.YTD_DSS_CNT                        AS DISS_CY,
		        S.APRP_SAFT_MCHR                     AS SAFT_MCHR,
		        S.C_USE_AMT                          AS SAFT_ACM_AMT,
		        S.APRP_USE_RATE                      AS SAFT_USE_RT
		    FROM TQHA_HOCHKRPT H
		    LEFT JOIN CM_SIT C    ON H.SIT_CD = C.SIT_CD
		    LEFT JOIN SAFT_DATA S ON H.SIT_CD = S.SIT_CD
		    WHERE H.SIT_CD = p_SIT_CD
		      AND H.CHK_DIV = p_CHK_DIV
		      AND H.CHK_DGR = p_CHK_DGR
		) U
		ON (H.ROWID = U.RID)
		WHEN MATCHED THEN
		UPDATE SET 
		    H.CNST_STR_DD  = U.CNST_STR_DD,     -- 공사시작일
		    H.CNST_END_DD  = U.CNST_END_DD,     -- 공사종료일
		    H.CNST_AMT     = U.CNST_AMT,        -- 공사금액
		    --H.PROCRT       = U.PROCRT,          -- 공정율
		    H.CNST_SCAL    = U.CNST_SCAL,       -- 공사규모
		    H.MBOT_PSNNO   = U.MBOT_PSNNO,      -- 출역인원
		    H.DISS_ACM     = U.DISS_ACM,        -- 재해누계 (전체 누계 재해자수)
		    H.DISS_CY      = U.DISS_CY,         -- 재해당해 (당해 재해자수)
		    H.SAFT_MCHR    = U.SAFT_MCHR,       -- 계상안전관리비
		    H.SAFT_ACM_AMT = U.SAFT_ACM_AMT,    -- 누계사용금액
		    H.SAFT_USE_RT  = U.SAFT_USE_RT      -- 사용율
		;
    
        
    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 5. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN 
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);
END PQHA_HOCHKRPT_S;
/

-- PQHA_HODCAB_Q (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_HODCAB_Q" 
                            (p_WRK_TP  VARCHAR2 :='U'                                     -- UPDATE FLAG( I: ISNERT, U:UPDATE, D:DELTE)
                            ,p_WRK_ID  VARCHAR2                                           -- 사용자 ID
                            ,p_WRK_IP  VARCHAR2                                           -- 사용자 IP
                            ,p_WRT_DT TQHA_HODCAB.WRT_DT%TYPE                             -- 작성일자
                            ,p_SEQ TQHA_HODCAB.SEQ%TYPE                                   -- 순번
                            ,p_WRT_FRDT TQHA_HODCAB.WRT_DT%TYPE                           -- 작성시작일자
                            ,p_WRT_TODT TQHA_HODCAB.WRT_DT%TYPE                           -- 작성종료일자
                            ,RTN_CURSOR              OUT SYS_REFCURSOR
                            )
IS
    /**************************************************************************************************************************
      Purpose : 본사 문서접수

      REVISIONS
      Ver      Date               Author                  Description
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2024/04/23 17:00:15                         최초생성

    /**************************************************************************************************************************/

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR2(200);            -- ERROR Message
    USER_EXCEPTION EXCEPTION;


BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 수행전 Check Logic ]
    ---------------------------------------------------------------------------------------------------------------------------


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Logic 처리
    ---------------------------------------------------------------------------------------------------------------------------
    IF p_WRK_TP = 'Q' THEN

        OPEN RTN_CURSOR FOR
        SELECT AAA.WRT_DT             -- 작성일자
             , AAA.SEQ AS SEQ2        -- 순번
             , AAA.TTL                -- 제목
             , AAA.WRTR_EMPNO         -- 작성자사번
             , AAA.WRTR_PNM           -- 작성자성명
             , AAA.REQ_DT             -- 요청일자
             , AAA.SNSB_YN            -- 가감점대상             
             , AAA.CMPL_YN            -- 완료여부
             , AAA.CMPL_DT            -- 완료일자
             , AAA.ATFL_GRP           -- 참고자료
             , (
                  SELECT NVL(SUM(BBB.SITE_ATFL_CNT), 0)
                    FROM (
                          SELECT BB.SIT_CD
                               , BB.ATFL_GRP
                               , (
                                  SELECT COUNT(1) 
                                    FROM TCOZ_ATFL 
                                   WHERE ATFL_GRP = BB.ATFL_GRP     
                                 ) AS SITE_ATFL_CNT
                            FROM TQHA_SITEDOC BB
                           WHERE 1=1        
                             AND BB.WRT_DT = AAA.WRT_DT
                             AND BB.SEQ = AAA.SEQ
                             AND BB.ATFL_GRP IS NOT NULL 
                           GROUP BY BB.SIT_CD  
                                  , BB.ATFL_GRP  
                         ) BBB               
               ) AS SITE_ATFL_CNT             
          FROM TQHA_HODCAB AAA
         WHERE 1=1
         
       AND AAA.WRT_DT BETWEEN NVL(p_WRT_FRDT, TO_DATE('1900-01-01', 'YYYY-MM-DD')) 
                          AND NVL(p_WRT_TODT, TO_DATE('4712-12-31', 'YYYY-MM-DD'))
                          
         ORDER BY AAA.WRT_DT DESC
        ;

    ELSIF p_WRK_TP = 'Q1' THEN

        OPEN RTN_CURSOR FOR
        SELECT AAAA.*
       FROM (
             SELECT AAA.WRT_DT                 -- 작성일자
                  , AAA.SEQ AS SEQ2             -- 순번
                  , AAA.SIT_CD                -- 현장코드
                  , AAA.SIT_NM                -- 현장명
                  , AAA.TERR_CD                -- 지역코드
                  , 'H' AS POSITION             -- 본부현장구분
                  , AAA.OBJ_YN                 -- 대상여부
                  , AAA.SBM_YN                 -- 제출여부
                  , AAA.SBM_DT                 -- 제출일자
                  , AAA.CMPL_YN                -- 완료여부
                  , AAA.CMPL_DT                -- 완료일자
                  , CASE WHEN AAA.SITE_ATFL_SUM  >  0 THEN '1'
                         ELSE '0'
                     END AS ATCH_YN             -- 첨부여부                            
                  , CASE WHEN AAA.SBM_YN = '1' THEN AAA.ATFL_GRP
                         ELSE ''
                     END AS ATFL_GRP            -- 첨부파일그룹 
               FROM (
                     SELECT AA.WRT_DT                 -- 작성일자
                          , AA.SEQ                    -- 순번
                          , AA.SIT_CD                -- 현장코드
                          , AA.SIT_NM                -- 현장명
                          , AA.TERR_CD                -- 지역코드
                          , AA.OBJ_YN                 -- 대상여부
                          , AA.SBM_YN                 -- 제출여부
                          , AA.SBM_DT                 -- 제출일자
                          , AA.CMPL_YN                -- 완료여부
                          , AA.CMPL_DT                -- 완료일자
                          , CASE WHEN NVL(AA.ATFL_GRP, '') IS NULL  THEN '0'
                                 ELSE  '1'
                            END AS ATCH_YN            -- 첨부여부
                          , AA.ATFL_GRP               -- 첨부파일그룹
                          , (
                             SELECT NVL(SUM(BBB.SITE_ATFL_CNT), 0)
                               FROM (
                                     SELECT BB.SIT_CD
                                          , BB.ATFL_GRP
                                          , (
                                             SELECT COUNT(1) 
                                               FROM TCOZ_ATFL 
                                              WHERE ATFL_GRP = BB.ATFL_GRP     
                                            ) AS SITE_ATFL_CNT
                                       FROM TQHA_SITEDOC BB
                                      WHERE 1=1                                   
                                        AND BB.SIT_CD = AA.SIT_CD
                                        AND BB.WRT_DT = AA.WRT_DT                             
                                        AND BB.SEQ = AA.SEQ
                                        AND BB.ATFL_GRP IS NOT NULL 
                                    ) BBB               
                           ) AS SITE_ATFL_SUM                                               
                      FROM TQHA_SITEDOC AA
                    ) AAA
              WHERE AAA.WRT_DT = p_WRT_DT
                AND AAA.SEQ = p_SEQ
      ) AAAA
      ORDER BY AAAA.SIT_NM
        ;

    END IF;


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);
END ;
/

-- PQHA_HODCAB_S (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_HODCAB_S" 
                            (p_WRK_TP  VARCHAR2 :='U'                                     -- UPDATE FLAG( I: ISNERT, U:UPDATE, D:DELTE)
                            ,p_WRK_ID  VARCHAR2                                           -- 사용자 ID
                            ,p_WRK_IP  VARCHAR2                                           -- 사용자 IP
                            ,p_WRT_DT TQHA_HODCAB.WRT_DT%TYPE                             -- 작성일자
                            ,p_SEQ TQHA_HODCAB.SEQ%TYPE                                   -- 순번
                            ,p_TTL TQHA_HODCAB.TTL%TYPE                                   -- 제목
                            ,p_WRTR_EMPNO TQHA_HODCAB.WRTR_EMPNO%TYPE                     -- 작성자사번
                            ,p_WRTR_PNM TQHA_HODCAB.WRTR_PNM%TYPE                         -- 작성자성명
                            ,p_REQ_DT TQHA_HODCAB.REQ_DT%TYPE                             -- 요청일자
                            ,p_SNSB_YN TQHA_HODCAB.SNSB_YN%TYPE                           -- 가감점대상
                            ,p_CMPL_YN TQHA_HODCAB.CMPL_YN%TYPE                           -- 완료여부
                            ,p_CMPL_DT TQHA_HODCAB.CMPL_DT%TYPE                           -- 완료일자
                            ,p_ATFL_GRP TQHA_HODCAB.ATFL_GRP%TYPE                         -- 완료일자
                            )
IS
    /**************************************************************************************************************************
      Purpose : 

      REVISIONS
      Ver      Date               Author                  Description
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2019/05/03 10:39:10                         최초생성

    /**************************************************************************************************************************/


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR(200);             -- ERROR Message
    USER_EXCEPTION EXCEPTION;

    v_SEQ  TQHA_SITEDOC.SEQ%TYPE;
    v_OBJ_YN       VARCHAR(1);              -- 대상여부

    v_SBM_YN_CNT    NUMBER;              -- 제출여부
    v_ATFL_CNT      NUMBER;              -- 첨부파일유무

BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 필수입력 필드  Check  ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_WRT_DT IS NULL)  THEN
        ERR_MSG := '작성일자는 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_TTL IS NULL)  THEN
        ERR_MSG := '제목은 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_REQ_DT IS NULL)  THEN
        ERR_MSG := '제출기한은 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Process 선행조건 Check ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_WRK_TP ='D') THEN

        --1. 특정 문서함의 대상현장중 제출된 경우 확인
        SELECT COUNT(1)
          INTO v_SBM_YN_CNT
          FROM TQHA_SITEDOC
         WHERE 1=1
           AND WRT_DT = p_WRT_DT
           AND SEQ = p_SEQ
           AND SBM_YN = '1';

        IF (v_SBM_YN_CNT >  0)  THEN
            ERR_MSG := '작성일자 ' || p_WRT_DT || '의 순번 ' || p_SEQ || '은(는) '||CHR(13)||CHR(10) || '제출되었으므로 삭제할 수 없습니다.';
            RAISE USER_EXCEPTION;
        END IF;

        --2. 특정 문서함의 대상현장중 제출하지 않았지만 첨부파일이 있는 경우 확인
       SELECT COUNT(1)
         INTO v_ATFL_CNT
         FROM TQHA_SITEDOC AA
            , TCOZ_ATFL BB
        WHERE 1=1
          AND AA.ATFL_GRP = BB.ATFL_GRP(+)
          AND AA.WRT_DT = p_WRT_DT
          AND AA.SEQ = p_SEQ
          AND AA.ATFL_GRP IS NOT NULL;

        IF (v_ATFL_CNT >  0)  THEN
            ERR_MSG := '작성일자 ' || p_WRT_DT || '의 순번 ' || p_SEQ || '은(는) '||CHR(13)||CHR(10) || '첨부파일 작업중인 현장이 있으므로 삭제할 수 없습니다.';
            RAISE USER_EXCEPTION;
        END IF;
    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Business Process ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_WRK_TP ='D') THEN
        DELETE
          FROM TQHA_HODCAB
         WHERE WRT_DT = p_WRT_DT          --작성일자
           AND SEQ = p_SEQ;

        DELETE
          FROM TQHA_SITEDOC
         WHERE WRT_DT = p_WRT_DT           --작성일자
           AND SEQ = p_SEQ ;        

    ELSIF (p_WRK_TP ='U') THEN

        -- 본부
        UPDATE TQHA_HODCAB
           SET TTL                  = p_TTL                     --제목
              ,WRTR_EMPNO           = p_WRTR_EMPNO              --작성자사번
              ,WRTR_PNM             = p_WRTR_PNM                --작성자성명
              ,REQ_DT               = p_REQ_DT                  --요청일자
              ,SNSB_YN              = p_SNSB_YN                 --가감점대상
              ,CMPL_YN              = p_CMPL_YN                 --완료여부
              ,CMPL_DT              = p_CMPL_DT                 --완료일자
              ,UPD_ID               = p_WRK_ID                  --수정ID
              ,UPD_DTM              = SYSDATE()                 --수정일시
              ,UPD_IP               = p_WRK_IP                  --수정IP
         WHERE WRT_DT = p_WRT_DT                                --작성일자
           AND SEQ = p_SEQ;                                     --순번

        -- 현장
        UPDATE TQHA_SITEDOC
           SET CMPL_YN              = p_CMPL_YN                 --완료여부
              ,CMPL_DT              = p_CMPL_DT                 --완료일자
              ,UPD_ID               = p_WRK_ID                  --수정ID
              ,UPD_DTM              = SYSDATE()                 --수정일시
              ,UPD_IP               = p_WRK_IP                  --수정IP
         WHERE WRT_DT = p_WRT_DT                                --작성일자
           AND SEQ = p_SEQ;                                     --순번
           
    ELSIF (p_WRK_TP ='ATFL') THEN

        -- 본부
        UPDATE TQHA_HODCAB
           SET 
               ATFL_GRP             = p_ATFL_GRP                
              ,UPD_ID               = p_WRK_ID                  --수정ID
              ,UPD_DTM              = SYSDATE()                 --수정일시
              ,UPD_IP               = p_WRK_IP                  --수정IP
         WHERE WRT_DT = p_WRT_DT                                --작성일자
           AND SEQ = p_SEQ;                                     --순번

    ELSE

        SELECT NVL(MAX(SEQ), 0) + 1  INTO v_SEQ
              FROM TQHA_HODCAB
             WHERE 1=1
               AND WRT_DT = p_WRT_DT;

        INSERT INTO TQHA_HODCAB
                   ( WRT_DT                  --작성일자
                    ,SEQ                     --순번
                    ,TTL                     --제목
                    ,WRTR_EMPNO              --작성자사번
                    ,WRTR_PNM                --작성자성명
                    ,REQ_DT                  --요청일자
                    ,SNSB_YN                 --가감점대상
                    ,CMPL_YN                 --완료여부
                    ,CMPL_DT                 --완료일자
                    ,IPT_ID                  --신규입력ID
                    ,IPT_DTM                 --신규입력일시
                    ,IPT_IP                  --신규입력IP
                    ,UPD_ID                  --최종수정ID
                    ,UPD_DTM                 --최종수정일시
                    ,UPD_IP)                 --최종수정IP
             VALUES (p_WRT_DT                --작성일자
                    ,v_SEQ                   --순번
                    ,p_TTL                   --제목
                    ,p_WRTR_EMPNO            --작성자사번
                    ,p_WRTR_PNM              --작성자성명
                    ,p_REQ_DT                --요청일자
                    ,p_SNSB_YN               --가감점대상
                    ,p_CMPL_YN               --완료여부
                    ,p_CMPL_DT               --완료일자
                    ,p_WRK_ID                --입력ID
                    ,SYSDATE()               --입력일시
                    ,p_WRK_IP                --입력IP
                    ,p_WRK_ID                --수정ID
                    ,SYSDATE()               --수정일시
                    ,p_WRK_IP);              --수정IP

        --현장별 더미데이터 입력

        FOR RI IN (
                    SELECT SIT_CD
                         , FQHA_GETDEPTNM_BY_DEPTCD(SIT_CD) AS SIT_NM
                    FROM TQHA_SAFT_SIT
                    WHERE SIT_TERR != 'QSZ0599'
                  )
            LOOP

                INSERT INTO TQHA_SITEDOC (
                                WRT_DT
                              , SEQ
                              , SIT_CD
                              , SIT_NM
                              , TERR_CD
                              , OBJ_YN
                              , SBM_YN
                              , SBM_DT
                              , CMPL_YN
                              , CMPL_DT
                              , ATCH_YN
                              , ATFL_GRP
                              , IPT_ID
                              , IPT_DTM
                              , IPT_IP
                              , UPD_ID
                              , UPD_DTM
                              , UPD_IP
                            )
                       VALUES(
                                p_WRT_DT
                              , v_SEQ
                              , RI.SIT_CD
                              , RI.SIT_NM
                              , NULL        --TERR_CD
                              , NULL
                              , NULL        --SBM_YN
                              , NULL        --SBM_DT
                              , NULL        --CMPL_YN
                              , NULL        --CMPL_DT
                              , NULL        --ATCH_YN
                              , NULL        --ATFL_GRP
                              , p_WRK_ID
                              , SYSDATE()
                              , p_WRK_ID
                              , p_WRK_ID
                              , SYSDATE()
                              , p_WRK_IP
                              );

            END LOOP;

    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 5. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
         WHEN OTHERS THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);
END;
/

-- PQHA_IDAC_DSVC_B (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_IDAC_DSVC_B" (
    p_WRK_TP            IN VARCHAR2 DEFAULT 'U'         -- FLAG(Q: SELECT)
,   p_WRK_ID            IN VARCHAR2                     -- 사용자 ID
,   p_WRK_IP            IN VARCHAR2                     -- 사용자 IP
,   p_SIT_CD            IN VARCHAR2                     -- 현장코드
,   p_ACCD_SEQ          IN NUMBER                       -- 사고순번
)
IS 
    /**************************************************************************************************************************
      Purpose : 산재관리 > 대표재해자 적용  

      REVISIONS
      Ver      Date               Author                  Description
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2024/04/30 16:11:12                         최초생성

    /**************************************************************************************************************************/
 

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR2(200);            -- ERROR Message

    v_APRV_STATS       VARCHAR2(1);            -- 현재 결재상태 값
    v_cnt  INTEGER;                            -- 대표선택 여부
    USER_EXCEPTION EXCEPTION;

BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 필수입력 필드  Check  ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_SIT_CD IS NULL)  THEN
        ERR_MSG := '현장코드는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_ACCD_SEQ IS NULL)  THEN
        ERR_MSG := '사고순번는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Process 선행조건 Check ]
    ---------------------------------------------------------------------------------------------------------------------------
    -- 2024/05/02  결재 여부 체크
    -- 결재 상태 체크

    SELECT NVL(B.APRV_STATS,0)
      INTO v_APRV_STATS
      FROM TQHA_IDAC_APRV   A  -- 산재결재 여부
         , TQHA_APRV        B
     WHERE A.SIT_CD     =  p_SIT_CD         -- 변수 (현장코드)
       AND A.ACCD_SEQ   =  p_ACCD_SEQ       -- 변수 (사고순번)
       AND A.APRV_DIV   = '1'               -- 현장결재
       --20240920 현장코드 조인 누락 추가
       AND A.SIT_CD     = B.SIT_CD(+)
       AND A.APRV_NO    = B.APRV_NO(+)
    ;

    IF v_APRV_STATS = '2' OR v_APRV_STATS = '4' THEN
        ERR_MSG := '내부결재가 상신되어 진행중이거나 완료되어 작업을 할 수 없습니다.';
        RAISE USER_EXCEPTION;
    END IF;

    -- 대표 피해자 선택되었는지 체크
    SELECT count(*)
      INTO v_cnt
      FROM TQHA_IDAC_DSVC
     WHERE SIT_CD       =  p_SIT_CD         -- 변수 (현장코드)
       AND ACCD_SEQ     =  p_ACCD_SEQ       -- 변수 (사고순번)
       AND REPR_DSVC    = '1'               -- 대표피해자
    ;

    IF v_cnt = '0'  THEN
        ERR_MSG := '대표피해자가 선택되지 않았습니다. 대표피해자 선택 후 진행바랍니다.';
        RAISE USER_EXCEPTION;
    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Business Process ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_WRK_TP = 'U') THEN
        -- 2024/05/02  대표피해자 적용
        -- 대표피해자를 업데이트 처리

        UPDATE TQHA_IDAC A
           SET 
             ( DSVC                 -- 개인정보 암호화 (재해자명)
             --, DSVC_BRTH            -- 개인정보 암호화 (재해자 생년월일)
             , DSVC_ADDR            -- 개인정보 암호화 (재해자 주소)
             --,DSVC_VNDR           -- 개인정보 암호화 (재해자 업체 및 직종)
             , DSVC_HIRDT           -- 개인정보 암호화 (재해자 취업일)
             , DSVC_RSDNNO          -- 재해자 주민번호
             , DSVC_SEX             -- 재해자 성별
             , DSVC_NATL            -- 재해자 국적
             , DSVC_STYQLF          -- 재해자 체류자격
             , DSVC_JBCLS           -- 재해자 직종
             , DSVC_SKND            -- 재해자 동종근무경력
             , DSVC_EMP             -- 재해자 고용형태
             , DSVC_INSURER         -- 근재보험사
             , CUST_CD              -- 거래처코드
             , VNDR_SEQ             -- 업체순번
             , DEAD_CNT             -- 사망자수
             , INJ_CNT              -- 부상자수
             , DSS_CNT              -- 재해자수
             , OCO_YN               -- 재해자소속
             , UPD_ID               --수정ID
             , UPD_DTM              --수정일시
             , UPD_IP               --수정IP
             ) 
             =
             (SELECT B.DSVC                 --개인정보 암호화 (재해자명)
                   --, B.DSVC_BRTH            --개인정보 암호화 (재해자 생년월일)
                   , B.DSVC_ADDR            --개인정보 암호화 (재해자 주소)
                   --,B.DSVC_VNDR           --개인정보 암호화 (재해자 업체 및 직종)
                   , B.DSVC_HIRDT           --개인정보 암호화 (재해자 취업일)
                   , B.DSVC_RSDNNO          -- 재해자 주민번호
                   , B.DSVC_SEX             -- 재해자 성별
                   , B.DSVC_NATL            -- 재해자 국적
                   , B.DSVC_STYQLF          -- 재해자 체류자격
                   , B.DSVC_JBCLS           -- 재해자 직종
                   , B.DSVC_SKND            -- 재해자 동종근무경력
                   , B.DSVC_EMP             -- 재해자 고용형태
                   , B.DSVC_INSURER         -- 근재보험사
                   , B.CUST_CD              -- 거래처코드
                   , B.VNDR_SEQ             -- 업체순번
                   , C.DEAD_CNT             -- 사망자수
                   , C.INJ_CNT              -- 부상자수
                   , C.DSS_CNT              -- 재해자수
                   , B.OCO_YN               -- 재해자소속
                   , p_WRK_ID               --수정ID
                   , SYSDATE()              --수정일시
                   , p_WRK_IP               --수정IP
                FROM TQHA_IDAC_DSVC B
                   , (SELECT SIT_CD
                           , ACCD_SEQ
                           , SUM(DECODE(DSVC_DIV,'1', 1, 0)) AS DEAD_CNT    -- 사망
                           , SUM(DECODE(DSVC_DIV,'2', 1, 0)) AS INJ_CNT     -- 부상
                           , SUM(DECODE(DSVC_DIV,'3', 1, 0)) AS DSS_CNT     -- 질병
                        FROM TQHA_IDAC_DSVC
                       WHERE SIT_CD         = p_SIT_CD                -- 변수 (현장코드)
                         AND ACCD_SEQ       = p_ACCD_SEQ              -- 변수 (사고순번)
                       GROUP BY SIT_CD, ACCD_SEQ
                         ) C
                 WHERE B.SIT_CD         = p_SIT_CD          -- 변수 (현장코드)
                   AND B.ACCD_SEQ       = p_ACCD_SEQ        -- 변수 (사고순번)
                   AND B.REPR_DSVC      = '1'               -- 대표재해자
                   AND B.SIT_CD         = C.SIT_CD
                   AND B.ACCD_SEQ       = C.ACCD_SEQ
              )
         WHERE A.SIT_CD    =  p_SIT_CD                -- 변수 (현장코드)
           AND A.ACCD_SEQ  =  p_ACCD_SEQ              -- 변수 (사고순번)
        ;

    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 5. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);

END ;
/

-- PQHA_IDAC_DSVC_Q (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_IDAC_DSVC_Q" (
    p_WRK_TP            VARCHAR2 DEFAULT 'Q'                    -- FLAG( Q: SELECT )
,   p_SIT_CD            TQHA_IDAC_DSVC.SIT_CD       %TYPE       -- 현장코드
,   p_ACCD_SEQ          TQHA_IDAC_DSVC.ACCD_SEQ     %TYPE       -- 사고순번
,   RTN_CURSOR          OUT SYS_REFCURSOR
)
IS
    /**************************************************************************************************************************
      Purpose : 산재관리 > 재해자등록 조회 

      REVISIONS
      Ver      Date               Author                  Description
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2024/04/23 17:00:15                         최초생성

    /**************************************************************************************************************************/


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR2(200);            -- ERROR Message
    USER_EXCEPTION EXCEPTION;


BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 수행전 Check Logic ]
    ---------------------------------------------------------------------------------------------------------------------------


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Logic 처리
    ---------------------------------------------------------------------------------------------------------------------------

    OPEN RTN_CURSOR FOR
    SELECT A.SIT_CD         AS SIT_CD_OBJ       -- 현장코드
         , A.ACCD_SEQ       AS ACCD_SEQ_OBJ     -- 사고순번
         , A.DSVC_SEQ                           -- 재해자순번
         , A.DSVC_DIV                           -- 공통코드(QS054)
         , A.DSVC                               -- 개인정보 암호화
         , A.DSVC_BRTH                          -- 개인정보 암호화
         , A.DSVC_ADDR                          -- 개인정보 암호화
         , A.DSVC_VNDR                          -- 개인정보 암호화
         , A.DSVC_HIRDT                         -- 개인정보 암호화
         , A.DSVC_RSDNNO                        -- 주민등록번호
         , A.DSVC_SEX                           -- 재해자_성별
         , A.DSVC_NATL                          -- 재해자_국적
         , A.DSVC_STYQLF                        -- 재해자_체류자격
         , A.DSVC_JBCLS                         -- 재해자_직종
         , A.DSVC_SKND                          -- 재해자_동종근무경력
         , A.DSVC_EMP                           -- 재해자_고용형태
         , A.DSVC_INSURER                       -- 재해자_근재보험사
         , A.REPR_DSVC                          -- 대표재해자
         , A.RMKS                               -- 비고
         , A.IPT_ID                             -- 입력ID
         , A.IPT_DTM                            -- 입력일시
         , A.IPT_IP                             -- 입력IP
         , A.UPD_ID                             -- 수정ID
         , A.UPD_DTM                            -- 수정일시
         , A.UPD_IP                             -- 수정IP
         , A.CUST_CD                            -- 거래처코드
         , A.VNDR_SEQ                           -- 협력업체순번
         , B.CUST_NM                            -- 거래처명
         , A.OCO_YN                             -- 당사여부
      FROM TQHA_IDAC_DSVC   A
         , TCOA_TRADE       B
     WHERE A.CUST_CD    = B.CUST_CD(+)
       AND A.SIT_CD     = p_SIT_CD              -- 현장코드
       AND A.ACCD_SEQ   = p_ACCD_SEQ            -- 사고순번
    ;


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);
END ;
/

-- PQHA_IDAC_DSVC_S (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_IDAC_DSVC_S" (
    p_WRK_TP                VARCHAR2 :='U'                                      -- UPDATE FLAG( I: ISNERT, U:UPDATE, D:DELTE)
,   p_WRK_ID                VARCHAR2                                            -- 사용자 ID
,   p_WRK_IP                VARCHAR2                                            -- 사용자 IP
,   p_SIT_CD                TQHA_IDAC_DSVC.SIT_CD               %TYPE           -- 현장코드
,   p_ACCD_SEQ              TQHA_IDAC_DSVC.ACCD_SEQ             %TYPE           -- 사고순번
,   p_DSVC_SEQ              TQHA_IDAC_DSVC.DSVC_SEQ             %TYPE           -- 재해자순번
,   p_DSVC_DIV              TQHA_IDAC_DSVC.DSVC_DIV             %TYPE           -- 공통코드(QS054)
,   p_DSVC                  TQHA_IDAC_DSVC.DSVC                 %TYPE           -- 개인정보 암호화
,   p_DSVC_BRTH             TQHA_IDAC_DSVC.DSVC_BRTH            %TYPE           -- 개인정보 암호화
,   p_DSVC_ADDR             TQHA_IDAC_DSVC.DSVC_ADDR            %TYPE           -- 개인정보 암호화
,   p_DSVC_VNDR             TQHA_IDAC_DSVC.DSVC_VNDR            %TYPE           -- 개인정보 암호화
,   p_DSVC_HIRDT            TQHA_IDAC_DSVC.DSVC_HIRDT           %TYPE           -- 개인정보 암호화
,   p_DSVC_RSDNNO           TQHA_IDAC_DSVC.DSVC_RSDNNO          %TYPE           -- 남성 M 여성 W
,   p_DSVC_SEX              TQHA_IDAC_DSVC.DSVC_SEX             %TYPE           -- 재해자_성별
,   p_DSVC_NATL             TQHA_IDAC_DSVC.DSVC_NATL            %TYPE           -- 재해자_국적
,   p_DSVC_STYQLF           TQHA_IDAC_DSVC.DSVC_STYQLF          %TYPE           -- 재해자_체류자격
,   p_DSVC_JBCLS            TQHA_IDAC_DSVC.DSVC_JBCLS           %TYPE           -- 재해자_직종
,   p_DSVC_SKND             TQHA_IDAC_DSVC.DSVC_SKND            %TYPE           -- 재해자_동종근무경력
,   p_DSVC_EMP              TQHA_IDAC_DSVC.DSVC_EMP             %TYPE           -- 재해자_고용형태
,   p_DSVC_INSURER          TQHA_IDAC_DSVC.DSVC_INSURER         %TYPE           -- 재해자_근재보험사
,   p_REPR_DSVC             TQHA_IDAC_DSVC.REPR_DSVC            %TYPE           -- 대표재해자
,   p_RMKS                  TQHA_IDAC_DSVC.RMKS                 %TYPE           -- 비고
,   p_CUST_CD               TQHA_IDAC_DSVC.CUST_CD              %TYPE           -- 거래처코드
,   p_VNDR_SEQ              TQHA_IDAC_DSVC.VNDR_SEQ             %TYPE           -- 협력업체순번
,   p_OCO_YN                TQHA_IDAC_DSVC.OCO_YN               %TYPE           -- 당사여부
)
IS 
    /**************************************************************************************************************************
      Purpose : 산재관리 > 재해자등록 저장

      REVISIONS
      Ver      Date               Author                  Description
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2024/04/23 13:45:37                         최초생성
      1.1      2024/04/23 16:40:00    정우성                  재해자 순번 자동생성 추가

    /**************************************************************************************************************************/


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR2(200);            -- ERROR Message
    USER_EXCEPTION EXCEPTION;

    v_DSVC_SEQ      TQHA_IDAC_DSVC.DSVC_SEQ%TYPE ;          -- 재해자순번 변수 선언

BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 필수입력 필드  Check  ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_SIT_CD IS NULL)  THEN
        ERR_MSG := '현장코드는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_ACCD_SEQ IS NULL)  THEN
        ERR_MSG := '사고순번는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

--    IF (p_DSVC_SEQ IS NULL)  THEN
--        ERR_MSG := '재해자순번는(은) 필수 입력사항 입니다.';
--        RAISE USER_EXCEPTION;
--    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Process 선행조건 Check ]
    ---------------------------------------------------------------------------------------------------------------------------



    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Business Process ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_WRK_TP ='D') THEN

        DELETE
          FROM TQHA_IDAC_DSVC
         WHERE SIT_CD       = p_SIT_CD          -- 현장코드
           AND ACCD_SEQ     = p_ACCD_SEQ        -- 사고순번
           AND DSVC_SEQ     = p_DSVC_SEQ        -- 재해자순번
        ;

    ELSIF (p_WRK_TP ='U') THEN

        UPDATE TQHA_IDAC_DSVC
           SET DSVC_DIV         = p_DSVC_DIV        --공통코드(QS054)
             , DSVC             = p_DSVC            --개인정보 암호화
             , DSVC_BRTH        = p_DSVC_BRTH       --개인정보 암호화
             , DSVC_ADDR        = p_DSVC_ADDR       --개인정보 암호화
             , DSVC_VNDR        = p_DSVC_VNDR       --개인정보 암호화
             , DSVC_HIRDT       = p_DSVC_HIRDT      --개인정보 암호화
             , DSVC_RSDNNO      = p_DSVC_RSDNNO     --남성 M 여성 W
             , DSVC_SEX         = p_DSVC_SEX        --재해자_성별
             , DSVC_NATL        = p_DSVC_NATL       --재해자_국적
             , DSVC_STYQLF      = p_DSVC_STYQLF     --재해자_체류자격
             , DSVC_JBCLS       = p_DSVC_JBCLS      --재해자_직종
             , DSVC_SKND        = p_DSVC_SKND       --재해자_동종근무경력
             , DSVC_EMP         = p_DSVC_EMP        --재해자_고용형태
             , DSVC_INSURER     = p_DSVC_INSURER    --재해자_근재보험사
             , REPR_DSVC        = p_REPR_DSVC       --대표재해자
             , RMKS             = p_RMKS            --비고
             , CUST_CD          = p_CUST_CD         --거래처코드
             , VNDR_SEQ         = p_VNDR_SEQ        --협력업체순번
             , OCO_YN           = p_OCO_YN          --당사여부
             , UPD_ID           = p_WRK_ID          --수정ID
             , UPD_DTM          = SYSDATE()         --수정일시
             , UPD_IP           = p_WRK_IP          --수정IP
         WHERE SIT_CD           = p_SIT_CD          --현장코드
           AND ACCD_SEQ         = p_ACCD_SEQ        --사고순번
           AND DSVC_SEQ         = p_DSVC_SEQ        --재해자순번
        ;

    ELSE

        -- 재해자순번 생성
        SELECT NVL( (MAX(DSVC_SEQ)+1),'1' )
          INTO v_DSVC_SEQ
          FROM TQHA_IDAC_DSVC
         WHERE SIT_CD       = p_SIT_CD          -- 현장코드
           AND ACCD_SEQ     = p_ACCD_SEQ        -- 사고순번
        ;

        INSERT 
          INTO TQHA_IDAC_DSVC
             ( SIT_CD               -- 현장코드
             , ACCD_SEQ             -- 사고순번
             , DSVC_SEQ             -- 재해자순번
             , DSVC_DIV             -- 공통코드(QS054)
             , DSVC                 -- 개인정보 암호화
             , DSVC_BRTH            -- 개인정보 암호화
             , DSVC_ADDR            -- 개인정보 암호화
             , DSVC_VNDR            -- 개인정보 암호화
             , DSVC_HIRDT           -- 개인정보 암호화
             , DSVC_RSDNNO          -- 남성 M 여성 W
             , DSVC_SEX             -- 재해자_성별
             , DSVC_NATL            -- 재해자_국적
             , DSVC_STYQLF          -- 재해자_체류자격
             , DSVC_JBCLS           -- 재해자_직종
             , DSVC_SKND            -- 재해자_동종근무경력
             , DSVC_EMP             -- 재해자_고용형태
             , DSVC_INSURER         -- 재해자_근재보험사
             , REPR_DSVC            -- 대표재해자
             , RMKS                 -- 비고
             , CUST_CD              -- 거래처코드
             , VNDR_SEQ             -- 협력업체순번
             , OCO_YN               -- 당사여부
             , IPT_ID               -- 입력ID
             , IPT_DTM              -- 입력일시
             , IPT_IP               -- 입력IP
             , UPD_ID               -- 수정ID
             , UPD_DTM              -- 수정일시
             , UPD_IP               -- 수정IP
             )
        VALUES 
             ( p_SIT_CD             -- 현장코드
             , p_ACCD_SEQ           -- 사고순번
             , v_DSVC_SEQ           -- 재해자순번
             , p_DSVC_DIV           -- 공통코드(QS054)
             , p_DSVC               -- 개인정보 암호화
             , p_DSVC_BRTH          -- 개인정보 암호화
             , p_DSVC_ADDR          -- 개인정보 암호화
             , p_DSVC_VNDR          -- 개인정보 암호화
             , p_DSVC_HIRDT         -- 개인정보 암호화
             , p_DSVC_RSDNNO        -- 남성 M 여성 W
             , p_DSVC_SEX           -- 재해자_성별
             , p_DSVC_NATL          -- 재해자_국적
             , p_DSVC_STYQLF        -- 재해자_체류자격
             , p_DSVC_JBCLS         -- 재해자_직종
             , p_DSVC_SKND          -- 재해자_동종근무경력
             , p_DSVC_EMP           -- 재해자_고용형태
             , p_DSVC_INSURER       -- 재해자_근재보험사
             , p_REPR_DSVC          -- 대표재해자
             , p_RMKS               -- 비고
             , p_CUST_CD            -- 거래처코드
             , p_VNDR_SEQ           -- 협력업체순번
             , p_OCO_YN             -- 당사여부
             , p_WRK_ID             -- 입력ID
             , SYSDATE()            -- 입력일시
             , p_WRK_IP             -- 입력IP
             , p_WRK_ID             -- 수정ID
             , SYSDATE()            -- 수정일시
             , p_WRK_IP             -- 수정IP
             )
        ;

    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 5. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);

END PQHA_IDAC_DSVC_S;
/

-- PQHA_IDAC_MAIN_APRV_W (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_IDAC_MAIN_APRV_W" (
    p_WRK_TP            VARCHAR2 :='U'                              -- UPDATE FLAG
,   p_WRK_ID            VARCHAR2                                    -- 사용자 ID
,   p_WRK_IP            VARCHAR2                                    -- 사용자 IP
,   p_SIT_CD            TQHA_IDAC_APRV.SIT_CD       %TYPE           -- 현장코드
,   p_ACCD_SEQ          TQHA_IDAC_APRV.ACCD_SEQ     %TYPE           -- 순번
,   p_APRV_NO           TQHA_IDAC_APRV.APRV_NO      %TYPE           -- 결재번호
)
IS
    /**************************************************************************************************************************
      Purpose : 산재등록(현장) (APRV) : 승인, (CNC) : 승인취소

      REVISIONS
      Ver      Date               Author                  Description
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2024/05/16 10:30:13                         최초생성

    /**************************************************************************************************************************/

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR2(200);            -- ERROR Message
    USER_EXCEPTION EXCEPTION;

    v_APRV_NO      TQHA_IDAC_APRV.APRV_NO%TYPE;             -- 결제번호

BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 필수입력 필드  Check  ]
    ---------------------------------------------------------------------------------------------------------------------------

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Process 선행조건 Check ]
    ---------------------------------------------------------------------------------------------------------------------------

    SELECT NVL(MAX(TO_NUMBER(APRV_NO)),0)+ 1
      INTO v_APRV_NO
      FROM TQHA_APRV
     WHERE SIT_CD = p_SIT_CD
    ;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Business Process ]
    ---------------------------------------------------------------------------------------------------------------------------


    ---------------------------------------------------------------------------------------------------------------------------
    -- 승인
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_WRK_TP ='APRV') THEN

        -- TQHA_APRV 테이블에 결제정보 INSERT
        INSERT 
          INTO TQHA_APRV
             ( SIT_CD           -- 현장코드
             , APRV_NO          -- 결재번호
             , APRV_STATS       -- 결재상태(QS031) 4:결재완료
             )
        VALUES 
             ( p_SIT_CD         -- 현장코드
             ,v_APRV_NO         -- 결재번호
             ,'4'               -- 결재상태(QS031)
             )
        ;

        -- TQHA_IDAC_APRV 테이블에 결제정보 UPDATE (현장)
        UPDATE TQHA_IDAC_APRV
           SET APRV_NO      = v_APRV_NO         -- 결재번호
              ,UPD_ID       = p_WRK_ID          -- 수정ID
              ,UPD_DTM      = SYSDATE()         -- 수정일시
              ,UPD_IP       = p_WRK_IP          -- 수정IP
         WHERE SIT_CD       = p_SIT_CD          -- 현장코드
           AND ACCD_SEQ     = p_ACCD_SEQ        -- 사고순번
           AND APRV_DIV     = '1'               -- 현장
        ;

    ---------------------------------------------------------------------------------------------------------------------------
    -- 승인취소
    ---------------------------------------------------------------------------------------------------------------------------
    ELSIF (p_WRK_TP ='CNC') THEN

        -- TQHA_APRV 삭제
        DELETE
          FROM TQHA_APRV
         WHERE SIT_CD   = p_SIT_CD          -- 현장코드
           AND APRV_NO  = p_APRV_NO         -- 결재번호
        ;

        -- TQHA_IDAC_APRV 결재번호 삭제
        UPDATE TQHA_IDAC_APRV
           SET APRV_NO      = NULL              --결재번호
             , UPD_ID       = p_WRK_ID          --수정ID
             , UPD_DTM      = SYSDATE()         --수정일시
             , UPD_IP       = p_WRK_IP          --수정IP
         WHERE SIT_CD       = p_SIT_CD          --현장코드
           AND ACCD_SEQ     = p_ACCD_SEQ        --사고순번
           AND APRV_DIV     = '1'               --현장
        ;

    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 5. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);

END PQHA_IDAC_MAIN_APRV_W;
/

-- PQHA_IDAC_Q (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_IDAC_Q" (
    p_WRK_TP                VARCHAR2 DEFAULT 'Q'                -- FLAG( Q: SELECT )
,   p_SIT_CD                TQHA_IDAC.SIT_CD        %TYPE       -- 현장코드
,   p_ACCD_SEQ              TQHA_IDAC.ACCD_SEQ      %TYPE       -- 사고순번
,   p_SEARCH_ACCD_YM_FR     TQHA_IDAC.ACCD_DT       %TYPE       -- 사고시작일자
,   p_SEARCH_ACCD_YM        TQHA_IDAC.ACCD_DT       %TYPE       -- 사고종료일자 
,   RTN_CURSOR              OUT SYS_REFCURSOR
)
IS
    /**************************************************************************************************************************
      Purpose : QSE > 안전관리 > 안전서류관리 > 산재관리(현장/본사) 조회 

      REVISIONS
      Ver      Date               Author                  Description
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2023/11/28 10:51:46                         최초생성
      1.1       2024/03/22 16:00:00 정우성                      새로 생성된 칼럼들 추가
      1.2       2024/03/25 16:00:00 정우성                      칼럼을 재해발생유형으로 변경
      1.3     2024/04/03 13:00:00 정우성                      사망/부상자수 칼럼 추가

    Q1 : 산재목록(현장)
    Q2 : 산재작성(현장)
    Q3 : 산재목록(본사)
    Q4 : 산재작성(본사)
    **************************************************************************************************************************/

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR2(200);            -- ERROR Message
    USER_EXCEPTION EXCEPTION;

BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 수행전 Check Logic ]
    ---------------------------------------------------------------------------------------------------------------------------


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Logic 처리
    ---------------------------------------------------------------------------------------------------------------------------
    -- get_IndustAcciSiteLstList >> 산재목록(현장)
    IF (p_WRK_TP = 'Q1') THEN

       -- 현장 목록
        OPEN RTN_CURSOR FOR
        SELECT  A.SIT_CD                 --현장코드
	           ,A.ACCD_SEQ                 --사고순번
	           ,A.ACCD_DT                 --사고일자
	           ,A.ACCD_TIME                 --사고시간
	           ,TO_CHAR(TO_DATE(A.ACCD_DT||A.ACCD_TIME, 'YYYYMMDDHH24MI'), 'YYYY-MM-DD HH24:MI')  AS ACCD_DTM
	           ,A.DSVC                 --성명
	           ,A.DSVC_ADDR                 --주소_개인정보 암호화
	           ,A.DSVC_VNDR                 --소속회사
	           ,A.DSVC_HIRDT                 --입사일자
	           ,A.DSVC_RSDNNO                 --재해자_주민번호(개인정보 암호화)
	           ,A.DSVC_MP                 --재해자_휴대폰
	           ,A.DSVC_SEX                 --재해자_성별 ( 1 남성, 0 여성)
	           ,A.DSVC_NATL                 --재해자_국적
	           ,A.DSVC_STYQLF                 --재해자_체류자격
	           ,A.DSVC_JBCLS                 --재해자_직종
	           ,A.DSVC_SKND                 --재해자_동종근무경력
	           ,A.DSVC_EMP                 --재해자_고용형태
	           ,A.DSVC_119                 --119신고여부
	           ,A.DSVC_DAYOFF                 --휴일예상일수
	           ,A.IDAC_TP                 --산재유형(공통코드)  -> 재해발생유형으로 변경 ( 미사용);
	           ,A.ACCD_CONTX                 --대쉬보드의 발생내용으로 사용
	           ,A.INJR_XTNT                 --상해정도
	           ,A.ACCD_CSE                 --사고원인
	           ,A.ACCD_CPLN                 --사고대책
	           ,A.SITE_OMGR                 --현장소장
	           ,A.RT_SITE                 --과실비율 현장소장
	           ,A.CNST_TMGR                 --공사팀장
	           ,A.RT_CONT                 --과실비율 공사팀장
	           ,A.CNST_PSN                 --공사담당자
	           ,A.RT_PSN                 --과실비율 공사담당자
	           ,A.SAFT_MGR                 --안전관리자
	           ,A.RT_SAFE                 --과실비율 안전관리자
	           ,( SELECT USR_NM FROM TCOZ_USR_INFO WHERE USR_ID = A.SITE_OMGR ) AS SITE_OMGR_NM     -- 현장소장명
	           ,( SELECT USR_NM FROM TCOZ_USR_INFO WHERE USR_ID = A.CNST_TMGR ) AS CNST_TMGR_NM     -- 공사팀장명
	           ,( SELECT USR_NM FROM TCOZ_USR_INFO WHERE USR_ID = A.CNST_PSN )  AS CNST_PSN_NM      -- 공사담당자명
	           ,( SELECT USR_NM FROM TCOZ_USR_INFO WHERE USR_ID = A.SAFT_MGR )  AS SAFT_MGR_NM      -- 안전관리자명
	           ,A.CUST_CD                 --거래처코드
	           ,A.VNDR_SEQ                 --업체순번
	           ,A.RT_VNDR                 --과실비율 협력업체
	           ,A.TOP7_DISS                 --TOP7재해(미사용)
	           ,A.SERI_DISS                 --중대재해(미사용)
	           ,A.MAIN_CHK                 --주관사여부
	           ,A.BE_CAUSED                 --기인물
	           ,A.INJR_KIND                 --상해종류(질병명)
	           ,A.INJR_PART                 --상해부위(질병부위)
	           ,A.ACCD_WHO                 --누가
	           ,A.ACCD_WHERE                 --어디서
	           ,A.ACCD_WHAT                 --무엇을
	           ,A.ACCD_HOW                 --어떻게
	           ,A.ACCD_WHY                 --왜
	           ,A.DISS_DIV                 --재해구분,공통코드(QS050)
	           ,A.RMKS                 --비고
	           ,A.DSVC_INSURER                 --근재보험사
	           ,A.DSS_CNT                 --재해자수
	           ,A.DEAD_CNT                 --사망자수
	           ,A.INJ_CNT                 --부상자수
	           ,A.OCO_YN                 --당사여부
	           ,A.DIS_CD                 --발생형태코드
	           ,A.PHOTO_GRP1                 --첨부파일그룹사진1
	           ,A.PHOTO_DESC_1                 --사진설명1
	           ,A.PHOTO_GRP2                 --첨부파일그룹사진2
	           ,A.PHOTO_DESC_2                 --사진설명2
	           ,A.PHOTO_GRP3                 --첨부파일그룹사진3
	           ,A.PHOTO_DESC_3                 --사진설명3
	           ,A.PHOTO_GRP4                 --첨부파일그룹사진4
	           ,A.PHOTO_DESC_4                 --사진설명4
	           ,A.ATFL_GRP                 --첨부파일그룹
	           ,A.ATFL_GRP2                 --첨부파일그룹
--	           ,A.BZ_HQ                 --사업본부
	           ,FQHA_GET_TELNO(A.SITE_TEL_NO) AS SITE_TEL_NO --현장전화번호
	           ,A.EMP_CNT                 --근로자수
	           ,A.PROCRT                 --공정율
	           ,A.TOT_CNST_AMT                 --총공사금액
	           ,A.WTS_NM1                 --목격자1
	           ,A.WTS_NM2                 --목격자2
	           ,A.WTS_NM3                 --목격자3
	           ,A.SAFT_EDU_CMPL_DT                 --안전교육 이수일자
	           ,A.OCC_DIS_CNT                 --직업병수
	           ,A.IDRT_TECH                 --간접적원인_기술
	           ,A.IDRT_EDU                 --간접적원인_교육
	           ,A.IDRT_WRK                 --간접적원인_작업관리
	           ,A.DRT_UNSF_STATS                 --직접적원인_불안전상태(물적)
	           ,A.DRT_UNSF_ACT                 --직접적원인_불안전행동(인적)
	           ,A.DFT_DOC                 --기인물
	           ,A.RPT_DT                 --보고일자
	           ,A.ACP_DT                 --접수일자
	           ,A.MA_MATT                 --조치사항
	           ,A.MED_ORG                 --의료기관명
	           ,FQHA_GET_TELNO(A.MED_CADDR) AS MED_CADDR --의료기관 연락처
	           ,A.ETC_MATT                 --기타사항
	           ,A.DISS_TYPE
	           ,A.DSVC_AGE
	           ,A.DISS_DIV_ETC
	           ,A.APRV_NO                 --현장 결재번호
	           ,A.APRV_NO_GW                 --본사 결재번호
             , C.APRS_DIV           -- 산재명
             , D.DIS_NM             -- 세부산재명
             , NVL(F.CUST_NM, A.DSVC_VNDR)      AS CUST_NM          -- 거래처명
             , ''                   			AS OCO_NM           --당사명
             , TO_CHAR(A.IPT_DTM, 'YYYYMMDD')   AS IPT_DTM
             , E.APRV_STATS         -- 현장결재 결재상태
             , G.CD_NM                          AS APRV_STATS_NM    -- 현장결재 결재상태명             
          FROM TQHA_IDAC            A
             , TQHA_DISASTER_DIV    C
             , TQHA_DISASTER_CD     D
             , TQHA_APRV            E
             , TCOA_TRADE           F
             , TCOA_COMCODE         G
         WHERE 1=1
           AND A.SIT_CD         = p_SIT_CD
           AND A.ACCD_DT        BETWEEN NVL(p_SEARCH_ACCD_YM_FR,'19000101') AND p_SEARCH_ACCD_YM
           AND C.DIV_CD         = D.DIV_CD
           AND D.DIS_CD         = A.DIS_CD
           AND A.SIT_CD         = E.SIT_CD(+)
           AND A.APRV_NO        = E.APRV_NO (+)
           AND A.CUST_CD        = F.CUST_CD(+)
           AND E.APRV_STATS     = G.COM_CD(+)
           AND G.HRNK_CD(+)     = 'QS031'
         ORDER BY A.ACCD_DT DESC
        ;

    -- 본사 목록
    ELSIF (p_WRK_TP = 'Q2') THEN

        OPEN RTN_CURSOR FOR
        SELECT A.SIT_CD             -- 현장코드
             ,( SELECT CNST_NM FROM VQSZ_SITEINFO WHERE SIT_CD = A.SIT_CD )    AS SIT_NM       -- 현장명칭
             , A.ACCD_SEQ           -- 사고순번
             , A.ACCD_DT            -- 사고일자
             , A.ACCD_TIME          -- 사고시간
             , A.DSVC               -- 재해자명 (개인정보 암호화)
             , A.DSVC_ADDR          -- 재해자 주소 (개인정보 암호화)
             , A.DSVC_VNDR          -- 재해자 업체 및 직종 (개인정보 암호화)
             , A.DSVC_HIRDT         -- 재해자 취업일 (개인정보 암호화)
             , A.ACCD_CONTX         -- 사고경위
             , A.DIS_CD             -- 산재유형
             , C.APRS_DIV           -- 산재명
             , D.DIS_NM             -- 세부산재명
             , CASE A.MAIN_CHK WHEN '0'  THEN '비주관사' WHEN '1'  THEN '주관사' ELSE '선택되지않음' END AS MAIN_CHK        -- 주관사여부 (1:주관사, 0:비주관사)
             , A.MA_MATT            -- 조치사항
             , A.ACCD_CSE           -- 사고원인
             , A.ACCD_CPLN          -- 사고대책
             , A.PHOTO_GRP1         -- 사진첨부1
             , A.PHOTO_DESC_1       -- 사진설명1
             , A.PHOTO_GRP2         -- 사진첨부2
             , A.PHOTO_DESC_2       -- 사진설명2
             , A.ATFL_GRP           -- 첨부파일그룹
             , A.ATFL_GRP2          --첨부파일그룹
             , A.APRV_NO            -- 결재번호
             , A.CUST_CD            -- 거래처번호
             , A.VNDR_SEQ           -- 업체순번
             , A.OCO_YN             -- 재해자구분
             , A.DISS_TYPE
             , A.DSVC_AGE
             , A.DISS_DIV_ETC
             , NVL(F.CUST_NM, A.DSVC_VNDR)      AS CUST_NM          -- 거래처명
             , ''                   			AS OCO_NM           --당사명
             , TO_CHAR(A.IPT_DTM, 'YYYYMMDD')   AS IPT_DTM
             , E.APRV_STATS         -- 현장결재 결재상태
             , G.CD_NM                          AS APRV_STATS_NM    -- 현장결재 결재상태명
            ,( 
	            SELECT CD_NM
				FROM TCOA_COMCODE
				WHERE HRNK_CD = 'CO91'
				AND COM_CD = (SELECT APRV_STATS FROM TCOF_APPROVE WHERE APRV_NO = A.APRV_NO_GW)
			) AS APRV_STATS_GW 
          FROM TQHA_IDAC            A
             , TQHA_DISASTER_DIV    C
             , TQHA_DISASTER_CD     D
             , TQHA_APRV            E
             , TCOA_TRADE           F
             , TCOA_COMCODE         G
         WHERE 1=1
           AND A.SIT_CD         LIKE '%'||p_SIT_CD
           AND A.ACCD_DT        BETWEEN NVL(p_SEARCH_ACCD_YM_FR,'19000101') AND p_SEARCH_ACCD_YM
           AND C.DIV_CD         = D.DIV_CD
           AND D.DIS_CD         = A.DIS_CD
           AND A.SIT_CD         = E.SIT_CD(+)
           AND A.APRV_NO        = E.APRV_NO (+)
           AND A.CUST_CD        = F.CUST_CD(+)
           AND E.APRV_STATS     = G.COM_CD(+)
           AND G.HRNK_CD(+)     = 'QS031'
           --AND E.APRV_STATS = '4'
         ORDER BY A.ACCD_DT DESC
        ;        
        
    -- 상세
    ELSIF (p_WRK_TP = 'Q3') THEN

        OPEN RTN_CURSOR FOR
        SELECT  A.SIT_CD                 --현장코드
	           ,A.ACCD_SEQ                 --사고순번
	           ,A.ACCD_DT                 --사고일자
	           ,A.ACCD_TIME                 --사고시간
	           ,A.DSVC                 --성명
	           ,A.DSVC_ADDR                 --주소_개인정보 암호화
	           ,A.DSVC_VNDR                 --소속회사
	           ,A.DSVC_HIRDT                 --입사일자
	           ,A.DSVC_RSDNNO                 --재해자_주민번호(개인정보 암호화)
	           ,A.DSVC_MP                 --재해자_휴대폰
	           ,A.DSVC_SEX                 --재해자_성별 ( 1 남성, 0 여성)
	           ,A.DSVC_NATL                 --재해자_국적
	           ,A.DSVC_STYQLF                 --재해자_체류자격
	           ,A.DSVC_JBCLS                 --재해자_직종
	           ,A.DSVC_SKND                 --재해자_동종근무경력
	           ,A.DSVC_EMP                 --재해자_고용형태
	           ,A.DSVC_119                 --119신고여부
	           ,A.DSVC_DAYOFF                 --휴일예상일수
	           ,A.IDAC_TP                 --산재유형(공통코드)  -> 재해발생유형으로 변경 ( 미사용);
	           ,A.ACCD_CONTX                 --대쉬보드의 발생내용으로 사용
	           ,A.INJR_XTNT                 --상해정도
	           ,A.ACCD_CSE                 --사고원인
	           ,A.ACCD_CPLN                 --사고대책
	           ,A.SITE_OMGR                 --현장소장
	           ,A.RT_SITE                 --과실비율 현장소장
	           ,A.CNST_TMGR                 --공사팀장
	           ,A.RT_CONT                 --과실비율 공사팀장
	           ,A.CNST_PSN                 --공사담당자
	           ,A.RT_PSN                 --과실비율 공사담당자
	           ,A.SAFT_MGR                 --안전관리자
	           ,A.RT_SAFE                 --과실비율 안전관리자
	           ,( SELECT USR_NM FROM TCOZ_USR_INFO WHERE USR_ID = A.SITE_OMGR ) AS SITE_OMGR_NM     -- 현장소장명
	           ,( SELECT USR_NM FROM TCOZ_USR_INFO WHERE USR_ID = A.CNST_TMGR ) AS CNST_TMGR_NM     -- 공사팀장명
	           ,( SELECT USR_NM FROM TCOZ_USR_INFO WHERE USR_ID = A.CNST_PSN )  AS CNST_PSN_NM      -- 공사담당자명
	           ,( SELECT USR_NM FROM TCOZ_USR_INFO WHERE USR_ID = A.SAFT_MGR )  AS SAFT_MGR_NM      -- 안전관리자명
	           ,A.CUST_CD                 --거래처코드
	           ,A.VNDR_SEQ                 --업체순번
	           ,A.RT_VNDR                 --과실비율 협력업체
	           ,A.TOP7_DISS                 --TOP7재해(미사용)
	           ,A.SERI_DISS                 --중대재해(미사용)
	           ,DECODE(A.SERI_DISS,'1','중대','일반') AS SERI_DISS_NM
	           ,A.MAIN_CHK                 --주관사여부
	           ,A.BE_CAUSED                 --기인물
	           ,A.INJR_KIND                 --상해종류(질병명)
	           ,A.INJR_PART                 --상해부위(질병부위)
	           ,A.ACCD_WHO                 --누가
	           ,A.ACCD_WHERE                 --어디서
	           ,A.ACCD_WHAT                 --무엇을
	           ,A.ACCD_HOW                 --어떻게
	           ,A.ACCD_WHY                 --왜
	           ,A.DISS_DIV                 --재해구분,공통코드(QS050)
	           ,(SELECT CD_NM FROM TCOA_COMCODE WHERE HRNK_CD = 'QS050' AND COM_CD = A.DISS_DIV) AS DISS_DIV_NM
	           ,A.RMKS                 --비고
	           ,A.DSVC_INSURER                 --근재보험사
	           ,A.DSS_CNT                 --재해자수
	           ,A.DEAD_CNT                 --사망자수
	           ,A.INJ_CNT                 --부상자수
	           ,A.OCO_YN                 --당사여부
	           ,A.DIS_CD                 --발생형태코드	           
	           ,A.DIS_DESC
	           ,D.APRS_DIV              -- 산재명
               ,E.DIS_NM                -- 세부산재명
	           ,A.PHOTO_GRP1                 --첨부파일그룹사진1
	           ,A.PHOTO_DESC_1                 --사진설명1
	           ,A.PHOTO_GRP2                 --첨부파일그룹사진2
	           ,A.PHOTO_DESC_2                 --사진설명2
	           ,A.PHOTO_GRP3                 --첨부파일그룹사진3
	           ,A.PHOTO_DESC_3                 --사진설명3
	           ,A.PHOTO_GRP4                 --첨부파일그룹사진4
	           ,A.PHOTO_DESC_4                 --사진설명4
	           ,A.ATFL_GRP                 --첨부파일그룹
	           ,A.ATFL_GRP2          --첨부파일그룹
	           ,FQHA_GET_TELNO(A.SITE_TEL_NO) AS SITE_TEL_NO --현장전화번호
	           ,A.EMP_CNT                 --근로자수
	           ,A.PROCRT                 --공정율
	           ,A.TOT_CNST_AMT                 --총공사금액
	           ,A.WTS_NM1                 --목격자1
	           ,A.WTS_NM2                 --목격자2
	           ,A.WTS_NM3                 --목격자3
	           ,A.SAFT_EDU_CMPL_DT                 --안전교육 이수일자
	           ,A.OCC_DIS_CNT                 --직업병수
	           ,A.IDRT_TECH                 --간접적원인_기술
	           ,A.IDRT_EDU                 --간접적원인_교육
	           ,A.IDRT_WRK                 --간접적원인_작업관리
	           ,A.DRT_UNSF_STATS                 --직접적원인_불안전상태(물적)
	           ,A.DRT_UNSF_ACT                 --직접적원인_불안전행동(인적)
	           ,A.DFT_DOC                 --기인물
	           ,A.RPT_DT                 --보고일자
	           ,A.ACP_DT                 --접수일자
	           ,A.MA_MATT                 --조치사항
	           ,A.MED_ORG                 --의료기관명
	           ,FQHA_GET_TELNO(A.MED_CADDR) AS MED_CADDR --의료기관 연락처
	           ,A.ETC_MATT                 --기타사항
	           ,A.DISS_TYPE
	           ,(SELECT CD_NM FROM TCOA_COMCODE WHERE HRNK_CD = 'QS070' AND COM_CD = A.DISS_TYPE) AS DISS_TYPE_NM
	           ,A.DSVC_AGE
	           ,A.DISS_DIV_ETC
	           ,A.APRV_NO                 --현장 결재번호
	           ,A.APRV_NO_GW              --본사 결재번호
	           ,B.APRV_STATS             -- 현장결재 결재상태
	           ,( SELECT CNST_NM FROM VQSZ_SITEINFO WHERE SIT_CD = A.SIT_CD )    AS SIT_NM       -- 현장명칭
               , NVL(C.CUST_NM, A.DSVC_VNDR)                                     AS CUST_NM      -- 소속회사명
               , C.CUST_NM                                                       AS VNDR_NM      -- 협력업체
               ,TO_CHAR(A.IPT_DTM, 'YYYYMMDD') AS IPT_DTM
               ,CASE WHEN A.BZ_HQ IS NOT NULL THEN A.BZ_HQ
                ELSE (
	             	SELECT DEPT_NM AS TOP_DEPT_NM
					FROM THRZ_DEPT
					WHERE CONNECT_BY_ISLEAF = 1
					START WITH DEPT_CD = p_SIT_CD
					CONNECT BY PRIOR HRNK_DEPT_CD = DEPT_CD
		  	      )
		  	    END  AS BZ_HQ --사업본부
		  	   , (SELECT APRV_STATS FROM TCOF_APPROVE WHERE APRV_NO = A.APRV_NO_GW) AS APRV_STATS_GW
          FROM TQHA_IDAC    A
             , TQHA_APRV    B
             , TCOA_TRADE   C
             , TQHA_DISASTER_DIV   D
             , TQHA_DISASTER_CD    E
         WHERE A.SIT_CD         = B.SIT_CD (+)
           AND A.APRV_NO        = B.APRV_NO (+)
           AND A.CUST_CD        = C.CUST_CD(+)
           AND D.DIV_CD         = E.DIV_CD(+)
           AND E.DIS_CD         = A.DIS_CD(+)
           AND A.SIT_CD         = p_SIT_CD
           AND A.ACCD_SEQ       = p_ACCD_SEQ
           ;
        
    -- 본사결재용상세
    ELSIF (p_WRK_TP = 'Q4') THEN

        OPEN RTN_CURSOR FOR
        SELECT  A.SIT_CD                   --현장코드
	           ,A.ACCD_SEQ                 --사고순번
	           ,A.APRV_NO_GW AS APRV_NO    --본사 결재번호
		  	   ,F.APRV_NO_GW AS APRV_NO_GW
		  	   ,F.APRV_STATS AS APRV_STATS
          FROM TQHA_IDAC    A
             , TCOF_APPROVE F
         WHERE A.APRV_NO_GW     = F.APRV_NO(+)
           AND A.SIT_CD         = p_SIT_CD
           AND A.ACCD_SEQ       = p_ACCD_SEQ
           ;

    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);
            
END ;
/

-- PQHA_IDAC_S (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_IDAC_S" 
                            (p_WRK_TP  VARCHAR2 :='U'                                     -- UPDATE FLAG( I: ISNERT, U:UPDATE, D:DELTE)
                            ,p_WRK_ID  VARCHAR2                                           -- 사용자 ID 
                            ,p_WRK_IP  VARCHAR2                                           -- 사용자 IP 
                            ,p_SIT_CD TQHA_IDAC.SIT_CD%TYPE                               -- 현장코드
                            ,p_ACCD_SEQ TQHA_IDAC.ACCD_SEQ%TYPE                           -- 사고순번
                            ,p_ACCD_DT TQHA_IDAC.ACCD_DT%TYPE                             -- 사고일자
                            ,p_ACCD_TIME TQHA_IDAC.ACCD_TIME%TYPE                         -- 사고시간
                            ,p_DSVC TQHA_IDAC.DSVC%TYPE                                   -- 성명
                            ,p_DSVC_ADDR TQHA_IDAC.DSVC_ADDR%TYPE                         -- 주소_개인정보 암호화
                            ,p_DSVC_VNDR TQHA_IDAC.DSVC_VNDR%TYPE                         -- 소속회사
                            ,p_DSVC_HIRDT TQHA_IDAC.DSVC_HIRDT%TYPE                       -- 입사일자
                            ,p_DSVC_RSDNNO TQHA_IDAC.DSVC_RSDNNO%TYPE                     -- 재해자_주민번호(개인정보 암호화)
                            ,p_DSVC_MP TQHA_IDAC.DSVC_MP%TYPE                             -- 재해자_휴대폰
                            ,p_DSVC_SEX TQHA_IDAC.DSVC_SEX%TYPE                           -- 재해자_성별 ( 1 남성, 0 여성)
                            ,p_DSVC_NATL TQHA_IDAC.DSVC_NATL%TYPE                         -- 재해자_국적
                            ,p_DSVC_STYQLF TQHA_IDAC.DSVC_STYQLF%TYPE                     -- 재해자_체류자격
                            ,p_DSVC_JBCLS TQHA_IDAC.DSVC_JBCLS%TYPE                       -- 재해자_직종
                            ,p_DSVC_SKND TQHA_IDAC.DSVC_SKND%TYPE                         -- 재해자_동종근무경력
                            ,p_DSVC_EMP TQHA_IDAC.DSVC_EMP%TYPE                           -- 재해자_고용형태
                            ,p_DSVC_119 TQHA_IDAC.DSVC_119%TYPE                           -- 119신고여부
                            ,p_DSVC_DAYOFF TQHA_IDAC.DSVC_DAYOFF%TYPE                     -- 휴일예상일수
                            ,p_IDAC_TP TQHA_IDAC.IDAC_TP%TYPE                             -- 산재유형(공통코드)  -> 재해발생유형으로 변경 ( 미사용);
                            ,p_ACCD_CONTX TQHA_IDAC.ACCD_CONTX%TYPE                       -- 대쉬보드의 발생내용으로 사용
                            ,p_INJR_XTNT TQHA_IDAC.INJR_XTNT%TYPE                         -- 상해정도
                            ,p_ACCD_CSE TQHA_IDAC.ACCD_CSE%TYPE                           -- 사고원인
                            ,p_ACCD_CPLN TQHA_IDAC.ACCD_CPLN%TYPE                         -- 사고대책
                            ,p_SITE_OMGR TQHA_IDAC.SITE_OMGR%TYPE                         -- 현장소장
                            ,p_RT_SITE TQHA_IDAC.RT_SITE%TYPE                             -- 과실비율 현장소장
                            ,p_CNST_TMGR TQHA_IDAC.CNST_TMGR%TYPE                         -- 공사팀장
                            ,p_RT_CONT TQHA_IDAC.RT_CONT%TYPE                             -- 과실비율 공사팀장
                            ,p_CNST_PSN TQHA_IDAC.CNST_PSN%TYPE                           -- 공사담당자
                            ,p_RT_PSN TQHA_IDAC.RT_PSN%TYPE                               -- 과실비율 공사담당자
                            ,p_SAFT_MGR TQHA_IDAC.SAFT_MGR%TYPE                           -- 안전관리자
                            ,p_RT_SAFE TQHA_IDAC.RT_SAFE%TYPE                             -- 과실비율 안전관리자
                            ,p_CUST_CD TQHA_IDAC.CUST_CD%TYPE                             -- 거래처코드
                            ,p_VNDR_SEQ TQHA_IDAC.VNDR_SEQ%TYPE                           -- 업체순번
                            ,p_RT_VNDR TQHA_IDAC.RT_VNDR%TYPE                             -- 과실비율 협력업체
                            ,p_TOP7_DISS TQHA_IDAC.TOP7_DISS%TYPE                         -- TOP7재해(미사용)
                            ,p_SERI_DISS TQHA_IDAC.SERI_DISS%TYPE                         -- 중대재해(미사용)
                            ,p_MAIN_CHK TQHA_IDAC.MAIN_CHK%TYPE                           -- 주관사여부
                            ,p_BE_CAUSED TQHA_IDAC.BE_CAUSED%TYPE                         -- 기인물
                            ,p_INJR_KIND TQHA_IDAC.INJR_KIND%TYPE                         -- 상해종류(질병명)
                            ,p_INJR_PART TQHA_IDAC.INJR_PART%TYPE                         -- 상해부위(질병부위)
                            ,p_ACCD_WHO TQHA_IDAC.ACCD_WHO%TYPE                           -- 누가
                            ,p_ACCD_WHERE TQHA_IDAC.ACCD_WHERE%TYPE                       -- 어디서
                            ,p_ACCD_WHAT TQHA_IDAC.ACCD_WHAT%TYPE                         -- 무엇을
                            ,p_ACCD_HOW TQHA_IDAC.ACCD_HOW%TYPE                           -- 어떻게
                            ,p_ACCD_WHY TQHA_IDAC.ACCD_WHY%TYPE                           -- 왜
                            ,p_DISS_DIV TQHA_IDAC.DISS_DIV%TYPE                           -- 재해구분,공통코드(QS050)
                            ,p_RMKS TQHA_IDAC.RMKS%TYPE                                   -- 비고
                            ,p_DSVC_INSURER TQHA_IDAC.DSVC_INSURER%TYPE                   -- 근재보험사
                            ,p_DSS_CNT TQHA_IDAC.DSS_CNT%TYPE                             -- 재해자수
                            ,p_DEAD_CNT TQHA_IDAC.DEAD_CNT%TYPE                           -- 사망자수
                            ,p_INJ_CNT TQHA_IDAC.INJ_CNT%TYPE                             -- 부상자수
                            ,p_OCO_YN TQHA_IDAC.OCO_YN%TYPE                               -- 당사여부
                            ,p_DIS_CD TQHA_IDAC.DIS_CD%TYPE                               -- 발생형태코드
                            ,p_DIS_DESC TQHA_IDAC.DIS_DESC%TYPE                           -- 발생형태내용
                            ,p_PHOTO_GRP1 TQHA_IDAC.PHOTO_GRP1%TYPE                       -- 첨부파일그룹사진1
                            ,p_PHOTO_DESC_1 TQHA_IDAC.PHOTO_DESC_1%TYPE                   -- 사진설명1
                            ,p_PHOTO_GRP2 TQHA_IDAC.PHOTO_GRP2%TYPE                       -- 첨부파일그룹사진2
                            ,p_PHOTO_DESC_2 TQHA_IDAC.PHOTO_DESC_2%TYPE                   -- 사진설명2
                            ,p_PHOTO_GRP3 TQHA_IDAC.PHOTO_GRP3%TYPE                       -- 첨부파일그룹사진3
                            ,p_PHOTO_DESC_3 TQHA_IDAC.PHOTO_DESC_3%TYPE                   -- 사진설명3
                            ,p_PHOTO_GRP4 TQHA_IDAC.PHOTO_GRP4%TYPE                       -- 첨부파일그룹사진4
                            ,p_PHOTO_DESC_4 TQHA_IDAC.PHOTO_DESC_4%TYPE                   -- 사진설명4
                            ,p_ATFL_GRP TQHA_IDAC.ATFL_GRP%TYPE                           -- 첨부파일그룹
                            ,p_ATFL_GRP2 TQHA_IDAC.ATFL_GRP%TYPE                           -- 첨부파일그룹
                            ,p_BZ_HQ TQHA_IDAC.BZ_HQ%TYPE                                 -- 사업본부
                            ,p_SITE_TEL_NO TQHA_IDAC.SITE_TEL_NO%TYPE                     -- 현장전화번호
                            ,p_EMP_CNT TQHA_IDAC.EMP_CNT%TYPE                             -- 근로자수
                            ,p_PROCRT TQHA_IDAC.PROCRT%TYPE                               -- 공정율
                            ,p_TOT_CNST_AMT TQHA_IDAC.TOT_CNST_AMT%TYPE                   -- 총공사금액
                            ,p_WTS_NM1 TQHA_IDAC.WTS_NM1%TYPE                             -- 목격자1
                            ,p_WTS_NM2 TQHA_IDAC.WTS_NM2%TYPE                             -- 목격자2
                            ,p_WTS_NM3 TQHA_IDAC.WTS_NM3%TYPE                             -- 목격자3
                            ,p_SAFT_EDU_CMPL_DT TQHA_IDAC.SAFT_EDU_CMPL_DT%TYPE           -- 안전교육 이수일자
                            ,p_OCC_DIS_CNT TQHA_IDAC.OCC_DIS_CNT%TYPE                     -- 직업병수
                            ,p_IDRT_TECH TQHA_IDAC.IDRT_TECH%TYPE                         -- 간접적원인_기술
                            ,p_IDRT_EDU TQHA_IDAC.IDRT_EDU%TYPE                           -- 간접적원인_교육
                            ,p_IDRT_WRK TQHA_IDAC.IDRT_WRK%TYPE                           -- 간접적원인_작업관리
                            ,p_DRT_UNSF_STATS TQHA_IDAC.DRT_UNSF_STATS%TYPE               -- 직접적원인_불안전상태(물적)
                            ,p_DRT_UNSF_ACT TQHA_IDAC.DRT_UNSF_ACT%TYPE                   -- 직접적원인_불안전행동(인적)
                            ,p_DFT_DOC TQHA_IDAC.DFT_DOC%TYPE                             -- 기인물
                            ,p_RPT_DT TQHA_IDAC.RPT_DT%TYPE                               -- 보고일자
                            ,p_ACP_DT TQHA_IDAC.ACP_DT%TYPE                               -- 접수일자
                            ,p_MA_MATT TQHA_IDAC.MA_MATT%TYPE                             -- 조치사항
                            ,p_MED_ORG TQHA_IDAC.MED_ORG%TYPE                             -- 의료기관명
                            ,p_MED_CADDR TQHA_IDAC.MED_CADDR%TYPE                         -- 의료기관 연락처
                            ,p_ETC_MATT TQHA_IDAC.ETC_MATT%TYPE                           -- 기타사항
                            ,p_DISS_TYPE TQHA_IDAC.DISS_TYPE%TYPE                         -- 사고형태
                            ,p_DSVC_AGE TQHA_IDAC.DSVC_AGE%TYPE                           -- 재해자_나이
                            ,p_DISS_DIV_ETC TQHA_IDAC.DISS_DIV_ETC%TYPE                   -- 재해구분_기타
                            ,p_APRV_NO TQHA_IDAC.APRV_NO%TYPE                             -- 현장 결재번호
                            ,p_APRV_NO_GW TQHA_IDAC.APRV_NO_GW%TYPE                       -- 본사 결재번호
                            ,p_RTN_ACCD_SEQ  OUT VARCHAR2                                -- 리턴변수(사고순번)
                            )
IS 
    /**************************************************************************************************************************
      Purpose : 

      REVISIONS
      Ver      Date               Author                  Description 
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2026/06/19 16:23:02                         최초생성

    /**************************************************************************************************************************/


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR2(200);            -- ERROR Message
    USER_EXCEPTION EXCEPTION;

	v_ACCD_SEQ      INTEGER;            -- 사고순번 MAX
    v_CNT_APRV      INTEGER := 0;
    V_CNT           INTEGER;            -- 하위 테이블 코드 존재 여부
    
BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 필수입력 필드  Check  ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_SIT_CD IS NULL)  THEN
        ERR_MSG := '현장코드는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_ACCD_SEQ IS NULL AND p_WRK_TP <> 'I')  THEN
        ERR_MSG := '사고순번는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Process 선행조건 Check ]
    ---------------------------------------------------------------------------------------------------------------------------
    /*   
    IF (p_WRK_TP <> 'I') THEN

        IF (p_APRV_DIV = '1') THEN
            -- 내부결재 상태확인
            SELECT B.APRV_STATS
              INTO v_CNT_APRV
              FROM (SELECT T1.SIT_CD
                         , T1.ACCD_SEQ
                         , T2.APRV_NO
                      FROM TQHA_IDAC T1
                         , TQHA_IDAC_APRV T2
                     WHERE T1.SIT_CD        = T2.SIT_CD (+)
                       AND T1.ACCD_SEQ      = T2.ACCD_SEQ (+)
                       AND T2.APRV_DIV      = '1'
                       AND T1.SIT_CD        = p_SIT_CD
                       AND T1.ACCD_SEQ      = p_ACCD_SEQ
                   ) A
                 , TQHA_APRV B
             WHERE A.SIT_CD = B.SIT_CD (+)
               AND A.APRV_NO = B.APRV_NO (+)
               AND A.SIT_CD = p_SIT_CD
               AND A.ACCD_SEQ = p_ACCD_SEQ
            ;

            IF v_CNT_APRV = '2' OR v_CNT_APRV = '4' THEN
                ERR_MSG := '내부결재가 상신되어 진행중이거나 완료되어 수정할 수 없습니다.';
                RAISE USER_EXCEPTION;
            END IF;

        ELSIF (p_APRV_DIV = '2') THEN

            -- 전자결재 상태확인
            SELECT NVL(MAX(1),0) INTO v_CNT_APRV
              FROM DUAL
             WHERE EXISTS (SELECT 1 
                             FROM TQHA_IDAC_APRV    A
                                , TCOF_APPROVE      B 
                            WHERE A.SIT_CD          = p_SIT_CD         --현장코드
                              AND A.ACCD_SEQ        = p_ACCD_SEQ       --사고순번
                              AND A.APRV_DIV        = '2'              --본사결재
                              AND A.APRV_NO         = B.APRV_NO(+) 
                              AND B.APRV_STATS      IN ('1030','3010')  -- 진행중, 완료     0919 결재상태값 변경
                          )
            ;

            IF v_CNT_APRV > 0   THEN
                ERR_MSG := '전자결재가 상신되어 진행중이거나 완료되어 수정할 수 없습니다.';
                RAISE USER_EXCEPTION;
            END IF;

        END IF;

     END IF;
*/
    
	--  산재 재해자 존재 여부 확인
    IF p_WRK_TP = 'D' THEN

        SELECT nvl(COUNT(SIT_CD),0) 
          INTO V_CNT
          FROM TQHA_IDAC_DSVC 
         WHERE SIT_CD   = p_SIT_CD
           AND ACCD_SEQ = p_ACCD_SEQ 
        ;

        IF V_CNT > 0 THEN
            ERR_MSG := '산재 재해자 데이터가 존재합니다. 산재 재해자 데이터를 전부 삭제해야 삭제할 수 있습니다. ';
            RAISE USER_EXCEPTION;
        END IF;
    END IF; 


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Business Process ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_WRK_TP ='D') THEN
        DELETE 
          FROM TQHA_IDAC
         WHERE SIT_CD = p_SIT_CD          --현장코드
           AND ACCD_SEQ = p_ACCD_SEQ;       --사고순번
           
          v_ACCD_SEQ := p_ACCD_SEQ;
    
    ELSIF (p_WRK_TP ='U') THEN
        UPDATE TQHA_IDAC
           SET ACCD_DT              = p_ACCD_DT                 --사고일자
              ,ACCD_TIME            = p_ACCD_TIME               --사고시간
              ,DSVC                 = p_DSVC                    --성명
              ,DSVC_ADDR            = p_DSVC_ADDR               --주소_개인정보 암호화
              ,DSVC_VNDR            = p_DSVC_VNDR               --소속회사
              ,DSVC_HIRDT           = p_DSVC_HIRDT              --입사일자
              ,DSVC_RSDNNO          = p_DSVC_RSDNNO             --재해자_주민번호(개인정보 암호화)
              ,DSVC_MP              = p_DSVC_MP                 --재해자_휴대폰
              ,DSVC_SEX             = p_DSVC_SEX                --재해자_성별 ( 1 남성, 0 여성)
              ,DSVC_NATL            = p_DSVC_NATL               --재해자_국적
              ,DSVC_STYQLF          = p_DSVC_STYQLF             --재해자_체류자격
              ,DSVC_JBCLS           = p_DSVC_JBCLS              --재해자_직종
              ,DSVC_SKND            = p_DSVC_SKND               --재해자_동종근무경력
              ,DSVC_EMP             = p_DSVC_EMP                --재해자_고용형태
              ,DSVC_119             = p_DSVC_119                --119신고여부
              ,DSVC_DAYOFF          = p_DSVC_DAYOFF             --휴일예상일수
              ,IDAC_TP              = p_IDAC_TP                 --산재유형(공통코드)  -> 재해발생유형으로 변경 ( 미사용);
              ,ACCD_CONTX           = p_ACCD_CONTX              --대쉬보드의 발생내용으로 사용
              ,INJR_XTNT            = p_INJR_XTNT               --상해정도
              ,ACCD_CSE             = p_ACCD_CSE                --사고원인
              ,ACCD_CPLN            = p_ACCD_CPLN               --사고대책
              ,SITE_OMGR            = p_SITE_OMGR               --현장소장
              ,RT_SITE              = p_RT_SITE                 --과실비율 현장소장
              ,CNST_TMGR            = p_CNST_TMGR               --공사팀장
              ,RT_CONT              = p_RT_CONT                 --과실비율 공사팀장
              ,CNST_PSN             = p_CNST_PSN                --공사담당자
              ,RT_PSN               = p_RT_PSN                  --과실비율 공사담당자
              ,SAFT_MGR             = p_SAFT_MGR                --안전관리자
              ,RT_SAFE              = p_RT_SAFE                 --과실비율 안전관리자
              ,CUST_CD              = p_CUST_CD                 --거래처코드
              ,VNDR_SEQ             = p_VNDR_SEQ                --업체순번
              ,RT_VNDR              = p_RT_VNDR                 --과실비율 협력업체
              ,TOP7_DISS            = p_TOP7_DISS               --TOP7재해(미사용)
              ,SERI_DISS            = p_SERI_DISS               --중대재해(미사용)
              ,MAIN_CHK             = p_MAIN_CHK                --주관사여부
              ,BE_CAUSED            = p_BE_CAUSED               --기인물
              ,INJR_KIND            = p_INJR_KIND               --상해종류(질병명)
              ,INJR_PART            = p_INJR_PART               --상해부위(질병부위)
              ,ACCD_WHO             = p_ACCD_WHO                --누가
              ,ACCD_WHERE           = p_ACCD_WHERE              --어디서
              ,ACCD_WHAT            = p_ACCD_WHAT               --무엇을
              ,ACCD_HOW             = p_ACCD_HOW                --어떻게
              ,ACCD_WHY             = p_ACCD_WHY                --왜
              ,DISS_DIV             = p_DISS_DIV                --재해구분,공통코드(QS050)
              ,RMKS                 = p_RMKS                    --비고
              ,DSVC_INSURER         = p_DSVC_INSURER            --근재보험사
              ,DSS_CNT              = NVL(p_DEAD_CNT,0)+NVL(p_INJ_CNT,0)+NVL(p_OCC_DIS_CNT,0)                 --재해자수
              ,DEAD_CNT             = p_DEAD_CNT                --사망자수
              ,INJ_CNT              = p_INJ_CNT                 --부상자수
              ,OCO_YN               = p_OCO_YN                  --당사여부
              ,DIS_CD               = p_DIS_CD                  --발생형태코드
              ,DIS_DESC             = p_DIS_DESC                  --발생형태코드
              ,PHOTO_GRP1           = p_PHOTO_GRP1              --첨부파일그룹사진1
              ,PHOTO_DESC_1         = p_PHOTO_DESC_1            --사진설명1
              ,PHOTO_GRP2           = p_PHOTO_GRP2              --첨부파일그룹사진2
              ,PHOTO_DESC_2         = p_PHOTO_DESC_2            --사진설명2
              ,PHOTO_GRP3           = p_PHOTO_GRP3              --첨부파일그룹사진3
              ,PHOTO_DESC_3         = p_PHOTO_DESC_3            --사진설명3
              ,PHOTO_GRP4           = p_PHOTO_GRP4              --첨부파일그룹사진4
              ,PHOTO_DESC_4         = p_PHOTO_DESC_4            --사진설명4
              ,ATFL_GRP             = p_ATFL_GRP                --첨부파일그룹
              ,BZ_HQ                = p_BZ_HQ                   --사업본부
              ,SITE_TEL_NO          = REPLACE(p_SITE_TEL_NO,'-','')  --현장전화번호
              ,EMP_CNT              = p_EMP_CNT                 --근로자수
              ,PROCRT               = p_PROCRT                  --공정율
              ,TOT_CNST_AMT         = p_TOT_CNST_AMT            --총공사금액
              ,WTS_NM1              = p_WTS_NM1                 --목격자1
              ,WTS_NM2              = p_WTS_NM2                 --목격자2
              ,WTS_NM3              = p_WTS_NM3                 --목격자3
              ,SAFT_EDU_CMPL_DT     = p_SAFT_EDU_CMPL_DT        --안전교육 이수일자
              ,OCC_DIS_CNT          = p_OCC_DIS_CNT             --직업병수
              ,IDRT_TECH            = p_IDRT_TECH               --간접적원인_기술
              ,IDRT_EDU             = p_IDRT_EDU                --간접적원인_교육
              ,IDRT_WRK             = p_IDRT_WRK                --간접적원인_작업관리
              ,DRT_UNSF_STATS       = p_DRT_UNSF_STATS          --직접적원인_불안전상태(물적)
              ,DRT_UNSF_ACT         = p_DRT_UNSF_ACT            --직접적원인_불안전행동(인적)
              ,DFT_DOC              = p_DFT_DOC                 --기인물
              ,RPT_DT               = p_RPT_DT                  --보고일자
              ,ACP_DT               = p_ACP_DT                  --접수일자
              ,MA_MATT              = p_MA_MATT                 --조치사항
              ,MED_ORG              = p_MED_ORG                 --의료기관명
              ,MED_CADDR            = REPLACE(p_MED_CADDR,'-','') --의료기관 연락처
              ,ETC_MATT             = p_ETC_MATT                --기타사항
              ,DISS_TYPE            = p_DISS_TYPE
              ,DSVC_AGE             = p_DSVC_AGE
              ,DISS_DIV_ETC         = p_DISS_DIV_ETC
              ,UPD_ID               = p_WRK_ID                  --수정ID 
              ,UPD_DTM              = SYSDATE()                 --수정일시
              ,UPD_IP               = p_WRK_IP                  --수정IP
         WHERE SIT_CD = p_SIT_CD          --현장코드
           AND ACCD_SEQ = p_ACCD_SEQ;       --사고순번
           
           v_ACCD_SEQ := p_ACCD_SEQ;
    
    ELSIF (p_WRK_TP ='I') THEN
    
    	-- 사고순번 생성
        SELECT NVL(MAX(ACCD_SEQ), 0)+1
          INTO v_ACCD_SEQ
          FROM TQHA_IDAC
         WHERE SIT_CD = p_SIT_CD         --현장코드
        ;
    	
        INSERT INTO TQHA_IDAC
                   ( SIT_CD                  --현장코드
                    ,ACCD_SEQ                --사고순번
                    ,ACCD_DT                 --사고일자
                    ,ACCD_TIME               --사고시간
                    ,DSVC                    --성명
                    ,DSVC_ADDR               --주소_개인정보 암호화
                    ,DSVC_VNDR               --소속회사
                    ,DSVC_HIRDT              --입사일자
                    ,DSVC_RSDNNO             --재해자_주민번호(개인정보 암호화)
                    ,DSVC_MP                 --재해자_휴대폰
                    ,DSVC_SEX                --재해자_성별 ( 1 남성, 0 여성)
                    ,DSVC_NATL               --재해자_국적
                    ,DSVC_STYQLF             --재해자_체류자격
                    ,DSVC_JBCLS              --재해자_직종
                    ,DSVC_SKND               --재해자_동종근무경력
                    ,DSVC_EMP                --재해자_고용형태
                    ,DSVC_119                --119신고여부
                    ,DSVC_DAYOFF             --휴일예상일수
                    ,IDAC_TP                 --산재유형(공통코드)  -> 재해발생유형으로 변경 ( 미사용);
                    ,ACCD_CONTX              --대쉬보드의 발생내용으로 사용
                    ,INJR_XTNT               --상해정도
                    ,ACCD_CSE                --사고원인
                    ,ACCD_CPLN               --사고대책
                    ,SITE_OMGR               --현장소장
                    ,RT_SITE                 --과실비율 현장소장
                    ,CNST_TMGR               --공사팀장
                    ,RT_CONT                 --과실비율 공사팀장
                    ,CNST_PSN                --공사담당자
                    ,RT_PSN                  --과실비율 공사담당자
                    ,SAFT_MGR                --안전관리자
                    ,RT_SAFE                 --과실비율 안전관리자
                    ,CUST_CD                 --거래처코드
                    ,VNDR_SEQ                --업체순번
                    ,RT_VNDR                 --과실비율 협력업체
                    ,TOP7_DISS               --TOP7재해(미사용)
                    ,SERI_DISS               --중대재해(미사용)
                    ,MAIN_CHK                --주관사여부
                    ,BE_CAUSED               --기인물
                    ,INJR_KIND               --상해종류(질병명)
                    ,INJR_PART               --상해부위(질병부위)
                    ,ACCD_WHO                --누가
                    ,ACCD_WHERE              --어디서
                    ,ACCD_WHAT               --무엇을
                    ,ACCD_HOW                --어떻게
                    ,ACCD_WHY                --왜
                    ,DISS_DIV                --재해구분,공통코드(QS050)
                    ,RMKS                    --비고
                    ,DSVC_INSURER            --근재보험사
                    ,DSS_CNT                 --재해자수
                    ,DEAD_CNT                --사망자수
                    ,INJ_CNT                 --부상자수
                    ,OCO_YN                  --당사여부
                    ,DIS_CD                  --발생형태코드
                    ,DIS_DESC
                    ,PHOTO_GRP1              --첨부파일그룹사진1
                    ,PHOTO_DESC_1            --사진설명1
                    ,PHOTO_GRP2              --첨부파일그룹사진2
                    ,PHOTO_DESC_2            --사진설명2
                    ,PHOTO_GRP3              --첨부파일그룹사진3
                    ,PHOTO_DESC_3            --사진설명3
                    ,PHOTO_GRP4              --첨부파일그룹사진4
                    ,PHOTO_DESC_4            --사진설명4
                    ,ATFL_GRP                --첨부파일그룹
                    ,BZ_HQ                   --사업본부
                    ,SITE_TEL_NO             --현장전화번호
                    ,EMP_CNT                 --근로자수
                    ,PROCRT                  --공정율
                    ,TOT_CNST_AMT            --총공사금액
                    ,WTS_NM1                 --목격자1
                    ,WTS_NM2                 --목격자2
                    ,WTS_NM3                 --목격자3
                    ,SAFT_EDU_CMPL_DT        --안전교육 이수일자
                    ,OCC_DIS_CNT             --직업병수
                    ,IDRT_TECH               --간접적원인_기술
                    ,IDRT_EDU                --간접적원인_교육
                    ,IDRT_WRK                --간접적원인_작업관리
                    ,DRT_UNSF_STATS          --직접적원인_불안전상태(물적)
                    ,DRT_UNSF_ACT            --직접적원인_불안전행동(인적)
                    ,DFT_DOC                 --기인물
                    ,RPT_DT                  --보고일자
                    ,ACP_DT                  --접수일자
                    ,MA_MATT                 --조치사항
                    ,MED_ORG                 --의료기관명
                    ,MED_CADDR               --의료기관 연락처
                    ,ETC_MATT                --기타사항
                    ,DISS_TYPE
                    ,DSVC_AGE
                    ,DISS_DIV_ETC
                    ,APRV_NO                 --현장 결재번호
                    ,APRV_NO_GW              --본사 결재번호
                    ,IPT_ID                  --입력ID
                    ,IPT_DTM                 --입력일시
                    ,IPT_IP                  --입력IP
                    ,UPD_ID                  --수정ID
                    ,UPD_DTM                 --수정일시
                    ,UPD_IP                  --수정IP
                    )
             VALUES (p_SIT_CD                --현장코드
                    ,v_ACCD_SEQ              --사고순번
                    ,p_ACCD_DT               --사고일자
                    ,p_ACCD_TIME             --사고시간
                    ,p_DSVC                  --성명
                    ,p_DSVC_ADDR             --주소_개인정보 암호화
                    ,p_DSVC_VNDR             --소속회사
                    ,p_DSVC_HIRDT            --입사일자
                    ,p_DSVC_RSDNNO           --재해자_주민번호(개인정보 암호화)
                    ,p_DSVC_MP               --재해자_휴대폰
                    ,p_DSVC_SEX              --재해자_성별 ( 1 남성, 0 여성)
                    ,p_DSVC_NATL             --재해자_국적
                    ,p_DSVC_STYQLF           --재해자_체류자격
                    ,p_DSVC_JBCLS            --재해자_직종
                    ,p_DSVC_SKND             --재해자_동종근무경력
                    ,p_DSVC_EMP              --재해자_고용형태
                    ,p_DSVC_119              --119신고여부
                    ,p_DSVC_DAYOFF           --휴일예상일수
                    ,p_IDAC_TP               --산재유형(공통코드)  -> 재해발생유형으로 변경 ( 미사용);
                    ,p_ACCD_CONTX            --대쉬보드의 발생내용으로 사용
                    ,p_INJR_XTNT             --상해정도
                    ,p_ACCD_CSE              --사고원인
                    ,p_ACCD_CPLN             --사고대책
                    ,p_SITE_OMGR             --현장소장
                    ,p_RT_SITE               --과실비율 현장소장
                    ,p_CNST_TMGR             --공사팀장
                    ,p_RT_CONT               --과실비율 공사팀장
                    ,p_CNST_PSN              --공사담당자
                    ,p_RT_PSN                --과실비율 공사담당자
                    ,p_SAFT_MGR              --안전관리자
                    ,p_RT_SAFE               --과실비율 안전관리자
                    ,p_CUST_CD               --거래처코드
                    ,p_VNDR_SEQ              --업체순번
                    ,p_RT_VNDR               --과실비율 협력업체
                    ,p_TOP7_DISS             --TOP7재해(미사용)
                    ,p_SERI_DISS             --중대재해(미사용)
                    ,p_MAIN_CHK              --주관사여부
                    ,p_BE_CAUSED             --기인물
                    ,p_INJR_KIND             --상해종류(질병명)
                    ,p_INJR_PART             --상해부위(질병부위)
                    ,p_ACCD_WHO              --누가
                    ,p_ACCD_WHERE            --어디서
                    ,p_ACCD_WHAT             --무엇을
                    ,p_ACCD_HOW              --어떻게
                    ,p_ACCD_WHY              --왜
                    ,p_DISS_DIV              --재해구분,공통코드(QS050)
                    ,p_RMKS                  --비고
                    ,p_DSVC_INSURER          --근재보험사
                    ,NVL(p_DEAD_CNT,0)+NVL(p_INJ_CNT,0)+NVL(p_OCC_DIS_CNT,0)               --재해자수
                    ,p_DEAD_CNT              --사망자수
                    ,p_INJ_CNT               --부상자수
                    ,p_OCO_YN                --당사여부
                    ,p_DIS_CD                --발생형태코드
                    ,p_DIS_DESC
                    ,p_PHOTO_GRP1            --첨부파일그룹사진1
                    ,p_PHOTO_DESC_1          --사진설명1
                    ,p_PHOTO_GRP2            --첨부파일그룹사진2
                    ,p_PHOTO_DESC_2          --사진설명2
                    ,p_PHOTO_GRP3            --첨부파일그룹사진3
                    ,p_PHOTO_DESC_3          --사진설명3
                    ,p_PHOTO_GRP4            --첨부파일그룹사진4
                    ,p_PHOTO_DESC_4          --사진설명4
                    ,p_ATFL_GRP              --첨부파일그룹
                    ,p_BZ_HQ                 --사업본부
                    ,REPLACE(p_SITE_TEL_NO,'-','')           --현장전화번호
                    ,p_EMP_CNT               --근로자수
                    ,p_PROCRT                --공정율
                    ,p_TOT_CNST_AMT          --총공사금액
                    ,p_WTS_NM1               --목격자1
                    ,p_WTS_NM2               --목격자2
                    ,p_WTS_NM3               --목격자3
                    ,p_SAFT_EDU_CMPL_DT      --안전교육 이수일자
                    ,p_OCC_DIS_CNT           --직업병수
                    ,p_IDRT_TECH             --간접적원인_기술
                    ,p_IDRT_EDU              --간접적원인_교육
                    ,p_IDRT_WRK              --간접적원인_작업관리
                    ,p_DRT_UNSF_STATS        --직접적원인_불안전상태(물적)
                    ,p_DRT_UNSF_ACT          --직접적원인_불안전행동(인적)
                    ,p_DFT_DOC               --기인물
                    ,p_RPT_DT                --보고일자
                    ,p_ACP_DT                --접수일자
                    ,p_MA_MATT               --조치사항
                    ,p_MED_ORG               --의료기관명
                    ,REPLACE(p_MED_CADDR,'-','')  --의료기관 연락처
                    ,p_ETC_MATT              --기타사항
                    ,p_DISS_TYPE
                    ,p_DSVC_AGE
                    ,p_DISS_DIV_ETC
                    ,p_APRV_NO               --현장 결재번호
                    ,p_APRV_NO_GW            --본사 결재번호
                    ,p_WRK_ID                --입력ID 
                    ,SYSDATE()               --입력일시
                    ,p_WRK_IP                --입력IP
                    ,p_WRK_ID                --수정ID
                    ,SYSDATE()               --수정일시
                    ,p_WRK_IP);              --수정IP
                    
                    
	ELSIF (p_WRK_TP ='GW') THEN
        UPDATE TQHA_IDAC
           SET APRV_NO_GW           = p_APRV_NO
              ,UPD_ID               = p_WRK_ID                  --수정ID 
              ,UPD_DTM              = SYSDATE()                 --수정일시
              ,UPD_IP               = p_WRK_IP                  --수정IP
         WHERE SIT_CD = p_SIT_CD          --현장코드
           AND ACCD_SEQ = p_ACCD_SEQ;       --사고순번
           
           v_ACCD_SEQ := p_ACCD_SEQ;
                    
        
    ELSIF (p_WRK_TP ='ATFL') THEN
        UPDATE TQHA_IDAC
           SET ATFL_GRP2            = p_ATFL_GRP2
              ,UPD_ID               = p_WRK_ID                  --수정ID 
              ,UPD_DTM              = SYSDATE()                 --수정일시
              ,UPD_IP               = p_WRK_IP                  --수정IP
         WHERE SIT_CD = p_SIT_CD          --현장코드
           AND ACCD_SEQ = p_ACCD_SEQ;       --사고순번
           
           v_ACCD_SEQ := p_ACCD_SEQ;
                    
    END IF;

    p_RTN_ACCD_SEQ := v_ACCD_SEQ;
    
    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 5. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN 
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);
END PQHA_IDAC_S;
/

-- PQHA_INDUST_ACCI_APRV_INFO_Q (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_INDUST_ACCI_APRV_INFO_Q" (
    p_WRK_TP            IN VARCHAR2 DEFAULT 'Q'         -- FLAG
,   p_SIT_CD            IN VARCHAR2                     -- 현장코드
,   p_ACCD_SEQ          IN NUMBER                       -- 사고순번
,   RTN_CURSOR          OUT SYS_REFCURSOR
)
IS
    /**************************************************************************************************************************
      Purpose : [산재작성 : 결재진행(그룹웨어)  ] PROCEDRE 

      REVISIONS
      Ver      Date               Author                  Description
      -------  -----------------  ----------------------  ---------------------------------------------------------------------
      1.0      2026/02/10                                 최초생성

    **************************************************************************************************************************/

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE  NUMBER :=-20009; -- ERROR 코드
    ERR_MSG   VARCHAR(200);    -- ERROR Message
    USER_EXCEPTION EXCEPTION;

BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 수행전 Check Logic ]
    ---------------------------------------------------------------------------------------------------------------------------

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Logic 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------

    ---------------------------------------------------------------------------------------
    -- 
    IF p_WRK_TP = 'Q1' THEN

        OPEN RTN_CURSOR FOR
        SELECT T1.APRV_NO     AS APRV_NO    -- 결재번호
             , T2.APRV_NO_GW  AS APRV_NO_GW -- 결재문서번호
             , T2.APRV_STATS  AS APRV_STATS -- 결재상태
         FROM TQHA_IDAC_APRV T1
         LEFT OUTER JOIN TCOF_APPROVE T2 ON T1.APRV_NO = T2.APRV_NO(+)
         WHERE T1.SIT_CD    = p_SIT_CD
           AND T1.ACCD_SEQ  = p_ACCD_SEQ
           AND T1.APRV_DIV  = '2'
        ;

    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
         WHEN OTHERS THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);

END PQHA_INDUST_ACCI_APRV_INFO_Q;
/

-- PQHA_INDUST_ACCI_APRV_INFO_S (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_INDUST_ACCI_APRV_INFO_S" (
    p_WRK_TP            VARCHAR2 :='U'                  -- UPDATE FLAG( I: ISNERT, U:UPDATE, D:DELTE)
,   p_WRK_ID            VARCHAR2                        -- 사용자 ID 
,   p_WRK_IP            VARCHAR2                        -- 사용자 IP 
,   p_SIT_CD            VARCHAR2                        -- 현장코드
,   p_ACCD_SEQ          NUMBER                          -- 사고순번
,   p_ACCD_CONTX        VARCHAR2                        -- 발생내용
,   p_APRV_NO           VARCHAR2                        -- 결재번호
)
IS 
    /**************************************************************************************************************************
      Purpose :  

      REVISIONS
      Ver      Date               Author                  Description  
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2026/02/10                                   최초생성

    **************************************************************************************************************************/

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR2(200);            -- ERROR Message
    USER_EXCEPTION EXCEPTION;

    v_cnt  INTEGER;                             -- 위험성 평가 일정 하위데이타 존재 여부

BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 필수입력 필드  Check  ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_SIT_CD IS NULL)  THEN
        ERR_MSG := '현장코드는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_ACCD_SEQ IS NULL)  THEN
        ERR_MSG := '사고순번은 필수 입력사항 입니다.'; 
        RAISE USER_EXCEPTION;
    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Process 선행조건 Check ]
    ---------------------------------------------------------------------------------------------------------------------------



    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Business Process ]
    ---------------------------------------------------------------------------------------------------------------------------

    ----------------------------------------------------------------------------------------------------
    -- 산재관리(본사) - 대시보드용 발생내용 수정
    IF (p_WRK_TP ='U') THEN

        UPDATE TQHA_IDAC
           SET ACCD_CONTX   = p_ACCD_CONTX      -- 발생내용
             , UPD_ID       = p_WRK_ID          -- 사용자 ID
             , UPD_DTM      = SYSDATE           -- 수정일시
             , UPD_IP       = p_WRK_IP          -- 사용자 IP
         WHERE SIT_CD       = p_SIT_CD          -- 현장코드
           AND ACCD_SEQ     = p_ACCD_SEQ        -- 사고순번
        ;

    ----------------------------------------------------------------------------------------------------
    -- 폼 저장 : 결재진행(본사)
    ELSIF (p_WRK_TP ='U2') THEN

        UPDATE TQHA_IDAC_APRV
           SET APRV_NO      = p_APRV_NO
             , UPD_ID       = p_WRK_ID          -- 사용자 ID
             , UPD_DTM      = SYSDATE
             , UPD_IP       = p_WRK_IP          -- 사용자 IP
         WHERE SIT_CD       = p_SIT_CD
           AND ACCD_SEQ     = p_ACCD_SEQ
           AND APRV_DIV     = '2'
        ;

    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 5. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN 
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);
END ;
/

-- PQHA_LABOR_JOINT_INSP_Q (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_LABOR_JOINT_INSP_Q"
(
     p_WRK_TP  VARCHAR2 DEFAULT 'Q'                                                       -- FLAG( Q: SELECT )
     ,p_SIT_CD TQHA_LABOR_JOINT_INSP.SIT_CD%TYPE                                          -- 현장코드
     ,p_LABOR_SEQ TQHA_LABOR_JOINT_INSP.LABOR_SEQ%TYPE                                    -- 노사합동점검순번
     ,p_LABOR_DT_STR TQHA_LABOR_JOINT_INSP.LABOR_DT%TYPE                                      -- 시자일
     ,p_LABOR_DT_END TQHA_LABOR_JOINT_INSP.LABOR_DT%TYPE                                      -- 종료일
     ,RTN_CURSOR OUT SYS_REFCURSOR
)
IS 
    /**************************************************************************************************************************
      Purpose : 

      REVISIONS
      Ver      Date               Author                  Description 
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2026/09/17 10:28:57                         최초생성

    /**************************************************************************************************************************/


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR2(200);            -- ERROR Message
    USER_EXCEPTION EXCEPTION;


BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 수행전 Check Logic ]
    ---------------------------------------------------------------------------------------------------------------------------


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Logic 처리
    ---------------------------------------------------------------------------------------------------------------------------

    OPEN RTN_CURSOR FOR
    SELECT  SIT_CD                 --현장코드
	       ,( SELECT CNST_NM FROM VQSZ_SITEINFO WHERE SIT_CD = A.SIT_CD ) AS SIT_NM
           ,LABOR_SEQ                 --노사합동점검순번
           ,LABOR_DGR                 --회차
           ,LABOR_DT                 --시행일자
           ,LABOR_CTS                 --주요내용
           ,RMKS                 --비고
           ,ATFL_GRP                 --첨부파일그룹
      FROM TQHA_LABOR_JOINT_INSP A
    WHERE SIT_CD LIKE p_SIT_CD ||'%'
      AND LABOR_DT BETWEEN NVL(p_LABOR_DT_STR, '19000101') AND NVL(p_LABOR_DT_END, '47121231')
      ORDER BY SIT_CD, LABOR_SEQ DESC 
           ;



    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN 
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);
END ;
/

-- PQHA_LABOR_JOINT_INSP_S (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_LABOR_JOINT_INSP_S"
                            (p_WRK_TP  VARCHAR2 :='U'                                     -- UPDATE FLAG( I: ISNERT, U:UPDATE, D:DELTE)
                            ,p_WRK_ID  VARCHAR2                                           -- 사용자 ID 
                            ,p_WRK_IP  VARCHAR2                                           -- 사용자 IP 
                            ,p_SIT_CD TQHA_LABOR_JOINT_INSP.SIT_CD%TYPE                   -- 현장코드
                            ,p_LABOR_SEQ TQHA_LABOR_JOINT_INSP.LABOR_SEQ%TYPE             -- 노사합동점검순번
                            ,p_LABOR_DGR TQHA_LABOR_JOINT_INSP.LABOR_DGR%TYPE             -- 회차
                            ,p_LABOR_DT TQHA_LABOR_JOINT_INSP.LABOR_DT%TYPE               -- 시행일자
                            ,p_LABOR_CTS TQHA_LABOR_JOINT_INSP.LABOR_CTS%TYPE             -- 주요내용
                            ,p_RMKS TQHA_LABOR_JOINT_INSP.RMKS%TYPE                       -- 비고
                            ,p_ATFL_GRP TQHA_LABOR_JOINT_INSP.ATFL_GRP%TYPE)              -- 첨부파일그룹
IS 
    /**************************************************************************************************************************
      Purpose : 

      REVISIONS
      Ver      Date               Author                  Description 
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2026/09/17 10:29:24                         최초생성

    /**************************************************************************************************************************/


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR2(200);            -- ERROR Message
    USER_EXCEPTION EXCEPTION;

	v_SEQ NUMBER;
BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 필수입력 필드  Check  ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_SIT_CD IS NULL)  THEN
        ERR_MSG := '현장코드는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_WRK_TP != 'I' AND p_LABOR_SEQ IS NULL)  THEN
        ERR_MSG := '순번는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Process 선행조건 Check ]
    ---------------------------------------------------------------------------------------------------------------------------
	SELECT  NVL(MAX(LABOR_SEQ),0)+1 INTO v_SEQ
      FROM TQHA_LABOR_JOINT_INSP
     WHERE SIT_CD = p_SIT_CD          --현장코드
     ;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Business Process ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_WRK_TP ='D') THEN
        DELETE 
          FROM TQHA_LABOR_JOINT_INSP
         WHERE SIT_CD = p_SIT_CD          --현장코드
           AND LABOR_SEQ = p_LABOR_SEQ;      --노사합동점검순번

    ELSIF (p_WRK_TP ='U') THEN
        UPDATE TQHA_LABOR_JOINT_INSP
           SET LABOR_DGR            = p_LABOR_DGR               --회차
              ,LABOR_DT             = p_LABOR_DT                --시행일자
              ,LABOR_CTS            = p_LABOR_CTS               --주요내용
              ,RMKS                 = p_RMKS                    --비고
              ,ATFL_GRP             = p_ATFL_GRP                --첨부파일그룹
              ,UPD_ID               = p_WRK_ID                  --수정ID 
              ,UPD_DTM              = SYSDATE()                 --수정일시
              ,UPD_IP               = p_WRK_IP                  --수정IP
         WHERE SIT_CD = p_SIT_CD          --현장코드
           AND LABOR_SEQ = p_LABOR_SEQ;      --노사합동점검순번
    ELSE 
        INSERT INTO TQHA_LABOR_JOINT_INSP
                   ( SIT_CD                  --현장코드
                    ,LABOR_SEQ               --노사합동점검순번
                    ,LABOR_DGR               --회차
                    ,LABOR_DT                --시행일자
                    ,LABOR_CTS               --주요내용
                    ,RMKS                    --비고
                    ,ATFL_GRP                --첨부파일그룹
                    ,IPT_ID                  --입력ID
                    ,IPT_DTM                 --입력일시
                    ,IPT_IP                  --입력IP
                    ,UPD_ID                  --수정ID
                    ,UPD_DTM                 --수정일시
                    ,UPD_IP                  --수정IP
                    )
             VALUES (p_SIT_CD                --현장코드
                    ,v_SEQ                  --노사합동점검순번
                    ,p_LABOR_DGR             --회차
                    ,p_LABOR_DT              --시행일자
                    ,p_LABOR_CTS             --주요내용
                    ,p_RMKS                  --비고
                    ,p_ATFL_GRP              --첨부파일그룹
                    ,p_WRK_ID                --입력ID 
                    ,SYSDATE()               --입력일시
                    ,p_WRK_IP                --입력IP
                    ,p_WRK_ID                --수정ID
                    ,SYSDATE()               --수정일시
                    ,p_WRK_IP);              --수정IP
    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 5. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN 
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);
END ;
/

-- PQHA_LABOR_LIST_Q (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_LABOR_LIST_Q" 
(
      p_WRK_TP  VARCHAR2 DEFAULT 'Q'                                                      -- FLAG( Q: SELECT )
     ,p_SIT_CD TQHA_LABOR_LIST.SIT_CD%TYPE                                                -- 현장코드
     ,RTN_CURSOR OUT SYS_REFCURSOR
)
IS 
    /**************************************************************************************************************************
      Purpose : 근로자 인명부 조회

      REVISIONS
      Ver      Date               Author                  Description 
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2024/04/01 12:54:48                         최초생성

    **************************************************************************************************************************/


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR2(200);            -- ERROR Message
    USER_EXCEPTION EXCEPTION;


BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 수행전 Check Logic ]
    ---------------------------------------------------------------------------------------------------------------------------


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Logic 처리
    ---------------------------------------------------------------------------------------------------------------------------

    OPEN RTN_CURSOR FOR
	    SELECT  SIT_CD                 --현장코드
	           ,LAB_SEQ                 --순번
	           ,LAB_KNM                 --성명(한글)
	           ,LAB_ENM                 --성명(영어)
	           ,BRTH_DT                 --생년월일
	           ,LAB_AGE                 --연령
	           ,HI_BLOOD                --고협압
	           ,JBCLS                   --직종
	           ,ADP_DT                  --채용일자
	           ,BLNCO                   --소속회사
	           ,CADDR                   --연락처
	           ,HLTHDGS_BAT             --건강진단 배치
	           ,HLTHDGS_RGL             --건강진단 정기
	           ,HLTHDGS_SPC             --건강진단 특수
	           ,EDU_RECU                --교육이수 채용시
	           ,EDU_SPCL                --교육이수 특별
	           ,EDU_RGL                 --교육이수 정기
	           ,EDU_MSDS                --교육이수 MSDS
	           ,EDU_CHAR_PSN            --교육이수 관리책임자
	           ,EDU_MNG_PSN1            --교육이수 관리감독자
	           ,RMKS                    --비고
	           ,DSVC_NATL				--국적
	           ,STY_QLF					--체류자격(QS057)
	           ,TRUNC(MONTHS_BETWEEN(TRUNC(SYSDATE), TO_DATE(BRTH_DT,'YYYYMMDD')) / 12) AS BRTH_AGE 
	           ,ATFL_GRP
	           ,ELDR
			   ,HLTH_ABN
	      FROM TQHA_LABOR_LIST
	     WHERE SIT_CD = p_SIT_CD      --현장코드
	  ORDER BY LAB_KNM
	           ;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN 
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);
END ;
/

