                            ,p_HLTHDGS_RGL 	TQHA_LABOR_LIST.HLTHDGS_RGL%TYPE                  -- 건강진단 정기
                            ,p_HLTHDGS_SPC 	TQHA_LABOR_LIST.HLTHDGS_SPC%TYPE                  -- 건강진단 특수
                            ,p_EDU_RECU 	TQHA_LABOR_LIST.EDU_RECU%TYPE                     -- 교육이수 채용시
                            ,p_EDU_SPCL 	TQHA_LABOR_LIST.EDU_SPCL%TYPE                     -- 교육이수 특별
                            ,p_EDU_RGL 		TQHA_LABOR_LIST.EDU_RGL%TYPE                      -- 교육이수 정기
                            ,p_EDU_MSDS 	TQHA_LABOR_LIST.EDU_MSDS%TYPE                     -- 교육이수 MSDS
                            ,p_EDU_CHAR_PSN TQHA_LABOR_LIST.EDU_CHAR_PSN%TYPE                 -- 교육이수 관리책임자
