                            ,p_RMKS 		TQHA_LABOR_LIST.RMKS%TYPE                         -- 비고
                            ,p_DSVC_NATL	TQHA_LABOR_LIST.DSVC_NATL%TYPE                    -- 국적
                            ,p_STY_QLF 		TQHA_LABOR_LIST.STY_QLF%TYPE                     -- 체류자격(QS057)
                            ,p_ATFL_GRP     TQHA_LABOR_LIST.ATFL_GRP%TYPE
                            ,p_ELDR   	    TQHA_LABOR_LIST.ELDR%TYPE
                            ,p_HLTH_ABN     TQHA_LABOR_LIST.HLTH_ABN%TYPE
                            )
IS 
    /**************************************************************************************************************************
      Purpose : 근로자 인명부 저장

      REVISIONS
      Ver      Date               Author                  Description 
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2024/03/19 15:13:21                         최초생성

    **************************************************************************************************************************/


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR2(200);            -- ERROR Message
    USER_EXCEPTION EXCEPTION;

    v_SEQ          NUMBER := 0;              -- 신규 채번


BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 필수입력 필드  Check  ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_SIT_CD IS NULL)  THEN
        ERR_MSG := '현장코드는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_LAB_SEQ IS NULL AND p_WRK_TP != 'I')  THEN
        ERR_MSG := '순번는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Process 선행조건 Check ]
    ---------------------------------------------------------------------------------------------------------------------------
 


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Business Process ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_WRK_TP ='D') THEN
        DELETE 
          FROM TQHA_LABOR_LIST
         WHERE SIT_CD = p_SIT_CD         --현장코드
           AND LAB_SEQ = p_LAB_SEQ;        --순번

    ELSIF (p_WRK_TP ='U') THEN
        UPDATE TQHA_LABOR_LIST
           SET LAB_KNM              = p_LAB_KNM                 --성명(한글)
              ,LAB_ENM              = p_LAB_ENM                 --성명(영어)
              ,BRTH_DT              = p_BRTH_DT                 --생년월일
              ,LAB_AGE              = p_LAB_AGE                 --연령
              ,HI_BLOOD             = p_HI_BLOOD                --고협압
              ,JBCLS                = p_JBCLS                   --직종
              ,ADP_DT               = p_ADP_DT                  --채용일자
              ,BLNCO                = p_BLNCO                   --소속회사
              ,CADDR                = p_CADDR                   --연락처
              ,HLTHDGS_BAT          = p_HLTHDGS_BAT             --건강진단 배치
              ,HLTHDGS_RGL          = p_HLTHDGS_RGL             --건강진단 정기
              ,HLTHDGS_SPC          = p_HLTHDGS_SPC             --건강진단 특수
              ,EDU_RECU             = p_EDU_RECU                --교육이수 채용시
              ,EDU_SPCL             = p_EDU_SPCL                --교육이수 특별
              ,EDU_RGL              = p_EDU_RGL                 --교육이수 정기
              ,EDU_MSDS             = p_EDU_MSDS                --교육이수 MSDS
              ,EDU_CHAR_PSN         = p_EDU_CHAR_PSN            --교육이수 관리책임자
              ,EDU_MNG_PSN1         = p_EDU_MNG_PSN1            --교육이수 관리감독자
              ,RMKS                 = p_RMKS                    --비고
              ,DSVC_NATL			= p_DSVC_NATL				--국적
              ,STY_QLF				= p_STY_QLF					--체류자격(QS057)
              ,ATFL_GRP             = p_ATFL_GRP              
              ,ELDR            	 	= p_ELDR
              ,HLTH_ABN             = p_HLTH_ABN
              ,UPD_ID               = p_WRK_ID                  --수정ID 
              ,UPD_DTM              = SYSDATE()                 --수정일시
              ,UPD_IP               = p_WRK_IP                  --수정IP
         WHERE SIT_CD = p_SIT_CD           --현장코드
           AND LAB_SEQ = p_LAB_SEQ;        --순번
    ELSE 

    	SELECT NVL(MAX(LAB_SEQ),0) + 1
    	  INTO v_SEQ
    	  FROM TQHA_LABOR_LIST
    	 WHERE SIT_CD = p_SIT_CD;

        INSERT INTO TQHA_LABOR_LIST
                   ( SIT_CD                  --현장코드
                    ,LAB_SEQ                 --순번
                    ,LAB_KNM                 --성명(한글)
                    ,LAB_ENM                 --성명(영어)
                    ,BRTH_DT                 --생년월일
                    ,LAB_AGE                 --연령
                    ,HI_BLOOD                --고협압
                    ,JBCLS                   --직종
                    ,ADP_DT                  --채용일자
                    ,BLNCO                   --소속회사
                    ,CADDR                   --연락처
                    ,HLTHDGS_BAT             --건강진단 배치
                    ,HLTHDGS_RGL             --건강진단 정기
                    ,HLTHDGS_SPC             --건강진단 특수
                    ,EDU_RECU                --교육이수 채용시
                    ,EDU_SPCL                --교육이수 특별
                    ,EDU_RGL                 --교육이수 정기
                    ,EDU_MSDS                --교육이수 MSDS
                    ,EDU_CHAR_PSN            --교육이수 관리책임자
                    ,EDU_MNG_PSN1            --교육이수 관리감독자
                    ,RMKS                    --비고
                    ,DSVC_NATL			     --국적
              		,STY_QLF				 --체류자격(QS057)
              		,ATFL_GRP
              		,ELDR
              		,HLTH_ABN
                    ,IPT_ID                  --입력ID
                    ,IPT_DTM                 --입력일시
                    ,IPT_IP                  --입력IP
                    ,UPD_ID                  --수정ID
                    ,UPD_DTM                 --수정일시
                    ,UPD_IP)                 --수정IP
             VALUES (p_SIT_CD                --현장코드
                    ,v_SEQ                   --순번
                    ,p_LAB_KNM               --성명(한글)
                    ,p_LAB_ENM               --성명(영어)
                    ,p_BRTH_DT               --생년월일
                    ,p_LAB_AGE               --연령
                    ,p_HI_BLOOD              --고협압
                    ,p_JBCLS                 --직종
                    ,p_ADP_DT                --채용일자
                    ,p_BLNCO                 --소속회사
                    ,p_CADDR                 --연락처
                    ,p_HLTHDGS_BAT           --건강진단 배치
                    ,p_HLTHDGS_RGL           --건강진단 정기
                    ,p_HLTHDGS_SPC           --건강진단 특수
                    ,p_EDU_RECU              --교육이수 채용시
                    ,p_EDU_SPCL              --교육이수 특별
                    ,p_EDU_RGL               --교육이수 정기
                    ,p_EDU_MSDS              --교육이수 MSDS
                    ,p_EDU_CHAR_PSN          --교육이수 관리책임자
                    ,p_EDU_MNG_PSN1          --교육이수 관리감독자
                    ,p_RMKS                  --비고
                    ,p_DSVC_NATL   	         --국적
              		,p_STY_QLF				 --체류자격(QS057)
              		,p_ATFL_GRP
              		,p_ELDR
              		,p_HLTH_ABN
                    ,p_WRK_ID                --입력ID 
                    ,SYSDATE()               --입력일시
                    ,p_WRK_IP                --입력IP
                    ,p_WRK_ID                --수정ID
                    ,SYSDATE()               --수정일시
                    ,p_WRK_IP);              --수정IP
    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 5. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN 
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);
END ;
/

-- PQHA_LABOR_MNG_CNCL_Q (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_LABOR_MNG_CNCL_Q"
(
     p_WRK_TP  VARCHAR2 DEFAULT 'Q'                                                       -- FLAG( Q: SELECT )
     ,p_SIT_CD TQHA_LABOR_MNG_CNCL.SIT_CD%TYPE                                            -- 현장코드
     ,p_LABOR_SEQ TQHA_LABOR_MNG_CNCL.LABOR_SEQ%TYPE                                      -- 노사협의체순번
     ,p_LABOR_DT_STR TQHA_LABOR_MNG_CNCL.LABOR_DT%TYPE                                      -- 시자일
     ,p_LABOR_DT_END TQHA_LABOR_MNG_CNCL.LABOR_DT%TYPE                                      -- 종료일
     ,RTN_CURSOR OUT SYS_REFCURSOR
)
IS 
    /**************************************************************************************************************************
      Purpose : 

      REVISIONS
      Ver      Date               Author                  Description 
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2026/09/17 10:27:33                         최초생성

    /**************************************************************************************************************************/


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR2(200);            -- ERROR Message
    USER_EXCEPTION EXCEPTION;


BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 수행전 Check Logic ]
    ---------------------------------------------------------------------------------------------------------------------------


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Logic 처리
    ---------------------------------------------------------------------------------------------------------------------------

    OPEN RTN_CURSOR FOR
    SELECT  SIT_CD                 --현장코드
           ,( SELECT CNST_NM FROM VQSZ_SITEINFO WHERE SIT_CD = A.SIT_CD ) AS SIT_NM
           ,LABOR_SEQ                 --노사협의체순번
           ,LABOR_DGR                 --회차
           ,LABOR_DT                 --시행일자
           ,LABOR_CTS                 --주요내용
           ,RMKS                 --비고
           ,ATFL_GRP                 --첨부파일그룹
      FROM TQHA_LABOR_MNG_CNCL A
    WHERE SIT_CD LIKE p_SIT_CD ||'%'
      AND LABOR_DT BETWEEN NVL(p_LABOR_DT_STR, '19000101') AND NVL(p_LABOR_DT_END, '47121231')
    ORDER BY SIT_CD, LABOR_SEQ DESC 
           ;



    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN 
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);
END ;
/

