                            ,p_LABOR_DT TQHA_LABOR_MNG_CNCL.LABOR_DT%TYPE                 -- 시행일자
                            ,p_LABOR_CTS TQHA_LABOR_MNG_CNCL.LABOR_CTS%TYPE               -- 주요내용
                            ,p_RMKS TQHA_LABOR_MNG_CNCL.RMKS%TYPE                         -- 비고
                            ,p_ATFL_GRP TQHA_LABOR_MNG_CNCL.ATFL_GRP%TYPE)                -- 첨부파일그룹
IS 
    /**************************************************************************************************************************
      Purpose : 

      REVISIONS
      Ver      Date               Author                  Description 
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2026/09/17 10:28:19                         최초생성

    /**************************************************************************************************************************/


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR2(200);            -- ERROR Message
    USER_EXCEPTION EXCEPTION;

	v_SEQ NUMBER;
BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 필수입력 필드  Check  ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_SIT_CD IS NULL)  THEN
        ERR_MSG := '현장코드는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_WRK_TP != 'I' AND p_LABOR_SEQ IS NULL)  THEN
        ERR_MSG := '노사협의체순번는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Process 선행조건 Check ]
    ---------------------------------------------------------------------------------------------------------------------------
	SELECT  NVL(MAX(LABOR_SEQ),0)+1 INTO v_SEQ
      FROM TQHA_LABOR_MNG_CNCL
     WHERE SIT_CD = p_SIT_CD          --현장코드
     ;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Business Process ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_WRK_TP ='D') THEN
        DELETE 
          FROM TQHA_LABOR_MNG_CNCL
         WHERE SIT_CD = p_SIT_CD          --현장코드
           AND LABOR_SEQ = p_LABOR_SEQ;      --노사협의체순번

    ELSIF (p_WRK_TP ='U') THEN
        UPDATE TQHA_LABOR_MNG_CNCL
           SET LABOR_DGR            = p_LABOR_DGR               --회차
              ,LABOR_DT             = p_LABOR_DT                --시행일자
              ,LABOR_CTS            = p_LABOR_CTS               --주요내용
              ,RMKS                 = p_RMKS                    --비고
