         WHERE SIT_CD = p_SIT_CD          --현장코드
           AND LABOR_SEQ = p_LABOR_SEQ;      --노사협의체순번
    ELSE 
        INSERT INTO TQHA_LABOR_MNG_CNCL
                   ( SIT_CD                  --현장코드
                    ,LABOR_SEQ               --노사협의체순번
                    ,LABOR_DGR               --회차
                    ,LABOR_DT                --시행일자
                    ,LABOR_CTS               --주요내용
