                    ,p_LABOR_DT              --시행일자
                    ,p_LABOR_CTS             --주요내용
                    ,p_RMKS                  --비고
                    ,p_ATFL_GRP              --첨부파일그룹
                    ,p_WRK_ID                --입력ID 
                    ,SYSDATE()               --입력일시
                    ,p_WRK_IP                --입력IP
                    ,p_WRK_ID                --수정ID
                    ,SYSDATE()               --수정일시
                    ,p_WRK_IP);              --수정IP
    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 5. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN 
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);
END ;
/

-- PQHA_LAB_AREC_B (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_LAB_AREC_B" (   -- 노사협의체 전회복사
    p_WRK_TP            VARCHAR2 :='U'                          -- UPDATE FLAG( I: ISNERT, U:UPDATE, D:DELTE)
,   p_WRK_ID            VARCHAR2                                -- 사용자 ID 
,   p_WRK_IP            VARCHAR2                                -- 사용자 IP 
,   p_SIT_CD            TQHA_LAB_AREC.SIT_CD%TYPE               -- 현장코드
-- 2024/03/07 회의체코드 추가
,   p_AREC_CD           TQHA_LAB_AREC.AREC_CD%TYPE              -- 교육코드
--------------------------------------------------------
,   p_CONF_DT           TQHA_LAB_AREC.CONF_DT%TYPE              -- 회의일자
,   p_RTN_CONF_SEQ      OUT VARCHAR2                            -- 리턴변수(회의순번)
)
IS 
    /**************************************************************************************************************************
      Purpose : 협의체 회의록 전회복사

      REVISIONS
      Ver      Date               Author                  Description 
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2022/02/18 11:58:50                         최초생성
      1.1     2024/03/07 10:00:00 정우성                    회의체코드 추가
    **************************************************************************************************************************/


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR2(200);            -- ERROR Message
    USER_EXCEPTION EXCEPTION;

    v_CONF_SEQ              TQHA_LAB_AREC.CONF_SEQ%TYPE;    -- 순번 변수 선언
    v_BEF_CONF_SEQ          TQHA_LAB_AREC.CONF_SEQ%TYPE;    -- 전회순번 변수

BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 필수입력 필드  Check  ]
    ---------------------------------------------------------------------------------------------------------------------------
    ---------------------------------------------------------------------
    -- 결재상태 체크
    -- 신규 추가일 경우에만 전회복사를 함.

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Process 선행조건 Check ]
    ---------------------------------------------------------------------------------------------------------------------------
    -- 전회 조회
    SELECT MAX(CONF_SEQ) AS CONF_SEQ
      INTO v_BEF_CONF_SEQ
      FROM TQHA_LAB_AREC
     WHERE SIT_CD = p_SIT_CD
       -- 2024/03/05 회의체코드 추가 
       AND AREC_CD = p_AREC_CD
       ------------------------------------------ 
       AND CONF_DT < p_CONF_DT
    ;

    IF (v_BEF_CONF_SEQ IS NULL) THEN
        ERR_MSG := '전회복사할 데이터가 없습니다.';
        RAISE USER_EXCEPTION;
    ELSE
        -- 노사협의체순번 생성
        SELECT NVL((MAX(CONF_SEQ)+1), 1) 
          INTO v_CONF_SEQ
          FROM TQHA_LAB_AREC
         WHERE SIT_CD = p_SIT_CD         --현장코드
        ;
        -- 노사협의체순번 생성 완료     
    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Business Process ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_WRK_TP = 'I') THEN 

        INSERT 
          INTO TQHA_LAB_AREC
             ( SIT_CD                   -- 현장코드
             , CONF_SEQ                 -- 회의순번
             -- 2024/03/07 회의체코드/기타사항 추가------------
             , AREC_CD                  -- 회의체코드
             , ETC_MATT                 -- 기타사항
             -------------------------------------
             , CONF_DT                  -- 회의일자
             , CONF_STR_TIME            -- 회의시작시간
             , CONF_END_TIME            -- 회의종료시간
             , CONF_PLC                 -- 회의장소
             , CONF_PRTR                -- 회의참석자
             , THME                     -- 주제
             , DECD_MATT                -- 의결사항
             , IPT_ID                   -- 입력ID
             , IPT_DTM                  -- 입력일시
             , IPT_IP                   -- 입력IP
             , UPD_ID                   -- 수정ID
             , UPD_DTM                  -- 수정일시
             , UPD_IP                   -- 수정IP
             )
        SELECT SIT_CD                   -- 현장코드
             , v_CONF_SEQ               -- 회의순번
             -- 2024/03/07 회의체코드/기타사항 추가------------
             , p_AREC_CD                -- 회의체코드
             , ETC_MATT                 -- 기타사항
             -------------------------------------
             , p_CONF_DT                -- 회의일자
             , CONF_STR_TIME            -- 회의시작시간
             , CONF_END_TIME            -- 회의종료시간
             , CONF_PLC                 -- 회의장소
             , CONF_PRTR                -- 회의참석자
             , THME                     -- 주제
             , DECD_MATT                -- 의결사항
             , p_WRK_ID                 -- 입력ID
             , SYSDATE()                -- 입력일시
             , p_WRK_IP                 -- 입력IP
             , p_WRK_ID                 -- 수정ID
             , SYSDATE()                -- 수정일시
             , p_WRK_IP                 -- 수정IP
          FROM TQHA_LAB_AREC
         WHERE SIT_CD       = p_SIT_CD
           AND CONF_SEQ     = v_BEF_CONF_SEQ
        ;

    END IF;

    p_RTN_CONF_SEQ := v_CONF_SEQ;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 5. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN 
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);

END PQHA_LAB_AREC_B;
/

-- PQHA_LAB_AREC_Q (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_LAB_AREC_Q" (
    p_WRK_TP                IN VARCHAR2 DEFAULT 'Q'         -- FLAG(Q)
,   p_SIT_CD                IN VARCHAR2                     -- 현장
,   p_SEARCH_CONF_YM        IN VARCHAR2                     -- 년월
,   p_CONF_SEQ              IN VARCHAR2                     -- 노사회의순번
,   RTN_CURSOR              OUT SYS_REFCURSOR
)
IS
    /**************************************************************************************************************************
    COPYRIGHT:    HUMAN PLUS
    PROCEDURE:    [PQHA_LAB_AREC_Q] PROCEDRE
    설명     :    [QSE > 안전관리 > 안전서류관리 > 노사협의체목록  조회] 프로시저

     개정일자                      변경내용요약                                 관련근거
    ---------------------------------------------------------------------------------------------------------------------------
     2023-11-28   HUMANPLUS        신규
     2023/03/06    정우성            협의체 코드 추가
    ***************************************************************************************************************************/


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009 ; --ERROR 코드
    ERR_MSG        VARCHAR2(200)   ; --ERROR Message
    USER_EXCEPTION EXCEPTION       ;

BEGIN
    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 수행전 Check Logic ]
    ---------------------------------------------------------------------------------------------------------------------------


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Logic 처리
    ---------------------------------------------------------------------------------------------------------------------------

    -- 노사협의체목록 조회
    IF p_WRK_TP = 'Q' THEN
        --DBMS_OUTPUT.PUT_LINE('PQHA_LAB_AREC_Q 노사협의체목록 조회');

        OPEN RTN_CURSOR FOR
        SELECT A.SIT_CD             -- 현장코드
             , A.CONF_SEQ           -- 회의순번
             , A.CONF_DT            -- 회의일자
             , A.CONF_STR_TIME      -- 회의시작시간
             , A.CONF_END_TIME      -- 회의종료시간
             , A.CONF_PLC           -- 회의장소
             , A.CONF_PRTR          -- 회의참석자
             , A.THME               -- 주제
             , A.DECD_MATT          -- 의결사항
             ---2023/03/06    (정우성) 협의체 코드(명)/기타사항 추가
             , A.AREC_CD            -- 협의체 코드
             , C.AREC_NM            -- 협의체명
             , A.ETC_MATT           -- 기타사항
             -------------------------------------
             , A.APRV_NO            -- 결재번호
             , D.CD_NM  AS APRV_STATS_NM  -- 결재진행상태
             , B.APRV_STATS         -- 결재상태
             , TO_CHAR(TO_DATE(A.CONF_DT, 'YYYYMMDD'), 'day') AS DAY_OF_WEEK --요일
          FROM TQHA_LAB_AREC        A
          LEFT JOIN TQHA_APRV       B ON A.SIT_CD       = B.SIT_CD
                                     AND A.APRV_NO      = B.APRV_NO
          ---2023/03/04    (정우성) 협의체 코드 추가
          LEFT JOIN  TQHA_AREC_CD   C ON C.AREC_CD      = A.AREC_CD
          LEFT JOIN  TCOA_COMCODE   D ON D.COM_CD       = B.APRV_STATS
                                     AND D.HRNK_CD      = 'QS031'
          -------------------------------------
         WHERE A.SIT_CD = p_SIT_CD
           AND (SUBSTR(A.CONF_DT,1,6) = p_SEARCH_CONF_YM OR NVL(p_SEARCH_CONF_YM, 0) = 0 )
         ORDER BY CONF_DT DESC
        ;

    ELSIF p_WRK_TP = 'Q1' THEN

        OPEN RTN_CURSOR FOR
        SELECT A.SIT_CD             -- 현장코드
             , A.CONF_SEQ           -- 노사회의순번
             , A.CONF_DT            -- 회의일자
             , A.CONF_STR_TIME      -- 회의시작시간
             , A.CONF_END_TIME      -- 회의종료시간
             , A.CONF_PLC           -- 회의장소
             , A.CONF_PRTR          -- 회의참석자
             , A.THME               -- 회의주제
             , A.DECD_MATT          -- 의결사항
             ---2023/03/06    (정우성) 협의체 코드(명)/기타사항 추가
             , A.AREC_CD            -- 협의체 코드
             , C.AREC_NM            -- 협의체명
             , A.ETC_MATT           -- 기타사항
             -------------------------------------
             , A.PHOTO_GRP1         -- 사진1
             , A.PHOTO_DESC_1       -- 사진설명1
             , A.PHOTO_GRP2         -- 사진2
             , A.PHOTO_DESC_2       -- 사진설명2
             , A.ATFL_GRP           -- 첨부파일그룹
             , A.APRV_NO            -- 결재번호
             , B.APRV_STATS         -- 결재상태
             , '▶ 결재상태 : ' || NVL(( SELECT CD_NM FROM TCOA_COMCODE WHERE HRNK_CD = 'QS031' AND COM_CD = B.APRV_STATS ), '-') AS APRV_STATS_NM -- 결재상태명
          FROM TQHA_LAB_AREC        A
          LEFT JOIN TQHA_APRV       B ON A.SIT_CD = B.SIT_CD
                                     AND A.APRV_NO = B.APRV_NO
          ---2023/03/04    (정우성) 협의체 코드 추가
            LEFT JOIN  TQHA_AREC_CD C ON C.AREC_CD = A.AREC_CD
          -------------------------------------
         WHERE A.SIT_CD     = p_SIT_CD
           AND A.CONF_SEQ   = p_CONF_SEQ
        ;

    END IF;


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);

END ;
/

-- PQHA_LAB_AREC_S (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_LAB_AREC_S" (
    p_WRK_TP                VARCHAR2 :='U'                                  -- UPDATE FLAG( I: ISNERT, U:UPDATE, D:DELTE)
,   p_WRK_ID                VARCHAR2                                        -- 사용자 ID 
,   p_WRK_IP                VARCHAR2                                        -- 사용자 IP 
,   p_SIT_CD                TQHA_LAB_AREC.SIT_CD                %TYPE       -- 현장코드
,   p_CONF_SEQ              TQHA_LAB_AREC.CONF_SEQ              %TYPE       -- 회의순번
,   p_CONF_DT               TQHA_LAB_AREC.CONF_DT               %TYPE       -- 회의일자
,   p_CONF_STR_TIME         TQHA_LAB_AREC.CONF_STR_TIME         %TYPE       -- 회의시작시간
,   p_CONF_END_TIME         TQHA_LAB_AREC.CONF_END_TIME         %TYPE       -- 회의종료시간
,   p_CONF_PLC              TQHA_LAB_AREC.CONF_PLC              %TYPE       -- 회의장소
,   p_CONF_PRTR             TQHA_LAB_AREC.CONF_PRTR             %TYPE       -- 회의참석자
,   p_THME                  TQHA_LAB_AREC.THME                  %TYPE       -- 주제
,   p_DECD_MATT             TQHA_LAB_AREC.DECD_MATT             %TYPE       -- 의결사항
--2023/03/06 (정우성) 협의체 코드,기타사항 추가---
,   p_AREC_CD               TQHA_LAB_AREC.AREC_CD               %TYPE       -- 협의체 코드
,   p_ETC_MATT              TQHA_LAB_AREC.ETC_MATT              %TYPE       -- 기타사항
---------------------------------------------
,   p_PHOTO_GRP1            TQHA_LAB_AREC.PHOTO_GRP1            %TYPE       -- 첨부파일그룹사진1
,   p_PHOTO_DESC_1          TQHA_LAB_AREC.PHOTO_DESC_1          %TYPE       -- 사진설명1
,   p_PHOTO_GRP2            TQHA_LAB_AREC.PHOTO_GRP2            %TYPE       -- 첨부파일그룹사진2
,   p_PHOTO_DESC_2          TQHA_LAB_AREC.PHOTO_DESC_2          %TYPE       -- 사진설명2
,   p_ATFL_GRP              TQHA_LAB_AREC.ATFL_GRP              %TYPE       -- 첨부파일그룹
,   p_APRV_NO               TQHA_LAB_AREC.APRV_NO               %TYPE       -- 결재번호
,   p_RTN_CONF_SEQ          OUT VARCHAR2                                    -- 리턴변수(회의순번)
)
IS 
    /**************************************************************************************************************************
      Purpose : 협의체 회의록 저장

      REVISIONS
      Ver      Date               Author                  Description 
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2021/10/26 19:36:28                         최초생성
      1.1      2023/03/06              정우성                  협의체 코드,기타사항 추가
    **************************************************************************************************************************/


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR2(200);            -- ERROR Message
    USER_EXCEPTION EXCEPTION;

    v_CONF_SEQ          TQHA_LAB_AREC.CONF_SEQ%TYPE ;             -- 순번 변수 선언

    v_APRV_STATS        VARCHAR2(20);
    v_APRV_STATS_NM     VARCHAR2(50);

BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 필수입력 필드  Check  ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_SIT_CD IS NULL AND p_WRK_TP <> 'I' )  THEN
        ERR_MSG := '현장코드는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_CONF_SEQ IS NULL AND p_WRK_TP <> 'I' )  THEN
        ERR_MSG := '회의순번는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;
    IF (p_AREC_CD IS NULL  )  THEN
        ERR_MSG := '협의체코드는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;   

    ---------------------------------------------------------------------
    -- 결재상태 체크
    SELECT MAX(T2.APRV_STATS)
         , MAX(T3.CD_NM )
      INTO v_APRV_STATS
         , v_APRV_STATS_NM
      FROM TQHA_LAB_AREC        T1
      LEFT JOIN TQHA_APRV       T2 ON T1.SIT_CD     = T2.SIT_CD
                                  AND T1.APRV_NO    = T2.APRV_NO
      LEFT JOIN TCOA_COMCODE    T3 ON T2.APRV_STATS = T3.COM_CD 
                                  AND T3.HRNK_CD    = 'QS031'
     WHERE T1.SIT_CD    = p_SIT_CD
       AND T1.CONF_SEQ  = p_CONF_SEQ
    ;

    IF v_APRV_STATS IN ('2', '4') THEN
        ERR_MSG := '결재상태 [' || v_APRV_STATS_NM || ']인 데이터는 수정 불가합니다.';
        RAISE USER_EXCEPTION;
    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Process 선행조건 Check ]
    ---------------------------------------------------------------------------------------------------------------------------



    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Business Process ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_WRK_TP ='D') THEN

        DELETE 
          FROM TQHA_LAB_AREC
         WHERE SIT_CD       = p_SIT_CD         -- 현장코드
           AND CONF_SEQ     = p_CONF_SEQ       -- 회의순번
        ;

        v_CONF_SEQ := p_CONF_SEQ;

    ELSIF (p_WRK_TP ='U') THEN

        UPDATE TQHA_LAB_AREC
           SET CONF_DT              = p_CONF_DT                 -- 회의일자
             , CONF_STR_TIME        = p_CONF_STR_TIME           -- 회의시작시간
             , CONF_END_TIME        = p_CONF_END_TIME           -- 회의종료시간
             , CONF_PLC             = p_CONF_PLC                -- 회의장소
             , CONF_PRTR            = p_CONF_PRTR               -- 회의참석자
             , THME                 = p_THME                    -- 주제
             , DECD_MATT            = p_DECD_MATT               -- 의결사항
             --2023/03/06 (정우성) 협의체 코드,기타사항 추가---
             , AREC_CD              = p_AREC_CD                 -- 협의체 코드
             , ETC_MATT             = p_ETC_MATT                -- 기타사항
              ---------------------------------------------
             , PHOTO_GRP1           = p_PHOTO_GRP1              -- 첨부파일그룹사진1
             , PHOTO_DESC_1         = p_PHOTO_DESC_1            -- 사진설명1
             , PHOTO_GRP2           = p_PHOTO_GRP2              -- 첨부파일그룹사진2
             , PHOTO_DESC_2         = p_PHOTO_DESC_2            -- 사진설명2
             , ATFL_GRP             = p_ATFL_GRP                -- 첨부파일그룹
             , APRV_NO              = p_APRV_NO                 -- 결재번호
             , UPD_ID               = p_WRK_ID                  -- 수정ID 
             , UPD_DTM              = SYSDATE()                 -- 수정일시
             , UPD_IP               = p_WRK_IP                  -- 수정IP
         WHERE SIT_CD               = p_SIT_CD                  -- 현장코드
           AND CONF_SEQ             = p_CONF_SEQ                -- 회의순번
        ;

        v_CONF_SEQ := p_CONF_SEQ;

    ELSE 
        -- 노사협의체순번 생성
        SELECT NVL( (MAX(CONF_SEQ)+1),'1' ) 
          INTO v_CONF_SEQ
          FROM TQHA_LAB_AREC
         WHERE SIT_CD   = p_SIT_CD         --현장코드
        ;
        -- 노사협의체순번 생성 완료    

        INSERT 
          INTO TQHA_LAB_AREC
             ( SIT_CD                   -- 현장코드
             , CONF_SEQ                 -- 회의순번
             , CONF_DT                  -- 회의일자
             , CONF_STR_TIME            -- 회의시작시간
             , CONF_END_TIME            -- 회의종료시간
             , CONF_PLC                 -- 회의장소
             , CONF_PRTR                -- 회의참석자
             , THME                     -- 주제
             , DECD_MATT                -- 의결사항
             --2023/03/06 (정우성) 협의체 코드,기타사항 추가---
             , AREC_CD                  -- 협의체 코드
             , ETC_MATT                 -- 기타사항
             ---------------------------------------------
             ,PHOTO_GRP1                -- 첨부파일그룹사진1
             ,PHOTO_DESC_1              -- 사진설명1
             ,PHOTO_GRP2                -- 첨부파일그룹사진2
             ,PHOTO_DESC_2              -- 사진설명2
             ,ATFL_GRP                  -- 첨부파일그룹
             ,APRV_NO                   -- 결재번호
             ,IPT_ID                    -- 입력ID
             ,IPT_DTM                   -- 입력일시
             ,IPT_IP                    -- 입력IP
             ,UPD_ID                    -- 수정ID
             ,UPD_DTM                   -- 수정일시
             ,UPD_IP                    -- 수정IP
             )
        VALUES 
             ( p_SIT_CD                 -- 현장코드
             , v_CONF_SEQ               -- 회의순번
             , p_CONF_DT                -- 회의일자
             , p_CONF_STR_TIME          -- 회의시작시간
             , p_CONF_END_TIME          -- 회의종료시간
             , p_CONF_PLC               -- 회의장소
             , p_CONF_PRTR              -- 회의참석자
             , p_THME                   -- 주제
             , p_DECD_MATT              -- 의결사항
             --2023/03/06 (정우성) 협의체 코드,기타사항 추가---
             , p_AREC_CD                -- 협의체 코드
             , p_ETC_MATT               -- 기타사항
             ---------------------------------------------
             , p_PHOTO_GRP1             -- 첨부파일그룹사진1
             , p_PHOTO_DESC_1           -- 사진설명1
             , p_PHOTO_GRP2             -- 첨부파일그룹사진2
             , p_PHOTO_DESC_2           -- 사진설명2
             , p_ATFL_GRP               -- 첨부파일그룹
             , p_APRV_NO                -- 결재번호
             , p_WRK_ID                 -- 입력ID 
             , SYSDATE()                -- 입력일시
             , p_WRK_IP                 -- 입력IP
             , p_WRK_ID                 -- 수정ID
             , SYSDATE()                -- 수정일시
             , p_WRK_IP                 -- 수정IP
             )
        ;

    END IF;

    p_RTN_CONF_SEQ := v_CONF_SEQ;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 5. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN 
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);

END ;
/

-- PQHA_LBR_CHK_ITM_S (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_LBR_CHK_ITM_S" (
    p_WRK_TP                VARCHAR2 :='U'                                  -- UPDATE FLAG( I: ISNERT, U:UPDATE, D:DELTE)
,   p_WRK_ID                VARCHAR2                                        -- 사용자 ID 
,   p_WRK_IP                VARCHAR2                                        -- 사용자 IP 
,   p_SIT_CD                TQHA_LBR_CHK_ITM.SIT_CD             %TYPE       -- 현장코드
,   p_CHK_SEQ               TQHA_LBR_CHK_ITM.CHK_SEQ            %TYPE       -- 점검순번
,   p_CHK_CD                TQHA_LBR_CHK_ITM.CHK_CD             %TYPE       -- 노사합동점검표 구분(QS027) 1 개인보호구 적정지급 
,   p_CHK_MATT              TQHA_LBR_CHK_ITM.CHK_MATT           %TYPE       -- 지적사항
,   p_MA_RSLT               TQHA_LBR_CHK_ITM.MA_RSLT            %TYPE       -- 조치결과
,   p_IMPRV_DT              TQHA_LBR_CHK_ITM.IMPRV_DT           %TYPE       -- 개선일자
,   p_PHOTO_GRP1            TQHA_LBR_CHK_ITM.PHOTO_GRP1         %TYPE       -- 첨부파일그룹사진1
,   p_PHOTO_DESC_1          TQHA_LBR_CHK_ITM.PHOTO_DESC_1       %TYPE       -- 사진설명1
,   p_PHOTO_GRP2            TQHA_LBR_CHK_ITM.PHOTO_GRP2         %TYPE       -- 개선일자
,   p_PHOTO_DESC_2          TQHA_LBR_CHK_ITM.PHOTO_DESC_2       %TYPE       -- 사진설명2
) 
IS 
    /**************************************************************************************************************************
      Purpose : 점검내용 저장

      REVISIONS
      Ver      Date               Author                  Description 
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2021/10/28 11:18:44                         최초생성

    **************************************************************************************************************************/


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR2(200);            -- ERROR Message
    USER_EXCEPTION EXCEPTION;
    v_CHK_CD            TQHA_LBR_CHK_ITM.CHK_CD%TYPE ;  -- 순번 변수 선언

    v_APRV_STATS        VARCHAR2(20);
    v_APRV_STATS_NM     VARCHAR2(50);

BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 필수입력 필드  Check  ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_SIT_CD IS NULL)  THEN
        ERR_MSG := '현장코드는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_CHK_SEQ IS NULL)  THEN
        ERR_MSG := '점검순번는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

--    IF (p_CHK_CD IS NULL)  THEN
--        ERR_MSG := '노사합동점검표는(은) 필수 입력사항 입니다.';
--        RAISE USER_EXCEPTION;
--    END IF;
    
    ---------------------------------------------------------------------
    -- 결재상태 체크
    SELECT MAX(T2.APRV_STATS)
         , MAX(T3.CD_NM )
      INTO v_APRV_STATS
         , v_APRV_STATS_NM
      FROM TQHA_LBR_CHK         T1
      LEFT JOIN TQHA_APRV       T2 ON T1.SIT_CD     = T2.SIT_CD
                                  AND T1.APRV_NO    = T2.APRV_NO
      LEFT JOIN TCOA_COMCODE    T3 ON T2.APRV_STATS = T3.COM_CD 
                                  AND T3.HRNK_CD    = 'QS031'
     WHERE T1.SIT_CD    = p_SIT_CD
       AND T1.CHK_SEQ   = p_CHK_SEQ
    ;
    
    IF v_APRV_STATS IN ('2', '4') THEN
        ERR_MSG := '결재상태 [' || v_APRV_STATS_NM || ']인 데이터는 수정 불가합니다.';
        RAISE USER_EXCEPTION;
    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Process 선행조건 Check ]
    ---------------------------------------------------------------------------------------------------------------------------

       -- 순번 생성
    SELECT NVL(MAX(CHK_CD), 0) +1     --노사합동점검표 구분(QS027) 1 개인보호구 적정지급 
          INTO v_CHK_CD
       FROM TQHA_LBR_CHK_ITM
      WHERE SIT_CD  = p_SIT_CD      -- 현장코드
        AND CHK_SEQ = p_CHK_SEQ     -- 점검순번
    ;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Business Process ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_WRK_TP ='D') THEN
    
        DELETE 
          FROM TQHA_LBR_CHK_ITM
         WHERE SIT_CD   = p_SIT_CD      -- 현장코드
           AND CHK_SEQ  = p_CHK_SEQ     -- 점검순번
           AND CHK_CD   = p_CHK_CD      -- 노사합동점검표 구분(QS027) 1 개인보호구 적정지급 
        ;

    ELSIF (p_WRK_TP ='U') THEN
    
        UPDATE TQHA_LBR_CHK_ITM
           SET CHK_MATT         = p_CHK_MATT            -- 지적사항
             , MA_RSLT          = p_MA_RSLT             -- 조치결과
             , IMPRV_DT         = p_IMPRV_DT            -- 개선일자
             , PHOTO_GRP1       = p_PHOTO_GRP1          -- 첨부파일그룹사진1
             , PHOTO_DESC_1     = p_PHOTO_DESC_1        -- 사진설명1
             , PHOTO_GRP2       = p_PHOTO_GRP2          -- 첨부파일그룹사진2
             , PHOTO_DESC_2     = p_PHOTO_DESC_2        -- 사진설명2
             , UPD_ID           = p_WRK_ID              -- 수정ID 
             , UPD_DTM          = SYSDATE()             -- 수정일시
             , UPD_IP           = p_WRK_IP              -- 수정IP
         WHERE SIT_CD           = p_SIT_CD              -- 현장코드
           AND CHK_SEQ          = p_CHK_SEQ             -- 점검순번
           AND CHK_CD           = p_CHK_CD              -- 노사합동점검표 구분(QS027) 1 개인보호구 적정지급 
        ;
        
    ELSE 

        INSERT 
          INTO TQHA_LBR_CHK_ITM
             ( SIT_CD               -- 현장코드
             , CHK_SEQ              -- 점검순번
             , CHK_CD               -- 노사합동점검표 구분(QS027) 1 개인보호구 적정지급 
             , CHK_MATT             -- 지적사항
             , MA_RSLT              -- 조치결과
             , IMPRV_DT             -- 개선일자
             , PHOTO_GRP1           -- 첨부파일그룹사진1
             , PHOTO_DESC_1         -- 사진설명1
             , PHOTO_GRP2           -- 첨부파일그룹사진2
             , PHOTO_DESC_2         -- 사진설명2
             , IPT_ID               -- 입력ID
             , IPT_DTM              -- 입력일시
             , IPT_IP               -- 입력IP
             , UPD_ID               -- 수정ID
             , UPD_DTM              -- 수정일시
             , UPD_IP               -- 수정IP
             )
        VALUES 
             ( p_SIT_CD             -- 현장코드
             , p_CHK_SEQ            -- 점검순번
             , v_CHK_CD             -- 노사합동점검표 구분(QS027) 1 개인보호구 적정지급 
             , p_CHK_MATT           -- 지적사항
             , p_MA_RSLT            -- 조치결과
             , p_IMPRV_DT           -- 개선일자
             , p_PHOTO_GRP1         -- 첨부파일그룹사진1
             , p_PHOTO_DESC_1       -- 사진설명1
             , p_PHOTO_GRP2         -- 첨부파일그룹사진2
             , p_PHOTO_DESC_2       -- 사진설명2
             , p_WRK_ID             -- 입력ID 
             , SYSDATE()            -- 입력일시
             , p_WRK_IP             -- 입력IP
             , p_WRK_ID             -- 수정ID
             , SYSDATE()            -- 수정일시
             , p_WRK_IP             -- 수정IP
             )
        ;
        
    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 5. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN 
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);
END ;
/

-- PQHA_LBR_CHK_Q (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_LBR_CHK_Q" (
    p_WRK_TP            IN VARCHAR2 DEFAULT 'Q'         -- FLAG(Q)
,   p_SIT_CD            IN VARCHAR2                     -- 현장
,   p_SEARCH_CHK_YM     IN VARCHAR2                     -- 년월
,   p_CHK_SEQ           IN VARCHAR2                     -- 점검순번
,   RTN_CURSOR          OUT SYS_REFCURSOR
) 
IS
    /**************************************************************************************************************************
    COPYRIGHT:    HUMAN PLUS
    PROCEDURE:    [PQHA_LBR_CHK_Q] PROCEDRE
    설명     :    [QSE > 안전관리 > 안전서류관리 > 노사합동점검관리 목록  조회] 프로시저

     개정일자                      변경내용요약                                 관련근거
    ---------------------------------------------------------------------------------------------------------------------------
     2023-11-28   HUMANPLUS        신규
    ***************************************************************************************************************************/


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009 ; --ERROR 코드
    ERR_MSG        VARCHAR2(200)   ; --ERROR Message
    USER_EXCEPTION EXCEPTION       ;

BEGIN
    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 수행전 Check Logic ]
    ---------------------------------------------------------------------------------------------------------------------------


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Logic 처리
    ---------------------------------------------------------------------------------------------------------------------------

    -- 노사합동점검관리 목록 조회
    IF p_WRK_TP = 'Q' THEN

        OPEN RTN_CURSOR FOR
        SELECT A.SIT_CD                 -- 현장코드
             , A.CHK_SEQ                -- 점검순번
             , A.CHK_DT                 -- 점검일자
             , A.LBR_PSN                -- 근로자
             , A.LBR_USR                -- 사용자
             , A.IMPTC_MATT             -- 중요사항
             , A.CORR_RSLT              -- 시정조치결과
             , A.ETC_MATT               -- 기타사항
             , A.SAFT_OPIN              -- 안전관리자 의견
             , A.SITE_OPIN              -- 현장소장 의견
             , A.PHOTO_GRP1             -- 첨부사진 1
             , A.PHOTO_DESC_1           -- 첨부사진 명칭1
             , A.PHOTO_GRP2             -- 첨부사진 2
             , A.PHOTO_DESC_2           -- 첨부사진 명칭2
             , A.ATFL_GRP               -- 첨부파일 그룹
             , A.APRV_NO                -- 공통코드 QS031 결재번호
             , ( SELECT CD_NM FROM TCOA_COMCODE WHERE COM_CD = B.APRV_STATS AND HRNK_CD = 'QS031') AS APRV_STATS_NM  -- 결재진행상태
             , B.APRV_STATS
          FROM TQHA_LBR_CHK     A
          LEFT JOIN TQHA_APRV   B ON A.SIT_CD   = B.SIT_CD
                                 AND A.APRV_NO  = B.APRV_NO
         WHERE A.SIT_CD = p_SIT_CD
           AND (SUBSTR(A.CHK_DT, 1, 6) = p_SEARCH_CHK_YM OR NVL(p_SEARCH_CHK_YM, 0) = 0)
         ORDER BY A.CHK_DT DESC
        ;

    ELSIF p_WRK_TP = 'Q1' THEN

        OPEN RTN_CURSOR FOR
        SELECT A.SIT_CD                 -- 현장코드
             , A.CHK_SEQ                -- 점검순번
             , A.CHK_DT                 -- 점검일자
             , A.LBR_PSN                -- 근로자
             , A.LBR_USR                -- 사용자
             , A.IMPTC_MATT             -- 중요사항
             , A.CORR_RSLT              -- 시정조치결과
             , A.ETC_MATT               -- 기타사항
             , A.SAFT_OPIN              -- 안전관리자 의견
             , A.SITE_OPIN              -- 현장소장 의견
             , A.PHOTO_GRP1             -- 첨부사진 1
             , A.PHOTO_DESC_1           -- 첨부사진 명칭1
             , A.PHOTO_GRP2             -- 첨부사진 2
             , A.PHOTO_DESC_2           -- 첨부사진 명칭2
             , A.ATFL_GRP               -- 첨부파일 그룹
             , A.APRV_NO                -- 공통코드 QS031 결재번호
             , B.APRV_STATS             -- 결재상태
             , '▶ 결재상태 : ' || NVL(( SELECT CD_NM FROM TCOA_COMCODE WHERE HRNK_CD = 'QS031' AND COM_CD = B.APRV_STATS ), '-') AS APRV_STATS_NM -- 결재상태명
          FROM TQHA_LBR_CHK A
          LEFT JOIN TQHA_APRV B
            ON A.SIT_CD     = B.SIT_CD
           AND A.APRV_NO    = B.APRV_NO
         WHERE A.SIT_CD     = p_SIT_CD
           AND A.CHK_SEQ    = p_CHK_SEQ
        ;

    ELSIF p_WRK_TP = 'Q2' THEN

        OPEN RTN_CURSOR FOR
        SELECT B.SIT_CD                 -- 현장코드
             , B.CHK_SEQ                -- 점검순번
             , B.CHK_CD                 -- 점검코드(공통코드 QS027)
             , B.CHK_MATT               -- 지적사항
             , B.MA_RSLT                -- 조치결과
             , B.IMPRV_DT               -- 개선일자
             , B.PHOTO_GRP1             -- 첨부파일그룹사진1
             , B.PHOTO_DESC_1           -- 사진설명1
             , B.PHOTO_GRP2             -- 첨부파일그룹사진2
             , B.PHOTO_DESC_2           -- 사진설명2
          FROM TQHA_LBR_CHK A
         INNER JOIN TQHA_LBR_CHK_ITM B
            ON A.SIT_CD = B.SIT_CD
           AND A.CHK_SEQ = B.CHK_SEQ
         WHERE B.SIT_CD = p_SIT_CD
           AND B.CHK_SEQ = p_CHK_SEQ
        ;

    END IF;


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);

END ;
/

-- PQHA_LBR_CHK_S (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_LBR_CHK_S" (
    p_WRK_TP                VARCHAR2 :='U'                              -- UPDATE FLAG( I: ISNERT, U:UPDATE, D:DELTE)
,   p_WRK_ID                VARCHAR2                                    -- 사용자 ID
,   p_WRK_IP                VARCHAR2                                    -- 사용자 IP
,   p_SIT_CD                TQHA_LBR_CHK.SIT_CD             %TYPE       -- 현장코드
,   p_CHK_SEQ               TQHA_LBR_CHK.CHK_SEQ            %TYPE       -- 점검순번
,   p_CHK_DT                TQHA_LBR_CHK.CHK_DT             %TYPE       -- 점검일자
,   p_LBR_PSN               TQHA_LBR_CHK.LBR_PSN            %TYPE       -- 근로자
,   p_LBR_USR               TQHA_LBR_CHK.LBR_USR            %TYPE       -- 사용자
,   p_IMPTC_MATT            TQHA_LBR_CHK.IMPTC_MATT         %TYPE       -- 중요사항
,   p_CORR_RSLT             TQHA_LBR_CHK.CORR_RSLT          %TYPE       -- 시정조치결과
,   p_ETC_MATT              TQHA_LBR_CHK.ETC_MATT           %TYPE       -- 기타사항
,   p_SAFT_OPIN             TQHA_LBR_CHK.SAFT_OPIN          %TYPE       -- 안전관리자 의견
,   p_SITE_OPIN             TQHA_LBR_CHK.SITE_OPIN          %TYPE       -- 현장소장 의견
,   p_PHOTO_GRP1            TQHA_LBR_CHK.PHOTO_GRP1         %TYPE       -- 첨부파일그룹사진1
,   p_PHOTO_DESC_1          TQHA_LBR_CHK.PHOTO_DESC_1       %TYPE       -- 사진설명1
,   p_PHOTO_GRP2            TQHA_LBR_CHK.PHOTO_GRP2         %TYPE       -- 첨부파일그룹사진2
,   p_PHOTO_DESC_2          TQHA_LBR_CHK.PHOTO_DESC_2       %TYPE       -- 사진설명2
,   p_ATFL_GRP              TQHA_LBR_CHK.ATFL_GRP           %TYPE       -- 첨부파일그룹
,   p_APRV_NO               TQHA_LBR_CHK.APRV_NO            %TYPE       -- 결재번호
,   p_RTN_CHK_SEQ           OUT VARCHAR2)                               -- 리턴변수(점검순번)
IS 
    /**************************************************************************************************************************
      Purpose : 노사합동점검 저장

      REVISIONS
      Ver      Date               Author                  Description
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2021/10/28 11:15:01                         최초생성

    **************************************************************************************************************************/


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR2(200);            -- ERROR Message
    USER_EXCEPTION EXCEPTION;

    v_CHK_SEQ           TQHA_LBR_CHK.CHK_SEQ%TYPE ;     -- 순번 변수 선언
    v_cnt               INTEGER;                        -- 하위 테이블 코드 존재 여부

    v_APRV_STATS        VARCHAR2(20);
    v_APRV_STATS_NM     VARCHAR2(50);

BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 필수입력 필드  Check  ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_SIT_CD IS NULL)  THEN
        ERR_MSG := '현장코드는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_CHK_SEQ IS NULL AND p_WRK_TP <> 'I')  THEN
        ERR_MSG := '점검순번는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_CHK_DT IS NULL)  THEN
        ERR_MSG := '점검일자는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    ---------------------------------------------------------------------
    -- 결재상태 체크
    SELECT MAX(T2.APRV_STATS)
         , MAX(T3.CD_NM )
      INTO v_APRV_STATS
         , v_APRV_STATS_NM
      FROM TQHA_LBR_CHK         T1
      LEFT JOIN TQHA_APRV       T2 ON T1.SIT_CD     = T2.SIT_CD
                                  AND T1.APRV_NO    = T2.APRV_NO
      LEFT JOIN TCOA_COMCODE    T3 ON T2.APRV_STATS = T3.COM_CD
                                  AND T3.HRNK_CD    = 'QS031'
     WHERE T1.SIT_CD    = p_SIT_CD
       AND T1.CHK_SEQ   = p_CHK_SEQ
    ;

    IF v_APRV_STATS IN ('2', '4') THEN
        ERR_MSG := '결재상태 [' || v_APRV_STATS_NM || ']인 데이터는 수정 불가합니다.';
        RAISE USER_EXCEPTION;
    END IF;

    ---------------------------------------------------------------------
    --  하위 노사합동점검ㅍ표 존재 여부 확인
    IF p_WRK_TP = 'D' THEN

        SELECT nvl(COUNT(CHK_CD),0)
          INTO v_cnt
          FROM TQHA_LBR_CHK_ITM
         WHERE SIT_CD = p_SIT_CD
           AND CHK_SEQ = p_CHK_SEQ
        ;

         -- 노사합동점검표  Validation
        IF v_cnt > 0 THEN
            ERR_MSG := '점검항목 해당일자  "' || p_CHK_DT || '" 은(는) 하위 노사합동점검표 데이타가 존재합니다. 하위 노사합동점검표 데이타를 전부 삭제해야 삭제할 수 있습니다. ';
            RAISE USER_EXCEPTION;
        END IF;

    END IF;
    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Process 선행조건 Check ]
    ---------------------------------------------------------------------------------------------------------------------------



    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Business Process ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_WRK_TP ='D') THEN

        DELETE
          FROM TQHA_LBR_CHK
         WHERE SIT_CD = p_SIT_CD        -- 현장코드
           AND CHK_SEQ = p_CHK_SEQ      -- 점검순번
        ;

        v_CHK_SEQ := p_CHK_SEQ;

    ELSIF (p_WRK_TP ='U') THEN

        UPDATE TQHA_LBR_CHK
           SET CHK_DT               = p_CHK_DT              --점검일자
             , LBR_PSN              = p_LBR_PSN             --근로자
             , LBR_USR              = p_LBR_USR             --사용자
             , IMPTC_MATT           = p_IMPTC_MATT          --중요사항
             , CORR_RSLT            = p_CORR_RSLT           --시정조치결과
             , ETC_MATT             = p_ETC_MATT            --기타사항
             , SAFT_OPIN            = p_SAFT_OPIN           --안전관리자 의견
             , SITE_OPIN            = p_SITE_OPIN           --현장소장 의견
             , PHOTO_GRP1           = p_PHOTO_GRP1          --첨부파일그룹사진1
             , PHOTO_DESC_1         = p_PHOTO_DESC_1        --사진설명1
             , PHOTO_GRP2           = p_PHOTO_GRP2          --첨부파일그룹사진2
             , PHOTO_DESC_2         = p_PHOTO_DESC_2        --사진설명2
             , ATFL_GRP             = p_ATFL_GRP            --첨부파일그룹
             , APRV_NO              = p_APRV_NO             --결재번호
             , UPD_ID               = p_WRK_ID              --수정ID
             , UPD_DTM              = SYSDATE()             --수정일시
             , UPD_IP               = p_WRK_IP              --수정IP
         WHERE SIT_CD               = p_SIT_CD              --현장코드
           AND CHK_SEQ              = p_CHK_SEQ             --점검순번
        ;

        v_CHK_SEQ := p_CHK_SEQ;

    ELSE

        -- 합동점검순번 생성
        SELECT NVL( (MAX(CHK_SEQ)+1),'1' )
          INTO v_CHK_SEQ
          FROM TQHA_LBR_CHK
         WHERE SIT_CD = p_SIT_CD;         --현장코드

        --
        INSERT
          INTO TQHA_LBR_CHK
             ( SIT_CD                   -- 현장코드
             , CHK_SEQ                  -- 점검순번
             , CHK_DT                   -- 점검일자
             , LBR_PSN                  -- 근로자
             , LBR_USR                  -- 사용자
             , IMPTC_MATT               -- 중요사항
             , CORR_RSLT                -- 시정조치결과
             , ETC_MATT                 -- 기타사항
             , SAFT_OPIN                -- 안전관리자 의견
             , SITE_OPIN                -- 현장소장 의견
             , PHOTO_GRP1               -- 첨부파일그룹사진1
             , PHOTO_DESC_1             -- 사진설명1
             , PHOTO_GRP2               -- 첨부파일그룹사진2
             , PHOTO_DESC_2             -- 사진설명2
             , ATFL_GRP                 -- 첨부파일그룹
             , APRV_NO                  -- 결재번호
             , IPT_ID                   -- 입력ID
             , IPT_DTM                  -- 입력일시
             , IPT_IP                   -- 입력IP
             , UPD_ID                   -- 수정ID
             , UPD_DTM                  -- 수정일시
             , UPD_IP                   -- 수정IP
             )
        VALUES
             ( p_SIT_CD                 -- 현장코드
             , v_CHK_SEQ                -- 점검순번
             , p_CHK_DT                 -- 점검일자
             , p_LBR_PSN                -- 근로자
             , p_LBR_USR                -- 사용자
             , p_IMPTC_MATT             -- 중요사항
             , p_CORR_RSLT              -- 시정조치결과
             , p_ETC_MATT               -- 기타사항
             , p_SAFT_OPIN              -- 안전관리자 의견
             , p_SITE_OPIN              -- 현장소장 의견
             , p_PHOTO_GRP1             -- 첨부파일그룹사진1
             , p_PHOTO_DESC_1           -- 사진설명1
             , p_PHOTO_GRP2             -- 첨부파일그룹사진2
             , p_PHOTO_DESC_2           -- 사진설명2
             , p_ATFL_GRP               -- 첨부파일그룹
             , p_APRV_NO                -- 결재번호
             , p_WRK_ID                 -- 입력ID
             , SYSDATE()                -- 입력일시
             , p_WRK_IP                 -- 입력IP
             , p_WRK_ID                 -- 수정ID
             , SYSDATE()                -- 수정일시
             , p_WRK_IP                 -- 수정IP
             )
        ;

        -- 점검표 생성
        INSERT
          INTO TQHA_LBR_CHK_ITM
             ( SIT_CD                   -- 현장코드
             , CHK_SEQ                  -- 점검순번
             , CHK_CD                   -- 노사합동점검표 구분(QS027) 1 개인보호구 적정지급
             , IPT_ID                   -- 입력ID
             , IPT_DTM                  -- 입력일시
             , IPT_IP                   -- 입력IP
             , UPD_ID                   -- 수정ID
             , UPD_DTM                  -- 수정일시
             , UPD_IP                   -- 수정IP
             )
        VALUES
             ( p_SIT_CD                 -- 현장코드
             ,v_CHK_SEQ                 -- 점검순번
             ,1                         -- 노사합동점검표 구분(QS027) 1 개인보호구 적정지급
             ,p_WRK_ID                  -- 입력ID
             ,SYSDATE()                 -- 입력일시
             ,p_WRK_IP                  -- 입력IP
             ,p_WRK_ID                  -- 수정ID
             ,SYSDATE()                 -- 수정일시
             ,p_WRK_IP                  -- 수정IP
             )
        ;

    END IF;

    p_RTN_CHK_SEQ := v_CHK_SEQ;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 5. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);
            
END ;
/

-- PQHA_MAIN_MNG_ITM_REG_OTHER_Q (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_MAIN_MNG_ITM_REG_OTHER_Q" (
    p_WRK_TP            IN VARCHAR2 DEFAULT 'Q'         -- FLAG
,   p_SIT_CD            IN VARCHAR2                     -- 현장코드
,   p_PLN_YM            IN VARCHAR2                     -- 계획연월
,   p_PLN_DGR           IN VARCHAR2                     -- 계획차수
,   RTN_CURSOR          OUT SYS_REFCURSOR
)
IS
    /**************************************************************************************************************************
      Purpose : [중점점검관리  ] PROCEDRE 

      REVISIONS
      Ver      Date               Author                  Description
      -------  -----------------  ----------------------  ---------------------------------------------------------------------
      1.0      2026/02/09                                 최초생성

    **************************************************************************************************************************/

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE  NUMBER :=-20009; -- ERROR 코드
    ERR_MSG   VARCHAR(200);    -- ERROR Message
    USER_EXCEPTION EXCEPTION;

BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 수행전 Check Logic ]
    ---------------------------------------------------------------------------------------------------------------------------

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Logic 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------

    ---------------------------------------------------------------------------------------
    -- 
    IF p_WRK_TP = 'Q1' THEN

        -- 조회조건 조회 : 계획년월
        OPEN RTN_CURSOR FOR
        SELECT MAX(A.PLN_YM) AS PLN_YM    -- 계획년월
          FROM TQHA_RISK_DGR A
         WHERE A.SIT_CD     = p_SIT_CD
        ;

    ---------------------------------------------------------------------------------------
    ELSIF p_WRK_TP = 'Q2' THEN

        -- 조회조건 조회 : 계획차수 
        OPEN RTN_CURSOR FOR
        SELECT MAX(A.PLN_DGR) AS PLN_DGR    -- 계획년월
          FROM TQHA_RISK_DGR A
         WHERE A.SIT_CD     = p_SIT_CD
           AND A.PLN_YM     = p_PLN_YM
        ;

    ---------------------------------------------------------------------------------------
    ELSIF p_WRK_TP = 'Q3' THEN

        OPEN RTN_CURSOR FOR
        SELECT APRS_STR_DT    -- 평가시작일
             , APRS_END_DT    -- 평가종료일
          FROM TQHA_RISK_DGR A
         WHERE A.SIT_CD     = p_SIT_CD
           AND A.PLN_YM     = p_PLN_YM
           AND A.PLN_DGR    = p_PLN_DGR
        ;

    ---------------------------------------------------------------------------------------
    ELSIF p_WRK_TP = 'Q4' THEN

        OPEN RTN_CURSOR FOR
        SELECT A.SIT_CD
             , A.PLN_YM
             , A.PLN_DGR
             , A.CUST_CD
             , ( SELECT CUST_NM FROM VQSZ_TRADE WHERE CUST_CD = A.CUST_CD ) AS VNDR_NM
             , A.VNDR_SEQ
             , B.SBM_YN
             , DECODE( B.SBM_YN, '1', '제출', '작성중' ) SBM_NM 
             , B.SBM_DT
             , B.SAFT_APRV_STATS
             , DECODE( B.SAFT_APRV_STATS, '1', '승인완료', '2', '반려', '진행중' ) AS SAFT_APRV_STATS_NM
             , B.SAFT_APRV_DT
          FROM ( -- 위험성 평가 제출 리스트
                 SELECT SIT_CD
                      , PLN_YM 
                      , PLN_DGR
                      , CUST_CD
                      , VNDR_SEQ
                   FROM TQHA_RISK_CHK
                  WHERE SIT_CD      = p_SIT_CD
                    AND PLN_YM      = p_PLN_YM
                    AND PLN_DGR     = p_PLN_DGR
                  GROUP BY SIT_CD, PLN_YM, PLN_DGR, CUST_CD, VNDR_SEQ
--                  MINUS
--                 -- 협의체 회의 제출 리스트
--                 SELECT SIT_CD
--                      , PLN_YM
--                      , PLN_DGR
--                      , CUST_CD
--                      , VNDR_SEQ
--                   FROM TQSA_RISK_AREC
--                  WHERE SIT_CD      = p_SIT_CD
--                    AND PLN_YM      = p_PLN_YM
--                    AND PLN_DGR     = p_PLN_DGR
--                  GROUP BY SIT_CD, PLN_YM, PLN_DGR, CUST_CD, VNDR_SEQ
               ) A
             , TQHA_RISK_VNDR B 
         WHERE A.SIT_CD = B.SIT_CD
           AND A.PLN_YM = B.PLN_YM
           AND A.PLN_DGR = B.PLN_DGR
           AND A.CUST_CD = B.CUST_CD
           AND A.VNDR_SEQ = B.VNDR_SEQ
           AND B.SBM_YN = '1'
        ;

    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
         WHEN OTHERS THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);

END PQHA_MAIN_MNG_ITM_REG_OTHER_Q;
/

-- PQHA_MEET_DRFT_OTHER_Q (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_MEET_DRFT_OTHER_Q" (
    p_WRK_TP            IN VARCHAR2 DEFAULT 'Q'         -- FLAG
,   p_SIT_CD            IN VARCHAR2                     -- 현장코드
,   p_PLN_YM            IN VARCHAR2                     -- 계획연월
,   p_PLN_DGR           IN VARCHAR2                     -- 계획차수
,   RTN_CURSOR          OUT SYS_REFCURSOR
)
IS
    /**************************************************************************************************************************
      Purpose : [위험성평가회의 ] PROCEDRE 

      REVISIONS
      Ver      Date               Author                  Description
      -------  -----------------  ----------------------  ---------------------------------------------------------------------
      1.0      2026/02/09                                 최초생성

    **************************************************************************************************************************/

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE  NUMBER :=-20009; -- ERROR 코드
    ERR_MSG   VARCHAR(200);    -- ERROR Message
    USER_EXCEPTION EXCEPTION;

BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 수행전 Check Logic ]
    ---------------------------------------------------------------------------------------------------------------------------

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Logic 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------

    ---------------------------------------------------------------------------------------
    -- 
    IF p_WRK_TP = 'Q1' THEN

        -- 그리드 조회 : 위험성평가 회의록 작성목록 - 협력업체목록
        OPEN RTN_CURSOR FOR
        SELECT A.SIT_CD                   --현장코드
             , A.PLN_YM                   --계획년월
             , A.PLN_DGR                  --계획차수
             , ( SELECT CD_NM FROM TCOA_COMCODE WHERE COM_CD = A.PLN_DGR AND HRNK_CD = 'QS005') AS PLN_DGR_NM  -- 계획차수명칭
             , A.CUST_CD                  --협력업체코드
             , A.VNDR_SEQ                 --협력업체차수
             , B.CUST_NM                  --협력업체명칭
             , A.SBM_YN                   --평가서제출여부
             , DECODE(NVL(A.SBM_YN,0), '1', '제출', '작성중') AS SBM_NM -- 제출여부명칭
             , A.SBM_DT                   --평가서제출일자
             , A.MNG_SUPR                 --관리감독자
             , ( SELECT USR_NM FROM TCOZ_USR_INFO WHERE USR_ID = A.MNG_SUPR ) AS MNG_SUPR_NM -- 관리감독자명
             , A.MNG_APRV_STATS           --관리감독자 승인상태(1승인, 2반려)
             , DECODE(NVL(A.SBM_YN,0), '1', DECODE(NVL(A.MNG_APRV_STATS,0), '1', '승인완료 ', DECODE(NVL(A.MNG_APRV_STATS,0), '2', '반려 ', '진행중')), '0', DECODE(NVL(A.MNG_APRV_STATS,0), '2', '반려 ', ''), '' ) AS MNG_APRV_STATS_NM -- 관리상태명칭
             , A.MNG_APRV_DT              --관리감독자 승인일자
             , A.SAFT_MGR                 --안전관리자
             , ( SELECT USR_NM FROM TCOZ_USR_INFO WHERE USR_ID = A.SAFT_MGR ) AS SAFT_MGR_NM -- 안전관리자명
             , A.SAFT_APRV_STATS          --안전관리자 승인상태(1승인 2반려)
             , DECODE(NVL(A.MNG_APRV_STATS,0), '1', DECODE(NVL(A.SAFT_APRV_STATS,0), '1', '승인완료 ', DECODE(NVL(A.SAFT_APRV_STATS,0), '2', '반려 ', '진행중')), '0', DECODE(NVL(A.SAFT_APRV_STATS,0), '1','승인', '2', '반려 ', ''), '' ) AS SAFT_APRV_STATS_NM -- 안전상태명칭
             , A.SAFT_APRV_DT             --안전관리자 승인일자
             , A.SITE_OMGR                --현장소장
             , ( SELECT USR_NM FROM TCOZ_USR_INFO WHERE USR_ID = A.SITE_OMGR ) AS SITE_OMGR_NM -- 현장소장명
             , A.SITE_APRV_STATS          --현장소장 승인상태(1승인, 2반려)
             , DECODE(NVL(A.SAFT_APRV_STATS,0), '1', DECODE(NVL(A.SITE_APRV_STATS,0), '1', '승인완료 ', DECODE(NVL(A.SITE_APRV_STATS,0), '2', '반려 ', '진행중')), '0', DECODE(NVL(A.SITE_APRV_STATS,0), '2', '반려 ', ''), '' ) AS SITE_APRV_STATS_NM -- 소장상태명칭
             , A.SITE_APRV_DT             --현장소장 승인일자
             , A.VNDR_WRK_NM
          FROM TQHA_RISK_VNDR A
             , VQSZ_TRADE B
         WHERE A.CUST_CD    = B.CUST_CD 
           AND A.SIT_CD     = p_SIT_CD
           AND A.PLN_YM     = p_PLN_YM
           AND A.PLN_DGR    = p_PLN_DGR
           AND A.OBJ_YN     = '1'
        ;

    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
         WHEN OTHERS THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);

END PQHA_MEET_DRFT_OTHER_Q;
/

-- PQHA_MIGRATION_IDAC_B (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_MIGRATION_IDAC_B" -- 산재 3년치 결재처리 
                            (p_WRK_TP  VARCHAR2 :='I' )                                    -- UPDATE FLAG( I: ISNERT, U:UPDATE, D:DELTE)
                            
IS
    /**************************************************************************************************************************
      Purpose : 산재 저누 데이타 결재처리

      REVISIONS
      Ver      Date               Author                  Description
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2024/12/04 12:51:10 이봉                                     최초생성

    /**************************************************************************************************************************/
    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR(200);             -- ERROR Message

    USER_EXCEPTION EXCEPTION; 

    v_APRV_NO VARCHAR(20);  -- 그룹웨어 결재번호 

BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 필수입력 필드  Check  ]
    ---------------------------------------------------------------------------------------------------------------------------

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Process 선행조건 Check ]
    ---------------------------------------------------------------------------------------------------------------------------


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Business Process ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_WRK_TP = 'I') THEN 



 /****  -- 산재 데이타 3년치 ******/  
        BEGIN
            FOR MIG_IDAC IN (  -- 산재 3년치
                            SELECT SIT_CD, ACCD_SEQ 
					          FROM TQHA_IDAC 
     						 where substr(to_char(IPT_DTM,'yyyymmdd'),1,8) = '20241231'    -- 데이타이관용
   			               ORDER BY ACCD_SEQ )
            LOOP
/*
              -- 데이아 insert  후 한번만 수행 ( 개인정보 암호화 처리 )
                 UPDATE  TQHA_IDAC
                   SET   IPT_DTM       = SYSDATE 
                 WHERE SITE_CD = MIG_IDAC.SITE_CD
                   AND ACCD_SEQ = MIG_IDAC.ACCD_SEQ ;
*/                   

	            -- 산재 결제(현장/ 본사) 생성
		        -- 산재결재(현장)
		        INSERT INTO TQHA_IDAC_APRV
		                  ( SIT_CD    --현장코드
		                  , ACCD_SEQ   --사고순번
		                  , APRV_DIV   --결재구분 (1:현장, 2:본사)
		                  , APRV_NO    --결재번호
		                  )
		           VALUES ( MIG_IDAC.SIT_CD
		                  , MIG_IDAC.ACCD_SEQ
		                  , '1'
                          , MIG_IDAC.ACCD_SEQ		        
		                  --20241230 데이타 이관 된 결재번호                          
--                          ,'0'       -- 이관된 결재 번호(현장 데이타 이관 된 결재번호)		                  
		                  );

                 -- 산재결재(본사)
		        INSERT INTO TQHA_IDAC_APRV
		                  ( SIT_CD    --현장코드
		                  , ACCD_SEQ   --사고순번
		                  , APRV_DIV   --결재구분 (1:현장, 2:본사)
		                  , APRV_NO    --결재번호
		                  )
		           VALUES ( MIG_IDAC.SIT_CD
		                  , MIG_IDAC.ACCD_SEQ
		                  , '2'
		                  , '0'       -- 이관된 결재 번호(그룹웨어 데이타 이관 된 결재번호)
		                  );

		        -- 산재결재(현장) - 결재완료 처리
		        INSERT INTO TQHA_APRV
		                  ( SIT_CD     --현장코드
		                  , APRV_NO    --결재순번
		                  , APRV_STATS --결재구분 (4:완료)
		                  )
		           VALUES ( MIG_IDAC.SIT_CD
		                  , MIG_IDAC.ACCD_SEQ
		                  , '4'
		                  );


			END LOOP;		        
		END ;        
    END IF ;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 5. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN 
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);
END;
/

-- PQHA_MMEDUPLAN_Q (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_MMEDUPLAN_Q" (
    p_WRK_TP            IN VARCHAR2 DEFAULT 'Q'                     -- FLAG
,   p_SIT_CD            IN TQHA_MMEDUPLAN.SIT_CD    %TYPE           -- 현장코드
,   p_YM                IN VARCHAR2                                 -- 조회년월
,   p_STR_DT            IN VARCHAR2                                 -- 조회시작일
,   p_END_DT            IN VARCHAR2                                 -- 조회종료일
,   RTN_CURSOR          OUT SYS_REFCURSOR
)
IS
    /**************************************************************************************************************************
      Purpose : [안전보건활동계획 조회] PROCEDRE (QSE > 안전보건계획 > 안전보건활동계획 )

      REVISIONS
      Ver      Date               Author                  Description
      -------  -----------------  ----------------------  ---------------------------------------------------------------------
      1.0      XXXX/XX/XX                                 최초생성

    **************************************************************************************************************************/

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE  NUMBER :=-20009; -- ERROR 코드
    ERR_MSG   VARCHAR(200);    -- ERROR Message
    USER_EXCEPTION EXCEPTION;

BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 수행전 Check Logic ]
    ---------------------------------------------------------------------------------------------------------------------------

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Logic 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------

    -------------------------------------------------------------------------------------------------------------------------
    -- 안전보건활동계획 목록 조회.
    IF p_WRK_TP = 'Q' THEN

        OPEN RTN_CURSOR FOR
        SELECT AA.SIT_CD
             , AA.DIV
             , AA.STR_DT
             , AA.END_DT
             , AA.CTS
             , AA.DIV_NM
             , '[' || AA. DIV_NM || '] ' || AA.CTS AS LABEL
             , AA.ACY_EDU_SEQ
             , NVL((
                   SELECT CHRC_VAL_1
                     FROM TCOA_COMCODE
                    WHERE 1=1
                      AND USE_YN    = '1'
                      AND HRNK_CD   = 'QSC01'
                      AND COM_CD    = AA.DIV
               ), '') AS COLOR
          FROM (SELECT SIT_CD
                     , DIV
                     , (SELECT CD_NM
                          FROM TCOA_COMCODE
                         WHERE COM_CD = DIV
                       ) AS DIV_NM
                     , STR_DT
                     , END_DT
                     , CTS
                     , ACY_EDU_SEQ
                  FROM TQHA_MMEDUPLAN
                 WHERE SIT_CD      = p_SIT_CD
                   AND STR_DT      LIKE p_YM || '%'
                 GROUP BY SIT_CD, ACY_EDU_SEQ, DIV , STR_DT, END_DT, CTS
                 ORDER BY SIT_CD, STR_DT, END_DT, DIV
               ) AA
        ;

    -------------------------------------------------------------------------------------------------------------------------
    -- 안전보건활동현황 목록 조회.
    ELSIF p_WRK_TP = 'Q2' THEN

        OPEN RTN_CURSOR FOR
        SELECT MP.SIT_CD                -- 현장코드
             , MP.STR_DT                -- 시작일자
             , MP.END_DT                -- 종료일자
             , MP.DIV                   -- 교육,활동
             , MP.CTS                   -- 내용
             , MP.RMKS                  -- 비고
             , CC.CD_NM                 -- 구분명
             , SI.SIT_NM                -- 현장명
          FROM TQHA_MMEDUPLAN MP
              ,TCMZ_SIT SI
              ,TCOA_COMCODE CC
         WHERE MP.SIT_CD        = NVL(p_SIT_CD, MP.SIT_CD)
           AND MP.SIT_CD        = SI.SIT_CD
           AND CC.HRNK_CD       = 'QSC01'
           AND MP.DIV           = CC.COM_CD
           AND SUBSTR(REPLACE(STR_DT,'-',''),0,6) >= REPLACE(p_STR_DT,'-','')
           AND SUBSTR(REPLACE(END_DT,'-',''),0,6) <= REPLACE(p_END_DT,'-','')
         ORDER BY STR_DT DESC, SIT_CD ASC
        ;

    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
         WHEN OTHERS THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);

END PQHA_MMEDUPLAN_Q;
/

-- PQHA_MOBILE_ADDRISK_S (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_MOBILE_ADDRISK_S" (
	    p_WRK_TP                    VARCHAR2 :='U'                                          -- 작업구분(신규:I, 조치전:U, 조치:CMP, 조치취소:CNC)
	,   p_WRK_ID                    VARCHAR2                                                -- 사용자 ID
	,   p_WRK_IP                    VARCHAR2                                                -- 사용자 IP
	,   p_SIT_CD                    TQHA_ADDRISK_ORD.SIT_CD                     %TYPE       -- 현장코드
	,   p_WRT_DT                    TQHA_ADDRISK_ORD.WRT_DT                     %TYPE       -- 작성일자
	,   p_WRT_SEQ                   TQHA_ADDRISK_ORD.WRT_SEQ                    %TYPE       -- 작성순번
	-- 신규
	,   p_MA_DDLN_DT                TQHA_ADDRISK_ORD.MA_DDLN_DT                 %TYPE       -- 조치기한일자
	,   p_CUST_CD                   TQHA_ADDRISK_ORD.CUST_CD                    %TYPE       -- 업체코드
	,   p_VNDR_SEQ                  TQHA_ADDRISK_ORD.VNDR_SEQ                   %TYPE       -- 업체순번
	,   p_CTP_CD                    TQHA_ADDRISK_ORD.CTP_CD                     %TYPE       -- 공종코드
	,   p_RISK_LOC                  TQHA_ADDRISK_ORD.RISK_LOC                   %TYPE       -- 위험위치
	,   p_RISK_CTS                  TQHA_ADDRISK_ORD.RISK_CTS                   %TYPE       -- 위험내용
	,   p_REQ_MATT                  TQHA_ADDRISK_ORD.REQ_MATT                   %TYPE       -- 요구사항
	--조치전 사진
	,   p_PHOTO_GRP1                TQHA_ADDRISK_ORD.PHOTO_GRP1                 %TYPE       -- 첨부파일그룹사진1
	,   p_PHOTO_DESC_1              TQHA_ADDRISK_ORD.PHOTO_DESC_1               %TYPE       -- 사진설명1
	,   p_PHOTO_GRP2                TQHA_ADDRISK_ORD.PHOTO_GRP2                 %TYPE       -- 첨부파일그룹사진2
	,   p_PHOTO_DESC_2              TQHA_ADDRISK_ORD.PHOTO_DESC_2               %TYPE       -- 사진설명2
	--조치후 작업
	,   p_VNDR_MA_DT                TQHA_ADDRISK_ORD.VNDR_MA_DT                 %TYPE       -- 업체조치일자
	,   p_VNDR_MA_PSN               TQHA_ADDRISK_ORD.VNDR_MA_PSN                %TYPE       -- 업체조치자
	,   p_VNDR_MA_CTS               TQHA_ADDRISK_ORD.VNDR_MA_CTS                %TYPE       -- 업체조치내용
	,   p_VNDR_PHOTO_GRP1           TQHA_ADDRISK_ORD.VNDR_PHOTO_GRP1            %TYPE       -- 업체조치첨부파일그룹사진1
	,   p_VNDR_PHOTO_DESC_1         TQHA_ADDRISK_ORD.VNDR_PHOTO_DESC_1          %TYPE       -- 사진설명1
	,   p_VNDR_PHOTO_GRP2           TQHA_ADDRISK_ORD.VNDR_PHOTO_GRP2            %TYPE       -- 업체조치첨부파일그룹사진2
	,   p_VNDR_PHOTO_DESC_2         TQHA_ADDRISK_ORD.VNDR_PHOTO_DESC_2          %TYPE       -- 사진설명2
	,   p_RNT_WRT_SEQ               OUT VARCHAR2)                                           -- 리턴변수(작성순번)
IS
    /**************************************************************************************************************************
      Purpose :

      REVISIONS
      Ver      Date               Author                  Description
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2021/11/05 14:17:07                         최초생성

    **************************************************************************************************************************/


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR2(200);            -- ERROR Message
    USER_EXCEPTION EXCEPTION;

    v_EXISTS_YN        VARCHAR2(1)     ; --존재여부
    v_WRT_SEQ TQHA_ADDRISK_ORD.WRT_SEQ%TYPE ;             -- 순번 변수 선언

BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 필수입력 필드  Check  ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_SIT_CD IS NULL)  THEN
        ERR_MSG := '현장코드는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_WRT_DT IS NULL)  THEN
        ERR_MSG := '작성일자는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;
    
    --신규 제외
	IF (p_WRK_TP <> 'I') THEN
	    IF (p_WRT_SEQ IS NULL)  THEN
	        ERR_MSG := '작성순번는(은) 필수 입력사항 입니다.';
	        RAISE USER_EXCEPTION;
	    END IF;
    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Process 선행조건 Check ]
    ---------------------------------------------------------------------------------------------------------------------------


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Business Process ]
    ---------------------------------------------------------------------------------------------------------------------------
    --신규등록
    IF (p_WRK_TP ='I') THEN

        -- 순번 생성
        SELECT NVL( (MAX(WRT_SEQ)+1),'1' )
          INTO v_WRT_SEQ
          FROM TQHA_ADDRISK_ORD
         WHERE SIT_CD       = p_SIT_CD      -- 현장코드
           AND WRT_DT       = p_WRT_DT      -- 일자
        ;

        -- 등록
        INSERT
          INTO TQHA_ADDRISK_ORD
             ( SIT_CD           -- 현장코드
			 , WRT_DT           -- 작성일자
			 , WRT_SEQ          -- 작성순번
			 , VNDR_MA_YN       -- 조치구분(QS007) 1 조치, 0 미조치
			 , MA_DDLN_DT       -- 조치기한일자
			 , CUST_CD          -- 업체코드
			 , VNDR_SEQ         -- 업체순번
			 , CTP_CD           -- 공종코드
			 , RISK_LOC         -- 위험위치
			 , RISK_CTS         -- 위험내용
			 , REQ_MATT         -- 요구사항
			 , PHOTO_GRP1       -- 첨부파일그룹사진1
			 , PHOTO_DESC_1     -- 사진설명1
			 , PHOTO_GRP2       -- 첨부파일그룹사진2
			 , PHOTO_DESC_2     -- 사진설명2
             , ADD_WRTR         -- 작성자
             , IPT_ID           -- 입력ID
             , IPT_DTM          -- 입력일시
             , IPT_IP           -- 입력IP
             , UPD_ID           -- 수정ID
             , UPD_DTM          -- 수정일시
             , UPD_IP           -- 수정IP
             )
        VALUES
             ( p_SIT_CD                 -- 현장코드
             , p_WRT_DT                 -- 작성일자
             , v_WRT_SEQ                -- 작성순번
             , '2'                      -- 조치구분(QS007) 1 조치, 0 미조치
             , p_MA_DDLN_DT             -- 조치기한일자
             , p_CUST_CD                -- 업체코드
             , p_VNDR_SEQ               -- 업체순번
             , p_CTP_CD                 -- 공종코드
             , p_RISK_LOC               -- 위험위치
             , p_RISK_CTS               -- 위험내용
             , p_REQ_MATT               -- 요구사항
             , p_PHOTO_GRP1             -- 첨부파일그룹사진1
             , p_PHOTO_DESC_1           -- 사진설명1
             , p_PHOTO_GRP2             -- 첨부파일그룹사진2
             , p_PHOTO_DESC_2           -- 사진설명2
             , p_WRK_ID                 -- 작성자
             , p_WRK_ID                 -- 입력ID
             , SYSDATE()                -- 입력일시
             , p_WRK_IP                 -- 입력IP
             , p_WRK_ID                 -- 수정ID
             , SYSDATE()                -- 수정일시
             , p_WRK_IP                 -- 수정IP
             )
        ;
    --조치전
    ELSIF (p_WRK_TP = 'U') THEN
    
    	UPDATE TQHA_ADDRISK_ORD
           SET PHOTO_GRP1               = p_PHOTO_GRP1              -- 첨부파일그룹사진1
             , PHOTO_DESC_1             = p_PHOTO_DESC_1            -- 사진설명1
             , PHOTO_GRP2               = p_PHOTO_GRP2              -- 첨부파일그룹사진2
             , PHOTO_DESC_2             = p_PHOTO_DESC_2            -- 사진설명2
             , UPD_ID                   = p_WRK_ID                  -- 수정ID
             , UPD_DTM                  = SYSDATE()                 -- 수정일시
             , UPD_IP                   = p_WRK_IP                  -- 수정IP
         WHERE SIT_CD                   = p_SIT_CD                  --현장코드
           AND WRT_DT                   = p_WRT_DT                  --작성일자
           AND WRT_SEQ                  = p_WRT_SEQ                 --작성순번
        ;

        v_WRT_SEQ := p_WRT_SEQ;
    --조치
    ELSIF (p_WRK_TP = 'CMP') THEN
    
	    --조치처리여부 체크
	    SELECT CASE WHEN EXISTS (--존재여부 SELECT
	                             SELECT '1' 
	                               FROM TQHA_ADDRISK_ORD
                                  WHERE SIT_CD        = p_SIT_CD     -- 현장코드
           							AND WRT_DT        = p_WRT_DT     -- 작성일자
           							AND WRT_SEQ       = p_WRT_SEQ    -- 작성순번
           							AND VNDR_MA_YN    = '1'          -- 조치구분(QS007) 1 조치, 0 미조치
	                            )
	                THEN '1'
	                ELSE '0' 
	                END
	      INTO v_EXISTS_YN
	      FROM DUAL;
	    
	    IF v_EXISTS_YN = '1' THEN
	        ERR_MSG := '조치가 완료된 건 입니다. 조치취소 후 다시 시도해주세요.';
	        RAISE USER_EXCEPTION;
	    END IF;
    
    
        UPDATE TQHA_ADDRISK_ORD
           SET VNDR_MA_YN               = '1'                       -- 조치구분(QS007) 1 조치, 2 미조치
             , VNDR_MA_DT               = p_VNDR_MA_DT              -- 업체조치일자
             , VNDR_MA_PSN              = p_VNDR_MA_PSN             -- 업체조치자
             , VNDR_MA_CTS              = p_VNDR_MA_CTS             -- 업체조치내용
             , VNDR_PHOTO_GRP1          = p_VNDR_PHOTO_GRP1         -- 업체조치첨부파일그룹사진1
             , VNDR_PHOTO_DESC_1        = p_VNDR_PHOTO_DESC_1       -- 사진설명1
             , VNDR_PHOTO_GRP2          = p_VNDR_PHOTO_GRP2         -- 업체조치첨부파일그룹사진2
             , VNDR_PHOTO_DESC_2        = p_VNDR_PHOTO_DESC_2       -- 사진설명2
             , UPD_ID                   = p_WRK_ID                  -- 수정ID
             , UPD_DTM                  = SYSDATE()                 -- 수정일시
             , UPD_IP                   = p_WRK_IP                  -- 수정IP
         WHERE SIT_CD                   = p_SIT_CD                  -- 현장코드
           AND WRT_DT                   = p_WRT_DT                  -- 작성일자
           AND WRT_SEQ                  = p_WRT_SEQ                 -- 작성순번
        ;

        v_WRT_SEQ := p_WRT_SEQ;
    -- 조치취소
    ELSIF (p_WRK_TP = 'CNC') THEN
    
	    --조치처리여부 체크
	    SELECT CASE WHEN EXISTS (--존재여부 SELECT
	                             SELECT '1' 
	                               FROM TQHA_ADDRISK_ORD
                                  WHERE SIT_CD        = p_SIT_CD     -- 현장코드
           							AND WRT_DT        = p_WRT_DT     -- 작성일자
           							AND WRT_SEQ       = p_WRT_SEQ    -- 작성순번
           							AND VNDR_MA_YN    = '1'          -- 조치구분(QS007) 1 조치, 2 미조치
	                            )
	                THEN '1'
	                ELSE '0' 
	                END
	      INTO v_EXISTS_YN
	      FROM DUAL;
	    
	    IF v_EXISTS_YN = '0' THEN
	        ERR_MSG := '이미 조치가 취소된 건입니다.';
	        RAISE USER_EXCEPTION;
	    END IF;
    	
        UPDATE TQHA_ADDRISK_ORD
           SET VNDR_MA_YN               = '2'                       -- 조치구분(QS007) 1 조치, 2 미조치
             , UPD_ID                   = p_WRK_ID                  -- 수정ID
             , UPD_DTM                  = SYSDATE()                 -- 수정일시
             , UPD_IP                   = p_WRK_IP                  -- 수정IP
         WHERE SIT_CD                   = p_SIT_CD                  -- 현장코드
           AND WRT_DT                   = p_WRT_DT                  -- 작성일자
           AND WRT_SEQ                  = p_WRT_SEQ                 -- 작성순번
        ;

    END IF;
        
    

    p_RNT_WRT_SEQ := v_WRT_SEQ;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 5. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);
END PQHA_MOBILE_ADDRISK_S;
/

-- PQHA_MOBILE_EDU_S (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_MOBILE_EDU_S" (
   					 		 p_WRK_TP  VARCHAR2 :='U'                                     -- UPDATE FLAG( I: ISNERT, U:UPDATE, D:DELTE)
                            ,p_WRK_ID  VARCHAR2                                           -- 사용자 ID 
                            ,p_WRK_IP  VARCHAR2                                           -- 사용자 IP 
                            ,p_SIT_CD TQHA_EDU.SIT_CD%TYPE                                -- 현장코드
                            ,p_EDU_SEQ TQHA_EDU.EDU_SEQ%TYPE                              -- 교육순번
                            ,p_PHOTO_GRP1 TQHA_EDU.PHOTO_GRP1%TYPE                        -- 첨부파일그룹사진1
                            ,p_PHOTO_DESC_1 TQHA_EDU.PHOTO_DESC_1%TYPE                    -- 사진설명1
                            ,p_PHOTO_GRP2 TQHA_EDU.PHOTO_GRP2%TYPE                        -- 첨부파일그룹사진2
                            ,p_PHOTO_DESC_2 TQHA_EDU.PHOTO_DESC_2%TYPE                    -- 사진설명2
                            ,p_PHOTO_GRP3 TQHA_EDU.PHOTO_GRP3%TYPE                        -- 첨부파일그룹사진3
                            ,p_PHOTO_DESC_3 TQHA_EDU.PHOTO_DESC_3%TYPE                    -- 사진설명3
)
IS
    /**************************************************************************************************************************
      Purpose : 교육일지 저장
 
      REVISIONS
      Ver      Date               Author                  Description
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2026/07/22 14:29:08 최준원                    최초생성

    **************************************************************************************************************************/


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR2(200);            -- ERROR Message
    USER_EXCEPTION EXCEPTION;

    v_APRV_STATS        VARCHAR2(20);
    v_APRV_STATS_NM     VARCHAR2(50);

BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 필수입력 필드  Check  ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_SIT_CD IS NULL AND p_WRK_TP <> 'I')  THEN
        ERR_MSG := '현장코드는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

--    IF (p_EDU_SEQ IS NULL AND p_WRK_TP <> 'I')  THEN
--        ERR_MSG := '교육순번는(은) 필수 입력사항 입니다.';
--        RAISE USER_EXCEPTION;
--    END IF;

    ---------------------------------------------------------------------
    -- 결재상태 체크
    SELECT MAX(T2.APRV_STATS)
         , MAX(T3.CD_NM )
      INTO v_APRV_STATS
         , v_APRV_STATS_NM
      FROM TQHA_EDU             T1
      LEFT JOIN TQHA_APRV       T2 ON T1.SIT_CD     = T2.SIT_CD
                                  AND T1.APRV_NO    = T2.APRV_NO
      LEFT JOIN TCOA_COMCODE    T3 ON T2.APRV_STATS = T3.COM_CD
                                  AND T3.HRNK_CD    = 'QS031'
     WHERE T1.SIT_CD    = p_SIT_CD
       AND T1.EDU_SEQ   = p_EDU_SEQ
    ;

    IF v_APRV_STATS IN ('2', '4') THEN
        ERR_MSG := '결재상태 [' || v_APRV_STATS_NM || ']인 데이터는 수정 불가합니다.';
        RAISE USER_EXCEPTION;
    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Process 선행조건 Check ]
    ---------------------------------------------------------------------------------------------------------------------------



    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Business Process ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_WRK_TP ='U') THEN

        UPDATE TQHA_EDU
           SET PHOTO_GRP1           = p_PHOTO_GRP1              --첨부파일그룹사진1
              ,PHOTO_DESC_1         = p_PHOTO_DESC_1            --사진설명1
              ,PHOTO_GRP2           = p_PHOTO_GRP2              --첨부파일그룹사진2
              ,PHOTO_DESC_2         = p_PHOTO_DESC_2            --사진설명2
              ,PHOTO_GRP3           = p_PHOTO_GRP3              --첨부파일그룹사진3
              ,PHOTO_DESC_3         = p_PHOTO_DESC_3            --사진설명3
              ,UPD_ID               = p_WRK_ID                  --수정ID 
              ,UPD_DTM              = SYSDATE()                 --수정일시
              ,UPD_IP               = p_WRK_IP                  --수정IP
         WHERE SIT_CD  = p_SIT_CD         --현장코드
           AND EDU_SEQ = p_EDU_SEQ        --교육순번
        ;

    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 5. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN
