    /**************************************************************************************************************************
      Purpose :

      REVISIONS
      Ver      Date               Author                  Description
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2019/04/25 11:50:50                         최초생성

    /**************************************************************************************************************************/


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR(200);             -- ERROR Message
    USER_EXCEPTION EXCEPTION;

    p_UPD_ID        VARCHAR2(30);
    p_UPD_DTM       DATE;
    p_UPD_IP        VARCHAR2(30);
    p_IPT_ID        VARCHAR2(30);
    p_IPT_DTM       DATE;
    p_IPT_IP        VARCHAR2(30);

BEGIN
    IF p_WRK_TP = 'I' THEN
        p_IPT_ID  := p_WRK_ID;
        p_IPT_DTM := SYSDATE();
        p_IPT_IP  := p_WRK_IP;
        p_UPD_ID  := p_WRK_ID;
        p_UPD_DTM := SYSDATE();
        p_UPD_IP  := p_WRK_IP;
    ELSE
        p_UPD_ID  := p_WRK_ID;
        p_UPD_DTM := SYSDATE();
        p_UPD_IP  := p_WRK_IP;
    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 필수입력 필드  Check  ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_SIT_CD IS NULL)  THEN
        ERR_MSG := '현장코드는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_MSDS_SEQ IS NULL)  THEN
        ERR_MSG := 'MSDS순번는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Process 선행조건 Check ]
    ---------------------------------------------------------------------------------------------------------------------------



    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Business Process ]
    ---------------------------------------------------------------------------------------------------------------------------

    UPDATE TQHA_MSDSMNG
       SET ATFL_GRP     = p_ATFL_GRP    -- 위험경고표시
         , UPD_ID       = p_UPD_ID      -- 최종수정ID
         , UPD_DTM      = p_UPD_DTM     -- 최종수정일시
         , UPD_IP       = p_UPD_IP      -- 최종수정IP
     WHERE SIT_CD       = p_SIT_CD      -- 현장코드
       AND MSDS_SEQ     = p_MSDS_SEQ    -- MSDS순번
    ;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 5. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
         WHEN OTHERS THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);

END;
/

-- PQHA_MSDSMNG_Q (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_MSDSMNG_Q" (
    p_WRK_TP            IN VARCHAR2 DEFAULT 'Q'         -- FLAG
,   p_SIT_CD            IN VARCHAR2                     -- 현장코드
,   p_CUST_CD           IN VARCHAR2                     -- 거래처코드
,   p_STR_DT            IN VARCHAR2                     -- 시작일자
,   p_END_DT            IN VARCHAR2                     -- 종료일자
,   RTN_CURSOR          OUT SYS_REFCURSOR
)
IS 
    /**************************************************************************************************************************
      Purpose : [MSDS관리대장 조회] PROCEDRE (QSE > 재해예방관리 > MSDS관리대장  )

      REVISIONS
      Ver      Date               Author                  Description 
      -------  -----------------  ----------------------  ---------------------------------------------------------------------
      1.0      XXXX/XX/XX                                 최초생성

    **************************************************************************************************************************/

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE  NUMBER :=-20009; -- ERROR 코드
    ERR_MSG   VARCHAR(200);    -- ERROR Message
    USER_EXCEPTION EXCEPTION;

BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 수행전 Check Logic ]
    ---------------------------------------------------------------------------------------------------------------------------

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Logic 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------

    IF p_WRK_TP = 'Q' THEN

        OPEN RTN_CURSOR FOR
        SELECT MM.SIT_CD                        -- 현장코드
             , SI.SIT_NM                        -- 현장명
             , MM.MSDS_SEQ                      -- MSDS순번
             , MM.MSDS_NM                       -- MSDS명
             , MM.MNFR_NM                       -- 제조사명
             , MM.HNL_PLC                       -- 취급장소
             , MM.CUST_CD                       -- 협력회사
             , MM.CUST_NM                       -- 거래처명
             , MM.JBCLS                         -- 직종코드
             , (SELECT CD_NM
                  FROM TCOA_COMCODE
                 WHERE HRNK_CD = 'LAG002'       -- QSK05
                   AND COM_CD = MM.JBCLS
               ) AS JBCLS_NM                    -- 직종명
             , MM.SCNT_CTP_CD                   -- TSCZ_SUBCONTJOBTYPE (하도급공종)
             , MM.SCNT_CTP_NM                   -- 하도급공종명
             , MM.CIN_DT                        -- 반입일자
             , MM.CROT_DT                       -- 반출일자
             , MM.RMKS                          -- 비고
             , MM.ATFL_GRP                      -- 위험경고표시
             , FQSE_GET_AFTL_CNT(MM.ATFL_GRP) AS AFTL_CNT
          FROM TQHA_MSDSMNG MM
             , TCMZ_SIT SI
         WHERE MM.SIT_CD    = NVL(p_SIT_CD, MM.SIT_CD)
           AND MM.SIT_CD    = SI.SIT_CD
           AND (NVL(p_CUST_CD, 'X') = 'X' OR MM.CUST_CD = p_CUST_CD)
           AND (NVL(p_STR_DT, 'X') = 'X'  OR MM.CIN_DT >= p_STR_DT)
           AND (NVL(p_END_DT, 'X') = 'X'  OR MM.CIN_DT <= p_END_DT)
         ORDER BY MM.SIT_CD,MM.MSDS_SEQ ASC
        ;

    -------------------------------------------------------------------------------------------------------------------------
    -- 폼 조회.
    ELSIF p_WRK_TP = 'Q2' THEN

        OPEN RTN_CURSOR FOR
        SELECT FQHA_GETDEPTNM_BY_DEPTCD(p_SIT_CD) AS SITE_NM1
          FROM DUAL
        ;

    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
         WHEN OTHERS THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);

END PQHA_MSDSMNG_Q;
/

