        p_UPD_DTM := SYSDATE();
        p_UPD_IP  := p_WRK_IP;
    ELSE
        p_UPD_ID  := p_WRK_ID;
        p_UPD_DTM := SYSDATE();
        p_UPD_IP  := p_WRK_IP;
    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 필수입력 필드  Check  ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_SIT_CD IS NULL)  THEN
        ERR_MSG := '현장코드는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

--    IF (p_MSDS_SEQ IS NULL)  THEN
--        ERR_MSG := 'MSDS순번는(은) 필수 입력사항 입니다.';
--        RAISE USER_EXCEPTION;
--    END IF;
--
--    IF (p_CUST_CD IS NULL)  THEN
--        ERR_MSG := '협력회사는(은) 필수 입력사항 입니다.';
--        RAISE USER_EXCEPTION;
--    END IF;
--
--    IF (p_CUST_NM IS NULL)  THEN
--        ERR_MSG := '거래처명는(은) 필수 입력사항 입니다.';
--        RAISE USER_EXCEPTION;
--    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Process 선행조건 Check ]
    ---------------------------------------------------------------------------------------------------------------------------



    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Business Process ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_WRK_TP ='D') THEN

        DELETE
          FROM TQHA_MSDSMNG
         WHERE SIT_CD       = p_SIT_CD      -- 현장코드
           AND MSDS_SEQ     = p_MSDS_SEQ    -- MSDS순번
        ;

    ELSIF (p_WRK_TP ='U') THEN

        UPDATE TQHA_MSDSMNG
           SET MSDS_NM          = p_MSDS_NM             -- MSDS명
             , MNFR_NM          = p_MNFR_NM             -- 제조사명
             , HNL_PLC          = p_HNL_PLC             -- 취급장소
             , CUST_CD          = p_CUST_CD             -- 협력회사
             , CUST_NM          = p_CUST_NM             -- 거래처명
--           , SCNT_CTP_CD      = p_SCNT_CTP_CD         -- TSCZ_SUBCONTJOBTYPE (하도급공종)
--           , SCNT_CTP_NM      = p_SCNT_CTP_NM         -- 하도급공종명
             , JBCLS            = p_JBCLS               -- 직종코드
             , CIN_DT           = p_CIN_DT              -- 반입일자
             , CROT_DT          = p_CROT_DT             -- 반출일자
             , RMKS             = p_RMKS                -- 비고
             , ATFL_GRP         = p_ATFL_GRP            -- 위험경고표시
             , UPD_ID           = p_UPD_ID              -- 최종수정ID
             , UPD_DTM          = p_UPD_DTM             -- 최종수정일시
             , UPD_IP           = p_UPD_IP              -- 최종수정IP
         WHERE SIT_CD           = p_SIT_CD              --현장코드
           AND MSDS_SEQ         = p_MSDS_SEQ            --MSDS순번
        ;

    ELSE

        INSERT 
          INTO TQHA_MSDSMNG
             ( SIT_CD                   -- 현장코드
             , MSDS_SEQ                 -- MSDS순번
             , MSDS_NM                  -- MSDS명
             , MNFR_NM                  -- 제조사명
             , HNL_PLC                  -- 취급장소
             , CUST_CD                  -- 협력회사
             , CUST_NM                  -- 거래처명
--           , SCNT_CTP_CD              -- TSCZ_SUBCONTJOBTYPE (하도급공종)
--           , SCNT_CTP_NM              -- 하도급공종명
             , JBCLS                    -- 직종코드
             , CIN_DT                   -- 반입일자
             , CROT_DT                  -- 반출일자
             , RMKS                     -- 비고
             , ATFL_GRP                 -- 위험경고표시
             , IPT_ID                   -- 신규입력ID
             , IPT_DTM                  -- 신규입력일시
             , IPT_IP                   -- 신규입력IP
             , UPD_ID                   -- 최종수정ID
             , UPD_DTM                  -- 최종수정일시
             , UPD_IP                   -- 최종수정IP
             )
        VALUES 
             ( p_SIT_CD                 -- 현장코드
             , (SELECT NVL(MAX(MSDS_SEQ),0) + 1 FROM TQHA_MSDSMNG WHERE SIT_CD = p_SIT_CD)              --MSDS순번
             , p_MSDS_NM                -- MSDS명
             , p_MNFR_NM                -- 제조사명
             , p_HNL_PLC                -- 취급장소
             , p_CUST_CD                -- 협력회사
             , p_CUST_NM                -- 거래처명
--           , p_SCNT_CTP_CD            -- TSCZ_SUBCONTJOBTYPE (하도급공종)
--           , p_SCNT_CTP_NM            -- 하도급공종명
             , p_JBCLS
             , p_CIN_DT                 -- 반입일자
             , p_CROT_DT                -- 반출일자
             , p_RMKS                   -- 비고
             , p_ATFL_GRP               -- 위험경고표시
             , p_IPT_ID                 -- 신규입력ID
             , p_IPT_DTM                -- 신규입력일시
             , p_IPT_IP                 -- 신규입력IP
             , p_UPD_ID                 -- 최종수정ID
             , p_UPD_DTM                -- 최종수정일시
             , p_UPD_IP                 -- 최종수정IP
             )
        ;

    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 5. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
         WHEN OTHERS THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);

END;
/

-- PQHA_MSDS_CD_Q (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_MSDS_CD_Q"
(
      p_WRK_TP  VARCHAR2 DEFAULT 'Q'                                                       -- FLAG( Q: SELECT )
     ,p_SIT_CD TQHA_MSDS_CD.SIT_CD%TYPE                                                   -- 현장코드
     ,p_MSDS_SEQ TQHA_MSDS_CD.MSDS_SEQ%TYPE                                               -- MSDS코드
     ,RTN_CURSOR OUT SYS_REFCURSOR
)
IS 
    /**************************************************************************************************************************
      Purpose : 

      REVISIONS
      Ver      Date               Author                  Description 
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2026/06/26 08:52:59                         최초생성

    /**************************************************************************************************************************/


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR2(200);            -- ERROR Message
    USER_EXCEPTION EXCEPTION;


BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 수행전 Check Logic ]
    ---------------------------------------------------------------------------------------------------------------------------
 

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Logic 처리
    ---------------------------------------------------------------------------------------------------------------------------

    OPEN RTN_CURSOR FOR
    SELECT  SIT_CD
	       ,FQHA_GETDEPTNM_BY_DEPTCD(SIT_CD) AS SIT_NM
           ,MSDS_SEQ
           ,MSDS_NM                 --제품명
           ,MNFR_NM                 --제조사명
           ,CHEM_CD                 --대상화학물질
           ,CHEM_NM                 --대상화학물질명
           ,HAZ_INFO                 --위험성유해성
           ,HDL_PRECT                 --취급주의사항
           ,PREQ                 --보호구
           ,FAID_MEAS                 --응급조치요령
           ,GHS_LBL                 --경고표지이해방법
           ,USE_YN                 --사용여부
      FROM TQHA_MSDS_CD
    WHERE 1=1
    AND SIT_CD LIKE '%'||p_SIT_CD||'%'
    ORDER BY SIT_CD, MSDS_NM
    ;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN 
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);
END ;
/

