    ELSIF (p_WRK_TP ='D2') THEN
        DELETE 
          FROM TQHA_MSDS_CD
         WHERE SIT_CD = p_SIT_CD;
           
    ELSIF (p_WRK_TP ='U') THEN
        UPDATE TQHA_MSDS_CD
           SET MSDS_NM              = p_MSDS_NM                 --제품명
              ,MNFR_NM              = p_MNFR_NM                 --제조사명
              ,CHEM_CD              = p_CHEM_CD                 --대상화학물질
              ,CHEM_NM              = p_CHEM_NM                 --대상화학물질명
              ,HAZ_INFO             = p_HAZ_INFO                --위험성유해성
              ,HDL_PRECT            = p_HDL_PRECT               --취급주의사항
              ,PREQ                 = p_PREQ                    --보호구
              ,FAID_MEAS            = p_FAID_MEAS               --응급조치요령
              ,GHS_LBL              = p_GHS_LBL                 --경고표지이해방법
              ,USE_YN               = p_USE_YN                  --사용여부
              ,UPD_ID               = p_WRK_ID                  --수정ID 
              ,UPD_DTM              = SYSDATE()                 --수정일시
              ,UPD_IP               = p_WRK_IP                  --수정IP
         WHERE SIT_CD = p_SIT_CD 
           AND MSDS_SEQ = p_MSDS_SEQ;       --MSDS코드
    ELSE 
        INSERT INTO TQHA_MSDS_CD
                   ( SIT_CD 
                    ,MSDS_SEQ                --MSDS코드
                    ,MSDS_NM                 --제품명
                    ,MNFR_NM                 --제조사명
                    ,CHEM_CD                 --대상화학물질
                    ,CHEM_NM                 --대상화학물질명
                    ,HAZ_INFO                --위험성유해성
                    ,HDL_PRECT               --취급주의사항
                    ,PREQ                    --보호구
                    ,FAID_MEAS               --응급조치요령
                    ,GHS_LBL                 --경고표지이해방법
                    ,USE_YN                  --사용여부
                    ,IPT_ID                  --입력ID
                    ,IPT_DTM                 --입력일시
                    ,IPT_IP                  --입력IP
                    ,UPD_ID                  --수정ID
                    ,UPD_DTM                 --수정일시
                    ,UPD_IP                  --수정IP
                    )
             VALUES (
                     p_SIT_CD
                    ,(SELECT NVL(MAX(MSDS_SEQ),0) + 1 FROM TQHA_MSDS_CD WHERE SIT_CD = p_SIT_CD)
                    ,p_MSDS_NM               --제품명
                    ,p_MNFR_NM               --제조사명
                    ,p_CHEM_CD               --대상화학물질
                    ,p_CHEM_NM               --대상화학물질명
                    ,p_HAZ_INFO              --위험성유해성
                    ,p_HDL_PRECT             --취급주의사항
                    ,p_PREQ                  --보호구
                    ,p_FAID_MEAS             --응급조치요령
                    ,p_GHS_LBL               --경고표지이해방법
                    ,CASE WHEN p_USE_YN = 'Y' THEN '1'
                          WHEN p_USE_YN = 'N' THEN '0'
                          WHEN p_USE_YN IS NULL THEN '1'
                          ELSE p_USE_YN
                     END
                    ,p_WRK_ID                --입력ID 
                    ,SYSDATE()               --입력일시
                    ,p_WRK_IP                --입력IP
                    ,p_WRK_ID                --수정ID
                    ,SYSDATE()               --수정일시
                    ,p_WRK_IP);              --수정IP
    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 5. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN 
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);
END ;
/

-- PQHA_NCR_REP_APRV_W (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_NCR_REP_APRV_W" (
    p_WRK_TP                VARCHAR2 :='U'      -- UPDATE FLAG( I: ISNERT, U:UPDATE, D:DELTE)
,   p_WRK_ID                VARCHAR2            -- 사용자 ID
,   p_WRK_IP                VARCHAR2            -- 사용자 IP
,   p_SIT_CD                VARCHAR2            -- 현장코드
,   p_NCR_DOC_NO            VARCHAR2            -- 부적합문서번호
)
IS
    /**************************************************************************************************************************
      Purpose :

      REVISIONS
      Ver      Date               Author                  Description
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2026/02/02                                    최초생성

    /**************************************************************************************************************************/

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR(200);             -- ERROR Message
    USER_EXCEPTION EXCEPTION;

    v_VNDR_APRV_YN  VARCHAR2(1);
    v_VNDR_APRV_DT  VARCHAR2(8);
    v_MGR_APRV_YN   VARCHAR2(1);

BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 필수입력 필드  Check  ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_SIT_CD IS NULL)  THEN
        ERR_MSG := '현장코드는 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_NCR_DOC_NO IS NULL)  THEN
        ERR_MSG := '부적합문서번호는 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Process 선행조건 Check ]
    ---------------------------------------------------------------------------------------------------------------------------

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Business Process ]
    ---------------------------------------------------------------------------------------------------------------------------
    -- 업체 승인요청 / 요청 취소
    IF (p_WRK_TP IN ('APRV_CO', 'RSTOR_CO')) THEN

        -- 관리자 승인 여부 체크
        SELECT NVL(MAX(MGR_APRV_YN), '0')
          INTO v_MGR_APRV_YN
          FROM TQHA_NCR_REP
         WHERE SIT_CD               = p_SIT_CD
           AND NCR_DOC_NO           = p_NCR_DOC_NO
        ;

        IF v_MGR_APRV_YN = '1' THEN
            IF p_WRK_TP = 'APRV_CO' THEN
                ERR_MSG := '승인된 상태이므로 제출 불가합니다.';
            ELSE
                ERR_MSG := '승인된 상태이므로 제출취소 불가합니다.';
            END IF;

            RAISE USER_EXCEPTION;
        END IF;

        v_VNDR_APRV_YN := CASE WHEN p_WRK_TP = 'APRV_CO' THEN '1' ELSE '0' END;
        v_VNDR_APRV_DT := CASE WHEN p_WRK_TP = 'APRV_CO' THEN TO_CHAR(SYSDATE, 'YYYYMMDD') ELSE '' END;

        UPDATE TQHA_NCR_REP
           SET VNDR_APRV_YN         = v_VNDR_APRV_YN
             , VNDR_APRV_DT         = v_VNDR_APRV_DT
             , UPD_ID               = p_WRK_ID
             , UPD_DTM              = SYSDATE
         WHERE SIT_CD               = p_SIT_CD
           AND NCR_DOC_NO           = p_NCR_DOC_NO
        ;

    ---------------------------------------------------------------------------------
    -- 관리자 승인 / 반려
    ELSIF (p_WRK_TP IN ('APRV', 'RSTOR')) THEN

        -- 업체 승인요청 여부 체크
        SELECT NVL(MAX(VNDR_APRV_YN), '0')
          INTO v_VNDR_APRV_YN
          FROM TQHA_NCR_REP
         WHERE SIT_CD               = p_SIT_CD
           AND NCR_DOC_NO           = p_NCR_DOC_NO
        ;

        IF v_VNDR_APRV_YN = '0' THEN
            ERR_MSG := '업체 승인요청상태가 아니어서 승인 및 반려가 불가합니다.';
            RAISE USER_EXCEPTION;
        END IF;

        v_MGR_APRV_YN := CASE WHEN p_WRK_TP = 'APRV' THEN '1' ELSE '0' END;

        UPDATE TQHA_NCR_REP
           SET MGR_APRV_YN          = v_MGR_APRV_YN
             , UPD_ID               = p_WRK_ID
             , UPD_DTM              = SYSDATE
         WHERE SIT_CD               = p_SIT_CD
           AND NCR_DOC_NO           = p_NCR_DOC_NO
        ;

    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 5. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
         WHEN OTHERS THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);
END;
/

-- PQHA_NCR_REP_Q (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_NCR_REP_Q" (
    p_WRK_TP                    IN VARCHAR2 DEFAULT 'Q'     -- FLAG (Q:ERP 부적합보고서, Q1:ERP 부적합보고서 작정, B:B2B부적합보고서, B1:B2B 부적합보고서 작성)
,   p_SIT_CD                    IN VARCHAR2
,   p_SEARCH_PUBC_YM            IN VARCHAR2
,   p_SEARCH_VNDR_MA_YN         IN VARCHAR2
,   p_NCR_DOC_NO                IN VARCHAR2                 -- 부적합문서번호
,   p_CUST_CD                   IN VARCHAR2    
,   p_VNDR_SEQ                  IN VARCHAR2    
,   RTN_CURSOR                  OUT SYS_REFCURSOR
)
IS
    /**************************************************************************************************************************
      Purpose : [평가항목 조회] PROCEDRE (QSE > 안전관리 > 중점점검관리 > 부적합보고서  )

      REVISIONS
      Ver      Date               Author                  Description 
      -------  -----------------  ----------------------  ---------------------------------------------------------------------
      1.0      2023/12/06                                 최초생성  

    **************************************************************************************************************************/

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE  NUMBER :=-20009; -- ERROR 코드
    ERR_MSG   VARCHAR(200);    -- ERROR Message
    USER_EXCEPTION EXCEPTION;

BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 수행전 Check Logic ]
    ---------------------------------------------------------------------------------------------------------------------------

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Logic 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------

    IF p_WRK_TP = 'Q' THEN

        OPEN RTN_CURSOR FOR
        SELECT A.SIT_CD                       -- 현장코드
             , A.VNDR_MA_YN                    -- 업체조치 여부(공통코드 QS025)
             , ( SELECT CD_NM FROM TCOA_COMCODE WHERE COM_CD = VNDR_MA_YN AND HRNK_CD = 'QS025') AS VNDR_MA_YN_NM  -- 조치여부명
             /*, A.NCR_TTL                       -- 부적합 제목*/
             , A.NCR_DOC_NO                    -- 부적합문서번호
             , A.PUBC_DT                       -- 발행일자
             , A.NCR_WRTR                      -- 발행자
             , ( SELECT USR_NM FROM TCOZ_USR_INFO WHERE USR_ID = A.NCR_WRTR ) AS NCR_WRTR_NM     -- 발행자 명칭
             , A.CUST_CD                       -- 업체코드
             , A.VNDR_SEQ                      -- 업체순번
             , CASE WHEN A.DIRECT_YN = '1' THEN '중흥'
                    ELSE ( SELECT CUST_NM FROM VQSZ_TRADE WHERE CUST_CD = A.CUST_CD )
               END AS VNDR_NM -- 업체명 (22.07.05 수정)
             , A.CTP_CD                        -- 공종코드
             , ( SELECT CTP_NM FROM TQHA_CTP  WHERE CTP_CD = A.CTP_CD ) AS CTP_NM  -- 공종명칭
             , A.NCR_LOC                       -- 발생위치
             , A.MA_DDLN_DT                    -- 조치기한일자
             , A.NCR_CTS                       -- 부적합내용
             , A.NCR_MATT                      -- 요구사항
             , A.VNDR_PRVN_CPLN                -- 업체재발방지 대책
             , A.NCR_CRT_DIV                   -- 부적합구분 (1:부적합, 2:안전점검, 3:추가위험)
             , CASE WHEN A.NCR_CRT_DIV = '1' THEN '부적합보고서'
                    WHEN A.NCR_CRT_DIV = '2' THEN '일일안전점검'
                    WHEN A.NCR_CRT_DIV = '3' THEN '추가위험발굴'
                END AS NCR_CRT_DIV_NM -- 부적합구분명
             , A.NCR_PHOTO_GRP1                -- 부적합내용 그룹사진1
             , A.NCR_PHOTO_DESC_1              -- 사진설명1
             , A.NCR_PHOTO_GRP2                -- 부적합내용 그룹사진2
             , A.NCR_PHOTO_DESC_2              -- 사진설명2
             , A.VNDR_PHOTO_GRP1               -- 조치내용 그룹사진1
             , A.VNDR_PHOTO_DESC_1             -- 사진설명1
             , A.VNDR_PHOTO_GRP2               -- 조치내용 그룹사진2
             , A.VNDR_PHOTO_DESC_2             -- 사진설명2
          FROM TQHA_NCR_REP A
         WHERE A.SIT_CD = p_SIT_CD
           AND (SUBSTR(A.PUBC_DT,1,6) = p_SEARCH_PUBC_YM OR NVL(p_SEARCH_PUBC_YM, 0) = 0 )
           AND (A.VNDR_MA_YN = p_SEARCH_VNDR_MA_YN OR NVL(p_SEARCH_VNDR_MA_YN, 0) = 0 )
         ORDER 
            BY A.PUBC_DT DESC
             , A.NCR_SEQ DESC
        ;

    ELSIF p_WRK_TP = 'Q1' THEN

        OPEN RTN_CURSOR FOR
        SELECT A.SIT_CD                     -- 현장코드
             , A.NCR_DOC_NO                 -- 부적합문서번호
             , A.NCR_SEQ                    -- 년도별일련번호
             , A.PUBC_DT                    -- 발행일자
             /*, A.NCR_TTL                  -- 부적합제목*/
             , A.MA_DDLN_DT                 -- 조치기한일자
             , A.CUST_CD                    -- 협력업체코드
             , A.VNDR_SEQ                   -- 업체순번
             , CASE WHEN A.DIRECT_YN = '1' THEN '휴먼플러스 건설'
                    ELSE ( SELECT CUST_NM FROM VQSZ_TRADE WHERE CUST_CD = A.CUST_CD )
               END AS VNDR_NM -- 업체명 (22.07.05 수정)
             , B.VNDR_PSN_NM                -- 업체담당자명
             , B.VNDR_PSN_CADDR AS VNDR_PSN_CADDR -- 업체담당자연락처
             , A.CTP_CD                     -- 공종코드
             , ( SELECT CTP_NM FROM TQHA_CTP WHERE CTP_CD = A.CTP_CD ) AS CTP_NM  -- 공종명
             , A.NCR_LOC                    -- 발생위치
             , A.NCR_MATT                   -- 요구사항
             , A.NCR_CTS                    -- 부적합내용
             , A.NCR_PHOTO_GRP1             -- 부적합내용 그룹사진1
             , A.NCR_PHOTO_DESC_1           -- 사진설명1
             , A.NCR_PHOTO_GRP2             -- 부적합내용 그룹사진2
             , A.NCR_PHOTO_DESC_2           -- 사진설명2
             , A.NCR_WRTR                   -- 작성자ID
             , ( SELECT USR_NM FROM TCOZ_USR_INFO WHERE USR_ID = A.NCR_WRTR ) AS NCR_WRTR_NM     -- 작성자명
             , A.VNDR_NOTI_YN               -- 업체통보여부(관리자->업체)
             , A.VNDR_NOTI_DT               -- 업체통보일자
             , A.VNDR_MA_TTL                -- 업체조치제목
             , A.VNDR_PRVN_CPLN             -- 업체재발방지대책
             , A.VNDR_MA_DT                 -- 업체조치일자
             , A.VNDR_MA_YN                 -- 조치여부
             , A.VNDR_MA_CTS                -- 업체조치내용
             , A.VNDR_MA_PSN                -- 업체조치자
             , DECODE((SELECT USR_NM FROM TCOZ_USR_INFO WHERE USR_ID = A.VNDR_MA_PSN), '', A.VNDR_MA_PSN, (SELECT USR_NM FROM TCOZ_USR_INFO WHERE USR_ID = A.VNDR_MA_PSN)) AS VNDR_MA_PSN_NM  -- 업체조치자명
             , A.VNDR_PHOTO_GRP1            -- 조치내용 그룹사진1
             , A.VNDR_PHOTO_DESC_1          -- 사진설명1
             , A.VNDR_PHOTO_GRP2            -- 조치내용 그룹사진2
             , A.VNDR_PHOTO_DESC_2          -- 사진설명2
             , A.VNDR_APRV_YN               -- 승인여부
             , A.VNDR_APRV_DT               -- 업체승인요청일자
             , A.MGR_NOTI_YN                -- 관리자발송여부(업체->관리자)
             , A.MGR_APRV_YN                -- 관리자승인여부
             , A.MGR_APRV_DT                -- 관리자승인일자
             , A.NCR_CRT_DIV                -- 부적합구분 (1:부적합, 2:안전점검, 3:추가위험)
             , A.DIRECT_YN                  -- 직영공사 체크여부(22.07.05 추가)
             , CASE WHEN A.NCR_CRT_DIV = '1' THEN '[부적합보고서에서 작성] '
                    WHEN A.NCR_CRT_DIV = '2' THEN '[일일안전점검에서 작성] '
                    WHEN A.NCR_CRT_DIV = '3' THEN '[추가위험발굴에서 작성] '
                    ELSE '' 
               END
               || ' ▶ 상태 : ' ||
               CASE WHEN A.MGR_APRV_YN IN ('1', '2') 
                        THEN CASE WHEN A.MGR_APRV_YN = '1' THEN '관리자 승인'
                                  ELSE '관리자 반려'
                             END
                    ELSE CASE WHEN VNDR_APRV_YN = '1' THEN '업체승인요청중'
                              ELSE CASE WHEN VNDR_NOTI_YN = '1' THEN '업체통지완료'
                                        ELSE '-'
                                   END
                         END
               END
               AS STATS_NM
          FROM TQHA_NCR_REP A
             , TQHA_VNDR B
         WHERE A.SIT_CD         = B.SIT_CD (+)
           AND A.CUST_CD        = B.CUST_CD (+)
           AND A.VNDR_SEQ       = B.VNDR_SEQ (+)
           AND A.SIT_CD         = p_SIT_CD
           AND A.NCR_DOC_NO     = p_NCR_DOC_NO
         ORDER 
            BY A.PUBC_DT DESC
             , A.NCR_SEQ DESC
        ;

    ELSIF p_WRK_TP = 'B' THEN

        OPEN RTN_CURSOR FOR
        SELECT A.SIT_CD                         -- 현장코드
             , A.VNDR_MA_YN                     -- 업체조치 여부(공통코드 QS025)
             , ( SELECT CD_NM FROM TCOA_COMCODE WHERE COM_CD = VNDR_MA_YN AND HRNK_CD = 'QS025') AS VNDR_MA_YN_NM  -- 조치여부명
             /*, A.NCR_TTL                      -- 부적합 제목*/
             , A.NCR_DOC_NO                     -- 부적합문서번호
             , A.PUBC_DT                        -- 발행일자
             , A.NCR_WRTR                       -- 발행자
             , ( SELECT USR_NM FROM TCOZ_USR_INFO WHERE USR_ID = A.NCR_WRTR ) AS NCR_WRTR_NM     -- 발행자 명칭
             , A.CUST_CD                        -- 업체코드
             , A.VNDR_SEQ                       -- 업체순번
             , ( SELECT CUST_NM FROM VQSZ_TRADE  WHERE CUST_CD = A.CUST_CD ) AS VNDR_NM  -- 업체명칭
             , A.CTP_CD                         -- 공종코드
             , ( SELECT CTP_NM FROM TQHA_CTP  WHERE CTP_CD = A.CTP_CD ) AS CTP_NM  -- 공종명칭
             , A.NCR_LOC                        -- 발생위치
             , A.MA_DDLN_DT                     -- 조치기한일자
             , A.NCR_CTS                        -- 부적합내용
             , A.NCR_MATT                       -- 요구사항
             , A.VNDR_PRVN_CPLN                 -- 업체재발방지 대책
             , A.NCR_CRT_DIV                    -- 부적합구분 (1:부적합, 2:안전점검, 3:추가위험)
             , A.NCR_PHOTO_GRP1                 -- 부적합내용 그룹사진1
             , A.NCR_PHOTO_DESC_1               -- 사진설명1
             , A.NCR_PHOTO_GRP2                 -- 부적합내용 그룹사진2
             , A.NCR_PHOTO_DESC_2               -- 사진설명2
             , A.VNDR_PHOTO_GRP1                -- 조치내용 그룹사진1
             , A.VNDR_PHOTO_DESC_1              -- 사진설명1
             , A.VNDR_PHOTO_GRP2                -- 조치내용 그룹사진2
             , A.VNDR_PHOTO_DESC_2              -- 사진설명2
          FROM TQHA_NCR_REP A
         WHERE A.SIT_CD             = p_SIT_CD
           AND A.CUST_CD            = p_CUST_CD
           AND A.VNDR_SEQ           = p_VNDR_SEQ
           AND ( SUBSTR(A.PUBC_DT,1,6) = p_SEARCH_PUBC_YM OR NVL(p_SEARCH_PUBC_YM, 0) = 0 )
           AND ( A.VNDR_MA_YN = p_SEARCH_VNDR_MA_YN OR NVL(p_SEARCH_VNDR_MA_YN, 0) = 0 )
         ORDER 
            BY A.PUBC_DT DESC
             , A.NCR_SEQ DESC
        ;

    ELSIF p_WRK_TP = 'B1' THEN    

        OPEN RTN_CURSOR FOR
        SELECT A.SIT_CD                     -- 현장코드
             , A.NCR_DOC_NO                 -- 부적합문서번호
             , A.NCR_SEQ                    -- 년도별일련번호
             , A.PUBC_DT                    -- 발행일자
             /*, A.NCR_TTL                  -- 부적합제목*/
             , A.MA_DDLN_DT                 -- 조치기한일자
             , A.CUST_CD                    -- 협력업체코드
             , A.VNDR_SEQ                   -- 업체순번
             , ( SELECT CUST_NM FROM VQSZ_TRADE WHERE CUST_CD = A.CUST_CD ) AS VNDR_NM   -- 협력업체명
             , B.VNDR_PSN_NM                -- 업체담당자명
             -- , sys.pkg_crypto_dec.decrypt(B.VNDR_PSN_CADDR) VNDR_PSN_CADDR -- 업체담당자연락처
             , B.VNDR_PSN_CADDR             -- 업체담당자연락처
             , A.CTP_CD                     -- 공종코드
             , ( SELECT CTP_NM FROM TQHA_CTP WHERE CTP_CD = A.CTP_CD ) AS CTP_NM  -- 공종명
             , A.NCR_LOC                    -- 발생위치
             , A.NCR_MATT                   -- 요구사항
             , A.NCR_CTS                    -- 부적합내용
             , A.NCR_PHOTO_GRP1             -- 부적합내용 그룹사진1
             , A.NCR_PHOTO_DESC_1           -- 사진설명1
             , A.NCR_PHOTO_GRP2             -- 부적합내용 그룹사진2
             , A.NCR_PHOTO_DESC_2           -- 사진설명2
             , A.NCR_WRTR                   -- 작성자ID
             , ( SELECT USR_NM FROM TCOZ_USR_INFO WHERE USR_ID = A.NCR_WRTR ) AS NCR_WRTR_NM     -- 작성자명
             , A.VNDR_NOTI_YN               -- 업체통보여부(관리자->업체)
             , A.VNDR_NOTI_DT               -- 업체통보일자
             , A.VNDR_MA_TTL                -- 업체조치제목
             , A.VNDR_PRVN_CPLN             -- 업체재발방지대책
             , A.VNDR_MA_DT                 -- 업체조치일자
             , A.VNDR_MA_YN                 -- 조치여부
             , A.VNDR_MA_CTS                -- 업체조치내용
             , A.VNDR_MA_PSN                -- 업체조치자
             , DECODE((SELECT USR_NM FROM TCOZ_USR_INFO WHERE USR_ID = A.VNDR_MA_PSN), '', A.VNDR_MA_PSN, (SELECT USR_NM FROM TCOZ_USR_INFO WHERE USR_ID = A.VNDR_MA_PSN)) AS VNDR_MA_PSN_NM -- 업체조치자명
             , A.VNDR_PHOTO_GRP1            -- 조치내용 그룹사진1
             , A.VNDR_PHOTO_DESC_1          -- 사진설명1
             , A.VNDR_PHOTO_GRP2            -- 조치내용 그룹사진2
             , A.VNDR_PHOTO_DESC_2          -- 사진설명2
             , A.VNDR_APRV_YN               -- 승인여부
             , A.VNDR_APRV_DT               -- 업체승인요청일자
             , A.MGR_NOTI_YN                -- 관리자발송여부(업체->관리자)
             , A.MGR_APRV_YN                -- 관리자승인여부
             , A.MGR_APRV_DT                -- 관리자승인일자
             , A.NCR_CRT_DIV                -- 부적합구분 (1:부적합, 2:안전점검, 3:추가위험)
             , CASE WHEN A.NCR_CRT_DIV = '1' THEN '[부적합보고서에서 작성] '
                    WHEN A.NCR_CRT_DIV = '2' THEN '[일일안전점검에서 작성] '
                    WHEN A.NCR_CRT_DIV = '3' THEN '[추가위험발굴에서 작성] '
                    ELSE '' 
               END
               || ' ▶ 상태 : ' ||
               CASE WHEN A.MGR_APRV_YN IN ('1', '2') 
                        THEN CASE WHEN A.MGR_APRV_YN = '1' THEN '관리자 승인'
                                  ELSE '관리자 반려'
                             END
                    ELSE CASE WHEN VNDR_APRV_YN = '1' THEN '승인요청중'
                              ELSE '-'
                         END
               END
               AS STATS_NM
          FROM TQHA_NCR_REP A
             , TQHA_VNDR B
         WHERE A.SIT_CD         = p_SIT_CD
           AND A.NCR_DOC_NO     = p_NCR_DOC_NO
           AND A.CUST_CD        = p_CUST_CD
           AND A.VNDR_SEQ       = p_VNDR_SEQ
           AND A.SIT_CD         = B.SIT_CD
           AND A.CUST_CD        = B.CUST_CD
           AND A.VNDR_SEQ       = B.VNDR_SEQ
         ORDER 
            BY A.PUBC_DT DESC
             , A.NCR_SEQ DESC
        ;

    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
         WHEN OTHERS THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);

END PQHA_NCR_REP_Q;
/

-- PQHA_NCR_REP_S (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_NCR_REP_S" (
    p_WRK_TP                    VARCHAR2 :='U'                                      -- UPDATE FLAG( I: ISNERT, U:UPDATE, D:DELTE)
,   p_WRK_ID                    VARCHAR2                                            -- 사용자 ID 
,   p_WRK_IP                    VARCHAR2                                            -- 사용자 IP 
,   p_SIT_CD                    TQHA_NCR_REP.SIT_CD                 %TYPE           -- 현장코드
,   p_NCR_DOC_NO                TQHA_NCR_REP.NCR_DOC_NO             %TYPE           -- 부적합문서번호
,   p_NCR_SEQ                   TQHA_NCR_REP.NCR_SEQ                %TYPE           -- 년도별일련번호
,   p_PUBC_DT                   TQHA_NCR_REP.PUBC_DT                %TYPE           -- 발행일자
--, p_NCR_TTL                   TQHA_NCR_REP.NCR_TTL                %TYPE           -- 부적합제목
,   p_MA_DDLN_DT                TQHA_NCR_REP.MA_DDLN_DT             %TYPE           -- 조치기한일자
,   p_CUST_CD                   TQHA_NCR_REP.CUST_CD                %TYPE           -- 협력업체코드
,   p_VNDR_SEQ                  TQHA_NCR_REP.VNDR_SEQ               %TYPE           -- 업체순번
--, p_VNDR_PSN                  TQHA_NCR_REP.VNDR_PSN               %TYPE           -- 업체담당자
--, p_VNDR_PSN_HP               TQHA_NCR_REP.VNDR_PSN_HP            %TYPE           -- 업체담당자연락처
,   p_CTP_CD                    TQHA_NCR_REP.CTP_CD                 %TYPE           -- 공종코드
,   p_NCR_LOC                   TQHA_NCR_REP.NCR_LOC                %TYPE           -- 발생위치
,   p_NCR_MATT                  TQHA_NCR_REP.NCR_MATT               %TYPE           -- 요구사항
,   p_NCR_CTS                   TQHA_NCR_REP.NCR_CTS                %TYPE           -- 부적합내용
,   p_NCR_PHOTO_GRP1            TQHA_NCR_REP.NCR_PHOTO_GRP1         %TYPE           -- 첨부파일그룹사진1
,   p_NCR_PHOTO_DESC_1          TQHA_NCR_REP.NCR_PHOTO_DESC_1       %TYPE           -- 사진설명1 
,   p_NCR_PHOTO_GRP2            TQHA_NCR_REP.NCR_PHOTO_GRP2         %TYPE           -- 첨부파일그룹사진2
,   p_NCR_PHOTO_DESC_2          TQHA_NCR_REP.NCR_PHOTO_DESC_2       %TYPE           -- 사진설명2
,   p_NCR_WRTR                  TQHA_NCR_REP.NCR_WRTR               %TYPE           -- 작성자
,   p_VNDR_NOTI_YN              TQHA_NCR_REP.VNDR_NOTI_YN           %TYPE           -- 발송 1 미발송 0
,   p_VNDR_NOTI_DT              TQHA_NCR_REP.VNDR_NOTI_DT           %TYPE           -- 업체통보일자
,   p_VNDR_MA_TTL               TQHA_NCR_REP.VNDR_MA_TTL            %TYPE           -- 업체조치제목
,   p_VNDR_PRVN_CPLN            TQHA_NCR_REP.VNDR_PRVN_CPLN         %TYPE           -- 업체재발방지대책
,   p_VNDR_MA_DT                TQHA_NCR_REP.VNDR_MA_DT             %TYPE           -- 업체조치일자
,   p_VNDR_MA_YN                TQHA_NCR_REP.VNDR_MA_YN             %TYPE           -- NCR조치(QS025) 1 조치, 2 미조치
,   p_VNDR_MA_CTS               TQHA_NCR_REP.VNDR_MA_CTS            %TYPE           -- 업체조치내용
,   p_VNDR_MA_PSN               TQHA_NCR_REP.VNDR_MA_PSN            %TYPE           -- 업체조치자
,   p_VNDR_PHOTO_GRP1           TQHA_NCR_REP.VNDR_PHOTO_GRP1        %TYPE           -- 업체조치그룹사진1
,   p_VNDR_PHOTO_DESC_1         TQHA_NCR_REP.VNDR_PHOTO_DESC_1      %TYPE           -- 업체사진설명1
,   p_VNDR_PHOTO_GRP2           TQHA_NCR_REP.VNDR_PHOTO_GRP2        %TYPE           -- 업체조치그룹사진2
,   p_VNDR_PHOTO_DESC_2         TQHA_NCR_REP.VNDR_PHOTO_DESC_2      %TYPE           -- 업체사진설명2
,   p_VNDR_APRV_YN              TQHA_NCR_REP.VNDR_APRV_YN           %TYPE           -- 승인요청 1 미요청 0
,   p_VNDR_APRV_DT              TQHA_NCR_REP.VNDR_APRV_DT           %TYPE           -- 업체승인요청일자
,   p_MGR_NOTI_YN               TQHA_NCR_REP.MGR_NOTI_YN            %TYPE           -- 발송Y (SMS)
,   p_MGR_APRV_YN               TQHA_NCR_REP.MGR_APRV_YN            %TYPE           -- 승인 1, 반려 2
,   p_MGR_APRV_DT               TQHA_NCR_REP.MGR_APRV_DT            %TYPE           -- 관리자승인일자
,   p_NCR_CRT_DIV               TQHA_NCR_REP.NCR_CRT_DIV            %TYPE           -- 부적합생성구분  1, 부적합, 2 안전점검, 3 추가위험
,   p_DIRECT_YN                 TQHA_NCR_REP.DIRECT_YN              %TYPE           -- 직영여부
,   p_RNT_NCR_DOC_NO            OUT VARCHAR2                                        -- 리턴변수(문서번호)
)
IS 
    /**************************************************************************************************************************
      Purpose : 

      REVISIONS
      Ver      Date               Author                  Description 
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2021/11/19 11:14:45                         최초생성

    **************************************************************************************************************************/


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR2(200);            -- ERROR Message
    USER_EXCEPTION EXCEPTION;

    v_NCR_SEQ INTEGER;                              -- 안전 부적합순번 MAX
    v_NCR_SEQ1   TQHA_NCR_REP.NCR_DOC_NO%TYPE ;       -- 안전 부적합순번 MAX
    v_NCR_DOC_NO TQHA_NCR_REP.NCR_DOC_NO%TYPE ;        -- 안전 부적합문서 번호

BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 필수입력 필드  Check  ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_SIT_CD IS NULL)  THEN
        ERR_MSG := '현장코드는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_NCR_DOC_NO IS NULL  AND p_WRK_TP <> 'I')  THEN
        ERR_MSG := '부적합문서번호는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_NCR_SEQ IS NULL  AND p_WRK_TP <> 'I')  THEN
        ERR_MSG := '년도별일련번호는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_PUBC_DT IS NULL)  THEN
        ERR_MSG := '발행일자는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

--    IF (p_CUST_CD IS NULL)  THEN
--        ERR_MSG := '협력업체코드는(은) 필수 입력사항 입니다.';
--        RAISE USER_EXCEPTION;
--    END IF;

    IF (p_VNDR_SEQ IS NULL  AND p_WRK_TP <> 'I')  THEN
        ERR_MSG := '업체순번는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_CTP_CD IS NULL)  THEN
        ERR_MSG := '공종코드는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Process 선행조건 Check ]
    ---------------------------------------------------------------------------------------------------------------------------



    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Business Process ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_WRK_TP ='D') THEN
        DELETE 
          FROM TQHA_NCR_REP
         WHERE SIT_CD       = p_SIT_CD          -- 현장코드
           AND NCR_DOC_NO   = p_NCR_DOC_NO      -- 부적합문서번호
        ;

        v_NCR_DOC_NO := p_NCR_DOC_NO;

        -- 22.07.04 추가
        -- 추가위험발굴에서 발행된 부적합보고서를 삭제한 경우
        IF p_NCR_CRT_DIV = '3' THEN

            UPDATE TQHA_ADDRISK_ORD
               SET NCR_PUBC_YN  = ''
                 , NCR_DOC_NO   = ''
             WHERE SIT_CD       = p_SIT_CD
               AND NCR_DOC_NO   = p_NCR_DOC_NO
            ;

        END IF;

        -- 22.07.05 추가
        -- 일일안전점검에서 발행된 부적합보고서를 삭제한 경우
        IF p_NCR_CRT_DIV = '2' THEN

            UPDATE TQHB_DAYSAFE_CHKLST
               SET NCR_PUBC_YN      = ''
                 , NCR_DOC_NO       = ''
             WHERE SIT_CD           = p_SIT_CD
               AND NCR_DOC_NO       = p_NCR_DOC_NO
            ;

        END IF;

    ELSIF (p_WRK_TP ='U') THEN

        UPDATE TQHA_NCR_REP
           SET NCR_SEQ                  = p_NCR_SEQ                 -- 년도별일련번호
             , PUBC_DT                  = p_PUBC_DT                 -- 발행일자
             --, NCR_TTL                = p_NCR_TTL                 -- 부적합제목
             , MA_DDLN_DT               = p_MA_DDLN_DT              -- 조치기한일자
             , CUST_CD                  = p_CUST_CD                 -- 협력업체코드
             , VNDR_SEQ                 = p_VNDR_SEQ                -- 업체순번
             --, VNDR_PSN               = p_VNDR_PSN                -- 업체담당자
             --, VNDR_PSN_HP            = p_VNDR_PSN_HP             -- 업체담당자연락처
             , CTP_CD                   = p_CTP_CD                  -- 공종코드
             , NCR_LOC                  = p_NCR_LOC                 -- 발생위치
             , NCR_MATT                 = p_NCR_MATT                -- 요구사항
             , NCR_CTS                  = p_NCR_CTS                 -- 부적합내용
             , NCR_PHOTO_GRP1           = p_NCR_PHOTO_GRP1          -- 첨부파일그룹사진1
             , NCR_PHOTO_DESC_1         = p_NCR_PHOTO_DESC_1        -- 사진설명1
             , NCR_PHOTO_GRP2           = p_NCR_PHOTO_GRP2          -- 첨부파일그룹사진2
             , NCR_PHOTO_DESC_2         = p_NCR_PHOTO_DESC_2        -- 사진설명2
             , NCR_WRTR                 = p_NCR_WRTR                -- 작성자
             , VNDR_NOTI_YN             = p_VNDR_NOTI_YN            -- 발송 1 미발송 0
             , VNDR_NOTI_DT             = p_VNDR_NOTI_DT            -- 업체통보일자
             , VNDR_MA_TTL              = p_VNDR_MA_TTL             -- 업체조치제목
             , VNDR_PRVN_CPLN           = p_VNDR_PRVN_CPLN          -- 업체재발방지대책
             , VNDR_MA_DT               = p_VNDR_MA_DT              -- 업체조치일자
             , VNDR_MA_YN               = p_VNDR_MA_YN              -- NCR조치(QS025) 1 조치, 2 미조치
             , VNDR_MA_CTS              = p_VNDR_MA_CTS             -- 업체조치내용
             , VNDR_MA_PSN              = p_VNDR_MA_PSN             -- 업체조치자
             , VNDR_PHOTO_GRP1          = p_VNDR_PHOTO_GRP1         -- 업체조치그룹사진1
             , VNDR_PHOTO_DESC_1        = p_VNDR_PHOTO_DESC_1       -- 업체사진설명1
             , VNDR_PHOTO_GRP2          = p_VNDR_PHOTO_GRP2         -- 업체조치그룹사진2
             , VNDR_PHOTO_DESC_2        = p_VNDR_PHOTO_DESC_2       -- 업체사진설명2
             , VNDR_APRV_YN             = p_VNDR_APRV_YN            -- 승인요청 1 미요청 0
             , VNDR_APRV_DT             = p_VNDR_APRV_DT            -- 업체승인요청일자
             , MGR_NOTI_YN              = p_MGR_NOTI_YN             -- 발송Y (SMS)
             , MGR_APRV_YN              = p_MGR_APRV_YN             -- 승인 1, 반려 2
             , MGR_APRV_DT              = p_MGR_APRV_DT             -- 관리자승인일자
             , NCR_CRT_DIV              = p_NCR_CRT_DIV             -- 부적합생성구분  1, 부적합, 2 안전점검, 3 추가위험     
             , DIRECT_YN                = p_DIRECT_YN               -- 직영여부  
             , UPD_ID                   = p_WRK_ID                  -- 수정ID 
             , UPD_DTM                  = SYSDATE()                 -- 수정일시
             , UPD_IP                   = p_WRK_IP                  -- 수정IP
         WHERE SIT_CD                   = p_SIT_CD                  -- 현장코드
           AND NCR_DOC_NO               = p_NCR_DOC_NO              -- 부적합문서번호
        ;

        v_NCR_DOC_NO := p_NCR_DOC_NO;

        -- 부적합생성구분이 2:안전점검, 3:추가위험인 경우
        -- 조치여부가 '조치'인 경우
        -- 추가위험발굴
        IF p_NCR_CRT_DIV = '3' AND p_VNDR_MA_YN = '1' THEN

            UPDATE TQHA_ADDRISK_ORD
               SET VNDR_MA_YN       = p_VNDR_MA_YN
                 , VNDR_MA_DT       = p_VNDR_MA_DT
             WHERE SIT_CD           = p_SIT_CD
               AND NCR_DOC_NO       = p_NCR_DOC_NO
            ;

        END IF;

        -- 일일안전점검
        IF p_NCR_CRT_DIV = '2' AND p_VNDR_MA_YN = '1' THEN

            UPDATE TQHB_DAYSAFE_CHKLST
               SET VNDR_MA_YN       = p_VNDR_MA_YN
                 , VNDR_MA_DT       = p_VNDR_MA_DT
             WHERE SIT_CD           = p_SIT_CD
               AND NCR_DOC_NO       = p_NCR_DOC_NO
            ;

        END IF;

        -- 조치여부가 '미조치'인 경우 22.07.04 추가
        -- 추가위험발굴
        IF p_NCR_CRT_DIV = '3' AND p_VNDR_MA_YN = '0' THEN

            UPDATE TQHA_ADDRISK_ORD
               SET VNDR_MA_YN       = p_VNDR_MA_YN
                 , VNDR_MA_DT       = ''
             WHERE SIT_CD           = p_SIT_CD
               AND NCR_DOC_NO       = p_NCR_DOC_NO
            ;

        END IF;

        -- 일일안전점검
        IF p_NCR_CRT_DIV = '2' AND p_VNDR_MA_YN = '0' THEN

            UPDATE TQHB_DAYSAFE_CHKLST
               SET VNDR_MA_YN       = ''
                 , VNDR_MA_DT       = ''
             WHERE SIT_CD           = p_SIT_CD
               AND NCR_DOC_NO       = p_NCR_DOC_NO
            ;

        END IF;

    ELSE 

        -- 안전 부적합문서 번호 생성
        -- 년도별 순번 생성
        SELECT NVL( (MAX(NCR_SEQ)+1),'1' ) 
          INTO v_NCR_SEQ
          FROM TQHA_NCR_REP
         WHERE SUBSTR(PUBC_DT,1,4) = SUBSTR(p_PUBC_DT,1,4)
        ;
         -- 부적합 문서 번호 생성 
        v_NCR_SEQ1      := LPAD(v_NCR_SEQ, 5,'0')     ;
        v_NCR_DOC_NO    := 'NCR' || SUBSTR(p_PUBC_DT,1,4) || v_NCR_SEQ1 ;

        INSERT 
          INTO TQHA_NCR_REP
             ( SIT_CD                       -- 현장코드
             , NCR_DOC_NO                   -- 부적합문서번호
             , NCR_SEQ                      -- 년도별일련번호
             , PUBC_DT                      -- 발행일자
             --, NCR_TTL                    -- 부적합제목
             , MA_DDLN_DT                   -- 조치기한일자
             , CUST_CD                      -- 협력업체코드
             , VNDR_SEQ                     -- 업체순번
             --, VNDR_PSN                   -- 업체담당자
             --, VNDR_PSN_HP                -- 업체담당자연락처
             , CTP_CD                       -- 공종코드
             , NCR_LOC                      -- 발생위치
             , NCR_MATT                     -- 요구사항
             , NCR_CTS                      -- 부적합내용
             , NCR_PHOTO_GRP1               -- 첨부파일그룹사진1
             , NCR_PHOTO_DESC_1             -- 사진설명1
             , NCR_PHOTO_GRP2               -- 첨부파일그룹사진2
             , NCR_PHOTO_DESC_2             -- 사진설명2
             , NCR_WRTR                     -- 작성자
             , VNDR_NOTI_YN                 -- 발송 1 미발송 0
             , VNDR_NOTI_DT                 -- 업체통보일자
             , VNDR_MA_TTL                  -- 업체조치제목
             , VNDR_PRVN_CPLN               -- 업체재발방지대책
             , VNDR_MA_DT                   -- 업체조치일자
             , VNDR_MA_YN                   -- NCR조치(QS025) 1 조치, 2 미조치
             , VNDR_MA_CTS                  -- 업체조치내용
             , VNDR_MA_PSN                  -- 업체조치자
             , VNDR_PHOTO_GRP1              -- 업체조치그룹사진1
             , VNDR_PHOTO_DESC_1            -- 업체사진설명1
             , VNDR_PHOTO_GRP2              -- 업체조치그룹사진2
             , VNDR_PHOTO_DESC_2            -- 업체사진설명2
             , VNDR_APRV_YN                 -- 승인요청 1 미요청 0
             , VNDR_APRV_DT                 -- 업체승인요청일자
             , MGR_NOTI_YN                  -- 발송Y (SMS)
             , MGR_APRV_YN                  -- 승인 1, 반려 2
             , MGR_APRV_DT                  -- 관리자승인일자
             , NCR_CRT_DIV                  -- 부적합생성구분  1, 부적합, 2 안전점검, 3 추가위험       
             , DIRECT_YN                    -- 직영여부 
             , IPT_ID                       -- 입력ID
             , IPT_DTM                      -- 입력일시
             , IPT_IP                       -- 입력IP
             , UPD_ID                       -- 수정ID
             , UPD_DTM                      -- 수정일시
             , UPD_IP                       -- 수정IP
             )
        VALUES 
             ( p_SIT_CD                     -- 현장코드
             , v_NCR_DOC_NO                 -- 부적합문서번호
             , v_NCR_SEQ                    -- 년도별일련번호
             , p_PUBC_DT                    -- 발행일자
             --, p_NCR_TTL                  -- 부적합제목
             , p_MA_DDLN_DT                 -- 조치기한일자
             , p_CUST_CD                    -- 협력업체코드
             , p_VNDR_SEQ                   -- 업체순번
             --, p_VNDR_PSN                 -- 업체담당자
             --, p_VNDR_PSN_HP              -- 업체담당자연락처
             , p_CTP_CD                     -- 공종코드
             , p_NCR_LOC                    -- 발생위치
             , p_NCR_MATT                   -- 요구사항
             , p_NCR_CTS                    -- 부적합내용
             , p_NCR_PHOTO_GRP1             -- 첨부파일그룹사진1
             , p_NCR_PHOTO_DESC_1           -- 사진설명1
             , p_NCR_PHOTO_GRP2             -- 첨부파일그룹사진2
             , p_NCR_PHOTO_DESC_2           -- 사진설명2
             , p_NCR_WRTR                   -- 작성자
             , p_VNDR_NOTI_YN               -- 발송 1 미발송 0
             , p_VNDR_NOTI_DT               -- 업체통보일자
             , p_VNDR_MA_TTL                -- 업체조치제목
             , p_VNDR_PRVN_CPLN             -- 업체재발방지대책
             , p_VNDR_MA_DT                 -- 업체조치일자
             , p_VNDR_MA_YN                 -- NCR조치(QS025) 1 조치, 2 미조치
             , p_VNDR_MA_CTS                -- 업체조치내용
             , p_VNDR_MA_PSN                -- 업체조치자
             , p_VNDR_PHOTO_GRP1            -- 업체조치그룹사진1
             , p_VNDR_PHOTO_DESC_1          -- 업체사진설명1
             , p_VNDR_PHOTO_GRP2            -- 업체조치그룹사진2
             , p_VNDR_PHOTO_DESC_2          -- 업체사진설명2
             , p_VNDR_APRV_YN               -- 승인요청 1 미요청 0
             , p_VNDR_APRV_DT               -- 업체승인요청일자
             , p_MGR_NOTI_YN                -- 발송Y (SMS)
             , p_MGR_APRV_YN                -- 승인 1, 반려 2
             , p_MGR_APRV_DT                -- 관리자승인일자
             , p_NCR_CRT_DIV                -- 부적합생성구분  1, 부적합, 2 안전점검, 3 추가위험
             , p_DIRECT_YN                  -- 직영여부 
             , p_WRK_ID                     -- 입력ID 
             , SYSDATE()                    -- 입력일시
             , p_WRK_IP                     -- 입력IP
             , p_WRK_ID                     -- 수정ID
             , SYSDATE()                    -- 수정일시
             , p_WRK_IP                     -- 수정IP
             )
        ;

    END IF;

       p_RNT_NCR_DOC_NO := v_NCR_DOC_NO;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 5. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN 
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);

END ;
/

-- PQHA_ODAYSAFE_NCR_B (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_ODAYSAFE_NCR_B" ( -- 일일안전점검 결과 불량인경우 부적합보고서 생성 및 수정
    p_WRK_TP            VARCHAR2 :='I'                                  -- UPDATE FLAG( I: ISNERT, U:UPDATE, D:DELTE)
,   p_WRK_ID            VARCHAR2                                        -- 사용자 ID
,   p_WRK_IP            VARCHAR2                                        -- 사용자 IP
,   p_SIT_CD            TQHA_DAYSAFE_CHKLST.SIT_CD          %TYPE       -- 현장코드
,   p_PLN_YM            TQHA_DAYSAFE_CHKLST.PLN_YM          %TYPE       -- 계획년월
,   p_PLN_DGR           TQHA_DAYSAFE_CHKLST.PLN_DGR         %TYPE       -- 계획차수
,   p_ODAY_CHK_DT       TQHA_DAYSAFE_CHKLST.ODAY_CHK_DT     %TYPE       -- 점검일자
)
IS
    /**************************************************************************************************************************
      Purpose : 일일안전점검 결과 불량인경우 부적합보고서 생성 및 수정 

      REVISIONS
      Ver      Date               Author                  Description
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2022/7/04 14:24:00                         최초생성

    **************************************************************************************************************************/


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR2(200);            -- ERROR Message
    USER_EXCEPTION EXCEPTION;

    v_cnt           INTEGER;                            --
    v_NCR_SEQ       INTEGER;                            -- 안전 부적합순번 MAX
    v_NCR_SEQ1      TQHA_NCR_REP.NCR_DOC_NO%TYPE ;      -- 안전 부적합순번 MAX
    v_NCR_DOC_NO    TQHA_NCR_REP.NCR_DOC_NO%TYPE ;      -- 안전 부적합문서 번호

BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 필수입력 필드  Check  ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_SIT_CD IS NULL)  THEN
        ERR_MSG := '현장코드는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_ODAY_CHK_DT IS NULL)  THEN
        ERR_MSG := '일일점검일자는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Process 선행조건 Check ]
    ---------------------------------------------------------------------------------------------------------------------------


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Business Process ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_WRK_TP ='I') THEN

        /**** 일일안전점검결과 불량이 존재하는지 체크 ******/
        BEGIN
            FOR CHKLST_NCR 
             IN (   -- 일일점검결과 불량이 존재하는 지 체크
                    SELECT A.SIT_CD                 -- 현장코드
                         , A.PLN_YM                 -- 계획년월
                         , A.PLN_DGR                -- 계획차수
                         , A.ODAY_CHK_DT            -- 일일점검일자
                         , A.CTP_CD                 -- 공종코드
                         , A.UNT_CD                 -- 단위코드
                         , A.CHK_ITM_CD             -- 점검항목코드
                         , A.CUST_CD                -- 협력업체코드
                         , A.VNDR_SEQ               -- 협력업체순서
                         , A.ODAY_CHK_RSLT          -- 일일점검결과 (QS006) 1 N/A,2 완료(유지),3 불량
                         , B.CHK_ITM_NM             -- 위험요인 ( 부적합 내용으로 )
                         , A.ODAY_CHK_OPIN          -- 일일점검의견( 추가 요청사항으로  )
                         , A.ODAY_INSP              -- 일일 점검자
                         , A.PHOTO_GRP1             -- 첨부파일 그룹사진1
                         , A.PHOTO_DESC_1           -- 첨부파일 그룹사진설명1
                         , A.PHOTO_GRP2             -- 첨부파일 그룹사진2
                         , A.PHOTO_DESC_2           -- 첨부파일 그룹사진설명2
                         , A.NCR_PUBC_YN            -- 부적합발행여부
                         , A.NCR_DOC_NO             -- 부적합발행번호
                         , A.MA_DDLN_DT             -- 조치기한일자
                         , C.CHK_LOC                -- 점검위치
                      FROM TQHA_DAYSAFE_CHKLST  A
                         , TQHA_CTPUNT_CHKITM   B
                         , TQHA_RISK_CHK    C
                     WHERE A.CTP_CD         = B.CTP_CD
                       AND A.UNT_CD         = B.UNT_CD
                       AND A.CHK_ITM_CD     = B.CHK_ITM_CD
                       AND A.SIT_CD         = p_SIT_CD          -- 변수 (현장코드)
                       AND A.PLN_YM         = p_PLN_YM          -- 변수 (계획년월)
                       AND A.PLN_DGR        = p_PLN_DGR         -- 변수 (계획차수)
                       AND A.ODAY_CHK_DT    = p_ODAY_CHK_DT     -- 변수(점검일자)
                       AND A.ODAY_CHK_RSLT  = '3'               -- 점검결과가 불량인 것들
                       --AND A.VNDR_MA_YN   = '0'               -- 업체 조치 여부
                       AND A.SIT_CD         = C.SIT_CD
                       AND A.PLN_YM         = C.PLN_YM
                       AND A.PLN_DGR        = C.PLN_DGR
                       AND A.CUST_CD        = C.CUST_CD
                       AND A.VNDR_SEQ       = C.VNDR_SEQ
                       AND A.CTP_CD         = C.CTP_CD
                       AND A.UNT_CD         = C.UNT_CD
                       AND A.CHK_ITM_CD     = C.CHK_ITM_CD
                )
            LOOP

                -- 점검일자에 불량 데이타가 있는지 여부 채크
                IF CHKLST_NCR.ODAY_CHK_RSLT = '3' THEN

                    IF CHKLST_NCR.NCR_PUBC_YN = '1' THEN   -- 부적합보고서 발행여부가 존재하면

                        --  부적합보고서 업데이트 처리
                        UPDATE TQHA_NCR_REP
                           SET PUBC_DT              = CHKLST_NCR.ODAY_CHK_DT            -- 발행일자
                             , MA_DDLN_DT           = CHKLST_NCR.MA_DDLN_DT             -- 조치기한일자
                             , CUST_CD              = CHKLST_NCR.CUST_CD                -- 협력업체코드
                             , VNDR_SEQ             = CHKLST_NCR.VNDR_SEQ               -- 업체순번
                             , CTP_CD               = CHKLST_NCR.CTP_CD                 -- 공종코드
                             , NCR_LOC              = CHKLST_NCR.CHK_LOC                -- 발생위치
                             , NCR_MATT             = CHKLST_NCR.ODAY_CHK_OPIN          -- 요구사항
                             , NCR_CTS              = CHKLST_NCR.CHK_ITM_NM             -- 부적합내용
                             , NCR_PHOTO_GRP1       = CHKLST_NCR.PHOTO_GRP1             -- 첨부파일그룹사진1
                             , NCR_PHOTO_DESC_1     = CHKLST_NCR.PHOTO_DESC_1           -- 사진설명1
                             , NCR_PHOTO_GRP2       = CHKLST_NCR.PHOTO_GRP2             -- 첨부파일그룹사진2
                             , NCR_PHOTO_DESC_2     = CHKLST_NCR.PHOTO_DESC_2           -- 사진설명2
                             , NCR_WRTR             = CHKLST_NCR.ODAY_INSP              -- 작성자
                             --, VNDR_NOTI_YN       = p_VNDR_NOTI_YN                    -- 발송 1 미발송 0
                             --, VNDR_NOTI_DT       = p_VNDR_NOTI_DT                    -- 업체통보일자
                             --, VNDR_MA_TTL        = p_VNDR_MA_TTL                     -- 업체조치제목
                             --, VNDR_PRVN_CPLN     = p_VNDR_PRVN_CPLN                  -- 업체재발방지대책
                             --, VNDR_MA_DT         = p_VNDR_MA_DT                      -- 업체조치일자
                             --, VNDR_MA_YN         = p_VNDR_MA_YN                      -- NCR조치(QS025) 1 조치, 2 미조치
                             --, VNDR_MA_CTS        = p_VNDR_MA_CTS                     -- 업체조치내용
                             --, VNDR_MA_PSN        = p_VNDR_MA_PSN                     -- 업체조치자
                             --, VNDR_PHOTO_GRP1    = p_VNDR_PHOTO_GRP1                 -- 업체조치그룹사진1
                             --, VNDR_PHOTO_DESC_1  = p_VNDR_PHOTO_DESC_1               -- 업체사진설명1
                             --, VNDR_PHOTO_GRP2    = p_VNDR_PHOTO_GRP2                 -- 업체조치그룹사진2
                             --, VNDR_PHOTO_DESC_2  = p_VNDR_PHOTO_DESC_2               -- 업체사진설명2
                             --, VNDR_APRV_YN       = p_VNDR_APRV_YN                    -- 승인요청 1 미요청 0
                             --, VNDR_APRV_DT       = p_VNDR_APRV_DT                    -- 업체승인요청일자
                             --, MGR_NOTI_YN        = p_MGR_NOTI_YN                     -- 발송Y (SMS)
                             --, MGR_APRV_YN        = p_MGR_APRV_YN                     -- 승인 1, 반려 2
                             --, MGR_APRV_DT        = p_MGR_APRV_DT                     -- 관리자승인일자
                             , NCR_CRT_DIV          = '2'                               -- 부적합생성구분  1, 부적합, 2 안전점검, 3 추가위험
                             , UPD_ID               = p_WRK_ID                          -- 수정ID
                             , UPD_DTM              = SYSDATE()                         -- 수정일시
                             , UPD_IP               = p_WRK_IP                          -- 수정IP
                         WHERE SIT_CD               = CHKLST_NCR.SIT_CD                 -- 현장코드
                           AND NCR_DOC_NO           = CHKLST_NCR.NCR_DOC_NO             -- 부적합문서번호
                        ;

                    ELSE

                        -- 안전 부적합문서 번호 생성
                        -- 년도별 순번 생성
                        SELECT NVL( (MAX(NCR_SEQ)+1),'1' )
                          INTO v_NCR_SEQ
                          FROM TQHA_NCR_REP
                         WHERE SUBSTR(PUBC_DT,1,4) = SUBSTR(CHKLST_NCR.ODAY_CHK_DT,1,4)
                        ;
                        -- 부적합 문서 번호 생성
                        v_NCR_SEQ1      := LPAD(v_NCR_SEQ, 5,'0')     ;
                        v_NCR_DOC_NO    := 'NCR' || SUBSTR(CHKLST_NCR.ODAY_CHK_DT,1,4) || v_NCR_SEQ1 ;

                        -- 부적합보고서 INSERT 처리
                        INSERT 
                          INTO TQHA_NCR_REP
                             ( SIT_CD                           -- 현장코드
                             , NCR_DOC_NO                       -- 부적합문서번호
                             , NCR_SEQ                          -- 년도별일련번호
                             , PUBC_DT                          -- 발행일자
                             , MA_DDLN_DT                       -- 조치기한일자
                             , CUST_CD                          -- 협력업체코드
                             , VNDR_SEQ                         -- 업체순번
                             , CTP_CD                           -- 공종코드
                             , NCR_LOC                          -- 발생위치
                             , NCR_MATT                         -- 요구사항
                             , NCR_CTS                          -- 부적합내용
                             , NCR_PHOTO_GRP1                   -- 첨부파일그룹사진1
                             , NCR_PHOTO_DESC_1                 -- 사진설명1
                             , NCR_PHOTO_GRP2                   -- 첨부파일그룹사진2
                             , NCR_PHOTO_DESC_2                 -- 사진설명2
                             , NCR_WRTR                         -- 작성자
                             --, VNDR_NOTI_YN                   -- 발송 1 미발송 0
                             --, VNDR_NOTI_DT                   -- 업체통보일자
                             --, VNDR_MA_TTL                    -- 업체조치제목
                             --, VNDR_PRVN_CPLN                 -- 업체재발방지대책
                             --, VNDR_MA_DT                     -- 업체조치일자
                             --, VNDR_MA_CTS                    -- 업체조치내용
                             --, VNDR_MA_PSN                    -- 업체조치자
                             --, VNDR_PHOTO_GRP1                -- 업체조치그룹사진1
                             --, VNDR_PHOTO_DESC_1              -- 업체사진설명1
                             --, VNDR_PHOTO_GRP2                -- 업체조치그룹사진2
                             --, VNDR_PHOTO_DESC_2              -- 업체사진설명2
                             --, VNDR_APRV_YN                   -- 승인요청 1 미요청 0
                             --, VNDR_APRV_DT                   -- 업체승인요청일자
                             --, MGR_NOTI_YN                    -- 발송Y (SMS)
                             --, MGR_APRV_YN                    -- 승인 1, 반려 2
                             --, MGR_APRV_DT                    -- 관리자승인일자
                             , VNDR_MA_YN                       -- NCR조치(QS025) 1 조치, 2 미조치
                             , NCR_CRT_DIV                      -- 부적합생성구분  1, 부적합, 2 안전점검, 3 추가위험
                             , IPT_ID                           -- 입력ID
                             , IPT_DTM                          -- 입력일시
                             , IPT_IP                           -- 입력IP
                             , UPD_ID                           -- 수정ID
                             , UPD_DTM                          -- 수정일시
                             , UPD_IP                           -- 수정IP
                             )
                        VALUES 
                             ( CHKLST_NCR.SIT_CD                -- 현장코드
                             , v_NCR_DOC_NO                     -- 부적합문서번호
                             , v_NCR_SEQ                        -- 년도별일련번호
                             , CHKLST_NCR.ODAY_CHK_DT           -- 발행일자
                             , CHKLST_NCR.MA_DDLN_DT            -- 조치기한일자
                             , CHKLST_NCR.CUST_CD               -- 협력업체코드
                             , CHKLST_NCR.VNDR_SEQ              -- 협력업체순번
                             , CHKLST_NCR.CTP_CD                -- 공종코드
                             , CHKLST_NCR.CHK_LOC               -- 발생위치
                             , CHKLST_NCR.ODAY_CHK_OPIN         -- 요구사항
                             , CHKLST_NCR.CHK_ITM_NM            -- 부적합내용
                             , CHKLST_NCR.PHOTO_GRP1            -- 첨부파일 그룹사진1
                             , CHKLST_NCR.PHOTO_DESC_1          -- 첨부파일 그룹사진설명1
                             , CHKLST_NCR.PHOTO_GRP2            -- 첨부파일 그룹사진2
                             , CHKLST_NCR.PHOTO_DESC_2          -- 첨부파일 그룹사진설명2
                             , CHKLST_NCR.ODAY_INSP             -- 작성자
                             , '2'                              -- 업체조치여부
                             , '2'                              -- 부적합보고서 생성구분( 1, 부적합, 2 안전점검, 3 추가위험 )
                             , p_WRK_ID                         -- 입력ID
                             , SYSDATE()                        -- 입력일시
                             , p_WRK_IP                         -- 입력IP
                             , p_WRK_ID                         -- 수정ID
                             , SYSDATE()                        -- 수정일시
                             , p_WRK_IP                         -- 수정IP
                             )
                        ;

                        -- 부적합 보고서 생성 후  일일점검 결과 업데이트 처리(부적합 발행여부 및 부적합문서번호)

                        UPDATE TQHA_DAYSAFE_CHKLST
                           SET NCR_PUBC_YN          = '1'                       --발행 1, 미발행 0
                              ,NCR_DOC_NO           = v_NCR_DOC_NO              --부적합문서번호
                              ,UPD_ID               = p_WRK_ID                  --수정ID
                              ,UPD_DTM              = SYSDATE()                 --수정일시
                              ,UPD_IP               = p_WRK_IP                  --수정IP
                         WHERE SIT_CD = CHKLST_NCR.SIT_CD         --현장코드
                           AND PLN_YM = CHKLST_NCR.PLN_YM           --계획년월
                           AND PLN_DGR = CHKLST_NCR.PLN_DGR         --차수구분코드(QS005) 1 1차,2 2차
                           AND ODAY_CHK_DT = CHKLST_NCR.ODAY_CHK_DT --일일점검일자
                           AND CTP_CD = CHKLST_NCR.CTP_CD           --공종코드
                           AND UNT_CD = CHKLST_NCR.UNT_CD          --단위코드
                           AND CHK_ITM_CD = CHKLST_NCR.CHK_ITM_CD ;  --점검항목코드

                    END IF ;

                END IF;
            END LOOP;

        END;
    END IF;


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 5. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);
END PQHA_ODAYSAFE_NCR_B ;
/

-- PQHA_PERF_VNDR_Q (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_PERF_VNDR_Q" 
(
      p_WRK_TP  	VARCHAR2 DEFAULT 'Q'    -- FLAG( Q: SELECT )
     ,p_SIT_CD 	VARCHAR2                -- 현장코드 
     ,p_MSRM_YM 	VARCHAR2                -- 해당년월
     ,RTN_CURSOR 	OUT SYS_REFCURSOR
)
IS  
    /**************************************************************************************************************************
      Purpose : 성과측정 해당년월의 협력업체 성과측정 결과

      REVISIONS
      Ver      Date               Author                  Description  
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2022/5/19 11:38:19                            최초생성

    **************************************************************************************************************************/
    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR2(200);            -- ERROR Message
    USER_EXCEPTION EXCEPTION;


BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 수행전 Check Logic ]
    ---------------------------------------------------------------------------------------------------------------------------


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Logic 처리
    ---------------------------------------------------------------------------------------------------------------------------
    IF p_WRK_TP = 'Q' THEN

	   OPEN RTN_CURSOR FOR
        SELECT A.SIT_CD                                                           -- 현장코드
             , A.CUST_CD                                                          -- 협력업체코드
             , A.VNDR_SEQ                                                         -- 협력업체순번
             , B.CUST_NM	                                                      -- 협력업체명칭
             , C.TOT_CNT                                                          -- 점검합계 건수
             , C.NA_CNT                                                           -- N/A 건수
             , C.CMPL_CNT                                                         -- 완료 건수(적합)
             , C.NO_CNT                                                           -- 불량 건수(부적합)
             , NVL(ROUND((C.CMPL_CNT / C.TOT_CNT) * 100, 2), 0) AS CMPL_RATE                   -- 적합율
             , E.NCR_CNT                                                          -- 부적합 전체 건수(합계)                
             , E.NCR_MA_CNT                                                       -- 부적합 조치 건수
             , E.NCR_NON_CNT                                                      -- 부적합 미조치 건수        
             , NVL(ROUND((E.NCR_MA_CNT / E.NCR_CNT) * 100, 2), 0) AS NCR_RATE                 -- 조치율                                        
             , D.ADD_CNT                                                          -- 추가 위험 전체 건수(합계)                
             , D.ADD_MA_CNT                                                       -- 추가 조치 건수
             , D.ADD_NON_CNT                                                      -- 추가 미조치 건수         
             , NVL(ROUND((D.ADD_MA_CNT / D.ADD_CNT) * 100, 2), 0) AS ADD_RATE                 -- 조치율
             , ( NVL(ROUND(ROUND((C.CMPL_CNT / C.TOT_CNT) * 100, 2) * 0.4, 2), 0) +
               NVL(ROUND(ROUND((E.NCR_MA_CNT / E.NCR_CNT) * 100, 2) * 0.3, 2), 0) +
               NVL(ROUND(ROUND((D.ADD_MA_CNT / D.ADD_CNT) * 100, 2) * 0.3, 2), 0) ) AS AVRG -- 가중치평균
        FROM TQHA_VNDR A,
             VQSZ_TRADE B,
             ( -- 성과측정 업체별 중점점검 건수
                 SELECT SIT_CD                                                   -- 현장코드
                      , CUST_CD                                                   -- 평가대상자 iD) 작성자                     
                      , COUNT(ODAY_CHK_RSLT)                          AS TOT_CNT  -- 점검합계 건수
                      , NVL(SUM(DECODE(ODAY_CHK_RSLT, '1', 1, 0)), 0) AS NA_CNT   -- N/A 건수
                      , NVL(SUM(DECODE(ODAY_CHK_RSLT, '2', 1, 0)), 0) AS CMPL_CNT -- 완료 건수(적합)
                      , NVL(SUM(DECODE(ODAY_CHK_RSLT, '3', 1, 0)), 0) AS NO_CNT   -- 불량 건수(부적합)
                 FROM TQHA_DAYSAFE_CHKLST
                 WHERE SIT_CD = p_SIT_CD -- 변수(현장코드)                   
                   AND SUBSTR(ODAY_CHK_DT, 1, 6) = p_MSRM_YM --변수(해당년월)
                 GROUP BY SIT_CD, CUST_CD
             ) C,
             ( -- 성과측정 업체별 추가발굴 지시건수(합)
                 SELECT SIT_CD                                                                           -- 현장코드  
                      , CUST_CD                                                                           -- 업체코드
                      , NVL(count(WRT_DT), 0)                                              AS ADD_CNT     -- 추가 위험 전체 건수(합계)
                      , NVL(SUM(DECODE(VNDR_MA_YN, '2', 1, 0)), 0)                         AS ADD_NON_CNT -- 추가 미조치 건수
                      , NVL(count(WRT_DT), 0) - NVL(SUM(DECODE(VNDR_MA_YN, '2', 1, 0)), 0) AS ADD_MA_CNT  -- 추가 조치 건수
                 FROM TQHA_ADDRISK_ORD
                 WHERE SIT_CD = p_SIT_CD -- 변수(현장코드) 
                   AND SUBSTR(WRT_DT, 1, 6) = p_MSRM_YM --변수(해당년월) 
                 GROUP BY SIT_CD, CUST_CD
             ) D,
             ( -- 성과측정 업체별 부적합 지시건수(합)
                 SELECT SIT_CD                                                                            -- 현장코드  
                      , CUST_CD                                                                            -- 업체코드
                      , NVL(count(PUBC_DT), 0)                                              AS NCR_CNT     -- 부적합 전체 건수(합계)
                      , NVL(SUM(DECODE(VNDR_MA_YN, '2', 1, 0)), 0)                          AS NCR_NON_CNT -- 부적합 미조치 건수
                      , NVL(count(PUBC_DT), 0) - NVL(SUM(DECODE(VNDR_MA_YN, '2', 1, 0)), 0) AS NCR_MA_CNT  -- 부적합 조치 건수
                 FROM TQHA_NCR_REP
                 WHERE SIT_CD = p_SIT_CD -- 변수(현장코드) 
                   AND SUBSTR(PUBC_DT, 1, 6) = p_MSRM_YM --변수(해당년월) 
                 GROUP BY SIT_CD, CUST_CD
             ) E
        WHERE A.SIT_CD = p_SIT_CD -- 변수(현장코드) 
          AND A.CUST_CD = B.CUST_CD
          AND A.CUST_CD = C.CUST_CD(+)
          AND A.CUST_CD = D.CUST_CD(+)
          AND A.CUST_CD = E.CUST_CD(+)		;							

    END IF ;      

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN 
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);

END ;
/

-- PQHA_PRES_SITE_CST_Q (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_PRES_SITE_CST_Q" (
    p_WRK_TP            VARCHAR2 DEFAULT 'Q'                    -- FLAG( Q1: 대표현장 목록 조회, Q2 : 대표현장에 속한 현장 목록 조회, Q3 : 월별실적 조회   )
,   p_DEPT_CD           VARCHAR2                                -- 부서코드
,   p_WRK_ID            VARCHAR2                                -- 아이디
,   p_SIT_CD            TQHA_PRES_SITE.SIT_CD       %TYPE       -- 현장코드
,   RTN_CURSOR          OUT SYS_REFCURSOR
)
IS
    /**************************************************************************************************************************
      Purpose : 안전 대표현장 목록

      REVISIONS
      Ver      Date               Author                  Description
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2024/04/02 10:45:18                         최초생성

    **************************************************************************************************************************/


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR2(200);            -- ERROR Message
    USER_EXCEPTION EXCEPTION;

    v_DEPT_CD      VARCHAR2(10);             -- 부서코드
    v_HO_SITE_DIV  VARCHAR2(20);             -- 본사현장구분
    v_PRES_SIT_CD  VARCHAR2(10);             -- 대표현장코드

BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 수행전 Check Logic ]
    ---------------------------------------------------------------------------------------------------------------------------

    -- 부서코드, 본사현장구분
    SELECT DEPT_CD, HO_SITE_DIV
      INTO v_DEPT_CD, v_HO_SITE_DIV
      FROM TCOZ_DEPT_INFO
     WHERE DEPT_CD = p_DEPT_CD;

    -- 안전팀이 아니거나 사용자가 ID가 dev_hs가 아닌 경우
    IF NOT( v_DEPT_CD = 'HS1040' OR p_WRK_ID = 'dev_hs') THEN

        BEGIN
            SELECT PRES_SIT_CD
              INTO v_PRES_SIT_CD
              FROM TQHA_PRES_SITE
             WHERE SIT_CD  = p_DEPT_CD    -- 현장코드
            ;

        EXCEPTION WHEN NO_DATA_FOUND THEN
            v_PRES_SIT_CD := '9999999999';
     END;

    END IF;


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Logic 처리
    ---------------------------------------------------------------------------------------------------------------------------

    ------------------------------------------------
    -- 대표현장 목록 조회
    ------------------------------------------------
    IF (p_WRK_TP = 'Q1') THEN

        OPEN RTN_CURSOR FOR
        SELECT TP.PRES_SIT_CD       AS PRES_SIT_CD
             , MAX(VS.CNST_NM)      AS PRES_SIT_NM
             , MAX(TP.RMKS)         AS RMKS
          FROM TQHA_PRES_SITE       TP
          LEFT JOIN VQSZ_SITEINFO   VS ON TP.PRES_SIT_CD = VS.SIT_CD
         WHERE TP.PRES_SIT_CD LIKE '%' || v_PRES_SIT_CD || '%'
         GROUP BY TP.PRES_SIT_CD
         ORDER BY TP.PRES_SIT_CD
        ;

    ------------------------------------------------
    -- 대표현장에 속한 현장 목록 조회
    ------------------------------------------------
    ELSIF (p_WRK_TP = 'Q2') THEN

        OPEN RTN_CURSOR FOR
        SELECT TP.SIT_CD        AS SIT_CD
             , VS.CNST_NM       AS SIT_NM
             , TP.RMKS          AS RMKS
          FROM TQHA_PRES_SITE       TP
          LEFT JOIN VQSZ_SITEINFO   VS ON TP.SIT_CD = VS.SIT_CD
         WHERE TP.PRES_SIT_CD = p_SIT_CD
         ORDER BY PRES_SIT_CD
        ;

    ------------------------------------------------
    -- 월별실적 조회
    ------------------------------------------------
    ELSIF (p_WRK_TP = 'Q3') THEN

        OPEN RTN_CURSOR FOR
        /*
        SELECT   A.SIT_CD
                ,A.RLV_YM
        --        ,A.ITM_DIV
                ,SUM(NVL(B.T_USE_AMT, 0)) + SUM(NVL(B1.T_USE_AMT,0)) AS T_USE_AMT -- 당월 실적금액
                , SUM(DECODE(A.ITM_DIV, '01', NVL(B.T_USE_AMT, 0) + NVL(B1.T_USE_AMT,0) , 0)) AS T_USE_AMT1  -- 1. 안전.보건관리자 임금 등
                , SUM(DECODE(A.ITM_DIV, '02', NVL(B.T_USE_AMT, 0) + NVL(B1.T_USE_AMT,0) , 0)) AS T_USE_AMT2  -- 2. 안전시설비 등
                , SUM(DECODE(A.ITM_DIV, '03', NVL(B.T_USE_AMT, 0) + NVL(B1.T_USE_AMT,0) , 0)) AS T_USE_AMT3  -- 3. 보호구 등
                , SUM(DECODE(A.ITM_DIV, '04', NVL(B.T_USE_AMT, 0) + NVL(B1.T_USE_AMT,0) , 0)) AS T_USE_AMT4  -- 4. 안전보건진단비 등
                , SUM(DECODE(A.ITM_DIV, '05', NVL(B.T_USE_AMT, 0) + NVL(B1.T_USE_AMT,0) , 0)) AS T_USE_AMT5  -- 5. 안전보건교육비 등
                , SUM(DECODE(A.ITM_DIV, '06', NVL(B.T_USE_AMT, 0) + NVL(B1.T_USE_AMT,0) , 0)) AS T_USE_AMT6  -- 6. 근로자 건강장애예방비 등
                , SUM(DECODE(A.ITM_DIV, '07', NVL(B.T_USE_AMT, 0) + NVL(B1.T_USE_AMT,0) , 0)) AS T_USE_AMT7  -- 7. 안전.보건관리자 임금 등
                , SUM(DECODE(A.ITM_DIV, '08', NVL(B.T_USE_AMT, 0) + NVL(B1.T_USE_AMT,0) , 0)) AS T_USE_AMT8  -- 8. 본사전담조직 근로자임금
                , SUM(DECODE(A.ITM_DIV, '09', NVL(B.T_USE_AMT, 0) + NVL(B1.T_USE_AMT,0) , 0)) AS T_USE_AMT9  -- 9 위험성평가에 따른 소요비용
                , SUBSTR(A.RLV_YM, 1 , 4 ) AS RLV_Y                                                           -- 해당년도
            FROM  TQHA_SAFECOST_BGTYM A
                 ,( -- 당사 당월 사용금액
                         SELECT SIT_CD
                              , RLV_YM
                              , ITM_DIV
                              , NVL(SUM(USE_AMT), 0) AS T_USE_AMT -- 당월 사용금액
                         FROM TQHA_SAFECOST_ARSLT
                         WHERE SIT_CD = p_SIT_CD              -- 변수 (현장코드)
                         GROUP BY SIT_CD, RLV_YM, ITM_DIV
                         ORDER BY SIT_CD, RLV_YM, ITM_DIV) B
                 ,( -- 업체 당월 사용금액
                         SELECT A.SIT_CD                           -- 현장코드
                              , A.RLV_YM
                              , A.ITM_DIV                           --
                              , NVL(SUM(A.USE_AMT), 0) AS T_USE_AMT -- 업체 당월 금액
                        FROM TQHA_SAFECOST_ARSLT_CO A, TQHA_SAFECOST_MMARSLT_CO B
                        WHERE A.SIT_CD =  p_SIT_CD              -- 변수 (현장코드)
                          AND A.SIT_CD = B.SIT_CD(+)
                          AND A.CUST_CD = B.CUST_CD(+)
                          AND A.VNDR_SEQ = B.VNDR_SEQ(+)
                          AND A.RLV_YM = B.RLV_YM(+)
                          AND B.SITE_APRV_YN = '1'     -- 승인
                        GROUP BY A.SIT_CD, A.RLV_YM, A.ITM_DIV) B1
                  ,(  -- 결재 완료 여부 체크 (20240920 결재완료 상태만 조회)
                     SELECT A.SIT_CD
                             ,A.APRV_YM
                             ,A.APRV_DIV
                             ,A.APRV_NO
                             ,B.APRV_STATS           -- 결재완료 인 상태
                         FROM TQHA_SAFECOST_APRV A
                             ,TQHA_APRV B
                       WHERE A.APRV_DIV = 2   -- 현장 안전관리비
                         AND A.SIT_CD  =  B.SIT_CD
                         AND A.APRV_NO =  B.APRV_NO
                         AND B.APRV_STATS = '4'  -- 결재완료 인 상태
                   ) C      -- 결재완료 인 상태
              WHERE A.SIT_CD  = p_SIT_CD              -- 변수 (현장코드)
                AND A.SIT_CD  = B.SIT_CD(+)
                AND A.RLV_YM  = B.RLV_YM(+)
                AND A.ITM_DIV = B.ITM_DIV(+)
                AND A.SIT_CD  = B1.SIT_CD(+)
                AND A.RLV_YM  = B1.RLV_YM(+)
                AND A.ITM_DIV = B1.ITM_DIV(+)
                -- 20240920 결재완료 상태인것만 금액표시
                AND A.SIT_CD  =  C.SIT_CD
                AND A.RLV_YM  =  C.APRV_YM
            GROUP BY A.SIT_CD, A.RLV_YM
            ORDER BY A.SIT_CD, A.RLV_YM ;
        */

        -- 20250106 대표현장별 산업안전보건관리비 집계
        WITH TQSA_PRES_HS_PER 
            AS (-- 대표현장의 개별현장별 당사 당월 사용금액
                SELECT A.SIT_CD
                     , A.RLV_YM
                     , A.ITM_DIV
                     , NVL(SUM(A.USE_AMT), 0)   AS T_USE_AMT    -- 당월 사용금액
                  FROM TQHA_SAFECOST_ARSLT  A
                     , TQHA_PRES_SITE       B                   -- 대표현장
                 WHERE A.SIT_CD             = B.SIT_CD          -- 대표현장별 개별현장코드
                   AND B.PRES_SIT_CD        = p_SIT_CD
                 GROUP BY A.SIT_CD, A.RLV_YM, A.ITM_DIV
                 ORDER BY A.SIT_CD, A.RLV_YM, A.ITM_DIV
               )
        , TQSA_PRES_CU_PER 
            AS (-- 대표현장의 개별현장별 업체 당월 사용금액
                SELECT A.SIT_CD                                 -- 현장코드
                     , A.RLV_YM
                     , A.ITM_DIV                                --
                     , NVL(SUM(A.USE_AMT), 0)   AS T_USE_AMT    -- 업체 당월 금액
                  FROM TQHA_SAFECOST_ARSLT_CO   A
                     , TQHA_SAFECOST_MMARSLT_CO B
                     , TQHA_PRES_SITE           C               -- 대표현장
                 WHERE A.SIT_CD                 = C.SIT_CD      -- 대표현장별 개별현장코드
                   AND A.SIT_CD                 = B.SIT_CD(+)
                   AND C.PRES_SIT_CD            = p_SIT_CD
                   AND A.CUST_CD                = B.CUST_CD(+)
                   AND A.VNDR_SEQ               = B.VNDR_SEQ(+)
                   AND A.RLV_YM                 = B.RLV_YM(+)
                   AND B.SITE_APRV_YN           = '1'           -- 승인
                 GROUP BY A.SIT_CD, A.RLV_YM, A.ITM_DIV
               )
        , TTQSA_PRES_APRV  
            AS (-- 결재 완료 여부 체크 (20240920 결재완료 상태만 조회)
                SELECT A.SIT_CD
                     , A.APRV_YM
                     , A.APRV_DIV
                     , A.APRV_NO
                     , B.APRV_STATS                             -- 결재완료 인 상태
                  FROM TQHA_SAFECOST_APRV   A
                     , TQHA_APRV            B
                 WHERE A.APRV_DIV               = 2             -- 현장 안전관리비
                   AND A.SIT_CD                 =  B.SIT_CD
                   AND A.APRV_NO                =  B.APRV_NO
                   AND B.APRV_STATS             = '4'           -- 결재완료 인 상태
               )
        SELECT A1.RLV_YM
             --, A1.ITM_DIV
             , SUM(NVL(B.T_USE_AMT, 0)) + SUM(NVL(B1.T_USE_AMT,0))                              AS T_USE_AMT        -- 당월 실적금액
             , SUM(DECODE(A1.ITM_DIV, '01', NVL(B.T_USE_AMT, 0) + NVL(B1.T_USE_AMT,0) , 0))     AS T_USE_AMT1       -- 1. 안전.보건관리자 임금 등
             , SUM(DECODE(A1.ITM_DIV, '02', NVL(B.T_USE_AMT, 0) + NVL(B1.T_USE_AMT,0) , 0))     AS T_USE_AMT2       -- 2. 안전시설비 등
             , SUM(DECODE(A1.ITM_DIV, '03', NVL(B.T_USE_AMT, 0) + NVL(B1.T_USE_AMT,0) , 0))     AS T_USE_AMT3       -- 3. 보호구 등
             , SUM(DECODE(A1.ITM_DIV, '04', NVL(B.T_USE_AMT, 0) + NVL(B1.T_USE_AMT,0) , 0))     AS T_USE_AMT4       -- 4. 안전보건진단비 등
             , SUM(DECODE(A1.ITM_DIV, '05', NVL(B.T_USE_AMT, 0) + NVL(B1.T_USE_AMT,0) , 0))     AS T_USE_AMT5       -- 5. 안전보건교육비 등
             , SUM(DECODE(A1.ITM_DIV, '06', NVL(B.T_USE_AMT, 0) + NVL(B1.T_USE_AMT,0) , 0))     AS T_USE_AMT6       -- 6. 근로자 건강장애예방비 등
             , SUM(DECODE(A1.ITM_DIV, '07', NVL(B.T_USE_AMT, 0) + NVL(B1.T_USE_AMT,0) , 0))     AS T_USE_AMT7       -- 7. 안전.보건관리자 임금 등
             , SUM(DECODE(A1.ITM_DIV, '08', NVL(B.T_USE_AMT, 0) + NVL(B1.T_USE_AMT,0) , 0))     AS T_USE_AMT8       -- 8. 본사전담조직 근로자임금
             , SUM(DECODE(A1.ITM_DIV, '09', NVL(B.T_USE_AMT, 0) + NVL(B1.T_USE_AMT,0) , 0))     AS T_USE_AMT9       -- 9 위험성평가에 따른 소요비용
             , SUBSTR(A1.RLV_YM, 1 , 4 )                                                        AS RLV_Y            -- 해당년도
          FROM TQHA_PRES_SITE A                     -- 대표현장 목록
             , TQHA_SAFECOST_BGTYM A1
             , TQSA_PRES_HS_PER B                   -- 대표현장의 개별현장별 당사 당월 사용금액
             , TQSA_PRES_CU_PER B1                  -- 대표현장의 개별현장별 업체 당월 사용금액
             , TTQSA_PRES_APRV C                    -- 결재 완료 여부 체크 (20240920 결재완료 상태만 조회)
         WHERE A.PRES_SIT_CD        = p_SIT_CD      -- 변수 (현장코드)
           AND A.SIT_CD             = A1.SIT_CD     -- 대표현장에 속한 현장만
           AND A.SIT_CD             = B.SIT_CD(+)
           AND A1.RLV_YM            = B.RLV_YM(+)
           AND A1.ITM_DIV           = B.ITM_DIV(+)
           AND A.SIT_CD             = B1.SIT_CD(+)
           AND A1.RLV_YM            = B1.RLV_YM(+)
           AND A1.ITM_DIV           = B1.ITM_DIV(+)
           AND A.SIT_CD             =  C.SIT_CD
           AND A1.RLV_YM            =  C.APRV_YM
         GROUP BY A1.RLV_YM
         ORDER BY A1.RLV_YM 
        ;

    END IF;


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);
END ;
/

-- PQHA_PRES_SITE_Q (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_PRES_SITE_Q" (
    p_WRK_TP        VARCHAR2 DEFAULT 'Q'        -- FLAG( Q: SELECT )
,   RTN_CURSOR      OUT SYS_REFCURSOR
)
IS 
    /**************************************************************************************************************************
      Purpose : 대표현장 설정 조회

      REVISIONS
      Ver      Date               Author                  Description 
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2025/01/31 13:54:33                         최초생성

    /**************************************************************************************************************************/


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR2(200);            -- ERROR Message
    USER_EXCEPTION EXCEPTION;


BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 수행전 Check Logic ]
    ---------------------------------------------------------------------------------------------------------------------------


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Logic 처리
    ---------------------------------------------------------------------------------------------------------------------------

    OPEN RTN_CURSOR FOR
    SELECT TR.SIT_CD            AS SIT_CD           -- 현장코드
         , TR.PRES_SIT_CD       AS PRES_SIT_CD      -- 데표현장코드
         , TR.PRES_YN           AS PRES_YN          -- 대표현장여부
         , TR.RMKS              AS RMKS             -- 비고
         , VS1.CNST_NM          AS SIT_NM           -- 현장명
         , VS2.CNST_NM          AS PRES_SIT_NM      -- 대표현장명
      FROM TQHA_PRES_SITE TR
      LEFT JOIN VQSZ_SITEINFO VS1 ON TR.SIT_CD      = VS1.SIT_CD
      LEFT JOIN VQSZ_SITEINFO VS2 ON TR.PRES_SIT_CD = VS2.SIT_CD
     ORDER BY TR.PRES_SIT_CD
    ;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN 
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);
END ;
/

-- PQHA_PRES_SITE_S (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_PRES_SITE_S" (
    p_WRK_TP            VARCHAR2 :='U'                                      -- UPDATE FLAG( I: ISNERT, U:UPDATE, D:DELTE)
,   p_WRK_ID            VARCHAR2                                            -- 사용자 ID 
,   p_WRK_IP            VARCHAR2                                            -- 사용자 IP 
,   p_SIT_CD            TQHA_PRES_SITE.SIT_CD               %TYPE           -- 현장코드
,   p_PRES_SIT_CD       TQHA_PRES_SITE.PRES_SIT_CD          %TYPE           -- 데표현장코드
,   p_PRES_YN           TQHA_PRES_SITE.PRES_YN              %TYPE           -- 대표현장여부
,   p_RMKS              TQHA_PRES_SITE.RMKS                 %TYPE           -- 비고
) 
IS 
    /**************************************************************************************************************************
      Purpose : 대표현장 설정 저장

      REVISIONS
      Ver      Date               Author                  Description 
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2025/01/31 13:55:03                         최초생성

    /**************************************************************************************************************************/

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR2(200);            -- ERROR Message
    USER_EXCEPTION EXCEPTION;

    v_CNT          NUMBER := 0;              -- 중복체크
BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 필수입력 필드  Check  ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_SIT_CD IS NULL)  THEN
        ERR_MSG := '현장코드는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Process 선행조건 Check ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_WRK_TP ='I') THEN
        SELECT COUNT(*)
          INTO v_CNT
          FROM TQHA_PRES_SITE
         WHERE SIT_CD = p_SIT_CD
        ;

        IF (v_CNT > 0) THEN
            ERR_MSG := '이미 등록되어 있는 현장입니다.';
            RAISE USER_EXCEPTION;
        END IF;

    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Business Process ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_WRK_TP ='D') THEN

        DELETE 
          FROM TQHA_PRES_SITE
         WHERE SIT_CD = p_SIT_CD         --현장코드
        ;

    ELSIF (p_WRK_TP ='U') THEN

        UPDATE TQHA_PRES_SITE
           SET PRES_SIT_CD      = p_PRES_SIT_CD     -- 대표현장코드
             , PRES_YN          = p_PRES_YN         -- 대표현장여부
             , RMKS             = p_RMKS            -- 비고
             , UPD_ID           = p_WRK_ID          -- 수정ID 
             , UPD_DTM          = SYSDATE()         -- 수정일시
             , UPD_IP           = p_WRK_IP          -- 수정IP
         WHERE SIT_CD           = p_SIT_CD          -- 현장코드
        ;

    ELSE 

        INSERT 
          INTO TQHA_PRES_SITE
             ( SIT_CD           -- 현장코드
             , PRES_SIT_CD      -- 대표현장코드
             , PRES_YN          -- 대표현장여부
             , RMKS             -- 비고
             , IPT_ID           -- 입력ID
             , IPT_DTM          -- 입력일시
             , IPT_IP           -- 입력IP
             , UPD_ID           -- 수정ID
             , UPD_DTM          -- 수정일시
             , UPD_IP           -- 수정IP
             )
        VALUES 
             ( p_SIT_CD         -- 현장코드
             , p_PRES_SIT_CD    -- 대표현장코드
             , p_PRES_YN        -- 대표현장여부
             , p_RMKS           -- 비고
             , p_WRK_ID         -- 입력ID 
             , SYSDATE()        -- 입력일시
             , p_WRK_IP         -- 입력IP
             , p_WRK_ID         -- 수정ID
             , SYSDATE()        -- 수정일시
             , p_WRK_IP         -- 수정IP
             )
        ;

    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 5. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN 
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);

END PQHA_PRES_SITE_S;
/

-- PQHA_RISKPLAN_D_B (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_RISKPLAN_D_B" ( -- 단위작업별 보사
    p_WRK_TP            VARCHAR2 :='I'                              -- UPDATE FLAG( I: ISNERT, U:UPDATE, D:DELTE)
,   p_WRK_ID            VARCHAR2                                    -- 사용자 ID
,   p_WRK_IP            VARCHAR2                                    -- 사용자 IP
,   p_WRK_DIV           VARCHAR2                                    -- 작업구분 (2:공종별 단위작업, 3:사용자정의 위험요인항목)
,   p_SIT_CD            TQHA_RISKPLAN_D.SIT_CD          %TYPE       -- 현장코드
,   p_FST_DIV           TQHA_RISKPLAN_D.FST_DIV         %TYPE       -- 위험성평가최초구분(QS001) 최초1,연간2
,   p_PLN_DGR           TQHA_RISKPLAN_D.PLN_DGR         %TYPE       -- 계획차수
,   p_CTP_CD            TQHA_RISKPLAN_D.CTP_CD          %TYPE       -- 공종코드
,   p_UNT_CD            TQHA_RISKPLAN_D.UNT_CD          %TYPE       -- 단위코드
,   p_CHK_ITM_CD        TQHA_RISKPLAN_D.CHK_ITM_CD      %TYPE       -- 위험요인 항목코드
)
IS
    /**************************************************************************************************************************
      Purpose : 위험성 평가 최초 (단위항목별 복사하기 )

      REVISIONS
      Ver      Date               Author                  Description
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2021/10/14 12:48:42                         최초생성
      1.1     2022/05/31                                  공종별 담당자 지정이 안된경우 수정
    **************************************************************************************************************************/


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR2(200);            -- ERROR Message
    USER_EXCEPTION EXCEPTION;

     v_cnt2  INTEGER;                               -- 단위작업 항목 존재 여부
     v_cnt3  INTEGER;                               -- 위험요인 항목 존재 여부
     v_UNT_NM  VARCHAR2(100);                       -- 단위명칭
     v_CHK_ITM_NM VARCHAR2(100);                    -- 위험요인 항목 명칭

BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 필수입력 필드  Check  ]
    ---------------------------------------------------------------------------------------------------------------------------



    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Process 선행조건 Check ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF p_WRK_DIV = '2' THEN      -- 단위점검별로 추가

        --  단위작업별 위험요인 항목 존재 여부 확인
        IF p_WRK_TP = 'I' THEN

            SELECT nvl(COUNT(CHK_ITM_CD),0)
              INTO v_cnt2
              FROM TQHA_RISKPLAN_D
             WHERE SIT_CD       = p_SIT_CD          -- 변수 (현장코드)
               AND FST_DIV      = p_FST_DIV         -- 변수 위험성평가최초구분(QS001) 최초1,연간2
               AND PLN_DGR      = p_PLN_DGR         -- 변수 (계획차수)
               AND CTP_CD       = p_CTP_CD          -- 변수 (공종코드)
               AND UNT_CD       = p_UNT_CD          -- 변수 (단위점검코드)
            ;

             -- 위험요인 항목 코드 Validation
            IF v_cnt2 > 0 THEN
                -- 사용자 정의 항목만 있는경우 처리 추가 예정

                --
                -- 중복되는 단위 명칭 조회
                SELECT UNT_NM
                  INTO v_UNT_NM
                  FROM TQHA_CTPUNT
                 WHERE CTP_CD   = p_CTP_CD      -- 변수 (공종코드)
                   AND UNT_CD   = p_UNT_CD      -- 변수 (단위점검코드)
                ;

                ERR_MSG := '단위작업 "' || v_UNT_NM || '" 은(는) 하위 위험요인 항목이 존재합니다. 해당 단위작업내에 위험요인 항목을 삭제한 후 실행해주세요. ';
                RAISE USER_EXCEPTION;

            END IF;
        END IF;

    -----------------------------------------------------------------------------------------------------
    ELSIF p_WRK_DIV = '3' THEN    -- 사용자정의 위험요인 항목 추가

        IF p_WRK_TP = 'I' THEN
            -- 위험요인 항목이 존재 여부 체크
            SELECT nvl(COUNT(CHK_ITM_CD),0)
              INTO v_cnt3
              FROM TQHA_RISKPLAN_D
             WHERE SIT_CD           = p_SIT_CD          -- 변수 (현장코드)
               AND FST_DIV          = p_FST_DIV         -- 변수 위험성평가최초구분(QS001) 최초1,연간2
               AND PLN_DGR          = p_PLN_DGR         -- 변수 (계획차수)
               AND CTP_CD           = p_CTP_CD          -- 변수 (공종코드)
               AND UNT_CD           = p_UNT_CD          -- 변수 (단위점검코드)
               AND CHK_ITM_CD       = p_CHK_ITM_CD      -- 변수 (위험요인 항목)
            ;

            -- 위험요인 항목 코드 Validation
            IF v_cnt3 > 0 THEN
                -- 중복되는 단위 명칭 조회
                SELECT CHK_ITM_NM
                  INTO v_CHK_ITM_NM
                  FROM TQHA_CTPUNT_CHKITM
                 WHERE CTP_CD           = p_CTP_CD          -- 변수 (공종코드)
                   AND UNT_CD           = p_UNT_CD          -- 변수 (단위점검코드)
                   AND CHK_ITM_CD       = p_CHK_ITM_CD      -- 변수 (위험요인 항목)
                ;

                ERR_MSG := '위험요인 항목 "' || v_CHK_ITM_NM || '" 은(는) 존재합니다. ';
                RAISE USER_EXCEPTION;
            END IF;
        END IF;

    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Business Process ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_WRK_TP = 'I') THEN

        ----------------------------------------------------------------------------------------
        IF p_WRK_DIV = '2' THEN      -- 단위점검별로 추가

             -- 최초/년간 단위작업별 위험요인 등록
            INSERT
              INTO TQHA_RISKPLAN_D          -- 위험성 평가 세부계획
                 ( SIT_CD                   -- 현장코드
                 , FST_DIV                  -- 위험성평가최초구분(QS001) 최초1,연간2
                 , PLN_DGR                  -- 계획차수
                 , CTP_CD                   -- 공종코드
                 , UNT_CD                   -- 단위코드
                 , CHK_ITM_CD               -- 위험요인코드
                 , CHK_ITM_NM               -- 위험요인명칭
                 , DISS_SHP                 -- 재해형태(QS036)
                 , RISK_FREQ                -- 빈도레벨(QS003) 1,2,3
                 , RISK_APRV                -- 강도레벨(QS004) 1,2,3
                 , RISK_CRIT                -- 위험성레벨(QS063)
                 , RISK_GRD                 -- 위험등급(QS024) 1상,2중,3하
                 , PRRT_REG                 -- 중점등록(QS002) O, X
                 , IMPRV_CPLN               -- 개선대책
                 , MA_CNFR                  -- 확인자
                 , IPT_ID                   -- 입력ID
                 , IPT_DTM                  -- 입력일시
                 , IPT_IP                   -- 입력IP
                 , UPD_ID                   -- 수정ID
                 , UPD_DTM                  -- 수정일시
                 , UPD_IP                   -- 수정IP
                 )
            SELECT p_SIT_CD                 -- 현장코드
                 , p_FST_DIV                -- 위험성평가최초구분(QS001) 최초1,연간2
                 , p_PLN_DGR                -- 계획차수
                 , A.CTP_CD                 -- 공종코드
                 , A.UNT_CD                 -- 단위코드
                 , A.CHK_ITM_CD             -- 위험요인 코드
                 , A.CHK_ITM_NM             -- 위험요인 명칭
                 , A.DISS_SHP               -- 재해형태(QS036)
                 , A.RISK_FREQ              -- 빈도
                 , A.RISK_APRV              -- 강도
                 , A.RISK_CRIT              -- 위험성레벨(QS063)
                 , A.RISK_GRD               -- 등급
                 , A.PRRT_REG               -- 중점등록
                 , A.IMPRV_CPLN             -- 개선대책
                 , B.CTP_CHR_PSN            -- 확인자
                 , p_WRK_ID                 -- 입력ID
                 , SYSDATE                  -- 입력일시
                 , p_WRK_IP                 -- 입력IP
                 , p_WRK_ID                 -- 수정ID
                 , SYSDATE                  -- 수정일시
                 , p_WRK_IP                 -- 수정IP
              FROM TQHA_CTPUNT_CHKITM A
                 , (SELECT B1.CTP_CD
                         , B1.CTP_DIV
                         , B2.CTP_CHR_PSN
                      FROM TQHA_CTP B1, TQHA_CTP_PSN B2
                     WHERE B1.CTP_DIV       = B2.CTP_DIV(+)
                       AND B1.CTP_CD        = p_CTP_CD   -- 변수 (공종코드)
                       AND B2.SIT_CD(+)     = p_SIT_CD
                   ) B
             WHERE A.CTP_CD         = p_CTP_CD          -- 변수 (공종코드)
               AND A.UNT_CD         = p_UNT_CD          -- 변수 (단위점검코드)
               AND A.USR_DEFN_YN    = '0'               -- 사용자정의 위험요인항목이 아닌것
               AND A.CTP_CD         = B.CTP_CD
            ;

        ----------------------------------------------------------------------------------------
        ELSIF p_WRK_DIV = '3' THEN    -- 사용자정의 위험요인 항목 추가

            -- 최초/년간 단위작업별 위험요인 등록
            INSERT 
              INTO TQHA_RISKPLAN_D          -- 위험성 평가 세부계획
                 ( SIT_CD                   -- 현장코드
                 , FST_DIV                  -- 위험성평가최초구분(QS001) 최초1,연간2
                 , PLN_DGR                  -- 계획차수
                 , CTP_CD                   -- 공종코드
                 , UNT_CD                   -- 단위코드
                 , CHK_ITM_CD               -- 위험요인코드
                 , CHK_ITM_NM               -- 위험요인명칭
                 , DISS_SHP                 -- 재해형태(QS036)
                 , RISK_FREQ                -- 빈도레벨(QS003) 1,2,3
                 , RISK_APRV                -- 강도레벨(QS004) 1,2,3
                 , RISK_CRIT                -- 위험성레벨(QS063)
                 , RISK_GRD                 -- 위험등급(QS024) 1상,2중,3하
                 , PRRT_REG                 -- 중점등록(QS002) O, X
                 , IMPRV_CPLN               -- 개선대책
                 , MA_CNFR                  -- 확인자
                 , IPT_ID                   -- 입력ID
                 , IPT_DTM                  -- 입력일시
                 , IPT_IP                   -- 입력IP
                 , UPD_ID                   -- 수정ID
                 , UPD_DTM                  -- 수정일시
                 , UPD_IP                   -- 수정IP
                 )
            SELECT p_SIT_CD                 -- 현장코드
                 , p_FST_DIV                -- 위험성평가최초구분(QS001) 최초1,연간2
                 , p_PLN_DGR                -- 계획차수
                 , A.CTP_CD                 -- 공종코드
                 , A.UNT_CD                 -- 단위코드
                 , A.CHK_ITM_CD             -- 위험요인 코드
                 , A.CHK_ITM_NM             -- 위험요인 명칭
                 , A.DISS_SHP               -- 재해형태(QS036)
                 , A.RISK_FREQ              -- 빈도
                 , A.RISK_APRV              -- 강도
                 , A.RISK_CRIT                -- 위험성레벨(QS063)
                 , A.RISK_GRD               -- 등급
                 , A.PRRT_REG               -- 중점등록
                 , A.IMPRV_CPLN             -- 개선대책
                 , B.CTP_CHR_PSN            -- 확인자
                 , p_WRK_ID                 -- 입력ID
                 , SYSDATE                  -- 입력일시
                 , p_WRK_IP                 -- 입력IP
                 , p_WRK_ID                 -- 수정ID
                 , SYSDATE                  -- 수정일시
                 , p_WRK_IP                 -- 수정IP
              FROM TQHA_CTPUNT_CHKITM A
                 , (SELECT B1.CTP_CD
                         , B1.CTP_DIV
                         , B2.CTP_CHR_PSN
                      FROM TQHA_CTP B1, TQHA_CTP_PSN B2
                     WHERE B1.CTP_DIV = B2.CTP_DIV(+)
                       AND B1.CTP_CD = p_CTP_CD   -- 변수 (공종코드)
                       AND B2.SIT_CD(+) = p_SIT_CD
                   ) B
             WHERE A.CTP_CD         = p_CTP_CD          -- 변수 (공종코드)
               AND A.UNT_CD         = p_UNT_CD          -- 변수 (단위점검코드)
               AND A.CHK_ITM_CD     = p_CHK_ITM_CD      -- 변수 (위험요인 항목)
               AND A.CTP_CD         = B.CTP_CD
            ;

         END IF;

    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 5. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);

END PQHA_RISKPLAN_D_B;
/

-- PQHA_RISKPLAN_D_B1 (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_RISKPLAN_D_B1" (    -- 위험성평가 계획수립 (타현장항목 가져오기)
    p_WRK_TP                VARCHAR2 :='U'                            -- UPDATE FLAG( I: ISNERT, U:UPDATE, D:DELTE)
,   p_WRK_ID                VARCHAR2                                  -- 사용자 ID
,   p_WRK_IP                VARCHAR2                                  -- 사용자 IP
,   p_SIT_CD                TQHA_RISKPLAN_D.SIT_CD          %TYPE     -- 현장코드
,   p_FST_DIV               TQHA_RISKPLAN_D.FST_DIV         %TYPE     -- 최초여부
,   p_PLN_DGR               TQHA_RISKPLAN_D.PLN_DGR         %TYPE     -- 차수구분
,   p_DIFF_SIT_CD           TQHA_RISKPLAN_D.SIT_CD          %TYPE     -- 현장코드(타현장)
,   p_DIFF_FST_DIV          TQHA_RISKPLAN_D.FST_DIV         %TYPE     -- 최초여부(타현장)
,   p_DIFF_PLN_DGR          TQHA_RISKPLAN_D.PLN_DGR         %TYPE     -- 차수구분(타현장)
)
IS
    /**************************************************************************************************************************
      Purpose : 

      REVISIONS
      Ver      Date               Author                  Description
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2022/02/18 19:36:28                         최초생성

    **************************************************************************************************************************/


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR2(200);            -- ERROR Message
    USER_EXCEPTION EXCEPTION;

    v_APRV_STATS  TQHA_APRV.APRV_STATS%TYPE;                    -- 결재상태 변수
    v_CNT          NUMBER :=0; 

BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 필수입력 필드  Check  ]
    ---------------------------------------------------------------------------------------------------------------------------

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Process 선행조건 Check ]
    ---------------------------------------------------------------------------------------------------------------------------
    -- 결재진행 확인
    SELECT B.APRV_STATS
      INTO v_APRV_STATS
      FROM TQHA_RISKPLAN A
         , TQHA_APRV B
     WHERE A.SIT_CD     = B.SIT_CD (+)
       AND A.APRV_NO    = B.APRV_NO (+)
       AND A.SIT_CD     = p_SIT_CD
       AND A.FST_DIV    = p_FST_DIV
       AND A.PLN_DGR    = p_PLN_DGR
    ;

    IF v_APRV_STATS IS NOT NULL AND v_APRV_STATS <> '1' THEN
       ERR_MSG := '결재 진행 중이거나 결재 완료 건입니다. 타 현장 항목을 가져올 수 없습니다.';
       RAISE USER_EXCEPTION;
    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Business Process ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_WRK_TP = 'I') THEN

        SELECT COUNT(*) AS CNT
          INTO v_CNT
          FROM TQHA_RISKPLAN_D
         WHERE SIT_CD       = p_SIT_CD
           AND FST_DIV      = p_FST_DIV
           AND PLN_DGR      = p_PLN_DGR
        ;

        IF v_CNT > 0 THEN
            -- 기존 차수에 위험성평가 데이터 삭제
            DELETE
              FROM TQHA_RISKPLAN_D
             WHERE SIT_CD       = p_SIT_CD          -- 현장코드
               AND FST_DIV      = p_FST_DIV         -- 위험성평가최초구분(QS001) 최초1,연간2
               AND PLN_DGR      = p_PLN_DGR         -- 계획차수
            ;

        END IF;

        INSERT 
          INTO TQHA_RISKPLAN_D          -- 위험성 평가 세부계획
             ( SIT_CD                   -- 현장코드
             , FST_DIV                  -- 위험성평가최초구분(QS001) 최초1,연간2
             , PLN_DGR                  -- 계획차수
             , CTP_CD                   -- 공종코드
             , UNT_CD                   -- 단위코드
             , CHK_ITM_CD               -- 위험요인코드
             , CHK_ITM_NM               -- 위험요인명칭
             , DISS_SHP                 -- 재해형태(QS036)
             , RISK_FREQ                -- 빈도레벨(QS003) 1,2,3
             , RISK_APRV                -- 강도레벨(QS004) 1,2,3
             , RISK_CRIT                -- 위험성(QS063)
             , RISK_GRD                 -- 위험등급(QS024) 1상,2중,3하
             , PRRT_REG                 -- 중점등록(QS002) O, X
             , IMPRV_CPLN               -- 개선대책
             , MA_CNFR                  -- 확인자
             , IPT_ID                   -- 입력ID
             , IPT_DTM                  -- 입력일시
             , IPT_IP                   -- 입력IP
             , UPD_ID                   -- 수정ID
             , UPD_DTM                  -- 수정일시
             , UPD_IP                   -- 수정IP
             )
        SELECT p_SIT_CD                 -- 현장코드
             , p_FST_DIV                -- 최초구분(공통코드 QS001)
             , p_PLN_DGR                -- 계획차수(공통코드 QS005)
             , A.CTP_CD                 -- 공종코드
             , A.UNT_CD                 -- 단위코드
             , A.CHK_ITM_CD             -- 위험요인항목코드
             , A.CHK_ITM_NM             -- 위험요인항목명칭
             , A.DISS_SHP               -- 재해형태(QS036)
             , A.RISK_FREQ              -- 위험빈도(공통코드 QS003)
             , A.RISK_APRV              -- 위험강도(공통코드 QS004)
             , A.RISK_CRIT              -- 위험성(QS063)
             , A.RISK_GRD               -- 위험등급(공통코드 QS024)
             , A.PRRT_REG               -- 중점등록(공통코드 QS002)
             , A.IMPRV_CPLN             -- 개선대책
             , B.CTP_CHR_PSN            -- 확인자(안전관리자)
             , p_WRK_TP                 -- 입력ID
             , SYSDATE()                -- 입력일시
             , p_WRK_IP                 -- 입력IP
             , p_WRK_TP                 -- 수정ID
             , SYSDATE()                -- 수정일시
             , p_WRK_IP                 -- 수정IP
          FROM TQHA_RISKPLAN_D A
             , ( SELECT T2.CTP_CD
                      , T1.CTP_CHR_PSN
                      , T1.SIT_CD
                   FROM TQHA_CTP_PSN T1
                      , TQHA_CTP T2
                  WHERE T1.SIT_CD   = p_SIT_CD
                    AND T1.CTP_DIV  = T2.CTP_DIV
               ) B
         WHERE A.CTP_CD     = B.CTP_CD (+)
           AND A.SIT_CD     = p_DIFF_SIT_CD
           AND A.FST_DIV    = p_DIFF_FST_DIV
           AND A.PLN_DGR    = p_DIFF_PLN_DGR
        ;

    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 5. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);
END PQHA_RISKPLAN_D_B1;
/

-- PQHA_RISKPLAN_D_S (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_RISKPLAN_D_S" (
    p_WRK_TP                VARCHAR2 :='U'                              -- UPDATE FLAG( I: ISNERT, U:UPDATE, D:DELTE)
,   p_WRK_ID                VARCHAR2                                    -- 사용자 ID
,   p_WRK_IP                VARCHAR2                                    -- 사용자 IP
,   p_SIT_CD                TQHA_RISKPLAN_D.SIT_CD          %TYPE       -- 현장코드
,   p_FST_DIV               TQHA_RISKPLAN_D.FST_DIV         %TYPE       -- 위험성평가최초구분(QS001) 최초1,연간2
,   p_PLN_DGR               TQHA_RISKPLAN_D.PLN_DGR         %TYPE       -- 계획차수
,   p_CTP_CD                TQHA_RISKPLAN_D.CTP_CD          %TYPE       -- 공종코드
,   p_UNT_CD                TQHA_RISKPLAN_D.UNT_CD          %TYPE       -- 단위코드
,   p_CHK_ITM_CD            TQHA_RISKPLAN_D.CHK_ITM_CD      %TYPE       -- 점검항목코드
,   p_DISS_SHP              TQHA_RISKPLAN_D.DISS_SHP        %TYPE       -- 재해형태(QS036)
,   p_RISK_FREQ             TQHA_RISKPLAN_D.RISK_FREQ       %TYPE       -- 빈도레벨(QS003)
,   p_RISK_APRV             TQHA_RISKPLAN_D.RISK_APRV       %TYPE       -- 강도레벨(QS004)
,   p_RISK_CRIT             TQHA_RISKPLAN_D.RISK_CRIT       %TYPE       -- 위험성레벨(QS063)
,   p_RISK_GRD              TQHA_RISKPLAN_D.RISK_GRD        %TYPE       -- 위험등급(QS024)
,   p_PRRT_REG              TQHA_RISKPLAN_D.PRRT_REG        %TYPE       -- 중점등록(QS002)
,   p_IMPRV_CPLN            TQHA_RISKPLAN_D.IMPRV_CPLN      %TYPE       -- 개선대책
,   p_CHK_ITM_NM            TQHA_RISKPLAN_D.CHK_ITM_NM      %TYPE       -- 점검항목명
,   p_MA_CNFR               TQHA_RISKPLAN_D.MA_CNFR         %TYPE       -- 확인자
)
IS
    /**************************************************************************************************************************
      Purpose :

      REVISIONS
      Ver      Date               Author                  Description
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2021/10/27 14:00:36                         최초생성

    **************************************************************************************************************************/


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR2(200);            -- ERROR Message
    USER_EXCEPTION EXCEPTION;


BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 필수입력 필드  Check  ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_SIT_CD IS NULL)  THEN
        ERR_MSG := '현장코드는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_FST_DIV IS NULL)  THEN
        ERR_MSG := '위험성평가최초구분는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_PLN_DGR IS NULL)  THEN
        ERR_MSG := '계획차수는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_CTP_CD IS NULL)  THEN
        ERR_MSG := '공종코드는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_UNT_CD IS NULL)  THEN
        ERR_MSG := '단위코드는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_CHK_ITM_CD IS NULL)  THEN
        ERR_MSG := '점검항목코드는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Process 선행조건 Check ]
    ---------------------------------------------------------------------------------------------------------------------------



    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Business Process ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_WRK_TP ='D') THEN

        DELETE
          FROM TQHA_RISKPLAN_D
         WHERE SIT_CD           = p_SIT_CD          -- 현장코드
           AND FST_DIV          = p_FST_DIV         -- 위험성평가최초구분(QS001) 최초1,연간2
           AND PLN_DGR          = p_PLN_DGR         -- 계획차수
           AND CTP_CD           = p_CTP_CD          -- 공종코드
           AND UNT_CD           = p_UNT_CD          -- 단위코드
           AND CHK_ITM_CD       = p_CHK_ITM_CD      -- 점검항목코드
        ;

    ---------------------------------------------------------------------------------------
    --
    ELSIF (p_WRK_TP ='U') THEN

        UPDATE TQHA_RISKPLAN_D
           SET DISS_SHP             = p_DISS_SHP        -- 재해형태(QS036)
             , RISK_FREQ            = p_RISK_FREQ       -- 빈도레벨(QS003) 1,2,3
             , RISK_APRV            = p_RISK_APRV       -- 강도레벨(QS004) 1,2,3
             , RISK_CRIT            = p_RISK_CRIT       -- 위험성레벨(QS063)
             , RISK_GRD             = p_RISK_GRD        -- 위험등급(QS024) 1상,2중,3하
             , PRRT_REG             = p_PRRT_REG        -- 중점등록(QS002) O, X
             , IMPRV_CPLN           = p_IMPRV_CPLN      -- 개선대책
             , CHK_ITM_NM           = p_CHK_ITM_NM      -- 점검항목명
             , MA_CNFR              = p_MA_CNFR         -- 확인자
             , UPD_ID               = p_WRK_ID          -- 수정ID
             , UPD_DTM              = SYSDATE()         -- 수정일시
             , UPD_IP               = p_WRK_IP          -- 수정IP
         WHERE SIT_CD               = p_SIT_CD          -- 현장코드
           AND FST_DIV              = p_FST_DIV         -- 위험성평가최초구분(QS001) 최초1,연간2
           AND PLN_DGR              = p_PLN_DGR         -- 계획차수
           AND CTP_CD               = p_CTP_CD          -- 공종코드
           AND UNT_CD               = p_UNT_CD          -- 단위코드
           AND CHK_ITM_CD           = p_CHK_ITM_CD      -- 점검항목코드
        ;

    ---------------------------------------------------------------------------------------
    --
    ELSE

        INSERT 
          INTO TQHA_RISKPLAN_D
             ( SIT_CD                   -- 현장코드
             , FST_DIV                  -- 위험성평가최초구분(QS001) 최초1,연간2
             , PLN_DGR                  -- 계획차수
             , CTP_CD                   -- 공종코드
             , UNT_CD                   -- 단위코드
             , CHK_ITM_CD               -- 점검항목코드
             , DISS_SHP                 -- 재해형태(QS036)
             , RISK_FREQ                -- 빈도레벨(QS003)
             , RISK_APRV                -- 강도레벨(QS004)
             , RISK_CRIT                -- 위험성레벨(QS063)
             , RISK_GRD                 -- 위험등급(QS024)
             , PRRT_REG                 -- 중점등록(QS002)
             , IMPRV_CPLN               -- 개선대책
             , MA_CNFR                  -- 확인자
             , CHK_ITM_NM               -- 점검항목명
             , IPT_ID                   -- 입력ID
             , IPT_DTM                  -- 입력일시
             , IPT_IP                   -- 입력IP
             , UPD_ID                   -- 수정ID
             , UPD_DTM                  -- 수정일시
             , UPD_IP                   -- 수정IP
             )
        VALUES 
             ( p_SIT_CD                 -- 현장코드
             , p_FST_DIV                -- 위험성평가최초구분(QS001) 최초1,연간2
             , p_PLN_DGR                -- 계획차수
             , p_CTP_CD                 -- 공종코드
             , p_UNT_CD                 -- 단위코드
             , p_CHK_ITM_CD             -- 점검항목코드
             , p_DISS_SHP               -- 재해형태(QS036)
             , p_RISK_FREQ              -- 빈도레벨(QS003) 1,2,3
             , p_RISK_APRV              -- 강도레벨(QS004) 1,2,3
             , p_RISK_CRIT                -- 위험성레벨(QS063)
             , p_RISK_GRD               -- 위험등급(QS024) 1상,2중,3하
             , p_PRRT_REG               -- 중점등록(QS002) O, X
             , p_IMPRV_CPLN             -- 개선대책
             , p_MA_CNFR                -- 확인자
             , p_CHK_ITM_NM             -- 점검항목명
             , p_WRK_ID                 -- 입력ID
             , SYSDATE()                -- 입력일시
             , p_WRK_IP                 -- 입력IP
             , p_WRK_ID                 -- 수정ID
             , SYSDATE()                -- 수정일시
             , p_WRK_IP                 -- 수정IP
             )
        ;

    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 5. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);

END ;
/

-- PQHA_RISKPLAN_Q (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_RISKPLAN_Q" (
    p_WRK_TP            IN VARCHAR2 DEFAULT 'Q'     -- FLAG(Q: 조회)
,   p_SIT_CD            IN VARCHAR2                 -- 현장코드
,   p_SEARCH_SIT_CD     IN VARCHAR2                 -- 현장코드
,   p_SEARCH_FST_DIV    IN VARCHAR2                 -- 최초여부
,   p_SEARCH_PLN_DGR    IN VARCHAR2                 -- 차수
,   RTN_CURSOR          OUT SYS_REFCURSOR
)
IS
    /**************************************************************************************************************************
      Purpose : [위험성평가계획 목록 조회] PROCEDRE (QSE > 안전관리 > 위험성평가(최초/연간) > 위험성평가 계획수립 )

      REVISIONS
      Ver      Date               Author                  Description
      -------  -----------------  ----------------------  ---------------------------------------------------------------------
      1.0      2023/12/04                                 최초생성

    **************************************************************************************************************************/

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE  NUMBER :=-20009; -- ERROR 코드
    ERR_MSG   VARCHAR(200);    -- ERROR Message
    USER_EXCEPTION EXCEPTION;

BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 수행전 Check Logic ]
    ---------------------------------------------------------------------------------------------------------------------------

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Logic 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------

   IF p_WRK_TP = 'Q' THEN

        -- SELECT  쿼리
        OPEN RTN_CURSOR FOR
        SELECT A.SIT_CD                                                                                                 -- 현장코드
             , A.FST_DIV                                                                                                -- 최초구분(공통코드 QS001)
             , ( SELECT CD_NM FROM TCOA_COMCODE WHERE COM_CD = A.FST_DIV AND HRNK_CD = 'QS001')     AS FST_DIV_NM       -- 최초여부
             , A.PLN_DGR                                                                                                -- 계획차수(공통코드 QS005)
             , ( SELECT CD_NM FROM TCOA_COMCODE WHERE COM_CD = A.PLN_DGR AND HRNK_CD = 'QS005')     AS PLN_DGR_NM       -- 차수
             , A.RISK_APRS_DT                                                                                           -- 위험성평가일자
             , A.APRV_PSN                                                                                               -- 결재자
             , A.APRV_NO                                                                                                -- 결재번호
             , A.ATFL_GRP                                                                                               -- 첨부파일그룹
             , B.APRV_STATS                                                                                             -- 결재상태(공통코드 QS031)
             , ( SELECT CD_NM FROM TCOA_COMCODE WHERE COM_CD = B.APRV_STATS AND HRNK_CD = 'QS031')  AS APRV_STATS_NM    -- 결재상태
             /*, B.SAFT_MGR_DT        -- 안전관리자 결재일자*/
             /*, B.SITE_OMGR_DT       -- 현장소장 결재일자*/
          FROM TQHA_RISKPLAN    A
          LEFT JOIN TQHA_APRV   B ON A.SIT_CD    = B.SIT_CD
                                 AND A.APRV_NO   = B.APRV_NO
         WHERE A.SIT_CD = p_SIT_CD
        ;

    ELSIF p_WRK_TP = 'Q1' THEN

        -- SELECT  쿼리
        OPEN RTN_CURSOR FOR
        SELECT A.SIT_CD                                                                                             -- 현장코드
             , A.FST_DIV                                                                                            -- 최초구분(공통코드 QS001)
             , A.PLN_DGR                                                                                            -- 계획차수(공통코드 QS005)
             , A.CTP_CD                                                                                             -- 공종코드
             , ( SELECT CTP_NM FROM TQHA_CTP WHERE CTP_CD = A.CTP_CD )                          AS CTP_NM           -- 공종명칭
             , A.UNT_CD                                                                                             -- 단위코드
             , ( SELECT UNT_NM FROM TQHA_CTPUNT WHERE CTP_CD = A.CTP_CD AND UNT_CD = A.UNT_CD ) AS UNT_NM           -- 단위명칭
             , A.CHK_ITM_CD                                                                                         -- 위험요인항목코드
             , A.CHK_ITM_NM                                                                                         -- 위험요인항목명칭
             , A.RISK_FREQ                                                                                          -- 위험빈도(공통코드 QS003)
             , ( SELECT CD_NM FROM TCOA_COMCODE WHERE COM_CD = A.RISK_FREQ AND HRNK_CD = 'QS003') AS RISK_FREQ_NM   -- 빈도명
             , A.RISK_APRV                                                                                          -- 위험강도(공통코드 QS004)
             , ( SELECT CD_NM FROM TCOA_COMCODE WHERE COM_CD = A.RISK_APRV AND HRNK_CD = 'QS004') AS RISK_APRV_NM   -- 강도명
             , A.RISK_CRIT                                                                                          -- 위험성레벨(공통코드 QS063)
             , A.RISK_GRD                                                                                           -- 위험등급(공통코드 QS024)
             , ( SELECT CD_NM FROM TCOA_COMCODE WHERE COM_CD = A.RISK_GRD AND HRNK_CD = 'QS024') AS RISK_GRD_NM     -- 위험등급
             , A.PRRT_REG                                                                                           -- 중점등록(공통코드 QS002)
             , ( SELECT CD_NM FROM TCOA_COMCODE WHERE COM_CD = A.PRRT_REG AND HRNK_CD = 'QS002') AS PRRT_REG_NM     -- 중점등록
             , A.IMPRV_CPLN                                                                                         -- 개선대책
             , A.MA_CNFR                                                                                            -- 확인자(안전관리자)
             , ( SELECT USR_NM FROM TCOZ_USR_INFO WHERE USR_ID = A.MA_CNFR ) AS MA_CNFR_NM                          -- 확인자성명
             , A.DISS_SHP                                                                                           -- 재해형태(QS036)
          FROM TQHA_RISKPLAN_D A
         WHERE SIT_CD = p_SEARCH_SIT_CD
           AND FST_DIV = p_SEARCH_FST_DIV
           AND PLN_DGR = p_SEARCH_PLN_DGR
        ;

    END IF;


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
         WHEN OTHERS THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);

END PQHA_RISKPLAN_Q;
/

-- PQHA_RISKPLAN_S (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_RISKPLAN_S" (
    p_WRK_TP                VARCHAR2 :='U'                              -- UPDATE FLAG( I: ISNERT, U:UPDATE, D:DELTE)
,   p_WRK_ID                VARCHAR2                                    -- 사용자 ID
,   p_WRK_IP                VARCHAR2                                    -- 사용자 IP
,   p_SIT_CD                TQHA_RISKPLAN.SIT_CD            %TYPE       -- 현장코드
,   p_FST_DIV               TQHA_RISKPLAN.FST_DIV           %TYPE       -- 위험성평가최초구분(QS001) 최초1,연간2
,   p_PLN_DGR               TQHA_RISKPLAN.PLN_DGR           %TYPE       -- 계획차수
,   p_RISK_APRS_DT          TQHA_RISKPLAN.RISK_APRS_DT      %TYPE       -- 위험성평가일
,   p_APRV_PSN              TQHA_RISKPLAN.APRV_PSN          %TYPE       -- 결재자
,   p_APRV_NO               TQHA_RISKPLAN.APRV_NO           %TYPE       -- 결재번호
,   p_ATFL_GRP              TQHA_RISKPLAN.ATFL_GRP          %TYPE       -- 첨부파일그룹
)
IS
    /**************************************************************************************************************************
      Purpose :

      REVISIONS
      Ver      Date               Author                  Description
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2021/10/27 13:05:08                         최초생성

    **************************************************************************************************************************/

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR2(200);            -- ERROR Message
    USER_EXCEPTION EXCEPTION;
    v_cnt  INTEGER;                                -- 하위 점검항목  코드 존재 여부

BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 필수입력 필드  Check  ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_SIT_CD IS NULL)  THEN
        ERR_MSG := '현장코드는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_FST_DIV IS NULL)  THEN
        ERR_MSG := '위험성평가최초구분는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_PLN_DGR IS NULL)  THEN
        ERR_MSG := '계획차수는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Process 선행조건 Check ]
    ---------------------------------------------------------------------------------------------------------------------------

    --  하위 점검항목 존재 여부 확인
    IF p_WRK_TP = 'D' THEN

        SELECT nvl(COUNT(CHK_ITM_CD),0)
          INTO v_cnt
          FROM TQHA_RISKPLAN_D
         WHERE SIT_CD       = p_SIT_CD      -- 현장코드
           AND FST_DIV      = p_FST_DIV     -- 최초구분
           AND PLN_DGR      = p_PLN_DGR     -- 계획차수
        ;

         -- 단위작업 코드 Validation
        IF v_cnt > 0 THEN
           ERR_MSG := '계획차수 "' || p_PLN_DGR || '" 은(는) 하위 위험성 평가 점검항목이 존재합니다. 하위 점검항목을 전부 삭제해야 해당차수를 삭제할 수 있습니다. ';
           RAISE USER_EXCEPTION;
        END IF;

    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Business Process ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_WRK_TP ='D') THEN

        DELETE
          FROM TQHA_RISKPLAN
         WHERE SIT_CD   = p_SIT_CD      -- 현장코드
           AND FST_DIV  = p_FST_DIV     -- 위험성평가최초구분(QS001) 최초1,연간2
           AND PLN_DGR  = p_PLN_DGR     -- 계획차수
        ;

    -----------------------------------------------------------------------------------
    --
    ELSIF (p_WRK_TP ='U') THEN
        UPDATE TQHA_RISKPLAN
           SET RISK_APRS_DT     = p_RISK_APRS_DT        -- 위험성평가일
             , ATFL_GRP         = p_ATFL_GRP            -- 펌부파일그룹
             , APRV_PSN         = p_APRV_PSN            -- 결재자
             , APRV_NO          = p_APRV_NO             -- 결재번호
             , UPD_ID           = p_WRK_ID              -- 수정ID
             , UPD_DTM          = SYSDATE()             -- 수정일시
             , UPD_IP           = p_WRK_IP              -- 수정IP
         WHERE SIT_CD           = p_SIT_CD              -- 현장코드
           AND FST_DIV          = p_FST_DIV             -- 위험성평가최초구분(QS001) 최초1,연간2
           AND PLN_DGR          = p_PLN_DGR             -- 계획차수
        ;

    -----------------------------------------------------------------------------------
    --
    ELSE

        INSERT
          INTO TQHA_RISKPLAN
             ( SIT_CD               -- 현장코드
             , FST_DIV              -- 위험성평가최초구분(QS001) 최초1,연간2
             , PLN_DGR              -- 계획차수
             , RISK_APRS_DT         -- 위험성평가일
             , ATFL_GRP             -- 첨부파일그룹
             , APRV_PSN             -- 결재자
             , APRV_NO              -- 결재번호
             , IPT_ID               -- 입력ID
             , IPT_DTM              -- 입력일시
             , IPT_IP               -- 입력IP
             , UPD_ID               -- 수정ID
             , UPD_DTM              -- 수정일시
             , UPD_IP               -- 수정IP
             )
        VALUES
             ( p_SIT_CD             -- 현장코드
             , p_FST_DIV            -- 위험성평가최초구분(QS001) 최초1,연간2
             , p_PLN_DGR            -- 계획차수
             , p_RISK_APRS_DT       -- 위험성평가일
             , p_ATFL_GRP           -- 첨부파일그룹
             , p_APRV_PSN           -- 결재자
             , p_APRV_NO            -- 결재번호
             , p_WRK_ID             -- 입력ID
             , SYSDATE()            -- 입력일시
             , p_WRK_IP             -- 입력IP
             , p_WRK_ID             -- 수정ID 
             , SYSDATE()            -- 수정일시
             , p_WRK_IP             -- 수정IP
             )
        ;

    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 5. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);

END ;
/

-- PQHA_RISK_AB_S (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_RISK_AB_S" 
                           ( p_SIT_CD TQHA_RISK_VNDR.SIT_CD%TYPE                        -- 현장코드
                            ,p_PLN_YM TQHA_RISK_VNDR.PLN_YM%TYPE                          -- 계획년월
                            ,p_PLN_DGR TQHA_RISK_VNDR.PLN_DGR%TYPE                        -- 차수구분코드(QS005) 1 1차,2 2차
                            ,p_CUST_CD TQHA_RISK_VNDR.CUST_CD%TYPE                        -- 업체코드
                            ,p_VNDR_SEQ TQHA_RISK_VNDR.VNDR_SEQ%TYPE                      -- 업체순번
                            ,p_SBM_YN TQHA_RISK_VNDR.SBM_YN%TYPE                          -- 제출Y 
                            ,p_SBM_DT TQHA_RISK_VNDR.SBM_DT%TYPE )                        -- 평가서제출일자

IS 
    /**************************************************************************************************************************
      Purpose : 

      REVISIONS
      Ver      Date               Author                  Description 
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2022/04/27 10:31:08                         협력업체 위험성평가서 제출 여부 처리

    **************************************************************************************************************************/


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR2(200);            -- ERROR Message
    USER_EXCEPTION EXCEPTION;

    v_MNG_APRV_STATS VARCHAR2(10) := '0';               -- 관리자 결재 여부 체크    
BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 필수입력 필드  Check  ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_SIT_CD IS NULL)  THEN
        ERR_MSG := '현장코드는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_PLN_YM IS NULL)  THEN
        ERR_MSG := '계획년월는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_PLN_DGR IS NULL)  THEN
        ERR_MSG := '차수구분코드는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_CUST_CD IS NULL)  THEN
        ERR_MSG := '업체코드는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_VNDR_SEQ IS NULL)  THEN
        ERR_MSG := '업체순번는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Process 선행조건 Check ]
    ---------------------------------------------------------------------------------------------------------------------------
    -- 위험성 평가서 제출 여부 체크
		SELECT MNG_APRV_STATS 
		  INTO v_MNG_APRV_STATS    -- 관리자 승인상태 여부
		  FROM TQHA_RISK_VNDR
		 WHERE SIT_CD = p_SIT_CD         --현장코드
           AND PLN_YM = p_PLN_YM           --계획년월
           AND PLN_DGR = p_PLN_DGR         --차수구분코드(QS005) 1 1차,2 2차
           AND CUST_CD = p_CUST_CD         --업체코드
           AND VNDR_SEQ = p_VNDR_SEQ;      --업체순번

    -- 1차 관리자 승인된 경우 제출 및 취소 불가
    IF v_MNG_APRV_STATS = '1' THEN
       ERR_MSG := '평가년월 "' || p_PLN_YM || '" 차수 "' || p_PLN_DGR || '"는(은) 관리자가 해당 위험성평가서를 승인한 상태이므로 평가서 제출 및 취소가 불가합니다. ';
       RAISE USER_EXCEPTION;
    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Business Process ]
    ---------------------------------------------------------------------------------------------------------------------------
	UPDATE TQHA_RISK_VNDR
	   SET SBM_YN = p_SBM_YN -- 평가서 제출여부
		 , SBM_DT = p_SBM_DT -- 평가서 제출일자
		 , MNG_SUPR = '' -- 관리자ID
		 , MNG_APRV_DT = '' -- 관리자 승인일자
		 , MNG_APRV_STATS = '' -- 관리자 승인여부
		 , SAFT_MGR = '' -- 안전관리자ID
		 , SAFT_APRV_DT = '' -- 안전관리자 승인일자
		 , SAFT_APRV_STATS = '' -- 안전관리자 승인여부
		 , SITE_OMGR = '' -- 현장소장ID
		 , SITE_APRV_DT = '' -- 현장소장 승인일자
		 , SITE_APRV_STATS = '' -- 현장소장 승인여부
	 WHERE SIT_CD = p_SIT_CD
  	   AND PLN_YM = p_PLN_YM
	   AND PLN_DGR = p_PLN_DGR
	   AND CUST_CD = p_CUST_CD
	   AND VNDR_SEQ = p_VNDR_SEQ ;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 5. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN 
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);
END ;
/

-- PQHA_RISK_CHK_AGO_Q (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_RISK_CHK_AGO_Q" (
    p_WRK_TP            IN VARCHAR2 DEFAULT 'Q'         -- FLAG
,   p_SIT_CD            IN VARCHAR2                     -- 현장코드
,   p_PLN_YM            IN VARCHAR2                     -- 계획년월
,   p_PLN_DGR           IN VARCHAR2                     -- 계획차수
,   RTN_CURSOR          OUT SYS_REFCURSOR
)
IS
    /**************************************************************************************************************************
      Purpose : [위험성평가회의 - 이전차수 조회] PROCEDRE 

      REVISIONS
      Ver      Date               Author                  Description
      -------  -----------------  ----------------------  ---------------------------------------------------------------------
      1.0      2026/01/28                                 최초생성

    **************************************************************************************************************************/

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE  NUMBER :=-20009; -- ERROR 코드
    ERR_MSG   VARCHAR(200);    -- ERROR Message 
    USER_EXCEPTION EXCEPTION;

BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 수행전 Check Logic ]
    ---------------------------------------------------------------------------------------------------------------------------

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Logic 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------

    ---------------------------------------------------------------------------------------
    -- 
    IF p_WRK_TP = 'Q1' THEN

        OPEN RTN_CURSOR FOR
        -- 전회 계획회차
        SELECT T1.PLN_YM              AS PRE_PLN_YM
             , T1.PLN_DGR             AS PRE_PLN_DGR
             , T1.PLN_DGR || '차'     AS  PRE_PLN_DGR_NM 
             , T1.APRS_STR_DT         AS PRE_APRS_STR_DT    -- 평가시작일자
             , T1.APRS_END_DT         AS PRE_APRS_END_DT    -- 평가종료일자
          FROM TQHB_RISK_DGR    T1
         WHERE T1.SIT_CD        = p_SIT_CD
           AND T1.PLN_YM || T1.PLN_DGR < p_PLN_YM || p_PLN_DGR
         ORDER 
            BY T1.PLN_YM DESC
             , T1.PLN_DGR DESC
         FETCH NEXT 1 ROWS ONLY 
        ;

     ---------------------------------------------------------------------------------------
     ELSIF p_WRK_TP = 'Q2' THEN

        OPEN RTN_CURSOR FOR
        WITH 
		-- 1. 기본 점검 및 위험요인 데이터
		BASE_DATA AS (
		    SELECT T1.SIT_CD
		         , T1.ODAY_CHK_DT
		         , T2.CUST_CD
		         , T2.VNDR_SEQ
		         , T2.CTP_CD
		         , T2.UNT_CD
		         , T2.CHK_ITM_CD
		         , T2.ODAY_CHK_RSLT
		         , T2.NCR_DOC_NO
		         , T2.PHOTO_GRP1
		         , T2.PHOTO_DESC_1
		         , T2.PHOTO_GRP2
		         , T2.PHOTO_DESC_2
		         , T3.CUST_NM
		         , T4.IMPRV_CPLN
		         , R.CHK_ITM_NM
		      FROM TQHB_DAYSAFE_DT T1
		      
		      -- T1 - T2 조인
		      JOIN TQHB_DAYSAFE_CHKLST T2 ON T1.SIT_CD      = T2.SIT_CD 
		                                 AND T1.ODAY_CHK_DT = T2.ODAY_CHK_DT
		                                 AND T1.PLN_YM      = T2.PLN_YM 
		                                 AND T1.PLN_DGR     = T2.PLN_DGR 
		                                 AND T1.RISK_GRD    = T2.RISK_GRD
		                                 
		      -- T2 - T4 조인 (중점개선대책)
		      JOIN TQHB_RISK_CHK       T4 ON T2.SIT_CD      = T4.SIT_CD
		                                 AND T2.PLN_YM      = T4.PLN_YM
		                                 AND T2.PLN_DGR     = T4.PLN_DGR
		                                 AND T2.CUST_CD     = T4.CUST_CD
		                                 AND T2.VNDR_SEQ    = T4.VNDR_SEQ
		                                 AND T2.CTP_CD      = T4.CTP_CD
		                                 AND T2.UNT_CD      = T4.UNT_CD
		                                 AND T2.CHK_ITM_CD  = T4.CHK_ITM_CD
		                                 AND T2.RISK_GRD    = T4.RISK_GRD
		                                 
		      -- T2 - R 조인 (위험요인항목명)
		      LEFT JOIN TQHB_RISK_LST   R ON T2.SIT_CD      = R.SIT_CD
		                                 AND T2.PLN_YM      = R.PLN_YM
		                                 AND T2.PLN_DGR     = R.PLN_DGR
		                                 AND T2.CUST_CD     = R.CUST_CD
		                                 AND T2.VNDR_SEQ    = R.VNDR_SEQ
		                                 AND T2.CTP_CD      = R.CTP_CD
		                                 AND T2.UNT_CD      = R.UNT_CD
		                                 AND T2.CHK_ITM_CD  = R.CHK_ITM_CD
		                                 AND T2.RISK_GRD    = R.RISK_GRD
		                                 
		      LEFT JOIN VQSZ_TRADE     T3 ON T2.CUST_CD     = T3.CUST_CD
		      
		     WHERE T1.SIT_CD   = p_SIT_CD
		       AND T1.PLN_YM   = p_PLN_YM
		       AND T1.PLN_DGR  = p_PLN_DGR
		      -- AND T1.RISK_GRD = 'QS0900201' -- 조인 조건에 따라 T2, T4, R에도 자동 적용됨
		),
		
		-- 2. NCR 관련 매핑 정보 정리
		NCR_DATA AS (
		    SELECT ST1.SIT_CD
		         , ST1.NCR_DOC_NO
		         , '* ' || REGEXP_REPLACE(ST2.ODAY_CHK_DT, '([0-9]{4})([0-9]{2})([0-9]{2})', '\1-\2-\3')
		           || '/' || ST1.NCR_CTS 
		           || '/' || ST1.VNDR_MA_CTS AS CTS       
		         , ST1.VNDR_PHOTO_GRP1
		         , ST1.VNDR_PHOTO_DESC_1
		         , ST1.VNDR_PHOTO_GRP2
		         , ST1.VNDR_PHOTO_DESC_2
		      FROM TQHA_NCR_REP ST1
		      JOIN (
		            SELECT SIT_CD
		                 , NCR_DOC_NO
		                 , MAX(ODAY_CHK_DT) AS ODAY_CHK_DT
		              FROM TQHB_DAYSAFE_CHKLST
		             WHERE SIT_CD   = p_SIT_CD
		               AND PLN_YM   = p_PLN_YM
		               AND PLN_DGR  = p_PLN_DGR
		               AND RISK_GRD = 'QS0900201'
		             GROUP BY SIT_CD, NCR_DOC_NO
		      ) ST2 ON ST1.SIT_CD     = ST2.SIT_CD
		           AND ST1.NCR_DOC_NO = ST2.NCR_DOC_NO
		     WHERE ST1.SIT_CD = p_SIT_CD
		       AND (ST1.NCR_CTS IS NOT NULL OR ST1.VNDR_MA_CTS IS NOT NULL)
		)
		
		-- 3. 메인 집계 조회
		SELECT B.CUST_CD
		     , B.VNDR_SEQ
		     , B.CTP_CD
		     , B.UNT_CD
		     , B.CHK_ITM_CD
		     , MAX(B.CHK_ITM_NM)                                                                           AS CHK_ITM_NM
		     , MAX(B.CUST_NM)                                                                              AS CUST_NM
		     , MAX(B.IMPRV_CPLN)                                                                           AS IMPRV_CPLN
		     
		     -- 건수 통계 (양호 / 미흡 / 해당없음)
		     , TO_CHAR(COUNT(CASE WHEN B.ODAY_CHK_RSLT = '2' THEN 1 END)) || '/' ||
		       TO_CHAR(COUNT(CASE WHEN B.ODAY_CHK_RSLT IN ('2', '3') THEN 1 END))                         AS SUCC_CNT
		     
		     , TO_CHAR(COUNT(CASE WHEN B.ODAY_CHK_RSLT = '3' THEN 1 END)) || '/' ||
		       TO_CHAR(COUNT(CASE WHEN B.ODAY_CHK_RSLT IN ('2', '3') THEN 1 END))                         AS FAIL_CNT
		     
		     , TO_CHAR(COUNT(CASE WHEN B.ODAY_CHK_RSLT = '1' THEN 1 END)) || '/' ||
		       TO_CHAR(COUNT(CASE WHEN B.ODAY_CHK_RSLT IN ('1', '2', '3') THEN 1 END))                    AS NA_CNT
		     
		     -- 달성률 계산
		     , TO_CHAR(
		           CASE WHEN COUNT(CASE WHEN B.ODAY_CHK_RSLT IN ('2', '3') THEN 1 END) = 0 THEN 0
		                ELSE COUNT(CASE WHEN B.ODAY_CHK_RSLT = '2' THEN 1 END) 
		                   / COUNT(CASE WHEN B.ODAY_CHK_RSLT IN ('2', '3') THEN 1 END) * 100
		           END, 'FM990'
		       )                                                                                           AS SUCC_RATE
		       
		     -- 사유/내용 목록
		     , LISTAGG(N.CTS, CHR(10)) WITHIN GROUP (ORDER BY B.ODAY_CHK_DT)                               AS CAUS_DESC
		     
		     -- NCR 발행 여부에 따른 사진 정보 분기 처리
		     , CASE WHEN MAX(B.NCR_DOC_NO) IS NULL 
		            THEN MAX(B.PHOTO_GRP1) KEEP (DENSE_RANK LAST ORDER BY B.ODAY_CHK_DT) 
		            ELSE MAX(N.VNDR_PHOTO_GRP1) KEEP (DENSE_RANK LAST ORDER BY N.NCR_DOC_NO)
		       END                                                                                          AS PHOTO_GRP1
		       
		     , CASE WHEN MAX(B.NCR_DOC_NO) IS NULL 
		            THEN MAX(B.PHOTO_DESC_1) KEEP (DENSE_RANK LAST ORDER BY B.ODAY_CHK_DT) 
		            ELSE MAX(N.VNDR_PHOTO_DESC_1) KEEP (DENSE_RANK LAST ORDER BY N.NCR_DOC_NO)
		       END                                                                                          AS PHOTO_DESC_1
		       
		     , CASE WHEN MAX(B.NCR_DOC_NO) IS NULL 
		            THEN MAX(B.PHOTO_GRP2) KEEP (DENSE_RANK LAST ORDER BY B.ODAY_CHK_DT) 
		            ELSE MAX(N.VNDR_PHOTO_GRP2) KEEP (DENSE_RANK LAST ORDER BY N.NCR_DOC_NO)
		       END                                                                                          AS PHOTO_GRP2
		       
		     , CASE WHEN MAX(B.NCR_DOC_NO) IS NULL 
		            THEN MAX(B.PHOTO_DESC_2) KEEP (DENSE_RANK LAST ORDER BY B.ODAY_CHK_DT) 
		            ELSE MAX(N.VNDR_PHOTO_DESC_2) KEEP (DENSE_RANK LAST ORDER BY N.NCR_DOC_NO)
		       END                                                                                          AS PHOTO_DESC_2
		
		  FROM BASE_DATA B
		  LEFT JOIN NCR_DATA N ON B.SIT_CD     = N.SIT_CD
		                      AND B.NCR_DOC_NO = N.NCR_DOC_NO
		
		 GROUP BY 
		       B.CUST_CD
		     , B.VNDR_SEQ
		     , B.CTP_CD
		     , B.UNT_CD
		     , B.CHK_ITM_CD
		    ;

    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
         WHEN OTHERS THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);

END PQHA_RISK_CHK_AGO_Q;
/

-- PQHA_RISK_CHK_B (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_RISK_CHK_B" -- 협력업체 위험성평가 전 차수 복사 
                            (p_WRK_TP  VARCHAR2 :='I'                                     -- UPDATE FLAG( I: ISNERT, U:UPDATE, D:DELTE)
                            ,p_WRK_ID  VARCHAR2                                           -- 사용자 ID 
                            ,p_WRK_IP  VARCHAR2                                           -- 사용자 IP 
                            ,p_SIT_CD TQHA_RISK_CHK.SIT_CD%TYPE                         -- 현장코드
                            ,p_PLN_PYM  TQHA_RISK_CHK.PLN_YM%TYPE                         -- 전 회자년월(예 202110)
                            ,p_PLN_TYM  TQHA_RISK_CHK.PLN_YM%TYPE                         -- 해당 회자년월(예 202111)
                            ,p_PLN_PDGR TQHA_RISK_CHK.PLN_DGR%TYPE                        -- 전 회자(예 01)
                            ,p_PLN_TDGR TQHA_RISK_CHK.PLN_DGR%TYPE                        -- 해당 회자(예 02)                                                                                                                
                            ,p_CUST_CD TQHA_RISK_CHK.CUST_CD%TYPE                         -- 업체코드
                            ,p_VNDR_SEQ TQHA_RISK_CHK.VNDR_SEQ%TYPE)                      -- 업체순번

IS 
    /**************************************************************************************************************************
      Purpose : 협력업체 위험성평가 전 차수 복사 
  
      REVISIONS
      Ver      Date               Author                  Description 
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2021/12/07 12:48:42                         최초생성
      1.1     2022/04/27                                  보안강화(위험성평가 승인여부 체크 추가)

    **************************************************************************************************************************/


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR2(200);            -- ERROR Message
    USER_EXCEPTION EXCEPTION;

    v_tcnt  INTEGER;                                -- 현 차수에 삭제할 데이타가 존재하는지 체크
    v_pcnt  INTEGER;                                -- 전 차수에 복사할 데이타가 존재하는지 체크
    v_SBM_YN VARCHAR2(10) := '0';               -- 관리자 승인 여부 체크
BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 필수입력 필드  Check  ]
    ---------------------------------------------------------------------------------------------------------------------------
        -- 전월의 데이타를 존재여부 체크
	    SELECT nvl(COUNT(PLN_DGR),0) 
	      INTO v_Pcnt
	      FROM TQHB_RISK_LST
         WHERE SIT_CD = p_SIT_CD          --변수 (현장코드) 
           AND PLN_YM = p_PLN_PYM           --전 회자년월
	       AND PLN_DGR = p_PLN_PDGR         --전 차수구분코드(QS005) 1 1차,2 2차
	       AND CUST_CD = p_CUST_CD          --협력업체코드
	       AND VNDR_SEQ = p_VNDR_SEQ;       --업체순번

         -- 전월 데이타코드 Validation
        IF v_Pcnt < 1 THEN
           ERR_MSG := '계획년월 "' || p_PLN_PYM || ' 전 회차 "' || p_PLN_PDGR || '" 은(는) 복사할 데이타가 존재하지 않습니다. 확인 후 다시 작업해주세요. ';
           RAISE USER_EXCEPTION;
        END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Process 선행조건 Check ]
    ---------------------------------------------------------------------------------------------------------------------------

    -- 위험성 평가서 제출 여부 체크 (보안 강화 2022/04/27 수정)
		SELECT SBM_YN INTO v_SBM_YN    -- 관리자 승인상태 여부
		  FROM TQHB_RISK_VNDR
		 WHERE SIT_CD = p_SIT_CD         --현장코드
           AND PLN_YM = p_PLN_TYM           --계획년월
           AND PLN_DGR = p_PLN_TDGR         --차수구분코드(QS005) 1 1차,2 2차
           AND CUST_CD = p_CUST_CD         --업체코드
           AND VNDR_SEQ = p_VNDR_SEQ;      --업체순번

    -- 1차 관리자 승인된 경우 제출 및 취소 불가
    IF v_SBM_YN = '1' THEN
       ERR_MSG := '위험성평가서를 제출한 경우 전회차 복사가 불가합니다. ';
       RAISE USER_EXCEPTION;
    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Business Process ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_WRK_TP = 'I') THEN 

        -- 기존 위험성평가 해당 차수의 데이타 존재여부 체크
	    SELECT nvl(COUNT(PLN_DGR),0) 
	      INTO v_tcnt
	      FROM TQHB_RISK_LST
         WHERE SIT_CD = p_SIT_CD          --변수 (현장코드) 
           AND PLN_YM = p_PLN_TYM           --해당 회자년월
	       AND PLN_DGR = p_PLN_TDGR         --차수구분코드(QS005) 1 1차,2 2차
	       AND CUST_CD = p_CUST_CD          --협력업체코드
	       AND VNDR_SEQ = p_VNDR_SEQ;       --업체순번

         -- 기존 위험성평가 해당 차수의 데이타가 존재하면
        IF v_tcnt > 0 THEN
            -- 기존 위험성평가 해당 차수의 데이타를 삭제
	        DELETE 
	          FROM TQHB_RISK_LST
	         WHERE SIT_CD = p_SIT_CD          --현장코드
	           AND PLN_YM = p_PLN_TYM           --해당 회자년월
	           AND PLN_DGR = p_PLN_TDGR         --차수구분코드(QS005) 1 1차,2 2차
	           AND CUST_CD = p_CUST_CD          --협력업체코드
	           AND VNDR_SEQ = p_VNDR_SEQ;       --업체순번

        END IF;       

		INSERT INTO TQHB_RISK_LST
                   ( SIT_CD                  --현장코드
                    ,PLN_YM                  --계획년월
                    ,PLN_DGR                 --차수구분코드(QS005) 1 1차,2 2차
                    ,CUST_CD                 --협력업체코드
                    ,VNDR_SEQ
                    ,CTP_CD                  --공종코드
                    ,UNT_CD                  --단위코드
                    ,CHK_ITM_CD              --점검항목코드
                    ,CHK_ITM_SEQ             --점검항목 정열순서 
                    ,CHK_ITM_NM              --점검항목명
                    ,CHK_LOC                 --점검위치
                    ,DISS_SHP                --재해형태(QS036)
                    ,RISK_FREQ               --확정_빈도(QS09003) 작성
                    ,RISK_APRV               --확정_강도(QS09004) 작성
                    ,RISK_CRIT               --확정_위험성(QS09001) 작성
                    ,RISK_GRD                --확정_위험등급(QS09002) 작성
                    ,IMPRV_CPLN              --개선대책
                    ,WRK_PSNNO               --작업인원
                    ,ITM_ADD_YN              --기존 : 0, 추가 : 1
                    ,IPT_ID                  --입력ID
                    ,IPT_DTM                 --입력일시
                    ,IPT_IP                  --입력IP
                    ,UPD_ID                  --수정ID
                    ,UPD_DTM                 --수정일시
                    ,UPD_IP                  --수정IP
                    )
				SELECT  A.SIT_CD                 --현장코드
			           ,p_PLN_TYM                 --계획년월
			           ,p_PLN_TDGR                 --차수구분코드(QS005) 1 1차,2 2차
			           ,A.CUST_CD                 --협력업체코드
			           ,A.VNDR_SEQ
			           ,A.CTP_CD                 --공종코드
			           ,A.UNT_CD                 --단위코드
			           ,A.CHK_ITM_CD                 --점검항목코드
			           ,A.CHK_ITM_SEQ                 --점검항목 정열순서
			           ,A.CHK_ITM_NM                 --점검항목명
			           ,A.CHK_LOC                 --점검위치
			           ,A.DISS_SHP                 --재해형태(QS036)
			           ,A.RISK_FREQ                 --확정_빈도(QS09003) 작성
			           ,A.RISK_APRV                 --확정_강도(QS09004) 작성
			           ,A.RISK_CRIT                 --확정_위험성(QS09001) 작성
			           ,A.RISK_GRD                 --확정_위험등급(QS09002) 작성
			           ,A.IMPRV_CPLN                 --개선대책
			           ,A.WRK_PSNNO                 --작업인원
			           ,A.ITM_ADD_YN                 --기존 : 0, 추가 : 1
			           ,p_WRK_ID                --입력ID 
	                   ,SYSDATE()               --입력일시
	                   ,p_WRK_IP                --입력IP
	                   ,p_WRK_ID                --수정ID
	                   ,SYSDATE()               --수정일시
	                   ,p_WRK_IP              --수정IP
			      FROM TQHB_RISK_LST A
			    WHERE  A.SIT_CD = p_SIT_CD                     --현장코드
			       AND A.PLN_YM = p_PLN_PYM                     --계획년월
			       AND A.PLN_DGR = p_PLN_PDGR                     --차수구분코드(QS005) 1 1차,2 2차
			       AND A.CUST_CD = p_CUST_CD                     --협력업체코드
			       AND A.VNDR_SEQ = p_VNDR_SEQ                    --협력업체순번
			       ;
    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 5. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN 
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);
END PQHA_RISK_CHK_B;
/

-- PQHA_RISK_CHK_B1 (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_RISK_CHK_B1" ( -- 위험성평가 차수 승인
    p_WRK_TP            VARCHAR2 :='S'                          -- UPDATE FLAG( I: ISNERT, U:UPDATE, D:DELTE, S : 승인처리)
,   p_WRK_ID            VARCHAR2                                -- 사용자 ID
,   p_WRK_IP            VARCHAR2                                -- 사용자 IP
,   p_SIT_CD            TQHA_RISK_CHK.SIT_CD        %TYPE       -- 현장코드
,   p_PLN_YM            TQHA_RISK_CHK.PLN_YM        %TYPE       -- 계획년월
,   p_PLN_DGR           TQHA_RISK_CHK.PLN_DGR       %TYPE       -- 회자
,   p_CUST_CD           TQHA_RISK_CHK.CUST_CD       %TYPE       -- 업체코드
,   p_VNDR_SEQ          TQHA_RISK_CHK.VNDR_SEQ      %TYPE       -- 업체순번
,   p_USR_ID            TQHA_RISK_CHK.MA_CNFR       %TYPE       -- 사번
,   p_RTN_BTN           OUT VARCHAR2                            -- 리턴값 (승인여부)
,   p_RTN_MNG_DIV       OUT VARCHAR2                            -- 리턴값 (관리자/안전/소장)
)
IS
    /**************************************************************************************************************************
      Purpose : 위험성평가 평가서제출 승인처리 

      REVISIONS
      Ver      Date               Author                  Description
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2021/12/13 12:48:42                         최초생성

    **************************************************************************************************************************/


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR2(200);            -- ERROR Message 
    USER_EXCEPTION EXCEPTION;


    v_MGR_APRV      VARCHAR2(1) ;   -- 관리감독자 승인여부
    v_SAFT_APRV     VARCHAR2(1) ;   -- 안전감독자 승인여부
    v_SITE_APRV     VARCHAR2(1) ;   -- 현장소장 승인여부

    v_CTP_CNT       INTEGER;                -- 공종담당자 여부
    v_MGR_CNT       INTEGER;                -- 관리감독자 여부
    v_SAFT_CNT      INTEGER;                -- 안전관리자 여부
    v_SITE_CNT      INTEGER;                -- 현장소장 여부

    v_RTN_BTN VARCHAR2(1)       := 'F' ;    -- 리턴 초기값
    v_RTN_MNG_DIV VARCHAR2(10)  := 'N' ;    -- 리턴 상태 초기값 ( 관리자 MGR : 관리자, SAFT : 안전관리자, SITE : 현장소장 )


BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 필수입력 필드  Check  ]
    ---------------------------------------------------------------------------------------------------------------------------
    -- 승인 할 데이터가 있는지 체크
    SELECT nvl(MNG_APRV_STATS,0)            -- 관리감독자 승인여부
         , nvl(SAFT_APRV_STATS,0)           -- 안전관리자 승인여부
         , nvl(SITE_APRV_STATS,0)           -- 현장소장 승인여부
      INTO v_MGR_APRV                       -- 관리감독자 승인여부
         , v_SAFT_APRV                      -- 안전관리자 승인여부
         , v_SITE_APRV                      -- 현장소장 승인여부
      FROM TQHA_RISK_VNDR
     WHERE SIT_CD       = p_SIT_CD          -- 변수 (현장코드)
       AND PLN_YM       = p_PLN_YM          -- 회자년월
       AND PLN_DGR      = p_PLN_DGR         -- 차수구분코드(QS005) 1 1차,2 2차
       AND CUST_CD      = p_CUST_CD         -- 협력업체코드
       AND VNDR_SEQ     = p_VNDR_SEQ        -- 업체순번
    ;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Process 선행조건 Check ]
    ---------------------------------------------------------------------------------------------------------------------------


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Business Process ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_WRK_TP = 'S') THEN    -- 승인처리
        --------------------------------------------------------
        -- 관리자 승인 전 단계
        IF (v_MGR_APRV = '0') THEN

            -- 관리자가 승인 권한이 있는지 체크
            SELECT nvl(COUNT(CUST_CD),0)
              INTO v_MGR_CNT
              FROM TQHA_VNDR
             WHERE SIT_CD       = p_SIT_CD          -- 변수 (현장코드)
               AND CUST_CD      = p_CUST_CD         -- 변수 (업체코드)
               AND VNDR_SEQ     = p_VNDR_SEQ        -- 변수 (업체차수)
               AND ( MGR_1 IN (p_USR_ID) OR MGR_2 IN (p_USR_ID) OR MGR_3 IN (p_USR_ID) )  -- 변수 (사번)
            ;
            -- 숭인권한이 있음
            IF v_MGR_CNT > 0 then
                v_RTN_BTN := 'T';
                v_RTN_MNG_DIV := 'MGR';
            ELSE
                -- 공종별 담당자 권한 체크
                SELECT NVL(COUNT(CHK_ITM_CD), 0)
                  INTO v_CTP_CNT
                  FROM TQHA_RISK_CHK
                 WHERE SIT_CD       = p_SIT_CD          -- 현장코드
                   AND PLN_YM       =  p_PLN_YM         -- 계획년월
                   AND PLN_DGR      = p_PLN_DGR         -- 차수구분코드(QS005) 1 1차,2 2차
                   AND CUST_CD      = p_CUST_CD         -- 업체순번
                   AND VNDR_SEQ     = p_VNDR_SEQ        -- 업체순번
                   AND MA_CNFR      IN (p_USR_ID)
                ;

                -- 숭인권한이 있음
                IF v_CTP_CNT > 0 then
                    v_RTN_BTN      := 'T';
                    v_RTN_MNG_DIV  := 'MGR';
                END IF;
            END IF;
        END IF;

        --------------------------------------------------------
        -- 관리자 승인 후 단계
        IF (v_MGR_APRV = '1' AND v_SAFT_APRV = '0' ) THEN     -- 관리자 승인 후 AND 안전관리자 승인 전

            /*
            -- 안전관리자 승인 권한이 있는지 체크
            SELECT  nvl(COUNT(JB_CD),0)
              INTO v_SAFT_CNT
              FROM  ( -- 조직도에서 직무코드가 안전관리자인 경우
                     SELECT   DEPT_CD   -- 현장코드
                           , USR_ID    -- 사용자 id
                           , JB_CD     -- 직무코드
                      FROM TCOZ_USR_INFO
                     WHERE DEPT_CD = p_SIT_CD       -- 변수(현장코드)
                     AND  JB_CD IN ('B37E01','CM0135','CM0136','CM0137') ) A
             WHERE A.DEPT_CD = p_SIT_CD   -- 변수 (현장코드)
               AND A.USR_ID = p_USR_ID     -- 변수 (사용자id)
                  ;
            */

            -- 안전관리자 승인 권한이 있는지 체크
            SELECT nvl(COUNT(JB_CD),0)
              INTO v_SAFT_CNT
              FROM (
                    -- 2026.01.20 주석
                    -- 조직도에서 직무코드가 안전관리자인 경우
                    --SELECT   DEPT_CD   -- 현장코드
                    --        , USR_ID    -- 사용자 id
                    --        , JB_CD     -- 직무코드
                    --  FROM TCOZ_USR_INFO
                    -- WHERE DEPT_CD = p_SIT_CD       -- 변수(현장코드)
                    --   AND  JB_CD IN ('B37E01','CM0135','CM0136','CM0137')
                    -- UNION   -- 2020/5/18 일 겸직정보 추가
                    -- SELECT DEPT_CD   -- 현장코드
                    --       , USR_ID    -- 사용자 id
                    --       , JB_CD     -- 직무코드
                    --   FROM TCOZ_SBJB_INFO
                    --  WHERE DEPT_CD = p_SIT_CD
                    --    AND JB_CD IN ('B37E01','CM0135','CM0136','CM0137')

                   SELECT SIT_CD    AS DEPT_CD
                         , EMPE_NO    AS USR_ID
                         , JB_CD      AS JB_CD
                      FROM TQHA_SITENAM
                     WHERE SIT_CD = p_SIT_CD
                       AND EMPE_NO = p_USR_ID
                       AND JB_CD IN ('QS07702')  -- 안전관리자, 안전총괄
                   ) A
             WHERE A.DEPT_CD = p_SIT_CD   -- 변수 (현장코드)
               AND A.USR_ID = p_USR_ID     -- 변수 (사용자id)
            ;

            -- 관리자가 승인 권한이 있는지 체크
            IF v_SAFT_CNT > 0 then
                v_RTN_BTN       := 'T';
                v_RTN_MNG_DIV   := 'SAFT';
            END IF;

        END IF;

        --------------------------------------------------------
        -- 안전관리자 승인 후 단계
        IF (v_MGR_APRV = '1' AND v_SAFT_APRV = '1') THEN

            -- 현장소장 승인 권한이 있는지 체크
            SELECT nvl(COUNT(JB_CD),0)
              INTO v_SITE_CNT
              FROM (
                   -- 2026.01.20 주석
                   -- 조직도에서 직무코드가 안전관리자인 경우
                    --SELECT   DEPT_CD   -- 현장코드
                    --      , USR_ID    -- 사용자 id
                    --      , JB_CD     -- 직무코드
                    -- FROM TCOZ_USR_INFO
                    --WHERE DEPT_CD = p_SIT_CD   -- 변수(현장코드)
                    --AND  JB_CD IN ('B37F01')
                    SELECT SIT_CD      AS DEPT_CD
                         , EMPE_NO     AS USR_ID
                         , DTY_CD      AS JB_CD
                      FROM TQHA_SITENAM
                     WHERE SIT_CD   = p_SIT_CD
                       AND DTY_CD   IN ('B37F01')       -- 현장소장
                   ) A
             WHERE A.DEPT_CD    = p_SIT_CD     -- 변수 (현장코드)
               AND A.USR_ID     = p_USR_ID     -- 변수 (사용자id)
            ;

            -- 현장소장 승인 권한이 있는지 체크
            IF v_SITE_CNT > 0 then
               v_RTN_BTN        := 'T';
               v_RTN_MNG_DIV    := 'SITE';
            END IF;

        END IF;

        -- 현장소장 승인 후 단계
        --IF (v_SITE_APRV <> '0' ) THEN

        -- 2026.01.27 수정. 소장 반려됐을 경우엔 무조건 F, N 으로 넘어감.
        IF (v_SITE_APRV = '1' ) THEN
               v_RTN_BTN        := 'F';
               v_RTN_MNG_DIV    := 'N';
        END IF;

        p_RTN_BTN       := v_RTN_BTN ;
        p_RTN_MNG_DIV   := v_RTN_MNG_DIV ;

    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 5. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);

END PQHA_RISK_CHK_B1;
/

-- PQHA_RISK_CHK_Q (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_RISK_CHK_Q" (  
    p_WRK_TP                IN VARCHAR2 DEFAULT 'Q'             -- FLAG
,   p_SIT_CD                IN VARCHAR2
,   p_SEARCH_SIT_CD         IN VARCHAR2
,   p_SEARCH_VNDR_CD        IN VARCHAR2
,   p_SEARCH_VNDR_SEQ       IN VARCHAR2
,   p_SEARCH_PLN_YM         IN VARCHAR2
,   p_SEARCH_PLN_DGR        IN VARCHAR2
,   p_CUST_CD               IN VARCHAR2
,   p_VNDR_SEQ              IN VARCHAR2
,   RTN_CURSOR              OUT SYS_REFCURSOR
)
IS
    /**************************************************************************************************************************
      Purpose : [평가항목 조회] PROCEDRE (QSE > 안전관리 > 위험성평가(수시) > 진행관리  )

      REVISIONS
      Ver      Date               Author                  Description
      -------  -----------------  ----------------------  ---------------------------------------------------------------------
      1.0      2023/12/07                                 최초생성  

    **************************************************************************************************************************/

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE  NUMBER :=-20009; -- ERROR 코드
    ERR_MSG   VARCHAR(200);    -- ERROR Message
    USER_EXCEPTION EXCEPTION; 

BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 수행전 Check Logic ]
    ---------------------------------------------------------------------------------------------------------------------------

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Logic 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------

    IF p_WRK_TP = 'Q' THEN

        OPEN RTN_CURSOR FOR
        SELECT A.SIT_CD                                     -- 현장코드
             , A.PLN_YM                                     -- 계획년월
             , A.PLN_DGR                                    -- 계획차수
             , (SELECT CD_NM FROM TCOA_COMCODE WHERE COM_CD = A.PLN_DGR AND HRNK_CD = 'QS005') AS PLN_DGR_NM  -- 계획차수 
             , A.APRS_STR_DT                                -- 평가시작일자
             , A.APRS_END_DT                                -- 평가종료일자
             , A.VNDR_CMPL_DT                               -- 업체작성완료일자
             , (SELECT CASE MIN(NVL(SITE_APRV_STATS,0)) WHEN '0' THEN ''
                                                        WHEN '1' THEN  MAX(SITE_APRV_DT) END FIN_DT
                   FROM TQHA_RISK_VNDR 
                  WHERE SIT_CD      = A.SIT_CD              -- 현장코드 변수
                    AND PLN_YM      = A.PLN_YM              -- 변수 ( 년월)
                    AND PLN_DGR     = A.PLN_DGR             -- 변수 ( 차수)
                    AND OBJ_YN      = '1' )  AS FINAL_DT    -- 최종승인일자
             , A.CONF_SCH_DT                                -- 회의예정일자
             , A.PLN_YM || A.PLN_DGR    AS FOCUS            -- 포커스용
             , A.APRV_NO                                    -- 결재번호
             , B.APRV_STATS                                 -- 결재상태
             , ( SELECT CD_NM FROM TCOA_COMCODE WHERE HRNK_CD = 'QS031' AND COM_CD = B.APRV_STATS ) AS APRV_STATS_NM -- 결재상태명
          FROM TQHA_RISK_DGR A      
              ,TQHA_APRV B
         WHERE A.SIT_CD     = p_SIT_CD
           AND A.SIT_CD     = B.SIT_CD (+)
           AND A.APRV_NO    = B.APRV_NO (+)
         ORDER BY A.PLN_YM DESC, A.PLN_DGR DESC
        ;

    ------------------------------------------------------------------------------
    ELSIF p_WRK_TP = 'Q1' THEN

        OPEN RTN_CURSOR FOR
        SELECT A.SIT_CD                     -- 현장코드
             , A.PLN_YM                     -- 계획년월
             , A.PLN_DGR                    -- 계획차수
             , A.CUST_CD                    -- 협력업체코드
             , B.CUST_NM AS VNDR_NM         -- 협력업체명
             , A.VNDR_SEQ                   -- 협력업체순번
             , A.CTP_CD                     -- 공종코드
             , C.CTP_NM                     -- 공종명
             , A.UNT_CD                     -- 단위코드
             , D.UNT_NM                     -- 단위명
             , A.CHK_ITM_CD                 -- 위험요인항목코드
             , A.CHK_ITM_NM                 -- 위험요인항목명
             , A.CHK_LOC                    -- 점검장소
             , A.DISS_SHP                   -- 재해형태(공통코드 QS036)
             , A.RISK_FREQ                  -- 위험빈도(공통코드 QS003)
             , A.RISK_APRV                  -- 위험강도(공통코드 QS004)
             , A.RISK_CRIT   	            -- 위험성레벨(QS063)
             , A.RISK_GRD                   -- 위험등급(공통코드 QS024)
             , A.PRRT_REG                   -- 중점등록(공통코드 QS002)             
             , A.RISK_FREQ2                  -- 위험빈도(공통코드 QS003)
             , A.RISK_APRV2                  -- 위험강도(공통코드 QS004)
             , A.RISK_CRIT2   	            -- 위험성레벨(QS063)
             , A.RISK_GRD2                   -- 위험등급(공통코드 QS024)             
             , A.RISK_FREQ3                  -- 위험빈도(공통코드 QS003)
             , A.RISK_APRV3                  -- 위험강도(공통코드 QS004)
             , A.RISK_CRIT3   	            -- 위험성레벨(QS063)
             , A.RISK_GRD3                   -- 위험등급(공통코드 QS024)             
             , A.RISK_FREQ4                  -- 위험빈도(공통코드 QS003)
             , A.RISK_APRV4                  -- 위험강도(공통코드 QS004)
             , A.RISK_CRIT4   	            -- 위험성레벨(QS063)
             , A.RISK_GRD4                   -- 위험등급(공통코드 QS024)             
             , A.RISK_FREQ5                  -- 위험빈도(공통코드 QS003)
             , A.RISK_APRV5                  -- 위험강도(공통코드 QS004)
             , A.RISK_CRIT5   	            -- 위험성레벨(QS063)
             , A.RISK_GRD5                   -- 위험등급(공통코드 QS024)             
             , A.RISK_FREQ6                  -- 위험빈도(공통코드 QS003)
             , A.RISK_APRV6                  -- 위험강도(공통코드 QS004)
             , A.RISK_CRIT6   	            -- 위험성레벨(QS063)
             , A.RISK_GRD6                   -- 위험등급(공통코드 QS024)    
             , A.MNG_SUPR
             , A.MGR_OPIN                 --관리자의견
             , ( SELECT USR_NM FROM TCOZ_USR_INFO WHERE USR_ID = A.MNG_SUPR ) AS MNG_SUPR_NM  -- 관리감독자성명           
             , A.SAFT_MGR                 --안전관리자
             , A.SAFT_OPIN                 --안전의견
             , ( SELECT USR_NM FROM TCOZ_USR_INFO WHERE USR_ID = A.SAFT_MGR ) AS SAFT_MGR_NM  -- 안전관리자성명           
             , A.SITE_OMGR                 --현장소장
             , A.SITE_OPIN                 --현장소장의견
             , ( SELECT USR_NM FROM TCOZ_USR_INFO WHERE USR_ID = A.SITE_OMGR ) AS SITE_OMGR_NM -- 현장소장성명
             , A.IMPRV_CPLN             -- 개선대책
             , A.WRK_PSNNO              -- 작업인원
             , A.MA_PSN                 -- 조치자(업체)
             , A.MA_CNFR                -- 확인자(안전관리자)
             , ( SELECT USR_NM FROM TCOZ_USR_INFO WHERE USR_ID = A.MA_CNFR ) AS MA_CNFR_NM        -- 확인자성명
             , A.WRK_STR_DT                  -- 작업시작일자
             , A.WRK_END_DT                  -- 작업종료일자
             , A.IMPRV_STR_DT                -- 개선시작일자
             , A.IMPRV_END_DT                -- 개선종료일자
             , A.CHK_LOC                     -- 점검위치
             ,(SELECT DECODE(COUNT(1),0,'중흥','협력사') FROM TQHA_VNDR WHERE SIT_CD = A.SIT_CD AND VNDR_PSN_ID = A.IPT_ID) AS REG_DIV
             , A.VNDR_WRK_NM
             , A.VNDR_WRK_OPIN
          FROM TQHA_RISK_CHK   A
             , VQSZ_TRADE       B 
             , TQHA_CTP         C
             , TQHA_CTPUNT      D
             , TCOZ_USR_INFO    E
         WHERE A.CUST_CD        = B.CUST_CD
           AND A.CTP_CD         = C.CTP_CD
           AND A.CTP_CD         = D.CTP_CD
           AND A.UNT_CD         = D.UNT_CD
           AND A.MA_CNFR        = E.USR_ID
           AND A.SIT_CD         = p_SEARCH_SIT_CD
           AND A.PLN_YM         = p_SEARCH_PLN_YM
           AND A.PLN_DGR        = p_SEARCH_PLN_DGR
           AND A.CUST_CD LIKE p_SEARCH_VNDR_CD ||'%'
           AND A.VNDR_SEQ LIKE p_SEARCH_VNDR_SEQ ||'%'
           AND (NVL(p_CUST_CD, '*') = '*' OR A.CUST_CD = p_CUST_CD)
        ;

    ------------------------------------------------------------------------------
    ELSIF p_WRK_TP = 'Q2' THEN

        OPEN RTN_CURSOR FOR
        SELECT SIT_CD           -- 현장코드
             , PLN_YM           -- 계획년월
             , PLN_DGR          -- 계획차수
             , CUST_CD          -- 협력업체코드
             , VNDR_SEQ         -- 협력업체차수
          FROM TQHA_RISK_VNDR
         WHERE SIT_CD       = p_SEARCH_SIT_CD
           AND PLN_YM       = p_SEARCH_PLN_YM
           AND PLN_DGR      = p_SEARCH_PLN_DGR
           AND CUST_CD      = p_CUST_CD
           AND VNDR_SEQ     = p_VNDR_SEQ
           AND OBJ_YN       = '1'   -- 대상유무
        ;

    ------------------------------------------------------------------------------
    ELSIF p_WRK_TP = 'Q3' THEN

        OPEN RTN_CURSOR FOR
        SELECT A.SIT_CD             -- 현장코드
             , A.PLN_YM             -- 계획년월
             , A.PLN_DGR            -- 계획차수
             , A.CONF_DT            -- 회의일자
             , A.CONF_PLC           -- 회의장소
             , A.AM_NOTICE          -- 공지사항
             , A.AREC_CTS           -- 회의록내용
             , A.AREC_ATFL_GRP      -- 회의록첨부파일그룹
             , A.PHOTO_GRP1         -- 회의록사진1
             , A.PHOTO_DESC_1       -- 회의록사진설명1
             , A.PHOTO_GRP2         -- 회의록사진2
             , A.PHOTO_DESC_2       -- 회의록사진설명2
             , (SELECT COUNT(SIT_CD) FROM TQHA_ASSLOG_CIRC 
                                      WHERE SIT_CD      = A.SIT_CD 
                                        AND PLN_YM      = A.PLN_YM 
                                        AND PLN_DGR     = A.PLN_DGR
                                        AND PRTR_YN     = '1'
               )                                                        AS PRTR_NO      -- 참석인원
             , (SELECT COUNT(SIT_CD) FROM TQHA_ASSLOG_CIRC 
                                      WHERE SIT_CD      = A.SIT_CD 
                                        AND PLN_YM      = A.PLN_YM 
                                        AND PLN_DGR     = A.PLN_DGR
                                        AND PRTR_YN     = '1'
                                        AND CO_DIV_CD   = '1'
               )                                                        AS PRTR_NO1     -- 당사참석인원
             , (SELECT COUNT(SIT_CD) FROM TQHA_ASSLOG_CIRC 
                                      WHERE SIT_CD      = A.SIT_CD 
                                        AND PLN_YM      = A.PLN_YM 
                                        AND PLN_DGR     = A.PLN_DGR
                                        AND PRTR_YN     = '1'
                                        AND CO_DIV_CD   = '2'
               )                                                        AS PRTR_NO2     -- 협력회사참석인원
          FROM TQHB_RISK_DGR A
         WHERE 1=1
           AND A.SIT_CD     = p_SEARCH_SIT_CD
           AND A.PLN_YM     = p_SEARCH_PLN_YM
           AND A.PLN_DGR    = p_SEARCH_PLN_DGR
        ;
        
    ELSIF p_WRK_TP = 'Q4' THEN
        -- 금회추전계획
        OPEN RTN_CURSOR FOR
        WITH BASE_DATA AS (
		    SELECT A.SIT_CD                 -- 현장코드
		          ,A.PLN_YM                 -- 계획년월
		          ,A.PLN_DGR                -- 차수구분코드(QS005) 1 1차, 2 2차
		          ,A.CUST_CD                -- 협력업체코드
		          ,A.VNDR_SEQ               -- 협력업체순번
		          ,(SELECT CUST_NM FROM VQSZ_TRADE WHERE CUST_CD = A.CUST_CD) AS CUST_NM
		          ,A.CTP_CD                 -- 공종코드
		          ,A.UNT_CD                 -- 단위코드
		          ,(SELECT CTP_NM FROM TQHA_CTP WHERE CTP_CD = A.CTP_CD) AS CTP_NM
		          ,(SELECT UNT_NM FROM TQHA_CTPUNT WHERE CTP_CD = A.CTP_CD AND UNT_CD = A.UNT_CD) AS UNT_NM
		          ,A.CHK_ITM_CD             -- 점검항목코드
		          ,A.CHK_ITM_SEQ            -- 점검항목 정열순서
		          ,A.CHK_ITM_NM             -- 점검항목명
		          ,A.CHK_LOC                -- 점검위치
		          ,A.DISS_SHP                -- 재해형태(QS036)
		          ,A.IMPRV_CPLN             -- 개선대책 (TQHB_RISK_LST)
		          ,A.WRK_PSNNO              -- 작업인원
		          ,A.ITM_ADD_YN             -- 기존 : 0, 추가 : 1
		          -- TQHB_RISK_LST 기본 위험성 점수 및 의견 (최종점수 행용)
		          ,A.RISK_CRIT   AS LST_RISK_CRIT
		          ,A.RISK_CRIT2  AS LST_RISK_CRIT2
		          ,A.MGR_OPIN    AS LST_MGR_OPIN
		          
		          -- [TQHB_RISK_NAM 명단 컬럼]
		          ,B.EMPE_NO                -- 사원번호
		          ,B.APRS_NAMSEQ            -- 점검자 정열순서
		          ,B.CO_DIV_CD              -- 회사구분코드
		          ,B.JB_CD                  -- 직무/직급코드
		          ,NVL((SELECT CD_NM FROM TCOA_COMCODE WHERE COM_CD = B.JB_CD AND HRNK_CD = 'QS077' AND USE_YN = '1'), '') AS JB_NM
		          ,CASE WHEN B.CO_DIV_CD = '1' THEN (SELECT USR_NM FROM TCOZ_USR_INFO WHERE EMPNO = B.EMPE_NO) 
		                                            || '/' || NVL((SELECT CD_NM FROM TCOA_COMCODE WHERE COM_CD = B.JB_CD AND HRNK_CD = 'QS077' AND USE_YN = '1'), '')
		                WHEN B.CO_DIV_CD = '2' THEN (SELECT PNM FROM TQHB_VNDRNAM WHERE SIT_CD = A.SIT_CD AND CUST_CD = A.CUST_CD AND VNDR_SEQ = A.VNDR_SEQ AND EMPE_NO = B.EMPE_NO) 
		                                            || '/' || NVL((SELECT CD_NM FROM TCOA_COMCODE WHERE COM_CD = B.JB_CD AND HRNK_CD = 'QS077' AND USE_YN = '1'), '')
		           END AS USR_NM
		           
		          -- [TQHB_RISK_CHK 실제 작성자 본인의 점수만 매핑 (미입력자는 NULL)]
		          ,TO_NUMBER(C.RISK_FREQ)  AS RISK_FREQ   
		          ,TO_NUMBER(C.RISK_APRV)  AS RISK_APRV   
		          ,TO_NUMBER(C.RISK_CRIT)  AS RISK_CRIT   
		          ,C.RISK_GRD                            
		          ,TO_NUMBER(C.RISK_FREQ2) AS RISK_FREQ2  
		          ,TO_NUMBER(C.RISK_APRV2) AS RISK_APRV2  
		          ,TO_NUMBER(C.RISK_CRIT2) AS RISK_CRIT2  
		          ,C.RISK_GRD2                            
		          ,C.MGR_OPIN               
		          ,C.SBM_DT                 
		          ,C.SBM_YN                 
		      FROM TQHB_RISK_LST A
		      -- 1. 해당 조건의 전체 점검자 명단 조인
		      INNER JOIN TQHB_RISK_NAM B
		        ON A.SIT_CD   = B.SIT_CD
		       AND A.PLN_YM   = B.PLN_YM
		       AND A.PLN_DGR  = B.PLN_DGR
		       AND A.CUST_CD  = B.CUST_CD
		       AND A.VNDR_SEQ = B.VNDR_SEQ
		      -- 2. 실제 점수를 작성했는지 확인하여 LEFT JOIN
		      LEFT JOIN TQHB_RISK_CHK C
		        ON A.SIT_CD     = C.SIT_CD
		       AND A.PLN_YM     = C.PLN_YM
		       AND A.PLN_DGR    = C.PLN_DGR
		       AND A.CUST_CD    = C.CUST_CD
		       AND A.VNDR_SEQ   = C.VNDR_SEQ
		       AND A.CTP_CD     = C.CTP_CD
		       AND A.UNT_CD     = C.UNT_CD
		       AND A.CHK_ITM_CD = C.CHK_ITM_CD
		       AND B.EMPE_NO    = C.EMPE_NO
		     WHERE A.SIT_CD   = p_SEARCH_SIT_CD                      -- 현장코드
		       AND A.PLN_YM   = p_SEARCH_PLN_YM                      -- 계획년월
		       AND A.PLN_DGR  = p_SEARCH_PLN_DGR                     -- 차수구분코드
		),
		SUMMARY_DATA AS (
		    -- 1. 원래 조회 데이터 (업체/점검자별 상세)
		    SELECT SIT_CD, PLN_YM, PLN_DGR, CUST_CD, VNDR_SEQ, CUST_NM
		          ,CTP_CD, UNT_CD, CTP_NM, UNT_NM, CHK_ITM_CD, CHK_ITM_SEQ, CHK_ITM_NM
		          ,CHK_LOC, DISS_SHP, IMPRV_CPLN, WRK_PSNNO, ITM_ADD_YN
		          ,1 AS ROW_DIV
		          ,APRS_NAMSEQ
		          ,EMPE_NO
		          ,CO_DIV_CD
		          ,JB_CD
		          ,JB_NM
		          ,SBM_YN
		          ,USR_NM
		          ,TO_CHAR(RISK_FREQ)  AS RISK_FREQ
		          ,TO_CHAR(RISK_APRV)  AS RISK_APRV
		          ,TO_CHAR(RISK_CRIT)  AS RISK_CRIT
		          ,TO_CHAR(RISK_CRIT2) AS RISK_CRIT2
		          ,MGR_OPIN
		      FROM BASE_DATA
		
		    UNION ALL
		
		    -- 2. 평균점수 행 (각 업체/위험요인 항목별 평균)
		    SELECT SIT_CD, PLN_YM, PLN_DGR, CUST_CD, VNDR_SEQ, CUST_NM
		          ,CTP_CD, UNT_CD, CTP_NM, UNT_NM, CHK_ITM_CD, CHK_ITM_SEQ, CHK_ITM_NM
		          ,CHK_LOC, DISS_SHP, IMPRV_CPLN, WRK_PSNNO, ITM_ADD_YN
		          ,2 AS ROW_DIV
		          ,998 AS APRS_NAMSEQ
		          ,NULL AS EMPE_NO
		          ,NULL AS CO_DIV_CD
		          ,NULL AS JB_CD
		          ,NULL AS JB_NM
		          ,NULL AS SBM_YN
		          ,'평균점수' AS USR_NM
		          ,NULL AS RISK_FREQ
		          ,NULL AS RISK_APRV
		          ,TO_CHAR(ROUND(AVG(RISK_CRIT), 1))  AS RISK_CRIT  -- 위험성 평균
		          ,TO_CHAR(ROUND(AVG(RISK_CRIT2), 1)) AS RISK_CRIT2 -- 개선후 위험성 평균
		          ,NULL AS MGR_OPIN
		      FROM BASE_DATA
		     GROUP BY SIT_CD, PLN_YM, PLN_DGR, CUST_CD, VNDR_SEQ, CUST_NM
		             ,CTP_CD, UNT_CD, CTP_NM, UNT_NM, CHK_ITM_CD, CHK_ITM_SEQ, CHK_ITM_NM
		             ,CHK_LOC, DISS_SHP, IMPRV_CPLN, WRK_PSNNO, ITM_ADD_YN
		
		    UNION ALL
		
		    -- 3. 최종점수 행 (BASE_DATA에서 직접 집계)
		    SELECT SIT_CD, PLN_YM, PLN_DGR, CUST_CD, VNDR_SEQ, CUST_NM
		          ,CTP_CD, UNT_CD, CTP_NM, UNT_NM, CHK_ITM_CD, CHK_ITM_SEQ, CHK_ITM_NM
		          ,CHK_LOC, DISS_SHP, IMPRV_CPLN, WRK_PSNNO, ITM_ADD_YN
		          ,3 AS ROW_DIV
		          ,999 AS APRS_NAMSEQ
		          ,NULL AS EMPE_NO
		          ,NULL AS CO_DIV_CD
		          ,NULL AS JB_CD
		          ,NULL AS JB_NM
		          ,NULL AS SBM_YN
		          ,'최종점수' AS USR_NM
		          ,NULL AS RISK_FREQ
		          ,NULL AS RISK_APRV
		          ,TO_CHAR(MAX(LST_RISK_CRIT))  AS RISK_CRIT   -- TQHB_RISK_LST의 위험성 점수
		          ,TO_CHAR(MAX(LST_RISK_CRIT2)) AS RISK_CRIT2  -- TQHB_RISK_LST의 개선후 위험성 점수
		          ,MAX(LST_MGR_OPIN)            AS MGR_OPIN
		      FROM BASE_DATA
		     GROUP BY SIT_CD, PLN_YM, PLN_DGR, CUST_CD, VNDR_SEQ, CUST_NM
		             ,CTP_CD, UNT_CD, CTP_NM, UNT_NM, CHK_ITM_CD, CHK_ITM_SEQ, CHK_ITM_NM
		             ,CHK_LOC, DISS_SHP, IMPRV_CPLN, WRK_PSNNO, ITM_ADD_YN
		)
		SELECT S.SIT_CD
		      ,S.PLN_YM
		      ,S.PLN_DGR
		      ,S.CUST_CD
		      ,S.VNDR_SEQ
		      ,S.CUST_NM
		      ,S.CTP_CD
		      ,S.UNT_CD
		      ,S.CTP_NM
		      ,S.UNT_NM
		      ,S.CHK_ITM_CD
		      ,S.CHK_ITM_SEQ
		      ,S.CHK_ITM_NM
		      ,S.CHK_LOC
		      ,S.DISS_SHP
		      ,S.IMPRV_CPLN
		      ,S.WRK_PSNNO
		      ,S.ITM_ADD_YN
		      ,S.RISK_FREQ      -- 빈도
		      ,S.RISK_APRV      -- 강도
		      ,S.RISK_CRIT      -- 위험성
		      ,S.RISK_CRIT2     -- 개선후 위험성
		      ,S.MGR_OPIN
		      ,S.EMPE_NO
		      ,S.APRS_NAMSEQ
		      ,S.CO_DIV_CD
		      ,S.JB_CD
		      ,S.JB_NM          -- 직급명
		      ,S.USR_NM         -- 사용자명/직급명
		      ,S.SBM_YN  
		      ,V.SBM_YN AS VNDR_SBM_YN  -- 업체별 제출 여부 (LEFT JOIN)
		  FROM SUMMARY_DATA S
		  LEFT JOIN TQHB_RISK_VNDR V
		    ON S.SIT_CD   = V.SIT_CD
		   AND S.PLN_YM   = V.PLN_YM
		   AND S.PLN_DGR  = V.PLN_DGR
		   AND S.CUST_CD  = V.CUST_CD
		   AND S.VNDR_SEQ = V.VNDR_SEQ
		 ORDER BY S.CUST_CD
		        , S.VNDR_SEQ
		        , S.CTP_CD
		        , S.UNT_CD
		        , S.CHK_ITM_CD
		        , S.DISS_SHP
		        , S.ROW_DIV
		        , S.APRS_NAMSEQ
    
        ;

    END IF;


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
         WHEN OTHERS THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);

END PQHA_RISK_CHK_Q;
/

-- PQHA_RISK_CHK_S (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_RISK_CHK_S" (
    p_WRK_TP                VARCHAR2 :='U'                                      -- UPDATE FLAG( I: ISNERT, U:UPDATE, D:DELTE)
,   p_WRK_ID                VARCHAR2                                            -- 사용자 ID
,   p_WRK_IP                VARCHAR2                                            -- 사용자 IP
,   p_SIT_CD                TQHA_RISK_CHK.SIT_CD                %TYPE           -- 현장코드
,   p_PLN_YM                TQHA_RISK_CHK.PLN_YM                %TYPE           -- 계획년월
,   p_PLN_DGR               TQHA_RISK_CHK.PLN_DGR               %TYPE           -- 차수구분코드(QS005) 1 1차,2 2차
,   p_CUST_CD               TQHA_RISK_CHK.CUST_CD               %TYPE           -- 협력업체코드
,   p_VNDR_SEQ              TQHA_RISK_CHK.VNDR_SEQ              %TYPE           -- 업체순번
,   p_CTP_CD                TQHA_RISK_CHK.CTP_CD                %TYPE           -- 공종코드
,   p_UNT_CD                TQHA_RISK_CHK.UNT_CD                %TYPE           -- 단위코드
,   p_CHK_ITM_CD            TQHA_RISK_CHK.CHK_ITM_CD            %TYPE           -- 점검항목코드
,   p_CHK_ITM_NM            TQHA_RISK_CHK.CHK_ITM_NM            %TYPE           -- 점검항목명 
,   p_CHK_LOC               TQHA_RISK_CHK.CHK_LOC               %TYPE           -- 점점위치
,   p_DISS_SHP              TQHA_RISK_CHK.DISS_SHP              %TYPE           -- 재해형태(QS036)
,   p_RISK_FREQ             TQHA_RISK_CHK.RISK_FREQ             %TYPE           -- 빈도레벨(QS003) 
,   p_RISK_APRV             TQHA_RISK_CHK.RISK_APRV             %TYPE           -- 강도레벨(QS004) 
,   p_RISK_CRIT             TQHA_RISK_CHK.RISK_CRIT             %TYPE           -- 위험성레벨(QS063) 
,   p_RISK_GRD              TQHA_RISK_CHK.RISK_GRD              %TYPE           -- 위험등급(QS024) 
,   p_PRRT_REG              TQHA_RISK_CHK.PRRT_REG              %TYPE           -- 중점등록(QS002) O, X 
,   p_RISK_FREQ2            TQHA_RISK_CHK.RISK_FREQ             %TYPE           -- 빈도레벨(QS003) 
,   p_RISK_APRV2            TQHA_RISK_CHK.RISK_APRV             %TYPE           -- 강도레벨(QS004) 
,   p_RISK_CRIT2            TQHA_RISK_CHK.RISK_CRIT             %TYPE           -- 위험성레벨(QS063) 
,   p_RISK_GRD2             TQHA_RISK_CHK.RISK_GRD              %TYPE           -- 위험등급(QS024) 
,   p_RISK_FREQ3            TQHA_RISK_CHK.RISK_FREQ             %TYPE           -- 빈도레벨(QS003) 
,   p_RISK_APRV3            TQHA_RISK_CHK.RISK_APRV             %TYPE           -- 강도레벨(QS004) 
,   p_RISK_CRIT3            TQHA_RISK_CHK.RISK_CRIT             %TYPE           -- 위험성레벨(QS063) 
,   p_RISK_GRD3             TQHA_RISK_CHK.RISK_GRD              %TYPE           -- 위험등급(QS024) 
,   p_RISK_FREQ4            TQHA_RISK_CHK.RISK_FREQ             %TYPE           -- 빈도레벨(QS003) 
,   p_RISK_APRV4            TQHA_RISK_CHK.RISK_APRV             %TYPE           -- 강도레벨(QS004) 
,   p_RISK_CRIT4            TQHA_RISK_CHK.RISK_CRIT             %TYPE           -- 위험성레벨(QS063) 
,   p_RISK_GRD4             TQHA_RISK_CHK.RISK_GRD              %TYPE           -- 위험등급(QS024) 
,   p_RISK_FREQ5            TQHA_RISK_CHK.RISK_FREQ             %TYPE           -- 빈도레벨(QS003) 
,   p_RISK_APRV5            TQHA_RISK_CHK.RISK_APRV             %TYPE           -- 강도레벨(QS004) 
,   p_RISK_CRIT5            TQHA_RISK_CHK.RISK_CRIT             %TYPE           -- 위험성레벨(QS063) 
,   p_RISK_GRD5             TQHA_RISK_CHK.RISK_GRD              %TYPE           -- 위험등급(QS024) 
,   p_RISK_FREQ6            TQHA_RISK_CHK.RISK_FREQ             %TYPE           -- 빈도레벨(QS003) 
,   p_RISK_APRV6            TQHA_RISK_CHK.RISK_APRV             %TYPE           -- 강도레벨(QS004) 
,   p_RISK_CRIT6            TQHA_RISK_CHK.RISK_CRIT             %TYPE           -- 위험성레벨(QS063) 
,   p_RISK_GRD6             TQHA_RISK_CHK.RISK_GRD              %TYPE           -- 위험등급(QS024)
,   p_MNG_SUPR              TQHA_RISK_CHK.MNG_SUPR              %TYPE           -- 관리감독자명
,   p_MGR_OPIN              TQHA_RISK_CHK.MGR_OPIN              %TYPE           -- 관리자의견
,   p_SAFT_MGR              TQHA_RISK_CHK.SAFT_MGR              %TYPE           -- 안전관리자명
,   p_SAFT_OPIN             TQHA_RISK_CHK.SAFT_OPIN             %TYPE           -- 안전의견
,   p_SITE_OMGR             TQHA_RISK_CHK.SITE_OMGR             %TYPE           -- 현장소장명
,   p_SITE_OPIN             TQHA_RISK_CHK.SITE_OPIN             %TYPE           -- 현장소장의견
,   p_IMPRV_CPLN            TQHA_RISK_CHK.IMPRV_CPLN            %TYPE           -- 개선대책
,   p_WRK_PSNNO             TQHA_RISK_CHK.WRK_PSNNO             %TYPE           -- 작업인원
,   p_MA_PSN                TQHA_RISK_CHK.MA_PSN                %TYPE           -- 조치자(업체)
,   p_MA_CNFR               TQHA_RISK_CHK.MA_CNFR               %TYPE           -- 확인자
,   p_WRK_STR_DT            TQHA_RISK_CHK.WRK_STR_DT            %TYPE           -- 작업시작일자
,   p_WRK_END_DT            TQHA_RISK_CHK.WRK_END_DT            %TYPE           -- 작업종료일자
,   p_IMPRV_STR_DT          TQHA_RISK_CHK.IMPRV_STR_DT          %TYPE           -- 개선시작일자
,   p_IMPRV_END_DT          TQHA_RISK_CHK.IMPRV_END_DT          %TYPE           -- 개선종료일자
,   p_VNDR_WRK_NM           TQHA_RISK_CHK.VNDR_WRK_NM           %TYPE           -- 근로자대표명
,   p_VNDR_WRK_OPIN         TQHA_RISK_CHK.VNDR_WRK_OPIN         %TYPE           -- 근로자대표의견
)
IS
    /**************************************************************************************************************************
      Purpose :

      REVISIONS
      Ver      Date               Author                  Description
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2021/11/22 16:44:41                         최초생성

    **************************************************************************************************************************/


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR2(200);            -- ERROR Message
    USER_EXCEPTION EXCEPTION;

    v_CNT           NUMBER;


BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 필수입력 필드  Check  ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_SIT_CD IS NULL)  THEN
        ERR_MSG := '현장코드는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_PLN_YM IS NULL)  THEN
        ERR_MSG := '계획년월는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_PLN_DGR IS NULL)  THEN
        ERR_MSG := '차수구분코드(QS005) 1 1차,2 2차는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_CUST_CD IS NULL)  THEN
        ERR_MSG := '협력업체코드는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_VNDR_SEQ IS NULL)  THEN
        ERR_MSG := '업체순번는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_CTP_CD IS NULL)  THEN
        ERR_MSG := '공종코드는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_UNT_CD IS NULL)  THEN
        ERR_MSG := '단위코드는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_CHK_ITM_CD IS NULL)  THEN
        ERR_MSG := '점검항목코드는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Process 선행조건 Check ]
    ---------------------------------------------------------------------------------------------------------------------------



    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Business Process ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_WRK_TP ='D') THEN

        DELETE
          FROM TQHA_RISK_CHK
         WHERE SIT_CD           = p_SIT_CD          -- 현장코드
           AND PLN_YM           = p_PLN_YM          -- 계획년월
           AND PLN_DGR          = p_PLN_DGR         -- 차수구분코드(QS005) 1 1차,2 2차
           AND CUST_CD          = p_CUST_CD         -- 협력업체코드
           AND VNDR_SEQ         = p_VNDR_SEQ        -- 업체순번
           AND CTP_CD           = p_CTP_CD          -- 공종코드
           AND UNT_CD           = p_UNT_CD          -- 단위코드
           AND CHK_ITM_CD       = p_CHK_ITM_CD      -- 점검항목코드
        ;

    ---------------------------------------------------------------------------------
    ELSIF (p_WRK_TP ='U') THEN

        UPDATE TQHA_RISK_CHK
           SET DISS_SHP             = p_DISS_SHP            -- 재해형태(QS036)
             , RISK_FREQ            = p_RISK_FREQ           -- 빈도레벨(QS003) 
             , RISK_APRV            = p_RISK_APRV           -- 강도레벨(QS004) 
             , RISK_CRIT            = p_RISK_CRIT           -- 위험성레벨(QS063)
             , RISK_GRD             = p_RISK_GRD            -- 위험등급(QS024) 
             , PRRT_REG             = p_PRRT_REG            -- 중점등록(QS002) O, X             
             , RISK_FREQ2           = p_RISK_FREQ2           -- 빈도레벨(QS003) 
             , RISK_APRV2           = p_RISK_APRV2           -- 강도레벨(QS004) 
             , RISK_CRIT2           = p_RISK_CRIT2           -- 위험성레벨(QS063)
             , RISK_GRD2            = p_RISK_GRD2            -- 위험등급(QS024)              
             , RISK_FREQ3           = p_RISK_FREQ3           -- 빈도레벨(QS003) 
             , RISK_APRV3           = p_RISK_APRV3           -- 강도레벨(QS004) 
             , RISK_CRIT3           = p_RISK_CRIT3           -- 위험성레벨(QS063)
             , RISK_GRD3            = p_RISK_GRD3            -- 위험등급(QS024)              
             , RISK_FREQ4           = p_RISK_FREQ4           -- 빈도레벨(QS003) 
             , RISK_APRV4           = p_RISK_APRV4           -- 강도레벨(QS004) 
             , RISK_CRIT4           = p_RISK_CRIT4           -- 위험성레벨(QS063)
             , RISK_GRD4            = p_RISK_GRD4            -- 위험등급(QS024)              
             , RISK_FREQ5           = p_RISK_FREQ5           -- 빈도레벨(QS003) 
             , RISK_APRV5           = p_RISK_APRV5           -- 강도레벨(QS004) 
             , RISK_CRIT5           = p_RISK_CRIT5           -- 위험성레벨(QS063)
             , RISK_GRD5            = p_RISK_GRD5            -- 위험등급(QS024)              
             , RISK_FREQ6           = p_RISK_FREQ6           -- 빈도레벨(QS003) 
             , RISK_APRV6           = p_RISK_APRV6           -- 강도레벨(QS004) 
             , RISK_CRIT6           = p_RISK_CRIT6           -- 위험성레벨(QS063)
             , RISK_GRD6            = p_RISK_GRD6            -- 위험등급(QS024)             
             , MNG_SUPR            = p_MNG_SUPR            -- 관리감독자명
             , MGR_OPIN            = p_MGR_OPIN            -- 관리자의견
             , SAFT_MGR            = p_SAFT_MGR            -- 안전관리자명
             , SAFT_OPIN            = p_SAFT_OPIN            -- 안전의견
             , SITE_OMGR            = p_SITE_OMGR            -- 현장소장명
             , SITE_OPIN            = p_SITE_OPIN            -- 현장소장의견             
             , IMPRV_CPLN           = p_IMPRV_CPLN          -- 개선대책
             , WRK_PSNNO            = p_WRK_PSNNO           -- 작업인원
             , MA_PSN               = p_MA_PSN              -- 조치자(업체)
             , MA_CNFR              = p_MA_CNFR             -- 확인자
             , WRK_STR_DT           = p_WRK_STR_DT          -- 작업시작일자
             , WRK_END_DT           = p_WRK_END_DT          -- 작업종료일자
             , IMPRV_STR_DT         = p_IMPRV_STR_DT        -- 개선시작일자
             , IMPRV_END_DT         = p_IMPRV_END_DT        -- 개선종료일자
             , CHK_ITM_NM           = p_CHK_ITM_NM          -- 점검항목명
             , CHK_LOC              = p_CHK_LOC             -- 점검위치
             , VNDR_WRK_NM			= (SELECT VNDR_WRK_NM FROM TQHA_VNDR WHERE SIT_CD = p_SIT_CD AND CUST_CD = p_CUST_CD AND VNDR_SEQ = p_VNDR_SEQ)
             , VNDR_WRK_OPIN		= p_VNDR_WRK_OPIN
             , UPD_ID               = p_WRK_ID              -- 수정ID
             , UPD_DTM              = SYSDATE()             -- 수정일시
             , UPD_IP               = p_WRK_IP              -- 수정IP
         WHERE SIT_CD               = p_SIT_CD              -- 현장코드
           AND PLN_YM               = p_PLN_YM              -- 계획년월
           AND PLN_DGR              = p_PLN_DGR             -- 차수구분코드(QS005) 1 1차,2 2차
           AND CUST_CD              = p_CUST_CD             -- 협력업체코드
           AND VNDR_SEQ             = p_VNDR_SEQ            -- 업체순번
           AND CTP_CD               = p_CTP_CD              -- 공종코드
           AND UNT_CD               = p_UNT_CD              -- 단위코드
           AND CHK_ITM_CD           = p_CHK_ITM_CD          -- 점검항목코드
        ;

    ---------------------------------------------------------------------------------
    ELSE

        SELECT COUNT(1)
          INTO v_CNT
          FROM TQHA_RISK_CHK
         WHERE SIT_CD       = p_SIT_CD
           AND PLN_YM       = p_PLN_YM
           AND PLN_DGR      = p_PLN_DGR
           AND CUST_CD      = p_CUST_CD
           AND VNDR_SEQ     = p_VNDR_SEQ
           AND CTP_CD       = p_CTP_CD
           AND UNT_CD       = p_UNT_CD
           AND CHK_ITM_CD   = p_CHK_ITM_CD
        ;

        IF v_CNT > 0 THEN
            ERR_MSG := '중복되는 점검항목이 존재합니다.';
            RAISE USER_EXCEPTION;
        END IF;

        INSERT 
          INTO TQHA_RISK_CHK
             ( SIT_CD                   -- 현장코드
             , PLN_YM                   -- 계획년월
             , PLN_DGR                  -- 차수구분코드(QS005)
             , CUST_CD                  -- 협력업체코드
             , VNDR_SEQ                 -- 업체순번
             , CTP_CD                   -- 공종코드
             , UNT_CD                   -- 단위코드
             , CHK_ITM_CD               -- 점검항목코드
             , DISS_SHP                 -- 재해형태(QS036)
             , RISK_FREQ                -- 빈도레벨(QS003) 
             , RISK_APRV                -- 강도레벨(QS004) 
             , RISK_CRIT                -- 위험성레벨(QS063)
             , RISK_GRD                 -- 위험등급(QS024) 
             , PRRT_REG                 -- 중점등록(QS002) O, X             
             , RISK_FREQ2                -- 빈도레벨(QS003) 
             , RISK_APRV2                -- 강도레벨(QS004) 
             , RISK_CRIT2                -- 위험성레벨(QS063)
             , RISK_GRD2                 -- 위험등급(QS024)              
             , RISK_FREQ3                -- 빈도레벨(QS003) 
             , RISK_APRV3                -- 강도레벨(QS004) 
             , RISK_CRIT3                -- 위험성레벨(QS063)
             , RISK_GRD3                 -- 위험등급(QS024)              
             , RISK_FREQ4                -- 빈도레벨(QS003) 
             , RISK_APRV4                -- 강도레벨(QS004) 
             , RISK_CRIT4                -- 위험성레벨(QS063)
             , RISK_GRD4                 -- 위험등급(QS024)              
             , RISK_FREQ5                -- 빈도레벨(QS003) 
             , RISK_APRV5                -- 강도레벨(QS004) 
             , RISK_CRIT5                -- 위험성레벨(QS063)
             , RISK_GRD5                 -- 위험등급(QS024)              
             , RISK_FREQ6                -- 빈도레벨(QS003) 
             , RISK_APRV6                -- 강도레벨(QS004) 
             , RISK_CRIT6                -- 위험성레벨(QS063)
             , RISK_GRD6                 -- 위험등급(QS024)
             , IMPRV_CPLN               -- 개선대책             
             , MNG_SUPR                   -- 관리감독자명
             , MGR_OPIN                   -- 관리자의견
             , SAFT_MGR                   -- 안전관리자명
             , SAFT_OPIN                    -- 안전의견
             , SITE_OMGR                    -- 현장소장명
             , SITE_OPIN                    -- 현장소장의견  
             , WRK_PSNNO                -- 작업인원
             , MA_PSN                   -- 조치자(업체)
             , MA_CNFR                  -- 확인자
             , WRK_STR_DT               -- 작업시작일자
             , WRK_END_DT               -- 작업종료일자
             , IMPRV_STR_DT             -- 개선시작일자
             , IMPRV_END_DT             -- 개선종료일자
             , CHK_ITM_NM               -- 점검항목명
             , CHK_LOC                  -- 점검위치
             , IPT_ID                   -- 입력ID
             , IPT_DTM                  -- 입력일시
             , IPT_IP                   -- 입력IP
             , UPD_ID                   -- 수정ID
             , UPD_DTM                  -- 수정일시
             , UPD_IP                   -- 수정IP
             )
        VALUES 
             ( p_SIT_CD                 -- 현장코드
             , p_PLN_YM                 -- 계획년월
             , p_PLN_DGR                -- 차수구분코드(QS005)
             , p_CUST_CD                -- 협력업체코드
             , p_VNDR_SEQ               -- 업체순번
             , p_CTP_CD                 -- 공종코드
             , p_UNT_CD                 -- 단위코드
             , p_CHK_ITM_CD             -- 점검항목코드
             , p_DISS_SHP               -- 재해형태(QS036)
             , p_RISK_FREQ              -- 빈도레벨(QS003) 
             , p_RISK_APRV              -- 강도레벨(QS004) 
             , p_RISK_CRIT              -- 위험성레벨(QS063)
             , p_RISK_GRD               -- 위험등급(QS024)        
             , p_PRRT_REG               -- 중점등록(QS002) O, X     
             , p_RISK_FREQ2              -- 빈도레벨(QS003) 
             , p_RISK_APRV2              -- 강도레벨(QS004) 
             , p_RISK_CRIT2              -- 위험성레벨(QS063)
             , p_RISK_GRD2               -- 위험등급(QS024)              
             , p_RISK_FREQ3              -- 빈도레벨(QS003) 
             , p_RISK_APRV3              -- 강도레벨(QS004) 
             , p_RISK_CRIT3              -- 위험성레벨(QS063)
             , p_RISK_GRD3               -- 위험등급(QS024)              
             , p_RISK_FREQ4              -- 빈도레벨(QS003) 
             , p_RISK_APRV4              -- 강도레벨(QS004) 
             , p_RISK_CRIT4              -- 위험성레벨(QS063)
             , p_RISK_GRD4               -- 위험등급(QS024)              
             , p_RISK_FREQ5              -- 빈도레벨(QS003) 
             , p_RISK_APRV5              -- 강도레벨(QS004) 
             , p_RISK_CRIT5              -- 위험성레벨(QS063)
             , p_RISK_GRD5               -- 위험등급(QS024)              
             , p_RISK_FREQ6              -- 빈도레벨(QS003) 
             , p_RISK_APRV6              -- 강도레벨(QS004) 
             , p_RISK_CRIT6              -- 위험성레벨(QS063)
             , p_RISK_GRD6               -- 위험등급(QS024)
             , p_IMPRV_CPLN             -- 개선대책 
             , p_MNG_SUPR                -- 관리감독자명
             , p_MGR_OPIN                -- 관리자의견
             , p_SAFT_MGR                -- 안전관리자명
             , p_SAFT_OPIN                -- 안전의견
             , p_SITE_OMGR                -- 현장소장명
             , p_SITE_OPIN                -- 현장소장의견
             , p_WRK_PSNNO              -- 작업인원
             , p_MA_PSN                 -- 조치자(업체)
             , p_MA_CNFR                -- 확인자
             , p_WRK_STR_DT             -- 작업시작일자
             , p_WRK_END_DT             -- 작업종료일자
             , p_IMPRV_STR_DT           -- 개선시작일자
             , p_IMPRV_END_DT           -- 개선종료일자
             , p_CHK_ITM_NM             -- 점검항목명
             , p_CHK_LOC                -- 점검위치
             , p_WRK_ID                 -- 입력ID
             , SYSDATE()                -- 입력일시
             , p_WRK_IP                 -- 입력IP
             , p_WRK_ID                 -- 수정ID
             , SYSDATE()                -- 수정일시
             , p_WRK_IP                 -- 수정IP
             )
        ;

    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 5. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);
END ;
/

-- PQHA_RISK_DGR_AREC_CTS_S (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_RISK_DGR_AREC_CTS_S" (
    p_WRK_TP            VARCHAR2 :='U'                          -- UPDATE FLAG( I: ISNERT, U:UPDATE, D:DELTE)
,   p_WRK_ID            VARCHAR2                                -- 사용자 ID 
,   p_WRK_IP            VARCHAR2                                -- 사용자 IP 
,   p_SIT_CD            TQHA_RISK_DGR.SIT_CD%TYPE               -- 현장코드
,   p_PLN_YM            TQHA_RISK_DGR.PLN_YM%TYPE               -- 계획년월
,   p_PLN_DGR           TQHA_RISK_DGR.PLN_DGR%TYPE              -- 차수구분코드(QS005) 1 1차,2 2차
,   p_AREC_CTS          VARCHAR2                                -- 회의내용
,   p_AREC_ATFL_GRP     VARCHAR2                                -- 회의첨부파일
,   p_PHOTO_DESC_1      VARCHAR2                                -- 회의첨부사진1
,   p_PHOTO_GRP1        VARCHAR2                                -- 사진설명1
,   p_PHOTO_DESC_2      VARCHAR2                                -- 회의첨부사진2
,   p_PHOTO_GRP2        VARCHAR2                                -- 사진설명2
)
IS 
    /**************************************************************************************************************************
      Purpose : 

      REVISIONS
      Ver      Date               Author                  Description 
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2021/10/27 14:12:51                         최초생성

    **************************************************************************************************************************/

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR2(200);            -- ERROR Message
    USER_EXCEPTION EXCEPTION;

    v_cnt  INTEGER;                             -- 위험성 평가 일정 하위데이타 존재 여부

BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 필수입력 필드  Check  ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_SIT_CD IS NULL)  THEN
        ERR_MSG := '현장코드는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_PLN_YM IS NULL  AND p_WRK_TP <> 'I')  THEN
        ERR_MSG := '계획년월는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_PLN_DGR IS NULL)  THEN
        ERR_MSG := '차수구분코드는(은) 필수 입력사항 입니다.'; 
        RAISE USER_EXCEPTION;
    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Process 선행조건 Check ]
    ---------------------------------------------------------------------------------------------------------------------------



    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Business Process ]
    ---------------------------------------------------------------------------------------------------------------------------

    ----------------------------------------------------------------------------------------------------
    -- 폼 저장 : 위험성평가 회의록 작성 - 회의내용 
    IF (p_WRK_TP ='U') THEN

        UPDATE TQHA_RISK_DGR
           SET AREC_CTS         = p_AREC_CTS            -- 회의내용
             , AREC_ATFL_GRP    = p_AREC_ATFL_GRP       -- 회의첨부파일
             , PHOTO_DESC_1     = p_PHOTO_DESC_1        -- 회의첨부사진1
             , PHOTO_GRP1       = p_PHOTO_GRP1          -- 사진설명1
             , PHOTO_DESC_2     = p_PHOTO_DESC_2        -- 회의첨부사진2
             , PHOTO_GRP2       = p_PHOTO_GRP2          -- 사진설명2
             , UPD_ID           = p_WRK_ID
             , UPD_DTM          = SYSDATE
         WHERE SIT_CD           = p_SIT_CD
           AND PLN_YM           = p_PLN_YM
           AND PLN_DGR          = p_PLN_DGR
        ;

    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 5. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN 
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);
END ;
/

-- PQHA_RISK_DGR_MEET_S (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_RISK_DGR_MEET_S" (
    p_WRK_TP            VARCHAR2 :='U'      -- UPDATE FLAG( I: ISNERT, U:UPDATE, D:DELTE)
,   p_WRK_ID            VARCHAR2            -- 사용자 ID 
,   p_WRK_IP            VARCHAR2            -- 사용자 IP 
,   p_SIT_CD            VARCHAR2            -- 현장코드
,   p_PLN_YM            VARCHAR2            -- 계획년월
,   p_PLN_DGR           NUMBER              -- 계획차수
,   p_CONF_DT           VARCHAR2            -- 회의일자
,   p_CONF_PLC          VARCHAR2            -- 회의장소
,   p_AM_NOTICE         VARCHAR2            -- 공지사항
,   p_AREC_CTS          VARCHAR2            -- 회의내용
,   p_AREC_ATFL_GRP     VARCHAR2            -- 회의첨부파일
,   p_PHOTO_DESC_1      VARCHAR2            -- 회의첨부사진1
,   p_PHOTO_GRP1        VARCHAR2            -- 사진설명1
,   p_PHOTO_DESC_2      VARCHAR2            -- 회의첨부사진2
,   p_PHOTO_GRP2        VARCHAR2            -- 사진설명2
)
IS 
    /**************************************************************************************************************************
      Purpose : 

      REVISIONS
      Ver      Date               Author                  Description 
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2026/02/12                                   최초생성

    **************************************************************************************************************************/

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR2(200);            -- ERROR Message
    USER_EXCEPTION EXCEPTION;

    v_APRV_STATS        VARCHAR2(20);
    v_APRV_STATS_NM     VARCHAR2(50);

BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 필수입력 필드  Check  ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_SIT_CD IS NULL)  THEN
        ERR_MSG := '현장코드는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_PLN_YM IS NULL)  THEN
        ERR_MSG := '계획년월은 필수 입력사항 입니다.'; 
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_PLN_DGR IS NULL)  THEN
        ERR_MSG := '계획차수는 필수 입력사항 입니다.'; 
        RAISE USER_EXCEPTION;
    END IF;

    ---------------------------------------------------------------------
    -- 결재상태 체크
    /*
    SELECT MAX(T2.APRV_STATS)
         , MAX(T3.CD_NM )
      INTO v_APRV_STATS
         , v_APRV_STATS_NM
      FROM TQHA_RISK_DGR        T1
      LEFT JOIN TQHA_APRV       T2 ON T1.SIT_CD     = T2.SIT_CD
                                  AND T1.APRV_NO    = T2.APRV_NO
      LEFT JOIN TCOA_COMCODE    T3 ON T2.APRV_STATS = T3.COM_CD 
                                  AND T3.HRNK_CD    = 'QS031'
     WHERE T1.SIT_CD    = p_SIT_CD
       AND T1.PLN_YM    = p_PLN_YM
       AND T1.PLN_DGR   = p_PLN_DGR
    ;

    IF v_APRV_STATS IN ('2', '4') THEN
        ERR_MSG := '결재상태 [' || v_APRV_STATS_NM || ']인 데이터는 수정 불가합니다.';
        RAISE USER_EXCEPTION;
    END IF;
*/
    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Process 선행조건 Check ]
    ---------------------------------------------------------------------------------------------------------------------------



    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Business Process ]
    ---------------------------------------------------------------------------------------------------------------------------

    ----------------------------------------------------------------------------------------------------
    -- 열람이력 업데이트.
    IF (p_WRK_TP ='U') THEN

        UPDATE TQHB_RISK_DGR
           SET CONF_DT          = p_CONF_DT         -- 회의일자
             , CONF_PLC         = p_CONF_PLC        -- 회의장소
             , AM_NOTICE        = p_AM_NOTICE       -- 공지사항
             , AREC_CTS         = p_AREC_CTS        -- 회의내용
             , AREC_ATFL_GRP    = p_AREC_ATFL_GRP   -- 회의첨부파일
             , PHOTO_DESC_1     = p_PHOTO_DESC_1    -- 회의첨부사진1
             , PHOTO_GRP1       = p_PHOTO_GRP1      -- 사진설명1
             , PHOTO_DESC_2     = p_PHOTO_DESC_2    -- 회의첨부사진2
             , PHOTO_GRP2       = p_PHOTO_GRP2      -- 사진설명2
         WHERE SIT_CD           = p_SIT_CD
           AND PLN_YM           = p_PLN_YM
           AND PLN_DGR          = p_PLN_DGR
        ;

    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 5. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN 
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);
END ;
/

-- PQHA_RISK_DGR_Q (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_RISK_DGR_Q" (  
    p_WRK_TP        IN VARCHAR2 DEFAULT 'Q'         -- FLAG(Q: 조회)
,   p_SIT_CD        IN VARCHAR2                     -- 현장코드
,   RTN_CURSOR      OUT SYS_REFCURSOR
)
IS
    /**************************************************************************************************************************
      Purpose : [위험성평가일정 조회] 

      REVISIONS
      Ver      Date               Author                  Description
      -------  -----------------  ----------------------  ---------------------------------------------------------------------
      1.0      2023/12/04                                 최초생성  

    **************************************************************************************************************************/

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE  NUMBER :=-20009; -- ERROR 코드
    ERR_MSG   VARCHAR(200);    -- ERROR Message
    USER_EXCEPTION EXCEPTION;

BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 수행전 Check Logic ]
    ---------------------------------------------------------------------------------------------------------------------------

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Logic 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------

    IF p_WRK_TP = 'Q' THEN

        OPEN RTN_CURSOR FOR
        SELECT A.SIT_CD                                         -- 현장코드
             , A.PLN_YM                                         -- 계획년월
             , A.PLN_DGR                                        -- 계획차수
             , ( SELECT CD_NM FROM TCOA_COMCODE WHERE COM_CD = A.PLN_DGR AND HRNK_CD = 'QS005' ) AS PLN_DGR_NM -- 계획차수명
             , A.APRS_STR_DT                                    -- 평가시작일자
             , A.APRS_END_DT                                    -- 평가종료일자
             , A.VNDR_CMPL_DT                                   -- 업체작성완료일자
             , ( SELECT CASE MIN(NVL(SITE_APRV_STATS,0)) 
                             WHEN '0' THEN ''
                             WHEN '1' THEN MAX(SITE_APRV_DT) 
                              END FIN_DT
                   FROM TQHA_RISK_VNDR 
                  WHERE SIT_CD      = A.SIT_CD      -- 현장코드 변수
                    AND PLN_YM      = A.PLN_YM      -- 변수 ( 년월)
                    AND PLN_DGR     = A.PLN_DGR     -- 변수 ( 차수)
                    AND OBJ_YN      = '1' )     AS FINAL_DT     -- 최종승인일자
             , A.CONF_SCH_DT                                    -- 회의예정일자
          FROM TQHA_RISK_DGR A
         WHERE A.SIT_CD = p_SIT_CD
         ORDER BY A.PLN_YM DESC, A.PLN_DGR DESC
        ;

    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
         WHEN OTHERS THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);
END PQHA_RISK_DGR_Q;
/

-- PQHA_RISK_DGR_S (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_RISK_DGR_S" (
    p_WRK_TP            VARCHAR2 :='U'                          -- UPDATE FLAG( I: ISNERT, U:UPDATE, D:DELTE)
,   p_WRK_ID            VARCHAR2                                -- 사용자 ID 
,   p_WRK_IP            VARCHAR2                                -- 사용자 IP 
,   p_SIT_CD            TQHA_RISK_DGR.SIT_CD%TYPE               -- 현장코드
,   p_PLN_YM            TQHA_RISK_DGR.PLN_YM%TYPE               -- 계획년월
,   p_PLN_DGR           TQHA_RISK_DGR.PLN_DGR%TYPE              -- 차수구분코드(QS005) 1 1차,2 2차
,   p_APRS_STR_DT       TQHA_RISK_DGR.APRS_STR_DT%TYPE          -- 평가시작일자
,   p_APRS_END_DT       TQHA_RISK_DGR.APRS_END_DT%TYPE          -- 평가종료일자
,   p_VNDR_CMPL_DT      TQHA_RISK_DGR.VNDR_CMPL_DT%TYPE         -- 업체작성완료일자
,   p_CONF_SCH_DT       TQHA_RISK_DGR.CONF_SCH_DT%TYPE          -- 회의예정일자 
)
IS 
    /**************************************************************************************************************************
      Purpose : 

      REVISIONS 
      Ver      Date               Author                  Description 
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2021/10/27 14:12:51                         최초생성

    **************************************************************************************************************************/

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;         -- ERROR 코드
    ERR_MSG        VARCHAR2(200);           -- ERROR Message
    USER_EXCEPTION EXCEPTION;

    v_cnt               INTEGER;            -- 위험성 평가 일정 하위데이타 존재 여부

    v_APRV_STATS        VARCHAR2(20);
    v_APRV_STATS_NM     VARCHAR2(50);

BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 필수입력 필드  Check  ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_SIT_CD IS NULL)  THEN
        ERR_MSG := '현장코드는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_PLN_YM IS NULL  AND p_WRK_TP <> 'I')  THEN
        ERR_MSG := '계획년월는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_PLN_DGR IS NULL)  THEN
        ERR_MSG := '차수구분코드는(은) 필수 입력사항 입니다.'; 
        RAISE USER_EXCEPTION;
    END IF;

    ---------------------------------------------------------------------
    -- 결재상태 체크
    SELECT MAX(T2.APRV_STATS)
         , MAX(T3.CD_NM )
      INTO v_APRV_STATS
         , v_APRV_STATS_NM
      FROM TQHA_RISK_DGR        T1
      LEFT JOIN TQHA_APRV       T2 ON T1.SIT_CD     = T2.SIT_CD
                                  AND T1.APRV_NO    = T2.APRV_NO
      LEFT JOIN TCOA_COMCODE    T3 ON T2.APRV_STATS = T3.COM_CD 
                                  AND T3.HRNK_CD    = 'QS031'
     WHERE T1.SIT_CD    = p_SIT_CD
       AND T1.PLN_YM    = p_PLN_YM
       AND T1.PLN_DGR   = p_PLN_DGR
    ;

    IF v_APRV_STATS IN ('2', '4') THEN
        ERR_MSG := '결재상태 [' || v_APRV_STATS_NM || ']인 데이터는 수정 불가합니다.';
        RAISE USER_EXCEPTION;
    END IF;

    ---------------------------------------------------------------------
    --  위험성 평가 일정 하위데이타 존재 여부
    IF p_WRK_TP = 'D' THEN

       SELECT NVL(COUNT(CUST_CD),0) 
         INTO v_cnt
         FROM TQHA_RISK_VNDR
        WHERE SIT_CD = p_SIT_CD
          AND PLN_YM = p_PLN_YM
          AND PLN_DGR = p_PLN_DGR ;

         -- 평가 대상업체 졵재여부 Validation
        IF v_cnt > 0 THEN
           ERR_MSG := '계획년월 "' || p_PLN_YM || '" 차수 "' || p_PLN_DGR || '"은(는) 하위 데이타가 존재하여 삭제할 수 없습니다. ';
           RAISE USER_EXCEPTION;
        END IF;
    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Process 선행조건 Check ]
    ---------------------------------------------------------------------------------------------------------------------------



    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Business Process ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_WRK_TP ='D') THEN

        DELETE 
          FROM TQHA_RISK_DGR
         WHERE SIT_CD   = p_SIT_CD          -- 현장코드
           AND PLN_YM   = p_PLN_YM          -- 계획년월
           AND PLN_DGR  = p_PLN_DGR         -- 차수구분코드(QS005) 1 1차,2 2차
        ;

    ----------------------------------------------------------------------------------------------------
    ELSIF (p_WRK_TP ='U') THEN

        UPDATE TQHA_RISK_DGR
           SET APRS_STR_DT      = p_APRS_STR_DT     -- 평가시작일자
             , APRS_END_DT      = p_APRS_END_DT     -- 평가종료일자
             , VNDR_CMPL_DT     = p_VNDR_CMPL_DT    -- 업체작성완료일자
             , CONF_SCH_DT      = p_CONF_SCH_DT     -- 회의예정일자
             , UPD_ID           = p_WRK_ID          -- 수정ID 
             , UPD_DTM          = SYSDATE()         -- 수정일시
             , UPD_IP           = p_WRK_IP          -- 수정IP
         WHERE SIT_CD           = p_SIT_CD          -- 현장코드
           AND PLN_YM           = p_PLN_YM          -- 계획년월
           AND PLN_DGR          = p_PLN_DGR         -- 차수구분코드(QS005) 1 1차,2 2차
        ;

    ----------------------------------------------------------------------------------------------------
    ELSE 

        INSERT 
          INTO TQHA_RISK_DGR
             ( SIT_CD               -- 현장코드
             , PLN_YM               -- 계획년월
             , PLN_DGR              -- 차수구분코드(QS005) 1 1차,2 2차
             , APRS_STR_DT          -- 평가시작일자
             , APRS_END_DT          -- 평가종료일자
             , VNDR_CMPL_DT         -- 업체작성완료일자
             , CONF_SCH_DT          -- 회의예정일자
             , IPT_ID               -- 입력ID
             , IPT_DTM              -- 입력일시
             , IPT_IP               -- 입력IP
             , UPD_ID               -- 수정ID
             , UPD_DTM              -- 수정일시
             , UPD_IP               -- 수정IP
             )
        VALUES 
             ( p_SIT_CD             -- 현장코드
             , P_PLN_YM             -- 계획년월
             , p_PLN_DGR            -- 차수구분코드(QS005) 1 1차,2 2차
             , p_APRS_STR_DT        -- 평가시작일자
             , p_APRS_END_DT        -- 평가종료일자
             , p_VNDR_CMPL_DT       -- 업체작성완료일자
             , p_CONF_SCH_DT        -- 회의예정일자
             , p_WRK_ID             -- 입력ID 
             , SYSDATE()            -- 입력일시
             , p_WRK_IP             -- 입력IP
             , p_WRK_ID             -- 수정ID
             , SYSDATE()            -- 수정일시
             , p_WRK_IP             -- 수정IP
             )
        ;

        -- 해당하는 협력업체
        MERGE 
          INTO TQHA_RISK_VNDR T
         USING (
                SELECT A.CUST_CD
                     , A.VNDR_SEQ
                  FROM TQHA_VNDR      A
                     , TQHA_RISK_VNDR B
                 WHERE A.SIT_CD = p_SIT_CD
                   AND ((TO_DATE(A.VNDR_STR_DT, 'YYYYMMDD') <= TO_DATE(p_APRS_STR_DT, 'YYYYMMDD') 
                         AND TO_DATE(A.VNDR_END_DT, 'YYYYMMDD') >= TO_DATE(p_APRS_END_DT, 'YYYYMMDD')) 
                          OR NVL(B.OBJ_YN, 0) = 1)
                   AND A.SIT_CD     = B.SIT_CD(+)
                   AND A.CUST_CD    = B.CUST_CD(+)
                   AND A.VNDR_SEQ   = B.VNDR_SEQ(+)
                   AND B.PLN_YM(+)  = p_PLN_YM
                   AND B.PLN_DGR(+) = p_PLN_DGR
               ) S
        ON (
                T.SIT_CD   = p_SIT_CD   
            AND T.PLN_YM   = p_PLN_YM   
            AND T.PLN_DGR  = p_PLN_DGR  
            AND T.CUST_CD  = S.CUST_CD  
            AND T.VNDR_SEQ = S.VNDR_SEQ
           )
        WHEN MATCHED THEN
            UPDATE 
               SET T.OBJ_YN     = '1'
                 , T.UPD_ID     = p_WRK_ID
                 , T.UPD_DTM    = SYSDATE
                 , T.UPD_IP     = p_WRK_IP
        WHEN NOT MATCHED THEN
            INSERT 
                 ( SIT_CD
                 , PLN_YM
                 , PLN_DGR
                 , CUST_CD
                 , VNDR_SEQ
                 , OBJ_YN
                 , VNDR_NOTI_YN
                 , IPT_ID
                 , IPT_DTM
                 , IPT_IP
                 , UPD_ID
                 , UPD_DTM
                 , UPD_IP
                 )
            VALUES 
                 ( p_SIT_CD
                 , p_PLN_YM
                 , p_PLN_DGR
                 , S.CUST_CD
                 , S.VNDR_SEQ
                 , '1'
                 , '0'
                 , p_WRK_ID
                 , SYSDATE
                 , p_WRK_IP
                 , p_WRK_ID
                 , SYSDATE
                 , p_WRK_IP
                 )
        ;

    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 5. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN 
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);

END ;
/

-- PQHA_RISK_ITM_LIST_OTHER_Q (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_RISK_ITM_LIST_OTHER_Q" (
    p_WRK_TP            IN VARCHAR2 DEFAULT 'Q'         -- FLAG
,   p_SIT_CD            IN VARCHAR2                     -- 현장코드
,   p_PLN_YM            IN VARCHAR2                     -- 계획연월
,   p_PLN_DGR           IN VARCHAR2                     -- 계획차수
,   p_CUST_CD           IN VARCHAR2                     -- 업체코드
,   p_VNDR_SEQ          IN VARCHAR2                     -- 업체순번
,   p_CTP_CD            IN VARCHAR2                     -- 공종코드
,   p_UNT_CD            IN VARCHAR2                     -- 단위코드
,   p_DIFF_SIT_CD       IN VARCHAR2                     -- 타현장코드
,   RTN_CURSOR          OUT SYS_REFCURSOR
)
IS
    /**************************************************************************************************************************
      Purpose : [위험성평가작성/검토] PROCEDRE 

      REVISIONS
      Ver      Date               Author                  Description
      -------  -----------------  ----------------------  ---------------------------------------------------------------------
      1.0      2026/02/09                                 최초생성

    **************************************************************************************************************************/

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE  NUMBER :=-20009; -- ERROR 코드
    ERR_MSG   VARCHAR(200);    -- ERROR Message
    USER_EXCEPTION EXCEPTION;

BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 수행전 Check Logic ]
    ---------------------------------------------------------------------------------------------------------------------------

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Logic 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------

    ---------------------------------------------------------------------------------------
    -- 
    IF p_WRK_TP = 'Q1' THEN

        -- 그리드 조회 : 위험성평가 승인관리 - 협력업체
        OPEN RTN_CURSOR FOR
        SELECT A.SIT_CD                   --현장코드
             , A.PLN_YM                   --계획년월 
             , A.PLN_DGR                  --계획차수
             , ( SELECT CD_NM FROM TCOA_COMCODE WHERE COM_CD = A.PLN_DGR AND HRNK_CD = 'QS005') AS PLN_DGR_NM  -- 계획차수명칭
             , A.CUST_CD                  --협력업체코드
             , A.VNDR_SEQ                 --협력업체차수
             , B.CUST_NM                  --협력업체명칭
             , A.SBM_YN                   --평가서제출여부
             , DECODE(NVL(A.SBM_YN,0), '1', '제출', '작성중') AS SBM_NM -- 제출여부명칭
             , A.SBM_DT                   --평가서제출일자
             , A.MNG_SUPR                 --관리감독자
             , ( SELECT USR_NM FROM TCOZ_USR_INFO WHERE USR_ID = A.MNG_SUPR ) AS MNG_SUPR_NM -- 관리감독자명
             , A.MNG_APRV_STATS           --관리감독자 승인상태(1승인, 2반려)
             , DECODE(NVL(A.SBM_YN,0), '1', DECODE(NVL(A.MNG_APRV_STATS,0), '1', '승인완료 ', DECODE(NVL(A.MNG_APRV_STATS,0), '2', '반려 ', '진행중')), '0', DECODE(NVL(A.MNG_APRV_STATS,0), '2', '반려 ', ''), '' ) AS MNG_APRV_STATS_NM -- 관리상태명칭                
             , A.MNG_APRV_DT              --관리감독자 승인일자
             , A.SAFT_MGR                 --안전관리자
             , ( SELECT USR_NM FROM TCOZ_USR_INFO WHERE USR_ID = A.SAFT_MGR ) AS SAFT_MGR_NM -- 안전관리자명
             , A.SAFT_APRV_STATS          --안전관리자 승인상태(1승인 2반려)
             , DECODE(NVL(A.MNG_APRV_STATS,0), '1', DECODE(NVL(A.SAFT_APRV_STATS,0), '1', '승인완료 ', DECODE(NVL(A.SAFT_APRV_STATS,0), '2', '반려 ', '진행중')), '0', DECODE(NVL(A.SAFT_APRV_STATS,0), '1','승인', '2', '반려 ', ''), '' ) AS SAFT_APRV_STATS_NM -- 안전상태명칭
             , A.SAFT_APRV_DT             --안전관리자 승인일자
             , A.SITE_OMGR                --현장소장
             , ( SELECT USR_NM FROM TCOZ_USR_INFO WHERE USR_ID = A.SITE_OMGR ) AS SITE_OMGR_NM -- 현장소장명
             , A.SITE_APRV_STATS          --현장소장 승인상태(1승인, 2반려)
             , DECODE(NVL(A.SAFT_APRV_STATS,0), '1', DECODE(NVL(A.SITE_APRV_STATS,0), '1', '승인완료 ', DECODE(NVL(A.SITE_APRV_STATS,0), '2', '반려 ', '진행중')), '0', DECODE(NVL(A.SITE_APRV_STATS,0), '2', '반려 ', ''), '' ) AS SITE_APRV_STATS_NM -- 소장상태명칭                
             , A.SITE_APRV_DT             --현장소장 승인일자
             , A.CUST_CD                  --협력업체코드
             , A.VNDR_WRK_NM
          FROM TQHA_RISK_VNDR A
             , VQSZ_TRADE B
         WHERE A.CUST_CD        = B.CUST_CD
           AND A.SIT_CD         = p_SIT_CD
           AND A.PLN_YM         = p_PLN_YM
           AND A.PLN_DGR        = p_PLN_DGR
           AND A.OBJ_YN         = '1'
        ;

    ---------------------------------------------------------------------------------------
    ELSIF p_WRK_TP = 'Q2' THEN

        -- 그리드 조회 : 위험성평가 승인관리 - 위험성평가서 항목
        OPEN RTN_CURSOR FOR
        SELECT A.SIT_CD                     -- 현장코드
             , A.PLN_YM                      -- 계획년월
             , A.PLN_DGR                     -- 계획차수
             , A.CUST_CD                     -- 협력업체코드
             , A.VNDR_SEQ                    -- 협력업체차수
             , A.CTP_CD                      -- 공종코드
             , ( SELECT CTP_NM FROM TQHA_CTP WHERE CTP_CD = A.CTP_CD ) AS CTP_NM           -- 공종명칭
             , A.UNT_CD                      -- 단위코드
             , ( SELECT UNT_NM FROM TQHA_CTPUNT WHERE CTP_CD = A.CTP_CD AND UNT_CD = A.UNT_CD ) AS UNT_NM           -- 단위명칭
             , A.CHK_ITM_CD                  -- 위험요인항목코드
             , A.CHK_ITM_NM                  -- 위험요인항목명칭
             , A.PRRT_REG               -- 중점등록(공통코드 QS002)             
             , A.DISS_SHP               -- 재해형태(공통코드 QS036)
             , ( SELECT CD_NM FROM TCOA_COMCODE WHERE COM_CD = A.PRRT_REG AND HRNK_CD = 'QS002') AS PRRT_REG_NM  -- 중점등록
             , ( SELECT CD_NM FROM TCOA_COMCODE WHERE COM_CD = A.DISS_SHP AND HRNK_CD = 'QS036') AS DISS_SHP_NM  -- 재해형태             
             , A.RISK_FREQ              -- 위험빈도(공통코드 QS003)             
             , A.RISK_APRV              -- 위험강도(공통코드 QS004)             
             , A.RISK_CRIT              -- 위험성(공통코드 QS063)
             , A.RISK_GRD               -- 위험등급(공통코드 QS024)             
             , A.RISK_FREQ2              -- 위험빈도(공통코드 QS003)             
             , A.RISK_APRV2              -- 위험강도(공통코드 QS004)             
             , A.RISK_CRIT2              -- 위험성(공통코드 QS063)
             , A.RISK_GRD2               -- 위험등급(공통코드 QS024)             
             , A.RISK_FREQ3              -- 위험빈도(공통코드 QS003)             
             , A.RISK_APRV3              -- 위험강도(공통코드 QS004)             
             , A.RISK_CRIT3              -- 위험성(공통코드 QS063)
             , A.RISK_GRD3               -- 위험등급(공통코드 QS024)             
             , A.RISK_FREQ4              -- 위험빈도(공통코드 QS003)             
             , A.RISK_APRV4              -- 위험강도(공통코드 QS004)             
             , A.RISK_CRIT4              -- 위험성(공통코드 QS063)
             , A.RISK_GRD4               -- 위험등급(공통코드 QS024)             
             , A.RISK_FREQ5              -- 위험빈도(공통코드 QS003)             
             , A.RISK_APRV5              -- 위험강도(공통코드 QS004)             
             , A.RISK_CRIT5              -- 위험성(공통코드 QS063)
             , A.RISK_GRD5               -- 위험등급(공통코드 QS024)             
             , A.RISK_FREQ6              -- 위험빈도(공통코드 QS003)             
             , A.RISK_APRV6              -- 위험강도(공통코드 QS004)             
             , A.RISK_CRIT6              -- 위험성(공통코드 QS063)
             , A.RISK_GRD6               -- 위험등급(공통코드 QS024)
             , ( SELECT CD_NM FROM TCOA_COMCODE WHERE COM_CD = A.RISK_FREQ AND HRNK_CD = 'QS003') AS RISK_FREQ_NM  -- 빈도명
             , ( SELECT CD_NM FROM TCOA_COMCODE WHERE COM_CD = A.RISK_APRV AND HRNK_CD = 'QS004') AS RISK_APRV_NM  -- 강도명
             , ( SELECT CD_NM FROM TCOA_COMCODE WHERE COM_CD = A.RISK_CRIT AND HRNK_CD = 'QS063') AS RISK_CRIT_NM  -- 위험성
             , ( SELECT CD_NM FROM TCOA_COMCODE WHERE COM_CD = A.RISK_GRD  AND HRNK_CD = 'QS024') AS RISK_GRD_NM  -- 위험등급
             , A.MNG_SUPR
             , A.MGR_OPIN                 --관리자의견
             , ( SELECT USR_NM FROM TCOZ_USR_INFO WHERE USR_ID = A.MNG_SUPR ) AS MNG_SUPR_NM  -- 관리감독자성명           
             , A.SAFT_MGR                 --안전관리자
             , A.SAFT_OPIN                 --안전의견
             , ( SELECT USR_NM FROM TCOZ_USR_INFO WHERE USR_ID = A.SAFT_MGR ) AS SAFT_MGR_NM  -- 안전관리자성명           
             , A.SITE_OMGR                 --현장소장
             , A.SITE_OPIN                 --현장소장의견
             , ( SELECT USR_NM FROM TCOZ_USR_INFO WHERE USR_ID = A.SITE_OMGR ) AS SITE_OMGR_NM -- 현장소장성명
             , A.IMPRV_CPLN             -- 개선대책
             , A.WRK_PSNNO              -- 작업인원
             , A.MA_PSN                 -- 조치자(업체)
             , A.MA_CNFR                -- 확인자(안전관리자)
             , ( SELECT USR_NM FROM TCOZ_USR_INFO WHERE USR_ID = A.MA_CNFR ) AS MA_CNFR_NM        -- 확인자성명
             , A.WRK_STR_DT                  -- 작업시작일자
             , A.WRK_END_DT                  -- 작업종료일자
             , A.IMPRV_STR_DT                -- 개선시작일자
             , A.IMPRV_END_DT                -- 개선종료일자
             , A.CHK_LOC                     -- 점검위치
             ,(SELECT DECODE(COUNT(1),0,'중흥','협력사') FROM TQHA_VNDR WHERE SIT_CD = A.SIT_CD AND VNDR_PSN_ID = A.IPT_ID) AS REG_DIV
          FROM TQHA_RISK_CHK A
         WHERE A.SIT_CD         = p_SIT_CD
           AND A.PLN_YM         = p_PLN_YM
           AND A.PLN_DGR        = p_PLN_DGR
           AND A.CUST_CD        = p_CUST_CD
           AND A.VNDR_SEQ       = p_VNDR_SEQ
         ORDER 
            BY A.CTP_CD                      -- 공종코드
             , A.UNT_CD
             , A.CHK_ITM_CD
        ;

    ---------------------------------------------------------------------------------------
    ELSIF p_WRK_TP = 'Q3' THEN

        -- 그리드 조회 : 위험성평가 승인관리 - 검토의견
        OPEN RTN_CURSOR FOR
        SELECT SIT_CD          -- 현장코드
             , PLN_YM           -- 계획년월
             , PLN_DGR          -- 계획차수
             , CUST_CD          -- 협력업체코드
             , VNDR_SEQ         -- 협력업체차수
             , MNG_SUPR         -- 관리자ID
             , MNG_APRV_DT      -- 관리자승인일자
             , MNG_APRV_STATS   -- 관리자승인상태
             , SAFT_MGR         -- 안전관리자ID
             , SAFT_APRV_DT     -- 안전관리자승인일자
             , SAFT_APRV_STATS  -- 안전관리자승인상태
             , SITE_OMGR        -- 현장소장ID
             , SITE_APRV_DT     -- 현장소장승인일자
             , SITE_APRV_STATS  -- 현장소장승인상태
             , CHK_ATFL_GRP     -- 첨부파일그룹
             , SBM_YN           -- 평가서제출여부
             , SBM_DT           -- 평가서제출일자
             , (SELECT VNDR_PSN_CADDR
                FROM TQHA_VNDR
                WHERE CUST_CD = A.CUST_CD
                  AND SIT_CD = A.SIT_CD
                  AND VNDR_SEQ = A.VNDR_SEQ) AS RCV_TEL_NO -- 담당자 연락처
             , '▶ 상태 : ' ||
               CASE WHEN SITE_APRV_STATS IN ('1', '2') THEN
                         CASE WHEN SITE_APRV_STATS = '1' THEN '현장소장-승인'
                              ELSE '현장소장-반려'
                         END
                    ELSE CASE WHEN SAFT_APRV_STATS IN ('1', '2') THEN
                                   CASE WHEN SAFT_APRV_STATS = '1' THEN '안전관리자-승인'
                                        ELSE '안전관리자-반려'
                                   END
                              ELSE CASE WHEN MNG_APRV_STATS IN ('1', '2') THEN
                                             CASE WHEN MNG_APRV_STATS = '1' THEN '관리자-승인'
                                                  ELSE '관리자-반려'
                                             END
                                        ELSE CASE WHEN SBM_YN = '1' THEN '제출'
                                                  ELSE '미제출'
                                             END
                                   END
                         END
               END              AS STATS_NM
             ,VNDR_WRK_NM
          FROM TQHA_RISK_VNDR A
         WHERE A.SIT_CD         = p_SIT_CD
           AND A.PLN_YM         = p_PLN_YM
           AND A.PLN_DGR        = p_PLN_DGR
           AND A.CUST_CD        = p_CUST_CD
           AND A.VNDR_SEQ       = p_VNDR_SEQ
           AND A.OBJ_YN         = '1'
        ;

    ---------------------------------------------------------------------------------------
    ELSIF p_WRK_TP = 'Q4' THEN

        -- Q4   그리드 조회 : 위험요인항목추가 - 공종별 단위작업
        OPEN RTN_CURSOR FOR
        SELECT A.CTP_CD   -- 상위공종코드
             , A.UNT_CD   -- 단위작업코드
             , A.CTP_NM   -- 단위작업명칭
             , A.USE_YN
             , A."Level"
          FROM ( SELECT CTP_CD         -- 공종코드
                      , ' ' AS UNT_CD  -- 단위작업코드
                      , CTP_NM         -- 공종명칭
                      , USE_YN         -- 공종 사용유무
                      , '1' AS "Level" -- 레벨1
                   FROM TQHA_CTP
                  WHERE USE_YN = '1'
                  UNION ALL
                 SELECT CTP_CD          -- 상위공종코드
                      , UNT_CD          -- 단위작업코드
                      , UNT_NM          -- 단위작업명칭
                      , USE_YN          -- 단위작업사용유무
                      , '2'  AS "Level" -- 레벨 2
                   FROM TQHA_CTPUNT 
                  WHERE USE_YN = '1') A
         ORDER 
            BY A.CTP_CD
             , A.UNT_CD ASC
        ;

     ---------------------------------------------------------------------------------------
    ELSIF p_WRK_TP = 'Q5' THEN

        -- Q5   그리드 조회 : 위험요인항목추가 - 위험요인항목
        OPEN RTN_CURSOR FOR
        SELECT A.CTP_CD      -- 상위공종코드
             , ( SELECT CTP_NM FROM TQHA_CTP WHERE CTP_CD = A.CTP_CD ) AS CTP_NM    -- 공종명칭
             , A.UNT_CD      -- 단위작업코드
             , ( SELECT UNT_NM FROM TQHA_CTPUNT WHERE CTP_CD = A.CTP_CD AND UNT_CD = A.UNT_CD ) AS UNT_NM    -- 단위명칭
             , A.CHK_ITM_CD  -- 위험요인항목코드
             , A.CHK_ITM_NM  -- 위험요인항목명칭
             , A.RISK_FREQ   -- 빈도레벨(QS003)
             , A.RISK_APRV   -- 강도레벨(QS004)
             , A.RISK_CRIT   -- 위험성(공통코드 QS063)
             , A.RISK_GRD    -- 위험등급(QS024)
             , A.PRRT_REG    -- 중점등록(QS002)
             , A.IMPRV_CPLN  -- 개선대책
             , A.USE_YN      -- 단위작업사용유무
             , A.CUST_CD     -- 업체코드
             , A.USR_DEFN_YN -- 사용자정의 구분
             , A.DISS_SHP    -- 재해형태(QS036)
             , A.SIT_CD
          FROM TQHA_CTPUNT_CHKITM A
         WHERE A.USR_DEFN_YN    = '0'
           AND A.CTP_CD         = p_CTP_CD
           AND A.UNT_CD         = p_UNT_CD
        ;

     ---------------------------------------------------------------------------------------
    ELSIF p_WRK_TP = 'Q6' THEN

        -- Q6   그리드 조회 : 위험요인항목추가 - 사용자정의 위험요인항목
        OPEN RTN_CURSOR FOR
        SELECT A.CTP_CD      -- 상위공종코드
             , ( SELECT CTP_NM FROM TQHA_CTP WHERE CTP_CD = A.CTP_CD ) AS CTP_NM    -- 공종명칭
             , A.UNT_CD      -- 단위작업코드
             , ( SELECT UNT_NM FROM TQHA_CTPUNT WHERE CTP_CD = A.CTP_CD AND UNT_CD = A.UNT_CD ) AS UNT_NM    -- 단위명칭
             , A.CHK_ITM_CD  -- 위험요인항목코드
             , A.CHK_ITM_NM  -- 위험요인항목명칭
             , A.RISK_FREQ   -- 빈도레벨(QS003)
             , A.RISK_APRV   -- 강도레벨(QS004)
             , A.RISK_CRIT   -- 위험성(공통코드 QS063)
             , A.RISK_GRD    -- 위험등급(QS024)
             , A.PRRT_REG    -- 중점등록(QS002)
             , A.IMPRV_CPLN  -- 개선대책
             , A.USE_YN      -- 단위작업사용유무
             , A.CUST_CD     -- 업체코드
             , A.USR_DEFN_YN -- 사용자정의 구분
             , A.DISS_SHP    -- 재해형태(QS036)
             , A.SIT_CD      -- 현장코드
          FROM TQHA_CTPUNT_CHKITM A
         WHERE A.USR_DEFN_YN    = '1'
           AND A.CTP_CD         = p_CTP_CD
           AND A.UNT_CD         = p_UNT_CD
           AND (NVL(p_CUST_CD, '*') = '*' OR A.CUST_CD        = p_CUST_CD)
           /** AND A.SIT_CD    = p_SIT_CD */
        ;

     ---------------------------------------------------------------------------------------
    ELSIF p_WRK_TP = 'Q7' THEN

        -- Q7   그리드 조회 : 위험요인항목추가 - 타현장 위험요인항목
        OPEN RTN_CURSOR FOR
          SELECT A.SIT_CD                     -- 현장코드
             , A.PLN_YM                      -- 계획년월
             , A.PLN_DGR                     -- 계획차수
             , A.CUST_CD                     -- 협력업체코드
             , A.VNDR_SEQ                    -- 협력업체차수
             , A.CTP_CD                      -- 공종코드
             , ( SELECT CTP_NM FROM TQHA_CTP WHERE CTP_CD = A.CTP_CD ) AS CTP_NM           -- 공종명칭
             , A.UNT_CD                      -- 단위코드
             , ( SELECT UNT_NM FROM TQHA_CTPUNT WHERE CTP_CD = A.CTP_CD AND UNT_CD = A.UNT_CD ) AS UNT_NM           -- 단위명칭
             , A.CHK_ITM_CD                  -- 위험요인항목코드
             , A.CHK_ITM_NM                  -- 위험요인항목명칭
             , A.PRRT_REG               -- 중점등록(공통코드 QS002)             
             , A.DISS_SHP               -- 재해형태(공통코드 QS036)
             , ( SELECT CD_NM FROM TCOA_COMCODE WHERE COM_CD = A.PRRT_REG AND HRNK_CD = 'QS002') AS PRRT_REG_NM  -- 중점등록
             , ( SELECT CD_NM FROM TCOA_COMCODE WHERE COM_CD = A.DISS_SHP AND HRNK_CD = 'QS036') AS DISS_SHP_NM  -- 재해형태             
             , A.RISK_FREQ              -- 위험빈도(공통코드 QS003)             
             , A.RISK_APRV              -- 위험강도(공통코드 QS004)             
             , A.RISK_CRIT              -- 위험성(공통코드 QS063)
             , A.RISK_GRD               -- 위험등급(공통코드 QS024)             
             , A.RISK_FREQ2              -- 위험빈도(공통코드 QS003)             
             , A.RISK_APRV2              -- 위험강도(공통코드 QS004)             
             , A.RISK_CRIT2              -- 위험성(공통코드 QS063)
             , A.RISK_GRD2               -- 위험등급(공통코드 QS024)             
             , A.RISK_FREQ3              -- 위험빈도(공통코드 QS003)             
             , A.RISK_APRV3              -- 위험강도(공통코드 QS004)             
             , A.RISK_CRIT3              -- 위험성(공통코드 QS063)
             , A.RISK_GRD3               -- 위험등급(공통코드 QS024)             
             , A.RISK_FREQ4              -- 위험빈도(공통코드 QS003)             
             , A.RISK_APRV4              -- 위험강도(공통코드 QS004)             
             , A.RISK_CRIT4              -- 위험성(공통코드 QS063)
             , A.RISK_GRD4               -- 위험등급(공통코드 QS024)             
             , A.RISK_FREQ5              -- 위험빈도(공통코드 QS003)             
             , A.RISK_APRV5              -- 위험강도(공통코드 QS004)             
             , A.RISK_CRIT5              -- 위험성(공통코드 QS063)
             , A.RISK_GRD5               -- 위험등급(공통코드 QS024)             
             , A.RISK_FREQ6              -- 위험빈도(공통코드 QS003)             
             , A.RISK_APRV6              -- 위험강도(공통코드 QS004)             
             , A.RISK_CRIT6              -- 위험성(공통코드 QS063)
             , A.RISK_GRD6               -- 위험등급(공통코드 QS024)
             , ( SELECT CD_NM FROM TCOA_COMCODE WHERE COM_CD = A.RISK_FREQ AND HRNK_CD = 'QS003') AS RISK_FREQ_NM  -- 빈도명
             , ( SELECT CD_NM FROM TCOA_COMCODE WHERE COM_CD = A.RISK_APRV AND HRNK_CD = 'QS004') AS RISK_APRV_NM  -- 강도명
             , ( SELECT CD_NM FROM TCOA_COMCODE WHERE COM_CD = A.RISK_CRIT AND HRNK_CD = 'QS063') AS RISK_CRIT_NM  -- 위험성
             , ( SELECT CD_NM FROM TCOA_COMCODE WHERE COM_CD = A.RISK_GRD  AND HRNK_CD = 'QS024') AS RISK_GRD_NM  -- 위험등급
             , A.MNG_SUPR
             , A.MGR_OPIN                 --관리자의견
             , ( SELECT USR_NM FROM TCOZ_USR_INFO WHERE USR_ID = A.MNG_SUPR ) AS MNG_SUPR_NM  -- 관리감독자성명           
             , A.SAFT_MGR                 --안전관리자
             , A.SAFT_OPIN                 --안전의견
             , ( SELECT USR_NM FROM TCOZ_USR_INFO WHERE USR_ID = A.SAFT_MGR ) AS SAFT_MGR_NM  -- 안전관리자성명           
             , A.SITE_OMGR                 --현장소장
             , A.SITE_OPIN                 --현장소장의견
             , ( SELECT USR_NM FROM TCOZ_USR_INFO WHERE USR_ID = A.SITE_OMGR ) AS SITE_OMGR_NM -- 현장소장성명
             , A.IMPRV_CPLN             -- 개선대책
             , A.WRK_PSNNO              -- 작업인원
             , A.MA_PSN                 -- 조치자(업체)
             , A.MA_CNFR                -- 확인자(안전관리자)
             , ( SELECT USR_NM FROM TCOZ_USR_INFO WHERE USR_ID = A.MA_CNFR ) AS MA_CNFR_NM        -- 확인자성명
             , A.WRK_STR_DT                  -- 작업시작일자
             , A.WRK_END_DT                  -- 작업종료일자
             , A.IMPRV_STR_DT                -- 개선시작일자
             , A.IMPRV_END_DT                -- 개선종료일자
             , A.CHK_LOC                     -- 점검위치
             ,(SELECT DECODE(COUNT(1),0,'중흥','협력사') FROM TQHA_VNDR WHERE SIT_CD = A.SIT_CD AND VNDR_PSN_ID = A.IPT_ID) AS REG_DIV
          FROM TQHA_RISK_CHK A
         WHERE A.CTP_CD         = p_CTP_CD
           AND A.UNT_CD         = p_UNT_CD
           AND A.SIT_CD         NOT IN(p_SIT_CD)
           AND (NVL(p_DIFF_SIT_CD, '*') = '*' OR A.SIT_CD = p_DIFF_SIT_CD)
           AND (NVL(p_PLN_YM, '*') = '*' OR A.PLN_YM = p_PLN_YM)
           AND (NVL(p_PLN_DGR, '*') = '*' OR A.PLN_DGR = p_PLN_DGR)
        ;

    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
         WHEN OTHERS THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);

END PQHA_RISK_ITM_LIST_OTHER_Q;
/

-- PQHA_RISK_ITM_MNG_Q (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_RISK_ITM_MNG_Q" (
    p_WRK_TP            IN VARCHAR2 DEFAULT 'Q'         -- FLAG
,   p_CTP_CD            IN VARCHAR2                     -- 공종코드
,   p_UNT_CD            IN NUMBER                       -- 단위코드
,   RTN_CURSOR          OUT SYS_REFCURSOR
)
IS
    /**************************************************************************************************************************
      Purpose : [위험요인관리   ] PROCEDRE 

      REVISIONS
      Ver      Date               Author                  Description
      -------  -----------------  ----------------------  ---------------------------------------------------------------------
      1.0      2026/02/10                                 최초생성

    **************************************************************************************************************************/

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE  NUMBER :=-20009; -- ERROR 코드
    ERR_MSG   VARCHAR(200);    -- ERROR Message
    USER_EXCEPTION EXCEPTION;

BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 수행전 Check Logic ]
    ---------------------------------------------------------------------------------------------------------------------------

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Logic 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------

    ---------------------------------------------------------------------------------------
    -- 그리드 조회 : 공종관리 리스트 조회
    IF p_WRK_TP = 'Q1' THEN

        OPEN RTN_CURSOR FOR
        SELECT A.CTP_CD   -- 상위공종코드
             , A.UNT_CD   -- 단위작업코드
             , A.CTP_NM   -- 단위작업명칭
             , A.USE_YN
             , A."Level"
          FROM ( SELECT CTP_CD         -- 공종코드
                      , ' ' AS UNT_CD  -- 단위작업코드
                      , CTP_NM         -- 공종명칭
                      , USE_YN         -- 공종 사용유무
                      , '1' AS "Level" -- 레벨1
                   FROM TQHA_CTP
                  WHERE USE_YN = '1'
                  UNION ALL
                 SELECT CTP_CD          -- 상위공종코드
                      , UNT_CD          -- 단위작업코드
                      , UNT_NM          -- 단위작업명칭
                      , USE_YN           -- 단위작업사용유무
                      , '2'  AS "Level" -- 레벨 2
                   FROM TQHA_CTPUNT 
                  WHERE USE_YN = '1') A
         ORDER BY A.CTP_CD, A.UNT_CD ASC
        ;

    ---------------------------------------------------------------------------------------
    -- 그리드 조회 : 위험요인 리스트 조회
    ELSIF p_WRK_TP = 'Q2' THEN

        OPEN RTN_CURSOR FOR
        SELECT CTP_CD         -- 상위공종코드
             , UNT_CD         -- 단위작업코드
             , CHK_ITM_CD     -- 점검항목코드
             , CHK_ITM_NM     -- 점검항목명칭
             , USR_DEFN_YN    -- 사용자정의 사용유무(협력업체)
             , CUST_CD        -- 업체코드
             , SIT_CD         -- 현장코드
             , USE_YN         -- 단위작업사용유무
             , RISK_FREQ      -- 빈도레벨(QS003)
             , RISK_APRV      -- 강도레벨(QS004)
             , RISK_CRIT      -- 위험성레벨(QS063)
             , RISK_GRD       -- 위험등급(QS024)
             , IMPRV_CPLN     -- 개선대책
             , DISS_SHP       -- 재해형태(QS036)
          FROM TQHB_CTPUNT_CHKITM
         WHERE CTP_CD       = p_CTP_CD
           AND UNT_CD       = p_UNT_CD
           AND USR_DEFN_YN  = '0'
        ;

    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
         WHEN OTHERS THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);

END PQHA_RISK_ITM_MNG_Q;
/

-- PQHA_RISK_ITM_OPIN_S (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_RISK_ITM_OPIN_S" (
    p_WRK_TP                VARCHAR2 :='U'      -- UPDATE FLAG( I: ISNERT, U:UPDATE, D:DELTE)
,   p_WRK_ID                VARCHAR2            -- 사용자 ID
,   p_WRK_IP                VARCHAR2            -- 사용자 IP
,   p_SIT_CD                VARCHAR2            -- 현장코드
,   p_PLN_YM                VARCHAR2            -- 계획년월
,   p_PLN_DGR               VARCHAR2            -- 계획차수
,   p_CUST_CD               VARCHAR2            -- 협력업체코드
,   p_VNDR_SEQ              VARCHAR2            -- 업체순번
,   p_MNG_SUPR              VARCHAR2            -- 관리자ID
,   p_MNG_APRV_DT           VARCHAR2            -- 관리자 승인일자
,   p_MNG_APRV_STATS        VARCHAR2            -- 관리자 승인여부
,   p_SAFT_MGR              VARCHAR2            -- 안전관리자ID
,   p_SAFT_APRV_DT          VARCHAR2            -- 안전관리자 승인일자
,   p_SAFT_APRV_STATS       VARCHAR2            -- 안전관리자 승인여부
,   p_SITE_OMGR             VARCHAR2            -- 현장소장ID
,   p_SITE_APRV_DT          VARCHAR2            -- 현장소장 승인일자
,   p_SITE_APRV_STATS       VARCHAR2            -- 현장소장 승인여부
,   p_SITE_OPIN             VARCHAR2            -- 현장소장의견
,   p_SBM_YN                VARCHAR2            -- 평가서 제출여부
,   p_SBM_DT                VARCHAR2            -- 평가서 제출일자
,   p_CHK_ATFL_GRP          VARCHAR2            -- 첨부파일그룹
,   p_MNG_DIV               VARCHAR2            -- 관리자구분
)
IS
    /**************************************************************************************************************************
      Purpose :

      REVISIONS
      Ver      Date               Author                  Description
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2025/01/27                                    최초생성

    /**************************************************************************************************************************/

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR(200);             -- ERROR Message
    USER_EXCEPTION EXCEPTION;

    v_SBM_YN       VARCHAR2(10);
    v_CUST_NM      VARCHAR2(100);
    
    v_CNT           NUMBER;

BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 필수입력 필드  Check  ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_SIT_CD IS NULL)  THEN
        ERR_MSG := '현장코드는 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_PLN_YM IS NULL)  THEN
        ERR_MSG := '계획년월은 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_PLN_DGR IS NULL)  THEN
        ERR_MSG := '계획차수는 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_CUST_CD IS NULL)  THEN
        ERR_MSG := '협력업체코드는 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_VNDR_SEQ IS NULL)  THEN
        ERR_MSG := '업체순번은 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Process 선행조건 Check ]
    ---------------------------------------------------------------------------------------------------------------------------

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Business Process ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_WRK_TP ='U') THEN

        -- 위험성 평가서 제출 여부 체크
        SELECT NVL(MAX(SBM_YN), '0')
          INTO v_SBM_YN                         -- 업체제출여부
          FROM TQHA_RISK_VNDR
         WHERE SIT_CD       = p_SIT_CD          -- 현장코드
           AND PLN_YM       = p_PLN_YM          -- 계획년월
           AND PLN_DGR      = p_PLN_DGR         -- 차수구분코드(QS005) 1 1차,2 2차
           AND CUST_CD      = p_CUST_CD         -- 업체코드
           AND VNDR_SEQ     = p_VNDR_SEQ        -- 업체순번
        ;

        IF v_SBM_YN = '0' THEN

            SELECT CUST_NM
              INTO v_CUST_NM
              FROM VQSZ_TRADE
             WHERE CUST_CD = p_CUST_CD
            ;

            ERR_MSG := '평가년월 "' || p_PLN_YM || '" 차수 "' || p_PLN_DGR || '"의 ' 
                    || CHR(10) || '업체 [' || v_CUST_NM || ']은(는) 해당 위험성평가서 제출 취소한 상태이므로 승인 및 반려가 불가합니다.';
            RAISE USER_EXCEPTION;
        END IF;
            
        
        IF (p_MNG_DIV ='MGR') THEN
        	
	        SELECT COUNT(1) INTO v_CNT
			  FROM TQHA_RISK_CHK
			WHERE  SIT_CD     = p_SIT_CD
			   AND PLN_YM     = p_PLN_YM
			   AND PLN_DGR    = p_PLN_DGR
			   AND CUST_CD    = p_CUST_CD
	           AND VNDR_SEQ   = p_VNDR_SEQ 
			   AND (MGR_OPIN IS NULL OR RISK_CRIT3 IS NULL)
			   ;
        
        ELSIF (p_MNG_DIV ='SAFT') THEN
        
        	SELECT COUNT(1) INTO v_CNT
			  FROM TQHA_RISK_CHK
			WHERE  SIT_CD     = p_SIT_CD
			   AND PLN_YM     = p_PLN_YM
			   AND PLN_DGR    = p_PLN_DGR
			   AND CUST_CD    = p_CUST_CD
	           AND VNDR_SEQ   = p_VNDR_SEQ 
	           AND (SAFT_OPIN IS NULL OR RISK_CRIT4 IS NULL)
			   ;
       ELSIF (p_MNG_DIV ='SITE') THEN
       
        	SELECT COUNT(1) INTO v_CNT
			  FROM TQHA_RISK_CHK 
			WHERE  SIT_CD     = p_SIT_CD
			   AND PLN_YM     = p_PLN_YM
			   AND PLN_DGR    = p_PLN_DGR
			   AND CUST_CD    = p_CUST_CD
	           AND VNDR_SEQ   = p_VNDR_SEQ 
	           AND (SITE_OPIN IS NULL OR RISK_CRIT5 IS NULL)
			   ;
        END IF;
            
        IF v_CNT > 0 THEN
          ERR_MSG := '입력하지 않은 검토항목이 있습니다.';
           RAISE USER_EXCEPTION;
        END IF;    

        UPDATE TQHA_RISK_VNDR 
           SET MNG_SUPR             = p_MNG_SUPR            -- 관리자ID
             , MNG_APRV_DT          = p_MNG_APRV_DT         -- 관리자 승인일자
             , MNG_APRV_STATS       = p_MNG_APRV_STATS      -- 관리자 승인여부
             , SAFT_MGR             = p_SAFT_MGR            -- 안전관리자ID
             , SAFT_APRV_DT         = p_SAFT_APRV_DT        -- 안전관리자 승인일자
             , SAFT_APRV_STATS      = p_SAFT_APRV_STATS     -- 안전관리자 승인여부
             , SITE_OMGR            = p_SITE_OMGR           -- 현장소장ID
             , SITE_APRV_DT         = p_SITE_APRV_DT        -- 현장소장 승인일자
             , SITE_APRV_STATS      = p_SITE_APRV_STATS     -- 현장소장 승인여부
             , SBM_YN               = p_SBM_YN              -- 평가서 제출여부
             , SBM_DT               = p_SBM_DT              -- 평가서 제출일자
             , CHK_ATFL_GRP         = p_CHK_ATFL_GRP        -- 첨부파일그룹
             , UPD_ID               = p_WRK_ID
             , UPD_DTM              = SYSDATE
         WHERE SIT_CD               = p_SIT_CD
           AND PLN_YM               = p_PLN_YM
           AND PLN_DGR              = p_PLN_DGR
           AND CUST_CD              = p_CUST_CD
           AND VNDR_SEQ             = p_VNDR_SEQ
           AND OBJ_YN               = '1'
        ;

    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 5. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
         WHEN OTHERS THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);
END;
/

-- PQHA_RISK_NCR_ACT_RSLT_CO_S (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_RISK_NCR_ACT_RSLT_CO_S" (
    p_WRK_TP                    VARCHAR2 :='U'                              -- UPDATE FLAG( I: ISNERT, U:UPDATE, D:DELTE)
,   p_WRK_ID                    VARCHAR2                                    -- 사용자 ID 
,   p_WRK_IP                    VARCHAR2                                    -- 사용자 IP 
,   p_SIT_CD                    TQHA_ADDRISK_ORD.SIT_CD%TYPE                -- 현장코드
,   p_NCR_DOC_NO                VARCHAR2                                    -- NCR번호
,   p_CUST_CD                   TQHA_ADDRISK_ORD.CUST_CD%TYPE               -- 업체코드
,   p_VNDR_SEQ                  TQHA_ADDRISK_ORD.VNDR_SEQ%TYPE              -- 업체순번
,   p_VNDR_MA_DT                TQHA_ADDRISK_ORD.VNDR_MA_DT%TYPE            -- 업체조치일자
,   p_VNDR_MA_YN                TQHA_ADDRISK_ORD.VNDR_MA_YN%TYPE            -- 조치구분(QS007) 1 조치, 0 미조치
,   p_VNDR_MA_PSN_NM            TQHA_ADDRISK_ORD.VNDR_MA_PSN%TYPE           -- 업체조치자
,   p_VNDR_MA_CTS               TQHA_ADDRISK_ORD.VNDR_MA_CTS%TYPE           -- 업체조치내용
,   p_VNDR_PRVN_CPLN            VARCHAR2                                    -- 재발방지대책
,   p_VNDR_PHOTO_GRP1           TQHA_ADDRISK_ORD.VNDR_PHOTO_GRP1%TYPE       -- 업체조치첨부파일그룹사진1
,   p_VNDR_PHOTO_DESC_1         TQHA_ADDRISK_ORD.VNDR_PHOTO_DESC_1%TYPE     -- 사진설명1
,   p_VNDR_PHOTO_GRP2           TQHA_ADDRISK_ORD.VNDR_PHOTO_GRP2%TYPE       -- 업체조치첨부파일그룹사진2
,   p_VNDR_PHOTO_DESC_2         TQHA_ADDRISK_ORD.VNDR_PHOTO_DESC_2%TYPE     -- 사진설명2
,   p_MGR_NOTI_YN               TQHA_ADDRISK_ORD.MGR_NOTI_YN%TYPE           -- 발송 1 미발송 0
)
IS 
    /**************************************************************************************************************************
      Purpose : 

      REVISIONS
      Ver      Date               Author                  Description 
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2026/03/03                                    최초생성

    **************************************************************************************************************************/


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR2(200);            -- ERROR Message
    USER_EXCEPTION EXCEPTION;

    v_WRT_SEQ TQHA_ADDRISK_ORD.WRT_SEQ%TYPE ;             -- 순번 변수 선언

BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 필수입력 필드  Check  ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_SIT_CD IS NULL)  THEN
        ERR_MSG := '현장코드는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Process 선행조건 Check ]
    ---------------------------------------------------------------------------------------------------------------------------


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Business Process ]
    ---------------------------------------------------------------------------------------------------------------------------
    -- 폼 저장 : 부적합보고서 조치결과 등록
    IF p_WRK_TP ='U1' THEN


        UPDATE TQHA_NCR_REP
           SET VNDR_MA_DT           = p_VNDR_MA_DT               -- 조치일자
             , VNDR_MA_YN           = p_VNDR_MA_YN               -- 조치여부
             , VNDR_MA_PSN          = p_VNDR_MA_PSN_NM          -- 조치자
             , VNDR_MA_CTS          = p_VNDR_MA_CTS             -- 조치사항
             , VNDR_PRVN_CPLN       = p_VNDR_PRVN_CPLN       -- 재발방지대책
             , VNDR_PHOTO_GRP1      = p_VNDR_PHOTO_GRP1     -- 조치사진첨부그룹1
             , VNDR_PHOTO_DESC_1    = p_VNDR_PHOTO_DESC_1 -- 사진설명1
             , VNDR_PHOTO_GRP2      = p_VNDR_PHOTO_GRP2     -- 조치사진첨부그룹2
             , VNDR_PHOTO_DESC_2    = p_VNDR_PHOTO_DESC_2 -- 사진설명2
             , MGR_NOTI_YN          = p_MGR_NOTI_YN             -- 관리자 발송여부
             , UPD_ID               = p_WRK_ID
             , UPD_DTM              = SYSDATE
             , UPD_IP               = p_WRK_IP
         WHERE SIT_CD               = p_SIT_CD
           AND NCR_DOC_NO           = p_NCR_DOC_NO
           AND CUST_CD              = p_CUST_CD
           AND VNDR_SEQ             = p_VNDR_SEQ
        ;

    --------------------------------------------------------------------------------------
    -- 폼 저장 : 추가위험발굴 조치결과 SMS발송
    ELSIF p_WRK_TP ='U2' THEN

        UPDATE TQHA_DAYSAFE_CHKLST
           SET VNDR_MA_DT           = p_VNDR_MA_DT               -- 조치일자
             , VNDR_MA_YN           = p_VNDR_MA_YN               -- 조치여부
             , UPD_ID               = p_WRK_ID
             , UPD_DTM              = SYSDATE
             , UPD_IP               = p_WRK_IP
         WHERE SIT_CD               = p_SIT_CD
           AND NCR_DOC_NO           = p_NCR_DOC_NO
           AND CUST_CD              = p_CUST_CD
           AND VNDR_SEQ             = p_VNDR_SEQ
        ;

    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 5. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN 
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);

END PQHA_RISK_NCR_ACT_RSLT_CO_S;
/

-- PQHA_RISK_OPIN_LIST_Q (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_RISK_OPIN_LIST_Q" (
    p_WRK_TP            IN VARCHAR2 DEFAULT 'Q'         -- FLAG
,   p_SIT_CD            IN VARCHAR2                     -- 현장코드
,   p_PLN_YM            IN VARCHAR2                     -- 계획연월
,   p_PLN_DGR           IN VARCHAR2                     -- 계획차수
,   p_CUST_CD           IN VARCHAR2                     -- 업체코드
,   p_VNDR_SEQ          IN VARCHAR2                     -- 업체순번
,   p_CTP_CD            IN VARCHAR2                     -- 공종코드
,   p_UNT_CD            IN VARCHAR2                     -- 단위코드
,   p_CHK_ITM_CD        IN VARCHAR2                     -- 요소아이템코드
,   RTN_CURSOR          OUT SYS_REFCURSOR 
)
IS
    /**************************************************************************************************************************
      Purpose : [위험성평가작성/검토] PROCEDRE 검토의견

      REVISIONS
      Ver      Date               Author                  Description
      -------  -----------------  ----------------------  ---------------------------------------------------------------------
      1.0      2026/02/09                                 최초생성

    **************************************************************************************************************************/

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE  NUMBER :=-20009; -- ERROR 코드
    ERR_MSG   VARCHAR(200);    -- ERROR Message
    USER_EXCEPTION EXCEPTION;

BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 수행전 Check Logic ]
    ---------------------------------------------------------------------------------------------------------------------------

	
    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Logic 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
	IF p_WRK_TP = 'Q' THEN
		
		OPEN RTN_CURSOR FOR
	    WITH BASE AS (
		    SELECT *
		      FROM TQHA_RISK_CHK A
		     WHERE A.SIT_CD     = p_SIT_CD
		       AND A.PLN_YM     = p_PLN_YM
		       AND A.PLN_DGR    = p_PLN_DGR
		       AND A.CUST_CD    = p_CUST_CD
		       AND A.VNDR_SEQ   = p_VNDR_SEQ
		       AND A.CTP_CD     = p_CTP_CD
		       AND A.UNT_CD     = p_UNT_CD
		       AND A.CHK_ITM_CD = p_CHK_ITM_CD
			),
			ROLE_LIST AS (
			    SELECT '3' AS SEQ FROM DUAL 
			    UNION ALL
			    SELECT '4' FROM DUAL
			    UNION ALL
			    SELECT '5' FROM DUAL
			)
			SELECT
			      R.SEQ AS RSEQ
			    , CASE R.SEQ
			        WHEN '3' THEN '관리감독자'
			        WHEN '4' THEN '안전관리자'
			        WHEN '5' THEN '현장소장'
			      END AS MNG_DIV
			
			    , CASE R.SEQ
			        WHEN '3' THEN B.RISK_FREQ3
			        WHEN '4' THEN B.RISK_FREQ4
			        WHEN '5' THEN B.RISK_FREQ5
			      END AS RISK_FREQ
			
			    , CASE R.SEQ
			        WHEN '3' THEN B.RISK_APRV3
			        WHEN '4' THEN B.RISK_APRV4
			        WHEN '5' THEN B.RISK_APRV5
			      END AS RISK_APRV
			
			    , CASE R.SEQ
			        WHEN '3' THEN B.RISK_CRIT3
			        WHEN '4' THEN B.RISK_CRIT4
			        WHEN '5' THEN B.RISK_CRIT5
			      END AS RISK_CRIT
			
			    , CASE R.SEQ
			        WHEN '3' THEN B.RISK_GRD3
			        WHEN '4' THEN B.RISK_GRD4
			        WHEN '5' THEN B.RISK_GRD5
			      END AS RISK_GRD
			
			    , CASE R.SEQ
			        WHEN '3' THEN B.MNG_SUPR
			        WHEN '4' THEN B.SAFT_MGR
			        WHEN '5' THEN B.SITE_OMGR
			      END AS OMGR
			      
			    , CASE R.SEQ
			        WHEN '3' THEN ( SELECT USR_NM FROM TCOZ_USR_INFO WHERE USR_ID = B.MNG_SUPR )
			        WHEN '4' THEN ( SELECT USR_NM FROM TCOZ_USR_INFO WHERE USR_ID = B.SAFT_MGR )
			        WHEN '5' THEN ( SELECT USR_NM FROM TCOZ_USR_INFO WHERE USR_ID = B.SITE_OMGR )
			      END AS OMGR_NM
			
			    , CASE R.SEQ
			        WHEN '3' THEN B.MGR_OPIN
			        WHEN '4' THEN B.SAFT_OPIN
			        WHEN '5' THEN B.SITE_OPIN
			      END AS OPIN
			
			FROM ROLE_LIST R
			LEFT JOIN BASE B
			       ON 1 = 1
			ORDER BY R.SEQ;
			
	ELSIF p_WRK_TP = 'Q2' THEN
	
		OPEN RTN_CURSOR FOR
	    WITH BASE AS (
		    SELECT *
		      FROM TQHA_RISK_CHK A
		     WHERE A.SIT_CD     = p_SIT_CD
		       AND A.PLN_YM     = p_PLN_YM
		       AND A.PLN_DGR    = p_PLN_DGR
		       AND A.CUST_CD    = p_CUST_CD
		       AND A.VNDR_SEQ   = p_VNDR_SEQ
		       AND A.CTP_CD     = p_CTP_CD
		       AND A.UNT_CD     = p_UNT_CD
		       AND A.CHK_ITM_CD = p_CHK_ITM_CD
			),
			ROLE_LIST AS (
				SELECT '2' AS SEQ FROM DUAL
			    UNION ALL
			    SELECT '3' FROM DUAL
			    UNION ALL
			    SELECT '4' FROM DUAL
			    UNION ALL
			    SELECT '5' FROM DUAL
			)
			SELECT
			      R.SEQ AS RSEQ
			    , CASE R.SEQ
  			        WHEN '2' THEN '근로자대표'
			        WHEN '3' THEN '관리감독자'
			        WHEN '4' THEN '안전관리자'
			        WHEN '5' THEN '현장소장'
			      END AS MNG_DIV
			
			    , CASE R.SEQ
 			        WHEN '2' THEN ''
			        WHEN '3' THEN B.RISK_FREQ3
			        WHEN '4' THEN B.RISK_FREQ4
			        WHEN '5' THEN B.RISK_FREQ5
			      END AS RISK_FREQ
			
			    , CASE R.SEQ
			        WHEN '2' THEN ''
			        WHEN '4' THEN B.RISK_APRV4
			        WHEN '5' THEN B.RISK_APRV5
			      END AS RISK_APRV
			
			    , CASE R.SEQ
			        WHEN '2' THEN ''
			        WHEN '4' THEN B.RISK_CRIT4
			        WHEN '5' THEN B.RISK_CRIT5
			      END AS RISK_CRIT
			
			    , CASE R.SEQ
			        WHEN '2' THEN ''
			        WHEN '4' THEN B.RISK_GRD4
			        WHEN '5' THEN B.RISK_GRD5
			      END AS RISK_GRD
			
			    , CASE R.SEQ
			        WHEN '2' THEN B.VNDR_WRK_NM
			        WHEN '3' THEN B.MNG_SUPR
			        WHEN '4' THEN B.SAFT_MGR
			        WHEN '5' THEN B.SITE_OMGR
			      END AS OMGR
			      
			    , CASE R.SEQ
 			        WHEN '2' THEN B.VNDR_WRK_NM
			        WHEN '3' THEN ( SELECT USR_NM FROM TCOZ_USR_INFO WHERE USR_ID = B.MNG_SUPR )
			        WHEN '4' THEN ( SELECT USR_NM FROM TCOZ_USR_INFO WHERE USR_ID = B.SAFT_MGR )
			        WHEN '5' THEN ( SELECT USR_NM FROM TCOZ_USR_INFO WHERE USR_ID = B.SITE_OMGR )
			      END AS OMGR_NM
			
			    , CASE R.SEQ
  			        WHEN '2' THEN B.VNDR_WRK_OPIN
			        WHEN '3' THEN B.MGR_OPIN
			        WHEN '4' THEN B.SAFT_OPIN
			        WHEN '5' THEN B.SITE_OPIN
			      END AS OPIN
			
			FROM ROLE_LIST R
			LEFT JOIN BASE B
			       ON 1 = 1
			ORDER BY R.SEQ;	
	END IF;
			
    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
         WHEN OTHERS THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);

END PQHA_RISK_OPIN_LIST_Q;
/

-- PQHA_RISK_PLAN_OTHER_Q (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_RISK_PLAN_OTHER_Q" (
    p_WRK_TP            IN VARCHAR2 DEFAULT 'Q'         -- FLAG
,   p_SIT_CD            IN VARCHAR2                     -- 현장코드
,   p_CTP_CD            IN VARCHAR2                     -- 상위공종코드
,   p_UNT_CD            IN VARCHAR2                     -- 단위작업코드
,   p_FST_DIV           IN VARCHAR2                     -- 최초구분
,   p_PLN_DGR           IN VARCHAR2                     -- 계획차수
,   RTN_CURSOR          OUT SYS_REFCURSOR
)
IS
    /**************************************************************************************************************************
      Purpose : [최초 위험성평가계획] PROCEDRE 

      REVISIONS
      Ver      Date               Author                  Description
      -------  -----------------  ----------------------  ---------------------------------------------------------------------
      1.0      2026/02/05                                 최초생성

    **************************************************************************************************************************/

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE  NUMBER :=-20009; -- ERROR 코드
    ERR_MSG   VARCHAR(200);    -- ERROR Message
    USER_EXCEPTION EXCEPTION;

BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 수행전 Check Logic ]
    ---------------------------------------------------------------------------------------------------------------------------

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Logic 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------

    ---------------------------------------------------------------------------------------
    -- 
    IF p_WRK_TP = 'Q1' THEN

        -- 위험요인항목추가 - 공종
        OPEN RTN_CURSOR FOR
        SELECT A.CTP_DIV
             , ( SELECT CD_NM FROM TCOA_COMCODE WHERE COM_CD = A.CTP_DIV AND HRNK_CD = 'QS035') AS CTP_DIV_NM       -- 공종구분명
             , A.CTP_CD                                                                                             -- 공종코드
             , A.CTP_NM                                                                                             -- 공종명칭
          FROM TQHA_CTP A
         ORDER BY A.CTP_DIV, A.CTP_CD
        ;

    ---------------------------------------------------------------------------------------
    ELSIF p_WRK_TP = 'Q2' THEN

        -- 위험요인항목추가 - 공종별 단위작업
        OPEN RTN_CURSOR FOR
        SELECT CTP_CD         -- 상위공종코드
             , UNT_CD         -- 단위작업코드
             , UNT_NM         -- 단위작업명칭
             , USE_YN         -- 단위작업사용유무
          FROM TQHA_CTPUNT
         WHERE CTP_CD = p_CTP_CD
        ;

    ---------------------------------------------------------------------------------------
    ELSIF p_WRK_TP = 'Q3' THEN

        -- 위험요인항목추가 - 사용자정의 위험요인항목
        OPEN RTN_CURSOR FOR
        SELECT CTP_CD               -- 상위공종코드
             , ( SELECT CTP_NM FROM TQHA_CTP WHERE CTP_CD = A.CTP_CD )                          AS CTP_NM   -- 공종명칭
             , UNT_CD               -- 단위작업코드
             , ( SELECT UNT_NM FROM TQHA_CTPUNT WHERE CTP_CD = A.CTP_CD AND UNT_CD = A.UNT_CD ) AS UNT_NM   -- 단위명칭
             , CHK_ITM_CD           -- 위험요인항목코드
             , CHK_ITM_NM           -- 위험요인항목명칭
             , CUST_CD              -- 업체코드  
             , USE_YN               -- 단위작업사용유무
             , USR_DEFN_YN          -- 사용자정의유무
             , RISK_FREQ            -- 빈도레벨(QS003)
             , RISK_APRV            -- 강도레벨(QS004)
             , RISK_CRIT            -- 위험성레벨(QS063)
             , RISK_GRD             -- 위험레벨(QS004)
             , PRRT_REG             -- 중점등록(QS003)
             , IMPRV_CPLN           -- 개선대책
             , DISS_SHP             -- 재해형태(QS036)
             , SIT_CD               -- 현장코드
          FROM TQHA_CTPUNT_CHKITM A
         WHERE CTP_CD       = p_CTP_CD
           AND UNT_CD       = p_UNT_CD
           AND USR_DEFN_YN  = '1'      -- 사용자 정의컬럼인 경우
           -- AND CUST_CD = {CUST_CD} 
           AND SIT_CD       = p_SIT_CD
        ;

    ---------------------------------------------------------------------------------------
    ELSIF p_WRK_TP = 'Q4' THEN

        -- 위험성평가계획 결재번호
        OPEN RTN_CURSOR FOR
        SELECT A.APRV_NO
             , B.APRV_STATS
          FROM TQHA_RISKPLAN    A
          LEFT JOIN TQHA_APRV   B ON A.SIT_CD   = B.SIT_CD
                                 AND A.APRV_NO  = B.APRV_NO
         WHERE A.SIT_CD     = p_SIT_CD
           AND A.FST_DIV    = p_FST_DIV
           AND A.PLN_DGR    = p_PLN_DGR
        ;

    ---------------------------------------------------------------------------------------
    ELSIF p_WRK_TP = 'Q5' THEN

        -- 위험성평가계획 결재번호
        OPEN RTN_CURSOR FOR
        SELECT A.SIT_CD                                                                                             -- 현장코드
             , A.FST_DIV                                                                                            -- 최초구분(공통코드 QS001)
             , A.PLN_DGR                                                                                            -- 계획차수(공통코드 QS005)
             , A.CTP_CD                                                                                             -- 공종코드
             , ( SELECT CTP_NM FROM TQHA_CTP WHERE CTP_CD = A.CTP_CD )                              AS CTP_NM       -- 공종명칭
             , A.UNT_CD                                                                                             -- 단위코드
             , ( SELECT UNT_NM FROM TQHA_CTPUNT WHERE CTP_CD = A.CTP_CD AND UNT_CD = A.UNT_CD )     AS UNT_NM       -- 단위명칭
             , A.CHK_ITM_CD                                                                                         -- 위험요인항목코드
             , A.CHK_ITM_NM                                                                                         -- 위험요인항목명칭
             , A.RISK_FREQ                                                                                          -- 위험빈도(공통코드 QS003)
             , ( SELECT CD_NM FROM TCOA_COMCODE WHERE COM_CD = A.RISK_FREQ AND HRNK_CD = 'QS003')   AS RISK_FREQ_NM -- 빈도명
             , A.RISK_APRV                                                                                          -- 위험강도(공통코드 QS004)
             , ( SELECT CD_NM FROM TCOA_COMCODE WHERE COM_CD = A.RISK_APRV AND HRNK_CD = 'QS004')   AS RISK_APRV_NM -- 강도명
             , A.RISK_CRIT        																				    -- 위험성레벨(QS063)
             , A.RISK_GRD                                                                                           -- 위험등급(공통코드 QS024)
             , ( SELECT CD_NM FROM TCOA_COMCODE WHERE COM_CD = A.RISK_GRD AND HRNK_CD = 'QS024')    AS RISK_GRD_NM  -- 위험등급
             , A.PRRT_REG                                                                                           -- 중점등록(공통코드 QS002)
             , ( SELECT CD_NM FROM TCOA_COMCODE WHERE COM_CD = A.PRRT_REG AND HRNK_CD = 'QS002')    AS PRRT_REG_NM  -- 중점등록
             , A.IMPRV_CPLN                                                                                         -- 개선대책
             , A.MA_CNFR                                                                                            -- 확인자(안전관리자)
             , ( SELECT USR_NM FROM TCOZ_USR_INFO WHERE USR_ID = A.MA_CNFR ) AS MA_CNFR_NM                          -- 확인자성명
             , A.DISS_SHP                                                                                           -- 재해형태(QS036)
          FROM TQHA_RISKPLAN_D A
         WHERE SIT_CD   = p_SIT_CD          -- DIFF_SIT_CD  타현장
           AND FST_DIV  = p_FST_DIV         -- DIFF_FST_DIV
           AND PLN_DGR  = p_PLN_DGR         -- DIFF_PLN_DGR
        ;

    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
         WHEN OTHERS THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);

END PQHA_RISK_PLAN_OTHER_Q;
/

-- PQHA_RISK_SCHD_MNG_CO_Q (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_RISK_SCHD_MNG_CO_Q" (
    p_WRK_TP            IN VARCHAR2 DEFAULT 'Q'             -- FLAG(Q: 현장평가, Q1:본사평가)
,   p_SIT_CD            IN VARCHAR2                         -- 현장코드
,   p_CUST_CD           IN VARCHAR2                         -- 고객코드
,   p_VNDR_SEQ          IN VARCHAR2                         -- 업체순번
,   p_PLN_YM            IN VARCHAR2                         -- 계획년월
,   p_PLN_DGR           IN VARCHAR2                         -- 계획차수
,   p_CTP_CD            IN VARCHAR2                         -- 공종코드 
,   p_UNT_CD            IN VARCHAR2                         -- 단위코드
,   RTN_CURSOR       OUT SYS_REFCURSOR
) 
IS

    /**************************************************************************************************************************
      Purpose : 파트너 위험성평가등록 

      REVISIONS
      Ver      Date               Author                  Description
      -------  -----------------  ----------------------  ---------------------------------------------------------------------
      1.0      2026/02/27                                 최초생성

    **************************************************************************************************************************/

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE  NUMBER :=-20009; -- ERROR 코드
    ERR_MSG   VARCHAR(200);    -- ERROR Message
    USER_EXCEPTION EXCEPTION;

BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 수행전 Check Logic ]
    ---------------------------------------------------------------------------------------------------------------------------

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Logic 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    -- 그리드 조회 : 위험성평가 목록 (현장)
    IF p_WRK_TP = 'Q1' THEN

        OPEN RTN_CURSOR FOR
        SELECT A.SIT_CD                  --현장코드
             , A.PLN_YM                   --계획년월
             , A.PLN_DGR                  --계획차수
             ,( SELECT CD_NM FROM TCOA_COMCODE WHERE COM_CD = A.PLN_DGR AND HRNK_CD = 'QS005') AS PLN_DGR_NM  -- 계획차수명칭
             , B.APRS_STR_DT              --평가시작일
             , B.APRS_END_DT              --평가종료일
             , B.VNDR_CMPL_DT             --업체작성완료일자
             , B.CONF_SCH_DT              --회의예정일자
             , A.SITE_APRV_DT AS FINAL_DT --최종승인일자
             , A.SBM_YN                   --평가서제출여부
             , DECODE(NVL(A.SBM_YN,0), '1', '제출', '작성중') AS SBM_NM -- 제출여부명칭
             , A.SBM_DT                   --평가서제출일자
             , A.MNG_SUPR                 --관리감독자
             , ( SELECT USR_NM FROM TCOZ_USR_INFO WHERE USR_ID = A.MNG_SUPR ) AS MNG_SUPR_NM -- 관리감독자명
             , A.MNG_APRV_STATS           --관리감독자 승인상태(1승인, 2반려)
             , DECODE(NVL(A.SBM_YN,0), '1', DECODE(NVL(A.MNG_APRV_STATS,0), '1', '승인완료 ', DECODE(NVL(A.MNG_APRV_STATS,0), '2', '반려 ', '진행중')), '0', DECODE(NVL(A.MNG_APRV_STATS,0), '2', '반려 ', ''), '' ) AS MNG_APRV_STATS_NM -- 관리상태명칭
             , A.MNG_APRV_DT              --관리감독자 승인일자
             , A.SAFT_MGR                 --안전관리자
             , ( SELECT USR_NM FROM TCOZ_USR_INFO WHERE USR_ID = A.SAFT_MGR ) AS SAFT_MGR_NM -- 안전관리자명
             , A.SAFT_APRV_STATS          --안전관리자 승인상태(1승인 2반려)
             , DECODE(NVL(A.MNG_APRV_STATS,0), '1', DECODE(NVL(A.SAFT_APRV_STATS,0), '1', '승인완료 ', DECODE(NVL(A.SAFT_APRV_STATS,0), '2', '반려 ', '진행중')), '0', DECODE(NVL(A.SAFT_APRV_STATS,0), '1','승인', '2', '반려 ', ''), '' ) AS SAFT_APRV_STATS_NM -- 안전상태명칭
             , A.SAFT_APRV_DT             --안전관리자 승인일자
             , A.SITE_OMGR                --현장소장
             , ( SELECT USR_NM FROM TCOZ_USR_INFO WHERE USR_ID = A.SITE_OMGR ) AS SITE_OMGR_NM -- 현장소장명
             , A.SITE_APRV_STATS          --현장소장 승인상태(1승인, 2반려)
             , DECODE(NVL(A.SAFT_APRV_STATS,0), '1', DECODE(NVL(A.SITE_APRV_STATS,0), '1', '승인완료 ', DECODE(NVL(A.SITE_APRV_STATS,0), '2', '반려 ', '진행중')), '0', DECODE(NVL(A.SITE_APRV_STATS,0), '2', '반려 ', ''), '' ) AS SITE_APRV_STATS_NM -- 소장상태명칭
             , A.SITE_APRV_DT             --현장소장 승인일자
             , A.CUST_CD                  --협력업체코드
             , ( SELECT CUST_NM FROM VQSZ_TRADE WHERE CUST_CD = A.CUST_CD ) AS VNDR_NM --협력업체명
             , A.VNDR_SEQ                 --협력업체차수
             , A.CHK_ATFL_GRP             --첨부파일그룹
             , '▶ 상태 : ' ||
               CASE WHEN SITE_APRV_STATS IN ('1', '2') THEN
                         CASE WHEN SITE_APRV_STATS = '1' THEN '현장소장-승인'
                              ELSE '현장소장-반려'
                         END
                    ELSE CASE WHEN SAFT_APRV_STATS IN ('1', '2') THEN
                                   CASE WHEN SAFT_APRV_STATS = '1' THEN '안전관리자-승인'
                                        ELSE '안전관리자-반려'
                                   END
                              ELSE CASE WHEN MNG_APRV_STATS IN ('1', '2') THEN
                                             CASE WHEN MNG_APRV_STATS = '1' THEN '관리자-승인'
                                                  ELSE '관리자-반려'
                                             END
                                        ELSE CASE WHEN SBM_YN = '1' THEN '제출'
                                                  ELSE '미제출'
                                             END
                                   END
                         END
               END              AS STATS_NM
          FROM TQHA_RISK_VNDR A
             , TQHA_RISK_DGR B
         WHERE A.SIT_CD         =  B.SIT_CD
           AND A.PLN_YM         = B.PLN_YM
           AND A.PLN_DGR        = B.PLN_DGR
           AND A.SIT_CD         = p_SIT_CD
           AND A.CUST_CD        = p_CUST_CD
           AND A.VNDR_SEQ       = p_VNDR_SEQ
           AND A.OBJ_YN         = '1'           -- 대상유무
           AND (NVL(p_PLN_YM, '*') = '*'     OR A.PLN_YM     = p_PLN_YM)
           AND (NVL(p_PLN_DGR, '*') = '*'    OR A.PLN_DGR    = p_PLN_DGR)
         ORDER BY A.PLN_YM DESC, A.PLN_DGR DESC
        ;

    -- 그리드 조회 : 위험성평가 목록 (본사)
    ELSIF p_WRK_TP = 'Q1_H' THEN

        OPEN RTN_CURSOR FOR
        SELECT A.SIT_CD                  --현장코드
             , A.PLN_YM                   --계획년월
             , A.PLN_DGR                  --계획차수
             ,( SELECT CD_NM FROM TCOA_COMCODE WHERE COM_CD = A.PLN_DGR AND HRNK_CD = 'QS005') AS PLN_DGR_NM  -- 계획차수명칭
             , B.APRS_STR_DT              --평가시작일
             , B.APRS_END_DT              --평가종료일
             , B.VNDR_CMPL_DT             --업체작성완료일자
             , B.CONF_SCH_DT              --회의예정일자
             , A.SITE_APRV_DT AS FINAL_DT --최종승인일자
             , A.SBM_YN                   --평가서제출여부
             , DECODE(NVL(A.SBM_YN,0), '1', '제출', '작성중') AS SBM_NM -- 제출여부명칭
             , A.SBM_DT                   --평가서제출일자
             , A.MNG_SUPR                 --관리감독자
             , ( SELECT USR_NM FROM TCOZ_USR_INFO WHERE USR_ID = A.MNG_SUPR ) AS MNG_SUPR_NM -- 관리감독자명
             , A.MNG_APRV_STATS           --관리감독자 승인상태(1승인, 2반려)
             , DECODE(NVL(A.SBM_YN,0), '1', DECODE(NVL(A.MNG_APRV_STATS,0), '1', '승인완료 ', DECODE(NVL(A.MNG_APRV_STATS,0), '2', '반려 ', '진행중')), '0', DECODE(NVL(A.MNG_APRV_STATS,0), '2', '반려 ', ''), '' ) AS MNG_APRV_STATS_NM -- 관리상태명칭
             , A.MNG_APRV_DT              --관리감독자 승인일자
             , A.SAFT_MGR                 --안전관리자
             , ( SELECT USR_NM FROM TCOZ_USR_INFO WHERE USR_ID = A.SAFT_MGR ) AS SAFT_MGR_NM -- 안전관리자명
             , A.SAFT_APRV_STATS          --안전관리자 승인상태(1승인 2반려)
             , DECODE(NVL(A.MNG_APRV_STATS,0), '1', DECODE(NVL(A.SAFT_APRV_STATS,0), '1', '승인완료 ', DECODE(NVL(A.SAFT_APRV_STATS,0), '2', '반려 ', '진행중')), '0', DECODE(NVL(A.SAFT_APRV_STATS,0), '1','승인', '2', '반려 ', ''), '' ) AS SAFT_APRV_STATS_NM -- 안전상태명칭
             , A.SAFT_APRV_DT             --안전관리자 승인일자
             , A.SITE_OMGR                --현장소장
             , ( SELECT USR_NM FROM TCOZ_USR_INFO WHERE USR_ID = A.SITE_OMGR ) AS SITE_OMGR_NM -- 현장소장명
             , A.SITE_APRV_STATS          --현장소장 승인상태(1승인, 2반려)
             , DECODE(NVL(A.SAFT_APRV_STATS,0), '1', DECODE(NVL(A.SITE_APRV_STATS,0), '1', '승인완료 ', DECODE(NVL(A.SITE_APRV_STATS,0), '2', '반려 ', '진행중')), '0', DECODE(NVL(A.SITE_APRV_STATS,0), '2', '반려 ', ''), '' ) AS SITE_APRV_STATS_NM -- 소장상태명칭
             , A.SITE_APRV_DT             --현장소장 승인일자
             , A.CUST_CD                  --협력업체코드
             , ( SELECT CUST_NM FROM VQSZ_TRADE WHERE CUST_CD = A.CUST_CD ) AS VNDR_NM --협력업체명
             , A.VNDR_SEQ                 --협력업체차수
             , A.CHK_ATFL_GRP             --첨부파일그룹
             , '▶ 상태 : ' ||
               CASE WHEN SITE_APRV_STATS IN ('1', '2') THEN
                         CASE WHEN SITE_APRV_STATS = '1' THEN '현장소장-승인'
                              ELSE '현장소장-반려'
                         END
                    ELSE CASE WHEN SAFT_APRV_STATS IN ('1', '2') THEN
                                   CASE WHEN SAFT_APRV_STATS = '1' THEN '안전관리자-승인'
                                        ELSE '안전관리자-반려'
                                   END
                              ELSE CASE WHEN MNG_APRV_STATS IN ('1', '2') THEN
                                             CASE WHEN MNG_APRV_STATS = '1' THEN '관리자-승인'
                                                  ELSE '관리자-반려'
                                             END
                                        ELSE CASE WHEN SBM_YN = '1' THEN '제출'
                                                  ELSE '미제출'
                                             END
                                   END
                         END
               END              AS STATS_NM 
          FROM TQHA_RISK_VNDR A
             , TQHA_RISK_DGR B
         WHERE A.SIT_CD         =  B.SIT_CD
           AND A.PLN_YM         = B.PLN_YM
           AND A.PLN_DGR        = B.PLN_DGR
           AND A.SIT_CD         = p_SIT_CD
           AND A.OBJ_YN         = '1'           -- 대상유무
           AND (NVL(p_PLN_YM, '*') = '*'     OR A.PLN_YM     = p_PLN_YM)
           AND (NVL(p_PLN_DGR, '*') = '*'    OR A.PLN_DGR    = p_PLN_DGR)
         ORDER BY A.PLN_YM DESC, A.PLN_DGR DESC
        ;
    --------------------------------------------------------------------------------
    -- 그리드 조회 : 위험성평가 작성
    ELSIF p_WRK_TP = 'Q2' THEN

        OPEN RTN_CURSOR FOR
        SELECT 
            A.SIT_CD          -- 현장코드
           ,A.PLN_YM                 --계획년월
           ,A.PLN_DGR                 --차수구분코드(QS005) 1 1차,2 2차
           ,A.CUST_CD                 --협력업체코드
           ,A.VNDR_SEQ                 --업체순번
           ,A.CTP_CD           -- 공종코드
           ,( SELECT CTP_NM FROM TQHA_CTP WHERE CTP_CD = A.CTP_CD ) AS CTP_NM    -- 공종명칭
           ,A.UNT_CD           -- 단위코드
           ,( SELECT UNT_NM FROM TQHA_CTPUNT WHERE CTP_CD = A.CTP_CD AND UNT_CD = A.UNT_CD ) AS UNT_NM    -- 단위명칭
           ,A.CHK_ITM_CD                 --점검항목코드
           ,A.CHK_ITM_NM                 --점검항목명
           ,A.CHK_LOC                 --점검위치
           ,A.DISS_SHP                 --재해형태(QS036)
           ,A.RISK_FREQ                 --빈도레벨(QS003)
           ,A.RISK_APRV                 --강도레벨(QS004)
           ,A.RISK_CRIT                 --위험성레벨(QS063)
           ,A.RISK_GRD                 --위험등급(QS024)
           ,A.PRRT_REG                 --중점등록(QS002) O, X
           ,A.IMPRV_CPLN                 --개선대책
           ,A.RISK_FREQ2                 --빈도레벨(QS003)
           ,A.RISK_APRV2                 --강도레벨(QS004)
           ,A.RISK_CRIT2                 --위험성레벨(QS063)
           ,A.RISK_GRD2                 --위험등급(QS024)
           ,A.MNG_SUPR                 --관리감독자
           ,A.MGR_OPIN                 --관리자의견
           ,( SELECT USR_NM FROM TCOZ_USR_INFO WHERE USR_ID = A.MNG_SUPR ) AS MNG_SUPR_NM  -- 관리감독자성명
           ,A.RISK_FREQ3                 --빈도레벨(QS003)
           ,A.RISK_APRV3                 --강도레벨(QS004)
           ,A.RISK_CRIT3                 --위험성레벨(QS063)
           ,A.RISK_GRD3                 --위험등급(QS024)
           ,A.SAFT_MGR                 --안전관리자
           ,A.SAFT_OPIN                 --안전의견
           ,( SELECT USR_NM FROM TCOZ_USR_INFO WHERE USR_ID = A.SAFT_MGR ) AS SAFT_MGR_NM  -- 안전관리자성명
           ,A.RISK_FREQ4                 --빈도레벨(QS003)
           ,A.RISK_APRV4                 --강도레벨(QS004)
           ,A.RISK_CRIT4                 --위험성레벨(QS063)
           ,A.RISK_GRD4                 --위험등급(QS024)
           ,A.SITE_OMGR                 --현장소장
           ,A.SITE_OPIN                 --현장소장의견
           ,( SELECT USR_NM FROM TCOZ_USR_INFO WHERE USR_ID = A.SITE_OMGR ) AS SITE_OMGR_NM -- 현장소장성명
           ,A.RISK_FREQ5                 --빈도레벨(QS003)
           ,A.RISK_APRV5                 --강도레벨(QS004)
           ,A.RISK_CRIT5                 --위험성레벨(QS063)
           ,A.RISK_GRD5                 --위험등급(QS024)
           ,A.RISK_FREQ6                 --빈도레벨(QS003)
           ,A.RISK_APRV6                 --강도레벨(QS004)
           ,A.RISK_CRIT6                 --위험성레벨(QS063)
           ,A.RISK_GRD6                 --위험등급(QS024)
           ,A.WRK_PSNNO                 --작업인원
           ,A.MA_PSN                 --조치자
           ,A.MA_CNFR                 --확인자
           ,( SELECT USR_NM FROM TCOZ_USR_INFO WHERE USR_ID = A.MA_CNFR ) AS MA_CNFR_NM  -- 확인자성명
           ,A.WRK_STR_DT                 --작업시작일자
           ,A.WRK_END_DT                 --작업종료일자
           ,A.IMPRV_STR_DT                 --개선시작일자
           ,A.IMPRV_END_DT                 --개선종료일자
           ,(SELECT DECODE(COUNT(1),0,'중흥','협력사') FROM TQHA_VNDR WHERE SIT_CD = A.SIT_CD AND VNDR_PSN_ID = A.IPT_ID) AS REG_DIV
          FROM TQHA_RISK_CHK A
         WHERE A.SIT_CD     = p_SIT_CD
           AND A.PLN_YM     = p_PLN_YM
           AND A.PLN_DGR    = p_PLN_DGR
           AND A.CUST_CD    = p_CUST_CD
           AND A.VNDR_SEQ   = p_VNDR_SEQ
        ;

    --------------------------------------------------------------------------------
    -- 그리드 조회 : 위험요인항목 추가 - 공종별 단위작업 리스트 (트리)
    ELSIF p_WRK_TP = 'Q3' THEN

        OPEN RTN_CURSOR FOR
        SELECT A.CTP_CD   -- 상위공종코드
             , A.UNT_CD   -- 단위작업코드
             , A.CTP_NM   -- 단위작업명칭
             , A.USE_YN
             , A."Level"
          FROM ( SELECT CTP_CD         -- 공종코드
                      , ' ' AS UNT_CD  -- 단위작업코드
                      , CTP_NM         -- 공종명칭
                      , USE_YN         -- 공종 사용유무
                      , '1' AS "Level" -- 레벨1
                   FROM TQHA_CTP
                  WHERE USE_YN = '1'
                  UNION ALL
                 SELECT CTP_CD          -- 상위공종코드
                      , UNT_CD          -- 단위작업코드
                      , UNT_NM          -- 단위작업명칭
                      , USE_YN          -- 단위작업사용유무
                      , '2'  AS "Level" -- 레벨 2
                   FROM TQHA_CTPUNT 
                  WHERE USE_YN = '1') A
         ORDER BY A.CTP_CD, A.UNT_CD ASC
        ;

    --------------------------------------------------------------------------------
    -- 그리드 조회 : 위험요인항목 추가 - 위험요인항목
    ELSIF p_WRK_TP = 'Q4' THEN

        OPEN RTN_CURSOR FOR

        SELECT A.CTP_CD      -- 상위공종코드
             , ( SELECT CTP_NM FROM TQHA_CTP WHERE CTP_CD = A.CTP_CD ) AS CTP_NM    -- 공종명칭
             , A.UNT_CD      -- 단위작업코드
             , ( SELECT UNT_NM FROM TQHA_CTPUNT WHERE CTP_CD = A.CTP_CD AND UNT_CD = A.UNT_CD ) AS UNT_NM    -- 단위명칭
             , A.CHK_ITM_CD  -- 점검항목코드
             , A.CHK_ITM_NM  -- 점검항목명칭
             , A.RISK_FREQ   -- 빈도레벨(QS003)
             , A.RISK_APRV   -- 강도레벨(QS004)
             , A.RISK_CRIT   -- 위험성(공통코드 QS063)
             , A.RISK_GRD    -- 위험등급(QS024)
             , A.PRRT_REG    -- 중점등록(QS002)
             , A.IMPRV_CPLN  -- 개선대책
             , A.USE_YN      -- 단위작업사용유무
             , A.CUST_CD     -- 업체코드
             , A.USR_DEFN_YN -- 사용자정의 구분
             , A.DISS_SHP    -- 재해형태(QS036)
          FROM TQHA_CTPUNT_CHKITM A
         WHERE A.USR_DEFN_YN    = '0'
           AND A.CTP_CD         = p_CTP_CD
           AND A.UNT_CD         = p_UNT_CD
        ;

    --------------------------------------------------------------------------------
    -- 그리드 조회 : 위험요인항목 추가 - 사용자정의 위험요인항목 
    ELSIF p_WRK_TP = 'Q5' THEN

        OPEN RTN_CURSOR FOR
        SELECT A.CTP_CD      -- 상위공종코드
             , ( SELECT CTP_NM FROM TQHA_CTP WHERE CTP_CD = A.CTP_CD ) AS CTP_NM    -- 공종명칭
             , A.UNT_CD      -- 단위작업코드
             , ( SELECT UNT_NM FROM TQHA_CTPUNT WHERE CTP_CD = A.CTP_CD AND UNT_CD = A.UNT_CD ) AS UNT_NM    -- 단위명칭
             , A.CHK_ITM_CD  -- 점검항목코드
             , A.CHK_ITM_NM  -- 점검항목명칭
             , A.RISK_FREQ   -- 빈도레벨(QS003)
             , A.RISK_APRV   -- 강도레벨(QS004)
             , A.RISK_CRIT   -- 위험성(공통코드 QS063)
             , A.RISK_GRD    -- 위험등급(QS024)
             , A.PRRT_REG    -- 중점등록(QS002)
             , A.IMPRV_CPLN  -- 개선대책
             , A.USE_YN      -- 단위작업사용유무
             , A.CUST_CD     -- 업체코드
             , A.USR_DEFN_YN -- 사용자정의 구분
             , A.DISS_SHP    -- 재해형태(QS036)
          FROM TQHA_CTPUNT_CHKITM A
         WHERE A.USR_DEFN_YN = '1'
           AND A.CTP_CD     = p_CTP_CD
           AND A.UNT_CD     = p_UNT_CD
           AND A.CUST_CD    = p_CUST_CD
        ;

    --------------------------------------------------------------------------------
    -- 위험성평가 평가서제출 여부 조회
    ELSIF p_WRK_TP = 'Q6' THEN

        OPEN RTN_CURSOR FOR
        SELECT SBM_YN
             , MNG_APRV_STATS
          FROM TQHA_RISK_VNDR
         WHERE SIT_CD       = p_SIT_CD
           AND PLN_DGR      = p_PLN_DGR
           AND PLN_YM       = p_PLN_YM
           AND CUST_CD      = p_CUST_CD
           AND VNDR_SEQ     = p_VNDR_SEQ
        ;

    --------------------------------------------------------------------------------
    -- 전회차복사 목록 조회
    ELSIF p_WRK_TP = 'Q7' THEN

        OPEN RTN_CURSOR FOR
        SELECT 
            A.SIT_CD          -- 현장코드
           ,A.PLN_YM                 --계획년월
           ,A.PLN_DGR                 --차수구분코드(QS005) 1 1차,2 2차
           ,A.CUST_CD                 --협력업체코드
           ,A.VNDR_SEQ                 --업체순번
           ,A.CTP_CD           -- 공종코드
           ,( SELECT CTP_NM FROM TQHA_CTP WHERE CTP_CD = A.CTP_CD ) AS CTP_NM    -- 공종명칭
           ,A.UNT_CD           -- 단위코드
           ,( SELECT UNT_NM FROM TQHA_CTPUNT WHERE CTP_CD = A.CTP_CD AND UNT_CD = A.UNT_CD ) AS UNT_NM    -- 단위명칭
           ,A.CHK_ITM_CD                 --점검항목코드
           ,A.CHK_ITM_NM                 --점검항목명
           ,A.CHK_LOC                 --점검위치
           ,A.DISS_SHP                 --재해형태(QS036)
           ,A.RISK_FREQ                 --빈도레벨(QS003)
           ,A.RISK_APRV                 --강도레벨(QS004)
           ,A.RISK_CRIT                 --위험성레벨(QS063)
           ,A.RISK_GRD                 --위험등급(QS024)
           ,A.PRRT_REG                 --중점등록(QS002) O, X
           ,A.IMPRV_CPLN                 --개선대책
           ,A.RISK_FREQ2                 --빈도레벨(QS003)
           ,A.RISK_APRV2                 --강도레벨(QS004)
           ,A.RISK_CRIT2                 --위험성레벨(QS063)
           ,A.RISK_GRD2                 --위험등급(QS024)
           ,A.MNG_SUPR                 --관리감독자
           ,A.MGR_OPIN                 --관리자의견
           ,( SELECT USR_NM FROM TCOZ_USR_INFO WHERE USR_ID = A.MNG_SUPR ) AS MNG_SUPR_NM  -- 관리감독자성명
           ,A.RISK_FREQ3                 --빈도레벨(QS003)
           ,A.RISK_APRV3                 --강도레벨(QS004)
           ,A.RISK_CRIT3                 --위험성레벨(QS063)
           ,A.RISK_GRD3                 --위험등급(QS024)
           ,A.SAFT_MGR                 --안전관리자
           ,A.SAFT_OPIN                 --안전의견
           ,( SELECT USR_NM FROM TCOZ_USR_INFO WHERE USR_ID = A.SAFT_MGR ) AS SAFT_MGR_NM  -- 안전관리자성명
           ,A.RISK_FREQ4                 --빈도레벨(QS003)
           ,A.RISK_APRV4                 --강도레벨(QS004)
           ,A.RISK_CRIT4                 --위험성레벨(QS063)
           ,A.RISK_GRD4                 --위험등급(QS024)
           ,A.SITE_OMGR                 --현장소장
           ,A.SITE_OPIN                 --현장소장의견
           ,( SELECT USR_NM FROM TCOZ_USR_INFO WHERE USR_ID = A.SITE_OMGR ) AS SITE_OMGR_NM -- 현장소장성명
           ,A.RISK_FREQ5                 --빈도레벨(QS003)
           ,A.RISK_APRV5                 --강도레벨(QS004)
           ,A.RISK_CRIT5                 --위험성레벨(QS063)
           ,A.RISK_GRD5                 --위험등급(QS024)
           ,A.RISK_FREQ6                 --빈도레벨(QS003)
           ,A.RISK_APRV6                 --강도레벨(QS004)
           ,A.RISK_CRIT6                 --위험성레벨(QS063)
           ,A.RISK_GRD6                 --위험등급(QS024)
           ,A.WRK_PSNNO                 --작업인원
           ,A.MA_PSN                 --조치자
           ,A.MA_CNFR                 --확인자
           ,( SELECT USR_NM FROM TCOZ_USR_INFO WHERE USR_ID = A.MA_CNFR ) AS MA_CNFR_NM  -- 확인자성명
           ,A.WRK_STR_DT                 --작업시작일자
           ,A.WRK_END_DT                 --작업종료일자
           ,A.IMPRV_STR_DT                 --개선시작일자
           ,A.IMPRV_END_DT                 --개선종료일자
           ,(SELECT DECODE(COUNT(1),0,'중흥','협력사') FROM TQHA_VNDR WHERE SIT_CD = A.SIT_CD AND VNDR_PSN_ID = A.IPT_ID) AS REG_DIV
          FROM TQHA_RISK_CHK A
         WHERE A.SIT_CD     = p_SIT_CD
           AND A.PLN_YM     = p_PLN_YM
           AND A.PLN_DGR    = p_PLN_DGR
           AND A.CUST_CD    = p_CUST_CD
           AND A.VNDR_SEQ   = p_VNDR_SEQ
           AND A.PRRT_REG   <>  '1'
        ;

    --------------------------------------------------------------------------------
    -- SMS 처리 ( 협력업체 평가서 제출 )
    ELSIF p_WRK_TP = 'Q8' THEN

        OPEN RTN_CURSOR FOR
        -- SMS 처리 ( 협력업체 평가서 제출 )
       --SELECT A.SIT_CD, A.PLN_YM, A.PLN_DGR, A.CUST_CD, A.VNDR_SEQ, A.MA_CNFR, REPLACE(B.MP_NO, '-', '') MP_NO
       ---- REPLACE(SYS.PKG_CRYPTO_DEC.DECRYPT(B.MP_NO), '-', '') MP_NO
       --FROM ( -- 협력업체 위험성평가 제출 시 확인자 리스트
       --        SELECT SIT_CD, PLN_YM, PLN_DGR, CUST_CD, VNDR_SEQ, MA_CNFR
       --        FROM TQHA_RISK_CHK
       --        WHERE SIT_CD = {SIT_CD}      -- 변수(현장)
       --          AND PLN_YM = {PLN_YM}        -- 변수(평가년월)
       --          AND PLN_DGR = {PLN_DGR}      -- 변수(차수)
       --          AND CUST_CD = {CUST_CD}      -- 변수(업체코드)
       --          AND VNDR_SEQ = {VNDR_SEQ}    -- 변수(업체순번)
       --        GROUP BY SIT_CD, PLN_YM, PLN_DGR, CUST_CD, VNDR_SEQ, MA_CNFR
       --    ) A,
       --    TCOZ_USR_INFO B
       --WHERE A.SIT_CD = B.DEPT_CD
       -- AND A.MA_CNFR = B.USR_ID
        SELECT A.SIT_CD
             , A.PLN_YM
             , A.PLN_DGR
             , A.CUST_CD
             , A.VNDR_SEQ
             , C.MGR_1                      AS MA_CNFR
             , REPLACE(B.MP_NO, '-', '')    AS MP_NO
             -- REPLACE(SYS.PKG_CRYPTO_DEC.DECRYPT(B.MP_NO), '-', '') MP_NO
          FROM (-- 협력업체 위험성평가 제출 시 확인자 리스트
                SELECT SIT_CD
                     , PLN_YM
                     , PLN_DGR
                     , CUST_CD
                     , VNDR_SEQ
                  FROM TQHA_RISK_CHK
                 WHERE SIT_CD   = p_SIT_CD     -- 변수(현장)
                   AND PLN_YM   = p_PLN_YM        -- 변수(평가년월)
                   AND PLN_DGR  = p_PLN_DGR     -- 변수(차수)
                   AND CUST_CD  = p_CUST_CD
                   AND VNDR_SEQ = p_VNDR_SEQ
                 GROUP 
                    BY SIT_CD
                     , PLN_YM
                     , PLN_DGR
                     , CUST_CD
                     , VNDR_SEQ
               ) A
               JOIN (
                               SELECT SIT_CD, MGR_1 FROM TQHA_VNDR WHERE SIT_CD = P_SIT_CD AND CUST_CD = p_CUST_CD AND VNDR_SEQ = p_VNDR_SEQ AND NVL(MGR_1, '*') != '*'
                     UNION ALL SELECT SIT_CD, MGR_2 FROM TQHA_VNDR WHERE SIT_CD = P_SIT_CD AND CUST_CD = p_CUST_CD AND VNDR_SEQ = p_VNDR_SEQ AND NVL(MGR_2, '*') != '*'
                     UNION ALL SELECT SIT_CD, MGR_3 FROM TQHA_VNDR WHERE SIT_CD = P_SIT_CD AND CUST_CD = p_CUST_CD AND VNDR_SEQ = p_VNDR_SEQ AND NVL(MGR_3, '*') != '*'
                    ) C  ON A.SIT_CD = C.SIT_CD
               JOIN TCOZ_USR_INFO B ON C.SIT_CD = B.DEPT_CD
                                   AND C.MGR_1  = B.USR_ID
        ;

    END IF;


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
         WHEN OTHERS THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);

END PQHA_RISK_SCHD_MNG_CO_Q ;
/

-- PQHA_RISK_SCHD_REG_OTHER_Q (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_RISK_SCHD_REG_OTHER_Q" (
    p_WRK_TP            IN VARCHAR2 DEFAULT 'Q'         -- FLAG
,   p_SIT_CD            IN VARCHAR2                     -- 현장코드
,   p_APRS_STR_DT       IN VARCHAR2                     -- 시작일
,   p_APRS_END_DT       IN VARCHAR2                     -- 종료일
,   p_PLN_YM            IN VARCHAR2                     -- 계획연월
,   p_PLN_DGR           IN VARCHAR2                     -- 계획차수
,   p_COP_VNDR          IN VARCHAR2                     -- 업체코드
,   p_VNDR_SEQ          IN VARCHAR2                     -- 업체순번
,   RTN_CURSOR          OUT SYS_REFCURSOR
)
IS 
    /**************************************************************************************************************************
      Purpose : [수시위험성평가계획] PROCEDRE 

      REVISIONS 
      Ver      Date               Author                  Description
      -------  -----------------  ----------------------  ---------------------------------------------------------------------
      1.0      2026/02/09                                 최초생성

    **************************************************************************************************************************/

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE  NUMBER :=-20009; -- ERROR 코드
    ERR_MSG   VARCHAR(200);    -- ERROR Message
    USER_EXCEPTION EXCEPTION;

BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 수행전 Check Logic ]
    ---------------------------------------------------------------------------------------------------------------------------

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Logic 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------

    ---------------------------------------------------------------------------------------
    -- 
    IF p_WRK_TP = 'Q1' THEN

        -- 위험성평가 일정관리 - 대상업체지정
        OPEN RTN_CURSOR FOR
         SELECT NVL(B.OBJ_YN,0) AS OBJ_YN    -- 대상여부
              , CASE WHEN NVL(B.OBJ_YN, 0) = 0 THEN 1
                     WHEN NVL(B.OBJ_YN, 0) = 1 THEN 0
                 END      AS DEL_YN         -- 제외여부
              , A.CUST_CD AS COP_VNDR       -- 협력업체코드
              , C.CUST_NM                   -- 업체명칭
              , A.VNDR_NM                   -- 공사명
              , A.VNDR_PSN_NM               -- 협력업체담당자
              , A.VNDR_STR_DT               -- 공사시작일
              , A.VNDR_END_DT               -- 공사종료일
              , A.VNDR_SEQ                  -- 최종계약차수
           FROM TQHA_VNDR A
              , TQHA_RISK_VNDR B
              , VQSZ_TRADE C
          WHERE A.SIT_CD        = p_SIT_CD
            AND (( TO_DATE(A.VNDR_STR_DT, 'YYYYMMDD') <= TO_DATE(p_APRS_STR_DT, 'YYYYMMDD') AND TO_DATE(A.VNDR_END_DT, 'YYYYMMDD') >= TO_DATE(p_APRS_END_DT, 'YYYYMMDD')) 
                  OR NVL(B.OBJ_YN, 0) = 1
                )
            -- 변수 처리(평가시작일,  평가종료일)
            AND A.SIT_CD        = B.SIT_CD(+)
            AND A.CUST_CD       = B.CUST_CD(+)
            AND A.VNDR_SEQ      = B.VNDR_SEQ(+)
            AND A.CUST_CD       = C.CUST_CD(+)
            AND B.PLN_YM(+)     = p_PLN_YM
            AND B.PLN_DGR(+)    = p_PLN_DGR
        ;

    ---------------------------------------------------------------------------------------
    ELSIF p_WRK_TP = 'Q2' THEN

        -- 대상업체 담당자 번호 조회
        OPEN RTN_CURSOR FOR
        SELECT VNDR_PSN_NM      -- 담당자명
             , VNDR_PSN_CADDR   -- 담당자 번호
          FROM TQHA_VNDR
         WHERE SIT_CD   = p_SIT_CD
           AND CUST_CD  = p_COP_VNDR
           AND VNDR_SEQ = p_VNDR_SEQ
        ;

    ---------------------------------------------------------------------------------------
    ELSIF p_WRK_TP = 'Q3' THEN

        -- 대상업체지정 - 공사기간변경 (협력업체)
        OPEN RTN_CURSOR FOR
        SELECT A.SIT_CD                 -- 현장코드
             , A.CUST_CD                -- 업체코드
             , B.CUST_NM                -- 업체명
             , B.BZMN_NO                -- 사업자번호
             , A.VNDR_SEQ               -- 업체순번
             , A.VNDR_NM                -- 공사명
             , A.VNDR_STR_DT            -- 공사시작일
             , A.VNDR_END_DT            -- 공사종료일
          FROM TQHA_VNDR A
             , VQSZ_TRADE B
         WHERE A.CUST_CD = B.CUST_CD(+)
           AND SIT_CD    = p_SIT_CD
        ;

    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
         WHEN OTHERS THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);

END PQHA_RISK_SCHD_REG_OTHER_Q;
/

-- PQHA_RISK_VNDR_ATFL_S (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_RISK_VNDR_ATFL_S" (
    p_WRK_TP                VARCHAR2 :='U'                          -- UPDATE FLAG( I: ISNERT, U:UPDATE, D:DELTE)
,   p_WRK_ID                VARCHAR2                                -- 사용자 ID 
