,   p_CUST_CD               TQHA_RISK_VNDR.CUST_CD%TYPE             -- 업체코드
,   p_VNDR_SEQ              TQHA_RISK_VNDR.VNDR_SEQ%TYPE            -- 업체순번
,   p_CHK_ATFL_GRP          TQHA_RISK_VNDR.CHK_ATFL_GRP%TYPE        -- 점검첨부파일그룹
)
IS 
    /**************************************************************************************************************************
      Purpose :  

      REVISIONS
      Ver      Date               Author                  Description 
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2026/03/03                                    최초생성

    **************************************************************************************************************************/


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR2(200);            -- ERROR Message
    USER_EXCEPTION EXCEPTION;

BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 필수입력 필드  Check  ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_SIT_CD IS NULL)  THEN
        ERR_MSG := '현장코드는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_PLN_YM IS NULL)  THEN
        ERR_MSG := '계획년월는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_PLN_DGR IS NULL)  THEN
        ERR_MSG := '차수구분코드는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_CUST_CD IS NULL)  THEN
        ERR_MSG := '업체코드는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_VNDR_SEQ IS NULL)  THEN
        ERR_MSG := '업체순번는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Process 선행조건 Check ]
    ---------------------------------------------------------------------------------------------------------------------------

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Business Process ]
    ---------------------------------------------------------------------------------------------------------------------------
    -- 
    IF p_WRK_TP = 'U' THEN

        UPDATE TQHA_RISK_VNDR
           SET CHK_ATFL_GRP     = p_CHK_ATFL_GRP
             , UPD_ID           = p_WRK_ID
             , UPD_DTM          = SYSDATE
             , UPD_IP           = p_WRK_IP
         WHERE SIT_CD           = p_SIT_CD
           AND PLN_YM           = p_PLN_YM
           AND PLN_DGR          = p_PLN_DGR
           AND CUST_CD          = p_CUST_CD
           AND VNDR_SEQ         = p_VNDR_SEQ
        ;

    END IF; 

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 5. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN 
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);
END ;
/

-- PQHA_RISK_VNDR_S (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_RISK_VNDR_S" (
    p_WRK_TP                VARCHAR2 :='U'                                          -- UPDATE FLAG( I: ISNERT, U:UPDATE, D:DELTE)
,   p_WRK_ID                VARCHAR2                                                -- 사용자 ID 
,   p_WRK_IP                VARCHAR2                                                -- 사용자 IP 
,   p_WRK_DIV               VARCHAR2                                                -- 작업구분
,   p_SIT_CD                TQHA_RISK_VNDR.SIT_CD                   %TYPE           -- 현장코드
,   p_PLN_YM                TQHA_RISK_VNDR.PLN_YM                   %TYPE           -- 계획년월
,   p_PLN_DGR               TQHA_RISK_VNDR.PLN_DGR                  %TYPE           -- 차수구분코드(QS005) 1 1차,2 2차
,   p_CUST_CD               TQHA_RISK_VNDR.CUST_CD                  %TYPE           -- 업체코드
,   p_VNDR_SEQ              TQHA_RISK_VNDR.VNDR_SEQ                 %TYPE           -- 업체순번
,   p_SBM_YN                TQHA_RISK_VNDR.SBM_YN                   %TYPE           -- 제출Y 
,   p_SBM_DT                TQHA_RISK_VNDR.SBM_DT                   %TYPE           -- 평가서제출일자
,   p_MNG_SUPR              TQHA_RISK_VNDR.MNG_SUPR                 %TYPE           -- 관리감독자
,   p_MNG_APRV_DT           TQHA_RISK_VNDR.MNG_APRV_DT              %TYPE           -- 관리승인일자
,   p_MNG_APRV_STATS        TQHA_RISK_VNDR.MNG_APRV_STATS           %TYPE           -- 승인 1, 반려 2
,   p_SAFT_MGR              TQHA_RISK_VNDR.SAFT_MGR                 %TYPE           -- 안전관리자
,   p_SAFT_APRV_DT          TQHA_RISK_VNDR.SAFT_APRV_DT             %TYPE           -- 안전승인일자
,   p_SAFT_APRV_STATS       TQHA_RISK_VNDR.SAFT_APRV_STATS          %TYPE           -- 승인 1, 반려 2
,   p_SITE_OMGR             TQHA_RISK_VNDR.SITE_OMGR                %TYPE           -- 현장소장
,   p_SITE_APRV_DT          TQHA_RISK_VNDR.SITE_APRV_DT             %TYPE           -- 소장승인일자
,   p_SITE_APRV_STATS       TQHA_RISK_VNDR.SITE_APRV_STATS          %TYPE           -- 승인 1, 반려 2
,   p_CHK_ATFL_GRP          TQHA_RISK_VNDR.CHK_ATFL_GRP             %TYPE           -- 점검첨부파일그룹
,   p_OBJ_YN                TQHA_RISK_VNDR.OBJ_YN                   %TYPE           -- 대상여부 (1 대상, 0 미대상)  
,   p_VNDR_NOTI_YN          TQHA_RISK_VNDR.VNDR_NOTI_YN             %TYPE           -- 발송여부 (1 발송, 0 미발송)
,   p_VNDR_SEND_DT          TQHA_RISK_VNDR.VNDR_SEND_DT             %TYPE           -- 발송일자 
,   p_DEL_YN                INTEGER                                                 -- 제외여부
)
IS  
    /**************************************************************************************************************************
      Purpose : 

      REVISIONS
      Ver      Date               Author                  Description 
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2021/10/27 14:15:34                         최초생성

    **************************************************************************************************************************/


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR2(200);            -- ERROR Message
    USER_EXCEPTION EXCEPTION;

    v_CNT NUMBER    := 0;
    v_cnt1  INTEGER := 0;                   -- 하위 데이타 존재 여부 확인

BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 필수입력 필드  Check  ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_SIT_CD IS NULL)  THEN
        ERR_MSG := '현장코드는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_PLN_YM IS NULL)  THEN
        ERR_MSG := '계획년월는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_PLN_DGR IS NULL)  THEN
        ERR_MSG := '차수구분코드는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_CUST_CD IS NULL)  THEN
        ERR_MSG := '업체코드는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_VNDR_SEQ IS NULL)  THEN
        ERR_MSG := '업체순번는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Process 선행조건 Check ]
    ---------------------------------------------------------------------------------------------------------------------------

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Business Process ] 
    ---------------------------------------------------------------------------------------------------------------------------
    -- 위험성평가일정관리 - 대상업체지정인 경우
    IF (p_WRK_DIV = 'RISK_SCHD_MNG') THEN

        -- [1] 삭제 로직 (p_DEL_YN = '1'인 경우 우선 처리)
        IF (p_DEL_YN = '1') THEN

            -- 하위 데이터가 존재하는지 체크 (TQHA_RISK_CHK)
            SELECT NVL(COUNT(CUST_CD), 0) 
              INTO v_cnt1
              FROM TQHA_RISK_CHK
             WHERE SIT_CD   = p_SIT_CD
               AND PLN_YM   = p_PLN_YM
               AND PLN_DGR  = p_PLN_DGR
               AND CUST_CD  = p_CUST_CD
               AND VNDR_SEQ = p_VNDR_SEQ
            ;

            IF v_cnt1 > 0 THEN
                ERR_MSG := '협력업체 코드 "' || p_CUST_CD || '" 은(는) 사용중입니다. 제외할 수 없습니다.';
                RAISE USER_EXCEPTION;
            ELSE
                DELETE FROM TQHA_RISK_VNDR
                 WHERE SIT_CD   = p_SIT_CD
                   AND PLN_YM   = p_PLN_YM
                   AND PLN_DGR  = p_PLN_DGR
                   AND CUST_CD  = p_CUST_CD
                   AND VNDR_SEQ = p_VNDR_SEQ
                ;
            END IF;

        -- [2] 등록/수정 로직 (p_DEL_YN = '0'인 경우)
        ELSIF (p_DEL_YN = '0') THEN

            -- 데이터가 이미 있는지 확인
            SELECT COUNT(*) INTO v_CNT
              FROM TQHA_RISK_VNDR
             WHERE SIT_CD   = p_SIT_CD
               AND PLN_YM   = p_PLN_YM
               AND PLN_DGR  = p_PLN_DGR
               AND CUST_CD  = p_CUST_CD
               AND VNDR_SEQ = p_VNDR_SEQ
            ;

            IF (v_CNT > 0) THEN

                -- 이미 있으면 업데이트 (대상여부를 1로)
                UPDATE TQHA_RISK_VNDR
                   SET OBJ_YN       = '1'
                     , UPD_ID       = p_WRK_ID
                     , UPD_DTM      = SYSDATE
                     , UPD_IP       = p_WRK_IP
                 WHERE SIT_CD       = p_SIT_CD
                   AND PLN_YM       = p_PLN_YM
                   AND PLN_DGR      = p_PLN_DGR
                   AND CUST_CD      = p_CUST_CD
                   AND VNDR_SEQ     = p_VNDR_SEQ
                ;

            ELSE

                -- 없으면 
                INSERT 
                  INTO TQHA_RISK_VNDR 
                     ( SIT_CD
                     , PLN_YM
                     , PLN_DGR
                     , CUST_CD
                     , VNDR_SEQ
                     , OBJ_YN
                     , VNDR_NOTI_YN
                     , IPT_ID
                     , IPT_DTM
                     , IPT_IP
                     , UPD_ID
                     , UPD_DTM
                     , UPD_IP
                     ) 
                VALUES 
                     ( p_SIT_CD
                     , p_PLN_YM
                     , p_PLN_DGR
                     , p_CUST_CD
                     , p_VNDR_SEQ
                     , '1'
                     , '0'
                     , p_WRK_ID
                     , SYSDATE
                     , p_WRK_IP
                     , p_WRK_ID
                     , SYSDATE
                     , p_WRK_IP
                     )
                ;

            END IF;
        END IF; 

    END IF; 


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 5. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN 
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);

END ;
/

-- PQHA_RISK_VNDR_S2 (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_RISK_VNDR_S2" (
    p_WRK_TP            VARCHAR2 :='U'                          -- UPDATE FLAG( I: ISNERT, U:UPDATE, D:DELTE)
,   p_WRK_ID            VARCHAR2                                -- 사용자 ID 
,   p_WRK_IP            VARCHAR2                                -- 사용자 IP 
,   p_SIT_CD            TQHA_VNDR.SIT_CD            %TYPE       -- 현장코드
,   p_CUST_CD           TQHA_VNDR.CUST_CD           %TYPE       -- 협력업체코드
,   p_VNDR_SEQ          TQHA_VNDR.VNDR_SEQ          %TYPE       -- 협력업체순번
,   p_VNDR_STR_DT       TQHA_VNDR.VNDR_STR_DT       %TYPE       -- 공사시작일
,   p_VNDR_END_DT       TQHA_VNDR.VNDR_END_DT       %TYPE       -- 공사종료일
)     
IS 
    /**************************************************************************************************************************
      Purpose :  

      REVISIONS
      Ver      Date               Author                  Description 
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2021/10/27 14:12:51                         최초생성

    **************************************************************************************************************************/


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR2(200);            -- ERROR Message
    USER_EXCEPTION EXCEPTION;

BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 필수입력 필드  Check  ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_SIT_CD IS NULL)  THEN
        ERR_MSG := '현장코드는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Process 선행조건 Check ]
    ---------------------------------------------------------------------------------------------------------------------------



    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Business Process ]
    ---------------------------------------------------------------------------------------------------------------------------

    BEGIN
        -- 1. 협력업체 공사 기간 업데이트
        UPDATE TQHA_VNDR
           SET VNDR_STR_DT      = p_VNDR_STR_DT     -- 공사시작일
             , VNDR_END_DT      = p_VNDR_END_DT     -- 공사종료일
         WHERE SIT_CD           = p_SIT_CD
           AND CUST_CD          = p_CUST_CD
           AND VNDR_SEQ         = p_VNDR_SEQ
        ;

        -- 2. 변경된 공사 기간에 포함되는 평가 차수들을 조회하여 일괄
        MERGE 
          INTO TQHA_RISK_VNDR T
         USING (
                SELECT PLN_YM
                     , PLN_DGR
                  FROM TQHA_RISK_DGR
                 WHERE SIT_CD = p_SIT_CD
                   -- 업체 공사기간 내에 평가기간이 포함
                   AND TO_DATE(p_VNDR_STR_DT, 'YYYYMMDD') <= TO_DATE(APRS_STR_DT, 'YYYYMMDD') 
                   AND TO_DATE(p_VNDR_END_DT, 'YYYYMMDD') >= TO_DATE(APRS_END_DT, 'YYYYMMDD')
        ) S
        ON (
                T.SIT_CD   = p_SIT_CD   
            AND T.PLN_YM   = S.PLN_YM   
            AND T.PLN_DGR  = S.PLN_DGR  
            AND T.CUST_CD  = p_CUST_CD  
            AND T.VNDR_SEQ = p_VNDR_SEQ
        )
        -- 이미 해당 차수에 업체가 등록되어 있다면 대상여부만 '1'로 업데이트
        WHEN MATCHED THEN
            UPDATE 
               SET T.OBJ_YN     = '1'
                 , T.UPD_ID     = p_WRK_ID
                 , T.UPD_DTM    = SYSDATE
                 , T.UPD_IP     = p_WRK_IP
        -- 해당 차수에 업체가 없다면 신규 입력
        WHEN NOT MATCHED THEN
            INSERT 
                 ( SIT_CD
                 , PLN_YM
                 , PLN_DGR
                 , CUST_CD
                 , VNDR_SEQ
                 , OBJ_YN
                 , VNDR_NOTI_YN
                 , IPT_ID
                 , IPT_DTM
                 , IPT_IP
                 , UPD_ID
                 , UPD_DTM
                 , UPD_IP
                 )
            VALUES 
                 ( p_SIT_CD
                 , S.PLN_YM
                 , S.PLN_DGR
                 , p_CUST_CD
                 , p_VNDR_SEQ 
                 , '1'
                 , '0'
                 , p_WRK_ID
                 , SYSDATE
                 , p_WRK_IP
                 , p_WRK_ID
                 , SYSDATE
                 , p_WRK_IP
                 )
            ;

    END;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 5. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN 
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);

END ;
/

-- PQHA_RISK_WK_MNG_Q (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_RISK_WK_MNG_Q" (
    p_WRK_TP            IN VARCHAR2 DEFAULT 'Q'         -- FLAG
,   p_CTP_CD            IN VARCHAR2                     -- 공종코드
,   RTN_CURSOR          OUT SYS_REFCURSOR
)
IS
    /**************************************************************************************************************************
      Purpose : [공종관리 ] PROCEDRE 

      REVISIONS
      Ver      Date               Author                  Description
      -------  -----------------  ----------------------  ---------------------------------------------------------------------
      1.0      2026/02/10                                 최초생성

    **************************************************************************************************************************/

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE  NUMBER :=-20009; -- ERROR 코드
    ERR_MSG   VARCHAR(200);    -- ERROR Message
    USER_EXCEPTION EXCEPTION;

BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 수행전 Check Logic ]
    ---------------------------------------------------------------------------------------------------------------------------

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Logic 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------

    ---------------------------------------------------------------------------------------
    -- 그리드 조회 : 공종관리 리스트 조회
    IF p_WRK_TP = 'Q1' THEN

        OPEN RTN_CURSOR FOR
        SELECT CTP_CD   -- 공종코드
             , CTP_NM   -- 공종명칭
             , USE_YN   -- 공종 사용유무
             , CTP_DIV  -- 공종구분(QS035)
          FROM TQHA_CTP
         ORDER BY CTP_CD
        ;

    ---------------------------------------------------------------------------------------
    -- 그리드 조회 : 공종별 단위작업 리스트 조회
    ELSIF p_WRK_TP = 'Q2' THEN

        OPEN RTN_CURSOR FOR
        SELECT CTP_CD     -- 상위공종코드
             , UNT_CD     -- 단위작업코드
             , UNT_NM     -- 단위작업명칭
             , USE_YN     -- 단위작업사용유무
          FROM TQHA_CTPUNT
         WHERE CTP_CD   = p_CTP_CD
         ORDER BY UNT_CD
        ;

    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
         WHEN OTHERS THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);

END PQHA_RISK_WK_MNG_Q;
/

-- PQHA_SAFEAPRV_AB_S (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_SAFEAPRV_AB_S" (
    p_WRK_TP                    VARCHAR2 :='A1'                                     -- A1: 허가승인 F1: 작업승인, A2: 허가반려 F2: 작업반려
,   p_SIT_CD                    TQHA_SAFE_PERREQ.SIT_CD                 %TYPE       -- 현장코드
,   p_REQ_SEQ                   TQHA_SAFE_PERREQ.REQ_SEQ                %TYPE       -- 요청순번
,   p_MNG_SUPR                  TQHA_SAFE_PERREQ.MNG_SUPR               %TYPE       -- 관리감독자
,   p_MNG_APRV_STATS            TQHA_SAFE_PERREQ.MNG_APRV_STATS         %TYPE       -- 관리승인상태
,   p_MNG_APRV_DT               TQHA_SAFE_PERREQ.MNG_APRV_DT            %TYPE       -- 관리승인일자
,   p_SAFT_MGR                  TQHA_SAFE_PERREQ.SAFT_MGR               %TYPE       -- 안전관리자
,   p_SAFT_APRV_STATS           TQHA_SAFE_PERREQ.SAFT_APRV_STATS        %TYPE       -- 안전승인상태
,   p_SAFT_APRV_DT              TQHA_SAFE_PERREQ.SAFT_APRV_DT           %TYPE       -- 안전승인일자
,   p_SITE_OMGR                 TQHA_SAFE_PERREQ.SITE_OMGR              %TYPE       -- 현장소장
,   p_SITE_APRV_STATS           TQHA_SAFE_PERREQ.SITE_APRV_STATS        %TYPE       -- 소장승인상태
,   p_SITE_APRV_DT              TQHA_SAFE_PERREQ.SITE_APRV_DT           %TYPE       -- 소장승인일자
,   p_SAFT_MA_CNF               TQHA_SAFE_PERREQ.SAFT_MA_CNF            %TYPE       -- 안전조치확인
,   p_SAFT_CMPL_YN              TQHA_SAFE_PERREQ.SAFT_CMPL_YN           %TYPE       -- 안전작업완료여부
,   p_SAFT_CMPL_DT              TQHA_SAFE_PERREQ.SAFT_CMPL_DT           %TYPE       -- 안전작업완료일자
,   p_SAFT_CMPL_TM              TQHA_SAFE_PERREQ.SAFT_CMPL_TM           %TYPE       -- 안전작업완료시간
,   p_SAFT_CMPL_CNFR            TQHA_SAFE_PERREQ.SAFT_CMPL_CNFR         %TYPE       -- 안전작업완료확인자
,   p_VNDR_YN                   TQHA_SAFE_PERREQ.SAFT_CMPL_YN           %TYPE       -- 안전허가승인요청여부/안전작업완료여부
,   p_VNDR_DT                   TQHA_SAFE_PERREQ.SAFT_CMPL_DT           %TYPE       -- 안전허가승인요청일자/안전작업완료일자
)
IS
    /**************************************************************************************************************************
      Purpose :

      REVISIONS
      Ver      Date               Author                  Description
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2022/04/27 10:31:08                         당사 허가요청 승인/반려, 작업종료 승인/반려

    **************************************************************************************************************************/

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR2(200);            -- ERROR Message
    USER_EXCEPTION EXCEPTION;

    v_SITE_APRV_STATS       VARCHAR2(10) := '0';                -- 허가승인 현장소장 승인 여부 체크
    v_SAFT_CMPL_YN          VARCHAR2(10) := '0';                -- 작업종료안전 관리자 승인 여부 체크
    v_PER_SEQ_NO            TQHA_SAFE_PERREQ.PER_NO%TYPE ;      -- 허가번호 인련번호 변수
    v_PER_NO                TQHA_SAFE_PERREQ.PER_NO%TYPE ;      -- 허가번호 변수

BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 필수입력 필드  Check  ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_SIT_CD IS NULL)  THEN
        ERR_MSG := '현장코드는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_REQ_SEQ IS NULL AND p_WRK_TP <> 'I')  THEN
        ERR_MSG := '요청순번는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    -- 허가 요청 승인 및 작업 종료 승인 여부 체크
    IF SUBSTR(p_WRK_TP,1,1) = 'A' THEN    -- 허가승인

        SELECT SITE_APRV_STATS
          INTO v_SITE_APRV_STATS
          FROM TQHA_SAFE_PERREQ
         WHERE SIT_CD   = p_SIT_CD        -- 현장코드
           AND REQ_SEQ  = p_REQ_SEQ       -- 요청순번
        ;

        -- 현장소장 승인된 경우 제출 및 취소 불가
        IF v_SITE_APRV_STATS = '1' THEN
            ERR_MSG := '해당 허가작업 승인(은) 현장소장이 승인한 상태이므로 승인 및 반려가 불가합니다. ';
            RAISE USER_EXCEPTION;
        END IF;

    ELSIF SUBSTR(p_WRK_TP,1,1) = 'F' THEN    -- 작업종료요청

        SELECT SAFT_CMPL_YN
          INTO v_SAFT_CMPL_YN
          FROM TQHA_SAFE_PERREQ
         WHERE SIT_CD       = p_SIT_CD          -- 현장코드
           AND REQ_SEQ      = p_REQ_SEQ         -- 요청순번
        ;

        -- 작업 죨료 안전 관리자 승인된 경우 제출 및 취소 불가
        IF v_SAFT_CMPL_YN = '1' THEN
           ERR_MSG := '해당 작업완료 승인(은) 안전 관리자가 승인한 상태이므로 작업완료 승인 및 반려가  불가합니다. ';
           RAISE USER_EXCEPTION;
        END IF;

    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Process 선행조건 Check ]
    ---------------------------------------------------------------------------------------------------------------------------
    -- 허가 요청 승인 및 작업 종료 승인 여부 체크
    IF SUBSTR(p_WRK_TP,1,1) = 'A' THEN    -- 허가승인/허가반려 UPDATE

        IF (SUBSTR(p_WRK_TP,2,1) = '1' AND p_SITE_APRV_STATS = '1') THEN    -- 허가승인

            -- 허가 번호 생성
            SELECT LPAD(NVL(MAX(SUBSTR(PER_NO, 10, 4)), 0) + 1, 4,'0')
              INTO v_PER_SEQ_NO
              FROM TQHA_SAFE_PERREQ
             WHERE SIT_CD = p_SIT_CD
               AND SUBSTR(PER_NO,5,4) = SUBSTR(p_SITE_APRV_DT,1,4) 
            ;

            v_PER_NO := 'SWL-' || SUBSTR(p_SITE_APRV_DT,1,4) || '-' || v_PER_SEQ_NO ;  -- 허가번호 생성

        ELSE -- 허가반려

            v_PER_NO := '' ;  -- 허가번호 반려

        END IF ;

        UPDATE TQHA_SAFE_PERREQ
           SET VNDR_APRV_YN         = p_VNDR_YN             -- 업체허가요청여부
             , VNDR_APRV_DT         = p_VNDR_DT             -- 업체허가요청일자
             , MNG_SUPR             = p_MNG_SUPR            -- 관리감독자
             , MNG_APRV_STATS       = p_MNG_APRV_STATS      -- 관리감독자 승인상태
             , MNG_APRV_DT          = p_MNG_APRV_DT         -- 관리감독자 승인일자
             , SAFT_MGR             = p_SAFT_MGR            -- 안전관리자
             , SAFT_APRV_STATS      = p_SAFT_APRV_STATS     -- 안전관리자 승인상태
             , SAFT_APRV_DT         = p_SAFT_APRV_DT        -- 안전관리자 승인일자
             , SITE_OMGR            = p_SITE_OMGR           -- 현장소장
             , SITE_APRV_STATS      = p_SITE_APRV_STATS     -- 현장소장 승인상태
             , SITE_APRV_DT         = p_SITE_APRV_DT        -- 현장소장 승인일자
             , PER_NO               = v_PER_NO              -- 허가번호
             , SAFT_MA_CNF          = p_SAFT_MA_CNF         -- 안전조치확인
         WHERE SIT_CD               = p_SIT_CD
           AND REQ_SEQ              = p_REQ_SEQ  ;


    ELSIF SUBSTR(p_WRK_TP,1,1) = 'F' THEN    -- 작업종료승인/반려 UPDATE

        UPDATE TQHA_SAFE_PERREQ
           SET VNDR_CMPL_YN         = p_VNDR_YN             -- 업체작업완료요청여부
             , SAFT_CMPL_YN         = p_SAFT_CMPL_YN        -- 안전작업완료확인여부
             , SAFT_CMPL_DT         = p_SAFT_CMPL_DT        -- 안전작업완료확인일자
             , SAFT_CMPL_TM         = p_SAFT_CMPL_TM        -- 안전작업완료확인시간
             , SAFT_CMPL_CNFR       = p_SAFT_CMPL_CNFR      -- 안전작업완료확인자
             , SAFT_MA_CNF          = p_SAFT_MA_CNF         -- 안전조치확인
         WHERE SIT_CD               = p_SIT_CD
           AND REQ_SEQ              = p_REQ_SEQ 
        ;

    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 5. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);

END ;
/

-- PQHA_SAFECOST_APRV_ATFL_S (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_SAFECOST_APRV_ATFL_S" (
    p_WRK_TP            VARCHAR2 :='U'      -- UPDATE FLAG( I: ISNERT, U:UPDATE, D:DELTE)
,   p_WRK_ID            VARCHAR2            -- 사용자 ID 
,   p_WRK_IP            VARCHAR2            -- 사용자 IP 
,   p_SIT_CD            VARCHAR2            -- 현장코드
,   p_APRV_DIV          VARCHAR2            -- 결재구분
,   p_APRV_YM           VARCHAR2            -- 결재년월
,   p_ATFL_GRP          VARCHAR2            -- 첨부파일
)
IS 
    /**************************************************************************************************************************
      Purpose : 

      REVISIONS
      Ver      Date               Author                  Description 
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2026/02/12                                   최초생성

    **************************************************************************************************************************/

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR2(200);            -- ERROR Message
    USER_EXCEPTION EXCEPTION;

    v_APRV_STATS        VARCHAR2(20);
    v_APRV_STATS_NM     VARCHAR2(50);

BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 필수입력 필드  Check  ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_SIT_CD IS NULL)  THEN
        ERR_MSG := '현장코드는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_APRV_DIV IS NULL)  THEN
        ERR_MSG := '결재구분은 필수 입력사항 입니다.'; 
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_APRV_YM IS NULL)  THEN
        ERR_MSG := '결재년월은 필수 입력사항 입니다.'; 
        RAISE USER_EXCEPTION;
    END IF;

    ---------------------------------------------------------------------
    -- 결재상태 체크
    SELECT MAX(T2.APRV_STATS)
         , MAX(T3.CD_NM )
      INTO v_APRV_STATS
         , v_APRV_STATS_NM
      FROM TQHA_SAFECOST_APRV   T1
      LEFT JOIN TQHA_APRV       T2 ON T1.SIT_CD     = T2.SIT_CD
                                  AND T1.APRV_NO    = T2.APRV_NO
      LEFT JOIN TCOA_COMCODE    T3 ON T2.APRV_STATS = T3.COM_CD 
                                  AND T3.HRNK_CD    = 'QS031'
     WHERE T1.SIT_CD    = p_SIT_CD
       AND T1.APRV_DIV  = '2'       -- 월별실적.
       AND T1.APRV_YM   = p_APRV_YM
    ;

    IF v_APRV_STATS IN ('2', '4') THEN
        ERR_MSG := '결재상태 [' || v_APRV_STATS_NM || ']인 데이터는 수정 불가합니다.';
        RAISE USER_EXCEPTION;
    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Process 선행조건 Check ]
    ---------------------------------------------------------------------------------------------------------------------------



    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Business Process ]
    ---------------------------------------------------------------------------------------------------------------------------

    ----------------------------------------------------------------------------------------------------
    -- 월별실적관리) : 첨부파일 저장 .
    IF (p_WRK_TP ='U') THEN

        MERGE 
          INTO TQHA_SAFECOST_APRV A
        USING DUAL
        ON (    A.SIT_CD        = p_SIT_CD
            AND A.APRV_DIV      = p_APRV_DIV
            AND A.APRV_YM       = p_APRV_YM
           )
        WHEN MATCHED THEN
            UPDATE
               SET ATFL_GRP     = p_ATFL_GRP
                 , UPD_ID       = p_WRK_ID
                 , UPD_DTM      = SYSDATE
                 , UPD_IP       = p_WRK_IP
        WHEN NOT MATCHED THEN
            INSERT 
                 ( SIT_CD
                 , APRV_DIV
                 , APRV_YM
                 , ATFL_GRP
                 , IPT_ID
                 , IPT_DTM
                 , IPT_IP
                 )
            VALUES 
                 ( p_SIT_CD
                 , p_APRV_DIV
                 , p_APRV_YM
                 , p_ATFL_GRP
                 , p_WRK_ID
                 , SYSDATE
                 , p_WRK_IP
                 )
        ;

    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 5. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN 
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);
END ;
/

-- PQHA_SAFECOST_APRV_Q (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_SAFECOST_APRV_Q" (
    p_WRK_TP        VARCHAR2 DEFAULT 'Q'        -- FLAG( Q1: 도급정보, Q2:안전관리비 정보, Q3:월별실적 목록 )
,   p_SIT_CD        VARCHAR2                    -- 현장코드
,   p_RLV_YM        VARCHAR2                    -- 결재년월
,   RTN_CURSOR      OUT SYS_REFCURSOR  
)
IS 
    /**************************************************************************************************************************
      Purpose : QSE > 산업안전관리비 결재 정보 조회

      REVISIONS
      Ver      Date               Author                  Description 
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2026/02/26                                    최초생성

    **************************************************************************************************************************/

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR2(200);            -- ERROR Message
    USER_EXCEPTION EXCEPTION; 


BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 수행전 Check Logic ]
    ---------------------------------------------------------------------------------------------------------------------------


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Logic 처리
    ---------------------------------------------------------------------------------------------------------------------------
    -- 실행예산관리 결재정보 조회  get_SafeCostAprv
    IF (p_WRK_TP = 'Q') THEN

        OPEN RTN_CURSOR FOR
        SELECT A.APRV_NO    APRV_NO    -- 결재번호
             , B.APRV_STATS APRV_STATS -- 결재상태
             , B.DOC_KEY    DOC_KEY    -- 결재문서번호
          FROM TQHA_SAFECOST_APRV A
             , TCOF_APPROVE B
         WHERE A.APRV_NO    = B.APRV_NO(+)
           AND A.SIT_CD     = p_SIT_CD
           AND A.APRV_DIV   = '1'
        ;

    -----------------------------------------------------------------
    -- get_SafeCostAprv2                           
    -----------------------------------------------------------------
    ELSIF (p_WRK_TP = 'Q2') THEN

        OPEN RTN_CURSOR FOR
        SELECT A.APRV_NO    APRV_NO    -- 결재번호
             , A.SIT_CD     SIT_CD     -- 현장코드
         FROM TQHA_SAFECOST_APRV A
            , TQHA_APRV B
        WHERE A.APRV_NO     = B.APRV_NO(+)
          AND A.SIT_CD      = B.SIT_CD(+)
          AND A.SIT_CD      = p_SIT_CD
          AND A.APRV_DIV    = '2'
          AND A.APRV_YM     = p_RLV_YM
          ;

       END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN 
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);
END ;
/

-- PQHA_SAFECOST_APRV_S (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_SAFECOST_APRV_S" (
    p_WRK_TP            VARCHAR2 :='U'                                  -- UPDATE FLAG( I: ISNERT, U:UPDATE, D:DELTE)
,   p_WRK_ID            VARCHAR2                                        -- 사용자 ID 
,   p_WRK_IP            VARCHAR2                                        -- 사용자 IP 
,   p_SIT_CD            TQHA_SAFECOST_APRV.SIT_CD           %TYPE       -- 현장코드
,   p_APRV_DIV          TQHA_SAFECOST_APRV.APRV_DIV         %TYPE       -- 1: 예산, 2 월별실적
,   p_APRV_YM           TQHA_SAFECOST_APRV.APRV_YM          %TYPE       -- 결재년월 
,   p_APRV_NO           TQHA_SAFECOST_APRV.APRV_NO          %TYPE       -- 결재번호
)
IS 
    /**************************************************************************************************************************
      Purpose : 안전관리비 월별실적 결재정보 생성

      REVISIONS
      Ver      Date               Author                  Description 
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2021/12/13 18:25:14                         최초생성

    **************************************************************************************************************************/


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR2(200);            -- ERROR Message
    USER_EXCEPTION EXCEPTION;


BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 필수입력 필드  Check  ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_SIT_CD IS NULL)  THEN
        ERR_MSG := '현장코드는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_APRV_DIV IS NULL)  THEN
        ERR_MSG := '1: 예산, 2 월별실적는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_APRV_YM IS NULL)  THEN
        ERR_MSG := '결재년월는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Process 선행조건 Check ]
    ---------------------------------------------------------------------------------------------------------------------------



    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Business Process ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_WRK_TP ='D') THEN

        DELETE 
          FROM TQHA_SAFECOST_APRV
         WHERE SIT_CD       = p_SIT_CD          -- 현장코드
           AND APRV_DIV     = p_APRV_DIV        -- 1: 예산, 2 월별실적
           AND APRV_YM      = p_APRV_YM         -- 결재년월
        ;

    ELSIF (p_WRK_TP ='U') THEN

        UPDATE TQHA_SAFECOST_APRV
           SET APRV_NO              = p_APRV_NO                 --결재번호
             , UPD_ID               = p_WRK_ID                  --수정ID 
             , UPD_DTM              = SYSDATE()                 --수정일시
             , UPD_IP               = p_WRK_IP                  --수정IP
         WHERE SIT_CD               = p_SIT_CD         --현장코드
           AND APRV_DIV             = p_APRV_DIV        --1: 예산, 2 월별실적
           AND APRV_YM              = p_APRV_YM        --결재년월
        ;

    ELSE

        INSERT 
          INTO TQHA_SAFECOST_APRV
             ( SIT_CD               -- 현장코드
             , APRV_DIV             -- 1: 예산, 2 월별실적
             , APRV_YM              -- 결재년월
             , APRV_NO              -- 결재번호
             , IPT_ID               -- 입력ID
             , IPT_DTM              -- 입력일시
             , IPT_IP               -- 입력IP
             , UPD_ID               -- 수정ID
             , UPD_DTM              -- 수정일시
             , UPD_IP               -- 수정IP
             )
        VALUES 
             ( p_SIT_CD             -- 현장코드
             , p_APRV_DIV           -- 1: 예산, 2 월별실적
             , p_APRV_YM            -- 결재년월
             , p_APRV_NO            -- 결재번호
             , p_WRK_ID             -- 입력ID 
             , SYSDATE()            -- 입력일시
             , p_WRK_IP             -- 입력IP
             , p_WRK_ID             -- 수정ID
             , SYSDATE()            -- 수정일시
             , p_WRK_IP             -- 수정IP
             )
        ;

    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 5. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN 
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);
END ;
/

-- PQHA_SAFECOST_ARSLT_CO_DIV_Q (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_SAFECOST_ARSLT_CO_DIV_Q" (
    p_WRK_TP            IN VARCHAR2 DEFAULT 'Q'             -- FLAG(Q: 현장평가, Q1:본사평가)
,   p_SIT_CD            IN VARCHAR2
,   p_ITM_DIV           IN VARCHAR2                         -- 안전 9대항목  01 안전보건관리자 입금 02 안전시설비 03 보호구 04 안전보건진단비 05 안전보건 교육비 06 근조자 건강장해예방비  07기술지도비 08 본사점담조직  09 위험성평가에 다른 소모비용
,   p_RLV_YM            IN VARCHAR2                         -- 변수(년월)
,   p_CUST_CD           IN VARCHAR2                         -- 변수 (업체코드)
,   p_VNDR_SEQ          IN VARCHAR2                         -- 변수 (업체순번)
,   RTN_CURSOR       OUT SYS_REFCURSOR
)
IS
    /**************************************************************************************************************************
      Purpose : 산업안전보건관리비 : 협력업체 항목별 사용내역 조회

      REVISIONS
      Ver      Date               Author                  Description
      -------  -----------------  ----------------------  ---------------------------------------------------------------------
      1.0      2026/02/26                                 최초생성

    **************************************************************************************************************************/

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE  NUMBER :=-20009; -- ERROR 코드
    ERR_MSG   VARCHAR(200);    -- ERROR Message
    USER_EXCEPTION EXCEPTION;

BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 수행전 Check Logic ]
    ---------------------------------------------------------------------------------------------------------------------------

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Logic 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    -- 협력업체 매월 사용실적 조회 ( 1 안전보건관리자 입금 )
    IF p_ITM_DIV = '01' THEN

        OPEN RTN_CURSOR FOR
        SELECT SIT_CD               -- 현장코드
             , ITM_DIV              -- 항목구분 (공통코드 QS026)
             , (SELECT CD_NM FROM TCOA_COMCODE WHERE COM_CD = ITM_DIV AND HRNK_CD = 'QS026') AS ITM_DIV_NM
             , RLV_YM               -- 해당년월
             , USE_SEQ              -- 사용순번
             , BLN_18               -- 소속
             , PNM_18               -- 성명
             , PRCR_DT_18           -- 선임일자
             , USE_AMT              -- 사용금액(지급금액)
             , USE_DT               -- 사용일자(지급일자)
             , USE_DTLS             -- 사용내역(지급내역)
             , RMKS                 -- 비고
             , GRP_PHOTO_1          -- 첨부파일그룹1
             , PHOTO_DESC_1         -- 사진설명1
             , CUST_CD              -- 업체코드
             , VNDR_SEQ             -- 업체순번
             , DLV_VNDR             -- 납품업체
             , CASE WHEN (SELECT COUNT(*) FROM TCOZ_ATFL WHERE ATFL_GRP = GRP_PHOTO_1 OR ATFL_GRP = GRP_PHOTO_2) > 0 THEN 'O' ELSE 'X' END AS ATFL_GRP_YN
             , GRP_PHOTO_2          -- 첨부파일그룹2
