             , DLV_VNDR             -- 거래납품업체
          FROM TQHA_SAFECOST_ARSLT_CO
         WHERE SIT_CD       = p_SIT_CD          -- 변수(현장코드)
           AND ITM_DIV      = p_ITM_DIV         -- 안전 9대항목  01 안전보건관리자 입금 02 안전시설비 03 보호구 04 안전보건진단비 05 안전보건 교육비 06 근조자 건강장해예방비  07기술지도비 08 본사점담조직  09 위험성평가에 다른 소모비용
           AND RLV_YM       = p_RLV_YM          -- 변수(년월)
           AND CUST_CD      = p_CUST_CD         -- 변수 (업체코드)
           AND VNDR_SEQ     = p_VNDR_SEQ        -- 변수 (업체순번)
         ORDER BY ITM_DIV, USE_DT
        ;

    END IF;


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
         WHEN OTHERS THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);

END PQHA_SAFECOST_ARSLT_CO_DIV_Q ;
/

-- PQHA_SAFECOST_ARSLT_CO_Q (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_SAFECOST_ARSLT_CO_Q" (  
    p_WRK_TP            IN VARCHAR2 DEFAULT 'Q'             -- FLAG(Q: 현장평가, Q1:본사평가)
,   p_SIT_CD            IN VARCHAR2
,   p_BSS_YY            IN VARCHAR2
,   RTN_CURSOR          OUT SYS_REFCURSOR 
)
IS
    /**************************************************************************************************************************
      Purpose : [평가항목 조회] PROCEDRE (QSE > 안전관리 > 산업안전보건관리비 > 업체별 현황  )

      REVISIONS
      Ver      Date               Author                  Description
      -------  -----------------  ----------------------  ---------------------------------------------------------------------
      1.0      2023/12/05                                 최초생성  

    **************************************************************************************************************************/

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ] 
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE  NUMBER :=-20009; -- ERROR 코드
    ERR_MSG   VARCHAR(200);    -- ERROR Message
    USER_EXCEPTION EXCEPTION;

BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 수행전 Check Logic ]
    ---------------------------------------------------------------------------------------------------------------------------

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Logic 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------

    IF p_WRK_TP = 'Q' THEN

        OPEN RTN_CURSOR FOR
        -- 업체별 신압인전보건 관리비 사용내역
        SELECT (SELECT CUST_NM FROM VQSZ_TRADE WHERE CUST_CD = A.CUST_CD)   AS CUST_NM  --업체명 
             , A.SIT_CD                                                                 -- 현장코드
             , A.CUST_CD                                                                -- 업체코드
             , A.VNDR_SEQ                                                               -- 업체순번  
             , A.ORD_NO                                                                 -- 외주계약 발주번호
             , A.CHG_DGR                                                                -- 외주계약 최종차수
             , A.VNDR_NM                                                                -- 공사명
             , NVL(B.CONT_AMT, 0)                               AS CONT_AMT             -- 외주 계약금액
             , NVL(E.SAFT_CONT_AMT, 0)                          AS SAFT_AMT             -- 외주 계약금액 중 안전관리비 금액
             , (NVL(D.C_USE_AMT, 0) - NVL(C.T_USE_AMT, 0))      AS LAST_YEAR_AMT        -- 전년까지 금액
             , NVL(C.USE_AMT1, 0)                               AS USE_AMT1             -- 1월 사용금액
             , NVL(C.USE_AMT2, 0)                               AS USE_AMT2             -- 2월 사용금액
             , NVL(C.USE_AMT3, 0)                               AS USE_AMT3             -- 3월 사용금액
             , NVL(C.USE_AMT4, 0)                               AS USE_AMT4             -- 4월 사용금액
             , NVL(C.USE_AMT5, 0)                               AS USE_AMT5             -- 5월 사용금액
             , NVL(C.USE_AMT6, 0)                               AS USE_AMT6             -- 6월 사용금액
             , NVL(C.USE_AMT7, 0)                               AS USE_AMT7             -- 7월 사용금액
             , NVL(C.USE_AMT8, 0)                               AS USE_AMT8             -- 8월 사용금액
             , NVL(C.USE_AMT9, 0)                               AS USE_AMT9             -- 9월 사용금액
             , NVL(C.USE_AMT10, 0)                              AS USE_AMT10            -- 10월 사용금액
             , NVL(C.USE_AMT11, 0)                              AS USE_AMT11            -- 11월 사용금액
             , NVL(C.USE_AMT12, 0)                              AS USE_AMT12            -- 12월 사용금액
             , NVL(C.T_USE_AMT, 0)                              AS T_USE_AMT            -- 금년누계
             , NVL(D.C_USE_AMT, 0)                              AS C_USE_AMT            -- 누계금액
             , (NVL(E.SAFT_CONT_AMT, 0) - NVL(D.C_USE_AMT, 0))  AS REMAIN               -- 잔여금액
          FROM TQHA_VNDR A
             , VQSZ_SUBCONT B
             , (-- 업체별 당해년월별 사용금액
                SELECT A.SIT_CD
                     , A.CUST_CD
                     , A.VNDR_SEQ
                     , SUM(DECODE(SUBSTR(A.RLV_YM, 5, 2), '01', USE_AMT, 0))    AS USE_AMT1     -- 1월
                     , SUM(DECODE(SUBSTR(A.RLV_YM, 5, 2), '02', USE_AMT, 0))    AS USE_AMT2     -- 2월
                     , SUM(DECODE(SUBSTR(A.RLV_YM, 5, 2), '03', USE_AMT, 0))    AS USE_AMT3     -- 3월
                     , SUM(DECODE(SUBSTR(A.RLV_YM, 5, 2), '04', USE_AMT, 0))    AS USE_AMT4     -- 4월
                     , SUM(DECODE(SUBSTR(A.RLV_YM, 5, 2), '05', USE_AMT, 0))    AS USE_AMT5     -- 5월
                     , SUM(DECODE(SUBSTR(A.RLV_YM, 5, 2), '06', USE_AMT, 0))    AS USE_AMT6     -- 6월
                     , SUM(DECODE(SUBSTR(A.RLV_YM, 5, 2), '07', USE_AMT, 0))    AS USE_AMT7     -- 7월
                     , SUM(DECODE(SUBSTR(A.RLV_YM, 5, 2), '08', USE_AMT, 0))    AS USE_AMT8     -- 8월
                     , SUM(DECODE(SUBSTR(A.RLV_YM, 5, 2), '09', USE_AMT, 0))    AS USE_AMT9     -- 9월
                     , SUM(DECODE(SUBSTR(A.RLV_YM, 5, 2), '10', USE_AMT, 0))    AS USE_AMT10    -- 10월
                     , SUM(DECODE(SUBSTR(A.RLV_YM, 5, 2), '11', USE_AMT, 0))    AS USE_AMT11    -- 11월
                     , SUM(DECODE(SUBSTR(A.RLV_YM, 5, 2), '12', USE_AMT, 0))    AS USE_AMT12    -- 12월
                     , NVL(SUM(USE_AMT), 0)                                     AS T_USE_AMT    -- 금년누계
                  FROM TQHA_SAFECOST_ARSLT_CO       A
                     , TQHA_SAFECOST_MMARSLT_CO     B
                 WHERE A.SIT_CD                 = p_SIT_CD          -- 변수 (현장코드)
                   AND SUBSTR(A.RLV_YM, 1, 4)   = p_BSS_YY          -- 변수 (년도)
                   AND A.SIT_CD                 = B.SIT_CD(+)
                   AND A.CUST_CD                = B.CUST_CD(+)
                   AND A.VNDR_SEQ               = B.VNDR_SEQ(+)
                   AND A.RLV_YM                 = B.RLV_YM(+)
                   AND B.SITE_APRV_YN           = 1
                 GROUP BY A.SIT_CD, A.CUST_CD, A.VNDR_SEQ
                 ORDER BY SIT_CD, CUST_CD, VNDR_SEQ
               ) C
             , (-- 업체별 당해년도까지 누계
                SELECT A.SIT_CD
                     , A.CUST_CD
                     , A.VNDR_SEQ
                     , NVL(SUM(USE_AMT), 0) AS C_USE_AMT -- 누계금액
                  FROM TQHA_SAFECOST_ARSLT_CO A, TQHA_SAFECOST_MMARSLT_CO B
                 WHERE A.SIT_CD                 = p_SIT_CD          -- 변수 (현장코드)
                   AND SUBSTR(A.RLV_YM, 1, 4)   <= p_BSS_YY         -- 변수 (년도)
                   AND A.SIT_CD                 = B.SIT_CD(+)
                   AND A.CUST_CD                = B.CUST_CD(+)
                   AND A.VNDR_SEQ               = B.VNDR_SEQ(+)
                   AND A.RLV_YM                 = B.RLV_YM(+)
                   AND B.SITE_APRV_YN           = 1
                 GROUP BY A.SIT_CD, A.CUST_CD, A.VNDR_SEQ
                 ORDER BY SIT_CD, CUST_CD, VNDR_SEQ
               ) D
             , (-- 20240906 추가 업체 계약별 안전관리비 금액
                SELECT SIT_CD
                     , CONT_NO
                     , CUST_CD
                     , SAFT_CONT_AMT        -- 계약업체(안전관리비 금액)
                  FROM FCMZ_SAFT_DEFC_IF('SM', p_SIT_CD )
               )  E   
         WHERE A.SIT_CD             = p_SIT_CD          -- 변수 (현장코드)
           AND A.SIT_CD             = B.SIT_CD
           AND A.SIT_CD             = C.SIT_CD(+)
           AND A.CUST_CD            = C.CUST_CD(+)
           AND A.VNDR_SEQ           = C.VNDR_SEQ (+)
           AND A.SIT_CD             = D.SIT_CD(+)
           AND A.CUST_CD            = D.CUST_CD(+)
           AND A.VNDR_SEQ           = D.VNDR_SEQ (+)
           AND A.ORD_NO             = B.ORD_NO
           AND A.CHG_DGR            = B.CHG_DGR
           AND A.SIT_CD             = E.SIT_CD(+)
           AND A.CUST_CD            = E.CUST_CD(+)
           AND A.ORD_NO             = E.CONT_NO(+)      -- 계약번호(발주번호)
        ;

    END IF;


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
         WHEN OTHERS THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);

END PQHA_SAFECOST_ARSLT_CO_Q;
/

-- PQHA_SAFECOST_ARSLT_CO_S (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_SAFECOST_ARSLT_CO_S" 
                            (p_WRK_TP  VARCHAR2 :='U'                                     -- UPDATE FLAG( I: ISNERT, U:UPDATE, D:DELTE)
                            ,p_WRK_ID  VARCHAR2                                           -- 사용자 ID 
                            ,p_WRK_IP  VARCHAR2                                           -- 사용자 IP 
                            ,p_SIT_CD 		 TQHA_SAFECOST_ARSLT_CO.SIT_CD%TYPE           -- 현장코드 
                            ,p_ITM_DIV 		 TQHA_SAFECOST_ARSLT_CO.ITM_DIV%TYPE          -- 안전관리비 예산구분(QS026) 1 안전인건비 
                            ,p_CUST_CD 		 TQHA_SAFECOST_ARSLT_CO.CUST_CD%TYPE          -- 협력업체코드
                            ,p_VNDR_SEQ 	 TQHA_SAFECOST_ARSLT_CO.VNDR_SEQ%TYPE         -- 업체순번
                            ,p_RLV_YM 		 TQHA_SAFECOST_ARSLT_CO.RLV_YM%TYPE           -- 해당년월
                            ,p_USE_DT 		 TQHA_SAFECOST_ARSLT_CO.USE_DT%TYPE           -- 사용일자
                            ,p_USE_SEQ 		 TQHA_SAFECOST_ARSLT_CO.USE_SEQ%TYPE          -- 사용순번
                            ,p_USE_DTLS 	 TQHA_SAFECOST_ARSLT_CO.USE_DTLS%TYPE         -- 사용내역
                            ,p_USE_UNT 		 TQHA_SAFECOST_ARSLT_CO.USE_UNT%TYPE          -- 사용단위                            
                            ,p_USE_QNT 		 TQHA_SAFECOST_ARSLT_CO.USE_QNT%TYPE          -- 사용수량
                            ,p_USE_UPRC 	 TQHA_SAFECOST_ARSLT_CO.USE_UPRC%TYPE         -- 사용단가
                            ,p_USE_AMT 		 TQHA_SAFECOST_ARSLT_CO.USE_AMT%TYPE          -- 사용금액
                            ,p_GRP_PHOTO_1   TQHA_SAFECOST_ARSLT_CO.GRP_PHOTO_1%TYPE      -- 첨부파일그룹사진1
                            ,p_PHOTO_DESC_1  TQHA_SAFECOST_ARSLT_CO.PHOTO_DESC_1%TYPE     -- 사진설명1
                            ,p_RMKS 		 TQHA_SAFECOST_ARSLT_CO.RMKS%TYPE             -- 비고
                            ,p_BLN_18        TQHA_SAFECOST_ARSLT.PNM_18%TYPE              -- 소속 
					        ,p_PNM_18        TQHA_SAFECOST_ARSLT.PNM_18%TYPE              -- 성명
					        ,p_PRCR_DT_18     TQHA_SAFECOST_ARSLT.PRCR_DT_18%TYPE         -- 선임일자 
--					        ,p_LCST_UPRC_2   TQHA_SAFECOST_ARSLT.LCST_UPRC_2%TYPE         -- 노무비단가 24.08.09 주석처리
--					        ,p_MCST_UPRC_2   TQHA_SAFECOST_ARSLT.MCST_UPRC_2%TYPE         -- 자재비단가 24.08.09 주석처리 
					        ,p_PLN_UPRC_39   TQHA_SAFECOST_ARSLT.PLN_UPRC_39%TYPE         -- 계획단가
					        ,p_PLN_QNT_39    TQHA_SAFECOST_ARSLT.PLN_QNT_39%TYPE          -- 계획수량
					        ,p_PLN_AMT_39    TQHA_SAFECOST_ARSLT.PLN_AMT_39%TYPE          -- 계획금액
					        ,p_DGS_ORG_4     TQHA_SAFECOST_ARSLT.DGS_ORG_4%TYPE           -- 진단기관
					        ,p_EDU_ATTL5     TQHA_SAFECOST_ARSLT.EDU_ATTL5%TYPE           -- 교육과목
					        ,p_EDU_SPNC_5    TQHA_SAFECOST_ARSLT.EDU_SPNC_5%TYPE          -- 교육주관
					        ,p_PRTC_PSNNO_56 TQHA_SAFECOST_ARSLT.PRTC_PSNNO_56%TYPE       -- 참가인원
					        ,p_DGS_HOSP6     TQHA_SAFECOST_ARSLT.DGS_HOSP6%TYPE           -- 진단병원
					        ,p_GUI_ATTL7     TQHA_SAFECOST_ARSLT.GUI_ATTL7%TYPE           -- 지도항목
					        ,p_GUI_ORG7      TQHA_SAFECOST_ARSLT.GUI_ORG7%TYPE            -- 지도기관
					        ,p_DTY_8         TQHA_SAFECOST_ARSLT.DTY_8%TYPE               -- 직책
					        ,p_DTY_DT8       TQHA_SAFECOST_ARSLT.DTY_DT8%TYPE             -- 보직일자
					        ,p_ITM_9         TQHA_SAFECOST_ARSLT.ITM_9%TYPE               -- 품목명
					        ,p_SAFE_DT9      TQHA_SAFECOST_ARSLT.SAFE_DT9%TYPE            -- 위험결정일자
					        ,p_LAB_DT9       TQHA_SAFECOST_ARSLT.LAB_DT9%TYPE             -- 노사결정일자
					        ,p_DLV_VNDR      TQHA_SAFECOST_ARSLT.DLV_VNDR%TYPE            -- 납품업체
					        ,p_GRP_PHOTO_2   TQHA_SAFECOST_ARSLT_CO.GRP_PHOTO_2%TYPE      -- 첨부파일그룹사진2
                            ,p_PHOTO_DESC_2  TQHA_SAFECOST_ARSLT_CO.PHOTO_DESC_2%TYPE     -- 사진설명2
					        )
                            
IS 
    /**************************************************************************************************************************
      Purpose : 협력업체 월별 실적 저장

      REVISIONS
      Ver      Date               Author                  Description 
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2021/12/09 14:05:48                         최초생성

    **************************************************************************************************************************/

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR2(200);            -- ERROR Message
    USER_EXCEPTION EXCEPTION;

    v_USE_SEQ TQHA_SAFECOST_ARSLT_CO.USE_SEQ%TYPE ;          -- 산업안전보건관리비 순번 변수 선언
    v_CNT  TQHA_SAFECOST_ARSLT_CO.USE_SEQ%TYPE ;             -- 월별 집계 테이블 존재 여부 체크 
BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 필수입력 필드  Check  ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_SIT_CD IS NULL)  THEN
        ERR_MSG := '현장코드는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_ITM_DIV IS NULL)  THEN
        ERR_MSG := '안전관리비 예산구분(QS026) 1 안전인건비 는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_CUST_CD IS NULL)  THEN
        ERR_MSG := '협력업체코드는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_VNDR_SEQ IS NULL)  THEN
        ERR_MSG := '업체순번는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_RLV_YM IS NULL)  THEN
        ERR_MSG := '해당년월는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_USE_DT IS NULL)  THEN
        ERR_MSG := '사용일자는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_USE_SEQ IS NULL AND p_WRK_TP <> 'I')  THEN
        ERR_MSG := '사용순번는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Process 선행조건 Check ]
    ---------------------------------------------------------------------------------------------------------------------------



    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Business Process ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_WRK_TP ='D') THEN
        DELETE 
          FROM TQHA_SAFECOST_ARSLT_CO
         WHERE SIT_CD = p_SIT_CD         --현장코드
           AND ITM_DIV = p_ITM_DIV         --안전관리비 예산구분(QS026) 1 안전인건비 
           AND CUST_CD = p_CUST_CD         --협력업체코드
           AND VNDR_SEQ = p_VNDR_SEQ        --업체순번
           AND RLV_YM = p_RLV_YM          --해당년월
           AND USE_DT = p_USE_DT          --사용일자
           AND USE_SEQ = p_USE_SEQ;        --사용순번

    ELSIF (p_WRK_TP ='U') THEN

        UPDATE TQHA_SAFECOST_ARSLT_CO
           SET USE_DTLS             = p_USE_DTLS                --사용내역
              ,USE_UNT              = p_USE_UNT                 --사용단위           
              ,USE_QNT              = p_USE_QNT                 --사용수량
              ,USE_UPRC             = p_USE_UPRC                --사용단가
              ,USE_AMT              = p_USE_AMT                 --사용금액
              ,GRP_PHOTO_1          = p_GRP_PHOTO_1             --첨부파일그룹사진1
              ,PHOTO_DESC_1         = p_PHOTO_DESC_1            --사진설명1
              ,RMKS                 = p_RMKS                    --비고
              ,BLN_18               = p_BLN_18             -- 소속 
	          ,PNM_18               = p_PNM_18             -- 성명
	          ,PRCR_DT_18           = p_PRCR_DT_18         -- 선임일자 
--	          ,LCST_UPRC_2          = p_LCST_UPRC_2        -- 노무비단가 24.08.09 주석처리
--	          ,MCST_UPRC_2          = p_MCST_UPRC_2        -- 자재비단가 24.08.09 주석처리  
	          ,PLN_UPRC_39          = p_PLN_UPRC_39        -- 계획단가
	          ,PLN_QNT_39           = p_PLN_QNT_39         -- 계획수량
	          ,PLN_AMT_39           = p_PLN_AMT_39         -- 계획금액
	          ,DGS_ORG_4            = p_DGS_ORG_4          -- 진단기관
	          ,EDU_ATTL5            = p_EDU_ATTL5          -- 교육과목
	          ,EDU_SPNC_5           = p_EDU_SPNC_5         -- 교육주관
	          ,PRTC_PSNNO_56        = p_PRTC_PSNNO_56      -- 참가인원
	          ,DGS_HOSP6            = p_DGS_HOSP6          -- 진단병원
	          ,GUI_ATTL7            = p_GUI_ATTL7          -- 지도항목
	          ,GUI_ORG7             = p_GUI_ORG7           -- 지도기관
	          ,DTY_8                = p_DTY_8              -- 직책
	          ,DTY_DT8              = p_DTY_DT8            -- 보직일자
	          ,ITM_9                = p_ITM_9              -- 품목명	          
	          ,SAFE_DT9             = p_SAFE_DT9           -- 위험결정일자
	          ,LAB_DT9              = p_LAB_DT9            -- 노사결정일자
	          ,DLV_VNDR				= p_DLV_VNDR		   -- 납품업체
	          ,GRP_PHOTO_2          = p_GRP_PHOTO_2             --첨부파일그룹사진2
              ,PHOTO_DESC_2         = p_PHOTO_DESC_2            --사진설명2
              ,UPD_ID               = p_WRK_ID                  --수정ID 
              ,UPD_DTM              = SYSDATE()                 --수정일시
              ,UPD_IP               = p_WRK_IP                  --수정IP
         WHERE SIT_CD = p_SIT_CD         --현장코드
           AND ITM_DIV = p_ITM_DIV         --안전관리비 예산구분(QS026) 1 안전인건비 
           AND CUST_CD = p_CUST_CD         --협력업체코드
           AND VNDR_SEQ = p_VNDR_SEQ        --업체순번
           AND RLV_YM = p_RLV_YM          --해당년월
           AND USE_DT = p_USE_DT          --사용일자
           AND USE_SEQ = p_USE_SEQ;        --사용순번
    ELSE 
         -- 산업안전보건관리비 순번 생성 
        SELECT NVL( (MAX(USE_SEQ)+1),'1' ) 
          INTO v_USE_SEQ
          FROM TQHA_SAFECOST_ARSLT_CO
         WHERE SIT_CD = p_SIT_CD        --현장코드
           AND ITM_DIV = p_ITM_DIV        --안전관리비 예산구분(QS026) 1 안전인건비 
           AND CUST_CD = p_CUST_CD        --협력업체코드
           AND VNDR_SEQ = p_VNDR_SEQ      --업체순번           
           AND RLV_YM = p_RLV_YM          --해당년월
           AND USE_DT = p_USE_DT  ;       --사용일자
        --   
        INSERT INTO TQHA_SAFECOST_ARSLT_CO
                   ( SIT_CD                 --현장코드
                    ,ITM_DIV                 --안전관리비 예산구분(QS026) 1 안전인건비 
                    ,CUST_CD                 --협력업체코드
                    ,VNDR_SEQ                --업체순번
                    ,RLV_YM                  --해당년월
                    ,USE_DT                  --사용일자
                    ,USE_SEQ                 --사용순번
                    ,USE_DTLS                --사용내역
                    ,USE_UNT                 --사용단위                    
                    ,USE_QNT                 --사용수량
                    ,USE_UPRC                --사용단가
                    ,USE_AMT                 --사용금액
                    ,GRP_PHOTO_1             --첨부파일그룹사진1
                    ,PHOTO_DESC_1            --사진설명1
                    ,RMKS                    --비고
		            ,BLN_18                  -- 소속 
			        ,PNM_18                  -- 성명
			        ,PRCR_DT_18               -- 선임일자 
--			        ,LCST_UPRC_2             -- 노무비단가 24.08.09 주석처리
--			        ,MCST_UPRC_2             -- 자재비단가 24.08.09 주석처리 
			        ,PLN_UPRC_39             -- 계획단가
			        ,PLN_QNT_39              -- 계획수량
			        ,PLN_AMT_39              -- 계획금액
			        ,DGS_ORG_4               -- 진단기관
			        ,EDU_ATTL5               -- 교육과목
			        ,EDU_SPNC_5              -- 교육주관
			        ,PRTC_PSNNO_56           -- 참가인원
			        ,DGS_HOSP6               -- 진단병원
			        ,GUI_ATTL7               -- 지도항목
			        ,GUI_ORG7                -- 지도기관
			        ,DTY_8                   -- 직책
			        ,DTY_DT8                 -- 보직일자
	                ,ITM_9                   -- 품목명			        
			        ,SAFE_DT9                -- 위험결정일자
			        ,LAB_DT9                 -- 노사결정일자
			        ,DLV_VNDR				 -- 납품업체
			        ,GRP_PHOTO_2             --첨부파일그룹사진2
                    ,PHOTO_DESC_2            --사진설명2
                    ,IPT_ID                  --입력ID
                    ,IPT_DTM                 --입력일시
                    ,IPT_IP                  --입력IP
                    ,UPD_ID                  --수정ID
                    ,UPD_DTM                 --수정일시
                    ,UPD_IP)                 --수정IP
             VALUES (p_SIT_CD               --현장코드
                    ,p_ITM_DIV               --안전관리비 예산구분(QS026) 1 안전인건비 
                    ,p_CUST_CD               --협력업체코드
                    ,p_VNDR_SEQ              --업체순번
                    ,p_RLV_YM                --해당년월
                    ,p_USE_DT                --사용일자
                    ,v_USE_SEQ               --사용순번
                    ,p_USE_DTLS              --사용내역
                    ,p_USE_UNT               --사용단위                    
                    ,p_USE_QNT               --사용수량
                    ,p_USE_UPRC              --사용단가
                    ,p_USE_AMT               --사용금액
                    ,p_GRP_PHOTO_1           --첨부파일그룹사진1
                    ,SUBSTRB(p_USE_DT||','||v_USE_SEQ||','||p_USE_DTLS ,0, 100)        --사진설명1
                    ,p_RMKS                  --비고
	                ,p_BLN_18                -- 소속 
		            ,p_PNM_18                -- 성명
		            ,p_PRCR_DT_18            -- 선임일자 
--		            ,p_LCST_UPRC_2           -- 노무비단가 24.08.09 주석처리
--		            ,p_MCST_UPRC_2           -- 자재비단가 24.08.09 주석처리
		            ,p_PLN_UPRC_39           -- 계획단가
		            ,p_PLN_QNT_39            -- 계획수량
		            ,p_PLN_AMT_39            -- 계획금액
		            ,p_DGS_ORG_4             -- 진단기관
		            ,p_EDU_ATTL5             -- 교육과목
		            ,p_EDU_SPNC_5            -- 교육주관
		            ,p_PRTC_PSNNO_56         -- 참가인원
		            ,p_DGS_HOSP6             -- 진단병원
		            ,p_GUI_ATTL7             -- 지도항목
		            ,p_GUI_ORG7              -- 지도기관
		            ,p_DTY_8                 -- 직책
			        ,p_DTY_DT8               -- 보직일자
	                ,p_ITM_9                 -- 품목명			        		            
		            ,p_SAFE_DT9              -- 위험결정일자
		            ,p_LAB_DT9               -- 노사결정일자
		            ,p_DLV_VNDR				 -- 납품업체
		            ,p_GRP_PHOTO_2           --첨부파일그룹사진2
                    ,SUBSTRB(p_USE_DT||','||v_USE_SEQ||','||p_USE_DTLS ,0, 100)        --사진설명2
                    ,p_WRK_ID                --입력ID 
                    ,SYSDATE()               --입력일시
                    ,p_WRK_IP                --입력IP
                    ,p_WRK_ID                --수정ID
                    ,SYSDATE()               --수정일시
                    ,p_WRK_IP);              --수정IP

    END IF;


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 5. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN 
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);
END ;
/

-- PQHA_SAFECOST_ARSLT_Q (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_SAFECOST_ARSLT_Q" (
    p_WRK_TP                IN VARCHAR2 DEFAULT 'Q'             -- FLAG(Q: 현장평가, Q1:본사평가)
,   p_SIT_CD                IN VARCHAR2
,   p_ITM_DIV               IN VARCHAR2
,   p_RLV_YM                IN VARCHAR2
,   p_SEARCH_STR_YM         IN VARCHAR2
,   RTN_CURSOR              OUT SYS_REFCURSOR
)
IS
    /**************************************************************************************************************************
      Purpose : [평가항목 조회] PROCEDRE (QSE > 안전관리 > 산업안전보건관리비 > 월별실적관리  )

      REVISIONS
      Ver      Date               Author                  Description
      -------  -----------------  ----------------------  ---------------------------------------------------------------------
      1.0      2023/12/05                                 최초생성

    **************************************************************************************************************************/

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE  NUMBER :=-20009; -- ERROR 코드
    ERR_MSG   VARCHAR(200);    -- ERROR Message
    USER_EXCEPTION EXCEPTION;

BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 수행전 Check Logic ]
    ---------------------------------------------------------------------------------------------------------------------------

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Logic 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------

    IF p_WRK_TP = 'Q' THEN

        IF (p_ITM_DIV = NULL) OR (p_ITM_DIV = '') THEN

            OPEN RTN_CURSOR FOR
            SELECT SIT_CD               -- 현장코드
                 , ITM_DIV              -- 항목구분 (공통코드 QS026)
                 , (SELECT CD_NM FROM TCOA_COMCODE WHERE COM_CD = ITM_DIV AND HRNK_CD = 'QS026') AS ITM_DIV_NM
                 , RLV_YM               -- 해당년월
                 , USE_DT               -- 사용일자
                 , USE_SEQ              -- 사용순번
                 , USE_DTLS             -- 사용내역
                 , USE_UNT              -- 사용단위
                 , USE_QNT              -- 사용수량
                 , USE_UPRC             -- 사용단가
                 , USE_AMT              -- 사용금액
                 , RMKS                 -- 비고
                 , GRP_PHOTO_1          -- 첨부파일그룹1
                 , PHOTO_DESC_1         -- 사진설명1
                 , (SELECT B.APRV_STATS
                      FROM TQHA_SAFECOST_APRV   A
                         , TQHA_APRV            B
                     WHERE A.APRV_NO        = B.APRV_NO
                       AND A.SIT_CD         = p_SIT_CD
                       AND A.SIT_CD         = B.SIT_CD
                       AND A.APRV_DIV       = '2'
                       AND A.APRV_YM        = p_SEARCH_STR_YM
                   ) AS APRV_STATS
                 , DLV_VNDR             -- 납품업체
              FROM TQHA_SAFECOST_ARSLT
             WHERE SIT_CD       = p_SIT_CD              -- 변수(현장코드)
               AND RLV_YM       = p_SEARCH_STR_YM       -- 변수(년월)
             ORDER BY ITM_DIV
            ;

        ELSIF p_ITM_DIV = '01' THEN

            OPEN RTN_CURSOR FOR
            SELECT SIT_CD               -- 현장코드
                 , ITM_DIV              -- 항목구분 (공통코드 QS026)
                 , (SELECT CD_NM FROM TCOA_COMCODE WHERE COM_CD = ITM_DIV AND HRNK_CD = 'QS026') AS ITM_DIV_NM
                 , RLV_YM               -- 해당년월
                 , USE_SEQ              -- 사용순번
                 , BLN_18               -- 소속
                 , PNM_18               -- 성명
                 , PRCR_DT_18           -- 선임일자
                 , USE_AMT              -- 사용금액(지급금액)
                 , USE_DT               -- 사용일자(지급일자)
                 , USE_DTLS             -- 사용내역(지급내역)
                 , RMKS                 -- 비고
                 , GRP_PHOTO_1          -- 첨부파일그룹1
                 , PHOTO_DESC_1         -- 사진설명1
                 , DLV_VNDR             -- 납품업체
                 , CASE WHEN (SELECT COUNT(*) FROM TCOZ_ATFL WHERE ATFL_GRP = GRP_PHOTO_1 OR ATFL_GRP = GRP_PHOTO_2) > 0 THEN 'O' ELSE 'X' END AS ATFL_GRP_YN
                 , GRP_PHOTO_2          -- 첨부파일그룹2
                 , PHOTO_DESC_2         -- 사진설명2
                 , USE_UPRC             -- 사용단가
                 , USE_QNT              -- 사용수량
              FROM TQHA_SAFECOST_ARSLT
             WHERE SIT_CD           = p_SIT_CD          -- 변수(현장코드)
               AND ITM_DIV          = p_ITM_DIV         -- 안전 9대항목  01 안전보건관리자 입금 02 안전시설비 03 보호구 04 안전보건진단비 05 안전보건 교육비 06 근조자 건강장해예방비  07기술지도비 08 본사점담조직  09 위험성평가에 다른 소모비용
               AND RLV_YM           = p_RLV_YM          -- 변수(년월)
             ORDER BY ITM_DIV, USE_DT
            ;

        ELSIF p_ITM_DIV = '02' THEN

            OPEN RTN_CURSOR FOR
            -- 당사 매월 사용실적 조회 ( 2 안전시설비 )
            SELECT SIT_CD               -- 현장코드
                 , ITM_DIV              -- 항목구분 (공통코드 QS026)
                 , (SELECT CD_NM FROM TCOA_COMCODE WHERE COM_CD = ITM_DIV AND HRNK_CD = 'QS026') AS ITM_DIV_NM
                 , RLV_YM               -- 해당년월
                 , USE_SEQ              -- 사용순번
                 , USE_DT               -- 사용일자
                 , USE_UNT              -- 사용단위
                 , USE_QNT              -- 사용수량
--               , LCST_UPRC_2          -- 노무비단가(24.08.09 주석처리)
--               , MCST_UPRC_2          -- 자재비단가(24.08.09 주석처리)
                 , USE_UPRC             -- 사용단가 계
                 , USE_AMT              -- 사용금액
                 , USE_DTLS             -- 사용내역(지급내역)
                 , RMKS                 -- 비고
                 , GRP_PHOTO_1          -- 첨부파일그룹1
                 , PHOTO_DESC_1         -- 사진설명1
                 , DLV_VNDR             -- 납품업체
                 , CASE WHEN (SELECT COUNT(*) FROM TCOZ_ATFL WHERE ATFL_GRP = GRP_PHOTO_1 OR ATFL_GRP = GRP_PHOTO_2) > 0 THEN 'O' ELSE 'X' END AS ATFL_GRP_YN
                 , GRP_PHOTO_2          -- 첨부파일그룹2
                 , PHOTO_DESC_2         -- 사진설명2
              FROM TQHA_SAFECOST_ARSLT
             WHERE SIT_CD               = p_SIT_CD          -- 변수(현장코드)
               AND ITM_DIV              = p_ITM_DIV         -- 안전 9대항목  01 안전보건관리자 입금 02 안전시설비 03 보호구 04 안전보건진단비 05 안전보건 교육비 06 근조자 건강장해예방비  07기술지도비 08 본사점담조직  09 위험성평가에 다른 소모비용
               AND RLV_YM               = p_RLV_YM          -- 변수(년월)
             ORDER BY ITM_DIV, USE_DT
            ;

        ELSIF p_ITM_DIV = '03' THEN

            OPEN RTN_CURSOR FOR
            -- 당사 매월 사용실적 조회 ( 3 보호구 )
            SELECT SIT_CD               -- 현장코드
                 , ITM_DIV              -- 항목구분 (공통코드 QS026)
                 , (SELECT CD_NM FROM TCOA_COMCODE WHERE COM_CD = ITM_DIV AND HRNK_CD = 'QS026') AS ITM_DIV_NM
                 , RLV_YM               -- 해당년월
                 , USE_SEQ              -- 사용순번
                 , PLN_UPRC_39          -- 계획단가
                 , PLN_QNT_39           -- 계획수량
                 , PLN_AMT_39           -- 계획금액
                 , USE_DT               -- 사용일자
                 , USE_UPRC             -- 사용단가
                 , USE_QNT              -- 사용수량
                 , USE_AMT              -- 사용금액
                 , USE_DTLS             -- 사용내역(지급내역)
                 , RMKS                 -- 비고
                 , GRP_PHOTO_1          -- 첨부파일그룹1
                 , PHOTO_DESC_1         -- 사진설명1
                 , DLV_VNDR             -- 납품업체
                 , CASE WHEN (SELECT COUNT(*) FROM TCOZ_ATFL WHERE ATFL_GRP = GRP_PHOTO_1 OR ATFL_GRP = GRP_PHOTO_2) > 0 THEN 'O' ELSE 'X' END AS ATFL_GRP_YN
                 , GRP_PHOTO_2          -- 첨부파일그룹2
                 , PHOTO_DESC_2         -- 사진설명2
              FROM TQHA_SAFECOST_ARSLT
             WHERE SIT_CD           = p_SIT_CD          -- 변수(현장코드)
               AND ITM_DIV          = p_ITM_DIV         -- 안전 9대항목  01 안전보건관리자 입금 02 안전시설비 03 보호구 04 안전보건진단비 05 안전보건 교육비 06 근조자 건강장해예방비  07기술지도비 08 본사점담조직  09 위험성평가에 다른 소모비용
               AND RLV_YM           = p_RLV_YM          -- 변수(년월)
             ORDER BY ITM_DIV, USE_DT
            ;

        ELSIF p_ITM_DIV = '04' THEN

            OPEN RTN_CURSOR FOR
            -- 당사 매월 사용실적 조회 ( 4 안전보건진단비 )
            SELECT SIT_CD               -- 현장코드
                 , ITM_DIV              -- 항목구분 (공통코드 QS026)
                 , (SELECT CD_NM FROM TCOA_COMCODE WHERE COM_CD = ITM_DIV AND HRNK_CD = 'QS026') AS ITM_DIV_NM
                 , RLV_YM               -- 해당년월
                 , USE_SEQ              -- 사용순번
                 , DGS_ORG_4            -- 진단기관
                 , USE_DT               -- 사용일자
                 , USE_AMT              -- 사용금액(소요비용)
                 , USE_DTLS             -- 사용내역(지급내역)
                 , RMKS                 -- 비고
                 , GRP_PHOTO_1          -- 첨부파일그룹1
                 , PHOTO_DESC_1         -- 사진설명1
                 , CASE WHEN (SELECT COUNT(*) FROM TCOZ_ATFL WHERE ATFL_GRP = GRP_PHOTO_1 OR ATFL_GRP = GRP_PHOTO_2) > 0 THEN 'O' ELSE 'X' END AS ATFL_GRP_YN
                 , GRP_PHOTO_2          -- 첨부파일그룹2
                 , PHOTO_DESC_2         -- 사진설명2
                 , USE_UPRC             -- 사용단가
                 , USE_QNT              -- 사용수량
              FROM TQHA_SAFECOST_ARSLT
             WHERE SIT_CD           = p_SIT_CD          -- 변수(현장코드)
               AND ITM_DIV          = p_ITM_DIV         -- 안전 9대항목  01 안전보건관리자 입금 02 안전시설비 03 보호구 04 안전보건진단비 05 안전보건 교육비 06 근조자 건강장해예방비  07기술지도비 08 본사점담조직  09 위험성평가에 다른 소모비용
               AND RLV_YM           = p_RLV_YM          -- 변수(년월)
             ORDER BY ITM_DIV, USE_DT
            ;

        ELSIF p_ITM_DIV = '05' THEN

            OPEN RTN_CURSOR FOR
            -- 당사 매월 사용실적 조회 ( 5 안전보건교육비 )
            SELECT SIT_CD               -- 현장코드
                 , ITM_DIV              -- 항목구분 (공통코드 QS026)
                 , (SELECT CD_NM FROM TCOA_COMCODE WHERE COM_CD = ITM_DIV AND HRNK_CD = 'QS026') AS ITM_DIV_NM
                 , RLV_YM               -- 해당년월
                 , USE_SEQ              -- 사용순번
                 , EDU_ATTL5            -- 교육과목
                 , EDU_SPNC_5           -- 교육주관
                 , USE_DT               -- 사용일자(교육일)
                 , PRTC_PSNNO_56        -- 참가인원(숫자)
                 , USE_AMT              -- 사용금액(소요경비)
                 , RMKS                 -- 비고
                 , GRP_PHOTO_1          -- 첨부파일그룹1
                 , PHOTO_DESC_1         -- 사진설명1
                 , CASE WHEN (SELECT COUNT(*) FROM TCOZ_ATFL WHERE ATFL_GRP = GRP_PHOTO_1 OR ATFL_GRP = GRP_PHOTO_2) > 0 THEN 'O' ELSE 'X' END AS ATFL_GRP_YN
                 , GRP_PHOTO_2          -- 첨부파일그룹2
                 , PHOTO_DESC_2         -- 사진설명2
                 , USE_UPRC             -- 사용단가
                 , USE_QNT              -- 사용수량
              FROM TQHA_SAFECOST_ARSLT
             WHERE SIT_CD           = p_SIT_CD          -- 변수(현장코드)
               AND ITM_DIV          = p_ITM_DIV         -- 안전 9대항목  01 안전보건관리자 입금 02 안전시설비 03 보호구 04 안전보건진단비 05 안전보건 교육비 06 근조자 건강장해예방비  07기술지도비 08 본사점담조직  09 위험성평가에 다른 소모비용
               AND RLV_YM           = p_RLV_YM          -- 변수(년월)
             ORDER BY ITM_DIV, USE_DT
            ;

        ELSIF p_ITM_DIV = '06' THEN

            OPEN RTN_CURSOR FOR
            -- 당사 매월 사용실적 조회 ( 6 근로자 건강장해예방비 )
            SELECT SIT_CD               -- 현장코드
                 , ITM_DIV              -- 항목구분 (공통코드 QS026)
                 , (SELECT CD_NM FROM TCOA_COMCODE WHERE COM_CD = ITM_DIV AND HRNK_CD = 'QS026') AS ITM_DIV_NM
                 , RLV_YM               -- 해당년월
                 , USE_SEQ              -- 사용순번
                 , USE_DT               -- 사용일자
                 , DGS_HOSP6            -- 진단병원
                 , PRTC_PSNNO_56        -- 참가인원
                 , USE_AMT              -- 사용금액(소요경비)
                 , RMKS                 -- 비고
                 , GRP_PHOTO_1          -- 첨부파일그룹1
                 , PHOTO_DESC_1         -- 사진설명1
                 , CASE WHEN (SELECT COUNT(*) FROM TCOZ_ATFL WHERE ATFL_GRP = GRP_PHOTO_1 OR ATFL_GRP = GRP_PHOTO_2) > 0 THEN 'O' ELSE 'X' END AS ATFL_GRP_YN
                 , GRP_PHOTO_2          -- 첨부파일그룹2
                 , PHOTO_DESC_2         -- 사진설명2
                 , USE_UPRC             -- 사용단가
                 , USE_QNT              -- 사용수량
              FROM TQHA_SAFECOST_ARSLT
             WHERE SIT_CD           = p_SIT_CD          -- 변수(현장코드)
               AND ITM_DIV          = p_ITM_DIV         -- 안전 9대항목  01 안전보건관리자 입금 02 안전시설비 03 보호구 04 안전보건진단비 05 안전보건 교육비 06 근조자 건강장해예방비  07기술지도비 08 본사점담조직  09 위험성평가에 다른 소모비용
               AND RLV_YM           = p_RLV_YM          -- 변수(년월)
             ORDER BY ITM_DIV, USE_DT
            ;

        ELSIF p_ITM_DIV = '07' THEN

            OPEN RTN_CURSOR FOR
            -- 당사 매월 사용실적 조회 ( 7 기술지도비 )
            SELECT SIT_CD               -- 현장코드
                 , ITM_DIV              -- 항목구분 (공통코드 QS026)
                 , (SELECT CD_NM FROM TCOA_COMCODE WHERE COM_CD = ITM_DIV AND HRNK_CD = 'QS026') AS ITM_DIV_NM
                 , RLV_YM               -- 해당년월
                 , USE_SEQ              -- 사용순번
                 , GUI_ATTL7            -- 지도항목
                 , GUI_ORG7             -- 지도기관
                 , USE_DT               -- 사용일자(점검일)
                 , USE_AMT              -- 사용금액(소요경비)
                 , RMKS                 -- 비고
                 , GRP_PHOTO_1          -- 첨부파일그룹1
                 , PHOTO_DESC_1         -- 사진설명1
                 , CASE WHEN (SELECT COUNT(*) FROM TCOZ_ATFL WHERE ATFL_GRP = GRP_PHOTO_1 OR ATFL_GRP = GRP_PHOTO_2) > 0 THEN 'O' ELSE 'X' END AS ATFL_GRP_YN
                 , GRP_PHOTO_2          -- 첨부파일그룹2
                 , PHOTO_DESC_2         -- 사진설명2
                 , USE_UPRC             -- 사용단가
                 , USE_QNT              -- 사용수량
              FROM TQHA_SAFECOST_ARSLT
             WHERE SIT_CD           = p_SIT_CD          -- 변수(현장코드)
               AND ITM_DIV          = p_ITM_DIV         -- 안전 9대항목  01 안전보건관리자 입금 02 안전시설비 03 보호구 04 안전보건진단비 05 안전보건 교육비 06 근조자 건강장해예방비  07기술지도비 08 본사점담조직  09 위험성평가에 다른 소모비용
               AND RLV_YM           = p_RLV_YM          -- 변수(년월)
             ORDER BY ITM_DIV, USE_DT
            ;

        ELSIF p_ITM_DIV = '08' THEN

            OPEN RTN_CURSOR FOR
             -- 당사 매월 사용실적 조회 ( 8 본사전담조직 8-2 사용내역)
            SELECT SIT_CD               -- 현장코드
                 , ITM_DIV              -- 항목구분 (공통코드 QS026)
                 , (SELECT CD_NM FROM TCOA_COMCODE WHERE COM_CD = ITM_DIV AND HRNK_CD = 'QS026') AS ITM_DIV_NM
                 , RLV_YM               -- 해당년월
                 , USE_SEQ              -- 사용순번
                 , BLN_18               -- 소속
                 , DTY_8                -- 직책
                 , PNM_18               -- 성명
                 , DTY_DT8              -- 보직일자
                 , USE_AMT              -- 사용금액(지급액)
                 , USE_DT               -- 사용일자(지급일)
                 , RMKS                 -- 비고
                 , GRP_PHOTO_1          -- 첨부파일그룹1
                 , PHOTO_DESC_1         -- 사진설명1
                 , CASE WHEN (SELECT COUNT(*) FROM TCOZ_ATFL WHERE ATFL_GRP = GRP_PHOTO_1 OR ATFL_GRP = GRP_PHOTO_2) > 0 THEN 'O' ELSE 'X' END AS ATFL_GRP_YN
                 , GRP_PHOTO_2          -- 첨부파일그룹2
                 , PHOTO_DESC_2         -- 사진설명2
              FROM TQHA_SAFECOST_ARSLT
             WHERE SIT_CD           = p_SIT_CD          -- 변수(현장코드)
               AND ITM_DIV          = p_ITM_DIV         -- 안전 9대항목  01 안전보건관리자 입금 02 안전시설비 03 보호구 04 안전보건진단비 05 안전보건 교육비 06 근조자 건강장해예방비  07기술지도비 08 본사점담조직  09 위험성평가에 다른 소모비용
               AND RLV_YM           = p_RLV_YM          -- 변수(년월)
             ORDER BY ITM_DIV, USE_DT
            ;

        ELSIF p_ITM_DIV = '09' THEN

            OPEN RTN_CURSOR FOR
            -- 당사 매월 사용실적 조회 (9 위험성평가 등에 따른 소요비용)
            SELECT SIT_CD               -- 현장코드
                 , ITM_DIV              -- 항목구분 (공통코드 QS026)
                 , (SELECT CD_NM FROM TCOA_COMCODE WHERE COM_CD = ITM_DIV AND HRNK_CD = 'QS026') AS ITM_DIV_NM
                 , RLV_YM               -- 해당년월
                 , USE_SEQ              -- 사용순번
                 , ITM_9                -- 품목명
                 , SAFE_DT9             -- 위험결정일자
                 , LAB_DT9              -- 노사결정일자
                   , PLN_UPRC_39        -- 계획단가
                   , PLN_QNT_39         -- 계획수량
                   , PLN_AMT_39         -- 계획금액
                 , USE_DT               -- 사용일자
                 , USE_UPRC             -- 사용단가
                 , USE_QNT              -- 사용수량
                 , USE_AMT              -- 사용금액
                 , USE_DTLS             -- 사용내역(지급내역)
                 , RMKS                 -- 비고
                 , GRP_PHOTO_1          -- 첨부파일그룹1
                 , PHOTO_DESC_1         -- 사진설명1
                 , DLV_VNDR             -- 납품업체
                 , CASE WHEN (SELECT COUNT(*) FROM TCOZ_ATFL WHERE ATFL_GRP = GRP_PHOTO_1 OR ATFL_GRP = GRP_PHOTO_2) > 0 THEN 'O' ELSE 'X' END AS ATFL_GRP_YN
                 , GRP_PHOTO_2          -- 첨부파일그룹2
                 , PHOTO_DESC_2         -- 사진설명2
              FROM TQHA_SAFECOST_ARSLT
             WHERE SIT_CD           = p_SIT_CD          -- 변수(현장코드)
               AND ITM_DIV          = p_ITM_DIV         -- 안전 9대항목  01 안전보건관리자 입금 02 안전시설비 03 보호구 04 안전보건진단비 05 안전보건 교육비 06 근조자 건강장해예방비  07기술지도비 08 본사점담조직  09 위험성평가에 다른 소모비용
               AND RLV_YM           = p_RLV_YM          -- 변수(년월)
             ORDER BY ITM_DIV, USE_DT
            ;

        END IF;

    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
         WHEN OTHERS THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);

END PQHA_SAFECOST_ARSLT_Q;
/

-- PQHA_SAFECOST_ARSLT_S (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_SAFECOST_ARSLT_S" (
    p_WRK_TP                    VARCHAR2 :='U'                                          -- UPDATE FLAG( I: ISNERT, U:UPDATE, D:DELTE)
,   p_WRK_ID                    VARCHAR2                                                -- 사용자 ID
,   p_WRK_IP                    VARCHAR2                                                -- 사용자 IP
,   p_SIT_CD                    TQHA_SAFECOST_ARSLT.SIT_CD              %TYPE           -- 현장코드
,   p_ITM_DIV                   TQHA_SAFECOST_ARSLT.ITM_DIV             %TYPE           -- 안전관리비 예산구분(QS026) 1 안전인건비
,   p_RLV_YM                    TQHA_SAFECOST_ARSLT.RLV_YM              %TYPE           -- 해당년월
,   p_USE_DT                    TQHA_SAFECOST_ARSLT.USE_DT              %TYPE           -- 사용일자
,   p_USE_SEQ                   TQHA_SAFECOST_ARSLT.USE_SEQ             %TYPE           -- 사용순번
,   p_USE_DTLS                  TQHA_SAFECOST_ARSLT.USE_DTLS            %TYPE           -- 사용내역
,   p_USE_UNT                   TQHA_SAFECOST_ARSLT.USE_UNT             %TYPE           -- 사용단위
,   p_USE_QNT                   TQHA_SAFECOST_ARSLT.USE_QNT             %TYPE           -- 사용수량
,   p_USE_UPRC                  TQHA_SAFECOST_ARSLT.USE_UPRC            %TYPE           -- 사용단가
,   p_USE_AMT                   TQHA_SAFECOST_ARSLT.USE_AMT             %TYPE           -- 사용금액
,   p_RMKS                      TQHA_SAFECOST_ARSLT.RMKS                %TYPE           -- 비고
,   p_GRP_PHOTO_1               TQHA_SAFECOST_ARSLT.GRP_PHOTO_1         %TYPE           -- 첨부파일그룹사진1
,   p_PHOTO_DESC_1              TQHA_SAFECOST_ARSLT.PHOTO_DESC_1        %TYPE           -- 사진설명1
,   p_BLN_18                    TQHA_SAFECOST_ARSLT.PNM_18              %TYPE           -- 소속
,   p_PNM_18                    TQHA_SAFECOST_ARSLT.PNM_18              %TYPE           -- 성명
,   p_PRCR_DT_18                TQHA_SAFECOST_ARSLT.PRCR_DT_18          %TYPE           -- 선임일자
--, p_LCST_UPRC_2               TQHA_SAFECOST_ARSLT.LCST_UPRC_2         %TYPE           -- 노무비단가 24.08.09 주석처리
--, p_MCST_UPRC_2               TQHA_SAFECOST_ARSLT.MCST_UPRC_2         %TYPE           -- 자재비단가 24.08.09 주석처리
,   p_PLN_UPRC_39               TQHA_SAFECOST_ARSLT.PLN_UPRC_39         %TYPE           -- 계획단가
,   p_PLN_QNT_39                TQHA_SAFECOST_ARSLT.PLN_QNT_39          %TYPE           -- 계획수량
,   p_PLN_AMT_39                TQHA_SAFECOST_ARSLT.PLN_AMT_39          %TYPE           -- 계획금액
,   p_DGS_ORG_4                 TQHA_SAFECOST_ARSLT.DGS_ORG_4           %TYPE           -- 진단기관
,   p_EDU_ATTL5                 TQHA_SAFECOST_ARSLT.EDU_ATTL5           %TYPE           -- 교육과목
,   p_EDU_SPNC_5                TQHA_SAFECOST_ARSLT.EDU_SPNC_5          %TYPE           -- 교육주관
,   p_PRTC_PSNNO_56             TQHA_SAFECOST_ARSLT.PRTC_PSNNO_56       %TYPE           -- 참가인원
,   p_DGS_HOSP6                 TQHA_SAFECOST_ARSLT.DGS_HOSP6           %TYPE           -- 진단병원
,   p_GUI_ATTL7                 TQHA_SAFECOST_ARSLT.GUI_ATTL7           %TYPE           -- 지도항목
,   p_GUI_ORG7                  TQHA_SAFECOST_ARSLT.GUI_ORG7            %TYPE           -- 지도기관
,   p_DTY_8                     TQHA_SAFECOST_ARSLT.DTY_8               %TYPE           -- 직책
,   p_DTY_DT8                   TQHA_SAFECOST_ARSLT.DTY_DT8             %TYPE           -- 보직일자
,   p_ITM_9                     TQHA_SAFECOST_ARSLT.ITM_9               %TYPE           -- 품목명
,   p_SAFE_DT9                  TQHA_SAFECOST_ARSLT.SAFE_DT9            %TYPE           -- 위험결정일자
,   p_LAB_DT9                   TQHA_SAFECOST_ARSLT.LAB_DT9             %TYPE           -- 노사결정일자
,   p_DLV_VNDR                  TQHA_SAFECOST_ARSLT.DLV_VNDR            %TYPE           -- 납품업체
,   p_GRP_PHOTO_2               TQHA_SAFECOST_ARSLT.GRP_PHOTO_2         %TYPE           -- 첨부파일그룹사진2
,   p_PHOTO_DESC_2              TQHA_SAFECOST_ARSLT.PHOTO_DESC_2        %TYPE           -- 사진설명2
)
IS
    /**************************************************************************************************************************
      Purpose : 당사 월별 실적 저장

      REVISIONS
      Ver      Date               Author                  Description
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2021/12/09 14:03:44                         최초생성

    **************************************************************************************************************************/



    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR2(200);            -- ERROR Message
    USER_EXCEPTION EXCEPTION;

    v_USE_SEQ TQHA_SAFECOST_ARSLT.USE_SEQ%TYPE ;             -- 산업안전보건관리비 순번 변수 선언

    v_APRV_STATS        VARCHAR2(20);
    v_APRV_STATS_NM     VARCHAR2(50);

BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 필수입력 필드  Check  ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_SIT_CD IS NULL)  THEN
        ERR_MSG := '현장코드는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_ITM_DIV IS NULL AND p_WRK_TP <> 'B')  THEN
        ERR_MSG := '안전관리비 예산구분(QS026) 1 안전인건비 는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_RLV_YM IS NULL AND p_WRK_TP <> 'B')  THEN
        ERR_MSG := '해당년월는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_USE_DT IS NULL AND p_WRK_TP <> 'B')  THEN
        ERR_MSG := '사용일자는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_USE_SEQ IS NULL AND p_WRK_TP <> 'I' AND p_WRK_TP <> 'B')  THEN
        ERR_MSG := '사용순번는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    ---------------------------------------------------------------------
    -- 결재상태 체크
    SELECT MAX(T2.APRV_STATS)
         , MAX(T3.CD_NM )
      INTO v_APRV_STATS
         , v_APRV_STATS_NM
      FROM TQHA_SAFECOST_APRV   T1
      LEFT JOIN TQHA_APRV       T2 ON T1.SIT_CD     = T2.SIT_CD
                                  AND T1.APRV_NO    = T2.APRV_NO
      LEFT JOIN TCOA_COMCODE    T3 ON T2.APRV_STATS = T3.COM_CD
                                  AND T3.HRNK_CD    = 'QS031'
     WHERE T1.SIT_CD    = p_SIT_CD
       AND T1.APRV_DIV  = '2'       -- 월별실적.
       AND T1.APRV_YM   = p_RLV_YM
    ;

    IF v_APRV_STATS IN ('2', '4') THEN
        ERR_MSG := '결재상태 [' || v_APRV_STATS_NM || ']인 데이터는 수정 불가합니다.';
        RAISE USER_EXCEPTION;
    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Process 선행조건 Check ]
    ---------------------------------------------------------------------------------------------------------------------------



    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Business Process ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_WRK_TP ='D') THEN

        DELETE
          FROM TQHA_SAFECOST_ARSLT
         WHERE SIT_CD       = p_SIT_CD          -- 현장코드
           AND ITM_DIV      = p_ITM_DIV         -- 안전관리비 예산구분(QS026) 1 안전인건비
           AND RLV_YM       = p_RLV_YM          -- 해당년월
           AND USE_DT       = p_USE_DT          -- 사용일자
           AND USE_SEQ      = p_USE_SEQ         -- 사용순번
        ;

    ELSIF (p_WRK_TP ='U') THEN

        UPDATE TQHA_SAFECOST_ARSLT
           SET USE_DTLS             = p_USE_DTLS                -- 사용내역
             , USE_UNT              = p_USE_UNT                 -- 사용단위
             , USE_QNT              = p_USE_QNT                 -- 사용수량
             , USE_UPRC             = p_USE_UPRC                -- 사용단가
             , USE_AMT              = p_USE_AMT                 -- 사용금액
             , RMKS                 = p_RMKS                    -- 비고
             , GRP_PHOTO_1          = p_GRP_PHOTO_1             -- 첨부파일그룹사진1
             , PHOTO_DESC_1         = p_PHOTO_DESC_1            -- 사진설명1
             , BLN_18               = p_BLN_18                  -- 소속
             , PNM_18               = p_PNM_18                  -- 성명
             , PRCR_DT_18           = p_PRCR_DT_18              -- 선임일자
--           , LCST_UPRC_2          = p_LCST_UPRC_2             -- 노무비단가 24.08.09 주석처리
--           , MCST_UPRC_2          = p_MCST_UPRC_2             -- 자재비단가 24.08.09 주석처리
             , PLN_UPRC_39          = p_PLN_UPRC_39             -- 계획단가
             , PLN_QNT_39           = p_PLN_QNT_39              -- 계획수량
             , PLN_AMT_39           = p_PLN_AMT_39              -- 계획금액
             , DGS_ORG_4            = p_DGS_ORG_4               -- 진단기관
             , EDU_ATTL5            = p_EDU_ATTL5               -- 교육과목
             , EDU_SPNC_5           = p_EDU_SPNC_5              -- 교육주관
             , PRTC_PSNNO_56        = p_PRTC_PSNNO_56           -- 참가인원
             , DGS_HOSP6            = p_DGS_HOSP6               -- 진단병원
             , GUI_ATTL7            = p_GUI_ATTL7               -- 지도항목
             , GUI_ORG7             = p_GUI_ORG7                -- 지도기관
             , DTY_8                = p_DTY_8                   -- 직책
             , DTY_DT8              = p_DTY_DT8                 -- 보직일자
             , ITM_9                = p_ITM_9                   -- 품목명
             , SAFE_DT9             = p_SAFE_DT9                -- 위험결정일자
             , LAB_DT9              = p_LAB_DT9                 -- 노사결정일자
             , DLV_VNDR             = p_DLV_VNDR                -- 납품업체
             , GRP_PHOTO_2          = p_GRP_PHOTO_2             -- 첨부파일그룹사진2
             , PHOTO_DESC_2         = p_PHOTO_DESC_2            -- 사진설명2
             , UPD_ID               = p_WRK_ID                  -- 수정ID
             , UPD_DTM              = SYSDATE()                 -- 수정일시
             , UPD_IP               = p_WRK_IP                  -- 수정IP
         WHERE SIT_CD               = p_SIT_CD                  -- 현장코드
           AND ITM_DIV              = p_ITM_DIV                 -- 안전관리비 예산구분(QS026) 1 안전인건비
           AND RLV_YM               = p_RLV_YM                  -- 해당년월
           AND USE_DT               = p_USE_DT                  -- 사용일자
           AND USE_SEQ              = p_USE_SEQ                 -- 사용순번
        ;

    ELSE

        -- 산업안전보건관리비 순번 생성
        SELECT NVL( (MAX(USE_SEQ)+1),'1' )
          INTO v_USE_SEQ
          FROM TQHA_SAFECOST_ARSLT
         WHERE SIT_CD       = p_SIT_CD          -- 현장코드
           AND ITM_DIV      = p_ITM_DIV         -- 안전관리비 예산구분(QS026) 1 안전인건비
           AND RLV_YM       = p_RLV_YM          -- 해당년월
           AND USE_DT       = p_USE_DT          -- 사용일자
        ;
        --

        INSERT 
          INTO TQHA_SAFECOST_ARSLT
             ( SIT_CD                   -- 현장코드
             , ITM_DIV                  -- 안전관리비 예산구분(QS026) 1 안전인건비
             , RLV_YM                   -- 해당년월
             , USE_DT                   -- 사용일자
             , USE_SEQ                  -- 사용순번
             , USE_DTLS                 -- 사용내역
             , USE_UNT                  -- 사용단위
             , USE_QNT                  -- 사용수량
             , USE_UPRC                 -- 사용단가
             , USE_AMT                  -- 사용금액
             , RMKS                     -- 비고
             , GRP_PHOTO_1              -- 첨부파일그룹사진1
             , PHOTO_DESC_1             -- 사진설명1
             , BLN_18                   -- 소속
             , PNM_18                   -- 성명
             , PRCR_DT_18               -- 선임일자
--           , LCST_UPRC_2              -- 노무비단가 24.08.09 주석처리
--           , MCST_UPRC_2              -- 자재비단가 24.08.09 주석처리
             , PLN_UPRC_39              -- 계획단가
             , PLN_QNT_39               -- 계획수량
             , PLN_AMT_39               -- 계획금액
             , DGS_ORG_4                -- 진단기관
             , EDU_ATTL5                -- 교육과목
             , EDU_SPNC_5               -- 교육주관
             , PRTC_PSNNO_56            -- 참가인원
             , DGS_HOSP6                -- 진단병원
             , GUI_ATTL7                -- 지도항목
             , GUI_ORG7                 -- 지도기관
             , DTY_8                    -- 직책
             , DTY_DT8                  -- 보직일자
             , ITM_9                    -- 품목명
             , SAFE_DT9                 -- 위험결정일자
             , LAB_DT9                  -- 노사결정일자
             , DLV_VNDR                 -- 납품업체
             , GRP_PHOTO_2              -- 첨부파일그룹사진2
             , PHOTO_DESC_2             -- 사진설명2
             , IPT_ID                   -- 입력ID
             , IPT_DTM                  -- 입력일시
             , IPT_IP                   -- 입력IP
             , UPD_ID                   -- 수정ID
             , UPD_DTM                  -- 수정일시
             , UPD_IP                   -- 수정IP
             )
        VALUES 
             ( p_SIT_CD                 -- 현장코드
             , p_ITM_DIV                -- 안전관리비 예산구분(QS026) 1 안전인건비
             , p_RLV_YM                 -- 해당년월
             , p_USE_DT                 -- 사용일자
             , v_USE_SEQ                -- 사용순번
             , p_USE_DTLS               -- 사용내역
             , p_USE_UNT                -- 사용단위
             , p_USE_QNT                -- 사용수량
             , p_USE_UPRC               -- 사용단가
             , p_USE_AMT                -- 사용금액
             , p_RMKS                   -- 비고
             , p_GRP_PHOTO_1            -- 첨부파일그룹사진1
             , SUBSTRB(p_USE_DT||','||v_USE_SEQ||','||p_USE_DTLS ,0, 100)          --사진설명1
             , p_BLN_18                 -- 소속
             , p_PNM_18                 -- 성명
             , p_PRCR_DT_18             -- 선임일자
--           , p_LCST_UPRC_2            -- 노무비단가 24.08.09 주석처리
--           , p_MCST_UPRC_2            -- 자재비단가 24.08.09 주석처리
             , p_PLN_UPRC_39            -- 계획단가
             , p_PLN_QNT_39             -- 계획수량
             , p_PLN_AMT_39             -- 계획금액
             , p_DGS_ORG_4              -- 진단기관
             , p_EDU_ATTL5              -- 교육과목
             , p_EDU_SPNC_5             -- 교육주관
             , p_PRTC_PSNNO_56          -- 참가인원
             , p_DGS_HOSP6              -- 진단병원
             , p_GUI_ATTL7              -- 지도항목
             , p_GUI_ORG7               -- 지도기관
             , p_DTY_8                  -- 직책
             , p_DTY_DT8                -- 보직일자
             , p_ITM_9                  -- 품목명
             , p_SAFE_DT9               -- 위험결정일자
             , p_LAB_DT9                -- 노사결정일자
             , p_DLV_VNDR               -- 납품업체
             , p_GRP_PHOTO_2            -- 첨부파일그룹사진1
             , SUBSTRB(p_USE_DT||','||v_USE_SEQ||','||p_USE_DTLS ,0, 100)          --사진설명2
             , p_WRK_ID                 -- 입력ID
             , SYSDATE()                -- 입력일시
             , p_WRK_IP                 -- 입력IP
             , p_WRK_ID                 -- 수정ID
             , SYSDATE()                -- 수정일시
             , p_WRK_IP                 -- 수정IP
             )
        ;

    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 5. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);

END ;
/

-- PQHA_SAFECOST_BGTYM_B (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_SAFECOST_BGTYM_B" 
                            (p_WRK_TP  VARCHAR2 :='U'                  -- UPDATE FLAG
                            ,p_WRK_ID  VARCHAR2                                           -- 사용자 ID 
                            ,p_WRK_IP  VARCHAR2                                           -- 사용자 IP 
                            ,p_SIT_CD 		VARCHAR2                   -- 현장코드
                            ,p_STR_DT		VARCHAR2                   -- 시작일자 
                            ,p_END_DT 		VARCHAR2)                  -- 종료일자
IS 
    /**************************************************************************************************************************
      Purpose : 예산 생성

      REVISIONS
      Ver      Date               Author                  Description 
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2024/05/08 14:05:17                         최초생성
    **************************************************************************************************************************/


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR2(200);            -- ERROR Message
    USER_EXCEPTION EXCEPTION;


BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 필수입력 필드  Check  ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_SIT_CD IS NULL)  THEN
        ERR_MSG := '현장코드는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_STR_DT IS NULL)  THEN
        ERR_MSG := '공사 시작일자는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

       IF (p_END_DT IS NULL)  THEN
        ERR_MSG := '공사 종료일자는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;
    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Process 선행조건 Check ]
    ---------------------------------------------------------------------------------------------------------------------------


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Business Process ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_WRK_TP ='B') THEN  -- 자동생성 ( 배치 )
       --  9대항목별 전체예산 추가  TQHA_SAFECOST_BGT
		MERGE INTO TQHA_SAFECOST_BGT T
		USING ( -- -- 공통코드에 등록된 안전관리비 항목
				    SELECT p_SIT_CD AS SIT_CD  -- p_SIT_CD                           -- 변수 (현장코드)
				           , COM_CD 
				           , CD_NM
					  FROM TCOA_COMCODE
					 WHERE HRNK_CD = 'QS026'   -- 상위코드가 'QS026'
					   AND USE_YN = '1'        -- 사용여부
					ORDER BY COM_CD			
		       ) S
		   ON (T.SIT_CD = S.SIT_CD AND T.ITM_DIV = S.COM_CD )
		WHEN MATCHED
			THEN UPDATE SET
		           T.WHL_EBGT_BGT  = 0                           -- 전체실행예산
		         , T.UPD_ID        = p_WRK_ID                    --수정ID
				 , T.UPD_DTM       = SYSDATE()                   --수정일시
				 , T.UPD_IP        = p_WRK_IP                    --수정IP
		WHEN NOT MATCHED
			THEN INSERT ( SIT_CD                         --현장코드 
			            , ITM_DIV                        --항목구분
			            , WHL_EBGT_BGT                   --전체실행예산
			            , T.IPT_ID                       --입력ID 
					    , T.IPT_DTM                      --입력일시
					    , T.IPT_IP)                      --입력IP
			     VALUES ( S.SIT_CD                          --현장코드 
			            , S.COM_CD                          --항목구분
			            , 0                                 --전체실행예산
                        , p_WRK_ID                          --입력ID 
				        , SYSDATE()                         --입력일시
				        , p_WRK_IP);                        --입력IP

          -- 9대항목별 월별예산 TQHA_SAFECOST_BGTYM

        BEGIN
            FOR SAFE_TBGT IN (  -- 시작일자부터 종료일자까지의 해당월을 생성
								SELECT to_char(ADD_MONTHS(Sdate, LEVEL-1), 'yyyymm') AS RLV_YM
								  FROM (
									     SELECT TO_DATE (p_STR_DT, 'YYYYMMDD') AS sdate, TO_DATE (p_END_DT, 'YYYYMMDD') AS Edate
										   FROM DUAL  
									   )
								CONNECT BY LEVEL <=  months_between(Edate+1, Sdate) 								       )                         
            LOOP

                   --9대항목별 월별예산 TQHA_SAFECOST_BGTYM
					MERGE INTO TQHA_SAFECOST_BGTYM  T
					USING ( -- -- 공통코드에 등록된 안전관리비 항목
							    SELECT p_SIT_CD AS SIT_CD  -- p_SIT_CD                           -- 변수 (현장코드)
							           , COM_CD 
								  FROM TCOA_COMCODE
								 WHERE HRNK_CD = 'QS026'   -- 상위코드가 'QS026'
								   AND USE_YN = '1'        -- 사용여부
								ORDER BY COM_CD			
					       )  S
					   ON (T.SIT_CD = S.SIT_CD AND T.ITM_DIV = S.COM_CD AND T.RLV_YM = SAFE_TBGT.RLV_YM)
					WHEN MATCHED
						THEN UPDATE SET
					           T.BYM_EBGT_BGT  = 0                           -- 월별실행예산
					         , T.CHG_EBGT_BGT  = 0                           -- 변경실행예산			           
					         , T.UPD_ID        = p_WRK_ID                    --수정ID
							 , T.UPD_DTM       = SYSDATE()                   --수정일시
							 , T.UPD_IP        = p_WRK_IP                    --수정IP
					WHEN NOT MATCHED
						THEN INSERT ( SIT_CD                         --현장코드 
						            , ITM_DIV                        --항목구분
						            , RLV_YM                         --해당년월
						            , BYM_EBGT_BGT                   --월별실행예산
						            , CHG_EBGT_BGT                   --변경실행예산			            
						            , T.IPT_ID                       --입력ID 
								    , T.IPT_DTM                      --입력일시
								    , T.IPT_IP)                      --입력IP
						     VALUES ( S.SIT_CD                          --현장코드 
						            , S.COM_CD                          --항목구분
						            , SAFE_TBGT.RLV_YM                  --해당년월
						            , 0                                 --월별실행예산
						            , 0                                 --변경실행예산			            
                                    , p_WRK_ID                          --입력ID 
							        , SYSDATE()                         --입력일시
							        , p_WRK_IP);                        --입력IP  
						    ---------------------------------------------------------------------------------------------------------------------------------------------------
            END LOOP;

        END;


    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 5. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN 
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);
END ;
/

-- PQHA_SAFECOST_BGTYM_CHG_BGT_S (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_SAFECOST_BGTYM_CHG_BGT_S" (
    p_WRK_TP            VARCHAR2 :='U'      -- UPDATE FLAG( I: ISNERT, U:UPDATE, D:DELTE)
,   p_WRK_ID            VARCHAR2            -- 사용자 ID 
,   p_WRK_IP            VARCHAR2            -- 사용자 IP 
,   p_SIT_CD            VARCHAR2            -- 현장코드
,   p_ITM_DIV           VARCHAR2            -- 안전관리비 예산구분(QS026) 1 안전인건비 
,   p_RLV_YM            VARCHAR2            -- 해당년월
,   p_CHG_EBGT_BGT      NUMBER              -- 변경실행예산
)
IS 
    /**************************************************************************************************************************
      Purpose : 

      REVISIONS
      Ver      Date               Author                  Description 
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2026/02/12                                   최초생성

    **************************************************************************************************************************/

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR2(200);            -- ERROR Message
    USER_EXCEPTION EXCEPTION;

    v_APRV_STATS        VARCHAR2(20);
    v_APRV_STATS_NM     VARCHAR2(50);

BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 필수입력 필드  Check  ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_SIT_CD IS NULL)  THEN
        ERR_MSG := '현장코드는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_ITM_DIV IS NULL)  THEN
        ERR_MSG := '안전관리비 예산구분은 필수 입력사항 입니다.'; 
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_RLV_YM IS NULL)  THEN
        ERR_MSG := '년월은 필수 입력사항 입니다.'; 
        RAISE USER_EXCEPTION;
    END IF;

    ---------------------------------------------------------------------
    -- 결재상태 체크
    SELECT MAX(T2.APRV_STATS)
         , MAX(T3.CD_NM )
      INTO v_APRV_STATS
         , v_APRV_STATS_NM
      FROM TQHA_SAFECOST_APRV   T1
      LEFT JOIN TQHA_APRV       T2 ON T1.SIT_CD     = T2.SIT_CD
                                  AND T1.APRV_NO    = T2.APRV_NO
      LEFT JOIN TCOA_COMCODE    T3 ON T2.APRV_STATS = T3.COM_CD 
                                  AND T3.HRNK_CD    = 'QS031'
     WHERE T1.SIT_CD    = p_SIT_CD
       AND T1.APRV_DIV  = '2'       -- 월별실적.
       AND T1.APRV_YM   = p_RLV_YM
    ;

    IF v_APRV_STATS IN ('2', '4') THEN
        ERR_MSG := '결재상태 [' || v_APRV_STATS_NM || ']인 데이터는 수정 불가합니다.';
        RAISE USER_EXCEPTION;
    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Process 선행조건 Check ]
    ---------------------------------------------------------------------------------------------------------------------------



    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Business Process ]
    ---------------------------------------------------------------------------------------------------------------------------

    ----------------------------------------------------------------------------------------------------
    -- 안전관리비 월별예산 : 변경실행예산 저장 .
    IF (p_WRK_TP ='U') THEN

        MERGE INTO TQHA_SAFECOST_BGTYM
            USING DUAL
        ON (    SIT_CD  = p_SIT_CD 
            AND ITM_DIV = p_ITM_DIV 
            AND RLV_YM  = p_RLV_YM)
        WHEN MATCHED THEN
            UPDATE 
               SET CHG_EBGT_BGT = p_CHG_EBGT_BGT
                 , UPD_ID       = p_WRK_ID
                 , UPD_DTM      = SYSDATE
                 , UPD_IP       = p_WRK_IP
        WHEN NOT MATCHED THEN
            INSERT (SIT_CD, ITM_DIV, RLV_YM, IPT_ID, IPT_DTM, IPT_IP, UPD_ID, UPD_DTM, UPD_IP, CHG_EBGT_BGT)
            VALUES (p_SIT_CD, p_ITM_DIV, p_RLV_YM, p_WRK_ID, SYSDATE, p_WRK_IP, p_WRK_ID, SYSDATE, p_WRK_IP, p_CHG_EBGT_BGT)
        ;

    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 5. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN 
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);
END ;
/

-- PQHA_SAFECOST_BGTYM_Q (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_SAFECOST_BGTYM_Q" (
    p_WRK_TP            IN VARCHAR2 DEFAULT 'Q'             -- FLAG(Q: 현장평가, Q1:본사평가)
,   p_SIT_CD            IN VARCHAR2
,   p_SEARCH_STR_YM     IN VARCHAR2
,   RTN_CURSOR          OUT SYS_REFCURSOR
)
IS
    /**************************************************************************************************************************
      Purpose : [평가항목 조회] PROCEDRE (QSE > 안전관리 > 산업안전보건관리비 > 월별실적관리  )

      REVISIONS
      Ver      Date               Author                  Description
      -------  -----------------  ----------------------  ---------------------------------------------------------------------
      1.0      2023/12/05                                 최초생성

    **************************************************************************************************************************/

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE  NUMBER :=-20009; -- ERROR 코드
    ERR_MSG   VARCHAR(200);    -- ERROR Message
    USER_EXCEPTION EXCEPTION;

BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 수행전 Check Logic ]
    ---------------------------------------------------------------------------------------------------------------------------

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Logic 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------

    IF p_WRK_TP = 'Q' THEN

        OPEN RTN_CURSOR FOR
        SELECT A.SIT_CD                                                                                                                                 -- 현장코드
             , (SELECT APRV_NO  FROM TQHA_SAFECOST_APRV WHERE SIT_CD = p_SIT_CD AND APRV_DIV = '2' AND APRV_YM = p_SEARCH_STR_YM)   AS APRV_NO          -- 추가
             , (SELECT ATFL_GRP FROM TQHA_SAFECOST_APRV WHERE SIT_CD = p_SIT_CD AND APRV_DIV = '2' AND APRV_YM = p_SEARCH_STR_YM)   AS ATFL_GRP         -- 추가
--             , (SELECT B.APRV_STATS
--                FROM TQHA_SAFECOST_APRV A,
--                     TQHA_APRV B
--                WHERE A.APRV_NO = B.APRV_NO
--                  AND A.SIT_CD = B.SIT_CD
--                  AND A.SIT_CD = p_SIT_CD
--                  AND A.APRV_DIV = '2'
--                  AND A.APRV_YM = p_SEARCH_STR_YM)                                                                                AS APRV_STATS       -- 결재상태 추가
             , Z.APRV_STATS
             , '▶ 결재상태 : ' || NVL(( SELECT CD_NM FROM TCOA_COMCODE WHERE HRNK_CD = 'QS031' AND COM_CD = Z.APRV_STATS ), '-')    AS APRV_STATS_NM    -- 결재상태명
             , A.ITM_DIV                                                                                                                                -- 항목구분 (공통코드 QS026)
             , (SELECT CD_NM FROM TCOA_COMCODE WHERE COM_CD = A.ITM_DIV AND HRNK_CD = 'QS026')                                      AS ITM_DIV_NM
             , NVL(A.CHG_EBGT_BGT, 0)                                                                                               AS CHG_EBGT_BGT     -- 변경 실행예산
             , (NVL(C.C_USE_AMT, 0) + NVL(C1.C_USE_AMT, 0)) - (NVL(B.T_USE_AMT, 0) + NVL(B1.T_USE_AMT, 0))                          AS P_USE_AMT        -- 전월 사용금액 ( 당사 + 협력업체)
             , (NVL(B.T_USE_AMT, 0) + NVL(B1.T_USE_AMT, 0))                                                                         AS T_USE_AMT        -- 당월 사용금액 ( 당사 + 협력업체)
             , (NVL(C.C_USE_AMT, 0) + NVL(C1.C_USE_AMT, 0))                                                                         AS C_USE_AMT        -- 누계 사용금액 ( 당사 + 협력업체)
             , (NVL(A.CHG_EBGT_BGT, 0) - (NVL(C.C_USE_AMT, 0) + NVL(C1.C_USE_AMT, 0)))                                              AS REMAIN_ALL       -- 전체잔액
             , ROUND( ((NVL(C.C_USE_AMT, 0) + NVL(C1.C_USE_AMT, 0))) / DECODE(A.CHG_EBGT_BGT, 0, NULL, A.CHG_EBGT_BGT) * 100 * 100) / 100  AS USE_RATE  -- 사용율
             , RLV_YM
          FROM TQHA_SAFECOST_BGTYM A
             , (  -- 당사 당월 사용금액   
                  SELECT SIT_CD
                       , ITM_DIV
                       , NVL(SUM(USE_AMT), 0)     AS T_USE_AMT        -- 당월 사용금액
                    FROM TQHA_SAFECOST_ARSLT
                   WHERE SIT_CD                   = p_SIT_CD          -- 변수 (현장코드)
                     AND SUBSTR(RLV_YM, 1, 6)     = p_SEARCH_STR_YM   -- 변수 (년도)
                   GROUP BY SIT_CD, ITM_DIV
                   ORDER BY SIT_CD, ITM_DIV
               ) B
             , (  -- 업체 당월 사용금액
                  SELECT A.SIT_CD                                     -- 현장코드
                      , ITM_DIV                           
                      , NVL(SUM(USE_AMT), 0)      AS T_USE_AMT        -- 업체 당월 금액
                   FROM TQHA_SAFECOST_ARSLT_CO    A
                      , TQHA_SAFECOST_MMARSLT_CO  B
                  WHERE A.SIT_CD                  = p_SIT_CD          -- 변수 (현장코드)
                    AND SUBSTR(A.RLV_YM, 1, 6)    = p_SEARCH_STR_YM   -- 변수 (년도)
                    AND A.SIT_CD                  = B.SIT_CD(+)
                    AND A.CUST_CD                 = B.CUST_CD(+)
                    AND A.VNDR_SEQ                = B.VNDR_SEQ(+)
                    AND A.RLV_YM                  = B.RLV_YM(+)
                    AND B.SITE_APRV_YN            = '1'
                  GROUP BY A.SIT_CD, ITM_DIV
               ) B1
             , (  -- 당사 누계 사용금액
                  SELECT SIT_CD
                       , ITM_DIV
                       , NVL(SUM(USE_AMT), 0)     AS C_USE_AMT        -- 누계 사용금액
                    FROM TQHA_SAFECOST_ARSLT
                   WHERE SIT_CD = p_SIT_CD                            -- 변수 (현장코드)
                     AND SUBSTR(RLV_YM, 1, 6) <= p_SEARCH_STR_YM      -- 변수 (년도)
                   GROUP BY SIT_CD, ITM_DIV
                   ORDER BY SIT_CD, ITM_DIV
               ) C
             , (  -- 업체 누계 사용금액
                  SELECT A.SIT_CD                                     -- 현장코드
                      , ITM_DIV                                       --
                      , NVL(SUM(USE_AMT), 0)      AS C_USE_AMT        -- 업체 당월 금액
                   FROM TQHA_SAFECOST_ARSLT_CO    A
                      , TQHA_SAFECOST_MMARSLT_CO  B
                  WHERE A.SIT_CD                  = p_SIT_CD          -- 변수 (현장코드)
                    AND SUBSTR(A.RLV_YM, 1, 6)    <= p_SEARCH_STR_YM  -- 변수 (년도)
                    AND A.SIT_CD                  = B.SIT_CD(+)
                    AND A.CUST_CD                 = B.CUST_CD(+)
                    AND A.VNDR_SEQ                = B.VNDR_SEQ(+)
                    AND A.RLV_YM                  = B.RLV_YM(+)
                    AND B.SITE_APRV_YN            = '1'
                  GROUP BY A.SIT_CD, ITM_DIV
               ) C1
             , TQHA_SAFECOST_APRV X
             , TQHA_APRV          Z
         WHERE A.SIT_CD                 = p_SIT_CD              -- 변수 (현장코드)
           AND SUBSTR(A.RLV_YM, 1, 6)   = p_SEARCH_STR_YM -- 변수 (년월)
           AND A.SIT_CD                 = B.SIT_CD(+)
           AND A.SIT_CD                 = C.SIT_CD(+)
           AND A.SIT_CD                 = B1.SIT_CD(+)
           AND A.SIT_CD                 = C1.SIT_CD(+)
           AND A.ITM_DIV                = B.ITM_DIV(+)
           AND A.ITM_DIV                = C.ITM_DIV(+)
           AND A.ITM_DIV                = B1.ITM_DIV(+)
           AND A.ITM_DIV                = C1.ITM_DIV(+)
           AND A.SIT_CD                 = X.SIT_CD(+)
           AND SUBSTR(A.RLV_YM, 1, 6)   = X.APRV_YM(+)
           AND X.APRV_DIV(+)            = '2'
           AND X.SIT_CD                 = Z.SIT_CD(+)
           AND X.APRV_NO                = Z.APRV_NO(+)
         ORDER BY A.ITM_DIV
        ;

    --------------------------------------------------------------------------------
    -- get_SafeCostDuration
    ELSIF p_WRK_TP = 'Q2' THEN

        OPEN RTN_CURSOR FOR
        SELECT MIN(RLV_YM)  AS RLV_YM_MIN
             , MAX(RLV_YM)  AS RLV_YM_MAX
          FROM TQHA_SAFECOST_BGTYM
         WHERE SIT_CD   = p_SIT_CD
        ;

    --------------------------------------------------------------------------------
    -- 당사 당월 사용금액
    ELSIF p_WRK_TP = 'Q3' THEN

        OPEN RTN_CURSOR FOR
        SELECT A.SIT_CD
		     , A.ITM_DIV
		     , CC.CD_NM AS ITM_DIV_NM
		
		     /* =========================
		        당사
		        ========================= */
		     , NVL(C.C_USE_AMT,0) - NVL(B.T_USE_AMT,0)             AS OWN_P_USE_AMT    -- 전월누계
		     , NVL(B.T_USE_AMT,0)                                  AS OWN_T_USE_AMT      -- 당월
		     , NVL(C.C_USE_AMT,0)                                  AS OWN_C_USE_AMT      -- 누계
		
		     /* =========================
		        협력사
		        ========================= */
		     , NVL(E.C_USE_AMT,0) - NVL(D.T_USE_AMT,0)             AS CO_P_USE_AMT     -- 전월누계
		     , NVL(D.T_USE_AMT,0)                                  AS CO_T_USE_AMT       -- 당월
		     , NVL(E.C_USE_AMT,0)                                  AS CO_C_USE_AMT       -- 누계
		
		FROM TQHA_SAFECOST_BGTYM A
		
		/* =========================
		   당사 당월
		   ========================= */
		LEFT JOIN (
		    SELECT SIT_CD
		         , ITM_DIV
		         , SUM(USE_AMT) AS T_USE_AMT
		      FROM TQHA_SAFECOST_ARSLT
		     WHERE SIT_CD = p_SIT_CD
		       AND SUBSTR(RLV_YM,1,6) = p_SEARCH_STR_YM
		     GROUP BY SIT_CD
		            , ITM_DIV
		) B
		ON A.SIT_CD = B.SIT_CD
		AND A.ITM_DIV = B.ITM_DIV
		
		/* =========================
		   당사 누계
		   ========================= */
		LEFT JOIN (
		    SELECT SIT_CD
		         , ITM_DIV
		         , SUM(USE_AMT) AS C_USE_AMT
		      FROM TQHA_SAFECOST_ARSLT
		     WHERE SIT_CD = p_SIT_CD
		       AND SUBSTR(RLV_YM,1,6) <= p_SEARCH_STR_YM
		     GROUP BY SIT_CD
		            , ITM_DIV
		) C
		ON A.SIT_CD = C.SIT_CD
		AND A.ITM_DIV = C.ITM_DIV
		
		/* =========================
		   협력사 당월
		   ========================= */
		LEFT JOIN (
		    SELECT SIT_CD
		         , ITM_DIV
		         , SUM(USE_AMT) AS T_USE_AMT
		      FROM TQHA_SAFECOST_ARSLT_CO
		     WHERE SIT_CD = p_SIT_CD
		       AND RLV_YM = p_SEARCH_STR_YM
		     GROUP BY SIT_CD
		            , ITM_DIV
		) D
		ON A.SIT_CD = D.SIT_CD
		AND A.ITM_DIV = D.ITM_DIV
		
		/* =========================
		   협력사 누계
		   ========================= */
		LEFT JOIN (
		    SELECT SIT_CD
		         , ITM_DIV
		         , SUM(USE_AMT) AS C_USE_AMT
		      FROM TQHA_SAFECOST_ARSLT_CO
		     WHERE SIT_CD = p_SIT_CD
		       AND RLV_YM <= p_SEARCH_STR_YM
		     GROUP BY SIT_CD
		            , ITM_DIV
		) E
		ON A.SIT_CD = E.SIT_CD
		AND A.ITM_DIV = E.ITM_DIV
		
		/* 항목명 */
		LEFT JOIN TCOA_COMCODE CC
		       ON CC.HRNK_CD = 'QS026'
		      AND CC.COM_CD  = A.ITM_DIV
		
		WHERE A.SIT_CD = p_SIT_CD
		  AND SUBSTR(A.RLV_YM,1,6) = p_SEARCH_STR_YM
		
		ORDER BY A.ITM_DIV;
        
        
        /*
        --  당사 월별 실적관리
        SELECT A.SIT_CD                                                                                         -- 현장코드
             , A.ITM_DIV                                                                                        -- 항목구분 (공통코드 QS026)
             , (SELECT CD_NM FROM TCOA_COMCODE WHERE COM_CD = A.ITM_DIV AND HRNK_CD = 'QS026')  AS ITM_DIV_NM
             , NVL(B.T_USE_AMT, 0)                                                              AS T_USE_AMT    -- 당월 사용금액
             , NVL(C.C_USE_AMT, 0)                                                              AS C_USE_AMT    -- 누계 사용금액
          FROM TQHA_SAFECOST_BGTYM A
             , (-- 당월 사용금액
                SELECT SIT_CD                                       -- 현장코드
                     , ITM_DIV                                      -- 항목구분 (공통코드 QS026)
                     , NVL(SUM(USE_AMT), 0)     AS T_USE_AMT        -- 당월 사용금액
                  FROM TQHA_SAFECOST_ARSLT
                 WHERE SIT_CD                  = p_SIT_CD           -- 변수(현장코드)
                   -- AND ITM_DIV              = '02'               -- 변수(항목구분 공통코드 QS026)
                   AND SUBSTR(RLV_YM, 1, 6)    = p_SEARCH_STR_YM    -- 변수(년월)
                 GROUP BY SIT_CD, ITM_DIV
               ) B
             , (-- 누계 사용금액
                SELECT SIT_CD
                     , ITM_DIV
                     , NVL(SUM(USE_AMT), 0)     AS C_USE_AMT        -- 누계 사용금액
                  FROM TQHA_SAFECOST_ARSLT
                 WHERE SIT_CD                  = p_SIT_CD           -- 변수 (현장코드)
                   AND SUBSTR(RLV_YM, 1, 6)    <= p_SEARCH_STR_YM   -- 변수 (년도)
                 GROUP BY SIT_CD, ITM_DIV
                 ORDER BY SIT_CD, ITM_DIV
               ) C
         WHERE A.SIT_CD                 = p_SIT_CD              -- 변수 (현장코드)
           AND SUBSTR(A.RLV_YM, 1, 6)   = p_SEARCH_STR_YM       -- 변수 (년월)
           AND A.SIT_CD                 = B.SIT_CD(+)
           AND A.SIT_CD                 = C.SIT_CD(+)
           AND A.ITM_DIV                = B.ITM_DIV(+)
           AND A.ITM_DIV                = C.ITM_DIV(+)
         ORDER BY A.ITM_DIV
        ;
		*/
    --------------------------------------------------------------------------------
    -- 업체별 당월 사용금액
    ELSIF p_WRK_TP = 'Q4' THEN

        OPEN RTN_CURSOR FOR
        SELECT (SELECT CUST_NM FROM VQSZ_TRADE WHERE CUST_CD = A.CUST_CD)   AS CUST_NM      -- 업체명
             , A.SIT_CD                                                                     -- 현장코드
             , A.CUST_CD                                                                    -- 업체코드
             , (SELECT CUST_NM FROM VQSZ_TRADE WHERE CUST_CD = A.CUST_CD)   AS COP_VNDR_NM  -- 업체명
             , A.VNDR_SEQ                                                                   -- CUST_NM
             , A.RLV_YM                                                                     -- 년월
             , B.T_USE_AMT                                                                  -- 당월금액
             , C.C_USE_AMT                                                                  -- 누계금액
             , (C.C_USE_AMT - B.T_USE_AMT)   AS  P_USE_AMT                                    -- 전원누계금액
             , NVL(A.VNDR_APRV_YN, 0)                                       AS VNDR_APRV_YN -- 업체승인요청여부
             , A.VNDR_APRV_DT                                                               -- 업체승인일자
             , NVL(A.SITE_APRV_YN, 0)                                       AS SITE_APRV_YN -- 현장승인여부
             , A.SITE_APRV_DT                                                               -- 현장승인일자
          FROM TQHA_SAFECOST_MMARSLT_CO A
             , ( -- 당월 금액
                SELECT SIT_CD                                   -- 현장코드
                     , CUST_CD                                  -- 업체코드
                     , VNDR_SEQ                                 -- 업체순번
                     , RLV_YM                                   -- 해당년월
                     , NVL(SUM(USE_AMT), 0) AS T_USE_AMT        -- 당월 금액
                  FROM TQHA_SAFECOST_ARSLT_CO
                 WHERE SIT_CD      = p_SIT_CD                   -- 변수 (현장코드)
                   AND RLV_YM      = p_SEARCH_STR_YM            -- 변수 (해당년월)
                 GROUP BY SIT_CD, CUST_CD, VNDR_SEQ, RLV_YM
               ) B
             , ( -- 누계 금액
                SELECT SIT_CD                                   -- 현장코드
                     , CUST_CD                                  -- 업체코드
                     , VNDR_SEQ                                 -- 업체순번
                     , NVL(SUM(USE_AMT), 0) C_USE_AMT           -- 누계 금액
                  FROM TQHA_SAFECOST_ARSLT_CO
                 WHERE SIT_CD       = p_SIT_CD                  -- 변수 (현장코드)
                   AND RLV_YM       <= p_SEARCH_STR_YM          -- 변수 (해당년월)
                 GROUP BY SIT_CD, CUST_CD, VNDR_SEQ
               ) C
         WHERE A.SIT_CD     = p_SIT_CD          -- 변수 (현장코드)
           AND A.RLV_YM     = p_SEARCH_STR_YM   -- 변수 (해당년월)
           AND A.SIT_CD     = B.SIT_CD(+)
           AND A.SIT_CD     = C.SIT_CD(+)
           AND A.CUST_CD    = B.CUST_CD(+)
           AND A.CUST_CD    = C.CUST_CD(+)
           AND A.VNDR_SEQ   = B.VNDR_SEQ(+)
           AND A.VNDR_SEQ   = C.VNDR_SEQ(+)
        ;

    END IF;


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
         WHEN OTHERS THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);

END PQHA_SAFECOST_BGTYM_Q;
/

-- PQHA_SAFECOST_BGTYM_S (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_SAFECOST_BGTYM_S" (
    p_WRK_TP                VARCHAR2 :='U'                                      -- UPDATE FLAG( I: ISNERT, U:UPDATE, D:DELTE, B:배치성 일괄삭제)
,   p_WRK_ID                VARCHAR2                                            -- 사용자 ID
,   p_WRK_IP                VARCHAR2                                            -- 사용자 IP
,   p_SIT_CD                TQHA_SAFECOST_BGTYM.SIT_CD              %TYPE       -- 현장코드
,   p_ITM_DIV               TQHA_SAFECOST_BGTYM.ITM_DIV             %TYPE       -- 안전관리비 예산구분(QS026) 1 안전인건비
,   p_RLV_YM                TQHA_SAFECOST_BGTYM.RLV_YM              %TYPE       -- 해당년월
,   p_BYM_EBGT_BGT          TQHA_SAFECOST_BGTYM.BYM_EBGT_BGT        %TYPE       -- 월별실행예산
--, p_CHG_EBGT_BGT          TQHA_SAFECOST_BGTYM.CHG_EBGT_BGT        %TYPE       -- 변경실행예산(22/04/01 추가)
)
IS
    /**************************************************************************************************************************
      Purpose : 안전관리 월별 예산 저장

      REVISIONS
      Ver      Date               Author                  Description
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2021/11/09 18:25:17                         최초생성
      2.0     2022/04/01 18:25:17                         변경 실해예산 추가(월별)
    **************************************************************************************************************************/


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR2(200);            -- ERROR Message
    USER_EXCEPTION EXCEPTION;


BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 필수입력 필드  Check  ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_SIT_CD IS NULL)  THEN
        ERR_MSG := '현장코드는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_ITM_DIV IS NULL AND p_WRK_TP <> 'B')  THEN
        ERR_MSG := '안전관리비 예산구분(QS026) 1 안전인건비 는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_RLV_YM IS NULL AND p_WRK_TP <> 'B')  THEN
        ERR_MSG := '해당년월는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Process 선행조건 Check ]
    ---------------------------------------------------------------------------------------------------------------------------



    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Business Process ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_WRK_TP ='D') THEN

        DELETE
          FROM TQHA_SAFECOST_BGTYM
         WHERE SIT_CD       = p_SIT_CD          -- 현장코드
           AND ITM_DIV      = p_ITM_DIV         -- 안전관리비 예산구분(QS026) 1 안전인건비
           AND RLV_YM       = p_RLV_YM          -- 해당년월
        ;

    ELSIF (p_WRK_TP ='U') THEN

        UPDATE TQHA_SAFECOST_BGTYM
           SET BYM_EBGT_BGT     = p_BYM_EBGT_BGT        -- 월별실행예산
             , UPD_ID           = p_WRK_ID              -- 수정ID
             , UPD_DTM          = SYSDATE()             -- 수정일시
             , UPD_IP           = p_WRK_IP              -- 수정IP
         WHERE SIT_CD           = p_SIT_CD              -- 현장코드
           AND ITM_DIV          = p_ITM_DIV             -- 안전관리비 예산구분(QS026) 1 안전인건비
           AND RLV_YM           = p_RLV_YM              -- 해당년월
        ;

    ELSIF (p_WRK_TP ='B') THEN

        DELETE
          FROM TQHA_SAFECOST_BGTYM
         WHERE SIT_CD = p_SIT_CD        -- 현장코드
        ;

    ELSE

        INSERT 
          INTO TQHA_SAFECOST_BGTYM
             ( SIT_CD               -- 현장코드
             , ITM_DIV              -- 안전관리비 예산구분(QS026) 1 안전인건비
             , RLV_YM               -- 해당년월
             , BYM_EBGT_BGT         -- 월별실행예산
--           , CHG_EBGT_BGT         --  변경실행예산(22/04/01 추가)
             , IPT_ID               -- 입력ID
             , IPT_DTM              -- 입력일시
             , IPT_IP               -- 입력IP
             , UPD_ID               -- 수정ID
             , UPD_DTM              -- 수정일시
             , UPD_IP               -- 수정IP
             )
        VALUES 
             ( p_SIT_CD             -- 현장코드
             , p_ITM_DIV            -- 안전관리비 예산구분(QS026) 1 안전인건비
             , p_RLV_YM             -- 해당년월
             , p_BYM_EBGT_BGT       -- 월별실행예산
--           , p_CHG_EBGT_BGT       -- 변경실행예산(22/04/01 추가)
             , p_WRK_ID             -- 입력ID
             , SYSDATE()            -- 입력일시
             , p_WRK_IP             -- 입력IP
             , p_WRK_ID             -- 수정ID
             , SYSDATE()            -- 수정일시
             , p_WRK_IP             -- 수정IP
             )
        ;

    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 5. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);

END ;
/

-- PQHA_SAFECOST_BGT_Q (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_SAFECOST_BGT_Q" (  
    p_WRK_TP        IN VARCHAR2 DEFAULT 'Q'             -- FLAG(Q: 현장평가, Q1:본사평가)
,   p_SIT_CD        IN VARCHAR2 
,   RTN_CURSOR      OUT SYS_REFCURSOR
)
IS
    /**************************************************************************************************************************
      Purpose : [평가항목 조회] PROCEDRE (QSE > 안전관리 > 협력업체 안전평가 > 현장평가, 본사평가 )

      REVISIONS
      Ver      Date               Author                  Description
      -------  -----------------  ----------------------  ---------------------------------------------------------------------
      1.0      2023/12/04                                 최초생성  

    **************************************************************************************************************************/

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE  NUMBER :=-20009; -- ERROR 코드
    ERR_MSG   VARCHAR(200);    -- ERROR Message
    USER_EXCEPTION EXCEPTION;

BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 수행전 Check Logic ]
    ---------------------------------------------------------------------------------------------------------------------------

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Logic 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------

    IF p_WRK_TP = 'Q' THEN

        OPEN RTN_CURSOR FOR
        SELECT D.PJT_CD                                                                                 -- 프로젝트 코드
             , J.DEPT_CD                                                                    AS SIT_CD   -- 현장코드
             , NVL(D.OCO_CONT_AMT, 0)                                                       AS UNTK_AMT -- 최초 도급금액(vat포함)
             , D.SCNST_DT                                                                               -- 착공일자
             , D.CCNST_SCH_DT                                                                           -- 준공예정일
             , (SELECT SUM(WHL_EBGT_BGT) FROM TQHA_SAFECOST_BGT WHERE SIT_CD = p_SIT_CD)    AS WHL_EBGT_BGT
          FROM VQSZ_CONT_INFO D
             , TCOZ_DEPT_INFO J
         WHERE D.PJT_CD     = J.SALE_DEPT_CD
           AND D.CONT_DGR   = '0'
           AND D.CHG_TMORD  = '0'
           AND J.DEPT_CD    = p_SIT_CD
        ;

    ---------------------------------------------------------------------------------
    -- 전체예산 조회
    ELSIF p_WRK_TP = 'Q2' THEN

        OPEN RTN_CURSOR FOR
        SELECT ITM_DIV
             , WHL_EBGT_BGT
             , BGT_ATFL_GRP
          FROM TQHA_SAFECOST_BGT 
         WHERE SIT_CD = p_SIT_CD
         ORDER BY ITM_DIV
        ;

    END IF;


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
         WHEN OTHERS THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);
END PQHA_SAFECOST_BGT_Q;
/

-- PQHA_SAFECOST_BGT_S (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_SAFECOST_BGT_S" (
    p_WRK_TP            VARCHAR2 :='U'                                  -- UPDATE FLAG( I: ISNERT, U:UPDATE, D:DELTE, B:배치성 일괄삭제)
,   p_WRK_ID            VARCHAR2                                        -- 사용자 ID
,   p_WRK_IP            VARCHAR2                                        -- 사용자 IP
,   p_SIT_CD            TQHA_SAFECOST_BGT.SIT_CD            %TYPE       -- 현장코드
,   p_ITM_DIV           TQHA_SAFECOST_BGT.ITM_DIV           %TYPE       -- 안전관리비 예산구분(QS026) 1 안전인건비
,   p_BGT_ATFL_GRP      TQHA_SAFECOST_BGT.BGT_ATFL_GRP      %TYPE       -- 첨부파일 그룹
,   p_WHL_EBGT_BGT      TQHA_SAFECOST_BGT.WHL_EBGT_BGT      %TYPE       -- 전체실행예산
)
IS
    /**************************************************************************************************************************
      Purpose : 안전관리 전체 예산 저장

      REVISIONS
      Ver      Date               Author                  Description
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2021/11/09 18:22:09                         최초생성

    **************************************************************************************************************************/



    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR2(200);            -- ERROR Message
    USER_EXCEPTION EXCEPTION;

    v_CNT_APRV  INTEGER := 0;   -- 결재 상태 체크
BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 필수입력 필드  Check  ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_SIT_CD IS NULL)  THEN
        ERR_MSG := '현장코드는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_ITM_DIV IS NULL AND p_WRK_TP <> 'B')  THEN
        ERR_MSG := '안전관리비 예산구분(QS026) 1 안전인건비 는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Process 선행조건 Check ]
    ---------------------------------------------------------------------------------------------------------------------------

    --2023/12/05  전자결재 상태확인(미확정)
--        SELECT NVL(MAX(1),0) INTO v_CNT_APRV
--          FROM DUAL
--         WHERE EXISTS (SELECT 1
--                      FROM TQHA_SAFECOST_APRV A, TCOA_APPROVE B
--                     WHERE A.SIT_CD = p_SIT_CD         --현장코드
--                       AND A.APRV_DIV = '1'              --1: 예산, 2 월별실적
--                       AND A.APRV_NO = B.APRV_NO(+)
--                       AND B.APRV_STATS IN ('CO0101','CO0104')  -- 진행중, 완료
--                      );
--
--     IF v_CNT_APRV > 0   THEN
--         ERR_MSG := '전자결재가 상신되어 진행중이거나 완료되어 수정할 수 없습니다.';
--         RAISE USER_EXCEPTION;
--     END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Business Process ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_WRK_TP ='D') THEN

        DELETE
          FROM TQHA_SAFECOST_BGT
         WHERE SIT_CD       = p_SIT_CD          -- 현장코드
           AND ITM_DIV      = p_ITM_DIV         -- 안전관리비 예산구분(QS026) 1 안전인건비
        ;

    ELSIF (p_WRK_TP ='U') THEN

        UPDATE TQHA_SAFECOST_BGT
           SET WHL_EBGT_BGT         = p_WHL_EBGT_BGT    --전체실행예산
             , BGT_ATFL_GRP         = p_BGT_ATFL_GRP    -- 첨부파일 그룹
             , UPD_ID               = p_WRK_ID          --수정ID
             , UPD_DTM              = SYSDATE()         --수정일시
             , UPD_IP               = p_WRK_IP          --수정IP
         WHERE SIT_CD               = p_SIT_CD          --현장코드
           AND ITM_DIV              = p_ITM_DIV         --안전관리비 예산구분(QS026) 1 안전인건비
        ;

    ELSIF (p_WRK_TP ='B') THEN

        DELETE
          FROM TQHA_SAFECOST_BGT
         WHERE SIT_CD = p_SIT_CD         --현장코드
        ;

    ELSIF p_WRK_TP = 'I' THEN

        INSERT 
          INTO TQHA_SAFECOST_BGT
             ( SIT_CD               -- 현장코드
             , ITM_DIV              -- 안전관리비 예산구분(QS026) 1 안전인건비
             , WHL_EBGT_BGT         -- 전체실행예산
             , BGT_ATFL_GRP         -- 첨부파일 그룹
             , IPT_ID               -- 입력ID
             , IPT_DTM              -- 입력일시
             , IPT_IP               -- 입력IP
             , UPD_ID               -- 수정ID
             , UPD_DTM              -- 수정일시
             , UPD_IP               -- 수정IP
             )
        VALUES 
             ( p_SIT_CD             -- 현장코드
             , p_ITM_DIV            -- 안전관리비 예산구분(QS026) 1 안전인건비
             , p_WHL_EBGT_BGT       -- 전체실행예산
             , p_BGT_ATFL_GRP       -- 첨부파일 그룹
             , p_WRK_ID             -- 입력ID
             , SYSDATE()            -- 입력일시
             , p_WRK_IP             -- 입력IP
             , p_WRK_ID             -- 수정ID
             , SYSDATE()            -- 수정일시
             , p_WRK_IP             -- 수정IP
             )
        ;

    ELSIF p_WRK_TP = 'ATFL' THEN

        UPDATE TQHA_SAFECOST_BGT
           SET BGT_ATFL_GRP = p_BGT_ATFL_GRP
             , UPD_ID       = p_WRK_ID
             , UPD_IP       = p_WRK_IP
             , UPD_DTM      = SYSDATE
         WHERE SIT_CD       = p_SIT_CD
        ;

    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 5. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);

END ;
/

-- PQHA_SAFECOST_INFO_Q (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_SAFECOST_INFO_Q" (
    p_WRK_TP        VARCHAR2 DEFAULT 'Q'                -- FLAG( Q1: 도급정보, Q2:안전관리비 정보, Q3:월별실적 목록 )
,   p_SIT_CD        TQHA_IDAC.SIT_CD        %TYPE       -- 현장코드
,   RTN_CURSOR      OUT SYS_REFCURSOR
)
IS
    /**************************************************************************************************************************
      Purpose : QSE > 안전관리 > 안전서류관리 > 산재관리(현장/본사) 조회

      REVISIONS
      Ver      Date               Author                  Description
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2023/11/28 10:51:46                         최초생성

    **************************************************************************************************************************/

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR2(200);            -- ERROR Message
    USER_EXCEPTION EXCEPTION;


BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 수행전 Check Logic ]
    ---------------------------------------------------------------------------------------------------------------------------


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Logic 처리
    ---------------------------------------------------------------------------------------------------------------------------

    IF (p_WRK_TP = 'Q') THEN

        OPEN RTN_CURSOR FOR
        SELECT SIT_CD
             , CNST_STR_DT
             , CNST_END_DT
             , CNST_AMT
             , OBJ_AM
             , SAFT_RT
             , BSC_AM
             , APRP_SAFT_MCHR
             , RMKS
             , IPT_ID
             , IPT_DTM
             , IPT_IP
             , UPD_ID
             , UPD_DTM
             , UPD_IP
          FROM TQHA_SAFECOST_INFO
         WHERE SIT_CD = p_SIT_CD
        ;

    -----------------------------------------------------------------
    -- 도급정보 조회
    -----------------------------------------------------------------
    ELSIF (p_WRK_TP = 'Q1') THEN

        OPEN RTN_CURSOR FOR
        /*
          SELECT A.SIT_CD                                               AS SIT_CD   -- 현장코드
               , A.SIT_NM                                               AS SIT_NM   -- 현장명칭
--              , NVL(Z.FST_TOT_CONT_AMT_SUM,0)                          AS FST_TOT_CONT_AMT_SUM    --최초계약금액합계(수주)
--              , NVL(B.FST_OCO_CONT_AMT_SUM,0)                          AS FST_OCO_CONT_AMT_SUM    --최초당사계약금액합계(수주)
--              , NVL(B.TOT_UNTKSO_SUM_AMT,0)                            AS TOT_UNTKSO_SUM_AMT      --최종계약합계금액(수주)
               -- 20240918 수정
               --, NVL(B.OCO_UNTKSO_SUM_AMT,0)                            AS UNTK_AMT                --최종당사계약합계금액(수주)
               , NVL(B.TOT_UNTKSO_SUM_AMT,0)                            AS UNTK_AMT                  --최종계약합계금액(수주)
               , decode(A.CHG_CNST_STR_DT,NULL,A.CNST_STR_DT)           AS SCNST_DT         -- 공사시작일
               , decode(A.CHG_CNST_END_DT,NULL,A.CNST_END_DT)           AS CCNST_SCH_DT     -- 공사종료일
          FROM  TCMZ_SIT    A
               ,TCMZ_SIT_CONT B
          WHERE A.SIT_CD = p_SIT_CD -- 변수 (현장코드)
            AND A.SIT_CD = B.SIT_CD
           ;
        */
        -- 20240926 도급정보에 도급최종금액 외 도급 산업안전관리비 금액 추가
        SELECT A.SIT_CD                                         AS SIT_CD           -- 현장코드
             , A.SIT_NM                                         AS SIT_NM           -- 현장명칭
             , NVL(B.TOT_UNTKSO_SUM_AMT,0)                      AS UNTK_AMT         -- 최종계약합계금액(수주)
             , C.SAFT_UNTK_AMT                                  AS SAFT_UNTK_AMT    -- 최종내역도급기준 산업안전관리비 금액
             , decode(A.CHG_CNST_STR_DT,NULL,A.CNST_STR_DT)     AS SCNST_DT         -- 공사시작일
             , decode(A.CHG_CNST_END_DT,NULL,A.CNST_END_DT)     AS CCNST_SCH_DT     -- 공사종료일
          FROM TCMZ_SIT         A
             , TCMZ_SIT_CONT    B
             , FCMZ_SAFT_DEFC_IF('SAFT', p_SIT_CD) C                                -- 도급기준 산업안전관리비 금액
         WHERE A.SIT_CD     = p_SIT_CD -- 변수 (현장코드)
           AND A.SIT_CD     = B.SIT_CD
           AND A.SIT_CD     = C.SIT_CD(+)
        ;

    -----------------------------------------------------------------
    -- 도급정보 조회
    -----------------------------------------------------------------

    ELSIF (p_WRK_TP = 'Q2') THEN

        OPEN RTN_CURSOR FOR
        SELECT SIT_CD
             , CNST_STR_DT
             , CNST_END_DT
             , CNST_AMT
             , OBJ_AM
             , SAFT_RT
             , BSC_AM
             , APRP_SAFT_MCHR
             , RMKS
             , IPT_ID
             , IPT_DTM
             , IPT_IP
             , UPD_ID
             , UPD_DTM
             , UPD_IP
          FROM TQHA_SAFECOST_INFO
         WHERE SIT_CD = p_SIT_CD
        ;

    -----------------------------------------------------------------
    -- 월별실적 목록 조회
    -----------------------------------------------------------------
    ELSIF (p_WRK_TP = 'Q3') THEN

        OPEN RTN_CURSOR FOR
        SELECT A.SIT_CD
             , A.RLV_YM
             --, A.ITM_DIV
             , SUM(NVL(B.T_USE_AMT, 0)) + SUM(NVL(B1.T_USE_AMT,0))                              AS T_USE_AMT        -- 당월 실적금액
             , SUM(DECODE(A.ITM_DIV, '01', NVL(B.T_USE_AMT, 0) + NVL(B1.T_USE_AMT,0) , 0))      AS T_USE_AMT1       -- 1. 안전.보건관리자 임금 등
             , SUM(DECODE(A.ITM_DIV, '02', NVL(B.T_USE_AMT, 0) + NVL(B1.T_USE_AMT,0) , 0))      AS T_USE_AMT2       -- 2. 안전시설비 등
             , SUM(DECODE(A.ITM_DIV, '03', NVL(B.T_USE_AMT, 0) + NVL(B1.T_USE_AMT,0) , 0))      AS T_USE_AMT3       -- 3. 보호구 등
             , SUM(DECODE(A.ITM_DIV, '04', NVL(B.T_USE_AMT, 0) + NVL(B1.T_USE_AMT,0) , 0))      AS T_USE_AMT4       -- 4. 안전보건진단비 등
             , SUM(DECODE(A.ITM_DIV, '05', NVL(B.T_USE_AMT, 0) + NVL(B1.T_USE_AMT,0) , 0))      AS T_USE_AMT5       -- 5. 안전보건교육비 등
             , SUM(DECODE(A.ITM_DIV, '06', NVL(B.T_USE_AMT, 0) + NVL(B1.T_USE_AMT,0) , 0))      AS T_USE_AMT6       -- 6. 근로자 건강장애예방비 등
             , SUM(DECODE(A.ITM_DIV, '07', NVL(B.T_USE_AMT, 0) + NVL(B1.T_USE_AMT,0) , 0))      AS T_USE_AMT7       -- 7. 안전.보건관리자 임금 등
             , SUM(DECODE(A.ITM_DIV, '08', NVL(B.T_USE_AMT, 0) + NVL(B1.T_USE_AMT,0) , 0))      AS T_USE_AMT8       -- 8. 본사전담조직 근로자임금
             , SUM(DECODE(A.ITM_DIV, '09', NVL(B.T_USE_AMT, 0) + NVL(B1.T_USE_AMT,0) , 0))      AS T_USE_AMT9       -- 9 위험성평가에 따른 소요비용
             , SUBSTR(A.RLV_YM, 1 , 4 )                                                         AS RLV_Y            -- 해당년도
          FROM TQHA_SAFECOST_BGTYM  A
             , ( -- 당사 당월 사용금액
                SELECT SIT_CD
                     , RLV_YM
                     , ITM_DIV
                     , NVL(SUM(USE_AMT), 0) AS T_USE_AMT    -- 당월 사용금액
                  FROM TQHA_SAFECOST_ARSLT
                 WHERE SIT_CD = p_SIT_CD                    -- 변수 (현장코드)
                 GROUP BY SIT_CD, RLV_YM, ITM_DIV
                 ORDER BY SIT_CD, RLV_YM, ITM_DIV
               ) B
             , ( -- 업체 당월 사용금액
                SELECT A.SIT_CD                             -- 현장코드
                     , A.RLV_YM
                     , A.ITM_DIV                            --
                     , NVL(SUM(A.USE_AMT), 0) AS T_USE_AMT  -- 업체 당월 금액
                  FROM TQHA_SAFECOST_ARSLT_CO   A
                     , TQHA_SAFECOST_MMARSLT_CO B
                 WHERE A.SIT_CD             = p_SIT_CD      -- 변수 (현장코드)
                   AND A.SIT_CD             = B.SIT_CD(+)
                   AND A.CUST_CD            = B.CUST_CD(+)
                   AND A.VNDR_SEQ           = B.VNDR_SEQ(+)
                   AND A.RLV_YM             = B.RLV_YM(+)
                   AND B.SITE_APRV_YN       = '1'     -- 승인
                 GROUP BY A.SIT_CD, A.RLV_YM, A.ITM_DIV
               ) B1
             , (-- 결재 완료 여부 체크 (20240920 결재완료 상태만 조회)
                SELECT A.SIT_CD
                     , A.APRV_YM
                     , A.APRV_DIV
                     , A.APRV_NO
                     , B.APRV_STATS                         -- 결재완료 인 상태
                  FROM TQHA_SAFECOST_APRV   A
                     , TQHA_APRV            B
                 WHERE A.APRV_DIV           = 2             -- 현장 안전관리비
                   AND A.SIT_CD             =  B.SIT_CD
                   AND A.APRV_NO            =  B.APRV_NO
                   AND B.APRV_STATS         = '4'           -- 결재완료 인 상태
               ) C      -- 결재완료 인 상태
         WHERE A.SIT_CD         = p_SIT_CD                  -- 변수 (현장코드)
           AND A.SIT_CD         = B.SIT_CD(+)
           AND A.RLV_YM         = B.RLV_YM(+)
           AND A.ITM_DIV        = B.ITM_DIV(+)
           AND A.SIT_CD         = B1.SIT_CD(+)
           AND A.RLV_YM         = B1.RLV_YM(+)
           AND A.ITM_DIV        = B1.ITM_DIV(+)
           -- 20240920 결재완료 상태인것만 금액표시
           AND A.SIT_CD         =  C.SIT_CD
           AND A.RLV_YM         =  C.APRV_YM
         GROUP BY A.SIT_CD, A.RLV_YM
         ORDER BY A.SIT_CD, A.RLV_YM 
        ;

/*
         -- 결재 완료 여부 체크 ( 20240527 결재완료 여부 추가 예정 )
         SELECT A.SIT_CD
                 ,A.APRV_YM
                 ,A.APRV_DIV
                 ,A.APRV_NO
                 ,B.APRV_STATS           -- 결재완료 인 상태
             FROM TQHA_SAFECOST_APRV A
                 ,TQHA_APRV B
           WHERE A.APRV_DIV = 2   -- 현장 안전관리비
             AND A.SIT_CD  =  B.SIT_CD
             AND A.APRV_NO =  B.APRV_NO
             AND B.APRV_STATS = '4'  -- 결재완료 인 상태
*/

       END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);
END ;
/

-- PQHA_SAFECOST_INFO_S (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_SAFECOST_INFO_S" (
    p_WRK_TP                VARCHAR2 :='U'                                      -- UPDATE FLAG( I: ISNERT, U:UPDATE, D:DELTE)
,   p_WRK_ID                VARCHAR2                                            -- 사용자 ID 
,   p_WRK_IP                VARCHAR2                                            -- 사용자 IP 
,   p_SIT_CD                TQHA_SAFECOST_INFO.SIT_CD               %TYPE       -- 현장코드
,   p_CNST_STR_DT           TQHA_SAFECOST_INFO.CNST_STR_DT          %TYPE       -- 공사시작일자
,   p_CNST_END_DT           TQHA_SAFECOST_INFO.CNST_END_DT          %TYPE       -- 공사종료일자
,   p_CNST_AMT              TQHA_SAFECOST_INFO.CNST_AMT             %TYPE       -- 공사금액 
,   p_OBJ_AM                TQHA_SAFECOST_INFO.OBJ_AM               %TYPE       -- 대상액
,   p_SAFT_RT               TQHA_SAFECOST_INFO.SAFT_RT              %TYPE       -- 안전요율
,   p_BSC_AM                TQHA_SAFECOST_INFO.BSC_AM               %TYPE       -- 기초액
,   p_APRP_SAFT_MCHR        TQHA_SAFECOST_INFO.APRP_SAFT_MCHR       %TYPE       -- 계상 안전관리비 
,   p_RMKS                  TQHA_SAFECOST_INFO.RMKS                 %TYPE       -- 비고
)
IS 
    /**************************************************************************************************************************
      Purpose : 산업안전보건관리비 정보 저장

      REVISIONS
      Ver      Date               Author                  Description 
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2022/02/11 10:43:55                         최초생성

    **************************************************************************************************************************/


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR2(200);            -- ERROR Message
    USER_EXCEPTION EXCEPTION;


BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 필수입력 필드  Check  ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_SIT_CD IS NULL)  THEN
        ERR_MSG := '현장코드는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Process 선행조건 Check ]
    ---------------------------------------------------------------------------------------------------------------------------



    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Business Process ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_WRK_TP ='D') THEN

        DELETE 
          FROM TQHA_SAFECOST_INFO
         WHERE SIT_CD = p_SIT_CD        --현장코드
        ;

    ELSIF (p_WRK_TP ='U') THEN

        UPDATE TQHA_SAFECOST_INFO
           SET CNST_STR_DT          = p_CNST_STR_DT             -- 공사시작일자
             , CNST_END_DT          = p_CNST_END_DT             -- 공사종료일자
             , CNST_AMT             = p_CNST_AMT                -- 공사금액
             , OBJ_AM               = p_OBJ_AM                  -- 대상액
             , SAFT_RT              = p_SAFT_RT                 -- 안전요율
             , BSC_AM               = p_BSC_AM                  -- 기초액
             , APRP_SAFT_MCHR       = p_APRP_SAFT_MCHR          -- 계상 안전관리비
             , RMKS                 = p_RMKS                    -- 비고
             , UPD_ID               = p_WRK_ID                  -- 수정ID 
             , UPD_DTM              = SYSDATE()                 -- 수정일시
             , UPD_IP               = p_WRK_IP                  -- 수정IP
         WHERE SIT_CD               = p_SIT_CD                  -- 현장코드
        ;

    ELSE 

        INSERT 
          INTO TQHA_SAFECOST_INFO
             ( SIT_CD                   -- 현장코드
             , CNST_STR_DT              -- 공사시작일자
             , CNST_END_DT              -- 공사종료일자
             , CNST_AMT                 -- 공사금액
             , OBJ_AM                   -- 대상액
             , SAFT_RT                  -- 안전요율
             , BSC_AM                   -- 기초액
             , APRP_SAFT_MCHR           -- 계상 안전관리비
             , RMKS                     -- 비고
             , IPT_ID                   -- 입력ID
             , IPT_DTM                  -- 입력일시
             , IPT_IP                   -- 입력IP
             , UPD_ID                   -- 수정ID
             , UPD_DTM                  -- 수정일시
             , UPD_IP                   -- 수정IP
             )
        VALUES 
             ( p_SIT_CD                 -- 현장코드
             , p_CNST_STR_DT            -- 공사시작일자
             , p_CNST_END_DT            -- 공사종료일자
             , p_CNST_AMT               -- 공사금액
             , p_OBJ_AM                 -- 대상액
             , p_SAFT_RT                -- 안전요율
             , p_BSC_AM                 -- 기초액
             , p_APRP_SAFT_MCHR         -- 계상 안전관리비
             , p_RMKS                   -- 비고
             , p_WRK_ID                 -- 입력ID 
             , SYSDATE()                -- 입력일시
             , p_WRK_IP                 -- 입력IP
             , p_WRK_ID                 -- 수정ID
             , SYSDATE()                -- 수정일시
             , p_WRK_IP                 -- 수정IP
             )
        ;

    END IF;

    IF (p_WRK_TP IN ('I', 'U')) THEN

       --------------------------------------------------------------------------
       -- CALL PQHA_SAFECOST_BGTYM_B  월별실적목록 생성
       --------------------------------------------------------------------------
       PQHA_SAFECOST_BGTYM_B( 
              'B'       --p_WRK_TP  
            , p_WRK_ID
            , p_WRK_IP
            , p_SIT_CD
            , p_CNST_STR_DT
            , p_CNST_END_DT
         );

    END IF;


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 5. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN 
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);

END ;
/

-- PQHA_SAFECOST_MMARSLT_CO_ATFL_S (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_SAFECOST_MMARSLT_CO_ATFL_S" (
    p_WRK_TP            VARCHAR2 :='U'                                      -- UPDATE FLAG( I: ISNERT, U:UPDATE, D:DELTE)
,   p_WRK_ID            VARCHAR2                                            -- 사용자 ID 
,   p_WRK_IP            VARCHAR2                                            -- 사용자 IP 
,   p_SIT_CD            TQHA_SAFECOST_MMARSLT_CO.SIT_CD%TYPE                -- 현장코드
,   p_CUST_CD           TQHA_SAFECOST_MMARSLT_CO.CUST_CD%TYPE               -- 협력업체코드
,   p_VNDR_SEQ          TQHA_SAFECOST_MMARSLT_CO.VNDR_SEQ%TYPE              -- 업체순번
,   p_RLV_YM            TQHA_SAFECOST_MMARSLT_CO.RLV_YM%TYPE                -- 해당년월
,   p_ATFL_GRP          VARCHAR2                                            -- 첨부파일
)
IS 
    /**************************************************************************************************************************
      Purpose : 첨부파일 저장

      REVISIONS
      Ver      Date               Author                  Description 
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2026/03/03                                    최초생성

    /**************************************************************************************************************************/


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR2(200);            -- ERROR Message
    USER_EXCEPTION EXCEPTION;

BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 필수입력 필드  Check  ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_SIT_CD IS NULL)  THEN
        ERR_MSG := '현장코드는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;
    IF (p_CUST_CD IS NULL)  THEN
        ERR_MSG := '거래처코드는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;
    IF (p_VNDR_SEQ IS NULL)  THEN
        ERR_MSG := '거래처순번는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;
    IF (p_RLV_YM IS NULL)  THEN
        ERR_MSG := '년월는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Process 선행조건 Check ]
    ---------------------------------------------------------------------------------------------------------------------------

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Business Process ]
    ---------------------------------------------------------------------------------------------------------------------------

    ---------------------------------------------------------------------------------------------------------------------------
    --  승인
    ---------------------------------------------------------------------------------------------------------------------------
    IF p_WRK_TP ='GRP_U' THEN

        MERGE   
          INTO TQHA_SAFECOST_MMARSLT_CO
        USING DUAL
            ON (    SIT_CD   = p_SIT_CD         --현장코드
                AND CUST_CD  = p_CUST_CD        --협력업체코드
                AND VNDR_SEQ = p_VNDR_SEQ       --업체순번
                AND RLV_YM   = p_RLV_YM         --해당년월   
                )
        WHEN MATCHED THEN
            UPDATE 
               SET ATFL_GRP     = p_ATFL_GRP
                 , UPD_ID       = p_WRK_ID      --수정ID
                 , UPD_DTM      = SYSDATE       --수정일시
                 , UPD_IP       = p_WRK_IP      --수정IP
        WHEN NOT MATCHED THEN
            INSERT
                 ( SIT_CD           --기준년월
                 , CUST_CD          --부서코드
                 , VNDR_SEQ         --계정코드
                 , RLV_YM           --년월
                 , ATFL_GRP         --첨부파일ID
                 , IPT_ID           --입력ID
                 , IPT_DTM          --입력일시
                 , IPT_IP           --입력IP
                 , UPD_ID           --수정ID
                 , UPD_DTM          --수정일시
                 , UPD_IP           --수정IP
                 )
            VALUES
                 ( p_SIT_CD         --기준년월
                 , p_CUST_CD        --부서코드
                 , p_VNDR_SEQ       --계정코드
                 , p_RLV_YM         --년월
                 , p_ATFL_GRP       --첨부파일ID
                 , p_WRK_ID         --입력ID 
                 , SYSDATE          --입력일시
                 , p_WRK_IP         --입력IP
                 , p_WRK_ID         --수정ID
                 , SYSDATE          --수정일시
                 , p_WRK_IP         --수정IP
                 )
        ;

    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 5. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN 
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);

END PQHA_SAFECOST_MMARSLT_CO_ATFL_S;
/

-- PQHA_SAFECOST_MMARSLT_CO_W (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_SAFECOST_MMARSLT_CO_W" (
    p_WRK_TP            VARCHAR2 :='U'                                          -- UPDATE FLAG( I: ISNERT, U:UPDATE, D:DELTE)
,   p_WRK_ID            VARCHAR2                                                -- 사용자 ID
,   p_WRK_IP            VARCHAR2                                                -- 사용자 IP
,   p_SIT_CD            TQHA_SAFECOST_MMARSLT_CO.SIT_CD         %TYPE           -- 현장코드
,   p_CUST_CD           TQHA_SAFECOST_MMARSLT_CO.CUST_CD        %TYPE           -- 협력업체코드
,   p_VNDR_SEQ          TQHA_SAFECOST_MMARSLT_CO.VNDR_SEQ       %TYPE           -- 업체순번
,   p_RLV_YM            TQHA_SAFECOST_MMARSLT_CO.RLV_YM         %TYPE           -- 해당년월
,   p_RSTOR_RSN         TQHA_SAFECOST_MMARSLT_CO.RSTOR_RSN      %TYPE           -- 반려사유
)
IS
    /**************************************************************************************************************************
      Purpose : 협력업체 월별 실적 (APRV) : 승인, (RSTOR) : 반려, (REQ) : 승인요청, (CNC) : 승인취소

      REVISIONS
      Ver      Date               Author                  Description
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2024/07/20 13:09:15                         최초생성

    /**************************************************************************************************************************/


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR2(200);            -- ERROR Message
    USER_EXCEPTION EXCEPTION;

    v_VNDR_APRV_YN      VARCHAR2(1);        -- 업체 승인요청 1, 미요청 0
    v_SITE_APRV_YN      VARCHAR2(1);        -- 승인 1 , 반려 2
    v_APRV_YN           VARCHAR2(1);        -- 결재상신,결재완료 1, 그외 0

    v_APRV_STATS        VARCHAR2(20);
    v_APRV_STATS_NM     VARCHAR2(50);

BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 필수입력 필드  Check  ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_SIT_CD IS NULL)  THEN
        ERR_MSG := '현장코드는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;
    IF (p_CUST_CD IS NULL)  THEN
        ERR_MSG := '거래처코드는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;
    IF (p_VNDR_SEQ IS NULL)  THEN
        ERR_MSG := '거래처순번는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;
    IF (p_RLV_YM IS NULL)  THEN
        ERR_MSG := '년월는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    ---------------------------------------------------------------------
    -- 결재상태 체크
    SELECT MAX(T2.APRV_STATS)
         , MAX(T3.CD_NM )
      INTO v_APRV_STATS
         , v_APRV_STATS_NM
      FROM TQHA_SAFECOST_APRV   T1
      LEFT JOIN TQHA_APRV       T2 ON T1.SIT_CD     = T2.SIT_CD
                                  AND T1.APRV_NO    = T2.APRV_NO
      LEFT JOIN TCOA_COMCODE    T3 ON T2.APRV_STATS = T3.COM_CD
                                  AND T3.HRNK_CD    = 'QS031'
     WHERE T1.SIT_CD    = p_SIT_CD
       AND T1.APRV_DIV  = '2'       -- 월별실적.
       AND T1.APRV_YM   = p_RLV_YM
    ;

    IF v_APRV_STATS IN ('2', '4') THEN
        ERR_MSG := '결재상태 [' || v_APRV_STATS_NM || ']인 데이터는 수정 불가합니다.';
        RAISE USER_EXCEPTION;
    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Process 선행조건 Check ]
    ---------------------------------------------------------------------------------------------------------------------------
    -- 상태값 체크 -- VNDR_APRV_YN (업체 승인요청 1, 미요청 0) , SITE_APRV_YN ( 승인 1 , 반려 2)
    SELECT nvl(max(VNDR_APRV_YN),0)
         , nvl(max(SITE_APRV_YN),0)
      INTO v_VNDR_APRV_YN             -- 업체 승인요청 1, 미요청 0
         , v_SITE_APRV_YN             -- 승인 1 , 반려 2
      FROM TQHA_SAFECOST_MMARSLT_CO
     WHERE SIT_CD    = p_SIT_CD           --현장코드
       AND CUST_CD   = p_CUST_CD          --협력업체코드
       AND VNDR_SEQ  = p_VNDR_SEQ         --업체순번
       AND RLV_YM    = p_RLV_YM           --해당년월
    ;

    SELECT CASE WHEN NVL(MAX(B.APRV_STATS),'0') IN ('2','4') THEN 1
                ELSE 0
           END
      INTO v_APRV_YN
      FROM TQHA_SAFECOST_APRV   A
         , TQHA_APRV            B
     WHERE A.APRV_NO        = B.APRV_NO
       AND A.SIT_CD         = B.SIT_CD 
       AND A.SIT_CD         = p_SIT_CD
       AND A.APRV_DIV       = '2'
       AND A.APRV_YM        = p_RLV_YM
    ;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Business Process ]
    ---------------------------------------------------------------------------------------------------------------------------

    ---------------------------------------------------------------------------------------------------------------------------
    --  승인
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_WRK_TP ='APRV') THEN

        UPDATE TQHA_SAFECOST_MMARSLT_CO
           SET SITE_APRV_YN     = '1'                               -- 승인 1, 반려 2
             -- 20240930 반려사유 추가
             , RSTOR_RSN        = NULL                              -- 반려사유
             ----------------
             , SITE_APRV_DT     = TO_CHAR(SYSDATE(), 'YYYYMMDD')    -- 현장승인일자
             , UPD_ID           = p_WRK_ID                          -- 수정ID
             , UPD_DTM          = SYSDATE                           -- 수정일시
             , UPD_IP           = p_WRK_IP                          -- 수정IP
         WHERE SIT_CD           = p_SIT_CD                          -- 현장코드
           AND CUST_CD          = p_CUST_CD                         -- 협력업체코드
           AND VNDR_SEQ         = p_VNDR_SEQ                        -- 업체순번
           AND RLV_YM           = p_RLV_YM                          -- 해당년월
        ;

    ---------------------------------------------------------------------------------------------------------------------------
    -- 반려
    ---------------------------------------------------------------------------------------------------------------------------
    ELSIF (p_WRK_TP ='RSTOR') THEN
    
	    DELETE 
	    FROM TQHA_SAFECOST_MMARSLT_CO
	    WHERE SIT_CD           = p_SIT_CD              -- 현장코드
          AND CUST_CD          = p_CUST_CD             -- 협력업체코드
          AND VNDR_SEQ         = p_VNDR_SEQ            -- 업체순번
          AND RLV_YM           = p_RLV_YM              -- 해당년월
        ;

    /*
        UPDATE TQHA_SAFECOST_MMARSLT_CO
           SET SITE_APRV_YN     = '2'                   -- 승인 1, 반려 2
             , VNDR_APRV_YN     = '0'                   -- 승인요청 1 미요청 0
             -- 20240930 반려사유 추가
             , RSTOR_RSN        = p_RSTOR_RSN           -- 반려사유
             ----------------
             , SITE_APRV_DT     = NULL                  -- 현장승인일자
             , UPD_ID           = p_WRK_ID              -- 수정ID
             , UPD_DTM          = SYSDATE               -- 수정일시
             , UPD_IP           = p_WRK_IP              -- 수정IP
         WHERE SIT_CD           = p_SIT_CD              -- 현장코드
           AND CUST_CD          = p_CUST_CD             -- 협력업체코드
           AND VNDR_SEQ         = p_VNDR_SEQ            -- 업체순번
           AND RLV_YM           = p_RLV_YM              -- 해당년월
        ;
	*/
    ---------------------------------------------------------------------------------------------------------------------------
    -- 승인요청(협력업체용)
    ---------------------------------------------------------------------------------------------------------------------------
    ELSIF (p_WRK_TP ='REQ') THEN

        IF(v_APRV_YN = '1') THEN
            ERR_MSG := '해당년월 ("' || p_RLV_YM || '")은 결재 완료되어 승인요청이 불가합니다.  ';
            RAISE USER_EXCEPTION;
        END IF;

        MERGE
          INTO TQHA_SAFECOST_MMARSLT_CO
        USING DUAL
        ON (    SIT_CD      = p_SIT_CD           -- 현장코드
            AND CUST_CD     = p_CUST_CD          -- 협력업체코드
            AND VNDR_SEQ    = p_VNDR_SEQ         -- 업체순번
            AND RLV_YM      = p_RLV_YM           -- 해당년월
           )
        WHEN MATCHED THEN
            UPDATE
               SET VNDR_APRV_YN         = '1'                               -- 승인요청 1, 미요청 0
                 -- 20240930 반려사유 추가
                 , RSTOR_RSN            = NULL                              -- 반려사유
                 ----------------
                 , VNDR_APRV_DT         = TO_CHAR(SYSDATE(), 'YYYYMMDD')    -- 업체승인요청일자
                 , UPD_ID               = p_WRK_ID                          -- 수정ID
                 , UPD_DTM              = SYSDATE                           -- 수정일시
                 , UPD_IP               = p_WRK_IP                          -- 수정IP
        WHEN NOT MATCHED THEN
            INSERT
                 ( SIT_CD                   -- 현장코드
                 , CUST_CD                  -- 협력업체코드
                 , VNDR_SEQ                 -- 업체순번
                 , RLV_YM                   -- 해당년월
                 -- 20240930 반려사유 추가
                 , RSTOR_RSN                -- 반려사유
                   ----------------
                 , VNDR_APRV_YN             -- 승인요청 1, 미요청 0
                 , IPT_ID                   -- 수정ID
                 , IPT_DTM                  -- 수정일시
                 , IPT_IP                   -- 수정IP
                 , VNDR_APRV_DT             -- 업체승인요청일자
                 )
            VALUES
                 ( p_SIT_CD                 -- 현장코드
                 , p_CUST_CD                -- 협력업체코드
                 , p_VNDR_SEQ               -- 업체순번
                 , p_RLV_YM                 -- 해당년월
                 -- 20240930 반려사유 추가
                 , p_RSTOR_RSN              -- 반려사유
                   ----------------
                 , '1'                      -- 승인요청 1, 미요청 0
                 , p_WRK_ID                 -- 수정ID
                 , SYSDATE                  -- 수정일시
                 , p_WRK_IP                 -- 수정IP
                 , TO_CHAR(SYSDATE(), 'YYYYMMDD')    --업체승인요청일자
                 )
            ;

    ---------------------------------------------------------------------------------------------------------------------------
    -- 승인취소(협력업체용)
    ---------------------------------------------------------------------------------------------------------------------------
    ELSIF (p_WRK_TP ='CNC') THEN

        -- 20240921 추가 , 승인이 완료되었는데 승인취소 불가 체크
        IF ( v_SITE_APRV_YN = '1' OR  v_SITE_APRV_YN = '2' ) THEN
           ERR_MSG := '해당년월 ("' || p_RLV_YM || '")은 승인 OR 반려 처리가 완료되어 취소가 불가합니다.  ';
           RAISE USER_EXCEPTION;
        END IF;
        -----------------------------------------
		/*
        UPDATE TQHA_SAFECOST_MMARSLT_CO
           SET VNDR_APRV_YN         = '0'               -- 승인요청 1 미요청 0
             , VNDR_APRV_DT         = NULL              -- 업체승인요청일자
              -- 20240930 반려사유 추가
             , RSTOR_RSN            = NULL              -- 반려사유
             ----------------
             , UPD_ID               = p_WRK_ID          -- 수정ID
             , UPD_DTM              = SYSDATE           -- 수정일시
             , UPD_IP               = p_WRK_IP          -- 수정IP
         WHERE SIT_CD               = p_SIT_CD          -- 현장코드
           AND CUST_CD              = p_CUST_CD         -- 협력업체코드
           AND VNDR_SEQ             = p_VNDR_SEQ        -- 업체순번
           AND RLV_YM               = p_RLV_YM          -- 해당년월
        ;
		*/
        DELETE 
	    FROM TQHA_SAFECOST_MMARSLT_CO
	    WHERE SIT_CD           = p_SIT_CD              -- 현장코드
          AND CUST_CD          = p_CUST_CD             -- 협력업체코드
          AND VNDR_SEQ         = p_VNDR_SEQ            -- 업체순번
          AND RLV_YM           = p_RLV_YM              -- 해당년월
        ;
        
    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 5. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);

END PQHA_SAFECOST_MMARSLT_CO_W;
/

-- PQHA_SAFECOST_REG2_Q (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_SAFECOST_REG2_Q" (
    p_WRK_TP            IN VARCHAR2 DEFAULT 'Q'             -- FLAG(Q: 현장평가, Q1:본사평가)
,   p_SIT_CD            IN VARCHAR2
,   p_RLV_YM            IN VARCHAR2                         -- 변수(년월)
,   RTN_CURSOR       OUT SYS_REFCURSOR
)
IS
    /**************************************************************************************************************************
      Purpose : 산업안전보건관리비 

      REVISIONS
      Ver      Date               Author                  Description
      -------  -----------------  ----------------------  ---------------------------------------------------------------------
      1.0      2026/02/26                                 최초생성

    **************************************************************************************************************************/

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE  NUMBER :=-20009; -- ERROR 코드
    ERR_MSG   VARCHAR(200);    -- ERROR Message
    USER_EXCEPTION EXCEPTION;

BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 수행전 Check Logic ]
    ---------------------------------------------------------------------------------------------------------------------------

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Logic 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    -- get_SafeCostRegPrvData
    IF p_WRK_TP = 'Q1' THEN

        OPEN RTN_CURSOR FOR
        SELECT ITM_DIV
             , CHG_EBGT_BGT
          FROM TQHA_SAFECOST_BGTYM
         WHERE SIT_CD   = p_SIT_CD
           AND RLV_YM   = (SELECT TO_CHAR(add_months(TO_DATE(p_RLV_YM, 'yyyymm'), -1), 'yyyymm') FROM DUAL)
         ORDER BY ITM_DIV
        ;

    --------------------------------------------------------------------------------
    -- get_LastCnstYm
    ELSIF p_WRK_TP = 'Q2' THEN

        OPEN RTN_CURSOR FOR
        SELECT TO_CHAR( ADD_MONTHS( TO_DATE(MAX(RLV_YM), 'YYYYMM'), 1), 'YYYYMM') RLV_YM_MAX 
          FROM TQHA_SAFECOST_BGTYM 
         WHERE SIT_CD    = p_SIT_CD
        ;

    --------------------------------------------------------------------------------
    -- 결재전, 협력업체 당월 사용금액 승인일자 여부 조회
    ELSIF p_WRK_TP = 'Q3' THEN

        OPEN RTN_CURSOR FOR
        SELECT COUNT(*) AS CNT
          FROM DUAL
         WHERE EXISTS (
                         SELECT SITE_APRV_DT
                           FROM TQHA_SAFECOST_MMARSLT_CO
                         WHERE SIT_CD       = p_SIT_CD
                           AND RLV_YM       = p_RLV_YM
                           AND SITE_APRV_DT IS NULL
                         )
        ;

    END IF;


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
         WHEN OTHERS THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);

END PQHA_SAFECOST_REG2_Q ;
/

-- PQHA_SAFECOST_REG_CO_Q (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_SAFECOST_REG_CO_Q" (
    p_WRK_TP            IN VARCHAR2 DEFAULT 'Q'             -- FLAG(Q: 현장평가, Q1:본사평가)
,   p_SIT_CD            IN VARCHAR2
,   p_CUST_CD           IN VARCHAR2
,   p_VNDR_SEQ          IN VARCHAR2
,   p_RLV_YM            IN VARCHAR2
,   RTN_CURSOR          OUT SYS_REFCURSOR
)
IS
    /**************************************************************************************************************************
      Purpose : [평가항목 조회] PROCEDRE (QSE > 안전관리 > 산업안전보건관리비 > 업체별 현황  )

      REVISIONS
      Ver      Date               Author                  Description
      -------  -----------------  ----------------------  ---------------------------------------------------------------------
      1.0      2023/12/05                                 최초생성

    **************************************************************************************************************************/
 
    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE  NUMBER :=-20009; -- ERROR 코드
    ERR_MSG   VARCHAR(200);    -- ERROR Message
    USER_EXCEPTION EXCEPTION;

BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 수행전 Check Logic ]
    ---------------------------------------------------------------------------------------------------------------------------

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Logic 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------

    IF p_WRK_TP = 'Q' THEN

        OPEN RTN_CURSOR FOR
        SELECT (SELECT CUST_NM FROM VQSZ_TRADE WHERE CUST_CD = A.CUST_CD)       AS CUST_NM          -- 업체명
             , A.SIT_CD                                                                             -- 현장코드
             , A.CUST_CD                                                                            -- 업체코드
             , A.VNDR_SEQ                                                                           -- 업체순번
             , A.VNDR_NM                                                                            -- 공사명
             , E.SAFT_CONT_AMT     AS SAFT_AMT                                                      -- 외주 계약금액 중 안전관리비 금액
             , NVL(B.T_USE_AMT, 0) AS T_USE_AMT                                                     -- 당월금액
             , NVL(C.C_USE_AMT, 0) AS C_USE_AMT                                                     -- 누계금액
             , D.VNDR_APRV_YN                                                                       -- 업체 승인요청 여부
             , D.SITE_APRV_YN                                                                       -- 업체 승인 여부
             , NVL(E.SAFT_CONT_AMT ,0) - NVL(C.C_USE_AMT, 0) AS REMAIN                              -- 잔여금액
             , DECODE(NVL(D.VNDR_APRV_YN, 0), '1', '승인요청', '승인 미요청')   AS VNDR_APRV_YN_NM  -- 요청상태
             , DECODE(NVL(D.SITE_APRV_YN, 0), '1', '승인',
                      DECODE(NVL(D.SITE_APRV_YN, 0), '2', '반려', '진행 중'))   AS SITE_APRV_YN_NM  -- 요청상태
             , D.RLV_YM                                                                             -- 해당년월
             , A.CONT_SUM_AMT                                                                       -- 계약긍맥
             , ATFL_GRP
             , D.RSTOR_RSN                                                      AS RSTOR_RSN_S      -- 반려사유
             , A.VNDR_PSN_CADDR                                                                     -- 담당자연락처
             , F.APRV_STATS
             , '▶ 사용실적 : ' || CASE WHEN D.SITE_APRV_YN = '1' THEN '승인'
                                    WHEN D.SITE_APRV_YN = '2' THEN '반려'
                                    ELSE CASE WHEN D.VNDR_APRV_YN = '1' THEN '승인요청'
                                              ELSE '승인 미요청'
                                         END
                               END
             || ' ▶ 결재상태 : ' || NVL(( SELECT CD_NM FROM TCOA_COMCODE WHERE HRNK_CD = 'QS031' AND COM_CD = F.APRV_STATS ), '-') AS STATS_NM -- 결재상태명
             , '▶ 사용실적 : ' || CASE WHEN D.SITE_APRV_YN = '1' THEN '승인'
                                    WHEN D.SITE_APRV_YN = '2' THEN '반려'
                                    ELSE CASE WHEN D.VNDR_APRV_YN = '1' THEN '승인요청'
                                              ELSE '승인 미요청'
                                         END
                               END                                              AS STATS_NM_CO      -- 결재상태명
          FROM TQHA_VNDR A
             , ( -- 당월 금액
                SELECT SIT_CD                            -- 현장코드
                     , CUST_CD                           -- 업체코드
                     , VNDR_SEQ                          -- 업체순번
                     , RLV_YM                            -- 해당년월
                     , NVL(SUM(USE_AMT), 0) AS T_USE_AMT -- 당월 금액
                  FROM TQHA_SAFECOST_ARSLT_CO
                 WHERE SIT_CD       = p_SIT_CD          --현장코드
                   AND CUST_CD      = p_CUST_CD         --업체코드
                   AND VNDR_SEQ     = p_VNDR_SEQ        --업체순번
                   AND RLV_YM       = p_RLV_YM          --해당년월
                 GROUP BY SIT_CD, CUST_CD, VNDR_SEQ, RLV_YM
               ) B
             , (-- 누계 금액
                SELECT SIT_CD                           -- 현장코드
                     , CUST_CD                          -- 업체코드
                     , VNDR_SEQ                         -- 업체순번
                     , NVL(SUM(USE_AMT), 0) C_USE_AMT   -- 누계 금액
                  FROM TQHA_SAFECOST_ARSLT_CO
                 WHERE SIT_CD       = p_SIT_CD          -- 현장코드
                   AND CUST_CD      = p_CUST_CD         -- 업체코드
                   AND VNDR_SEQ     = p_VNDR_SEQ        -- 업체순번
                   AND RLV_YM   <   = p_RLV_YM          -- 해당년월
                 GROUP BY SIT_CD, CUST_CD, VNDR_SEQ
               ) C
             , ( -- 협력업체 안전관리비 사용 승인요청/ 승인여부
                SELECT SIT_CD                                   -- 현장코드
                     , CUST_CD                                  -- 업체코드
                     , VNDR_SEQ                                 -- 업체순번
                     , RLV_YM                                   -- 년월
                     , NVL(VNDR_APRV_YN, 0) AS VNDR_APRV_YN     -- 업체승인요청여부
                     , VNDR_APRV_DT                             -- 업체승인일자
                     , NVL(SITE_APRV_YN, 0) AS SITE_APRV_YN     -- 현장승인여부
                     , SITE_APRV_DT                             -- 현장승인일자
                     , ATFL_GRP
                     , RSTOR_RSN                                -- 반려사유
                  FROM TQHA_SAFECOST_MMARSLT_CO
                 WHERE SIT_CD       = p_SIT_CD                  --현장코드
                   AND CUST_CD      = p_CUST_CD                 --업체코드
                   AND VNDR_SEQ     = p_VNDR_SEQ                --업체순번
                   AND RLV_YM       = p_RLV_YM                  --해당년월
               ) D
             , (-- 20240906 추가 업체 계약별 안전관리비 금액
                SELECT SIT_CD
                     , CONT_NO
                     , CUST_CD
                     , SAFT_CONT_AMT      -- 계약업체(안전관리비 금액)
                  FROM FCMZ_SAFT_DEFC_IF('SM',  p_SIT_CD )
               ) E
             , (
                SELECT A.SIT_CD, B.APRV_STATS
                  FROM TQHA_SAFECOST_APRV A
                     , TQHA_APRV B
                 WHERE A.APRV_NO        = B.APRV_NO
                   AND A.SIT_CD         = B.SIT_CD
                   AND A.SIT_CD         = p_SIT_CD
                   AND A.APRV_DIV       = '2'
                   AND A.APRV_YM        = p_RLV_YM
               ) F
         WHERE A.SIT_CD         = p_SIT_CD          --현장코드
           AND A.CUST_CD        = p_CUST_CD         --업체코드
           AND A.VNDR_SEQ       = p_VNDR_SEQ        --업체순번
           AND A.SIT_CD         = B.SIT_CD(+)
           AND A.SIT_CD         = C.SIT_CD(+)
           AND A.SIT_CD         = D.SIT_CD(+)
           AND A.SIT_CD         = E.SIT_CD(+)
           AND A.CUST_CD        = E.CUST_CD(+)
           AND A.ORD_NO         = E.CONT_NO(+)      -- 계약번호(발주번호)
           AND A.SIT_CD         = F.SIT_CD(+)
        ;

    END IF;


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
         WHEN OTHERS THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);

END PQHA_SAFECOST_REG_CO_Q;
/

-- PQHA_SAFECOST_VNDR_Q (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_SAFECOST_VNDR_Q" (
    p_WRK_TP            IN VARCHAR2 DEFAULT 'Q'           -- FLAG(Q)
,   p_SIT_CD            IN VARCHAR2                       -- 현장
,   RTN_CURSOR          OUT SYS_REFCURSOR
)
IS
    /**************************************************************************************************************************
    COPYRIGHT:    HUMAN PLUS
    PROCEDURE:    [PQHA_SAFECOST_VNDR_Q] PROCEDRE
    설명     :    [QSE > 안전관리 > 산업안전보건관리비 > 업체별 계약금액 조회] 프로시저

     개정일자                      변경내용요약                                 관련근거
    ---------------------------------------------------------------------------------------------------------------------------
     2023-12-05   HUMANPLUS        신규
    ***************************************************************************************************************************/

 
    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009 ; --ERROR 코드
    ERR_MSG        VARCHAR2(200)   ; --ERROR Message
    USER_EXCEPTION EXCEPTION       ;

BEGIN
    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 수행전 Check Logic ]
    ---------------------------------------------------------------------------------------------------------------------------

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Logic 처리
    ---------------------------------------------------------------------------------------------------------------------------

    -- get_SafeCostContList1 계약된 외주 업체의 계약금액 중 안전관리비 금액
    IF p_WRK_TP = 'Q1' THEN

        OPEN RTN_CURSOR FOR
        SELECT D.BZMN_NO                    AS BZMN_NO          --사업자번호
             , D.CUST_NM                    AS CUST_NM          -- 업체명
             , A.SIT_CD                                         -- 현장코드
             , A.CUST_CD                                        -- 업체코드
             , A.VNDR_SEQ                                       -- 업체순번
             , A.ORD_NO                                         -- 외주계약 발주번호
             , A.CHG_DGR                                        -- 외주계약 최종차수
             , A.VNDR_NM                                        -- 공사명
             , A.CONT_DT                                        -- 계약일자
             , A.VNDR_STR_DT                                    -- 공사시작일
             , A.VNDR_END_DT                                    -- 공사종료일
             , A.VNDR_PSN_NM                                    -- 업체담당자 성명
             , B.SCNT_CNST_NM
             , B.CONT_SUM_AMT               AS CONT_AMT         -- 외주 계약금액
             , C.SAFT_CONT_AMT              AS SAFT_AMT         -- 외주 계약금액 중 안전관리비 금액
--           , C.SAFT_CONT_AMT              AS CONT_AMT2        -- 외주 안전관리비 금액( 사용여부 ?)
--           , A.SAFT_AMT                   AS SAFT_AMT         -- 외주 계약금액 중 안전관리비 금액(i/F 안될경우 사용하는 컬럼)
          FROM TQHA_VNDR A
             , VQSZ_SUBCONT B
             , ( -- 20240520 업체 계약별 안전관리비 금액
                 SELECT SIT_CD
                       ,CONT_NO
                       ,CUST_CD
                       ,SAFT_CONT_AMT      -- 계약업체(안전관리비 금액)
                     FROM FCMZ_SAFT_DEFC_IF('SM',  p_SIT_CD )
               )  C
             , VQSZ_TRADE D
         WHERE A.SIT_CD         = p_SIT_CD -- 변수 (현장코드)
           AND A.SIT_CD         = B.SIT_CD(+)
           AND A.ORD_NO         = B.ORD_NO(+)
           AND A.CHG_DGR        = B.CHG_DGR(+)
           AND A.SIT_CD         = C.SIT_CD(+)
           AND A.CUST_CD        = C.CUST_CD(+)
           AND A.ORD_NO         = C.CONT_NO(+)     -- 계약번호(발주번호)
           AND A.CUST_CD        = D.CUST_CD
           -- 20240905 조건 추가
           AND B.CONT_CMPL_YN   = '1'        -- 계약완료여부
           AND B.CUR_CONT_YN    = '1'         --  현계약여부
--         AND NVL(B.CONT_CMPL_YN, '1') = '1'        -- 계약완료여부
--         AND NVL(B.CUR_CONT_YN, '1')  = '1'         --  현계약여부

        ;

    -- (20240524)HS화성에서는 안전의 공종율을 사용하지 않고 공사의 공종율을 사용해서 제외
--    ELSIF p_WRK_TP = 'Q2' THEN
--        OPEN RTN_CURSOR FOR
--
--        SELECT RLV_YM, SIT_CD
--               ,SUM(TMON_PROCRT) AS TMON_PROCRT
--               ,SUM(SUM(TMON_PROCRT)) OVER(ORDER BY RLV_YM) AS SUM
--          FROM TQSA_SAFECOST_PROCRT
--         WHERE SIT_CD = p_SIT_CD    -- 변수 (현장코드)
--         GROUP BY RLV_YM, SIT_CD ;

    END IF; -- 'Q' END


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);

END ;
/

-- PQHA_SAFE_AB_S (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_SAFE_AB_S" (
    p_WRK_TP            VARCHAR2 :='A'                                      -- A: 허가요청 F: 작업완료
,   p_SIT_CD            TQHA_SAFE_PERREQ.SIT_CD             %TYPE           -- 현장코드
,   p_REQ_SEQ           TQHA_SAFE_PERREQ.REQ_SEQ            %TYPE           -- 요청순번
,   p_CUST_CD           TQHA_SAFE_PERREQ.CUST_CD            %TYPE           -- 협력업체코드
,   p_VNDR_SEQ          TQHA_SAFE_PERREQ.VNDR_SEQ           %TYPE           -- 업체순번
,   p_VNDR_YN           TQHA_SAFE_PERREQ.SAFT_CMPL_YN       %TYPE           -- 업체허가요청여부/안전작업완료여부
,   p_VNDR_DT           TQHA_SAFE_PERREQ.SAFT_CMPL_DT       %TYPE           -- 업체허가요청일자/안전작업완료일자
,   p_VNDR_TM           TQHA_SAFE_PERREQ.SAFT_CMPL_TM       %TYPE           -- 안전작업완료시간
)
IS 
    /**************************************************************************************************************************
      Purpose : 

      REVISIONS
      Ver      Date               Author                  Description 
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2022/04/27 10:31:08                         협력업체 허가요청/작업종료요청 여부 처리

    **************************************************************************************************************************/

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR2(200);            -- ERROR Message
    USER_EXCEPTION EXCEPTION;

    v_cnt               INTEGER;                        -- 안전대책 데이타가  존재 여부
    v_MNG_APRV_STATS    VARCHAR2(10) := '0';            -- 허가요청 관리자 승인 여부 체크   
    v_SAFT_CMPL_YN      VARCHAR2(10) := '0';            -- 작업 종료 안전 관리자 승인 여부 체크
BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 필수입력 필드  Check  ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_SIT_CD IS NULL)  THEN
        ERR_MSG := '현장코드는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_REQ_SEQ IS NULL AND p_WRK_TP <> 'I')  THEN
        ERR_MSG := '요청순번는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    -- 허가 요청 시 안전작업 대상작업 미 등록 시 허가 요청 안되도록 추가 5/10 추가
    SELECT nvl(COUNT(REQ_SEQ),0) 
      INTO v_cnt
      FROM TQHA_SAFE_PERREQ_OBJ
     WHERE SIT_CD       = p_SIT_CD      -- 현장코드
       AND REQ_SEQ      = p_REQ_SEQ     -- 요청순번
    ;

    -- 대상작업 데이타가 존재 여부 확인
    IF v_cnt < 1 THEN
        ERR_MSG := '안전 대상작업이 1건이라도 등록이 되어야 허가 요청이 가능합니다. ';
        RAISE USER_EXCEPTION;
    END IF;

    -- 허가 요청 승인 및 작업 종료 승인 여부 체크
    IF p_WRK_TP = 'A' THEN    -- 허가요청

        SELECT nvl(MNG_APRV_STATS,0)
          INTO v_MNG_APRV_STATS
          FROM TQHA_SAFE_PERREQ
         WHERE SIT_CD       = p_SIT_CD      -- 현장코드
           AND REQ_SEQ      = p_REQ_SEQ     -- 요청순번
        ;

        -- 1차 관리자 승인된 경우 제출 및 취소 불가
        IF v_MNG_APRV_STATS = '1' THEN
            ERR_MSG := '해당 허가작업요청(은) 관리자가 승인한 상태이므로 승인요청 및 승인취소가 불가합니다. ';
            RAISE USER_EXCEPTION;
        END IF;

    ELSIF p_WRK_TP = 'F' THEN    -- 작업종료요청  

        SELECT SAFT_CMPL_YN 
          INTO v_SAFT_CMPL_YN
          FROM TQHA_SAFE_PERREQ
         WHERE SIT_CD       = p_SIT_CD      -- 현장코드
           AND REQ_SEQ      = p_REQ_SEQ     -- 요청순번
        ;

        -- 작업 죨료 안전 관리자 승인된 경우 제출 및 취소 불가
        IF v_SAFT_CMPL_YN = '1' THEN
            ERR_MSG := '해당 작업완료요청(은) 안전 관리자가 승인한 상태이므로 작업완료요청 및 작업완료취소가 불가합니다. ';
            RAISE USER_EXCEPTION;
        END IF;

    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Process 선행조건 Check ]
    ---------------------------------------------------------------------------------------------------------------------------
    -- 허가 요청 승인 및 작업 종료 승인 여부 체크
    IF (p_WRK_TP = 'A') THEN    -- 허가요청/취소 UPDATE

        UPDATE TQHA_SAFE_PERREQ
           SET VNDR_APRV_YN         = p_VNDR_YN         -- 업체허가요청여부
             , VNDR_APRV_DT         = p_VNDR_DT         -- 업체허가요청일자
             , MNG_APRV_STATS       = ''                -- 관리감독자 승인상태
             , MNG_APRV_DT          = ''                -- 관리감독자 승인일자
             , SAFT_MGR             = ''                -- 안전관리자
             , SAFT_APRV_STATS      = ''                -- 안전관리자 승인상태
             , SAFT_APRV_DT         = ''                -- 안전관리자 승인일자
             , SITE_OMGR            = ''                -- 현장소장
             , SITE_APRV_STATS      = ''                -- 현장소장 승인상태
             , SITE_APRV_DT         = ''                -- 현장소장 승인일자
         WHERE SIT_CD               = p_SIT_CD
           AND REQ_SEQ              = p_REQ_SEQ  
        ;

    ELSIF (p_WRK_TP = 'F') THEN    -- 작업종료요청/취소 UPDATE

        UPDATE TQHA_SAFE_PERREQ
           SET VNDR_CMPL_YN         = p_VNDR_YN         -- 업체작업완료요청여부
             , VNDR_CMPL_DT         = p_VNDR_DT         -- 작업완료요청일자
             , VNDR_CMPL_TM         = p_VNDR_TM         -- 작업완료요청시간 
             , SAFT_CMPL_YN         = ''                -- 안전작업완료확인여부
             , SAFT_CMPL_DT         = ''                -- 안전작업완료확인일자
             , SAFT_CMPL_TM         = ''                -- 안전작업완료확인시간
             , SAFT_CMPL_CNFR       = ''                -- 안전작업완료확인자
         WHERE SIT_CD               = p_SIT_CD
           AND REQ_SEQ              = p_REQ_SEQ 
        ;

    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 5. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN 
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);

END ;
/

-- PQHA_SAFE_ANALYSIS_Q (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_SAFE_ANALYSIS_Q" (
    p_WRK_TP        VARCHAR2 DEFAULT 'Q'            -- FLAG(Q: 항목, Q1 : 하도급계약 정산결과)
,   p_SIT_CD        TCMZ_SIT.SIT_CD     %TYPE       -- 현장코드
,   RTN_CURSOR      OUT SYS_REFCURSOR
)
IS
    /**************************************************************************************************************************
     COPYRIGHT:    Human Plus
     Procedure:    [PQHA_SAFE_ANALYSIS_Q] Procedure
     설명     :    [정산결과 분석 조회] 프로시저      (안전 > 산업안전보건관리비 > 정산결과 분석 조회 프로시저)

     개정일자                      변경내용요약                                 관련근거
    ---------------------------------------------------------------------------------------------------------------------------
     [2024-06-11]         HumanPlus 신규 자동 생성               [Procedure Creator]
    ***************************************************************************************************************************/

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009; --ERROR 코드
    ERR_MSG        VARCHAR2(200)  ; --ERROR Message
    USER_EXCEPTION EXCEPTION      ;

BEGIN
    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 수행전 Check Logic ]
    ---------------------------------------------------------------------------------------------------------------------------


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Logic 처리
    ---------------------------------------------------------------------------------------------------------------------------

    ------------------
    -- 현장 리스트
    ------------------
    IF (p_WRK_TP ='Q') THEN

        OPEN RTN_CURSOR FOR
        WITH SUBCONT_SUM 
            AS (-- 외주 계약별 최초금액
                SELECT A.SIT_CD                                             -- 현장코드
--                   , A.ORD_NO                                             -- 발주번호
--                   , A.ORD_DGR                                            -- 발주차수
                     , SUM(nvl(A.CONT_SUM_AMT,0))       AS CONT_SUM_AMT     -- 계약최종금액(부가세포함)
                  FROM TSMC_CONT A                                          -- 외주계약
                     , (-- 외주 계약 총금액 - 계약별 최종차수
                        SELECT SIT_CD                                       -- 현장코드
                             , ORD_NO                                       -- 발주번호
                             , max(ORD_DGR) AS ORD_DGR                      -- 발주차수
                          FROM TSMC_CONT
                         WHERE SIT_CD LIKE  p_SIT_CD || '%'                 -- 변수 (현장코드)
                           AND CONT_CMPL_YN = '1'                           -- 계약완료여부
                           AND FNL_DGR_YN = '1'                             -- 최종차수여부
                         group BY  SIT_CD ,  ORD_NO
                       ) B
                 WHERE A.SIT_CD         = B.SIT_CD
                   AND A.ORD_NO         = B.ORD_NO
                   AND A.ORD_DGR        = B.ORD_DGR
                 GROUP BY A.SIT_CD
               )
        , SUBCONT_SAFE 
            AS (-- 협력업체 최종 계약별 계약금액 중 안전관리비 금액
                SELECT SIT_CD
                --   , CONT_NO
                --   , CUST_CD
                --   , SAFT_UNTK_AMT    --안전_도급금액
                --   , SAFT_EBGT_AMT    --안전_실행금액
                     , sum(nvl(SAFT_CONT_AMT,0))  AS SAFT_CONT_AMT     --안전관리비_계약금액
                  FROM FCMZ_SAFT_DEFC_IF('SM', p_SIT_CD)
                 GROUP BY SIT_CD
               )
        SELECT A.SIT_NM                                                         AS SIT_NM               -- 사업장명
             , A.SIT_CD                                                         AS SIT_CD               -- 사업장코드
             , A.PRGS_STATS                                                     AS PRGS_STATS           -- 진행상태(CMZ008)
             , ( SELECT CUST_NM FROM TCOA_TRADE WHERE CUST_CD = B.CUST_CD )     AS CUST_NM              -- 발주자명칭
             , A.CNST_CMPD                                                      AS CNST_CMPD            -- 공사개요
             -- 20240611 수정보완 예정(공동도급 사)
             --,C.SKAT_RT                                                       AS CNST_CUST            -- 원도급사(공동도급인경우 업체명 (최종지분율) )
             --------------------------------------
             , C.TOT_UNTKSO_SUM_AMT                                             AS TOT_UNTKCM_SUM_AMT   -- 총도급합계금액(공사)
             --,A.FTN_ADDR || ' ' ||  A.DTL_ADDR    -- 소재지(기본주소_상세주소)
             , A.SCNST_DT                                                       AS SCNST_DT             -- 착공일자
             , A.CCNST_DT                                                       AS CCNST_DT             -- 준공일자
             , TO_DATE(A.CCNST_DT, 'YYYYMMDD') - TO_DATE(A.SCNST_DT, 'YYYYMMDD') AS CCNST_DU            -- 공사일수
             , round(MONTHS_BETWEEN(TO_DATE(A.CCNST_DT, 'YYYYMMDD'), TO_DATE(A.SCNST_DT, 'YYYYMMDD')),0)  AS CCNST_MM              -- 공사개월(반올림 처리 ?)
             -- 20240623 추가
             , A.CNST_FLD                                                       AS CNST_FLD             -- 공사분야(CMZ006)
             , A.CNST_KND                                                       AS CNST_KND             -- 공사종류(CMZ005)
             , A.CNST_TP                                                        AS CNST_TP              -- 공사유형(CMZ007)
             , A.SIT_TP                                                         AS SIT_TP               -- 현장유형(CMZ004)
             --------------------
             --,C.TOT_UNTKCM_SUM_AMT                                            AS TOT_UNTKCM_SUM_AMT   -- 총도급합계금액_부가세포함(공사)
             -- 20240611 수정보완 예정(하도급금액 계산 )
             , C.TOT_UNTKSO_SUM_AMT                                             AS SUBCONT_TAMT         -- 하도급계약 ( 총공사금액 -> 최종도급금액)
             , D.CONT_SUM_AMT                                                   AS SUBCONT_SAMT         -- 하도급계약 ( 하도급계약금액-최종 하도급계약금액 )
             , decode(nvl(C.TOT_UNTKSO_SUM_AMT,0), 0 , 0,    round(( D.CONT_SUM_AMT / C.TOT_UNTKSO_SUM_AMT ) * 100,2) )      AS SUBCONT_PER           -- 하도급계약 ( 비율 )
             , C.TOT_UNTKSO_SUM_AMT                                             AS SAFECONT_TAMT        -- 하도급산업안전관리비비율 (  총공사금액 - 최종도급금액 (안전관리비 금액 ?)
             , E.SAFT_CONT_AMT                                                  AS SAFECONT_SAM         -- 하도급산업안전관리비비율 ( 산업안전관리비 금액 )
             , decode(nvl(C.TOT_UNTKSO_SUM_AMT,0), 0 , 0,    round(( E.SAFT_CONT_AMT / C.TOT_UNTKSO_SUM_AMT ) * 100,2) )      AS SAFECONT_PER            -- 하도급산업안전관리비비율 ( 비율 )
             ------------------------------------------
          FROM TCMZ_SIT             A                       -- 공사개요
             , TCMZ_SIT_CLIENT      B                       -- 발주처/수요처
             , TCMZ_SIT_CONT        C                       -- 도급/실행정보
             , SUBCONT_SUM          D                       -- 외주 계약(총금액)
             , SUBCONT_SAFE         E                       -- 협력업체 최종 계약별 계약금액 중 안전관리비 금액
         WHERE A.SIT_CD         LIKE  p_SIT_CD || '%'       -- 변수 (현장코드)
           AND A.SIT_CD         =  B.SIT_CD(+)
           AND B.ORDPLC_DIV(+)  = '1010'                    -- 발주처구분(CMZ012) , 발주처 공통코드
           AND A.SIT_CD         = C.SIT_CD(+)
           AND A.SIT_CD         = D.SIT_CD(+)
           AND A.SIT_CD         = E.SIT_CD(+)
        ;

       ------------------
    -- 하도급계약 정산결과
    ------------------
    ELSIF (p_WRK_TP ='Q1') THEN

        OPEN RTN_CURSOR FOR
        WITH SUBCONT_FIR 
        AS (-- 외주 계약별 최초금액
            SELECT A.SIT_CD                                 -- 현장코드
                 , A.ORD_NO                                 -- 발주번호
                 , A.ORD_DGR                                -- 발주차수
                 , A.CONT_DIV                               -- 계약방법(SMB001)
                 , A.CONT_NM                                -- 계약명
                 , A.CUST_CD                                -- 거래처코드
                 , A.CONT_DT                                -- 계약일자
                 , A.CONT_SUM_AMT                           -- 계약최종금액(부가세포함)
              FROM TSMC_CONT A                              -- 외주계약
             WHERE A.SIT_CD             =  p_SIT_CD         -- 변수 (현장코드)
               AND A.CONT_CMPL_YN       = '1'               -- 계약완료여부
               AND A.ORD_DGR            = '0'               -- 최초차수여부(0부터 시작)
               -- 20250307 외주계약 계약구분(CONT_DIV) 공통코드(SMB001):납품(1040)/용역(1050)/건설기계(1060)/건설기계(표준)(1070)/건설폐기물(1080) 제외 처리
               AND A.CONT_DIV           IN ('1010','1020','1030')
             ---------------------
             ORDER BY  A.SIT_CD ,  A.ORD_NO , A.ORD_DGR
        )
        , SUBCONT_FIN 
            AS (-- 외주 계약별 최종금액
                SELECT A.SIT_CD                             -- 현장코드
                     , A.ORD_NO                             -- 발주번호
                     , A.ORD_DGR                            -- 발주차수
                     , A.CONT_DIV                           -- 계약방법(SMB001)
                     , A.CONT_NM                            -- 계약명
                     , A.CUST_CD                            -- 거래처코드
                     , A.CONT_DT                            -- 계약일자
                     , A.CONT_SUM_AMT                       -- 계약최종금액(부가세포함)
                  FROM TSMC_CONT A                          -- 외주계약
                 WHERE A.SIT_CD             =  p_SIT_CD     -- 변수 (현장코드)
                   AND A.CONT_CMPL_YN       = '1'           -- 계약완료여부
                   AND A.FNL_DGR_YN         = '1'           -- 최종차수여부
                 -- 20250307 외주계약 계약구분(CONT_DIV) 공통코드(SMB001):납품(1040)/용역(1050)/건설기계(1060)/건설기계(표준)(1070)/건설폐기물(1080) 제외 처리
                   AND A.CONT_DIV           IN ('1010','1020','1030')
                 ---------------------
                 ORDER BY  A.SIT_CD ,  A.ORD_NO , A.ORD_DGR
            )
        , SUBCONT_SAFE_FIN 
            AS (-- 협력업체 최종 계약별 계약금액 중 안전관리비 금액
                SELECT SIT_CD
                     , CONT_NO
                     , CUST_CD
                --   , SAFT_UNTK_AMT    --안전_도급금액
                --   , SAFT_EBGT_AMT    --안전_실행금액
                     , nvl(SAFT_CONT_AMT,0)  AS SAFT_CONT_AMT     --안전_계약금액(최종)
                  FROM FCMZ_SAFT_DEFC_IF('SM', p_SIT_CD)
        )
        , SUBCONT_SAFE_FIR 
            AS (-- 협력업체 최초 계약별 계약금액 중 안전관리비 금액
                SELECT SIT_CD
                     , CONT_NO
                     , CUST_CD
                --   , SAFT_UNTK_AMT    --안전_도급금액
                --   , SAFT_EBGT_AMT    --안전_실행금액
                     , nvl(SAFT_CONT_AMT,0)  AS SAFT_CONT_AMT     --안전_계약금액(최초)
                  FROM FCMZ_SAFT_DEFC_IF('SM_0', p_SIT_CD)
        )
        , SUBCONT_SAFE_PER 
            AS (-- 계약별 안전관리비 적용요율
                SELECT A.SIT_CD       -- 현장코드
                     , A.ORD_NO       -- 발주번호
                     , A.ORD_DGR      -- 발주차수
                     , A.APL_RT_1     -- 안전관리비 요율 1
                     , A.APL_RT_2     -- 안전관리비 요율 2
                  FROM TSMB_ICST_RT A
                     , ( -- 최종발주차수
                        SELECT SIT_CD, ORD_NO, max(ORD_DGR) AS ORD_DGR
                          from TSMB_ICST_RT
                         WHERE SIT_CD               = p_SIT_CD      -- 현장코드
                           AND substr(STD_CD,-1,1)  = '1'           -- std_cd 의 끝자리 1번이 기본, 나머지 확장/옵션(주택인경우)
                           AND STD_CD               LIKE 'B002%'    -- 안전관리비 : 표준공종
                         GROUP BY SIT_CD, ORD_NO
                       ) B
                     WHERE A.SIT_CD                 = B.SIT_CD
                       AND A.ORD_NO                 = B.ORD_NO
                       AND A.ORD_DGR                = B.ORD_DGR
                       AND A.SIT_CD                 = p_SIT_CD      -- 현장코드
                       AND substr(A.STD_CD,-1,1)    = '1'           -- std_cd 의 끝자리 1번이 기본, 나머지 확장/옵션(주택인경우)
                       AND A.STD_CD                 LIKE 'B002%'    -- 안전관리비 : 표준공종
        )
        SELECT A.SIT_CD                                         AS SIT_CD                   -- 현장코드
             , A.ORD_NO                                         AS ORD_NO                   -- 발주번호
--           , A.ORD_DGR                                        AS ORD_DGR_FIR              -- 최초차수
             , B.CONT_DIV                                       AS CONT_MTD_FIN             -- 계약방법(SMB001)
             , B.ORD_DGR                                        AS ORD_DGR_FIN              -- 최종 차수
--           , A.CONT_NM                                        AS CONT_NM_FIR              -- 최초계약명
             , B.CONT_NM                                        AS CONT_NM_FIN              -- 최종 계약명
             , A.CUST_CD                                        AS CUST_CD                  -- 거래처코드
             , C.CUST_NM                                        AS CUST_NM                  -- 거래처업체명
--           , A.CONT_DT                                        AS CONT_FIR_DT              -- 최초계약일자
--           , B.CONT_DT                                        AS CONT_FIN_DT              -- 최종계약일자
--           , A.CONT_SUM_AMT                                   AS CONT_SUM_AMT_FIR         -- 최초계약금액
             , B.CONT_SUM_AMT                                   AS CONT_SUM_AMT_FIN         -- 최종계약금액
             -- 20240612 수정 보완 추가 예정
             , G.APL_RT_1                                       AS SATT_AMT_PER             -- 안전관리비 적용요율
             , nvl(F.SAFT_CONT_AMT,0)                           AS SATT_AMT_FIR             -- 안전관리비 최초금액
             , nvl(D.SAFT_CONT_AMT,0)                           AS SATT_AMT_FIN             -- 안전관리비 최종금액
             , nvl(D.SAFT_CONT_AMT,0) - nvl(F.SAFT_CONT_AMT,0)  AS SATT_AMT_DIF             -- 안전관리비 증감( 최종금액 - 최초금액)
              --------------------------------------------------------------------------------------
          FROM SUBCONT_FIR          A           -- 외주 계약별 최초금액
             , SUBCONT_FIN          B           -- 외주 계약별 최종금액
             , TCOA_TRADE           C
             , SUBCONT_SAFE_FIN     D           -- 협력업체 최종 계약별 계약금액 중 안전관리비 금액
             , SUBCONT_SAFE_FIR     F           -- 협력업체 최초 계약별 계약금액 중 안전관리비 금액
             , SUBCONT_SAFE_PER     G           -- 계약별 안전관리비 적용요율
         WHERE A.SIT_CD     = B.SIT_CD(+)
           AND A.ORD_NO     = B.ORD_NO(+)
           AND B.CUST_CD    = C.CUST_CD(+)
           AND A.SIT_CD     = D.SIT_CD(+)
           AND A.ORD_NO     = D.CONT_NO(+)
           AND A.SIT_CD     = F.SIT_CD(+)
           AND A.ORD_NO     = F.CONT_NO(+)
           AND A.SIT_CD     = G.SIT_CD(+)
           AND A.ORD_NO     = G.ORD_NO(+)
        ;

    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);

END;
/

-- PQHA_SAFE_APRS_Q (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_SAFE_APRS_Q" (
                                                          p_WRK_TP    VARCHAR2 DEFAULT 'Q'  --FLAG(Q: SELECT)
                                                         ,p_SIT_CD    TSMB_ORD.SIT_CD %TYPE --현장코드                                                          
                                                         ,p_ORD_DT_FR TSMB_ORD.ORD_DT %TYPE --발주일자_FR
                                                         ,p_ORD_DT_TO TSMB_ORD.ORD_DT %TYPE --발주일자_TO
                                                         ,RTN_CURSOR OUT SYS_REFCURSOR 
                                                         )
IS 
    /**************************************************************************************************************************
     COPYRIGHT:    Human Plus   
     Procedure:    [PSMB_SAFT_APRS_CURST_Q] Procedure
     설명     :    [적격수급인이행현황 조회] 프로시저 (외주 > 안전적격평가 > 적격수급인이행현황 > 적격수급인이행현황 조회 프로시저)

     개정일자                      변경내용요약                                 관련근거        
    ---------------------------------------------------------------------------------------------------------------------------
     [2024-03-19]         HumanPlus 신규 자동 생성               [Procedure Creator]  
    ***************************************************************************************************************************/

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009 ; --ERROR 코드
    ERR_MSG        VARCHAR2(200)   ; --ERROR Message
    USER_EXCEPTION EXCEPTION       ;
BEGIN
    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 수행전 Check Logic ]
    ---------------------------------------------------------------------------------------------------------------------------


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Logic 처리
    ---------------------------------------------------------------------------------------------------------------------------
    IF p_WRK_TP = 'Q' THEN    
        OPEN RTN_CURSOR FOR
		-- 20240909 수정        
        WITH TMP_00 AS (--해당 발주건 SELECT
                        SELECT SIT_CD
                              ,ORD_NO
                              ,ORD_DGR
                          FROM TSMB_ORD
                         WHERE ORD_DT BETWEEN NVL(p_ORD_DT_FR, '19000101') AND p_ORD_DT_TO
                           AND ORD_DGR = 0 --최초건
                       ) 
            ,TMP_10 AS (--안전적격평가 : 선정최저점수
                        SELECT A.SIT_CD       SIT_CD       --현장코드
                              ,A.ORD_NO       ORD_NO       --발주번호
                              ,A.ORD_DGR      ORD_DGR      --발주차수
                              ,A.SEL_LWST_SCR SEL_LWST_SCR --선정최저점수
                              -- 20240909 추가
                              ,A.BD_DGR	      BD_DGR       --입찰차수
                              ,APRSR_ID       APRSR_ID	 --평가담당ID
                          FROM TSMB_SAFT_APRS A
                         WHERE A.BD_DGR = 1
                           AND EXISTS (
                                       SELECT '1'
                                         FROM TMP_00 Z
                                        WHERE Z.SIT_CD  = A.SIT_CD
                                          AND Z.ORD_NO  = A.ORD_NO
                                          AND Z.ORD_DGR = A.ORD_DGR
                                      )
                       )
            ,TMP_20 AS (--안전적격평가 : 안전평가점수
                        SELECT A.SIT_CD        SIT_CD        --현장코드
                              ,A.ORD_NO        ORD_NO        --발주번호
                              ,A.ORD_DGR       ORD_DGR       --발주차수
                              ,A.CUST_CD       CUST_CD       --거래처코드
                              ,A.SAFT_APRS_SCR SAFT_APRS_SCR --안전평가점수
                              ,A.BD_RNK        BD_RNK        --입찰순위
                              ,A.SBD_YN        SBD_YN        --낙찰여부
                          FROM TSMB_BD_VNDR A
                               INNER JOIN TSMB_BD B ON B.SIT_CD    = A.SIT_CD
                                                   AND B.ORD_NO    = A.ORD_NO
                                                   AND B.ORD_DGR   = A.ORD_DGR
                                                   AND B.BD_DGR    = A.BD_DGR
                                                   AND B.CUR_BD_YN = '1' --현입찰여부
                         WHERE A.PRTC_QLF_YN = '1' --참여자격여부
                           AND EXISTS (
                                       SELECT '1'
                                         FROM TMP_00 Z
                                        WHERE Z.SIT_CD  = A.SIT_CD
                                          AND Z.ORD_NO  = A.ORD_NO
                                          AND Z.ORD_DGR = A.ORD_DGR
                                      )
                       )
            ,TMP_21 AS (--입찰참가업체수 SELECT
                        SELECT A.SIT_CD         SIT_CD       --현장코드
                              ,A.ORD_NO         ORD_NO       --발주번호
                              ,A.ORD_DGR        ORD_DGR      --발주차수
                              ,COUNT(A.CUST_CD) TOT_CUST_CNT --입찰참가업체수
                          FROM TMP_20 A
                         WHERE EXISTS (
                                       SELECT '1'
                                         FROM TMP_00 Z
                                        WHERE Z.SIT_CD  = A.SIT_CD
                                          AND Z.ORD_NO  = A.ORD_NO
                                          AND Z.ORD_DGR = A.ORD_DGR
                                      )
                         GROUP BY A.SIT_CD
                                 ,A.ORD_NO
                                 ,A.ORD_DGR
                       )
            ,TMP_22 AS (--점수미달업체수 SELECT
                        SELECT A.SIT_CD        SIT_CD       --현장코드
                              ,A.ORD_NO        ORD_NO       --발주번호
                              ,A.ORD_DGR       ORD_DGR      --발주차수
                              ,COUNT(A.SIT_CD) UND_VNDR_CNT --점수미달업체수
                          FROM TMP_20 A 
                         WHERE EXISTS (
                                       SELECT '1'
                                         FROM TMP_10 B 
                                        WHERE B.SIT_CD       = A.SIT_CD
                                          AND B.ORD_NO       = A.ORD_NO
                                          AND B.ORD_DGR      = A.ORD_DGR
                                          AND B.SEL_LWST_SCR > A.SAFT_APRS_SCR
                                      )
                         GROUP BY A.SIT_CD
                                 ,A.ORD_NO
                                 ,A.ORD_DGR
                       )
            ,TMP_23 AS (--낙찰업체 SELECT
                        SELECT A.SIT_CD        SIT_CD        --현장코드
                              ,A.ORD_NO        ORD_NO        --발주번호
                              ,A.ORD_DGR       ORD_DGR       --발주차수
                              ,A.CUST_CD       CUST_CD       --거래처코드
                              ,B.CUST_NM       CUST_NM       --거래처명
                              ,A.BD_RNK        BD_RNK        --입찰순위
                              ,A.SAFT_APRS_SCR SAFT_APRS_SCR --안전평가점수
                              ,A.SBD_YN        SBD_YN        --낙찰여부
                          FROM TMP_20 A
                               INNER JOIN VSMA_VNDR B ON B.CUST_CD = A.CUST_CD
                                                     AND B.GUBUN   = '10' --외주거래처
                         WHERE A.SBD_YN = '1' --낙찰여부
                       )
        SELECT A.SIT_CD                               SIT_CD        --현장코드
              ,Z.SIT_NM                               SIT_NM        --현장명
              ,A.ORD_NO                               ORD_NO        --발주번호
              ,A.ORD_NM                               ORD_NM        --발주명
              ,A.ORD_DGR                              ORD_DGR       --발주차수
              ,A.ORD_DT                               ORD_DT        --발주일자
              ,A.ORD_CTP_CD                           ORD_CTP_CD    --발주공종코드
              ,B.ORD_CTP_NM                           ORD_CTP_NM    --발주공종명
              ,NVL(F.TOT_CUST_CNT,0)                  TOT_CUST_CNT  --입찰참가업체수
              ,NVL(G.UND_VNDR_CNT,0)                  UND_VNDR_CNT  --점수미달업체수
              ,H.CUST_NM                              SBD_CUST_NM   --낙찰업체명
              ,H.BD_RNK                               BD_RNK        --낙찰업체_입찰순위
              ,H.SAFT_APRS_SCR                        SAFT_APRS_SCR --낙찰업체_안전평가점수              
              ,NVL(E.SAFT_XTRA_YN, '0')               SAFT_XTRA_YN  --안전관리비별도합산여부
              ,NVL(E.DURA_MARK_YN, '0')               DURA_MARK_YN  --계약기간변경가능현설명시여부
              ,NULL                                   RMKS          --비고
              ,CASE WHEN H.BD_RNK != 1                 
                     AND H.SBD_YN  = '1' THEN '1'      
                                         ELSE '0' END CLRT_APL_YN   --색상적용여부
               -- 20240909 추가    
			  ,C.BD_DGR						          BD_DGR		--입찰차수                                     
              ,H.CUST_CD                              CUST_CD       --낙찰업체코드                           
              ,NVL(F.TOT_CUST_CNT,0)                  TOT_CUST_CNT  --입찰참가업체수        (추가)
              ,NVL(G.UND_VNDR_CNT,0)                  UND_VNDR_CNT  --점수미달업체수        (추가)
              ,H.BD_RNK                               BD_RNK        --낙찰업체_입찰순위     (추가)  
          	  ,X.NCR_ITM						      NCR_ITM		--부적합항목
			  ,X.NCR_RSN                              NCR_RSN		--부적합사유
			  ,X.RCR_PLN                              RCR_PLN		--재발방지대책       			  
           FROM TSMB_ORD A
               INNER JOIN TSMZ_ORD_CTP B ON B.ORD_CTP_CD = A.ORD_CTP_CD
               INNER JOIN TMP_10       C ON C.SIT_CD     = A.SIT_CD --[안전적격평가 : 선정최저점수]
                                        AND C.ORD_NO     = A.ORD_NO
                                        AND C.ORD_DGR    = A.ORD_DGR
               LEFT  JOIN TSMB_STDM    E ON E.SIT_CD     = A.SIT_CD
                                        AND E.ORD_NO     = A.ORD_NO
                                        AND E.ORD_DGR    = A.ORD_DGR
               LEFT  JOIN TMP_21       F ON F.SIT_CD     = A.SIT_CD --[입찰참가업체수]
                                        AND F.ORD_NO     = A.ORD_NO 
                                        AND F.ORD_DGR    = A.ORD_DGR
               LEFT  JOIN TMP_22       G ON G.SIT_CD     = A.SIT_CD --[점수미달업체수]
                                        AND G.ORD_NO     = A.ORD_NO 
                                        AND G.ORD_DGR    = A.ORD_DGR
               LEFT  JOIN TMP_23       H ON H.SIT_CD     = A.SIT_CD --[낙찰업체]
                                        AND H.ORD_NO     = A.ORD_NO 
                                        AND H.ORD_DGR    = A.ORD_DGR
               INNER JOIN TCMZ_SIT     Z ON Z.SIT_CD     = A.SIT_CD
               LEFT  JOIN TQHA_SELECT  X ON X.SIT_CD     = C.SIT_CD
                            			AND X.ORD_NO 	 = C.ORD_NO
                            			AND X.ORD_DGR    = C.ORD_DGR
                            			AND X.BD_DGR 	 = C.BD_DGR                
         WHERE A.ORD_DT BETWEEN NVL(p_ORD_DT_FR, '19000101') AND p_ORD_DT_TO
           AND A.SIT_CD = p_SIT_CD
           AND A.ORD_DGR = 0 --최초건
        ;       

    END IF;


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN 
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);
END;
/

-- PQHA_SAFE_COST_MNG_Q (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_SAFE_COST_MNG_Q" (  
    p_WRK_TP        IN VARCHAR2 DEFAULT 'Q'         -- FLAG(Q: 현장평가, Q1:본사평가)
,   p_SIT_CD        IN VARCHAR2 
,   p_ITM_DIV       IN VARCHAR2                     -- 예산구분
,   p_RLV_YM        IN VARCHAR2                     -- 해당년월
,   RTN_CURSOR      OUT SYS_REFCURSOR
)
IS
    /**************************************************************************************************************************
      Purpose : 안전보건관리비

      REVISIONS
      Ver      Date               Author                  Description
      -------  -----------------  ----------------------  ---------------------------------------------------------------------
      1.0      2026/02/26                                 최초생성  

    **************************************************************************************************************************/

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE  NUMBER :=-20009; -- ERROR 코드
    ERR_MSG   VARCHAR(200);    -- ERROR Message
    USER_EXCEPTION EXCEPTION;

BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 수행전 Check Logic ]
    ---------------------------------------------------------------------------------------------------------------------------

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Logic 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    -- 현장의 월별실행 예산 예산년월 목록 조회
    IF p_WRK_TP = 'Q1' THEN

        OPEN RTN_CURSOR FOR
        SELECT RLV_YM
          FROM TQHA_SAFECOST_BGTYM
         WHERE SIT_CD   = p_SIT_CD
           AND ITM_DIV  = p_ITM_DIV
        ;

    ---------------------------------------------------------------------------------
    -- 공정률 조회 <= 사용 X.  TQSA_SAFECOST_PROCRT  테이블 없음.
--    ELSIF p_WRK_TP = 'Q2' THEN
--    
--        OPEN RTN_CURSOR FOR
--        SELECT RLV_YM
--          FROM TQSA_SAFECOST_PROCRT
--         WHERE SIT_CD = p_SIT_CD
--        ;

    ---------------------------------------------------------------------------------
    -- get_SafeCostOrgInfo 조회
    ELSIF p_WRK_TP = 'Q3' THEN

        OPEN RTN_CURSOR FOR
        SELECT NVL(A.SIT_CD, B.SIT_CD)                      AS SIT_CD           -- 현장코드
             , A.APRS_RNK                                                       -- 시공능력평가순위
             , A.ORG_NM                                                         -- 조직명
             , A.ORG_DTY                                                        -- 직책
             , A.ORG_PCNT                                                       -- 인원 수
             -- , A.SAFT_APRP_TAMT                                              -- 안전보건관리비 계상총액
             -- , A.SAFT_PLAN_TAMT                                              -- 본사임급 등 계상액(계획)
             , NVL(A.SAFT_APRP_TAMT, B.CHG_EBGT_BGT)        AS SAFT_APRP_TAMT   -- 월별 산업안전보건관리비 변경 전체실행예산
             , NVl(A.SAFT_PLAN_TAMT, B.CHG_EBGT_BGT08)      AS SAFT_PLAN_TAMT   -- 월별 산업안전보건관리비 임금 등 계상액
          FROM TQHA_BON_ORG A
             , (-- 산업안전보건관리비 월별 변경실행예산 계산
                 SELECT B.SIT_CD
                      , B.RLV_YM
                      , NVL(SUM(B.CHG_EBGT_BGT), 0)                         AS CHG_EBGT_BGT     -- 월별 산업안전보건관리비 변경 실행예산
                      , SUM(DECODE(B.ITM_DIV, '08', B.CHG_EBGT_BGT, 0))     AS CHG_EBGT_BGT08
                   FROM TQHA_SAFECOST_BGTYM B
                  WHERE B.SIT_CD    = p_SIT_CD  -- 변수 (현장코드)
                    AND B.RLV_YM    = p_RLV_YM
                  GROUP BY B.SIT_CD, B.RLV_YM
             ) B
         WHERE A.SIT_CD(+)   = p_SIT_CD      -- 변수 (현장코드)
           AND A.RLV_YM(+)   = p_RLV_YM      -- 변수 (해당년월)
           AND A.SIT_CD(+)   = B.SIT_CD
           AND A.RLV_YM(+)   = B.RLV_YM
        ;

    ---------------------------------------------------------------------------------
    -- get_SafeCostOrgCnt 조회
    ELSIF p_WRK_TP = 'Q4' THEN

        OPEN RTN_CURSOR FOR
        SELECT COUNT(*)     AS CNT
          FROM TQHA_BON_ORG
         WHERE RLV_YM   = p_RLV_YM
           AND SIT_CD   = p_SIT_CD
        ;

    END IF;


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
         WHEN OTHERS THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);
END PQHA_SAFE_COST_MNG_Q;
/

-- PQHA_SAFE_COST_REQ_CO_Q (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_SAFE_COST_REQ_CO_Q" (
    p_WRK_TP            IN VARCHAR2 DEFAULT 'Q'             -- FLAG(Q: 현장평가, Q1:본사평가)
,   p_SIT_CD            IN VARCHAR2                         -- 현장코드
,   p_ITM_DIV           IN VARCHAR2                         -- 안전항목
,   p_RLV_YM            IN VARCHAR2                         -- 해당년월
,   p_CUST_CD           IN VARCHAR2                         -- 고객코드
,   p_VNDR_SEQ          IN VARCHAR2                         -- 업체순번
,   RTN_CURSOR       OUT SYS_REFCURSOR
)
IS

    /**************************************************************************************************************************
      Purpose : 산업안전보건관리비

      REVISIONS
      Ver      Date               Author                  Description
      -------  -----------------  ----------------------  ---------------------------------------------------------------------
      1.0      2026/03/03                                 최초생성

    **************************************************************************************************************************/

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE  NUMBER :=-20009; -- ERROR 코드
    ERR_MSG   VARCHAR(200);    -- ERROR Message
    USER_EXCEPTION EXCEPTION;

BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 수행전 Check Logic ]
    ---------------------------------------------------------------------------------------------------------------------------

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Logic 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    -- 협력업체 매월 사용실적 조회 ( 1 안전보건관리자 입금 )
    IF p_ITM_DIV = '01' THEN

        OPEN RTN_CURSOR FOR
        SELECT SIT_CD      -- 현장코드
             , ITM_DIV      -- 항목구분 (공통코드 QS026)
             , (SELECT CD_NM FROM TCOA_COMCODE WHERE COM_CD = ITM_DIV AND HRNK_CD = 'QS026') AS ITM_DIV_NM
             , RLV_YM       -- 해당년월
             , USE_SEQ      -- 사용순번
             , BLN_18       -- 소속
             , PNM_18       -- 성명
             , PRCR_DT_18   -- 선임일자
             , USE_AMT      -- 사용금액(지급금액)
             , USE_DT       -- 사용일자(지급일자)
             , USE_DTLS     -- 사용내역(지급내역)
             , RMKS         -- 비고
             , GRP_PHOTO_1  -- 첨부파일그룹1
             , PHOTO_DESC_1 -- 사진설명1
             , CUST_CD      -- 업체코드
             , VNDR_SEQ     -- 업체순번
             , DLV_VNDR     -- 납품업체
             , CASE WHEN (SELECT COUNT(*) FROM TCOZ_ATFL WHERE ATFL_GRP = GRP_PHOTO_1 OR ATFL_GRP = GRP_PHOTO_2) > 0 THEN 'O' ELSE 'X' END AS ATFL_GRP_YN
             , GRP_PHOTO_2  -- 첨부파일그룹2
             , PHOTO_DESC_2 -- 사진설명2
             , USE_QNT      -- 수량
             , USE_UPRC     -- 단가
          FROM TQHA_SAFECOST_ARSLT_CO
         WHERE SIT_CD       = p_SIT_CD        -- 변수(현장코드)
           AND ITM_DIV      = p_ITM_DIV       -- 안전 9대항목  01 안전보건관리자 입금 02 안전시설비 03 보호구 04 안전보건진단비 05 안전보건 교육비 06 근조자 건강장해예방비  07기술지도비 08 본사점담조직  09 위험성평가에 다른 소모비용
           AND RLV_YM       = p_RLV_YM        -- 변수(년월)
           AND CUST_CD      = p_CUST_CD       -- 변수 (업체코드)
           AND VNDR_SEQ     = p_VNDR_SEQ      -- 변수 (업체순번)
         ORDER BY ITM_DIV, USE_DT
        ;

    --------------------------------------------------------------------------------
    -- 협력업체 매월 사용실적 조회 ( 2 안전시설비 )
    ELSIF p_ITM_DIV = '02' THEN

        OPEN RTN_CURSOR FOR
        SELECT SIT_CD       -- 현장코드
             , ITM_DIV      -- 항목구분 (공통코드 QS026)
             , (SELECT CD_NM FROM TCOA_COMCODE WHERE COM_CD = ITM_DIV AND HRNK_CD = 'QS026') AS ITM_DIV_NM
             , RLV_YM       -- 해당년월
             , USE_SEQ      -- 사용순번
             , USE_DT       -- 사용일자
             , USE_UNT      -- 사용단위
             , USE_QNT      -- 사용수량
             , USE_UPRC     -- 사용단가 계(노무비단가 + 자재비단가)
             , USE_AMT      -- 사용금액
             , USE_DTLS     -- 사용내역(지급내역)
             , RMKS         -- 비고
             , GRP_PHOTO_1  -- 첨부파일그룹1
             , PHOTO_DESC_1 -- 사진설명1
             , CUST_CD      -- 업체코드
             , VNDR_SEQ     -- 업체순번
             , DLV_VNDR     -- 납품업체
             , CASE WHEN (SELECT COUNT(*) FROM TCOZ_ATFL WHERE ATFL_GRP = GRP_PHOTO_1 OR ATFL_GRP = GRP_PHOTO_2) > 0 THEN 'O' ELSE 'X' END AS ATFL_GRP_YN
             , GRP_PHOTO_2  -- 첨부파일그룹2
             , PHOTO_DESC_2 -- 사진설명2
          FROM TQHA_SAFECOST_ARSLT_CO
         WHERE SIT_CD       = p_SIT_CD     -- 변수(현장코드)
           AND ITM_DIV      = p_ITM_DIV    -- 안전 9대항목  01 안전보건관리자 입금 02 안전시설비 03 보호구 04 안전보건진단비 05 안전보건 교육비 06 근조자 건강장해예방비  07기술지도비 08 본사점담조직  09 위험성평가에 다른 소모비용
           AND RLV_YM       = p_RLV_YM     -- 변수(년월)
           AND CUST_CD      = p_CUST_CD    -- 변수 (업체코드)
           AND VNDR_SEQ     = p_VNDR_SEQ   -- 변수 (업체순번)
         ORDER BY ITM_DIV, USE_DT
        ;

    --------------------------------------------------------------------------------
    -- 협력업체 매월 사용실적 조회 ( 3 보호구 )
    ELSIF p_ITM_DIV = '03' THEN

        OPEN RTN_CURSOR FOR
        SELECT SIT_CD      -- 현장코드
                 , ITM_DIV      -- 항목구분 (공통코드 QS026)
                 , (SELECT CD_NM FROM TCOA_COMCODE WHERE COM_CD = ITM_DIV AND HRNK_CD = 'QS026') AS ITM_DIV_NM
                 , RLV_YM       -- 해당년월
                 , USE_SEQ      -- 사용순번
                 , PLN_UPRC_39  -- 계획단가
                 , PLN_QNT_39   -- 계획수량
                 , PLN_AMT_39   -- 계획금액
                 , USE_DT       -- 사용일자
                 , USE_UPRC     -- 사용단가
                 , USE_QNT      -- 사용수량
                 , USE_AMT      -- 사용금액
                 , USE_DTLS     -- 사용내역(지급내역)
                 , RMKS         -- 비고
                 , GRP_PHOTO_1  -- 첨부파일그룹1
                 , PHOTO_DESC_1 -- 사진설명1
                 , CUST_CD      -- 업체코드
                 , VNDR_SEQ     -- 업체순번
                 , DLV_VNDR     -- 납품업체
                 , CASE WHEN (SELECT COUNT(*) FROM TCOZ_ATFL WHERE ATFL_GRP = GRP_PHOTO_1 OR ATFL_GRP = GRP_PHOTO_2) > 0 THEN 'O' ELSE 'X' END AS ATFL_GRP_YN
                 , GRP_PHOTO_2  -- 첨부파일그룹2
                 , PHOTO_DESC_2 -- 사진설명2
            FROM TQHA_SAFECOST_ARSLT_CO
            WHERE SIT_CD   = p_SIT_CD      -- 변수(현장코드)
              AND ITM_DIV  = p_ITM_DIV     -- 안전 9대항목  01 안전보건관리자 입금 02 안전시설비 03 보호구 04 안전보건진단비 05 안전보건 교육비 06 근조자 건강장해예방비  07기술지도비 08 본사점담조직  09 위험성평가에 다른 소모비용
              AND RLV_YM   = p_RLV_YM      -- 변수(년월)
              AND CUST_CD  = p_CUST_CD     -- 변수 (업체코드)
              AND VNDR_SEQ = p_VNDR_SEQ    -- 변수 (업체순번)
            ORDER BY ITM_DIV, USE_DT
        ;

    --------------------------------------------------------------------------------
    -- 협력업체 매월 사용실적 조회 ( 4 안전보건진단비 )
    ELSIF p_ITM_DIV = '04' THEN

        OPEN RTN_CURSOR FOR
        SELECT SIT_CD       -- 현장코드
             , ITM_DIV      -- 항목구분 (공통코드 QS026)
             , (SELECT CD_NM FROM TCOA_COMCODE WHERE COM_CD = ITM_DIV AND HRNK_CD = 'QS026') AS ITM_DIV_NM
             , RLV_YM       -- 해당년월
             , USE_SEQ      -- 사용순번
             , DGS_ORG_4    -- 진단기관
             , USE_DT       -- 사용일자
             , USE_AMT      -- 사용금액(소요비용)
             , USE_DTLS     -- 사용내역(지급내역)
             , RMKS         -- 비고
             , GRP_PHOTO_1  -- 첨부파일그룹1
             , PHOTO_DESC_1 -- 사진설명1
             , CUST_CD      -- 업체코드
             , VNDR_SEQ     -- 업체순번
             , CASE WHEN (SELECT COUNT(*) FROM TCOZ_ATFL WHERE ATFL_GRP = GRP_PHOTO_1 OR ATFL_GRP = GRP_PHOTO_2) > 0 THEN 'O' ELSE 'X' END AS ATFL_GRP_YN
             , GRP_PHOTO_2  -- 첨부파일그룹2
             , PHOTO_DESC_2 -- 사진설명2
             , USE_UPRC     -- 사용단가
             , USE_QNT      -- 사용수량
          FROM TQHA_SAFECOST_ARSLT_CO
         WHERE SIT_CD       = p_SIT_CD    -- 변수(현장코드)
           AND ITM_DIV      = p_ITM_DIV   -- 안전 9대항목  01 안전보건관리자 입금 02 안전시설비 03 보호구 04 안전보건진단비 05 안전보건 교육비 06 근조자 건강장해예방비  07기술지도비 08 본사점담조직  09 위험성평가에 다른 소모비용
           AND RLV_YM       = p_RLV_YM    -- 변수(년월)
           AND CUST_CD      = p_CUST_CD   -- 변수 (업체코드)
           AND VNDR_SEQ     = p_VNDR_SEQ  -- 변수 (업체순번)
         ORDER BY ITM_DIV, USE_DT
        ;

    --------------------------------------------------------------------------------
    -- 협력업체 매월 사용실적 조회 ( 5 안전보건교육비 )
    ELSIF p_ITM_DIV = '05' THEN

        OPEN RTN_CURSOR FOR
        SELECT SIT_CD      -- 현장코드
             , ITM_DIV      -- 항목구분 (공통코드 QS026)
             , (SELECT CD_NM FROM TCOA_COMCODE WHERE COM_CD = ITM_DIV AND HRNK_CD = 'QS026') AS ITM_DIV_NM
             , RLV_YM       -- 해당년월
             , USE_SEQ      -- 사용순번
             , EDU_ATTL5    -- 교육과목
             , EDU_SPNC_5   -- 교육주관
             , USE_DT       -- 사용일자(교육일)
             , PRTC_PSNNO_56   -- 참가인원(숫자)
             , USE_AMT      -- 사용금액(소요경비)
             , RMKS         -- 비고
             , GRP_PHOTO_1  -- 첨부파일그룹1
             , PHOTO_DESC_1 -- 사진설명1
             , CUST_CD      -- 업체코드
             , VNDR_SEQ     -- 업체순번
             , CASE WHEN (SELECT COUNT(*) FROM TCOZ_ATFL WHERE ATFL_GRP = GRP_PHOTO_1 OR ATFL_GRP = GRP_PHOTO_2) > 0 THEN 'O' ELSE 'X' END AS ATFL_GRP_YN
             , GRP_PHOTO_2  -- 첨부파일그룹2
             , PHOTO_DESC_2 -- 사진설명2
             , USE_UPRC     -- 사용단가
             , USE_QNT      -- 사용수량
          FROM TQHA_SAFECOST_ARSLT_CO
         WHERE SIT_CD       = p_SIT_CD          -- 변수(현장코드)
           AND ITM_DIV      = p_ITM_DIV         -- 안전 9대항목  01 안전보건관리자 입금 02 안전시설비 03 보호구 04 안전보건진단비 05 안전보건 교육비 06 근조자 건강장해예방비  07기술지도비 08 본사점담조직  09 위험성평가에 다른 소모비용
           AND RLV_YM       = p_RLV_YM          -- 변수(년월)
           AND CUST_CD      = p_CUST_CD         -- 변수 (업체코드)
           AND VNDR_SEQ     = p_VNDR_SEQ        -- 변수 (업체순번)
         ORDER BY ITM_DIV, USE_DT
        ;

    --------------------------------------------------------------------------------
    -- 협력업체 매월 사용실적 조회 ( 6 근로자 건강장해예방비 )
    ELSIF p_ITM_DIV = '06' THEN

        OPEN RTN_CURSOR FOR
        SELECT SIT_CD       -- 현장코드
             , ITM_DIV      -- 항목구분 (공통코드 QS026)
             , (SELECT CD_NM FROM TCOA_COMCODE WHERE COM_CD = ITM_DIV AND HRNK_CD = 'QS026') AS ITM_DIV_NM
             , RLV_YM       -- 해당년월
             , USE_SEQ      -- 사용순번
             , USE_DT       -- 사용일자
             , DGS_HOSP6      -- 진단병원
             , PRTC_PSNNO_56  -- 참가인원
             , USE_AMT      -- 사용금액(소요경비)
             , RMKS         -- 비고
             , GRP_PHOTO_1  -- 첨부파일그룹1
             , PHOTO_DESC_1 -- 사진설명1
             , CUST_CD      -- 업체코드
             , VNDR_SEQ     -- 업체순번
             , CASE WHEN (SELECT COUNT(*) FROM TCOZ_ATFL WHERE ATFL_GRP = GRP_PHOTO_1 OR ATFL_GRP = GRP_PHOTO_2) > 0 THEN 'O' ELSE 'X' END AS ATFL_GRP_YN
             , GRP_PHOTO_2  -- 첨부파일그룹2
             , PHOTO_DESC_2 -- 사진설명2
             , USE_UPRC     -- 사용단가
             , USE_QNT      -- 사용수량
          FROM TQHA_SAFECOST_ARSLT_CO
         WHERE SIT_CD       = p_SIT_CD          -- 변수(현장코드)
           AND ITM_DIV      = p_ITM_DIV         -- 안전 9대항목  01 안전보건관리자 입금 02 안전시설비 03 보호구 04 안전보건진단비 05 안전보건 교육비 06 근조자 건강장해예방비  07기술지도비 08 본사점담조직  09 위험성평가에 다른 소모비용
           AND RLV_YM       = p_RLV_YM          -- 변수(년월)
           AND CUST_CD      = p_CUST_CD         -- 변수 (업체코드)
           AND VNDR_SEQ     = p_VNDR_SEQ        -- 변수 (업체순번)
         ORDER BY ITM_DIV, USE_DT
        ;
    --------------------------------------------------------------------------------
    -- 협력업체 매월 사용실적 조회 (9 위험성평가 등에 따른 소요비용)
    ELSIF p_ITM_DIV = '09' THEN

        OPEN RTN_CURSOR FOR
        SELECT SIT_CD         -- 현장코드
             , ITM_DIV        -- 항목구분 (공통코드 QS026)
             , (SELECT CD_NM FROM TCOA_COMCODE WHERE COM_CD = ITM_DIV AND HRNK_CD = 'QS026') AS ITM_DIV_NM
             , RLV_YM         -- 해당년월
             , USE_SEQ        -- 사용순번
             , USE_DT         -- 사용일자
             , DGS_HOSP6      -- 진단병원
             , PRTC_PSNNO_56  -- 참가인원
             , USE_AMT        -- 사용금액(소요경비)
             , RMKS           -- 비고
             , GRP_PHOTO_1    -- 첨부파일그룹1
             , PHOTO_DESC_1   -- 사진설명1
             , CUST_CD        -- 업체코드
             , VNDR_SEQ       -- 업체순번
             , CASE WHEN (SELECT COUNT(*) FROM TCOZ_ATFL WHERE ATFL_GRP = GRP_PHOTO_1 OR ATFL_GRP = GRP_PHOTO_2) > 0 THEN 'O' ELSE 'X' END AS ATFL_GRP_YN
             , GRP_PHOTO_2    -- 첨부파일그룹2
             , PHOTO_DESC_2   -- 사진설명2
             , USE_UPRC       -- 사용단가
             , USE_QNT        -- 사용수량
             , USE_DTLS       -- 품명/규격
             , ITM_9          -- 지급내역
             , DLV_VNDR       -- 거래납품업체
          FROM TQHA_SAFECOST_ARSLT_CO
         WHERE SIT_CD       = p_SIT_CD          -- 변수(현장코드)
           AND ITM_DIV      = p_ITM_DIV         -- 안전 9대항목  01 안전보건관리자 입금 02 안전시설비 03 보호구 04 안전보건진단비 05 안전보건 교육비 06 근조자 건강장해예방비  07기술지도비 08 본사점담조직  09 위험성평가에 다른 소모비용
           AND RLV_YM       = p_RLV_YM          -- 변수(년월)
           AND CUST_CD      = p_CUST_CD         -- 변수 (업체코드)
           AND VNDR_SEQ     = p_VNDR_SEQ        -- 변수 (업체순번)
         ORDER BY ITM_DIV, USE_DT
        ;

    END IF;


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
         WHEN OTHERS THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);

END PQHA_SAFE_COST_REQ_CO_Q ;
/

-- PQHA_SAFE_PERM_CD_S (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_SAFE_PERM_CD_S" (
    p_WRK_TP        VARCHAR2 :='U'                              -- UPDATE FLAG( I: ISNERT, U:UPDATE, D:DELTE)
,   p_WRK_ID        VARCHAR2                                    -- 사용자 ID 
,   p_WRK_IP        VARCHAR2                                    -- 사용자 IP 
,   p_PER_CD        TQHA_SAFE_PERM_CD.PER_CD        %TYPE       -- 허가코드
,   p_PER_NM        TQHA_SAFE_PERM_CD.PER_NM        %TYPE       -- 허가작업명칭
,   p_USE_YN        TQHA_SAFE_PERM_CD.USE_YN        %TYPE       -- 사용여부
)
IS 
    /**************************************************************************************************************************
      Purpose : 

      REVISIONS
      Ver      Date               Author                  Description 
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2021/10/25 15:20:45                         최초생성

    **************************************************************************************************************************/


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR2(200);            -- ERROR Message
    USER_EXCEPTION EXCEPTION;

     v_PER_CD TQHA_SAFE_PERM_CD.PER_CD%TYPE ;             -- 허가코드 변수 선언
     v_cnt  INTEGER;                                      -- 안전작업 목록 하위 안전대책 코드 존재 여부
BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 필수입력 필드  Check  ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_PER_CD IS NULL AND p_WRK_TP <> 'I' )  THEN
        ERR_MSG := '허가코드는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

       --  안전작업 목록 하위코드 존재 여부 확인
    IF p_WRK_TP = 'D' THEN

        SELECT nvl(COUNT(PER_CD),0) 
          INTO v_cnt
          FROM TQHA_SAFE_PERM_CPLN
         WHERE PER_CD = p_PER_CD 
        ;   

         -- 안전대책 코드 Validation
        IF v_cnt > 0 THEN
           ERR_MSG := '안전작업 "' || p_PER_NM || '" 은(는) 하위 안전대책 항목이 존재합니다. 하위 작업별 안전대책을 전부 삭제해야 안전작업목록을 삭제할 수 있습니다. ';
           RAISE USER_EXCEPTION;
        END IF;
    END IF;     
    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Process 선행조건 Check ]
    ---------------------------------------------------------------------------------------------------------------------------



    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Business Process ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_WRK_TP ='D') THEN

        DELETE 
          FROM TQHA_SAFE_PERM_CD
         WHERE PER_CD = p_PER_CD         --허가코드
        ;

    ELSIF (p_WRK_TP ='U') THEN

        UPDATE TQHA_SAFE_PERM_CD
           SET PER_NM           = p_PER_NM          -- 허가작업명칭
             , USE_YN           = p_USE_YN          -- 사용여부
             , UPD_ID           = p_WRK_ID          -- 수정ID 
             , UPD_DTM          = SYSDATE()         -- 수정일시
             , UPD_IP           = p_WRK_IP          -- 수정IP
         WHERE PER_CD           = p_PER_CD          -- 허가코드
        ;

    ELSE 

        -- 허가코드 MAX부여
        SELECT  LPAD(NVL(MAX(SUBSTR(PER_CD, 1, 2)), 0) + 1, 2,'0')
          INTO v_PER_CD
          FROM TQHA_SAFE_PERM_CD 
        ; 
        --
        INSERT 
          INTO TQHA_SAFE_PERM_CD
             ( PER_CD               -- 허가코드
             , PER_NM               -- 허가작업명칭
             , USE_YN               -- 사용여부
             , IPT_ID               -- 입력ID
             , IPT_DTM              -- 입력일시
             , IPT_IP               -- 입력IP
             , UPD_ID               -- 수정ID
             , UPD_DTM              -- 수정일시
             , UPD_IP               -- 수정IP
             )
        VALUES 
            ( v_PER_CD              -- 허가코드
            , p_PER_NM              -- 허가작업명칭
            , '1'                   -- 사용여부 디폴트 사용처리
            , p_WRK_ID              -- 입력ID 
            , SYSDATE()             -- 입력일시
            , p_WRK_IP              -- 입력IP
            , p_WRK_ID              -- 수정ID
            , SYSDATE()             -- 수정일시
            , p_WRK_IP              -- 수정IP
            )
        ;

    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 5. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN 
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);
END ;
/

-- PQHA_SAFE_PERM_CPLN_Q (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_SAFE_PERM_CPLN_Q" (
    p_WRK_TP            IN VARCHAR2 DEFAULT 'Q'         -- FLAG
,   p_PER_CD            IN VARCHAR2                     -- 상위작업코드
,   RTN_CURSOR          OUT SYS_REFCURSOR
)
IS
    /**************************************************************************************************************************
      Purpose : [안전작업허가코드 목록] PROCEDRE 

      REVISIONS
      Ver      Date               Author                  Description
      -------  -----------------  ----------------------  ---------------------------------------------------------------------
      1.0      2026/02/05                                 최초생성

    **************************************************************************************************************************/

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE  NUMBER :=-20009; -- ERROR 코드
    ERR_MSG   VARCHAR(200);    -- ERROR Message
    USER_EXCEPTION EXCEPTION;

BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 수행전 Check Logic ]
    ---------------------------------------------------------------------------------------------------------------------------

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Logic 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------

    ---------------------------------------------------------------------------------------
    -- 
    IF p_WRK_TP = 'Q' THEN

        OPEN RTN_CURSOR FOR
        SELECT PER_CD -- 허가코드
             , PER_NM -- 허가신청명칭
             , USE_YN -- 허가 사용유무
          FROM TQHA_SAFE_PERM_CD
        ;

    ELSIF p_WRK_TP = 'Q2' THEN

        OPEN RTN_CURSOR FOR
        SELECT PER_CD          -- 상위작업코드
             , CPLN_CD         -- 안전대책코드
             , CPLN_NM         -- 안전대책명칭
             , USE_YN          -- 안전대책사용유무
          FROM TQHA_SAFE_PERM_CPLN
         WHERE PER_CD   = p_PER_CD
        ;

    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
         WHEN OTHERS THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);

END PQHA_SAFE_PERM_CPLN_Q;
/

-- PQHA_SAFE_PERM_CPLN_S (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_SAFE_PERM_CPLN_S" (
    p_WRK_TP        VARCHAR2 :='U'                                  -- UPDATE FLAG( I: ISNERT, U:UPDATE, D:DELTE)
,   p_WRK_ID        VARCHAR2                                        -- 사용자 ID 
,   p_WRK_IP        VARCHAR2                                        -- 사용자 IP 
,   p_PER_CD        TQHA_SAFE_PERM_CPLN.PER_CD          %TYPE       -- 허가코드
,   p_CPLN_CD       TQHA_SAFE_PERM_CPLN.CPLN_CD         %TYPE       -- 대책코드
,   p_CPLN_NM       TQHA_SAFE_PERM_CPLN.CPLN_NM         %TYPE       -- 대책명칭
,   p_USE_YN        TQHA_SAFE_PERM_CPLN.USE_YN          %TYPE       -- 사용여부
)
IS 
    /**************************************************************************************************************************
      Purpose : 

      REVISIONS
      Ver      Date               Author                  Description 
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2021/10/25 15:24:22                         최초생성

    **************************************************************************************************************************/

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR2(200);            -- ERROR Message
    USER_EXCEPTION EXCEPTION;

     v_CPLN_CD      TQHA_SAFE_PERM_CPLN.CPLN_CD %TYPE ;         -- 안전대책코드 변수 선언
     v_cnt          INTEGER;                                    -- 안전대책코드 사용여부 확인

BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 필수입력 필드  Check  ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_PER_CD IS NULL)  THEN
        ERR_MSG := '허가코드는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_CPLN_CD IS NULL AND p_WRK_TP <> 'I' )  THEN
        ERR_MSG := '대책코드는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

       --  안저넌대책 코드 사용 여부 확인
    IF p_WRK_TP = 'D' THEN
        -- 안전작업 대상작업별 대책
        SELECT nvl(COUNT(CPLN_CD),0) 
          INTO v_cnt
          FROM TQHA_SAFE_PERREQ_OBJLST 
         WHERE PER_CD = p_PER_CD
           AND CPLN_CD = p_CPLN_CD 
        ;

        -- 안전작업 대상작업별 Validation
        IF ( v_cnt ) > 0 THEN
           ERR_MSG := '작업별 안전대책 "' || p_CPLN_NM || '" 은(는) 사용중입니다.. 사용중인 안전대책은 삭제할 수 없습니다. ';
           RAISE USER_EXCEPTION;
        END IF;

    END IF;  
    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Process 선행조건 Check ]
    ---------------------------------------------------------------------------------------------------------------------------



    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Business Process ] 
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_WRK_TP ='D') THEN

        DELETE 
          FROM TQHA_SAFE_PERM_CPLN
         WHERE PER_CD       = p_PER_CD          -- 허가코드
           AND CPLN_CD      = p_CPLN_CD         -- 대책코드
        ;

    ELSIF (p_WRK_TP ='U') THEN

        UPDATE TQHA_SAFE_PERM_CPLN
           SET CPLN_NM          = p_CPLN_NM     -- 대책명칭
             , USE_YN           = p_USE_YN      -- 사용여부
             , UPD_ID           = p_WRK_ID      -- 수정ID 
             , UPD_DTM          = SYSDATE()     -- 수정일시
             , UPD_IP           = p_WRK_IP      -- 수정IP
         WHERE PER_CD           = p_PER_CD      -- 허가코드
           AND CPLN_CD          = p_CPLN_CD     -- 대책코드
        ;

    ELSE 

        -- 안전대책코드 MAX부여
        SELECT LPAD(NVL(MAX(SUBSTR(CPLN_CD, 1, 3)), 0) + 1, 3,'0')
          INTO v_CPLN_CD
          FROM TQHA_SAFE_PERM_CPLN  
         WHERE PER_CD = p_PER_CD 
        ; 
        --
        INSERT 
          INTO TQHA_SAFE_PERM_CPLN
             ( PER_CD               -- 허가코드
             , CPLN_CD              -- 대책코드
             , CPLN_NM              -- 대책명칭
             , USE_YN               -- 사용여부
             , IPT_ID               -- 입력ID
             , IPT_DTM              -- 입력일시
             , IPT_IP               -- 입력IP
             , UPD_ID               -- 수정ID
             , UPD_DTM              -- 수정일시
             , UPD_IP               -- 수정IP
             )
        VALUES 
             ( p_PER_CD             -- 허가코드
             , v_CPLN_CD            -- 대책코드
             , p_CPLN_NM            -- 대책명칭
             , '1'                  -- 사용여부 디폴트 사용여부 처리
             , p_WRK_ID             -- 입력ID 
             , SYSDATE()            -- 입력일시
             , p_WRK_IP             -- 입력IP
             , p_WRK_ID             -- 수정ID
             , SYSDATE()            -- 수정일시
             , p_WRK_IP             -- 수정IP
             )
        ;

    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 5. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN 
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);

END ;
/

-- PQHA_SAFE_PERREQ_B1 (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_SAFE_PERREQ_B1" ( -- 안전허가작업 승인
    p_WRK_TP                VARCHAR2 :='S'                                  -- UPDATE FLAG( I: ISNERT, U:UPDATE, D:DELTE, S : 승인처리)
,   p_WRK_ID                VARCHAR2                                        -- 사용자 ID
,   p_WRK_IP                VARCHAR2                                        -- 사용자 IP
,   p_SIT_CD                TQHA_SAFE_PERREQ.SIT_CD             %TYPE       -- 현장코드
,   p_REQ_SEQ               TQHA_SAFE_PERREQ.REQ_SEQ            %TYPE       -- 요청순번
,   p_USR_ID                TQHA_SAFE_PERREQ.WRK_CHR_PSN        %TYPE       -- 사번
,   p_RTN_BTN               OUT VARCHAR2                                    -- 리턴값 (안전관리자, 현장소장 승인여부)
,   p_RTN_MNG_DIV           OUT VARCHAR2                                    -- 리턴값 (관리자/안전/소장)
)
IS
    /**************************************************************************************************************************
      Purpose : 안전허가작업 승인

      REVISIONS
      Ver      Date               Author                  Description
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2022/1/4 12:48:42                         최초생성

    **************************************************************************************************************************/


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR2(200);            -- ERROR Message
    USER_EXCEPTION EXCEPTION;

    v_MGR_APRV      VARCHAR2(1) ;   -- 관리감독자 승인여부
    v_SAFT_APRV     VARCHAR2(1) ;   -- 안전감독자 승인여부
    v_SITE_APRV     VARCHAR2(1) ;   -- 현장소장 승인여부

    v_MGR_CNT       INTEGER;     -- 관리감독자 여부
    v_SAFT_CNT      INTEGER;     -- 안전관리자 여부
    v_SITE_CNT      INTEGER;     -- 현장소장 여부


    v_RTN_BTN VARCHAR2(1) := 'F' ;       -- 리턴 초기값 (관리감독자, 안전관리자, 현장소장)
    v_RTN_MNG_DIV VARCHAR2(10) := 'N' ;  -- 리턴 상태 초기값 ( 관리자 MGR : 관리자, SAFT : 안전관리자, SITE : 현장소장 )


BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 필수입력 필드  Check  ]
    ---------------------------------------------------------------------------------------------------------------------------
         -- 안전작업허가에서 승읜 할 데이터가 있는지 체크
        SELECT nvl(MNG_APRV_STATS,0)            -- 관리감독자 승인여부
             , nvl(SAFT_APRV_STATS,0)           -- 안전관리자 승인여부
             , nvl(SITE_APRV_STATS,0)           -- 현장소장 승인여부
          INTO v_MGR_APRV                       -- 관리감독자 승인여부
             , v_SAFT_APRV                      -- 안전관리자 승인여부
             , v_SITE_APRV                      -- 현장소장 승인여부
          FROM TQHA_SAFE_PERREQ
         WHERE SIT_CD       = p_SIT_CD          -- 변수 (현장코드)
           AND REQ_SEQ      = p_REQ_SEQ         -- 변수 (요청순번 )
        ;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Process 선행조건 Check ]
    ---------------------------------------------------------------------------------------------------------------------------


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Business Process ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_WRK_TP = 'S') THEN    -- 승인처리

        -- 관리자 승인 전 단계
        IF (v_MGR_APRV = '0') THEN

            -- 관리자가 승인 권한이 있는지 체크
            SELECT nvl(COUNT(MNG_SUPR),0)
              INTO v_MGR_CNT
              FROM TQHA_SAFE_PERREQ
             WHERE SIT_CD       = p_SIT_CD          -- 변수 (현장코드)
               AND REQ_SEQ      = p_REQ_SEQ         -- 변수 (요청순번 )
               AND MNG_SUPR     = p_USR_ID          -- 변수 (사번)
            ;

            -- 숭인권한이 있음
            IF v_MGR_CNT > 0 then
                v_RTN_BTN       := 'T';
                v_RTN_MNG_DIV   := 'MGR';
            END IF;

        END IF;

        -- 관리자 승인 후 단계
        IF (v_MGR_APRV = '1' AND v_SAFT_APRV = '0' ) THEN     -- 관리자 승인 후 AND 안전관리자 승인 전

            /*
            -- 안전관리자 승인 권한이 있는지 체크
            SELECT  nvl(COUNT(JB_CD),0)
              INTO v_SAFT_CNT
              FROM  ( -- 조직도에서 직무코드가 안전관리자인 경우
                     SELECT   DEPT_CD   -- 현장코드
                           , USR_ID    -- 사용자 id
                           , JB_CD     -- 직무코드
                      FROM TCOZ_USR_INFO
                     WHERE DEPT_CD = p_SIT_CD       -- 변수(현장코드)
                     AND  JB_CD IN ('B37E01','CM0135','CM0136','CM0137') ) A
             WHERE A.DEPT_CD = p_SIT_CD   -- 변수 (현장코드)
               AND A.USR_ID = p_USR_ID     -- 변수 (사용자id)
                  ;
            */

            -- 안전관리자 승인 권한이 있는지 체크
            SELECT  nvl(COUNT(JB_CD),0)
              INTO v_SAFT_CNT
              FROM (
                    -- 2026.01.20 주석처리
                    -- 조직도에서 직무코드가 안전관리자인 경우
                    --SELECT   DEPT_CD   -- 현장코드
                    --        , USR_ID    -- 사용자 id
                    --        , JB_CD     -- 직무코드
                    --  FROM TCOZ_USR_INFO
                    -- WHERE DEPT_CD = p_SIT_CD       -- 변수(현장코드)
                    --   AND  JB_CD IN ('B37E01','CM0135','CM0136','CM0137')
                    -- UNION   -- 2020/5/18 일 겸직정보 추가
                    -- SELECT DEPT_CD   -- 현장코드
                    --       , USR_ID    -- 사용자 id
                    --       , JB_CD     -- 직무코드
                    --   FROM TCOZ_SBJB_INFO
                    --  WHERE DEPT_CD = p_SIT_CD
                    --    AND JB_CD IN ('B37E01','CM0135','CM0136','CM0137')

                    SELECT SIT_CD    AS DEPT_CD
                         , EMPE_NO    AS USR_ID
                         , JB_CD      AS JB_CD
                      FROM TQHA_SITENAM
                     WHERE SIT_CD = p_SIT_CD
                       AND EMPE_NO = p_USR_ID
                       AND JB_CD IN ('QS07702')  -- 안전관리자, 안전총괄
                    ) A
             WHERE A.DEPT_CD    = p_SIT_CD      -- 변수 (현장코드)
               AND A.USR_ID     = p_USR_ID      -- 변수 (사용자id)
            ;

            -- 안전관리자가 승인 권한이 있는지 체크
            IF v_SAFT_CNT > 0 then
                v_RTN_BTN       := 'T';
                v_RTN_MNG_DIV   := 'SAFT';
            END IF;

        END IF;

        -- 안전관리자 승인 후 단계
        IF (v_MGR_APRV = '1' AND v_SAFT_APRV = '1') THEN

            -- 현장소장 승인 권한이 있는지 체크
            SELECT nvl(COUNT(JB_CD),0)
              INTO v_SITE_CNT
              FROM (
                    -- 2026.01.20 주석처리
                    -- 조직도에서 직무코드가 안전관리자인 경우
                    --                    SELECT   DEPT_CD   -- 현장코드
                    --                          , USR_ID    -- 사용자 id
                    --                          , JB_CD     -- 직무코드
                    --                     FROM TCOZ_USR_INFO
                    --                    WHERE DEPT_CD = p_SIT_CD   -- 변수(현장코드)
                    --                    AND  JB_CD IN ('B37F01')
                    SELECT SIT_CD       AS DEPT_CD
                         , EMPE_NO      AS USR_ID
                         , DTY_CD       AS JB_CD
                      FROM TQHA_SITENAM
                     WHERE SIT_CD = p_SIT_CD
                       AND DTY_CD IN ('B37F01')       -- 현장소장
                   ) A
             WHERE A.DEPT_CD    = p_SIT_CD      -- 변수 (현장코드)
               AND A.USR_ID     = p_USR_ID      -- 변수 (사용자id)
            ;

            -- 현장소장 승인 권한이 있는지 체크
            IF v_SITE_CNT > 0 then
                v_RTN_BTN       := 'T';
                v_RTN_MNG_DIV   := 'SITE';
            END IF;

        END IF;

       -- 현장소장 승인 후 단계
        IF (v_SITE_APRV <> '0' ) THEN
            v_RTN_BTN       := 'F';
            v_RTN_MNG_DIV   := 'N';
        END IF;

        p_RTN_BTN := v_RTN_BTN ;
        p_RTN_MNG_DIV := v_RTN_MNG_DIV ;

    END IF;


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 5. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);

END PQHA_SAFE_PERREQ_B1;
/

-- PQHA_SAFE_PERREQ_OBJLST_S (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_SAFE_PERREQ_OBJLST_S" (
    p_WRK_TP            VARCHAR2 :='U'                                      -- UPDATE FLAG( I: ISNERT, U:UPDATE, D:DELTE)
,   p_WRK_ID            VARCHAR2                                            -- 사용자 ID 
,   p_WRK_IP            VARCHAR2                                            -- 사용자 IP 
,   p_SIT_CD            TQHA_SAFE_PERREQ_OBJLST.SIT_CD          %TYPE       -- 현장코드
,   p_REQ_SEQ           TQHA_SAFE_PERREQ_OBJLST.REQ_SEQ         %TYPE       -- 요청순번
,   p_PER_CD            TQHA_SAFE_PERREQ_OBJLST.PER_CD          %TYPE       -- 허가코드
,   p_CPLN_CD           TQHA_SAFE_PERREQ_OBJLST.CPLN_CD         %TYPE       -- 대책코드
,   p_RMKS              TQHA_SAFE_PERREQ_OBJLST.RMKS            %TYPE       -- 비고
)
IS 
    /**************************************************************************************************************************
      Purpose : 

      REVISIONS
      Ver      Date               Author                  Description 
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2021/12/23 18:38:18                         최초생성

    **************************************************************************************************************************/


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR2(200);            -- ERROR Message
    USER_EXCEPTION EXCEPTION;

BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 필수입력 필드  Check  ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_SIT_CD IS NULL)  THEN
        ERR_MSG := '현장코드는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_REQ_SEQ IS NULL)  THEN
        ERR_MSG := '요청순번는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_PER_CD IS NULL)  THEN
        ERR_MSG := '허가코드는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_CPLN_CD IS NULL)  THEN
        ERR_MSG := '대책코드는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Process 선행조건 Check ]
    ---------------------------------------------------------------------------------------------------------------------------



    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Business Process ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_WRK_TP ='D') THEN

        DELETE 
          FROM TQHA_SAFE_PERREQ_OBJLST
         WHERE SIT_CD = p_SIT_CD         --현장코드
           AND REQ_SEQ = p_REQ_SEQ         --요청순번
           AND PER_CD = p_PER_CD          --허가코드
           AND CPLN_CD = p_CPLN_CD        --대책코드
        ;

    ELSIF (p_WRK_TP ='U') THEN

        UPDATE TQHA_SAFE_PERREQ_OBJLST
           SET RMKS                 = p_RMKS                    --비고
              ,UPD_ID               = p_WRK_ID                  --수정ID 
              ,UPD_DTM              = SYSDATE()                 --수정일시
              ,UPD_IP               = p_WRK_IP                  --수정IP
         WHERE SIT_CD = p_SIT_CD         --현장코드
           AND REQ_SEQ = p_REQ_SEQ         --요청순번
           AND PER_CD = p_PER_CD          --허가코드
           AND CPLN_CD = p_CPLN_CD        --대책코드
        ;

    ELSE

        INSERT 
          INTO TQHA_SAFE_PERREQ_OBJLST
             ( SIT_CD           -- 현장코드
             , REQ_SEQ          -- 요청순번
             , PER_CD           -- 허가코드
             , CPLN_CD          -- 대책코드
             , RMKS             -- 비고
             , IPT_ID           -- 입력ID
             , IPT_DTM          -- 입력일시
             , IPT_IP           -- 입력IP
             , UPD_ID           -- 수정ID
             , UPD_DTM          -- 수정일시
             , UPD_IP           -- 수정IP
             )
        VALUES 
             ( p_SIT_CD         -- 현장코드
             , p_REQ_SEQ        -- 요청순번
             , p_PER_CD         -- 허가코드
             , p_CPLN_CD        -- 대책코드
             , p_RMKS           -- 비고
             , p_WRK_ID         -- 입력ID 
             , SYSDATE()        -- 입력일시
             , p_WRK_IP         -- 입력IP
             , p_WRK_ID         -- 수정ID
             , SYSDATE()        -- 수정일시
             , p_WRK_IP         -- 수정IP
             )
        ;

    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 5. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN 
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);

END ;
/

-- PQHA_SAFE_PERREQ_OBJ_S (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_SAFE_PERREQ_OBJ_S" (
    p_WRK_TP            VARCHAR2 :='U'                                  -- UPDATE FLAG( I: ISNERT, U:UPDATE, D:DELTE)
,   p_WRK_ID            VARCHAR2                                        -- 사용자 ID
,   p_WRK_IP            VARCHAR2                                        -- 사용자 IP
,   p_SIT_CD            TQHA_SAFE_PERREQ_OBJ.SIT_CD         %TYPE       -- 현장코드
,   p_REQ_SEQ           TQHA_SAFE_PERREQ_OBJ.REQ_SEQ        %TYPE       -- 요청순번
,   p_PER_CD            TQHA_SAFE_PERREQ_OBJ.PER_CD         %TYPE       -- 허가코드
,   p_WRK_PLC           TQHA_SAFE_PERREQ_OBJ.WRK_PLC        %TYPE       -- 작업장소
,   p_IPT_PSNNO         TQHA_SAFE_PERREQ_OBJ.IPT_PSNNO      %TYPE       -- 투입인원
,   p_WRK_CTS           TQHA_SAFE_PERREQ_OBJ.WRK_CTS        %TYPE       -- 작업내용
)
IS
    /**************************************************************************************************************************
      Purpose :

      REVISIONS
      Ver      Date               Author                  Description
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2021/12/23 18:36:17                         최초생성

    **************************************************************************************************************************/


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR2(200);            -- ERROR Message
    USER_EXCEPTION EXCEPTION;

    V_PER_NM       VARCHAR2(200);               -- 대상작업명칭 가져오기
    v_cnt  INTEGER;                             -- 안전대책 데이타가  존재 여부

BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 필수입력 필드  Check  ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_SIT_CD IS NULL)  THEN
        ERR_MSG := '현장코드는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_REQ_SEQ IS NULL)  THEN
        ERR_MSG := '요청순번는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_PER_CD IS NULL)  THEN
        ERR_MSG := '허가코드는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Process 선행조건 Check ]
    ---------------------------------------------------------------------------------------------------------------------------
    --  대상작업별 안전대책 데이타가 존재 여부 확인
    IF p_WRK_TP = 'D' THEN

        SELECT nvl(COUNT(CPLN_CD),0)
          INTO v_cnt
          FROM TQHA_SAFE_PERREQ_OBJLST
         WHERE SIT_CD       = p_SIT_CD      -- 현장코드
           AND REQ_SEQ      = p_REQ_SEQ     -- 요청순번
           AND PER_CD       = p_PER_CD      -- 허가코드
        ;

         -- 안전대책 데이타가 존재 여부 확인
        IF v_cnt > 0 THEN
            -- 안전대상작업 명칭 가져오기
            SELECT PER_NM
              INTO V_PER_NM
              FROM TQHA_SAFE_PERM_CD
             WHERE PER_CD = p_PER_CD        -- 허가코드
            ;

            ERR_MSG := '대상 작업 "' || V_PER_NM || '" 은(는) 하위 안전대책 항목이 존재합니다. 안전 대책을 삭제해야 삭제할 수 있습니다. ';
            RAISE USER_EXCEPTION;
        END IF;

    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Business Process ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_WRK_TP ='D') THEN

        DELETE
          FROM TQHA_SAFE_PERREQ_OBJ
         WHERE SIT_CD       = p_SIT_CD      -- 현장코드
           AND REQ_SEQ      = p_REQ_SEQ     -- 요청순번
           AND PER_CD       = p_PER_CD      -- 허가코드
        ;

    ELSIF (p_WRK_TP ='U') THEN

        UPDATE TQHA_SAFE_PERREQ_OBJ
           SET WRK_PLC      = p_WRK_PLC     -- 작업장소
              ,IPT_PSNNO    = p_IPT_PSNNO   -- 투입인원
              ,WRK_CTS      = p_WRK_CTS     -- 작업내용
              ,UPD_ID       = p_WRK_ID      -- 수정ID
              ,UPD_DTM      = SYSDATE()     -- 수정일시
              ,UPD_IP       = p_WRK_IP      -- 수정IP
         WHERE SIT_CD       = p_SIT_CD      -- 현장코드
           AND REQ_SEQ      = p_REQ_SEQ     -- 요청순번
           AND PER_CD       = p_PER_CD      -- 허가코드
        ;

    ELSE

        INSERT 
          INTO TQHA_SAFE_PERREQ_OBJ
             ( SIT_CD               -- 현장코드
             , REQ_SEQ              -- 요청순번
             , PER_CD               -- 허가코드
             , WRK_PLC              -- 작업장소
             , IPT_PSNNO            -- 투입인원
             , WRK_CTS              -- 작업내용
             , IPT_ID               -- 입력ID
             , IPT_DTM              -- 입력일시
             , IPT_IP               -- 입력IP
             , UPD_ID               -- 수정ID
             , UPD_DTM              -- 수정일시
             , UPD_IP               -- 수정IP
             )
        VALUES 
             ( p_SIT_CD             -- 현장코드
             , p_REQ_SEQ            -- 요청순번
             , p_PER_CD             -- 허가코드
             , p_WRK_PLC            -- 작업장소
             , p_IPT_PSNNO          -- 투입인원
             , p_WRK_CTS            -- 작업내용
             , p_WRK_ID             -- 입력ID
             , SYSDATE()            -- 입력일시
             , p_WRK_IP             -- 입력IP
             , p_WRK_ID             -- 수정ID
             , SYSDATE()            -- 수정일시
             , p_WRK_IP             -- 수정IP
             )
        ;

    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 5. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);
END ;
/

-- PQHA_SAFE_PERREQ_S (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_SAFE_PERREQ_S" (
    p_WRK_TP                    VARCHAR2 :='U'                                          -- UPDATE FLAG( I: ISNERT, U:UPDATE, D:DELTE)
,   p_WRK_ID                    VARCHAR2                                                -- 사용자 ID
,   p_WRK_IP                    VARCHAR2                                                -- 사용자 IP
,   p_SIT_CD                    TQHA_SAFE_PERREQ.SIT_CD                 %TYPE           -- 현장코드
,   p_REQ_SEQ                   TQHA_SAFE_PERREQ.REQ_SEQ                %TYPE           -- 요청순번
,   p_CUST_CD                   TQHA_SAFE_PERREQ.CUST_CD                %TYPE           -- 협력업체코드
,   p_VNDR_SEQ                  TQHA_SAFE_PERREQ.VNDR_SEQ               %TYPE           -- 업체순번
,   p_VNDR_REQ_DT               TQHA_SAFE_PERREQ.VNDR_REQ_DT            %TYPE           -- 업체요청일자
,   p_VNDR_STR_DT               TQHA_SAFE_PERREQ.VNDR_STR_DT            %TYPE           -- 업체시작일자
,   p_VNDR_STR_TM               TQHA_SAFE_PERREQ.VNDR_STR_TM            %TYPE           -- 업체시작시간
,   p_VNDR_END_TM               TQHA_SAFE_PERREQ.VNDR_END_TM            %TYPE           -- 업체종료시간
,   p_VNDR_REQ_PSN              TQHA_SAFE_PERREQ.VNDR_REQ_PSN           %TYPE           -- 업체요청자
,   p_WRK_CHR_PSN               TQHA_SAFE_PERREQ.WRK_CHR_PSN            %TYPE           -- 작업담당자
,   p_ADD_RISK_CMP              TQHA_SAFE_PERREQ.ADD_RISK_CMP           %TYPE           -- 추가위험요소
,   p_SAFT_CPLN                 TQHA_SAFE_PERREQ.SAFT_CPLN              %TYPE           -- 안전대책
,   p_VNDR_APRV_YN              TQHA_SAFE_PERREQ.VNDR_APRV_YN           %TYPE           -- 승인요청 1 미요청 0
,   p_VNDR_APRV_DT              TQHA_SAFE_PERREQ.VNDR_APRV_DT           %TYPE           -- 업체승인요청일자
,   p_MNG_SUPR                  TQHA_SAFE_PERREQ.MNG_SUPR               %TYPE           -- 관리감독자
,   p_MNG_APRV_DT               TQHA_SAFE_PERREQ.MNG_APRV_DT            %TYPE           -- 관리승인일자
,   p_MNG_APRV_STATS            TQHA_SAFE_PERREQ.MNG_APRV_STATS         %TYPE           -- 승인 1, 반려 2
,   p_SAFT_MGR                  TQHA_SAFE_PERREQ.SAFT_MGR               %TYPE           -- 안전관리자
,   p_SAFT_APRV_DT              TQHA_SAFE_PERREQ.SAFT_APRV_DT           %TYPE           -- 안전승인일자
,   p_SAFT_APRV_STATS           TQHA_SAFE_PERREQ.SAFT_APRV_STATS        %TYPE           -- 승인 1, 반려 2
,   p_SITE_OMGR                 TQHA_SAFE_PERREQ.SITE_OMGR              %TYPE           -- 현장소장
,   p_SITE_APRV_DT              TQHA_SAFE_PERREQ.SITE_APRV_DT           %TYPE           -- 소장승인일자
,   p_SITE_APRV_TM              TQHA_SAFE_PERREQ.SITE_APRV_TM           %TYPE           -- 현장승인시간
,   p_SITE_APRV_STATS           TQHA_SAFE_PERREQ.SITE_APRV_STATS        %TYPE           -- 승인 1, 반려 2
,   p_SAFT_MA_CNF               TQHA_SAFE_PERREQ.SAFT_MA_CNF            %TYPE           -- 안전조치확인
,   p_PER_NO                    TQHA_SAFE_PERREQ.PER_NO                 %TYPE           -- 허가번호
,   p_APRV_PSN                  TQHA_SAFE_PERREQ.APRV_PSN               %TYPE           -- 결재자
,   p_APRV_NO                   TQHA_SAFE_PERREQ.APRV_NO                %TYPE           -- 결재번호
,   p_VNDR_CMPL_YN              TQHA_SAFE_PERREQ.VNDR_CMPL_YN           %TYPE           -- 완료 1, 미완료 0
,   p_VNDR_CMPL_DT              TQHA_SAFE_PERREQ.VNDR_CMPL_DT           %TYPE           -- 업체작업완료일자
,   p_VNDR_CMPL_TM              TQHA_SAFE_PERREQ.VNDR_CMPL_TM           %TYPE           -- 업체작업완료시간
,   p_SAFT_CMPL_CNFR            TQHA_SAFE_PERREQ.SAFT_CMPL_CNFR         %TYPE           -- 안전작업완료확인자
,   p_SAFT_CMPL_YN              TQHA_SAFE_PERREQ.SAFT_CMPL_YN           %TYPE           -- 안전작업완료여부
,   p_SAFT_CMPL_DT              TQHA_SAFE_PERREQ.SAFT_CMPL_DT           %TYPE           -- 안전작업완료일자
,   p_SAFT_CMPL_TM              TQHA_SAFE_PERREQ.SAFT_CMPL_TM           %TYPE           -- 안전작업완료시간
,   p_RTN_REQ_SEQ               OUT VARCHAR2                                            -- 리턴변수(요청순번)
)
IS
    /**************************************************************************************************************************
      Purpose :

      REVISIONS
      Ver      Date               Author                  Description
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2022/01/03 10:15:56                         최초생성

    **************************************************************************************************************************/


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR2(200);            -- ERROR Message
    USER_EXCEPTION EXCEPTION;

    v_REQ_SEQ               TQHA_SAFE_PERREQ.REQ_SEQ%TYPE;      -- 요청순번 변수 선언
    v_cnt                   INTEGER;                            -- 안전대책 데이타가  존재 여부
    v_SITE_APRV_STATS        VARCHAR2(10) := '0';               -- 허가요청 현장소장 승인 여부 체크
    v_SAFT_CMPL_YN          VARCHAR2(10) := '0';                -- 작업 종료 안전 관리자 승인 여부 체크
    v_VNDR_APRV_YN          VARCHAR2(10) := '0';                -- 업체 승인요청 여부 체크
    v_VNDR_CMPL_YN          VARCHAR2(10) := '0';                -- 업체 작업종료요청 여부 체크

BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 필수입력 필드  Check  ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_SIT_CD IS NULL)  THEN
        ERR_MSG := '현장코드는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_REQ_SEQ IS NULL AND p_WRK_TP <> 'I')  THEN
        ERR_MSG := '요청순번는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Process 선행조건 Check ]
    ---------------------------------------------------------------------------------------------------------------------------
    --  대상작업 데이타가 존재 여부 확인
    IF p_WRK_TP = 'D' THEN

        SELECT nvl(COUNT(REQ_SEQ),0)
          INTO v_cnt
          FROM TQHA_SAFE_PERREQ_OBJ
         WHERE SIT_CD       = p_SIT_CD      -- 현장코드
           AND REQ_SEQ      = p_REQ_SEQ     -- 요청순번
        ;

         -- 대상작업 데이타가 존재 여부 확인
        IF v_cnt > 0 THEN
            ERR_MSG := '요청일자  "' || p_VNDR_REQ_DT || '" 에는 하위 안전대상작업이 존재합니다. 안전 대상작업을 삭제해야 삭제할 수 있습니다. ';
            RAISE USER_EXCEPTION;
        END IF;

    END IF;

    IF p_WRK_TP <> 'I' THEN
        -- 허가 요청 승인 및 작업 종료 승인 여부 체크(보안 강화 2022/04/28)
        --BEGIN

            SELECT NVL(VNDR_APRV_YN,0)
                 , NVL(VNDR_CMPL_YN,0)
              INTO v_VNDR_APRV_YN               -- 헙체 승인요청 여부
                 , v_VNDR_CMPL_YN               -- 업체 작업종료 여부
              FROM TQHA_SAFE_PERREQ
             WHERE SIT_CD       = p_SIT_CD      -- 현장코드
               AND REQ_SEQ      = p_REQ_SEQ     -- 요청순번
            ;

        --EXCEPTION WHEN No_Data_Found THEN
        --    v_VNDR_APRV_YN := 0 ;
        --    v_VNDR_CMPL_YN := 0 ;
        --END;

       --------------------------------------------------------------------------------
       -- 2026.01.30 주석 S
        --     IF ( v_VNDR_APRV_YN = '1' AND  v_VNDR_CMPL_YN = '0' ) THEN    -- 협력업체 허가승인요청 상태확인
        -- 
        -- --       SELECT SITE_APRV_STATS
        -- --         INTO v_SITE_APRV_STATS
        -- --          FROM TQHA_SAFE_PERREQ
        -- --         WHERE SIT_CD = p_SIT_CD         --현장코드
        -- --           AND REQ_SEQ = p_REQ_SEQ ;         --요청순번
        -- 
        --         -- 1차 관리자 승인된 경우 제출 및 취소 불가
        -- --        IF v_SITE_APRV_STATS = '1' THEN
        -- --           ERR_MSG := '해당 허가작업요청(은) 현장소장(이) 승인한 상태여서 승인요청 및 승인취소가 불가합니다. ';
        --            ERR_MSG := '해당 허가작업 승인요청을 한 상태이므로 데이터 수정이 불가합니다. ';
        --            RAISE USER_EXCEPTION;
        -- --        END IF;
        -- 2026.01.30 주석 E
        --------------------------------------------------------------------------------
        -- ELS
        IF ( v_VNDR_APRV_YN = '1' AND  v_VNDR_CMPL_YN = '1' ) THEN    -- 협력업체 작업종료요청  상태확인

            --       SELECT SAFT_CMPL_YN
            --         INTO v_SAFT_CMPL_YN
            --          FROM TQHA_SAFE_PERREQ
            --         WHERE SIT_CD = p_SIT_CD         --현장코드
            --           AND REQ_SEQ = p_REQ_SEQ ;         --요청순번

                    -- 작업 죨료 안전 관리자 승인된 경우 제출 및 취소 불가
            --        IF v_SAFT_CMPL_YN = '1' THEN
            --           ERR_MSG := '해당 작업완료요청(은) 안전 관리자가 승인한 상태여서 작업완료요청 및 작업완료취소가 불가합니다. ';
            ERR_MSG := '해당 작업완료 승인요청을 한 상태이므로 데이터 수정이 불가합니다. ';
            RAISE USER_EXCEPTION;

            --       END IF;

        END IF;

    END IF;
    ----------------------------------------------------------------------------

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Business Process ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_WRK_TP ='D') THEN

        DELETE
          FROM TQHA_SAFE_PERREQ
         WHERE SIT_CD       = p_SIT_CD         -- 현장코드
           AND REQ_SEQ      = p_REQ_SEQ        -- 요청순번
        ;

        v_REQ_SEQ := p_REQ_SEQ;

    ELSIF (p_WRK_TP ='U') THEN

        UPDATE TQHA_SAFE_PERREQ
           SET CUST_CD              = p_CUST_CD                 -- 협력업체코드
             , VNDR_SEQ             = p_VNDR_SEQ                -- 업체순번
             , VNDR_REQ_DT          = p_VNDR_REQ_DT             -- 업체요청일자
             , VNDR_STR_DT          = p_VNDR_STR_DT             -- 업체시작일자
             , VNDR_STR_TM          = p_VNDR_STR_TM             -- 업체시작시간
             , VNDR_END_TM          = p_VNDR_END_TM             -- 업체종료시간
             , VNDR_REQ_PSN         = p_VNDR_REQ_PSN            -- 업체요청자
             , WRK_CHR_PSN          = p_WRK_CHR_PSN             -- 작업담당자
             , ADD_RISK_CMP         = p_ADD_RISK_CMP            -- 추가위험요소
             , SAFT_CPLN            = p_SAFT_CPLN               -- 안전대책
             , VNDR_APRV_YN         = p_VNDR_APRV_YN            -- 승인요청 1 미요청 0
             , VNDR_APRV_DT         = p_VNDR_APRV_DT            -- 업체승인요청일자
             , MNG_SUPR             = p_MNG_SUPR                -- 관리감독자
             , MNG_APRV_DT          = p_MNG_APRV_DT             -- 관리승인일자
             , MNG_APRV_STATS       = p_MNG_APRV_STATS          -- 승인 1, 반려 2
             , SAFT_MGR             = p_SAFT_MGR                -- 안전관리자
             , SAFT_APRV_DT         = p_SAFT_APRV_DT            -- 안전승인일자
             , SAFT_APRV_STATS      = p_SAFT_APRV_STATS         -- 승인 1, 반려 2
             , SITE_OMGR            = p_SITE_OMGR               -- 현장소장
             , SITE_APRV_DT         = p_SITE_APRV_DT            -- 소장승인일자
             , SITE_APRV_STATS      = p_SITE_APRV_STATS         -- 승인 1, 반려 2
             , SITE_APRV_TM         = p_SITE_APRV_TM            -- 현장승인시간
             , SAFT_MA_CNF          = p_SAFT_MA_CNF             -- 안전조치확인
             , PER_NO               = p_PER_NO                  -- 허가번호
             , APRV_PSN             = p_APRV_PSN                -- 결재자
             , APRV_NO              = p_APRV_NO                 -- 결재번호
             , VNDR_CMPL_YN         = p_VNDR_CMPL_YN            -- 완료 1, 미완료 0
             , VNDR_CMPL_DT         = p_VNDR_CMPL_DT            -- 업체작업완료일자
             , VNDR_CMPL_TM         = p_VNDR_CMPL_TM            -- 업체작업완료시간
             , SAFT_CMPL_CNFR       = p_SAFT_CMPL_CNFR          -- 안전작업완료확인자
             , SAFT_CMPL_YN         = p_SAFT_CMPL_YN            -- 안전작업완료여부
             , SAFT_CMPL_DT         = p_SAFT_CMPL_DT            -- 안전작업완료일자
             , SAFT_CMPL_TM         = p_SAFT_CMPL_TM            -- 안전작업완료시간
             , UPD_ID               = p_WRK_ID                  -- 수정ID
             , UPD_DTM              = SYSDATE()                 -- 수정일시
             , UPD_IP               = p_WRK_IP                  -- 수정IP
         WHERE SIT_CD               = p_SIT_CD                  -- 현장코드
           AND REQ_SEQ              = p_REQ_SEQ                 -- 요청순번
        ;

        v_REQ_SEQ := p_REQ_SEQ;

    ELSE

        -- 요청순번 생성
        SELECT NVL( (MAX(REQ_SEQ)+1),'1' )
          INTO v_REQ_SEQ
          FROM TQHA_SAFE_PERREQ
         WHERE SIT_CD = p_SIT_CD         --현장코드
        ;

        INSERT 
          INTO TQHA_SAFE_PERREQ
             ( SIT_CD                       -- 현장코드
             , REQ_SEQ                      -- 요청순번
             , CUST_CD                      -- 협력업체코드
             , VNDR_SEQ                     -- 업체순번
             , VNDR_REQ_DT                  -- 업체요청일자
             , VNDR_STR_DT                  -- 업체시작일자
             , VNDR_STR_TM                  -- 업체시작시간
             , VNDR_END_TM                  -- 업체종료시간
             , VNDR_REQ_PSN                 -- 업체요청자
             , WRK_CHR_PSN                  -- 작업담당자
             , ADD_RISK_CMP                 -- 추가위험요소
             , SAFT_CPLN                    -- 안전대책
             , VNDR_APRV_YN                 -- 승인요청 1 미요청 0
             , VNDR_APRV_DT                 -- 업체승인요청일자
             , MNG_SUPR                     -- 관리감독자
             , MNG_APRV_DT                  -- 관리승인일자
             , MNG_APRV_STATS               -- 승인 1, 반려 2
             , SAFT_MGR                     -- 안전관리자
             , SAFT_APRV_DT                 -- 안전승인일자
             , SAFT_APRV_STATS              -- 승인 1, 반려 2
             , SITE_OMGR                    -- 현장소장
             , SITE_APRV_DT                 -- 소장승인일자
             , SITE_APRV_STATS              -- 승인 1, 반려 2
             , SITE_APRV_TM                 -- 현장승인시간
             , SAFT_MA_CNF                  -- 안전조치확인
             , PER_NO                       -- 허가번호
             , APRV_PSN                     -- 결재자
             , APRV_NO                      -- 결재번호
             , VNDR_CMPL_YN                 -- 완료 1, 미완료 0
             , VNDR_CMPL_DT                 -- 업체작업완료일자
             , VNDR_CMPL_TM                 -- 업체작업완료시간
             , SAFT_CMPL_CNFR               -- 안전작업완료확인자
             , SAFT_CMPL_YN                 -- 안전작업완료여부
             , SAFT_CMPL_DT                 -- 안전작업완료일자
             , SAFT_CMPL_TM                 -- 안전작업완료시간
             , IPT_ID                       -- 입력ID
             , IPT_DTM                      -- 입력일시
             , IPT_IP                       -- 입력IP
             , UPD_ID                       -- 수정ID
             , UPD_DTM                      -- 수정일시
             , UPD_IP                       -- 수정IP
             )
        VALUES 
             ( p_SIT_CD                     -- 현장코드
             , v_REQ_SEQ                    -- 요청순번
             , p_CUST_CD                    -- 협력업체코드
             , p_VNDR_SEQ                   -- 업체순번
             , p_VNDR_REQ_DT                -- 업체요청일자
             , p_VNDR_STR_DT                -- 업체시작일자
             , p_VNDR_STR_TM                -- 업체시작시간
             , p_VNDR_END_TM                -- 업체종료시간
             , p_VNDR_REQ_PSN               -- 업체요청자
             , p_WRK_CHR_PSN                -- 작업담당자
             , p_ADD_RISK_CMP               -- 추가위험요소
             , p_SAFT_CPLN                  -- 안전대책
             , p_VNDR_APRV_YN               -- 승인요청 1 미요청 0
             , p_VNDR_APRV_DT               -- 업체승인요청일자
             , p_MNG_SUPR                   -- 관리감독자
             , p_MNG_APRV_DT                -- 관리승인일자
             , p_MNG_APRV_STATS             -- 승인 1, 반려 2
             , p_SAFT_MGR                   -- 안전관리자
             , p_SAFT_APRV_DT               -- 안전승인일자
             , p_SAFT_APRV_STATS            -- 승인 1, 반려 2
             , p_SITE_OMGR                  -- 현장소장
             , p_SITE_APRV_DT               -- 소장승인일자
             , p_SITE_APRV_STATS            -- 승인 1, 반려 2
             , p_SITE_APRV_TM               -- 현장승인시간
             , p_SAFT_MA_CNF                -- 안전조치확인
             , p_PER_NO                     -- 허가번호
             , p_APRV_PSN                   -- 결재자
             , p_APRV_NO                    -- 결재번호
             , p_VNDR_CMPL_YN               -- 완료 1, 미완료 0
             , p_VNDR_CMPL_DT               -- 업체작업완료일자
             , p_VNDR_CMPL_TM               -- 업체작업완료시간
             , p_SAFT_CMPL_CNFR             -- 안전작업완료확인자
             , p_SAFT_CMPL_YN               -- 안전작업완료여부
             , p_SAFT_CMPL_DT               -- 안전작업완료일자
             , p_SAFT_CMPL_TM               -- 안전작업완료시간
             , p_WRK_ID                     -- 입력ID
             , SYSDATE()                    -- 입력일시
             , p_WRK_IP                     -- 입력IP
             , p_WRK_ID                     -- 수정ID
             , SYSDATE()                    -- 수정일시
             , p_WRK_IP                     -- 수정IP
             )
        ;

    END IF;

       p_RTN_REQ_SEQ := v_REQ_SEQ;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 5. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);

END ;
/

-- PQHA_SAFE_WORK_REQ2_Q (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_SAFE_WORK_REQ2_Q" (
    p_WRK_TP            IN VARCHAR2 DEFAULT 'Q'         -- FLAG
,   p_SIT_CD            IN VARCHAR2                     -- 현장코드
,   p_VNDR_APRV_YN      IN VARCHAR2                     -- 업체승인여부
,   p_SITE_APRV_YN      IN VARCHAR2                     -- 현장승인여부
,   p_VNDR_CMPL_YN      IN VARCHAR2                     -- 업체완료여부
,   p_SAFT_CMPL_YN      IN VARCHAR2                     -- 안전완료여부
,   p_REQ_SEQ           IN VARCHAR2                     -- 요청순번
,   p_CUST_CD           IN VARCHAR2                     -- 업체코드
,   p_VNDR_SEQ          IN NUMBER                       -- 업체순번
,   p_PER_CD            IN VARCHAR2                     -- 허가코드
,   RTN_CURSOR          OUT SYS_REFCURSOR
)
IS
    /**************************************************************************************************************************
      Purpose : [안전작업허가승인  ] PROCEDRE 

      REVISIONS
      Ver      Date               Author                  Description
      -------  -----------------  ----------------------  ---------------------------------------------------------------------
      1.0      2026/02/09                                 최초생성

    **************************************************************************************************************************/

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE  NUMBER :=-20009; -- ERROR 코드
    ERR_MSG   VARCHAR(200);    -- ERROR Message
    USER_EXCEPTION EXCEPTION;

BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 수행전 Check Logic ]
    ---------------------------------------------------------------------------------------------------------------------------

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Logic 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------

    ---------------------------------------------------------------------------------------
    -- 
    IF p_WRK_TP = 'Q1' THEN

        -- 그리드 조회 : 안전작업허가요청목록
        OPEN RTN_CURSOR FOR
        SELECT CASE WHEN NVL(A.VNDR_APRV_YN, 0) = 0 AND NVL(A.SITE_APRV_STATS, 0) = 0 AND NVL(A.VNDR_CMPL_YN, 0) = 0 AND NVL(A.SAFT_CMPL_YN, 0) = 0 THEN '작성중'
                    WHEN NVL(A.VNDR_APRV_YN, 0) = 0 AND NVL(A.SITE_APRV_STATS, 0) = 2 AND NVL(A.VNDR_CMPL_YN, 0) = 0 AND NVL(A.SAFT_CMPL_YN, 0) = 0 THEN '작성중'
                    WHEN NVL(A.VNDR_APRV_YN, 0) = 1 AND NVL(A.SITE_APRV_STATS, 0) = 0 AND NVL(A.VNDR_CMPL_YN, 0) = 0 AND NVL(A.SAFT_CMPL_YN, 0) = 0 THEN '요청승인대기'
                    WHEN NVL(A.VNDR_APRV_YN, 0) = 1 AND NVL(A.SITE_APRV_STATS, 0) = 1 AND NVL(A.VNDR_CMPL_YN, 0) = 0 AND NVL(A.SAFT_CMPL_YN, 0) = 0 THEN '요청승인'
                    WHEN NVL(A.VNDR_APRV_YN, 0) = 1 AND NVL(A.SITE_APRV_STATS, 0) = 1 AND NVL(A.VNDR_CMPL_YN, 0) = 1 AND NVL(A.SAFT_CMPL_YN, 0) = 0 THEN '작업완료대기'
                    WHEN NVL(A.VNDR_APRV_YN, 0) = 1 AND NVL(A.SITE_APRV_STATS, 0) = 1 AND NVL(A.VNDR_CMPL_YN, 0) = 0 AND NVL(A.SAFT_CMPL_YN, 0) = 2 THEN '작업완료대기'
                    WHEN NVL(A.VNDR_APRV_YN, 0) = 1 AND NVL(A.SITE_APRV_STATS, 0) = 1 AND NVL(A.VNDR_CMPL_YN, 0) = 1 AND NVL(A.SAFT_CMPL_YN, 0) = 1 THEN '작업완료'
               END AS APRV_CMPL_YN               -- 승인진행현황(안전작업허가요청, 작업완료요청)
             , A.SIT_CD                         -- 현장코드
             , A.REQ_SEQ                         -- 요청순번
             , A.CUST_CD                         -- 협력업체코드
             , DECODE(NVL(A.CUST_CD, ''), A.SIT_CD, G.CNST_NM, B.CUST_NM) AS VNDR_NM    -- 협력업체명
             , A.VNDR_SEQ                        -- 협력업체순번
             , A.VNDR_REQ_DT                     -- 업체요청일자
             , A.VNDR_STR_DT                     -- 업체시작일자
             , A.VNDR_STR_TM                     -- 업체시작시간
             , A.VNDR_END_TM                     -- 업체종료시간
             , A.VNDR_REQ_PSN                    -- 업체요청자
             , A.WRK_CHR_PSN                     -- 업체작업담당자
             , A.ADD_RISK_CMP                    -- 추가위험요소
             , A.SAFT_CPLN                       -- 안전대책
             , A.VNDR_APRV_YN                    -- 업체승인요청여부 승인요청 1 미요청 0
             , DECODE(NVL(A.VNDR_APRV_YN, '0'), '1', '승인요청', '작성중') AS VNDR_APRV_STATS
             , A.VNDR_APRV_DT                    -- 업체승인일자
             , A.MNG_SUPR                        -- 관리감독자ID
             , C.USR_NM AS MNG_SUPR_NM           -- 관리감독자명
             , A.MNG_APRV_DT                     -- 관리승인일자
             , A.MNG_APRV_STATS                  -- 관리자승인상태
             , DECODE(NVL(A.VNDR_APRV_YN, '0'), '1', DECODE(NVL(A.MNG_APRV_STATS, '0'), '1', '승인완료', '2', '반려', '진행중'), DECODE(NVL(A.MNG_APRV_STATS, '0'), '1', '승인완료', '2', '반려', '')) AS MNG_APRV_STATS_NM
             , A.SAFT_MGR                        -- 안전관리자ID
             , D.USR_NM AS SAFT_MGR_NM           -- 안전관리자명
             , A.SAFT_APRV_DT                    -- 안전승인일자
             , A.SAFT_APRV_STATS                 -- 안전승인상태
             , DECODE(NVL(A.MNG_APRV_STATS, '0'), '1', DECODE(NVL(A.SAFT_APRV_STATS, '0'), '1', '승인완료', '2', '반려', '진행중'), DECODE(NVL(A.SAFT_APRV_STATS, '0'), '1', '승인완료', '2', '반려', '')) AS SAFT_APRV_STATS_NM
             , A.SITE_OMGR                       -- 현장소장ID
             , E.USR_NM AS SITE_OMGR_NM          -- 현장소장명
             , A.SITE_APRV_DT                    -- 현장승인일자
             , A.SITE_APRV_TM                    -- 현장승인시간
             , A.SITE_APRV_STATS                 -- 현장승인상태
             , DECODE(NVL(A.SAFT_APRV_STATS, '0'), '1', DECODE(NVL(A.SITE_APRV_STATS, '0'), '1', '승인완료', '2', '반려', '진행중'), DECODE(NVL(A.SITE_APRV_STATS, '0'), '1', '승인완료', '2', '반려', '')) AS SITE_APRV_STATS_NM
             , A.SAFT_MA_CNF                     -- 안전조치확인
             , A.PER_NO                          -- 허가번호
             , A.APRV_PSN                        -- 결재자
             , A.APRV_NO                         -- 결재번호
             , A.VNDR_CMPL_YN                    -- 업체작성완료여부
             , DECODE(NVL(A.VNDR_CMPL_YN, '0'), '1', '승인요청', DECODE(NVL(A.SAFT_APRV_STATS, '0'), '1', '작성중', '')) AS VNDR_CMPL_YN_NM
             , A.VNDR_CMPL_DT                    -- 업체작업완료일자
             , A.VNDR_CMPL_TM                    -- 업체작업완료시간
             , A.SAFT_CMPL_CNFR                  -- 현장작업완료확인자ID
             , F.USR_NM AS SAFT_CMPL_CNFR_NM     -- 현장작업완료확인자명
             , A.SAFT_CMPL_YN                    -- 현장작업완료승인여부
             , DECODE(NVL(A.SAFT_APRV_STATS, '0'), '1', DECODE(NVL(A.VNDR_CMPL_YN, '0'), '1', DECODE(NVL(A.SAFT_CMPL_YN, '0'), '1', '승인완료', '2', '반려', '진행중'), DECODE(NVL(A.SAFT_CMPL_YN, '0'), '1', '승인완료', '2', '반려', '')), '') AS SAFT_CMPL_YN_NM
             , A.SAFT_CMPL_DT                    -- 현장작업완료승인일자
             , A.SAFT_CMPL_TM                    -- 현장작업완료승인시간
             , (SELECT MAX(WRK_CTS) || CASE WHEN COUNT(1)  <  2 THEN ''
                                            ELSE ' 외 ' || TO_CHAR(COUNT(1)) || '건'
                                       END
                  FROM TQHA_SAFE_PERREQ_OBJ K
                 WHERE A.SIT_CD = K.SIT_CD
                   AND A.REQ_SEQ = K.REQ_SEQ
              ) AS WRK_CTS
          FROM TQHA_SAFE_PERREQ A
             , VQSZ_TRADE B
             , TCOZ_USR_INFO C
             , TCOZ_USR_INFO D
             , TCOZ_USR_INFO E
             , TCOZ_USR_INFO F
             , VQSZ_SITEINFO G
         WHERE A.SIT_CD             = p_SIT_CD
           AND A.CUST_CD            = B.CUST_CD (+)
           AND A.MNG_SUPR           = C.USR_ID (+)
           AND A.SAFT_MGR           = D.USR_ID (+)
           AND A.SITE_OMGR          = E.USR_ID (+)
           AND A.SAFT_CMPL_CNFR     = F.USR_ID (+)
           AND A.SIT_CD             = G.SIT_CD (+)
           AND (NVL(p_VNDR_APRV_YN, '*') = '*' OR NVL(A.VNDR_APRV_YN, 0) = p_VNDR_APRV_YN)
           AND (NVL(p_SITE_APRV_YN, '*') = '*' OR DECODE(NVL(A.SITE_APRV_STATS, 0), '0', '0', '2', '0', '1') = p_SITE_APRV_YN)
           AND (NVL(p_VNDR_CMPL_YN, '*') = '*' OR NVL(A.VNDR_CMPL_YN, 0) = p_VNDR_CMPL_YN)
           AND (NVL(p_SAFT_CMPL_YN, '*') = '*' OR DECODE(NVL(A.SAFT_CMPL_YN, 0), '0', '0', '2', '0', '1') = p_SAFT_CMPL_YN)
         ORDER BY VNDR_REQ_DT DESC
        ;

    ---------------------------------------------------------------------------------------
    ELSIF p_WRK_TP = 'Q2' THEN

        -- 폼 조회 : 안전작업허가요청등록
        OPEN RTN_CURSOR FOR
        SELECT A.SIT_CD                         -- 현장코드
             , A.REQ_SEQ                         -- 요청순번
             , A.CUST_CD                         -- 협력업체코드
             , DECODE(NVL(A.CUST_CD, ''), A.SIT_CD, ( SELECT CNST_NM FROM VQSZ_SITEINFO WHERE SIT_CD = A.SIT_CD ), ( SELECT CUST_NM FROM VQSZ_TRADE WHERE CUST_CD = A.CUST_CD )) AS VNDR_NM -- 협력업체명
             , A.VNDR_SEQ                        -- 협력업체순번
             , A.VNDR_REQ_DT                     -- 업체요청일자
             , A.VNDR_STR_DT                     -- 업체시작일자
             , A.VNDR_STR_TM                     -- 업체시작시간
             , A.VNDR_END_TM                     -- 업체종료시간
             , A.VNDR_REQ_PSN                    -- 업체요청자
             , A.WRK_CHR_PSN                     -- 업체작업담당자
             , A.ADD_RISK_CMP                    -- 추가위험요소
             , A.SAFT_CPLN                       -- 안전대책
             , A.VNDR_APRV_YN                    -- 업체승인요청여부 승인요청 1 미요청 0
             , DECODE(NVL(A.VNDR_APRV_YN, '0'), '1', '승인요청', '작성중') AS VNDR_APRV_STATS
             , A.VNDR_APRV_DT                    -- 업체승인일자
             , A.MNG_SUPR                        -- 관리감독자ID
             , ( SELECT USR_NM FROM TCOZ_USR_INFO WHERE USR_ID = A.MNG_SUPR ) AS MNG_SUPR_NM -- 관리감독자명
             , A.MNG_APRV_DT                     -- 관리승인일자
             , A.MNG_APRV_STATS                  -- 관리자승인상태
             , DECODE(NVL(A.VNDR_APRV_YN, '0'), '1', DECODE(NVL(A.MNG_APRV_STATS, '0'), '1', '승인완료', '2', '반려', '진행중'), DECODE(NVL(A.MNG_APRV_STATS, '0'), '1', '승인완료', '2', '반려', '')) AS MNG_APRV_STATS_NM
             , A.SAFT_MGR                        -- 안전관리자ID
             , ( SELECT USR_NM FROM TCOZ_USR_INFO WHERE USR_ID = A.SAFT_MGR ) AS SAFT_MGR_NM -- 안전관리자명
             , A.SAFT_APRV_DT                    -- 안전승인일자
             , A.SAFT_APRV_STATS                 -- 안전승인상태
             , DECODE(NVL(A.MNG_APRV_STATS, '0'), '1', DECODE(NVL(A.SAFT_APRV_STATS, '0'), '1', '승인완료', '2', '반려', '진행중'), DECODE(NVL(A.SAFT_APRV_STATS, '0'), '1', '승인완료', '2', '반려', '')) AS SAFT_APRV_STATS_NM
             , A.SITE_OMGR                       -- 현장소장
             , ( SELECT USR_NM FROM TCOZ_USR_INFO WHERE USR_ID = A.SITE_OMGR ) AS SITE_OMGR_NM -- 현장소장명
             , A.SITE_APRV_DT                    -- 현장승인일자
             , A.SITE_APRV_TM                    -- 현장승인시간
             , A.SITE_APRV_STATS                 -- 현장승인상태
             , DECODE(NVL(A.SAFT_APRV_STATS, '0'), '1', DECODE(NVL(A.SITE_APRV_STATS, '0'), '1', '승인완료', '2', '반려', '진행중'), DECODE(NVL(A.SITE_APRV_STATS, '0'), '1', '승인완료', '2', '반려', '')) AS SITE_APRV_STATS_NM
             , A.SAFT_MA_CNF                     -- 안전조치확인
             , A.PER_NO                          -- 허가번호
             , A.APRV_PSN                        -- 결재자
             , A.APRV_NO                         -- 결재번호
             , A.VNDR_CMPL_YN                    -- 업체작성완료여부
             , DECODE(NVL(A.VNDR_CMPL_YN, '0'), '1', '승인요청', DECODE(NVL(A.SAFT_APRV_STATS, '0'), '1', '작성중', '')) AS VNDR_CMPL_YN_NM
             , A.VNDR_CMPL_DT                    -- 업체작업완료일자
             , A.VNDR_CMPL_TM                    -- 업체작업완료시간
             , A.SAFT_CMPL_CNFR                  -- 안전작업완료확인자ID
             , ( SELECT USR_NM FROM TCOZ_USR_INFO WHERE USR_ID = A.SAFT_CMPL_CNFR ) AS SAFT_CMPL_CNFR_NM -- 안전작업완료확인자명
             , A.SAFT_CMPL_DT                    -- 안전작업완료승인일자
             , A.SAFT_CMPL_TM                    -- 안전작업완료승인시간
             , A.SAFT_CMPL_YN                    -- 안전작업완료승인여부
             , DECODE(NVL(A.SAFT_APRV_STATS, '0'), '1', DECODE(NVL(A.VNDR_CMPL_YN, '0'), '1', DECODE(NVL(A.SAFT_CMPL_YN, '0'), '1', '승인완료', '2', '반려', '진행중'), DECODE(NVL(A.SAFT_CMPL_YN, '0'), '1', '승인완료', '2', '반려', '')), '') AS SAFT_CMPL_YN_NM
             , '▶ 상태 : ' ||
               CASE WHEN SAFT_CMPL_YN = '1' THEN '안전관리자 작업완료 승인'
                    ELSE CASE WHEN VNDR_CMPL_YN = '1' THEN '작업완료 요청' 
                              ELSE CASE WHEN SITE_APRV_STATS IN ('1', '2') THEN
                                             CASE WHEN SITE_APRV_STATS = '1' THEN '현장소장 작업요청 승인'
                                                  ELSE '현장소장 작업요청 반려'
                                             END
                                        ELSE CASE WHEN SAFT_APRV_STATS IN ('1', '2') THEN
                                                       CASE WHEN SAFT_APRV_STATS = '1' THEN '안전관리자 작업요청 승인'
                                                            ELSE '안전관리자 작업요청 반려'
                                                       END
                                                  ELSE CASE WHEN MNG_APRV_STATS IN ('1', '2') THEN
                                                                 CASE WHEN MNG_APRV_STATS = '1' THEN '관리감독자 작업요청 승인'
                                                                      ELSE '관리감독자 작업요청 반려'
                                                                 END
                                                            ELSE CASE WHEN VNDR_APRV_YN = '1' THEN '작업승인 요청중'
                                                                      ELSE '-'
                                                                 END
                                                       END
                                             END
                                   END
                         END
               END                      AS STATS_NM
          FROM TQHA_SAFE_PERREQ A
         WHERE A.SIT_CD     = p_SIT_CD
           AND A.REQ_SEQ    = p_REQ_SEQ
           -- AND A.CUST_CD = p_CUST_CD 
           AND (NVL(p_VNDR_SEQ, -1) = -1 OR A.VNDR_SEQ = p_VNDR_SEQ)
        ;

    ---------------------------------------------------------------------------------------
    ELSIF p_WRK_TP = 'Q3' THEN

        -- 그리드 조회 : 안전작업 대상작업
        OPEN RTN_CURSOR FOR
        SELECT A.SIT_CD              -- 현장코드
             , A.REQ_SEQ              -- 요청순번
             , A.PER_CD               -- 허가코드
             , B.PER_NM               -- 허가명칭
             , A.WRK_PLC              -- 작업장소
             , A.IPT_PSNNO            -- 투입인원
             , A.WRK_CTS              -- 작업내용
          FROM TQHA_SAFE_PERREQ_OBJ A
             , TQHA_SAFE_PERM_CD B
         WHERE A.SIT_CD     = p_SIT_CD
           AND A.REQ_SEQ    = p_REQ_SEQ
           AND A.PER_CD     = B.PER_CD
        ;

    ---------------------------------------------------------------------------------------
    ELSIF p_WRK_TP = 'Q4' THEN

        -- 그리드 조회 : 대상작업별 안전대책
        OPEN RTN_CURSOR FOR
        SELECT A.SIT_CD              -- 현장코드
             , A.REQ_SEQ              -- 요청순번
             , A.PER_CD               -- 허가코드
             , A.CPLN_CD              -- 대책코드
             , B.CPLN_NM              -- 대책명칭
          FROM TQHA_SAFE_PERREQ_OBJLST A
             , TQHA_SAFE_PERM_CPLN B
         WHERE A.SIT_CD     = p_SIT_CD
           AND A.REQ_SEQ    = p_REQ_SEQ
           AND A.PER_CD     = p_PER_CD
           AND A.PER_CD     = B.PER_CD
           AND A.CPLN_CD    = B.CPLN_CD
        ;

    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
         WHEN OTHERS THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);

END PQHA_SAFE_WORK_REQ2_Q;
/

-- PQHA_SAFE_WORK_REQ3_Q (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_SAFE_WORK_REQ3_Q" (
    p_WRK_TP            IN VARCHAR2 DEFAULT 'Q'         -- FLAG
,   p_SIT_CD            IN VARCHAR2                     -- 현장코드
,   p_VNDR_APRV_YN      IN VARCHAR2                     -- 업체승인여부
,   p_SITE_APRV_YN      IN VARCHAR2                     -- 현장승인여부
,   p_VNDR_CMPL_YN      IN VARCHAR2                     -- 업체완료여부
,   p_SAFT_CMPL_YN      IN VARCHAR2                     -- 안전완료여부
,   p_REQ_SEQ           IN VARCHAR2                     -- 요청순번
,   p_CUST_CD           IN VARCHAR2                     -- 업체코드
,   p_PER_CD            IN VARCHAR2                     -- 허가코드
,   RTN_CURSOR          OUT SYS_REFCURSOR
)
IS
    /**************************************************************************************************************************
      Purpose : [안전작업허가요청 ] PROCEDRE 

      REVISIONS
      Ver      Date               Author                  Description
      -------  -----------------  ----------------------  ---------------------------------------------------------------------
      1.0      2026/02/09                                 최초생성

    **************************************************************************************************************************/

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE  NUMBER :=-20009; -- ERROR 코드
    ERR_MSG   VARCHAR(200);    -- ERROR Message
    USER_EXCEPTION EXCEPTION;

BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 수행전 Check Logic ]
    ---------------------------------------------------------------------------------------------------------------------------

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Logic 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------

    ---------------------------------------------------------------------------------------
    -- 
    IF p_WRK_TP = 'Q1' THEN

        -- 그리드 조회 : 안전작업허가요청목록
        OPEN RTN_CURSOR FOR
        SELECT CASE WHEN NVL(A.VNDR_APRV_YN, 0) = 0 AND NVL(A.SITE_APRV_STATS, 0) = 0 AND NVL(A.VNDR_CMPL_YN, 0) = 0 AND NVL(A.SAFT_CMPL_YN, 0) = 0 THEN '작성중'
                    WHEN NVL(A.VNDR_APRV_YN, 0) = 0 AND NVL(A.SITE_APRV_STATS, 0) = 2 AND NVL(A.VNDR_CMPL_YN, 0) = 0 AND NVL(A.SAFT_CMPL_YN, 0) = 0 THEN '작성중'
                    WHEN NVL(A.VNDR_APRV_YN, 0) = 1 AND NVL(A.SITE_APRV_STATS, 0) = 0 AND NVL(A.VNDR_CMPL_YN, 0) = 0 AND NVL(A.SAFT_CMPL_YN, 0) = 0 THEN '요청승인대기'
                    WHEN NVL(A.VNDR_APRV_YN, 0) = 1 AND NVL(A.SITE_APRV_STATS, 0) = 1 AND NVL(A.VNDR_CMPL_YN, 0) = 0 AND NVL(A.SAFT_CMPL_YN, 0) = 0 THEN '요청승인'
                    WHEN NVL(A.VNDR_APRV_YN, 0) = 1 AND NVL(A.SITE_APRV_STATS, 0) = 1 AND NVL(A.VNDR_CMPL_YN, 0) = 1 AND NVL(A.SAFT_CMPL_YN, 0) = 0 THEN '작업완료대기'
                    WHEN NVL(A.VNDR_APRV_YN, 0) = 1 AND NVL(A.SITE_APRV_STATS, 0) = 1 AND NVL(A.VNDR_CMPL_YN, 0) = 0 AND NVL(A.SAFT_CMPL_YN, 0) = 2 THEN '작업완료대기'
                    WHEN NVL(A.VNDR_APRV_YN, 0) = 1 AND NVL(A.SITE_APRV_STATS, 0) = 1 AND NVL(A.VNDR_CMPL_YN, 0) = 1 AND NVL(A.SAFT_CMPL_YN, 0) = 1 THEN '작업완료'
               END AS APRV_CMPL_YN               -- 승인진행현황(안전작업허가요청, 작업완료요청)
             , A.SIT_CD                          -- 현장코드
             , A.REQ_SEQ                         -- 요청순번
             , A.CUST_CD                         -- 협력업체코드
             , B.CNST_NM AS VNDR_NM              -- 협력업체명(당사인경우 현장명)
             , A.VNDR_SEQ                        -- 협력업체순번
             , A.VNDR_REQ_DT                     -- 업체요청일자
             , A.VNDR_STR_DT                     -- 업체시작일자
             , A.VNDR_STR_TM                     -- 업체시작시간
             , A.VNDR_END_TM                     -- 업체종료시간
             , A.VNDR_REQ_PSN                    -- 업체요청자
             , A.WRK_CHR_PSN                     -- 업체작업담당자
             , A.ADD_RISK_CMP                    -- 추가위험요소
             , A.SAFT_CPLN                       -- 안전대책
             , A.VNDR_APRV_YN                    -- 업체승인요청여부 승인요청 1 미요청 0
             , DECODE(NVL(A.VNDR_APRV_YN, '0'), '1', '승인요청', '작성중') AS VNDR_APRV_STATS
             , A.VNDR_APRV_DT                    -- 업체승인일자
             , A.MNG_SUPR                        -- 관리감독자ID
             , C.USR_NM AS MNG_SUPR_NM           -- 관리감독자명
             , A.MNG_APRV_DT                     -- 관리승인일자
             , A.MNG_APRV_STATS                  -- 관리자승인상태
             , DECODE(NVL(A.VNDR_APRV_YN, '0'), '1', DECODE(NVL(A.MNG_APRV_STATS, '0'), '1', '승인완료', '2', '반려', '진행중'), DECODE(NVL(A.MNG_APRV_STATS, '0'), '1', '승인완료', '2', '반려', '')) AS MNG_APRV_STATS_NM
             , A.SAFT_MGR                        -- 안전관리자ID
             , D.USR_NM AS SAFT_MGR_NM           -- 안전관리자명
             , A.SAFT_APRV_DT                    -- 안전승인일자
             , A.SAFT_APRV_STATS                 -- 안전승인상태
             , DECODE(NVL(A.MNG_APRV_STATS, '0'), '1', DECODE(NVL(A.SAFT_APRV_STATS, '0'), '1', '승인완료', '2', '반려', '진행중'), DECODE(NVL(A.SAFT_APRV_STATS, '0'), '1', '승인완료', '2', '반려', '')) AS SAFT_APRV_STATS_NM
             , A.SITE_OMGR                       -- 현장소장ID
             , E.USR_NM AS SITE_OMGR_NM          -- 현장소장명
             , A.SITE_APRV_DT                    -- 현장승인일자
             , A.SITE_APRV_TM                    -- 현장승인시간
             , A.SITE_APRV_STATS                 -- 현장승인상태
             , DECODE(NVL(A.SAFT_APRV_STATS, '0'), '1', DECODE(NVL(A.SITE_APRV_STATS, '0'), '1', '승인완료', '2', '반려', '진행중'), DECODE(NVL(A.SITE_APRV_STATS, '0'), '1', '승인완료', '2', '반려', '')) AS SITE_APRV_STATS_NM
             , A.SAFT_MA_CNF                     -- 안전조치확인
             , A.PER_NO                          -- 허가번호
             , A.APRV_PSN                        -- 결재자
             , A.APRV_NO                         -- 결재번호
             , A.VNDR_CMPL_YN                    -- 업체작성완료여부
             , DECODE(NVL(A.VNDR_CMPL_YN, '0'), '1', '승인요청', DECODE(NVL(A.SAFT_APRV_STATS, '0'), '1', '작성중', '')) AS VNDR_CMPL_YN_NM
             , A.VNDR_CMPL_DT                    -- 업체작업완료일자
             , A.VNDR_CMPL_TM                    -- 업체작업완료시간
             , A.SAFT_CMPL_CNFR                  -- 현장작업완료확인자ID
             , F.USR_NM AS SAFT_CMPL_CNFR_NM     -- 현장작업완료확인자명
             , A.SAFT_CMPL_YN                    -- 현장작업완료승인여부
             , DECODE(NVL(A.SAFT_APRV_STATS, '0'), '1', DECODE(NVL(A.VNDR_CMPL_YN, '0'), '1', DECODE(NVL(A.SAFT_CMPL_YN, '0'), '1', '승인완료', '2', '반려', '진행중'), DECODE(NVL(A.SAFT_CMPL_YN, '0'), '1', '승인완료', '2', '반려', '')), '') AS SAFT_CMPL_YN_NM
             , A.SAFT_CMPL_DT                    -- 현장작업완료승인일자
             , A.SAFT_CMPL_TM                    -- 현장작업완료승인시간
          FROM TQHA_SAFE_PERREQ A 
             , VQSZ_SITEINFO B
             , TCOZ_USR_INFO C
             , TCOZ_USR_INFO D
             , TCOZ_USR_INFO E
             , TCOZ_USR_INFO F
         WHERE A.SIT_CD             = p_SIT_CD
           AND A.CUST_CD            IS NULL
           AND A.SIT_CD             = B.SIT_CD (+)
           AND A.MNG_SUPR           = C.USR_ID (+)
           AND A.SAFT_MGR           = D.USR_ID (+)
           AND A.SITE_OMGR          = E.USR_ID (+)
           AND A.SAFT_CMPL_CNFR     = F.USR_ID (+)
           AND (NVL(p_VNDR_APRV_YN, '*') = '*' OR NVL(A.VNDR_APRV_YN, 0) = p_VNDR_APRV_YN)
           AND (NVL(p_SITE_APRV_YN, '*') = '*' OR DECODE(NVL(A.SITE_APRV_STATS, 0), '0', '0', '2', '0', '1') = p_SITE_APRV_YN)
           AND (NVL(p_VNDR_CMPL_YN, '*') = '*' OR NVL(A.VNDR_CMPL_YN, 0) = p_VNDR_CMPL_YN)
           AND (NVL(p_SAFT_CMPL_YN, '*') = '*' OR DECODE(NVL(A.SAFT_CMPL_YN, 0), '0', '0', '2', '0', '1') = p_SAFT_CMPL_YN)
         ORDER BY VNDR_REQ_DT DESC
        ;

    ---------------------------------------------------------------------------------------
    ELSIF p_WRK_TP = 'Q2' THEN

        -- 폼 조회 : 안전작업허가요청등록
        OPEN RTN_CURSOR FOR
        SELECT A.SIT_CD                          -- 현장코드
             , A.REQ_SEQ                         -- 요청순번
             , A.CUST_CD                         -- 협력업체코드
             , ( SELECT CNST_NM FROM VQSZ_SITEINFO WHERE SIT_CD = A.SIT_CD ) AS VNDR_NM -- 협력업체명
             , A.VNDR_SEQ                        -- 협력업체순번
             , A.VNDR_REQ_DT                     -- 업체요청일자
             , A.VNDR_STR_DT                     -- 업체시작일자
             , A.VNDR_STR_TM                     -- 업체시작시간
             , A.VNDR_END_TM                     -- 업체종료시간
             , A.VNDR_REQ_PSN                    -- 업체요청자
             , A.WRK_CHR_PSN                     -- 업체작업담당자
             , A.ADD_RISK_CMP                    -- 추가위험요소
             , A.SAFT_CPLN                       -- 안전대책
             , A.VNDR_APRV_YN                    -- 업체승인요청여부 승인요청 1 미요청 0
             , DECODE(NVL(A.VNDR_APRV_YN, '0'), '1', '승인요청', '작성중') AS VNDR_APRV_STATS
             , A.VNDR_APRV_DT                    -- 업체승인일자
             , A.MNG_SUPR                        -- 관리감독자ID
             , ( SELECT USR_NM FROM TCOZ_USR_INFO WHERE USR_ID = A.MNG_SUPR ) AS MNG_SUPR_NM -- 관리감독자명
             , A.MNG_APRV_DT                     -- 관리승인일자
             , A.MNG_APRV_STATS                  -- 관리자승인상태
             , DECODE(NVL(A.VNDR_APRV_YN, '0'), '1', DECODE(NVL(A.MNG_APRV_STATS, '0'), '1', '승인완료', '2', '반려', '진행중'), DECODE(NVL(A.MNG_APRV_STATS, '0'), '1', '승인완료', '2', '반려', '')) AS MNG_APRV_STATS_NM
             , A.SAFT_MGR                        -- 안전관리자ID
             , ( SELECT USR_NM FROM TCOZ_USR_INFO WHERE USR_ID = A.SAFT_MGR ) AS SAFT_MGR_NM -- 안전관리자명
             , A.SAFT_APRV_DT                    -- 안전승인일자
             , A.SAFT_APRV_STATS                 -- 안전승인상태
             , DECODE(NVL(A.MNG_APRV_STATS, '0'), '1', DECODE(NVL(A.SAFT_APRV_STATS, '0'), '1', '승인완료', '2', '반려', '진행중'), DECODE(NVL(A.SAFT_APRV_STATS, '0'), '1', '승인완료', '2', '반려', '')) AS SAFT_APRV_STATS_NM
             , A.SITE_OMGR                       -- 현장소장
             , ( SELECT USR_NM FROM TCOZ_USR_INFO WHERE USR_ID = A.SITE_OMGR ) AS SITE_OMGR_NM -- 현장소장명
             , A.SITE_APRV_DT                    -- 현장승인일자
             , A.SITE_APRV_TM                    -- 현장승인시간
             , A.SITE_APRV_STATS                 -- 현장승인상태
             , DECODE(NVL(A.SAFT_APRV_STATS, '0'), '1', DECODE(NVL(A.SITE_APRV_STATS, '0'), '1', '승인완료', '2', '반려', '진행중'), DECODE(NVL(A.SITE_APRV_STATS, '0'), '1', '승인완료', '2', '반려', '')) AS SITE_APRV_STATS_NM
             , A.SAFT_MA_CNF                     -- 안전조치확인
             , A.PER_NO                          -- 허가번호
             , A.APRV_PSN                        -- 결재자
             , A.APRV_NO                         -- 결재번호
             , A.VNDR_CMPL_YN                    -- 업체작성완료여부
             , DECODE(NVL(A.VNDR_CMPL_YN, '0'), '1', '승인요청', DECODE(NVL(A.SAFT_APRV_STATS, '0'), '1', '작성중', '')) AS VNDR_CMPL_YN_NM
             , A.VNDR_CMPL_DT                    -- 업체작업완료일자
             , A.VNDR_CMPL_TM                    -- 업체작업완료시간
             , A.SAFT_CMPL_CNFR                  -- 안전작업완료확인자ID
             , ( SELECT USR_NM FROM TCOZ_USR_INFO WHERE USR_ID = A.SAFT_CMPL_CNFR ) AS SAFT_CMPL_CNFR_NM -- 안전작업완료확인자명
             , A.SAFT_CMPL_DT                    -- 안전작업완료승인일자
             , A.SAFT_CMPL_TM                    -- 안전작업완료승인시간
             , A.SAFT_CMPL_YN                    -- 안전작업완료승인여부
             , DECODE(NVL(A.SAFT_APRV_STATS, '0'), '1', DECODE(NVL(A.VNDR_CMPL_YN, '0'), '1', DECODE(NVL(A.SAFT_CMPL_YN, '0'), '1', '승인완료', '2', '반려', '진행중'), DECODE(NVL(A.SAFT_CMPL_YN, '0'), '1', '승인완료', '2', '반려', '')), '') AS SAFT_CMPL_YN_NM
             , '▶ 상태 : ' ||
               CASE WHEN SAFT_CMPL_YN = '1' THEN '안전관리자 작업완료 승인'
                    ELSE CASE WHEN VNDR_CMPL_YN = '1' THEN '작업완료 요청' 
                              ELSE CASE WHEN SITE_APRV_STATS IN ('1', '2') THEN
                                             CASE WHEN SITE_APRV_STATS = '1' THEN '현장소장 작업요청 승인'
                                                  ELSE '현장소장 작업요청 반려'
                                             END
                                        ELSE CASE WHEN SAFT_APRV_STATS IN ('1', '2') THEN
                                                       CASE WHEN SAFT_APRV_STATS = '1' THEN '안전관리자 작업요청 승인'
                                                            ELSE '안전관리자 작업요청 반려'
                                                       END
                                                  ELSE CASE WHEN MNG_APRV_STATS IN ('1', '2') THEN
                                                                 CASE WHEN MNG_APRV_STATS = '1' THEN '관리감독자 작업요청 승인'
                                                                      ELSE '관리감독자 작업요청 반려'
                                                                 END
                                                            ELSE CASE WHEN VNDR_APRV_YN = '1' THEN '작업승인 요청중'
                                                                      ELSE '-'
                                                                 END
                                                       END
                                             END
                                   END
                         END
               END                      AS STATS_NM
          FROM TQHA_SAFE_PERREQ A
         WHERE A.SIT_CD     = p_SIT_CD
           AND A.REQ_SEQ    = p_REQ_SEQ
           -- AND A.CUST_CD = p_CUST_CD
        ;

    ---------------------------------------------------------------------------------------
    ELSIF p_WRK_TP = 'Q3' THEN

        -- 그리드 조회 : 안전작업 대상작업
        OPEN RTN_CURSOR FOR
        SELECT A.SIT_CD               -- 현장코드
             , A.REQ_SEQ              -- 요청순번
             , A.PER_CD               -- 허가코드
             , B.PER_NM               -- 허가명칭
             , A.WRK_PLC              -- 작업장소
             , A.IPT_PSNNO            -- 투입인원
             , A.WRK_CTS              -- 작업내용
          FROM TQHA_SAFE_PERREQ_OBJ A
             , TQHA_SAFE_PERM_CD B
         WHERE A.SIT_CD     = p_SIT_CD
           AND A.REQ_SEQ    = p_REQ_SEQ
           AND A.PER_CD     = B.PER_CD
        ;

    ---------------------------------------------------------------------------------------
    ELSIF p_WRK_TP = 'Q4' THEN

        -- 그리드 조회 : 대상작업별 안전대책
        OPEN RTN_CURSOR FOR
        SELECT A.SIT_CD              -- 현장코드
             , A.REQ_SEQ              -- 요청순번
             , A.PER_CD               -- 허가코드
             , A.CPLN_CD              -- 대책코드
             , B.CPLN_NM              -- 대책명칭
          FROM TQHA_SAFE_PERREQ_OBJLST A
             , TQHA_SAFE_PERM_CPLN B
         WHERE A.SIT_CD     = p_SIT_CD
           AND A.REQ_SEQ    = p_REQ_SEQ
           AND A.PER_CD     = p_PER_CD
           AND A.PER_CD     = B.PER_CD
           AND A.CPLN_CD    = B.CPLN_CD
        ;

    ---------------------------------------------------------------------------------------
    ELSIF p_WRK_TP = 'Q5' THEN

        -- 그리드 조회 : 안전작업허가 코드관리
        OPEN RTN_CURSOR FOR
        SELECT PER_CD -- 허가코드
             , PER_NM -- 허가신청명칭
             , USE_YN -- 허가 사용유무
          FROM TQHA_SAFE_PERM_CD
         WHERE USE_YN = '1'
        ;

    ---------------------------------------------------------------------------------------
    ELSIF p_WRK_TP = 'Q6' THEN

        -- 그리드 조회 : 작업별 안전대책
        OPEN RTN_CURSOR FOR
        SELECT PER_CD          -- 상위작업코드
             , CPLN_CD         -- 안전대책코드
             , CPLN_NM         -- 안전대책명칭
             , USE_YN          -- 안전대책사용유무
          FROM TQHA_SAFE_PERM_CPLN
         WHERE PER_CD   = p_PER_CD
           AND USE_YN   = '1'
        ;

    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
         WHEN OTHERS THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);

END PQHA_SAFE_WORK_REQ3_Q;
/

-- PQHA_SAFE_WORK_REQ_CO_Q (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_SAFE_WORK_REQ_CO_Q" (
    p_WRK_TP            IN VARCHAR2 DEFAULT 'Q'             -- FLAG(Q: 현장평가, Q1:본사평가)
,   p_SIT_CD            IN VARCHAR2                         -- 현장코드
,   p_CUST_CD           IN VARCHAR2                         -- 고객코드
,   p_VNDR_SEQ          IN VARCHAR2                         -- 업체순번
,   p_VNDR_APRV_YN      IN VARCHAR2                         -- 업체승인여부
,   p_SITE_APRV_YN      IN VARCHAR2                         -- 현장승인여부
,   p_VNDR_CMPL_YN      IN VARCHAR2                         -- 업체완료여부
,   p_SAFT_CMPL_YN      IN VARCHAR2                         -- 안전완료여부
,   p_REQ_SEQ           IN VARCHAR2                         -- 요청순번
,   p_PER_CD            IN VARCHAR2                         -- 허가코드
,   RTN_CURSOR       OUT SYS_REFCURSOR
)
IS

    /**************************************************************************************************************************
      Purpose : 안전작업허가

      REVISIONS
      Ver      Date               Author                  Description
      -------  -----------------  ----------------------  ---------------------------------------------------------------------
      1.0      2026/03/03                                 최초생성

    **************************************************************************************************************************/

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE  NUMBER :=-20009; -- ERROR 코드
    ERR_MSG   VARCHAR(200);    -- ERROR Message
    USER_EXCEPTION EXCEPTION;

BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 수행전 Check Logic ]
    ---------------------------------------------------------------------------------------------------------------------------

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Logic 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    -- 그리드 조회 : 안전작업허가요청목록
    IF p_WRK_TP = 'Q1' THEN

        OPEN RTN_CURSOR FOR
        SELECT CASE WHEN NVL(A.VNDR_APRV_YN, 0) = 0 AND NVL(A.SITE_APRV_STATS, 0) = 0 AND NVL(A.VNDR_CMPL_YN, 0) = 0 AND NVL(A.SAFT_CMPL_YN, 0) = 0 THEN '작성중'
                    WHEN NVL(A.VNDR_APRV_YN, 0) = 0 AND NVL(A.SITE_APRV_STATS, 0) = 2 AND NVL(A.VNDR_CMPL_YN, 0) = 0 AND NVL(A.SAFT_CMPL_YN, 0) = 0 THEN '작성중'
                    WHEN NVL(A.VNDR_APRV_YN, 0) = 1 AND NVL(A.SITE_APRV_STATS, 0) = 0 AND NVL(A.VNDR_CMPL_YN, 0) = 0 AND NVL(A.SAFT_CMPL_YN, 0) = 0 THEN '요청승인대기'
                    WHEN NVL(A.VNDR_APRV_YN, 0) = 1 AND NVL(A.SITE_APRV_STATS, 0) = 1 AND NVL(A.VNDR_CMPL_YN, 0) = 0 AND NVL(A.SAFT_CMPL_YN, 0) = 0 THEN '요청승인'
                    WHEN NVL(A.VNDR_APRV_YN, 0) = 1 AND NVL(A.SITE_APRV_STATS, 0) = 1 AND NVL(A.VNDR_CMPL_YN, 0) = 1 AND NVL(A.SAFT_CMPL_YN, 0) = 0 THEN '작업완료대기'
                    WHEN NVL(A.VNDR_APRV_YN, 0) = 1 AND NVL(A.SITE_APRV_STATS, 0) = 1 AND NVL(A.VNDR_CMPL_YN, 0) = 0 AND NVL(A.SAFT_CMPL_YN, 0) = 2 THEN '작업완료대기'
                    WHEN NVL(A.VNDR_APRV_YN, 0) = 1 AND NVL(A.SITE_APRV_STATS, 0) = 1 AND NVL(A.VNDR_CMPL_YN, 0) = 1 AND NVL(A.SAFT_CMPL_YN, 0) = 1 THEN '작업완료'
               END AS APRV_CMPL_YN               -- 승인진행현황(안전작업허가요청, 작업완료요청)
             , A.SIT_CD                         -- 현장코드
             , A.REQ_SEQ                         -- 요청순번
             , A.CUST_CD                         -- 협력업체코드
             , B.CUST_NM AS VNDR_NM          -- 협력업체명
             , A.VNDR_SEQ                        -- 협력업체순번
             , A.VNDR_REQ_DT                     -- 업체요청일자
             , A.VNDR_STR_DT                     -- 업체시작일자
             , A.VNDR_STR_TM                     -- 업체시작시간
             , A.VNDR_END_TM                     -- 업체종료시간
             , A.VNDR_REQ_PSN                    -- 업체요청자
             , A.WRK_CHR_PSN                     -- 업체작업담당자
             , A.ADD_RISK_CMP                    -- 추가위험요소
             , A.SAFT_CPLN                       -- 안전대책
             , A.VNDR_APRV_YN                    -- 업체승인요청여부 승인요청 1 미요청 0
             , DECODE(NVL(A.VNDR_APRV_YN, '0'), '1', '승인요청', '작성중') AS VNDR_APRV_STATS
             , A.VNDR_APRV_DT                    -- 업체승인일자
             , A.MNG_SUPR                        -- 관리감독자ID
             , C.USR_NM AS MNG_SUPR_NM           -- 관리감독자명
             , A.MNG_APRV_DT                     -- 관리승인일자
             , A.MNG_APRV_STATS                  -- 관리자승인상태
             , DECODE(NVL(A.VNDR_APRV_YN, '0'), '1', DECODE(NVL(A.MNG_APRV_STATS, '0'), '1', '승인완료', '2', '반려', '진행중'), DECODE(NVL(A.MNG_APRV_STATS, '0'), '1', '승인완료', '2', '반려', '')) AS MNG_APRV_STATS_NM
             , A.SAFT_MGR                        -- 안전관리자ID
             , D.USR_NM AS SAFT_MGR_NM           -- 안전관리자명
             , A.SAFT_APRV_DT                    -- 안전승인일자
             , A.SAFT_APRV_STATS                 -- 안전승인상태
             , DECODE(NVL(A.MNG_APRV_STATS, '0'), '1', DECODE(NVL(A.SAFT_APRV_STATS, '0'), '1', '승인완료', '2', '반려', '진행중'), DECODE(NVL(A.SAFT_APRV_STATS, '0'), '1', '승인완료', '2', '반려', '')) AS SAFT_APRV_STATS_NM
             , A.SITE_OMGR                       -- 현장소장ID
             , E.USR_NM AS SITE_OMGR_NM          -- 현장소장명
             , A.SITE_APRV_DT                    -- 현장승인일자
             , A.SITE_APRV_TM                    -- 현장승인시간
             , A.SITE_APRV_STATS                 -- 현장승인상태
             , DECODE(NVL(A.SAFT_APRV_STATS, '0'), '1', DECODE(NVL(A.SITE_APRV_STATS, '0'), '1', '승인완료', '2', '반려', '진행중'), DECODE(NVL(A.SITE_APRV_STATS, '0'), '1', '승인완료', '2', '반려', '')) AS SITE_APRV_STATS_NM
             , A.SAFT_MA_CNF                     -- 안전조치확인
             , A.PER_NO                          -- 허가번호
             , A.APRV_PSN                        -- 결재자
             , A.APRV_NO                         -- 결재번호
             , A.VNDR_CMPL_YN                    -- 업체작성완료여부
             , DECODE(NVL(A.VNDR_CMPL_YN, '0'), '1', '승인요청', DECODE(NVL(A.SAFT_APRV_STATS, '0'), '1', '작성중', '')) AS VNDR_CMPL_YN_NM
             , A.VNDR_CMPL_DT                    -- 업체작업완료일자
             , A.VNDR_CMPL_TM                    -- 업체작업완료시간
             , A.SAFT_CMPL_CNFR                  -- 현장작업완료확인자ID
             , F.USR_NM AS SAFT_CMPL_CNFR_NM     -- 현장작업완료확인자명
             , A.SAFT_CMPL_YN                    -- 현장작업완료승인여부
             , DECODE(NVL(A.SAFT_APRV_STATS, '0'), '1', DECODE(NVL(A.VNDR_CMPL_YN, '0'), '1', DECODE(NVL(A.SAFT_CMPL_YN, '0'), '1', '승인완료', '2', '반려', '진행중'), DECODE(NVL(A.SAFT_CMPL_YN, '0'), '1', '승인완료', '2', '반려', '')), '') AS SAFT_CMPL_YN_NM
             , A.SAFT_CMPL_DT                    -- 현장작업완료승인일자
             , A.SAFT_CMPL_TM                    -- 현장작업완료승인시간
          FROM TQHA_SAFE_PERREQ A 
             , VQSZ_TRADE B
             , TCOZ_USR_INFO C
             , TCOZ_USR_INFO D
             , TCOZ_USR_INFO E
             , TCOZ_USR_INFO F
         WHERE A.SIT_CD         = p_SIT_CD
           AND A.CUST_CD        = p_CUST_CD
           AND A.VNDR_SEQ       = p_VNDR_SEQ
           AND A.CUST_CD        = B.CUST_CD
           AND A.MNG_SUPR       = C.USR_ID (+)
           AND A.SAFT_MGR       = D.USR_ID (+)
           AND A.SITE_OMGR      = E.USR_ID (+)
           AND A.SAFT_CMPL_CNFR = F.USR_ID (+)
           AND (NVL(p_VNDR_APRV_YN, '*') = '*' OR NVL(A.VNDR_APRV_YN, 0) = p_VNDR_APRV_YN)
           AND (NVL(p_SITE_APRV_YN, '*') = '*' OR NVL(A.SITE_APRV_STATS, 0) = p_SITE_APRV_YN)
           AND (NVL(p_VNDR_CMPL_YN, '*') = '*' OR NVL(A.VNDR_CMPL_YN, 0) = p_VNDR_CMPL_YN)
           AND (NVL(p_SAFT_CMPL_YN, '*') = '*' OR NVL(A.SAFT_CMPL_YN, 0) = p_SAFT_CMPL_YN)
         ORDER BY VNDR_REQ_DT DESC
        ;

    --------------------------------------------------------------------------------
    -- 폼 조회 : 안전작업허가요청등록
    ELSIF p_WRK_TP = 'Q2' THEN

        OPEN RTN_CURSOR FOR
        SELECT A.SIT_CD                         -- 현장코드
             , A.REQ_SEQ                         -- 요청순번
             , A.CUST_CD                         -- 협력업체코드
             , ( SELECT CUST_NM FROM VQSZ_TRADE WHERE CUST_CD = A.CUST_CD ) AS VNDR_NM -- 협력업체명
             , A.VNDR_SEQ                        -- 협력업체순번
             , A.VNDR_REQ_DT                     -- 업체요청일자
             , A.VNDR_STR_DT                     -- 업체시작일자
             , A.VNDR_STR_TM                     -- 업체시작시간
             , A.VNDR_END_TM                     -- 업체종료시간
             , A.VNDR_REQ_PSN                    -- 업체요청자
             , A.WRK_CHR_PSN                     -- 업체작업담당자
             , A.ADD_RISK_CMP                    -- 추가위험요소
             , A.SAFT_CPLN                       -- 안전대책
             , A.VNDR_APRV_YN                    -- 업체승인요청여부 승인요청 1 미요청 0
             , DECODE(NVL(A.VNDR_APRV_YN, '0'), '1', '승인요청', '작성중') AS VNDR_APRV_STATS
             , A.VNDR_APRV_DT                    -- 업체승인일자
             , A.MNG_SUPR                        -- 관리감독자ID
             , ( SELECT USR_NM FROM TCOZ_USR_INFO WHERE USR_ID = A.MNG_SUPR ) AS MNG_SUPR_NM -- 관리감독자명
             , A.MNG_APRV_DT                     -- 관리승인일자
             , A.MNG_APRV_STATS                  -- 관리자승인상태
             , DECODE(NVL(A.VNDR_APRV_YN, '0'), '1', DECODE(NVL(A.MNG_APRV_STATS, '0'), '1', '승인완료', '2', '반려', '진행중'), DECODE(NVL(A.MNG_APRV_STATS, '0'), '1', '승인완료', '2', '반려', '')) AS MNG_APRV_STATS_NM
             , A.SAFT_MGR                        -- 안전관리자ID
             , ( SELECT USR_NM FROM TCOZ_USR_INFO WHERE USR_ID = A.SAFT_MGR ) AS SAFT_MGR_NM -- 안전관리자명
             , A.SAFT_APRV_DT                    -- 안전승인일자
             , A.SAFT_APRV_STATS                 -- 안전승인상태
             , DECODE(NVL(A.MNG_APRV_STATS, '0'), '1', DECODE(NVL(A.SAFT_APRV_STATS, '0'), '1', '승인완료', '2', '반려', '진행중'), DECODE(NVL(A.SAFT_APRV_STATS, '0'), '1', '승인완료', '2', '반려', '')) AS SAFT_APRV_STATS_NM
             , A.SITE_OMGR                       -- 현장소장
             , ( SELECT USR_NM FROM TCOZ_USR_INFO WHERE USR_ID = A.SITE_OMGR ) AS SITE_OMGR_NM -- 현장소장명
             , A.SITE_APRV_DT                    -- 현장승인일자
             , A.SITE_APRV_TM                    -- 현장승인시간
             , A.SITE_APRV_STATS                 -- 현장승인상태
             , DECODE(NVL(A.SAFT_APRV_STATS, '0'), '1', DECODE(NVL(A.SITE_APRV_STATS, '0'), '1', '승인완료', '2', '반려', '진행중'), DECODE(NVL(A.SITE_APRV_STATS, '0'), '1', '승인완료', '2', '반려', '')) AS SITE_APRV_STATS_NM
             , A.SAFT_MA_CNF                     -- 안전조치확인
             , A.PER_NO                          -- 허가번호
             , A.APRV_PSN                        -- 결재자
             , A.APRV_NO                         -- 결재번호
             , A.VNDR_CMPL_YN                    -- 업체작성완료여부
             , DECODE(NVL(A.VNDR_CMPL_YN, '0'), '1', '승인요청', DECODE(NVL(A.SAFT_APRV_STATS, '0'), '1', '작성중', '')) AS VNDR_CMPL_YN_NM
             , A.VNDR_CMPL_DT                    -- 업체작업완료일자
             , A.VNDR_CMPL_TM                    -- 업체작업완료시간
             , A.SAFT_CMPL_CNFR                  -- 안전작업완료확인자ID
             , ( SELECT USR_NM FROM TCOZ_USR_INFO WHERE USR_ID = A.SAFT_CMPL_CNFR ) AS SAFT_CMPL_CNFR_NM -- 안전작업완료확인자명
             , A.SAFT_CMPL_DT                    -- 안전작업완료승인일자
             , A.SAFT_CMPL_TM                    -- 안전작업완료승인시간
             , A.SAFT_CMPL_YN                    -- 안전작업완료승인여부
             , DECODE(NVL(A.SAFT_APRV_STATS, '0'), '1', DECODE(NVL(A.VNDR_CMPL_YN, '0'), '1', DECODE(NVL(A.SAFT_CMPL_YN, '0'), '1', '승인완료', '2', '반려', '진행중'), DECODE(NVL(A.SAFT_CMPL_YN, '0'), '1', '승인완료', '2', '반려', '')), '') AS SAFT_CMPL_YN_NM
             , '▶ 상태 : ' ||
               CASE WHEN SAFT_CMPL_YN = '1' THEN '안전관리자 작업완료 승인'
                    ELSE CASE WHEN VNDR_CMPL_YN = '1' THEN '작업완료 요청' 
                              ELSE CASE WHEN SITE_APRV_STATS IN ('1', '2') THEN
                                             CASE WHEN SITE_APRV_STATS = '1' THEN '현장소장 작업요청 승인'
                                                  ELSE '현장소장 작업요청 반려'
                                             END
                                        ELSE CASE WHEN SAFT_APRV_STATS IN ('1', '2') THEN
                                                       CASE WHEN SAFT_APRV_STATS = '1' THEN '안전관리자 작업요청 승인'
                                                            ELSE '안전관리자 작업요청 반려'
                                                       END
                                                  ELSE CASE WHEN MNG_APRV_STATS IN ('1', '2') THEN
                                                                 CASE WHEN MNG_APRV_STATS = '1' THEN '관리감독자 작업요청 승인'
                                                                      ELSE '관리감독자 작업요청 반려'
                                                                 END
                                                            ELSE CASE WHEN VNDR_APRV_YN = '1' THEN '작업승인 요청중'
                                                                      ELSE '-'
                                                                 END
                                                       END
                                             END
                                   END
                         END
               END                      AS STATS_NM
          FROM TQHA_SAFE_PERREQ A
         WHERE A.SIT_CD     = p_SIT_CD
           AND A.REQ_SEQ    = p_REQ_SEQ
           AND A.CUST_CD    = p_CUST_CD
           AND A.VNDR_SEQ   = p_VNDR_SEQ
        ;

    --------------------------------------------------------------------------------
    -- 그리드 조회 : 안전작업 대상작업
    ELSIF p_WRK_TP = 'Q3' THEN

        OPEN RTN_CURSOR FOR
        SELECT A.SIT_CD              -- 현장코드
             , A.REQ_SEQ              -- 요청순번
             , A.PER_CD               -- 허가코드
             , B.PER_NM               -- 허가명칭
             , A.WRK_PLC              -- 작업장소
             , A.IPT_PSNNO            -- 투입인원
             , A.WRK_CTS              -- 작업내용
          FROM TQHA_SAFE_PERREQ_OBJ A
             , TQHA_SAFE_PERM_CD B
         WHERE A.SIT_CD     = p_SIT_CD
           AND A.REQ_SEQ    = p_REQ_SEQ
           AND A.PER_CD     = B.PER_CD
        ;

    --------------------------------------------------------------------------------
    -- 그리드 조회 : 대상작업별 안전대책
    ELSIF p_WRK_TP = 'Q4' THEN

        OPEN RTN_CURSOR FOR
        SELECT A.SIT_CD              -- 현장코드
             , A.REQ_SEQ              -- 요청순번
             , A.PER_CD               -- 허가코드
             , A.CPLN_CD              -- 대책코드
             , B.CPLN_NM              -- 대책명칭
          FROM TQHA_SAFE_PERREQ_OBJLST A
             , TQHA_SAFE_PERM_CPLN B
         WHERE A.SIT_CD     = p_SIT_CD
           AND A.REQ_SEQ    = p_REQ_SEQ
           AND A.PER_CD     = p_PER_CD
           AND A.PER_CD     = B.PER_CD
           AND A.CPLN_CD    = B.CPLN_CD
        ;

    --------------------------------------------------------------------------------
    -- 그리드 조회 : 안전작업허가 코드관리
    ELSIF p_WRK_TP = 'Q5' THEN

        OPEN RTN_CURSOR FOR
        SELECT PER_CD -- 허가코드
             , PER_NM -- 허가신청명칭
             , USE_YN -- 허가 사용유무
          FROM TQHA_SAFE_PERM_CD
         WHERE USE_YN = '1'
        ;

    --------------------------------------------------------------------------------
    -- 그리드 조회 : 작업별 안전대책
    ELSIF p_WRK_TP = 'Q6' THEN

        OPEN RTN_CURSOR FOR
        SELECT PER_CD          -- 상위작업코드
             , CPLN_CD         -- 안전대책코드
             , CPLN_NM         -- 안전대책명칭
             , USE_YN          -- 안전대책사용유무
          FROM TQHA_SAFE_PERM_CPLN
         WHERE PER_CD   = p_PER_CD
           AND USE_YN   = '1'
        ;

    --------------------------------------------------------------------------------
    -- 안전관리자 휴대폰 번호 조회
    ELSIF p_WRK_TP = 'Q7' THEN

        OPEN RTN_CURSOR FOR
        SELECT MP_NO
            -- SYS.PKG_CRYPTO_DEC.DECRYPT(MP_NO) AS MP_NO
            FROM TCOZ_USR_INFO
        WHERE USR_ID = (
           SELECT MNG_SUPR
           FROM TQHA_SAFE_PERREQ
           WHERE SIT_CD     = p_SIT_CD
             and REQ_SEQ    = p_REQ_SEQ
         )
        ;

    END IF;


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
         WHEN OTHERS THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);

END PQHA_SAFE_WORK_REQ_CO_Q ;
/

-- PQHA_SAFT_PGM_Q (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_SAFT_PGM_Q"
							(
							      p_WRK_TP  VARCHAR2 :='Q'
	                             ,p_WRK_ID  VARCHAR2                                            -- 사용자 ID
	                             ,p_WRK_IP  VARCHAR2                                            -- 사용자 IP
							     ,p_SIT_CD  TQHA_SAFT_PGM.SIT_CD%TYPE                             -- 현장코드
							     ,p_PGM_DIV TQHA_SAFT_PGM.PGM_DIV%TYPE                          
							     ,p_PGM_YY  TQHA_SAFT_PGM.PGM_YY%TYPE                          
							     ,RTN_CURSOR OUT SYS_REFCURSOR
							) 
IS 
    /**************************************************************************************************************************
      Purpose :  

      REVISIONS
      Ver      Date               Author                  Description 
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2026/05/22 12:35:37                         최초생성

    /**************************************************************************************************************************/


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR2(200);            -- ERROR Message
    USER_EXCEPTION EXCEPTION;


BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 수행전 Check Logic ]
    ---------------------------------------------------------------------------------------------------------------------------


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Logic 처리
    ---------------------------------------------------------------------------------------------------------------------------

    OPEN RTN_CURSOR FOR
    SELECT  A.SIT_CD                 --현장코드
    	   ,( SELECT CNST_NM FROM VQSZ_SITEINFO WHERE SIT_CD = A.SIT_CD ) AS SIT_NM
           ,A.PGM_SEQ                 --프로그램순번
           ,A.PGM_DIV                 --프로그램구분
           ,A.PGM_YY                 --프로그램연도
           ,A.PGM_KND                 --프로그램종류
           ,A.PGM_NM                 --프로그램명
           ,A.PGM_CTS                 --프로그램내용
           ,A.REG_DT                 --제정일자
           ,A.RV_DT                 --개정일자
           ,A.RMKS                 --비고
           ,A.ATFL_GRP                 --첨부파일그룹
      FROM TQHA_SAFT_PGM A
    WHERE SIT_CD LIKE p_SIT_CD ||'%'
      AND PGM_DIV LIKE p_PGM_DIV ||'%'
      AND PGM_YY LIKE p_PGM_YY   ||'%'                 
      ORDER BY SIT_CD, PGM_YY DESC, PGM_SEQ DESC           
           ;


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN 
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);
END ;
/

-- PQHA_SAFT_PGM_S (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_SAFT_PGM_S"
                            (p_WRK_TP  VARCHAR2 :='U'                                     -- UPDATE FLAG( I: ISNERT, U:UPDATE, D:DELTE)
                            ,p_WRK_ID  VARCHAR2                                           -- 사용자 ID 
                            ,p_WRK_IP  VARCHAR2                                           -- 사용자 IP 
                            ,p_SIT_CD TQHA_SAFT_PGM.SIT_CD%TYPE                           -- 현장코드
                            ,p_PGM_SEQ TQHA_SAFT_PGM.PGM_SEQ%TYPE                         -- 프로그램순번
                            ,p_PGM_DIV TQHA_SAFT_PGM.PGM_DIV%TYPE                         -- 프로그램구분
                            ,p_PGM_YY TQHA_SAFT_PGM.PGM_YY%TYPE                           -- 프로그램연도
                            ,p_PGM_KND TQHA_SAFT_PGM.PGM_KND%TYPE                         -- 프로그램종류
                            ,p_PGM_NM TQHA_SAFT_PGM.PGM_NM%TYPE                           -- 프로그램명
                            ,p_PGM_CTS TQHA_SAFT_PGM.PGM_CTS%TYPE                         -- 프로그램내용
                            ,p_REG_DT TQHA_SAFT_PGM.REG_DT%TYPE                           -- 제정일자
                            ,p_RV_DT TQHA_SAFT_PGM.RV_DT%TYPE                             -- 개정일자
                            ,p_RMKS TQHA_SAFT_PGM.RMKS%TYPE                               -- 비고
                            ,p_ATFL_GRP TQHA_SAFT_PGM.ATFL_GRP%TYPE)                      -- 첨부파일그룹
IS 
    /**************************************************************************************************************************
      Purpose : 

      REVISIONS
      Ver      Date               Author                  Description 
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2026/05/22 12:53:19                         최초생성

    /**************************************************************************************************************************/


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR2(200);            -- ERROR Message
    USER_EXCEPTION EXCEPTION;

    v_SEQ NUMBER;

BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 필수입력 필드  Check  ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_SIT_CD IS NULL)  THEN
        ERR_MSG := '현장코드는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_WRK_TP != 'I' AND p_PGM_SEQ IS NULL)  THEN
        ERR_MSG := '프로그램순번는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_PGM_DIV IS NULL)  THEN
        ERR_MSG := '프로그램구분는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Process 선행조건 Check ]
    ---------------------------------------------------------------------------------------------------------------------------

	 SELECT NVL(MAX(PGM_SEQ), 0) + 1 INTO v_SEQ 
     FROM TQHA_SAFT_PGM
     WHERE SIT_CD = p_SIT_CD;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Business Process ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_WRK_TP ='D') THEN
        DELETE 
          FROM TQHA_SAFT_PGM
         WHERE SIT_CD = p_SIT_CD          --현장코드
           AND PGM_SEQ = p_PGM_SEQ;        --프로그램순번

    ELSIF (p_WRK_TP ='U') THEN
        UPDATE TQHA_SAFT_PGM
           SET PGM_DIV              = p_PGM_DIV                 --프로그램구분
              ,PGM_YY               = p_PGM_YY                  --프로그램연도
              ,PGM_KND              = p_PGM_KND                 --프로그램종류
              ,PGM_NM               = p_PGM_NM                  --프로그램명
              ,PGM_CTS              = p_PGM_CTS                 --프로그램내용
              ,REG_DT               = p_REG_DT                  --제정일자
              ,RV_DT                = p_RV_DT                   --개정일자
              ,RMKS                 = p_RMKS                    --비고
              ,ATFL_GRP             = p_ATFL_GRP                --첨부파일그룹
              ,UPD_ID               = p_WRK_ID                  --수정ID 
              ,UPD_DTM              = SYSDATE()                 --수정일시
              ,UPD_IP               = p_WRK_IP                  --수정IP
         WHERE SIT_CD = p_SIT_CD          --현장코드
           AND PGM_SEQ = p_PGM_SEQ;        --프로그램순번
    ELSE 
        INSERT INTO TQHA_SAFT_PGM
                   ( SIT_CD                  --현장코드
                    ,PGM_SEQ                 --프로그램순번
                    ,PGM_DIV                 --프로그램구분
                    ,PGM_YY                  --프로그램연도
                    ,PGM_KND                 --프로그램종류
                    ,PGM_NM                  --프로그램명
                    ,PGM_CTS                 --프로그램내용
                    ,REG_DT                  --제정일자
                    ,RV_DT                   --개정일자
                    ,RMKS                    --비고
                    ,ATFL_GRP                --첨부파일그룹
                    ,IPT_ID                  --입력ID
                    ,IPT_DTM                 --입력일시
                    ,IPT_IP                  --입력IP
                    ,UPD_ID                  --수정ID
                    ,UPD_DTM                 --수정일시
                    ,UPD_IP                  --수정IP
                    )
             VALUES (p_SIT_CD                --현장코드
                    ,v_SEQ                   --프로그램순번
                    ,p_PGM_DIV               --프로그램구분
                    ,p_PGM_YY                --프로그램연도
                    ,p_PGM_KND               --프로그램종류
                    ,p_PGM_NM                --프로그램명
                    ,p_PGM_CTS               --프로그램내용
                    ,p_REG_DT                --제정일자
                    ,p_RV_DT                 --개정일자
                    ,p_RMKS                  --비고
                    ,p_ATFL_GRP              --첨부파일그룹
                    ,p_WRK_ID                --입력ID 
                    ,SYSDATE()               --입력일시
                    ,p_WRK_IP                --입력IP
                    ,p_WRK_ID                --수정ID
                    ,SYSDATE()               --수정일시
                    ,p_WRK_IP);              --수정IP
    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 5. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN 
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);
END ;
/

