           ,RMKS                 --비고
           ,ATFL_GRP                 --첨부파일그룹
      FROM TQHA_SAFT_RGLN A
    WHERE SIT_CD LIKE p_SIT_CD ||'%'
      AND RGLN_DIV LIKE p_RGLN_DIV ||'%'
      AND RGLN_DT BETWEEN NVL(p_FRDT, '19000101') AND NVL(p_TODT, '47121231')
      ORDER BY SIT_CD, RGLN_DT DESC, RGLN_DIV
	;


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN 
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);
END ;
