-- PQHA_SAFT_SIT_S (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_SAFT_SIT_S" (
    p_WRK_TP            VARCHAR2 := 'U'                         -- UPDATE FLAG(I: ISNERT, U:UPDATE, D:DELTE)
,   p_WRK_ID            VARCHAR2                                -- 사용자 ID 
,   p_WRK_IP            VARCHAR2                                -- 사용자 IP
,   p_SIT_CD            TQHA_SAFT_SIT.SIT_CD        %TYPE       -- 현장코드
,   p_SAFT_ZP_CD        TQHA_SAFT_SIT.SAFT_ZP_CD    %TYPE       -- 안전우편번호
,   p_SAFT_ADDR_1       TQHA_SAFT_SIT.SAFT_ADDR_1   %TYPE       -- 안전주소1
,   p_SAFT_ADDR_2       TQHA_SAFT_SIT.SAFT_ADDR_2   %TYPE       -- 안전주소2
,   p_SIT_TERR          TQHA_SAFT_SIT.SIT_TERR      %TYPE       -- 현장지역
,   p_SAFT_MNG_AMT      TQHA_SAFT_SIT.SAFT_MNG_AMT  %TYPE       -- 도급안전관리비
)
IS 
    /************************************************************************************************************************** 
     COPYRIGHT:    Human Plus
     Procedure:    [PQHA_SAFT_SIT_S] Procedure
     설명     :    [안전현장정보 저장] 프로시저      (안전 > 기준정보 > 현장기준정보상세 저장 프로시저)

     개정일자                      변경내용요약                                 관련근거
    ---------------------------------------------------------------------------------------------------------------------------
     [XXXX-XX-XX]         HumanPlus 신규 자동 생성               [Procedure Creator]  
    ***************************************************************************************************************************/

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE        NUMBER :=-20009 ; --ERROR 코드
    ERR_MSG         VARCHAR2(200)   ; --ERROR Message
    USER_EXCEPTION  EXCEPTION       ;

BEGIN
    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 필수입력 필드  Check  ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_SIT_CD IS NULL)  THEN
        ERR_MSG := '현장코드는 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Process ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF p_WRK_TP = 'U' THEN

        MERGE
         INTO TQHA_SAFT_SIT T1
        USING (SELECT p_SIT_CD          AS SIT_CD
                    , p_SAFT_ZP_CD      AS SAFT_ZP_CD
                    , p_SAFT_ADDR_1     AS SAFT_ADDR_1
                    , p_SAFT_ADDR_2     AS SAFT_ADDR_2
                    , p_SIT_TERR        AS SIT_TERR
                    , p_SAFT_MNG_AMT    AS SAFT_MNG_AMT
                 FROM DUAL
              ) T2
           ON (T1.SIT_CD = T2.SIT_CD)
        WHEN MATCHED THEN
            UPDATE
               SET SAFT_ZP_CD       = p_SAFT_ZP_CD
                 , SAFT_ADDR_1      = p_SAFT_ADDR_1
                 , SAFT_ADDR_2      = p_SAFT_ADDR_2
                 , SIT_TERR         = p_SIT_TERR
                 , SAFT_MNG_AMT     = p_SAFT_MNG_AMT
                 , UPD_ID           = p_WRK_ID
                 , UPD_DTM          = SYSDATE
                 , UPD_IP           = p_WRK_IP
        WHEN NOT MATCHED THEN
            INSERT
                 ( SIT_CD
                 , SAFT_ZP_CD
                 , SAFT_ADDR_1
                 , SAFT_ADDR_2
                 , SIT_TERR
                 , SAFT_MNG_AMT
                 , IPT_ID
                 , IPT_DTM
                 , IPT_IP
                 , UPD_ID
                 , UPD_DTM
                 , UPD_IP
                 )
            VALUES
                 ( p_SIT_CD
                 , p_SAFT_ZP_CD
                 , p_SAFT_ADDR_1
                 , p_SAFT_ADDR_2
                 , p_SIT_TERR
                 , p_SAFT_MNG_AMT
                 , p_WRK_ID
                 , SYSDATE
                 , p_WRK_IP
                 , p_WRK_ID
                 , SYSDATE
                 , p_WRK_IP
                 )
        ;

    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 5. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN 
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);
END PQHA_SAFT_SIT_S;
/

-- PQHA_SELECT_Q1 (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_SELECT_Q1" (
                                                          p_WRK_TP    	VARCHAR2 DEFAULT 'Q'  --FLAG(Q: SELECT)
                                                         ,p_SIT_CD    	TSMB_SAFT_APRS_DTL.SIT_CD %TYPE  --현장코드                                                          
                                                         ,p_ORD_NO 		TSMB_SAFT_APRS_DTL.ORD_NO %TYPE  --발주번호
                                                         ,p_ORD_DGR 	TSMB_SAFT_APRS_DTL.ORD_DGR %TYPE --발주차수
                                                         ,p_BD_DGR 		TSMB_SAFT_APRS_DTL.BD_DGR %TYPE  --입찰번호
                                                         ,p_CUST_CD 	TSMB_SAFT_APRS_DTL.CUST_CD %TYPE --거래처코드
                                                         ,RTN_CURSOR OUT SYS_REFCURSOR 
                                                         )
IS 
    /**************************************************************************************************************************
     COPYRIGHT:    Human Plus   
     Procedure:    [PSMB_SAFT_APRS_CURST_Q] Procedure
     설명     :    [적격수급인이행현황 조회] 프로시저 (외주 > 안전적격평가 > 적격수급인이행현황 > 적격수급인이행현황 조회 프로시저)

     개정일자                      변경내용요약                                 관련근거        
    ---------------------------------------------------------------------------------------------------------------------------
     [2024-03-19]         HumanPlus 신규 자동 생성               [Procedure Creator]  
    ***************************************************************************************************************************/

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009 ; --ERROR 코드
    ERR_MSG        VARCHAR2(200)   ; --ERROR Message
    USER_EXCEPTION EXCEPTION       ;
BEGIN
    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 수행전 Check Logic ]
    ---------------------------------------------------------------------------------------------------------------------------


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Logic 처리
    ---------------------------------------------------------------------------------------------------------------------------
    IF p_WRK_TP = 'Q' THEN    
        OPEN RTN_CURSOR FOR
        WITH TSMB_SAFT AS ( SELECT A.SIT_CD                    -- 현장코드
							     , A.APRS_DGR                  -- 평가차수
							     , A.CUST_CD                   -- 거래처코드
							     , C.CUST_NM                   -- 거래처명
							     , A.ORD_NO                    -- 발주번호
							     , A.ORD_DGR                   -- 발주차수
							     , A.BD_DGR                    -- 입찰번호
							     , A.APRS_ITM_CD               -- 항목코드
							     , B.APRS_ITM_NM               -- 평가항목명칭
							     , A.APRS_SCR                  -- 평가 점수
							     , A.ATFL_GRP                  -- 첨부파일
							  FROM TSMB_SAFT_APRS_DTL A        -- 항목별 평가점수
							      ,TSMB_SAFT_APRS_ITM B        -- 평가항목
							      ,TCOA_TRADE C                -- 업체명
							 WHERE A.SIT_CD      = p_SIT_CD                 -- 현장코드
							   AND A.ORD_NO      = p_ORD_NO                 -- 발주번호
							   AND A.ORD_DGR     = p_ORD_DGR                -- 발주차수
							   AND A.BD_DGR      = p_BD_DGR                 -- 입찰번호
							   AND A.CUST_CD     = p_CUST_CD         		-- 거래처코드
							   AND A.APRS_DGR    = B.APRS_DGR               -- 평가차수    
							   AND A.APRS_ITM_CD = B.APRS_ITM_CD          	-- 평가항목
							   AND A.CUST_CD     = C.CUST_CD                -- 평가차수    

							UNION ALL 

                            SELECT A.SIT_CD 
                                  ,B.APRS_DGR
                                  ,A.CUST_CD 
                                  ,C.CUST_NM
                                  ,A.ORD_NO
                                  ,A.ORD_DGR
                                  ,A.BD_DGR 
                                  ,'ZZ'       AS APRS_ITM_CD
                                  ,'취합본'    AS APRS_ITM_NM
                                  ,NULL        AS APRS_SCR
                                  ,A.ATFL_GRP 
                              FROM TSMB_BD_VNDR A   
                              LEFT JOIN TSMB_SAFT_APRS_DTL B ON A.SIT_CD  = B.SIT_CD
                                                            AND A.ORD_NO  = B.ORD_NO
                                                            AND A.ORD_DGR = B.ORD_DGR
                                                            AND A.BD_DGR  = B.BD_DGR 
                              LEFT JOIN TCOA_TRADE C ON A.CUST_CD = C.CUST_CD
                             WHERE A.SIT_CD      = p_SIT_CD                 -- 현장코드
                               AND A.ORD_NO      = p_ORD_NO                 -- 발주번호
                               AND A.ORD_DGR     = p_ORD_DGR                -- 발주차수
                               AND A.BD_DGR      = (SELECT MAX(BD_DGR)
                                                      FROM TSMB_BD_VNDR
                                                     WHERE SIT_CD  = A.SIT_CD 
                                                       AND ORD_NO  = A.ORD_NO 
                                                       AND ORD_DGR = A.ORD_DGR 
                                                       AND CUST_CD = A.CUST_CD)  -- 입찰번호
                               AND A.CUST_CD     = p_CUST_CD                -- 거래처코드
                               AND A.SBD_YN      = '1'                      -- 낙찰여부
                               AND ROWNUM = 1
							)	  
		SELECT  CUST_NM
		      , LISTAGG(DECODE(APRS_ITM_CD,'A', APRS_ITM_NM),'')                 AS APRS_ITM_NM_1             -- 회사의 안전보건방침 및 목표수립
		      , LISTAGG(DECODE(APRS_ITM_CD,'A', ATFL_GRP),'')                    AS ATFL_GRP_1                -- 첨부파일            
		      , SUM(DECODE(APRS_ITM_CD,'A', APRS_SCR, 0))                        AS APRS_SCR_1                -- 점수
		      , LISTAGG(DECODE(APRS_ITM_CD,'B', APRS_ITM_NM),'')                 AS APRS_ITM_NM_2             -- 대표이사의 안전보건교육 이수여부
		      , LISTAGG(DECODE(APRS_ITM_CD,'B', ATFL_GRP),'')                    AS ATFL_GRP_2                -- 첨부파일            
		      , SUM(DECODE(APRS_ITM_CD,'B', APRS_SCR, 0))                        AS APRS_SCR_2                -- 점수
		      , LISTAGG(DECODE(APRS_ITM_CD,'C', APRS_ITM_NM),'')                 AS APRS_ITM_NM_3             -- 안전보건관리조직의 적정성
		      , LISTAGG(DECODE(APRS_ITM_CD,'C', ATFL_GRP),'')                    AS ATFL_GRP_3                -- 첨부파일            
		      , SUM(DECODE(APRS_ITM_CD,'C', APRS_SCR, 0))                        AS APRS_SCR_3                --  점수
		      , LISTAGG(DECODE(APRS_ITM_CD,'D', APRS_ITM_NM),'')                 AS APRS_ITM_NM_4             -- 최초 위험성평가의 적정성
		      , LISTAGG(DECODE(APRS_ITM_CD,'D', ATFL_GRP),'')                    AS ATFL_GRP_4                -- 첨부파일            
		      , SUM(DECODE(APRS_ITM_CD,'D', APRS_SCR, 0))                        AS APRS_SCR_4                -- 점수
		      , LISTAGG(DECODE(APRS_ITM_CD,'E', APRS_ITM_NM),'')                 AS APRS_ITM_NM_5             -- 위험성 감소대책 이행계획의 적정성
		      , LISTAGG(DECODE(APRS_ITM_CD,'E', ATFL_GRP),'')                    AS ATFL_GRP_5                -- 첨부파일            
		      , SUM(DECODE(APRS_ITM_CD,'E', APRS_SCR, 0))                        AS APRS_SCR_5                -- 점수
		--      ,DECODE(APRS_ITM_CD,'F', APRS_ITM_NM)      AS APRS_ITM_NM_F             -- 안전보건경영시스템 인증 보유여부
		      , LISTAGG(DECODE(APRS_ITM_CD,'F', APRS_ITM_NM),'')                 AS APRS_ITM_NM_6              -- 안전보건경영시스템 인증 보유여부
		      , LISTAGG(DECODE(APRS_ITM_CD,'F', ATFL_GRP),'')                    AS ATFL_GRP_6                 -- 첨부파일            
		      , SUM(DECODE(APRS_ITM_CD,'F', APRS_SCR, 0))                        AS APRS_SCR_6                 -- 점수
		      , LISTAGG(DECODE(APRS_ITM_CD,'G', APRS_ITM_NM),'')                 AS APRS_ITM_NM_7              -- 사고사망만인율
		      , LISTAGG(DECODE(APRS_ITM_CD,'G', ATFL_GRP),'')                    AS ATFL_GRP_7                 -- 첨부파일            
		      , SUM(DECODE(APRS_ITM_CD,'G', APRS_SCR, 0))                        AS APRS_SCR_7                 -- 사고사망만인율 점수

		      , '취합본'                                                         AS APRS_ITM_NM_8              -- 사고사망만인율
              , LISTAGG(DECODE(APRS_ITM_CD,'ZZ', ATFL_GRP),'')                   AS ATFL_GRP_8                 -- 첨부파일


		      , SUM(DECODE(APRS_ITM_CD,'A', APRS_SCR, 0)) + SUM(DECODE(APRS_ITM_CD,'B', APRS_SCR, 0)) +  SUM(DECODE(APRS_ITM_CD,'C', APRS_SCR, 0))  + SUM(DECODE(APRS_ITM_CD,'D', APRS_SCR, 0)) 
              + SUM(DECODE(APRS_ITM_CD,'E', APRS_SCR, 0)) +  SUM(DECODE(APRS_ITM_CD,'F', APRS_SCR, 0))  +  SUM(DECODE(APRS_ITM_CD,'G', APRS_SCR, 0))      AS    APRS_SCR_TOT
		  FROM 	TSMB_SAFT
		  GROUP BY CUST_NM
		 ;   

    END IF;


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN 
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);
END;
/

-- PQHA_SEL_LST_S (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_SEL_LST_S" (
    p_WRK_TP            VARCHAR2 :='U'      -- UPDATE FLAG( I: ISNERT, U:UPDATE, D:DELTE)
,   p_WRK_ID            VARCHAR2            -- 사용자 ID 
,   p_WRK_IP            VARCHAR2            -- 사용자 IP 
,   p_MNU_CD            VARCHAR2            -- 메뉴ID
,   p_KEY_1             VARCHAR2            -- 키1
,   p_KEY_2             VARCHAR2            -- 키2
,   p_KEY_3             VARCHAR2            -- 키3
,   p_KEY_4             VARCHAR2            -- 키4
,   p_KEY_5             VARCHAR2            -- 키5
)
IS 
    /**************************************************************************************************************************
      Purpose : 

      REVISIONS
      Ver      Date               Author                  Description 
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2026/02/13                                   최초생성

    **************************************************************************************************************************/

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR2(200);            -- ERROR Message
    USER_EXCEPTION EXCEPTION;

BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 필수입력 필드  Check  ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_MNU_CD IS NULL)  THEN
        ERR_MSG := '메뉴ID는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Process 선행조건 Check ]
    ---------------------------------------------------------------------------------------------------------------------------



    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Business Process ]
    ---------------------------------------------------------------------------------------------------------------------------

    ----------------------------------------------------------------------------------------------------
    --  
    IF (p_WRK_TP ='I') THEN

        INSERT 
          INTO TQHA_SEL_LST
             ( MNU_CD
             , USR_ID
             , KEY_1
             , KEY_2
             , KEY_3
             , KEY_4
             , KEY_5
             , IPT_ID
             , IPT_DTM
             , IPT_IP
             , UPD_ID
             , UPD_DTM
             , UPD_IP
             )
        VALUES 
             ( p_MNU_CD
             , p_WRK_ID
             , p_KEY_1
             , p_KEY_2
             , p_KEY_3
             , p_KEY_4
             , p_KEY_5
             , p_WRK_ID
             , SYSDATE
             , p_WRK_IP
             , p_WRK_ID
             , SYSDATE
             , p_WRK_IP
             )
        ;

    --------------------------------------------------------------------
    ELSIF (p_WRK_TP ='D') THEN

        DELETE 
          FROM TQHA_SEL_LST
         WHERE MNU_CD   = p_MNU_CD
           AND USR_ID   = p_WRK_ID
           AND KEY_1    = p_KEY_1
           AND KEY_2    = p_KEY_2
           AND KEY_3    = p_KEY_3
           AND KEY_4    = p_KEY_4
           AND KEY_5    = p_KEY_5
        ;

    --------------------------------------------------------------------
    ELSIF (p_WRK_TP ='DA') THEN

        DELETE 
          FROM TQHA_SEL_LST
         WHERE MNU_CD   = p_MNU_CD
           AND USR_ID   = p_WRK_ID
        ;

    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 5. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN 
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);
END ;
/

-- PQHA_SEND_SMS_Q (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_SEND_SMS_Q" (
    p_WRK_TP            IN VARCHAR2 DEFAULT 'Q'         -- FLAG
,   p_CORP_CD           IN VARCHAR2
,   p_DEPT_CD           IN VARCHAR2
,   p_RCV_NO            IN VARCHAR2
,   RTN_CURSOR          OUT SYS_REFCURSOR
)
IS
    /**************************************************************************************************************************
      Purpose : QS SMS

      REVISIONS
      Ver      Date               Author                  Description
      -------  -----------------  ----------------------  ---------------------------------------------------------------------
      1.0      XXXX/XX/XX                                 최초생성

    **************************************************************************************************************************/

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE  NUMBER :=-20009; -- ERROR 코드
    ERR_MSG   VARCHAR(200);    -- ERROR Message
    USER_EXCEPTION EXCEPTION;

BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 수행전 Check Logic ]
    ---------------------------------------------------------------------------------------------------------------------------

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Logic 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------

    IF p_WRK_TP = 'Q' THEN
    
   		OPEN RTN_CURSOR FOR					
		   SELECT A.CORP_CD                                                            AS CORP_CD         -- 법인코드
		     , A.EMP_NO                                                                AS EMP_NO          -- 사번
		     , A.HGL_PNM                                                               AS HGL_PNM     -- 성명
		     , A.DEPT_CD                                                               AS DEPT_CD         -- 소소부서/현장코드
		     , B.DEPT_NM || CASE WHEN NVL(C.DEPT_NM,' ') <> ' '                        
                                 THEN ' - ' || C.DEPT_NM ELSE '' END                   AS DEPT_NM         -- 소속부서/현장명
		     , A.GRADE_CD                                                              AS GRADE_CD        -- 직급코드
		     , FHRZ_GETCDNAME(A.GRADE_CD, 'HRZ0ED')                                    AS GRADE_NM        -- 직급명
		     , FHRZ_GETCDNAME(A.JBCLS_CD, 'HRZ0EB')                                    AS JBCLS_NM        -- 직종명
		     , A.DEPT_WORK_CD                                                          AS DEPT_WORK_CD    -- 근무부서/현장코드
             , NVL(C.DEPT_NM, DEPT_WORK_CD)                                            AS DEPT_WORK_NM    -- 근무부서/현장명
		     , A.CELPH_NO															   AS CELPH_NO
		     , A.CELPH_NO															   AS MP_NO
		     , A.EMAIL_ADDR                                                            AS EMAIL_ADDR
		  FROM THRA_BASEINFO A
		  LEFT OUTER JOIN THRZ_DEPT B 
		  	ON B.CORP_CD = A.CORP_CD AND B.DEPT_CD = A.DEPT_CD
		  LEFT OUTER JOIN THRZ_DEPT C ON C.CORP_CD = A.CORP_CD  -- [이관 수정 2026-11-13] JH: A.WORK_CORP_CD (vplus THRA_BASEINFO에 컬럼 없음)
               AND C.DEPT_CD = A.DEPT_WORK_CD
		 WHERE A.CORP_CD = p_CORP_CD
  		   AND A.CELPH_NO IS NOT NULL 
		   AND (A.DEPT_CD = NVL(p_DEPT_CD, A.DEPT_CD) OR A.DEPT_WORK_CD = NVL(p_DEPT_CD, A.DEPT_WORK_CD))
		 ORDER BY B.DEPT_NM, C.DEPT_NM, A.HGL_PNM
        ;
		
   		/*
   		SELECT A.USR_ID  AS EMP_NO           -- 사용자ID
		         , A.USR_NM  AS HGL_PNM           -- 사용자명
		         , A.DEPT_CD            -- 소속부서
		         , B.DEPT_NM            -- 부서명
		         , A.USE_YN             -- 사용여부
		         , FHRZ_GETCDNAME(A.JBPOS_CD, 'HRZ0ED') AS GRADE_NM   -- 직책명칭
		         , A.MP_NO       AS CELPH_NO            --
		         , A.MAIL_ADDR  AS EMAIL_ADDR         -- 이메일 
		      FROM TCOZ_USR_INFO A
		           LEFT OUTER JOIN TCOZ_DEPT_INFO B
		                        ON A.DEPT_CD = B.DEPT_CD
		     WHERE A.DEPT_CD LIKE '%' || p_DEPT_CD || '%'
		       AND A.MP_NO IS NOT NULL 
		  ORDER BY A.DEPT_CD, A.USR_NM 
		  ;
   		*/
    ELSIF p_WRK_TP = 'Q2' THEN

        -- 비활성: MONO.M2X_SUBMIT_LOG 조회 컴파일 오류. 원문 보존.
        OPEN RTN_CURSOR FOR SELECT NULL AS MSG_ID, NULL AS STATUS, NULL AS SEND_DT, NULL AS SEND_NO, NULL AS RCV_NO, NULL AS MSG, NULL AS RESULT_DESC, NULL AS FAIL_YN FROM DUAL WHERE 1=0;
--         OPEN RTN_CURSOR FOR
-- 		     SELECT MSG_ID AS MSG_ID -- 메시지 ID
-- 	              ,STATUS AS STATUS -- 상태(숨김)
-- 	              ,SUBSTR(SUBMIT_TIME, 1, 8) AS SEND_DT -- 발송일자
-- 	              ,CALLBACK_NUM AS SEND_NO -- 발신번호
-- 	              ,RCPT_DATA AS RCV_NO -- 수신번호
-- 	              ,MESSAGE AS MSG -- 메시지 내용
-- 	              ,RESULT_DESC AS RESULT_DESC -- 발신결과
-- 	              ,FAIL_SEND AS FAIL_YN -- 실패여부
-- 	         FROM MONO.M2X_SUBMIT_LOG
-- 	        WHERE 1=1
-- 	          AND CALLBACK_NUM LIKE '%' || ''
-- 	          --AND SUBSTR(SUBMIT_TIME, 1, 8) BETWEEN NVL('','19900101') AND NVL('', '29991231')
-- 	          AND RESERVED01 LIKE 'ERP_QS%'
-- 	          AND RCPT_DATA = p_RCV_NO
-- 	        ORDER BY MSG_ID DESC
--         ;
                
    ELSIF p_WRK_TP = 'Q3' THEN

        OPEN RTN_CURSOR FOR
		SELECT AA.SIT_CD
		     , AA.CUST_CD
		     ,( SELECT CUST_NM FROM VQSZ_TRADE WHERE CUST_CD = AA.CUST_CD )||' - '||( SELECT DEPT_NM FROM TCOZ_DEPT_INFO WHERE DEPT_CD = AA.SIT_CD ) AS DEPT_NM
		     --,( SELECT CUST_NM FROM VQSZ_TRADE WHERE CUST_CD = AA.CUST_CD ) AS DEPT_NM
			 , AA.VNDR_SEQ
	         , AA.EMPE_NO AS EMP_NO
	         , AA.PNM     AS HGL_PNM
	         , AA.DTY_CD
	         , AA.DTY_NM
	         , AA.TEL_NO
	         , AA.CELPH   AS CELPH_NO
	         , AA.EMAIL   AS EMAIL_ADDR
	         , AA.ATCH_EN
	         , AA.USE_YN
	      FROM TQHB_VNDRNAM AA
	     WHERE 1=1
	       AND SIT_CD LIKE p_DEPT_CD||'%'
	     ORDER
	        BY AA.SIT_CD, AA.CUST_CD, AA.PNM
        ;

    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
         WHEN OTHERS THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);

END PQHA_SEND_SMS_Q;
/

-- PQHA_SITECURST_Q (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_SITECURST_Q" (
    p_WRK_TP            IN VARCHAR2 DEFAULT 'Q'        -- FLAG
,   p_SAFT_TERR_CD      IN VARCHAR2                     -- 안전지역구분
,   p_PRGS_STATS        IN VARCHAR2                     -- 진행상태
,   p_SIT_CD            IN VARCHAR2                     -- 현장코드
,   RTN_CURSOR          OUT SYS_REFCURSOR 
)
IS
    /**************************************************************************************************************************
      Purpose : [현장기준정보 조회] PROCEDRE (QSE > 기준정보 > 현장기준정보  )

      REVISIONS
      Ver      Date               Author                  Description
      -------  -----------------  ----------------------  ---------------------------------------------------------------------
      1.0      XXXX/XX/XX                                 최초생성

    **************************************************************************************************************************/

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE  NUMBER :=-20009; -- ERROR 코드
    ERR_MSG   VARCHAR(200);    -- ERROR Message
    USER_EXCEPTION EXCEPTION;
 
BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 수행전 Check Logic ]
    ---------------------------------------------------------------------------------------------------------------------------

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Logic 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------

    IF p_WRK_TP = 'Q' THEN

        OPEN RTN_CURSOR FOR
        SELECT AAA.*
          FROM (
                SELECT FCOZ_GET_CD_NM(AA.PRGS_STATS, 'CMZ008')              AS PRGS_STATS_NM            --진행상태명
                     , AA.PRGS_STATS
                     , K.SIT_TERR                                           AS SAFT_TERR_CD
                     , (SELECT CD_NM
                          FROM TCOA_COMCODE
                         WHERE HRNK_CD  = 'QSZ05'
                           AND COM_CD   = K.SIT_TERR
                       )                                                    AS SAFT_TERR_NM             --지역구분(CO11)
                     , (SELECT SRT_SO
                          FROM TCOA_COMCODE
                         WHERE HRNK_CD  = 'QSZ05'
                           AND COM_CD   = K.SIT_TERR
                       )                                                    AS SRT_SO
                     , AA.MNG_DEPT_CD                                       AS MNG_DEPT_CD              --관리부서(CMZ003)
                     , E.CD_NM                                              AS MNG_DEPT_NM              --관리부서명
                     , AA.SIT_NM                                                                        --현장명
                     , AA.SIT_CD                                                                        --현장코드
                     , NVL(Z.OCO_UNTKSO_SUM_AMT,0)                          AS SKAT_AMT                 --최종당사계약합계금액(수주)
                     , CASE WHEN AA.CNST_STR_DT IS NULL OR AA.CNST_END_DT IS NULL THEN NULL
                            ELSE TO_CHAR(TO_DATE(AA.CNST_STR_DT, 'YYYYMMDD'), 'YYYY-MM-DD') || ' ~ ' || TO_CHAR(TO_DATE(AA.CNST_END_DT, 'YYYYMMDD'), 'YYYY-MM-DD')
                        END                                                 AS CNST_DT                  --공사기간
                     , H.CD_NM                                              AS CNST_NO_ROW_FRML_NM      --공사종류명
                     , TO_CHAR(CASE WHEN NVL(Z.TOT_UNTK_SPLCM_AMT,0) = 0
                                    THEN 0
                                    ELSE ROUND(NVL(Z.OCO_UNTK_SPLCM_AMT,0) * 1.0 /
                                         NVL(Z.TOT_UNTK_SPLCM_AMT,0) * 100, 2)
                               END, 'FM999,999,990.00')                     AS ERT                      --지분율(공사)
                     , DECODE(FQHA_GETLMYN_BY_SITECD(AA.SIT_CD),'Y','1','0') AS LM_YN
                  FROM TCMZ_SIT AA
                  LEFT JOIN TQHA_SAFT_SIT   K ON AA.SIT_CD  = K.SIT_CD
                  LEFT JOIN TCOA_COMCODE    E ON E.COM_CD   = AA.MNG_DEPT_CD
                                          AND E.HRNK_CD     = 'CMZ003'      --관리부서
                  LEFT JOIN TCOA_COMCODE    H ON H.COM_CD   = AA.CNST_KND
                                          AND H.HRNK_CD     = 'CMZ005'      --공사종류
                  LEFT JOIN TCMZ_SIT_CONT   Z ON Z.SIT_CD   = AA.SIT_CD
                 WHERE 1=1
                   AND (NVL(p_SAFT_TERR_CD, '-') = '-' OR K.SIT_TERR    = p_SAFT_TERR_CD)
                   AND (NVL(p_PRGS_STATS, '-')   = '-' OR AA.PRGS_STATS = p_PRGS_STATS)
               ) AAA
         ORDER
            BY AAA.SRT_SO
             , AAA.SAFT_TERR_NM
             , AAA.SIT_NM
        ;

    -------------------------------------------------------------------------------------------------------------------------
    -- 상세 화면의 폼 조회.
    ELSIF p_WRK_TP = 'Q2' THEN

        OPEN RTN_CURSOR FOR
        SELECT AA.SIT_CD                                                                                --현장코드
             , AA.PRGS_STATS                                                AS PRGS_STATS_CD            --진행상태코드
             , FQHA_GET_CDNM_BY_COMCD(AA.PRGS_STATS)              		    AS PRGS_STATS_NM            --진행상태명
             , H.CD_NM                                                      AS CNST_NO_ROW_FRML_NM      --공사종류명
             , TO_CHAR(CASE WHEN NVL(Z.TOT_UNTK_SPLCM_AMT,0) = 0
                            THEN 0
                            ELSE ROUND(NVL(Z.OCO_UNTK_SPLCM_AMT,0) * 1.0 /
                                 NVL(Z.TOT_UNTK_SPLCM_AMT,0) * 100, 2)
                       END, 'FM999,999,990.00')                             AS ERT                      --지분율(공사)
             , K.SAFT_ZP_CD                                                                             --안전우편번호
             , K.SAFT_ADDR_1                                                                            --안전주소1
             , K.SAFT_ADDR_2                                                                            --안전주소2
             , AA.CNST_TP                                                   AS CNST_TP_1                --공사유형1(SA110_7자리)
             , (SELECT CD_NM
                  FROM TCOA_COMCODE
                 WHERE HRNK_CD  = 'CMZ007'
                   AND COM_CD   = AA.CNST_TP
               )                                                            AS CNST_TP_1_NM
             , NVL(Z.OCO_UNTK_SPLSO_AMT,0)                                  AS OCO_SPLPRC_AMT           --최종당사계약공급가금액(수주))
             , NULL                                                         AS CNST_TEAM_CD             --시공팀코드
             , NULL                                                         AS CNST_TEAM_NM             --시공팀명
             , AA.MNG_DEPT_CD                                               AS MNG_DEPT_CD              --관리부서(CMZ003)
             , E.CD_NM                                                      AS MNG_DEPT_NM              --관리부서명
             , (SELECT LISTAGG(B.CUST_NM, ', ') WITHIN GROUP (ORDER BY B.CUST_NM) AS CUST_LIST
                  FROM TCMZ_SIT_CLIENT A
                       JOIN TCOA_TRADE   B ON B.CUST_CD = A.CUST_CD
                 WHERE A.SIT_CD = AA.SIT_CD
                   AND A.ORDPLC_DIV = '1010'    -- 발주처구분이 발주처
                 GROUP BY A.SIT_CD
               )                                                            AS ORDPLC_NM                --발주처명
             , K.SIT_TERR                                                   AS SAFT_TERR_CD             --안전지역코드
             , CASE WHEN AA.CNST_STR_DT IS NULL OR AA.CNST_END_DT IS NULL THEN NULL
                    ELSE REGEXP_REPLACE(AA.CNST_STR_DT, '([0-9]{4})([0-9]{2})([0-9]{2})', '\1-\2-\3')
                         || ' ~ ' || 
                         REGEXP_REPLACE(AA.CNST_END_DT, '([0-9]{4})([0-9]{2})([0-9]{2})', '\1-\2-\3')
                END                                                         AS CNST_DT                  --공사기간
             , CASE WHEN AA.SCNST_DT IS NULL OR AA.CCNST_DT IS NULL THEN NULL
                    --ELSE AA.SCNST_DT || ' ~ ' || AA.CCNST_DT
                    ELSE REGEXP_REPLACE(AA.SCNST_DT, '([0-9]{4})([0-9]{2})([0-9]{2})', '\1-\2-\3')
                         || ' ~ ' || 
                         REGEXP_REPLACE(AA.CCNST_DT, '([0-9]{4})([0-9]{2})([0-9]{2})', '\1-\2-\3')
                END                                                         AS RCNST_DT                 --착준공일자
             , AA.TEL_NO                                                                                --현장전화번호
             , C.SAFT_UNTK_AMT                                              AS SAFT_MNG_AMT             --도급안전관리비. 최종내역도급기준 산업안전관리비 금액
          FROM TCMZ_SIT AA
          LEFT JOIN TQHA_SAFT_SIT   K ON AA.SIT_CD  = K.SIT_CD
          LEFT JOIN TCOA_COMCODE    E ON E.COM_CD   = AA.MNG_DEPT_CD
                                     AND E.HRNK_CD  = 'CMZ003'      --관리부서
          LEFT JOIN TCOA_COMCODE    H ON H.COM_CD   = AA.CNST_KND
                                     AND H.HRNK_CD  = 'CMZ005'      --공사종류
          LEFT JOIN TCMZ_SIT_CONT   Z ON Z.SIT_CD   = AA.SIT_CD
          LEFT JOIN FCMZ_SAFT_DEFC_IF('SAFT', p_SIT_CD) C ON AA.SIT_CD = C.SIT_CD
         WHERE AA.SIT_CD = p_SIT_CD
        ;

    -------------------------------------------------------------------------------------------------------------------------
    -- 현장직원 목록 조회.
    ELSIF p_WRK_TP = 'Q3' THEN

        OPEN RTN_CURSOR FOR
        SELECT AA.SIT_CD
             , AA.EMPE_NO
             , AA.PNM
             , (
                SELECT JBPOS_NM FROM TCOZ_USR_INFO
                 WHERE 1=1
                   AND USR_ID = AA.EMPE_NO
               ) AS JIKGUB_NM
             , (SELECT CD_NM FROM TCOA_COMCODE WHERE COM_CD = BB.JBPOS_CD AND HRNK_CD = 'HRZ0ED' AND USE_YN = '1') AS JBPOS_NM
             , AA.DTY_CD
             , AA.DTY_NM
             , AA.TEL_NO
             --, PKG_XX1.DEC_VARCHAR2_SEL(AA.CELPH , 10 , 'SSN' , 'TQSZ_SITENAM' ,'CELPH') AS CELPH
             --, PKG_XX1.DEC_VARCHAR2_SEL(AA.EMAIL , 10 , 'SSN' , 'TQSZ_SITENAM' ,'EMAIL') AS EMAIL
             , AA.CELPH
             , AA.EMAIL
             , AA.ATCH_EN
             , AA.USE_YN
             , AA.ATFL_GRP
             , '' AS ATFL_STS
             , BB.USR_KND
             , CASE WHEN BB.USR_KND = 'QS' THEN '외부'
                     ELSE ''
                END AS USR_KND_NM
             --, '/file/previewPhotoQS/'|| AA.EMPE_NO || '/s' AS SPICT_PATH     --  인장정보
             , ''                                               AS SPICT_PATH     --  인장정보
             --, (
             --    SELECT COUNT(1)
             --    FROM TQSB_RSKEVLNAM
             --    WHERE SIT_CD = AA.SIT_CD
             --     AND EMPE_NO = AA.EMPE_NO
             --  ) AS IS_ON_TQSB
             --, (
             --    SELECT COUNT(1)
             --    FROM TQSN_CK_DD
             --    WHERE SIT_CD = AA.SIT_CD
             --     AND ODAY_SAFT_CHR_PSN_EMPNO = AA.EMPE_NO
             --  ) AS IS_ON_TQSN_D
             --, (
             --    SELECT COUNT(1)
             --    FROM TQSN_CK_DD
             --    WHERE SIT_CD = AA.SIT_CD
             --     AND SAFT_HLCR_MGR_EMPNO = AA.EMPE_NO
             --  ) AS IS_ON_TQSN_S
          FROM TQHA_SITENAM AA
             , TCOZ_USR_INFO BB
         WHERE 1=1
           AND AA.SIT_CD    = BB.DEPT_CD (+)
           AND AA.EMPE_NO   = BB.USR_ID (+)
           AND AA.SIT_CD    = p_SIT_CD
         ORDER
            BY BB.USR_KND DESC, AA.PNM, AA.DTY_CD
        ;

    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
         WHEN OTHERS THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);

END PQHA_SITECURST_Q;
/

-- PQHA_SITEDOC_Q (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_SITEDOC_Q" 
                            (p_WRK_TP  VARCHAR2 :='U'                                     -- UPDATE FLAG( I: ISNERT, U:UPDATE, D:DELTE)
                            ,p_WRK_ID  VARCHAR2                                           -- 사용자 ID
                            ,p_WRK_IP  VARCHAR2                                           -- 사용자 IP
                            ,p_WRT_FRDT TQHA_SITEDOC.WRT_DT%TYPE                          -- 작성시작일자
                            ,p_WRT_TODT TQHA_SITEDOC.WRT_DT%TYPE                          -- 작성종료일자
                            ,p_SIT_CD TQHA_SITEDOC.SIT_CD%TYPE                            -- 현장코드
                            ,RTN_CURSOR              OUT SYS_REFCURSOR
                            )

IS
    /**************************************************************************************************************************
      Purpose :

      REVISIONS
      Ver      Date               Author                  Description
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2019/05/07 10:48:20                         최초생성

    /**************************************************************************************************************************/


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR(200);             -- ERROR Message
    USER_EXCEPTION EXCEPTION;
    v_SBM_DT       VARCHAR(200);             -- 제출일자임시
    v_TTL          VARCHAR(200);             -- 문서제목
    v_SBM_YN       VARCHAR(1);               -- 제출여부
    v_CMPL_YN      VARCHAR(1);              -- 완료여부
    v_OBJ_YN       VARCHAR(1);              -- 대상여부

BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 필수입력 필드  Check  ]
    ---------------------------------------------------------------------------------------------------------------------------
	OPEN RTN_CURSOR FOR
        SELECT AA.WRT_DT                -- 작성일자
                , AA.SEQ AS SEQ2                  -- 순번
                , AA.SIT_CD               -- 현장코드
                , AA.SIT_NM               -- 현장명 
                , BB.TTL
                , BB.WRTR_PNM
                , BB.REQ_DT
                , BB.SNSB_YN
                , BB.ATFL_GRP AS ATFL_GRP2
                , AA.TERR_CD               -- 지역코드
                , 'Q' AS POSITION          -- 본부현장구분             
                , AA.OBJ_YN                -- 대상여부             
                , AA.SBM_YN                -- 제출여부
                , AA.SBM_DT                -- 제출일자
                , AA.CMPL_YN               -- 완료여부
                , AA.CMPL_DT               -- 완료일자
                , AA.ATCH_YN               -- 첨부여부
                , AA.ATFL_GRP              -- 첨부파일그룹
                , (
                    AA.SIT_CD 
                    || '-' || 
                    AA.WRT_DT 
                    || '-' ||
                    AA.SEQ
                ) AS RK             
           FROM TQHA_SITEDOC AA
              , TQHA_HODCAB BB
           WHERE 1=1
           AND AA.WRT_DT = BB.WRT_DT(+) 
           AND AA.SEQ = BB.SEQ(+)
           AND AA.SIT_CD = p_SIT_CD
           
           AND AA.WRT_DT BETWEEN NVL(p_WRT_FRDT, TO_DATE('1900-01-01', 'YYYY-MM-DD')) 
                          AND NVL(p_WRT_TODT, TO_DATE('4712-12-31', 'YYYY-MM-DD'))
           
           AND  AA.OBJ_YN = '1'
         ORDER BY AA.WRT_DT DESC
        ;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 5. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
         WHEN OTHERS THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);
END;
/

-- PQHA_SITEDOC_S (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_SITEDOC_S" 
                            (p_WRK_TP  VARCHAR2 :='U'                                     -- UPDATE FLAG( I: ISNERT, U:UPDATE, D:DELTE)
                            ,p_WRK_ID  VARCHAR2                                           -- 사용자 ID
                            ,p_WRK_IP  VARCHAR2                                           -- 사용자 IP
--                            ,p_POSITION  VARCHAR2                                         -- 본부(H), 현장(S)
                            ,p_WRT_DT TQHA_SITEDOC.WRT_DT%TYPE                            -- 작성일자
                            ,p_SEQ TQHA_SITEDOC.SEQ%TYPE                                  -- 순번
                            ,p_SIT_CD TQHA_SITEDOC.SIT_CD%TYPE                          -- 현장코드
                            ,p_SIT_NM TQHA_SITEDOC.SIT_NM%TYPE                          -- 현장명
                            ,p_TERR_CD TQHA_SITEDOC.TERR_CD%TYPE                          -- 지역코드
                            ,p_SAFT_TERR_CD VARCHAR2            						  -- 안전지역코드
                            ,p_OBJ_YN TQHA_SITEDOC.OBJ_YN%TYPE                            -- 대상여부
                            ,p_SBM_YN TQHA_SITEDOC.SBM_YN%TYPE                            -- 제출여부
                            ,p_SBM_DT TQHA_SITEDOC.SBM_DT%TYPE                            -- 제출일자
                            ,p_CMPL_YN TQHA_SITEDOC.CMPL_YN%TYPE                          -- 완료여부
                            ,p_CMPL_DT TQHA_SITEDOC.CMPL_DT%TYPE                          -- 완료일자
                            ,p_ATCH_YN TQHA_SITEDOC.ATCH_YN%TYPE                          -- 첨부여부
                            ,p_ATFL_GRP TQHA_SITEDOC.ATFL_GRP%TYPE)                       -- 첨부파일그룹

IS
    /**************************************************************************************************************************
      Purpose :

      REVISIONS
      Ver      Date               Author                  Description
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2019/05/07 10:48:20                         최초생성

    /**************************************************************************************************************************/


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR(200);             -- ERROR Message
    USER_EXCEPTION EXCEPTION;
    v_SBM_DT       VARCHAR(200);             -- 제출일자임시
    v_TTL          VARCHAR(200);             -- 문서제목
    v_SBM_YN       VARCHAR(1);               -- 제출여부
    v_CMPL_YN      VARCHAR(1);              -- 완료여부
    v_OBJ_YN       VARCHAR(1);              -- 대상여부

BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 필수입력 필드  Check  ]
    ---------------------------------------------------------------------------------------------------------------------------
	BEGIN
	      SELECT TTL INTO v_TTL
	        FROM TQHA_HODCAB
	       WHERE WRT_DT = p_WRT_DT
	         AND SEQ = p_SEQ;
	    EXCEPTION
	       WHEN no_data_found THEN NULL;

	      IF (v_TTL = NULL)  THEN
	          ERR_MSG := '문서제목 데이터가 없습니다.';
	          RAISE USER_EXCEPTION;
	      END IF;
	END;

    BEGIN
	      SELECT SBM_YN INTO v_SBM_YN
	        FROM TQHA_SITEDOC
	       WHERE 1=1
	         AND SIT_CD = p_SIT_CD
	         AND WRT_DT = p_WRT_DT
	         AND SEQ = p_SEQ;
	      EXCEPTION
		       WHEN no_data_found THEN NULL;

	      IF (v_SBM_YN = NULL)  THEN
	          ERR_MSG := '제출여부 데이터가 없습니다.';
	          RAISE USER_EXCEPTION;
	      END IF;
     END; 

	BEGIN
        SELECT CMPL_YN INTO v_CMPL_YN
          FROM TQHA_SITEDOC
         WHERE 1=1
           AND SIT_CD = p_SIT_CD
           AND WRT_DT = p_WRT_DT
           AND SEQ = p_SEQ;
        EXCEPTION
	       WHEN no_data_found THEN NULL;

		  IF (v_CMPL_YN = NULL)  THEN
	          ERR_MSG := '완료여부 데이터가 없습니다.';
	          RAISE USER_EXCEPTION;
	      END IF;
	END;

      IF (v_CMPL_YN = '1')  THEN
          ERR_MSG := p_WRT_DT || ' ' || v_TTL || ' ' || '은(는) 완료된 문서로 변경할 수 없습니다.';
          RAISE USER_EXCEPTION;
      END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Process 선행조건 Check ]
    ---------------------------------------------------------------------------------------------------------------------------


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Business Process ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_WRK_TP ='D') THEN
        DELETE
          FROM TQHA_SITEDOC
         WHERE WRT_DT = p_WRT_DT          --작성일자
           AND SEQ = p_SEQ             --순번
           AND SIT_CD = p_SIT_CD;        --현장코드

    ELSIF (p_WRK_TP ='U') THEN

        --제출시 제출일자 입력
        IF (p_SBM_YN = '1')  THEN
             --v_SBM_DT := SYSDATE();
             v_SBM_DT := TO_CHAR(SYSDATE, 'YYYYMMDD');

         ELSE
             v_SBM_DT := NULL;
         END IF;

        UPDATE TQHA_SITEDOC
           SET TERR_CD              = p_TERR_CD                 --지역코드
              ,OBJ_YN               = p_OBJ_YN                  --대상여부
              ,SBM_YN               = p_SBM_YN                  --제출여부
              ,SBM_DT               = v_SBM_DT                  --제출일자
              ,CMPL_YN              = p_CMPL_YN                 --완료여부
              ,CMPL_DT              = p_CMPL_DT                 --완료일자
              ,ATCH_YN              = p_ATCH_YN                 --첨부여부
              ,ATFL_GRP             = p_ATFL_GRP                --첨부파일그룹
              ,UPD_ID               = p_WRK_ID                  --수정ID
              ,UPD_DTM              = SYSDATE()                 --수정일시
              ,UPD_IP               = p_WRK_IP                  --수정IP
         WHERE WRT_DT = p_WRT_DT          --작성일자
           AND SEQ = p_SEQ             --순번
           AND SIT_CD = p_SIT_CD;        --현장코드
    
    ELSE

        INSERT INTO TQHA_SITEDOC
                   ( WRT_DT                  --작성일자
                    ,SEQ                     --순번
                    ,SIT_CD                 --현장코드
                    ,SIT_NM                 --현장명
                    ,TERR_CD                 --지역코드
                    ,OBJ_YN                  --대상여부
                    ,SBM_YN                  --제출여부
                    ,SBM_DT                  --제출일자
                    ,CMPL_YN                 --완료여부
                    ,CMPL_DT                 --완료일자
                    ,ATCH_YN                 --첨부여부
                    ,ATFL_GRP                --첨부파일그룹
                    ,IPT_ID                  --신규입력ID
                    ,IPT_DTM                 --신규입력일시
                    ,IPT_IP                  --신규입력IP
                    ,UPD_ID                  --최종수정ID
                    ,UPD_DTM                 --최종수정일시
                    ,UPD_IP)                 --최종수정IP
             VALUES (p_WRT_DT                --작성일자
                    ,p_SEQ                   --순번
                    ,p_SIT_CD               --현장코드
                    ,p_SIT_NM               --현장명
                    ,p_TERR_CD               --지역코드
                    --,p_OBJ_YN                --대상여부
                    , NULL
                    ,p_SBM_YN                --제출여부
                    ,p_SBM_DT                --제출일자
                    ,p_CMPL_YN               --완료여부
                    ,p_CMPL_DT               --완료일자
                    ,p_ATCH_YN               --첨부여부
                    ,p_ATFL_GRP              --첨부파일그룹
                    ,p_WRK_ID                --입력ID
                    ,SYSDATE()               --입력일시
                    ,p_WRK_IP                --입력IP
                    ,p_WRK_ID                --수정ID
                    ,SYSDATE()               --수정일시
                    ,p_WRK_IP);              --수정IP
    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 5. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
         WHEN OTHERS THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);
END;
/

-- PQHA_SITEMA_CLOSE_Q (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_SITEMA_CLOSE_Q" (
    p_WRK_TP            IN VARCHAR2 DEFAULT 'Q'         -- FLAG
,   p_SIT_CD            IN VARCHAR2                     -- 현장코드
,   p_CHK_DIV           IN VARCHAR2                     -- 체크구분
,   p_CHK_YYYY          IN VARCHAR2                     -- 점검연도
,   RTN_CURSOR          OUT SYS_REFCURSOR 
)
IS
    /**************************************************************************************************************************
      Purpose : [조치결과등록 마감 조회] PROCEDRE

      REVISIONS
      Ver      Date               Author                  Description
      -------  -----------------  ----------------------  ---------------------------------------------------------------------
      1.0      XXXX/XX/XX                                 최초생성

    **************************************************************************************************************************/

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE  NUMBER :=-20009; -- ERROR 코드
    ERR_MSG   VARCHAR(200);    -- ERROR Message
    USER_EXCEPTION EXCEPTION;

BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 수행전 Check Logic ]
    ---------------------------------------------------------------------------------------------------------------------------

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Logic 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------

    IF p_WRK_TP = 'Q' THEN

        OPEN RTN_CURSOR FOR
        SELECT 
        	   A.CHK_YYYY
        	  ,A.SIT_CD
        	  ,FQHA_GETDEPTNM_BY_DEPTCD(A.SIT_CD) AS SIT_NM
        	  ,A.CHK_DIV
        	  ,A.CLOSE_YN1
        	  ,A.CLOSE_YN2
        	  ,A.CLOSE_YN3
        	  ,A.CLOSE_YN4
        	  ,A.CLOSE_YN1 AS CLOSE_YN1_TXT
        	  ,A.CLOSE_YN2 AS CLOSE_YN2_TXT
        	  ,A.CLOSE_YN3 AS CLOSE_YN3_TXT
        	  ,A.CLOSE_YN4 AS CLOSE_YN4_TXT
        FROM (
		        SELECT 
				    SUBSTR(CHK_DT, 1, 4) AS CHK_YYYY,
				    SIT_CD,
				    CHK_DIV,
				    MAX(CASE WHEN QUARTER IN ('1분기', '1') THEN CLOSE_YN END) AS CLOSE_YN1,
				    MAX(CASE WHEN QUARTER IN ('2분기', '2') THEN CLOSE_YN END) AS CLOSE_YN2,
				    MAX(CASE WHEN QUARTER IN ('3분기', '3') THEN CLOSE_YN END) AS CLOSE_YN3,
				    MAX(CASE WHEN QUARTER IN ('4분기', '4') THEN CLOSE_YN END) AS CLOSE_YN4
				FROM TQHA_HOCHKRPT
				WHERE 1=1
				AND CHK_DIV = NVL(p_CHK_DIV, CHK_DIV)
				AND SUBSTR(CHK_DT, 1, 4) = NVL(p_CHK_YYYY, SUBSTR(CHK_DT, 1, 4))
				GROUP BY SUBSTR(CHK_DT, 1, 4), SIT_CD, CHK_DIV
				ORDER BY CHK_YYYY DESC, SIT_CD, CHK_DIV
			) A
			;

    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
         WHEN OTHERS THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);

END PQHA_SITEMA_CLOSE_Q;
/

-- PQHA_SITEMA_CLOSE_S (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_SITEMA_CLOSE_S" (  
	 p_WRK_TP   VARCHAR2 :='U'                                     -- UPDATE FLAG( I: ISNERT, U:UPDATE, D:DELTE)
    ,p_WRK_ID   VARCHAR2                                           -- 사용자 ID 
    ,p_WRK_IP   VARCHAR2                                           -- 사용자 IP 
    ,p_SIT_CD   TQHA_HOCHKRPT.SIT_CD%TYPE                          -- 현장코드
    ,p_CHK_DIV  TQHA_HOCHKRPT.CHK_DIV%TYPE                         -- 점검구분
    ,p_CHK_YYYY  VARCHAR2                                          -- 점검연도
    ,p_CLOSE_YN1 TQHA_HOCHKRPT.CLOSE_YN%TYPE                       -- 마감여부1
    ,p_CLOSE_YN2 TQHA_HOCHKRPT.CLOSE_YN%TYPE                       -- 마감여부2
    ,p_CLOSE_YN3 TQHA_HOCHKRPT.CLOSE_YN%TYPE                       -- 마감여부3
    ,p_CLOSE_YN4 TQHA_HOCHKRPT.CLOSE_YN%TYPE                       -- 마감여부4
)
IS
    /**************************************************************************************************************************
      Purpose : [조치결과등록 마감 저장] PROCEDRE 

      REVISIONS
      Ver      Date               Author                  Description
      -------  -----------------  ----------------------  ---------------------------------------------------------------------
      1.0      XXXX/XX/XX                                 최초생성

    **************************************************************************************************************************/

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE  NUMBER :=-20009; -- ERROR 코드
    ERR_MSG   VARCHAR(200);    -- ERROR Message
    USER_EXCEPTION EXCEPTION;

    v_CHK_DGR1   NUMBER;
    v_CHK_DGR2   NUMBER;
    v_CHK_DGR3   NUMBER;
    v_CHK_DGR4   NUMBER;
BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 수행전 Check Logic ]
    ---------------------------------------------------------------------------------------------------------------------------

	SELECT MAX(CHK_DGR) INTO v_CHK_DGR1
	FROM TQHA_HOCHKRPT
	WHERE SIT_CD = p_SIT_CD
	  AND CHK_DIV = p_CHK_DIV
	  AND QUARTER = '1'
	  AND SUBSTR(CHK_DT,1,4) = p_CHK_YYYY
	;
	
	SELECT MAX(CHK_DGR) INTO v_CHK_DGR2
	FROM TQHA_HOCHKRPT
	WHERE SIT_CD = p_SIT_CD
	  AND CHK_DIV = p_CHK_DIV
	  AND QUARTER = '2'
	  AND SUBSTR(CHK_DT,1,4) = p_CHK_YYYY
	;
	
	SELECT MAX(CHK_DGR) INTO v_CHK_DGR3
	FROM TQHA_HOCHKRPT
	WHERE SIT_CD = p_SIT_CD
	  AND CHK_DIV = p_CHK_DIV
	  AND QUARTER = '3'
	  AND SUBSTR(CHK_DT,1,4) = p_CHK_YYYY
	;
	
	SELECT MAX(CHK_DGR) INTO v_CHK_DGR4
	FROM TQHA_HOCHKRPT
	WHERE SIT_CD = p_SIT_CD
	  AND CHK_DIV = p_CHK_DIV
	  AND QUARTER = '4'
	  AND SUBSTR(CHK_DT,1,4) = p_CHK_YYYY
	;
	
	
    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Logic 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------

    IF p_WRK_TP = 'U' THEN
    
		UPDATE TQHA_HOCHKRPT
           SET CLOSE_YN             = p_CLOSE_YN1
              ,UPD_ID               = p_WRK_ID    
              ,UPD_DTM              = SYSDATE()  
              ,UPD_IP               = p_WRK_IP   
         WHERE SIT_CD = p_SIT_CD   
           AND CHK_DIV = p_CHK_DIV 
           AND CHK_DGR = v_CHK_DGR1;
		
		UPDATE TQHA_HOCHKRPT
           SET CLOSE_YN             = p_CLOSE_YN2
              ,UPD_ID               = p_WRK_ID    
              ,UPD_DTM              = SYSDATE()  
              ,UPD_IP               = p_WRK_IP   
         WHERE SIT_CD = p_SIT_CD   
           AND CHK_DIV = p_CHK_DIV 
           AND CHK_DGR = v_CHK_DGR2;
		
		UPDATE TQHA_HOCHKRPT
           SET CLOSE_YN             = p_CLOSE_YN3
              ,UPD_ID               = p_WRK_ID    
              ,UPD_DTM              = SYSDATE()  
              ,UPD_IP               = p_WRK_IP   
         WHERE SIT_CD = p_SIT_CD   
           AND CHK_DIV = p_CHK_DIV 
           AND CHK_DGR = v_CHK_DGR3;
		
		UPDATE TQHA_HOCHKRPT
           SET CLOSE_YN             = p_CLOSE_YN4
              ,UPD_ID               = p_WRK_ID  
              ,UPD_DTM              = SYSDATE()
              ,UPD_IP               = p_WRK_IP 
         WHERE SIT_CD = p_SIT_CD   
           AND CHK_DIV = p_CHK_DIV 
           AND CHK_DGR = v_CHK_DGR4;

    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
         WHEN OTHERS THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);

END PQHA_SITEMA_CLOSE_S;
/

-- PQHA_SITEMA_NAM_Q (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_SITEMA_NAM_Q" (
    p_WRK_TP            IN VARCHAR2 DEFAULT 'Q'        -- FLAG
,   p_SIT_CD            IN VARCHAR2                     -- 현장코드
,   p_EMPE_NO           IN VARCHAR2                     -- 
,   RTN_CURSOR          OUT SYS_REFCURSOR
)
IS
    /**************************************************************************************************************************
      Purpose : [현장직원 조회] PROCEDRE (QSE > 기준정보 > 현장기준정보  )

      REVISIONS
      Ver      Date               Author                  Description
      -------  -----------------  ----------------------  ---------------------------------------------------------------------
      1.0      XXXX/XX/XX                                 최초생성

    **************************************************************************************************************************/

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE  NUMBER :=-20009; -- ERROR 코드
    ERR_MSG   VARCHAR(200);    -- ERROR Message
    USER_EXCEPTION EXCEPTION;

BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 수행전 Check Logic ]
    ---------------------------------------------------------------------------------------------------------------------------

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Logic 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------

    -------------------------------------------------------------------------------------------------------------------------
    -- 현장직원 목록 조회.
    IF p_WRK_TP = 'Q' THEN

        OPEN RTN_CURSOR FOR
        SELECT AA.SIT_CD
             , AA.EMPE_NO
             , AA.PNM
             , (
                SELECT JBPOS_NM FROM TCOZ_USR_INFO
                 WHERE 1=1
                   AND USR_ID = AA.EMPE_NO
               ) AS JBPOS_NM
             --, (SELECT CD_NM FROM TCOA_COMCODE WHERE COM_CD = BB.JBPOS_CD AND HRNK_CD = 'HRZ0ED' AND USE_YN = '1') AS JBPOS_NM
             , AA.DTY_CD
             , AA.DTY_NM
             , AA.TEL_NO
             --, PKG_XX1.DEC_VARCHAR2_SEL(AA.CELPH , 10 , 'SSN' , 'TQSZ_SITENAM' ,'CELPH') AS CELPH
             --, PKG_XX1.DEC_VARCHAR2_SEL(AA.EMAIL , 10 , 'SSN' , 'TQSZ_SITENAM' ,'EMAIL') AS EMAIL
             , AA.CELPH
             , AA.EMAIL
             , AA.ATCH_EN
             , AA.USE_YN
             , AA.ATFL_GRP
             , '' AS ATFL_STS
             , BB.USR_KND
             , CASE WHEN BB.USR_KND = 'QS' THEN '외부'
                     ELSE ''
                END AS USR_KND_NM
             --, '/file/previewPhotoQS/'|| AA.EMPE_NO || '/s' AS SPICT_PATH     --  인장정보
             , ''                                               AS SPICT_PATH     --  인장정보
             , NVL(CO_DIV_CD, '1') AS CO_DIV_CD            -- 회사구분코드
             , AA.WRK_STR_DT
             , AA.WRK_END_DT
             , AA.JB_CD
          FROM TQHA_SITENAM AA
             , TCOZ_USR_INFO BB
         WHERE 1=1
           AND AA.SIT_CD    = BB.DEPT_CD (+)
           AND AA.EMPE_NO   = BB.USR_ID (+)
           AND AA.SIT_CD    = p_SIT_CD
           AND AA.EMPE_NO   = p_EMPE_NO
        ;

    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
         WHEN OTHERS THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);

END PQHA_SITEMA_NAM_Q;
/

-- PQHA_SITEMA_Q (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_SITEMA_Q" (
    p_WRK_TP            IN VARCHAR2 DEFAULT 'Q'         -- FLAG
,   p_SIT_CD            IN VARCHAR2                     -- 현장코드
,   p_CHK_DIV           IN VARCHAR2                     -- 체크구분
,   p_CHK_DGR           IN VARCHAR2                     -- 체크일자
,   p_STR_DT            IN VARCHAR2                     -- 체크시작일자
,   p_END_DT            IN VARCHAR2                     -- 체크종료일자
,   RTN_CURSOR          OUT SYS_REFCURSOR 
)
IS
    /**************************************************************************************************************************
      Purpose : [조치결과등록 조회] PROCEDRE (QSE > 재해예방관리 > 조치결과등록 )

      REVISIONS
      Ver      Date               Author                  Description
      -------  -----------------  ----------------------  ---------------------------------------------------------------------
      1.0      XXXX/XX/XX                                 최초생성

    **************************************************************************************************************************/

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE  NUMBER :=-20009; -- ERROR 코드
    ERR_MSG   VARCHAR(200);    -- ERROR Message
    USER_EXCEPTION EXCEPTION;

BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 수행전 Check Logic ]
    ---------------------------------------------------------------------------------------------------------------------------

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Logic 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------

    IF p_WRK_TP = 'Q' THEN

        OPEN RTN_CURSOR FOR
        SELECT A.SIT_CD                 -- 현장코드
             , A.CHK_DT
             , A.CHK_DIV                -- 공통코드 : QSZ03
             , A.CHK_DGR                 -- 점검일자
             , A.ERR_SEQ                -- 지적순번
             , A.DIV_1                  -- 안전 > 공통코드 : QSM02, 환경 > 공통코드 : QSM03
             , A.DIV_2                  -- 안전 > 공통코드 : QSM02, 환경 > 공통코드 : QSM03
             , A.DIV_3                  -- 공통코드 : QSK03
             , (
                SELECT CD_NM
                  FROM TCOA_COMCODE
                 WHERE COM_CD = A.DIV_1
               ) AS DIV_1_NM 
             , (
                SELECT CD_NM
                  FROM TCOA_COMCODE
                 WHERE COM_CD = A.DIV_2
               ) AS DIV_2_NM
             , (
                SELECT CD_NM
                  FROM TCOA_COMCODE
                 WHERE COM_CD = A.DIV_3
               ) AS DIV_3_NM
             , A.CHK_ELMT               -- 지적부위
             , A.CHK_MATT               -- 지적사항
             , A.CSE                    -- 원인
             , A.CPLN_MA_SHM            -- 대책조치방안
             , A.INSP_EMPNO             -- 점검자
             , A.INSP_NM               -- 점검자성명
             , A.MA_DT                  -- 조치일자
             , A.MA_MATT                -- 조치사항
             , A.MA_PSN_EMPNO           -- 조치자/담당직원
             ,(SELECT USR_NM FROM TCOZ_USR_INFO WHERE EMPNO = A.MA_PSN_EMPNO) AS MA_PSN_NM
             --, A.MA_PSN_NM             -- 조치자성명
             , A.CUST_CD                -- 협력회사
             , A.CUST_NM                -- 거래처명
             , A.ATFL_GRP               -- 첨부문서
             , A.ATFL_GRP2              -- 조치전 사진
             , A.PHOTO_DESC_2           -- 조치전 사진내용
             , A.ATFL_GRP3              -- 조치후 사진
             , A.PHOTO_DESC_3           -- 조치후 사진내용
             , B.PRGS_STATS_CD2 AS PRGS_STATS_CD --전자결재상태
             , B.QUARTER
             , B.CLOSE_YN
	         , DECODE(B.CLOSE_YN,'1','마감','') AS CLOSE_YN_NM
          FROM TQHA_HOCHKRPT_ERR    A
             , TQHA_HOCHKRPT        B
         WHERE A.SIT_CD         = B.SIT_CD
           AND A.CHK_DIV        = B.CHK_DIV
           AND A.CHK_DGR        = B.CHK_DGR
           AND A.SIT_CD         = p_SIT_CD
           AND A.CHK_DIV        = p_CHK_DIV
           AND A.CHK_DGR        = p_CHK_DGR
         ORDER BY ERR_SEQ
        ;


    ------------------------------------------------------------------------------------------------
    ELSIF p_WRK_TP = 'Q2' THEN

        OPEN RTN_CURSOR FOR
        SELECT A.SIT_CD
             , FQHA_GETDEPTNM_BY_DEPTCD(A.SIT_CD) AS SIT_NM
             , CHK_DIV
             , CHK_DT
             , CHK_DGR
             , MA_DT
             , SIT_OMGR_EMPNO
             ,( SELECT USR_NM FROM TCOZ_USR_INFO WHERE USR_ID = A.INSP_EMPNO ) AS INSP_NM   			  -- 점검자
		     ,( SELECT USR_NM FROM TCOZ_USR_INFO WHERE USR_ID = A.SIT_OMGR_EMPNO ) AS SIT_OMGR_EMPNO_NM   -- 점검자
	         ,( SELECT USR_NM FROM TCOZ_USR_INFO WHERE USR_ID = A.SAFT_MGR )  AS SAFT_MGR_NM   		  -- 안전관리자명	
             , INSP_BLN
             , INSP_EMPNO
             , ORDPLC
             , CNST_STR_DD ||' ~ '|| CNST_END_DD AS    CNST_STR_DD
             , CNST_END_DD
             , CNST_AMT
             , PROCRT
             , CNST_SCAL
             , WRK_MATT
             , MBOT_PSNNO
             , ATFL_GRP
             , A.PRGS_STATS_CD2
             , (
                SELECT CD_NM
                  FROM TCOA_COMCODE
                 WHERE HRNK_CD = 'QS031'
                   AND COM_CD = C.APRV_STATS
               ) AS PRGS_STATS_CD2_NM
             , (
                   A.SIT_CD
                || CHK_DIV
                || CHK_DGR
               ) AS ROWKEY
             , APRV_NO2
             , A.QUARTER
             , A.CLOSE_YN
	         , DECODE(A.CLOSE_YN,'1','마감','') AS CLOSE_YN_NM
          FROM TQHA_HOCHKRPT A
             , TCOA_COMCODE B
             , TQHA_APRV    C
         WHERE A.SIT_CD     = NVL(p_SIT_CD, A.SIT_CD)
           AND A.CHK_DIV    = NVL(p_CHK_DIV, CHK_DIV)
           AND A.CHK_DIV    = B.COM_CD
           AND REPLACE(CHK_DT,'-','') BETWEEN REPLACE(NVL(p_STR_DT, CHK_DT),'-','')
                                          AND REPLACE(NVL(p_END_DT, CHK_DT),'-','')
           AND A.APRV_NO2   = C.APRV_NO(+)
           AND A.SIT_CD     = C.SIT_CD(+)
         ORDER BY CHK_DT DESC,SIT_CD ASC 
        ;

    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
         WHEN OTHERS THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);

END PQHA_SITEMA_Q;
/

-- PQHA_SITENAM_Q (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_SITENAM_Q" (
    p_WRK_TP            IN VARCHAR2 DEFAULT 'Q'        -- FLAG
,   p_SIT_CD            IN VARCHAR2                     -- 현장코드
,   RTN_CURSOR          OUT SYS_REFCURSOR
)
IS
    /**************************************************************************************************************************
      Purpose : [현장직원 조회] PROCEDRE (QSE > 기준정보 > 현장기준정보  )

      REVISIONS
      Ver      Date               Author                  Description
      -------  -----------------  ----------------------  ---------------------------------------------------------------------
      1.0      XXXX/XX/XX                                 최초생성

    **************************************************************************************************************************/

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE  NUMBER :=-20009; -- ERROR 코드
    ERR_MSG   VARCHAR(200);    -- ERROR Message
    USER_EXCEPTION EXCEPTION;

BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 수행전 Check Logic ]
    ---------------------------------------------------------------------------------------------------------------------------

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Logic 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------

    -------------------------------------------------------------------------------------------------------------------------
    -- 현장직원 목록 조회.
    IF p_WRK_TP = 'Q' THEN

        OPEN RTN_CURSOR FOR
        SELECT AA.SIT_CD
             , AA.EMPE_NO
             , AA.PNM
             , (
                SELECT JBPOS_NM FROM TCOZ_USR_INFO
                 WHERE 1=1
                   AND USR_ID = AA.EMPE_NO
               ) AS JBPOS_NM
             --, (SELECT CD_NM FROM TCOA_COMCODE WHERE COM_CD = BB.JBPOS_CD AND HRNK_CD = 'HRZ0ED' AND USE_YN = '1') AS JBPOS_NM
             , AA.DTY_CD
             , AA.DTY_NM
             , AA.TEL_NO
             --, PKG_XX1.DEC_VARCHAR2_SEL(AA.CELPH , 10 , 'SSN' , 'TQSZ_SITENAM' ,'CELPH') AS CELPH
             --, PKG_XX1.DEC_VARCHAR2_SEL(AA.EMAIL , 10 , 'SSN' , 'TQSZ_SITENAM' ,'EMAIL') AS EMAIL
             , AA.CELPH
             , AA.EMAIL
             , AA.ATCH_EN
             , AA.USE_YN
             , AA.ATFL_GRP
             , '' AS ATFL_STS
             , BB.USR_KND
             , CASE WHEN BB.USR_KND = 'QS' THEN '외부'
                     ELSE ''
                END AS USR_KND_NM
             --, '/file/previewPhotoQS/'|| AA.EMPE_NO || '/s' AS SPICT_PATH     --  인장정보
             , ''                                               AS SPICT_PATH     --  인장정보
             , NVL(CO_DIV_CD, '1') AS CO_DIV_CD            -- 회사구분코드
             , AA.WRK_STR_DT
             , AA.WRK_END_DT
             , AA.JB_CD
             ,(SELECT CD_NM FROM TCOA_COMCODE WHERE COM_CD = AA.JB_CD AND HRNK_CD = 'QS077' AND USE_YN = '1') AS JB_NM
          FROM TQHA_SITENAM AA
             , TCOZ_USR_INFO BB
         WHERE 1=1
           AND AA.SIT_CD    = BB.DEPT_CD (+)
           AND AA.EMPE_NO   = BB.USR_ID (+)
           AND AA.SIT_CD    = p_SIT_CD
         ORDER
            BY AA.CO_DIV_CD, BB.USR_KND DESC, AA.PNM, AA.DTY_CD
        ;

    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
         WHEN OTHERS THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);

END PQHA_SITENAM_Q;
/

-- PQHA_SITENAM_S (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_SITENAM_S" (
    p_WRK_TP        VARCHAR2 :='U'                      -- UPDATE FLAG( I: ISNERT, U:UPDATE, D:DELTE)
,   p_WRK_ID        VARCHAR2                            -- 사용자 ID
,   p_WRK_IP        VARCHAR2                            -- 사용자 IP
,   p_SIT_CD        TQHA_SITENAM.SIT_CD     %TYPE       -- 현장코드
,   p_EMPE_NO       TQHA_SITENAM.EMPE_NO    %TYPE       -- 사원번호
,   p_PNM           TQHA_SITENAM.PNM        %TYPE       -- 성명
,   p_DTY_CD        TQHA_SITENAM.DTY_CD     %TYPE       -- 직책코드
,   p_DTY_NM        TQHA_SITENAM.DTY_NM     %TYPE       -- 직책명
,   p_TEL_NO        TQHA_SITENAM.TEL_NO     %TYPE       -- 전화번호
,   p_CELPH         VARCHAR2                            -- 핸드폰
,   p_EMAIL         VARCHAR2                            -- 이메일
,   p_WRK_STR_DT    TQHA_SITENAM.WRK_STR_DT %TYPE       -- 근무시작일자
,   p_WRK_END_DT    TQHA_SITENAM.WRK_END_DT %TYPE       -- 근무종료일자
,   p_USE_YN        TQHA_SITENAM.USE_YN     %TYPE       -- 사용여부
,   p_ATCH_EN       TQHA_SITENAM.ATCH_EN    %TYPE       -- 싸인유무
,   p_ATFL_GRP      TQHA_SITENAM.ATFL_GRP   %TYPE       -- 첨부파일그룹
,   p_CO_DIV_CD     VARCHAR2                            -- 회사구분코드
,   p_JB_CD         VARCHAR2                            -- 직무
)
IS
    /**************************************************************************************************************************
      Purpose :

      REVISIONS
      Ver      Date               Author                  Description
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2019/04/15 13:26:30                         최초생성

    /**************************************************************************************************************************/

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR(200);             -- ERROR Message
    USER_EXCEPTION EXCEPTION;

    v_COUNT02           NUMBER :=0;              --  현장소장 인원수

    p_UPD_ID  VARCHAR2(30);
    p_UPD_DTM DATE;
    p_UPD_IP  VARCHAR2(30);
    p_IPT_ID  VARCHAR2(30);
    p_IPT_DTM DATE;
    p_IPT_IP  VARCHAR2(30);

BEGIN
    IF p_WRK_TP = 'I' THEN
        p_IPT_ID  := p_WRK_ID;
        p_IPT_DTM := SYSDATE();
        p_IPT_IP  := p_WRK_IP;
        p_UPD_ID  := p_WRK_ID;
        p_UPD_DTM := SYSDATE();
        p_UPD_IP  := p_WRK_IP;
    ELSE
        p_UPD_ID  := p_WRK_ID;
        p_UPD_DTM := SYSDATE();
        p_UPD_IP  := p_WRK_IP;
    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 필수입력 필드  Check  ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_SIT_CD IS NULL)  THEN
        ERR_MSG := '현장코드는 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_EMPE_NO IS NULL)  THEN
        ERR_MSG := '사원번호는 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Process 선행조건 Check ]
    ---------------------------------------------------------------------------------------------------------------------------



    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Business Process ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_WRK_TP ='D') THEN

        DELETE
          FROM TQHA_SITENAM
         WHERE SIT_CD   = p_SIT_CD         --현장코드
           AND EMPE_NO  = p_EMPE_NO        --사원번호
        ;

    ---------------------------------------------------------------------------------------------------------
    ELSIF (p_WRK_TP ='U') THEN

        --현장소장 인원 확인
        IF (p_JB_CD ='QS07703') THEN
            SELECT COUNT(1)
           INTO v_COUNT02
           FROM TQHA_SITENAM
          WHERE 1=1
            AND SIT_CD  = p_SIT_CD
            AND JB_CD   = p_JB_CD
            AND EMPE_NO != p_EMPE_NO;

            IF (v_COUNT02 > 0) THEN
                ERR_MSG := '이미 현장소장이 존재합니다.';
                RAISE USER_EXCEPTION;
            END IF;
        END IF;

        UPDATE TQHA_SITENAM
           SET PNM                  = p_PNM                     --성명
              ,DTY_CD               = p_DTY_CD                  --직책코드
              ,DTY_NM               = p_DTY_NM                  --직책명
              ,TEL_NO               = p_TEL_NO                  --전화번호
              ,CELPH                = p_CELPH 
              -- (SELECT xx1.enc_varchar2_ins(p_CELPH, 10 , 'SSN','','' ) FROM DUAL)  --핸드폰
              ,EMAIL                = p_EMAIL --(SELECT xx1.enc_varchar2_ins(p_EMAIL, 10 , 'SSN','','' ) FROM DUAL)  --이메일
              ,WRK_STR_DT           = p_WRK_STR_DT              --근무시작일자
              ,WRK_END_DT           = p_WRK_END_DT              --근무종료일자
              ,USE_YN               = p_USE_YN                  --사용여부
              ,ATCH_EN              = p_ATCH_EN                 --싸인유무
              ,ATFL_GRP             = p_ATFL_GRP                --첨부파일그룹
              ,CO_DIV_CD            = p_CO_DIV_CD               --회사구분코드
              ,JB_CD                = p_JB_CD
              ,UPD_ID               = p_UPD_ID                  --최종수정ID
              ,UPD_DTM              = p_UPD_DTM                 --최종수정일시
              ,UPD_IP               = p_UPD_IP                  --최종수정IP
         WHERE SIT_CD               = p_SIT_CD                  --현장코드
           AND EMPE_NO              = p_EMPE_NO                 --사원번호
        ;

--        
--        UPDATE TCOZ_USR_INFO
--           SET USE_YN               = p_USE_YN                  --사용여부
--              ,JB_CD                = p_DTY_CD                  --직책코드
--              ,JB_NM                = p_DTY_NM                  --직책명
--              ,UPD_ID               = p_UPD_ID                  --최종수정ID
--              ,UPD_DTM              = p_UPD_DTM                 --최종수정일시
--              ,UPD_IP               = p_UPD_IP                  --최종수정IP
--         WHERE USR_ID               = p_EMPE_NO                 --사원번호
--        ;
--        
        
    ---------------------------------------------------------------------------------------------------------
    -- 첨부파일 저장
    ELSIF  (p_WRK_TP ='U2') THEN

        UPDATE TQHA_SITENAM
           SET ATFL_GRP     = p_ATFL_GRP        --첨부파일그룹
             , UPD_ID       = p_UPD_ID          --최종수정ID
             , UPD_DTM      = p_UPD_DTM         --최종수정일시
             , UPD_IP       = p_UPD_IP          --최종수정IP
         WHERE SIT_CD       = p_SIT_CD          --현장코드
           AND EMPE_NO      = p_EMPE_NO         --사원번호
        ;

    ---------------------------------------------------------------------------------------------------------
    ELSE
        INSERT 
          INTO TQHA_SITENAM
             ( SIT_CD                   --현장코드
             , EMPE_NO                  --사원번호
             , PNM                      --성명
             , DTY_CD                   --직책코드
             , DTY_NM                   --직책명
             , TEL_NO                   --전화번호
             , CELPH                    --핸드폰
             , EMAIL                    --이메일
             , WRK_STR_DT               --근무시작일자
             , WRK_END_DT               --근무종료일자
             , USE_YN                   --사용여부
             , ATCH_EN                  --싸인유무
             , ATFL_GRP                 --첨부파일그룹
             , CO_DIV_CD                --회사구분코드
             , JB_CD
             , IPT_ID                   --신규입력ID
             , IPT_DTM                  --신규입력일시
             , IPT_IP                   --신규입력IP
             , UPD_ID                   --최종수정ID
             , UPD_DTM                  --최종수정일시
             , UPD_IP)                  --최종수정IP
        VALUES 
             ( p_SIT_CD                 --현장코드
             , p_EMPE_NO                --사원번호
             , p_PNM                    --성명
             , p_DTY_CD                 --직책코드
             , p_DTY_NM                 --직책명
             , p_TEL_NO                 --전화번호
             , p_CELPH --(SELECT xx1.enc_varchar2_ins(p_CELPH, 10 , 'SSN','','' ) FROM DUAL)                 --핸드폰
--                    ,PKG_XX1.ENC_VARCHAR2_INS(p_CELPH , 10 , 'SSN' , 'TQHA_SITENAM' ,'CELPH')
             , p_EMAIL -- (SELECT xx1.enc_varchar2_ins(p_EMAIL, 10 , 'SSN','','' ) FROM DUAL)                 --이메일
--                    ,PKG_XX1.ENC_VARCHAR2_INS(p_EMAIL , 10 , 'SSN' , 'TQHA_SITENAM' ,'EMAIL')
             , p_WRK_STR_DT             --근무시작일자
             , p_WRK_END_DT             --근무종료일자
             , p_USE_YN                 --사용여부
             , p_ATCH_EN                --싸인유무
             , p_ATFL_GRP               --첨부파일그룹
             , p_CO_DIV_CD              --회사구분코드
             , p_JB_CD
             , p_IPT_ID                 --신규입력ID
             , p_IPT_DTM                --신규입력일시
             , p_IPT_IP                 --신규입력IP
             , p_UPD_ID                 --최종수정ID
             , p_UPD_DTM                --최종수정일시
             , p_UPD_IP)                --최종수정IP
        ;
--    
--	    UPDATE TCOZ_USR_INFO
--           SET USE_YN               = p_USE_YN                  --사용여부
--              ,JB_CD                = p_DTY_CD                  --직책코드
--              ,JB_NM                = p_DTY_NM                  --직책명
--              ,UPD_ID               = p_UPD_ID                  --최종수정ID
--              ,UPD_DTM              = p_UPD_DTM                 --최종수정일시
--              ,UPD_IP               = p_UPD_IP                  --최종수정IP
--         WHERE USR_ID               = p_EMPE_NO                 --사원번호
--        ;

    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 5. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
         WHEN OTHERS THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);

END;
/

-- PQHA_SITERSK_EVL_CURST_Q (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_SITERSK_EVL_CURST_Q" (
    p_WRK_TP            IN VARCHAR2 DEFAULT 'Q'         -- FLAG
,   p_RISK_LNM_APRS_YM  IN VARCHAR2                     -- 기준년도
,   p_PRGS_STATS        IN VARCHAR2                     -- 진행상태
,   p_INC_YN            IN VARCHAR2
,   RTN_CURSOR          OUT SYS_REFCURSOR
)
IS
    /**************************************************************************************************************************
      Purpose : [현장별 위험성평가 현황 조회] PROCEDRE 

      REVISIONS
      Ver      Date               Author                  Description
      -------  -----------------  ----------------------  ---------------------------------------------------------------------
      1.0      2026/01/19                                 최초생성

    **************************************************************************************************************************/

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE  NUMBER :=-20009; -- ERROR 코드
    ERR_MSG   VARCHAR(200);    -- ERROR Message
    USER_EXCEPTION EXCEPTION;

BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 수행전 Check Logic ]
    ---------------------------------------------------------------------------------------------------------------------------

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Logic 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------

    ---------------------------------------------------------------------------------------
    -- 
    IF p_WRK_TP = 'Q' THEN

        OPEN RTN_CURSOR FOR
        SELECT T2.SIT_CD
             , T1.SIT_CD                AS RISK_SIT_CD
             , MAX(T2.SIT_NM)           AS SIT_NM
             , T1.PLN_YM                AS RISK_LNM_APRS_YM             -- 위험성평가년월
             --, EXTRACT(MONTH FROM TO_DATE(T1.PLN_YM, 'YYYY/MM')) AS RISK_LNM_APRS_M
             --, T1.PLN_YM                AS RISK_LNM_APRS_M             -- 위험성평가년월
             , SUBSTR(T1.PLN_YM, 1, 4) || '-' || SUBSTR(T1.PLN_YM, 5, 2)                AS RISK_LNM_APRS_M             -- 위험성평가년월
             , T1.PLN_DGR               AS RISK_LNM_DGR                 -- 위험성차수
             , MAX(T1.APRS_STR_DT)      AS RISK_LNM_APRS_STR_DT         -- 위험성평가시작일자
             , MAX(T1.APRS_END_DT)      AS RISK_LNM_APRS_END_DT         -- 위험성평가종료일자
             , MAX(T3.SITE_APRV_DT)     AS RISK_LNM_APRS_APRV_DT 
             , MAX(T1.CONF_SCH_DT)      AS CONF_SCH_DT                  -- 회의예정일자
             , SUM(CASE WHEN NVL(T3.SIT_CD, '*') = '*' THEN 0 ELSE 1 END)               AS CNT
             , SUM(CASE WHEN NVL(T3.SBM_YN, '0') = '1' THEN 1 ELSE 0 END)               AS SBM_YCOUNT
             , SUM(CASE WHEN NVL(T3.SITE_APRV_STATS, '0') = '1' THEN 1 ELSE 0 END)      AS SITE_OMGR_APRV_YCOUNT
          FROM TCMZ_SIT T2
          LEFT JOIN TQHA_RISK_DGR   T1 ON T1.SIT_CD     = T2.SIT_CD
                                      AND (    T1.APRS_STR_DT LIKE p_RISK_LNM_APRS_YM || '%'
                                            OR T1.APRS_END_DT LIKE p_RISK_LNM_APRS_YM || '%')
          LEFT JOIN TQHA_RISK_VNDR  T3 ON T1.SIT_CD     = T3.SIT_CD
                                      AND T1.PLN_YM     = T3.PLN_YM 
                                      AND T1.PLN_DGR    = T3.PLN_DGR 
                                      AND T3.OBJ_YN     = '1'
         WHERE 1=1
           AND (NVL(p_PRGS_STATS, '*') = '*' OR T2.PRGS_STATS = p_PRGS_STATS)
           AND ((p_INC_YN  = '1') OR (p_INC_YN = '0' AND T1.PLN_DGR IS NOT NULL))
         GROUP BY T2.SIT_CD, T1.PLN_YM, T1.PLN_DGR, T1.SIT_CD
         ORDER BY T1.SIT_CD, T2.SIT_CD, T1.PLN_YM DESC, T1.PLN_DGR DESC
        ;

    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
         WHEN OTHERS THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);

END PQHA_SITERSK_EVL_CURST_Q;
/

-- PQHA_SUBCONT_W (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_SUBCONT_W" 
							(
							     p_WRK_TP  	VARCHAR2 :='U'                                     -- UPDATE FLAG
							    ,p_WRK_ID   VARCHAR2                                           -- 사용자 ID 
                            	,p_WRK_IP   VARCHAR2                                           -- 사용자 IP 
							)
IS 
    /**************************************************************************************************************************
      Purpose : QS > 안전관리 > 기준정보 > 협력사 기본정보 관리 계약정보 업데이트

      REVISIONS
      Ver      Date               Author                  Description  
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2025/03/10 10:51:46                         최초생성

    /**************************************************************************************************************************/

  
    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR2(200);            -- ERROR Message
    USER_EXCEPTION EXCEPTION;


BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 수행전 Check Logic ]
    ---------------------------------------------------------------------------------------------------------------------------


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Logic 처리
    ---------------------------------------------------------------------------------------------------------------------------

        MERGE INTO TQHA_VNDR A
        USING (SELECT  A.SIT_CD                  -- 현장코드
		             , A.ORD_NO                  -- 발주번호
		             , A.CHG_DGR                 -- 최종차수
		             , A.CUST_CD                 -- 업체코드
		             , B.CUST_NM  AS CUST_NM     -- 업체명칭
		             , A.SCNT_CNST_NM            -- 외주공사명
		             , A.CONT_DT                 -- 계약일자
		             , A.CNST_STR_DT             -- 외주공사시작일자
		             , A.CNST_END_DT             -- 외주공사종료일자
		             , B.BZMN_NO  AS BZMN_NO     -- 사업자번호 
		             , B.RDRTR_PNM           	 -- 대표자명
		             , B.TEL_NO              	 -- 대표전화번호
		             , A.CONT_SUM_AMT        	 -- 계약합계금액
		          FROM  VQSZ_SUBCONT A
		              , VQSZ_TRADE B
		         WHERE A.CUST_CD = B.CUST_CD
		           AND A.CUR_CONT_YN = '1'
	              -- 20250307 외주계약 계약구분(CONT_DIV) 공통코드(SMB001):납품(1040)/용역(1050)/건설기계(1060)/건설기계(표준)(1070)/건설폐기물(1080) 제외 처리
	               AND A.CONT_KND_CD IN ('1010','1020','1030')	 	           
	           ) B
          ON (A.SIT_CD  = B.SIT_CD
          AND A.ORD_NO  = B.ORD_NO
          AND A.CUST_CD = B.CUST_CD)
        WHEN MATCHED THEN 
            UPDATE 
               SET A.VNDR_NM      = B.SCNT_CNST_NM		--외주공사명
                  ,A.VNDR_STR_DT  = B.CNST_STR_DT     	--외주공사시작일자 
                  ,A.VNDR_END_DT  = B.CNST_END_DT     	--외주공사종료일자 
                  ,A.CHG_DGR      = B.CHG_DGR      		--최종차수 
                  ,A.RDRTR_PNM    = B.RDRTR_PNM      	--대표자명 
                  ,A.TEL_NO       = B.TEL_NO      		--대표전화번호 
                  ,A.CONT_SUM_AMT = B.CONT_SUM_AMT    	--계약합계금액 
                  ,A.CONT_DT      = B.CONT_DT      		--계약일자 
                  ,A.UPD_ID       = p_WRK_ID      		--수정ID 
                  ,A.UPD_DTM      = SYSDATE()     		--수정일시 
                  ,A.UPD_IP       = p_WRK_IP      		--수정IP 
          ; 

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN 
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);
END PQHA_SUBCONT_W;
/

-- PQHA_SUBJECT_Q (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_SUBJECT_Q" (
    p_WRK_TP                VARCHAR2 DEFAULT 'Q'        -- FLAG( Q: SELECT )
,   p_WRK_CORP              VARCHAR2                    -- 법인코드
,   p_SIT_CD                TQHA_SUBJECT.SIT_CD%TYPE    -- 현장코드
,   p_SEARCH_DIV            VARCHAR2                    -- 검색조건
,   p_SEARCH_TEXT           VARCHAR2                    -- 검색어 
,   p_AUTH_LVL              VARCHAR2 DEFAULT '1'
,   RTN_CURSOR              OUT SYS_REFCURSOR
)
IS 
    /**************************************************************************************************************************
      Purpose : QSE > 안전관리 > 공지사항 조회

      REVISIONS
      Ver      Date               Author                  Description 
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2023/11/29 09:23:27                         최초생성
    -- 2023/11/29 현장명칭 가져오기 수정 -> 안전관리용 view 사용
    **************************************************************************************************************************/


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR2(200);            -- ERROR Message
    USER_EXCEPTION EXCEPTION;


BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 수행전 Check Logic ]
    ---------------------------------------------------------------------------------------------------------------------------


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Logic 처리
    ---------------------------------------------------------------------------------------------------------------------------
    IF p_WRK_TP = 'Q' THEN

        IF p_AUTH_LVL ='1' THEN

            OPEN RTN_CURSOR FOR
            SELECT A.BLT_NO                                                                -- 게시번호
                 , A.BLT_DIV                                                               -- 공통코드(QS046)
                 , A.SIT_CD                                                                -- 현장코드
                 , ( SELECT CNST_NM FROM VQSZ_SITEINFO WHERE SIT_CD = A.SIT_CD ) AS SIT_NM -- 현장명칭   
                 , A.BLT_TTL TTL                                                           -- 게시제목
                 , A.DTL_CTS                                                               -- 상세내용
                 , B.USR_NM AS BLT_PSN                                                     -- 게시자
                 , A.BLT_DT AS IPT_DTM                                                     -- 게시일자
                 , A.INQ_NO                                                                -- 조회수
                 , A.ATFL_GRP                                                              -- 첨부파일그룹
                 , A.ANNC_STR_DD                                                           -- 공지시작일
                 , A.ANNC_END_DD                                                           -- 공지종료일
              FROM TQHA_SUBJECT A LEFT OUTER JOIN TCOZ_USR_INFO B
                                               ON A.BLT_PSN = B.USR_ID
             WHERE BLT_DIV IN ('1','3')                                                    -- 변수(현장코드)
               AND ((p_SEARCH_DIV = '0' AND B.USR_NM LIKE '%'||p_SEARCH_TEXT||'%') 
                    OR (p_SEARCH_DIV = '1' AND (BLT_TTL LIKE '%'||p_SEARCH_TEXT||'%' OR DTL_CTS LIKE '%'||p_SEARCH_TEXT||'%'))
                   )
             ORDER BY A.BLT_DT DESC
            ;

        ELSE 
            OPEN RTN_CURSOR FOR
            SELECT A.BLT_NO                -- 게시번호
                 , A.BLT_DIV               -- 공통코드(QS046)
                 , A.SIT_CD                -- 현장코드
                 , C.SIT_NM AS SIT_NM      -- 현장명칭   
                 , A.BLT_TTL TTL           -- 게시제목
                 , A.DTL_CTS               -- 상세내용
                 , B.USR_NM AS BLT_PSN     -- 게시자
                 , A.BLT_DT AS IPT_DTM     -- 게시일자
                 , A.INQ_NO                -- 조회수
                 , A.ATFL_GRP              -- 첨부파일그룹
                 , A.ANNC_STR_DD           -- 공지시작일
                 , A.ANNC_END_DD           -- 공지종료일
              FROM TQHA_SUBJECT A LEFT OUTER JOIN TCOZ_USR_INFO B
                                               ON A.BLT_PSN = B.USR_ID
                                  LEFT OUTER JOIN TCMZ_SIT C
                                               ON A.SIT_CD = C.SIT_CD 
              WHERE A.SIT_CD = p_SIT_CD
                AND ((p_SEARCH_DIV = '0' AND B.USR_NM LIKE '%'||p_SEARCH_TEXT||'%') 
                     OR (p_SEARCH_DIV = '1' AND (BLT_TTL LIKE '%'||p_SEARCH_TEXT||'%' OR DTL_CTS LIKE '%'||p_SEARCH_TEXT||'%'))
                    )
              ORDER BY A.BLT_DT DESC
            ;

        END IF;

    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN 
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);
END ;
/

-- PQHA_SUBJECT_S (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_SUBJECT_S" (
    p_WRK_TP                VARCHAR2 :='U'                                  -- UPDATE FLAG( I: ISNERT, U:UPDATE, D:DELTE)
,   p_WRK_ID                VARCHAR2                                        -- 사용자 ID
,   p_WRK_IP                VARCHAR2                                        -- 사용자 IP
,   p_BLT_NO                TQHA_SUBJECT.BLT_NO         %TYPE               -- 게시번호
,   p_BLT_DIV               TQHA_SUBJECT.BLT_DIV        %TYPE               -- 안전공지구분(QS046)
,   p_SIT_CD                TQHA_SUBJECT.SIT_CD         %TYPE DEFAULT ' '   -- 현장코드
,   p_BLT_TTL               TQHA_SUBJECT.BLT_TTL        %TYPE               -- 게시제목
,   p_DTL_CTS               TQHA_SUBJECT.DTL_CTS        %TYPE               -- 상세내용
,   p_BLT_PSN               TQHA_SUBJECT.BLT_PSN        %TYPE               -- 게시자
,   p_BLT_DT                TQHA_SUBJECT.BLT_DT         %TYPE               -- 게시일자
,   p_INQ_NO                TQHA_SUBJECT.INQ_NO         %TYPE               -- 조회수
,   p_ATFL_GRP              TQHA_SUBJECT.ATFL_GRP       %TYPE               -- 첨부파일그룹
,   p_ANNC_STR_DD           TQHA_SUBJECT.ANNC_STR_DD    %TYPE               -- 공지시작일
,   p_ANNC_END_DD           TQHA_SUBJECT.ANNC_END_DD    %TYPE               -- 공지종료일
,   p_RTN_BLT_NO            OUT VARCHAR2                                    -- 리턴변수(게시순번)
)
IS
    /**************************************************************************************************************************
      Purpose : 공지사항 저장

      REVISIONS
      Ver      Date               Author                  Description
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2022/05/26 18:42:41                         최초생성

    **************************************************************************************************************************/


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR2(200);            -- ERROR Message
    USER_EXCEPTION EXCEPTION;

       v_BLT_NO INTEGER;      -- 게시번호 MAX

BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 필수입력 필드  Check  ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_BLT_NO IS NULL)  THEN
        ERR_MSG := '게시번호는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Process 선행조건 Check ]
    ---------------------------------------------------------------------------------------------------------------------------



    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Business Process ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_WRK_TP ='D') THEN
        DELETE
          FROM TQHA_SUBJECT
         WHERE BLT_NO = p_BLT_NO        -- 게시번호
        ;

        v_BLT_NO := p_BLT_NO;

    -----------------------------------------------------------------------------------------
    -- U
    ELSIF (p_WRK_TP ='U') THEN

        UPDATE TQHA_SUBJECT
           SET BLT_DIV          = p_BLT_DIV         -- 안전공지구분(QS046)
             , SIT_CD           = p_SIT_CD          -- 현장코드
             , BLT_TTL          = p_BLT_TTL         -- 게시제목
             , DTL_CTS          = p_DTL_CTS         -- 상세내용
             , BLT_PSN          = p_BLT_PSN         -- 게시자
             , BLT_DT           = p_BLT_DT          -- 게시일자
             , INQ_NO           = p_INQ_NO          -- 조회수
             , ATFL_GRP         = p_ATFL_GRP        -- 첨부파일그룹
             , ANNC_STR_DD      = p_ANNC_STR_DD     -- 공지시작일
             , ANNC_END_DD      = p_ANNC_END_DD     -- 공지종료일
             , UPD_ID           = p_WRK_ID          -- 수정ID
             , UPD_DTM          = SYSDATE()         -- 수정일시
             , UPD_IP           = p_WRK_IP          -- 수정IP
         WHERE BLT_NO           = p_BLT_NO          -- 게시번호
        ;

        v_BLT_NO := p_BLT_NO;

    -----------------------------------------------------------------------------------------
    -- I
    ELSIF (p_WRK_TP ='I') THEN

        -- 게시번호 생성
        SELECT NVL( (MAX(BLT_NO)+1),'1' ) INTO v_BLT_NO
          FROM TQHA_SUBJECT
        ;

        -- 게시번호 생성 완료

        INSERT 
          INTO TQHA_SUBJECT
             ( BLT_NO               -- 게시번호
             , BLT_DIV              -- 안전공지구분(QS046)
             , SIT_CD               -- 현장코드
             , BLT_TTL              -- 게시제목
             , DTL_CTS              -- 상세내용
             , BLT_PSN              -- 게시자
             , BLT_DT               -- 게시일자
             , INQ_NO               -- 조회수
             , ATFL_GRP             -- 첨부파일그룹
             , ANNC_STR_DD          -- 공지시작일
             , ANNC_END_DD          -- 공지종료일
             , IPT_ID               -- 입력ID
             , IPT_DTM              -- 입력일시
             , IPT_IP               -- 입력IP
             , UPD_ID               -- 수정ID
             , UPD_DTM              -- 수정일시
             , UPD_IP               -- 수정IP
             )
        VALUES 
             ( v_BLT_NO             -- 게시번호
             , p_BLT_DIV            -- 안전공지구분(QS046)
             , p_SIT_CD             -- 현장코드
             , p_BLT_TTL            -- 게시제목
             , p_DTL_CTS            -- 상세내용
             , p_BLT_PSN            -- 게시자
             , p_BLT_DT             -- 게시일자
             , p_INQ_NO             -- 조회수
             , p_ATFL_GRP           -- 첨부파일그룹
             , p_ANNC_STR_DD        -- 공지시작일
             , p_ANNC_END_DD        -- 공지종료일
             , p_WRK_ID             -- 입력ID
             , SYSDATE()            -- 입력일시
             , p_WRK_IP             -- 입력IP
             , p_WRK_ID             -- 수정ID
             , SYSDATE()            -- 수정일시
             , p_WRK_IP             -- 수정IP
             )
        ;


    -----------------------------------------------------------------------------------------
    -- A
    ELSIF (p_WRK_TP ='A') THEN

        UPDATE TQHA_SUBJECT
           SET INQ_NO   = NVL(INQ_NO,0) + 1
             , UPD_ID   = p_WRK_ID
             , UPD_DTM  = SYSDATE
             , UPD_IP   = p_WRK_IP
         WHERE BLT_NO   = p_BLT_NO
           AND IPT_ID   != p_WRK_ID     --본인게시글제외
        ;

    END IF;

    p_RTN_BLT_NO := v_BLT_NO;
    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 5. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);

END ;
/

-- PQHA_VIEW_HIS_S (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_VIEW_HIS_S" (
    p_WRK_TP            VARCHAR2 :='U'      -- UPDATE FLAG( I: ISNERT, U:UPDATE, D:DELTE)
,   p_WRK_ID            VARCHAR2            -- 사용자 ID 
,   p_WRK_IP            VARCHAR2            -- 사용자 IP 
,   p_REG_NO            NUMBER              -- 등록번호
,   p_REG_DGR           NUMBER              -- 등록차수
)
IS 
    /**************************************************************************************************************************
      Purpose : 

      REVISIONS
      Ver      Date               Author                  Description 
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2026/02/11                                   최초생성

    **************************************************************************************************************************/

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR2(200);            -- ERROR Message
    USER_EXCEPTION EXCEPTION;

    v_cnt  INTEGER;                             -- 위험성 평가 일정 하위데이타 존재 여부

BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 필수입력 필드  Check  ]
    ---------------------------------------------------------------------------------------------------------------------------
--    IF (p_REG_NO IS NULL)  THEN
--        ERR_MSG := '등록번호는(은) 필수 입력사항 입니다.';
--        RAISE USER_EXCEPTION;
--    END IF;
--
--    IF (p_REG_DGR IS NULL)  THEN
--        ERR_MSG := '등록차수는 필수 입력사항 입니다.'; 
--        RAISE USER_EXCEPTION;
--    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Process 선행조건 Check ]
    ---------------------------------------------------------------------------------------------------------------------------



    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Business Process ]
    ---------------------------------------------------------------------------------------------------------------------------

    ----------------------------------------------------------------------------------------------------
    -- 열람이력 업데이트.
    IF (p_WRK_TP ='U' AND p_REG_NO IS NOT NULL) THEN

        MERGE 
          INTO TQHA_VIEW_HIS T1
         USING (SELECT p_REG_NO     AS REG_NO
                     , p_REG_DGR    AS REG_DGR
                     , p_WRK_ID     AS USR_ID
                  FROM DUAL
               ) T2
            ON (    T1.REG_NO   = T2.REG_NO
                AND T1.REG_DGR  = T2.REG_DGR
                AND T1.USR_ID   = T2.USR_ID
               )
        WHEN NOT MATCHED THEN
            INSERT 
                 ( REG_NO
                 , REG_DGR
                 , USR_ID
                 , IPT_ID
                 , IPT_DTM
                 , IPT_IP
                 , UPD_ID
                 , UPD_DTM
                 , UPD_IP
                 )
            VALUES
                 ( p_REG_NO
                 , p_REG_DGR
                 , p_WRK_ID
                 , p_WRK_ID
                 , SYSDATE
                 , p_WRK_IP
                 , p_WRK_ID
                 , SYSDATE
                 , p_WRK_IP
                 )
        ;

    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 5. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN 
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);
END ;
/

-- PQHA_VIEW_REQ_LST_Q (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_VIEW_REQ_LST_Q" (
    p_WRK_TP            IN VARCHAR2 DEFAULT 'Q'         -- FLAG
,   p_APL_SEQ           IN NUMBER                       -- 신청순번
,   p_WRK_ID            IN VARCHAR2                     -- 입력자ID 
,   p_WRK_MNU           IN VARCHAR2                     -- 메뉴코드
,   RTN_CURSOR          OUT SYS_REFCURSOR
)
IS
    /**************************************************************************************************************************
      Purpose : [자료실 열람 신청목록] PROCEDRE 

      REVISIONS
      Ver      Date               Author                  Description
      -------  -----------------  ----------------------  ---------------------------------------------------------------------
      1.0      2026/02/19                                 최초생성

    **************************************************************************************************************************/

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE  NUMBER :=-20009; -- ERROR 코드
    ERR_MSG   VARCHAR(200);    -- ERROR Message
    USER_EXCEPTION EXCEPTION;

BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 수행전 Check Logic ]
    ---------------------------------------------------------------------------------------------------------------------------

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Logic 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------

    --------------------------------------------------------------------------------------
    -- 그리드 조회 : 열람신청 목록 조회 - 신청 전
    IF (p_WRK_TP = 'Q1') THEN

        OPEN RTN_CURSOR FOR
        SELECT T1.*
             , T3.SIT_NM
             , T8.CD_NM         AS DATA_SUB_DIV_NM
             , T9.CD_NM         AS DATA_SUB_DIV2_NM
          FROM TQHA_DRM                 T1
               JOIN TQHA_SEL_LST        T2 ON T1.REG_NO     = T2.KEY_1
--                                      AND T1.REG_DGR    = T2.KEY_2
          LEFT JOIN TCMZ_SIT            T3 ON T1.SIT_CD = T3.SIT_CD
          LEFT JOIN TCOA_COMCODE        T8 ON T1.DATA_SUB_DIV = T8.COM_CD
                                          AND T8.HRNK_CD      = T1.DATA_DIV
          LEFT JOIN TCOA_COMCODE        T9 ON T1.DATA_SUB_DIV2 = T9.COM_CD
                                          AND T9.HRNK_CD      = T1.DATA_SUB_DIV
         WHERE T1.FNL_YN    = '1'
           AND T2.MNU_CD    = p_WRK_MNU
           AND T2.USR_ID    = p_WRK_ID
         ORDER 
            BY T1.IPT_DTM DESC
        ;

    ---------------------------------------------------------------------------------------
    -- 그리드 조회 : 열람신청 목록 조회 - 신청 후
    ELSIF p_WRK_TP = 'Q2' THEN

        OPEN RTN_CURSOR FOR
        SELECT T1.*
             , T3.SIT_NM
             , T8.CD_NM         AS DATA_SUB_DIV_NM
             , T10.CD_NM         AS DATA_SUB_DIV2_NM
             , T9.VIEW_CNT
          FROM TQHA_DRM                 T1
               JOIN TQHA_VIEW_REQ_LST   T2 ON T1.REG_NO = T2.REG_NO
          LEFT JOIN TCMZ_SIT            T3 ON T1.SIT_CD = T3.SIT_CD
          LEFT JOIN TCOA_COMCODE        T8 ON T1.DATA_SUB_DIV = T8.COM_CD
                                          AND T8.HRNK_CD      = T1.DATA_DIV
          LEFT JOIN TCOA_COMCODE        T10 ON T1.DATA_SUB_DIV2 = T10.COM_CD
                                          AND T10.HRNK_CD      = T1.DATA_SUB_DIV
          LEFT JOIN (   SELECT REG_NO
                             , REG_DGR
                             , COUNT(1)    AS VIEW_CNT
                          FROM TQHA_VIEW_HIS T1
                         GROUP BY REG_NO, REG_DGR
                    )             T9    ON T1.REG_NO    = T9.REG_NO
                                       AND T1.REG_DGR   = T9.REG_DGR
         WHERE T1.FNL_YN    = '1'
           AND T2.APL_SEQ   = p_APL_SEQ
         ORDER 
            BY T1.IPT_DTM DESC
        ;

    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
         WHEN OTHERS THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);

END PQHA_VIEW_REQ_LST_Q;
/

-- PQHA_VIEW_REQ_LST_S (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_VIEW_REQ_LST_S" (
    p_WRK_TP            VARCHAR2 :='U'  -- UPDATE FLAG( I: ISNERT, U:UPDATE, D:DELTE)
,   p_WRK_ID            VARCHAR2        -- 사용자 ID 
,   p_WRK_IP            VARCHAR2        -- 사용자 IP 
,   p_APL_SEQ           NUMBER          -- 신청순번
,   p_REQ_USR_ID        VARCHAR2        -- 신청자ID
,   p_REG_NO            NUMBER          -- 등록번호
)
IS 
    /**************************************************************************************************************************
      Purpose : 자료실 저장

      REVISIONS
      Ver      Date               Author                  Description 
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2026/02/13                                    최초생성

    **************************************************************************************************************************/


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드 
    ERR_MSG        VARCHAR2(200);            -- ERROR Message
    USER_EXCEPTION EXCEPTION;

BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 필수입력 필드  Check  ]
    ---------------------------------------------------------------------------------------------------------------------------

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Process 선행조건 Check ]
    ---------------------------------------------------------------------------------------------------------------------------



    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Business Process ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_WRK_TP ='D') THEN

        DELETE 
          FROM TQHA_VIEW_REQ_LST
         WHERE APL_SEQ      = p_APL_SEQ
           AND REG_NO       = p_REG_NO
        ;


    ---------------------------------------------------------------------------------------------
    ELSIF p_WRK_TP = 'I' THEN

        INSERT 
          INTO TQHA_VIEW_REQ_LST
             ( APL_SEQ              -- 신청순번
             , REG_NO
             , IPT_ID               -- 입력자
             , IPT_DTM              -- 입력일시
             , IPT_IP               -- 입력IP
             , UPD_ID               -- 수정자
             , UPD_DTM              -- 수정일시
             , UPD_IP               -- 수정IP
             )
        VALUES 
             ( p_APL_SEQ            -- 신청순번
             , p_REG_NO
             , p_WRK_ID             -- 입력ID 
             , SYSDATE()            -- 입력일시
             , p_WRK_IP             -- 입력IP
             , p_WRK_ID             -- 수정ID
             , SYSDATE()            -- 수정일시
             , p_WRK_IP             -- 수정IP
             )
        ;

    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 5. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN 
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);
END ;
/

-- PQHA_VIEW_REQ_Q (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_VIEW_REQ_Q" (
    p_WRK_TP            IN VARCHAR2 DEFAULT 'Q'         -- FLAG
,   p_APL_SEQ           IN NUMBER                       -- 신청순번
,   p_APL_STATS         IN VARCHAR2                     -- 신청상태
,   p_REQ_NM            IN VARCHAR2                     -- 신청자
,   p_REQ_STR_DD        IN VARCHAR2                     -- 신청일
,   p_REQ_END_DD        IN VARCHAR2                     -- 신청일
,   RTN_CURSOR          OUT SYS_REFCURSOR
)
IS
    /**************************************************************************************************************************
      Purpose : [자료실 열람] PROCEDRE 

      REVISIONS
      Ver      Date               Author                  Description
      -------  -----------------  ----------------------  ---------------------------------------------------------------------
      1.0      2026/02/19                                 최초생성

    **************************************************************************************************************************/

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE  NUMBER :=-20009; -- ERROR 코드
    ERR_MSG   VARCHAR(200);    -- ERROR Message
    USER_EXCEPTION EXCEPTION;

BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 수행전 Check Logic ]
    ---------------------------------------------------------------------------------------------------------------------------

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Logic 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------

    ---------------------------------------------------------------------------------------
    -- 폼 조회 : 열람신청 내역 조회
    IF p_WRK_TP = 'Q1' THEN

        OPEN RTN_CURSOR FOR
        SELECT APL_SEQ
             , REQ_USR_ID
             , TO_CHAR(APL_DTM, 'YYYY-MM-DD')   AS APL_DTM
             , READ_STR_DD
             , READ_END_DD
             , APL_STATS
             , RSTOR_CTS
             , T2.USR_NM    AS REG_NM
             , T3.CD_NM     AS APL_STATS_NM
          FROM TQHA_VIEW_REQ        T1
               JOIN TCOZ_USR_INFO   T2 ON T1.REQ_USR_ID = T2.USR_ID
          LEFT JOIN TCOA_COMCODE    T3 ON T1.APL_STATS  = T3.COM_CD
                                      AND T3.HRNK_CD = 'QS061'
         WHERE APL_SEQ  = p_APL_SEQ
        ;

    ---------------------------------------------------------------------------------------
    -- 그리드 조회 : 열람신청 리스트 조회
    ELSIF p_WRK_TP = 'Q2' THEN

        OPEN RTN_CURSOR FOR
        SELECT APL_SEQ
             , REQ_USR_ID
             , TO_CHAR(APL_DTM, 'YYYYMMDD')   AS APL_DTM
             , READ_STR_DD
             , READ_END_DD
             , APL_STATS
             , RSTOR_CTS
             , T2.USR_NM        AS REQ_USR_NM
          FROM TQHA_VIEW_REQ        T1
               JOIN TCOZ_USR_INFO   T2 ON T1.REQ_USR_ID = T2.USR_ID
         WHERE (NVL(p_APL_STATS, '*') = '*'     OR T1.APL_STATS = p_APL_STATS)
           AND (NVL(p_REQ_NM, '*') = '*'        OR T1.REQ_USR_ID = p_REQ_NM)
           AND (NVL(p_REQ_NM, '*') = '*'        OR T2.USR_NM LIKE  '%' || p_REQ_NM || '%')
           AND (NVL(p_REQ_STR_DD, '*') = '*'    OR T1.APL_DTM >= TO_DATE(p_REQ_STR_DD, 'YYYYMMDD'))
           AND (NVL(p_REQ_END_DD, '*') = '*'    OR T1.APL_DTM <  TO_DATE(p_REQ_END_DD, 'YYYYMMDD') + 1)
         ORDER BY APL_DTM DESC
        ;

    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
         WHEN OTHERS THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);

END PQHA_VIEW_REQ_Q;
/

-- PQHA_VIEW_REQ_S (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_VIEW_REQ_S" (
    p_WRK_TP            VARCHAR2 :='U'   -- UPDATE FLAG( I: ISNERT, U:UPDATE, D:DELTE)
,   p_WRK_ID            VARCHAR2         -- 사용자 ID 
,   p_WRK_IP            VARCHAR2         -- 사용자 IP 
,   p_APL_SEQ           NUMBER           -- 신청순번
,   p_READ_STR_DD       VARCHAR2         -- 열람시작일
,   p_READ_END_DD       VARCHAR2         -- 열람종료일
,   p_APL_STATS         VARCHAR2         -- 신청상태
,   p_RSTOR_CTS         VARCHAR2         -- 반려내용
,   p_MNU_CD            VARCHAR2         -- 메뉴ID
,   p_RTN_APL_SEQ       OUT VARCHAR2     -- 리턴변수(신청순번)
)
IS 
    /**************************************************************************************************************************
      Purpose : 열람신청

      REVISIONS
      Ver      Date               Author                  Description 
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2026/02/13                                    최초생성

    **************************************************************************************************************************/


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드 
    ERR_MSG        VARCHAR2(200);            -- ERROR Message
    USER_EXCEPTION EXCEPTION;

    v_APL_SEQ       NUMBER;         -- 신청순번

BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 필수입력 필드  Check  ]
    ---------------------------------------------------------------------------------------------------------------------------

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Process 선행조건 Check ]
    ---------------------------------------------------------------------------------------------------------------------------



    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Business Process ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_WRK_TP ='D') THEN

        DELETE 
          FROM TQHA_VIEW_REQ_LST
         WHERE APL_SEQ      = p_APL_SEQ
        ;

        DELETE 
          FROM TQHA_VIEW_REQ
         WHERE APL_SEQ      = p_APL_SEQ
        ;

        --신청순번
        v_APL_SEQ := p_APL_SEQ;

    ---------------------------------------------------------------------------------------------
    ELSIF (p_WRK_TP ='U') THEN

        UPDATE TQHA_VIEW_REQ
           SET READ_STR_DD      = p_READ_STR_DD
             , READ_END_DD      = p_READ_END_DD
             , UPD_ID           = p_WRK_ID          -- 수정ID
             , UPD_DTM          = SYSDATE           -- 수정일시
             , UPD_IP           = p_WRK_IP          -- 수정IP
         WHERE APL_SEQ          = p_APL_SEQ         -- 신청순번
           AND REQ_USR_ID       = p_WRK_ID
        ;

        v_APL_SEQ := p_APL_SEQ;

    ---------------------------------------------------------------------------------------------
    ELSIF (p_WRK_TP ='STATS') THEN

        UPDATE TQHA_VIEW_REQ
           SET APL_STATS        = p_APL_STATS
             , RSTOR_CTS        = p_RSTOR_CTS
             , UPD_ID           = p_WRK_ID          -- 수정ID
             , UPD_DTM          = SYSDATE           -- 수정일시
             , UPD_IP           = p_WRK_IP          -- 수정IP
         WHERE APL_SEQ          = p_APL_SEQ         -- 신청순번
        ;

        v_APL_SEQ := p_APL_SEQ;

    ---------------------------------------------------------------------------------------------
    ELSIF p_WRK_TP = 'I' THEN

        IF NVL(p_APL_SEQ, 0) != 0 THEN

            UPDATE TQHA_VIEW_REQ
               SET APL_STATS        = '001'             -- 승인요청중으로 변경.
                 , RSTOR_CTS        = p_RSTOR_CTS
                 , UPD_ID           = p_WRK_ID          -- 수정ID
                 , UPD_DTM          = SYSDATE           -- 수정일시
                 , UPD_IP           = p_WRK_IP          -- 수정IP
             WHERE APL_SEQ          = p_APL_SEQ         -- 신청순번
            ;

            v_APL_SEQ := p_APL_SEQ;

        ELSE 
            SELECT NVL(MAX(APL_SEQ), 0) + 1
              INTO v_APL_SEQ
              FROM TQHA_VIEW_REQ 
            ;

            INSERT 
              INTO TQHA_VIEW_REQ
                 ( APL_SEQ               -- 신청순번
                 , REQ_USR_ID
                 , APL_DTM
                 , READ_STR_DD
                 , READ_END_DD
                 , APL_STATS
                 , RSTOR_CTS
                 , IPT_ID               -- 입력자
                 , IPT_DTM              -- 입력일시
                 , IPT_IP               -- 입력IP
                 , UPD_ID               -- 수정자
                 , UPD_DTM              -- 수정일시
                 , UPD_IP               -- 수정IP
                 )
            VALUES 
                 ( v_APL_SEQ            -- 신청순번
                 , p_WRK_ID
                 , SYSDATE
                 , p_READ_STR_DD
                 , p_READ_END_DD
                 , '001'                -- 신청용청중
                 , NULL
                 , p_WRK_ID             -- 입력ID 
                 , SYSDATE              -- 입력일시
                 , p_WRK_IP             -- 입력IP
                 , p_WRK_ID             -- 수정ID
                 , SYSDATE              -- 수정일시
                 , p_WRK_IP             -- 수정IP
                 )
            ;

            -- TQHA_SEL_LST 에 있는 목록을 저장.
            INSERT 
              INTO TQHA_VIEW_REQ_LST
                 ( APL_SEQ              -- 신청순번
                 , REG_NO
                 , IPT_ID               -- 입력자
                 , IPT_DTM              -- 입력일시
                 , IPT_IP               -- 입력IP
                 , UPD_ID               -- 수정자
                 , UPD_DTM              -- 수정일시
                 , UPD_IP               -- 수정IP
                 )
            SELECT v_APL_SEQ
                 , KEY_1
                 , p_WRK_ID             -- 입력ID 
                 , SYSDATE              -- 입력일시
                 , p_WRK_IP             -- 입력IP
                 , p_WRK_ID             -- 수정ID
                 , SYSDATE              -- 수정일시
                 , p_WRK_IP             -- 수정IP
              FROM TQHA_SEL_LST
             WHERE MNU_CD   = p_MNU_CD
               AND USR_ID   = p_WRK_ID
            ;
        END IF;

    END IF;

    p_RTN_APL_SEQ := v_APL_SEQ;
    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 5. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN 
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);
END ;
/

-- PQHA_VNDR_PWD_S (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_VNDR_PWD_S" (
    p_WRK_TP                VARCHAR2 :='U'      -- UPDATE FLAG( I: ISNERT, U:UPDATE, D:DELTE)
,   p_WRK_ID                VARCHAR2            -- 사용자 ID
,   p_WRK_IP                VARCHAR2            -- 사용자 IP
,   p_SIT_CD                VARCHAR2            -- 현장코드
,   p_CUST_CD               VARCHAR2            -- 협력업체코드
,   p_VNDR_SEQ              VARCHAR2            -- 업체순번 
,   p_VNDR_PSN_PWD          VARCHAR2            -- 비밀번호
,   p_PWD_NO_CHG_DT         VARCHAR2            -- 비밀번호변경일
,   p_RSET_YN               VARCHAR2            -- 초기화여부
,   p_EMPE_NO               VARCHAR2            -- 사번
)
IS
    /**************************************************************************************************************************
      Purpose : 업체 비밀번호 초기화

      REVISIONS
      Ver      Date               Author                  Description
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2025/02/06                                    최초생성

    /**************************************************************************************************************************/
 
    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR(200);             -- ERROR Message
    USER_EXCEPTION EXCEPTION;


BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 필수입력 필드  Check  ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_SIT_CD IS NULL)  THEN
        ERR_MSG := '현장코드는 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_CUST_CD IS NULL)  THEN
        ERR_MSG := '협력업체코드는 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_VNDR_SEQ IS NULL)  THEN
        ERR_MSG := '업체순번은 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Process 선행조건 Check ]
    ---------------------------------------------------------------------------------------------------------------------------

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Business Process ]
    ---------------------------------------------------------------------------------------------------------------------------
    
    
    	UPDATE TQHB_VNDRNAM
           SET 
               VNDR_PSN_PWD         = p_VNDR_PSN_PWD            --개인정보 암호 (폰 전화번호 뒤 4자리 암호화)
              ,PWD_NO_CHG_DT        = TO_CHAR(SYSDATE(),'YYYYMMDD')      --비번최종변경일자
              ,RSET_YN              = '1'                       --비번 초기화여부
              ,FAIL_CNT             = 0                         --실패횟수
              ,UPD_ID               = p_WRK_ID                  --수정ID 
              ,UPD_DTM              = SYSDATE()                 --수정일시
              ,UPD_IP               = p_WRK_IP                  --수정IP
         WHERE SIT_CD = p_SIT_CD          --현장코드
           AND CUST_CD = p_CUST_CD         --협력업체코드
           AND VNDR_SEQ = p_VNDR_SEQ        --업체순번
           AND EMPE_NO = p_EMPE_NO;        --사원번호
           
--
--        UPDATE TQHA_VNDR
--           SET VNDR_PSN_PWD     = p_VNDR_PSN_PWD        -- JAVA에서 폰 전화번호 뒤 4자리 암호화하여 넘어옴.
--               -- VNDR_PSN_PWD = SYS.PKG_HASHCRYPTO.encryptHash(p_VNDR_PSN_PWD)
--             , PWD_NO_CHG_DT    = p_PWD_NO_CHG_DT
--             , RSET_YN          = p_RSET_YN
--             , FAIL_CNT         = 0
--             , UPD_ID           = p_WRK_ID
--             , UPD_DTM          = SYSDATE
--         WHERE SIT_CD           = p_SIT_CD
--           AND CUST_CD          = p_CUST_CD
--           AND VNDR_SEQ         = p_VNDR_SEQ
--        ;

    

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 5. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
         WHEN OTHERS THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);
END;
/

-- PQHA_VNDR_Q (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_VNDR_Q" (
    p_WRK_TP        VARCHAR2 DEFAULT 'Q'            -- FLAG( Q: SELECT )
,   p_SIT_CD        TQHA_VNDR.SIT_CD    %TYPE       -- 현장코드
,   RTN_CURSOR      OUT SYS_REFCURSOR
) 
IS 
    /**************************************************************************************************************************
      Purpose : QSE > 안전관리 > 기준정보 > 협력업체관리 조회

      REVISIONS
      Ver      Date               Author                  Description 
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2023/11/28 10:42:37                         최초생성

    **************************************************************************************************************************/

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;    -- ERROR 코드
    ERR_MSG        VARCHAR2(200);   -- ERROR Message
    USER_EXCEPTION EXCEPTION;

BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 수행전 Check Logic ]
    ---------------------------------------------------------------------------------------------------------------------------

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Logic 처리
    ---------------------------------------------------------------------------------------------------------------------------

    OPEN RTN_CURSOR FOR
    SELECT SIT_CD               -- 현장코드  
         , CUST_CD              -- 업체코드
         -- 2023/11/29 업체명칭 가져오기 수정 -> 안전관리용 view 사용             
         --             , ( SELECT COP_VNDR_NM FROM TSCA_TRADE WHERE COP_VNDR_CD = VNDR_CD )    AS COP_VNDR_NM      -- 업체명
         --             , ( SELECT BZMN_NO FROM TSCA_TRADE WHERE COP_VNDR_CD = VNDR_CD )        AS BZMN_NO          -- 사업자번호 
         , ( SELECT CUST_NM FROM VQSZ_TRADE WHERE CUST_CD = A.CUST_CD )                         AS CUST_NM          -- 업체명
         , ( SELECT BZMN_NO FROM VQSZ_TRADE WHERE CUST_CD = A.CUST_CD )                         AS BZMN_NO          -- 사업자번호 
         -----------------------------             
         , VNDR_SEQ              -- 업체순번
         , VNDR_NM               -- 공사명
         , cont_dt               -- 계약일자
         , VNDR_STR_DT           -- 공사시작일
         , VNDR_END_DT           -- 공사종료일
         , VNDR_PSN_ID           -- 업체담당자 ID
         , VNDR_PSN_PWD          -- 업체담당자 PWD  ' 암호화하여 *로 표시'
         , VNDR_PSN_NM           -- 업체담당자 성명
         -- , PKG_CRYPTO_dec.decrypt(VNDR_PSN_EMAIL) AS VNDR_PSN_EMAIL   -- 업체담당자 이메일
         -- , PKG_CRYPTO_dec.decrypt(VNDR_PSN_CADDR) AS VNDR_PSN_CADDR   -- 업체담당자 핸드폰번호
         ,  VNDR_PSN_EMAIL       -- 업체담당자 이메일
         ,  VNDR_PSN_CADDR       -- 업체담당자 핸드폰번호
         , MGR_1                 -- 관리감독자1
         , ( SELECT USR_NM FROM TCOZ_USR_INFO WHERE USR_ID = MGR_1 )                                AS MGR_1_NM             -- 관리감독자1 성명
         -- , ( SELECT PKG_CRYPTO_dec.decrypt(MP_NO) FROM TCOZ_USR_INFO WHERE USR_ID = MGR_1 )      AS MGR_1_CADDR          -- 관리감독자1 전화번호
         -- , ( SELECT MP_NO FROM TCOZ_USR_INFO WHERE USR_ID = MGR_1 )                              AS MGR_1_CADDR          -- 관리감독자1 전화번호
         , ( SELECT CELPH FROM TQHA_SITENAM WHERE SIT_CD = p_SIT_CD AND EMPE_NO = MGR_1 )           AS MGR_1_CADDR          -- 관리감독자1 전화번호
         , MGR_2                 -- 관리감독자2
         , ( SELECT USR_NM FROM TCOZ_USR_INFO WHERE USR_ID = MGR_2 )                                AS MGR_2_NM             -- 관리감독자2 성명
         -- , ( SELECT PKG_CRYPTO_dec.decrypt(MP_NO) FROM TCOZ_USR_INFO WHERE USR_ID = MGR_2 )      AS MGR_2_CADDR          -- 관리감독자2 전화번호
         -- , ( SELECT MP_NO FROM TCOZ_USR_INFO WHERE USR_ID = MGR_2 )                              AS MGR_2_CADDR          -- 관리감독자2 전화번호
         , ( SELECT CELPH FROM TQHA_SITENAM WHERE SIT_CD = p_SIT_CD AND EMPE_NO = MGR_2 )           AS MGR_2_CADDR          -- 관리감독자2 전화번호
         , MGR_3                 -- 관리감독자3
         , ( SELECT USR_NM FROM TCOZ_USR_INFO WHERE USR_ID = MGR_3 )                                AS MGR_3_NM             -- 관리감독자3 성명
         -- , ( SELECT PKG_CRYPTO_dec.decrypt(MP_NO) FROM TCOZ_USR_INFO WHERE USR_ID = MGR_3 )      AS MGR_3_CADDR          -- 관리감독자3 전화번호
         -- , ( SELECT MP_NO FROM TCOZ_USR_INFO WHERE USR_ID = MGR_3 )                              AS MGR_3_CADDR          -- 관리감독자3 전화번호
         , ( SELECT CELPH FROM TQHA_SITENAM WHERE SIT_CD = p_SIT_CD AND EMPE_NO = MGR_3 )           AS MGR_3_CADDR          -- 관리감독자3 전화번호
         , ORD_NO                -- 외주계약 발주번호
         , CHG_DGR               -- 외주계약 최종차수
         , VNDR_WRK_NM           -- 근로자대표명
         , VNDR_OMGR_NM          -- 업체소장명
         , PWD_NO_CHG_DT         -- 비밀번호 최종변경일자
         , RSET_YN               -- 비밀번호 초기화여부
         , CONT_SUM_AMT          -- 계약금액
         , RDRTR_PNM             -- 대표자명
         , TEL_NO                -- 대표연락처
         , VNDR_OMGR_DT          -- 현장소장선임일자
         , VNDR_SAFT_NM          -- 안전관리자명칭
         , VNDR_SAFT_DT          -- 안전관리자선임일자
         , CTP_CD
         , CTP_NM    -- 공종명칭
      FROM TQHA_VNDR A
     WHERE SIT_CD = p_SIT_CD
    ;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN 
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);
END ;
/

