,   p_TEL_NO                    TQHA_VNDR.TEL_NO                %TYPE       -- 대표연락처
,   p_VNDR_OMGR_DT              TQHA_VNDR.VNDR_OMGR_DT          %TYPE       -- 현장소장선임일자
,   p_VNDR_SAFT_NM              TQHA_VNDR.VNDR_SAFT_NM          %TYPE       -- 안전관리자명칭
,   p_VNDR_SAFT_DT              TQHA_VNDR.VNDR_SAFT_DT          %TYPE       -- 안전관리자선임일자
,   p_CONT_DT                   TQHA_VNDR.CONT_DT               %TYPE       -- 계약일자
,   p_CTP_CD                    TQHA_VNDR.CTP_CD                %TYPE       -- 공종
,   p_CTP_NM                    TQHA_VNDR.CTP_NM                %TYPE       -- 공종명
)
IS
    /**************************************************************************************************************************
      Purpose : 협력사목록 저장

      REVISIONS
      Ver      Date               Author                  Description
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2021/10/21 17:25:21                         최초생성

    **************************************************************************************************************************/

---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR2(200);            -- ERROR Message
    USER_EXCEPTION EXCEPTION;

    v_VNDR_SEQ TQHA_VNDR.VNDR_SEQ%TYPE;          -- 순번 변수 선언

    v_cnt   INTEGER := 0;           -- 협력업체코드 사용여부 확인
    v_cnt1  INTEGER := 0;           -- 협력업체코드 사용여부 확인
    v_cnt2  INTEGER := 0;           -- 협력업체코드 사용여부 확인
    v_cnt3  INTEGER := 0;           -- 협력업체코드 사용여부 확인
    v_cnt4  INTEGER := 0;           -- 협력업체코드 사용여부 확인
    v_cnt5  INTEGER := 0;           -- 협력업체코드 사용여부 확인
    v_cnt6  INTEGER := 0;           -- 담당자ID 중복체크

    v_COP_VNDR_NM   VARCHAR2(100);      -- 협력업체 명칭
    v_VNDR_PSN_ID   VARCHAR2(20);       -- 사용자ID 자동 생성용.

BEGIN
    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 필수입력 필드  Check  ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_SIT_CD IS NULL)  THEN
        ERR_MSG := '현장코드는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_CUST_CD IS NULL)  THEN
        ERR_MSG := '업체코드는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_VNDR_SEQ IS NULL AND p_WRK_TP <> 'I')  THEN
        ERR_MSG := '업체순번는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Process 선행조건 Check ]
    ---------------------------------------------------------------------------------------------------------------------------
    --  협력업체 사용 여부( 5/23 현장코드 추가 )
    IF p_WRK_TP = 'D' THEN

        -- 2024/04/24 화성에서 안전 위험성평가 모듈 미사용으로 주석처리
        -- 위험성평가 대상업체
        SELECT nvl(COUNT(CUST_CD),0)
          INTO v_cnt
          FROM TQHB_RISK_VNDR
         WHERE SIT_CD       = p_SIT_CD
           AND CUST_CD      = p_CUST_CD
           AND VNDR_SEQ     = p_VNDR_SEQ
        ;

        --추가위험발굴
         SELECT nvl(COUNT(CUST_CD),0)
          INTO v_cnt1
          FROM TQHA_ADDRISK_ORD
         WHERE SIT_CD       = p_SIT_CD
           AND CUST_CD      = p_CUST_CD
           AND VNDR_SEQ     = p_VNDR_SEQ
        ;

        -- 품질 부적합보고서
        SELECT nvl(COUNT(CUST_CD),0)
          INTO v_cnt2
          FROM TQHA_NCR_REP
         WHERE SIT_CD       = p_SIT_CD
           AND CUST_CD      = p_CUST_CD
           AND VNDR_SEQ     = p_VNDR_SEQ
        ;
--
--        IF v_cnt2 < 1 THEN
--             -- 안전작업 허가요청
--            SELECT nvl(COUNT(CUST_CD),0)
--              INTO v_cnt3
--              FROM TQHA_SAFE_PERREQ
--             WHERE SIT_CD       = p_SIT_CD
--               AND CUST_CD      = p_CUST_CD
--               AND VNDR_SEQ     = p_VNDR_SEQ
--            ;
--        END IF;
--
--        IF v_cnt3 < 1 THEN
--            -- 안전 부적합보고서
--            SELECT nvl(COUNT(CUST_CD),0)
--              INTO v_cnt4
--              FROM TQHA_NCR_REP
--             WHERE SIT_CD       = p_SIT_CD
--               AND CUST_CD      = p_CUST_CD
--               AND VNDR_SEQ     = p_VNDR_SEQ
--            ;
--        END IF;

        -- 안전관리비 월별실적(협력업체용)
        SELECT nvl(COUNT(CUST_CD),0)
          INTO v_cnt4
          FROM TQHA_SAFECOST_ARSLT_CO
         WHERE SIT_CD       = p_SIT_CD
           AND CUST_CD      = p_CUST_CD
           AND VNDR_SEQ     = p_VNDR_SEQ
        ;

        -- 안전관리비 월별실적갑지(협력업체용)
        SELECT nvl(COUNT(CUST_CD),0)
          INTO v_cnt5
          FROM TQHA_SAFECOST_MMARSLT_CO
         WHERE SIT_CD       = p_SIT_CD
           AND CUST_CD      = p_CUST_CD
           AND VNDR_SEQ     = p_VNDR_SEQ
        ;

         -- 단위작업 코드 Validation
        IF (v_cnt + v_cnt1 + v_cnt2 + v_cnt3 + v_cnt5 + v_cnt4 ) > 0 THEN
            SELECT CASE WHEN v_cnt > 0 THEN '위험성평가 대상업체'
			            WHEN v_cnt1 > 0 THEN '추가위험발굴지시'
			            WHEN v_cnt2 > 0 THEN '품질 부적합보고서'
            			WHEN v_cnt4 > 0 THEN '안전관리비 사용내역'
            			WHEN v_cnt5 > 0 THEN '안전관리비 월별실적'
            		END 
              INTO v_COP_VNDR_NM
              FROM TQHA_VNDR
             WHERE SIT_CD       = p_SIT_CD
               AND CUST_CD      = p_CUST_CD
               AND VNDR_SEQ     = p_VNDR_SEQ
            ;

            ERR_MSG := v_COP_VNDR_NM || ' 에서 협력업체를 사용하여 삭제할 수 없습니다. ';
            RAISE USER_EXCEPTION;
        END IF;
    END IF;


--    IF (p_WRK_TP ='I') THEN
--        -- 담당자ID 중복체크 확인
--        SELECT COUNT(*) AS CNT
--          INTO v_cnt6
--          FROM TQHA_VNDR
--         WHERE VNDR_PSN_ID = p_VNDR_PSN_ID;
--
--        IF v_cnt6 > 0 THEN
--            ERR_MSG := '"' || p_VNDR_PSN_ID || '" 은(는) 이미 사용중인 ID입니다. ID를 다시 입력해주시기 바랍니다.';
--            RAISE USER_EXCEPTION;
--        END IF;
--    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Business Process ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_WRK_TP ='D') THEN

        DELETE
          FROM TQHA_VNDR
         WHERE SIT_CD       = p_SIT_CD      -- 현장코드
           AND CUST_CD      = p_CUST_CD     -- 업체코드
           AND VNDR_SEQ     = p_VNDR_SEQ    -- 업체순번
        ;

    -------------------------------------------------------------------------------------
    -- 
    ELSIF (p_WRK_TP ='U') THEN

        UPDATE TQHA_VNDR
           SET VNDR_NM              = p_VNDR_NM                 -- 공사명
             , VNDR_STR_DT          = p_VNDR_STR_DT             -- 공사시작일
             , VNDR_END_DT          = p_VNDR_END_DT             -- 공사종료일
             -- ,VNDR_PSN_ID        = p_VNDR_PSN_ID             -- 담당자 ID 개인정보 암호
             , VNDR_PSN_NM          = p_VNDR_PSN_NM             -- 담당자 명 개인정보 암호
             -- 개인정보 암호 2023/11/27 수정예정
             --              ,VNDR_PSN_PWD         = SYS.PKG_HASHCRYPTO.encryptHash(p_VNDR_PSN_PWD)        -- 담당자 PW 개인정보 암호
             --              ,VNDR_PSN_EMAIL       = sys.pkg_crypto_enc.encrypt(p_VNDR_PSN_EMAIL)          -- 담당자 이메일 개인정보 암호
             --              ,VNDR_PSN_CADDR       = sys.pkg_crypto_enc.encrypt(p_VNDR_PSN_CADDR)          -- 담당자 연락처 개인정보 암호
             , VNDR_PSN_PWD         = p_VNDR_PSN_PWD            -- 담당자 PW 개인정보 암호
             , VNDR_PSN_EMAIL       = p_VNDR_PSN_EMAIL          -- 담당자 이메일 개인정보 암호
             , VNDR_PSN_CADDR       = p_VNDR_PSN_CADDR          -- 담당자 연락처 개인정보 암호
             ----------------------------------------------
             , MGR_1                = p_MGR_1                   -- 관리감독자1
             , MGR_2                = p_MGR_2                   -- 관리감독자2
             , MGR_3                = p_MGR_3                   -- 관리감독자3
             , ORD_NO               = p_ORD_NO                  -- 발주번호
             , CHG_DGR              = p_CHG_DGR                 -- 변경차수
             , VNDR_WRK_NM          = p_VNDR_WRK_NM             -- 근로자대표명
             , VNDR_OMGR_NM         = p_VNDR_OMGR_NM            -- 업체소장명
             , PWD_NO_CHG_DT        = p_PWD_NO_CHG_DT           -- 비밀번호 최종변경일자
             , RSET_YN              = p_RSET_YN                 -- 비밀번호 초기화여부
             , CONT_SUM_AMT         = p_CONT_SUM_AMT            -- 계약금액
             , RDRTR_PNM            = p_RDRTR_PNM               -- 대표자명
             , TEL_NO               = p_TEL_NO                  -- 대표연락처
             , VNDR_OMGR_DT         = p_VNDR_OMGR_DT            -- 현장소장선임일자
             , VNDR_SAFT_NM         = p_VNDR_SAFT_NM            -- 안전관리자명칭
             , VNDR_SAFT_DT         = p_VNDR_SAFT_DT            -- 안전관리자선임일자
             , CONT_DT              = p_CONT_DT                 -- 계약일자
             , CTP_CD               = p_CTP_CD
             , CTP_NM               = p_CTP_NM
             , UPD_ID               = p_WRK_ID                  -- 수정ID
             , UPD_DTM              = SYSDATE()                 -- 수정일시
             , UPD_IP               = p_WRK_IP                  -- 수정IP
         WHERE SIT_CD               = p_SIT_CD                  -- 현장코드
           AND CUST_CD              = p_CUST_CD                 -- 업체코드
           AND VNDR_SEQ             = p_VNDR_SEQ                -- 업체순번
        ;

    -------------------------------------------------------------------------------------
    -- 
    ELSE

        -- 업체순번 생성
        SELECT NVL((MAX(VNDR_SEQ) + 1), '1')
          INTO v_VNDR_SEQ
          FROM TQHA_VNDR
         WHERE SIT_CD   = p_SIT_CD      -- 현장코드
           AND CUST_CD  = p_CUST_CD     -- 업체코드
        ;

        -- ID 생성.  년도 + 순번5자리  10자리.
        SELECT 'U' || TO_CHAR(SYSDATE, 'YYYY')
               || SUBSTR(LPAD(TO_CHAR(TO_NUMBER(NVL(MAX(SUBSTR(VNDR_PSN_ID, 6, 5)), '0')) + 1), 5,  '0'), -5)
          INTO v_VNDR_PSN_ID
          FROM TQHA_VNDR
         WHERE VNDR_PSN_ID LIKE 'U' || TO_CHAR(SYSDATE, 'YYYY') ||'%'
        ;

        INSERT 
          INTO TQHA_VNDR
             ( SIT_CD                   -- 현장코드
             , CUST_CD                  -- 업체코드
             , VNDR_SEQ                 -- 업체순번
             , VNDR_NM                  -- 공사명
             , VNDR_STR_DT              -- 공사시작일
             , VNDR_END_DT              -- 공사종료일
             , VNDR_PSN_ID              -- 개인정보 암호
             -- 개인정보 암호 2023/11/27 수정예정
             , VNDR_PSN_PWD             -- 개인정보 암호
             , VNDR_PSN_NM              -- 개인정보 암호
             , VNDR_PSN_EMAIL           -- 개인정보 암호
             , VNDR_PSN_CADDR           -- 개인정보 암호
             , MGR_1                    -- 관리감독자1
             , MGR_2                    -- 관리감독자2
             , MGR_3                    -- 관리감독자3
             , ORD_NO                   -- 발주번호
             , CHG_DGR                  -- 변경차수
             , VNDR_WRK_NM              -- 근로자대표명
             , VNDR_OMGR_NM             -- 업체소장명
             , PWD_NO_CHG_DT            -- 비밀번호 최종변경일자
             , RSET_YN                  -- 비밀번호 초기화여부
             , CONT_SUM_AMT             -- 계약금액
             , RDRTR_PNM                -- 대표자명
             , TEL_NO                   -- 대표연락처
             , VNDR_OMGR_DT             -- 현장소장선임일자
             , VNDR_SAFT_NM             -- 안전관리자명칭
             , VNDR_SAFT_DT             -- 안전관리자선임일자
             , CONT_DT                  -- 계약일자
             , CTP_CD
             , CTP_NM
             , IPT_ID                   -- 입력ID
             , IPT_DTM                  -- 입력일시
             , IPT_IP                   -- 입력IP
             , UPD_ID                   -- 수정ID
             , UPD_DTM                  -- 수정일시
             , UPD_IP                   -- 수정IP
             )
        VALUES 
             ( p_SIT_CD                 -- 현장코드
             , p_CUST_CD                -- 업체코드
             , v_VNDR_SEQ               -- 업체순번
             , p_VNDR_NM                -- 공사명
             , p_VNDR_STR_DT            -- 공사시작일
             , p_VNDR_END_DT            -- 공사종료일
             --,p_VNDR_PSN_ID           -- 개인정보 암호
             , v_VNDR_PSN_ID            -- 
             -- 개인정보 암호 2023/11/27 수정예정
             -- , SYS.PKG_HASHCRYPTO.encryptHash(p_VNDR_PSN_PWD)      --개인정보 암호
             , p_VNDR_PSN_PWD           -- 개인정보 암호
             , p_VNDR_PSN_NM            -- 개인정보 암호
             -- , sys.pkg_crypto_enc.encrypt(p_VNDR_PSN_EMAIL)        --개인정보 암호
             , p_VNDR_PSN_EMAIL         -- 개인정보 암호
             -- , sys.pkg_crypto_enc.encrypt(p_VNDR_PSN_CADDR)        --개인정보 암호
             , p_VNDR_PSN_CADDR         -- 개인정보 암호
             , p_MGR_1                  -- 관리감독자1
             , p_MGR_2                  -- 관리감독자2
             , p_MGR_3                  -- 관리감독자3
             , p_ORD_NO                 -- 발주번호
             , p_CHG_DGR                -- 변경차수
             , p_VNDR_WRK_NM            -- 근로자대표명
             , p_VNDR_OMGR_NM           -- 업체소장명
             , p_PWD_NO_CHG_DT          -- 비밀번호 최종변경일자
             , p_RSET_YN                -- 비밀번호 초기화여부
             , p_CONT_SUM_AMT           -- 계약금액
             , p_RDRTR_PNM              -- 대표자명
             , p_TEL_NO                 -- 대표연락처
             , p_VNDR_OMGR_DT           -- 현장소장선임일자
             , p_VNDR_SAFT_NM           -- 안전관리자명칭
             , p_VNDR_SAFT_DT           -- 안전관리자선임일자
             , p_CONT_DT                -- 계약일자
             , p_CTP_CD
             , p_CTP_NM
             , p_WRK_ID                 -- 입력ID
             , SYSDATE()                -- 입력일시
             , p_WRK_IP                 -- 입력IP
             , p_WRK_ID                 -- 수정ID
             , SYSDATE()                -- 수정일시
             , p_WRK_IP                 -- 수정IP
             )
        ;
    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 5. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);

END ;
/

-- PQHA_WEEK_WORK_GET_HAZARD_S (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_WEEK_WORK_GET_HAZARD_S"
                            (p_WRK_TP  VARCHAR2 :='U'                                     -- UPDATE FLAG( I: ISNERT, U:UPDATE, D:DELTE)
                            ,p_WRK_ID  VARCHAR2                                           -- 사용자 ID 
                            ,p_WRK_IP  VARCHAR2                                           -- 사용자 IP 
                            ,p_RPTING_DT TQHA_WEEK_WORK_LOG_HO.RPTING_DT%TYPE        -- 보고일자
                            ,p_WEK_STR_DT TQHA_WEEK_WORK_LOG_HO.WEK_STR_DT%TYPE
                            ,p_WEK_END_DT TQHA_WEEK_WORK_LOG_HO.WEK_END_DT%TYPE
                            ) 
IS 
    /**************************************************************************************************************************
      Purpose : 본사주간업무보고 주요위험작업 가져오기

      REVISIONS
      Ver      Date               Author                  Description 
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2026/06/01 10:57:51                         최초생성

    /**************************************************************************************************************************/


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR2(200);            -- ERROR Message
    USER_EXCEPTION EXCEPTION;
	
    v_SEQ NUMBER;
    v_CNT NUMBER;
BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 필수입력 필드  Check  ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_WEK_STR_DT IS NULL)  THEN
        ERR_MSG := '관리기간시작일자는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;
    
    IF (p_WEK_END_DT IS NULL)  THEN
        ERR_MSG := '관리기간시작일자는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;
    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Process 선행조건 Check ]
    ---------------------------------------------------------------------------------------------------------------------------
    SELECT COUNT(1) INTO v_CNT 
	FROM TQHA_WEEK_WORK_LOG_PLAN_HO
	WHERE RPTING_DT = p_RPTING_DT;
    
    IF (v_CNT > 0)  THEN
        ERR_MSG := '등록된 주요위험작업이 있어 가져올 수 없습니다.';
        RAISE USER_EXCEPTION;
    END IF;
    
    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Business Process ]
    ---------------------------------------------------------------------------------------------------------------------------
    INSERT INTO TQHA_WEEK_WORK_LOG_PLAN_HO
				   ( RPTING_DT               --보고일자
				    ,PLN_SEQ                 --계획순번
				    ,SIT_CD                  --현장코드
				    ,WRK_SCH_STR_DT          --작업예정시작일자
				    ,WRK_SCH_END_DT          --작업예정종료일자
				    ,WRK_CTS                 --작업내용
				    ,TOT_PROCRT              --총공정율
				    ,RMKS                    --비고
				    ,IPT_ID                  --입력ID
				    ,IPT_DTM                 --입력일시
				    ,IPT_IP                  --입력IP
				    ,UPD_ID                  --수정ID
				    ,UPD_DTM                 --수정일시
				    ,UPD_IP                  --수정IP
				    )
		     SELECT p_RPTING_DT              --보고일자
  		           ,ROWNUM
				   ,A.SIT_CD
			       ,A.WRK_SCH_STR_DT         --작업예정시작일자
			       ,A.WRK_SCH_END_DT         --작업예정종료일자	       
			       ,A.WRK_CTS                --작업내용
			       ,B.TOT_PROCRT             --총공정율
			       ,''
			       ,p_WRK_ID                --입력ID 
		           ,SYSDATE()               --입력일시
		           ,p_WRK_IP                --입력IP
		           ,p_WRK_ID                --수정ID
		           ,SYSDATE()               --수정일시
		           ,p_WRK_IP
			FROM TQHA_WEEK_WORK_LOG_PLAN A
			    ,TQHA_WEEK_WORK_LOG B
			WHERE A.SIT_CD = B.SIT_CD
			  AND A.RPTING_DT = B.RPTING_DT
			  --AND A.OPT_YN = '1'
			  AND B.APRV_NO IS NOT NULL
			  AND (
			          (A.WRK_SCH_STR_DT >= p_WEK_STR_DT AND A.WRK_SCH_END_DT <= p_WEK_END_DT)
			       OR (A.WRK_SCH_STR_DT >= p_WEK_STR_DT AND A.WRK_SCH_STR_DT <= p_WEK_END_DT AND A.WRK_SCH_END_DT IS NULL)
			      )
			  ;	

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 5. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN 
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);
END ;
/

-- PQHA_WEEK_WORK_LOG_HO_Q (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_WEEK_WORK_LOG_HO_Q"
(
      p_WRK_TP  VARCHAR2 DEFAULT 'Q'                                                      -- FLAG( Q: SELECT )
     ,p_WEK_RPTING_TTL TQHA_WEEK_WORK_LOG_HO.WEK_RPTING_TTL%TYPE                                  -- 보고시작일자
     ,p_RPTING_STR_DT TQHA_WEEK_WORK_LOG_HO.RPTING_DT%TYPE                                  -- 보고시작일자
     ,p_RPTING_END_DT TQHA_WEEK_WORK_LOG_HO.RPTING_DT%TYPE                                  -- 보고종료일자
     ,p_WEK_STR_DT TQHA_WEEK_WORK_LOG_HO.WEK_STR_DT%TYPE                                    -- 주간시작일자
     ,p_WEK_END_DT TQHA_WEEK_WORK_LOG_HO.WEK_END_DT%TYPE                                    -- 주간종료일자
     ,RTN_CURSOR OUT SYS_REFCURSOR
)
IS 
    /**************************************************************************************************************************
      Purpose : 

      REVISIONS
      Ver      Date               Author                  Description 
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2026/06/01 09:31:33                         최초생성

    /**************************************************************************************************************************/


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR2(200);            -- ERROR Message
    USER_EXCEPTION EXCEPTION;


BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 수행전 Check Logic ]
    ---------------------------------------------------------------------------------------------------------------------------


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Logic 처리
    ---------------------------------------------------------------------------------------------------------------------------

    OPEN RTN_CURSOR FOR
    SELECT  RPTING_DT                 --보고일자
           ,WEK_STR_DT                 --주간시작일자
           ,WEK_END_DT                 --주간종료일자
           ,WEK_RPTING_TTL                 --주간보고제목
           ,TOT_PROCRT                 --총공정율
           ,RMKS                    --비고
      FROM TQHA_WEEK_WORK_LOG_HO
     WHERE WEK_RPTING_TTL LIKE p_WEK_RPTING_TTL || '%'                 
      AND (RPTING_DT BETWEEN NVL(p_RPTING_STR_DT, '19000101') AND NVL(p_RPTING_END_DT, '99991231'))
      OR (WEK_STR_DT >= NVL(p_WEK_STR_DT, '19000101') AND WEK_END_DT <= NVL(p_WEK_END_DT, '19000101'))
      
    ORDER BY RPTING_DT DESC;
           
    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN 
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);
END ;
/

-- PQHA_WEEK_WORK_LOG_HO_S (PROCEDURE, VALID)
