                            ,p_RPTING_DT TQHA_WEEK_WORK_LOG_HO.RPTING_DT%TYPE             -- 보고일자
                            ,p_WEK_STR_DT TQHA_WEEK_WORK_LOG_HO.WEK_STR_DT%TYPE           -- 주간시작일자
                            ,p_WEK_END_DT TQHA_WEEK_WORK_LOG_HO.WEK_END_DT%TYPE           -- 주간종료일자
                            ,p_WEK_RPTING_TTL TQHA_WEEK_WORK_LOG_HO.WEK_RPTING_TTL%TYPE   -- 주간보고제목
                            )
IS 
    /**************************************************************************************************************************
      Purpose : 본사주간업무보고

      REVISIONS
      Ver      Date               Author                  Description 
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2026/06/01 09:38:01                         최초생성

    /**************************************************************************************************************************/


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR2(200);            -- ERROR Message
    USER_EXCEPTION EXCEPTION;


BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 필수입력 필드  Check  ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_RPTING_DT IS NULL)  THEN
        ERR_MSG := '보고일자는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Process 선행조건 Check ]
    ---------------------------------------------------------------------------------------------------------------------------



    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Business Process ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_WRK_TP ='D') THEN
    
	    DELETE 
          FROM TQHA_WEEK_WORK_LOG_PLAN_HO
         WHERE RPTING_DT = p_RPTING_DT;       --보고일자;
           
        DELETE 
          FROM TQHA_WEEK_WORK_LOG_HO
         WHERE RPTING_DT = p_RPTING_DT;      --보고일자

    ELSIF (p_WRK_TP ='U') THEN
        UPDATE TQHA_WEEK_WORK_LOG_HO
           SET WEK_STR_DT           = p_WEK_STR_DT              --주간시작일자
              ,WEK_END_DT           = p_WEK_END_DT              --주간종료일자
              ,WEK_RPTING_TTL       = p_WEK_RPTING_TTL          --주간보고제목
              ,UPD_ID               = p_WRK_ID                  --수정ID 
              ,UPD_DTM              = SYSDATE()                 --수정일시
              ,UPD_IP               = p_WRK_IP                  --수정IP
         WHERE RPTING_DT = p_RPTING_DT;      --보고일자
    ELSE 
        INSERT INTO TQHA_WEEK_WORK_LOG_HO
                   ( RPTING_DT               --보고일자
                    ,WEK_STR_DT              --주간시작일자
                    ,WEK_END_DT              --주간종료일자
                    ,WEK_RPTING_TTL          --주간보고제목
                    ,IPT_ID                  --입력ID
                    ,IPT_DTM                 --입력일시
                    ,IPT_IP                  --입력IP
                    ,UPD_ID                  --수정ID
                    ,UPD_DTM                 --수정일시
                    ,UPD_IP                  --수정IP
                    )
             VALUES (p_RPTING_DT             --보고일자
                    ,p_WEK_STR_DT            --주간시작일자
                    ,p_WEK_END_DT            --주간종료일자
                    ,p_WEK_RPTING_TTL        --주간보고제목
                    ,p_WRK_ID                --입력ID 
                    ,SYSDATE()               --입력일시
                    ,p_WRK_IP                --입력IP
                    ,p_WRK_ID                --수정ID
                    ,SYSDATE()               --수정일시
                    ,p_WRK_IP);              --수정IP
    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 5. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN 
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);
END ;
