-- PQHA_WEEK_WORK_LOG_PLAN_HO_Q (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_WEEK_WORK_LOG_PLAN_HO_Q"
(
      p_WRK_TP  VARCHAR2 DEFAULT 'Q'                                                       -- FLAG( Q: SELECT )
     ,p_RPTING_DT TQHA_WEEK_WORK_LOG_PLAN_HO.RPTING_DT%TYPE                               -- 보고일자
     ,RTN_CURSOR OUT SYS_REFCURSOR
)
IS  
    /**************************************************************************************************************************
      Purpose : 본사주간업무보고 주요위험작업

      REVISIONS
      Ver      Date               Author                  Description 
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2026/06/01 10:56:24                         최초생성

    /**************************************************************************************************************************/


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR2(200);            -- ERROR Message
    USER_EXCEPTION EXCEPTION;


BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 수행전 Check Logic ]
    ---------------------------------------------------------------------------------------------------------------------------


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Logic 처리
    ---------------------------------------------------------------------------------------------------------------------------

    OPEN RTN_CURSOR FOR
	    SELECT A.RPTING_DT                 -- 보고일자
		     , A.PLN_SEQ                   -- 계획순번
		     , A.SIT_CD                    -- 현장코드
		     , ( SELECT DEPT_NM FROM TCOZ_DEPT_INFO WHERE DEPT_CD = A.SIT_CD ) AS SIT_NM -- 현장명칭
		     -- 현장별 정렬 기준(WRK_SCH_STR_DT, WRK_SCH_END_DT)에 따른 첫 번째 행 여부
		     , CASE 
		            WHEN ROW_NUMBER() OVER(PARTITION BY A.SIT_CD ORDER BY A.WRK_SCH_STR_DT, A.WRK_SCH_END_DT) = 1 
		            THEN 1 
		            ELSE 0 
		       END AS SIT_START_YN
		     , A.WRK_SCH_STR_DT            -- 작업예정시작일자
		     , A.WRK_SCH_END_DT            -- 작업예정종료일자
		     , A.WRK_CTS                   -- 작업내용
		     , A.RMKS                      -- 비고
		     , A.TOT_PROCRT
		     , A.IMPTC_YN
		  FROM TQHA_WEEK_WORK_LOG_PLAN_HO A
		 WHERE A.RPTING_DT = p_RPTING_DT
	 ORDER BY A.SIT_CD
	        , A.WRK_SCH_STR_DT
	        , A.WRK_SCH_END_DT

           ;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN 
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);
END ;
/

-- PQHA_WEEK_WORK_LOG_PLAN_HO_S (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_WEEK_WORK_LOG_PLAN_HO_S"
                            (p_WRK_TP  VARCHAR2 :='U'                                     -- UPDATE FLAG( I: ISNERT, U:UPDATE, D:DELTE)
                            ,p_WRK_ID  VARCHAR2                                           -- 사용자 ID 
                            ,p_WRK_IP  VARCHAR2                                           -- 사용자 IP 
                            ,p_RPTING_DT TQHA_WEEK_WORK_LOG_PLAN_HO.RPTING_DT%TYPE        -- 보고일자
                            ,p_PLN_SEQ TQHA_WEEK_WORK_LOG_PLAN_HO.PLN_SEQ%TYPE            -- 계획순번
                            ,p_SIT_CD TQHA_WEEK_WORK_LOG_PLAN_HO.SIT_CD%TYPE              -- 현장코드
                            ,p_WRK_SCH_STR_DT TQHA_WEEK_WORK_LOG_PLAN_HO.WRK_SCH_STR_DT%TYPE-- 작업예정시작일자
                            ,p_WRK_SCH_END_DT TQHA_WEEK_WORK_LOG_PLAN_HO.WRK_SCH_END_DT%TYPE-- 작업예정종료일자
                            ,p_WRK_CTS TQHA_WEEK_WORK_LOG_PLAN_HO.WRK_CTS%TYPE            -- 작업내용
                            ,p_TOT_PROCRT TQHA_WEEK_WORK_LOG_PLAN_HO.TOT_PROCRT%TYPE           -- 총공정율
                            ,p_RMKS TQHA_WEEK_WORK_LOG_PLAN_HO.RMKS%TYPE                 -- 비고
                            ,p_IMPTC_YN TQHA_WEEK_WORK_LOG_PLAN_HO.IMPTC_YN%TYPE                 -- 중요여부
                            )
IS 
    /**************************************************************************************************************************
      Purpose : 본사주간업무보고 주요위험작업

      REVISIONS
      Ver      Date               Author                  Description 
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2026/06/01 10:57:51                         최초생성

    /**************************************************************************************************************************/


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR2(200);            -- ERROR Message
    USER_EXCEPTION EXCEPTION;

	v_SEQ NUMBER;
BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 필수입력 필드  Check  ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_RPTING_DT IS NULL)  THEN
        ERR_MSG := '보고일자는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_WRK_TP != 'I' AND p_PLN_SEQ IS NULL)  THEN
        ERR_MSG := '계획순번는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_SIT_CD IS NULL)  THEN
        ERR_MSG := '현장코드는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Process 선행조건 Check ]
    ---------------------------------------------------------------------------------------------------------------------------
	SELECT NVL(MAX(PLN_SEQ), 0) + 1 INTO v_SEQ 
	FROM TQHA_WEEK_WORK_LOG_PLAN_HO
	WHERE RPTING_DT = p_RPTING_DT;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Business Process ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_WRK_TP ='D') THEN
        DELETE 
          FROM TQHA_WEEK_WORK_LOG_PLAN_HO
         WHERE RPTING_DT = p_RPTING_DT       --보고일자
           AND PLN_SEQ = p_PLN_SEQ;        --계획순번

    ELSIF (p_WRK_TP ='U') THEN
        UPDATE TQHA_WEEK_WORK_LOG_PLAN_HO
           SET SIT_CD               = p_SIT_CD                  --현장코드
              ,WRK_SCH_STR_DT       = p_WRK_SCH_STR_DT          --작업예정시작일자
              ,WRK_SCH_END_DT       = p_WRK_SCH_END_DT          --작업예정종료일자
              ,WRK_CTS              = p_WRK_CTS                 --작업내용
              ,TOT_PROCRT           = p_TOT_PROCRT              --총공정율
              ,IMPTC_YN             = p_IMPTC_YN
              ,RMKS                 = p_RMKS                    --비고
              ,UPD_ID               = p_WRK_ID                  --수정ID 
              ,UPD_DTM              = SYSDATE()                 --수정일시
              ,UPD_IP               = p_WRK_IP                  --수정IP
         WHERE RPTING_DT = p_RPTING_DT       --보고일자
           AND PLN_SEQ = p_PLN_SEQ;        --계획순번
    ELSE 
        INSERT INTO TQHA_WEEK_WORK_LOG_PLAN_HO
                   ( RPTING_DT               --보고일자
                    ,PLN_SEQ                 --계획순번
                    ,SIT_CD                  --현장코드
                    ,WRK_SCH_STR_DT          --작업예정시작일자
                    ,WRK_SCH_END_DT          --작업예정종료일자
                    ,WRK_CTS                 --작업내용
                    ,TOT_PROCRT              --총공정율
                    ,IMPTC_YN
                    ,RMKS                    --비고
                    ,IPT_ID                  --입력ID
                    ,IPT_DTM                 --입력일시
                    ,IPT_IP                  --입력IP
                    ,UPD_ID                  --수정ID
                    ,UPD_DTM                 --수정일시
                    ,UPD_IP                  --수정IP
                    )
             VALUES (p_RPTING_DT             --보고일자
                    ,v_SEQ                   --계획순번
                    ,p_SIT_CD                --현장코드
                    ,p_WRK_SCH_STR_DT        --작업예정시작일자
                    ,p_WRK_SCH_END_DT        --작업예정종료일자
                    ,p_WRK_CTS               --작업내용
                    ,p_TOT_PROCRT            --총공정율
                    ,p_IMPTC_YN
                    ,p_RMKS                  --비고
                    ,p_WRK_ID                --입력ID 
                    ,SYSDATE()               --입력일시
                    ,p_WRK_IP                --입력IP
                    ,p_WRK_ID                --수정ID
                    ,SYSDATE()               --수정일시
                    ,p_WRK_IP);              --수정IP
    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 5. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN 
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);
END ;
/

