           ,A.PHOTO_LOC_2                 --사진설명1
           ,A.PHOTO_GRP3                 --첨부파일그룹사진2
           ,A.PHOTO_DESC_3                 --사진설명2
           ,A.PHOTO_LOC_3                 --사진설명1
           ,A.PHOTO_GRP4                 --첨부파일그룹사진2
           ,A.PHOTO_DESC_4                 --사진설명2
           ,A.PHOTO_LOC_4                 --사진설명1
