           ,A.PHOTO_DESC_5                 --사진설명2
           ,A.PHOTO_LOC_5                 --사진설명1
           ,A.PHOTO_GRP6                 --첨부파일그룹사진2
           ,A.PHOTO_DESC_6                 --사진설명2
           ,A.PHOTO_LOC_6                 --사진설명1
           ,A.ETC_MATT                 --기타사항
           ,A.GF_YN                 --갱폼설치여부
