                            ,p_TCRN_DMT_CNT TQHA_WEEK_WORK_LOG.TCRN_DMT_CNT%TYPE          -- 타워크레인해체개수
                            ,p_HST_INST_YN TQHA_WEEK_WORK_LOG.HST_INST_YN%TYPE            -- 호이스트설치여부
                            ,p_HST_INST_CNT TQHA_WEEK_WORK_LOG.HST_INST_CNT%TYPE          -- 호이스트설치개수
                            ,p_HST_DMT_CNT TQHA_WEEK_WORK_LOG.HST_DMT_CNT%TYPE            -- 호이스트해체개수
                            ,p_ETC_INST_MATT TQHA_WEEK_WORK_LOG.ETC_INST_MATT%TYPE            
                            ,p_APRV_NO TQHA_WEEK_WORK_LOG.APRV_NO%TYPE)                   -- 결재번호
IS 
    /**************************************************************************************************************************
      Purpose : 현장주간업무보고

      REVISIONS
      Ver      Date               Author                  Description 
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2026/05/13 15:15:16                         최초생성

    /**************************************************************************************************************************/


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR(200);             -- ERROR Message
    USER_EXCEPTION EXCEPTION;

	v_SEQ NUMBER;
BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 필수입력 필드  Check  ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_SIT_CD IS NULL)  THEN
        ERR_MSG := '현장코드는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_RPTING_DT IS NULL)  THEN
        ERR_MSG := '보고일자는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;
    
    IF (p_WEK_STR_DT > p_WEK_END_DT)  THEN
        ERR_MSG := '주간 종료일자가 시작일자보다 큽니다.';
        RAISE USER_EXCEPTION;
    END IF;
    
    IF (p_WEK_STR_DT IS NOT NULL AND p_WEK_END_DT IS NOT NULL)  THEN
    	IF (p_WEK_STR_DT > p_WEK_END_DT)  THEN
	        ERR_MSG := '주간 종료일자가 시작일자보다 큽니다.';
	        RAISE USER_EXCEPTION;
	    END IF;    
    END IF;
    
    IF (p_SCNST_DT IS NOT NULL AND p_CCNST_DT IS NOT NULL)  THEN
    	IF (p_SCNST_DT > p_CCNST_DT)  THEN
	        ERR_MSG := '착공일자가 준공일자보다 큽니다.';
	        RAISE USER_EXCEPTION;
	    END IF;    
    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Process 선행조건 Check ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_WRK_TP = 'I') THEN
	 	 SELECT COUNT(1) INTO v_SEQ 
	     FROM TQHA_WEEK_WORK_LOG
	     WHERE SIT_CD = p_SIT_CD
	     AND RPTING_DT = p_RPTING_DT;
    
	    IF (v_SEQ > 0) THEN
	    	ERR_MSG := '이미 등록된 보고일자 입니다.';
	        RAISE USER_EXCEPTION;
	    END IF;
   	END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Business Process ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_WRK_TP ='D') THEN
    
	    DELETE 
          FROM TQHA_WEEK_WORK_LOG_PLAN
         WHERE SIT_CD = p_SIT_CD          --현장코드
           AND RPTING_DT = p_RPTING_DT;       --보고일자
           
        DELETE 
          FROM TQHA_WEEK_WORK_LOG
         WHERE SIT_CD = p_SIT_CD          --현장코드
           AND RPTING_DT = p_RPTING_DT;      --보고일자

    ELSIF (p_WRK_TP ='U') THEN
        UPDATE TQHA_WEEK_WORK_LOG
           SET WEK_STR_DT           = p_WEK_STR_DT              --주간시작일자
              ,WEK_END_DT           = p_WEK_END_DT              --주간종료일자
              ,SCNST_DT             = p_SCNST_DT                --착공일자
              ,CCNST_DT             = p_CCNST_DT                --준공일자
              ,TOT_PROCRT           = p_TOT_PROCRT              --총공정율
              ,TOT_DISS_CNT         = p_TOT_DISS_CNT            --총재해건수
              ,DEAD_CNT             = p_DEAD_CNT                --사망건수
              ,INJ_CNT              = p_INJ_CNT                 --부상건수
              ,MAIN_CTP_DTLS        = p_MAIN_CTP_DTLS           --주요공종내역
              ,APRP_SAFT_MCHR_AMT   = p_APRP_SAFT_MCHR_AMT      --계상안전관리비금액
              ,SAFT_MCHR_USE_AMT    = p_SAFT_MCHR_USE_AMT       --안전관리비사용금액
              ,SAFT_MCHR_USE_RATE   = p_SAFT_MCHR_USE_RATE      --안전관리비사용율
              ,PHOTO_GRP1           = p_PHOTO_GRP1              --첨부파일그룹사진1
              ,PHOTO_DESC_1         = p_PHOTO_DESC_1            --사진설명1
              ,PHOTO_LOC_1          = p_PHOTO_LOC_1             --사진설명1
              ,PHOTO_GRP2           = p_PHOTO_GRP2              --첨부파일그룹사진2
              ,PHOTO_DESC_2         = p_PHOTO_DESC_2            --사진설명2
              ,PHOTO_LOC_2          = p_PHOTO_LOC_2             --사진설명1
              ,PHOTO_GRP3           = p_PHOTO_GRP3              --첨부파일그룹사진2
              ,PHOTO_DESC_3         = p_PHOTO_DESC_3            --사진설명2
              ,PHOTO_LOC_3          = p_PHOTO_LOC_3             --사진설명1
              ,PHOTO_GRP4           = p_PHOTO_GRP4              --첨부파일그룹사진2
              ,PHOTO_DESC_4         = p_PHOTO_DESC_4            --사진설명2
              ,PHOTO_LOC_4          = p_PHOTO_LOC_4             --사진설명1
              ,PHOTO_GRP5           = p_PHOTO_GRP5              --첨부파일그룹사진2
              ,PHOTO_DESC_5         = p_PHOTO_DESC_5            --사진설명2
              ,PHOTO_LOC_5          = p_PHOTO_LOC_5             --사진설명1
              ,PHOTO_GRP6           = p_PHOTO_GRP6              --첨부파일그룹사진2
              ,PHOTO_DESC_6         = p_PHOTO_DESC_6            --사진설명2
              ,PHOTO_LOC_6          = p_PHOTO_LOC_6             --사진설명1
              ,ETC_MATT             = p_ETC_MATT                --기타사항
              ,GF_YN                = p_GF_YN                   --갱폼설치여부
              ,GF_INST_CNT          = p_GF_INST_CNT             --갱폼설치개수
              ,GF_DMT_CNT           = p_GF_DMT_CNT              --갱폼해체개수
              ,TCRN_INST_YN         = p_TCRN_INST_YN            --타워크레인설치여부
              ,TCRN_INST_CNT        = p_TCRN_INST_CNT           --타워크레인설치개수
              ,TCRN_DMT_CNT         = p_TCRN_DMT_CNT            --타워크레인해체개수
              ,HST_INST_YN          = p_HST_INST_YN             --호이스트설치여부
              ,HST_INST_CNT         = p_HST_INST_CNT            --호이스트설치개수
              ,HST_DMT_CNT          = p_HST_DMT_CNT             --호이스트해체개수
              ,ETC_INST_MATT        = p_ETC_INST_MATT             
              ,UPD_ID               = p_WRK_ID                  --수정ID 
              ,UPD_DTM              = SYSDATE()                 --수정일시
              ,UPD_IP               = p_WRK_IP                  --수정IP
         WHERE SIT_CD = p_SIT_CD          --현장코드
           AND RPTING_DT = p_RPTING_DT;      --보고일자
    ELSE 
    
        INSERT INTO TQHA_WEEK_WORK_LOG
                   ( SIT_CD                  --현장코드
                    ,RPTING_DT               --보고일자
                    ,WEK_STR_DT              --주간시작일자
                    ,WEK_END_DT              --주간종료일자
                    ,SCNST_DT                --착공일자
                    ,CCNST_DT                --준공일자
                    ,TOT_PROCRT              --총공정율
                    ,TOT_DISS_CNT            --총재해건수
                    ,DEAD_CNT                --사망건수
                    ,INJ_CNT                 --부상건수
                    ,MAIN_CTP_DTLS           --주요공종내역
                    ,APRP_SAFT_MCHR_AMT      --계상안전관리비금액
                    ,SAFT_MCHR_USE_AMT       --안전관리비사용금액
                    ,SAFT_MCHR_USE_RATE      --안전관리비사용율
                    ,PHOTO_GRP1              --첨부파일그룹사진1
                    ,PHOTO_DESC_1            --사진설명1
                    ,PHOTO_LOC_1             --사진설명1
                    ,PHOTO_GRP2              --첨부파일그룹사진2
                    ,PHOTO_DESC_2            --사진설명2
                    ,PHOTO_LOC_2             --사진설명1
                    ,PHOTO_GRP3              --첨부파일그룹사진2
                    ,PHOTO_DESC_3            --사진설명2
                    ,PHOTO_LOC_3             --사진설명1
                    ,PHOTO_GRP4              --첨부파일그룹사진2
                    ,PHOTO_DESC_4            --사진설명2
                    ,PHOTO_LOC_4             --사진설명1
                    ,PHOTO_GRP5              --첨부파일그룹사진2
                    ,PHOTO_DESC_5            --사진설명2
                    ,PHOTO_LOC_5             --사진설명1
                    ,PHOTO_GRP6              --첨부파일그룹사진2
                    ,PHOTO_DESC_6            --사진설명2
                    ,PHOTO_LOC_6             --사진설명1
                    ,ETC_MATT                --기타사항
                    ,GF_YN                   --갱폼설치여부
                    ,GF_INST_CNT             --갱폼설치개수
                    ,GF_DMT_CNT              --갱폼해체개수
                    ,TCRN_INST_YN            --타워크레인설치여부
                    ,TCRN_INST_CNT           --타워크레인설치개수
                    ,TCRN_DMT_CNT            --타워크레인해체개수
                    ,HST_INST_YN             --호이스트설치여부
                    ,HST_INST_CNT            --호이스트설치개수
                    ,HST_DMT_CNT             --호이스트해체개수
                    ,ETC_INST_MATT
                    ,APRV_NO                 --결재번호
                    ,IPT_ID                  --입력ID
                    ,IPT_DTM                 --입력일시
                    ,IPT_IP                  --입력IP
                    ,UPD_ID                  --수정ID
                    ,UPD_DTM                 --수정일시
                    ,UPD_IP                  --수정IP
                    )
             VALUES (p_SIT_CD                --현장코드
                    ,p_RPTING_DT             --보고일자
                    ,p_WEK_STR_DT            --주간시작일자
                    ,p_WEK_END_DT            --주간종료일자
                    ,p_SCNST_DT              --착공일자
                    ,p_CCNST_DT              --준공일자
                    ,p_TOT_PROCRT            --총공정율
                    ,p_TOT_DISS_CNT          --총재해건수
                    ,p_DEAD_CNT              --사망건수
                    ,p_INJ_CNT               --부상건수
                    ,p_MAIN_CTP_DTLS         --주요공종내역
                    ,p_APRP_SAFT_MCHR_AMT    --계상안전관리비금액
                    ,p_SAFT_MCHR_USE_AMT     --안전관리비사용금액
                    ,p_SAFT_MCHR_USE_RATE    --안전관리비사용율
                    ,p_PHOTO_GRP1            --첨부파일그룹사진1
                    ,p_PHOTO_DESC_1          --사진설명1
                    ,p_PHOTO_LOC_1           --사진설명1
                    ,p_PHOTO_GRP2            --첨부파일그룹사진2
                    ,p_PHOTO_DESC_2          --사진설명2
                    ,p_PHOTO_LOC_2           --사진설명1
                    ,p_PHOTO_GRP3            --첨부파일그룹사진2
                    ,p_PHOTO_DESC_3          --사진설명2
                    ,p_PHOTO_LOC_3           --사진설명1
                    ,p_PHOTO_GRP4            --첨부파일그룹사진2
                    ,p_PHOTO_DESC_4          --사진설명2
                    ,p_PHOTO_LOC_4           --사진설명1
                    ,p_PHOTO_GRP5            --첨부파일그룹사진2
                    ,p_PHOTO_DESC_5          --사진설명2
                    ,p_PHOTO_LOC_5           --사진설명1
                    ,p_PHOTO_GRP6            --첨부파일그룹사진2
                    ,p_PHOTO_DESC_6          --사진설명2
                    ,p_PHOTO_LOC_6           --사진설명1
                    ,p_ETC_MATT              --기타사항
                    ,p_GF_YN                 --갱폼설치여부
                    ,p_GF_INST_CNT           --갱폼설치개수
                    ,p_GF_DMT_CNT            --갱폼해체개수
                    ,p_TCRN_INST_YN          --타워크레인설치여부
                    ,p_TCRN_INST_CNT         --타워크레인설치개수
                    ,p_TCRN_DMT_CNT          --타워크레인해체개수
                    ,p_HST_INST_YN           --호이스트설치여부
                    ,p_HST_INST_CNT          --호이스트설치개수
                    ,p_HST_DMT_CNT           --호이스트해체개수
                    ,p_ETC_INST_MATT
                    ,p_APRV_NO               --결재번호
                    ,p_WRK_ID                --입력ID 
                    ,SYSDATE()               --입력일시
                    ,p_WRK_IP                --입력IP
                    ,p_WRK_ID                --수정ID
                    ,SYSDATE()               --수정일시
                    ,p_WRK_IP);              --수정IP
    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 5. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
         WHEN OTHERS THEN 
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);
END;
/

-- PQHA_WORK_ENV_MON_Q (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_WORK_ENV_MON_Q"
(
      p_WRK_TP  VARCHAR2 DEFAULT 'Q'                                                       -- FLAG( Q: SELECT )
     ,p_SIT_CD TQHA_WORK_ENV_MON.SIT_CD%TYPE                                              -- 현장코드
     ,p_MON_SEQ TQHA_WORK_ENV_MON.MON_SEQ%TYPE                                            -- 작업순번
     ,p_FRDT TQHA_WORK_ENV_MON.MON_DT%TYPE                           -- 작성시작일자
     ,p_TODT TQHA_WORK_ENV_MON.MON_DT%TYPE                           -- 작성종료일자
     ,p_HALF_DIV TQHA_WORK_ENV_MON.HALF_DIV%TYPE                          
     ,RTN_CURSOR OUT SYS_REFCURSOR
)
IS 
    /**************************************************************************************************************************
      Purpose : 

      REVISIONS
      Ver      Date               Author                  Description 
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2026/09/17 10:29:50                         최초생성

    /**************************************************************************************************************************/


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR2(200);            -- ERROR Message
    USER_EXCEPTION EXCEPTION;


BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 수행전 Check Logic ]
    ---------------------------------------------------------------------------------------------------------------------------


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Logic 처리
    ---------------------------------------------------------------------------------------------------------------------------

    OPEN RTN_CURSOR FOR
    SELECT  SIT_CD                 --현장코드
		   ,( SELECT CNST_NM FROM VQSZ_SITEINFO WHERE SIT_CD = A.SIT_CD ) AS SIT_NM
           ,MON_SEQ                 --작업순번
           ,HALF_DIV                 --상하반기구분
           ,MON_DGR                 --회차
           ,MON_DT                 --시행일자
           ,MON_CTS                 --주요내용
           ,RMKS                 --비고
           ,ATFL_GRP                 --첨부파일그룹
      FROM TQHA_WORK_ENV_MON A
    WHERE SIT_CD LIKE p_SIT_CD ||'%'
      AND HALF_DIV LIKE p_HALF_DIV ||'%'
      AND MON_DT BETWEEN NVL(p_FRDT, '19000101') AND NVL(p_TODT, '47121231')
      ORDER BY SIT_CD, MON_DT DESC
           ;



    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN 
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);
END ;
/

-- PQHA_WORK_ENV_MON_S (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_WORK_ENV_MON_S"
                            (p_WRK_TP  VARCHAR2 :='U'                                     -- UPDATE FLAG( I: ISNERT, U:UPDATE, D:DELTE)
                            ,p_WRK_ID  VARCHAR2                                           -- 사용자 ID 
                            ,p_WRK_IP  VARCHAR2                                           -- 사용자 IP 
                            ,p_SIT_CD TQHA_WORK_ENV_MON.SIT_CD%TYPE                       -- 현장코드
                            ,p_MON_SEQ TQHA_WORK_ENV_MON.MON_SEQ%TYPE                     -- 작업순번
                            ,p_HALF_DIV TQHA_WORK_ENV_MON.HALF_DIV%TYPE                   -- 상하반기구분
                            ,p_MON_DGR TQHA_WORK_ENV_MON.MON_DGR%TYPE                     -- 회차
                            ,p_MON_DT TQHA_WORK_ENV_MON.MON_DT%TYPE                       -- 시행일자
                            ,p_MON_CTS TQHA_WORK_ENV_MON.MON_CTS%TYPE                     -- 주요내용
                            ,p_RMKS TQHA_WORK_ENV_MON.RMKS%TYPE                           -- 비고
                            ,p_ATFL_GRP TQHA_WORK_ENV_MON.ATFL_GRP%TYPE)                  -- 첨부파일그룹
IS 
    /**************************************************************************************************************************
      Purpose : 

      REVISIONS
      Ver      Date               Author                  Description 
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2026/09/17 10:30:06                         최초생성

    /**************************************************************************************************************************/


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR2(200);            -- ERROR Message
    USER_EXCEPTION EXCEPTION;

	v_SEQ NUMBER;
BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 필수입력 필드  Check  ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_SIT_CD IS NULL)  THEN
        ERR_MSG := '현장코드는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_WRK_TP != 'I' AND p_MON_SEQ IS NULL)  THEN
        ERR_MSG := '작업순번는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Process 선행조건 Check ]
    ---------------------------------------------------------------------------------------------------------------------------

	SELECT  NVL(MAX(MON_SEQ),0)+1 INTO v_SEQ
      FROM TQHA_WORK_ENV_MON
     WHERE SIT_CD = p_SIT_CD          --현장코드
     ;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Business Process ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_WRK_TP ='D') THEN
        DELETE 
          FROM TQHA_WORK_ENV_MON
         WHERE SIT_CD = p_SIT_CD          --현장코드
           AND MON_SEQ = p_MON_SEQ;        --작업순번

    ELSIF (p_WRK_TP ='U') THEN
        UPDATE TQHA_WORK_ENV_MON
           SET HALF_DIV             = p_HALF_DIV                --상하반기구분
              ,MON_DGR              = p_MON_DGR                 --회차
              ,MON_DT               = p_MON_DT                  --시행일자
              ,MON_CTS              = p_MON_CTS                 --주요내용
              ,RMKS                 = p_RMKS                    --비고
              ,ATFL_GRP             = p_ATFL_GRP                --첨부파일그룹
              ,UPD_ID               = p_WRK_ID                  --수정ID 
              ,UPD_DTM              = SYSDATE()                 --수정일시
              ,UPD_IP               = p_WRK_IP                  --수정IP
         WHERE SIT_CD = p_SIT_CD          --현장코드
           AND MON_SEQ = p_MON_SEQ;        --작업순번
    ELSE 
        INSERT INTO TQHA_WORK_ENV_MON
                   ( SIT_CD                  --현장코드
                    ,MON_SEQ                 --작업순번
                    ,HALF_DIV                --상하반기구분
                    ,MON_DGR                 --회차
                    ,MON_DT                  --시행일자
                    ,MON_CTS                 --주요내용
