                    ,UPD_ID                  --수정ID
                    ,UPD_DTM                 --수정일시
                    ,UPD_IP                  --수정IP
                    )
             VALUES (p_SIT_CD                --현장코드
                    ,v_SEQ                    --작업순번
                    ,p_HALF_DIV              --상하반기구분
                    ,p_MON_DGR               --회차
                    ,p_MON_DT                --시행일자
                    ,p_MON_CTS               --주요내용
                    ,p_RMKS                  --비고
                    ,p_ATFL_GRP              --첨부파일그룹
                    ,p_WRK_ID                --입력ID 
                    ,SYSDATE()               --입력일시
                    ,p_WRK_IP                --입력IP
                    ,p_WRK_ID                --수정ID
                    ,SYSDATE()               --수정일시
                    ,p_WRK_IP);              --수정IP
    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 5. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN 
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);
END ;
/

-- PQHA_WRK_PDOC_Q (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_WRK_PDOC_Q"
(
      p_WRK_TP  VARCHAR2 DEFAULT 'Q'                                                       -- FLAG( Q: SELECT )
     ,p_SIT_CD TQHA_WRK_PDOC.SIT_CD%TYPE                             -- 현장코드
     ,p_WRK_PLN_CD1 TQHA_WRK_PDOC.WRK_PLN_CD1%TYPE                   -- 작업계획
     ,p_WRK_PLN_CD2 TQHA_WRK_PDOC.WRK_PLN_CD2%TYPE                   -- 작업계획
     ,p_WRK_DT_STR TQHA_WRK_PDOC.WRK_DT_STR%TYPE                           -- 작성시작일자
     ,p_WRK_DT_END TQHA_WRK_PDOC.WRK_DT_END%TYPE                           -- 작성종료일자
     ,RTN_CURSOR OUT SYS_REFCURSOR
)
IS 
    /**************************************************************************************************************************
      Purpose : 

      REVISIONS
      Ver      Date               Author                  Description 
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2026/06/15 12:57:12                         최초생성

    /**************************************************************************************************************************/


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR2(200);            -- ERROR Message
    USER_EXCEPTION EXCEPTION;


BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 수행전 Check Logic ]
    ---------------------------------------------------------------------------------------------------------------------------


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Logic 처리
    ---------------------------------------------------------------------------------------------------------------------------

    OPEN RTN_CURSOR FOR
    SELECT  A.SIT_CD                 --현장코드
		   ,( SELECT CNST_NM FROM VQSZ_SITEINFO WHERE SIT_CD = A.SIT_CD ) AS SIT_NM
           ,A.WRK_SEQ                 --작업순번
           ,A.WRK_PLN_CD1                 --작업계획코드
           ,A.WRK_PLN_CD2                 --작업계획코드
           ,A.CUST_CD                 --협력업체코드
           ,(SELECT CUST_NM FROM VQSZ_TRADE WHERE CUST_CD = A.CUST_CD)   AS CUST_NM 
           ,A.CTP_CD                 --공종코드
           ,A.RMKS                 --등록일자
           ,A.ATFL_GRP                 --첨부파일그룹
           ,A.WGT_HNL_YN
           ,A.WRK_DT_STR
           ,A.WRK_DT_END
      FROM TQHA_WRK_PDOC A
    WHERE SIT_CD LIKE p_SIT_CD ||'%'
      AND A.WRK_PLN_CD1 LIKE '%'||p_WRK_PLN_CD1||'%'
      AND ( p_WRK_DT_STR IS NULL OR A.WRK_DT_STR >= p_WRK_DT_STR)
      AND ( p_WRK_DT_END IS NULL OR A.WRK_DT_END <= p_WRK_DT_END )
     ;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN 
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);
END ;
/

-- PQHA_WRK_PDOC_S (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_WRK_PDOC_S"
                            (p_WRK_TP  VARCHAR2 :='U'                                     -- UPDATE FLAG( I: ISNERT, U:UPDATE, D:DELTE)
                            ,p_WRK_ID  VARCHAR2                                           -- 사용자 ID 
                            ,p_WRK_IP  VARCHAR2                                           -- 사용자 IP 
                            ,p_SIT_CD TQHA_WRK_PDOC.SIT_CD%TYPE                           -- 현장코드
                            ,p_WRK_SEQ TQHA_WRK_PDOC.WRK_SEQ%TYPE                         -- 작업순번
                            ,p_WRK_PLN_CD1 TQHA_WRK_PDOC.WRK_PLN_CD1%TYPE                 -- 작업계획코드
                            ,p_WRK_PLN_CD2 TQHA_WRK_PDOC.WRK_PLN_CD2%TYPE                 -- 작업계획코드
                            ,p_CUST_CD TQHA_WRK_PDOC.CUST_CD%TYPE                         -- 협력업체코드
                            ,p_CTP_CD TQHA_WRK_PDOC.CTP_CD%TYPE                           -- 공종코드
                            ,p_RMKS TQHA_WRK_PDOC.RMKS%TYPE                               -- 등록일자
                            ,p_ATFL_GRP TQHA_WRK_PDOC.ATFL_GRP%TYPE                       -- 첨부파일그룹
                            ,p_WGT_HNL_YN TQHA_WRK_PDOC.WGT_HNL_YN%TYPE                   -- 중량물취급여부
                            ,p_WRK_DT_STR TQHA_WRK_PDOC.WRK_DT_STR%TYPE                   -- 작성시작일자
						    ,p_WRK_DT_END TQHA_WRK_PDOC.WRK_DT_END%TYPE                   -- 작성종료일자
                            )
IS 
    /**************************************************************************************************************************
      Purpose : 

      REVISIONS
      Ver      Date               Author                  Description 
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2026/06/15 12:58:05                         최초생성

    /**************************************************************************************************************************/


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR2(200);            -- ERROR Message
    USER_EXCEPTION EXCEPTION;

	v_SEQ NUMBER;
BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 필수입력 필드  Check  ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_SIT_CD IS NULL)  THEN
        ERR_MSG := '현장코드는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_WRK_TP != 'I' AND p_WRK_SEQ IS NULL)  THEN
        ERR_MSG := '작업순번는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;
    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Process 선행조건 Check ]
    ---------------------------------------------------------------------------------------------------------------------------
	SELECT NVL(MAX(WRK_SEQ), 0) + 1 INTO v_SEQ
    FROM TQHA_WRK_PDOC
    WHERE SIT_CD = p_SIT_CD;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Business Process ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_WRK_TP ='D') THEN
        DELETE 
          FROM TQHA_WRK_PDOC
         WHERE SIT_CD = p_SIT_CD          --현장코드
           AND WRK_SEQ = p_WRK_SEQ;        --작업순번

    ELSIF (p_WRK_TP ='U') THEN
        UPDATE TQHA_WRK_PDOC
           SET WRK_PLN_CD1          = p_WRK_PLN_CD1             --작업계획코드
              ,WRK_PLN_CD2          = p_WRK_PLN_CD2             --작업계획코드
              ,CUST_CD              = p_CUST_CD                 --협력업체코드
              ,CTP_CD               = p_CTP_CD                  --공종코드
              ,RMKS                 = p_RMKS                    --등록일자
              ,ATFL_GRP             = p_ATFL_GRP                --첨부파일그룹
              ,WGT_HNL_YN           = p_WGT_HNL_YN              --중량물취급여부
              ,WRK_DT_STR           = p_WRK_DT_STR
              ,WRK_DT_END           = p_WRK_DT_END
              ,UPD_ID               = p_WRK_ID                  --수정ID 
              ,UPD_DTM              = SYSDATE()                 --수정일시
              ,UPD_IP               = p_WRK_IP                  --수정IP
         WHERE SIT_CD = p_SIT_CD          --현장코드
           AND WRK_SEQ = p_WRK_SEQ;        --작업순번
    ELSE 
        INSERT INTO TQHA_WRK_PDOC
                   ( SIT_CD                  --현장코드
                    ,WRK_SEQ                 --작업순번
                    ,WRK_PLN_CD1              --작업계획코드
                    ,WRK_PLN_CD2              --작업계획코드
                    ,CUST_CD                 --협력업체코드
                    ,CTP_CD                  --공종코드
                    ,RMKS                    --등록일자
                    ,ATFL_GRP                --첨부파일그룹
                    ,WGT_HNL_YN
                    ,WRK_DT_STR
                    ,WRK_DT_END
                    ,IPT_ID                  --입력ID
                    ,IPT_DTM                 --입력일시
                    ,IPT_IP                  --입력IP
                    ,UPD_ID                  --수정ID
                    ,UPD_DTM                 --수정일시
                    ,UPD_IP                  --수정IP
                    )
             VALUES (p_SIT_CD                --현장코드
                    ,v_SEQ               --작업순번
                    ,p_WRK_PLN_CD1            --작업계획코드
                    ,p_WRK_PLN_CD2            --작업계획코드
                    ,p_CUST_CD               --협력업체코드
                    ,p_CTP_CD                --공종코드
                    ,p_RMKS                  --등록일자
                    ,p_ATFL_GRP              --첨부파일그룹
                    ,p_WGT_HNL_YN
                    ,p_WRK_DT_STR
                    ,p_WRK_DT_END
                    ,p_WRK_ID                --입력ID 
                    ,SYSDATE()               --입력일시
                    ,p_WRK_IP                --입력IP
                    ,p_WRK_ID                --수정ID
                    ,SYSDATE()               --수정일시
                    ,p_WRK_IP);              --수정IP
    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 5. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN 
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);
END ;
/

