-- PQHA_YYTRGPLN_Q (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_YYTRGPLN_Q" (
    p_WRK_TP            IN VARCHAR2 DEFAULT 'Q'                 -- FLAG
,   p_SIT_CD            IN TQHA_YYTRGPLN.SIT_CD     %TYPE       -- 현장코드
,   p_TRG_YY            IN TQHA_YYTRGPLN.TRG_YY     %TYPE       -- 목표년도
,   p_TRG_DGR           IN TQHA_YYTRGPLN.TRG_DGR    %TYPE       -- 목표차수
,   RTN_CURSOR          OUT SYS_REFCURSOR
)
IS
    /**************************************************************************************************************************
      Purpose : [안전보건목표 조회] PROCEDRE (안전 > 안전보건목표/실적 > 안전보건목표  )

      REVISIONS
      Ver      Date               Author                  Description
      -------  -----------------  ----------------------  ---------------------------------------------------------------------
      1.0      XXXX/XX/XX                                 최초생성

    **************************************************************************************************************************/

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE  NUMBER :=-20009; -- ERROR 코드
    ERR_MSG   VARCHAR(200);    -- ERROR Message
    USER_EXCEPTION EXCEPTION;

BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 수행전 Check Logic ]
    ---------------------------------------------------------------------------------------------------------------------------

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Logic 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------

    IF p_WRK_TP = 'Q' THEN

        OPEN RTN_CURSOR FOR
        SELECT AA.SIT_CD                                        -- 현장코드
             , AA.TRG_YY                                        -- 목표년도
             , AA.TRG_DGR                                       -- 목표차수
             , AA.DRV_TRG_SEQ                                   -- 추진목표순번
             , AA.DRV_TRG_DIV                                   -- 추진목표구분
             , AA.DRV_TRG                                       -- 추진목표
             , AA.PRTCL_DRV_PLN                                 -- 세부추진계획
             , AA.ACHV_TRG                                      -- 달성목표치
             , AA.ACHV_STR_DD                                   -- 달성시작일
             , AA.ACHV_END_DD                                   -- 달성종료일
          FROM TQHA_YYTRGPLN AA
         WHERE 1=1
           AND SIT_CD   = p_SIT_CD
           AND TRG_YY   = p_TRG_YY
           AND TRG_DGR  = p_TRG_DGR
         ORDER
            BY DRV_TRG_SEQ
        ;

    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
         WHEN OTHERS THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);

END PQHA_YYTRGPLN_Q;
/

-- PQHA_YYTRGPLN_S (PROCEDURE, VALID)
CREATE PROCEDURE "PQHA_YYTRGPLN_S" (
    p_WRK_TP            VARCHAR2 :='U'                                  -- UPDATE FLAG( I: ISNERT, U:UPDATE, D:DELTE)
,   p_WRK_ID            VARCHAR2                                        -- 사용자 ID
,   p_WRK_IP            VARCHAR2                                        -- 사용자 IP
,   p_SIT_CD            TQHA_YYTRGPLN.SIT_CD                %TYPE       -- 현장코드
,   p_TRG_YY            TQHA_YYTRGPLN.TRG_YY                %TYPE       -- 목표년도
,   p_TRG_DGR           TQHA_YYTRGPLN.TRG_DGR               %TYPE       -- 목표차수
,   p_DRV_TRG_SEQ       TQHA_YYTRGPLN.DRV_TRG_SEQ           %TYPE       -- 추진목표순번
,   p_DRV_TRG_DIV       TQHA_YYTRGPLN.DRV_TRG_DIV           %TYPE       -- 추진목표구분
,   p_DRV_TRG           TQHA_YYTRGPLN.DRV_TRG               %TYPE       -- 추진목표
,   p_PRTCL_DRV_PLN     TQHA_YYTRGPLN.PRTCL_DRV_PLN         %TYPE       -- 세부추진계획
,   p_ACHV_TRG          TQHA_YYTRGPLN.ACHV_TRG              %TYPE       -- 달성목표치
,   p_ACHV_STR_DD       TQHA_YYTRGPLN.ACHV_STR_DD           %TYPE       -- 달성시작일
,   p_ACHV_END_DD       TQHA_YYTRGPLN.ACHV_END_DD           %TYPE       -- 달성종료일
)
IS
    /**************************************************************************************************************************
      Purpose :

      REVISIONS
      Ver      Date               Author                  Description
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2019/04/18 09:44:58                         최초생성

    /**************************************************************************************************************************/


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR(200);             -- ERROR Message
    USER_EXCEPTION EXCEPTION;

    p_UPD_ID            VARCHAR2(30);
    p_UPD_DTM           DATE;
    p_UPD_IP            VARCHAR2(30);
    p_IPT_ID            VARCHAR2(30);
    p_IPT_DTM           DATE;
    p_IPT_IP            VARCHAR2(30);

    v_APRV_STATS        VARCHAR2(20);
    v_APRV_STATS_NM     VARCHAR2(50);

BEGIN
    IF p_WRK_TP = 'I' THEN
        p_IPT_ID  := p_WRK_ID;
        p_IPT_DTM := SYSDATE();
        p_IPT_IP  := p_WRK_IP;
        p_UPD_ID  := p_WRK_ID;
        p_UPD_DTM := SYSDATE();
        p_UPD_IP  := p_WRK_IP;
    ELSE
        p_UPD_ID  := p_WRK_ID;
        p_UPD_DTM := SYSDATE();
        p_UPD_IP  := p_WRK_IP;
    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 필수입력 필드  Check  ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_SIT_CD IS NULL)  THEN
        ERR_MSG := '현장코드는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_TRG_YY IS NULL)  THEN
        ERR_MSG := '계획년도는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_TRG_DGR IS NULL)  THEN
        ERR_MSG := '계획차수는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    ---------------------------------------------------------------------
    -- 결재상태 체크
    SELECT MAX(T2.APRV_STATS)
         , MAX(T3.CD_NM )
      INTO v_APRV_STATS
         , v_APRV_STATS_NM
      FROM TQHA_YYTRGPLNSEQ     T1
      LEFT JOIN TQHA_APRV       T2 ON T1.SIT_CD     = T2.SIT_CD
                                  AND T1.APRV_NO    = T2.APRV_NO
      LEFT JOIN TCOA_COMCODE    T3 ON T2.APRV_STATS = T3.COM_CD 
                                  AND T3.HRNK_CD    = 'QS031'
     WHERE T1.SIT_CD    = p_SIT_CD
       AND T1.TRG_YY    = p_TRG_YY
       AND T1.TRG_DGR   = p_TRG_DGR
    ;

    IF v_APRV_STATS IN ('2', '4') THEN
        ERR_MSG := '결재상태 [' || v_APRV_STATS_NM || ']인 데이터는 수정 불가합니다.';
        RAISE USER_EXCEPTION;
    END IF;

--    IF (p_DRV_TRG_SEQ IS NULL)  THEN
--        ERR_MSG := '추진목표순번는(은) 필수 입력사항 입니다.';
--        RAISE USER_EXCEPTION;
--    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Process 선행조건 Check ]
    ---------------------------------------------------------------------------------------------------------------------------



    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Business Process ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_WRK_TP ='D') THEN
        DELETE
          FROM TQHA_YYTRGPLN
         WHERE SIT_CD           = p_SIT_CD          -- 현장코드
           AND TRG_YY           = p_TRG_YY          -- 목표년도
           AND TRG_DGR          = p_TRG_DGR         -- 목표차수
           AND DRV_TRG_SEQ      = p_DRV_TRG_SEQ     -- 추진목표순번
        ;

    -------------------------------------------------------------------------------------
    ELSIF (p_WRK_TP ='U') THEN

        UPDATE TQHA_YYTRGPLN
           SET DRV_TRG_DIV          = p_DRV_TRG_DIV         -- 추진목표구분
             , DRV_TRG              = p_DRV_TRG             -- 추진목표
             , PRTCL_DRV_PLN        = p_PRTCL_DRV_PLN       -- 세부추진계획
             , ACHV_TRG             = p_ACHV_TRG            -- 달성목표치
             , ACHV_STR_DD          = p_ACHV_STR_DD         -- 달성시작일
             , ACHV_END_DD          = p_ACHV_END_DD         -- 달성종료일
             , UPD_ID               = p_UPD_ID              -- 최종수정ID
             , UPD_DTM              = p_UPD_DTM             -- 최종수정일시
             , UPD_IP               = p_UPD_IP              -- 최종수정IP
         WHERE SIT_CD               = p_SIT_CD              -- 현장코드
           AND TRG_YY               = p_TRG_YY              -- 목표년도
           AND TRG_DGR              = p_TRG_DGR             -- 목표차수
           AND DRV_TRG_SEQ          = p_DRV_TRG_SEQ         -- 추진목표순번
        ;

    -------------------------------------------------------------------------------------
    ELSE
        INSERT 
          INTO TQHA_YYTRGPLN
             ( SIT_CD               -- 현장코드
             , TRG_YY               -- 목표년도
             , TRG_DGR              -- 목표차수
             , DRV_TRG_SEQ          -- 추진목표순번
             , DRV_TRG_DIV          -- 추진목표구분
             , DRV_TRG              -- 추진목표
             , PRTCL_DRV_PLN        -- 세부추진계획
             , ACHV_TRG             -- 달성목표치
             , ACHV_STR_DD          -- 달성시작일
             , ACHV_END_DD          -- 달성종료일
             , IPT_ID               -- 신규입력ID
             , IPT_DTM              -- 신규입력일시
             , IPT_IP               -- 신규입력IP
             , UPD_ID               -- 최종수정ID
             , UPD_DTM              -- 최종수정일시
             , UPD_IP               -- 최종수정IP
             )
        VALUES 
             ( p_SIT_CD             -- 현장코드
             , p_TRG_YY             -- 목표년도
             , p_TRG_DGR            -- 목표차수
             , (SELECT NVL(MAX(DRV_TRG_SEQ), 0) + 1
                  FROM TQHA_YYTRGPLN
                 WHERE 1=1
                   AND SIT_CD   = p_SIT_CD
                   AND TRG_YY   = p_TRG_YY
                   AND TRG_DGR  = p_TRG_DGR
               )                    -- 추진목표순번
             , p_DRV_TRG_DIV        -- 추진목표구분
             , p_DRV_TRG            -- 추진목표
             , p_PRTCL_DRV_PLN      -- 세부추진계획
             , p_ACHV_TRG           -- 달성목표치
             , p_ACHV_STR_DD        -- 달성시작일
             , p_ACHV_END_DD        -- 달성종료일
             , p_IPT_ID             -- 신규입력ID
             , p_IPT_DTM            -- 신규입력일시
             , p_IPT_IP             -- 신규입력IP
             , p_UPD_ID             -- 최종수정ID
             , p_UPD_DTM            -- 최종수정일시
             , p_UPD_IP             -- 최종수정IP
             )
        ;

    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 5. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
         WHEN OTHERS THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);

END;
/

-- PQHB_CTPUNT_CHKITM_S (PROCEDURE, VALID)
CREATE PROCEDURE "PQHB_CTPUNT_CHKITM_S" (
    p_WRK_TP                VARCHAR2 :='U'                                          -- UPDATE FLAG( I: ISNERT, U:UPDATE, D:DELTE)
,   p_WRK_ID                VARCHAR2                                                -- 사용자 ID
,   p_WRK_IP                VARCHAR2                                                -- 사용자 IP
,   p_CTP_CD                TQHB_CTPUNT_CHKITM.CTP_CD               %TYPE           -- 공종코드
,   p_UNT_CD                TQHB_CTPUNT_CHKITM.UNT_CD               %TYPE           -- 단위코드
,   p_CHK_ITM_CD            TQHB_CTPUNT_CHKITM.CHK_ITM_CD           %TYPE           -- 점검항목코드
,   p_CHK_ITM_NM            TQHB_CTPUNT_CHKITM.CHK_ITM_NM           %TYPE           -- 점검항목명
,   p_DISS_SHP              TQHB_CTPUNT_CHKITM.DISS_SHP             %TYPE           -- 재해형태(QS036)
,   p_RISK_FREQ             TQHB_CTPUNT_CHKITM.RISK_FREQ            %TYPE           -- 빈도레벨(QS003)
,   p_RISK_APRV             TQHB_CTPUNT_CHKITM.RISK_APRV            %TYPE           -- 강도레벨(QS004)
,   p_RISK_CRIT             TQHB_CTPUNT_CHKITM.RISK_CRIT            %TYPE           -- 위험성(QS063)
,   p_RISK_GRD              TQHB_CTPUNT_CHKITM.RISK_GRD             %TYPE           -- 위험등급(QS024)
,   p_IMPRV_CPLN            TQHB_CTPUNT_CHKITM.IMPRV_CPLN           %TYPE           -- 개선대책
,   p_USR_DEFN_YN           TQHB_CTPUNT_CHKITM.USR_DEFN_YN          %TYPE           -- 표준 0, 사용자정의 1
,   p_CUST_CD               TQHB_CTPUNT_CHKITM.CUST_CD              %TYPE           -- 업체코드
,   p_SIT_CD                TQHB_CTPUNT_CHKITM.SIT_CD               %TYPE           -- 현장코드
,   p_USE_YN                TQHB_CTPUNT_CHKITM.USE_YN               %TYPE           -- 사용여부
) 
IS 
    /**************************************************************************************************************************
      Purpose : 

      REVISIONS
      Ver      Date               Author                  Description
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2021/10/21 14:21:20                         최초생성

    **************************************************************************************************************************/


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR2(200);            -- ERROR Message
    USER_EXCEPTION EXCEPTION;

    v_CHK_ITM_CD TQHB_CTPUNT_CHKITM.CHK_ITM_CD%TYPE ;           -- 점검코드 변수 선언
    v_cnt   INTEGER := 0;                                       -- 점검항목코드 사용여부 확인
    v_cnt1  INTEGER := 0;                                       -- 점검항목코드 사용여부 확인
    v_cnt2  INTEGER := 0;                                       -- 점검항목코드 사용여부 확인
    v_cnt3  INTEGER := 0;                                       -- 점검항목코드 사용여부 확인

BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 필수입력 필드  Check  ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_CTP_CD IS NULL)  THEN
        ERR_MSG := '공종코드는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_UNT_CD IS NULL)  THEN
        ERR_MSG := '단위코드는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_CHK_ITM_CD IS NULL AND p_WRK_TP <> 'I' )  THEN
        ERR_MSG := '점검항목코드는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_USR_DEFN_YN IS NULL)  THEN
        ERR_MSG := '표준 0, 사용자정의 1는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    --  점검항목 사용 여부
    --  점검항목 코드 사용 여부 확인
    IF p_WRK_TP = 'D' THEN
        -- 위험성평가 세부계획(최초/연간)
        SELECT nvl(COUNT(CHK_ITM_CD),0)
          INTO v_cnt
          FROM TQHA_RISKPLAN_D
         WHERE CTP_CD       = p_CTP_CD
           AND UNT_CD       = p_UNT_CD
           AND CHK_ITM_CD   = p_CHK_ITM_CD
        ;

        IF v_cnt < 1  THEN
            -- 위험성평가 점검내용(수시)
            SELECT nvl(COUNT(CHK_ITM_CD),0)
              INTO v_cnt1
              FROM TQHB_RISK_LST
             WHERE CTP_CD       = p_CTP_CD
               AND UNT_CD       = p_UNT_CD
               AND CHK_ITM_CD   = p_CHK_ITM_CD
            ;
        END IF; 
--
--        IF v_cnt1 < 1  THEN
--            -- 위험성평가 취수 중점점검(수시)
--            SELECT nvl(COUNT(CHK_ITM_CD),0)
--              INTO v_cnt2
--              FROM TQSB_RISK_PRRTCHK
--             WHERE CTP_CD       = p_CTP_CD
--               AND UNT_CD       = p_UNT_CD
--               AND CHK_ITM_CD   = p_CHK_ITM_CD
--            ;
--        END IF ;

        -- 단위작업 코드 Validation
        IF ( v_cnt +  v_cnt1 ) > 0 THEN
            ERR_MSG := '점검항목 "' || p_CHK_ITM_NM || '" 은(는) 사용중입니다.. 사용중인 점검항목은 삭제할 수 없습니다. ';
            RAISE USER_EXCEPTION;
        END IF;

    END IF;


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Process 선행조건 Check ]
    ---------------------------------------------------------------------------------------------------------------------------



    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Business Process ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_WRK_TP ='D') THEN

        DELETE
          FROM TQHB_CTPUNT_CHKITM
         WHERE CTP_CD       = p_CTP_CD          -- 공종코드
           AND UNT_CD       = p_UNT_CD          -- 단위코드
           AND CHK_ITM_CD   = p_CHK_ITM_CD      -- 점검항목코드 
        ;

    --------------------------------------------------------------------------------------
    ELSIF (p_WRK_TP ='U') THEN

        UPDATE TQHB_CTPUNT_CHKITM
           SET CHK_ITM_NM           = p_CHK_ITM_NM          -- 점검항목명
             , DISS_SHP             = p_DISS_SHP            -- 재해형태(QS036)
             , RISK_FREQ            = p_RISK_FREQ           -- 빈도레벨(QS003)
             , RISK_APRV            = p_RISK_APRV           -- 강도레벨(QS004)
             , RISK_CRIT            = p_RISK_CRIT           -- 위험성(QS063)
             , RISK_GRD             = p_RISK_GRD            -- 위험등급(QS024)
             , IMPRV_CPLN           = p_IMPRV_CPLN          -- 개선대책
             , USR_DEFN_YN          = p_USR_DEFN_YN         -- 표준 0, 사용자정의 1
             , CUST_CD              = p_CUST_CD             -- 업체코드
             , SIT_CD               = p_SIT_CD              -- 현장코드
             , USE_YN               = p_USE_YN              -- 사용여부
             , UPD_ID               = p_WRK_ID              -- 수정ID
             , UPD_DTM              = SYSDATE()             -- 수정일시
             , UPD_IP               = p_WRK_IP              -- 수정IP
         WHERE CTP_CD               = p_CTP_CD              -- 공종코드
           AND UNT_CD               = p_UNT_CD              -- 단위코드
           AND CHK_ITM_CD           = p_CHK_ITM_CD          -- 점검항목코드
        ;

    --------------------------------------------------------------------------------------
    ELSE
        -- 점검항목코드 MAX부여
        SELECT LPAD(NVL(MAX(SUBSTR(CHK_ITM_CD, 1, 5)), 0) + 1, 5,'0')
          INTO v_CHK_ITM_CD
          FROM TQHB_CTPUNT_CHKITM
         WHERE CTP_CD   = p_CTP_CD          -- 공종코드
           AND UNT_CD   = p_UNT_CD          -- 단위작업코드
        ;
        --
        INSERT 
          INTO TQHB_CTPUNT_CHKITM
             ( CTP_CD                   -- 공종코드
             , UNT_CD                   -- 단위코드
             , CHK_ITM_CD               -- 점검항목코드
             , CHK_ITM_NM               -- 점검항목명
             , DISS_SHP                 -- 재해형태(QS036)
             , RISK_FREQ                -- 빈도레벨(QS003)
             , RISK_APRV                -- 강도레벨(QS004)
             , RISK_CRIT                -- 위험성(QS063)
             , RISK_GRD                 -- 위험등급(QS024)
             , IMPRV_CPLN               -- 개선대책
             , USR_DEFN_YN              -- 표준 0, 사용자정의 1
             , CUST_CD                  -- 업체코드
             , SIT_CD                   -- 현장코드
             , USE_YN                   -- 사용여부
             , IPT_ID                   -- 입력ID
             , IPT_DTM                  -- 입력일시
             , IPT_IP                   -- 입력IP
             , UPD_ID                   -- 수정ID
             , UPD_DTM                  -- 수정일시
             , UPD_IP                   -- 수정IP
             )
        VALUES 
             ( p_CTP_CD                 -- 공종코드
             , p_UNT_CD                 -- 단위코드
             , v_CHK_ITM_CD             -- 점검항목코드
             , p_CHK_ITM_NM             -- 점검항목명
             , p_DISS_SHP               -- 재해형태(QS036)
             , p_RISK_FREQ              -- 빈도레벨(QS003)
             , p_RISK_APRV              -- 강도레벨(QS004)
             , p_RISK_CRIT              -- 위험성(QS063)
             , p_RISK_GRD               -- 위험등급(QS024)
             , p_IMPRV_CPLN             -- 개선대책
             , p_USR_DEFN_YN            -- 표준 0, 사용자정의 1
             , p_CUST_CD                -- 업체코드
             , p_SIT_CD                 -- 현장코드
             , p_USE_YN                 -- 사용여부
             , p_WRK_ID                 -- 입력ID
             , SYSDATE()                -- 입력일시
             , p_WRK_IP                 -- 입력IP
             , p_WRK_ID                 -- 수정ID
             , SYSDATE()                -- 수정일시
             , p_WRK_IP                 -- 수정IP
             )
        ;

    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 5. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);
END ;
/

-- PQHB_DAYSAFE_CHKLST_S (PROCEDURE, VALID)
CREATE PROCEDURE "PQHB_DAYSAFE_CHKLST_S" 
                            (p_WRK_TP  VARCHAR2 :='U'                                     -- UPDATE FLAG( I: ISNERT, U:UPDATE, D:DELTE)
                            ,p_WRK_ID  VARCHAR2                                           -- 사용자 ID 
                            ,p_WRK_IP  VARCHAR2                                           -- 사용자 IP 
                            ,p_SIT_CD TQHB_DAYSAFE_CHKLST.SIT_CD%TYPE                     -- 현장코드
                            ,p_PLN_YM TQHB_DAYSAFE_CHKLST.PLN_YM%TYPE                     -- 계획년월
                            ,p_PLN_DGR TQHB_DAYSAFE_CHKLST.PLN_DGR%TYPE                   -- 차수구분코드(QS005) 1 1차,2 2차
                            ,p_CUST_CD TQHB_DAYSAFE_CHKLST.CUST_CD%TYPE                   -- 협력업체코드
                            ,p_VNDR_SEQ TQHB_DAYSAFE_CHKLST.VNDR_SEQ%TYPE                -- 업체순번
                            ,p_CTP_CD TQHB_DAYSAFE_CHKLST.CTP_CD%TYPE                     -- 공종코드
                            ,p_UNT_CD TQHB_DAYSAFE_CHKLST.UNT_CD%TYPE                     -- 단위코드
                            ,p_CHK_ITM_CD TQHB_DAYSAFE_CHKLST.CHK_ITM_CD%TYPE             -- 점검항목코드
                            ,p_ODAY_CHK_DT TQHB_DAYSAFE_CHKLST.ODAY_CHK_DT%TYPE           -- 일일점검일자
                            ,p_RISK_GRD TQHB_DAYSAFE_CHKLST.RISK_GRD%TYPE                 -- 위험등급(QS09002) 작성
                            ,p_CHK_ITM_SEQ TQHB_DAYSAFE_CHKLST.CHK_ITM_SEQ%TYPE           -- 점검항목 정열순서
                            ,p_ODAY_CHK_RSLT TQHB_DAYSAFE_CHKLST.ODAY_CHK_RSLT%TYPE       -- 점검결과(QS006) 1 N/A,2 완료(유지),3 불량
                            ,p_ODAY_CHK_OPIN TQHB_DAYSAFE_CHKLST.ODAY_CHK_OPIN%TYPE       -- 일일안전책임자 점검의견
                            ,p_EMPE_NO TQHB_DAYSAFE_CHKLST.EMPE_NO%TYPE                   -- 일일안전책임자 사번
                            ,p_PHOTO_GRP1 TQHB_DAYSAFE_CHKLST.PHOTO_GRP1%TYPE             -- 첨부파일그룹사진1
                            ,p_PHOTO_DESC_1 TQHB_DAYSAFE_CHKLST.PHOTO_DESC_1%TYPE         -- 사진설명1
                            ,p_PHOTO_GRP2 TQHB_DAYSAFE_CHKLST.PHOTO_GRP2%TYPE             -- 첨부파일그룹사진2
                            ,p_PHOTO_DESC_2 TQHB_DAYSAFE_CHKLST.PHOTO_DESC_2%TYPE         -- 사진설명2
                            ,p_NCR_PUBC_YN TQHB_DAYSAFE_CHKLST.NCR_PUBC_YN%TYPE           -- 발행 1, 미발행 0
                            ,p_NCR_DOC_NO TQHB_DAYSAFE_CHKLST.NCR_DOC_NO%TYPE             -- 부적합문서번호
                            ,p_MA_DDLN_DT TQHB_DAYSAFE_CHKLST.MA_DDLN_DT%TYPE             -- 조치기한일자
                            ,p_VNDR_NOTI_YN TQHB_DAYSAFE_CHKLST.VNDR_NOTI_YN%TYPE         -- 발송 1 미발송0
                            ,p_VNDR_SEND_DT TQHB_DAYSAFE_CHKLST.VNDR_SEND_DT%TYPE         -- 업체발송일자
                            ,p_VNDR_MA_YN TQHB_DAYSAFE_CHKLST.VNDR_MA_YN%TYPE             -- 조치구분(QS007) 1 조치, 0 미조치
                            ,p_VNDR_MA_DT TQHB_DAYSAFE_CHKLST.VNDR_MA_DT%TYPE             -- 업체조치일자
                            ,p_NCR_LOC VARCHAR2    -- 발생위치 
                            ,p_CHK_ITM_NM VARCHAR2
                            )
                            
IS 
    /**************************************************************************************************************************
      Purpose : 

      REVISIONS
      Ver      Date               Author                  Description 
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2026/09/10 14:13:42                         최초생성

    /**************************************************************************************************************************/


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR2(200);            -- ERROR Message
    USER_EXCEPTION EXCEPTION;

	v_SEQ NUMBER;
	v_EMPE_NO VARCHAR2(20);
	v_OUT VARCHAR2(20);
	v_OLD_NCR_DOC_NO VARCHAR2(20);
	v_VNDR_APRV_YN VARCHAR2(1);
	v_MGR_APRV_YN VARCHAR2(1);
	
BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 필수입력 필드  Check  ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_SIT_CD IS NULL)  THEN
        ERR_MSG := '현장코드는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_PLN_YM IS NULL)  THEN
        ERR_MSG := '계획년월는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_PLN_DGR IS NULL)  THEN
        ERR_MSG := '차수구분코드(QS005) 1 1차,2 2차는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_CUST_CD IS NULL)  THEN
        ERR_MSG := '협력업체코드는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_CTP_CD IS NULL)  THEN
        ERR_MSG := '공종코드는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_UNT_CD IS NULL)  THEN
        ERR_MSG := '단위코드는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_CHK_ITM_CD IS NULL)  THEN
        ERR_MSG := '점검항목코드는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_ODAY_CHK_DT IS NULL)  THEN
        ERR_MSG := '일일점검일자는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_RISK_GRD IS NULL)  THEN
        ERR_MSG := '위험등급(QS09002) 작성는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_VNDR_SEQ IS NULL)  THEN
        ERR_MSG := '업체순번는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Process 선행조건 Check ]
    ---------------------------------------------------------------------------------------------------------------------------

        -- 2025.02.02 부적합보고서 승인 상태 체크하여, 업체 승인 요청시 또는 관리자 승인시엔 불량에서 다른걸로 변경하지 못하게 막아야 함.
        SELECT NVL(MAX(NCR_DOC_NO), '*')
          INTO v_OLD_NCR_DOC_NO
          FROM TQHB_DAYSAFE_CHKLST
         WHERE SIT_CD       = p_SIT_CD          --현장코드
           AND PLN_YM       = p_PLN_YM          --계획년월
           AND PLN_DGR      = p_PLN_DGR         --차수구분코드(QS005) 1 1차,2 2차
           AND CUST_CD      = p_CUST_CD         --공종코드
           AND VNDR_SEQ     = p_VNDR_SEQ        --공종코드
           AND CTP_CD       = p_CTP_CD          --공종코드
           AND UNT_CD       = p_UNT_CD          --단위코드
           AND CHK_ITM_CD   = p_CHK_ITM_CD      --점검항목코드
           AND ODAY_CHK_DT  = p_ODAY_CHK_DT     --일일점검일자
           AND RISK_GRD     = p_RISK_GRD
        ;

        IF v_OLD_NCR_DOC_NO != '*' THEN
            SELECT VNDR_APRV_YN
                 , MGR_APRV_YN
              INTO v_VNDR_APRV_YN
                 , v_MGR_APRV_YN
              FROM TQHA_NCR_REP
             WHERE SIT_CD       = p_SIT_CD
               AND NCR_DOC_NO   = v_OLD_NCR_DOC_NO
            ;

            IF v_MGR_APRV_YN = '1' THEN
                ERR_MSG := '부적합보고서 관리자가 승인한 상태여서 변경할 수 없습니다.'
                        || CHR(10) || '관리자 반려 후, 업체 승인요청취소 후에 변경 가능합니다. ';
                RAISE USER_EXCEPTION;
            END IF;

            IF v_VNDR_APRV_YN = '1' THEN
                ERR_MSG := '부적합보고서 업체 승인요청중이어서 변경할 수 없습니다.'
                        || CHR(10) || '승인요청 취소 후 변경 가능합니다 ';
                RAISE USER_EXCEPTION;
            END IF;

        END IF;

        
     SELECT MAX(EMPE_NO) INTO v_EMPE_NO 
      FROM TQHB_DAYSAFE_CHKLST
     WHERE SIT_CD = p_SIT_CD          --현장코드
       AND PLN_YM = p_PLN_YM          --계획년월
       AND PLN_DGR = p_PLN_DGR         --차수구분코드(QS005) 1 1차,2 2차
       AND CUST_CD = p_CUST_CD         --협력업체코드
       AND CTP_CD = p_CTP_CD          --공종코드
       AND UNT_CD = p_UNT_CD          --단위코드
       AND CHK_ITM_CD = p_CHK_ITM_CD      --점검항목코드
       AND ODAY_CHK_DT = p_ODAY_CHK_DT     --일일점검일자
       AND RISK_GRD = p_RISK_GRD        --위험등급(QS09002) 작성
       AND VNDR_SEQ = p_VNDR_SEQ;       --업체순번
           
    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Business Process ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_WRK_TP ='D') THEN
        DELETE 
          FROM TQHB_DAYSAFE_CHKLST
         WHERE SIT_CD = p_SIT_CD          --현장코드
           AND PLN_YM = p_PLN_YM          --계획년월
           AND PLN_DGR = p_PLN_DGR         --차수구분코드(QS005) 1 1차,2 2차
           AND CUST_CD = p_CUST_CD         --협력업체코드
           AND CTP_CD = p_CTP_CD          --공종코드
           AND UNT_CD = p_UNT_CD          --단위코드
           AND CHK_ITM_CD = p_CHK_ITM_CD      --점검항목코드
           AND ODAY_CHK_DT = p_ODAY_CHK_DT     --일일점검일자
           AND RISK_GRD = p_RISK_GRD        --위험등급(QS09002) 작성
           AND VNDR_SEQ = p_VNDR_SEQ;       --업체순번

    ELSIF (p_WRK_TP ='U') THEN
        UPDATE TQHB_DAYSAFE_CHKLST
           SET CHK_ITM_SEQ          = p_CHK_ITM_SEQ             --점검항목 정열순서
              ,ODAY_CHK_RSLT        = p_ODAY_CHK_RSLT           --점검결과(QS006) 1 N/A,2 완료(유지),3 불량
              ,ODAY_CHK_OPIN        = p_ODAY_CHK_OPIN           --일일안전책임자 점검의견
              ,EMPE_NO              = p_WRK_ID                  --일일안전책임자 사번
              ,PHOTO_GRP1           = p_PHOTO_GRP1              --첨부파일그룹사진1
              ,PHOTO_DESC_1         = p_PHOTO_DESC_1            --사진설명1
              ,PHOTO_GRP2           = p_PHOTO_GRP2              --첨부파일그룹사진2
              ,PHOTO_DESC_2         = p_PHOTO_DESC_2            --사진설명2
--              ,NCR_PUBC_YN          = p_NCR_PUBC_YN             --발행 1, 미발행 0
--              ,NCR_DOC_NO           = v_OLD_NCR_DOC_NO              --부적합문서번호
--              ,MA_DDLN_DT           = p_MA_DDLN_DT              --조치기한일자
--              ,VNDR_NOTI_YN         = p_VNDR_NOTI_YN            --발송 1 미발송0
--              ,VNDR_SEND_DT         = p_VNDR_SEND_DT            --업체발송일자
--              ,VNDR_MA_YN           = p_VNDR_MA_YN              --조치구분(QS007) 1 조치, 0 미조치
--              ,VNDR_MA_DT           = p_VNDR_MA_DT              --업체조치일자
              ,UPD_ID               = p_WRK_ID                  --수정ID 
              ,UPD_DTM              = SYSDATE()                 --수정일시
              ,UPD_IP               = p_WRK_IP                  --수정IP
         WHERE SIT_CD = p_SIT_CD          --현장코드
           AND PLN_YM = p_PLN_YM          --계획년월
           AND PLN_DGR = p_PLN_DGR         --차수구분코드(QS005) 1 1차,2 2차
           AND CUST_CD = p_CUST_CD         --협력업체코드
           AND CTP_CD = p_CTP_CD          --공종코드
           AND UNT_CD = p_UNT_CD          --단위코드
           AND CHK_ITM_CD = p_CHK_ITM_CD      --점검항목코드
           AND ODAY_CHK_DT = p_ODAY_CHK_DT     --일일점검일자
           AND RISK_GRD = p_RISK_GRD        --위험등급(QS09002) 작성
           AND VNDR_SEQ = p_VNDR_SEQ;       --업체순번
                      
           
         SELECT NVL(MAX(EMPE_NO_SEQ), 0)
          INTO v_SEQ
          FROM TQHB_DAYSAFE_NAM
         WHERE SIT_CD = p_SIT_CD          --현장코드
           AND PLN_YM = p_PLN_YM          --계획년월
           AND PLN_DGR = p_PLN_DGR         --차수구분코드(QS005) 1 1차,2 2차
           AND ODAY_CHK_DT = p_ODAY_CHK_DT     --일일점검일자
           AND EMPE_NO = v_EMPE_NO
           AND RISK_GRD = p_RISK_GRD       --위험등급(QS09002) 작성
         ;
           
         -- 안전책임자 변경    
         UPDATE TQHB_DAYSAFE_NAM
         SET EMPE_NO = p_WRK_ID
         WHERE SIT_CD = p_SIT_CD          --현장코드
           AND PLN_YM = p_PLN_YM          --계획년월
           AND PLN_DGR = p_PLN_DGR         --차수구분코드(QS005) 1 1차,2 2차
           AND ODAY_CHK_DT = p_ODAY_CHK_DT     --일일점검일자
           AND EMPE_NO = v_EMPE_NO
           AND EMPE_NO_SEQ = v_SEQ
           AND RISK_GRD = p_RISK_GRD;       --위험등급(QS09002) 작성
           
         -- 부적합 보고서
         IF (p_ODAY_CHK_RSLT = '3' AND v_OLD_NCR_DOC_NO = '*' ) THEN
           		PQHA_NCR_REP_S(
				    'I'                        -- UPDATE FLAG( I: ISNERT, U:UPDATE, D:DELTE)
				,   p_WRK_ID                        -- 사용자 ID 
				,   p_WRK_IP                        -- 사용자 IP 
				,   p_SIT_CD                        -- 현장코드
				,   NULL                    -- 부적합문서번호
				,   NULL                       -- 년도별일련번호
				,   TO_CHAR(SYSDATE(),'YYYYMMDD')                       -- 발행일자
				,   TO_CHAR(SYSDATE()+3,'YYYYMMDD')                     -- 조치기한일자
				,   p_CUST_CD                       -- 협력업체코드
				,   p_VNDR_SEQ                      -- 업체순번
				,   p_CTP_CD                        -- 공종코드
				,   p_NCR_LOC                       -- 발생위치
				,   p_ODAY_CHK_OPIN                 -- 요구사항
				,   p_CHK_ITM_NM                    -- 부적합내용 
				,   p_PHOTO_GRP1                -- 첨부파일그룹사진1
				,   p_PHOTO_DESC_1              -- 사진설명1 
				,   p_PHOTO_GRP2                -- 첨부파일그룹사진2
				,   p_PHOTO_DESC_2              -- 사진설명2
				,   NULL                      -- 작성자
				,   NULL                  -- 발송 1 미발송 0
				,   NULL                  -- 업체통보일자
				,   NULL                   -- 업체조치제목
				,   NULL                -- 업체재발방지대책
				,   NULL                    -- 업체조치일자
				,   '2'                    -- NCR조치(QS025) 1 조치, 2 미조치
				,   NULL                   -- 업체조치내용
				,   NULL                   -- 업체조치자
				,   NULL               -- 업체조치그룹사진1
				,   NULL             -- 업체사진설명1
				,   NULL               -- 업체조치그룹사진2
				,   NULL             -- 업체사진설명2
				,   NULL                  -- 승인요청 1 미요청 0
				,   NULL                  -- 업체승인요청일자
				,   NULL                   -- 발송Y (SMS)
				,   NULL                   -- 승인 1, 반려 2
				,   NULL                   -- 관리자승인일자
				,   NULL                   -- 부적합생성구분  1, 부적합, 2 안전점검, 3 추가위험
				,   '0'                     -- 직영여부
				,   v_OUT
				);
           
	           UPDATE TQHB_DAYSAFE_CHKLST
		           SET NCR_DOC_NO           = v_OUT              --부적합문서번호
		              ,NCR_PUBC_YN          = '1'
		              ,UPD_ID               = p_WRK_ID                  --수정ID 
		              ,UPD_DTM              = SYSDATE()                 --수정일시
		              ,UPD_IP               = p_WRK_IP                  --수정IP
		         WHERE SIT_CD = p_SIT_CD          --현장코드
		           AND PLN_YM = p_PLN_YM          --계획년월
		           AND PLN_DGR = p_PLN_DGR         --차수구분코드(QS005) 1 1차,2 2차
		           AND CUST_CD = p_CUST_CD         --협력업체코드
		           AND CTP_CD = p_CTP_CD          --공종코드
		           AND UNT_CD = p_UNT_CD          --단위코드
		           AND CHK_ITM_CD = p_CHK_ITM_CD      --점검항목코드
		           AND ODAY_CHK_DT = p_ODAY_CHK_DT     --일일점검일자
		           AND RISK_GRD = p_RISK_GRD        --위험등급(QS09002) 작성
		           AND VNDR_SEQ = p_VNDR_SEQ;       --업체순번
           
           -- 부적합 보고서
           ELSIF (p_ODAY_CHK_RSLT != '3' AND v_OLD_NCR_DOC_NO != '*') THEN
           		
	            DELETE 
		          FROM TQHA_NCR_REP
		         WHERE SIT_CD       = p_SIT_CD          -- 현장코드
		           AND NCR_DOC_NO   = v_OLD_NCR_DOC_NO  -- 부적합문서번호
		        ;
           
	           UPDATE TQHB_DAYSAFE_CHKLST
		           SET NCR_DOC_NO           = NULL              --부적합문서번호
		              ,NCR_PUBC_YN          = '0'
		              ,UPD_ID               = p_WRK_ID                  --수정ID 
		              ,UPD_DTM              = SYSDATE()                 --수정일시
		              ,UPD_IP               = p_WRK_IP                  --수정IP
		         WHERE SIT_CD = p_SIT_CD          --현장코드
		           AND PLN_YM = p_PLN_YM          --계획년월
		           AND PLN_DGR = p_PLN_DGR         --차수구분코드(QS005) 1 1차,2 2차
		           AND CUST_CD = p_CUST_CD         --협력업체코드
		           AND CTP_CD = p_CTP_CD          --공종코드
		           AND UNT_CD = p_UNT_CD          --단위코드
		           AND CHK_ITM_CD = p_CHK_ITM_CD      --점검항목코드
		           AND ODAY_CHK_DT = p_ODAY_CHK_DT     --일일점검일자
		           AND RISK_GRD = p_RISK_GRD        --위험등급(QS09002) 작성
		           AND VNDR_SEQ = p_VNDR_SEQ;       --업체순번
           
           END IF;
           
    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 5. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN 
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);
END PQHB_DAYSAFE_CHKLST_S;
/

-- PQHB_DAYSAFE_DT_S (PROCEDURE, VALID)
CREATE PROCEDURE "PQHB_DAYSAFE_DT_S"
                            (p_WRK_TP  VARCHAR2 :='U'                                     -- UPDATE FLAG( I: ISNERT, U:UPDATE, D:DELTE)
                            ,p_WRK_ID  VARCHAR2                                           -- 사용자 ID 
                            ,p_WRK_IP  VARCHAR2                                           -- 사용자 IP 
                            ,p_SIT_CD TQHB_DAYSAFE_DT.SIT_CD%TYPE                         -- 현장코드
                            ,p_PLN_YM TQHB_DAYSAFE_DT.PLN_YM%TYPE                         -- 계획년월
                            ,p_PLN_DGR TQHB_DAYSAFE_DT.PLN_DGR%TYPE                       -- 차수구분코드(QS005) 1 1차,2 2차
                            ,p_ODAY_CHK_DT TQHB_DAYSAFE_DT.ODAY_CHK_DT%TYPE               -- 일일점검일자
                            ,p_RISK_GRD TQHB_DAYSAFE_DT.RISK_GRD%TYPE                     -- 위험등급(QS09002) 작성
                            ,p_EMPE_NO_SAFT TQHB_DAYSAFE_DT.EMPE_NO_SAFT%TYPE             -- 일일안전책임자 사원번호
                            ,p_SAFT_MGR_YN TQHB_DAYSAFE_DT.SAFT_MGR_YN%TYPE               -- 일일안전책임자(승인1 미승인0)
                            ,p_SAFT_MGR_DT TQHB_DAYSAFE_DT.SAFT_MGR_DT%TYPE               -- 일일안전책임자 승인/반려일자
                            ,p_EMPE_NO_OMGR TQHB_DAYSAFE_DT.EMPE_NO_OMGR%TYPE             -- 현장소장 사원번호
                            ,p_SITE_OMGR_YN TQHB_DAYSAFE_DT.SITE_OMGR_YN%TYPE             -- 현장소장(승인1 미승인0)
                            ,p_SITE_OMGR_DT TQHB_DAYSAFE_DT.SITE_OMGR_DT%TYPE             -- 현장소장 승인/반려일자
                            ,p_MGR_OPIN TQHB_DAYSAFE_DT.SITE_OMGR_OPIN%TYPE)        -- 현장소장 승인/반려의견
IS 
    /**************************************************************************************************************************
      Purpose : 

      REVISIONS
      Ver      Date               Author                  Description 
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2026/09/10 17:16:30                         최초생성

    /**************************************************************************************************************************/


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR2(200);            -- ERROR Message
    USER_EXCEPTION EXCEPTION;


BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 필수입력 필드  Check  ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_SIT_CD IS NULL)  THEN
        ERR_MSG := '현장코드는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_PLN_YM IS NULL)  THEN
        ERR_MSG := '계획년월는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_PLN_DGR IS NULL)  THEN
        ERR_MSG := '차수구분코드(QS005) 1 1차,2 2차는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_ODAY_CHK_DT IS NULL)  THEN
        ERR_MSG := '일일점검일자는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_RISK_GRD IS NULL)  THEN
        ERR_MSG := '위험등급(QS09002) 작성는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Process 선행조건 Check ]
    ---------------------------------------------------------------------------------------------------------------------------



    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Business Process ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_WRK_TP ='W1') THEN
        UPDATE TQHB_DAYSAFE_DT
           SET EMPE_NO_SAFT         = p_WRK_ID            --일일안전책임자 사원번호
              ,SAFT_MGR_YN          = p_SAFT_MGR_YN             --일일안전책임자(승인1 미승인0)
              ,SAFT_MGR_DT          = TO_CHAR(SYSDATE(),'YYYYMMDD')             --일일안전책임자 승인/반려일자
              ,SAFT_MGR_OPIN        = p_MGR_OPIN           --일일안전책임자 승인/반려의견
              ,UPD_ID               = p_WRK_ID                  --수정ID 
              ,UPD_DTM              = SYSDATE()                 --수정일시
              ,UPD_IP               = p_WRK_IP                  --수정IP
         WHERE SIT_CD = p_SIT_CD          --현장코드
           AND PLN_YM = p_PLN_YM          --계획년월
           AND PLN_DGR = p_PLN_DGR         --차수구분코드(QS005) 1 1차,2 2차
           AND ODAY_CHK_DT = p_ODAY_CHK_DT     --일일점검일자
           AND RISK_GRD = p_RISK_GRD;       --위험등급(QS09002) 작성

    ELSIF (p_WRK_TP ='W2') THEN
        UPDATE TQHB_DAYSAFE_DT
           SET EMPE_NO_OMGR         = p_WRK_ID              --현장소장 사원번호
              ,SITE_OMGR_YN         = p_SITE_OMGR_YN            --현장소장(승인1 미승인0)
              ,SITE_OMGR_DT         = TO_CHAR(SYSDATE(),'YYYYMMDD')            --현장소장 승인/반려일자
              ,SITE_OMGR_OPIN       = p_MGR_OPIN          --현장소장 승인/반려의견
              ,UPD_ID               = p_WRK_ID                  --수정ID 
              ,UPD_DTM              = SYSDATE()                 --수정일시
              ,UPD_IP               = p_WRK_IP                  --수정IP
         WHERE SIT_CD = p_SIT_CD          --현장코드
           AND PLN_YM = p_PLN_YM          --계획년월
           AND PLN_DGR = p_PLN_DGR         --차수구분코드(QS005) 1 1차,2 2차
           AND ODAY_CHK_DT = p_ODAY_CHK_DT     --일일점검일자
           AND RISK_GRD = p_RISK_GRD;       --위험등급(QS09002) 작성
           
    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 5. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN 
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);
END ;
/

-- PQHB_DAYSAFE_DT_W (PROCEDURE, VALID)
CREATE PROCEDURE "PQHB_DAYSAFE_DT_W"
                            (p_WRK_TP  VARCHAR2 :='U'                                     -- UPDATE FLAG( I: ISNERT, U:UPDATE, D:DELTE)
                            ,p_WRK_ID  VARCHAR2                                           -- 사용자 ID 
                            ,p_WRK_IP  VARCHAR2                                           -- 사용자 IP 
                            ,p_SIT_CD TQHB_DAYSAFE_DT.SIT_CD%TYPE                         -- 현장코드
                            ,p_PLN_YM TQHB_DAYSAFE_DT.PLN_YM%TYPE                         -- 계획년월
                            ,p_PLN_DGR TQHB_DAYSAFE_DT.PLN_DGR%TYPE                       -- 차수구분코드(QS005)
                            ,p_APRS_STR_DT VARCHAR2
                            ,p_APRS_END_DT VARCHAR2
                            )
IS 
    /**************************************************************************************************************************
      Purpose : 
 
      REVISIONS
      Ver      Date               Author                  Description 
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2026/09/04 17:04:01                         최초생성

    /**************************************************************************************************************************/


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR2(200);            -- ERROR Message
    USER_EXCEPTION EXCEPTION;

	v_CNT NUMBER;
BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 필수입력 필드  Check  ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_SIT_CD IS NULL)  THEN
        ERR_MSG := '현장코드는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_PLN_YM IS NULL)  THEN
        ERR_MSG := '계획년월는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_PLN_DGR IS NULL)  THEN
        ERR_MSG := '차수구분코드(QS005) 는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;
    
    IF (p_APRS_STR_DT IS NULL OR p_APRS_END_DT IS NULL)  THEN
        ERR_MSG := '평가기간은 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Process 선행조건 Check ]
    ---------------------------------------------------------------------------------------------------------------------------
  
	SELECT COUNT(1) INTO v_CNT
	FROM TQHB_DAYSAFE_CHKLST
	WHERE 1=1
	AND SIT_CD  = p_SIT_CD
    AND PLN_YM  = p_PLN_YM
    AND PLN_DGR = p_PLN_DGR
    AND EMPE_NO IS NOT NULL
    ;
    
    IF (v_CNT > 0)  THEN
        ERR_MSG := '이미 점검이 시작되어 진행할 수 없습니다.';
        RAISE USER_EXCEPTION;
    END IF;
  
    
    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Business Process ]
    ---------------------------------------------------------------------------------------------------------------------------
    
  
    -- 점검자 초기화
    DELETE FROM TQHB_DAYSAFE_NAM
    WHERE 1=1
	AND SIT_CD  = p_SIT_CD
    AND PLN_YM  = p_PLN_YM
    AND PLN_DGR = p_PLN_DGR;
    
    -- 점검자체크 초기화
    DELETE FROM TQHB_DAYSAFE_CHKLST
    WHERE 1=1
	AND SIT_CD  = p_SIT_CD
    AND PLN_YM  = p_PLN_YM
    AND PLN_DGR = p_PLN_DGR;
    
    -- 점검일자 초기화
    DELETE FROM TQHB_DAYSAFE_DT
    WHERE 1=1
	AND SIT_CD  = p_SIT_CD
    AND PLN_YM  = p_PLN_YM
    AND PLN_DGR = p_PLN_DGR;
    
    
    --중점점검 일자
    INSERT INTO TQHB_DAYSAFE_DT (
	     SIT_CD
	    ,PLN_YM
	    ,PLN_DGR
	    ,ODAY_CHK_DT
	    ,RISK_GRD
	    ,IPT_ID                  --입력ID
	    ,IPT_DTM                 --입력일시
	    ,IPT_IP                  --입력IP
	    ,UPD_ID                  --수정ID
	    ,UPD_DTM                 --수정일시
	    ,UPD_IP                  --수정IP
	)
	SELECT  p_SIT_CD
	       ,p_PLN_YM
	       ,p_PLN_DGR
	       ,TO_CHAR(TO_DATE(p_APRS_STR_DT, 'YYYYMMDD') + LEVEL - 1, 'YYYYMMDD')
	       ,'QS0900201'
	       ,p_WRK_ID                --입력ID 
           ,SYSDATE()               --입력일시
           ,p_WRK_IP                --입력IP
           ,p_WRK_ID                --수정ID
           ,SYSDATE()               --수정일시
           ,p_WRK_IP              --수정IP
	  FROM DUAL
	CONNECT BY LEVEL <= (TO_DATE(p_APRS_END_DT, 'YYYYMMDD') - TO_DATE(p_APRS_STR_DT, 'YYYYMMDD') + 1);

   --일상점검 일자
   INSERT INTO TQHB_DAYSAFE_DT (
	     SIT_CD
	    ,PLN_YM
	    ,PLN_DGR
	    ,ODAY_CHK_DT
	    ,RISK_GRD
	    ,IPT_ID                  --입력ID
	    ,IPT_DTM                 --입력일시
	    ,IPT_IP                  --입력IP
	    ,UPD_ID                  --수정ID
	    ,UPD_DTM                 --수정일시
	    ,UPD_IP                  --수정IP
	)
	SELECT  p_SIT_CD
	       ,p_PLN_YM
	       ,p_PLN_DGR
	       ,TO_CHAR(TO_DATE(p_APRS_STR_DT, 'YYYYMMDD') + LEVEL - 1, 'YYYYMMDD')
	       ,'QS0900202'
	       ,p_WRK_ID                --입력ID 
           ,SYSDATE()               --입력일시
           ,p_WRK_IP                --입력IP
           ,p_WRK_ID                --수정ID
           ,SYSDATE()               --수정일시
           ,p_WRK_IP              --수정IP
	  FROM DUAL
	CONNECT BY LEVEL <= (TO_DATE(p_APRS_END_DT, 'YYYYMMDD') - TO_DATE(p_APRS_STR_DT, 'YYYYMMDD') + 1);
   
    
   -- 위험요인 체크리스트 추가
   INSERT INTO TQHB_DAYSAFE_CHKLST
	(
	     SIT_CD
	    ,PLN_YM
	    ,PLN_DGR
	    ,CUST_CD
	    ,VNDR_SEQ
	    ,CTP_CD
	    ,UNT_CD
	    ,CHK_ITM_CD
	    ,ODAY_CHK_DT
	    ,RISK_GRD
	    ,IPT_ID                  --입력ID
	    ,IPT_DTM                 --입력일시
	    ,IPT_IP                  --입력IP
	    ,UPD_ID                  --수정ID
	    ,UPD_DTM                 --수정일시
	    ,UPD_IP                  --수정IP
	)
	SELECT
	     R.SIT_CD
	    ,R.PLN_YM
	    ,R.PLN_DGR
	    ,R.CUST_CD
	    ,R.VNDR_SEQ
	    ,R.CTP_CD
	    ,R.UNT_CD
	    ,R.CHK_ITM_CD
	    ,D.ODAY_CHK_DT
	    ,D.RISK_GRD
	    ,p_WRK_ID                --입력ID 
        ,SYSDATE()               --입력일시
        ,p_WRK_IP                --입력IP
        ,p_WRK_ID                --수정ID
        ,SYSDATE()               --수정일시
        ,p_WRK_IP              --수정IP
	FROM TQHB_RISK_LST R
	JOIN TQHB_DAYSAFE_DT D
	  ON D.SIT_CD  = R.SIT_CD
	 AND D.PLN_YM  = R.PLN_YM
	 AND D.PLN_DGR = R.PLN_DGR
	 AND D.RISK_GRD = R.RISK_GRD
	WHERE D.SIT_CD      = P_SIT_CD
	  AND D.PLN_YM      = P_PLN_YM
	  AND D.PLN_DGR     = P_PLN_DGR
	  AND R.RISK_GRD != 'QS0900203'
	  ORDER BY 
	    R.SIT_CD,
	    R.PLN_YM,
	    R.PLN_DGR,
	    R.CUST_CD,
	    R.VNDR_SEQ,
	    R.CTP_CD,
	    R.UNT_CD,
	    R.CHK_ITM_CD,
	    D.ODAY_CHK_DT,
	    D.RISK_GRD
	  ;
   

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 5. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN 
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);
END ;
/

-- PQHB_DAYSAFE_NAM_S (PROCEDURE, VALID)
CREATE PROCEDURE "PQHB_DAYSAFE_NAM_S"
                            (p_WRK_TP  VARCHAR2 :='U'                                     -- UPDATE FLAG( I: ISNERT, U:UPDATE, D:DELTE)
                            ,p_WRK_ID  VARCHAR2                                           -- 사용자 ID 
                            ,p_WRK_IP  VARCHAR2                                           -- 사용자 IP 
                            ,p_SIT_CD TQHB_DAYSAFE_NAM.SIT_CD%TYPE                        -- 현장코드
                            ,p_PLN_YM TQHB_DAYSAFE_NAM.PLN_YM%TYPE                        -- 계획년월
                            ,p_PLN_DGR TQHB_DAYSAFE_NAM.PLN_DGR%TYPE                      -- 차수구분코드(QS005) 1 1차,2 2차
                            ,p_ODAY_CHK_DT TQHB_DAYSAFE_NAM.ODAY_CHK_DT%TYPE              -- 일일점검일자
                            ,p_EMPE_NO_SEQ TQHB_DAYSAFE_NAM.EMPE_NO_SEQ%TYPE              -- 일일안전책임자 순번
                            ,p_RISK_GRD TQHB_DAYSAFE_NAM.RISK_GRD%TYPE                    -- 위험등급(QS09002) 작성
                            ,p_EMPE_NO TQHB_DAYSAFE_NAM.EMPE_NO%TYPE)                     -- 일일안전책임자 사번
IS 
    /**************************************************************************************************************************
      Purpose : 

      REVISIONS
      Ver      Date               Author                  Description 
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2026/09/07 18:35:50                         최초생성

    /**************************************************************************************************************************/


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR2(200);            -- ERROR Message
    USER_EXCEPTION EXCEPTION;

	v_SEQ              NUMBER := 0;
BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 필수입력 필드  Check  ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_SIT_CD IS NULL)  THEN
        ERR_MSG := '현장코드는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_PLN_YM IS NULL)  THEN
        ERR_MSG := '계획년월는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_PLN_DGR IS NULL)  THEN
        ERR_MSG := '차수구분코드(QS005) 1 1차,2 2차는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_ODAY_CHK_DT IS NULL)  THEN
        ERR_MSG := '일일점검일자는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_RISK_GRD IS NULL)  THEN
        ERR_MSG := '위험등급(QS09002) 작성는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Process 선행조건 Check ]
    ---------------------------------------------------------------------------------------------------------------------------



    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Business Process ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_WRK_TP ='D') THEN
        DELETE 
          FROM TQHB_DAYSAFE_NAM
         WHERE SIT_CD = p_SIT_CD          --현장코드
           AND PLN_YM = p_PLN_YM          --계획년월
           AND PLN_DGR = p_PLN_DGR         --차수구분코드(QS005) 1 1차,2 2차
           AND ODAY_CHK_DT = p_ODAY_CHK_DT     --일일점검일자
--           AND EMPE_NO_SEQ = p_EMPE_NO_SEQ     --일일안전책임자 순번
           AND RISK_GRD = p_RISK_GRD;       --위험등급(QS09002) 작성

    ELSE 
    
	    SELECT NVL(MAX(EMPE_NO_SEQ), 0) + 1
          INTO v_SEQ
          FROM TQHB_DAYSAFE_NAM
         WHERE SIT_CD = p_SIT_CD          --현장코드
           AND PLN_YM = p_PLN_YM          --계획년월
           AND PLN_DGR = p_PLN_DGR         --차수구분코드(QS005) 1 1차,2 2차
           AND ODAY_CHK_DT = p_ODAY_CHK_DT     --일일점검일자
           AND RISK_GRD = p_RISK_GRD       --위험등급(QS09002) 작성
        ;
        INSERT INTO TQHB_DAYSAFE_NAM
                   ( SIT_CD                  --현장코드
                    ,PLN_YM                  --계획년월
                    ,PLN_DGR                 --차수구분코드(QS005) 1 1차,2 2차
                    ,ODAY_CHK_DT             --일일점검일자
                    ,EMPE_NO_SEQ             --일일안전책임자 순번
                    ,RISK_GRD                --위험등급(QS09002) 작성
                    ,EMPE_NO                 --일일안전책임자 사번
                    ,IPT_ID                  --입력ID
                    ,IPT_DTM                 --입력일시
                    ,IPT_IP                  --입력IP
                    ,UPD_ID                  --수정ID
                    ,UPD_DTM                 --수정일시
                    ,UPD_IP                  --수정IP
                    )
             VALUES (p_SIT_CD                --현장코드
                    ,p_PLN_YM                --계획년월
                    ,p_PLN_DGR               --차수구분코드(QS005) 1 1차,2 2차
                    ,p_ODAY_CHK_DT           --일일점검일자
                    ,v_SEQ                   --일일안전책임자 순번
                    ,p_RISK_GRD              --위험등급(QS09002) 작성
                    ,p_EMPE_NO               --일일안전책임자 사번
                    ,p_WRK_ID                --입력ID 
                    ,SYSDATE()               --입력일시
                    ,p_WRK_IP                --입력IP
                    ,p_WRK_ID                --수정ID
                    ,SYSDATE()               --수정일시
                    ,p_WRK_IP);              --수정IP
    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 5. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN 
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);
END ;
/

-- PQHB_MOBILE_DAYSAFE_S (PROCEDURE, VALID)
CREATE PROCEDURE "PQHB_MOBILE_DAYSAFE_S" (
    p_WRK_TP                VARCHAR2 :='U'                                          -- UPDATE FLAG( I: ISNERT, U:UPDATE, D:DELTE)
,   p_WRK_ID                VARCHAR2                                                -- 사용자 ID
,   p_WRK_IP                VARCHAR2                                                -- 사용자 IP
,   p_SIT_CD                TQHB_DAYSAFE_CHKLST.SIT_CD              %TYPE           -- 현장코드
,   p_PLN_YM                TQHB_DAYSAFE_CHKLST.PLN_YM              %TYPE           -- 계획년월
,   p_PLN_DGR               TQHB_DAYSAFE_CHKLST.PLN_DGR             %TYPE           -- 차수구분코드(QS005) 1 1차,2 2차
,   p_ODAY_CHK_DT           TQHB_DAYSAFE_CHKLST.ODAY_CHK_DT         %TYPE           -- 일일점검일자
,   p_CTP_CD                TQHB_DAYSAFE_CHKLST.CTP_CD              %TYPE           -- 공종코드
,   p_RISK_GRD              TQHB_DAYSAFE_CHKLST.RISK_GRD            %TYPE           -- 위험등급(QS09002) 작성
,   p_CHK_ITM_CD            TQHB_DAYSAFE_CHKLST.CHK_ITM_CD          %TYPE           -- 점검항목코드
,   p_UNT_CD                TQHB_DAYSAFE_CHKLST.UNT_CD              %TYPE           -- 단위코드
,   p_CUST_CD               TQHB_DAYSAFE_CHKLST.CUST_CD             %TYPE           -- 협력업체코드
,   p_ODAY_CHK_RSLT         TQHB_DAYSAFE_CHKLST.ODAY_CHK_RSLT       %TYPE           -- 점검결과(QS006) 1 N/A,2 완료(유지),3 불량
,   p_ODAY_CHK_OPIN         TQHB_DAYSAFE_CHKLST.ODAY_CHK_OPIN       %TYPE           -- 일일점검의견
,   p_PHOTO_GRP1            TQHB_DAYSAFE_CHKLST.PHOTO_GRP1          %TYPE           -- 첨부파일그룹사진1
,   p_PHOTO_DESC_1          TQHB_DAYSAFE_CHKLST.PHOTO_DESC_1        %TYPE           -- 사진설명1
,   p_PHOTO_GRP2            TQHB_DAYSAFE_CHKLST.PHOTO_GRP2          %TYPE           -- 첨부파일그룹사진2
,   p_PHOTO_DESC_2          TQHB_DAYSAFE_CHKLST.PHOTO_DESC_2        %TYPE           -- 사진설명2
,   p_NCR_PUBC_YN           TQHB_DAYSAFE_CHKLST.NCR_PUBC_YN         %TYPE           -- 발행 1, 미발행 0
,   p_NCR_DOC_NO            TQHB_DAYSAFE_CHKLST.NCR_DOC_NO          %TYPE           -- 부적합문서번호
,   p_MA_DDLN_DT            TQHB_DAYSAFE_CHKLST.MA_DDLN_DT          %TYPE           -- 조치기한일자
)
IS
    /**************************************************************************************************************************
      Purpose :

      REVISIONS
      Ver      Date               Author                  Description
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2026/07/29 14:05:11 최준원                    최초생성

    **************************************************************************************************************************/


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR2(200);            -- ERROR Message
    USER_EXCEPTION EXCEPTION;

    v_CNT              NUMBER := 0;
    v_NCR_DOC_NO       VARCHAR2(50);
    v_VNDR_APRV_YN     VARCHAR2(1);
    v_MGR_APRV_YN      VARCHAR2(1);
    
    v_SAFT_MGR_YN      VARCHAR2(1); --점검 안전관리자승인
    v_SITE_OMGR_YN     VARCHAR2(1); --점검 현장소장승인
    
    v_NCR_SEQ       INTEGER;                            -- 안전 부적합순번 MAX
    v_NCR_SEQ1      TQHA_NCR_REP.NCR_DOC_NO%TYPE ;      -- 안전 부적합순번 MAX
    
    
   	v_CTP_CD        TQHB_RISK_LST.CTP_CD%TYPE;     --공종코드
	v_CHK_LOC       TQHB_RISK_LST.CHK_LOC%TYPE;    --점검위치
	v_CHK_ITM_NM    TQHB_RISK_LST.CHK_ITM_NM%TYPE; --점검항목명

BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 필수입력 필드  Check  ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_ODAY_CHK_RSLT IS NULL)  THEN
        ERR_MSG := '점검 결과는 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

	
	IF (p_ODAY_CHK_RSLT <> '1' AND p_ODAY_CHK_OPIN IS NULL)  THEN
        ERR_MSG := '점검의견은 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;



    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Process 선행조건 Check ]
    ---------------------------------------------------------------------------------------------------------------------------

    SELECT NVL(SAFT_MGR_YN, 0)   -- 안전관리자 승인 
        ,  NVL(SITE_OMGR_YN, 0)  -- 현장소장 승인
      INTO v_SAFT_MGR_YN
        ,  v_MGR_APRV_YN
      FROM TQHB_DAYSAFE_DT
     WHERE SIT_CD       = p_SIT_CD      --현장코드
       AND PLN_YM       = p_PLN_YM      --계획년월
       AND PLN_DGR      = p_PLN_DGR     --차수구분코드(QS005) 1 1차,2 2차
       AND ODAY_CHK_DT  = p_ODAY_CHK_DT --일일점검일자
       AND RISK_GRD     = p_RISK_GRD    --위험등급(QS09002) 작성 
       ;
    
    IF  (v_SAFT_MGR_YN = '1' AND v_MGR_APRV_YN = '1') THEN
    	ERR_MSG := '승인이 완료된 날짜의 점검 내역은 변경 할 수 없습니다.';
        RAISE USER_EXCEPTION;
    ELSIF (v_SAFT_MGR_YN = '1' OR v_MGR_APRV_YN = '1') THEN
    	ERR_MSG := '해당 날짜에 대해서 승인이 진행되고 있어 변경 할 수 없습니다.';
        RAISE USER_EXCEPTION;
    END IF;
    

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Business Process ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_WRK_TP ='U') THEN
    
        -- 부적합보고서 승인 상태 체크하여, 업체 승인 요청시 또는 관리자 승인시엔 불량에서 다른걸로 변경하지 못하게 막아야 함.
        SELECT NVL(MAX(NCR_DOC_NO), ' ')
          INTO v_NCR_DOC_NO
          FROM TQHB_DAYSAFE_CHKLST
         WHERE SIT_CD       = p_SIT_CD          --현장코드
           AND PLN_YM       = p_PLN_YM          --계획년월
           AND PLN_DGR      = p_PLN_DGR         --차수구분코드(QS005) 1 1차,2 2차
           AND ODAY_CHK_DT  = p_ODAY_CHK_DT     --일일점검일자
           AND CTP_CD       = p_CTP_CD          --공종코드
           AND CHK_ITM_CD   = p_CHK_ITM_CD      --점검항목코드
           AND UNT_CD       = p_UNT_CD          --단위코드
           AND RISK_GRD     = p_RISK_GRD        --위험등급(QS09002) 작성
        ;

        -- 부적합보고서 번호가 이미 존재하는 경우 수정제어
        IF v_NCR_DOC_NO != ' ' THEN
            SELECT VNDR_APRV_YN
                 , MGR_APRV_YN
              INTO v_VNDR_APRV_YN
                 , v_MGR_APRV_YN
              FROM TQHA_NCR_REP
             WHERE SIT_CD       = p_SIT_CD
               AND NCR_DOC_NO   = v_NCR_DOC_NO
            ;

            IF v_MGR_APRV_YN = '1' THEN
                ERR_MSG := '부적합보고서 관리자가 승인한 상태여서 변경할 수 없습니다.'
                        || CHR(10) || '관리자 반려 후, 업체 승인요청취소 후에 변경 가능합니다. ';
                RAISE USER_EXCEPTION;
            END IF;

            IF v_VNDR_APRV_YN = '1' THEN
                ERR_MSG := '부적합보고서 업체 승인요청중이어서 변경할 수 없습니다.'
                        || CHR(10) || '승인요청 취소 후 변경 가능합니다 ';
                RAISE USER_EXCEPTION;
            END IF;
        END IF;
            
        -- 부적합 보고서 발행한 경우 부적합보고서 테이블 업데이트
        IF p_NCR_PUBC_YN = '1' THEN
            -- 위험성평가에서 위험요소 정보 가져오기
	        SELECT A.CTP_CD       --공종코드
				 , A.CHK_LOC      --점검위치
				 , A.CHK_ITM_NM   --점검항목명
			  INTO v_CTP_CD
			     , v_CHK_LOC
			     , v_CHK_ITM_NM
		      FROM TQHB_RISK_LST A
		     WHERE A.SIT_CD     = p_SIT_CD     
	           AND A.PLN_YM     = p_PLN_YM     
	           AND A.PLN_DGR    = p_PLN_DGR    
	           AND A.CUST_CD    = p_CUST_CD
	           AND A.CTP_CD     = p_CTP_CD     
	           AND A.UNT_CD     = p_UNT_CD
	           AND A.CHK_ITM_CD = p_CHK_ITM_CD;
            
            
            -- 부적합보고서 데이터 유무 체크
            SELECT COUNT(*)
              INTO v_CNT
              FROM TQHA_NCR_REP
             WHERE SIT_CD     = p_SIT_CD
			   AND NCR_DOC_NO = v_NCR_DOC_NO;
            
            IF v_CNT > 0 THEN
            	UPDATE TQHA_NCR_REP
            	   SET PUBC_DT              = p_ODAY_CHK_DT            -- 발행일자
                     , MA_DDLN_DT           = p_MA_DDLN_DT             -- 조치기한일자
                     , CUST_CD              = p_CUST_CD                -- 협력업체코드
                     , VNDR_SEQ             = '1'                      -- 업체순번
                     , CTP_CD               = v_CTP_CD                 -- 공종코드
                     , NCR_LOC              = v_CHK_LOC                -- 발생위치
                     , NCR_MATT             = p_ODAY_CHK_OPIN          -- 요구사항
                     , NCR_CTS              = v_CHK_ITM_NM             -- 부적합내용
                     , NCR_PHOTO_GRP1       = p_PHOTO_GRP1             -- 첨부파일그룹사진1
                     , NCR_PHOTO_DESC_1     = p_PHOTO_DESC_1           -- 사진설명1
                     , NCR_PHOTO_GRP2       = p_PHOTO_GRP2             -- 첨부파일그룹사진2
                     , NCR_PHOTO_DESC_2     = p_PHOTO_DESC_2           -- 사진설명2
                     , NCR_WRTR             = p_WRK_ID                 -- 작성자
			         , NCR_CRT_DIV          = '2'                      -- 부적합생성구분  1, 부적합, 2 안전점검, 3 추가위험
                     , UPD_ID               = p_WRK_ID                 -- 수정ID
                     , UPD_DTM              = SYSDATE()                -- 수정일시
                     , UPD_IP               = p_WRK_IP                 -- 수정IP
                 WHERE SIT_CD     = p_SIT_CD
			       AND NCR_DOC_NO = v_NCR_DOC_NO;
            ELSE
	            -- 안전 부적합문서 번호 생성
	            -- 년도별 순번 생성
	            SELECT NVL( (MAX(NCR_SEQ)+1),'1' )
	              INTO v_NCR_SEQ
	              FROM TQHA_NCR_REP
	             WHERE SUBSTR(PUBC_DT,1,4) = SUBSTR(p_ODAY_CHK_DT,1,4)
	            ;
	            -- 부적합 문서 번호 생성
	            v_NCR_SEQ1      := LPAD(v_NCR_SEQ, 5,'0')     ;
	            v_NCR_DOC_NO    := 'NCR' || SUBSTR(p_ODAY_CHK_DT,1,4) || v_NCR_SEQ1 ;
            
            	INSERT INTO TQHA_NCR_REP(
			           SIT_CD                         -- 현장코드
                     , NCR_DOC_NO                     -- 부적합문서번호
                     , NCR_SEQ                        -- 년도별일련번호
                     , PUBC_DT                        -- 발행일자
                     , MA_DDLN_DT                     -- 조치기한일자
                     , CUST_CD                        -- 협력업체코드
                     , VNDR_SEQ                       -- 업체순번
                     , CTP_CD                         -- 공종코드
                     , NCR_LOC                        -- 발생위치
                     , NCR_MATT                       -- 요구사항
                     , NCR_CTS                        -- 부적합내용
                     , NCR_PHOTO_GRP1                 -- 첨부파일그룹사진1
                     , NCR_PHOTO_DESC_1               -- 사진설명1
                     , NCR_PHOTO_GRP2                 -- 첨부파일그룹사진2
                     , NCR_PHOTO_DESC_2               -- 사진설명2
                     , NCR_WRTR                       -- 작성자
                     , VNDR_MA_YN                     -- NCR조치(QS025) 1 조치, 2 미조치
                     , NCR_CRT_DIV                    -- 부적합생성구분  1, 부적합, 2 안전점검, 3 추가위험
                     , IPT_ID                         -- 입력ID
                     , IPT_DTM                        -- 입력일시
                     , IPT_IP                         -- 입력IP
                     , UPD_ID                         -- 수정ID
                     , UPD_DTM                        -- 수정일시
                     , UPD_IP                         -- 수정IP
		    	)
		    	VALUES (
			          p_SIT_CD                        -- 현장코드    
			        , v_NCR_DOC_NO                    -- 부적합문서번호 
			        , v_NCR_SEQ                       -- 년도별일련번호 
                    , p_ODAY_CHK_DT                   -- 발행일자
                    , p_MA_DDLN_DT                    -- 조치기한일자
                    , p_CUST_CD                       -- 협력업체코드
                    , 1                               -- 협력업체순번
                    , v_CTP_CD                        -- 공종코드
                    , v_CHK_LOC                       -- 발생위치
                    , p_ODAY_CHK_OPIN                 -- 요구사항
                    , v_CHK_ITM_NM                    -- 부적합내용
                    , p_PHOTO_GRP1                    -- 첨부파일 그룹사진1
                    , p_PHOTO_DESC_1                  -- 첨부파일 그룹사진설명1
                    , p_PHOTO_GRP2                    -- 첨부파일 그룹사진2
                    , p_PHOTO_DESC_2                  -- 첨부파일 그룹사진설명2
                    , p_WRK_ID                        -- 작성자
                    , '2'                             -- 업체조치여부
                    , '2'                             -- 부적합보고서 생성구분( 1, 부적합, 2 안전점검, 3 추가위험 )
                    , p_WRK_ID                        -- 입력ID
                    , SYSDATE()                       -- 입력일시
                    , p_WRK_IP                        -- 입력IP
                    , p_WRK_ID                        -- 수정ID
                    , SYSDATE()                       -- 수정일시
                    , p_WRK_IP                        -- 수정IP
			    );
            END IF;
        ELSE
        	v_NCR_DOC_NO := '';
        END IF;
	

		--본 테이블 업데이트
        UPDATE TQHB_DAYSAFE_CHKLST
           SET ODAY_CHK_RSLT        = p_ODAY_CHK_RSLT           -- 점검결과(QS006) 1 N/A,2 완료(유지),3 불량
             , ODAY_CHK_OPIN        = p_ODAY_CHK_OPIN           -- 일일점검의견
             , EMPE_NO              = p_WRK_ID                  -- 일일점검자
             , PHOTO_GRP1           = p_PHOTO_GRP1              -- 첨부파일그룹사진1
             , PHOTO_DESC_1         = p_PHOTO_DESC_1            -- 사진설명1
             , PHOTO_GRP2           = p_PHOTO_GRP2              -- 첨부파일그룹사진2
             , PHOTO_DESC_2         = p_PHOTO_DESC_2            -- 사진설명2
             , NCR_PUBC_YN          = p_NCR_PUBC_YN             -- 발행 1, 미발행 0
             , NCR_DOC_NO           = v_NCR_DOC_NO              -- 부적합문서번호
             , MA_DDLN_DT           = p_MA_DDLN_DT              -- 조치기한일자
             , UPD_ID               = p_WRK_ID                  -- 수정ID
             , UPD_DTM              = SYSDATE()                 -- 수정일시
             , UPD_IP               = p_WRK_IP                  -- 수정IP
         WHERE SIT_CD               = p_SIT_CD                  -- 현장코드
           AND PLN_YM               = p_PLN_YM                  -- 계획년월
           AND PLN_DGR              = p_PLN_DGR                 -- 차수구분코드(QS005) 1 1차,2 2차
           AND ODAY_CHK_DT          = p_ODAY_CHK_DT             -- 일일점검일자
           AND CTP_CD               = p_CTP_CD                  -- 공종코드
           AND CHK_ITM_CD           = p_CHK_ITM_CD              -- 점검항목코드
           AND UNT_CD               = p_UNT_CD                  -- 단위코드
           AND RISK_GRD             = p_RISK_GRD                -- 위험등급(QS09002) 작성
        ;
        
    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 5. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);
END PQHB_MOBILE_DAYSAFE_S;
/

-- PQHB_MOBILE_SUGGESTION_S (PROCEDURE, VALID)
CREATE PROCEDURE "PQHB_MOBILE_SUGGESTION_S" (
							  p_WRK_TP          VARCHAR2 :='U'                  -- UPDATE FLAG( I: ISNERT, U:UPDATE, D:DELTE)
							, p_WRK_IP          VARCHAR2                        -- 사용자 IP
							, p_SIT_CD          TQHB_STOP_WK.SIT_CD      %TYPE  -- 현장코드
							, p_STOP_DIV        TQHB_STOP_WK.STOP_DIV    %TYPE  -- 유형(1:소리함, 2:작업중지)
			                , p_CHK_MATT        TQHB_STOP_WK.CHK_MATT    %TYPE  -- 발생내용
			                , p_CUST_NM         TQHB_STOP_WK.CUST_NM     %TYPE  -- 거래처명
			                , p_INSP_PNM        TQHB_STOP_WK.INSP_PNM    %TYPE  -- 요청자성명
			                , p_ATFL_GRP        TQHB_STOP_WK.ATFL_GRP    %TYPE  -- 첨부파일그룹
							)
IS
    /**************************************************************************************************************************
      Purpose :

      REVISIONS
      Ver      Date               Author                  Description
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2026/08/10 13:11:11 최준원                    최초생성

    **************************************************************************************************************************/


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR2(200);            -- ERROR Message
    USER_EXCEPTION EXCEPTION;

    v_CNT              NUMBER := 0;
    v_TODAY            VARCHAR2(8) := TO_CHAR(SYSDATE, 'YYYYMMDD');
    v_SEQ              NUMBER := 0;


BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 필수입력 필드  Check  ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_SIT_CD IS NULL)  THEN
        ERR_MSG := '현장은 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Process 선행조건 Check ]
    ---------------------------------------------------------------------------------------------------------------------------


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Business Process ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_WRK_TP ='I') THEN
    
        --실존하는 현장인지 확인
    	SELECT COUNT(*)
    	  INTO v_CNT
          FROM TCMZ_SIT A
               LEFT OUTER JOIN TQHA_SAFT_SIT   K ON A.SIT_CD  = K.SIT_CD
         WHERE A.SIT_CD = p_SIT_CD;
    	
    	IF (v_CNT = 0) THEN
    		ERR_MSG := '잘못된 현장정보입니다. 관리자에게 문의해주세요.';
       		RAISE USER_EXCEPTION;
    	END IF;
    
        -- 같은 일시에 입력한 경우를 방지해, SEQ max값 구하기
        SELECT NVL(MAX(STOP_SEQ), 0) + 1
          INTO v_SEQ
          FROM TQHB_STOP_WK
         WHERE SIT_CD       = p_SIT_CD          --현장코드
           AND STOP_DIV     = p_STOP_DIV        --유형(1:소리함, 2:작업중지)
           AND STOP_DT      = v_TODAY           --발생일시
        ;-- 입력 IP
	
       	INSERT INTO TQHB_STOP_WK(
       		 SIT_CD                         -- 현장코드             
			,STOP_DIV                       -- 유형(1:소리함, 2:작업중지)
			,STOP_DT                        -- 발생일시
			,STOP_SEQ                       -- 발생순번
			,CHK_MATT                       -- 발생내용 
			,CUST_NM                        -- 거래처명 
			,INSP_PNM                       -- 요청자성명
			,ATFL_GRP2                      -- 첨부파일
			,IPT_ID                         -- 입력ID
			,IPT_DTM                        -- 입력일시
			,IPT_IP                         -- 입력IP
       	) VALUES(                           
       		 p_SIT_CD                       -- 현장코드                 
			,p_STOP_DIV                     -- 유형(1:소리함, 2:작업중지)    
			,v_TODAY                        -- 발생일시                 
			,v_SEQ                          -- 발생순번                 
			,NVL(p_CHK_MATT, '작업중지 요청')  -- 발생내용                 
			,p_CUST_NM                      -- 거래처명                 
			,p_INSP_PNM                     -- 요청자성명     
			,p_ATFL_GRP                     -- 첨부파일           
			,'MOBILE'                       -- 입력ID                 
			,SYSDATE                        -- 입력일시                 
			,p_WRK_IP                       -- 입력IP                 
       	);
         
    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 5. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);
END PQHB_MOBILE_SUGGESTION_S;
/

-- PQHB_RISK_CHK_Q (PROCEDURE, VALID)
CREATE PROCEDURE "PQHB_RISK_CHK_Q"
(
      p_WRK_TP  VARCHAR2 DEFAULT 'Q'                                                       -- FLAG( Q: SELECT )
     ,p_SIT_CD TQHB_RISK_CHK.SIT_CD%TYPE                                                  -- 현장코드
     ,p_PLN_YM TQHB_RISK_CHK.PLN_YM%TYPE                                                  -- 계획년월
     ,p_PLN_DGR TQHB_RISK_CHK.PLN_DGR%TYPE                                                -- 차수구분코드(QS005) 1 1차,2 2차
     ,p_CUST_CD TQHB_RISK_CHK.CUST_CD%TYPE                                                -- 협력업체코드
     ,p_VNDR_SEQ TQHB_RISK_CHK.VNDR_SEQ%TYPE                                              -- 업체순번     
     ,RTN_CURSOR OUT SYS_REFCURSOR
)
IS 
    /**************************************************************************************************************************
      Purpose : 

      REVISIONS
      Ver      Date               Author                  Description 
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2026/08/27 14:47:26                         최초생성

    /**************************************************************************************************************************/


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR2(200);            -- ERROR Message
    USER_EXCEPTION EXCEPTION;


BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 수행전 Check Logic ]
    ---------------------------------------------------------------------------------------------------------------------------


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Logic 처리
    ---------------------------------------------------------------------------------------------------------------------------

    OPEN RTN_CURSOR FOR
    WITH BASE_DATA AS (
    SELECT A.SIT_CD                 -- 현장코드
          ,A.PLN_YM                 -- 계획년월
          ,A.PLN_DGR                -- 차수구분코드(QS005) 1 1차,2 2차
          ,A.CUST_CD                -- 협력업체코드
          ,A.VNDR_SEQ               -- 협력업체순번
          ,(SELECT CUST_NM FROM VQSZ_TRADE WHERE CUST_CD = A.CUST_CD) AS CUST_NM
          ,A.CTP_CD                 -- 공종코드
          ,A.UNT_CD                 -- 단위코드
          ,(SELECT CTP_NM FROM TQHA_CTP WHERE CTP_CD = A.CTP_CD) AS CTP_NM
          ,(SELECT UNT_NM FROM TQHA_CTPUNT WHERE CTP_CD = A.CTP_CD AND UNT_CD = A.UNT_CD) AS UNT_NM
          ,A.CHK_ITM_CD             -- 점검항목코드
          ,A.CHK_ITM_SEQ            -- 점검항목 정열순서
          ,A.CHK_ITM_NM             -- 점검항목명
          ,A.CHK_LOC                -- 점검위치
          ,A.DISS_SHP                -- 재해형태(QS036)
          ,A.IMPRV_CPLN             -- 개선대책 (TQHB_RISK_LST)
          ,A.WRK_PSNNO              -- 작업인원
          ,A.ITM_ADD_YN             -- 기존 : 0, 추가 : 1
          -- [TQHB_RISK_NAM 명단 컬럼]
          ,B.EMPE_NO                -- 사원번호
          ,B.APRS_NAMSEQ            -- 점검자 정열순서
          ,B.CO_DIV_CD              -- 회사구분코드
          ,B.JB_CD                  -- 직무/직급코드
          ,NVL((SELECT CD_NM FROM TCOA_COMCODE WHERE COM_CD = B.JB_CD AND HRNK_CD = 'QS077' AND USE_YN = '1'), '') AS JB_NM
          ,CASE WHEN B.CO_DIV_CD = '1' THEN (SELECT USR_NM FROM TCOZ_USR_INFO WHERE EMPNO = B.EMPE_NO) 
                                            || '/' || NVL((SELECT CD_NM FROM TCOA_COMCODE WHERE COM_CD = B.JB_CD AND HRNK_CD = 'QS077' AND USE_YN = '1'), '')
                WHEN B.CO_DIV_CD = '2' THEN (SELECT PNM FROM TQHB_VNDRNAM WHERE SIT_CD = A.SIT_CD AND CUST_CD = A.CUST_CD AND VNDR_SEQ = A.VNDR_SEQ AND EMPE_NO = B.EMPE_NO) 
                                            || '/' || NVL((SELECT CD_NM FROM TCOA_COMCODE WHERE COM_CD = B.JB_CD AND HRNK_CD = 'QS077' AND USE_YN = '1'), '')
           END AS USR_NM
           
          -- [TQHB_RISK_CHK 실제 작성자 본인의 점수만 매핑 (미입력자는 NULL)]
          ,TO_NUMBER(C.RISK_FREQ)  AS RISK_FREQ   
          ,TO_NUMBER(C.RISK_APRV)  AS RISK_APRV   
          ,TO_NUMBER(C.RISK_CRIT)  AS RISK_CRIT   
          ,C.RISK_GRD                            
          ,TO_NUMBER(C.RISK_FREQ2) AS RISK_FREQ2  
          ,TO_NUMBER(C.RISK_APRV2) AS RISK_APRV2  
          ,TO_NUMBER(C.RISK_CRIT2) AS RISK_CRIT2  
          ,C.RISK_GRD2                            
          ,C.MGR_OPIN               
          ,C.SBM_DT                 
          ,C.SBM_YN                 
      FROM TQHB_RISK_LST A
      -- 1. 해당 조건의 전체 점검자 명단 조인 (점검자 명단 N개 생성)
      INNER JOIN TQHB_RISK_NAM B
        ON A.SIT_CD   = B.SIT_CD
       AND A.PLN_YM   = B.PLN_YM
       AND A.PLN_DGR  = B.PLN_DGR
       AND A.CUST_CD  = B.CUST_CD
       AND A.VNDR_SEQ = B.VNDR_SEQ
      -- 2. 해당 점검자가 실제 점수를 작성했는지 사원번호(EMPE_NO)까지 확인하여 LEFT JOIN
      LEFT JOIN TQHB_RISK_CHK C
        ON A.SIT_CD     = C.SIT_CD
       AND A.PLN_YM     = C.PLN_YM
       AND A.PLN_DGR    = C.PLN_DGR
       AND A.CUST_CD    = C.CUST_CD
       AND A.VNDR_SEQ   = C.VNDR_SEQ
       AND A.CTP_CD     = C.CTP_CD
       AND A.UNT_CD     = C.UNT_CD
       AND A.CHK_ITM_CD = C.CHK_ITM_CD
       AND B.EMPE_NO    = C.EMPE_NO  -- ★ 본인이 작성한 점수만 매핑
     WHERE A.SIT_CD   = p_SIT_CD                      -- 현장코드
	   AND A.PLN_YM   = p_PLN_YM                      -- 계획년월
	   AND A.PLN_DGR  = p_PLN_DGR                     -- 차수구분코드(QS005) 1 1차,2 2차
	   AND A.CUST_CD  = p_CUST_CD                     -- 협력업체코드
	   AND A.VNDR_SEQ = p_VNDR_SEQ                    -- 협력업체순번
	),
	SUMMARY_DATA AS (
	    -- 1. 원래 조회 데이터 (의도된 카티전 곱/다건 출력 유지)
	    SELECT SIT_CD, PLN_YM, PLN_DGR, CUST_CD, VNDR_SEQ, CUST_NM
	          ,CTP_CD, UNT_CD, CTP_NM, UNT_NM, CHK_ITM_CD, CHK_ITM_SEQ, CHK_ITM_NM
	          ,CHK_LOC, DISS_SHP, IMPRV_CPLN, WRK_PSNNO, ITM_ADD_YN
	          ,1 AS ROW_DIV
	          ,APRS_NAMSEQ
	          ,EMPE_NO
	          ,CO_DIV_CD
	          ,JB_CD
	          ,JB_NM
	          ,SBM_YN
	          ,USR_NM
	          ,TO_CHAR(RISK_FREQ)  AS RISK_FREQ
	          ,TO_CHAR(RISK_APRV)  AS RISK_APRV
	          ,TO_CHAR(RISK_CRIT)  AS RISK_CRIT
	          ,TO_CHAR(RISK_CRIT2) AS RISK_CRIT2
	          ,MGR_OPIN
	      FROM BASE_DATA
	
	    UNION ALL
	
	    -- 2. 평균점수 행 (각 위험요인 항목별 평균)
	    SELECT SIT_CD, PLN_YM, PLN_DGR, CUST_CD, VNDR_SEQ, CUST_NM
	          ,CTP_CD, UNT_CD, CTP_NM, UNT_NM, CHK_ITM_CD, CHK_ITM_SEQ, CHK_ITM_NM
	          ,CHK_LOC, DISS_SHP, IMPRV_CPLN, WRK_PSNNO, ITM_ADD_YN
	          ,2 AS ROW_DIV
	          ,998 AS APRS_NAMSEQ
	          ,NULL AS EMPE_NO
	          ,NULL AS CO_DIV_CD
	          ,NULL AS JB_CD
	          ,NULL AS JB_NM
	          ,NULL AS SBM_YN
	          ,'평균점수' AS USR_NM
	          ,NULL AS RISK_FREQ
	          ,NULL AS RISK_APRV
	          ,TO_CHAR(ROUND(AVG(RISK_CRIT), 1))  AS RISK_CRIT  -- 위험성 평균
	          ,TO_CHAR(ROUND(AVG(RISK_CRIT2), 1)) AS RISK_CRIT2 -- 개선후 위험성 평균
	          ,NULL AS MGR_OPIN
	      FROM BASE_DATA
	     GROUP BY SIT_CD, PLN_YM, PLN_DGR, CUST_CD, VNDR_SEQ, CUST_NM
	             ,CTP_CD, UNT_CD, CTP_NM, UNT_NM, CHK_ITM_CD, CHK_ITM_SEQ, CHK_ITM_NM
	             ,CHK_LOC, DISS_SHP, IMPRV_CPLN, WRK_PSNNO, ITM_ADD_YN
	
	    UNION ALL
	
	    -- 3. 최종점수 행 (각 위험요인 항목별 최종)
	    SELECT SIT_CD
	          ,PLN_YM
	          ,PLN_DGR
	          ,CUST_CD
	          ,VNDR_SEQ
	          ,(SELECT CUST_NM FROM VQSZ_TRADE WHERE CUST_CD = A.CUST_CD) AS CUST_NM
	          ,CTP_CD
	          ,UNT_CD
	          ,(SELECT CTP_NM FROM TQHA_CTP WHERE CTP_CD = A.CTP_CD) AS CTP_NM
	          ,(SELECT UNT_NM FROM TQHA_CTPUNT WHERE CTP_CD = A.CTP_CD AND UNT_CD = A.UNT_CD) AS UNT_NM
	          ,CHK_ITM_CD
	          ,CHK_ITM_SEQ
	          ,CHK_ITM_NM
	          ,CHK_LOC
	          ,DISS_SHP
	          ,IMPRV_CPLN
	          ,WRK_PSNNO
	          ,ITM_ADD_YN
	          ,3 AS ROW_DIV
	          ,999 AS APRS_NAMSEQ
	          ,NULL AS EMPE_NO
	          ,NULL AS CO_DIV_CD
	          ,NULL AS JB_CD
	          ,NULL AS JB_NM
	          ,NULL AS SBM_YN
	          ,'최종점수' AS USR_NM
	          ,NULL AS RISK_FREQ
	          ,NULL AS RISK_APRV
	          ,TO_CHAR(RISK_CRIT)  AS RISK_CRIT   -- TQHB_RISK_LST의 위험성 점수
	          ,TO_CHAR(RISK_CRIT2) AS RISK_CRIT2  -- TQHB_RISK_LST의 개선후 위험성 점수
	          ,MGR_OPIN
	      FROM TQHB_RISK_LST A
	      WHERE SIT_CD   = p_SIT_CD                      -- 현장코드
	 	    AND PLN_YM   = p_PLN_YM                      -- 계획년월
	   	    AND PLN_DGR  = p_PLN_DGR                     -- 차수구분코드(QS005) 1 1차,2 2차
	   	  	AND CUST_CD  = p_CUST_CD                     -- 협력업체코드
	   		AND VNDR_SEQ = p_VNDR_SEQ                    -- 협력업체순번
	)
	SELECT SIT_CD
	      ,PLN_YM
	      ,PLN_DGR
	      ,CUST_CD
	      ,VNDR_SEQ
	      ,CUST_NM
	      ,CTP_CD
	      ,UNT_CD
	      ,CTP_NM
	      ,UNT_NM
	      ,CHK_ITM_CD
	      ,CHK_ITM_SEQ
	      ,CHK_ITM_NM
	      ,CHK_LOC
	      ,DISS_SHP
	      ,IMPRV_CPLN
	      ,WRK_PSNNO
	      ,ITM_ADD_YN
	      ,RISK_FREQ      -- 빈도 (평균행에는 평균값 표시)
	      ,RISK_APRV      -- 강도 (평균행에는 평균값 표시)
	      ,RISK_CRIT      -- 위험성 (평균/최종행에 표시)
	      ,RISK_CRIT2     -- 개선후 위험성 (평균/최종행에 표시)
	      ,MGR_OPIN
	      ,EMPE_NO
	      ,APRS_NAMSEQ
	      ,CO_DIV_CD
	      ,JB_CD
	      ,JB_NM          -- 직급명
	      ,USR_NM         -- 사용자명/직급명
          ,SBM_YN  
          ,(
          		SELECT SBM_YN
				FROM TQHB_RISK_VNDR
				WHERE 1=1
				AND SIT_CD        = p_SIT_CD
				AND PLN_YM        = p_PLN_YM
				AND PLN_DGR       = p_PLN_DGR
				AND CUST_CD       = p_CUST_CD
				AND VNDR_SEQ      = p_VNDR_SEQ 
           ) AS VNDR_SBM_YN
	  FROM SUMMARY_DATA
	 ORDER BY CTP_CD, UNT_CD, CHK_ITM_CD, DISS_SHP, ROW_DIV, APRS_NAMSEQ
 ;
    
    
    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN 
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);
END ;
/

-- PQHB_RISK_CHK_S (PROCEDURE, VALID)
CREATE PROCEDURE "PQHB_RISK_CHK_S"
                            (p_WRK_TP  VARCHAR2 :='U'                                     -- UPDATE FLAG( I: ISNERT, U:UPDATE, D:DELTE)
                            ,p_WRK_ID  VARCHAR2                                           -- 사용자 ID 
                            ,p_WRK_IP  VARCHAR2                                           -- 사용자 IP 
                            ,p_SIT_CD TQHB_RISK_CHK.SIT_CD%TYPE                           -- 현장코드
                            ,p_PLN_YM TQHB_RISK_CHK.PLN_YM%TYPE                           -- 계획년월
                            ,p_PLN_DGR TQHB_RISK_CHK.PLN_DGR%TYPE                         -- 차수구분코드(QS005) 1 1차,2 2차
                            ,p_CUST_CD TQHB_RISK_CHK.CUST_CD%TYPE                         -- 협력업체코드
                            ,p_VNDR_SEQ TQHB_RISK_CHK.VNDR_SEQ%TYPE                       -- 업체순번
                            ,p_CTP_CD TQHB_RISK_CHK.CTP_CD%TYPE                           -- 공종코드
                            ,p_UNT_CD TQHB_RISK_CHK.UNT_CD%TYPE                           -- 단위코드
                            ,p_CHK_ITM_CD TQHB_RISK_CHK.CHK_ITM_CD%TYPE                   -- 점검항목코드
                            ,p_EMPE_NO TQHB_RISK_CHK.EMPE_NO%TYPE                         -- 사원번호
                            ,p_APRS_NAMSEQ TQHB_RISK_CHK.APRS_NAMSEQ%TYPE                 -- 점검자 정열순서
                            ,p_RISK_FREQ TQHB_RISK_CHK.RISK_FREQ%TYPE                     -- 빈도(QS09003) 작성
                            ,p_RISK_APRV TQHB_RISK_CHK.RISK_APRV%TYPE                     -- 강도(QS09004) 작성
                            ,p_RISK_CRIT TQHB_RISK_CHK.RISK_CRIT%TYPE                     -- 위험성(QS09001) 작성
                            ,p_RISK_GRD TQHB_RISK_CHK.RISK_GRD%TYPE                       -- 위험등급(QS09002) 작성
                            ,p_IMPRV_CPLN TQHB_RISK_CHK.IMPRV_CPLN%TYPE                   -- 개선대책
                            ,p_RISK_FREQ2 TQHB_RISK_CHK.RISK_FREQ2%TYPE                   -- 개선후_빈도(QS09003) 작성
                            ,p_RISK_APRV2 TQHB_RISK_CHK.RISK_APRV2%TYPE                   -- 개선후_강도(QS09004) 작성
                            ,p_RISK_CRIT2 TQHB_RISK_CHK.RISK_CRIT2%TYPE                   -- 개선후_위험성(QS09001) 작성
                            ,p_RISK_GRD2 TQHB_RISK_CHK.RISK_GRD2%TYPE                     -- 개선후_위험등급(QS09002) 작성
                            ,p_DTY_CD TQHB_RISK_CHK.DTY_CD%TYPE                           -- 직책코드
                            ,p_MGR_OPIN TQHB_RISK_CHK.MGR_OPIN%TYPE                       -- 관리자의견
                            ,p_SBM_DT TQHB_RISK_CHK.SBM_DT%TYPE                           -- 제출일자
                            ,p_SBM_YN TQHB_RISK_CHK.SBM_YN%TYPE                           -- 제출1 미제출0
                            )
IS 
    /**************************************************************************************************************************
      Purpose : 

      REVISIONS
      Ver      Date               Author                  Description 
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2026/08/27 14:48:50                         최초생성

    /**************************************************************************************************************************/


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR2(200);            -- ERROR Message
    USER_EXCEPTION EXCEPTION;

	v_CNT NUMBER;
    v_WRK_TP VARCHAR2(1);
BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 필수입력 필드  Check  ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_SIT_CD IS NULL)  THEN
        ERR_MSG := '현장코드는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_PLN_YM IS NULL)  THEN
        ERR_MSG := '계획년월는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_PLN_DGR IS NULL)  THEN
        ERR_MSG := '차수구분코드(QS005) 1 1차,2 2차는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_CUST_CD IS NULL)  THEN
        ERR_MSG := '협력업체코드는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_CTP_CD IS NULL)  THEN
        ERR_MSG := '공종코드는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_UNT_CD IS NULL)  THEN
        ERR_MSG := '단위코드는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_CHK_ITM_CD IS NULL)  THEN
        ERR_MSG := '점검항목코드는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;
--
--    IF (p_EMPE_NO IS NULL)  THEN
--        ERR_MSG := '사원번호는(은) 필수 입력사항 입니다.';
--        RAISE USER_EXCEPTION;
--    END IF;

    IF (p_VNDR_SEQ IS NULL)  THEN
        ERR_MSG := '업체순번는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Process 선행조건 Check ]
    ---------------------------------------------------------------------------------------------------------------------------
    -- TQHB_RISK_CHK 점수등록
    IF (p_EMPE_NO IS NOT NULL)  THEN
    
		SELECT COUNT(1) INTO v_CNT
	          FROM TQHB_RISK_CHK
	         WHERE SIT_CD = p_SIT_CD          --현장코드
	           AND PLN_YM = p_PLN_YM          --계획년월
	           AND PLN_DGR = p_PLN_DGR         --차수구분코드(QS005) 1 1차,2 2차
	           AND CUST_CD = p_CUST_CD         --협력업체코드
	           AND VNDR_SEQ = p_VNDR_SEQ       --업체순번
	           AND CTP_CD = p_CTP_CD          --공종코드
	           AND UNT_CD = p_UNT_CD          --단위코드
	           AND CHK_ITM_CD = p_CHK_ITM_CD      --점검항목코드
	           AND EMPE_NO = p_EMPE_NO;         --사원번호
	    
		IF (v_CNT > 0)  THEN
	        v_WRK_TP := 'U';
	    ELSE
	    	v_WRK_TP := 'I';
	    END IF;
		
	    ---------------------------------------------------------------------------------------------------------------------------
	    -- ▩▩ [ 4. Business Process ]
	    ---------------------------------------------------------------------------------------------------------------------------
	    IF (v_WRK_TP ='D') THEN
	        DELETE 
	          FROM TQHB_RISK_CHK
	         WHERE SIT_CD = p_SIT_CD          --현장코드
	           AND PLN_YM = p_PLN_YM          --계획년월
	           AND PLN_DGR = p_PLN_DGR         --차수구분코드(QS005) 1 1차,2 2차
	           AND CUST_CD = p_CUST_CD         --협력업체코드
	           AND VNDR_SEQ = p_VNDR_SEQ       --업체순번
	           AND CTP_CD = p_CTP_CD          --공종코드
	           AND UNT_CD = p_UNT_CD          --단위코드
	           AND CHK_ITM_CD = p_CHK_ITM_CD      --점검항목코드
	           AND EMPE_NO = p_EMPE_NO         --사원번호
	           ;
	
	    ELSIF (v_WRK_TP ='U') THEN
	        UPDATE TQHB_RISK_CHK
	           SET RISK_FREQ            = p_RISK_FREQ               --빈도(QS09003) 작성
	              ,RISK_APRV            = p_RISK_APRV               --강도(QS09004) 작성
	              ,RISK_CRIT            = p_RISK_CRIT               --위험성(QS09001) 작성
	              ,RISK_GRD             = CASE 
											    WHEN TRUNC(TO_NUMBER(p_RISK_CRIT)) BETWEEN 1 AND 5   THEN 'QS0900203'
											    WHEN TRUNC(TO_NUMBER(p_RISK_CRIT)) BETWEEN 6 AND 12  THEN 'QS0900202'
											    WHEN TRUNC(TO_NUMBER(p_RISK_CRIT)) BETWEEN 13 AND 99 THEN 'QS0900201'
											    ELSE NULL
											END
	              ,IMPRV_CPLN           = p_IMPRV_CPLN              --개선대책
	              ,RISK_FREQ2           = p_RISK_FREQ2              --개선후_빈도(QS09003) 작성
	              ,RISK_APRV2           = p_RISK_APRV2              --개선후_강도(QS09004) 작성
	              ,RISK_CRIT2           = p_RISK_CRIT2              --개선후_위험성(QS09001) 작성
	              ,RISK_GRD2            = p_RISK_GRD2               --개선후_위험등급(QS09002) 작성
	              ,MGR_OPIN             = p_MGR_OPIN                --관리자의견
	              ,UPD_ID               = p_WRK_ID                  --수정ID 
	              ,UPD_DTM              = SYSDATE()                 --수정일시
	              ,UPD_IP               = p_WRK_IP                  --수정IP
	         WHERE SIT_CD = p_SIT_CD          --현장코드
	           AND PLN_YM = p_PLN_YM          --계획년월
	           AND PLN_DGR = p_PLN_DGR         --차수구분코드(QS005) 1 1차,2 2차
	           AND CUST_CD = p_CUST_CD         --협력업체코드
	           AND VNDR_SEQ = p_VNDR_SEQ       --업체순번
	           AND CTP_CD = p_CTP_CD          --공종코드
	           AND UNT_CD = p_UNT_CD          --단위코드
	           AND CHK_ITM_CD = p_CHK_ITM_CD      --점검항목코드
	           AND EMPE_NO = p_EMPE_NO         --사원번호
	           ;
	    
	    ELSE 
	        INSERT INTO TQHB_RISK_CHK
	                   ( SIT_CD                  --현장코드
	                    ,PLN_YM                  --계획년월
	                    ,PLN_DGR                 --차수구분코드(QS005) 1 1차,2 2차
	                    ,CUST_CD                 --협력업체코드
	                    ,VNDR_SEQ                --업체순번
	                    ,CTP_CD                  --공종코드
	                    ,UNT_CD                  --단위코드
	                    ,CHK_ITM_CD              --점검항목코드
	                    ,EMPE_NO                 --사원번호
	                    ,APRS_NAMSEQ             --점검자 정열순서
	                    ,RISK_FREQ               --빈도(QS09003) 작성
	                    ,RISK_APRV               --강도(QS09004) 작성
	                    ,RISK_CRIT               --위험성(QS09001) 작성
	                    ,RISK_GRD                --위험등급(QS09002) 작성
	                    ,IMPRV_CPLN              --개선대책
	                    ,RISK_FREQ2              --개선후_빈도(QS09003) 작성
	                    ,RISK_APRV2              --개선후_강도(QS09004) 작성
	                    ,RISK_CRIT2              --개선후_위험성(QS09001) 작성
	                    ,RISK_GRD2               --개선후_위험등급(QS09002) 작성
	                    ,DTY_CD                  --직책코드
	                    ,MGR_OPIN                --관리자의견
	                    ,SBM_DT                  --제출일자
	                    ,SBM_YN                  --제출1 미제출0
	                    ,IPT_ID                  --입력ID
	                    ,IPT_DTM                 --입력일시
	                    ,IPT_IP                  --입력IP
	                    ,UPD_ID                  --수정ID
	                    ,UPD_DTM                 --수정일시
	                    ,UPD_IP                  --수정IP
						)
	             VALUES (p_SIT_CD                --현장코드
	                    ,p_PLN_YM                --계획년월
	                    ,p_PLN_DGR               --차수구분코드(QS005) 1 1차,2 2차
	                    ,p_CUST_CD               --협력업체코드
	                    ,p_VNDR_SEQ              --업체순번
	                    ,p_CTP_CD                --공종코드
	                    ,p_UNT_CD                --단위코드
	                    ,p_CHK_ITM_CD            --점검항목코드
	                    ,p_EMPE_NO               --사원번호
	                    ,p_APRS_NAMSEQ           --점검자 정열순서
	                    ,p_RISK_FREQ             --빈도(QS09003) 작성
	                    ,p_RISK_APRV             --강도(QS09004) 작성
	                    ,p_RISK_CRIT             --위험성(QS09001) 작성
	                    ,CASE 
						    WHEN TRUNC(TO_NUMBER(p_RISK_CRIT)) BETWEEN 1 AND 5   THEN 'QS0900203'
						    WHEN TRUNC(TO_NUMBER(p_RISK_CRIT)) BETWEEN 6 AND 12  THEN 'QS0900202'
						    WHEN TRUNC(TO_NUMBER(p_RISK_CRIT)) BETWEEN 13 AND 99 THEN 'QS0900201'
						    ELSE NULL
						END
	                    ,p_IMPRV_CPLN            --개선대책
	                    ,p_RISK_FREQ2            --개선후_빈도(QS09003) 작성
	                    ,p_RISK_APRV2            --개선후_강도(QS09004) 작성
	                    ,p_RISK_CRIT2            --개선후_위험성(QS09001) 작성
	                    ,p_RISK_GRD2             --개선후_위험등급(QS09002) 작성
	                    ,p_DTY_CD                --직책코드
	                    ,p_MGR_OPIN              --관리자의견
	                    ,p_SBM_DT                --제출일자
	                    ,p_SBM_YN                --제출1 미제출0
	                    ,p_WRK_ID                --입력ID 
	                    ,SYSDATE()               --입력일시
	                    ,p_WRK_IP                --입력IP
	                    ,p_WRK_ID                --수정ID
	                    ,SYSDATE()               --수정일시
	                    ,p_WRK_IP);              --수정IP
	    END IF;
	    
	    --최종점수 자동등록
	    MERGE INTO TQHB_RISK_LST T
			USING (
			    SELECT SIT_CD
			          ,PLN_YM
			          ,PLN_DGR
			          ,CUST_CD
			          ,VNDR_SEQ
			          ,CTP_CD
			          ,UNT_CD
			          ,CHK_ITM_CD
			          ,ROUND(AVG(TO_NUMBER(RISK_FREQ)), 1)  AS AVG_RISK_FREQ
			          ,ROUND(AVG(TO_NUMBER(RISK_APRV)), 1)  AS AVG_RISK_APRV
			          ,ROUND(AVG(TO_NUMBER(RISK_CRIT)), 1)  AS AVG_RISK_CRIT
			          ,ROUND(AVG(TO_NUMBER(RISK_CRIT2)), 1) AS AVG_RISK_CRIT2
			      FROM TQHB_RISK_CHK
			     WHERE SIT_CD     = p_SIT_CD
			       AND PLN_YM     = p_PLN_YM
			       AND PLN_DGR    = p_PLN_DGR
			       AND CUST_CD    = p_CUST_CD
			       AND VNDR_SEQ   = p_VNDR_SEQ
			       AND CTP_CD     = p_CTP_CD
			       AND UNT_CD     = p_UNT_CD
			       AND CHK_ITM_CD = p_CHK_ITM_CD
			     GROUP BY SIT_CD, PLN_YM, PLN_DGR, CUST_CD, VNDR_SEQ, CTP_CD, UNT_CD, CHK_ITM_CD
			) S
			ON (
			       T.SIT_CD     = S.SIT_CD
			   AND T.PLN_YM     = S.PLN_YM
			   AND T.PLN_DGR    = S.PLN_DGR
			   AND T.CUST_CD    = S.CUST_CD
			   AND T.VNDR_SEQ   = S.VNDR_SEQ
			   AND T.CTP_CD     = S.CTP_CD
			   AND T.UNT_CD     = S.UNT_CD
			   AND T.CHK_ITM_CD = S.CHK_ITM_CD
			)
			WHEN MATCHED THEN
			UPDATE SET 
			    T.RISK_CRIT  = TO_CHAR(S.AVG_RISK_CRIT),
			    T.RISK_CRIT2 = TO_CHAR(S.AVG_RISK_CRIT2),
			    T.RISK_FREQ  = TO_CHAR(S.AVG_RISK_FREQ),
			    T.RISK_APRV  = TO_CHAR(S.AVG_RISK_APRV),
			    T.RISK_GRD   = CASE 
								    WHEN TRUNC(TO_NUMBER(S.AVG_RISK_CRIT)) BETWEEN 1 AND 5   THEN 'QS0900203'
								    WHEN TRUNC(TO_NUMBER(S.AVG_RISK_CRIT)) BETWEEN 6 AND 12  THEN 'QS0900202'
								    WHEN TRUNC(TO_NUMBER(S.AVG_RISK_CRIT)) BETWEEN 13 AND 99 THEN 'QS0900201'
								    ELSE NULL
								END
			    ;
    
    ELSE 
    	--최종점수 수동등록
    	UPDATE TQHB_RISK_LST
           SET 
               RISK_CRIT            = p_RISK_CRIT               --확정_위험성(QS09001) 작성
              ,RISK_CRIT2           = p_RISK_CRIT2              --확정_개선 후 위험성(QS09001) 작성
              ,RISK_GRD   			= CASE 
									    WHEN TRUNC(TO_NUMBER(p_RISK_CRIT)) BETWEEN 1 AND 5   THEN 'QS0900203'
									    WHEN TRUNC(TO_NUMBER(p_RISK_CRIT)) BETWEEN 6 AND 12  THEN 'QS0900202'
									    WHEN TRUNC(TO_NUMBER(p_RISK_CRIT)) BETWEEN 13 AND 99 THEN 'QS0900201'
									    ELSE NULL
									END
              ,MGR_OPIN             = p_MGR_OPIN                --검토의견
              ,UPD_ID               = p_WRK_ID                  --수정ID 
              ,UPD_DTM              = SYSDATE()                 --수정일시
              ,UPD_IP               = p_WRK_IP                  --수정IP 
         WHERE SIT_CD = p_SIT_CD          --현장코드
           AND PLN_YM = p_PLN_YM          --계획년월
           AND PLN_DGR = p_PLN_DGR         --차수구분코드(QS005) 1 1차,2 2차
           AND CUST_CD = p_CUST_CD         --협력업체코드
           AND VNDR_SEQ = p_VNDR_SEQ         --협력업체순번
           AND CTP_CD = p_CTP_CD          --공종코드
           AND UNT_CD = p_UNT_CD          --단위코드
           AND CHK_ITM_CD = p_CHK_ITM_CD;     --점검항목코드
    
    END IF;
    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 5. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN 
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);
END ;
/

-- PQHB_RISK_CHK_W (PROCEDURE, VALID)
CREATE PROCEDURE "PQHB_RISK_CHK_W"
                            (p_WRK_TP  VARCHAR2 :='U'                                     -- UPDATE FLAG( I: ISNERT, U:UPDATE, D:DELTE)
                            ,p_WRK_ID  VARCHAR2                                           -- 사용자 ID 
                            ,p_WRK_IP  VARCHAR2                                           -- 사용자 IP 
                            ,p_SIT_CD TQHB_RISK_CHK.SIT_CD%TYPE                           -- 현장코드
                            ,p_PLN_YM TQHB_RISK_CHK.PLN_YM%TYPE                           -- 계획년월
                            ,p_PLN_DGR TQHB_RISK_CHK.PLN_DGR%TYPE                         -- 차수구분코드(QS005) 1 1차,2 2차
                            ,p_CUST_CD TQHB_RISK_CHK.CUST_CD%TYPE                         -- 협력업체코드
                            ,p_VNDR_SEQ TQHB_RISK_CHK.VNDR_SEQ%TYPE                       -- 업체순번
                            ,p_EMPE_NO TQHB_RISK_CHK.EMPE_NO%TYPE                         -- 사원번호
                            ,p_SBM_YN TQHB_RISK_CHK.SBM_YN%TYPE                           -- 제출1 미제출0
                            )
IS 
    /**************************************************************************************************************************
      Purpose : 제출/취소

      REVISIONS
      Ver      Date               Author                  Description 
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2026/08/27 14:48:50                         최초생성

    /**************************************************************************************************************************/


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR2(200);            -- ERROR Message
    USER_EXCEPTION EXCEPTION;

	v_CNT  NUMBER;
	v_CNT2 NUMBER;
	v_CNT3 NUMBER;
    v_WRK_TP VARCHAR2(1);
	
BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 필수입력 필드  Check  ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_SIT_CD IS NULL)  THEN
        ERR_MSG := '현장코드는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_PLN_YM IS NULL)  THEN
        ERR_MSG := '계획년월는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_PLN_DGR IS NULL)  THEN
        ERR_MSG := '차수구분코드(QS005) 1 1차,2 2차는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_CUST_CD IS NULL)  THEN
        ERR_MSG := '협력업체코드는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_EMPE_NO IS NULL)  THEN
        ERR_MSG := '사원번호는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_VNDR_SEQ IS NULL)  THEN
        ERR_MSG := '업체순번는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Process 선행조건 Check ]
    ---------------------------------------------------------------------------------------------------------------------------
    
    SELECT COUNT(1) INTO v_CNT
	  FROM TQHB_RISK_CHK
	 WHERE SIT_CD = p_SIT_CD          --현장코드
	   AND PLN_YM = p_PLN_YM          --계획년월
	   AND PLN_DGR = p_PLN_DGR         --차수구분코드(QS005) 1 1차,2 2차
	   AND CUST_CD = p_CUST_CD         --협력업체코드
	   AND VNDR_SEQ = p_VNDR_SEQ         
	   AND EMPE_NO = p_EMPE_NO         
	   AND ( RISK_CRIT IS NULL  OR RISK_CRIT = '0'  OR TO_NUMBER(NVL(RISK_CRIT, '0')) = 0
	      OR RISK_CRIT2 IS NULL OR RISK_CRIT2 = '0' OR TO_NUMBER(NVL(RISK_CRIT2, '0')) = 0 )
	      ;
    
    IF (v_CNT > 0)  THEN
        ERR_MSG := '입력하지 않은 점수가 있어 진행할 수 없습니다.';
        RAISE USER_EXCEPTION;
    END IF;
    
    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Business Process ]
    ---------------------------------------------------------------------------------------------------------------------------
    
    UPDATE TQHB_RISK_CHK
           SET SBM_YN               = p_SBM_YN                  --제출1 미제출0
              ,SBM_DT               = DECODE(p_SBM_YN,'1', TO_CHAR(SYSDATE,'YYYYMMDD'), '') --제출일자 
              ,UPD_ID               = p_WRK_ID                  --수정ID 
              ,UPD_DTM              = SYSDATE()                 --수정일시
              ,UPD_IP               = p_WRK_IP                  --수정IP
         WHERE SIT_CD = p_SIT_CD          --현장코드
           AND PLN_YM = p_PLN_YM          --계획년월
           AND PLN_DGR = p_PLN_DGR         --차수구분코드(QS005) 1 1차,2 2차
           AND CUST_CD = p_CUST_CD         --협력업체코드
           AND VNDR_SEQ = p_VNDR_SEQ       --업체순번
           AND EMPE_NO = p_EMPE_NO         --사원번호
    ;
    
    
     SELECT COUNT(1) INTO v_CNT2
      FROM TQHB_RISK_CHK
     WHERE SIT_CD = p_SIT_CD          --현장코드
       AND PLN_YM = p_PLN_YM          --계획년월
       AND PLN_DGR = p_PLN_DGR         --차수구분코드(QS005) 1 1차,2 2차
       AND CUST_CD = p_CUST_CD         --협력업체코드
       AND VNDR_SEQ = p_VNDR_SEQ         --공종코드
       AND (SBM_YN IS NULL OR SBM_YN != '1')
       ;
    
     
	  SELECT NAM.CNT - CHK.CNT INTO v_CNT3
	  FROM (
	        /* TQHB_RISK_CHK 그룹화 카운트 */
	        SELECT COUNT(1) AS CNT
	          FROM (
	                SELECT SIT_CD, PLN_YM, PLN_DGR, CUST_CD, VNDR_SEQ, EMPE_NO
	                  FROM TQHB_RISK_CHK
	                 WHERE SIT_CD   = p_SIT_CD
	                   AND PLN_YM   = p_PLN_YM
	                   AND PLN_DGR  = p_PLN_DGR
	                   AND CUST_CD  = p_CUST_CD
	                   AND VNDR_SEQ = p_VNDR_SEQ
	                 GROUP BY SIT_CD, PLN_YM, PLN_DGR, CUST_CD, VNDR_SEQ, EMPE_NO
	               )
	       ) CHK,
	       (
	        /* TQHB_RISK_NAM 전체 카운트 */
	        SELECT COUNT(1) AS CNT
	          FROM TQHB_RISK_NAM
	         WHERE SIT_CD   = p_SIT_CD
	           AND PLN_YM   = p_PLN_YM
	           AND PLN_DGR  = p_PLN_DGR
	           AND CUST_CD  = p_CUST_CD
	           AND VNDR_SEQ = p_VNDR_SEQ
	       ) NAM;
     
	  
     IF (v_CNT3 = 0 AND v_CNT2 <= 0)  THEN
         UPDATE TQHB_RISK_VNDR
           SET SBM_YN               = p_SBM_YN                  --제출1 미제출0
              ,SBM_DT               = DECODE(p_SBM_YN,'1', TO_CHAR(SYSDATE,'YYYYMMDD'), '') --제출일자
              ,UPD_ID               = p_WRK_ID                  --수정ID 
              ,UPD_DTM              = SYSDATE()                 --수정일시
              ,UPD_IP               = p_WRK_IP                  --수정IP
         WHERE SIT_CD = p_SIT_CD          --현장코드
           AND PLN_YM = p_PLN_YM          --계획년월
           AND PLN_DGR = p_PLN_DGR         --차수구분코드(QS005) 1 1차,2 2차
           AND CUST_CD = p_CUST_CD         --협력업체코드
           AND VNDR_SEQ = p_VNDR_SEQ         --공종코드           
	    ;
     
     ELSE
     
     	UPDATE TQHB_RISK_VNDR
           SET SBM_YN               = ''
              ,SBM_DT               = ''
              ,UPD_ID               = p_WRK_ID                  --수정ID 
              ,UPD_DTM              = SYSDATE()                 --수정일시
              ,UPD_IP               = p_WRK_IP                  --수정IP
         WHERE SIT_CD = p_SIT_CD          --현장코드
           AND PLN_YM = p_PLN_YM          --계획년월
           AND PLN_DGR = p_PLN_DGR         --차수구분코드(QS005) 1 1차,2 2차
           AND CUST_CD = p_CUST_CD         --협력업체코드
           AND VNDR_SEQ = p_VNDR_SEQ         --공종코드           
	    ;
     END IF;
	    
    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 5. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN 
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);
END ;
/

-- PQHB_RISK_DGR_Q (PROCEDURE, VALID)
CREATE PROCEDURE "PQHB_RISK_DGR_Q" (  
						     p_WRK_TP  VARCHAR2 :='Q'                                     -- 
                            ,p_WRK_ID  VARCHAR2                                           -- 사용자 ID 
                            ,p_WRK_IP  VARCHAR2                                           -- 사용자 IP 
							,p_SIT_CD TQHB_RISK_DGR.SIT_CD%TYPE                           -- 현장코드
                            ,p_PLN_YM TQHB_RISK_DGR.PLN_YM%TYPE                           -- 계획년월
                            ,p_PLN_DGR TQHB_RISK_DGR.PLN_DGR%TYPE                         -- 차수구분코드(QS005) 1 1차,2 2차
							,RTN_CURSOR      OUT SYS_REFCURSOR
)
IS
    /**************************************************************************************************************************
      Purpose : [위험성평가차수 조회] 

      REVISIONS
      Ver      Date               Author                  Description
      -------  -----------------  ----------------------  ---------------------------------------------------------------------
      1.0      2023/12/04                                 최초생성  

    **************************************************************************************************************************/

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE  NUMBER :=-20009; -- ERROR 코드
    ERR_MSG   VARCHAR(200);    -- ERROR Message
    USER_EXCEPTION EXCEPTION;

BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 수행전 Check Logic ]
    ---------------------------------------------------------------------------------------------------------------------------

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Logic 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------

    IF p_WRK_TP = 'Q' THEN

        OPEN RTN_CURSOR FOR 
        SELECT  
		        SIT_CD
		       ,PLN_YM                 --계획년월
		       ,PLN_DGR                 --차수구분코드(QS005) 1 1차,2 2차
		       , ( SELECT CD_NM FROM TCOA_COMCODE WHERE COM_CD = A.PLN_DGR AND HRNK_CD = 'QS005' ) AS PLN_DGR_NM -- 계획차수명
		       ,APRS_STR_DT                 --평가시작일자
		       ,APRS_END_DT                 --평가종료일자
		       ,VNDR_CMPL_DT                 --업체작성완료일자
		       ,CONF_SCH_DT                 --회의예정일자
		       ,AREC_CTS                 --회의록내용
		       ,AREC_ATFL_GRP                 --회의록첨부파일그룹
		       ,PHOTO_GRP1                 --첨부파일그룹사진1
		       ,PHOTO_DESC_1                 --사진설명1
		       ,PHOTO_GRP2                 --첨부파일그룹사진2
		       ,PHOTO_DESC_2                 --사진설명2
		       ,CONF_DT                 --회의일자
		       ,CONF_PLC                 --회의장소
		       ,AM_NOTICE                 --공지사항
		       ,AREC_NAM                 --회의명
		       ,EMPE_NO_SAFT                 --안전관리자 사원번호
		       ,SAFT_MGR_YN                 --안전관리자(승인1 미승인0)
		       ,SAFT_MGR_DT                 --안전관리자 승인/반려일자
		       ,DECODE(SAFT_MGR_YN,'1',SAFT_MGR_DT,'') AS SAFT_MGR_DT_NM
		       ,SAFT_MGR_OPIN                 --안전관리자 승인/반려의견
		       ,EMPE_NO_OMGR                 --현장소장 사원번호
		       ,SITE_OMGR_YN                 --현장소장(승인1 미승인0)
		       ,SITE_OMGR_DT                 --현장소장 승인/반려일자
		       ,DECODE(SITE_OMGR_YN,'1',SITE_OMGR_DT,'') AS SITE_OMGR_DT_NM
		       ,SITE_OMGR_OPIN                 --현장소장 승인/반려의견
		       ,DECODE(SITE_OMGR_YN,'1','승인','') AS SITE_OMGR_YN_NM
		       ,(SELECT LISTAGG(CUST_CD, ',') WITHIN GROUP (ORDER BY CUST_CD)
		         FROM TQHB_RISK_VNDR
		         WHERE SIT_CD = A.SIT_CD
		         AND PLN_YM = A.PLN_YM
		         AND PLN_DGR = A.PLN_DGR
		        ) AS CUST_CD_LIST
		 FROM TQHB_RISK_DGR A
         WHERE A.SIT_CD = p_SIT_CD
         ORDER BY A.PLN_YM DESC, A.PLN_DGR DESC
        ;
                
    ELSIF p_WRK_TP = 'Q2' THEN

        OPEN RTN_CURSOR FOR 
        SELECT  
        	    SIT_CD
	           ,PLN_YM                 --계획년월
	           ,PLN_DGR                 --차수구분코드(QS005) 1 1차,2 2차
	           , ( SELECT CD_NM FROM TCOA_COMCODE WHERE COM_CD = A.PLN_DGR AND HRNK_CD = 'QS005' ) AS PLN_DGR_NM -- 계획차수명
	           ,APRS_STR_DT                 --평가시작일자
	           ,APRS_END_DT                 --평가종료일자
	           ,TO_CHAR(TO_DATE(APRS_STR_DT,'YYYYMMDD'),'YYYY-MM-dd') AS APRS_STR_DT_NM
	           ,TO_CHAR(TO_DATE(APRS_END_DT,'YYYYMMDD'),'YYYY-MM-dd') AS APRS_END_DT_NM
	           ,VNDR_CMPL_DT                 --업체작성완료일자
	           ,CONF_SCH_DT                 --회의예정일자
	           ,AREC_CTS                 --회의록내용
	           ,AREC_ATFL_GRP                 --회의록첨부파일그룹
	           ,PHOTO_GRP1                 --첨부파일그룹사진1
	           ,PHOTO_DESC_1                 --사진설명1
	           ,PHOTO_GRP2                 --첨부파일그룹사진2
	           ,PHOTO_DESC_2                 --사진설명2
	           ,TO_CHAR(TO_DATE(APRS_END_DT,'YYYYMMDD'),'YYYY-MM-dd') AS CONF_DT
	           ,CONF_PLC                 --회의장소
	           ,AM_NOTICE                 --공지사항
	           ,AREC_NAM                 --회의명
	           ,EMPE_NO_SAFT                 --안전관리자 사원번호
	           ,SAFT_MGR_YN                 --안전관리자(승인1 미승인0)
	           ,SAFT_MGR_DT                 --안전관리자 승인/반려일자
	           ,SAFT_MGR_OPIN                 --안전관리자 승인/반려의견
	           ,EMPE_NO_OMGR                 --현장소장 사원번호
	           ,SITE_OMGR_YN                 --현장소장(승인1 미승인0)
	           ,SITE_OMGR_DT                 --현장소장 승인/반려일자
	           ,SITE_OMGR_OPIN                 --현장소장 승인/반려의견
	           ,DECODE(SITE_OMGR_YN,'1','승인','') AS SITE_OMGR_YN_NM
	           ,SUBSTR(PLN_YM, 1, 4) || '년 ' || SUBSTR(PLN_YM, 5, 2) || '월 ' || PLN_DGR || '차 위험성평가' AS AREC_DGR
	           ,(
	           		 SELECT JB_CD
					  FROM TQHA_SITENAM
					 WHERE 1=1
					   AND SIT_CD    = A.SIT_CD
					   AND EMPE_NO   = p_WRK_ID
	            ) AS JB_CD
	            ,(
	            	SELECT CASE 
				         WHEN COUNT(*) > 0 AND COUNT(*) = COUNT(CASE WHEN SBM_YN = '1' THEN 1 END) 
				         THEN '1' -- 전체가 1임
				         ELSE '0' -- 1이 아닌 값이 섞여 있거나 데이터가 없음
				       END AS ALL_SBM_YN
				  FROM TQHB_RISK_VNDR
				 WHERE SIT_CD = A.SIT_CD          
				   AND PLN_YM = A.PLN_YM          
				   AND PLN_DGR = A.PLN_DGR
	            ) AS VNDR_SBM_YN
          FROM TQHB_RISK_DGR A
         WHERE A.SIT_CD = p_SIT_CD
           AND A.PLN_YM = p_PLN_YM
           AND A.PLN_DGR = p_PLN_DGR
        ;

    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
         WHEN OTHERS THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);
END PQHB_RISK_DGR_Q;
/

-- PQHB_RISK_DGR_S (PROCEDURE, VALID)
CREATE PROCEDURE "PQHB_RISK_DGR_S"
                            (p_WRK_TP  VARCHAR2 :='U'                                     -- UPDATE FLAG( I: ISNERT, U:UPDATE, D:DELTE)
                            ,p_WRK_ID  VARCHAR2                                           -- 사용자 ID 
                            ,p_WRK_IP  VARCHAR2                                           -- 사용자 IP 
                            ,p_SIT_CD TQHB_RISK_DGR.SIT_CD%TYPE                           -- 현장코드
                            ,p_PLN_YM TQHB_RISK_DGR.PLN_YM%TYPE                           -- 계획년월
                            ,p_PLN_DGR TQHB_RISK_DGR.PLN_DGR%TYPE                         -- 차수구분코드(QS005) 1 1차,2 2차
                            ,p_APRS_STR_DT TQHB_RISK_DGR.APRS_STR_DT%TYPE                 -- 평가시작일자
                            ,p_APRS_END_DT TQHB_RISK_DGR.APRS_END_DT%TYPE                 -- 평가종료일자
                            ,p_VNDR_CMPL_DT TQHB_RISK_DGR.VNDR_CMPL_DT%TYPE               -- 업체작성완료일자
                            ,p_CONF_SCH_DT TQHB_RISK_DGR.CONF_SCH_DT%TYPE                 -- 회의예정일자
                            ,p_AREC_CTS TQHB_RISK_DGR.AREC_CTS%TYPE                       -- 회의록내용
                            ,p_AREC_ATFL_GRP TQHB_RISK_DGR.AREC_ATFL_GRP%TYPE             -- 회의록첨부파일그룹
                            ,p_PHOTO_GRP1 TQHB_RISK_DGR.PHOTO_GRP1%TYPE                   -- 첨부파일그룹사진1
                            ,p_PHOTO_DESC_1 TQHB_RISK_DGR.PHOTO_DESC_1%TYPE               -- 사진설명1
                            ,p_PHOTO_GRP2 TQHB_RISK_DGR.PHOTO_GRP2%TYPE                   -- 첨부파일그룹사진2
                            ,p_PHOTO_DESC_2 TQHB_RISK_DGR.PHOTO_DESC_2%TYPE               -- 사진설명2
                            ,p_CONF_DT TQHB_RISK_DGR.CONF_DT%TYPE                         -- 회의일자
                            ,p_CONF_PLC TQHB_RISK_DGR.CONF_PLC%TYPE                       -- 회의장소
                            ,p_AM_NOTICE TQHB_RISK_DGR.AM_NOTICE%TYPE                     -- 공지사항
                            ,p_AREC_NAM TQHB_RISK_DGR.AREC_NAM%TYPE                       -- 회의명
                            ,p_EMPE_NO_SAFT TQHB_RISK_DGR.EMPE_NO_SAFT%TYPE               -- 안전관리자 사원번호
                            ,p_SAFT_MGR_YN TQHB_RISK_DGR.SAFT_MGR_YN%TYPE                 -- 안전관리자(승인1 미승인0)
                            ,p_SAFT_MGR_DT TQHB_RISK_DGR.SAFT_MGR_DT%TYPE                 -- 안전관리자 승인/반려일자
                            ,p_SAFT_MGR_OPIN TQHB_RISK_DGR.SAFT_MGR_OPIN%TYPE             -- 안전관리자 승인/반려의견
                            ,p_EMPE_NO_OMGR TQHB_RISK_DGR.EMPE_NO_OMGR%TYPE               -- 현장소장 사원번호
                            ,p_SITE_OMGR_YN TQHB_RISK_DGR.SITE_OMGR_YN%TYPE               -- 현장소장(승인1 미승인0)
                            ,p_SITE_OMGR_DT TQHB_RISK_DGR.SITE_OMGR_DT%TYPE               -- 현장소장 승인/반려일자
                            ,p_SITE_OMGR_OPIN TQHB_RISK_DGR.SITE_OMGR_OPIN%TYPE)          -- 현장소장 승인/반려의견
IS 
    /**************************************************************************************************************************
      Purpose : 위험성평가 차수 저장
 
      REVISIONS
      Ver      Date               Author                  Description 
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2026/07/28 17:26:51                         최초생성

    /**************************************************************************************************************************/


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR2(200);            -- ERROR Message
    USER_EXCEPTION EXCEPTION;

 
    v_CNT               INTEGER;            -- 위험성 평가 일정 하위데이타 존재 여부
BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 필수입력 필드  Check  ]
    ---------------------------------------------------------------------------------------------------------------------------
     IF (p_SIT_CD IS NULL)  THEN
        ERR_MSG := '현장코드는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_PLN_YM IS NULL  AND p_WRK_TP <> 'I')  THEN
        ERR_MSG := '계획년월는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_PLN_DGR IS NULL)  THEN
        ERR_MSG := '차수구분코드는(은) 필수 입력사항 입니다.'; 
        RAISE USER_EXCEPTION;
    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Process 선행조건 Check ]
    ---------------------------------------------------------------------------------------------------------------------------
	--  위험성 평가 일정 하위데이타 존재 여부
    IF p_WRK_TP = 'D' THEN

       SELECT NVL(COUNT(CUST_CD),0) 
         INTO v_CNT
         FROM TQHB_RISK_VNDR
        WHERE SIT_CD = p_SIT_CD
          AND PLN_YM = p_PLN_YM
          AND PLN_DGR = p_PLN_DGR ;

         -- 평가 대상업체 졵재여부 Validation
        IF v_CNT > 0 THEN
           ERR_MSG := '계획년월 "' || p_PLN_YM || '" 차수 "' || p_PLN_DGR || '"은(는) 하위 데이타가 존재하여 삭제할 수 없습니다. ';
           RAISE USER_EXCEPTION;
        END IF;
    END IF;


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Business Process ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_WRK_TP ='D') THEN
        DELETE 
          FROM TQHB_RISK_DGR
         WHERE SIT_CD = p_SIT_CD          --현장코드
           AND PLN_YM = p_PLN_YM          --계획년월
           AND PLN_DGR = p_PLN_DGR;        --차수구분코드(QS005) 1 1차,2 2차

    ELSIF (p_WRK_TP ='U') THEN
        UPDATE TQHB_RISK_DGR
           SET APRS_STR_DT      = p_APRS_STR_DT     -- 평가시작일자
             , APRS_END_DT      = p_APRS_END_DT     -- 평가종료일자
             , VNDR_CMPL_DT     = p_VNDR_CMPL_DT    -- 업체작성완료일자
             , CONF_DT          = p_CONF_DT     -- 회의예정일자
             , AREC_NAM         = p_AREC_NAM         --회의명
             , UPD_ID           = p_WRK_ID          -- 수정ID 
             , UPD_DTM          = SYSDATE()         -- 수정일시
             , UPD_IP           = p_WRK_IP          -- 수정IP
         WHERE SIT_CD           = p_SIT_CD          -- 현장코드
           AND PLN_YM           = p_PLN_YM          -- 계획년월
           AND PLN_DGR          = p_PLN_DGR         -- 차수구분코드(QS005) 1 1차,2 2차
           ;
    ELSIF (p_WRK_TP ='POP') THEN
        UPDATE TQHB_RISK_DGR
           SET AREC_ATFL_GRP    = p_AREC_ATFL_GRP     -- 평가시작일자
           	 , PHOTO_GRP1       = p_PHOTO_GRP1      --첨부파일그룹사진1
             , PHOTO_DESC_1     = p_PHOTO_DESC_1         --사진설명1
             , PHOTO_GRP2       = p_PHOTO_GRP2       --첨부파일그룹사진2
             , PHOTO_DESC_2     = p_PHOTO_DESC_2          --사진설명2
             , UPD_ID           = p_WRK_ID          -- 수정ID 
             , UPD_DTM          = SYSDATE()         -- 수정일시
             , UPD_IP           = p_WRK_IP          -- 수정IP
         WHERE SIT_CD           = p_SIT_CD          -- 현장코드
           AND PLN_YM           = p_PLN_YM          -- 계획년월
           AND PLN_DGR          = p_PLN_DGR         -- 차수구분코드(QS005) 1 1차,2 2차
           ;
    ELSE 
        INSERT INTO TQHB_RISK_DGR
                   ( SIT_CD                  --현장코드
                    ,PLN_YM                  --계획년월
                    ,PLN_DGR                 --차수구분코드(QS005) 1 1차,2 2차
                    ,APRS_STR_DT             --평가시작일자
                    ,APRS_END_DT             --평가종료일자
                    ,VNDR_CMPL_DT            --업체작성완료일자
                    ,CONF_SCH_DT             --회의예정일자
                    ,AREC_CTS                --회의록내용
                    ,AREC_ATFL_GRP           --회의록첨부파일그룹
                    ,PHOTO_GRP1              --첨부파일그룹사진1
                    ,PHOTO_DESC_1            --사진설명1
                    ,PHOTO_GRP2              --첨부파일그룹사진2
                    ,PHOTO_DESC_2            --사진설명2
                    ,CONF_DT                 --회의일자
                    ,CONF_PLC                --회의장소
                    ,AM_NOTICE               --공지사항
                    ,AREC_NAM                --회의명
                    ,EMPE_NO_SAFT            --안전관리자 사원번호
                    ,SAFT_MGR_YN             --안전관리자(승인1 미승인0)
                    ,SAFT_MGR_DT             --안전관리자 승인/반려일자
                    ,SAFT_MGR_OPIN           --안전관리자 승인/반려의견
                    ,EMPE_NO_OMGR            --현장소장 사원번호
                    ,SITE_OMGR_YN            --현장소장(승인1 미승인0)
                    ,SITE_OMGR_DT            --현장소장 승인/반려일자
                    ,SITE_OMGR_OPIN          --현장소장 승인/반려의견
                    ,IPT_ID                  --입력ID
                    ,IPT_DTM                 --입력일시
                    ,IPT_IP                  --입력IP
                    ,UPD_ID                  --수정ID
                    ,UPD_DTM                 --수정일시
                    ,UPD_IP                  --수정IP
                    )
             VALUES (p_SIT_CD                --현장코드
                    ,p_PLN_YM                --계획년월
                    ,p_PLN_DGR               --차수구분코드(QS005) 1 1차,2 2차
                    ,p_APRS_STR_DT           --평가시작일자
                    ,p_APRS_END_DT           --평가종료일자
                    ,p_VNDR_CMPL_DT          --업체작성완료일자
                    ,p_CONF_SCH_DT           --회의예정일자
                    ,p_AREC_CTS              --회의록내용
                    ,p_AREC_ATFL_GRP         --회의록첨부파일그룹
                    ,p_PHOTO_GRP1            --첨부파일그룹사진1
                    ,p_PHOTO_DESC_1          --사진설명1
                    ,p_PHOTO_GRP2            --첨부파일그룹사진2
                    ,p_PHOTO_DESC_2          --사진설명2
                    ,p_CONF_DT               --회의일자
                    ,p_CONF_PLC              --회의장소
                    ,p_AM_NOTICE             --공지사항
                    ,p_AREC_NAM              --회의명
                    ,p_EMPE_NO_SAFT          --안전관리자 사원번호
                    ,p_SAFT_MGR_YN           --안전관리자(승인1 미승인0)
                    ,p_SAFT_MGR_DT           --안전관리자 승인/반려일자
                    ,p_SAFT_MGR_OPIN         --안전관리자 승인/반려의견
                    ,p_EMPE_NO_OMGR          --현장소장 사원번호
                    ,p_SITE_OMGR_YN          --현장소장(승인1 미승인0)
                    ,p_SITE_OMGR_DT          --현장소장 승인/반려일자
                    ,p_SITE_OMGR_OPIN        --현장소장 승인/반려의견
                    ,p_WRK_ID                --입력ID 
                    ,SYSDATE()               --입력일시
                    ,p_WRK_IP                --입력IP
                    ,p_WRK_ID                --수정ID
                    ,SYSDATE()               --수정일시
                    ,p_WRK_IP);              --수정IP
                    
                    
        -- 해당하는 협력업체
        MERGE 
          INTO TQHB_RISK_VNDR T
         USING (
                SELECT A.CUST_CD
                	 , A.VNDR_SEQ
                     , A.CTP_CD
                  FROM TQHA_VNDR      A
                     , TQHB_RISK_VNDR B
                 WHERE A.SIT_CD = p_SIT_CD
                   AND ((TO_DATE(A.VNDR_STR_DT, 'YYYYMMDD') <= TO_DATE(p_APRS_STR_DT, 'YYYYMMDD') 
                         AND TO_DATE(A.VNDR_END_DT, 'YYYYMMDD') >= TO_DATE(p_APRS_END_DT, 'YYYYMMDD')) 
                          OR NVL(B.OBJ_YN, 0) = 1)
                   AND A.SIT_CD     = B.SIT_CD(+)
                   AND A.CUST_CD    = B.CUST_CD(+)
                   AND A.VNDR_SEQ   = B.VNDR_SEQ(+)
                   AND B.PLN_YM(+)  = p_PLN_YM
                   AND B.PLN_DGR(+) = p_PLN_DGR
               ) S
        ON (
                T.SIT_CD   = p_SIT_CD   
            AND T.PLN_YM   = p_PLN_YM   
            AND T.PLN_DGR  = p_PLN_DGR  
            AND T.CUST_CD  = S.CUST_CD
            AND T.VNDR_SEQ = S.VNDR_SEQ
           )
        WHEN MATCHED THEN
            UPDATE 
               SET T.OBJ_YN     = '1'
                 , T.UPD_ID     = p_WRK_ID
                 , T.UPD_DTM    = SYSDATE
                 , T.UPD_IP     = p_WRK_IP
        WHEN NOT MATCHED THEN
            INSERT 
                 ( SIT_CD
                 , PLN_YM
                 , PLN_DGR
                 , CUST_CD
                 , VNDR_SEQ
                 , CTP_CD
                 , OBJ_YN
                 , VNDR_NOTI_YN
                 , IPT_ID
                 , IPT_DTM
                 , IPT_IP
                 , UPD_ID
                 , UPD_DTM
                 , UPD_IP
                 )
            VALUES 
                 ( p_SIT_CD
                 , p_PLN_YM
                 , p_PLN_DGR
                 , S.CUST_CD
                 , S.VNDR_SEQ
                 , S.CTP_CD
                 , '1'
                 , '0'
                 , p_WRK_ID
                 , SYSDATE
                 , p_WRK_IP
                 , p_WRK_ID
                 , SYSDATE
                 , p_WRK_IP
                 )
        ;
                    
    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 5. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN 
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);
END ;
/

-- PQHB_RISK_DGR_W (PROCEDURE, VALID)
CREATE PROCEDURE "PQHB_RISK_DGR_W"
                            (p_WRK_TP  VARCHAR2 :='U'                                     -- UPDATE FLAG( I: ISNERT, U:UPDATE, D:DELTE)
                            ,p_WRK_ID  VARCHAR2                                           -- 사용자 ID 
                            ,p_WRK_IP  VARCHAR2                                           -- 사용자 IP 
                            ,p_SIT_CD TQHB_RISK_DGR.SIT_CD%TYPE                           -- 현장코드
                            ,p_PLN_YM TQHB_RISK_DGR.PLN_YM%TYPE                           -- 계획년월
                            ,p_PLN_DGR TQHB_RISK_DGR.PLN_DGR%TYPE                         -- 차수구분코드
                            ,p_MGR_OPIN TQHB_RISK_DGR.SAFT_MGR_OPIN%TYPE                  -- 승인/반려의견
                            ,p_APRS_STR_DT TQHB_RISK_DGR.APRS_STR_DT%TYPE                 -- 평가시작일자
                            ,p_APRS_END_DT TQHB_RISK_DGR.APRS_END_DT%TYPE                 -- 평가종료일자
                            )
IS 
    /**************************************************************************************************************************
      Purpose : 위험성평가 승인 및 반려 저장
 
      REVISIONS
      Ver      Date               Author                  Description 
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2026/07/28 17:26:51                         최초생성

    /**************************************************************************************************************************/


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR2(200);            -- ERROR Message
    USER_EXCEPTION EXCEPTION;

 
    v_CNT               INTEGER;            -- 위험성 평가 일정 하위데이타 존재 여부
BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 필수입력 필드  Check  ]
    ---------------------------------------------------------------------------------------------------------------------------
     IF (p_SIT_CD IS NULL)  THEN
        ERR_MSG := '현장코드는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_PLN_YM IS NULL  AND p_WRK_TP <> 'I')  THEN
        ERR_MSG := '계획년월는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_PLN_DGR IS NULL)  THEN
        ERR_MSG := '차수구분코드는(은) 필수 입력사항 입니다.'; 
        RAISE USER_EXCEPTION;
    END IF;


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Business Process ]
    ---------------------------------------------------------------------------------------------------------------------------
    -- 승인요청
    IF (p_WRK_TP = 'APPR1') THEN    

       UPDATE TQHB_RISK_DGR
           SET EMPE_NO_SAFT     = p_WRK_ID
          	 , SAFT_MGR_YN      = '1'
           	 , SAFT_MGR_DT      = TO_CHAR(SYSDATE(),'YYYYMMDD')
          	 , SAFT_MGR_OPIN    = p_MGR_OPIN
             , UPD_ID           = p_WRK_ID          -- 수정ID 
             , UPD_DTM          = SYSDATE()         -- 수정일시
             , UPD_IP           = p_WRK_IP          -- 수정IP
         WHERE SIT_CD           = p_SIT_CD          -- 현장코드
           AND PLN_YM           = p_PLN_YM          -- 계획년월
           AND PLN_DGR          = p_PLN_DGR         -- 차수구분코드(QS005) 1 1차,2 2차
           ;

    -- 승인요청취소
    ELSIF (p_WRK_TP ='APPR2') THEN
    
        UPDATE TQHB_RISK_DGR
           SET EMPE_NO_SAFT     = p_WRK_ID
          	 , SAFT_MGR_YN      = '0'
           	 , SAFT_MGR_DT      = TO_CHAR(SYSDATE(),'YYYYMMDD')
          	 , SAFT_MGR_OPIN    = p_MGR_OPIN
             , UPD_ID           = p_WRK_ID          -- 수정ID 
             , UPD_DTM          = SYSDATE()         -- 수정일시
             , UPD_IP           = p_WRK_IP          -- 수정IP
         WHERE SIT_CD           = p_SIT_CD          -- 현장코드
           AND PLN_YM           = p_PLN_YM          -- 계획년월
           AND PLN_DGR          = p_PLN_DGR         -- 차수구분코드(QS005) 1 1차,2 2차
           ;
    
     -- 승인
     ELSIF (p_WRK_TP ='APPR3') THEN
     
     	-- 점검일자 생성
     	 PQHB_DAYSAFE_DT_W('W'       
	                        ,p_WRK_ID 
	                        ,p_WRK_IP      
	                        ,p_SIT_CD
	                        ,p_PLN_YM
	                        ,p_PLN_DGR
	                        ,p_APRS_STR_DT 
	                        ,p_APRS_END_DT
	                        );
     
     	UPDATE TQHB_RISK_DGR
         SET   EMPE_NO_OMGR     = p_WRK_ID
          	 , SITE_OMGR_YN     = '1'
           	 , SITE_OMGR_DT     = TO_CHAR(SYSDATE(),'YYYYMMDD')
          	 , SITE_OMGR_OPIN   = p_MGR_OPIN
             , UPD_ID           = p_WRK_ID          -- 수정ID 
             , UPD_DTM          = SYSDATE()         -- 수정일시
             , UPD_IP           = p_WRK_IP          -- 수정IP
         WHERE SIT_CD           = p_SIT_CD          -- 현장코드
           AND PLN_YM           = p_PLN_YM          -- 계획년월
           AND PLN_DGR          = p_PLN_DGR         -- 차수구분코드(QS005) 1 1차,2 2차
           ;
     	
     -- 승인취소
     ELSIF (p_WRK_TP ='APPR4') THEN
     
		-- 점검진행 확인
        SELECT COUNT(1) INTO v_CNT
		FROM TQHB_DAYSAFE_CHKLST
		WHERE 1=1
		AND SIT_CD  = p_SIT_CD
	    AND PLN_YM  = p_PLN_YM
	    AND PLN_DGR = p_PLN_DGR
	    AND EMPE_NO IS NOT NULL
	    ;
	    
	    IF (v_CNT > 0)  THEN
	        ERR_MSG := '이미 점검이 시작되어 취소 할 수 없습니다.';
	        RAISE USER_EXCEPTION;
	    END IF;
	    
     
	     UPDATE TQHB_RISK_DGR
         SET   EMPE_NO_OMGR     = p_WRK_ID
          	 , SITE_OMGR_YN     = '0'
           	 , SITE_OMGR_DT     = TO_CHAR(SYSDATE(),'YYYYMMDD')
          	 , SITE_OMGR_OPIN   = p_MGR_OPIN
             , UPD_ID           = p_WRK_ID          -- 수정ID 
             , UPD_DTM          = SYSDATE()         -- 수정일시
             , UPD_IP           = p_WRK_IP          -- 수정IP
         WHERE SIT_CD           = p_SIT_CD          -- 현장코드
           AND PLN_YM           = p_PLN_YM          -- 계획년월
           AND PLN_DGR          = p_PLN_DGR         -- 차수구분코드(QS005) 1 1차,2 2차
           ;
	     
		   -- 점검자 초기화
		    DELETE FROM TQHB_DAYSAFE_NAM
		    WHERE 1=1
			AND SIT_CD  = p_SIT_CD
		    AND PLN_YM  = p_PLN_YM
		    AND PLN_DGR = p_PLN_DGR;
		    
		    -- 점검자체크 초기화
		    DELETE FROM TQHB_DAYSAFE_CHKLST
		    WHERE 1=1
			AND SIT_CD  = p_SIT_CD
		    AND PLN_YM  = p_PLN_YM
		    AND PLN_DGR = p_PLN_DGR;
		    
		    -- 점검일자 초기화
		    DELETE FROM TQHB_DAYSAFE_DT
		    WHERE 1=1
			AND SIT_CD  = p_SIT_CD
		    AND PLN_YM  = p_PLN_YM
		    AND PLN_DGR = p_PLN_DGR; 
     
    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 5. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN 
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);
END ;
/

-- PQHB_RISK_LST_Q (PROCEDURE, VALID)
CREATE PROCEDURE "PQHB_RISK_LST_Q"
(
      p_WRK_TP  VARCHAR2 DEFAULT 'Q'                                                      -- FLAG( Q: SELECT )
     ,p_SIT_CD TQHB_RISK_LST.SIT_CD%TYPE                                                  -- 현장코드
     ,p_PLN_YM TQHB_RISK_LST.PLN_YM%TYPE                                                  -- 계획년월
     ,p_PLN_DGR TQHB_RISK_LST.PLN_DGR%TYPE                                                -- 차수구분코드(QS005) 1 1차,2 2차
     ,p_CUST_CD TQHB_RISK_LST.CUST_CD%TYPE                                                -- 협력업체코드
     ,p_VNDR_SEQ TQHB_RISK_LST.VNDR_SEQ%TYPE                                              -- 업체순번
     ,p_CTP_CD TQHB_RISK_LST.CTP_CD%TYPE                                                  -- 공종코드
     ,p_UNT_CD TQHB_RISK_LST.UNT_CD%TYPE                                                  -- 단위코드
     ,p_CHK_ITM_CD TQHB_RISK_LST.CHK_ITM_CD%TYPE                                          -- 점검항목코드
     ,RTN_CURSOR OUT SYS_REFCURSOR
)
IS 
    /**************************************************************************************************************************
      Purpose : 위험성평가표작성 조회

      REVISIONS
      Ver      Date               Author                  Description 
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2026/08/03 08:52:04                         최초생성

    /**************************************************************************************************************************/


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR2(200);            -- ERROR Message
    USER_EXCEPTION EXCEPTION;


BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 수행전 Check Logic ]
    ---------------------------------------------------------------------------------------------------------------------------


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Logic 처리
    ---------------------------------------------------------------------------------------------------------------------------
	IF p_WRK_TP = 'Q' THEN
		
	    OPEN RTN_CURSOR FOR
	    SELECT  A.SIT_CD                 --현장코드
	           ,A.PLN_YM                 --계획년월
	           ,A.PLN_DGR                 --차수구분코드(QS005) 1 1차,2 2차
	           ,A.CUST_CD                 --협력업체코드
	           ,A.VNDR_SEQ
	           ,(SELECT CUST_NM FROM VQSZ_TRADE WHERE CUST_CD = A.CUST_CD) AS CUST_NM  --업체명
	           ,A.CTP_CD                 --공종코드
	           ,A.UNT_CD                 --단위코드
	           ,(SELECT CTP_NM FROM TQHA_CTP WHERE CTP_CD = A.CTP_CD) AS CTP_NM
	           ,(SELECT UNT_NM FROM TQHA_CTPUNT WHERE CTP_CD = A.CTP_CD AND UNT_CD = A.UNT_CD) AS UNT_NM
	           ,A.CHK_ITM_CD                 --점검항목코드
	           ,A.CHK_ITM_SEQ                 --점검항목 정열순서
	           ,A.CHK_ITM_NM                 --점검항목명
	           ,A.CHK_LOC                 --점검위치
	           ,A.DISS_SHP                 --재해형태(QS036)
	           ,A.RISK_FREQ                 --확정_빈도(QS09003) 작성
	           ,A.RISK_APRV                 --확정_강도(QS09004) 작성
	           ,A.RISK_CRIT                 --확정_위험성(QS09001) 작성
	           ,A.RISK_GRD                 --확정_위험등급(QS09002) 작성
	           ,A.IMPRV_CPLN                 --개선대책
	           ,A.WRK_PSNNO                 --작업인원
	           ,A.ITM_ADD_YN                 --기존 : 0, 추가 : 1
	      FROM TQHB_RISK_LST A
	    WHERE  A.SIT_CD = p_SIT_CD                     --현장코드
	       AND A.PLN_YM = p_PLN_YM                     --계획년월
	       AND A.PLN_DGR = p_PLN_DGR                     --차수구분코드(QS005) 1 1차,2 2차
	           ;
	    
	ELSIF p_WRK_TP = 'Q2' THEN
		OPEN RTN_CURSOR FOR
	    SELECT  A.SIT_CD                 --현장코드
	           ,A.PLN_YM                 --계획년월
	           ,A.PLN_DGR                 --차수구분코드(QS005) 1 1차,2 2차
	           ,A.CUST_CD                 --협력업체코드
	           ,A.VNDR_SEQ
	           ,(SELECT CUST_NM FROM VQSZ_TRADE WHERE CUST_CD = A.CUST_CD) AS CUST_NM  --업체명
	           ,A.CTP_CD                 --공종코드
	           ,A.UNT_CD                 --단위코드
	           ,(SELECT CTP_NM FROM TQHA_CTP WHERE CTP_CD = A.CTP_CD) AS CTP_NM
	           ,(SELECT UNT_NM FROM TQHA_CTPUNT WHERE CTP_CD = A.CTP_CD AND UNT_CD = A.UNT_CD) AS UNT_NM
	           ,A.CHK_ITM_CD                 --점검항목코드
	           ,A.CHK_ITM_SEQ                 --점검항목 정열순서
	           ,A.CHK_ITM_NM                 --점검항목명
	           ,A.CHK_LOC                 --점검위치
	           ,A.DISS_SHP                 --재해형태(QS036)
	           ,A.RISK_FREQ                 --확정_빈도(QS09003) 작성
	           ,A.RISK_APRV                 --확정_강도(QS09004) 작성
	           ,A.RISK_CRIT                 --확정_위험성(QS09001) 작성
	           ,A.RISK_GRD                 --확정_위험등급(QS09002) 작성
	           ,A.IMPRV_CPLN                 --개선대책
	           ,A.WRK_PSNNO                 --작업인원
	           ,A.ITM_ADD_YN                 --기존 : 0, 추가 : 1
	      FROM TQHB_RISK_LST A
	    WHERE  A.SIT_CD = p_SIT_CD                     --현장코드
	       AND A.PLN_YM = p_PLN_YM                     --계획년월
	       AND A.PLN_DGR = p_PLN_DGR                     --차수구분코드(QS005) 1 1차,2 2차
	       AND A.CUST_CD = p_CUST_CD                     --협력업체코드
	       AND A.VNDR_SEQ = p_VNDR_SEQ                    --협력업체순번
	      ;
	

	END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN 
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);
END ;
/

-- PQHB_RISK_LST_S (PROCEDURE, VALID)
CREATE PROCEDURE "PQHB_RISK_LST_S"
                            (p_WRK_TP  VARCHAR2 :='U'                                     -- UPDATE FLAG( I: ISNERT, U:UPDATE, D:DELTE)
                            ,p_WRK_ID  VARCHAR2                                           -- 사용자 ID 
                            ,p_WRK_IP  VARCHAR2                                           -- 사용자 IP 
                            ,p_SIT_CD TQHB_RISK_LST.SIT_CD%TYPE                           -- 현장코드
                            ,p_PLN_YM TQHB_RISK_LST.PLN_YM%TYPE                           -- 계획년월
                            ,p_PLN_DGR TQHB_RISK_LST.PLN_DGR%TYPE                         -- 차수구분코드(QS005) 1 1차,2 2차
                            ,p_CUST_CD TQHB_RISK_LST.CUST_CD%TYPE                         -- 협력업체코드
                            ,p_VNDR_SEQ TQHB_RISK_LST.VNDR_SEQ%TYPE                       -- 업체순번
                            ,p_CTP_CD TQHB_RISK_LST.CTP_CD%TYPE                           -- 공종코드
                            ,p_UNT_CD TQHB_RISK_LST.UNT_CD%TYPE                           -- 단위코드
                            ,p_CHK_ITM_CD TQHB_RISK_LST.CHK_ITM_CD%TYPE                   -- 점검항목코드
                            ,p_CHK_ITM_SEQ TQHB_RISK_LST.CHK_ITM_SEQ%TYPE                 -- 점검항목 정열순서
                            ,p_CHK_ITM_NM TQHB_RISK_LST.CHK_ITM_NM%TYPE                   -- 점검항목명
                            ,p_CHK_LOC TQHB_RISK_LST.CHK_LOC%TYPE                         -- 점검위치
                            ,p_DISS_SHP TQHB_RISK_LST.DISS_SHP%TYPE                       -- 재해형태(QS036)
                            ,p_RISK_FREQ TQHB_RISK_LST.RISK_FREQ%TYPE                     -- 확정_빈도(QS09003) 작성
                            ,p_RISK_APRV TQHB_RISK_LST.RISK_APRV%TYPE                     -- 확정_강도(QS09004) 작성
                            ,p_RISK_CRIT TQHB_RISK_LST.RISK_CRIT%TYPE                     -- 확정_위험성(QS09001) 작성
                            ,p_RISK_GRD TQHB_RISK_LST.RISK_GRD%TYPE                       -- 확정_위험등급(QS09002) 작성
                            ,p_IMPRV_CPLN TQHB_RISK_LST.IMPRV_CPLN%TYPE                   -- 개선대책
                            ,p_WRK_PSNNO TQHB_RISK_LST.WRK_PSNNO%TYPE                     -- 작업인원
                            ,p_ITM_ADD_YN TQHB_RISK_LST.ITM_ADD_YN%TYPE)                  -- 기존 : 0, 추가 : 1
IS 
    /**************************************************************************************************************************
      Purpose : 위험성평가표작성 저장

      REVISIONS
      Ver      Date               Author                  Description 
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2026/08/03 08:52:39                         최초생성

    /**************************************************************************************************************************/


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR2(200);            -- ERROR Message
    USER_EXCEPTION EXCEPTION;


BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 필수입력 필드  Check  ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_SIT_CD IS NULL)  THEN
        ERR_MSG := '현장코드는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_PLN_YM IS NULL)  THEN
        ERR_MSG := '계획년월는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_PLN_DGR IS NULL)  THEN
        ERR_MSG := '차수구분코드(QS005) 1 1차,2 2차는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_CUST_CD IS NULL)  THEN
        ERR_MSG := '협력업체코드는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_UNT_CD IS NULL)  THEN
        ERR_MSG := '단위코드는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_CHK_ITM_CD IS NULL)  THEN
        ERR_MSG := '점검항목코드는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Process 선행조건 Check ]
    ---------------------------------------------------------------------------------------------------------------------------



    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Business Process ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_WRK_TP ='D') THEN
        DELETE 
          FROM TQHB_RISK_LST
         WHERE SIT_CD = p_SIT_CD          --현장코드
           AND PLN_YM = p_PLN_YM          --계획년월
           AND PLN_DGR = p_PLN_DGR         --차수구분코드(QS005) 1 1차,2 2차
           AND CUST_CD = p_CUST_CD         --협력업체코드
           AND VNDR_SEQ = p_VNDR_SEQ         --협력업체순번
           AND CTP_CD = p_CTP_CD          --공종코드
           AND UNT_CD = p_UNT_CD          --단위코드
           AND CHK_ITM_CD = p_CHK_ITM_CD;     --점검항목코드

    ELSIF (p_WRK_TP ='U') THEN
        UPDATE TQHB_RISK_LST
           SET CHK_ITM_SEQ          = p_CHK_ITM_SEQ             --점검항목 정열순서
              ,CHK_ITM_NM           = p_CHK_ITM_NM              --점검항목명
              ,CHK_LOC              = p_CHK_LOC                 --점검위치
              ,DISS_SHP             = p_DISS_SHP                --재해형태(QS036)
              ,IMPRV_CPLN           = p_IMPRV_CPLN              --개선대책
              ,WRK_PSNNO            = p_WRK_PSNNO               --작업인원
              ,ITM_ADD_YN           = p_ITM_ADD_YN              --기존 : 0, 추가 : 1
              ,UPD_ID               = p_WRK_ID                  --수정ID 
              ,UPD_DTM              = SYSDATE()                 --수정일시
              ,UPD_IP               = p_WRK_IP                  --수정IP
         WHERE SIT_CD = p_SIT_CD          --현장코드
           AND PLN_YM = p_PLN_YM          --계획년월
           AND PLN_DGR = p_PLN_DGR         --차수구분코드(QS005) 1 1차,2 2차
           AND CUST_CD = p_CUST_CD         --협력업체코드
           AND VNDR_SEQ = p_VNDR_SEQ         --협력업체순번
           AND CTP_CD = p_CTP_CD          --공종코드
           AND UNT_CD = p_UNT_CD          --단위코드
           AND CHK_ITM_CD = p_CHK_ITM_CD;     --점검항목코드
    ELSE 
        INSERT INTO TQHB_RISK_LST
                   ( SIT_CD                  --현장코드
                    ,PLN_YM                  --계획년월
                    ,PLN_DGR                 --차수구분코드(QS005) 1 1차,2 2차
                    ,CUST_CD                 --협력업체코드
                    ,VNDR_SEQ
                    ,CTP_CD                  --공종코드
                    ,UNT_CD                  --단위코드
                    ,CHK_ITM_CD              --점검항목코드
                    ,CHK_ITM_SEQ             --점검항목 정열순서
                    ,CHK_ITM_NM              --점검항목명
                    ,CHK_LOC                 --점검위치
                    ,DISS_SHP                --재해형태(QS036)
                    ,RISK_FREQ               --확정_빈도(QS09003) 작성
                    ,RISK_APRV               --확정_강도(QS09004) 작성
                    ,RISK_CRIT               --확정_위험성(QS09001) 작성
                    ,RISK_GRD                --확정_위험등급(QS09002) 작성
                    ,IMPRV_CPLN              --개선대책
                    ,WRK_PSNNO               --작업인원
                    ,ITM_ADD_YN              --기존 : 0, 추가 : 1
                    ,IPT_ID                  --입력ID
                    ,IPT_DTM                 --입력일시
                    ,IPT_IP                  --입력IP
                    ,UPD_ID                  --수정ID
                    ,UPD_DTM                 --수정일시
                    ,UPD_IP                  --수정IP
                    )
             VALUES (p_SIT_CD                --현장코드
                    ,p_PLN_YM                --계획년월
                    ,p_PLN_DGR               --차수구분코드(QS005) 1 1차,2 2차
                    ,p_CUST_CD               --협력업체코드
                    ,p_VNDR_SEQ
                    ,p_CTP_CD                --공종코드
                    ,p_UNT_CD                --단위코드
                    ,p_CHK_ITM_CD            --점검항목코드
                    ,p_CHK_ITM_SEQ           --점검항목 정열순서
                    ,p_CHK_ITM_NM            --점검항목명
                    ,p_CHK_LOC               --점검위치
                    ,p_DISS_SHP              --재해형태(QS036)
                    ,p_RISK_FREQ             --확정_빈도(QS09003) 작성
                    ,p_RISK_APRV             --확정_강도(QS09004) 작성
                    ,p_RISK_CRIT             --확정_위험성(QS09001) 작성
                    ,p_RISK_GRD              --확정_위험등급(QS09002) 작성
                    ,p_IMPRV_CPLN            --개선대책
                    ,p_WRK_PSNNO             --작업인원
                    ,p_ITM_ADD_YN            --기존 : 0, 추가 : 1
                    ,p_WRK_ID                --입력ID 
                    ,SYSDATE()               --입력일시
                    ,p_WRK_IP                --입력IP
                    ,p_WRK_ID                --수정ID
                    ,SYSDATE()               --수정일시
                    ,p_WRK_IP);              --수정IP
    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 5. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN 
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);
END ;
/

-- PQHB_RISK_NAM_Q (PROCEDURE, VALID)
CREATE PROCEDURE "PQHB_RISK_NAM_Q"
(
      p_WRK_TP  VARCHAR2 DEFAULT 'Q'                                                       -- FLAG( Q: SELECT )
     ,p_SIT_CD TQHB_RISK_NAM.SIT_CD%TYPE                                                  -- 현장코드
     ,p_PLN_YM TQHB_RISK_NAM.PLN_YM%TYPE                                                  -- 계획년월
     ,p_PLN_DGR TQHB_RISK_NAM.PLN_DGR%TYPE                                                -- 차수구분코드(QS005) 1 1차,2 2차
     ,p_CUST_CD TQHB_RISK_NAM.CUST_CD%TYPE                                                -- 협력업체코드
     ,p_EMPE_NO TQHB_RISK_NAM.EMPE_NO%TYPE                                                -- 사원번호
     ,p_VNDR_SEQ VARCHAR2                                                                 -- 업체순번
     ,RTN_CURSOR OUT SYS_REFCURSOR
)
IS 
    /**************************************************************************************************************************
      Purpose : 위험성평가 평가자 - 조회

      REVISIONS
      Ver      Date               Author                  Description 
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2026/07/29 16:08:42                         최초생성

    /**************************************************************************************************************************/


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR2(200);            -- ERROR Message
    USER_EXCEPTION EXCEPTION;


BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 수행전 Check Logic ]
    ---------------------------------------------------------------------------------------------------------------------------
	
    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Logic 처리
    ---------------------------------------------------------------------------------------------------------------------------

    OPEN RTN_CURSOR FOR
    SELECT  A.SIT_CD                 --현장코드
           ,A.PLN_YM                 --계획년월
           ,A.PLN_DGR                 --차수구분코드(QS005) 1 1차,2 2차
           ,A.CUST_CD                 --협력업체코드
           ,A.VNDR_SEQ
           ,A.EMPE_NO                 --사원번호
           , CASE WHEN CO_DIV_CD = '1' THEN (SELECT USR_NM FROM TCOZ_USR_INFO WHERE EMPNO = A.EMPE_NO)
                  WHEN CO_DIV_CD = '2' THEN B.PNM
             END AS USR_NM
           ,A.APRS_NAMSEQ             --정열순서
           ,A.DTY_CD                 --직책코드
           , CASE WHEN CO_DIV_CD = '1' THEN FHRZ_GETCDNAME(A.DTY_CD, 'HRZ0EF')
                  WHEN CO_DIV_CD = '2' THEN B.DTY_NM
             END AS DTY_NM
           ,A.CO_DIV_CD
           ,A.JB_CD
           , NVL((SELECT CD_NM FROM TCOA_COMCODE WHERE COM_CD = A.JB_CD AND HRNK_CD = 'QS077' AND USE_YN = '1'),'') AS JB_NM
           ,(
           		SELECT COUNT(1)
		          FROM TQHB_RISK_CHK
		         WHERE SIT_CD = A.SIT_CD
		           AND PLN_YM = A.PLN_YM
		           AND PLN_DGR = A.PLN_DGR
		           AND CUST_CD = A.CUST_CD
		           AND VNDR_SEQ = A.VNDR_SEQ
		           AND EMPE_NO = A.EMPE_NO
		           AND SBM_YN = '1'
            ) AS SBM_CNT
      FROM TQHB_RISK_NAM A,
           (
           	 SELECT *
			  FROM TQHB_VNDRNAM
			 WHERE 1=1
			   AND SIT_CD    = p_SIT_CD
			   AND CUST_CD   = p_CUST_CD
			   AND VNDR_SEQ  = p_VNDR_SEQ
           ) B
    WHERE 1=1
      AND A.EMPE_NO = B.EMPE_NO(+)
      AND A.SIT_CD = p_SIT_CD                     --현장코드
      AND A.PLN_YM = p_PLN_YM                     --계획년월
      AND A.PLN_DGR = p_PLN_DGR                     --차수구분코드(QS005) 1 1차,2 2차
      AND A.CUST_CD = p_CUST_CD                     --협력업체코드
      AND A.VNDR_SEQ = p_VNDR_SEQ                     
    ORDER BY A.APRS_NAMSEQ
    ;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN 
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);
END ;
/

-- PQHB_RISK_NAM_S (PROCEDURE, VALID)
CREATE PROCEDURE "PQHB_RISK_NAM_S"
                            (p_WRK_TP  VARCHAR2 :='U'                                     -- UPDATE FLAG( I: ISNERT, U:UPDATE, D:DELTE)
                            ,p_WRK_ID  VARCHAR2                                           -- 사용자 ID 
                            ,p_WRK_IP  VARCHAR2                                           -- 사용자 IP 
                            ,p_SIT_CD TQHB_RISK_NAM.SIT_CD%TYPE                           -- 현장코드
                            ,p_PLN_YM TQHB_RISK_NAM.PLN_YM%TYPE                           -- 계획년월
                            ,p_PLN_DGR TQHB_RISK_NAM.PLN_DGR%TYPE                         -- 차수구분코드(QS005) 1 1차,2 2차
                            ,p_CUST_CD TQHB_RISK_NAM.CUST_CD%TYPE                         -- 협력업체코드
                            ,p_VNDR_SEQ TQHB_RISK_NAM.VNDR_SEQ%TYPE                       -- 업체순번
                            ,p_EMPE_NO TQHB_RISK_NAM.EMPE_NO%TYPE                         -- 사원번호
                            ,p_EMPE_NO_PRV TQHB_RISK_NAM.EMPE_NO%TYPE                     -- 이전
                            ,p_APRS_NAMSEQ TQHB_RISK_NAM.APRS_NAMSEQ%TYPE                 -- 정열순서
                            ,p_DTY_CD TQHB_RISK_NAM.DTY_CD%TYPE                           -- 직책코드
                            ,p_JB_CD TQHB_RISK_NAM.JB_CD%TYPE                             -- 직위코드
                            ,p_CO_DIV_CD TQHB_RISK_NAM.CO_DIV_CD%TYPE                     -- 회사구분
                            )
IS 
    /**************************************************************************************************************************
      Purpose : 위험성평가 평가자 - 추가

      REVISIONS
      Ver      Date               Author                  Description 
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2026/07/29 16:09:28                         최초생성

    /**************************************************************************************************************************/


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR2(200);            -- ERROR Message
    USER_EXCEPTION EXCEPTION;

	v_APRS_NAMSEQ NUMBER;
	v_CNT	      NUMBER;
	v_CNT2	      NUMBER;
BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 필수입력 필드  Check  ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_SIT_CD IS NULL)  THEN
        ERR_MSG := '현장코드는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_PLN_YM IS NULL)  THEN
        ERR_MSG := '계획년월는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_PLN_DGR IS NULL)  THEN
        ERR_MSG := '차수구분는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_CUST_CD IS NULL)  THEN
        ERR_MSG := '협력업체코드는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_EMPE_NO IS NULL)  THEN
        ERR_MSG := '사원번호는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Process 선행조건 Check ]
    ---------------------------------------------------------------------------------------------------------------------------
    
	SELECT COUNT(1) INTO v_CNT 
      FROM TQHB_RISK_NAM
     WHERE SIT_CD = p_SIT_CD          --현장코드
       AND PLN_YM = p_PLN_YM          --계획년월
       AND PLN_DGR = p_PLN_DGR         --차수구분코드(QS005) 1 1차,2 2차
       AND CUST_CD = p_CUST_CD         --협력업체코드
       AND VNDR_SEQ = p_VNDR_SEQ          --공종코드
       AND EMPE_NO = p_EMPE_NO;        --사원번호
       
    IF (p_WRK_TP = 'I' AND v_CNT > 0)  THEN
        ERR_MSG := '이미 추가된 직원 입니다.';
        RAISE USER_EXCEPTION;
    END IF;


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Business Process ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_WRK_TP ='D') THEN
    
     	DELETE 
          FROM TQHB_RISK_CHK
         WHERE SIT_CD = p_SIT_CD          --현장코드
           AND PLN_YM = p_PLN_YM          --계획년월
           AND PLN_DGR = p_PLN_DGR         --차수구분코드(QS005) 1 1차,2 2차
           AND CUST_CD = p_CUST_CD         --협력업체코드
           AND VNDR_SEQ = p_VNDR_SEQ       --업체순번
           AND EMPE_NO = p_EMPE_NO;         --사원번호
                    
        DELETE 
          FROM TQHB_RISK_NAM
         WHERE SIT_CD = p_SIT_CD          --현장코드
           AND PLN_YM = p_PLN_YM          --계획년월
           AND PLN_DGR = p_PLN_DGR         --차수구분코드(QS005) 1 1차,2 2차
           AND CUST_CD = p_CUST_CD         --협력업체코드
           AND VNDR_SEQ = p_VNDR_SEQ          --공종코드
           AND EMPE_NO = p_EMPE_NO;        --사원번호

    ELSIF (p_WRK_TP ='U') THEN
    
    	IF (p_EMPE_NO_PRV != p_EMPE_NO) THEN
    		DELETE 
	          FROM TQHB_RISK_CHK
	         WHERE SIT_CD = p_SIT_CD          --현장코드
	           AND PLN_YM = p_PLN_YM          --계획년월
	           AND PLN_DGR = p_PLN_DGR         --차수구분코드(QS005) 1 1차,2 2차
	           AND CUST_CD = p_CUST_CD         --협력업체코드
	           AND VNDR_SEQ = p_VNDR_SEQ       --업체순번
	           AND EMPE_NO = p_EMPE_NO;         --사원번호
    	END IF;    	
           
        UPDATE TQHB_RISK_NAM
           SET
               EMPE_NO              = p_EMPE_NO  				--사원번호
              ,JB_CD                = p_JB_CD                  --직책코드
              ,CO_DIV_CD            = p_CO_DIV_CD               --회사구분
              ,UPD_ID               = p_WRK_ID                  --수정ID 
              ,UPD_DTM              = SYSDATE()                 --수정일시
              ,UPD_IP               = p_WRK_IP                  --수정IP
         WHERE SIT_CD = p_SIT_CD          --현장코드
           AND PLN_YM = p_PLN_YM          --계획년월
           AND PLN_DGR = p_PLN_DGR         --차수구분코드(QS005) 1 1차,2 2차
           AND CUST_CD = p_CUST_CD         --협력업체코드
           AND VNDR_SEQ = p_VNDR_SEQ        
           AND EMPE_NO = p_EMPE_NO_PRV;        --사원번호
    ELSE 
    
    	 SELECT NVL(MAX(APRS_NAMSEQ),0)+1 INTO v_APRS_NAMSEQ 
          FROM TQHB_RISK_NAM
         WHERE SIT_CD = p_SIT_CD          --현장코드
           AND PLN_YM = p_PLN_YM          --계획년월
           AND PLN_DGR = p_PLN_DGR         --차수구분코드(QS005) 1 1차,2 2차
           AND CUST_CD = p_CUST_CD         --협력업체코드
           AND VNDR_SEQ = p_VNDR_SEQ;          --공종코드
           
        INSERT INTO TQHB_RISK_NAM
                   ( SIT_CD                  --현장코드
                    ,PLN_YM                  --계획년월
                    ,PLN_DGR                 --차수구분코드(QS005) 1 1차,2 2차
                    ,CUST_CD                 --협력업체코드
                    ,VNDR_SEQ
                    ,EMPE_NO                 --사원번호
                    ,APRS_NAMSEQ             --정열순서
                    ,JB_CD                  --직책코드
                    ,CO_DIV_CD
                    ,IPT_ID                  --입력ID
                    ,IPT_DTM                 --입력일시
                    ,IPT_IP                  --입력IP
                    ,UPD_ID                  --수정ID
                    ,UPD_DTM                 --수정일시
                    ,UPD_IP                  --수정IP
                    )
             VALUES (p_SIT_CD                --현장코드
                    ,p_PLN_YM                --계획년월
                    ,p_PLN_DGR               --차수구분코드(QS005) 1 1차,2 2차
                    ,p_CUST_CD               --협력업체코드
                    ,p_VNDR_SEQ
                    ,p_EMPE_NO               --사원번호
                    ,v_APRS_NAMSEQ           --정열순서
                    ,p_JB_CD                --직책코드
                    ,p_CO_DIV_CD
                    ,p_WRK_ID                --입력ID 
                    ,SYSDATE()               --입력일시
                    ,p_WRK_IP                --입력IP
                    ,p_WRK_ID                --수정ID
                    ,SYSDATE()               --수정일시
                    ,p_WRK_IP);              --수정IP
    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 5. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN 
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);
END ;
/

-- PQHB_RISK_SCHD_MNG_CO_Q (PROCEDURE, VALID)
CREATE PROCEDURE "PQHB_RISK_SCHD_MNG_CO_Q" (
    p_WRK_TP            IN VARCHAR2 DEFAULT 'Q'             -- FLAG(Q: 현장평가, Q1:본사평가)
,   p_SIT_CD            IN VARCHAR2                         -- 현장코드
,   p_CUST_CD           IN VARCHAR2                         -- 고객코드
,   p_VNDR_SEQ          IN VARCHAR2                         -- 업체순번
,   p_PLN_YM            IN VARCHAR2                         -- 계획년월
,   p_PLN_DGR           IN VARCHAR2                         -- 계획차수
,   p_CTP_CD            IN VARCHAR2                         -- 공종코드 
,   p_UNT_CD            IN VARCHAR2                         -- 단위코드
,   RTN_CURSOR       OUT SYS_REFCURSOR
) 
IS

    /**************************************************************************************************************************
      Purpose : 파트너 위험성평가등록 

      REVISIONS
      Ver      Date               Author                  Description
      -------  -----------------  ----------------------  ---------------------------------------------------------------------
      1.0      2026/02/27                                 최초생성

    **************************************************************************************************************************/

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE  NUMBER :=-20009; -- ERROR 코드
    ERR_MSG   VARCHAR(200);    -- ERROR Message
    USER_EXCEPTION EXCEPTION;

BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 수행전 Check Logic ]
    ---------------------------------------------------------------------------------------------------------------------------

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Logic 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    -- 그리드 조회 : 위험성평가 목록 (현장)
    IF p_WRK_TP = 'Q1' THEN

        OPEN RTN_CURSOR FOR
        SELECT A.SIT_CD                  --현장코드
             , A.PLN_YM                   --계획년월
             , A.PLN_DGR                  --계획차수
             ,( SELECT CD_NM FROM TCOA_COMCODE WHERE COM_CD = A.PLN_DGR AND HRNK_CD = 'QS005') AS PLN_DGR_NM  -- 계획차수명칭
             , B.APRS_STR_DT              --평가시작일
             , B.APRS_END_DT              --평가종료일
             , B.VNDR_CMPL_DT             --업체작성완료일자
             , B.CONF_SCH_DT              --회의예정일자
             , A.SBM_YN                   --평가서제출여부
             , DECODE(NVL(A.SBM_YN,0), '1', '제출', '작성중') AS SBM_NM -- 제출여부명칭
             , A.SBM_DT                   --평가서제출일자
             , A.CUST_CD                  --협력업체코드
             , ( SELECT CUST_NM FROM VQSZ_TRADE WHERE CUST_CD = A.CUST_CD ) AS VNDR_NM --협력업체명
             , A.VNDR_SEQ                 --협력업체차수
             , A.CHK_ATFL_GRP             --첨부파일그룹
          FROM TQHB_RISK_VNDR A
             , TQHB_RISK_DGR B
         WHERE A.SIT_CD         =  B.SIT_CD
           AND A.PLN_YM         = B.PLN_YM
           AND A.PLN_DGR        = B.PLN_DGR
           AND A.SIT_CD         = p_SIT_CD
           AND A.CUST_CD        = p_CUST_CD
           AND A.VNDR_SEQ       = p_VNDR_SEQ
           AND A.OBJ_YN         = '1'           -- 대상유무
           AND (NVL(p_PLN_YM, '*') = '*'     OR A.PLN_YM     = p_PLN_YM)
           AND (NVL(p_PLN_DGR, '*') = '*'    OR A.PLN_DGR    = p_PLN_DGR)
         ORDER BY A.PLN_YM DESC, A.PLN_DGR DESC
        ;

    -- 그리드 조회 : 위험성평가 목록 (본사)
    ELSIF p_WRK_TP = 'Q1_H' THEN

        OPEN RTN_CURSOR FOR
        SELECT A.SIT_CD                  --현장코드
             , A.PLN_YM                   --계획년월
             , A.PLN_DGR                  --계획차수
             ,( SELECT CD_NM FROM TCOA_COMCODE WHERE COM_CD = A.PLN_DGR AND HRNK_CD = 'QS005') AS PLN_DGR_NM  -- 계획차수명칭
             , B.APRS_STR_DT              --평가시작일
             , B.APRS_END_DT              --평가종료일
             , B.VNDR_CMPL_DT             --업체작성완료일자
             , B.CONF_SCH_DT              --회의예정일자
             , A.SBM_YN                   --평가서제출여부
             , DECODE(NVL(A.SBM_YN,0), '1', '제출', '작성중') AS SBM_NM -- 제출여부명칭
             , A.SBM_DT                   --평가서제출일자
             , A.CUST_CD                  --협력업체코드
             , ( SELECT CUST_NM FROM VQSZ_TRADE WHERE CUST_CD = A.CUST_CD ) AS VNDR_NM --협력업체명
             , A.VNDR_SEQ                 --협력업체차수
             , A.CHK_ATFL_GRP             --첨부파일그룹
          FROM TQHB_RISK_VNDR A
             , TQHB_RISK_DGR B
         WHERE A.SIT_CD         =  B.SIT_CD
           AND A.PLN_YM         = B.PLN_YM
           AND A.PLN_DGR        = B.PLN_DGR 
           AND A.SIT_CD         = p_SIT_CD
           AND A.OBJ_YN         = '1'           -- 대상유무
           AND (NVL(p_PLN_YM, '*') = '*'     OR A.PLN_YM     = p_PLN_YM)
           AND (NVL(p_PLN_DGR, '*') = '*'    OR A.PLN_DGR    = p_PLN_DGR)
         ORDER BY A.PLN_YM DESC, A.PLN_DGR DESC
        ;
    --------------------------------------------------------------------------------
    -- 그리드 조회 : 위험성평가 작성
    ELSIF p_WRK_TP = 'Q2' THEN

        OPEN RTN_CURSOR FOR
        SELECT 
            SIT_CD                 --현장코드
           ,PLN_YM                 --계획년월
           ,PLN_DGR                 --차수구분코드(QS005) 1 1차,2 2차
           ,CTP_CD           -- 공종코드
           ,( SELECT CTP_NM FROM TQHA_CTP WHERE CTP_CD = A.CTP_CD ) AS CTP_NM    -- 공종명칭
           ,UNT_CD           -- 단위코드
           ,( SELECT UNT_NM FROM TQHA_CTPUNT WHERE CTP_CD = A.CTP_CD AND UNT_CD = A.UNT_CD ) AS UNT_NM    -- 단위명칭
           ,CHK_ITM_CD                 --점검항목코드
           ,EMPE_NO                 --사원번호
           ,APRS_NAMSEQ                 --점검자 정열순서
           ,RISK_FREQ                 --빈도(QS09003) 작성
           ,RISK_APRV                 --강도(QS09004) 작성
           ,RISK_CRIT                 --위험성(QS09001) 작성
           ,RISK_GRD                 --위험등급(QS09002) 작성
           ,IMPRV_CPLN                 --개선대책
           ,RISK_FREQ2                 --개선후_빈도(QS09003) 작성
           ,RISK_APRV2                 --개선후_강도(QS09004) 작성
           ,RISK_CRIT2                 --개선후_위험성(QS09001) 작성
           ,RISK_GRD2                 --개선후_위험등급(QS09002) 작성
           ,DTY_CD                 --직책코드
           ,MGR_OPIN                 --관리자의견
           ,SBM_DT                 --제출일자
           ,SBM_YN                 --제출1 미제출0
           ,VNDR_SEQ                 --업체순번
           ,(SELECT DECODE(COUNT(1),0,'중흥','협력사') FROM TQHA_VNDR WHERE SIT_CD = A.SIT_CD AND VNDR_PSN_ID = A.IPT_ID) AS REG_DIV
          FROM TQHB_RISK_CHK A
         WHERE A.SIT_CD     = p_SIT_CD
           AND A.PLN_YM     = p_PLN_YM
           AND A.PLN_DGR    = p_PLN_DGR
           AND A.CUST_CD    = p_CUST_CD
           AND A.VNDR_SEQ   = p_VNDR_SEQ
        ;

    --------------------------------------------------------------------------------
    -- 그리드 조회 : 위험요인항목 추가 - 공종별 단위작업 리스트 (트리)
    ELSIF p_WRK_TP = 'Q3' THEN

        OPEN RTN_CURSOR FOR
        SELECT A.CTP_CD   -- 상위공종코드
             , A.UNT_CD   -- 단위작업코드
             , A.CTP_NM   -- 단위작업명칭
             , A.USE_YN
             , A."Level"
          FROM ( SELECT CTP_CD         -- 공종코드
                      , ' ' AS UNT_CD  -- 단위작업코드
                      , CTP_NM         -- 공종명칭
                      , USE_YN         -- 공종 사용유무
                      , '1' AS "Level" -- 레벨1
                   FROM TQHA_CTP
                  WHERE USE_YN = '1'
                  UNION ALL
                 SELECT CTP_CD          -- 상위공종코드
                      , UNT_CD          -- 단위작업코드
                      , UNT_NM          -- 단위작업명칭
                      , USE_YN          -- 단위작업사용유무
                      , '2'  AS "Level" -- 레벨 2
                   FROM TQHA_CTPUNT 
                  WHERE USE_YN = '1') A
         ORDER BY A.CTP_CD, A.UNT_CD ASC
        ;

    --------------------------------------------------------------------------------
    -- 그리드 조회 : 위험요인항목 추가 - 위험요인항목
    ELSIF p_WRK_TP = 'Q4' THEN

        OPEN RTN_CURSOR FOR

        SELECT A.CTP_CD      -- 상위공종코드
             , ( SELECT CTP_NM FROM TQHA_CTP WHERE CTP_CD = A.CTP_CD ) AS CTP_NM    -- 공종명칭
             , A.UNT_CD      -- 단위작업코드
             , ( SELECT UNT_NM FROM TQHA_CTPUNT WHERE CTP_CD = A.CTP_CD AND UNT_CD = A.UNT_CD ) AS UNT_NM    -- 단위명칭
             , A.CHK_ITM_CD  -- 점검항목코드
             , A.CHK_ITM_NM  -- 점검항목명칭
             , A.RISK_FREQ   -- 빈도레벨(QS003)
             , A.RISK_APRV   -- 강도레벨(QS004)  
             , A.RISK_CRIT   -- 위험성(공통코드 QS063)
             , A.RISK_GRD    -- 위험등급(QS024)
             , A.IMPRV_CPLN  -- 개선대책
             , A.USE_YN      -- 단위작업사용유무
             , A.CUST_CD     -- 업체코드
             , A.USR_DEFN_YN -- 사용자정의 구분
             , A.DISS_SHP    -- 재해형태(QS036)
          FROM TQHB_CTPUNT_CHKITM A
         WHERE A.USR_DEFN_YN    = '0'
           AND A.CTP_CD         = p_CTP_CD
           AND A.UNT_CD         = p_UNT_CD
        ;

    --------------------------------------------------------------------------------
    -- 그리드 조회 : 위험요인항목 추가 - 사용자정의 위험요인항목 
    ELSIF p_WRK_TP = 'Q5' THEN

        OPEN RTN_CURSOR FOR
        SELECT A.CTP_CD      -- 상위공종코드
             , ( SELECT CTP_NM FROM TQHA_CTP WHERE CTP_CD = A.CTP_CD ) AS CTP_NM    -- 공종명칭
             , A.UNT_CD      -- 단위작업코드
             , ( SELECT UNT_NM FROM TQHA_CTPUNT WHERE CTP_CD = A.CTP_CD AND UNT_CD = A.UNT_CD ) AS UNT_NM    -- 단위명칭
             , A.CHK_ITM_CD  -- 점검항목코드
             , A.CHK_ITM_NM  -- 점검항목명칭
             , A.RISK_FREQ   -- 빈도레벨(QS003)
             , A.RISK_APRV   -- 강도레벨(QS004)
             , A.RISK_CRIT   -- 위험성(공통코드 QS063)
             , A.RISK_GRD    -- 위험등급(QS024)
             , A.IMPRV_CPLN  -- 개선대책
             , A.USE_YN      -- 단위작업사용유무
             , A.CUST_CD     -- 업체코드
             , A.USR_DEFN_YN -- 사용자정의 구분
             , A.DISS_SHP    -- 재해형태(QS036)
          FROM TQHB_CTPUNT_CHKITM A
         WHERE A.USR_DEFN_YN = '1'
           AND A.CTP_CD     = p_CTP_CD
           AND A.UNT_CD     = p_UNT_CD
           AND A.CUST_CD    = p_CUST_CD
        ;

    --------------------------------------------------------------------------------
    -- 위험성평가 평가서제출 여부 조회
    ELSIF p_WRK_TP = 'Q6' THEN

        OPEN RTN_CURSOR FOR
        SELECT SBM_YN
             --, MNG_APRV_STATS
          FROM TQHB_RISK_VNDR
         WHERE SIT_CD       = p_SIT_CD
           AND PLN_DGR      = p_PLN_DGR
           AND PLN_YM       = p_PLN_YM
           AND CUST_CD      = p_CUST_CD
           AND VNDR_SEQ     = p_VNDR_SEQ
        ;

    --------------------------------------------------------------------------------
    -- 전회차복사 목록 조회
    ELSIF p_WRK_TP = 'Q7' THEN

        OPEN RTN_CURSOR FOR
         SELECT  SIT_CD                 --현장코드
	           ,PLN_YM                 --계획년월
	           ,PLN_DGR                 --차수구분코드(QS005) 1 1차,2 2차
	           ,CUST_CD                 --협력업체코드
	           ,VNDR_SEQ                 --업체순번
	           ,CTP_CD           -- 공종코드
	           ,( SELECT CTP_NM FROM TQHA_CTP WHERE CTP_CD = A.CTP_CD ) AS CTP_NM    -- 공종명칭
	           ,UNT_CD           -- 단위코드
	           ,( SELECT UNT_NM FROM TQHA_CTPUNT WHERE CTP_CD = A.CTP_CD AND UNT_CD = A.UNT_CD ) AS UNT_NM    -- 단위명칭
	           ,CHK_ITM_CD                 --점검항목코드
	           ,CHK_ITM_SEQ                 --점검항목 정열순서
	           ,CHK_ITM_NM                 --점검항목명
	           ,CHK_LOC                 --점검위치
	           ,DISS_SHP                 --재해형태(QS036)
	           ,RISK_FREQ                 --확정_빈도(QS09003) 작성
	           ,RISK_APRV                 --확정_강도(QS09004) 작성
	           ,RISK_CRIT                 --확정_위험성(QS09001) 작성
	           ,RISK_GRD                 --확정_위험등급(QS09002) 작성
	           ,IMPRV_CPLN                 --개선대책
	           ,WRK_PSNNO                 --작업인원
	           ,ITM_ADD_YN                 --기존 : 0, 추가 : 1         
	           ,(SELECT DECODE(COUNT(1),0,'중흥','협력사') FROM TQHA_VNDR WHERE SIT_CD = A.SIT_CD AND VNDR_PSN_ID = A.IPT_ID) AS REG_DIV  
	      	FROM TQHB_RISK_LST A
	         WHERE A.SIT_CD     = p_SIT_CD
	           AND A.PLN_YM     = p_PLN_YM
	           AND A.PLN_DGR    = p_PLN_DGR
	           AND A.CUST_CD    = p_CUST_CD
	           AND A.VNDR_SEQ   = p_VNDR_SEQ
        ;

    --------------------------------------------------------------------------------
    -- SMS 처리 ( 협력업체 평가서 제출 )
    ELSIF p_WRK_TP = 'Q8' THEN

        OPEN RTN_CURSOR FOR
        SELECT A.SIT_CD
             , A.PLN_YM
             , A.PLN_DGR
             , A.CUST_CD
             , A.VNDR_SEQ
             , C.MGR_1                      AS MA_CNFR
             , REPLACE(B.MP_NO, '-', '')    AS MP_NO
             -- REPLACE(SYS.PKG_CRYPTO_DEC.DECRYPT(B.MP_NO), '-', '') MP_NO
          FROM (-- 협력업체 위험성평가 제출 시 확인자 리스트
                SELECT SIT_CD
                     , PLN_YM
                     , PLN_DGR
                     , CUST_CD
                     , VNDR_SEQ
                  FROM TQHB_RISK_CHK
                 WHERE SIT_CD   = p_SIT_CD     -- 변수(현장)
                   AND PLN_YM   = p_PLN_YM        -- 변수(평가년월)
                   AND PLN_DGR  = p_PLN_DGR     -- 변수(차수)
                   AND CUST_CD  = p_CUST_CD
                   AND VNDR_SEQ = p_VNDR_SEQ
                 GROUP 
                    BY SIT_CD
                     , PLN_YM
                     , PLN_DGR
                     , CUST_CD
                     , VNDR_SEQ
               ) A
               JOIN (
                               SELECT SIT_CD, MGR_1 FROM TQHA_VNDR WHERE SIT_CD = P_SIT_CD AND CUST_CD = p_CUST_CD AND VNDR_SEQ = p_VNDR_SEQ AND NVL(MGR_1, '*') != '*'
                     UNION ALL SELECT SIT_CD, MGR_2 FROM TQHA_VNDR WHERE SIT_CD = P_SIT_CD AND CUST_CD = p_CUST_CD AND VNDR_SEQ = p_VNDR_SEQ AND NVL(MGR_2, '*') != '*'
                     UNION ALL SELECT SIT_CD, MGR_3 FROM TQHA_VNDR WHERE SIT_CD = P_SIT_CD AND CUST_CD = p_CUST_CD AND VNDR_SEQ = p_VNDR_SEQ AND NVL(MGR_3, '*') != '*'
                    ) C  ON A.SIT_CD = C.SIT_CD
               JOIN TCOZ_USR_INFO B ON C.SIT_CD = B.DEPT_CD
                                   AND C.MGR_1  = B.USR_ID
        ;

    END IF;


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
         WHEN OTHERS THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);

END PQHB_RISK_SCHD_MNG_CO_Q ;
/

-- PQHB_RISK_USER_LIST_Q (PROCEDURE, VALID)
CREATE PROCEDURE "PQHB_RISK_USER_LIST_Q" (
      p_WRK_TP  VARCHAR2 DEFAULT 'Q'                                                       -- FLAG( Q: SELECT )
     ,p_SIT_CD  VARCHAR2                                                  -- 현장코드
     ,p_CUST_CD VARCHAR2                                                 -- 협력업체코드
     ,p_VNDR_SEQ VARCHAR2                                                 -- 협력업체코드
     ,RTN_CURSOR OUT SYS_REFCURSOR
)
IS
    /**************************************************************************************************************************
      Purpose : 위험성평가 사용자 리스트 조회

      REVISIONS
      Ver      Date               Author                  Description 
      -------  -----------------  ----------------------  ---------------------------------------------------------------------
      1.0      XXXX/XX/XX                                 최초생성

    **************************************************************************************************************************/

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE  NUMBER :=-20009; -- ERROR 코드
    ERR_MSG   VARCHAR(200);    -- ERROR Message
    USER_EXCEPTION EXCEPTION;

BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 수행전 Check Logic ]
    ---------------------------------------------------------------------------------------------------------------------------

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Logic 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------

    -------------------------------------------------------------------------------------------------------------------------
    
    IF p_WRK_TP = 'Q' THEN

        OPEN RTN_CURSOR FOR
	        SELECT A.SIT_CD
			     , A.EMPE_NO
			     , A.PNM
			     , A.DTY_CD
			     , (SELECT CD_NM FROM TCOA_COMCODE WHERE COM_CD = A.DTY_CD AND HRNK_CD = 'HRZ0EF' AND USE_YN = '1') AS DTY_NM
			     , A.TEL_NO
			     , A.CELPH
			     , A.EMAIL
			     , '중흥' AS CUST_NM
			     , ( SELECT DEPT_NM FROM TCOZ_DEPT_INFO WHERE DEPT_CD = A.SIT_CD ) AS SIT_NM -- 현장명칭			     , NULL AS VNDR_SEQ
			     , '1' AS CO_DIV_CD
			     , A.JB_CD
			     , NVL((SELECT CD_NM FROM TCOA_COMCODE WHERE COM_CD = A.JB_CD AND HRNK_CD = 'QS077' AND USE_YN = '1'),'') AS JB_NM
			  FROM TQHA_SITENAM A
			 WHERE 1=1
			   AND A.SIT_CD    = p_SIT_CD
			UNION ALL 
			SELECT A.SIT_CD
			     , A.EMPE_NO
			     , A.PNM
			     , A.DTY_CD
			     , A.DTY_NM
			     , A.TEL_NO
			     , A.CELPH
			     , A.EMAIL
			     , ( SELECT CUST_NM FROM VQSZ_TRADE WHERE CUST_CD = A.CUST_CD ) AS CUST_NM   -- 업체명
			     , ( SELECT DEPT_NM FROM TCOZ_DEPT_INFO WHERE DEPT_CD = A.SIT_CD ) AS SIT_NM -- 현장명칭
			     , '2' AS CO_DIV_CD
			     , A.JB_CD
			     , NVL((SELECT CD_NM FROM TCOA_COMCODE WHERE COM_CD = A.JB_CD AND HRNK_CD = 'QS077' AND USE_YN = '1'),'') AS JB_NM
			  FROM TQHB_VNDRNAM A
			 WHERE 1=1
			   AND A.SIT_CD    = p_SIT_CD
			   AND A.CUST_CD   = p_CUST_CD
			   AND A.VNDR_SEQ   = p_VNDR_SEQ
			 ORDER BY CO_DIV_CD, SIT_CD, CUST_NM, PNM
	     ;

    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
         WHEN OTHERS THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);

END PQHB_RISK_USER_LIST_Q;
/

-- PQHB_RISK_VNDR_Q (PROCEDURE, VALID)
CREATE PROCEDURE "PQHB_RISK_VNDR_Q" (
    p_WRK_TP            IN VARCHAR2 DEFAULT 'Q'         -- FLAG
,   p_SIT_CD            IN VARCHAR2                     -- 현장코드
,   p_APRS_STR_DT       IN VARCHAR2                     -- 시작일
,   p_APRS_END_DT       IN VARCHAR2                     -- 종료일
,   p_PLN_YM            IN VARCHAR2                     -- 계획연월
,   p_PLN_DGR           IN VARCHAR2                     -- 계획차수
,   p_CUST_CD           IN VARCHAR2                     
,   p_VNDR_SEQ          IN VARCHAR2                     
,   RTN_CURSOR          OUT SYS_REFCURSOR
)
IS 
    /**************************************************************************************************************************
      Purpose : 위험성평가 대상업체_조회 

      REVISIONS 
      Ver      Date               Author                  Description
      -------  -----------------  ----------------------  ---------------------------------------------------------------------
      1.0      2026/02/09                                 최초생성

    **************************************************************************************************************************/

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE  NUMBER :=-20009; -- ERROR 코드
    ERR_MSG   VARCHAR(200);    -- ERROR Message 
    USER_EXCEPTION EXCEPTION;

BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 수행전 Check Logic ]
    ---------------------------------------------------------------------------------------------------------------------------

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Logic 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------

    ---------------------------------------------------------------------------------------
    -- 
    IF p_WRK_TP = 'Q1' THEN    
    
    	 OPEN RTN_CURSOR FOR
         SELECT 
         		A.SIT_CD
         	  , B.PLN_YM
			  , B.PLN_DGR
			  , A.CUST_CD
			  , A.VNDR_SEQ
 		      , NVL(B.OBJ_YN,0) AS OBJ_YN    -- 대상여부
              , CASE WHEN NVL(B.OBJ_YN, 0) = 0 THEN 1
                     WHEN NVL(B.OBJ_YN, 0) = 1 THEN 0
                 END      AS DEL_YN         -- 제외여부
              , A.CUST_CD AS COP_VNDR       -- 협력업체코드
              ,(SELECT CUST_NM FROM VQSZ_TRADE WHERE CUST_CD = A.CUST_CD) AS CUST_NM  --업체명
              , A.VNDR_NM                   -- 공사명
              , A.VNDR_PSN_NM               -- 협력업체담당자
              , A.VNDR_STR_DT               -- 공사시작일
              , A.VNDR_END_DT               -- 공사종료일
              , A.CTP_CD
              , A.CTP_NM -- 공종명칭
              , B.SBM_YN
              , DECODE(B.SBM_YN,'1','제출', '') AS SBM_YN_NM
			  , B.SBM_DT
			  ,(
			     SELECT SAFT_MGR_YN
			      FROM TQHB_RISK_DGR
			     WHERE SIT_CD = B.SIT_CD
			       AND PLN_YM = B.PLN_YM
			       AND PLN_DGR = B.PLN_DGR
			 ) AS SAFT_MGR_YN
           FROM TQHA_VNDR A
              , TQHB_RISK_VNDR B
          WHERE 1=1
            AND ((A.VNDR_STR_DT <= p_APRS_END_DT AND A.VNDR_END_DT >= p_APRS_STR_DT) OR NVL(B.OBJ_YN, 0) = 1)
            -- 변수 처리(평가시작일,  평가종료일)
            AND A.SIT_CD        = B.SIT_CD
            AND A.CUST_CD       = B.CUST_CD
            AND A.VNDR_SEQ      = B.VNDR_SEQ
            AND B.SIT_CD        = p_SIT_CD
            AND B.PLN_YM        = p_PLN_YM
            AND B.PLN_DGR       = p_PLN_DGR
        ;
    
   	ELSIF p_WRK_TP = 'Q2' THEN    
   	
   		OPEN RTN_CURSOR FOR
   		SELECT 
         		A.SIT_CD
         	  , B.PLN_YM
			  , B.PLN_DGR
			  , A.CUST_CD
			  , A.VNDR_SEQ
 		      , NVL(B.OBJ_YN,0) AS OBJ_YN    -- 대상여부
              , CASE WHEN NVL(B.OBJ_YN, 0) = 0 THEN 1
                     WHEN NVL(B.OBJ_YN, 0) = 1 THEN 0
                 END      AS DEL_YN         -- 제외여부
              ,(SELECT CUST_NM FROM VQSZ_TRADE WHERE CUST_CD = A.CUST_CD) AS CUST_NM  --업체명
              , A.VNDR_NM                   -- 공사명
              , A.VNDR_PSN_NM               -- 협력업체담당자
              , A.VNDR_STR_DT               -- 공사시작일
              , A.VNDR_END_DT               -- 공사종료일
              , A.CTP_CD
              , A.CTP_NM -- 공종명칭
              , B.SBM_YN
              , DECODE(B.SBM_YN,'1','제출', '') AS SBM_YN_NM
			  , B.SBM_DT
			  ,(
			     SELECT SAFT_MGR_YN
			      FROM TQHB_RISK_DGR
			     WHERE SIT_CD = B.SIT_CD
			       AND PLN_YM = B.PLN_YM
			       AND PLN_DGR = B.PLN_DGR
			 ) AS SAFT_MGR_YN
           FROM TQHA_VNDR A
              , TQHB_RISK_VNDR B
          WHERE 1=1
            AND A.SIT_CD        = B.SIT_CD
            AND A.CUST_CD       = B.CUST_CD
            AND A.VNDR_SEQ      = B.VNDR_SEQ
            AND B.SIT_CD        = p_SIT_CD
            AND B.PLN_YM        = p_PLN_YM
            AND B.PLN_DGR       = p_PLN_DGR
            AND B.CUST_CD       = p_CUST_CD
            AND B.VNDR_SEQ      = p_VNDR_SEQ 
            ; 
   		
   	ELSIF p_WRK_TP = 'Q3' THEN    
   	
   		OPEN RTN_CURSOR FOR
   		SELECT 
	 	        SIT_CD                 --현장코드
	           ,PLN_YM                 --계획년월
	           ,PLN_DGR                 --차수구분코드(QS005) 1 1차,2 2차
	           ,CUST_CD                 --협력업체코드
	           ,VNDR_SEQ                 --업체순번
	           ,CTP_CD                 --공종코드
	           ,CTP_NM                 --공종명
	           ,OBJ_YN                 --대상 1 , 미대상 0
	           ,VNDR_NOTI_YN                 --발송 1 미발송 0
	           ,VNDR_SEND_DT                 --업체발송일자
	           ,SBM_YN                 --제출1 미제출0
	           ,SBM_DT                 --제출일자
	           ,CHK_ATFL_GRP                 --점검첨부파일그룹
	           ,(SELECT CUST_NM FROM VQSZ_TRADE WHERE CUST_CD = A.CUST_CD) AS CUST_NM  --업체명
	   FROM TQHB_RISK_VNDR A
	  WHERE 1=1
	    AND SIT_CD        = p_SIT_CD
        AND PLN_YM        = p_PLN_YM
        AND PLN_DGR       = p_PLN_DGR
	    ;
   		
	END IF;


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
         WHEN OTHERS THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);

END PQHB_RISK_VNDR_Q;
/

-- PQHB_RISK_VNDR_S (PROCEDURE, VALID)
CREATE PROCEDURE "PQHB_RISK_VNDR_S"
                            (p_WRK_TP  VARCHAR2 :='U'                                     -- UPDATE FLAG( I: ISNERT, U:UPDATE, D:DELTE)
                            ,p_WRK_ID  VARCHAR2                                           -- 사용자 ID 
                            ,p_WRK_IP  VARCHAR2                                           -- 사용자 IP 
                            ,p_SIT_CD TQHB_RISK_VNDR.SIT_CD%TYPE                          -- 현장코드
                            ,p_PLN_YM TQHB_RISK_VNDR.PLN_YM%TYPE                          -- 계획년월
                            ,p_PLN_DGR TQHB_RISK_VNDR.PLN_DGR%TYPE                        -- 차수구분코드(QS005) 1 1차,2 2차
                            ,p_CUST_CD TQHB_RISK_VNDR.CUST_CD%TYPE                        -- 협력업체코드
                            ,p_VNDR_SEQ TQHB_RISK_VNDR.VNDR_SEQ%TYPE                       -- 업체순번
                            ,p_CTP_CD TQHB_RISK_VNDR.CTP_CD%TYPE                          -- 공종코드
                            ,p_CTP_NM TQHB_RISK_VNDR.CTP_NM%TYPE                          -- 공종명
                            ,p_OBJ_YN TQHB_RISK_VNDR.OBJ_YN%TYPE                          -- 대상 1 , 미대상 0
                            ,p_VNDR_NOTI_YN TQHB_RISK_VNDR.VNDR_NOTI_YN%TYPE              -- 발송 1 미발송 0
                            ,p_VNDR_SEND_DT TQHB_RISK_VNDR.VNDR_SEND_DT%TYPE              -- 업체발송일자
                            ,p_SBM_YN TQHB_RISK_VNDR.SBM_YN%TYPE                          -- 제출1 미제출0
                            ,p_SBM_DT TQHB_RISK_VNDR.SBM_DT%TYPE                          -- 제출일자
                            ,p_CHK_ATFL_GRP TQHB_RISK_VNDR.CHK_ATFL_GRP%TYPE             -- 점검첨부파일그룹
                            )
IS 
    /**************************************************************************************************************************
      Purpose : 위험성평가 대상업체 - 추가

      REVISIONS
      Ver      Date               Author                  Description 
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2026/07/29 13:09:38                         최초생성

    /**************************************************************************************************************************/


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR2(200);            -- ERROR Message
    USER_EXCEPTION EXCEPTION;

	v_CNT NUMBER    := 0;
    v_CNT1  INTEGER := 0;                   -- 하위 데이타 존재 여부 확인
BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 필수입력 필드  Check  ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_SIT_CD IS NULL)  THEN
        ERR_MSG := '현장코드는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_PLN_YM IS NULL)  THEN
        ERR_MSG := '계획년월는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_PLN_DGR IS NULL)  THEN
        ERR_MSG := '차수는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_CUST_CD IS NULL)  THEN
        ERR_MSG := '협력업체코드는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Process 선행조건 Check ]
    ---------------------------------------------------------------------------------------------------------------------------



    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Business Process ]
    ---------------------------------------------------------------------------------------------------------------------------
     ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Business Process ] 
    ---------------------------------------------------------------------------------------------------------------------------
   
    IF (p_WRK_TP ='D') THEN
    
       -- 하위 데이터가 존재하는지 체크 
        SELECT NVL(COUNT(CUST_CD), 0) 
          INTO v_CNT1
          FROM TQHB_RISK_NAM
         WHERE SIT_CD   = p_SIT_CD
           AND PLN_YM   = p_PLN_YM
           AND PLN_DGR  = p_PLN_DGR
           AND CUST_CD  = p_CUST_CD
           AND VNDR_SEQ   = p_VNDR_SEQ
        ;
        IF v_CNT1 > 0 THEN
            ERR_MSG := '결재선 데이터가 존재 합니다. 삭제할 수 없습니다.';
            RAISE USER_EXCEPTION;
        END IF;
    
       -- 하위 데이터가 존재하는지 체크
        SELECT NVL(COUNT(CUST_CD), 0) 
          INTO v_CNT1
          FROM TQHB_RISK_LST
         WHERE SIT_CD   = p_SIT_CD
           AND PLN_YM   = p_PLN_YM
           AND PLN_DGR  = p_PLN_DGR
           AND CUST_CD  = p_CUST_CD
           AND VNDR_SEQ   = p_VNDR_SEQ
        ;
        IF v_CNT1 > 0 THEN
            ERR_MSG := '위험요인 데이터가 존재 합니다. 삭제할 수 없습니다.';
            RAISE USER_EXCEPTION;
        END IF;
    	
    	-- 하위 데이터가 존재하는지 체크 (TQHB_RISK_CHK)
        SELECT NVL(COUNT(CUST_CD), 0) 
          INTO v_CNT1
          FROM TQHB_RISK_CHK
         WHERE SIT_CD   = p_SIT_CD
           AND PLN_YM   = p_PLN_YM
           AND PLN_DGR  = p_PLN_DGR
           AND CUST_CD  = p_CUST_CD
           AND VNDR_SEQ   = p_VNDR_SEQ
        ;
        IF v_CNT1 > 0 THEN
            ERR_MSG := '평가 데이터가 존재 합니다. 삭제할 수 없습니다.';
            RAISE USER_EXCEPTION;
        END IF;
    
         DELETE 
          FROM TQHB_RISK_VNDR
         WHERE SIT_CD = p_SIT_CD          --현장코드
           AND PLN_YM = p_PLN_YM          --계획년월
           AND PLN_DGR = p_PLN_DGR         --차수구분코드(QS005) 1 1차,2 2차
           AND CUST_CD = p_CUST_CD         --협력업체코드
           AND VNDR_SEQ = p_VNDR_SEQ;         --공종코드
       

    ELSIF (p_WRK_TP ='U') THEN
        UPDATE TQHB_RISK_VNDR
           SET CTP_NM               = p_CTP_NM                  --공종명
              ,OBJ_YN               = p_OBJ_YN                  --대상 1 , 미대상 0
              ,VNDR_NOTI_YN         = p_VNDR_NOTI_YN            --발송 1 미발송 0
              ,VNDR_SEND_DT         = p_VNDR_SEND_DT            --업체발송일자
              ,SBM_YN               = p_SBM_YN                  --제출1 미제출0
              ,SBM_DT               = p_SBM_DT                  --제출일자
              ,CHK_ATFL_GRP         = p_CHK_ATFL_GRP            --점검첨부파일그룹
              ,UPD_ID               = p_WRK_ID                  --수정ID 
              ,UPD_DTM              = SYSDATE()                 --수정일시
              ,UPD_IP               = p_WRK_IP                  --수정IP
         WHERE SIT_CD = p_SIT_CD          --현장코드
           AND PLN_YM = p_PLN_YM          --계획년월
           AND PLN_DGR = p_PLN_DGR         --차수구분코드(QS005) 1 1차,2 2차
           AND CUST_CD = p_CUST_CD         --협력업체코드
           AND VNDR_SEQ = p_VNDR_SEQ;         --공종코드
           
    ELSE 
    
    	-- 데이터가 이미 있는지 확인
        SELECT COUNT(*) INTO v_CNT
          FROM TQHB_RISK_VNDR
         WHERE SIT_CD   = p_SIT_CD
           AND PLN_YM   = p_PLN_YM
           AND PLN_DGR  = p_PLN_DGR
           AND CUST_CD  = p_CUST_CD
           AND VNDR_SEQ   = p_VNDR_SEQ
        ;
    	IF (v_CNT > 0)  THEN
	        ERR_MSG := '이미 등록된 업체 입니다.';
	        RAISE USER_EXCEPTION;
	    END IF;

    	
        INSERT INTO TQHB_RISK_VNDR
                   ( SIT_CD                  --현장코드
                    ,PLN_YM                  --계획년월
                    ,PLN_DGR                 --차수구분코드(QS005) 1 1차,2 2차
                    ,CUST_CD                 --협력업체코드
                    ,VNDR_SEQ
                    ,CTP_CD                  --공종코드
                    ,CTP_NM                  --공종명
                    ,OBJ_YN                  --대상 1 , 미대상 0
                    ,VNDR_NOTI_YN            --발송 1 미발송 0
                    ,VNDR_SEND_DT            --업체발송일자
                    ,SBM_YN                  --제출1 미제출0
                    ,SBM_DT                  --제출일자
                    ,CHK_ATFL_GRP            --점검첨부파일그룹
                    ,IPT_ID                  --입력ID
                    ,IPT_DTM                 --입력일시
                    ,IPT_IP                  --입력IP
                    ,UPD_ID                  --수정ID
                    ,UPD_DTM                 --수정일시
                    ,UPD_IP                  --수정IP
                    )
             VALUES (p_SIT_CD                --현장코드
                    ,p_PLN_YM                --계획년월
                    ,p_PLN_DGR               --차수구분코드(QS005) 1 1차,2 2차
                    ,p_CUST_CD               --협력업체코드
                    ,p_VNDR_SEQ
                    ,p_CTP_CD                --공종코드
                    ,p_CTP_NM                --공종명
                    ,p_OBJ_YN                --대상 1 , 미대상 0
                    ,0				         --발송 1 미발송 0
                    ,p_VNDR_SEND_DT          --업체발송일자
                    ,p_SBM_YN                --제출1 미제출0
                    ,p_SBM_DT                --제출일자
                    ,p_CHK_ATFL_GRP          --점검첨부파일그룹
                    ,p_WRK_ID                --입력ID 
                    ,SYSDATE()               --입력일시
                    ,p_WRK_IP                --입력IP
                    ,p_WRK_ID                --수정ID
                    ,SYSDATE()               --수정일시
                    ,p_WRK_IP);              --수정IP
    END IF;
    
    
    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 5. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN 
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);
END ;
/

-- PQHB_RISK_VNDR_W (PROCEDURE, VALID)
CREATE PROCEDURE "PQHB_RISK_VNDR_W"
                            (p_WRK_TP  VARCHAR2 :='U'                                     -- UPDATE FLAG( I: ISNERT, U:UPDATE, D:DELTE)
                            ,p_WRK_ID  VARCHAR2                                           -- 사용자 ID 
                            ,p_WRK_IP  VARCHAR2                                           -- 사용자 IP 
                            ,p_SIT_CD TQHB_RISK_VNDR.SIT_CD%TYPE                          -- 현장코드
                            ,p_PLN_YM TQHB_RISK_VNDR.PLN_YM%TYPE                          -- 계획년월
                            ,p_PLN_DGR TQHB_RISK_VNDR.PLN_DGR%TYPE                        -- 차수구분코드(QS005) 1 1차,2 2차
                            ,p_CUST_CD TQHB_RISK_VNDR.CUST_CD%TYPE                        -- 협력업체코드
                            ,p_VNDR_SEQ TQHB_RISK_VNDR.VNDR_SEQ%TYPE                       -- 업체순번
                            ,p_SBM_YN TQHB_RISK_VNDR.SBM_YN%TYPE                          -- 제출1 미제출0
                            )
IS 
    /**************************************************************************************************************************
      Purpose : 최종점수등록

      REVISIONS
      Ver      Date               Author                  Description 
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2026/07/29 13:09:38                         최초생성

    /**************************************************************************************************************************/


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR2(200);            -- ERROR Message
    USER_EXCEPTION EXCEPTION;

	v_CNT NUMBER    := 0;
    v_CNT1  INTEGER := 0;                   -- 하위 데이타 존재 여부 확인
BEGIN 

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 필수입력 필드  Check  ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_SIT_CD IS NULL)  THEN
        ERR_MSG := '현장코드는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_PLN_YM IS NULL)  THEN
        ERR_MSG := '계획년월는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_PLN_DGR IS NULL)  THEN
        ERR_MSG := '차수는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_CUST_CD IS NULL)  THEN
        ERR_MSG := '협력업체코드는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

   ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Process 선행조건 Check ]
    ---------------------------------------------------------------------------------------------------------------------------
	SELECT COUNT(1) INTO v_CNT
      FROM TQHB_RISK_CHK
     WHERE SIT_CD = p_SIT_CD          --현장코드
       AND PLN_YM = p_PLN_YM          --계획년월
       AND PLN_DGR = p_PLN_DGR         --차수구분코드(QS005) 1 1차,2 2차
       AND CUST_CD = p_CUST_CD         --협력업체코드
       AND VNDR_SEQ = p_VNDR_SEQ         --공종코드
       AND (SBM_YN IS NULL OR SBM_YN = '0')
   ;
       
    IF (v_CNT > 0)  THEN
        ERR_MSG := '제출되지 않은 평가가 있어 진행할 수 없습니다.';
        RAISE USER_EXCEPTION;
    END IF;
    
    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Business Process ]
    ---------------------------------------------------------------------------------------------------------------------------
      UPDATE TQHB_RISK_VNDR
           SET SBM_YN               = p_SBM_YN                  --제출1 미제출0
              ,SBM_DT               = DECODE(p_SBM_YN,'1', TO_CHAR(SYSDATE,'YYYYMMDD'), '') --제출일자
              ,UPD_ID               = p_WRK_ID                  --수정ID 
              ,UPD_DTM              = SYSDATE()                 --수정일시
              ,UPD_IP               = p_WRK_IP                  --수정IP
         WHERE SIT_CD = p_SIT_CD          --현장코드
           AND PLN_YM = p_PLN_YM          --계획년월
           AND PLN_DGR = p_PLN_DGR         --차수구분코드(QS005) 1 1차,2 2차
           AND CUST_CD = p_CUST_CD         --협력업체코드
           AND VNDR_SEQ = p_VNDR_SEQ         --공종코드           
    ;
    
   
    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 5. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN 
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);
END ;
/

-- PQHB_SAFT_MNG_ASSIGN_Q (PROCEDURE, VALID)
CREATE PROCEDURE "PQHB_SAFT_MNG_ASSIGN_Q"
(
      p_WRK_TP  VARCHAR2 DEFAULT 'Q'                                                       -- FLAG( Q: SELECT )
     ,p_SIT_CD TQHB_DAYSAFE_NAM.SIT_CD%TYPE                                               -- 현장코드
     ,p_PLN_YM TQHB_DAYSAFE_NAM.PLN_YM%TYPE                                               -- 계획년월
     ,p_PLN_DGR TQHB_DAYSAFE_NAM.PLN_DGR%TYPE                                             -- 차수구분코드(QS005) 1 1차,2 2차
     ,p_ODAY_CHK_DT TQHB_DAYSAFE_NAM.ODAY_CHK_DT%TYPE                                     -- 일일점검일자
     ,p_RISK_GRD TQHB_DAYSAFE_NAM.RISK_GRD%TYPE                                           -- 위험등급(QS09002) 작성
     ,p_EMPE_NO_SEQ TQHB_DAYSAFE_NAM.EMPE_NO_SEQ%TYPE                                       -- 일일안전책임자 순번
     ,p_EMPE_NO TQHB_DAYSAFE_NAM.EMPE_NO%TYPE                                     			  -- 일일안전책임자
     ,RTN_CURSOR OUT SYS_REFCURSOR
) 
IS 
    /**************************************************************************************************************************
      Purpose : 

      REVISIONS
      Ver      Date               Author                  Description 
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2026/09/04 16:09:44                         최초생성

    /**************************************************************************************************************************/


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR2(200);            -- ERROR Message
    USER_EXCEPTION EXCEPTION;


BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 수행전 Check Logic ]
    ---------------------------------------------------------------------------------------------------------------------------


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Logic 처리
    ---------------------------------------------------------------------------------------------------------------------------
    
	-- 그리드 헤더 조회   
	 IF p_WRK_TP = 'Q1' THEN
	
	    OPEN RTN_CURSOR FOR
		    SELECT ROW_NUMBER() OVER(ORDER BY ODAY_CHK_DT) AS COL_SEQ
			     , ODAY_CHK_DT
			     , TO_CHAR(TO_DATE(ODAY_CHK_DT,'YYYYMMDD'),'MM/DD')
			       || CHR(10)
			       || '('
			       || TO_CHAR(TO_DATE(ODAY_CHK_DT,'YYYYMMDD'),'DY','NLS_DATE_LANGUAGE=KOREAN')
			       || ')' AS HDR_NM
			     , MIN(SUBSTR(ODAY_CHK_DT, -2)) OVER() AS MIN_CHK_DAY
			     , MAX(SUBSTR(ODAY_CHK_DT, -2)) OVER() AS MAX_CHK_DAY
			FROM (
			    SELECT DISTINCT ODAY_CHK_DT
			    FROM TQHB_DAYSAFE_DT
			    WHERE SIT_CD  = p_SIT_CD
			      AND PLN_YM  = p_PLN_YM
			      AND PLN_DGR = p_PLN_DGR
			)
			ORDER BY ODAY_CHK_DT;
	    
	    /*
			SELECT ROW_NUMBER() OVER(ORDER BY ODAY_CHK_DT) AS COL_SEQ
			     , ODAY_CHK_DT
			     , TO_CHAR(TO_DATE(ODAY_CHK_DT,'YYYYMMDD'),'MM/DD')
			       || CHR(10)
			       || '('
			       || TO_CHAR(TO_DATE(ODAY_CHK_DT,'YYYYMMDD'),'DY','NLS_DATE_LANGUAGE=KOREAN')
			       || ')' AS HDR_NM
			     , TO_NUMBER(SUBSTR(ODAY_CHK_DT, -2)) AS CHK_DAY
			FROM (
			    SELECT DISTINCT ODAY_CHK_DT
			    FROM TQHB_DAYSAFE_DT
			    WHERE SIT_CD  = p_SIT_CD
			      AND PLN_YM  = p_PLN_YM
			      AND PLN_DGR = p_PLN_DGR
			)
			ORDER BY ODAY_CHK_DT;
		*/		 
	    
	-- 중점 그리드 데이터 조회
	ELSIF p_WRK_TP = 'Q2' THEN
	
	    OPEN RTN_CURSOR FOR
		WITH DT_MAIN AS (
		    -- 1. TQHB_DAYSAFE_DT 메인: 점검 일자 목록 및 해당 월의 최대 점검일(MAX_DAY) 추출
		    SELECT DISTINCT 
		           ODAY_CHK_DT,
		           MAX(TO_NUMBER(SUBSTR(ODAY_CHK_DT, 7, 2))) OVER() AS MAX_DAY
		      FROM TQHB_DAYSAFE_DT
		     WHERE SIT_CD = p_SIT_CD
		       AND PLN_YM = p_PLN_YM
		       AND PLN_DGR = p_PLN_DGR
		       AND RISK_GRD = 'QS0900201'
		)
		SELECT 
		       (SELECT CD_NM FROM TCOA_COMCODE WHERE COM_CD = S.JB_CD AND HRNK_CD = 'QS077' AND USE_YN = '1') AS JB_NM,
		       S.PNM,
		       S.EMPE_NO,
		       'QS0900201' AS RISK_GRD, 
		       MAX(CASE WHEN D.DAY_DD = '01' THEN CASE WHEN N.EMPE_NO IS NOT NULL THEN '1' ELSE NULL END END) AS D_1,
		       MAX(CASE WHEN D.DAY_DD = '02' THEN CASE WHEN N.EMPE_NO IS NOT NULL THEN '1' ELSE NULL END END) AS D_2,
		       MAX(CASE WHEN D.DAY_DD = '03' THEN CASE WHEN N.EMPE_NO IS NOT NULL THEN '1' ELSE NULL END END) AS D_3,
		       MAX(CASE WHEN D.DAY_DD = '04' THEN CASE WHEN N.EMPE_NO IS NOT NULL THEN '1' ELSE NULL END END) AS D_4,
		       MAX(CASE WHEN D.DAY_DD = '05' THEN CASE WHEN N.EMPE_NO IS NOT NULL THEN '1' ELSE NULL END END) AS D_5,
		       MAX(CASE WHEN D.DAY_DD = '06' THEN CASE WHEN N.EMPE_NO IS NOT NULL THEN '1' ELSE NULL END END) AS D_6,
		       MAX(CASE WHEN D.DAY_DD = '07' THEN CASE WHEN N.EMPE_NO IS NOT NULL THEN '1' ELSE NULL END END) AS D_7,
		       MAX(CASE WHEN D.DAY_DD = '08' THEN CASE WHEN N.EMPE_NO IS NOT NULL THEN '1' ELSE NULL END END) AS D_8,
		       MAX(CASE WHEN D.DAY_DD = '09' THEN CASE WHEN N.EMPE_NO IS NOT NULL THEN '1' ELSE NULL END END) AS D_9,
		       MAX(CASE WHEN D.DAY_DD = '10' THEN CASE WHEN N.EMPE_NO IS NOT NULL THEN '1' ELSE NULL END END) AS D_10,
		       MAX(CASE WHEN D.DAY_DD = '11' THEN CASE WHEN N.EMPE_NO IS NOT NULL THEN '1' ELSE NULL END END) AS D_11,
		       MAX(CASE WHEN D.DAY_DD = '12' THEN CASE WHEN N.EMPE_NO IS NOT NULL THEN '1' ELSE NULL END END) AS D_12,
		       MAX(CASE WHEN D.DAY_DD = '13' THEN CASE WHEN N.EMPE_NO IS NOT NULL THEN '1' ELSE NULL END END) AS D_13,
		       MAX(CASE WHEN D.DAY_DD = '14' THEN CASE WHEN N.EMPE_NO IS NOT NULL THEN '1' ELSE NULL END END) AS D_14,
		       MAX(CASE WHEN D.DAY_DD = '15' THEN CASE WHEN N.EMPE_NO IS NOT NULL THEN '1' ELSE NULL END END) AS D_15,
		       MAX(CASE WHEN D.DAY_DD = '16' THEN CASE WHEN N.EMPE_NO IS NOT NULL THEN '1' ELSE NULL END END) AS D_16,
		       MAX(CASE WHEN D.DAY_DD = '17' THEN CASE WHEN N.EMPE_NO IS NOT NULL THEN '1' ELSE NULL END END) AS D_17,
		       MAX(CASE WHEN D.DAY_DD = '18' THEN CASE WHEN N.EMPE_NO IS NOT NULL THEN '1' ELSE NULL END END) AS D_18,
		       MAX(CASE WHEN D.DAY_DD = '19' THEN CASE WHEN N.EMPE_NO IS NOT NULL THEN '1' ELSE NULL END END) AS D_19,
		       MAX(CASE WHEN D.DAY_DD = '20' THEN CASE WHEN N.EMPE_NO IS NOT NULL THEN '1' ELSE NULL END END) AS D_20,
		       MAX(CASE WHEN D.DAY_DD = '21' THEN CASE WHEN N.EMPE_NO IS NOT NULL THEN '1' ELSE NULL END END) AS D_21,
		       MAX(CASE WHEN D.DAY_DD = '22' THEN CASE WHEN N.EMPE_NO IS NOT NULL THEN '1' ELSE NULL END END) AS D_22,
		       MAX(CASE WHEN D.DAY_DD = '23' THEN CASE WHEN N.EMPE_NO IS NOT NULL THEN '1' ELSE NULL END END) AS D_23,
		       MAX(CASE WHEN D.DAY_DD = '24' THEN CASE WHEN N.EMPE_NO IS NOT NULL THEN '1' ELSE NULL END END) AS D_24,
		       MAX(CASE WHEN D.DAY_DD = '25' THEN CASE WHEN N.EMPE_NO IS NOT NULL THEN '1' ELSE NULL END END) AS D_25,
		       MAX(CASE WHEN D.DAY_DD = '26' THEN CASE WHEN N.EMPE_NO IS NOT NULL THEN '1' ELSE NULL END END) AS D_26,
		       MAX(CASE WHEN D.DAY_DD = '27' THEN CASE WHEN N.EMPE_NO IS NOT NULL THEN '1' ELSE NULL END END) AS D_27,
		       MAX(CASE WHEN D.DAY_DD = '28' THEN CASE WHEN N.EMPE_NO IS NOT NULL THEN '1' ELSE NULL END END) AS D_28,
		       MAX(CASE WHEN D.DAY_DD = '29' THEN CASE WHEN N.EMPE_NO IS NOT NULL THEN '1' ELSE NULL END END) AS D_29,
		       MAX(CASE WHEN D.DAY_DD = '30' THEN CASE WHEN N.EMPE_NO IS NOT NULL THEN '1' ELSE NULL END END) AS D_30,
		       MAX(CASE WHEN D.DAY_DD = '31' THEN CASE WHEN N.EMPE_NO IS NOT NULL THEN '1' ELSE NULL END END) AS D_31,		       
		       MAX(CASE WHEN D.DAY_DD = '01' THEN D.ODAY_CHK_DT ELSE NULL END) AS DD_1,		       
		       MAX(CASE WHEN D.DAY_DD = '02' THEN D.ODAY_CHK_DT ELSE NULL END) AS DD_2,
		       MAX(CASE WHEN D.DAY_DD = '03' THEN D.ODAY_CHK_DT ELSE NULL END) AS DD_3,
		       MAX(CASE WHEN D.DAY_DD = '04' THEN D.ODAY_CHK_DT ELSE NULL END) AS DD_4,
		       MAX(CASE WHEN D.DAY_DD = '05' THEN D.ODAY_CHK_DT ELSE NULL END) AS DD_5,
		       MAX(CASE WHEN D.DAY_DD = '06' THEN D.ODAY_CHK_DT ELSE NULL END) AS DD_6,
		       MAX(CASE WHEN D.DAY_DD = '07' THEN D.ODAY_CHK_DT ELSE NULL END) AS DD_7,
		       MAX(CASE WHEN D.DAY_DD = '08' THEN D.ODAY_CHK_DT ELSE NULL END) AS DD_8,
		       MAX(CASE WHEN D.DAY_DD = '09' THEN D.ODAY_CHK_DT ELSE NULL END) AS DD_9,
		       MAX(CASE WHEN D.DAY_DD = '10' THEN D.ODAY_CHK_DT ELSE NULL END) AS DD_10,
		       MAX(CASE WHEN D.DAY_DD = '11' THEN D.ODAY_CHK_DT ELSE NULL END) AS DD_11,
		       MAX(CASE WHEN D.DAY_DD = '12' THEN D.ODAY_CHK_DT ELSE NULL END) AS DD_12,
		       MAX(CASE WHEN D.DAY_DD = '13' THEN D.ODAY_CHK_DT ELSE NULL END) AS DD_13,
		       MAX(CASE WHEN D.DAY_DD = '14' THEN D.ODAY_CHK_DT ELSE NULL END) AS DD_14,
		       MAX(CASE WHEN D.DAY_DD = '15' THEN D.ODAY_CHK_DT ELSE NULL END) AS DD_15,
		       MAX(CASE WHEN D.DAY_DD = '16' THEN D.ODAY_CHK_DT ELSE NULL END) AS DD_16,
		       MAX(CASE WHEN D.DAY_DD = '17' THEN D.ODAY_CHK_DT ELSE NULL END) AS DD_17,
		       MAX(CASE WHEN D.DAY_DD = '18' THEN D.ODAY_CHK_DT ELSE NULL END) AS DD_18,
		       MAX(CASE WHEN D.DAY_DD = '19' THEN D.ODAY_CHK_DT ELSE NULL END) AS DD_19,
		       MAX(CASE WHEN D.DAY_DD = '20' THEN D.ODAY_CHK_DT ELSE NULL END) AS DD_20,
		       MAX(CASE WHEN D.DAY_DD = '21' THEN D.ODAY_CHK_DT ELSE NULL END) AS DD_21,
		       MAX(CASE WHEN D.DAY_DD = '22' THEN D.ODAY_CHK_DT ELSE NULL END) AS DD_22,
		       MAX(CASE WHEN D.DAY_DD = '23' THEN D.ODAY_CHK_DT ELSE NULL END) AS DD_23,
		       MAX(CASE WHEN D.DAY_DD = '24' THEN D.ODAY_CHK_DT ELSE NULL END) AS DD_24,
		       MAX(CASE WHEN D.DAY_DD = '25' THEN D.ODAY_CHK_DT ELSE NULL END) AS DD_25,
		       MAX(CASE WHEN D.DAY_DD = '26' THEN D.ODAY_CHK_DT ELSE NULL END) AS DD_26,
		       MAX(CASE WHEN D.DAY_DD = '27' THEN D.ODAY_CHK_DT ELSE NULL END) AS DD_27,
		       MAX(CASE WHEN D.DAY_DD = '28' THEN D.ODAY_CHK_DT ELSE NULL END) AS DD_28,
		       MAX(CASE WHEN D.DAY_DD = '29' THEN D.ODAY_CHK_DT ELSE NULL END) AS DD_29,
		       MAX(CASE WHEN D.DAY_DD = '30' THEN D.ODAY_CHK_DT ELSE NULL END) AS DD_30,
		       MAX(CASE WHEN D.DAY_DD = '31' THEN D.ODAY_CHK_DT ELSE NULL END) AS DD_31
		  FROM TQHA_SITENAM S
		  LEFT JOIN (
		        SELECT ODAY_CHK_DT,
		               SUBSTR(ODAY_CHK_DT, 7, 2) AS DAY_DD,
		               MAX_DAY
		          FROM DT_MAIN
		  ) D ON 1 = 1
		  LEFT JOIN TQHB_DAYSAFE_NAM N
		         ON S.SIT_CD = N.SIT_CD
		        AND S.EMPE_NO = N.EMPE_NO
		        AND D.ODAY_CHK_DT = N.ODAY_CHK_DT
		        AND N.PLN_YM = p_PLN_YM
		        AND N.PLN_DGR = p_PLN_DGR
		        AND N.RISK_GRD = 'QS0900201'
		 WHERE S.SIT_CD = p_SIT_CD
		   AND S.USE_YN = '1'
		   AND S.JB_CD IS NOT NULL
		 GROUP BY S.JB_CD, S.PNM, S.EMPE_NO
		 ORDER BY JB_NM, S.PNM
		 ;
	    
	 -- 일상 그리드 데이터 조회
	ELSIF p_WRK_TP = 'Q3' THEN
	
	    OPEN RTN_CURSOR FOR
		WITH DT_MAIN AS (
		    -- 1. TQHB_DAYSAFE_DT 메인: 점검 일자 목록 및 해당 월의 최대 점검일(MAX_DAY) 추출
		    SELECT DISTINCT 
		           ODAY_CHK_DT,
		           MAX(TO_NUMBER(SUBSTR(ODAY_CHK_DT, 7, 2))) OVER() AS MAX_DAY
		      FROM TQHB_DAYSAFE_DT
		     WHERE SIT_CD = p_SIT_CD
		       AND PLN_YM = p_PLN_YM
		       AND PLN_DGR = p_PLN_DGR
		       AND RISK_GRD = 'QS0900202'
		)
		SELECT 
		       (SELECT CD_NM FROM TCOA_COMCODE WHERE COM_CD = S.JB_CD AND HRNK_CD = 'QS077' AND USE_YN = '1') AS JB_NM,
		       S.PNM,
		       S.EMPE_NO,
		       'QS0900202' AS RISK_GRD, 
		       MAX(CASE WHEN D.DAY_DD = '01' THEN CASE WHEN N.EMPE_NO IS NOT NULL THEN '1' ELSE NULL END END) AS D_1,
		       MAX(CASE WHEN D.DAY_DD = '02' THEN CASE WHEN N.EMPE_NO IS NOT NULL THEN '1' ELSE NULL END END) AS D_2,
		       MAX(CASE WHEN D.DAY_DD = '03' THEN CASE WHEN N.EMPE_NO IS NOT NULL THEN '1' ELSE NULL END END) AS D_3,
		       MAX(CASE WHEN D.DAY_DD = '04' THEN CASE WHEN N.EMPE_NO IS NOT NULL THEN '1' ELSE NULL END END) AS D_4,
		       MAX(CASE WHEN D.DAY_DD = '05' THEN CASE WHEN N.EMPE_NO IS NOT NULL THEN '1' ELSE NULL END END) AS D_5,
		       MAX(CASE WHEN D.DAY_DD = '06' THEN CASE WHEN N.EMPE_NO IS NOT NULL THEN '1' ELSE NULL END END) AS D_6,
		       MAX(CASE WHEN D.DAY_DD = '07' THEN CASE WHEN N.EMPE_NO IS NOT NULL THEN '1' ELSE NULL END END) AS D_7,
		       MAX(CASE WHEN D.DAY_DD = '08' THEN CASE WHEN N.EMPE_NO IS NOT NULL THEN '1' ELSE NULL END END) AS D_8,
		       MAX(CASE WHEN D.DAY_DD = '09' THEN CASE WHEN N.EMPE_NO IS NOT NULL THEN '1' ELSE NULL END END) AS D_9,
		       MAX(CASE WHEN D.DAY_DD = '10' THEN CASE WHEN N.EMPE_NO IS NOT NULL THEN '1' ELSE NULL END END) AS D_10,
		       MAX(CASE WHEN D.DAY_DD = '11' THEN CASE WHEN N.EMPE_NO IS NOT NULL THEN '1' ELSE NULL END END) AS D_11,
		       MAX(CASE WHEN D.DAY_DD = '12' THEN CASE WHEN N.EMPE_NO IS NOT NULL THEN '1' ELSE NULL END END) AS D_12,
		       MAX(CASE WHEN D.DAY_DD = '13' THEN CASE WHEN N.EMPE_NO IS NOT NULL THEN '1' ELSE NULL END END) AS D_13,
		       MAX(CASE WHEN D.DAY_DD = '14' THEN CASE WHEN N.EMPE_NO IS NOT NULL THEN '1' ELSE NULL END END) AS D_14,
		       MAX(CASE WHEN D.DAY_DD = '15' THEN CASE WHEN N.EMPE_NO IS NOT NULL THEN '1' ELSE NULL END END) AS D_15,
		       MAX(CASE WHEN D.DAY_DD = '16' THEN CASE WHEN N.EMPE_NO IS NOT NULL THEN '1' ELSE NULL END END) AS D_16,
		       MAX(CASE WHEN D.DAY_DD = '17' THEN CASE WHEN N.EMPE_NO IS NOT NULL THEN '1' ELSE NULL END END) AS D_17,
		       MAX(CASE WHEN D.DAY_DD = '18' THEN CASE WHEN N.EMPE_NO IS NOT NULL THEN '1' ELSE NULL END END) AS D_18,
		       MAX(CASE WHEN D.DAY_DD = '19' THEN CASE WHEN N.EMPE_NO IS NOT NULL THEN '1' ELSE NULL END END) AS D_19,
		       MAX(CASE WHEN D.DAY_DD = '20' THEN CASE WHEN N.EMPE_NO IS NOT NULL THEN '1' ELSE NULL END END) AS D_20,
		       MAX(CASE WHEN D.DAY_DD = '21' THEN CASE WHEN N.EMPE_NO IS NOT NULL THEN '1' ELSE NULL END END) AS D_21,
		       MAX(CASE WHEN D.DAY_DD = '22' THEN CASE WHEN N.EMPE_NO IS NOT NULL THEN '1' ELSE NULL END END) AS D_22,
		       MAX(CASE WHEN D.DAY_DD = '23' THEN CASE WHEN N.EMPE_NO IS NOT NULL THEN '1' ELSE NULL END END) AS D_23,
		       MAX(CASE WHEN D.DAY_DD = '24' THEN CASE WHEN N.EMPE_NO IS NOT NULL THEN '1' ELSE NULL END END) AS D_24,
		       MAX(CASE WHEN D.DAY_DD = '25' THEN CASE WHEN N.EMPE_NO IS NOT NULL THEN '1' ELSE NULL END END) AS D_25,
		       MAX(CASE WHEN D.DAY_DD = '26' THEN CASE WHEN N.EMPE_NO IS NOT NULL THEN '1' ELSE NULL END END) AS D_26,
		       MAX(CASE WHEN D.DAY_DD = '27' THEN CASE WHEN N.EMPE_NO IS NOT NULL THEN '1' ELSE NULL END END) AS D_27,
		       MAX(CASE WHEN D.DAY_DD = '28' THEN CASE WHEN N.EMPE_NO IS NOT NULL THEN '1' ELSE NULL END END) AS D_28,
		       MAX(CASE WHEN D.DAY_DD = '29' THEN CASE WHEN N.EMPE_NO IS NOT NULL THEN '1' ELSE NULL END END) AS D_29,
		       MAX(CASE WHEN D.DAY_DD = '30' THEN CASE WHEN N.EMPE_NO IS NOT NULL THEN '1' ELSE NULL END END) AS D_30,
		       MAX(CASE WHEN D.DAY_DD = '31' THEN CASE WHEN N.EMPE_NO IS NOT NULL THEN '1' ELSE NULL END END) AS D_31,
		       MAX(CASE WHEN D.DAY_DD = '01' THEN D.ODAY_CHK_DT ELSE NULL END) AS DD_1,		       
		       MAX(CASE WHEN D.DAY_DD = '02' THEN D.ODAY_CHK_DT ELSE NULL END) AS DD_2,
		       MAX(CASE WHEN D.DAY_DD = '03' THEN D.ODAY_CHK_DT ELSE NULL END) AS DD_3,
		       MAX(CASE WHEN D.DAY_DD = '04' THEN D.ODAY_CHK_DT ELSE NULL END) AS DD_4,
		       MAX(CASE WHEN D.DAY_DD = '05' THEN D.ODAY_CHK_DT ELSE NULL END) AS DD_5,
		       MAX(CASE WHEN D.DAY_DD = '06' THEN D.ODAY_CHK_DT ELSE NULL END) AS DD_6,
		       MAX(CASE WHEN D.DAY_DD = '07' THEN D.ODAY_CHK_DT ELSE NULL END) AS DD_7,
		       MAX(CASE WHEN D.DAY_DD = '08' THEN D.ODAY_CHK_DT ELSE NULL END) AS DD_8,
		       MAX(CASE WHEN D.DAY_DD = '09' THEN D.ODAY_CHK_DT ELSE NULL END) AS DD_9,
		       MAX(CASE WHEN D.DAY_DD = '10' THEN D.ODAY_CHK_DT ELSE NULL END) AS DD_10,
		       MAX(CASE WHEN D.DAY_DD = '11' THEN D.ODAY_CHK_DT ELSE NULL END) AS DD_11,
		       MAX(CASE WHEN D.DAY_DD = '12' THEN D.ODAY_CHK_DT ELSE NULL END) AS DD_12,
		       MAX(CASE WHEN D.DAY_DD = '13' THEN D.ODAY_CHK_DT ELSE NULL END) AS DD_13,
		       MAX(CASE WHEN D.DAY_DD = '14' THEN D.ODAY_CHK_DT ELSE NULL END) AS DD_14,
		       MAX(CASE WHEN D.DAY_DD = '15' THEN D.ODAY_CHK_DT ELSE NULL END) AS DD_15,
		       MAX(CASE WHEN D.DAY_DD = '16' THEN D.ODAY_CHK_DT ELSE NULL END) AS DD_16,
		       MAX(CASE WHEN D.DAY_DD = '17' THEN D.ODAY_CHK_DT ELSE NULL END) AS DD_17,
		       MAX(CASE WHEN D.DAY_DD = '18' THEN D.ODAY_CHK_DT ELSE NULL END) AS DD_18,
		       MAX(CASE WHEN D.DAY_DD = '19' THEN D.ODAY_CHK_DT ELSE NULL END) AS DD_19,
		       MAX(CASE WHEN D.DAY_DD = '20' THEN D.ODAY_CHK_DT ELSE NULL END) AS DD_20,
		       MAX(CASE WHEN D.DAY_DD = '21' THEN D.ODAY_CHK_DT ELSE NULL END) AS DD_21,
		       MAX(CASE WHEN D.DAY_DD = '22' THEN D.ODAY_CHK_DT ELSE NULL END) AS DD_22,
		       MAX(CASE WHEN D.DAY_DD = '23' THEN D.ODAY_CHK_DT ELSE NULL END) AS DD_23,
		       MAX(CASE WHEN D.DAY_DD = '24' THEN D.ODAY_CHK_DT ELSE NULL END) AS DD_24,
		       MAX(CASE WHEN D.DAY_DD = '25' THEN D.ODAY_CHK_DT ELSE NULL END) AS DD_25,
		       MAX(CASE WHEN D.DAY_DD = '26' THEN D.ODAY_CHK_DT ELSE NULL END) AS DD_26,
		       MAX(CASE WHEN D.DAY_DD = '27' THEN D.ODAY_CHK_DT ELSE NULL END) AS DD_27,
		       MAX(CASE WHEN D.DAY_DD = '28' THEN D.ODAY_CHK_DT ELSE NULL END) AS DD_28,
		       MAX(CASE WHEN D.DAY_DD = '29' THEN D.ODAY_CHK_DT ELSE NULL END) AS DD_29,
		       MAX(CASE WHEN D.DAY_DD = '30' THEN D.ODAY_CHK_DT ELSE NULL END) AS DD_30,
		       MAX(CASE WHEN D.DAY_DD = '31' THEN D.ODAY_CHK_DT ELSE NULL END) AS DD_31
		  FROM TQHA_SITENAM S
		  LEFT JOIN (
		        SELECT ODAY_CHK_DT,
		               SUBSTR(ODAY_CHK_DT, 7, 2) AS DAY_DD,
		               MAX_DAY
		          FROM DT_MAIN
		  ) D ON 1 = 1
		  LEFT JOIN TQHB_DAYSAFE_NAM N
		         ON S.SIT_CD = N.SIT_CD
		        AND S.EMPE_NO = N.EMPE_NO
		        AND D.ODAY_CHK_DT = N.ODAY_CHK_DT
		        AND N.PLN_YM = p_PLN_YM
		        AND N.PLN_DGR = p_PLN_DGR
		        AND N.RISK_GRD = 'QS0900202'
		 WHERE S.SIT_CD = p_SIT_CD
		   AND S.USE_YN = '1'
		   AND S.JB_CD IS NOT NULL
		 GROUP BY S.JB_CD, S.PNM, S.EMPE_NO
		 ORDER BY JB_NM, S.PNM
		 ;
	 
	  -- 점검항목별 안전책임자 조회
	ELSIF p_WRK_TP = 'Q4' THEN
	
	    OPEN RTN_CURSOR FOR
		 SELECT A.SIT_CD                 --현장코드
		       ,A.PLN_YM                 --계획년월
		       ,A.PLN_DGR                 --차수구분코드(QS005) 1 1차,2 2차
		       ,A.CUST_CD                 --협력업체코드
		       ,A.VNDR_SEQ
		       ,(SELECT CUST_NM FROM VQSZ_TRADE WHERE CUST_CD = A.CUST_CD) AS CUST_NM  --업체명
		       ,A.CTP_CD                 --공종코드
		       ,A.UNT_CD                 --단위코드
		       ,(SELECT CTP_NM FROM TQHA_CTP WHERE CTP_CD = A.CTP_CD) AS CTP_NM
		       ,(SELECT UNT_NM FROM TQHA_CTPUNT WHERE CTP_CD = A.CTP_CD AND UNT_CD = A.UNT_CD) AS UNT_NM
		       ,A.CHK_ITM_CD                 --점검항목코드
		       ,A.ODAY_CHK_DT
		       ,A.RISK_GRD
		       ,A.EMPE_NO
		       ,(SELECT USR_NM FROM TCOZ_USR_INFO WHERE EMPNO = A.EMPE_NO) AS USR_NM
		       ,B.CHK_ITM_NM                 --점검항목명
		       ,B.IMPRV_CPLN                 --개선대책
		       ,B.CHK_LOC
    	       ,B.WRK_PSNNO
		  FROM TQHB_DAYSAFE_CHKLST A,
		       TQHB_RISK_LST B
		WHERE 1=1
		   AND A.SIT_CD = B.SIT_CD                     --현장코드
		   AND A.PLN_YM = B.PLN_YM                     --계획년월
		   AND A.PLN_DGR = B.PLN_DGR                   --차수구분코드(QS005) 1 1차,2 2차
		   AND A.CUST_CD = B.CUST_CD
		   AND A.CTP_CD = B.CTP_CD
		   AND A.UNT_CD = B.UNT_CD
		   AND A.CHK_ITM_CD = B.CHK_ITM_CD
		   AND A.SIT_CD = p_SIT_CD                    --현장코드
		   AND A.PLN_YM = p_PLN_YM                     --계획년월
		   AND A.PLN_DGR = p_PLN_DGR                     --차수구분코드(QS005) 1 1차,2 2차
		   AND A.RISK_GRD = p_RISK_GRD
		   AND A.ODAY_CHK_DT = p_ODAY_CHK_DT
		ORDER BY A.SIT_CD, A.PLN_YM, A.PLN_DGR, A.CUST_CD, A.UNT_CD, A.CHK_ITM_CD 
	   		;
	    
	 END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN 
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);
END ;
/

-- PQHB_SAFT_MNG_ASSIGN_S (PROCEDURE, VALID)
CREATE PROCEDURE "PQHB_SAFT_MNG_ASSIGN_S"
                            (p_WRK_TP  VARCHAR2 :='U'                                     -- UPDATE FLAG( I: ISNERT, U:UPDATE, D:DELTE)
                            ,p_WRK_ID  VARCHAR2                                           -- 사용자 ID 
                            ,p_WRK_IP  VARCHAR2                                           -- 사용자 IP 
                            ,p_SIT_CD TQHB_DAYSAFE_CHKLST.SIT_CD%TYPE                     -- 현장코드
                            ,p_PLN_YM TQHB_DAYSAFE_CHKLST.PLN_YM%TYPE                     -- 계획년월
                            ,p_PLN_DGR TQHB_DAYSAFE_CHKLST.PLN_DGR%TYPE                   -- 차수구분코드(QS005) 1 1차,2 2차
                            ,p_CUST_CD TQHB_DAYSAFE_CHKLST.CUST_CD%TYPE                   -- 협력업체코드
                            ,p_VNDR_SEQ TQHB_DAYSAFE_CHKLST.VNDR_SEQ%TYPE                 -- 업체순번
                            ,p_CTP_CD TQHB_DAYSAFE_CHKLST.CTP_CD%TYPE                     -- 공종코드
                            ,p_UNT_CD TQHB_DAYSAFE_CHKLST.UNT_CD%TYPE                     -- 단위코드
                            ,p_CHK_ITM_CD TQHB_DAYSAFE_CHKLST.CHK_ITM_CD%TYPE             -- 점검항목코드
                            ,p_ODAY_CHK_DT TQHB_DAYSAFE_CHKLST.ODAY_CHK_DT%TYPE           -- 일일점검일자
                            ,p_RISK_GRD TQHB_DAYSAFE_CHKLST.RISK_GRD%TYPE                 -- 위험등급(QS09002) 작성
                            ,p_CHK_ITM_SEQ TQHB_DAYSAFE_CHKLST.CHK_ITM_SEQ%TYPE           -- 점검항목 정열순서
                            ,p_ODAY_CHK_RSLT TQHB_DAYSAFE_CHKLST.ODAY_CHK_RSLT%TYPE       -- 점검결과(QS006) 1 N/A,2 완료(유지),3 불량
                            ,p_ODAY_CHK_OPIN TQHB_DAYSAFE_CHKLST.ODAY_CHK_OPIN%TYPE       -- 일일안전책임자 점검의견
                            ,p_EMPE_NO TQHB_DAYSAFE_CHKLST.EMPE_NO%TYPE                   -- 일일안전책임자 사번
                            ,p_PHOTO_GRP1 TQHB_DAYSAFE_CHKLST.PHOTO_GRP1%TYPE             -- 첨부파일그룹사진1
                            ,p_PHOTO_DESC_1 TQHB_DAYSAFE_CHKLST.PHOTO_DESC_1%TYPE         -- 사진설명1
                            ,p_PHOTO_GRP2 TQHB_DAYSAFE_CHKLST.PHOTO_GRP2%TYPE             -- 첨부파일그룹사진2
                            ,p_PHOTO_DESC_2 TQHB_DAYSAFE_CHKLST.PHOTO_DESC_2%TYPE         -- 사진설명2
                            ,p_NCR_PUBC_YN TQHB_DAYSAFE_CHKLST.NCR_PUBC_YN%TYPE           -- 발행 1, 미발행 0
                            ,p_NCR_DOC_NO TQHB_DAYSAFE_CHKLST.NCR_DOC_NO%TYPE             -- 부적합문서번호
                            ,p_MA_DDLN_DT TQHB_DAYSAFE_CHKLST.MA_DDLN_DT%TYPE             -- 조치기한일자
                            ,p_VNDR_NOTI_YN TQHB_DAYSAFE_CHKLST.VNDR_NOTI_YN%TYPE         -- 발송 1 미발송0
                            ,p_VNDR_SEND_DT TQHB_DAYSAFE_CHKLST.VNDR_SEND_DT%TYPE         -- 업체발송일자
                            ,p_VNDR_MA_YN TQHB_DAYSAFE_CHKLST.VNDR_MA_YN%TYPE             -- 조치구분(QS007) 1 조치, 0 미조치
                            ,p_VNDR_MA_DT TQHB_DAYSAFE_CHKLST.VNDR_MA_DT%TYPE             -- 업체조치일자
                            )
IS 
    /**************************************************************************************************************************
      Purpose : 

      REVISIONS
      Ver      Date               Author                  Description 
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2026/09/07 17:06:53                         최초생성

    /**************************************************************************************************************************/


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR2(200);            -- ERROR Message
    USER_EXCEPTION EXCEPTION;


BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 필수입력 필드  Check  ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_SIT_CD IS NULL)  THEN
        ERR_MSG := '현장코드는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_PLN_YM IS NULL)  THEN
        ERR_MSG := '계획년월는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_PLN_DGR IS NULL)  THEN
        ERR_MSG := '차수구분코드(QS005) 1 1차,2 2차는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_CUST_CD IS NULL)  THEN
        ERR_MSG := '협력업체코드는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_VNDR_SEQ IS NULL)  THEN
        ERR_MSG := '업체순번는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;
    
    IF (p_CTP_CD IS NULL)  THEN
        ERR_MSG := '공종코드는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_UNT_CD IS NULL)  THEN
        ERR_MSG := '단위코드는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_CHK_ITM_CD IS NULL)  THEN
        ERR_MSG := '점검항목코드는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_ODAY_CHK_DT IS NULL)  THEN
        ERR_MSG := '일일점검일자는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_RISK_GRD IS NULL)  THEN
        ERR_MSG := '위험등급(QS09002) 작성는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    
    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Process 선행조건 Check ]
    ---------------------------------------------------------------------------------------------------------------------------



    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Business Process ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_WRK_TP ='D') THEN
        DELETE 
          FROM TQHB_DAYSAFE_CHKLST
         WHERE SIT_CD = p_SIT_CD          --현장코드
           AND PLN_YM = p_PLN_YM          --계획년월
           AND PLN_DGR = p_PLN_DGR         --차수구분코드(QS005) 1 1차,2 2차
           AND CUST_CD = p_CUST_CD         --협력업체코드
           AND CTP_CD = p_CTP_CD          --공종코드
           AND UNT_CD = p_UNT_CD          --단위코드
           AND CHK_ITM_CD = p_CHK_ITM_CD      --점검항목코드
           AND ODAY_CHK_DT = p_ODAY_CHK_DT     --일일점검일자
           AND RISK_GRD = p_RISK_GRD        --위험등급(QS09002) 작성
           AND VNDR_SEQ = p_VNDR_SEQ;       --업체순번

    ELSE 
        UPDATE TQHB_DAYSAFE_CHKLST
           SET CHK_ITM_SEQ          = p_CHK_ITM_SEQ             --점검항목 정열순서
              ,ODAY_CHK_RSLT        = p_ODAY_CHK_RSLT           --점검결과(QS006) 1 N/A,2 완료(유지),3 불량
              ,ODAY_CHK_OPIN        = p_ODAY_CHK_OPIN           --일일안전책임자 점검의견
              ,EMPE_NO              = p_EMPE_NO                 --일일안전책임자 사번
              ,PHOTO_GRP1           = p_PHOTO_GRP1              --첨부파일그룹사진1
              ,PHOTO_DESC_1         = p_PHOTO_DESC_1            --사진설명1
              ,PHOTO_GRP2           = p_PHOTO_GRP2              --첨부파일그룹사진2
              ,PHOTO_DESC_2         = p_PHOTO_DESC_2            --사진설명2
              ,NCR_PUBC_YN          = p_NCR_PUBC_YN             --발행 1, 미발행 0
              ,NCR_DOC_NO           = p_NCR_DOC_NO              --부적합문서번호
              ,MA_DDLN_DT           = p_MA_DDLN_DT              --조치기한일자
              ,VNDR_NOTI_YN         = p_VNDR_NOTI_YN            --발송 1 미발송0
              ,VNDR_SEND_DT         = p_VNDR_SEND_DT            --업체발송일자
              ,VNDR_MA_YN           = p_VNDR_MA_YN              --조치구분(QS007) 1 조치, 0 미조치
              ,VNDR_MA_DT           = p_VNDR_MA_DT              --업체조치일자
              ,UPD_ID               = p_WRK_ID                  --수정ID 
              ,UPD_DTM              = SYSDATE()                 --수정일시
              ,UPD_IP               = p_WRK_IP                  --수정IP
         WHERE SIT_CD = p_SIT_CD          --현장코드
           AND PLN_YM = p_PLN_YM          --계획년월
           AND PLN_DGR = p_PLN_DGR         --차수구분코드(QS005) 1 1차,2 2차
           AND CUST_CD = p_CUST_CD         --협력업체코드
           AND CTP_CD = p_CTP_CD          --공종코드
           AND UNT_CD = p_UNT_CD          --단위코드
           AND CHK_ITM_CD = p_CHK_ITM_CD      --점검항목코드
           AND ODAY_CHK_DT = p_ODAY_CHK_DT     --일일점검일자
           AND RISK_GRD = p_RISK_GRD        --위험등급(QS09002) 작성
           AND VNDR_SEQ = p_VNDR_SEQ;       --업체순번
           
	END IF;
    
    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 5. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN 
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);
END ;
/

-- PQHB_SAFT_MNG_COPY_W (PROCEDURE, VALID)
CREATE PROCEDURE "PQHB_SAFT_MNG_COPY_W"
                            (p_WRK_TP  VARCHAR2 :='U'                                     -- UPDATE FLAG( I: ISNERT, U:UPDATE, D:DELTE)
                            ,p_WRK_ID  VARCHAR2                                           -- 사용자 ID 
                            ,p_WRK_IP  VARCHAR2                                           -- 사용자 IP 
                            ,p_SIT_CD TQHB_DAYSAFE_CHKLST.SIT_CD%TYPE                     -- 현장코드
                            ,p_PLN_YM TQHB_DAYSAFE_CHKLST.PLN_YM%TYPE                     -- 계획년월
                            ,p_PLN_DGR TQHB_DAYSAFE_CHKLST.PLN_DGR%TYPE                   -- 차수구분코드(QS0
                            )
IS 
    /**************************************************************************************************************************
      Purpose : 

      REVISIONS
      Ver      Date               Author                  Description 
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2026/09/07 17:06:53                         최초생성

    /**************************************************************************************************************************/


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR2(200);            -- ERROR Message
    USER_EXCEPTION EXCEPTION;

	v_ODAY_CHK_DT  VARCHAR2(8);
	
	v_CNT NUMBER;
BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 필수입력 필드  Check  ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_SIT_CD IS NULL)  THEN
        ERR_MSG := '현장코드는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_PLN_YM IS NULL)  THEN
        ERR_MSG := '계획년월는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_PLN_DGR IS NULL)  THEN
        ERR_MSG := '차수구분코드(QS005) 1 1차,2 2차는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Process 선행조건 Check ]
    ---------------------------------------------------------------------------------------------------------------------------
	SELECT MIN(ODAY_CHK_DT)
	  INTO v_ODAY_CHK_DT
	  FROM TQHB_DAYSAFE_CHKLST
	 WHERE SIT_CD   = p_SIT_CD
	   AND PLN_YM   = p_PLN_YM
	   AND PLN_DGR  = p_PLN_DGR;
    
    
    SELECT COUNT(1) INTO v_CNT
      FROM TQHB_DAYSAFE_CHKLST
    WHERE SIT_CD = p_SIT_CD                     --현장코드
       AND PLN_YM = p_PLN_YM                     --계획년월
       AND PLN_DGR = p_PLN_DGR                     --차수구분코드(QS005) 1 1차,2 2차
       AND ODAY_CHK_RSLT IS NOT NULL 
    ;

	IF (v_CNT> 0)  THEN
        ERR_MSG := '점검내역이 존재하여 책임자 일괄복사를 할 수 없습니다.';
        RAISE USER_EXCEPTION;
    END IF;
    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Business Process ]
    ---------------------------------------------------------------------------------------------------------------------------
   -- 중점점검
   MERGE INTO TQHB_DAYSAFE_CHKLST T
	USING (
	    SELECT *
	      FROM TQHB_DAYSAFE_CHKLST
	     WHERE SIT_CD      = p_SIT_CD
	       AND PLN_YM      = p_PLN_YM
	       AND PLN_DGR     = p_PLN_DGR
	       AND RISK_GRD    = 'QS0900201'
	       AND ODAY_CHK_DT = v_ODAY_CHK_DT
	) S
	ON (
	       T.SIT_CD     = S.SIT_CD
	   AND T.PLN_YM     = S.PLN_YM
	   AND T.PLN_DGR    = S.PLN_DGR
	   AND T.RISK_GRD   = S.RISK_GRD
	   AND T.CUST_CD    = S.CUST_CD
	   AND T.VNDR_SEQ   = S.VNDR_SEQ
	   AND T.CTP_CD     = S.CTP_CD
	   AND T.UNT_CD     = S.UNT_CD
	   AND T.CHK_ITM_CD = S.CHK_ITM_CD
	)
	WHEN MATCHED THEN
	UPDATE SET T.EMPE_NO = S.EMPE_NO
	WHERE T.ODAY_CHK_DT <> v_ODAY_CHK_DT;
   
   -- 일상점검
   MERGE INTO TQHB_DAYSAFE_CHKLST T
	USING (
	    SELECT *
	      FROM TQHB_DAYSAFE_CHKLST
	     WHERE SIT_CD      = p_SIT_CD
	       AND PLN_YM      = p_PLN_YM
	       AND PLN_DGR     = p_PLN_DGR
	       AND RISK_GRD    = 'QS0900202'
	       AND ODAY_CHK_DT = v_ODAY_CHK_DT
	) S
	ON (
	       T.SIT_CD     = S.SIT_CD
	   AND T.PLN_YM     = S.PLN_YM
	   AND T.PLN_DGR    = S.PLN_DGR
	   AND T.RISK_GRD   = S.RISK_GRD
	   AND T.CUST_CD    = S.CUST_CD
	   AND T.VNDR_SEQ   = S.VNDR_SEQ
	   AND T.CTP_CD     = S.CTP_CD
	   AND T.UNT_CD     = S.UNT_CD
	   AND T.CHK_ITM_CD = S.CHK_ITM_CD
	)
	WHEN MATCHED THEN
	UPDATE SET T.EMPE_NO = S.EMPE_NO
	WHERE T.ODAY_CHK_DT <> v_ODAY_CHK_DT;
   
	
   DELETE FROM TQHB_DAYSAFE_NAM
   WHERE   SIT_CD   = p_SIT_CD
	   AND PLN_YM   = p_PLN_YM
	   AND PLN_DGR  = p_PLN_DGR
	   AND ODAY_CHK_DT <> v_ODAY_CHK_DT
   ;
   
   INSERT INTO TQHB_DAYSAFE_NAM
	(
	    SIT_CD,
	    PLN_YM,
	    PLN_DGR,
	    ODAY_CHK_DT,
	    EMPE_NO_SEQ,
	    RISK_GRD,
	    EMPE_NO
	)
	SELECT
	    N.SIT_CD,
	    N.PLN_YM,
	    N.PLN_DGR,
	    D.ODAY_CHK_DT,   -- 날짜만 변경
	    N.EMPE_NO_SEQ,
	    N.RISK_GRD,
	    N.EMPE_NO
	FROM TQHB_DAYSAFE_NAM N
	JOIN TQHB_DAYSAFE_DT D
	  ON D.SIT_CD   = N.SIT_CD
	 AND D.PLN_YM   = N.PLN_YM
	 AND D.PLN_DGR  = N.PLN_DGR
	 AND D.RISK_GRD = N.RISK_GRD
	WHERE N.SIT_CD      = p_SIT_CD
	  AND N.PLN_YM      = p_PLN_YM
	  AND N.PLN_DGR     = p_PLN_DGR
	  AND N.ODAY_CHK_DT = v_ODAY_CHK_DT
	  AND D.ODAY_CHK_DT <> v_ODAY_CHK_DT
	ORDER BY ODAY_CHK_DT, EMPE_NO_SEQ
	;
    
    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 5. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN 
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);
END ;
/

-- PQHB_SAFT_MNG_ITEM_Q (PROCEDURE, VALID)
CREATE PROCEDURE "PQHB_SAFT_MNG_ITEM_Q" (
    p_WRK_TP            IN VARCHAR2 DEFAULT 'Q'         -- FLAG
,   p_WRK_ID            IN VARCHAR2                     
,   p_SIT_CD            IN VARCHAR2                     -- 현장코드
,   p_PLN_YM            IN VARCHAR2                     -- 계획연월
,   p_PLN_DGR           IN VARCHAR2                     -- 계획차수
,   RTN_CURSOR          OUT SYS_REFCURSOR
)
IS
    /**************************************************************************************************************************
      Purpose : [일일점검활동  ] PROCEDRE 

      REVISIONS
      Ver      Date               Author                  Description
      -------  -----------------  ----------------------  ---------------------------------------------------------------------
      1.0      2026/02/09                                 최초생성

    **************************************************************************************************************************/

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE  NUMBER :=-20009; -- ERROR 코드
    ERR_MSG   VARCHAR(200);    -- ERROR Message
    USER_EXCEPTION EXCEPTION;

BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 수행전 Check Logic ]
    ---------------------------------------------------------------------------------------------------------------------------
 
    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Logic 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------

    ---------------------------------------------------------------------------------------
    -- 
    IF p_WRK_TP = 'Q1' THEN

        -- 조회조건 조회 : 계획년월
        OPEN RTN_CURSOR FOR
        SELECT MAX(A.PLN_YM) AS PLN_YM    -- 계획년월
          FROM TQHB_RISK_DGR A
         WHERE A.SIT_CD     = p_SIT_CD
        ;

    ---------------------------------------------------------------------------------------
    ELSIF p_WRK_TP = 'Q2' THEN

        -- 조회조건 조회 : 계획차수 
        OPEN RTN_CURSOR FOR
        SELECT MAX(A.PLN_DGR) AS PLN_DGR    -- 계획년월
            , MAX(( SELECT JB_CD FROM TQHA_SITENAM WHERE SIT_CD = p_SIT_CD AND EMPE_NO = p_WRK_ID )) AS JB_CD
          FROM TQHB_RISK_DGR A
         WHERE A.SIT_CD     = p_SIT_CD
           AND A.PLN_YM     = p_PLN_YM
        ;

    ---------------------------------------------------------------------------------------
    ELSIF p_WRK_TP = 'Q3' THEN

        OPEN RTN_CURSOR FOR
        SELECT APRS_STR_DT    -- 평가시작일
             , APRS_END_DT    -- 평가종료일
          FROM TQHB_RISK_DGR A
         WHERE A.SIT_CD     = p_SIT_CD
           AND A.PLN_YM     = p_PLN_YM
           AND A.PLN_DGR    = p_PLN_DGR
        ;

    /*---------------------------------------------------------------------------------------
    ELSIF p_WRK_TP = 'Q4' THEN

        OPEN RTN_CURSOR FOR
        SELECT A.SIT_CD
             , A.PLN_YM
             , A.PLN_DGR
             , A.CUST_CD
             , ( SELECT CUST_NM FROM VQSZ_TRADE WHERE CUST_CD = A.CUST_CD ) AS VNDR_NM
             , A.VNDR_SEQ
             , B.SBM_YN
             , DECODE( B.SBM_YN, '1', '제출', '작성중' ) SBM_NM 
             , B.SBM_DT
             , B.SAFT_APRV_STATS
             , DECODE( B.SAFT_APRV_STATS, '1', '승인완료', '2', '반려', '진행중' ) AS SAFT_APRV_STATS_NM
             , B.SAFT_APRV_DT
          FROM ( -- 위험성 평가 제출 리스트
                 SELECT SIT_CD
                      , PLN_YM 
                      , PLN_DGR
                      , CUST_CD
                      , VNDR_SEQ
                   FROM TQHB_RISK_CHK
                  WHERE SIT_CD      = p_SIT_CD
                    AND PLN_YM      = p_PLN_YM
                    AND PLN_DGR     = p_PLN_DGR
                  GROUP BY SIT_CD, PLN_YM, PLN_DGR, CUST_CD, VNDR_SEQ
               ) A
             , TQHB_RISK_VNDR B 
         WHERE A.SIT_CD = B.SIT_CD
           AND A.PLN_YM = B.PLN_YM
           AND A.PLN_DGR = B.PLN_DGR
           AND A.CUST_CD = B.CUST_CD
           AND A.VNDR_SEQ = B.VNDR_SEQ
           AND B.SBM_YN = '1'
        ;
*/
        
    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
         WHEN OTHERS THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);

END PQHB_SAFT_MNG_ITEM_Q;
/

-- PQHB_STOP_WK_Q (PROCEDURE, VALID)
CREATE PROCEDURE "PQHB_STOP_WK_Q"
(
      p_WRK_TP  VARCHAR2 DEFAULT 'Q'                                                      -- FLAG( Q: SELECT )
     ,p_SIT_CD TQHB_STOP_WK.SIT_CD%TYPE                                                   -- 현장코드
     ,p_STOP_DIV TQHB_STOP_WK.STOP_DIV%TYPE                                               -- 작업구분(1:소리함,9:작업중지)
     ,p_STOP_DT TQHB_STOP_WK.STOP_DT%TYPE                                                 -- 발생일시
     ,p_STOP_DT_STR TQHB_STOP_WK.STOP_DT%TYPE                                             -- 발생일시
     ,p_STOP_DT_END TQHB_STOP_WK.STOP_DT%TYPE                                             -- 발생일시
     ,p_STOP_SEQ TQHB_STOP_WK.STOP_SEQ%TYPE                                               -- 발생순번
     ,RTN_CURSOR OUT SYS_REFCURSOR
)
IS 
    /**************************************************************************************************************************
      Purpose : 

      REVISIONS
      Ver      Date               Author                  Description 
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2026/09/03 14:39:22                         최초생성

    /**************************************************************************************************************************/


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR2(200);            -- ERROR Message
    USER_EXCEPTION EXCEPTION;


BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 수행전 Check Logic ]
    ---------------------------------------------------------------------------------------------------------------------------


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Logic 처리
    ---------------------------------------------------------------------------------------------------------------------------

    IF p_WRK_TP = 'Q1' THEN    
    
	    OPEN RTN_CURSOR FOR
	    SELECT  SIT_CD                 --현장코드
 	           ,( SELECT SIT_NM FROM TCMZ_SIT WHERE SIT_CD = A.SIT_CD ) AS SIT_NM -- 현장명칭
	           ,STOP_DIV                 --작업구분(1:소리함,9:작업중지)
	           ,STOP_DT
	           ,STOP_SEQ                 --발생순번
	           ,CHK_MATT                 --발생내용
	           ,CUST_NM                 --거래처명
	           ,INSP_PNM                 --점검자성명
	           ,MA_DT                 --조치일자
	           ,MA_MATT                 --조치사항
	           ,MA_PSN_EMPNO                 --조치자/담당직원
	           ,(SELECT USR_NM FROM TCOZ_USR_INFO WHERE EMPNO = A.MA_PSN_EMPNO) AS MA_PSN_PNM
	           --,MA_PSN_PNM                 --조치자성명
	           ,ATFL_GRP                 --첨부문서
	           ,ATFL_GRP2                 --조지전사진
	           ,ATFL_GRP3                 --조치후사진
	           ,PHOTO_DESC_2                 --조치전사진설명
	           ,PHOTO_DESC_3                 --조치후사진설명
	           ,PHOTO_LOC2                 --조치전사진설명
	           ,PHOTO_LOC3                 --조치후사진설명
	           ,RMKS                	 --조치사항
	      FROM TQHB_STOP_WK A
	    WHERE 1=1
	      AND SIT_CD LIKE '%'||p_SIT_CD||'%' 
	      AND STOP_DIV LIKE '%'||p_STOP_DIV||'%'
      	  AND STOP_DT BETWEEN NVL(p_STOP_DT_STR, '19000101') AND NVL(p_STOP_DT_END, '99991231')
       ORDER BY SIT_CD, STOP_DT DESC, STOP_SEQ DESC
	      ;
	    
	ELSIF p_WRK_TP = 'Q2' THEN    
    
	    OPEN RTN_CURSOR FOR
	    SELECT  SIT_CD                 --현장코드
	           ,( SELECT SIT_NM FROM TCMZ_SIT WHERE SIT_CD = A.SIT_CD ) AS SIT_NM -- 현장명칭
	           ,STOP_DIV                 --작업구분(1:소리함,9:작업중지)
	           ,STOP_DT
	           ,STOP_SEQ                 --발생순번
	           ,CHK_MATT                 --발생내용
	           ,CUST_NM                 --거래처명
	           ,INSP_PNM                 --점검자성명
	           ,MA_DT                 --조치일자
	           ,MA_MATT                 --조치사항
	           ,MA_PSN_EMPNO                 --조치자/담당직원
	           ,(SELECT USR_NM FROM TCOZ_USR_INFO WHERE EMPNO = A.MA_PSN_EMPNO) AS MA_PSN_PNM
	           --,MA_PSN_PNM                 --조치자성명
	           ,ATFL_GRP                 --첨부문서
	           ,ATFL_GRP2                 --조지전사진
	           ,ATFL_GRP3                 --조치후사진
	           ,PHOTO_DESC_2                 --조치전사진설명
	           ,PHOTO_DESC_3                 --조치후사진설명
	           ,PHOTO_LOC2                 --조치전사진설명
	           ,PHOTO_LOC3                 --조치후사진설명
	           ,RMKS                	 --조치사항
	      FROM TQHB_STOP_WK A
	    WHERE SIT_CD = p_SIT_CD                     --현장코드
	      AND STOP_DIV = p_STOP_DIV                     --작업구분(1:소리함,9:작업중지)
	      AND STOP_DT = p_STOP_DT                     --발생일시
	      AND STOP_SEQ = p_STOP_SEQ                     --발생순번
	      ;
	    
	END IF;
    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN 
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);
END ;
/

-- PQHB_STOP_WK_S (PROCEDURE, VALID)
CREATE PROCEDURE "PQHB_STOP_WK_S"
                            (p_WRK_TP  VARCHAR2 :='U'                                     -- UPDATE FLAG( I: ISNERT, U:UPDATE, D:DELTE)
                            ,p_WRK_ID  VARCHAR2                                           -- 사용자 ID 
                            ,p_WRK_IP  VARCHAR2                                           -- 사용자 IP 
                            ,p_SIT_CD TQHB_STOP_WK.SIT_CD%TYPE                            -- 현장코드
                            ,p_STOP_DIV TQHB_STOP_WK.STOP_DIV%TYPE                        -- 작업구분(1:소리함,9:작업중지)
                            ,p_STOP_DT TQHB_STOP_WK.STOP_DT%TYPE                          -- 발생일시
                            ,p_STOP_SEQ TQHB_STOP_WK.STOP_SEQ%TYPE                        -- 발생순번
                            ,p_CHK_MATT TQHB_STOP_WK.CHK_MATT%TYPE                        -- 발생내용
                            ,p_CUST_NM TQHB_STOP_WK.CUST_NM%TYPE                          -- 거래처명
                            ,p_INSP_PNM TQHB_STOP_WK.INSP_PNM%TYPE                        -- 점검자성명
                            ,p_MA_DT TQHB_STOP_WK.MA_DT%TYPE                              -- 조치일자
                            ,p_MA_MATT TQHB_STOP_WK.MA_MATT%TYPE                          -- 조치사항
                            ,p_MA_PSN_EMPNO TQHB_STOP_WK.MA_PSN_EMPNO%TYPE                -- 조치자/담당직원
                            ,p_MA_PSN_PNM TQHB_STOP_WK.MA_PSN_PNM%TYPE                    -- 조치자성명
                            ,p_ATFL_GRP TQHB_STOP_WK.ATFL_GRP%TYPE                        -- 첨부문서
                            ,p_ATFL_GRP2 TQHB_STOP_WK.ATFL_GRP2%TYPE                      -- 조지전사진
                            ,p_ATFL_GRP3 TQHB_STOP_WK.ATFL_GRP3%TYPE                      -- 조치후사진
                            ,p_PHOTO_DESC_2 TQHB_STOP_WK.PHOTO_DESC_2%TYPE                -- 조치전사진설명
                            ,p_PHOTO_DESC_3 TQHB_STOP_WK.PHOTO_DESC_3%TYPE                -- 조치후사진설명
                            ,p_PHOTO_LOC2 TQHB_STOP_WK.PHOTO_LOC2%TYPE                    -- 조치전사진설명
                            ,p_PHOTO_LOC3 TQHB_STOP_WK.PHOTO_LOC3%TYPE                    -- 조치후사진설명
                            ,p_RMKS TQHB_STOP_WK.RMKS%TYPE                                -- 조치사항
                            )
IS 
    /**************************************************************************************************************************
      Purpose : 

      REVISIONS
      Ver      Date               Author                  Description 
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2026/09/03 14:40:10                         최초생성

    /**************************************************************************************************************************/


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR2(200);            -- ERROR Message
    USER_EXCEPTION EXCEPTION;

	v_SEQ              NUMBER := 0;
BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 필수입력 필드  Check  ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_SIT_CD IS NULL)  THEN
        ERR_MSG := '현장코드는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_STOP_DIV IS NULL)  THEN
        ERR_MSG := '작업구분(1:소리함,9:작업중지)는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_STOP_DT IS NULL)  THEN
        ERR_MSG := '발생일시는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_WRK_TP != 'I' AND p_STOP_SEQ IS NULL)  THEN
        ERR_MSG := '발생순번는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Process 선행조건 Check ]
    ---------------------------------------------------------------------------------------------------------------------------



    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Business Process ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_WRK_TP ='D') THEN
        DELETE 
          FROM TQHB_STOP_WK
         WHERE SIT_CD = p_SIT_CD          --현장코드
           AND STOP_DIV = p_STOP_DIV        --작업구분(1:소리함,9:작업중지)
           AND STOP_DT = p_STOP_DT         --발생일시
           AND STOP_SEQ = p_STOP_SEQ;       --발생순번

    ELSIF (p_WRK_TP ='U') THEN
        UPDATE TQHB_STOP_WK
           SET CHK_MATT             = p_CHK_MATT                --발생내용
              ,CUST_NM              = p_CUST_NM                 --거래처명
              ,INSP_PNM             = p_INSP_PNM                --점검자성명
              ,MA_DT                = p_MA_DT                   --조치일자
              ,MA_MATT              = p_MA_MATT                 --조치사항
              ,MA_PSN_EMPNO         = p_WRK_ID                  --조치자/담당직원
              ,MA_PSN_PNM           = p_MA_PSN_PNM              --조치자성명
              ,ATFL_GRP             = p_ATFL_GRP                --첨부문서
              ,ATFL_GRP2            = p_ATFL_GRP2               --조지전사진
              ,ATFL_GRP3            = p_ATFL_GRP3               --조치후사진
              ,PHOTO_DESC_2         = p_PHOTO_DESC_2            --조치전사진설명
              ,PHOTO_DESC_3         = p_PHOTO_DESC_3            --조치후사진설명
              ,PHOTO_LOC2           = p_PHOTO_LOC2              --조치전사진설명
              ,PHOTO_LOC3           = p_PHOTO_LOC3              --조치후사진설명
              ,RMKS                 = p_RMKS                    --조치사항
              ,UPD_ID               = p_WRK_ID                  --수정ID 
              ,UPD_DTM              = SYSDATE()                 --수정일시
              ,UPD_IP               = p_WRK_IP                  --수정IP
         WHERE SIT_CD = p_SIT_CD          --현장코드
           AND STOP_DIV = p_STOP_DIV        --작업구분(1:소리함,9:작업중지)
           AND STOP_DT = p_STOP_DT         --발생일시
           AND STOP_SEQ = p_STOP_SEQ;       --발생순번
           
    ELSIF (p_WRK_TP ='U2') THEN -- 조치후 저장시

    	UPDATE TQHB_STOP_WK
           SET MA_DT                = p_MA_DT                   --조치일자
              ,MA_MATT              = p_MA_MATT                 --조치사항
              ,MA_PSN_EMPNO         = p_WRK_ID                  --조치자/담당직원
              ,MA_PSN_PNM           = p_MA_PSN_PNM              --조치자성명
              ,ATFL_GRP             = p_ATFL_GRP                --첨부문서
              ,ATFL_GRP2            = p_ATFL_GRP2               --조지전사진
              ,ATFL_GRP3            = p_ATFL_GRP3               --조치후사진
              ,PHOTO_DESC_2         = p_PHOTO_DESC_2            --조치전사진설명
              ,PHOTO_DESC_3         = p_PHOTO_DESC_3            --조치후사진설명
              ,PHOTO_LOC2           = p_PHOTO_LOC2              --조치전사진설명
              ,PHOTO_LOC3           = p_PHOTO_LOC3              --조치후사진설명
              ,UPD_ID               = p_WRK_ID                  --수정ID 
              ,UPD_DTM              = SYSDATE()                 --수정일시
              ,UPD_IP               = p_WRK_IP                  --수정IP
         WHERE SIT_CD = p_SIT_CD          --현장코드
           AND STOP_DIV = p_STOP_DIV        --작업구분(1:소리함,9:작업중지)
           AND STOP_DT = p_STOP_DT         --발생일시
           AND STOP_SEQ = p_STOP_SEQ;       --발생순번
    
    ELSIF (p_WRK_TP ='U3') THEN

        UPDATE TQHB_STOP_WK
           SET ATFL_GRP2            = p_ATFL_GRP2               -- 조치전 사진
             , UPD_ID               = p_WRK_ID                  -- 수정ID
             , UPD_DTM              = SYSDATE()                 -- 수정일시
             , UPD_IP               = p_WRK_IP                  -- 수정IP
          WHERE SIT_CD = p_SIT_CD          --현장코드
           AND STOP_DIV = p_STOP_DIV        --작업구분(1:소리함,9:작업중지)
           AND STOP_DT = p_STOP_DT         --발생일시
           AND STOP_SEQ = p_STOP_SEQ       --발생순번
        ;
        
     ELSIF (p_WRK_TP ='U4') THEN

        UPDATE TQHB_STOP_WK
           SET ATFL_GRP3            = p_ATFL_GRP3               -- 조치전 사진
             , UPD_ID               = p_WRK_ID                  -- 수정ID
             , UPD_DTM              = SYSDATE()                 -- 수정일시
             , UPD_IP               = p_WRK_IP                  -- 수정IP
          WHERE SIT_CD = p_SIT_CD          --현장코드
           AND STOP_DIV = p_STOP_DIV        --작업구분(1:소리함,9:작업중지)
           AND STOP_DT = p_STOP_DT         --발생일시
           AND STOP_SEQ = p_STOP_SEQ       --발생순번
        ;
        
     ELSIF (p_WRK_TP ='U5') THEN

        UPDATE TQHB_STOP_WK
           SET ATFL_GRP            = p_ATFL_GRP               -- 조치전 사진
             , UPD_ID               = p_WRK_ID                  -- 수정ID
             , UPD_DTM              = SYSDATE()                 -- 수정일시
             , UPD_IP               = p_WRK_IP                  -- 수정IP
          WHERE SIT_CD = p_SIT_CD          --현장코드
           AND STOP_DIV = p_STOP_DIV        --작업구분(1:소리함,9:작업중지)
           AND STOP_DT = p_STOP_DT         --발생일시
           AND STOP_SEQ = p_STOP_SEQ       --발생순번
        ;
        
    ELSE 
    
        SELECT NVL(MAX(STOP_SEQ), 0) + 1
          INTO v_SEQ
          FROM TQHB_STOP_WK
         WHERE SIT_CD       = p_SIT_CD          --현장코드
           AND STOP_DIV     = p_STOP_DIV        --유형(1:소리함, 2:작업중지)
           AND STOP_DT      = TO_CHAR(SYSDATE(),'YYYYMMDD') --발생일시
        ;
        
        INSERT INTO TQHB_STOP_WK
                   ( SIT_CD                  --현장코드
                    ,STOP_DIV                --작업구분(1:소리함,9:작업중지)
                    ,STOP_DT                 --발생일시
                    ,STOP_SEQ                --발생순번
                    ,CHK_MATT                --발생내용
                    ,CUST_NM                 --거래처명
                    ,INSP_PNM                --점검자성명
                    ,MA_DT                   --조치일자
                    ,MA_MATT                 --조치사항
                    ,MA_PSN_EMPNO            --조치자/담당직원
                    ,MA_PSN_PNM              --조치자성명
                    ,ATFL_GRP                --첨부문서
                    ,ATFL_GRP2               --조지전사진
                    ,ATFL_GRP3               --조치후사진
                    ,PHOTO_DESC_2            --조치전사진설명
                    ,PHOTO_DESC_3            --조치후사진설명
                    ,PHOTO_LOC2              --조치전사진설명
                    ,PHOTO_LOC3              --조치후사진설명
                    ,RMKS                    --조치사항
                    ,IPT_ID                  --입력ID
                    ,IPT_DTM                 --입력일시
                    ,IPT_IP                  --입력IP
                    ,UPD_ID                  --수정ID
                    ,UPD_DTM                 --수정일시
                    ,UPD_IP                  --수정IP
                    )
             VALUES (p_SIT_CD                --현장코드
                    ,p_STOP_DIV              --작업구분(1:소리함,9:작업중지)
                    ,TO_CHAR(SYSDATE(),'YYYYMMDD') --발생일시
                    ,v_SEQ                   --발생순번
                    ,p_CHK_MATT              --발생내용
                    ,p_CUST_NM               --거래처명
                    ,p_INSP_PNM              --점검자성명
                    ,p_MA_DT                 --조치일자
                    ,p_MA_MATT               --조치사항
                    ,p_MA_PSN_EMPNO          --조치자/담당직원
                    ,p_MA_PSN_PNM            --조치자성명
                    ,p_ATFL_GRP              --첨부문서
                    ,p_ATFL_GRP2             --조지전사진
                    ,p_ATFL_GRP3             --조치후사진
                    ,p_PHOTO_DESC_2          --조치전사진설명
                    ,p_PHOTO_DESC_3          --조치후사진설명
                    ,p_PHOTO_LOC2            --조치전사진설명
                    ,p_PHOTO_LOC3            --조치후사진설명
                    ,p_RMKS                  --조치사항
                    ,p_WRK_ID                --입력ID 
                    ,SYSDATE()               --입력일시
                    ,p_WRK_IP                --입력IP
                    ,p_WRK_ID                --수정ID
                    ,SYSDATE()               --수정일시
                    ,p_WRK_IP);              --수정IP
    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 5. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN 
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);
END ;
/

-- PQHB_VNDRNAM_Q (PROCEDURE, VALID)
CREATE PROCEDURE "PQHB_VNDRNAM_Q" (
      p_WRK_TP  VARCHAR2 DEFAULT 'Q'                                                       -- FLAG( Q: SELECT )
     ,p_SIT_CD TQHB_VNDRNAM.SIT_CD%TYPE                                                   -- 현장코드
     ,p_CUST_CD TQHB_VNDRNAM.CUST_CD%TYPE                                                 -- 협력업체코드
     ,p_VNDR_SEQ TQHB_VNDRNAM.VNDR_SEQ%TYPE                                               -- 업체순번
     ,RTN_CURSOR          OUT SYS_REFCURSOR
)
IS
    /**************************************************************************************************************************
      Purpose : [협력업체직원 조회] PROCEDRE (QSE > 기준정보 > 현장기준정보  )

      REVISIONS
      Ver      Date               Author                  Description 
      -------  -----------------  ----------------------  ---------------------------------------------------------------------
      1.0      XXXX/XX/XX                                 최초생성

    **************************************************************************************************************************/

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE  NUMBER :=-20009; -- ERROR 코드
    ERR_MSG   VARCHAR(200);    -- ERROR Message
    USER_EXCEPTION EXCEPTION;

BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 수행전 Check Logic ]
    ---------------------------------------------------------------------------------------------------------------------------

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Logic 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------

    -------------------------------------------------------------------------------------------------------------------------
    -- 협력업체직원 목록 조회.
    IF p_WRK_TP = 'Q' THEN

        OPEN RTN_CURSOR FOR
        SELECT AA.SIT_CD
 		     , AA.CUST_CD
			 , AA.VNDR_SEQ
             , AA.EMPE_NO
             --, AA.VNDR_PSN_PWD
             , AA.PNM
             , (
                SELECT JBPOS_NM FROM TCOZ_USR_INFO
                 WHERE 1=1
                   AND USR_ID = AA.EMPE_NO
               ) AS JIKGUB_NM
             , (SELECT CD_NM FROM TCOA_COMCODE WHERE COM_CD = BB.JBPOS_CD AND HRNK_CD = 'HRZ0ED' AND USE_YN = '1') AS JBPOS_NM
             , AA.DTY_CD
             , AA.DTY_NM
             , AA.TEL_NO
             --, PKG_XX1.DEC_VARCHAR2_SEL(AA.CELPH , 10 , 'SSN' , 'TQSZ_SITENAM' ,'CELPH') AS CELPH
             --, PKG_XX1.DEC_VARCHAR2_SEL(AA.EMAIL , 10 , 'SSN' , 'TQSZ_SITENAM' ,'EMAIL') AS EMAIL
             , AA.CELPH
             , AA.EMAIL
             , AA.ATCH_EN
             , AA.USE_YN
             , AA.JB_CD
             , NVL((SELECT CD_NM FROM TCOA_COMCODE WHERE COM_CD = AA.JB_CD AND HRNK_CD = 'QS077' AND USE_YN = '1'),'') AS JB_NM
          FROM TQHB_VNDRNAM AA
             , TCOZ_USR_INFO BB
         WHERE 1=1
           AND AA.SIT_CD    = BB.DEPT_CD (+)
           AND AA.EMPE_NO   = BB.USR_ID (+)
           AND AA.SIT_CD    = p_SIT_CD
           AND AA.CUST_CD   = p_CUST_CD
           AND AA.VNDR_SEQ  = p_VNDR_SEQ
         ORDER
            BY AA.PNM, AA.DTY_CD
        ;

    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
         WHEN OTHERS THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);

END PQHB_VNDRNAM_Q;
/

-- PQHB_VNDRNAM_S (PROCEDURE, VALID)
CREATE PROCEDURE "PQHB_VNDRNAM_S"
                            (p_WRK_TP  VARCHAR2 :='U'                                     -- UPDATE FLAG( I: ISNERT, U:UPDATE, D:DELTE)
                            ,p_WRK_ID  VARCHAR2                                           -- 사용자 ID 
                            ,p_WRK_IP  VARCHAR2                                           -- 사용자 IP 
                            ,p_SIT_CD TQHB_VNDRNAM.SIT_CD%TYPE                            -- 현장코드
                            ,p_CUST_CD TQHB_VNDRNAM.CUST_CD%TYPE                          -- 협력업체코드
                            ,p_VNDR_SEQ TQHB_VNDRNAM.VNDR_SEQ%TYPE                        -- 업체순번
                            ,p_EMPE_NO TQHB_VNDRNAM.EMPE_NO%TYPE                          -- 사원번호
                            ,p_PNM TQHB_VNDRNAM.PNM%TYPE                                  -- 성명
                            ,p_DTY_CD TQHB_VNDRNAM.DTY_CD%TYPE                            -- 직책코드
                            ,p_DTY_NM TQHB_VNDRNAM.DTY_NM%TYPE                            -- 직책명
                            ,p_RSET_YN TQHB_VNDRNAM.RSET_YN%TYPE                          -- 비번 초기화여부
                            ,p_VNDR_PSN_PWD TQHB_VNDRNAM.VNDR_PSN_PWD%TYPE                -- 개인정보 암호
                            ,p_PWD_NO_CHG_DT TQHB_VNDRNAM.PWD_NO_CHG_DT%TYPE              -- 비번최종변경일자
                            ,p_FAIL_CNT TQHB_VNDRNAM.FAIL_CNT%TYPE                        -- 실패횟수
                            ,p_TEL_NO TQHB_VNDRNAM.TEL_NO%TYPE                            -- 전화번호
                            ,p_CELPH TQHB_VNDRNAM.CELPH%TYPE                              -- 핸드폰
                            ,p_EMAIL TQHB_VNDRNAM.EMAIL%TYPE                              -- 이메일
                            ,p_USE_YN TQHB_VNDRNAM.USE_YN%TYPE                            -- 사용여부
                            ,p_ATCH_EN TQHB_VNDRNAM.ATCH_EN%TYPE                          -- 싸인여부
                            ,p_ATFL_GRP TQHB_VNDRNAM.ATFL_GRP%TYPE                        -- 첨부파일그룹
                            ,p_JB_CD TQHB_VNDRNAM.JB_CD%TYPE            		          -- 직무
                            )
IS 
    /**************************************************************************************************************************
      Purpose : 

      REVISIONS
      Ver      Date               Author                  Description 
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2026/07/28 12:50:07                         최초생성

    /**************************************************************************************************************************/


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR2(200);            -- ERROR Message
    USER_EXCEPTION EXCEPTION;

	v_CNT 		   NUMBER;
BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 필수입력 필드  Check  ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_SIT_CD IS NULL)  THEN
        ERR_MSG := '현장코드는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_CUST_CD IS NULL)  THEN
        ERR_MSG := '협력업체코드는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_VNDR_SEQ IS NULL)  THEN
        ERR_MSG := '업체순번는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    IF (p_EMPE_NO IS NULL)  THEN
        ERR_MSG := '사원번호는(은) 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Process 선행조건 Check ]
    ---------------------------------------------------------------------------------------------------------------------------

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Business Process ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_WRK_TP ='D') THEN
        DELETE 
          FROM TQHB_VNDRNAM
         WHERE SIT_CD = p_SIT_CD          --현장코드
           AND CUST_CD = p_CUST_CD         --협력업체코드
           AND VNDR_SEQ = p_VNDR_SEQ        --업체순번
           AND EMPE_NO = p_EMPE_NO;        --사원번호

    ELSIF (p_WRK_TP ='U') THEN
        UPDATE TQHB_VNDRNAM
           SET PNM                  = p_PNM                     --성명
              ,DTY_CD               = p_DTY_CD                  --직책코드
              ,DTY_NM               = p_DTY_NM                  --직책명
              --,RSET_YN              = p_RSET_YN                 --비번 초기화여부
              --,VNDR_PSN_PWD         = DECODE(p_VNDR_PSN_PWD, '', VNDR_PSN_PWD, p_VNDR_PSN_PWD)    --개인정보 암호
              --,PWD_NO_CHG_DT        = DECODE(p_VNDR_PSN_PWD, '', PWD_NO_CHG_DT, TO_CHAR(SYSDATE(),'YYYYMMDD'))  --비번최종변경일자
              --,FAIL_CNT             = p_FAIL_CNT                --실패횟수
              ,TEL_NO               = p_TEL_NO                  --전화번호
              ,CELPH                = p_CELPH                   --핸드폰
              ,EMAIL                = p_EMAIL                   --이메일
              ,USE_YN               = p_USE_YN                  --사용여부
              ,ATCH_EN              = p_ATCH_EN                 --싸인여부
              ,ATFL_GRP             = p_ATFL_GRP                --첨부파일그룹
              ,JB_CD             	= p_JB_CD
              ,UPD_ID               = p_WRK_ID                  --수정ID 
              ,UPD_DTM              = SYSDATE()                 --수정일시
              ,UPD_IP               = p_WRK_IP                  --수정IP
         WHERE SIT_CD = p_SIT_CD          --현장코드
           AND CUST_CD = p_CUST_CD         --협력업체코드
           AND VNDR_SEQ = p_VNDR_SEQ        --업체순번
           AND EMPE_NO = p_EMPE_NO;        --사원번호
    ELSE 
    
	     SELECT COUNT(1) INTO v_CNT
	     FROM TQHB_VNDRNAM
	     WHERE 1=1
	      AND EMPE_NO  = p_EMPE_NO
	      ;
	    
	     IF (v_CNT > 0)  THEN
	        ERR_MSG := '이미 등록된 아이디 입니다.';
	        RAISE USER_EXCEPTION;
	     END IF;
     
        INSERT INTO TQHB_VNDRNAM
                   ( SIT_CD                  --현장코드
                    ,CUST_CD                 --협력업체코드
                    ,VNDR_SEQ                --업체순번
                    ,EMPE_NO                 --사원번호
                    ,PNM                     --성명
                    ,DTY_CD                  --직책코드
                    ,DTY_NM                  --직책명
                    ,RSET_YN                 --비번 초기화여부
                    ,VNDR_PSN_PWD            --개인정보 암호
                    ,PWD_NO_CHG_DT           --비번최종변경일자
                    ,FAIL_CNT                --실패횟수
                    ,TEL_NO                  --전화번호
                    ,CELPH                   --핸드폰
                    ,EMAIL                   --이메일
                    ,USE_YN                  --사용여부
                    ,ATCH_EN                 --싸인여부
                    ,ATFL_GRP                --첨부파일그룹
                    ,JB_CD
                    ,IPT_ID                  --입력ID
                    ,IPT_DTM                 --입력일시
                    ,IPT_IP                  --입력IP
                    ,UPD_ID                  --수정ID
                    ,UPD_DTM                 --수정일시
                    ,UPD_IP                  --수정IP
                    )
             VALUES (p_SIT_CD                --현장코드
                    ,p_CUST_CD               --협력업체코드
                    ,p_VNDR_SEQ              --업체순번
                    ,p_EMPE_NO               --사원번호
                    ,p_PNM                   --성명
                    ,p_DTY_CD                --직책코드
                    ,p_DTY_NM                --직책명
                    ,'1'                     --비번 초기화여부
                    ,p_VNDR_PSN_PWD          --개인정보 암호
                    ,TO_CHAR(SYSDATE(),'YYYYMMDD')      --비번최종변경일자
                    ,0                       --실패횟수
                    ,p_TEL_NO                --전화번호
                    ,p_CELPH                 --핸드폰
                    ,p_EMAIL                 --이메일
                    ,p_USE_YN                --사용여부
                    ,p_ATCH_EN               --싸인여부
                    ,p_ATFL_GRP              --첨부파일그룹
                    ,p_JB_CD
                    ,p_WRK_ID                --입력ID 
                    ,SYSDATE()               --입력일시
                    ,p_WRK_IP                --입력IP
                    ,p_WRK_ID                --수정ID
                    ,SYSDATE()               --수정일시
                    ,p_WRK_IP);              --수정IP
    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 5. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
        WHEN OTHERS THEN 
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);
END ;
/

-- PQHB_VNDR_NAM_INFO_Q (PROCEDURE, VALID)
CREATE PROCEDURE "PQHB_VNDR_NAM_INFO_Q" (
      p_WRK_TP  VARCHAR2 DEFAULT 'Q'                                                       -- FLAG( Q: SELECT )
     ,p_SIT_CD TQHB_VNDRNAM.SIT_CD%TYPE                                                   -- 현장코드
     ,p_CUST_CD TQHB_VNDRNAM.CUST_CD%TYPE                                                 -- 협력업체코드
     ,p_VNDR_SEQ TQHB_VNDRNAM.VNDR_SEQ%TYPE                                               -- 업체순번
     ,p_EMPE_NO TQHB_VNDRNAM.EMPE_NO%TYPE                                                 -- 사번
     ,RTN_CURSOR          OUT SYS_REFCURSOR
)
IS
    /**************************************************************************************************************************
      Purpose : [협력업체직원 조회] PROCEDRE (QSE > 기준정보 > 현장기준정보  )

      REVISIONS
      Ver      Date               Author                  Description 
      -------  -----------------  ----------------------  ---------------------------------------------------------------------
      1.0      XXXX/XX/XX                                 최초생성

    **************************************************************************************************************************/

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE  NUMBER :=-20009; -- ERROR 코드
    ERR_MSG   VARCHAR(200);    -- ERROR Message
    USER_EXCEPTION EXCEPTION;

BEGIN

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 수행전 Check Logic ]
    ---------------------------------------------------------------------------------------------------------------------------

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Logic 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------

    -------------------------------------------------------------------------------------------------------------------------
    -- 본사	
	IF p_WRK_TP = 'Q' THEN

        OPEN RTN_CURSOR FOR
        SELECT AA.SIT_CD
             , AA.EMPE_NO
             , AA.PNM
             , AA.DTY_CD
             , AA.DTY_NM
             , AA.TEL_NO
             , AA.CELPH
             , AA.EMAIL
             , AA.USE_YN
             , AA.JB_CD
             ,(SELECT CD_NM FROM TCOA_COMCODE WHERE COM_CD = AA.JB_CD AND HRNK_CD = 'QS077' AND USE_YN = '1') AS JB_NM
          FROM TQHA_SITENAM AA
         WHERE 1=1
           AND AA.SIT_CD    = p_SIT_CD
           AND AA.EMPE_NO   = p_EMPE_NO 
        ;
        
    -- 협력업체직원  조회.
    ELSIF p_WRK_TP = 'Q2' THEN

        OPEN RTN_CURSOR FOR
        SELECT AA.SIT_CD
 		     , AA.CUST_CD
			 , AA.VNDR_SEQ
             , AA.EMPE_NO
             , AA.PNM
             , AA.DTY_CD
             , AA.DTY_NM
             , AA.TEL_NO
             , AA.CELPH
             , AA.EMAIL
             , AA.ATCH_EN
             , AA.USE_YN
             , AA.JB_CD
             , NVL((SELECT CD_NM FROM TCOA_COMCODE WHERE COM_CD = AA.JB_CD AND HRNK_CD = 'QS077' AND USE_YN = '1'),'') AS JB_NM
          FROM TQHB_VNDRNAM AA
         WHERE 1=1
           AND AA.SIT_CD    = p_SIT_CD
           AND AA.CUST_CD   = p_CUST_CD
           AND AA.VNDR_SEQ  = p_VNDR_SEQ
           AND AA.EMPE_NO   = p_EMPE_NO 
        ;

    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 4. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
         WHEN OTHERS THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);

END PQHB_VNDR_NAM_INFO_Q;
/

-- PQHZ_IMPORT_EMPS_S (PROCEDURE, VALID)
CREATE PROCEDURE "PQHZ_IMPORT_EMPS_S" (
    p_WRK_ID        VARCHAR2                            -- 사용자 ID
,   p_WRK_IP        VARCHAR2                            -- 사용자 IP
,   p_SIT_CD        TQHA_SITENAM.SIT_CD     %TYPE       -- 현장코드
)
IS
    /**************************************************************************************************************************
      Purpose :

      REVISIONS
      Ver      Date               Author                  Description
      -------  -----------------  ----------------------  -------------------------------------------------------------
      1.0     2019/04/15 13:26:30                         최초생성

    /**************************************************************************************************************************/

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 1. 변수선언 ]
    ---------------------------------------------------------------------------------------------------------------------------
    ERR_CODE       NUMBER :=-20009;          -- ERROR 코드
    ERR_MSG        VARCHAR(200);             -- ERROR Message
    USER_EXCEPTION EXCEPTION;

BEGIN
    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 2. 필수입력 필드  Check  ]
    ---------------------------------------------------------------------------------------------------------------------------
    IF (p_SIT_CD IS NULL)  THEN
        ERR_MSG := '현장코드는 필수 입력사항 입니다.';
        RAISE USER_EXCEPTION;
    END IF;

    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 3. Business Process 선행조건 Check ]
    ---------------------------------------------------------------------------------------------------------------------------

	MERGE INTO TQHA_SITENAM T
	USING (
	    SELECT 
	        A.SIT_CD,
	        A.EMP_NO,
	        A.EMP_NM,
	        B.DTY_CD,
	        B.DTY_NM,
	        B.JB_CD,
	        B.JB_NM,
	        B.MP_NO,
	        B.MAIL_ADDR,
	        A.IPT_STR_DT,
	        A.IPT_END_DT,
	        B.CORP_CD,
	        B.USE_YN
	    FROM TCMZ_SIT_PSN A
	    INNER JOIN TCOZ_USR_INFO B 
	       ON A.EMP_NO = B.EMPNO -- 사원 번호로 조인
	    WHERE A.SIT_CD = p_SIT_CD
	) S
	ON (
	    T.SIT_CD = S.SIT_CD AND 
	    T.EMPE_NO = S.EMP_NO
	)
	-- 1. 매칭되는 데이터가 이미 있는 경우: 기존 데이터 UPDATE
	WHEN MATCHED THEN
	    UPDATE SET 
	        T.PNM        = S.EMP_NM,
	        --T.DTY_CD     = S.DTY_CD,
	        --T.DTY_NM     = S.DTY_NM,      -- 직책명 업데이트
	        T.DTY_CD     = S.JB_CD,
	        T.DTY_NM     = S.JB_NM,       -- 직무
	        T.CELPH      = S.MP_NO,       -- 휴대폰번호 업데이트
	        T.EMAIL      = S.MAIL_ADDR,   -- 이메일 업데이트
	        T.WRK_STR_DT = S.IPT_STR_DT,
	        T.WRK_END_DT = S.IPT_END_DT,
	        T.CO_DIV_CD  = '1',     -- 법인코드 업데이트
	        T.USE_YN     = S.USE_YN,      -- 사용여부 업데이트
	        T.UPD_ID     = p_WRK_ID,
	        T.UPD_DTM    = SYSDATE(),
	        T.UPD_IP     = p_WRK_IP        
	-- 2. 매칭되는 데이터가 없는 경우: 신규 데이터 INSERT
	WHEN NOT MATCHED THEN
	    INSERT (
	        T.SIT_CD,
	        T.EMPE_NO,
	        T.PNM,
	        T.DTY_CD,
	        T.DTY_NM,
	        T.CELPH,
	        T.EMAIL,
	        T.WRK_STR_DT,
	        T.WRK_END_DT,
	        T.CO_DIV_CD,
	        T.USE_YN,
	        T.IPT_ID,
	        T.IPT_DTM,
	        T.IPT_IP,
	        T.UPD_ID,
	        T.UPD_DTM,
	        T.UPD_IP
	    ) 
	    VALUES (
	        S.SIT_CD,
	        S.EMP_NO,
	        S.EMP_NM,
	        --S.DTY_CD,
	        --S.DTY_NM,
	        S.JB_CD,
	        S.JB_NM,       -- 직무
	        S.MP_NO,
	        S.MAIL_ADDR,
	        S.IPT_STR_DT,
	        S.IPT_END_DT,
	        '1',
	        S.USE_YN,
	        p_WRK_ID,              
	        SYSDATE(),             
	        p_WRK_IP,              
	        p_WRK_ID,              
	        SYSDATE(),             
	        p_WRK_IP               
	    );
	
--	
--	-- 2. 해당 대상자의 USR_INFO 테이블 일괄 UPDATE	
--	MERGE INTO TCOZ_USR_INFO U
--	USING (
--	    SELECT SIT_CD,
--	           EMPE_NO,
--	           USE_YN,
--	           DTY_CD,
--	           DTY_NM
--	      FROM TQHA_SITENAM
--	     WHERE SIT_CD = p_SIT_CD
--	) S
--	ON (U.EMPNO = S.EMPE_NO) -- USR_ID 컬럼명이 EMPNO라면 U.EMPNO로 변경
--	WHEN MATCHED THEN
--	    UPDATE SET 
--	        U.USE_YN  = S.USE_YN,
--	        U.JB_CD   = S.DTY_CD,
--	        U.JB_NM   = S.DTY_NM,
--	        U.UPD_ID  = p_WRK_ID,
--	        U.UPD_DTM = SYSDATE,
--	        U.UPD_IP  = p_WRK_IP
--	;
--

/*	
	INSERT INTO TQHA_SITENAM (
	    SIT_CD,
	    EMPE_NO,
	    PNM,
	    DTY_CD,
	    DTY_NM,
	    CELPH,
	    EMAIL,
	    WRK_STR_DT,
	    WRK_END_DT,
	    CO_DIV_CD,
	    USE_YN,
	    IPT_ID,
	    IPT_DTM,
	    IPT_IP,
	    UPD_ID,
	    UPD_DTM,
	    UPD_IP
	)
	SELECT 
	    A.SIT_CD,
	    A.EMP_NO,
	    A.EMP_NM,
	    A.DTY_CD,
	    B.DTY_NM,
	    B.MP_NO,
	    B.MAIL_ADDR,
	    A.IPT_STR_DT,
	    A.IPT_END_DT,
	    B.CORP_CD,
	    B.USE_YN,
	    p_WRK_ID,              
        SYSDATE(),             
        p_WRK_IP,              
        p_WRK_ID,              
        SYSDATE(),             
        p_WRK_IP 
	FROM TCMZ_SIT_PSN A
	INNER JOIN TCOZ_USR_INFO B
	   ON A.EMP_NO = B.EMPNO
	WHERE NOT EXISTS (
	    -- TQHA_SITENAM 테이블에 동일한 사번(EMPE_NO)이 이미 있다면 제외
	    SELECT 1 
	    FROM TQHA_SITENAM T
	    WHERE T.EMPE_NO = A.EMP_NO
	      AND T.SIT_CD = A.SIT_CD
	);
*/


    ---------------------------------------------------------------------------------------------------------------------------
    -- ▩▩ [ 5. Exception 처리 ]
    ---------------------------------------------------------------------------------------------------------------------------
    EXCEPTION
        WHEN USER_EXCEPTION THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,ERR_MSG);
         WHEN OTHERS THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(ERR_CODE,SQLERRM);

END;
/

-- QHSITEOBJ01 (TYPE, VALID)
CREATE TYPE "QHSITEOBJ01" AS OBJECT 
(
  SIT_CD         VARCHAR2(6)  --  현장코드
, LM_YN           VARCHAR2(1)  --  주간사여부(0:비주간사 : 1:주간사)
, CONT_ERT        NUMBER(8,3)  --  계약지분율
, WHL_SPLPRC_AMT  NUMBER(20)   --  전체공급금액
, WHL_VAT         NUMBER(20)   --  전체부가세
)
/

-- QHSITETAB01 (TYPE, VALID)
CREATE TYPE "QHSITETAB01" 
AS TABLE OF QHSITEOBJ01
/

